INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0009', 'verse', 4, 3, '[\"His birth fulfilled long expectation,\",\"born to save both rich and poor.\",\"His death, removing condemnation,\",\"opened wide the heavenly door.\",\"Now he is king, his praise we sing;\",\"our worship bring, an offering.\",\"This message is our sure foundation,\",\"Christ is Lord for evermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0010', 10, 'All my heart', 'CP', 'en', 'in this version Word & Music, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'All my heart this night rejoices,
as I hear,
far and near,
sweetest angel voices.
‘Christ is born!’ their choirs are singing,
till the air
everywhere
now with joy is ringing.
Listen! from a humble manger
comes the call,
‘One and all,
run from sin and danger!
Christians come, let nothing grieve you;
you are freed!
All you need
I will surely give you.’
Gather, then, from every nation;
here let all,
great and small,
kneel in adoration;
love him who with love is yearning;
hail the star
that from far
bright with hope is burning!
You, my Lord, with love I’ll cherish,
live to you,
and with you
dying shall not perish,
but shall dwell with you for ever:
joy divine
shall be mine
that can alter never.
Words after by Paul Gerhardt');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0010', 'Catherine Winkworth');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0010', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0010', 'verse', 1, 0, '[\"All my heart this night rejoices,\",\"as I hear,\",\"far and near,\",\"sweetest angel voices.\",\"‘Christ is born!’ their choirs are singing,\",\"till the air\",\"everywhere\",\"now with joy is ringing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0010', 'verse', 2, 1, '[\"Listen! from a humble manger\",\"comes the call,\",\"‘One and all,\",\"run from sin and danger!\",\"Christians come, let nothing grieve you;\",\"you are freed!\",\"All you need\",\"I will surely give you.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0010', 'verse', 3, 2, '[\"Gather, then, from every nation;\",\"here let all,\",\"great and small,\",\"kneel in adoration;\",\"love him who with love is yearning;\",\"hail the star\",\"that from far\",\"bright with hope is burning!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0010', 'verse', 4, 3, '[\"You, my Lord, with love I’ll cherish,\",\"live to you,\",\"and with you\",\"dying shall not perish,\",\"but shall dwell with you for ever:\",\"joy divine\",\"shall be mine\",\"that can alter never.\",\"Words after by Paul Gerhardt\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0011', 11, 'Hurry the Lord is near', 'CP', 'en', 'Patrick Lee / OCP Publications, 5536 NE Hassalo, Portland, OR 97213 USA            ? Ernest Sands / OCP Publications|arrangement: ? Paul Inwood / OCP Publications', '', 0, 0, 0, 1, 1, 'Alleluia! Hurry, the Lord is near.
Alleluia, alleluia!
Hurry, the Lord is near.
Sound the trumpet, the Lord is near;
hurry, the Lord is near;
see, he comes to save us all.
Hurry, the Lord is near!
Alleluia! Hurry...
Earth has longed for his approach:
hurry, the Lord is near;
straighten the road, smooth the path.
Hurry, the Lord is near!
Alleluia! Hurry...
Go out to meet him, shout his name:
hurry, the Lord is near;
his mighty kingdom shall never end.
Hurry, the Lord is near!
Alleluia! Hurry...
He is the mighty One, he is the Word;
hurry, the Lord is near;
God everlasting, prince of peace.
Hurry, the Lord is near!
Alleluia! Hurry...');
