INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0011', 'verse', 1, 1, '[\"Sound the trumpet, the Lord is near;\",\"hurry, the Lord is near;\",\"see, he comes to save us all.\",\"Hurry, the Lord is near!\",\"Alleluia! Hurry...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0011', 'verse', 2, 2, '[\"Earth has longed for his approach:\",\"hurry, the Lord is near;\",\"straighten the road, smooth the path.\",\"Hurry, the Lord is near!\",\"Alleluia! Hurry...\"]');
