INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0012', 'verse', 4, 3, '[\"Jesus came from heaven\",\"and he’s still with us today.\",\"He says ‘I’ll always be with you’,\",\"so do not be afraid.\",\"We sing with the angels:\",\"Glory to God, glory in the highest\",\"and peace on earth to those he loves.\",\"Glory to God, glory in the highest\",\"and peace on earth to those he loves.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0013', 13, 'Angels from the realms of glory', 'CP', 'en', 'in this version The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Angels from the realms of glory,
wing your flight through all the earth;
heralds of creation’s story
now proclaim Messiah’s birth!
Come and worship
Christ, the new-born king;
come and worship,
worship Christ the new-born king.
Shepherds in the fields abiding,
watching by your flocks at night,
God with us is now residing:
see, there shines the infant light!
Come and worship...
Wise men, leave your contemplations!
brighter visions shine afar;
seek in him the hope of nations,
you have seen his rising star:
Come and worship...
Though an infant now we view him,
he will share his Father’s throne,
gather all the nations to him;
every knee shall then bow down:
Come and worship...');
