INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0019', 'verse', 2, 1, '[\"Life found in him its source,\",\"death found its end;\",\"light found in him its course,\",\"darkness its friend;\",\"for neither death nor doubt\",\"nor darkness can put out\",\"the glow of God, the shout\",\"‘I am for you’.\"]');
