INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0020', 20, 'Behold his love', 'CP', 'en', '1996 Sovereign Music UK, PO Box 356, Leighton Buzzard LU7 3WP, UK. sovereignmusic@aol.com', '', 0, 0, 0, 1, 1, 'Behold his love!
I stand amazed and marvel
at the God of grace;
that the Alpha and Omega,
the Beginning and the End,
the Creator of the universe
on whom all life depends,
should be clothed in frail humanity
and suffer in my place.
Behold his love
and worship him, the God of grace.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0020', 'Geoff Baker');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0020', 'Geoff Baker');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0020', 'verse', 1, 0, '[\"Behold his love!\",\"I stand amazed and marvel\",\"at the God of grace;\",\"that the Alpha and Omega,\",\"the Beginning and the End,\",\"the Creator of the universe\",\"on whom all life depends,\",\"should be clothed in frail humanity\",\"and suffer in my place.\",\"Behold his love\",\"and worship him, the God of grace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0021', 21, 'Brightest and best', 'CP', 'en', 'in this version The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? No?l Tredinnick, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Brightest and best of the sons of the morning,
dawn on our darkness and come to our aid;
star of the east, the horizon adorning,
guide where our infant redeemer is laid!
What shall we give him, in costly devotion?
Shall we bring incense and offerings divine,
gems of the mountain and pearls of the ocean,
myrrh from the forest or gold from the mine?
Vainly we offer each lavish oblation,
vainly with gifts would his favour secure;
richer by far is the heart’s adoration,
dearer to God are the prayers of the poor.
Brightest and best of the sons of the morning,
dawn on our darkness and come to our aid;
star of the east, the horizon adorning,
guide where our infant redeemer is laid!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0021', 'Reginald Heber');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0021', 'Joseph Francis Thrupp');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0021', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0021', 'verse', 1, 0, '[\"Brightest and best of the sons of the morning,\",\"dawn on our darkness and come to our aid;\",\"star of the east, the horizon adorning,\",\"guide where our infant redeemer is laid!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0021', 'verse', 2, 1, '[\"What shall we give him, in costly devotion?\",\"Shall we bring incense and offerings divine,\",\"gems of the mountain and pearls of the ocean,\",\"myrrh from the forest or gold from the mine?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0021', 'verse', 3, 2, '[\"Vainly we offer each lavish oblation,\",\"vainly with gifts would his favour secure;\",\"richer by far is the heart’s adoration,\",\"dearer to God are the prayers of the poor.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0021', 'verse', 4, 3, '[\"Brightest and best of the sons of the morning,\",\"dawn on our darkness and come to our aid;\",\"star of the east, the horizon adorning,\",\"guide where our infant redeemer is laid!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0022', 22, 'Bethlehem, we come to bring', 'CP', 'en', 'Paul Wigmore, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Bethlehem, we come to bring
merry dances for your king!
Step by step and drum by drum,
pat-a-pat-a-pan,
pat-a-pat-a-pan;
step by step and drum by drum
stepping bravely, here we come!
Mary, may we come to sing
merry songs to Christ our king?
Step by step and drum by drum,
pat-a-pat-a-pan,
pat-a-pat-a-pan;
step by step and drum by drum
stepping softly, here we come!
Christian people, now we say
merry Christmas on this day!
Step by step and drum by drum,
pat-a-pat-a-pan,
pat-a-pat-a-pan;
step by step and drum by drum
stepping gladly, here we come!
Words after by B de La Monnoye');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0022', 'Paul Wigmore');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0022', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0022', 'verse', 1, 0, '[\"Bethlehem, we come to bring\",\"merry dances for your king!\",\"Step by step and drum by drum,\",\"pat-a-pat-a-pan,\",\"pat-a-pat-a-pan;\",\"step by step and drum by drum\",\"stepping bravely, here we come!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0022', 'verse', 2, 1, '[\"Mary, may we come to sing\",\"merry songs to Christ our king?\",\"Step by step and drum by drum,\",\"pat-a-pat-a-pan,\",\"pat-a-pat-a-pan;\",\"step by step and drum by drum\",\"stepping softly, here we come!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0022', 'verse', 3, 2, '[\"Christian people, now we say\",\"merry Christmas on this day!\",\"Step by step and drum by drum,\",\"pat-a-pat-a-pan,\",\"pat-a-pat-a-pan;\",\"step by step and drum by drum\",\"stepping gladly, here we come!\",\"Words after by B de La Monnoye\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0023', 23, 'Born as a stranger', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Born as a stranger,
laid in a manger,
Jesus, the Lord of heaven and earth;
to us descending,
sinners befriending,
bring us to glory by your birth!
Infant so tender!
Gone is the splendour,
Jesus, that graced your Father’s home;
our nature wearing,
our sorrows bearing,
poor and alone for us you come.
Lord of all lowliness,
perfect in holiness,
Jesus the Christ, of whom we sing;
we bow before you,
praise and adore you:
be our true saviour and our king!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0023', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0023', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0023', 'verse', 1, 0, '[\"Born as a stranger,\",\"laid in a manger,\",\"Jesus, the Lord of heaven and earth;\",\"to us descending,\",\"sinners befriending,\",\"bring us to glory by your birth!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0023', 'verse', 2, 1, '[\"Infant so tender!\",\"Gone is the splendour,\",\"Jesus, that graced your Father’s home;\",\"our nature wearing,\",\"our sorrows bearing,\",\"poor and alone for us you come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0023', 'verse', 3, 2, '[\"Lord of all lowliness,\",\"perfect in holiness,\",\"Jesus the Christ, of whom we sing;\",\"we bow before you,\",\"praise and adore you:\",\"be our true saviour and our king!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0024', 24, 'Mary’s child', 'CP', 'en', 'Stainer & Bell Ltd, 23 Gruneisen Road, London N3 1DZ. www.stainer.co.uk', '', 0, 0, 0, 1, 1, 'Born in the night,
Mary’s child,
a long way from your home;
coming in need,
Mary’s child,
born in a borrowed room:
Clear shining light,
Mary’s child,
your face lights up our way:
light of the world,
Mary’s child,
dawn on our darkened day.
Truth of our life,
Mary’s child,
you tell us God is good:
prove it is true,
Mary’s child,
go to your cross of wood.
Hope of the world,
Mary’s child,
you’re coming soon to reign:
king of the earth,
Mary’s child,
walk in our streets again,
walk in our streets again.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0024', 'Geoffrey Ainger');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0024', 'Geoffrey Ainger');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0024', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0024', 'verse', 1, 0, '[\"Born in the night,\",\"Mary’s child,\",\"a long way from your home;\",\"coming in need,\",\"Mary’s child,\",\"born in a borrowed room:\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0024', 'verse', 2, 1, '[\"Clear shining light,\",\"Mary’s child,\",\"your face lights up our way:\",\"light of the world,\",\"Mary’s child,\",\"dawn on our darkened day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0024', 'verse', 3, 2, '[\"Truth of our life,\",\"Mary’s child,\",\"you tell us God is good:\",\"prove it is true,\",\"Mary’s child,\",\"go to your cross of wood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0024', 'verse', 4, 3, '[\"Hope of the world,\",\"Mary’s child,\",\"you’re coming soon to reign:\",\"king of the earth,\",\"Mary’s child,\",\"walk in our streets again,\",\"walk in our streets again.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0025', 25, 'A child is born for us', 'CP', 'en', 'Bernadette Farrell / OCP Publications, 5536 NE Hassalo, Portland, OR 97213 USA', '', 0, 0, 0, 1, 1, 'Bread of life, hope of the world,
Jesus Christ our brother:
feed us now, give us life,
lead us to one another.
A child is born for us,
a son is given to us;
in our midst Christ our Lord and God
comes as one who serves.
Bread of life...
With our own eyes we see,
with our own ears we hear
the salvation of all the world,
God’s incarnate Word.
Bread of life...
You are the hope of all,
promised since time began,
radiant light in our darkness,
truth to set us free.
Bread of life...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0025', 'Bernadette Farrell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0025', 'Bernadette Farrell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0025', 'chorus', 0, 0, '[\"Bread of life, hope of the world,\",\"Jesus Christ our brother:\",\"feed us now, give us life,\",\"lead us to one another.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0025', 'verse', 1, 1, '[\"A child is born for us,\",\"a son is given to us;\",\"in our midst Christ our Lord and God\",\"comes as one who serves.\",\"Bread of life...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0025', 'verse', 2, 2, '[\"With our own eyes we see,\",\"with our own ears we hear\",\"the salvation of all the world,\",\"God’s incarnate Word.\",\"Bread of life...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0025', 'verse', 3, 3, '[\"You are the hope of all,\",\"promised since time began,\",\"radiant light in our darkness,\",\"truth to set us free.\",\"Bread of life...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0026', 26, 'Child in a manger born', 'CP', 'en', '1994 Out of the Ark Music', '', 0, 0, 0, 1, 1, 'Child in a manger born.
lies in a cattle stall;
safely he’s sleeping,
Mary is keeping
close beside her baby so small.
Angels watch over him,
softly, their praises sing;
voices ascending,
joy never-ending,
glory be to Jesus the King!
And God in the heavens above
looks down with a heart full of love.
Leaving their flocks behind,
shepherds have come to find
Jesus the saviour,
Lord of the Ages,
here within the stable tonight.
And God in the heavens...
Wise men from far and wide
kneel at the baby’s side,
gazing in wonder,
praising the Son who
came to earth to lay down his life.
And God in the heavens...
Child in a manger born,
I want to know you more;
know you are near me,
love you more dearly,
Jesus, my Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0026', 'Mark Johnson');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0026', 'Helen Johnson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0026', 'Mark Johnson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0026', 'Helen Johnson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0026', 'verse', 1, 0, '[\"Child in a manger born.\",\"lies in a cattle stall;\",\"safely he’s sleeping,\",\"Mary is keeping\",\"close beside her baby so small.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0026', 'verse', 2, 1, '[\"Angels watch over him,\",\"softly, their praises sing;\",\"voices ascending,\",\"joy never-ending,\",\"glory be to Jesus the King!\",\"And God in the heavens above\",\"looks down with a heart full of love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0026', 'verse', 3, 2, '[\"Leaving their flocks behind,\",\"shepherds have come to find\",\"Jesus the saviour,\",\"Lord of the Ages,\",\"here within the stable tonight.\",\"And God in the heavens...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0026', 'verse', 4, 3, '[\"Wise men from far and wide\",\"kneel at the baby’s side,\",\"gazing in wonder,\",\"praising the Son who\",\"came to earth to lay down his life.\",\"And God in the heavens...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0026', 'verse', 5, 4, '[\"Child in a manger born,\",\"I want to know you more;\",\"know you are near me,\",\"love you more dearly,\",\"Jesus, my Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0027', 27, 'Child in a stable', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? Norman Warren, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Child in a stable:
how lovely is this place
where God is able
to show such perfect grace!
No princely babe that smiled
or palace that beguiled,
in history or fable,
could ever match this Child
within a stable.
God comes in weakness,
and to our world for love
descends with meekness');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0027', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0027', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0027', 'verse', 1, 0, '[\"Child in a stable:\",\"how lovely is this place\",\"where God is able\",\"to show such perfect grace!\",\"No princely babe that smiled\",\"or palace that beguiled,\",\"in history or fable,\",\"could ever match this Child\",\"within a stable.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0027', 'verse', 2, 1, '[\"God comes in weakness,\",\"and to our world for love\",\"descends with meekness\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0028', 28, 'Child in the manger', 'CP', 'en', '', '', 0, 0, 0, 1, 1, 'Child in the manger, infant of Mary,
outcast and stranger, Lord of all!
child who inherits all our transgressions,
all our demerits on him fall.
Once the most holy child of salvation
gentle and lowly lived below:
now as our glorious mighty redeemer,
see him victorious over each foe.
Prophets foretold him, infant of wonder;
angels behold him on his throne:
worthy our saviour of all their praises;
happy for ever are his own.
Words after by Mary MacDonald');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0028', 'Lachlan Macbean');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0028', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0028', 'verse', 1, 0, '[\"Child in the manger, infant of Mary,\",\"outcast and stranger, Lord of all!\",\"child who inherits all our transgressions,\",\"all our demerits on him fall.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0028', 'verse', 2, 1, '[\"Once the most holy child of salvation\",\"gentle and lowly lived below:\",\"now as our glorious mighty redeemer,\",\"see him victorious over each foe.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0028', 'verse', 3, 2, '[\"Prophets foretold him, infant of wonder;\",\"angels behold him on his throne:\",\"worthy our saviour of all their praises;\",\"happy for ever are his own.\",\"Words after by Mary MacDonald\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0029', 29, 'Christ came in faith', 'CP', 'en', 'John Capon, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? SGO Music Publishing Ltd', '', 0, 0, 0, 1, 1, 'Christ came in faith to Bethlehem,
faith of the shepherds, waiting long.
Saw for themselves the promised one,
confirmed with joy the angels’ song.
Christ came in hope to Bethlehem,
hope of the wise men from afar.
They knew a king had come to earth,
followed with joy the guiding star.
Christ came in love to Bethlehem,
love of the mother, lost for words.
As Mary hugged her newborn son,
cradled with joy the Lord of Lords.
Christ came that night to Bethlehem,
faith, hope and love, God’s cure for sin.
Seen, yet again, on Calvary’s cross,
faith, hope and love, a world to win.
Christ came for us to Bethlehem,
piercing the dark, a shining ray,
bearing our guilt, that we might know;
faith, hope and love through him today.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0029', 'John Capon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0029', 'Dave Bainbridge');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0029', 'Joanne Hogg');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0029', 'Terl Bryant');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0029', 'verse', 1, 0, '[\"Christ came in faith to Bethlehem,\",\"faith of the shepherds, waiting long.\",\"Saw for themselves the promised one,\",\"confirmed with joy the angels’ song.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0029', 'verse', 2, 1, '[\"Christ came in hope to Bethlehem,\",\"hope of the wise men from afar.\",\"They knew a king had come to earth,\",\"followed with joy the guiding star.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0029', 'verse', 3, 2, '[\"Christ came in love to Bethlehem,\",\"love of the mother, lost for words.\",\"As Mary hugged her newborn son,\",\"cradled with joy the Lord of Lords.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0029', 'verse', 4, 3, '[\"Christ came that night to Bethlehem,\",\"faith, hope and love, God’s cure for sin.\",\"Seen, yet again, on Calvary’s cross,\",\"faith, hope and love, a world to win.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0029', 'verse', 5, 4, '[\"Christ came for us to Bethlehem,\",\"piercing the dark, a shining ray,\",\"bearing our guilt, that we might know;\",\"faith, hope and love through him today.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0030', 30, 'Christ is born to be our king', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            ? David Sanderson', '', 0, 0, 0, 1, 1, 'Christ is born to be our king –
listen, as the angels sing,
to the heavens echoing,
‘Glory be to God on high!’
Shepherds in the fields at night
hear the tidings, see the light,
find the child, in praise unite:
‘Glory be to God on high!’
Christians down the ages tell
Christ can break the powers of hell,
so that we may sing as well,
‘Glory be to God on high!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0030', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0030', 'David Sanderson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0030', 'verse', 1, 0, '[\"Christ is born to be our king –\",\"listen, as the angels sing,\",\"to the heavens echoing,\",\"‘Glory be to God on high!’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0030', 'verse', 2, 1, '[\"Shepherds in the fields at night\",\"hear the tidings, see the light,\",\"find the child, in praise unite:\",\"‘Glory be to God on high!’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0030', 'verse', 3, 2, '[\"Christians down the ages tell\",\"Christ can break the powers of hell,\",\"so that we may sing as well,\",\"‘Glory be to God on high!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0031', 31, 'Christ is surely coming', 'CP', 'en', 'Christopher Idle, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? No?l Tredinnick, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Christ is surely coming bringing his reward,
Alpha and Omega, First and Last and Lord:
Root and stem of David, brilliant Morning Star:
meet your Judge and Saviour, nations near and far;
meet your Judge and Saviour, nations near and far!
See the holy city! There they enter in,
all by Christ made holy, washed from every sin:
thirsty ones, desiring all he loves to give,
come for living water, freely drink, and live;
come for living water, freely drink, and live!
Grace be with God’s people! Praise his holy name!
Father, Son and Spirit, evermore the same.
Hear the certain promise from the eternal home:
‘Surely I come quickly!’ Come, Lord Jesus, come;
‘Surely I come quickly!’ Come, Lord Jesus, come!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0031', 'Christopher Idle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0031', 'Edward Elgar');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0031', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0031', 'verse', 1, 0, '[\"Christ is surely coming bringing his reward,\",\"Alpha and Omega, First and Last and Lord:\",\"Root and stem of David, brilliant Morning Star:\",\"meet your Judge and Saviour, nations near and far;\",\"meet your Judge and Saviour, nations near and far!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0031', 'verse', 2, 1, '[\"See the holy city! There they enter in,\",\"all by Christ made holy, washed from every sin:\",\"thirsty ones, desiring all he loves to give,\",\"come for living water, freely drink, and live;\",\"come for living water, freely drink, and live!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0031', 'verse', 3, 2, '[\"Grace be with God’s people! Praise his holy name!\",\"Father, Son and Spirit, evermore the same.\",\"Hear the certain promise from the eternal home:\",\"‘Surely I come quickly!’ Come, Lord Jesus, come;\",\"‘Surely I come quickly!’ Come, Lord Jesus, come!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0032', 32, 'Christians, make a joyful sound', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? No?l Tredinnick, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Christians, make a joyful sound,
sing to all the world around:
he is in a manger found,
the holy One, the infant son of Mary.
Let the people join to say
that Christ the Lord is born today,
till the very earth shall raise
the song of praise:
‘Nowell, nowell –
Christ is born, the infant son of Mary!’
Mighty God, Emmanuel –
prince of whom the prophets tell,
child announced by Gabriel,
the holy One, the infant son of Mary.
Let the people...
Come, you choirs, with gladness sing,
instruments of music bring –
eager to proclaim the king,
the holy One, the infant son of Mary.
Let the people...
Love is here to seek and save –
heaven’s master as a slave:
God so loved the world he gave
the holy One, the infant son of Mary.
Let the people...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0032', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0032', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0032', 'verse', 1, 0, '[\"Christians, make a joyful sound,\",\"sing to all the world around:\",\"he is in a manger found,\",\"the holy One, the infant son of Mary.\",\"Let the people join to say\",\"that Christ the Lord is born today,\",\"till the very earth shall raise\",\"the song of praise:\",\"‘Nowell, nowell –\",\"Christ is born, the infant son of Mary!’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0032', 'verse', 2, 1, '[\"Mighty God, Emmanuel –\",\"prince of whom the prophets tell,\",\"child announced by Gabriel,\",\"the holy One, the infant son of Mary.\",\"Let the people...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0032', 'verse', 3, 2, '[\"Come, you choirs, with gladness sing,\",\"instruments of music bring –\",\"eager to proclaim the king,\",\"the holy One, the infant son of Mary.\",\"Let the people...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0032', 'verse', 4, 3, '[\"Love is here to seek and save –\",\"heaven’s master as a slave:\",\"God so loved the world he gave\",\"the holy One, the infant son of Mary.\",\"Let the people...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0033', 33, 'Christians, awake!', 'CP', 'en', 'in this version The Jubilate Group. www.jubilate.co.uk. Used by permission.            last verse arrangement and descant ? John Barnard, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Christians, awake! Salute the happy morn
on which the saviour of the world was born;
rise to adore the mystery of love
which hosts of angels chanted from above!
With them the joyful tidings first begun
of God incarnate and the virgin’s Son.
First, to the watchful shepherds it was told,
who heard the herald angel’s voice: ‘Behold,
I bring good news of your Messiah’s birth
to you and all the nations here on earth!
This day has God fulfilled his promised word;
this day is born a saviour, Christ the Lord!’
To Bethlehem these eager shepherds ran
to see the wonder of our God made man;
they found, with Joseph and the holy maid,
Jesus, the saviour, in a manger laid.
Amazed, with joy this story they proclaim,
the first apostles of his infant fame.
Let us, like those good shepherds, now employ
our grateful voices to declare the joy:
trace we the babe, who has redeemed our loss,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0033', 'John Byrom');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0033', 'John Wainwright');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0033', 'William Henry Monk');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0033', 'verse', 1, 0, '[\"Christians, awake! Salute the happy morn\",\"on which the saviour of the world was born;\",\"rise to adore the mystery of love\",\"which hosts of angels chanted from above!\",\"With them the joyful tidings first begun\",\"of God incarnate and the virgin’s Son.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0033', 'verse', 2, 1, '[\"First, to the watchful shepherds it was told,\",\"who heard the herald angel’s voice: ‘Behold,\",\"I bring good news of your Messiah’s birth\",\"to you and all the nations here on earth!\",\"This day has God fulfilled his promised word;\",\"this day is born a saviour, Christ the Lord!’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0033', 'verse', 3, 2, '[\"To Bethlehem these eager shepherds ran\",\"to see the wonder of our God made man;\",\"they found, with Joseph and the holy maid,\",\"Jesus, the saviour, in a manger laid.\",\"Amazed, with joy this story they proclaim,\",\"the first apostles of his infant fame.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0033', 'verse', 4, 3, '[\"Let us, like those good shepherds, now employ\",\"our grateful voices to declare the joy:\",\"trace we the babe, who has redeemed our loss,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0034', 34, 'Christmas is coming', 'CP', 'en', '1992 WGRG, The Iona Community, 4th Floor, Savoy House, 140 Sauchiehall Street, Glasgow G2 EDH', '', 0, 0, 0, 1, 1, 'Christmas is coming,
the Church is glad to sing,
and let the advent candles
brightly burn in a ring.
The first is for God’s promise
to put the wrong things right,
and bring to earth’s darkness
the hope of love and light.
Christmas is coming...
The second for the prophets,
who said that Christ would come
with good news for many
and angry words for some.
Christmas is coming...
The third is for the Baptist,
who cried, ‘Prepare the way.
Be ready for Jesus,
both this and every day.’
Christmas is coming...
The fourth is for the Virgin,
who mothered God’s own son
and sang how God’s justice
was meant for everyone.
Christmas is coming...
At last we light the candle
kept new for Christmas day.
This shines bright for Jesus,
new-born, and here to stay.
Christ is among us.
The candles in the ring
remind us that our Saviour
will light up everything.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0034', 'John L Bell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0034', 'John L Bell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0034', 'chorus', 0, 0, '[\"Christmas is coming,\",\"the Church is glad to sing,\",\"and let the advent candles\",\"brightly burn in a ring.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0034', 'verse', 1, 1, '[\"The first is for God’s promise\",\"to put the wrong things right,\",\"and bring to earth’s darkness\",\"the hope of love and light.\",\"Christmas is coming...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0034', 'verse', 2, 2, '[\"The second for the prophets,\",\"who said that Christ would come\",\"with good news for many\",\"and angry words for some.\",\"Christmas is coming...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0034', 'verse', 3, 3, '[\"The third is for the Baptist,\",\"who cried, ‘Prepare the way.\",\"Be ready for Jesus,\",\"both this and every day.’\",\"Christmas is coming...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0034', 'verse', 4, 4, '[\"The fourth is for the Virgin,\",\"who mothered God’s own son\",\"and sang how God’s justice\",\"was meant for everyone.\",\"Christmas is coming...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0034', 'verse', 5, 5, '[\"At last we light the candle\",\"kept new for Christmas day.\",\"This shines bright for Jesus,\",\"new-born, and here to stay.\",\"Christ is among us.\",\"The candles in the ring\",\"remind us that our Saviour\",\"will light up everything.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0035', 35, 'Christmas for God’s holy people', 'CP', 'en', 'Michael Saward, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            ? Stainer & Bell Ltd, 23 Gruneisen Road, London N3 1DZ. www.stainer.co.uk', '', 0, 0, 0, 1, 1, 'Christmas for God’s holy people
is a time of joy and peace:
so, all Christian men and women,
hymns and carols let us raise
to our God
come to earth,
Son of Man, by human birth.
Child of Mary, virgin mother,
peasant baby, yet our king,
cradled there among the oxen:
joyful carols now we sing
to our God...
Angel armies sang in chorus
at our Christ’s nativity;
he who came to share our nature:
so we sing with gaiety
to our God...
Shepherds hurried to the manger,
saw the babe of Bethlehem,
glorified the God of heaven:
now we join to sing with them
to our God...
Infant lowly, born in squalor,
prophet, king and great high priest,
Word of God, to us descending:
still we sing, both great and least,
to our God...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0035', 'Michael Saward');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0035', 'Sydney Carter');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0035', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0035', 'verse', 1, 0, '[\"Christmas for God’s holy people\",\"is a time of joy and peace:\",\"so, all Christian men and women,\",\"hymns and carols let us raise\",\"to our God\",\"come to earth,\",\"Son of Man, by human birth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0035', 'verse', 2, 1, '[\"Child of Mary, virgin mother,\",\"peasant baby, yet our king,\",\"cradled there among the oxen:\",\"joyful carols now we sing\",\"to our God...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0035', 'verse', 3, 2, '[\"Angel armies sang in chorus\",\"at our Christ’s nativity;\",\"he who came to share our nature:\",\"so we sing with gaiety\",\"to our God...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0035', 'verse', 4, 3, '[\"Shepherds hurried to the manger,\",\"saw the babe of Bethlehem,\",\"glorified the God of heaven:\",\"now we join to sing with them\",\"to our God...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0035', 'verse', 5, 4, '[\"Infant lowly, born in squalor,\",\"prophet, king and great high priest,\",\"Word of God, to us descending:\",\"still we sing, both great and least,\",\"to our God...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0036', 36, 'Christmas news', 'CP', 'en', 'David Mowbray, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Christmas news! Christ is born,
night has fled bright the dawn,
angel hosts greet the morn,
shepherds there adore him,
wise men kneel before him.
Lift your hearts today
mercy starts today.
Christmas news!
Christ is born,
Christ our Lord and Saviour.
Christmas news! Christ the boy
Israel’s hope, Mary’s joy
Herod’s hate can’t destroy:
now he takes our nature,
grows in grace and stature.
Lift your hearts...
Christmas news! Christ stoops low,
all our grief he will know,
every hurt, every blow,
like his human brothers
yet unlike all others.
Lift your hearts...
Christmas news! Christ the Lord
in our world has restored
what was spoilt, what was flawed:
praise his incarnation,
cross and resurrection.
Lift your hearts...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0036', 'David Mowbray');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0036', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0036', 'verse', 1, 0, '[\"Christmas news! Christ is born,\",\"night has fled bright the dawn,\",\"angel hosts greet the morn,\",\"shepherds there adore him,\",\"wise men kneel before him.\",\"Lift your hearts today\",\"mercy starts today.\",\"Christmas news!\",\"Christ is born,\",\"Christ our Lord and Saviour.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0036', 'verse', 2, 1, '[\"Christmas news! Christ the boy\",\"Israel’s hope, Mary’s joy\",\"Herod’s hate can’t destroy:\",\"now he takes our nature,\",\"grows in grace and stature.\",\"Lift your hearts...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0036', 'verse', 3, 2, '[\"Christmas news! Christ stoops low,\",\"all our grief he will know,\",\"every hurt, every blow,\",\"like his human brothers\",\"yet unlike all others.\",\"Lift your hearts...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0036', 'verse', 4, 3, '[\"Christmas news! Christ the Lord\",\"in our world has restored\",\"what was spoilt, what was flawed:\",\"praise his incarnation,\",\"cross and resurrection.\",\"Lift your hearts...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0037', 37, 'Clear and calm the night', 'CP', 'en', 'Zhi Wei and Wu Jing-reu / Copyright control. English ? Brynmor Price and Michael Ball / Copyright control            ? Shi Qu-gui / Copyright control', '', 0, 0, 0, 1, 1, 'Clear and calm the night –
holy night of nights.
Earth and mountains tranquil lie
under starry lights.
Like a mother’s arms, the hills
embrace the holy town of Bethlehem
where the heavenly Babe lies in stable bare.
Clear and calm the night –
holy night of nights.
Shepherds tremble as they hear
angels in the heights.
‘Hallelujah!’ echoes back from earth;
news with jade harps sounded out –
good news for us all of the Saviour’s birth.
Clear and calm the night –
holy night of nights.
Jesus Christ is born to us,
earthing heaven’s delights.
Sacrifice and joy and peace and love,
righteousness, forgiveness, hope
shine from Jesus’ face – glory from above!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0037', 'Zhi Wei');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0037', 'Wu Jing-reu');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0037', 'Shi Qu-gui');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0037', 'verse', 1, 0, '[\"Clear and calm the night –\",\"holy night of nights.\",\"Earth and mountains tranquil lie\",\"under starry lights.\",\"Like a mother’s arms, the hills\",\"embrace the holy town of Bethlehem\",\"where the heavenly Babe lies in stable bare.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0037', 'verse', 2, 1, '[\"Clear and calm the night –\",\"holy night of nights.\",\"Shepherds tremble as they hear\",\"angels in the heights.\",\"‘Hallelujah!’ echoes back from earth;\",\"news with jade harps sounded out –\",\"good news for us all of the Saviour’s birth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0037', 'verse', 3, 2, '[\"Clear and calm the night –\",\"holy night of nights.\",\"Jesus Christ is born to us,\",\"earthing heaven’s delights.\",\"Sacrifice and joy and peace and love,\",\"righteousness, forgiveness, hope\",\"shine from Jesus’ face – glory from above!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0038', 38, 'Come all you good people', 'CP', 'en', 'Michael Saward, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Come all you good people and burst into song!
be joyful and happy, your praises prolong;
remember the birthday of Jesus our king,
who brings us salvation: his glory we sing.
His mother, a virgin so gentle and pure
was told of God’s promise, unchanging and sure,
foretelling the birthday of Jesus our king,
who brings us salvation: his glory we sing.
To Bethlehem hurried the shepherds amazed,
with stories of angels and heavens that blazed,
proclaiming the birthday of Jesus our king,
who brings us salvation: his glory we sing.
So come let us honour the babe in the hay
and give him our homage and worship today,
recalling the birthday of Jesus our king,
who brings us salvation: his glory we sing.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0038', 'Michael Saward');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0038', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0038', 'verse', 1, 0, '[\"Come all you good people and burst into song!\",\"be joyful and happy, your praises prolong;\",\"remember the birthday of Jesus our king,\",\"who brings us salvation: his glory we sing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0038', 'verse', 2, 1, '[\"His mother, a virgin so gentle and pure\",\"was told of God’s promise, unchanging and sure,\",\"foretelling the birthday of Jesus our king,\",\"who brings us salvation: his glory we sing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0038', 'verse', 3, 2, '[\"To Bethlehem hurried the shepherds amazed,\",\"with stories of angels and heavens that blazed,\",\"proclaiming the birthday of Jesus our king,\",\"who brings us salvation: his glory we sing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0038', 'verse', 4, 3, '[\"So come let us honour the babe in the hay\",\"and give him our homage and worship today,\",\"recalling the birthday of Jesus our king,\",\"who brings us salvation: his glory we sing.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0039', 39, 'Come and hear the joyful singing', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Come and hear the joyful singing,
alleluia, gloria,
set the bells of heaven ringing:
alleluia, gloria,
God the Lord has shown us favour –
alleluia, gloria,
Christ is born to be our saviour.
Alleluia, gloria!
Angels of his birth are telling,
alleluia, gloria,
prince of peace all powers excelling;
alleluia, gloria,
death and hell can not defeat him:
alleluia, gloria,
go to Bethlehem and greet him.
Alleluia, gloria!
Choir and people, shout in wonder,
alleluia, gloria,
let the merry organ thunder;
alleluia, gloria,
thank our God for love amazing,
alleluia, gloria,
Father, Son and Spirit praising.
Alleluia, gloria!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0039', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0039', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0039', 'verse', 1, 0, '[\"Come and hear the joyful singing,\",\"alleluia, gloria,\",\"set the bells of heaven ringing:\",\"alleluia, gloria,\",\"God the Lord has shown us favour –\",\"alleluia, gloria,\",\"Christ is born to be our saviour.\",\"Alleluia, gloria!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0039', 'verse', 2, 1, '[\"Angels of his birth are telling,\",\"alleluia, gloria,\",\"prince of peace all powers excelling;\",\"alleluia, gloria,\",\"death and hell can not defeat him:\",\"alleluia, gloria,\",\"go to Bethlehem and greet him.\",\"Alleluia, gloria!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0039', 'verse', 3, 2, '[\"Choir and people, shout in wonder,\",\"alleluia, gloria,\",\"let the merry organ thunder;\",\"alleluia, gloria,\",\"thank our God for love amazing,\",\"alleluia, gloria,\",\"Father, Son and Spirit praising.\",\"Alleluia, gloria!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0040', 40, 'Come and join the celebration', 'CP', 'en', '1972 High-Fye Music Ltd. Used by permission of Music Sales Ltd. All rights reserved. International copyright secured.', '', 0, 0, 0, 1, 1, 'Come and join the celebration –
it’s a very special day;
come and share our jubilation –
there’s a new king born today!
See the shepherds hurry down to Bethlehem,
gaze in wonder at the Son of God who lies before them:
Come and join...
Wise men journey, led to worship by a star,
kneel in homage, bringing precious gifts from lands afar, so
Come and join...
‘God is with us!’ – round the world the message bring;
he is with us – ‘Welcome!’ all the bells on earth are pealing:
Come and join...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0040', 'Valerie Collison');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0040', 'Valerie Collison');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0040', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0040', 'chorus', 0, 0, '[\"Come and join the celebration –\",\"it’s a very special day;\",\"come and share our jubilation –\",\"there’s a new king born today!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0040', 'verse', 1, 1, '[\"See the shepherds hurry down to Bethlehem,\",\"gaze in wonder at the Son of God who lies before them:\",\"Come and join...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0040', 'verse', 2, 2, '[\"Wise men journey, led to worship by a star,\",\"kneel in homage, bringing precious gifts from lands afar, so\",\"Come and join...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0040', 'verse', 3, 3, '[\"‘God is with us!’ – round the world the message bring;\",\"he is with us – ‘Welcome!’ all the bells on earth are pealing:\",\"Come and join...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0041', 41, 'Come and see the shining hope', 'CP', 'en', 'Christopher Idle, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David G Wilson and David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Come and see the shining hope that Christ’s apostle saw;
on the earth, confusion, but in heaven an open door,
where the living creatures praise the Lamb for evermore:
Love has the victory for ever!
Amen, he comes! to bring his own reward!
Amen, praise God! for justice now restored;
kingdoms of the world become the kingdoms of the Lord:
Love has the victory for ever!
All the gifts you send us, Lord, are faithful, good, and true;
holiness and righteousness are shown in all you do:
who can see your greatest Gift and fail to worship you?
Love has the victory for ever!
Amen, he comes...
Power and salvation all belong to God on high!
So the mighty multitudes of heaven make their cry,
singing Hallelujah! where the echoes never die:
Love has the victory for ever!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0041', 'Christopher Idle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0041', 'David G Wilson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0041', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0041', 'verse', 1, 0, '[\"Come and see the shining hope that Christ’s apostle saw;\",\"on the earth, confusion, but in heaven an open door,\",\"where the living creatures praise the Lamb for evermore:\",\"Love has the victory for ever!\",\"Amen, he comes! to bring his own reward!\",\"Amen, praise God! for justice now restored;\",\"kingdoms of the world become the kingdoms of the Lord:\",\"Love has the victory for ever!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0041', 'verse', 2, 1, '[\"All the gifts you send us, Lord, are faithful, good, and true;\",\"holiness and righteousness are shown in all you do:\",\"who can see your greatest Gift and fail to worship you?\",\"Love has the victory for ever!\",\"Amen, he comes...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0041', 'verse', 3, 2, '[\"Power and salvation all belong to God on high!\",\"So the mighty multitudes of heaven make their cry,\",\"singing Hallelujah! where the echoes never die:\",\"Love has the victory for ever!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0042', 42, 'Come and sing the Christmas story', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Come and sing the Christmas story
this holy night!
Christ is born: the hope of glory
dawns on our sight.
Alleluia! earth is ringing
with a thousand angels singing –
hear the message they are bringing
this holy night.
Jesus, Saviour, child of Mary
this holy night,
in a world confused and weary
you are our light.
God is in a manger lying,
self effacing, wealth denying,
life embracing, death defying
this holy night.
Lord of all! Let us acclaim him
this holy night;
king of our salvation name him,
throned in the height.
Son of Man – let us adore him:
all the earth is waiting for him;
Son of God – we bow before him
this holy night.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0042', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0042', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0042', 'verse', 1, 0, '[\"Come and sing the Christmas story\",\"this holy night!\",\"Christ is born: the hope of glory\",\"dawns on our sight.\",\"Alleluia! earth is ringing\",\"with a thousand angels singing –\",\"hear the message they are bringing\",\"this holy night.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0042', 'verse', 2, 1, '[\"Jesus, Saviour, child of Mary\",\"this holy night,\",\"in a world confused and weary\",\"you are our light.\",\"God is in a manger lying,\",\"self effacing, wealth denying,\",\"life embracing, death defying\",\"this holy night.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0042', 'verse', 3, 2, '[\"Lord of all! Let us acclaim him\",\"this holy night;\",\"king of our salvation name him,\",\"throned in the height.\",\"Son of Man – let us adore him:\",\"all the earth is waiting for him;\",\"Son of God – we bow before him\",\"this holy night.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0043', 43, 'Come let us all with one accord', 'CP', 'en', 'Copyright control            ? No?l Tredinnick, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'Come let us all with one accord,
hail the birthday of our Lord,
with hymns of glory, songs of praise,
Jesus child, to you we raise.
A stable room was where he lay,
ox and ass were there to stay;
beneath the bright stars in the sky,
lowly our nativity.
Glad shepherds came to view this sight,
sent by angels, gleaming white;
the hosts of heaven with one accord
praised our holy, infant Lord.
Three kings, they travelled from afar,
led and guided by a star
which gave them light upon their way
till they came to where he lay.
Rejoice all you who hear this song,
every person join the throng;
the angels did the theme prolong –
‘peace, goodwill for ever.’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0043', 'Unknown');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0043', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0043', 'verse', 1, 0, '[\"Come let us all with one accord,\",\"hail the birthday of our Lord,\",\"with hymns of glory, songs of praise,\",\"Jesus child, to you we raise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0043', 'verse', 2, 1, '[\"A stable room was where he lay,\",\"ox and ass were there to stay;\",\"beneath the bright stars in the sky,\",\"lowly our nativity.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0043', 'verse', 3, 2, '[\"Glad shepherds came to view this sight,\",\"sent by angels, gleaming white;\",\"the hosts of heaven with one accord\",\"praised our holy, infant Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0043', 'verse', 4, 3, '[\"Three kings, they travelled from afar,\",\"led and guided by a star\",\"which gave them light upon their way\",\"till they came to where he lay.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0043', 'verse', 5, 4, '[\"Rejoice all you who hear this song,\",\"every person join the throng;\",\"the angels did the theme prolong –\",\"‘peace, goodwill for ever.’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0044', 44, 'Come now, O Prince of peace', 'CP', 'en', '1991 Geonyong Lee', '', 0, 0, 0, 1, 1, 'Come now, O Prince of peace,
make us one body,
come, O Lord Jesus,
reconcile your people.
Come now, O God of love,
make us one body,
come, O Lord Jesus,
reconcile your people.
Come now and set us free,
O God, our Saviour,
come, O Lord Jesus,
reconcile all nations.
Come, Hope of unity,
make us one body,
come, O Lord Jesus,
reconcile all nations.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0044', 'Geonyong Lee');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0044', 'Geonyong Lee');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0044', 'verse', 1, 0, '[\"Come now, O Prince of peace,\",\"make us one body,\",\"come, O Lord Jesus,\",\"reconcile your people.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0044', 'verse', 2, 1, '[\"Come now, O God of love,\",\"make us one body,\",\"come, O Lord Jesus,\",\"reconcile your people.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0044', 'verse', 3, 2, '[\"Come now and set us free,\",\"O God, our Saviour,\",\"come, O Lord Jesus,\",\"reconcile all nations.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0044', 'verse', 4, 3, '[\"Come, Hope of unity,\",\"make us one body,\",\"come, O Lord Jesus,\",\"reconcile all nations.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0045', 45, 'Come, O long-expected Jesus', 'CP', 'en', 'in this version The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Come, O long-expected Jesus,
born to set your people free!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0045', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0045', 'John Stainer');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0045', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0045', 'verse', 1, 0, '[\"Come, O long-expected Jesus,\",\"born to set your people free!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0046', 46, 'Come, see the Lord', 'CP', 'en', '2000 Kevin Mayhew Ltd, Buxhall, Stowmarket, Suffolk IP14 3DJ, UK. www.kevinmayhew.com            ? John Barnard, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'Come see the Lord in his breathtaking splendour:
gaze at his majesty – bow and adore!
Enter his presence with wonder and worship –
he is the King, and enthroned evermore.
He is the Word who was sent by the Father,
born as a baby, a child of our race:
God here among us, revealed as a servant,
walking the pathway of truth and of grace.
He is the Lamb who was slain to redeem us –
there at the cross his appearance was marred;
though he emerged from the grave as the victor,
still from the nails and the spear he is scarred.
He is the Lord who ascended in triumph –
ever the sound of his praises shall ring!
Hail him the First and the Last, the Almighty:
Jesus, our Prophet, our Priest and our King.
Come see the Lord in his breathtaking splendour:
gaze at his majesty – bow and adore!
Come and acknowledge him Saviour and Sovereign:
Jesus our King is enthroned evermore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0046', 'Martin E Leckebusch');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0046', 'John Barnard');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0046', 'verse', 1, 0, '[\"Come see the Lord in his breathtaking splendour:\",\"gaze at his majesty – bow and adore!\",\"Enter his presence with wonder and worship –\",\"he is the King, and enthroned evermore.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0046', 'verse', 2, 1, '[\"He is the Word who was sent by the Father,\",\"born as a baby, a child of our race:\",\"God here among us, revealed as a servant,\",\"walking the pathway of truth and of grace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0046', 'verse', 3, 2, '[\"He is the Lamb who was slain to redeem us –\",\"there at the cross his appearance was marred;\",\"though he emerged from the grave as the victor,\",\"still from the nails and the spear he is scarred.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0046', 'verse', 4, 3, '[\"He is the Lord who ascended in triumph –\",\"ever the sound of his praises shall ring!\",\"Hail him the First and the Last, the Almighty:\",\"Jesus, our Prophet, our Priest and our King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0046', 'verse', 5, 4, '[\"Come see the Lord in his breathtaking splendour:\",\"gaze at his majesty – bow and adore!\",\"Come and acknowledge him Saviour and Sovereign:\",\"Jesus our King is enthroned evermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0047', 47, 'Cradle rocking', 'CP', 'en', '1975 Celebration / kingswaysongs.com. tym@kingsway.co.uk Europe and Commonwealth (excl. Canada, Australia and Africa). Used by permission.', '', 0, 0, 0, 1, 0, 'Cradle rocking, cattle lowing,
bright star guiding men to see
little Christ-child in the manger,
light of all the world to be:
Alleluia, holy Child,
hosanna in the highest;
gloria, Emmanuel,
hosanna in the highest!
Mother Mary, watching carefully
by the light of one bright star;
Bread of heaven, softly sleeping,
gentle gift of God to all:
Alleluia...
Who could guess, to see you lie there,
that you came to bring a sword?
Prince of peace, born in a manger,
with a price upon your soul.
Alleluia...
Do you know – so weak and helpless –
of the grace you bear to us;
do you dream yet of the kingdom
you will some day bring to pass?');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0047', 'Jodi Page Clark');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0047', 'Jodi Page Clark');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0047', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0047', 'verse', 1, 0, '[\"Cradle rocking, cattle lowing,\",\"bright star guiding men to see\",\"little Christ-child in the manger,\",\"light of all the world to be:\",\"Alleluia, holy Child,\",\"hosanna in the highest;\",\"gloria, Emmanuel,\",\"hosanna in the highest!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0047', 'verse', 2, 1, '[\"Mother Mary, watching carefully\",\"by the light of one bright star;\",\"Bread of heaven, softly sleeping,\",\"gentle gift of God to all:\",\"Alleluia...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0047', 'verse', 3, 2, '[\"Who could guess, to see you lie there,\",\"that you came to bring a sword?\",\"Prince of peace, born in a manger,\",\"with a price upon your soul.\",\"Alleluia...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0047', 'verse', 4, 3, '[\"Do you know – so weak and helpless –\",\"of the grace you bear to us;\",\"do you dream yet of the kingdom\",\"you will some day bring to pass?\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0048', 48, 'Ding dong! Merrily on high', 'CP', 'en', '', '', 0, 0, 0, 1, 1, 'Ding dong! Merrily on high
in heaven the bells are ringing.
Ding dong! Verily the sky
is riven with angels singing:
Gloria, hosanna in excelsis;
gloria, hosanna in excelsis!
E’en so, here below, below,
let steeple bells be swungen;
and i-o, i-o, i-o,
by priest and people sungen!
Gloria...
Pray you, dutifully prime
your matin chime, you ringers;
may you beautifully rhyme
your evetime song, you singers:
Gloria...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0048', 'George Ratcliffe Woodward');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0048', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0048', 'verse', 1, 0, '[\"Ding dong! Merrily on high\",\"in heaven the bells are ringing.\",\"Ding dong! Verily the sky\",\"is riven with angels singing:\",\"Gloria, hosanna in excelsis;\",\"gloria, hosanna in excelsis!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0048', 'verse', 2, 1, '[\"E’en so, here below, below,\",\"let steeple bells be swungen;\",\"and i-o, i-o, i-o,\",\"by priest and people sungen!\",\"Gloria...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0048', 'verse', 3, 2, '[\"Pray you, dutifully prime\",\"your matin chime, you ringers;\",\"may you beautifully rhyme\",\"your evetime song, you singers:\",\"Gloria...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0049', 49, 'Down from the height', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            ? No?l Tredinnick, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Down from the height of his glory he came,
willingly leaving his rightful domain:
Jesus was born in the image of man;
love was his motive and mercy his aim.
All through those days his resolve was the same
Jesus the servant, the sharer of pain:
perfect obedience, the path of disdain,
down to a death of derision and shame.
Now God has granted him honour and fame,
taken him up to the highest to reign:
‘Jesus is Lord!’ every voice shall maintain,
all of creation shall bow to his name.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0049', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0049', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0049', 'verse', 1, 0, '[\"Down from the height of his glory he came,\",\"willingly leaving his rightful domain:\",\"Jesus was born in the image of man;\",\"love was his motive and mercy his aim.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0049', 'verse', 2, 1, '[\"All through those days his resolve was the same\",\"Jesus the servant, the sharer of pain:\",\"perfect obedience, the path of disdain,\",\"down to a death of derision and shame.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0049', 'verse', 3, 2, '[\"Now God has granted him honour and fame,\",\"taken him up to the highest to reign:\",\"‘Jesus is Lord!’ every voice shall maintain,\",\"all of creation shall bow to his name.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0050', 50, 'Earth lies spellbound', 'CP', 'en', '1994 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Earth lies spellbound in darkness,
sin’s oppressive night;
yet in Bethlehem
hope is burning bright.
Mysteries are unfolding,
but the only sign
is a manger bed
where a baby cries.
Wake up, wake up, it’s Christmas morning,
Christ’s eternal day is dawning.
Angels sing in exultation,
fill the streets with celebration.
Now to God on high be glory,
to the earth proclaim the story.
Ring the bells in jubilation,
tell the news to every nation:
Christ has come!
Crowding stairways of starlight,
choirs of angels sing:
‘Glory, glory to God
in the highest heaven.’
Peace is stilling the violence,
hope is rising high,
God is watching us now
through a baby’s eyes.
Wake up, wake up...
Weakness shatters the powerful,
meekness shames the proud,
vain imaginings
come tumbling down.
Ancient mercies remembered;
hungry, satisfied,
lowly, humble hearts
are lifted high.
Wake up, wake up...
Wake up, it’s Christmas morning,
wake up, it’s Christmas morning,
wake up, it’s Christmas morning.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0050', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0050', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0050', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0050', 'verse', 1, 0, '[\"Earth lies spellbound in darkness,\",\"sin’s oppressive night;\",\"yet in Bethlehem\",\"hope is burning bright.\",\"Mysteries are unfolding,\",\"but the only sign\",\"is a manger bed\",\"where a baby cries.\",\"Wake up, wake up, it’s Christmas morning,\",\"Christ’s eternal day is dawning.\",\"Angels sing in exultation,\",\"fill the streets with celebration.\",\"Now to God on high be glory,\",\"to the earth proclaim the story.\",\"Ring the bells in jubilation,\",\"tell the news to every nation:\",\"Christ has come!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0050', 'verse', 2, 1, '[\"Crowding stairways of starlight,\",\"choirs of angels sing:\",\"‘Glory, glory to God\",\"in the highest heaven.’\",\"Peace is stilling the violence,\",\"hope is rising high,\",\"God is watching us now\",\"through a baby’s eyes.\",\"Wake up, wake up...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0050', 'verse', 3, 2, '[\"Weakness shatters the powerful,\",\"meekness shames the proud,\",\"vain imaginings\",\"come tumbling down.\",\"Ancient mercies remembered;\",\"hungry, satisfied,\",\"lowly, humble hearts\",\"are lifted high.\",\"Wake up, wake up...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0050', 'chorus', 0, 3, '[\"Wake up, it’s Christmas morning,\",\"wake up, it’s Christmas morning,\",\"wake up, it’s Christmas morning.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0051', 51, 'Emmanuel', 'CP', 'en', '1993 Golden Apple Productions, a division of Chester Music Ltd., 8/9 Frith Street, London W1V 5TZ. Used by permission of Music Sales Ltd. All rights reserved. International copyright secured.', '', 0, 0, 0, 1, 0, 'At the request of the copyright holder, words for this item have not been included.
