INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0052', 52, 'Empty he came', 'CP', 'en', 'Gavin Reid            ? Norman Warren, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'Empty he came
as a man to our race,
equal with God
yet forsaking his place –
humbly he served in our world,
humbly he served in our world.
Lowlier still,
he was willing to die
nailed to a cross
as the people passed by –
bravely he died in our world,
bravely he died in our world.
Raised by our God
for us all to revere,
given a name
that shall stand without peer –
honoured as Lord in our world,
honoured as Lord in our world.
Give us that mind
that refuses to claim
even our rights,
make our outlook the same –
humbly to serve in our world,
humbly to serve in our world.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0052', 'Gavin Reid');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0052', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0052', 'verse', 1, 0, '[\"Empty he came\",\"as a man to our race,\",\"equal with God\",\"yet forsaking his place –\",\"humbly he served in our world,\",\"humbly he served in our world.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0052', 'verse', 2, 1, '[\"Lowlier still,\",\"he was willing to die\",\"nailed to a cross\",\"as the people passed by –\",\"bravely he died in our world,\",\"bravely he died in our world.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0052', 'verse', 3, 2, '[\"Raised by our God\",\"for us all to revere,\",\"given a name\",\"that shall stand without peer –\",\"honoured as Lord in our world,\",\"honoured as Lord in our world.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0052', 'verse', 4, 3, '[\"Give us that mind\",\"that refuses to claim\",\"even our rights,\",\"make our outlook the same –\",\"humbly to serve in our world,\",\"humbly to serve in our world.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0053', 53, 'Eternal Word', 'CP', 'en', '2000 Kevin Mayhew Ltd, Buxhall, Stowmarket, Suffolk IP14 3DJ, UK. www.kevinmayhew.com            ? Norman Warren, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'Eternal Word, beyond creation’s story,
the central focus of the Father’s plan,
you were the One with God in the beginning
before the worlds of time and space began.
Eternal Light, the gift of life bestowing,
in whom the cosmos meets both source and end,
you are the light no darkness can extinguish,
the light which darkness cannot comprehend.
Though others came to herald your arrival,
you are the Word their words could scarcely tell:
eternal Light, your splendour shone among us;
eternal Life, you came with us to dwell.
Unrecognised, you came among your people;
so many proved reluctant to believe;
yet still you call us to become God’s children –
what finer gift could human hearts receive?
Eternal Life who shared our mortal journey,
eternal Light whose glory floods our gaze,
eternal Word whose grace and truth astound us,
eternal God, receive our heartfelt praise!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0053', 'Martin E Leckebusch');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0053', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0053', 'verse', 1, 0, '[\"Eternal Word, beyond creation’s story,\",\"the central focus of the Father’s plan,\",\"you were the One with God in the beginning\",\"before the worlds of time and space began.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0053', 'verse', 2, 1, '[\"Eternal Light, the gift of life bestowing,\",\"in whom the cosmos meets both source and end,\",\"you are the light no darkness can extinguish,\",\"the light which darkness cannot comprehend.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0053', 'verse', 3, 2, '[\"Though others came to herald your arrival,\",\"you are the Word their words could scarcely tell:\",\"eternal Light, your splendour shone among us;\",\"eternal Life, you came with us to dwell.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0053', 'verse', 4, 3, '[\"Unrecognised, you came among your people;\",\"so many proved reluctant to believe;\",\"yet still you call us to become God’s children –\",\"what finer gift could human hearts receive?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0053', 'verse', 5, 4, '[\"Eternal Life who shared our mortal journey,\",\"eternal Light whose glory floods our gaze,\",\"eternal Word whose grace and truth astound us,\",\"eternal God, receive our heartfelt praise!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0054', 54, 'Fear not, for I bring all people', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, '‘Fear not, for I bring all people
news of great joy,
news of great joy,
news of great joy:
‘On this day in David’s city
Jesus is born,
Jesus is born,
Jesus is born.
‘Glory in the highest heaven,
peace on the earth,
peace on the earth,
peace on the earth!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0054', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0054', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0054', 'verse', 1, 0, '[\"‘Fear not, for I bring all people\",\"news of great joy,\",\"news of great joy,\",\"news of great joy:\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0054', 'verse', 2, 1, '[\"‘On this day in David’s city\",\"Jesus is born,\",\"Jesus is born,\",\"Jesus is born.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0054', 'verse', 3, 2, '[\"‘Glory in the highest heaven,\",\"peace on the earth,\",\"peace on the earth,\",\"peace on the earth!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0055', 55, 'For God so loved the world', 'CP', 'en', 'Word & Music, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? No?l Tredinnick, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'For God so loved the world he gave his only Son,
who came to die that we might ever live;
and on a cruel cross our full redemption won,
that we might know the peace he longs to give!
Though he was rich, he came alone and poor for us;
though he was Lord, he served as if a slave;
though he was God, our human shape he bore for us;
to earth he came in love, his own to seek and save.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0055', 'Word & Music');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0055', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0055', 'verse', 1, 0, '[\"For God so loved the world he gave his only Son,\",\"who came to die that we might ever live;\",\"and on a cruel cross our full redemption won,\",\"that we might know the peace he longs to give!\",\"Though he was rich, he came alone and poor for us;\",\"though he was Lord, he served as if a slave;\",\"though he was God, our human shape he bore for us;\",\"to earth he came in love, his own to seek and save.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0056', 56, 'For to us a child is born', 'CP', 'en', 'Judy Gresham, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'For to us a child is born,
and to us a son is given,
and the government will be upon his shoulder;
of the increase of his rule there will be no end –
he will reign in righteousness and peace.
He’ll be called Wonderful,
Everlasting Father,
Counsellor, Prince of peace,
the Mighty God.
Oh, Immanuel, God is with us now,
Immanuel.
Oh, Immanuel, God is with us now,
Immanuel.
He’ll be called...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0056', 'Judy Gresham');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0056', 'Judy Gresham');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0056', 'chorus', 0, 0, '[\"For to us a child is born,\",\"and to us a son is given,\",\"and the government will be upon his shoulder;\",\"of the increase of his rule there will be no end –\",\"he will reign in righteousness and peace.\",\"He’ll be called Wonderful,\",\"Everlasting Father,\",\"Counsellor, Prince of peace,\",\"the Mighty God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0056', 'chorus', 0, 1, '[\"Oh, Immanuel, God is with us now,\",\"Immanuel.\",\"Oh, Immanuel, God is with us now,\",\"Immanuel.\",\"He’ll be called...\"]');
