INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0059', 'verse', 3, 2, '[\"Through the kisses of a friend’s betrayal,\",\"he was lifted on a cruel cross;\",\"he was punished for a world’s transgressions,\",\"he was suffering to save the lost.\",\"He fights for breath, he fights for me,\",\"loosing sinners from the claims of hell,\",\"and, with a shout, our souls are free –\",\"death defeated by Immanuel!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0059', 'verse', 4, 3, '[\"Now he’s standing in the place of honour,\",\"crowned with glory on the highest throne,\",\"interceding for his own beloved\",\"till his Father calls to bring them home!\",\"Then the skies will part as the trumpet sounds\",\"hope of heaven or the fear of hell;\",\"but the bride will run to her lover’s arms,\",\"giving glory to Immanuel!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0060', 60, 'Girls and boys', 'CP', 'en', 'Oxford University Press 1958. Reproduced by permission. In this version Word & Music / The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Girls and boys, leave your toys, make no noise,
kneel at his crib and worship him.
For this shrine, Child divine, is the sign
our Saviour’s here.
Alleluia, the church bells ring,
‘Alleluia!’ the angels sing,
alleluia from everything –
all must draw near!
On that day, far away, Jesus lay –
angels were watching round his head
Holy Child, mother mild, undefiled,
we sing your praise.
Alleluia, the church bells ring,
‘Alleluia!’ the angels sing,
alleluia from everything –
our hearts we raise.
Shepherds came at the fame of your name,
angels their guide to Bethlehem;
in that place, saw your face filled with grace,
stood at your door.
Alleluia, the church bells ring,
‘Alleluia!’ the angels sing,
alleluia from everything –
love evermore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0060', 'Malcolm Sargent');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0060', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0060', 'verse', 1, 0, '[\"Girls and boys, leave your toys, make no noise,\",\"kneel at his crib and worship him.\",\"For this shrine, Child divine, is the sign\",\"our Saviour’s here.\",\"Alleluia, the church bells ring,\",\"‘Alleluia!’ the angels sing,\",\"alleluia from everything –\",\"all must draw near!\"]');
