INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0060', 'verse', 3, 2, '[\"Shepherds came at the fame of your name,\",\"angels their guide to Bethlehem;\",\"in that place, saw your face filled with grace,\",\"stood at your door.\",\"Alleluia, the church bells ring,\",\"‘Alleluia!’ the angels sing,\",\"alleluia from everything –\",\"love evermore.\"]');
