INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0062', 'verse', 2, 1, '[\"Of tender love for God she sings,\",\"the chosen mother of the Son;\",\"she knows that wonders have begun,\",\"and trusts for all the future brings.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0062', 'verse', 3, 2, '[\"The angel chorus of the skies\",\"who come to tell us of God’s grace\",\"have yet to know his human face,\",\"to watch him die, to see him rise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0062', 'verse', 4, 3, '[\"Let praise be true and love sincere,\",\"rejoice to greet the saviour’s birth;\",\"let peace and honour fill the earth\",\"and mercy reign – for God is here!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0062', 'verse', 5, 4, '[\"Then lift your hearts and voices high,\",\"sing once again the Christmas song:\",\"for love and praise to Christ belong\",\"in shouts of joy, and lullaby.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0063', 63, 'Glory in the highest heaven', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? 1993 HarperCollinsReligious, administered by Copycare PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.', '', 0, 0, 0, 1, 1, '‘Glory in the highest heaven,
grace and peace on earth!’
To our world a Son is given,
songs attend his birth:
come with angel hosts to name him,
then proclaim him tell his worth!
Shepherds, these glad tidings hearing,
leave their flock and fold,
seek the place of Christ’s appearing
David’s town of old:
come to worship and adore him,
kneel before him and behold!
Wise men travel with their treasure,
frankincense they bring,
myrrh and gold in royal measure
this their offering;
come in homage, drawing near him
to revere him mighty king!
Christ is born! the sure salvation
for a world of wrong,
light of every generation,
hope awaited long:
come with joyful faith to meet him,
gladly greet him with a song!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0063', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0063', 'Edwin George Monk');
