INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0063', 'verse', 3, 2, '[\"Wise men travel with their treasure,\",\"frankincense they bring,\",\"myrrh and gold in royal measure\",\"this their offering;\",\"come in homage, drawing near him\",\"to revere him mighty king!\"]');
