INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0064', 64, 'Go, tell it on the mountain', 'CP', 'en', 'in this version Richard Bewes, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? No?l Tredinnick, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Go, tell it on the mountain,
over the hills and everywhere;
go tell it on the mountain,
that Jesus Christ is born!
The shepherds from the hillside
gave worship and adored;
they saw the Babe of Bethlehem
was Jesus Christ the Lord:
Go, tell...
The men from eastern countries
came later there to bring
their gifts of loving homage
to Jesus Christ the King:
Go, tell...
A road that Jews and Gentiles,
both rich and poor have trod –
it led them all to Bethl’em,
to Christ, the Son of God:
Go, tell...
The learnèd and the simple
come to the manger-stall;
he joins us in his family,
the saviour of us all!
Go, tell...
Words in this version by Richard Bewes');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0064', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0064', 'chorus', 0, 0, '[\"Go, tell it on the mountain,\",\"over the hills and everywhere;\",\"go tell it on the mountain,\",\"that Jesus Christ is born!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0064', 'verse', 1, 1, '[\"The shepherds from the hillside\",\"gave worship and adored;\",\"they saw the Babe of Bethlehem\",\"was Jesus Christ the Lord:\",\"Go, tell...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0064', 'verse', 2, 2, '[\"The men from eastern countries\",\"came later there to bring\",\"their gifts of loving homage\",\"to Jesus Christ the King:\",\"Go, tell...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0064', 'verse', 3, 3, '[\"A road that Jews and Gentiles,\",\"both rich and poor have trod –\",\"it led them all to Bethl’em,\",\"to Christ, the Son of God:\",\"Go, tell...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0064', 'verse', 4, 4, '[\"The learnèd and the simple\",\"come to the manger-stall;\",\"he joins us in his family,\",\"the saviour of us all!\",\"Go, tell...\",\"Words in this version by Richard Bewes\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0065', 65, 'God of God, the uncreated', 'CP', 'en', 'in this version The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'God of God, the uncreated
love before the world began;
he the source and he the ending,
Son of God and Son of Man,
Lord of all the things that have been,
master of the eternal plan,
evermore and evermore!
He is here, whom generations
sought throughout the ages long;
promised by the ancient prophets,
justice for a world of wrong,
God’s salvation for the faithful:
him we praise in endless song
evermore and evermore!
Happy is that day for ever
when, by God the Spirit’s grace,
lowly Mary, virgin mother,
bore the saviour of our race.
Man and child, the world’s redeemer
now displays his sacred face
evermore and evermore!
Praise him, heaven of the heavens,
praise him, angels in the height;
priests and prophets, bow before him,
saints who longed to see this sight.
Let no human voice be silent,
in his glory hearts unite
evermore and evermore!
Christ be praised with God the Father,
and the Holy Spirit, praised!
Hymns of worship, high thanksgiving
echo through a world amazed:
honour, majesty, dominion!
Songs of victory be raised
evermore and evermore!
Words after by Prudentius');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0065', 'John Mason Neale');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0065', 'Henry Williams Baker');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0065', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0065', 'verse', 1, 0, '[\"God of God, the uncreated\",\"love before the world began;\",\"he the source and he the ending,\",\"Son of God and Son of Man,\",\"Lord of all the things that have been,\",\"master of the eternal plan,\",\"evermore and evermore!\"]');
