INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0066', 66, 'God rest you merry', 'CP', 'en', 'in this version The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? No?l Tredinnick, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'God rest you merry, gentlemen,
let nothing you dismay!
for Jesus Christ our saviour
was born on Christmas Day,
to save us all from Satan’s power
when we were gone astray:
O tidings of comfort and joy,
comfort and joy!
O tidings of comfort and joy!
At Bethlehem in Judah
the holy babe was born;
they laid him in a manger
on this most happy morn:
at which his mother Mary
did neither fear nor scorn:
O tidings of comfort and joy...
From God our heavenly Father
a holy angel came;
the shepherds saw the glory
and heard the voice proclaim
that Christ was born in Bethlehem –
and Jesus is his name:
O tidings of comfort and joy...
Fear not, then said the angel,
let nothing cause you fright;
to you is born a saviour
in David’s town tonight,
to free all those who trust in him');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0066', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0066', 'verse', 1, 0, '[\"God rest you merry, gentlemen,\",\"let nothing you dismay!\",\"for Jesus Christ our saviour\",\"was born on Christmas Day,\",\"to save us all from Satan’s power\",\"when we were gone astray:\",\"O tidings of comfort and joy,\",\"comfort and joy!\",\"O tidings of comfort and joy!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0066', 'verse', 2, 1, '[\"At Bethlehem in Judah\",\"the holy babe was born;\",\"they laid him in a manger\",\"on this most happy morn:\",\"at which his mother Mary\",\"did neither fear nor scorn:\",\"O tidings of comfort and joy...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0066', 'verse', 3, 2, '[\"From God our heavenly Father\",\"a holy angel came;\",\"the shepherds saw the glory\",\"and heard the voice proclaim\",\"that Christ was born in Bethlehem –\",\"and Jesus is his name:\",\"O tidings of comfort and joy...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0066', 'verse', 4, 3, '[\"Fear not, then said the angel,\",\"let nothing cause you fright;\",\"to you is born a saviour\",\"in David’s town tonight,\",\"to free all those who trust in him\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0067', 67, 'God sent his son', 'CP', 'en', '1993 Geoff Weaver, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            ? Joseph Kiwele / Copyright control', '', 0, 0, 0, 1, 1, '');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0067', 'Geoff Weaver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0067', 'Unknown');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0067', 'Joseph Kiwele');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0068', 68, 'God whose love is everywhere', 'CP', 'en', 'Timothy Dudley-Smith, and from January 2007 administered by Oxford University Press. Reproduced by permission.            ? No?l Tredinnick, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'God whose love is everywhere
made our earth and all things fair,
ever keeps them in his care;
praise the God of love!
He who hung the stars in space
holds the spinning world in place;
praise the God of love!
Come with thankfulness to sing
of the gifts the seasons bring,
summer, winter, autumn, spring;
praise the God of love!
He who gave us breath and birth
gives us all the fruitful earth;
praise the God of love!
Mark what love the Lord displayed,
all our sins upon him laid,
by his blood our ransom paid;
praise the God of love!
Circled by that scarlet band
all the world is in his hand;
praise the God of love!
See the sign of love appear,
flame of glory, bright and clear,
light for all the world is here;
praise the God of love!
Gloom and darkness, get you gone!
Christ the Light of life has shone;
praise the God of love!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0068', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0068', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0068', 'verse', 1, 0, '[\"God whose love is everywhere\",\"made our earth and all things fair,\",\"ever keeps them in his care;\",\"praise the God of love!\",\"He who hung the stars in space\",\"holds the spinning world in place;\",\"praise the God of love!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0068', 'verse', 2, 1, '[\"Come with thankfulness to sing\",\"of the gifts the seasons bring,\",\"summer, winter, autumn, spring;\",\"praise the God of love!\",\"He who gave us breath and birth\",\"gives us all the fruitful earth;\",\"praise the God of love!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0068', 'verse', 3, 2, '[\"Mark what love the Lord displayed,\",\"all our sins upon him laid,\",\"by his blood our ransom paid;\",\"praise the God of love!\",\"Circled by that scarlet band\",\"all the world is in his hand;\",\"praise the God of love!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0068', 'verse', 4, 3, '[\"See the sign of love appear,\",\"flame of glory, bright and clear,\",\"light for all the world is here;\",\"praise the God of love!\",\"Gloom and darkness, get you gone!\",\"Christ the Light of life has shone;\",\"praise the God of love!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0069', 69, 'Good Christian people, rise and sing', 'CP', 'en', 'in this version Word & Music / The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? Norman Warren, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Good Christian people, rise and sing
to greet the news the angels bring;
good Christian people, rise and sing
to greet the news the angels bring:
news of great joy for all the earth,
news of our holy saviour’s birth!
Rejoice and be no longer sad,
for Christ is born to make us glad;
rejoice and be no longer sad,
for Christ is born to make us glad:
his power will drive away our sin,
his lowly birth our love shall win.
Now in our darkness shines the light
which made the angels sing that night;
now in our darkness shines the light
which made the angels sing that night.
Glory to God! good-will and peace
be to us all, and never cease!
Words in this version by Word & Music');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0069', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0069', 'verse', 1, 0, '[\"Good Christian people, rise and sing\",\"to greet the news the angels bring;\",\"good Christian people, rise and sing\",\"to greet the news the angels bring:\",\"news of great joy for all the earth,\",\"news of our holy saviour’s birth!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0069', 'verse', 2, 1, '[\"Rejoice and be no longer sad,\",\"for Christ is born to make us glad;\",\"rejoice and be no longer sad,\",\"for Christ is born to make us glad:\",\"his power will drive away our sin,\",\"his lowly birth our love shall win.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0069', 'verse', 3, 2, '[\"Now in our darkness shines the light\",\"which made the angels sing that night;\",\"now in our darkness shines the light\",\"which made the angels sing that night.\",\"Glory to God! good-will and peace\",\"be to us all, and never cease!\",\"Words in this version by Word & Music\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0070', 70, 'Good Christians all, rejoice', 'CP', 'en', '', '', 0, 0, 0, 1, 1, 'Good Christians all, rejoice
with heart and soul and voice!
listen now to what we say,
Jesus Christ is born today;
ox and ass before him bow
and he is in the manger now:
Christ is born today;
Christ is born today!
Good Christians all, rejoice
with heart and soul and voice!
hear the news of endless bliss,
Jesus Christ was born for this:
he has opened heaven’s door
and we are blessed for evermore!
Christ was born for this;
Christ was born for this.
Good Christians all, rejoice
with heart and soul and voice!
now you need not fear the grave;
Jesus Christ was born to save:
come at his most gracious call
to find salvation, one and all:
Christ was born to save;
Christ was born to save!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0070', 'John Mason Neale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0070', 'John Stainer');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0070', 'verse', 1, 0, '[\"Good Christians all, rejoice\",\"with heart and soul and voice!\",\"listen now to what we say,\",\"Jesus Christ is born today;\",\"ox and ass before him bow\",\"and he is in the manger now:\",\"Christ is born today;\",\"Christ is born today!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0070', 'verse', 2, 1, '[\"Good Christians all, rejoice\",\"with heart and soul and voice!\",\"hear the news of endless bliss,\",\"Jesus Christ was born for this:\",\"he has opened heaven’s door\",\"and we are blessed for evermore!\",\"Christ was born for this;\",\"Christ was born for this.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0070', 'verse', 3, 2, '[\"Good Christians all, rejoice\",\"with heart and soul and voice!\",\"now you need not fear the grave;\",\"Jesus Christ was born to save:\",\"come at his most gracious call\",\"to find salvation, one and all:\",\"Christ was born to save;\",\"Christ was born to save!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0071', 71, 'Good King Wenceslas', 'CP', 'en', 'in this version Word & Music / The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'ALL
Good king Wenceslas looked out
on the Feast of Stephen,
when the snow lay round about,
deep, and crisp, and even:
brightly shone the moon that night,
though the frost was cruel,
when a poor man came in sight,
gathering winter fuel.
KING
‘Hither, page, and stand by me!
If you know it, telling:
yonder poor man – who is he,
where and what his dwelling?’
PAGE
‘Sir, he lives a good way hence,
underneath the mountain;
right against the forest fence
by Saint Agnes’ fountain.’
KING
‘Bring me food, and bring me wine,
bring me pine logs hither:
you and I will see him dine,
when we take them thither.’
ALL
Page and monarch forth they went,
forth they went together,
through the wild wind’s loud lament
and the bitter weather.
PAGE
‘Sir, the night is darker now,
and the wind grows stronger;
fails my heart – I know not how,
I can go no longer.’
KING
‘Mark my footsteps well, my page,
follow in them boldly:
you shall find the winter’s rage
chills your blood less coldly.’
ALL
In his master’s steps he trod
where the snow lay even,
strong to do the will of God
in the hope of heaven:
therefore, Christians all, be sure,
grace and wealth possessing,
you that now will bless the poor
shall yourselves find blessing.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0071', 'John Mason Neale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0071', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0071', 'verse', 1, 0, '[\"ALL\",\"Good king Wenceslas looked out\",\"on the Feast of Stephen,\",\"when the snow lay round about,\",\"deep, and crisp, and even:\",\"brightly shone the moon that night,\",\"though the frost was cruel,\",\"when a poor man came in sight,\",\"gathering winter fuel.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0071', 'verse', 2, 1, '[\"KING\",\"‘Hither, page, and stand by me!\",\"If you know it, telling:\",\"yonder poor man – who is he,\",\"where and what his dwelling?’\",\"PAGE\",\"‘Sir, he lives a good way hence,\",\"underneath the mountain;\",\"right against the forest fence\",\"by Saint Agnes’ fountain.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0071', 'verse', 3, 2, '[\"KING\",\"‘Bring me food, and bring me wine,\",\"bring me pine logs hither:\",\"you and I will see him dine,\",\"when we take them thither.’\",\"ALL\",\"Page and monarch forth they went,\",\"forth they went together,\",\"through the wild wind’s loud lament\",\"and the bitter weather.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0071', 'verse', 4, 3, '[\"PAGE\",\"‘Sir, the night is darker now,\",\"and the wind grows stronger;\",\"fails my heart – I know not how,\",\"I can go no longer.’\",\"KING\",\"‘Mark my footsteps well, my page,\",\"follow in them boldly:\",\"you shall find the winter’s rage\",\"chills your blood less coldly.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0071', 'verse', 5, 4, '[\"ALL\",\"In his master’s steps he trod\",\"where the snow lay even,\",\"strong to do the will of God\",\"in the hope of heaven:\",\"therefore, Christians all, be sure,\",\"grace and wealth possessing,\",\"you that now will bless the poor\",\"shall yourselves find blessing.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0072', 72, 'Good news, good news', 'CP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Good news, good news to you we bring,
alleluia!
News of great joy that angels sing,
alleluia!
Tender mercy he has shown us,
joy to all the world;
for us God sends his only Son,
alleluia!
Let earth’s dark shadows fly away,
alleluia!
In Christ has dawned an endless day,
alleluia!
Tender mercy he has shown us...
Now God with us on earth resides,
alleluia!
And heaven’s door is open wide,
alleluia!
Tender mercy he has shown us...');
