INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0073', 'verse', 2, 1, '[\"Prince of peace, God’s Word incarnate,\",\"with the poor identified;\",\"all his riches and his glory\",\"for love’s sake are laid aside.\",\"Jesus comes to his creation,\",\"loving saviour, God’s dear Son:\",\"sing with joy, ring out your praises,\",\"‘Welcome to the holy One!’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0073', 'verse', 3, 2, '[\"Hear the message of salvation\",\"Jesus brings to every race,\",\"see the infant who embodies\",\"God’s great glory and his grace.\",\"Purest light will reach dark places\",\"through the love of Christ the Son:\",\"sing with joy, ring out your praises,\",\"‘Welcome to the holy One!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0074', 74, 'Hark! the herald angels sing', 'CP', 'en', '', '', 0, 0, 0, 1, 1, 'Hark! the herald angels sing
glory to the new-born King;
peace on earth and mercy mild,
God and sinners reconciled!
Joyful all you nations rise,
join the triumph of the skies;
with the angelic host proclaim,
‘Christ is born in Bethlehem’:
Hark! the herald angels sing
glory to the new-born King.
Christ, by highest heaven adored,
Christ, the everlasting Lord:
late in time behold him come,
offspring of a virgin’s womb;
veiled in flesh the Godhead see,
hail the incarnate Deity!
pleased as man with us to dwell,
Jesus our Emmanuel:
Hark! the herald...
Hail the heaven-born Prince of peace,
hail the Sun of righteousness;
light and life to all he brings,
risen with healing in his wings:
mild, he lays his glory by,
born that we no more may die;
born to raise us from the earth,
born to give us second birth:
Hark! the herald...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0074', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0074', 'Felix Mendelssohn');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0074', 'verse', 1, 0, '[\"Hark! the herald angels sing\",\"glory to the new-born King;\",\"peace on earth and mercy mild,\",\"God and sinners reconciled!\",\"Joyful all you nations rise,\",\"join the triumph of the skies;\",\"with the angelic host proclaim,\",\"‘Christ is born in Bethlehem’:\",\"Hark! the herald angels sing\",\"glory to the new-born King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0074', 'verse', 2, 1, '[\"Christ, by highest heaven adored,\",\"Christ, the everlasting Lord:\",\"late in time behold him come,\",\"offspring of a virgin’s womb;\",\"veiled in flesh the Godhead see,\",\"hail the incarnate Deity!\",\"pleased as man with us to dwell,\",\"Jesus our Emmanuel:\",\"Hark! the herald...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0074', 'verse', 3, 2, '[\"Hail the heaven-born Prince of peace,\",\"hail the Sun of righteousness;\",\"light and life to all he brings,\",\"risen with healing in his wings:\",\"mild, he lays his glory by,\",\"born that we no more may die;\",\"born to raise us from the earth,\",\"born to give us second birth:\",\"Hark! the herald...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0075', 75, 'Have you seen the little Child', 'CP', 'en', '1983 Mosie Lister Songs, administered by Copycare PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.', '', 0, 0, 0, 1, 1, 'Have you seen the little Child
born in Bethlehem this night?
Have you seen the little Child,
Mary’s new-born Son?
Did you hear the angels sing,
‘Glory to the new-born King’?
Did you hear the praises ring
for Mary’s new-born Son?
Did you kneel in Bethlehem?
Did you bow and worship him –
born the Saviour of us all,
Mary’s new-born Son?
Have you seen the little Child
born in Bethlehem this night?
Have you seen the little Child,
Mary’s new-born Son?');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0075', 'Mosie Lister');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0075', 'Mosie Lister');
