INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0075', 'verse', 2, 1, '[\"Did you hear the angels sing,\",\"‘Glory to the new-born King’?\",\"Did you hear the praises ring\",\"for Mary’s new-born Son?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0075', 'verse', 3, 2, '[\"Did you kneel in Bethlehem?\",\"Did you bow and worship him –\",\"born the Saviour of us all,\",\"Mary’s new-born Son?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0075', 'verse', 4, 3, '[\"Have you seen the little Child\",\"born in Bethlehem this night?\",\"Have you seen the little Child,\",\"Mary’s new-born Son?\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0076', 76, 'Hail to the Lord’s anointed', 'CP', 'en', '', '', 0, 0, 0, 1, 1, 'Hail to the Lord’s anointed,
great David’s greater son!
Hail, in the time appointed
his reign on earth begun!
He comes to break oppression,
to set the captive free,
to take away transgression
and rule in equity.
He comes with comfort speedy
to those who suffer wrong;
to save the poor and needy
and help the weak be strong:
to give them songs for sighing,
their darkness turn to light,
whose souls, condemned and dying,
are precious in his sight.
He shall come down like showers
upon the fruitful earth;
and love, joy, hope, like flowers
spring in his path to birth:
before him on the mountains
shall peace, the herald, go;
and righteousness in fountains');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0076', 'James Montgomery');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0076', 'Johann Crüger');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0076', 'verse', 1, 0, '[\"Hail to the Lord’s anointed,\",\"great David’s greater son!\",\"Hail, in the time appointed\",\"his reign on earth begun!\",\"He comes to break oppression,\",\"to set the captive free,\",\"to take away transgression\",\"and rule in equity.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0076', 'verse', 2, 1, '[\"He comes with comfort speedy\",\"to those who suffer wrong;\",\"to save the poor and needy\",\"and help the weak be strong:\",\"to give them songs for sighing,\",\"their darkness turn to light,\",\"whose souls, condemned and dying,\",\"are precious in his sight.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0076', 'verse', 3, 2, '[\"He shall come down like showers\",\"upon the fruitful earth;\",\"and love, joy, hope, like flowers\",\"spring in his path to birth:\",\"before him on the mountains\",\"shall peace, the herald, go;\",\"and righteousness in fountains\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0077', 77, 'He became poor', 'CP', 'en', '1989 WGRG, The Iona Community, 4th Floor, Savoy House, 140 Sauchiehall Street, Glasgow G2 EDH', '', 0, 0, 0, 1, 1, 'He became poor that we may be rich,
loving the world and leaving his throne;
King of all kings and Lord of all lords,
flesh of our flesh and bone of our bone.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0077', 'John L Bell');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0077', 'Graham Maule');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0077', 'John L Bell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0077', 'Graham Maule');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0077', 'verse', 1, 0, '[\"He became poor that we may be rich,\",\"loving the world and leaving his throne;\",\"King of all kings and Lord of all lords,\",\"flesh of our flesh and bone of our bone.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0078', 78, 'He came to earth in poverty', 'CP', 'en', '2000 Kevin Mayhew Ltd, Buxhall, Stowmarket, Suffolk IP14 3DJ, UK. www.kevinmayhew.com                        arrangement: ? David Peacock, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'He came to earth in poverty,
a child uniquely holy,
forsaking heaven’s majesty
to live among the lowly:
Emmanuel means God has come,
a child of human birth
and here with us he made his home,
the Son of God on earth.
A servant toiling with his hands,
his sovereignty concealing,
our daily lives he understands
with perfect fellow-feeling:
Emmanuel means God has come...
In meek obedience stooping down
to taste humiliation,
he freely took a thorny crown
for reconciliation:
Emmanuel means God has come...
Emmanuel! Our God is near,
our every sorrow sharing:
he knows our feelings – he is here,
our human frailty bearing:
Emmanuel means God has come...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0078', 'Martin E Leckebusch');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0078', 'Robert Lowry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0078', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0078', 'verse', 1, 0, '[\"He came to earth in poverty,\",\"a child uniquely holy,\",\"forsaking heaven’s majesty\",\"to live among the lowly:\",\"Emmanuel means God has come,\",\"a child of human birth\",\"and here with us he made his home,\",\"the Son of God on earth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0078', 'verse', 2, 1, '[\"A servant toiling with his hands,\",\"his sovereignty concealing,\",\"our daily lives he understands\",\"with perfect fellow-feeling:\",\"Emmanuel means God has come...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0078', 'verse', 3, 2, '[\"In meek obedience stooping down\",\"to taste humiliation,\",\"he freely took a thorny crown\",\"for reconciliation:\",\"Emmanuel means God has come...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0078', 'verse', 4, 3, '[\"Emmanuel! Our God is near,\",\"our every sorrow sharing:\",\"he knows our feelings – he is here,\",\"our human frailty bearing:\",\"Emmanuel means God has come...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0079', 79, 'He is here', 'CP', 'en', '1994 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'He is here,
and we have come to worship him,
in his presence opening
the treasures of our heart.
He is here,
the centre of our longings,
all our restless journeyings
are ended in his peace.
And God is here with us,
our Saviour, Jesus;
his mercy covers us.
Immanuel is here,
so tender, so near.
We welcome you, Immanuel,
adore you more than words can tell,
we worship you.
Immanuel is here,
he is here.
He is here,
and we have come to worship him,
in his presence opening
the treasures of our hearts.
He is here,
the One for whom the angels sing.
Heaven and earth are touching,
this is a holy place.
And God is here with us...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0079', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0079', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0079', 'verse', 1, 0, '[\"He is here,\",\"and we have come to worship him,\",\"in his presence opening\",\"the treasures of our heart.\",\"He is here,\",\"the centre of our longings,\",\"all our restless journeyings\",\"are ended in his peace.\",\"And God is here with us,\",\"our Saviour, Jesus;\",\"his mercy covers us.\",\"Immanuel is here,\",\"so tender, so near.\",\"We welcome you, Immanuel,\",\"adore you more than words can tell,\",\"we worship you.\",\"Immanuel is here,\",\"he is here.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0079', 'verse', 2, 1, '[\"He is here,\",\"and we have come to worship him,\",\"in his presence opening\",\"the treasures of our hearts.\",\"He is here,\",\"the One for whom the angels sing.\",\"Heaven and earth are touching,\",\"this is a holy place.\",\"And God is here with us...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0080', 80, 'He came down', 'CP', 'en', 'control                        arrangement: ? 1993 Geoff Weaver, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'He came down that we may have love;
he came down that we may have love;
he came down that we may have love;
hallelujah for evermore.
He came down that we may have peace;
He came down that we may have peace;
He came down that we may have peace;
hallelujah for evermore.
He came down that we may have joy;
He came down that we may have joy;
He came down that we may have joy;
hallelujah for evermore.
He came down that we may have power;
He came down that we may have power;
He came down that we may have power;
hallelujah for evermore.
He came down that we may have hope;
He came down that we may have hope;
He came down that we may have hope;
hallelujah for evermore.');
