INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0081', 'verse', 2, 1, '[\"Shepherds and their quiet sheep saw the angel bright;\",\"shepherds heard the angels singing in the night.\",\"Mother Mary...\"]');
