INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0082', 82, 'Hear how the bells', 'CP', 'en', 'Timothy Dudley-Smith, and from January 2007 administered by Oxford University Press. Reproduced by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'Hear how the bells of Christmas play!
Well may they ring for joy and say,
O praise him, alleluia;
God has fulfilled his promised word,
born is our Saviour and our Lord,
O praise him, O praise him,
alleluia, alleluia, alleluia!
Let all the waiting earth rejoice,
lift every heart and every voice,
O praise him, alleluia;
sing now the song to angels given,
glory to God in highest heaven!
O praise him...
As through the silence of the skies
shepherds in wonder heard arise,
O praise him, alleluia;
so may we hear again with them
songs in the night at Bethlehem,
O praise him...
All nature sang at Jesus’ birth,
hail the Creator come to earth!
O praise him, alleluia;
sun, moon and shining stars above,
tell out the story of his love,
O praise him...
Hear how the bells of Christmas play!
Well may they ring for joy and say,
O praise him, alleluia;
come now to worship and adore,
Christ is our peace for evermore,
O praise him...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0082', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0082', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0082', 'verse', 1, 0, '[\"Hear how the bells of Christmas play!\",\"Well may they ring for joy and say,\",\"O praise him, alleluia;\",\"God has fulfilled his promised word,\",\"born is our Saviour and our Lord,\",\"O praise him, O praise him,\",\"alleluia, alleluia, alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0082', 'verse', 2, 1, '[\"Let all the waiting earth rejoice,\",\"lift every heart and every voice,\",\"O praise him, alleluia;\",\"sing now the song to angels given,\",\"glory to God in highest heaven!\",\"O praise him...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0082', 'verse', 3, 2, '[\"As through the silence of the skies\",\"shepherds in wonder heard arise,\",\"O praise him, alleluia;\",\"so may we hear again with them\",\"songs in the night at Bethlehem,\",\"O praise him...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0082', 'verse', 4, 3, '[\"All nature sang at Jesus’ birth,\",\"hail the Creator come to earth!\",\"O praise him, alleluia;\",\"sun, moon and shining stars above,\",\"tell out the story of his love,\",\"O praise him...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0082', 'verse', 5, 4, '[\"Hear how the bells of Christmas play!\",\"Well may they ring for joy and say,\",\"O praise him, alleluia;\",\"come now to worship and adore,\",\"Christ is our peace for evermore,\",\"O praise him...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0083', 83, 'Hear the skies around', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Hear the skies around
fill with joyful sound,
and the praise of angels ring;
hear the skies...
Singing ‘Glory in the highest,’
singing ‘Glory to the King!’
Hear the skies...
‘To the earth be peace,
fear and sorrow cease!’
is the birthday news they bring.
‘To the earth...
Singing ‘Glory in the highest,’
singing ‘Glory to the King!’
‘To the earth...
Banish all dismay,
for on Christmas Day
there’s a song of praise to sing;
Banish all dismay...
Singing ‘Glory in the highest,’
singing ‘Glory to the King!’
Banish all dismay...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0083', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0083', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0083', 'verse', 1, 0, '[\"Hear the skies around\",\"fill with joyful sound,\",\"and the praise of angels ring;\",\"hear the skies...\",\"Singing ‘Glory in the highest,’\",\"singing ‘Glory to the King!’\",\"Hear the skies...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0083', 'verse', 2, 1, '[\"‘To the earth be peace,\",\"fear and sorrow cease!’\",\"is the birthday news they bring.\",\"‘To the earth...\",\"Singing ‘Glory in the highest,’\",\"singing ‘Glory to the King!’\",\"‘To the earth...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0083', 'verse', 3, 2, '[\"Banish all dismay,\",\"for on Christmas Day\",\"there’s a song of praise to sing;\",\"Banish all dismay...\",\"Singing ‘Glory in the highest,’\",\"singing ‘Glory to the King!’\",\"Banish all dismay...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0084', 84, 'Hear the chimes as they ring', 'CP', 'en', '1980 Birdwing Music / BMG Songs / Garden Valley Music administered by Kevin Mayhew Ltd, Buxhall, Stowmarket, Suffolk IP14 3DJ, UK. www.kevinmayhew.com', '', 0, 0, 0, 1, 1, 'Hear the chimes (hear the chimes)
as they ring (as they ring),
they foretell (they foretell)
of the King (of the King);
he is born (he is born),
let us bring (let us bring)
every gift (every gift)
as we sing (as we sing)
to the King.
Hosanna! bring praises to the King.
Alleluia! let your praises ring.
Every land (every land),
every town (every town),
every home (every home),
every heart (every heart):
ring it out (ring it out),
sing and shout (sing and shout)
dance and sing (dance and sing),
let it ring (let it ring)
to the King.
Hosanna...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0084', 'Georgian Banov');
