INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0087', 87, 'Holy child', 'CP', 'en', 'Timothy Dudley-Smith, and from January 2007 administered by Oxford University Press. Reproduced by permission.            ? Michael Baughen, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.. arrangement: ? No?l Tredinnick, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Holy child, how still you lie!
safe the manger, soft the hay;
faint upon the eastern sky
breaks the dawn of Christmas Day.
Holy child, whose birthday brings
shepherds from their field and fold,
angel choirs and eastern kings,
myrrh and frankincense and gold:
Holy child, what gift of grace');
