INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0088', 88, 'Hush, do not cry', 'CP', 'en', 'in this version Word & Music / The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Hush, do not cry, my little tiny child:
Lullaby, lullaby!
O brothers, tell what ill befell
Bethlehem’s town this day;
let grief recite these infants’ plight,
sorrow and sore dismay.
Hush, do not cry,...
O sisters too, what may we do
and save from death today
this poor young thing to whom we sing:
‘Lullaby, lullalay’?
Hush, do not cry,...
Herod the king, in his raging,
gave his command this day:
his men of might in his own sight
all little boys to slay.
Hush, do not cry,...
Then woe is me, poor child, to see
this sad and sorry day;');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0088', 'R Croo');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0088', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0088', 'chorus', 0, 0, '[\"Hush, do not cry, my little tiny child:\",\"Lullaby, lullaby!\"]');
