INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0088', 'verse', 2, 2, '[\"O sisters too, what may we do\",\"and save from death today\",\"this poor young thing to whom we sing:\",\"‘Lullaby, lullalay’?\",\"Hush, do not cry,...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0088', 'verse', 3, 3, '[\"Herod the king, in his raging,\",\"gave his command this day:\",\"his men of might in his own sight\",\"all little boys to slay.\",\"Hush, do not cry,...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0088', 'verse', 4, 4, '[\"Then woe is me, poor child, to see\",\"this sad and sorry day;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0089', 89, 'Hush, little baby', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Hush, little baby; peace, little boy
slumbering in the hay;
dream while we carol tidings of joy,
Jesus of Christmas Day.
Angels will tell news of good cheer,
glory will light the sky;
shepherds will kneel wondering here,
worshipping God most high.
Hush, little baby...
Joseph will guard, Mary will smile,
holding in sweet embrace
heaven’s true Lord, here for a while,
Jesus, God’s gift of grace.
Hush, little baby...
Wise men from far, soon they will come,
worship and gifts they bring:
incense for prayer, myrrh for a tomb,
gold to reveal a king.
Hush, little baby...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0089', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0089', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0089', 'chorus', 0, 0, '[\"Hush, little baby; peace, little boy\",\"slumbering in the hay;\",\"dream while we carol tidings of joy,\",\"Jesus of Christmas Day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0089', 'verse', 1, 1, '[\"Angels will tell news of good cheer,\",\"glory will light the sky;\",\"shepherds will kneel wondering here,\",\"worshipping God most high.\",\"Hush, little baby...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0089', 'verse', 2, 2, '[\"Joseph will guard, Mary will smile,\",\"holding in sweet embrace\",\"heaven’s true Lord, here for a while,\",\"Jesus, God’s gift of grace.\",\"Hush, little baby...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0089', 'verse', 3, 3, '[\"Wise men from far, soon they will come,\",\"worship and gifts they bring:\",\"incense for prayer, myrrh for a tomb,\",\"gold to reveal a king.\",\"Hush, little baby...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0090', 90, 'Hush you, my baby', 'CP', 'en', 'Timothy Dudley-Smith, and from January 2007 administered by Oxford University Press. Reproduced by permission.            ? David Peacock, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'Hush you, my baby,
the night wind is cold,
the lambs from the hillside
are safe in the fold:
sleep with the starlight
and wake with the morn –
the Lord of all glory
a baby is born.
Hush you, my baby,
so soon to be grown,
watching by moonlight
on mountains alone,
toiling and travelling –
so sleep while you can,
till the Lord of all glory
is seen as a man.
Hush you, my baby,
the years will not stay,
the cross on the hilltop
the end of the way.
Dim through the darkness,
in grief and in gloom,
the Lord of all glory
lies cold in the tomb.
Hush you, my baby,
the Father on high
in power and dominion
the darkness puts by;
bright from the shadows,
the seal and the stone,
the Lord of all glory
returns to his own.
Hush you, my baby,
the sky turns to gold,
the lambs on the hillside
are loose from the fold;
fast fades the midnight
and new springs the morn,
the Lord of all glory
a Saviour is born.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0090', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0090', 'David Peacock');
