INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0094', 94, 'Immanuel', 'CP', 'en', 'Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Immanuel, O Immanuel,
bowed in awe I worship at your feet
and sing, Immanuel, God is with us;
sharing my humanness, my shame,
feeling my weaknesses, my pain,
taking the punishment, the blame –
Immanuel.
And now my words cannot explain
all that my heart cannot contain –
how great are the glories of your name,
Immanuel!');
