INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0096', 96, 'In a stable', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? Tom Cunningham, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'In a stable, in a manger,
lies a baby – our true saviour:
hear the carol that we sing you,
and the tidings that we bring you.
There’s a light in the heavens this morning
and a song for the angels to sing;
in a stable, in a manger,
lies a baby – our true saviour.
There the virgin mother Mary
tends her infant – oh so gently;
and the beauty of the Godhead
shines around him – her belovèd.
There’s a light...
Let the mighty faint and tremble
at the triumph of the humble;
and the guilty leave their sighing
where the sinner’s hope is lying.
There’s a light...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0096', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0096', 'Tom Cunningham');
