INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0096', 'verse', 2, 1, '[\"There the virgin mother Mary\",\"tends her infant – oh so gently;\",\"and the beauty of the Godhead\",\"shines around him – her belovèd.\",\"There’s a light...\"]');
