INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0097', 'verse', 2, 1, '[\"Many angels and a star\",\"led the people from afar\",\"to the place where Christ the saviour had been born.\",\"It was such an awesome sight,\",\"to behold him there that night,\",\"and to know his love would last for evermore.\",\"And the angels sang...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0097', 'verse', 3, 2, '[\"As we turn our minds again\",\"to the shepherds and wise men\",\"and the stable where our story did begin;\",\"though the manger now has gone,\",\"there’s a Saviour who lives on\",\"with an invitation now to worship him.\",\"And the angels sang...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0098', 98, 'In the bleak mid-winter', 'CP', 'en', '', '', 0, 0, 0, 1, 0, 'In the bleak mid-winter
frosty wind made moan,
earth stood hard as iron,
water like a stone;
snow had fallen, snow on snow,
snow on snow,
in the bleak mid-winter
long ago.
Heaven cannot hold him,
nor earth sustain;
heaven and earth shall flee away
when he comes to reign:
in the bleak mid-winter
a stable-place sufficed
God, the Lord almighty,
Jesus Christ.
Enough for him whom cherubim
worship night and day –
a breastful of milk,
and a manger full of hay;
enough for him whom angels
fall down before –
the wise men and the shepherds
who adore!
What can I give him,
poor as I am?
If I were a shepherd
I would give a lamb,
if I were a wise man
I would do my part;
yet what I can I give him –
give my heart.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0098', 'Christina Georgina Rossetti');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0098', 'Gustav Holst');
