INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0098', 'verse', 2, 1, '[\"Heaven cannot hold him,\",\"nor earth sustain;\",\"heaven and earth shall flee away\",\"when he comes to reign:\",\"in the bleak mid-winter\",\"a stable-place sufficed\",\"God, the Lord almighty,\",\"Jesus Christ.\"]');
