INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0098', 'verse', 4, 3, '[\"What can I give him,\",\"poor as I am?\",\"If I were a shepherd\",\"I would give a lamb,\",\"if I were a wise man\",\"I would do my part;\",\"yet what I can I give him –\",\"give my heart.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0099', 99, 'In the night, the sound of crying', 'CP', 'en', '2000 Kevin Mayhew Ltd, Buxhall, Stowmarket, Suffolk IP14 3DJ, UK. www.kevinmayhew.com            arrangement: ? No?l Tredinnick, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'In the night, the sound of crying –
whimpers from a babe so small:
angels hail the newborn infant
in that dingy cattle-stall.
In the night, the sound of crying –
Mary journeys on with tears,
further from the home she treasures,
onward to uncertain years.
In the night, the sound of crying –
fury nothing can assuage!
Schemes of pointless, brutal murder
spring from Herod’s jealous rage.
In the night, the sound of crying –
agonies beyond belief!
Soldiers searching, children slaughtered –
parents overwhelmed with grief.
In the night, the sound of crying –
cries of faith, though hope looks vain;
cries of joy, for Christ has conquered,
and, with justice, comes to reign.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0099', 'Martin E Leckebusch');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0099', 'Noël Tredinnick');
