INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0103', 'verse', 2, 1, '[\"Flocks were sleeping, shepherds keeping\",\"vigil till the morning new,\",\"saw the glory, heard the story –\",\"tidings of a gospel true.\",\"Thus rejoicing, free from sorrow,\",\"praises voicing greet tomorrow:\",\"Christ the babe was born for you;\",\"Christ the babe was born for you!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0104', 104, 'It was in Judah’s land', 'CP', 'en', 'in this version Word & Music, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            ? collected Berea College, Berea, Kentucky. arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'It was in Judah’s land
by God’s almighty hand
that Jesus Christ was born in a stable:
in a stable,
in a stable,
that Jesus Christ was born in a stable.
For by his mother’s hand
he was wrapped in swathing band
and in a manger laid in a stable:
in a stable,
in a stable,
and in a manger laid in a stable.
Words in this version by Word & Music');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0104', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0104', 'verse', 1, 0, '[\"It was in Judah’s land\",\"by God’s almighty hand\",\"that Jesus Christ was born in a stable:\",\"in a stable,\",\"in a stable,\",\"that Jesus Christ was born in a stable.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0104', 'verse', 2, 1, '[\"For by his mother’s hand\",\"he was wrapped in swathing band\",\"and in a manger laid in a stable:\",\"in a stable,\",\"in a stable,\",\"and in a manger laid in a stable.\",\"Words in this version by Word & Music\"]');
