INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0110', 'verse', 3, 2, '[\"Jesus, bringing hope to all who fear;\",\"Jesus, bringing strength to all who mourn:\",\"hear our prayer...\"]');
