INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0122', 'verse', 2, 1, '[\"He did not come in wealth and grandeur,\",\"he did not stand with men of power,\",\"he had no status to commend him,\",\"he was homeless – he was poor.\",\"Like a candle...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0122', 'verse', 3, 2, '[\"But he came to heal the wounded,\",\"and he came to heal the scars\",\"of a world that’s bruised and broken,\",\"where the image has been marred.\",\"Like a candle...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0122', 'verse', 4, 3, '[\"And we see him in the hungry\",\"and the homeless refugee,\",\"in the sick and dying children –\",\"his hands reach out for you and me.\",\"Like a candle...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0122', 'verse', 5, 4, '[\"And I feel his breath upon me,\",\"and he whispers, ‘Follow me!’\",\"and he grants his fire within me,\",\"says, ‘Let it shine for all to see!’\",\"Like a candle...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0123', 123, 'Little children, wake and listen', 'CP', 'en', '', '', 0, 0, 0, 1, 1, 'Little children, wake and listen!
songs are filling all the earth;
while the stars in heaven glisten,
hear the news of Jesus’ birth.
Long ago, to lonely meadows
angels brought the message down;
still each year through midnight shadows
it is heard in every town.
Shepherds hurry to the stable
by the inn at Bethlehem,
run as fast as they are able
to the baby born for them.
People find the news amazing
as on that first Christmas morn:
let us join the shepherds praising
God, for Christ the king is born!
Words verse 1 by L H Ward
Words verse 2 by The Jubilate Group');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0123', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0123', 'verse', 1, 0, '[\"Little children, wake and listen!\",\"songs are filling all the earth;\",\"while the stars in heaven glisten,\",\"hear the news of Jesus’ birth.\",\"Long ago, to lonely meadows\",\"angels brought the message down;\",\"still each year through midnight shadows\",\"it is heard in every town.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0123', 'verse', 2, 1, '[\"Shepherds hurry to the stable\",\"by the inn at Bethlehem,\",\"run as fast as they are able\",\"to the baby born for them.\",\"People find the news amazing\",\"as on that first Christmas morn:\",\"let us join the shepherds praising\",\"God, for Christ the king is born!\",\"Words verse 1 by L H Ward\",\"Words verse 2 by The Jubilate Group\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0124', 124, 'Little donkey', 'CP', 'en', '1959 Chappell Music Ltd, London W6 8BS. Reproduced by permission of Faber Music Ltd. All rights reserved.', '', 0, 0, 0, 1, 1, 'Little donkey, little donkey,
on a dusty road,
got to keep on plodding onward
with your precious load:
Been a long time little donkey,
through the winter’s night –
don’t give up now, little donkey,
Bethlehem’s in sight.
Ring out those bells tonight,
Bethlehem, Bethlehem;
follow that star tonight,
Bethlehem, Bethlehem!
Little donkey, little donkey,
had a heavy day –
little donkey, carry Mary
safely on her way.
Ring out...
Little donkey, little donkey,
had a heavy day –
little donkey, carry Mary
safely on her way.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0124', 'Eric Boswell');
