INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0124', 'verse', 1, 0, '[\"Little donkey, little donkey,\",\"on a dusty road,\",\"got to keep on plodding onward\",\"with your precious load:\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0124', 'verse', 2, 1, '[\"Been a long time little donkey,\",\"through the winter’s night –\",\"don’t give up now, little donkey,\",\"Bethlehem’s in sight.\",\"Ring out those bells tonight,\",\"Bethlehem, Bethlehem;\",\"follow that star tonight,\",\"Bethlehem, Bethlehem!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0124', 'verse', 3, 2, '[\"Little donkey, little donkey,\",\"had a heavy day –\",\"little donkey, carry Mary\",\"safely on her way.\",\"Ring out...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0124', 'verse', 4, 3, '[\"Little donkey, little donkey,\",\"had a heavy day –\",\"little donkey, carry Mary\",\"safely on her way.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0125', 125, 'Mary’s boy child', 'CP', 'en', 'Bourne Music Ltd', '', 0, 0, 0, 1, 1, 'Long time ago in Bethlehem,
so the Holy Bible say,
Mary’s boy-child, Jesus Christ,
was born on Christmas Day.
Hark now, hear the angels sing –
a new king born today!
And we may live for evermore
because of Christmas Day.
Trumpets sound and angels sing –
listen to what they say,
that we may live for evermore
because of Christmas Day.
While shepherds watch their flocks by night,
them see a bright new shining star;
them hear a choir sing –
the music seems to come from afar.
Now Joseph and his wife Mary
come to Bethlehem that night;
she have no place to bear her child –
not a single room was in sight.
Hark now...
By and by they find a little nook
in a stable all forlorn,
and in a manger cold and dark,
Mary’s little boy was born.
Long time ago in Bethlehem,
so the Holy Bible say,
Mary’s boy-child, Jesus Christ,
was born on Christmas Day.
Hark now...
Yes, we may live for evermore
because of Christmas Day.');
