INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0125', 'verse', 3, 2, '[\"Now Joseph and his wife Mary\",\"come to Bethlehem that night;\",\"she have no place to bear her child –\",\"not a single room was in sight.\",\"Hark now...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0125', 'verse', 4, 3, '[\"By and by they find a little nook\",\"in a stable all forlorn,\",\"and in a manger cold and dark,\",\"Mary’s little boy was born.\"]');
