INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0126', 126, 'Lord everlasting', 'CP', 'en', 'David Mowbray, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? No?l Tredinnick, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Lord everlasting yet child born in Bethlehem,
Mary your mother and favoured indeed,
sharing our struggle, our grief and uncertainty,
shining as light of the world in its need:
Lord God among us your strength found in gentleness,
greeted by shepherds in fields with their flock:
call us as servants, and send us as witnesses
to all our neighbours and places of work.
Lord of all lords and our promised deliverer,
worshipped by kings bringing gifts from afar:
guide with your wisdom all those in authority,
sparing the nations from hatred and war.
Lord, taking flight in a refugee family,
harrassed and threatened the poor of the earth:
open our hearts to the outcast and prisoner,
bringing compassion and justice to birth.
Lord, lowly stooping to raise up your broken ones
love at the crib and the cross is the same:
help us with angels your great name to glorify,
and with archangels that love to proclaim!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0126', 'David Mowbray');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0126', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0126', 'verse', 1, 0, '[\"Lord everlasting yet child born in Bethlehem,\",\"Mary your mother and favoured indeed,\",\"sharing our struggle, our grief and uncertainty,\",\"shining as light of the world in its need:\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0126', 'verse', 2, 1, '[\"Lord God among us your strength found in gentleness,\",\"greeted by shepherds in fields with their flock:\",\"call us as servants, and send us as witnesses\",\"to all our neighbours and places of work.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0126', 'verse', 3, 2, '[\"Lord of all lords and our promised deliverer,\",\"worshipped by kings bringing gifts from afar:\",\"guide with your wisdom all those in authority,\",\"sparing the nations from hatred and war.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0126', 'verse', 4, 3, '[\"Lord, taking flight in a refugee family,\",\"harrassed and threatened the poor of the earth:\",\"open our hearts to the outcast and prisoner,\",\"bringing compassion and justice to birth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0126', 'verse', 5, 4, '[\"Lord, lowly stooping to raise up your broken ones\",\"love at the crib and the cross is the same:\",\"help us with angels your great name to glorify,\",\"and with archangels that love to proclaim!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0127', 127, 'Lord, now let your servant depart', 'CP', 'en', '1984 Sovereign Music UK, PO Box 356, Leighton Buzzard LU7 3WP, UK. sovereignmusic@aol.com', '', 0, 0, 0, 1, 1, 'Lord, now let your servant depart in peace,
according to your word:
for my eyes have seen your salvation,
which you have prepared
before the face of the people;
to be a light to lighten the Gentiles,
and to be the glory of your people Israel.');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0127', 'Andrew Maries');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0127', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0127', 'verse', 1, 0, '[\"Lord, now let your servant depart in peace,\",\"according to your word:\",\"for my eyes have seen your salvation,\",\"which you have prepared\",\"before the face of the people;\",\"to be a light to lighten the Gentiles,\",\"and to be the glory of your people Israel.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0128', 128, 'Lord, speak softly to my soul', 'CP', 'en', 'Angela Griffiths, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'Lord, speak softly to my soul;
tell me more of that first Christmas night
when a warm breath of peace covered Bethlehem,
and the hills came alive with your light.
Lord, speak slowly; draw me near,
let me share in the joy of your birth:
did you know, even then, you would bear my shame –
did you weep for the sins of this earth?
Lord, speak gently; lead me on,
guide me straight to that rough stable door;
let me gaze on that low, holy manger bed
where the royal Son of God slept on straw.
Lord, speak clearly, teach me now,
hear my prayer; let my love overflow:
then my anthem will rise on the pure clear air,
as I pledge back the life that I owe.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0128', 'Angela Griffiths');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0128', 'Angela Griffiths');
