INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0128', 'verse', 2, 1, '[\"Lord, speak slowly; draw me near,\",\"let me share in the joy of your birth:\",\"did you know, even then, you would bear my shame –\",\"did you weep for the sins of this earth?\"]');
