INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0129', 129, 'Lord, we wait', 'CP', 'en', '2003 Thankyou Music, administered by worshiptogether.com songs excl. UK and Europe, administered by kingswaysongs.com. tym@kingsway.co.uk. Used by permission.', '', 0, 0, 0, 1, 0, 'Lord, we wait for the day of your appearing;
Lord, we wait for your coming in the clouds.
With a shout the trumpet will sound,
and the dead will be raised to life,
and we shall meet him in the air!
In that day death is swallowed up in victory;
in that day sin and death will be no more.
With a shout...
Now in part – we see shadows of his glory;
then in full – we shall see him face to face!
With a shout...');
