INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0130', 'verse', 2, 1, '[\"Lord, where have we left you –\",\"somewhere lost to light,\",\"submerged in doubt or dreaming\",\"and seeming out of sight?\"]');
