INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0131', 131, 'Lord, you were rich', 'CP', 'en', 'Overseas Missionary Fellowship and in this version The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? Copyright control', '', 0, 0, 0, 1, 1, 'Lord, you were rich beyond all splendour,
yet, for love’s sake, became so poor;
leaving your throne in glad surrender,
sapphire-paved courts for stable floor:
Lord, you were rich beyond all splendour,
yet, for love’s sake, became so poor.
You are our God beyond all praising,
yet, for love’s sake, became a man
stooping so low, but sinners raising
heavenwards, by your eternal plan:
you are our God beyond all praising,
yet, for love’s sake, became a man.
Lord, you are love beyond all telling,
Saviour and King, we worship you;
Emmanuel, within us dwelling,
make us and keep us pure and true:
Lord, you are love beyond all telling,
Saviour and King, we worship you.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0131', 'Frank Houghton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0131', 'C H Kitson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0131', 'verse', 1, 0, '[\"Lord, you were rich beyond all splendour,\",\"yet, for love’s sake, became so poor;\",\"leaving your throne in glad surrender,\",\"sapphire-paved courts for stable floor:\",\"Lord, you were rich beyond all splendour,\",\"yet, for love’s sake, became so poor.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0131', 'verse', 2, 1, '[\"You are our God beyond all praising,\",\"yet, for love’s sake, became a man\",\"stooping so low, but sinners raising\",\"heavenwards, by your eternal plan:\",\"you are our God beyond all praising,\",\"yet, for love’s sake, became a man.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0131', 'verse', 3, 2, '[\"Lord, you are love beyond all telling,\",\"Saviour and King, we worship you;\",\"Emmanuel, within us dwelling,\",\"make us and keep us pure and true:\",\"Lord, you are love beyond all telling,\",\"Saviour and King, we worship you.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0132', 132, 'Lord, you left your throne', 'CP', 'en', 'in this version Word & Music, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            Descant ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Lord, you left your throne and your kingly crown
when you came to this earth for me,
but in Bethlehem’s home there was found no room
for your holy nativity:
O come to my heart, Lord Jesus;
Emmanuel, come to me.
Heaven’s arches rang when the angels sang
proclaiming your royal degree,
but to lowly birth you came here on earth,
and in great humility:
O come to my heart, Lord Jesus;
Redeemer, be born in me.
You were sent, O Lord, with the living word
that should set your people free;
but with mocking scorn and with crown of thorn,
they bore you to Calvary:
O come to my heart, Lord Jesus,
your cross is my only plea.
When the heavens shall ring, and the choirs shall sing
at your coming to victory,
let your voice call me home saying, ‘Yes, there is room!’ –
there is room at your side for me.
Then my heart shall rejoice, Lord Jesus,
when you come and you call for me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0132', 'Emily Elizabeth Steele Elliott');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0132', 'Timothy Richard Matthews');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0132', 'verse', 1, 0, '[\"Lord, you left your throne and your kingly crown\",\"when you came to this earth for me,\",\"but in Bethlehem’s home there was found no room\",\"for your holy nativity:\",\"O come to my heart, Lord Jesus;\",\"Emmanuel, come to me.\"]');
