INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0133', 133, 'Love came down at Christmas', 'CP', 'en', 'in this version The Jubilate Group. www.jubilate.co.uk. Used by permission.            by permission of Oxford University Press', '', 0, 0, 0, 1, 1, 'Love came down at Christmas,
love all lovely, love divine;
love was born at Christmas –
star and angels gave the sign.
Worship we the Godhead,
love incarnate, love divine;
worship we our Jesus –
what shall be our sacred sign?
Love shall be our token,
love be yours and love be mine;
love to God and neighbour,
love for prayer and gift and sign.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0133', 'Christina Georgina Rossetti');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0133', 'Reginald Owen Morris');
