INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0135', 135, 'Lowly Jesus, king of glory', 'CP', 'en', 'Christopher Porteous, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Lowly Jesus, King of glory,
born on earth a little child,
in your mother’s arms a-sleeping,
pure and gentle, undefiled:
how I long, Lord, to adore you,
and to see you fast asleep,
like the shepherds round your manger,
leaving hillside, leaving sheep!
Loving Jesus, be my Master,
loving Jesus, be my King;
let me come close to your cradle,
hear the good news angels bring:
peace, good-will, from God in heaven
to all people here on earth,
through the coming of a baby,
through his lowly stable-birth.
Precious Jesus, be my Saviour –
in your mercy heal my sin;
please forgive me for my failures –
may your Spirit enter in.
Gift of wonder, gift of glory,
born to give us heavenly grace!
How I wish I were a wise man
to behold you face to face!
Holy Jesus, my Redeemer
in a manger for a bed,
ox and ass may bow before you –
but no pillow for your head.
God’s own Son who came to save me,
let your Spirit rule my heart;
let my body be your dwelling,
and your love fill every part.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0135', 'Christopher Porteous');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0135', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0135', 'verse', 1, 0, '[\"Lowly Jesus, King of glory,\",\"born on earth a little child,\",\"in your mother’s arms a-sleeping,\",\"pure and gentle, undefiled:\",\"how I long, Lord, to adore you,\",\"and to see you fast asleep,\",\"like the shepherds round your manger,\",\"leaving hillside, leaving sheep!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0135', 'verse', 2, 1, '[\"Loving Jesus, be my Master,\",\"loving Jesus, be my King;\",\"let me come close to your cradle,\",\"hear the good news angels bring:\",\"peace, good-will, from God in heaven\",\"to all people here on earth,\",\"through the coming of a baby,\",\"through his lowly stable-birth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0135', 'verse', 3, 2, '[\"Precious Jesus, be my Saviour –\",\"in your mercy heal my sin;\",\"please forgive me for my failures –\",\"may your Spirit enter in.\",\"Gift of wonder, gift of glory,\",\"born to give us heavenly grace!\",\"How I wish I were a wise man\",\"to behold you face to face!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0135', 'verse', 4, 3, '[\"Holy Jesus, my Redeemer\",\"in a manger for a bed,\",\"ox and ass may bow before you –\",\"but no pillow for your head.\",\"God’s own Son who came to save me,\",\"let your Spirit rule my heart;\",\"let my body be your dwelling,\",\"and your love fill every part.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0136', 136, 'Lullaby, little Jesus', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Lullaby, little Jesus;
there you lie, little Jesus –
as the winds bite
on this cold night –
in the hay, little Jesus.
As the winds bite
on this cold night:
Lullaby, little Jesus!
Lullaby, little Jesus;
don’t you cry, little Jesus:
come tomorrow
there’ll be sorrow
and dismay, little Jesus.
Come tomorrow
there’ll be sorrow.
Lullaby, little Jesus!
Lullaby, little Jesus:
in the sky, little Jesus,
there is singing,
glory bringing
to this day, little Jesus.
There is singing,
glory bringing.
Lullaby, little Jesus!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0136', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0136', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0136', 'verse', 1, 0, '[\"Lullaby, little Jesus;\",\"there you lie, little Jesus –\",\"as the winds bite\",\"on this cold night –\",\"in the hay, little Jesus.\",\"As the winds bite\",\"on this cold night:\",\"Lullaby, little Jesus!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0136', 'verse', 2, 1, '[\"Lullaby, little Jesus;\",\"don’t you cry, little Jesus:\",\"come tomorrow\",\"there’ll be sorrow\",\"and dismay, little Jesus.\",\"Come tomorrow\",\"there’ll be sorrow.\",\"Lullaby, little Jesus!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0136', 'verse', 3, 2, '[\"Lullaby, little Jesus:\",\"in the sky, little Jesus,\",\"there is singing,\",\"glory bringing\",\"to this day, little Jesus.\",\"There is singing,\",\"glory bringing.\",\"Lullaby, little Jesus!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0137', 137, 'Mary came with meekness', 'CP', 'en', 'Paul Wigmore, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Mary came with meekness, Jesus Christ to bear,
laid the Lord of glory in a manger there.
We come rejoicing, Jesus Christ to love:
baby in a manger – king of heaven above!
Angels came with praises, Jesus Christ to name,
heaven’s choirs exalting him who bears our shame.
We come rejoicing...
Shepherds came with trembling, Jesus Christ to see;
king who, at their bidding, would their shepherd be.
We come rejoicing...
Wise men came with treasure, Jesus Christ to bless –
he who shares all blessings heaven and earth possess.
We come rejoicing...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0137', 'Paul Wigmore');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0137', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0137', 'verse', 1, 0, '[\"Mary came with meekness, Jesus Christ to bear,\",\"laid the Lord of glory in a manger there.\",\"We come rejoicing, Jesus Christ to love:\",\"baby in a manger – king of heaven above!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0137', 'verse', 2, 1, '[\"Angels came with praises, Jesus Christ to name,\",\"heaven’s choirs exalting him who bears our shame.\",\"We come rejoicing...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0137', 'verse', 3, 2, '[\"Shepherds came with trembling, Jesus Christ to see;\",\"king who, at their bidding, would their shepherd be.\",\"We come rejoicing...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0137', 'verse', 4, 3, '[\"Wise men came with treasure, Jesus Christ to bless –\",\"he who shares all blessings heaven and earth possess.\",\"We come rejoicing...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0138', 138, 'Mary had a baby', 'CP', 'en', 'in this version Word & Music, administered by The Jubilate Group www.jubilate.co.uk. Used by permission.            arrangement: ? David Iliff, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Mary had a baby, yes, Lord;
Mary had a baby, yes, my Lord;
Mary had a baby, yes, Lord;
The people keep a-coming
for to see her child!
Words in this version by Word & Music');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0138', 'David Iliff');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0138', 'verse', 1, 0, '[\"Mary had a baby, yes, Lord;\",\"Mary had a baby, yes, my Lord;\",\"Mary had a baby, yes, Lord;\",\"The people keep a-coming\",\"for to see her child!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0138', 'verse', 2, 1, '[\"Words in this version by Word & Music\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0139', 139, 'Midnight', 'CP', 'en', 'Out of the Ark Music', '', 0, 0, 0, 1, 1, 'Midnight – there’s the strangest feeling in the air tonight,
there’s something going on, but I can’t make it out –
I wonder what it’s all about?
Starlight – breaking through the darkness in the dead of night,
illuminates the path that takes you out of sight
and all the way to Bethlehem.
Tonight’s events were planned in heaven,
the greatest story ever penned,
heaven and earth have come together
and life has come to Bethlehem.
Angels – taking care of things that only they can do,
are waiting in the wings to bring the joyful news –
it’s going to turn the world around.
Strangers – having made arrangements for a night or two,
have found accommodation in the crowded rooms,
the house is packed in Bethlehem.
Tonight’s events...
Shepherds minding their own business looking after things,
are startled by an unexpected happening
as angel choirs appear to them.
Wise men – taking charts and telescopes and compasses,
investigate the star that takes them travelling
until they come to Bethlehem.
Tonight’s events...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0139', 'Mark Johnson');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0139', 'Helen Johnson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0139', 'Mark Johnson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0139', 'Helen Johnson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0139', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0139', 'verse', 1, 0, '[\"Midnight – there’s the strangest feeling in the air tonight,\",\"there’s something going on, but I can’t make it out –\",\"I wonder what it’s all about?\",\"Starlight – breaking through the darkness in the dead of night,\",\"illuminates the path that takes you out of sight\",\"and all the way to Bethlehem.\",\"Tonight’s events were planned in heaven,\",\"the greatest story ever penned,\",\"heaven and earth have come together\",\"and life has come to Bethlehem.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0139', 'verse', 2, 1, '[\"Angels – taking care of things that only they can do,\",\"are waiting in the wings to bring the joyful news –\",\"it’s going to turn the world around.\",\"Strangers – having made arrangements for a night or two,\",\"have found accommodation in the crowded rooms,\",\"the house is packed in Bethlehem.\",\"Tonight’s events...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0139', 'verse', 3, 2, '[\"Shepherds minding their own business looking after things,\",\"are startled by an unexpected happening\",\"as angel choirs appear to them.\",\"Wise men – taking charts and telescopes and compasses,\",\"investigate the star that takes them travelling\",\"until they come to Bethlehem.\",\"Tonight’s events...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0140', 140, 'My Lord, he is a-coming soon', 'CP', 'en', '1975 Celebration / kingswaysongs.com. tym@kingsway.co.uk. For Europe and Commonwealth (excl. Canada, Australasia and Africa). Used by permission.', '', 0, 0, 0, 1, 0, 'My Lord, he is a-coming soon –
prepare the way of the Lord;
get everything ready for that day –
prepare the way of the Lord!
If you’re asleep, it’s time to wake up –
awake, O sleeper, arise!
If you’re in the dark, it’s time to be lit –
awake, O sleeper, arise!
My Lord...
Come, Lord Jesus, come into my heart –
prepare the way of the king!
He is coming, he’s coming soon:
prepare the way of the king!
My Lord...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0140', 'Laura Winnen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0140', 'Jeff Cothran');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0140', 'chorus', 0, 0, '[\"My Lord, he is a-coming soon –\",\"prepare the way of the Lord;\",\"get everything ready for that day –\",\"prepare the way of the Lord!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0140', 'verse', 1, 1, '[\"If you’re asleep, it’s time to wake up –\",\"awake, O sleeper, arise!\",\"If you’re in the dark, it’s time to be lit –\",\"awake, O sleeper, arise!\",\"My Lord...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0140', 'verse', 2, 2, '[\"Come, Lord Jesus, come into my heart –\",\"prepare the way of the king!\",\"He is coming, he’s coming soon:\",\"prepare the way of the king!\",\"My Lord...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0141', 141, 'My soul will glorify', 'CP', 'en', 'D T Niles / Christian Conference of Asia. in this version Word & Music, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? 1993 Geoff Weaver, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'My soul will glorify the Lord,
my spirit will rejoice;
for my Redeemer has looked down
and made my life his choice.
God’s willing servant I’ll become –
the mother of the Christ,
and wonder that for Jesus’ home
my humble heart sufficed.
Rejoice for ever at my name,
for God has done great things,
and holy is the one who came –
the saviour, King of kings.
The mercy of our God is great,
and sure his deeds of love;
he looks upon our lowly state
and lifts us high above.
The proud he scatters in their pride,
the rich must empty go;
the strong his strength has set aside,
the mighty are brought low.
The humble will yet high appear,
the poor be filled with food;
the God of Israel has drawn near –
the Lord, our God, is good!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0141', 'D T Niles');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0141', 'Geoff Weaver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0141', 'verse', 1, 0, '[\"My soul will glorify the Lord,\",\"my spirit will rejoice;\",\"for my Redeemer has looked down\",\"and made my life his choice.\",\"God’s willing servant I’ll become –\",\"the mother of the Christ,\",\"and wonder that for Jesus’ home\",\"my humble heart sufficed.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0141', 'verse', 2, 1, '[\"Rejoice for ever at my name,\",\"for God has done great things,\",\"and holy is the one who came –\",\"the saviour, King of kings.\",\"The mercy of our God is great,\",\"and sure his deeds of love;\",\"he looks upon our lowly state\",\"and lifts us high above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0141', 'verse', 3, 2, '[\"The proud he scatters in their pride,\",\"the rich must empty go;\",\"the strong his strength has set aside,\",\"the mighty are brought low.\",\"The humble will yet high appear,\",\"the poor be filled with food;\",\"the God of Israel has drawn near –\",\"the Lord, our God, is good!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0142', 142, 'Magnificat', 'CP', 'en', 'Sam Hargreaves, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, '');
