INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0143', 143, 'No wind at the window', 'CP', 'en', '1992 WGRG, The Iona Community, 4th Floor, Savoy House, 140 Sauchiehall Street, Glasgow G2 EDH', '', 0, 0, 0, 1, 1, 'No wind at the window,
no knock on the door;
no light from the lampstand,
no foot on the floor;
no dream born of tiredness,
no ghost raised by fear:
just an angel and a woman
and a voice in her ear.
‘Oh Mary, oh Mary,
don’t hide from my face.
Be glad that you’re favoured
and filled with God’s grace.
The time for redeeming
the world has begun;
and you are requested
to mother God’s son.’
‘This child must be born
that the kingdom might come:
salvation for many,
destruction for some;
both end and beginning,
both message and sign;
both victor and victim,
both yours and divine,’
No payment was promised,
no promises made;
no wedding was dated,
no blueprint displayed.
Yet Mary, consenting
to what none could guess,
replied with conviction
‘Tell God, I say yes.’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0143', 'John L Bell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0143', 'John L Bell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0143', 'verse', 1, 0, '[\"No wind at the window,\",\"no knock on the door;\",\"no light from the lampstand,\",\"no foot on the floor;\",\"no dream born of tiredness,\",\"no ghost raised by fear:\",\"just an angel and a woman\",\"and a voice in her ear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0143', 'verse', 2, 1, '[\"‘Oh Mary, oh Mary,\",\"don’t hide from my face.\",\"Be glad that you’re favoured\",\"and filled with God’s grace.\",\"The time for redeeming\",\"the world has begun;\",\"and you are requested\",\"to mother God’s son.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0143', 'verse', 3, 2, '[\"‘This child must be born\",\"that the kingdom might come:\",\"salvation for many,\",\"destruction for some;\",\"both end and beginning,\",\"both message and sign;\",\"both victor and victim,\",\"both yours and divine,’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0143', 'verse', 4, 3, '[\"No payment was promised,\",\"no promises made;\",\"no wedding was dated,\",\"no blueprint displayed.\",\"Yet Mary, consenting\",\"to what none could guess,\",\"replied with conviction\",\"‘Tell God, I say yes.’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0144', 144, 'The Gift', 'CP', 'en', '1994 Out of the Ark Music', '', 0, 0, 0, 1, 1, 'Nearly two thousand years ago,
under a starlight sky,
many events were taking place
as the ancients had prophesied.
And a gift was given from heaven to earth,
the everlasting light,
so let us adore the Saviour born –
Emmanuel here tonight.
Heavenly hosts of angels,
praising God on high,
sang of the promised child to come –
the Saviour, Jesus Christ.
And a gift was given...
Darkness was over Bethlehem,
brightly the stars did shine,
showing the way to where he lay
in a manger for all to find.
And a gift was given...
Never before in history
had there been such a sign;
for God was born in human form
for the sake of all the world.
And a gift was given from heaven to earth,
the everlasting light,
so let us adore the Saviour born –
Emmanuel here tonight.
So let us adore him, Christ the Lord –
Emmanuel here tonight!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0144', 'Mark Johnson');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0144', 'Helen Johnson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0144', 'Mark Johnson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0144', 'Helen Johnson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0144', 'David Peacock');
