INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0144', 'verse', 4, 3, '[\"Never before in history\",\"had there been such a sign;\",\"for God was born in human form\",\"for the sake of all the world.\",\"And a gift was given from heaven to earth,\",\"the everlasting light,\",\"so let us adore the Saviour born –\",\"Emmanuel here tonight.\",\"So let us adore him, Christ the Lord –\",\"Emmanuel here tonight!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0145', 145, 'Now is the time, the time of God’s favour', 'CP', 'en', 'Christopher Idle, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            ? Christopher Hayward, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Now is the time, the time of God’s favour,
promise and hope for a people restored ;
listen, repent, and turn back to the Saviour,
truly to welcome the year of our Lord!
This is the day of Jesus’ arrival;
here in the desert, the threshold of home.
After earth’s longings comes heaven’s revival;
God, make us ready this day as you come!
Now is the time...
Here is the hour, the hour of salvation;
learn the new song for new people to sing:
risen from death is the Source of creation;
lift up your heads for the hour of the King!
Now is the time...
Do not delay, but come now to meet him,
Sabbath and Jubilee joining in one;
Christmas and Easter and Advent will greet him;
see a fresh universe rise to the Son!
Now is the time...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0145', 'Christopher Idle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0145', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0145', 'chorus', 0, 0, '[\"Now is the time, the time of God’s favour,\",\"promise and hope for a people restored ;\",\"listen, repent, and turn back to the Saviour,\",\"truly to welcome the year of our Lord!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0145', 'verse', 1, 1, '[\"This is the day of Jesus’ arrival;\",\"here in the desert, the threshold of home.\",\"After earth’s longings comes heaven’s revival;\",\"God, make us ready this day as you come!\",\"Now is the time...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0145', 'verse', 2, 2, '[\"Here is the hour, the hour of salvation;\",\"learn the new song for new people to sing:\",\"risen from death is the Source of creation;\",\"lift up your heads for the hour of the King!\",\"Now is the time...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0145', 'verse', 3, 3, '[\"Do not delay, but come now to meet him,\",\"Sabbath and Jubilee joining in one;\",\"Christmas and Easter and Advent will greet him;\",\"see a fresh universe rise to the Son!\",\"Now is the time...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0146', 146, 'Saviour’s Day', 'CP', 'en', '1990 Clouseau Music / SGO Music Publishing Ltd, PO Box 2015, Salisbury SP2 7WU', '', 0, 0, 0, 1, 1, 'Now we have been through the harvest,
winter has truly begun;
now we have walked in the chill of the night
we are waiting for, waiting for,
for the Saviour’s Day.
Many have come from the valleys.
many have come from the hills,
many have started their journey home
to be with someone, with someone
on the Saviour’s Day.
Open your eyes on Saviour’s Day,
don’t look back or turn away,
life can be yours if you’ll only stay,
he is calling you, calling you
on the Saviour’s Day.
Joining the old and the young ones,
joining the black and the white,
meeting the need of the hungry is he –
will we ever remember him
on the Saviour’s Day?
Open your eyes...
Here’s to the God of the present,
here’s to the God of the past,
here’s to the hope in the future he brings,
we will sing to him, sing to him
on the Saviour’s Day.
Open your eyes...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0146', 'Chris Eaton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0146', 'Chris Eaton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0146', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0146', 'verse', 1, 0, '[\"Now we have been through the harvest,\",\"winter has truly begun;\",\"now we have walked in the chill of the night\",\"we are waiting for, waiting for,\",\"for the Saviour’s Day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0146', 'verse', 2, 1, '[\"Many have come from the valleys.\",\"many have come from the hills,\",\"many have started their journey home\",\"to be with someone, with someone\",\"on the Saviour’s Day.\",\"Open your eyes on Saviour’s Day,\",\"don’t look back or turn away,\",\"life can be yours if you’ll only stay,\",\"he is calling you, calling you\",\"on the Saviour’s Day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0146', 'verse', 3, 2, '[\"Joining the old and the young ones,\",\"joining the black and the white,\",\"meeting the need of the hungry is he –\",\"will we ever remember him\",\"on the Saviour’s Day?\",\"Open your eyes...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0146', 'verse', 4, 3, '[\"Here’s to the God of the present,\",\"here’s to the God of the past,\",\"here’s to the hope in the future he brings,\",\"we will sing to him, sing to him\",\"on the Saviour’s Day.\",\"Open your eyes...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0147', 147, 'Now tell us, gentle Mary', 'CP', 'en', 'Blandford Press Ltd            arrangement: ? Norman Warren, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'Now tell us, gentle Mary,
what did Gabriel say to you?
Now tell us of the tidings
that he brought to Galilee.');
