INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0147', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0147', 'verse', 1, 0, '[\"Now tell us, gentle Mary,\",\"what did Gabriel say to you?\",\"Now tell us of the tidings\",\"that he brought to Galilee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0148', 148, 'O come, all ye faithful', 'CP', 'en', '', '', 0, 0, 0, 1, 1, 'O come, all ye faithful,
joyful and triumphant;
O come ye, O come ye to Bethlehem;
come and behold him born, the king of angels!
O come, let us adore him,
O come, let us adore him,
O come, let us adore him,
Christ the Lord!
God from God,
Light from light –
lo, he abhors not the virgin’s womb!
Very God, begotten, not created.
O come...
Sing, choirs of angels,
sing in exultation!
Sing, all ye citizens of heaven above,
‘Glory to God in the highest!’
O come...
Yea, Lord, we greet thee,
born for our salvation;
Jesus, to thee be glory given!
Word of the Father now in flesh appearing.
O come...
Words after by John Francis Wade');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0148', 'F Oakeley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0148', 'John Francis Wade');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0148', 'verse', 1, 0, '[\"O come, all ye faithful,\",\"joyful and triumphant;\",\"O come ye, O come ye to Bethlehem;\",\"come and behold him born, the king of angels!\",\"O come, let us adore him,\",\"O come, let us adore him,\",\"O come, let us adore him,\",\"Christ the Lord!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0148', 'verse', 2, 1, '[\"God from God,\",\"Light from light –\",\"lo, he abhors not the virgin’s womb!\",\"Very God, begotten, not created.\",\"O come...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0148', 'verse', 3, 2, '[\"Sing, choirs of angels,\",\"sing in exultation!\",\"Sing, all ye citizens of heaven above,\",\"‘Glory to God in the highest!’\",\"O come...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0148', 'verse', 4, 3, '[\"Yea, Lord, we greet thee,\",\"born for our salvation;\",\"Jesus, to thee be glory given!\",\"Word of the Father now in flesh appearing.\",\"O come...\",\"Words after by John Francis Wade\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0149', 149, 'O come and join the dance', 'CP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'O come and join the dance
that all began so long ago,
when Christ the Lord was born in Bethlehem.
Through all the years of darkness
still the dance goes on and on,
oh, take my hand and come and join the song.
Rejoice! Rejoice!
Rejoice! Rejoice!
O lift your voice and sing,
and open up your heart to welcome him.
Rejoice! Rejoice!
Rejoice! Rejoice!
and welcome now your King,
for Christ the Lord was born in Bethlehem.
Come shed your heavy load
and dance your worries all away,
for Christ the Lord was born in Bethlehem.
He came to break the power of sin
and turn your night to day,
oh, take my hand and come and join the song.
Rejoice! Rejoice!...
Let laughter ring and angels sing
and joy be all around,
for Christ the Lord was born in Bethlehem.
And if you seek with all your heart
he surely can be found,
oh, take my hand and come and join the song.
Rejoice! Rejoice!...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0149', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0149', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0149', 'verse', 1, 0, '[\"O come and join the dance\",\"that all began so long ago,\",\"when Christ the Lord was born in Bethlehem.\",\"Through all the years of darkness\",\"still the dance goes on and on,\",\"oh, take my hand and come and join the song.\",\"Rejoice! Rejoice!\",\"Rejoice! Rejoice!\",\"O lift your voice and sing,\",\"and open up your heart to welcome him.\",\"Rejoice! Rejoice!\",\"Rejoice! Rejoice!\",\"and welcome now your King,\",\"for Christ the Lord was born in Bethlehem.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0149', 'verse', 2, 1, '[\"Come shed your heavy load\",\"and dance your worries all away,\",\"for Christ the Lord was born in Bethlehem.\",\"He came to break the power of sin\",\"and turn your night to day,\",\"oh, take my hand and come and join the song.\",\"Rejoice! Rejoice!...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0149', 'verse', 3, 2, '[\"Let laughter ring and angels sing\",\"and joy be all around,\",\"for Christ the Lord was born in Bethlehem.\",\"And if you seek with all your heart\",\"he surely can be found,\",\"oh, take my hand and come and join the song.\",\"Rejoice! Rejoice!...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0150', 150, 'O come all you children', 'CP', 'en', 'Paul Wigmore, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'O come all you children to Bethlehem town,
and see here a baby from heaven come down;
tread softly and enter on this sacred night
a stable with heavenly glory alight.
O come all you children, come here to the stall
and see here a child who is born Lord of all;
more fair than the angels in glory is he,
more lovely than cherubim ever could be.
O come all you children, and stand by his bed,
and see gentle Mary bend low at his head;
see Joseph, so humble in wondering joy,
kneel down at the feet of this most holy boy.
O come then you children, and hark at the throng
of angels, all crowding the sky with their song;
join in with their praises and joyfully sing
your loudest thanksgiving – for Jesus the King!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0150', 'Paul Wigmore');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0150', 'Jonathan Abraham Peter Schulz');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0150', 'David Peacock');
