INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0151', 151, 'O come, O come, Emmanuel', 'CP', 'en', 'in this version administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? No?l Tredinnick, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'O come, O come, Emmanuel,
and ransom captive Israel
who mourns in lonely exile here
until the Son of God draws near:
Rejoice, rejoice!
Emmanuel shall come to you, O Israel.
O come, true Wisdom from on high,
who orders all to mind and eye:
to us the path of knowledge show
and teach us in her ways to grow.
Rejoice, rejoice...
O come, O come, great Lord of might
who long ago on Sinai’s height
gave all your tribes the ancient law,
in cloud and majesty and awe:
Rejoice, rejoice...
O come, true Branch of Jesse, free
your children from this tyranny;');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0151', 'John Mason Neale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0151', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0151', 'verse', 1, 0, '[\"O come, O come, Emmanuel,\",\"and ransom captive Israel\",\"who mourns in lonely exile here\",\"until the Son of God draws near:\",\"Rejoice, rejoice!\",\"Emmanuel shall come to you, O Israel.\"]');
