INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0165', 165, 'Unto us a child is born', 'CP', 'en', 'Sovereign Music UK PO Box 356, Leighton Buzzard LU7 3WP, UK. sovereignmusic@aol.com', '', 0, 0, 0, 1, 1, 'People walking in the dark,
people living in a land of shadows –
now their darkness is dispelled,
for a light has dawned.
Unto us a child is born,
unto us a son is given,
and the government is his,
and he is called:
Wonderful Counsellor, Mighty God,
Everlasting Father, Prince of peace;
Wonderful...
He will reign for ever,
his peace will never end;
he will bring us joy,
will bring us life, our freedom defend.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0165', 'Mark Cheesman');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0165', 'Chris Jeffrey');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0165', 'Mark Cheesman');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0165', 'Chris Jeffrey');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0165', 'verse', 1, 0, '[\"People walking in the dark,\",\"people living in a land of shadows –\",\"now their darkness is dispelled,\",\"for a light has dawned.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0165', 'verse', 2, 1, '[\"Unto us a child is born,\",\"unto us a son is given,\",\"and the government is his,\",\"and he is called:\",\"Wonderful Counsellor, Mighty God,\",\"Everlasting Father, Prince of peace;\",\"Wonderful...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0165', 'verse', 3, 2, '[\"He will reign for ever,\",\"his peace will never end;\",\"he will bring us joy,\",\"will bring us life, our freedom defend.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0166', 166, 'Play your pipe, beat your drum', 'CP', 'en', 'Judy Davies, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.                        arrangement ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Play your pipe, beat your drum,
sing to Christ the Saviour;
come and worship, come and worship,
worship Christ our king!
Shepherds come a-dancing,
bring your pipe and drum;
come and see the baby –
run, run, run!
Play your pipe...
Peaceful in the manger
see him lying there,
gently gather round him –
Oh take care!
Play your pipe...
Listen to the angels,
can you hear them sing –
welcoming the saviour?
He’s our king!
Play your pipe...
Come to us, Lord Jesus,
come to us again,
in our hearts we’ll keep you,
there to reign!
Play your pipe...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0166', 'Judy Davies');
