INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0166', 'verse', 1, 1, '[\"Shepherds come a-dancing,\",\"bring your pipe and drum;\",\"come and see the baby –\",\"run, run, run!\",\"Play your pipe...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0166', 'verse', 2, 2, '[\"Peaceful in the manger\",\"see him lying there,\",\"gently gather round him –\",\"Oh take care!\",\"Play your pipe...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0166', 'verse', 3, 3, '[\"Listen to the angels,\",\"can you hear them sing –\",\"welcoming the saviour?\",\"He’s our king!\",\"Play your pipe...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0166', 'verse', 4, 4, '[\"Come to us, Lord Jesus,\",\"come to us again,\",\"in our hearts we’ll keep you,\",\"there to reign!\",\"Play your pipe...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0167', 167, 'Prepare the way', 'CP', 'en', '1995 I.Q. Music Ltd', '', 0, 0, 0, 1, 1, 'Prepare the way
for the Lord;
make straight his path
in the wilderness –
a highway for our God:
every valley
shall be raised up,
and every mountain
be made low;
and the glory of the Lord will be revealed,
and the glory of the Lord will be revealed.
Do you not know?
Have you not heard?
He sits enthroned
above the earth
and stretches out the heavens:
lift up your voice
and with a shout,
come, lift it up:
don’t be afraid –
and the glory of the Lord will be revealed,
and the glory of the Lord will be revealed,
and the glory of the Lord will be revealed.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0167', 'Andy Piercy');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0167', 'Charlie Groves');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0167', 'Andy Piercy');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0167', 'Charlie Groves');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0167', 'verse', 1, 0, '[\"Prepare the way\",\"for the Lord;\",\"make straight his path\",\"in the wilderness –\",\"a highway for our God:\",\"every valley\",\"shall be raised up,\",\"and every mountain\",\"be made low;\",\"and the glory of the Lord will be revealed,\",\"and the glory of the Lord will be revealed.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0167', 'verse', 2, 1, '[\"Do you not know?\",\"Have you not heard?\",\"He sits enthroned\",\"above the earth\",\"and stretches out the heavens:\",\"lift up your voice\",\"and with a shout,\",\"come, lift it up:\",\"don’t be afraid –\",\"and the glory of the Lord will be revealed,\",\"and the glory of the Lord will be revealed,\",\"and the glory of the Lord will be revealed.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0168', 168, 'Rejoice and be merry', 'CP', 'en', 'in this version Word & Music, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Iliff, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Rejoice and be merry in songs and in mirth;
O praise our redeemer, all mortals on earth!
for this is the birthday of Jesus our king,
who brought us salvation –
his praises we sing!
A heavenly vision appeared in the sky;
vast numbers of angels the shepherds did spy,
proclaiming the birthday of Jesus our king,
who brought us salvation –
his praises we sing!
And soon in the sky a bright star did appear,
which led the wise men from the east to draw near;
they found the messiah, Christ Jesus our king,
who brought us salvation –
his praises we sing!
They came and they offered myrrh, incense and gold –
for God’s gracious purpose these treasures foretold:
then worshipped for ever be Jesus our king,
who brought us salvation –
his praises we sing!
Words in this version by Word & Music');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0168', 'David Iliff');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0168', 'verse', 1, 0, '[\"Rejoice and be merry in songs and in mirth;\",\"O praise our redeemer, all mortals on earth!\",\"for this is the birthday of Jesus our king,\",\"who brought us salvation –\",\"his praises we sing!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0168', 'verse', 2, 1, '[\"A heavenly vision appeared in the sky;\",\"vast numbers of angels the shepherds did spy,\",\"proclaiming the birthday of Jesus our king,\",\"who brought us salvation –\",\"his praises we sing!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0168', 'verse', 3, 2, '[\"And soon in the sky a bright star did appear,\",\"which led the wise men from the east to draw near;\",\"they found the messiah, Christ Jesus our king,\",\"who brought us salvation –\",\"his praises we sing!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0168', 'verse', 4, 3, '[\"They came and they offered myrrh, incense and gold –\",\"for God’s gracious purpose these treasures foretold:\",\"then worshipped for ever be Jesus our king,\",\"who brought us salvation –\",\"his praises we sing!\",\"Words in this version by Word & Music\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0169', 169, 'Rejoice with us this Christmas', 'CP', 'en', '2002 Out of the Ark Music', '', 0, 0, 0, 1, 1, 'Rejoice with us this Christmas,
the Son of God has come;
we’ve found the Saviour, Jesus,
given for everyone.
Rejoice with us this Christmas,
the Son of God has come;
we’ve found the Saviour, Jesus,
given for everyone.
We’re gonna shout out – to the heavens,
we’re gonna reach out – to the skies,
we’re gonna jump up – everybody!
Lift the name of Jesus high!
Sing out the Christmas story,
sing out this joyful song;
for love has come from glory,
given for everyone.
Sing out the Christmas story,
sing out this joyful song;
for love has come from glory,
given for everyone.
We’re gonna shout out...
Sing out the Christmas story...
... given for everyone.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0169', 'Mark Johnson');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0169', 'Helen Johnson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0169', 'Mark Johnson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0169', 'Helen Johnson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0169', 'verse', 1, 0, '[\"Rejoice with us this Christmas,\",\"the Son of God has come;\",\"we’ve found the Saviour, Jesus,\",\"given for everyone.\",\"Rejoice with us this Christmas,\",\"the Son of God has come;\",\"we’ve found the Saviour, Jesus,\",\"given for everyone.\",\"We’re gonna shout out – to the heavens,\",\"we’re gonna reach out – to the skies,\",\"we’re gonna jump up – everybody!\",\"Lift the name of Jesus high!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0169', 'verse', 2, 1, '[\"Sing out the Christmas story,\",\"sing out this joyful song;\",\"for love has come from glory,\",\"given for everyone.\",\"Sing out the Christmas story,\",\"sing out this joyful song;\",\"for love has come from glory,\",\"given for everyone.\",\"We’re gonna shout out...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0169', 'verse', 3, 2, '[\"Sing out the Christmas story...\",\"... given for everyone.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0170', 170, 'Rejoice with heart and voice', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? John Barnard, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Rejoice with heart and voice!
now is our Saviour
of the virgin Mary born –
so rejoice!
At this time our God fulfils
all our expectation:
let us offer hearts and wills
in rededication.
Rejoice...
God of God when time began,
Lord of all creation:
we revere the Son of Man
at his incarnation.
Rejoice...
Alleluia! Let us sing
hymns of adoration,
blessing Christ our worthy king
in this celebration!
Rejoice...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0170', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0170', 'John Barnard');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0170', 'chorus', 0, 0, '[\"Rejoice with heart and voice!\",\"now is our Saviour\",\"of the virgin Mary born –\",\"so rejoice!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0170', 'verse', 1, 1, '[\"At this time our God fulfils\",\"all our expectation:\",\"let us offer hearts and wills\",\"in rededication.\",\"Rejoice...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0170', 'verse', 2, 2, '[\"God of God when time began,\",\"Lord of all creation:\",\"we revere the Son of Man\",\"at his incarnation.\",\"Rejoice...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0170', 'verse', 3, 3, '[\"Alleluia! Let us sing\",\"hymns of adoration,\",\"blessing Christ our worthy king\",\"in this celebration!\",\"Rejoice...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0171', 171, 'Riding out across the desert', 'CP', 'en', 'Peter Ratcliffe, administered by The Jubilate Group www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'Riding out across the desert,
travelling over sandy plains,
comes a company of wise men,
moving steadily along their way;
leaving all their friends behind them,
guided by the star so bright,
now they’ve got to keep on going –
must not let the star get out of sight.
Riding through the desert, gently the wise men go,
onwards to the king who was promised long ago;
but they don’t know where they’re going to find him –
there’s many towns to search –
so they’ll keep on following the star,
for it will lead them to his place of birth.
Wise men on their desert journey,
travelled many miles so far –
though they’re getting tired and weary,
town of Bethlehem is not too far:
how they long to worship Jesus
and honour him with royal gifts –
hearts are full of joy and wonder
as they’re searching for the new born king!
Riding through the desert...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0171', 'Peter Ratcliffe');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0171', 'Peter Ratcliffe');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0171', 'verse', 1, 0, '[\"Riding out across the desert,\",\"travelling over sandy plains,\",\"comes a company of wise men,\",\"moving steadily along their way;\",\"leaving all their friends behind them,\",\"guided by the star so bright,\",\"now they’ve got to keep on going –\",\"must not let the star get out of sight.\",\"Riding through the desert, gently the wise men go,\",\"onwards to the king who was promised long ago;\",\"but they don’t know where they’re going to find him –\",\"there’s many towns to search –\",\"so they’ll keep on following the star,\",\"for it will lead them to his place of birth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0171', 'verse', 2, 1, '[\"Wise men on their desert journey,\",\"travelled many miles so far –\",\"though they’re getting tired and weary,\",\"town of Bethlehem is not too far:\",\"how they long to worship Jesus\",\"and honour him with royal gifts –\",\"hearts are full of joy and wonder\",\"as they’re searching for the new born king!\",\"Riding through the desert...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0172', 172, 'Ring aloud the Christmas bells', 'CP', 'en', '2000 Kevin Mayhew Ltd, Buxhall, Stowmarket, Suffolk IP14 3DJ, UK. www.kevinmayhew.com            arrangement: ? No?l Tredinnick, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'Ring aloud the Christmas bells –
joyful news their message tells:
news about a royal birth
God has sent his Son to earth!
See the candles, burning bright –
Jesus came to give us light.
Light and life and truth and grace:
all are seen in Jesus’ face.
Choosing gifts with special care
we express the love we share;
but the finest gift of all
is the Christ-child in the stall.
Beautiful the Christmas tree;
on a tree he died for me –
crucified, my sin he bore;
now he lives for evermore!
Sing the carols, loud and clear:
God our Saviour has come near.
Worship Christ, the newborn King –
life for all he’s born to bring.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0172', 'Martin E Leckebusch');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0172', 'P de Corbeil');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0172', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0172', 'verse', 1, 0, '[\"Ring aloud the Christmas bells –\",\"joyful news their message tells:\",\"news about a royal birth\",\"God has sent his Son to earth!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0172', 'verse', 2, 1, '[\"See the candles, burning bright –\",\"Jesus came to give us light.\",\"Light and life and truth and grace:\",\"all are seen in Jesus’ face.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0172', 'verse', 3, 2, '[\"Choosing gifts with special care\",\"we express the love we share;\",\"but the finest gift of all\",\"is the Christ-child in the stall.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0172', 'verse', 4, 3, '[\"Beautiful the Christmas tree;\",\"on a tree he died for me –\",\"crucified, my sin he bore;\",\"now he lives for evermore!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0172', 'verse', 5, 4, '[\"Sing the carols, loud and clear:\",\"God our Saviour has come near.\",\"Worship Christ, the newborn King –\",\"life for all he’s born to bring.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0173', 173, 'Ring, bells of Bethlehem', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? Norman Warren, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Ring, bells of Bethlehem,
ding-dong-ding, ding-a-dong-a-ding;
rise up, Jerusalem,
joyfully sing.
Come from your lands afar,
ding-dong-ding, ding-a-dong-a-ding,
follow the royal star,
look for the king!
Come, as the wise of old,
ding-dong-ding, ding-a-dong-a-ding;
frankincense, myrrh and gold
joyfully bring:
incense shows fervent prayers,
ding-dong-ding, ding-a-dong-a-ding,
myrrh his great love declares,
gold makes him king!
Ring, bells of Bethlehem,
ding-dong-ding, ding-a-dong-a-ding;
rise up, Jerusalem,
joyfully sing.
Come and before him bow,
ding-dong-ding, ding-a-dong-a-ding,
open your treasures now,
welcome your king!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0173', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0173', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0173', 'verse', 1, 0, '[\"Ring, bells of Bethlehem,\",\"ding-dong-ding, ding-a-dong-a-ding;\",\"rise up, Jerusalem,\",\"joyfully sing.\",\"Come from your lands afar,\",\"ding-dong-ding, ding-a-dong-a-ding,\",\"follow the royal star,\",\"look for the king!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0173', 'verse', 2, 1, '[\"Come, as the wise of old,\",\"ding-dong-ding, ding-a-dong-a-ding;\",\"frankincense, myrrh and gold\",\"joyfully bring:\",\"incense shows fervent prayers,\",\"ding-dong-ding, ding-a-dong-a-ding,\",\"myrrh his great love declares,\",\"gold makes him king!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0173', 'verse', 3, 2, '[\"Ring, bells of Bethlehem,\",\"ding-dong-ding, ding-a-dong-a-ding;\",\"rise up, Jerusalem,\",\"joyfully sing.\",\"Come and before him bow,\",\"ding-dong-ding, ding-a-dong-a-ding,\",\"open your treasures now,\",\"welcome your king!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0174', 174, 'Rumours of angels', 'CP', 'en', '1994 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Rumours of angels,
visions of light,
new star appearing,
piercing the night.
Town full of strangers
sleeps in the gloom.
God comes among us;
there is no room.
Rumours of angels,
songs in the night,
deep in the danger,
unquenchable light.
World full of strangers
sleeps in the gloom.
God comes among us;
there is no room.
And the years of our sorrow have rolled on and on,
and the wars of our pride never cease.
We have ravaged the earth with our envy and greed –
tell me, when will we welcome his peace?
When will we welcome his peace?
Hearts full of longing,
eyes filled with tears,
nations are waiting
at the end of the years.
Empires are falling,
judgements appear.
God comes among us;
his kingdom is near.
And the years of our sorrow have rolled on and on,
and the wars of our pride never cease.
We have ravaged the earth with our envy and greed –
tell me, when will we welcome his peace?
When will we welcome his peace?
Oh, when will we welcome the Prince of peace?
Oh, when will we welcome the Prince of peace?');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0174', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0174', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0174', 'verse', 1, 0, '[\"Rumours of angels,\",\"visions of light,\",\"new star appearing,\",\"piercing the night.\",\"Town full of strangers\",\"sleeps in the gloom.\",\"God comes among us;\",\"there is no room.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0174', 'verse', 2, 1, '[\"Rumours of angels,\",\"songs in the night,\",\"deep in the danger,\",\"unquenchable light.\",\"World full of strangers\",\"sleeps in the gloom.\",\"God comes among us;\",\"there is no room.\",\"And the years of our sorrow have rolled on and on,\",\"and the wars of our pride never cease.\",\"We have ravaged the earth with our envy and greed –\",\"tell me, when will we welcome his peace?\",\"When will we welcome his peace?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0174', 'verse', 3, 2, '[\"Hearts full of longing,\",\"eyes filled with tears,\",\"nations are waiting\",\"at the end of the years.\",\"Empires are falling,\",\"judgements appear.\",\"God comes among us;\",\"his kingdom is near.\",\"And the years of our sorrow have rolled on and on,\",\"and the wars of our pride never cease.\",\"We have ravaged the earth with our envy and greed –\",\"tell me, when will we welcome his peace?\",\"When will we welcome his peace?\",\"Oh, when will we welcome the Prince of peace?\",\"Oh, when will we welcome the Prince of peace?\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0175', 175, 'Ring out the bells', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Iliff, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Ring out the bells –
the joyful news is breaking;
ring out the bells
for Jesus Christ is born!
Angels in wonder
sing of his glory;
shepherds returning
tell us the story.
Ring out...
Let all creation
worship before him;
earth bring him homage,
heaven adore him!
Ring out...
Prophets have spoken –
hark to their warning:
shadows are passing,
soon comes the morning!
Ring out...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0175', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0175', 'David Iliff');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0175', 'chorus', 0, 0, '[\"Ring out the bells –\",\"the joyful news is breaking;\",\"ring out the bells\",\"for Jesus Christ is born!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0175', 'verse', 1, 1, '[\"Angels in wonder\",\"sing of his glory;\",\"shepherds returning\",\"tell us the story.\",\"Ring out...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0175', 'verse', 2, 2, '[\"Let all creation\",\"worship before him;\",\"earth bring him homage,\",\"heaven adore him!\",\"Ring out...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0175', 'verse', 3, 3, '[\"Prophets have spoken –\",\"hark to their warning:\",\"shadows are passing,\",\"soon comes the morning!\",\"Ring out...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0176', 176, 'See, amid the winter snow', 'CP', 'en', 'in this version The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? No?l Tredinnick, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'See, amid the winter snow,
born for us on earth below;
see, the gentle Lamb appears,
promised from eternal years:
Hail, O ever-blessèd morn!
hail, redemption’s happy dawn!
sing through all Jerusalem:
‘Christ is born in Bethlehem!’
Low within a manger lies
he who built the starry skies;
he who, throned in height sublime,
reigns above the cherubim:
Hail, O ever-blessèd morn...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0176', 'Edward Caswall');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0176', 'John Goss');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0176', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0176', 'verse', 1, 0, '[\"See, amid the winter snow,\",\"born for us on earth below;\",\"see, the gentle Lamb appears,\",\"promised from eternal years:\",\"Hail, O ever-blessèd morn!\",\"hail, redemption’s happy dawn!\",\"sing through all Jerusalem:\",\"‘Christ is born in Bethlehem!’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0176', 'verse', 2, 1, '[\"Low within a manger lies\",\"he who built the starry skies;\",\"he who, throned in height sublime,\",\"reigns above the cherubim:\",\"Hail, O ever-blessèd morn...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0177', 177, 'See him lying on a bed of straw', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? No?l Tredinnick, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'See him lying on a bed of straw:
a draughty stable with an open door;
Mary cradling the babe she bore
the prince of glory is his name.
O now carry me to Bethlehem
to see the Lord of love again:
just as poor as was the stable then,
the prince of glory when he came.
Star of silver, sweep across the skies,
show where Jesus in the manger lies;
shepherds, swiftly from your stupor rise
to see the saviour of the world!
O now carry me...
Angels, sing again the song you sang,
sing the glory of God’s gracious plan;
Sing that Bethlehem’s little baby can
be the saviour of us all.
O now carry me...
Mine are riches, from your poverty,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0177', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0177', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0177', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0177', 'verse', 1, 0, '[\"See him lying on a bed of straw:\",\"a draughty stable with an open door;\",\"Mary cradling the babe she bore\",\"the prince of glory is his name.\",\"O now carry me to Bethlehem\",\"to see the Lord of love again:\",\"just as poor as was the stable then,\",\"the prince of glory when he came.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0177', 'verse', 2, 1, '[\"Star of silver, sweep across the skies,\",\"show where Jesus in the manger lies;\",\"shepherds, swiftly from your stupor rise\",\"to see the saviour of the world!\",\"O now carry me...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0177', 'verse', 3, 2, '[\"Angels, sing again the song you sang,\",\"sing the glory of God’s gracious plan;\",\"Sing that Bethlehem’s little baby can\",\"be the saviour of us all.\",\"O now carry me...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0177', 'verse', 4, 3, '[\"Mine are riches, from your poverty,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0178', 178, 'See the dawn appearing', 'CP', 'en', 'Stanley Johnson            ? David Cooper', '', 0, 0, 0, 1, 1, 'See the dawn appearing, lighting the sky –
though shadows fly, don’t you awake!
The daylight breaking shines bright and clear –
though day is near, don’t you awake.
Angels have sung you their lullabies –
capture this moment before it dies.
See the dawn appearing
lighting the sky –
though shadows fly,
don’t you awake!
Ox and ass are stirring – though they draw near
no need to fear, don’t you awake.
Though shepherds greet you kneeling to pray,
king born today, don’t you awake.
Wise men will bring you their gifts of gold,
born to be king as the prophets told.
See the dawn appearing...
Cruel day awaits you, dawn’s icy breath,
sorrow and death, when you awake.
Rough hands will seize you – scorned and denied,
nailed, crucified when you awake.
Though people hail you today as king,
they will not hear the Good News you bring.
See the dawn appearing...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0178', 'Stanley Johnson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0178', 'David Cooper');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0178', 'verse', 1, 0, '[\"See the dawn appearing, lighting the sky –\",\"though shadows fly, don’t you awake!\",\"The daylight breaking shines bright and clear –\",\"though day is near, don’t you awake.\",\"Angels have sung you their lullabies –\",\"capture this moment before it dies.\",\"See the dawn appearing\",\"lighting the sky –\",\"though shadows fly,\",\"don’t you awake!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0178', 'verse', 2, 1, '[\"Ox and ass are stirring – though they draw near\",\"no need to fear, don’t you awake.\",\"Though shepherds greet you kneeling to pray,\",\"king born today, don’t you awake.\",\"Wise men will bring you their gifts of gold,\",\"born to be king as the prophets told.\",\"See the dawn appearing...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0178', 'verse', 3, 2, '[\"Cruel day awaits you, dawn’s icy breath,\",\"sorrow and death, when you awake.\",\"Rough hands will seize you – scorned and denied,\",\"nailed, crucified when you awake.\",\"Though people hail you today as king,\",\"they will not hear the Good News you bring.\",\"See the dawn appearing...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0179', 179, 'Shepherds came, their praises bringing', 'CP', 'en', 'The Estate of Revd. George Caird, c/o The United Reformed Church            arrangement: ? No?l Tredinnick, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'Shepherds came their praises bringing,
who had heard the angels singing:
‘Far from you be fear unruly,
Christ is king of glory born.’
Wise men whom a star had guided
incense, gold, and myrrh provided,
made their sacrifices truly
to the king of glory born.
Jesus born the king of heaven,
Christ to us through Mary given,
to your praise and honour duly
be resounding glory done.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0179', 'G B Caird');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0179', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0179', 'verse', 1, 0, '[\"Shepherds came their praises bringing,\",\"who had heard the angels singing:\",\"‘Far from you be fear unruly,\",\"Christ is king of glory born.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0179', 'verse', 2, 1, '[\"Wise men whom a star had guided\",\"incense, gold, and myrrh provided,\",\"made their sacrifices truly\",\"to the king of glory born.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0179', 'verse', 3, 2, '[\"Jesus born the king of heaven,\",\"Christ to us through Mary given,\",\"to your praise and honour duly\",\"be resounding glory done.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0180', 180, 'All for a baby', 'CP', 'en', '1996 Russell Ewens', '', 0, 0, 0, 1, 1, 'Shepherds heard the angels sing,
saw their brightness in the sky,
went to find a new-born child
in Bethlehem, a town nearby.
All for a baby, born in a barn
where animals lay,
sleeping on the hay.
All for a baby, born to be
the Lord of all we see,
of you and me.
Wise men came with precious gifts,
myrrh and frankincense and gold,
offered them to a new-born child
of whom the prophets had foretold.
All for a baby...
This all happened long ago,
yet we celebrate his birth:
God appeared as a new-born child
and lived in human form on earth.
All for a baby...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0180', 'Russell Ewens');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0180', 'Russell Ewens');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0180', 'verse', 1, 0, '[\"Shepherds heard the angels sing,\",\"saw their brightness in the sky,\",\"went to find a new-born child\",\"in Bethlehem, a town nearby.\",\"All for a baby, born in a barn\",\"where animals lay,\",\"sleeping on the hay.\",\"All for a baby, born to be\",\"the Lord of all we see,\",\"of you and me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0180', 'verse', 2, 1, '[\"Wise men came with precious gifts,\",\"myrrh and frankincense and gold,\",\"offered them to a new-born child\",\"of whom the prophets had foretold.\",\"All for a baby...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0180', 'verse', 3, 2, '[\"This all happened long ago,\",\"yet we celebrate his birth:\",\"God appeared as a new-born child\",\"and lived in human form on earth.\",\"All for a baby...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0181', 181, 'Silent night', 'CP', 'en', '', '', 0, 0, 0, 1, 1, 'Silent night! holy night!
all is calm, all is bright
round the virgin and her child:
holy infant, so gentle and mild,
sleep in heavenly peace;
sleep in heavenly peace!
Silent night! holy night!
shepherds quail at the sight,
glory streams from heaven afar:
heavenly hosts sing, ‘Alleluia,
Christ the saviour is born,
Christ the saviour is born.’
Silent night! holy night!
Son of God, love’s pure light:
radiant beams your holy face
with the dawn of saving grace,
Jesus, Lord, at your birth,
Jesus, Lord, at your birth.
Words after by J Möhr');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0181', 'J F Young');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0181', 'Franz X Gruber');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0181', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0181', 'verse', 1, 0, '[\"Silent night! holy night!\",\"all is calm, all is bright\",\"round the virgin and her child:\",\"holy infant, so gentle and mild,\",\"sleep in heavenly peace;\",\"sleep in heavenly peace!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0181', 'verse', 2, 1, '[\"Silent night! holy night!\",\"shepherds quail at the sight,\",\"glory streams from heaven afar:\",\"heavenly hosts sing, ‘Alleluia,\",\"Christ the saviour is born,\",\"Christ the saviour is born.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0181', 'verse', 3, 2, '[\"Silent night! holy night!\",\"Son of God, love’s pure light:\",\"radiant beams your holy face\",\"with the dawn of saving grace,\",\"Jesus, Lord, at your birth,\",\"Jesus, Lord, at your birth.\",\"Words after by J Möhr\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0182', 182, 'Silently at Christmas', 'CP', 'en', 'Michael Saward, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'Silently at Christmas
Jesus came to town,
homelessness he suffered,
in a stable born.
Son of God almighty
heir to heaven’s crown,
powerlessness he suffered
on that morn.
Hurriedly at Christmas
shepherds came to town,
guilelessness they offered,
in the humble barn.
To the Lord almighty
heir to heaven’s crown,
lowliness they offered
on that morn.
Painfully at Christmas
people live in town,
hopelessness they suffer
hungry and alone.
Cursing the almighty
heir to heaven’s crown,
thoughtlessness they suffer
on this morn.
Willingly at Christmas,
Christians in our town,
joyfulness they offer,
carolling the Son,
and to Christ almighty
heir to heaven’s crown,
selflessness they offer
on this morn.
Longingly each Christmas
Jesus comes to town,
godlessness he suffers,
how his heart must burn!
He is love almighty
heir to heaven’s crown,
loneliness he suffers
on this morn.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0182', 'Michael Saward');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0182', 'Gustav Holst');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0182', 'verse', 1, 0, '[\"Silently at Christmas\",\"Jesus came to town,\",\"homelessness he suffered,\",\"in a stable born.\",\"Son of God almighty\",\"heir to heaven’s crown,\",\"powerlessness he suffered\",\"on that morn.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0182', 'verse', 2, 1, '[\"Hurriedly at Christmas\",\"shepherds came to town,\",\"guilelessness they offered,\",\"in the humble barn.\",\"To the Lord almighty\",\"heir to heaven’s crown,\",\"lowliness they offered\",\"on that morn.\"]');
