INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0182', 'verse', 4, 3, '[\"Willingly at Christmas,\",\"Christians in our town,\",\"joyfulness they offer,\",\"carolling the Son,\",\"and to Christ almighty\",\"heir to heaven’s crown,\",\"selflessness they offer\",\"on this morn.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0182', 'verse', 5, 4, '[\"Longingly each Christmas\",\"Jesus comes to town,\",\"godlessness he suffers,\",\"how his heart must burn!\",\"He is love almighty\",\"heir to heaven’s crown,\",\"loneliness he suffers\",\"on this morn.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0183', 183, 'Silver star', 'CP', 'en', 'Mrs B Perry, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? Norman Warren, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Silver star
shining out over Bethlehem,
lead worshippers from afar,
inspiring and guiding them!
They look for the infant King –
with their gifts they will honour him;
and love in their hearts they bring,
true service to offer him.
Holy night
for a pilgrim to journey through!
O traveller, seek the light
that welcomes and beckons you!
You come to the brink of heaven,
to the gateway of paradise;
for you has the Child been given,
on you shall the Sun arise.
Silent sky
full of wonder and mystery –
the splendour of God most high,
the mantle of majesty!
Yet God lays aside his crown –
O give praise to the mighty Lord!
and for our release comes down –
O welcome the living Word!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0183', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0183', 'A Borodin');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0183', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0183', 'verse', 1, 0, '[\"Silver star\",\"shining out over Bethlehem,\",\"lead worshippers from afar,\",\"inspiring and guiding them!\",\"They look for the infant King –\",\"with their gifts they will honour him;\",\"and love in their hearts they bring,\",\"true service to offer him.\"]');
