INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0199', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0199', 'verse', 1, 0, '[\"The darkness turns to dawn,\",\"the dayspring shines from heaven;\",\"for unto us a child is born,\",\"to us a Son is given.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0199', 'verse', 2, 1, '[\"The Son of God most high,\",\"before all else began,\",\"a virgin’s son behold him lie,\",\"the new-born Son of Man.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0199', 'verse', 3, 2, '[\"God’s Word of truth and grace\",\"made flesh with us to dwell;\",\"the brightness of the Father’s face,\",\"the child Emmanuel.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0199', 'verse', 4, 3, '[\"How rich his heavenly home!\",\"How poor his human birth!\",\"As mortal man he stoops to come,\",\"the light and life of earth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0199', 'verse', 5, 4, '[\"A servant’s form, a slave,\",\"the Lord consents to share;\",\"our sin and shame, our cross and grave,\",\"he bows himself to bear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0199', 'verse', 6, 5, '[\"Obedient and alone\",\"upon that cross to die,\",\"and then to share the Father’s throne\",\"in majesty on high.\"]');
