INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0200', 200, 'The bells ring out at Christmas-time', 'CP', 'en', 'Salvationist Publishing and Supplies, administered by Copycare PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'The bells ring out at Christmas-time
their message loud and clear;
our hearts are stirred as on the air
the joyful sound we hear:
Ring out the Christmas bells,
ring out the Christmas bells!
The saviour comes –
make straight his way,
ring out those bells!
The saviour comes –
make straight his way,
ring out those bells!
Thanks be to God, since all may learn
the bells’ exultant theme –
the babe of Bethlehem was born
this lost world to redeem:
Ring out...
Glad message of the Christmas bells,
of God whose name is love –
O may this music all our days
our hope and comfort prove!
Ring out...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0200', 'Miriam Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0200', 'Unknown');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0200', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0200', 'verse', 1, 0, '[\"The bells ring out at Christmas-time\",\"their message loud and clear;\",\"our hearts are stirred as on the air\",\"the joyful sound we hear:\",\"Ring out the Christmas bells,\",\"ring out the Christmas bells!\",\"The saviour comes –\",\"make straight his way,\",\"ring out those bells!\",\"The saviour comes –\",\"make straight his way,\",\"ring out those bells!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0200', 'verse', 2, 1, '[\"Thanks be to God, since all may learn\",\"the bells’ exultant theme –\",\"the babe of Bethlehem was born\",\"this lost world to redeem:\",\"Ring out...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0200', 'verse', 3, 2, '[\"Glad message of the Christmas bells,\",\"of God whose name is love –\",\"O may this music all our days\",\"our hope and comfort prove!\",\"Ring out...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0201', 201, 'The earth was dark', 'CP', 'en', '1986 Harper Collins Religious (admin. by Song Solutions Copycare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'The earth was dark until you spoke –
then all was light and all was peace;
yet still, O God, so many wait
to see the flame of love released.
Lights to the world!
O Light divine,
kindle in us a mighty flame,
till every heart, consumed by love
shall rise to praise
your holy name!
In Christ you gave your gift of life
to save us from the depths of night:
O come and set our spirits free
and draw us to your perfect light!
Lights to the world...
Where there is fear may we bring joy,
and healing to a world of pain:
Lord, build your kingdom through our lives
till Jesus walks this earth again.
Lights to the world...
O burn in us, that we may burn
with love that triumphs in despair;
and touch our lives with such a fire
that souls may search and find you there.
Lights to the world...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0201', 'John Daniels');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0201', 'Phil Johnson');
