INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0206', 'verse', 1, 0, '[\"The virgin Mary had a baby boy,\",\"the virgin Mary had a baby boy,\",\"the virgin Mary had a baby boy\",\"and they say that his name is Jesus.\",\"He come from the glory,\",\"he come from the glorious kingdom;\",\"(Yes!) he come from the glory,\",\"he come from the glorious kingdom:\",\"O yes, believer!\",\"O yes, believer!\",\"He come from the glory,\",\"he come from the glorious kingdom.\",\"O yes...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0206', 'verse', 2, 1, '[\"The angels sang when the baby was born,\",\"the angels sang when the baby was born,\",\"the angels sang when the baby was born\",\"and they sang that his name is Jesus.\",\"He come from the glory...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0206', 'verse', 3, 2, '[\"The shepherds came where the baby was born,\",\"the shepherds came where the baby was born,\",\"the shepherds came where the baby was born\",\"and they say that his name is Jesus.\",\"He come from the glory...\",\"Music collected by by H Evans\",\"Music collected by by E Connor\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0207', 207, 'The wise may bring their learning', 'CP', 'en', 'in this version Word & Music, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'The wise may bring their learning,
the rich may bring their wealth,
and some may bring their greatness,
and some their strength and health;
we too would bring our treasures
to offer to the king:
how shall we greet our saviour,
what presents shall we bring?
We’ll bring the many duties
we have to do each day,
we’ll try our best to please him,
at home, at work, at play;
and better are these treasures
to offer to the king,
than richest gifts without them –
yet these we all may bring.
We’ll bring him hearts that love him,
we’ll bring him thankful praise,
and lives for ever striving
to follow in his ways;
and these shall be the treasures
we offer to the king,
the gifts that now and ever
our grateful hearts may bring!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0207', 'Unknown');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0207', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0207', 'verse', 1, 0, '[\"The wise may bring their learning,\",\"the rich may bring their wealth,\",\"and some may bring their greatness,\",\"and some their strength and health;\",\"we too would bring our treasures\",\"to offer to the king:\",\"how shall we greet our saviour,\",\"what presents shall we bring?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0207', 'verse', 2, 1, '[\"We’ll bring the many duties\",\"we have to do each day,\",\"we’ll try our best to please him,\",\"at home, at work, at play;\",\"and better are these treasures\",\"to offer to the king,\",\"than richest gifts without them –\",\"yet these we all may bring.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0207', 'verse', 3, 2, '[\"We’ll bring him hearts that love him,\",\"we’ll bring him thankful praise,\",\"and lives for ever striving\",\"to follow in his ways;\",\"and these shall be the treasures\",\"we offer to the king,\",\"the gifts that now and ever\",\"our grateful hearts may bring!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0208', 208, 'These were the words', 'CP', 'en', 'Christopher Voke', '', 0, 0, 0, 1, 1, 'These were the words – God to Adam:
you are a rebel banished from light;');
