INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0209', 209, 'There’s a Saviour to see', 'CP', 'en', 'in this version Word & Music, administered by The Jubilate Group www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'There’s a Saviour to see on Christmas morn –
rise up, shepherd, and follow;
we will show you the place where the Child is born –
rise up shepherd and follow!
Leave your sheep
and leave your lambs –
rise up, shepherd, and follow;
leave your sheep
and leave your rams –
rise up, shepherd, and follow!
Follow, follow,
rise up, shepherd, and follow,
hark to the angels of Bethlehem –
rise up, shepherd, and follow!
If you take good heed to the angel’s words –
rise up, shepherd, and follow,
you’ll forget your flocks, you’ll forget your herds –
rise up, shepherd, and follow!
Leave your sheep...
Words in this version by Word & Music');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0209', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0209', 'verse', 1, 0, '[\"There’s a Saviour to see on Christmas morn –\",\"rise up, shepherd, and follow;\",\"we will show you the place where the Child is born –\",\"rise up shepherd and follow!\",\"Leave your sheep\",\"and leave your lambs –\",\"rise up, shepherd, and follow;\",\"leave your sheep\",\"and leave your rams –\",\"rise up, shepherd, and follow!\",\"Follow, follow,\",\"rise up, shepherd, and follow,\",\"hark to the angels of Bethlehem –\",\"rise up, shepherd, and follow!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0209', 'verse', 2, 1, '[\"If you take good heed to the angel’s words –\",\"rise up, shepherd, and follow,\",\"you’ll forget your flocks, you’ll forget your herds –\",\"rise up, shepherd, and follow!\",\"Leave your sheep...\",\"Words in this version by Word & Music\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0210', 210, 'This Child', 'CP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'This Child secretly comes in the night,
oh this Child, hiding a heavenly light,
oh this Child, coming to us like a stranger,
this heavenly Child.
This Child, heaven come down now
to be with us here,
heavenly love and mercy appear,
softly in awe and wonder come near –
to this heavenly Child.
This Child, rising on us like the sun
oh this child, given to light everyone,
oh this Child, guiding our feet on the pathway
to peace on earth.
This Child...
This Child, raising the humble and poor,
oh this Child, making the proud ones to fall;
oh this Child, filling the hungry with good things
this heavenly Child.
This Child...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0210', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0210', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0210', 'verse', 1, 0, '[\"This Child secretly comes in the night,\",\"oh this Child, hiding a heavenly light,\",\"oh this Child, coming to us like a stranger,\",\"this heavenly Child.\",\"This Child, heaven come down now\",\"to be with us here,\",\"heavenly love and mercy appear,\",\"softly in awe and wonder come near –\",\"to this heavenly Child.\"]');
