INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0211', 211, 'This night a miracle happened', 'CP', 'en', '1984 Sovereign Music UK, PO Box 356, Leighton Buzzard LU7 3WP, UK. sovereignmusic@aol.com', '', 0, 0, 0, 1, 1, 'This night a miracle happened –
a boy child was born.
Go spread the news: from today
a new era will dawn.
Glorious things tonight are happening –
who can disbelieve their sight?
royal kings will pay him homage,
yes, coming to find this town tonight!
For, this night...
Angels sing their heavenly choruses
to the babe, the King of kings –
he who is the truth and glory,
a light to the darkness he will bring.
For, this night...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0211', 'Elaine Davies');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0211', 'Elaine Davies');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0211', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0211', 'chorus', 0, 0, '[\"This night a miracle happened –\",\"a boy child was born.\",\"Go spread the news: from today\",\"a new era will dawn.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0211', 'verse', 1, 1, '[\"Glorious things tonight are happening –\",\"who can disbelieve their sight?\",\"royal kings will pay him homage,\",\"yes, coming to find this town tonight!\",\"For, this night...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0211', 'verse', 2, 2, '[\"Angels sing their heavenly choruses\",\"to the babe, the King of kings –\",\"he who is the truth and glory,\",\"a light to the darkness he will bring.\",\"For, this night...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0212', 212, 'To people of goodwill', 'CP', 'en', '', '', 0, 0, 0, 1, 1, 'To people of goodwill,
be peace on earth and gladness!
Let joyful carols fill
the world where once was sadness.
So let us on this morn
lift up our hearts to heaven:
to us a Child is born,
to us a Son is given:
O praise him, O praise him, O praise him!
Through pain of sin’s distress,
all worldly pride unheeding,
in paths of righteousness
a little child is leading:
So let us...
All you that burdens bear,
come, take his yoke upon you:
your work he comes to share,
and lays his light load on you:
So let us...
O holy, humble birth –
now sing the joyful story!
Good will, good will on earth,
and in the highest glory!
So let us...
Words after by F Fletcher
Words in this version by Word & Music');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0212', 'C Wood');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0212', 'verse', 1, 0, '[\"To people of goodwill,\",\"be peace on earth and gladness!\",\"Let joyful carols fill\",\"the world where once was sadness.\",\"So let us on this morn\",\"lift up our hearts to heaven:\",\"to us a Child is born,\",\"to us a Son is given:\",\"O praise him, O praise him, O praise him!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0212', 'verse', 2, 1, '[\"Through pain of sin’s distress,\",\"all worldly pride unheeding,\",\"in paths of righteousness\",\"a little child is leading:\",\"So let us...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0212', 'verse', 3, 2, '[\"All you that burdens bear,\",\"come, take his yoke upon you:\",\"your work he comes to share,\",\"and lays his light load on you:\",\"So let us...\"]');
