INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0213', 213, 'To us a child of royal birth', 'CP', 'en', 'in this version Word & Music, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            ? 1993 HarperCollinsReligious, administered by Copycare PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.', '', 0, 0, 0, 1, 1, 'To us a child of royal birth,
the heir of promises is given;
invisible, yet here on earth,
the Son of Man, the God of heaven.
A saviour born, in love supreme
he comes our fallen souls to raise;
he comes his people to redeem
with all the fulness of his grace.
The Christ foretold by prophecy
and filled with all the Spirit’s power,
our prophet, priest and king is he,
the mighty Lord whom we adore.
The Lord of hosts, the God most high
who leaves his throne to live on earth,
with joy we welcome from the sky
and take into our hearts by faith.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0213', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0213', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0213', 'verse', 1, 0, '[\"To us a child of royal birth,\",\"the heir of promises is given;\",\"invisible, yet here on earth,\",\"the Son of Man, the God of heaven.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0213', 'verse', 2, 1, '[\"A saviour born, in love supreme\",\"he comes our fallen souls to raise;\",\"he comes his people to redeem\",\"with all the fulness of his grace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0213', 'verse', 3, 2, '[\"The Christ foretold by prophecy\",\"and filled with all the Spirit’s power,\",\"our prophet, priest and king is he,\",\"the mighty Lord whom we adore.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0213', 'verse', 4, 3, '[\"The Lord of hosts, the God most high\",\"who leaves his throne to live on earth,\",\"with joy we welcome from the sky\",\"and take into our hearts by faith.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0214', 214, 'Glory to God', 'CP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Tonight, while all the world was sleeping,
a light exploded in the skies.
And then, as glory did surround us,
a voice, an angel did appear!
Glory to God in the highest,
and on the earth all peace from heaven!
Glory to God in the highest,
and on the earth all peace from heaven!
Afraid, we covered up our faces,
amazed at what our ears did hear.
Good news of joy for all the people –
today a Saviour has appeared!
Glory to God in the highest...
And so to Bethlehem
to find it all was true;
despised and worthless shepherds,
we were the first to know.
Glory to God in the highest...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0214', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0214', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0214', 'verse', 1, 0, '[\"Tonight, while all the world was sleeping,\",\"a light exploded in the skies.\",\"And then, as glory did surround us,\",\"a voice, an angel did appear!\",\"Glory to God in the highest,\",\"and on the earth all peace from heaven!\",\"Glory to God in the highest,\",\"and on the earth all peace from heaven!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0214', 'verse', 2, 1, '[\"Afraid, we covered up our faces,\",\"amazed at what our ears did hear.\",\"Good news of joy for all the people –\",\"today a Saviour has appeared!\",\"Glory to God in the highest...\"]');
