INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0215', 215, 'Wait for the Lord', 'CP', 'en', 'Ateliers et Presses de Taiz?, 71250 Taiz? Community, France', '', 0, 0, 0, 1, 1, 'Wait for the Lord,
whose day is near.
Wait for the Lord:
keep watch, take heart.');
