INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0232', 232, 'When the King shall come again', 'CP', 'en', 'Christopher Idle, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'When the King shall come again
all his power revealing,
splendour shall announce his reign,
life and joy and healing:
earth no longer in decay,
hope no more frustrated;
this is God’s redemption day
longingly awaited.
In the desert trees take root
fresh from his creation;
plants and flowers and sweetest fruit
join the celebration.
Rivers spring up from the earth,
barren lands adorning;
valleys, this is your new birth,
mountains, greet the morning!
Strengthen feeble hands and knees,
fainting hearts, be cheerful!
God who comes for such as these
seeks and saves the fearful.
Deaf ears hear the silent tongues
sing away their weeping;
blind eyes see the lifeless ones
walking, running, leaping.
There God’s highway shall be seen
where no roaring lion,
nothing evil or unclean
walks the road to Zion:
ransomed people homeward bound
all your praises voicing,
see your Lord with glory crowned,
share in his rejoicing!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0232', 'Christopher Idle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0232', 'John Stainer');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0232', 'verse', 1, 0, '[\"When the King shall come again\",\"all his power revealing,\",\"splendour shall announce his reign,\",\"life and joy and healing:\",\"earth no longer in decay,\",\"hope no more frustrated;\",\"this is God’s redemption day\",\"longingly awaited.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0232', 'verse', 2, 1, '[\"In the desert trees take root\",\"fresh from his creation;\",\"plants and flowers and sweetest fruit\",\"join the celebration.\",\"Rivers spring up from the earth,\",\"barren lands adorning;\",\"valleys, this is your new birth,\",\"mountains, greet the morning!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0232', 'verse', 3, 2, '[\"Strengthen feeble hands and knees,\",\"fainting hearts, be cheerful!\",\"God who comes for such as these\",\"seeks and saves the fearful.\",\"Deaf ears hear the silent tongues\",\"sing away their weeping;\",\"blind eyes see the lifeless ones\",\"walking, running, leaping.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0232', 'verse', 4, 3, '[\"There God’s highway shall be seen\",\"where no roaring lion,\",\"nothing evil or unclean\",\"walks the road to Zion:\",\"ransomed people homeward bound\",\"all your praises voicing,\",\"see your Lord with glory crowned,\",\"share in his rejoicing!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0233', 233, 'When the sun is darkened', 'CP', 'en', 'Christopher Idle,  administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            ? Norman Warren, administered by The Jubilate Group. Used by permission. arrangement: ? No?l Tredinnick, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'When the sun is darkened
and the moon gives no light,
and the stars fall from the sky,
then in heaven will appear
the long-promised sign
that proclaims the Son of Man.
All the peoples of the world
will cry and lament
when they see the Son of Man
coming in great power and glory
high on the clouds
with his angels serving him.
He will send his angels
with a loud trumpet blast,');
