INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0233', 'verse', 2, 1, '[\"All the peoples of the world\",\"will cry and lament\",\"when they see the Son of Man\",\"coming in great power and glory\",\"high on the clouds\",\"with his angels serving him.\"]');
