INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0234', 'verse', 3, 2, '[\"Only love can answer why\",\"he should come to grieve and die,\",\"share on earth our pain and loss,\",\"bear for us the bitter cross.\",\"Love is come to seek and save,\",\"Life to master death and grave,\",\"so in Christ is all restored,\",\"risen and redeeming Lord!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0234', 'verse', 4, 3, '[\"Praise we then, in Christmas songs,\",\"him to whom all praise belongs.\",\"Hear the angel host reply\",\"‘Glory be to God on high,\",\"joy and peace to mortals given,\",\"peace on earth and peace with heaven!’\",\"Join we now, as one with them:\",\"sing the songs of Bethlehem!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0235', 235, 'While shepherds watched their flocks', 'CP', 'en', '', '', 0, 0, 0, 1, 1, 'While shepherds watched their flocks by night,
all seated on the ground,
the angel of the Lord came down
and glory shone around.
‘Fear not,’ said he – for mighty dread
had seized their troubled mind –
‘Good new of greatest joy I bring
to you and all mankind:
‘To you in Bethlehem this day
is born of David’s line
a saviour, who is Christ the Lord.
And this shall be the sign:
‘The heavenly babe you there shall find
to human view displayed,
all tightly wrapped in swathing bands
and in a manger laid.’
Thus spoke the seraph, and forthwith
appeared a shining throng
of angels praising God, who thus
addressed their joyful song:
‘All glory be to God on high,
and to the earth be peace;
good will henceforth from highest heaven
begin and never cease!’');
