INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0240', 240, 'Within a crib my saviour lay', 'CP', 'en', 'Timothy Dudley-Smith, and from January 2007 administered by Oxford University Press. Reproduced by permission.            ? Norman Warren, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'Within a crib my saviour lay,
a wooden manger filled with hay,
come down for love on Christmas Day:
all glory be to Jesus!
Upon a cross my saviour died,
to ransom sinners crucified,
his loving arms still open wide:
all glory be to Jesus!
A victor’s crown my saviour won,
his work of love and mercy done,
the Father’s high-ascended Son:
all glory be to Jesus!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0240', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0240', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0240', 'verse', 1, 0, '[\"Within a crib my saviour lay,\",\"a wooden manger filled with hay,\",\"come down for love on Christmas Day:\",\"all glory be to Jesus!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0240', 'verse', 2, 1, '[\"Upon a cross my saviour died,\",\"to ransom sinners crucified,\",\"his loving arms still open wide:\",\"all glory be to Jesus!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0240', 'verse', 3, 2, '[\"A victor’s crown my saviour won,\",\"his work of love and mercy done,\",\"the Father’s high-ascended Son:\",\"all glory be to Jesus!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0241', 241, 'Wise men of old', 'CP', 'en', 'John Capon, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Peacock, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Wise men of old came seeking, searching,
long was their journey, hard their task,
riding their camels, swaying. lurching,
losing their way, they stopped to ask.
Wise men of old came seeking, searching,
long was their journey, hard their task.
Led by a star the wise men journeyed
sure they would see a new king’s birth.
Theirs was a faith profound and learned
seeking a jewel of priceless worth.
Led by a star the wise men journeyed
sure they would see a new king’s birth.
Inside the house the wise men found him,
this was the King they long had sought.
Filled with great joy they knelt around him,
frankincense, gold and myrrh they brought.
Inside the house the wise men found him,
this was the King they long had sought.
Joy to the world, the message ringing,
homage to Christ, whom we adore;
praises to God, the whole world singing,
wise men and humble, rich and poor.
With them we come, our own gifts bringing,
serving him now and evermore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0241', 'John Capon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0241', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0241', 'verse', 1, 0, '[\"Wise men of old came seeking, searching,\",\"long was their journey, hard their task,\",\"riding their camels, swaying. lurching,\",\"losing their way, they stopped to ask.\",\"Wise men of old came seeking, searching,\",\"long was their journey, hard their task.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0241', 'verse', 2, 1, '[\"Led by a star the wise men journeyed\",\"sure they would see a new king’s birth.\",\"Theirs was a faith profound and learned\",\"seeking a jewel of priceless worth.\",\"Led by a star the wise men journeyed\",\"sure they would see a new king’s birth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0241', 'verse', 3, 2, '[\"Inside the house the wise men found him,\",\"this was the King they long had sought.\",\"Filled with great joy they knelt around him,\",\"frankincense, gold and myrrh they brought.\",\"Inside the house the wise men found him,\",\"this was the King they long had sought.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0241', 'verse', 4, 3, '[\"Joy to the world, the message ringing,\",\"homage to Christ, whom we adore;\",\"praises to God, the whole world singing,\",\"wise men and humble, rich and poor.\",\"With them we come, our own gifts bringing,\",\"serving him now and evermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0242', 242, 'Word of the Father everlasting', 'CP', 'en', 'David Mowbray, administered by The Jubilate Group. www.jubilate.co.uk. Used by permission.            arrangement: ? David Iliff, administered by The Jubilate Group. Used by permission.', '', 0, 0, 0, 1, 1, 'Word of the Father everlasting,
there at his side when time began;
who but the Word reflects his glory,
who but the Word may speak to man?
Word of the Father everlasting,
there at his side when time began.
Word once made flesh in Mary’s keeping,
source of all life and one true light;
who of his own will dare receive him,
or to their homes and hearts invite?
Word once made flesh in Mary’s keeping,
source of all life and one true light.
Word full of grace, among us dwelling,
Jesus our Lord, the Father’s Son:
give us the power, your name confessing,
truly God’s children to become.
Word full of grace, among us dwelling,
Jesus our Lord, the Father’s Son.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('CP-0242', 'David Mowbray');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('CP-0242', 'David Iliff');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0242', 'verse', 1, 0, '[\"Word of the Father everlasting,\",\"there at his side when time began;\",\"who but the Word reflects his glory,\",\"who but the Word may speak to man?\",\"Word of the Father everlasting,\",\"there at his side when time began.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0242', 'verse', 2, 1, '[\"Word once made flesh in Mary’s keeping,\",\"source of all life and one true light;\",\"who of his own will dare receive him,\",\"or to their homes and hearts invite?\",\"Word once made flesh in Mary’s keeping,\",\"source of all life and one true light.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CP-0242', 'verse', 3, 2, '[\"Word full of grace, among us dwelling,\",\"Jesus our Lord, the Father’s Son:\",\"give us the power, your name confessing,\",\"truly God’s children to become.\",\"Word full of grace, among us dwelling,\",\"Jesus our Lord, the Father’s Son.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CP-0243', 243, 'You’re the word of God the Father', 'CP', 'en', '2002 Thankyou Music, administered by worshiptogether.com songs excl. UK and Europe, administered by kingswaysongs.com. tym@kingsway.co.uk. Used by permission.', '', 0, 0, 0, 1, 0, 'You’re the word of God the Father,');
