INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0001', 1, 'A boy gave to Jesus', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Then all worshipped Jesus as enough loaves and fish
were given to everyone there.
But Jesus just watched them, and smiled at the lad
who’d given his lunch-box for Jesus to share.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0001', 'Peter Horrobin');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0001', 'Peter Horrobin');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0001', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0001', 'verse', 3, 0, '[\"Then all worshipped Jesus as enough loaves and fish\",\"were given to everyone there.\",\"But Jesus just watched them, and smiled at the lad\",\"who’d given his lunch-box for Jesus to share.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0002', 2, 'Abba Father', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Abba Father, let me be
Yours and Yours alone.
May my will for ever be
evermore Your own.
Never let my heart grow cold,
never let me go,
Abba Father, let me be
Yours and Yours alone.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0002', 'Dave Bilbrough');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0002', 'Dave Bilbrough');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0002', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0002', 'verse', 1, 0, '[\"Abba Father, let me be\",\"Yours and Yours alone.\",\"May my will for ever be\",\"evermore Your own.\",\"Never let my heart grow cold,\",\"never let me go,\",\"Abba Father, let me be\",\"Yours and Yours alone.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0003', 3, 'Alleluia, alleluia, give thanks', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Come let us praise the living God,
joyfully sing to our Saviour:
Alleluia, alleluia...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0003', 'Donald Fishel');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0003', 'Donald Fishel');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0003', 'Betty Pulkingham');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0003', 'verse', 5, 0, '[\"Come let us praise the living God,\",\"joyfully sing to our Saviour:\",\"Alleluia, alleluia...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0005', 5, 'All over the world', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Right here in this place the Spirit is moving,
right here in this place as the prophet said it would be;
right here in this place there’s a mighty revelation
of the glory of the Lord, as the waters cover the sea.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0005', 'Roy Turner');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0005', 'Roy Turner');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0005', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0005', 'verse', 3, 0, '[\"Right here in this place the Spirit is moving,\",\"right here in this place as the prophet said it would be;\",\"right here in this place there’s a mighty revelation\",\"of the glory of the Lord, as the waters cover the sea.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0007', 7, 'All around me, Lord', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'All around me, Lord, I see Your goodness,
all creation sings Your praises,
all the world cries, ‘God is love!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0007', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0007', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0007', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0007', 'verse', 1, 0, '[\"All around me, Lord, I see Your goodness,\",\"all creation sings Your praises,\",\"all the world cries, ‘God is love!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0008', 8, 'Amazing grace', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'When we’ve been there ten thousand years
bright shining as the sun,
we’ve no less days to sing God’s praise
than when we’ve first begun.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0008', 'John Newton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0008', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0008', 'verse', 4, 0, '[\"When we’ve been there ten thousand years\",\"bright shining as the sun,\",\"we’ve no less days to sing God’s praise\",\"than when we’ve first begun.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0009', 9, 'As with gladness', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'In the heavenly country bright
need they no created light;
You its light, its joy, its crown,
You its sun which goes not down.
There for ever may we sing
hallelujahs to our King.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0009', 'William Chatterton Dix');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0009', 'verse', 5, 0, '[\"In the heavenly country bright\",\"need they no created light;\",\"You its light, its joy, its crown,\",\"You its sun which goes not down.\",\"There for ever may we sing\",\"hallelujahs to our King.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0010', 10, 'Angels from the realms of glory', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Though an infant now we view Him,
He will share His Father’s throne,
gather all the nations to Him;
every knee shall then bow down:
Come and worship...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0010', 'James Montgomery');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0010', 'verse', 4, 0, '[\"Though an infant now we view Him,\",\"He will share His Father’s throne,\",\"gather all the nations to Him;\",\"every knee shall then bow down:\",\"Come and worship...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0011', 11, 'Ask! Ask! Ask!', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'Ask! Ask! Ask! and it shall be given you;
Seek! Seek! Seek! and you shall find;
Knock! Knock! Knock! it shall be opened unto you,
your heavenly Father is so kind.
He knows what is best for His children
in body, soul and mind;
So ask! Ask! Ask! Knock! Knock! Knock!
Seek and you shall find.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0011', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0011', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0011', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0011', 'verse', 1, 0, '[\"Ask! Ask! Ask! and it shall be given you;\",\"Seek! Seek! Seek! and you shall find;\",\"Knock! Knock! Knock! it shall be opened unto you,\",\"your heavenly Father is so kind.\",\"He knows what is best for His children\",\"in body, soul and mind;\",\"So ask! Ask! Ask! Knock! Knock! Knock!\",\"Seek and you shall find.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0012', 12, 'Away in a manger', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Be near me, Lord Jesus; I ask You to stay
close by me for ever and love me, I pray;
bless all the dear children in Your tender care,
and fit us for heaven to live with You there.
Words verses 1, 2 by Anon
Words verse 3 by J T McFarland');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0012', 'William James Kirkpatrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0012', 'verse', 3, 0, '[\"Be near me, Lord Jesus; I ask You to stay\",\"close by me for ever and love me, I pray;\",\"bless all the dear children in Your tender care,\",\"and fit us for heaven to live with You there.\",\"Words verses 1, 2 by Anon\",\"Words verse 3 by J T McFarland\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0014', 14, 'Be bold, be strong', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Be bold, be strong,
for the Lord your God is with you;
be bold, be strong,
for the Lord your God is with you!
I am not afraid, (No! No! No!)
I am not dismayed, (Not me!)
for I’m walking in faith and victory:
come on and walk in faith and victory,
for the Lord your God is with you.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0014', 'Morris Chapman');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0014', 'Morris Chapman');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0014', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0014', 'verse', 1, 0, '[\"Be bold, be strong,\",\"for the Lord your God is with you;\",\"be bold, be strong,\",\"for the Lord your God is with you!\",\"I am not afraid, (No! No! No!)\",\"I am not dismayed, (Not me!)\",\"for I’m walking in faith and victory:\",\"come on and walk in faith and victory,\",\"for the Lord your God is with you.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0015', 15, 'Behold, what manner of love', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Behold, what manner of love the Father has given unto us,
Behold, what manner of love the Father has given unto us,
that we should be called the sons of God,
that we should be called the sons of God.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0015', 'Patricia van Tine');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0015', 'Patricia van Tine');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0015', 'verse', 1, 0, '[\"Behold, what manner of love the Father has given unto us,\",\"Behold, what manner of love the Father has given unto us,\",\"that we should be called the sons of God,\",\"that we should be called the sons of God.\"]');
