INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0017', 17, 'Bind us together, Lord', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'You are the family of God,
You are the promise divine,
You are God’s chosen desire,
You are the glorious new wine.
Bind us together...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0017', 'Bob Gillman');
