INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0018', 18, 'Barabbas was a bad man', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'So Jesus, though a good man,
was killed on Calvary,
but three days on, He rose again
to live eternally.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0018', 'Peter Horrobin');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0018', 'Peter Horrobin');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0018', 'verse', 4, 0, '[\"So Jesus, though a good man,\",\"was killed on Calvary,\",\"but three days on, He rose again\",\"to live eternally.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0019', 19, 'Bless the Lord, O my soul', 'JP', 'en', 'control            arrangement:', '', 0, 0, 0, 1, 1, 'Bless the Lord, O my soul...');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0019', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0019', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0019', 'verse', 1, 0, '[\"Bless the Lord, O my soul...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0020', 20, 'Bless', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Perfect submission, all is at rest,
I in my Saviour am happy and blest;
watching and waiting, looking above,
filled with His goodness, lost in His love.
This is my story...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0020', 'Fanny J Crosby');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0020', 'Phoebe Palmer Knapp');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0020', 'verse', 3, 0, '[\"Perfect submission, all is at rest,\",\"I in my Saviour am happy and blest;\",\"watching and waiting, looking above,\",\"filled with His goodness, lost in His love.\",\"This is my story...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0021', 21, 'Brothers and sisters', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus has told us
to be of good cheer,
for He is with us,
His Spirit is here!
He gives us power
His message to share.
We’re brothers and sisters
in Jesus our Lord!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0021', 'Roger Jones');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0021', 'Roger Jones');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0021', 'verse', 3, 0, '[\"Jesus has told us\",\"to be of good cheer,\",\"for He is with us,\",\"His Spirit is here!\",\"He gives us power\",\"His message to share.\",\"We’re brothers and sisters\",\"in Jesus our Lord!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0022', 22, 'Be still and know', 'JP', 'en', 'control            arrangement:', '', 0, 0, 0, 1, 1, 'In Thee, O Lord, I put my trust.
In Thee, O Lord, I put my trust.
In Thee, O Lord, I put my trust.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0022', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0022', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0022', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0022', 'verse', 3, 0, '[\"In Thee, O Lord, I put my trust.\",\"In Thee, O Lord, I put my trust.\",\"In Thee, O Lord, I put my trust.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0023', 23, 'By blue Galilee', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, 'By blue Galilee Jesus walked of old,
by blue Galilee wondrous things He told.
Saviour, still my teacher be,
showing wondrous things to me
as of old by Galilee, blue Galilee.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0023', 'E H Swinstead');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0023', 'E H Swinstead');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0023', 'verse', 1, 0, '[\"By blue Galilee Jesus walked of old,\",\"by blue Galilee wondrous things He told.\",\"Saviour, still my teacher be,\",\"showing wondrous things to me\",\"as of old by Galilee, blue Galilee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0024', 24, 'Children of Jerusalem', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Parents, teachers, old and young,
all unite to swell the song;
higher let God’s praises rise,
as hosannas fill the skies:
Hark, hark, hark...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0024', 'John Henley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0024', 'verse', 3, 0, '[\"Parents, teachers, old and young,\",\"all unite to swell the song;\",\"higher let God’s praises rise,\",\"as hosannas fill the skies:\",\"Hark, hark, hark...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0025', 25, 'Christ triumphant', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'So, our hearts and voices raising
through the ages long,
ceaselessly upon You gazing,
this shall be our song:
Yours the glory...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0025', 'Michael Saward');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0025', 'Michael Baughen');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0025', 'verse', 5, 0, '[\"So, our hearts and voices raising\",\"through the ages long,\",\"ceaselessly upon You gazing,\",\"this shall be our song:\",\"Yours the glory...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0026', 26, 'Clap your hands, all you people', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Clap your hands, all you people,
shout unto God with a voice of triumph,
clap your hands, all you people,
shout unto God with a voice of praise!
Hosanna, hosanna,
shout unto God with a voice of triumph,
praise Him, praise Him,
shout unto God with a voice of praise!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0026', 'Jimmy Owens');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0026', 'Jimmy Owens');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0026', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0026', 'verse', 1, 0, '[\"Clap your hands, all you people,\",\"shout unto God with a voice of triumph,\",\"clap your hands, all you people,\",\"shout unto God with a voice of praise!\",\"Hosanna, hosanna,\",\"shout unto God with a voice of triumph,\",\"praise Him, praise Him,\",\"shout unto God with a voice of praise!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0027', 27, 'Cleanse me from my sin', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Cleanse me from my sin, Lord,
put Your power within, Lord,
take me as I am, Lord,
and make me all Your own.
Keep me day by day, Lord,
in Your perfect way, Lord,
make my heart Your palace,
and Your royal throne.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0027', 'R Hudson Pope');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0027', 'R Hudson Pope');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0027', 'verse', 1, 0, '[\"Cleanse me from my sin, Lord,\",\"put Your power within, Lord,\",\"take me as I am, Lord,\",\"and make me all Your own.\",\"Keep me day by day, Lord,\",\"in Your perfect way, Lord,\",\"make my heart Your palace,\",\"and Your royal throne.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0028', 28, 'Light up the fire', 'JP', 'en', '', '', 0, 0, 0, 1, 0, '');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0028', 'Sue McClellan');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0028', 'John Paculabo');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0028', 'Keith Ryecroft');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0028', 'Sue McClellan');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0028', 'John Paculabo');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0028', 'Keith Ryecroft');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0028', 'Douglas Coombes');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0029', 29, 'Come, let us sing', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Come fill my heart with Your wonderful love,
come and abide,
lifting my life till it rises above
envy and falsehood and pride;
seeking to live
life that is humble, with strength that You give.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0029', 'Robert Walmsley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0029', 'Frederick Luke Wiseman');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0029', 'verse', 4, 0, '[\"Come fill my heart with Your wonderful love,\",\"come and abide,\",\"lifting my life till it rises above\",\"envy and falsehood and pride;\",\"seeking to live\",\"life that is humble, with strength that You give.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0030', 30, 'Come, listen to my tale', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'Come, listen to my tale
of Jonah and the whale,
way down in the middle of the ocean.
Well, how did he get there?
Whatever did he wear?
Way down in the middle of the ocean.
A-preaching he should be
at Nineveh, you see –
to disobey’s a very foolish notion.
But God forgave his sin,
salvation entered in,
way down in the middle of the
way down in the middle of the
way down in the middle of the ocean.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0030', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0030', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0030', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0030', 'verse', 1, 0, '[\"Come, listen to my tale\",\"of Jonah and the whale,\",\"way down in the middle of the ocean.\",\"Well, how did he get there?\",\"Whatever did he wear?\",\"Way down in the middle of the ocean.\",\"A-preaching he should be\",\"at Nineveh, you see –\",\"to disobey’s a very foolish notion.\",\"But God forgave his sin,\",\"salvation entered in,\",\"way down in the middle of the\",\"way down in the middle of the\",\"way down in the middle of the ocean.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0031', 31, 'Come on, let’s get up and go', 'JP', 'en', '1986 Kingsway\'s Thankyou Music, PO Box 75, Eastbourne, East Sussex BN23 6NW, UK. Used by permission', '', 0, 0, 0, 1, 0, 'Come on, let’s get up and go,
let everyone know.
We’ve got a reason to shout and to sing
’cause Jesus loves us
and that’s a wonderful thing.
Go! go! go! go! get up and go,
don’t be sleepy or slow!
You, you, you, you know what to do,
give your life to Him.
Come on, let’s get up and go...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0031', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0031', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0031', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0031', 'verse', 1, 0, '[\"Come on, let’s get up and go,\",\"let everyone know.\",\"We’ve got a reason to shout and to sing\",\"’cause Jesus loves us\",\"and that’s a wonderful thing.\",\"Go! go! go! go! get up and go,\",\"don’t be sleepy or slow!\",\"You, you, you, you know what to do,\",\"give your life to Him.\",\"Come on, let’s get up and go...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0032', 32, 'Come, you thankful people, come', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Even so, Lord, quickly come –
bring Your final harvest home!
Gather all Your people in
free from sorrow, free from sin,
there together purified,
ever thankful at Your side –
come, with all Your angels, come,
bring that glorious harvest home!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0032', 'Henry Alford');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0032', 'George Job Elvey');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0032', 'verse', 4, 0, '[\"Even so, Lord, quickly come –\",\"bring Your final harvest home!\",\"Gather all Your people in\",\"free from sorrow, free from sin,\",\"there together purified,\",\"ever thankful at Your side –\",\"come, with all Your angels, come,\",\"bring that glorious harvest home!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0033', 33, 'Come to Jesus, He’s amazing', 'JP', 'en', '1986 Peter Horrobin            ? 1986 Phil Burt', '', 0, 0, 0, 1, 1, '‘Come to Jesus, He’s amazing!’
people cried out when they saw
people walking who were crippled,
blind eyes seeing, healed once more.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0033', 'Peter Horrobin');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0033', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0033', 'verse', 1, 0, '[\"‘Come to Jesus, He’s amazing!’\",\"people cried out when they saw\",\"people walking who were crippled,\",\"blind eyes seeing, healed once more.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0034', 34, 'Come and praise the Lord our King', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'We will live with Him one day, hallelujah,
and for ever with Him stay, hallelujah.
Come and praise...
Words adapted by Geoffrey Marshall-Taylor');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0034', 'Douglas Coombes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0034', 'verse', 6, 0, '[\"We will live with Him one day, hallelujah,\",\"and for ever with Him stay, hallelujah.\",\"Come and praise...\",\"Words adapted by Geoffrey Marshall-Taylor\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0035', 35, 'Deep and wide', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Deep and wide, deep and wide,
there’s a fountain flowing deep and wide;
deep and wide, deep and wide,
there’s a fountain flowing deep and wide.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0035', 'Sidney E Cox');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0035', 'Sidney E Cox');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0035', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0035', 'verse', 1, 0, '[\"Deep and wide, deep and wide,\",\"there’s a fountain flowing deep and wide;\",\"deep and wide, deep and wide,\",\"there’s a fountain flowing deep and wide.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0036', 36, 'Daniel was a man of prayer', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'Daniel was a man of prayer,
daily he prayed three times.
Till one day they had him cast
into a den of lions.
In the den, in the den,
fear could not alarm him.
God just shut the lions’ mouths
so they could not harm him.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0036', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0036', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0036', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0036', 'verse', 1, 0, '[\"Daniel was a man of prayer,\",\"daily he prayed three times.\",\"Till one day they had him cast\",\"into a den of lions.\",\"In the den, in the den,\",\"fear could not alarm him.\",\"God just shut the lions’ mouths\",\"so they could not harm him.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0037', 37, 'Dear Lord and Father of mankind', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Breathe through the heats of our desire
Your coolness and Your balm;
let sense be dumb, let flesh retire;
speak through the earthquake, wind, and fire,
O still small voice of calm!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0037', 'John Greenleaf Whittier');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0037', 'Charles Hubert Hastings Parry');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0037', 'verse', 6, 0, '[\"Breathe through the heats of our desire\",\"Your coolness and Your balm;\",\"let sense be dumb, let flesh retire;\",\"speak through the earthquake, wind, and fire,\",\"O still small voice of calm!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0038', 38, 'Ding dong! Merrily on high', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, 'Pray you, dutifully prime
your matin chime, ye ringers;
may you beautifully rime
your eve-time song, ye singers:
Gloria...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0038', 'George Ratcliffe Woodward');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0038', 'Charles Wood');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0038', 'B V Burnett');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0038', 'verse', 3, 0, '[\"Pray you, dutifully prime\",\"your matin chime, ye ringers;\",\"may you beautifully rime\",\"your eve-time song, ye singers:\",\"Gloria...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0039', 39, 'Don’t build your house on the sandy land', 'JP', 'en', '1981 Maranatha! Music, administered by CopyCare Ltd, PO Box 77, Hailsham, East Sussex BN27 3EF, UK. Used by permission', '', 0, 0, 0, 1, 1, 'Don’t build your house on the sandy land,
don’t build it too near the shore.
Well, it might look kind of nice,
but you’ll have to build it twice,
oh, you’ll have to build your house
once more.
You’d better build your house upon a rock,
make a good foundation on a solid spot.
Oh, the storms may come and go,
but the peace of God you will know.
Rock of ages, cleft for me,
let me hide myself in Thee.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0039', 'Karen Lafferty');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0039', 'Karen Lafferty');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0039', 'verse', 1, 0, '[\"Don’t build your house on the sandy land,\",\"don’t build it too near the shore.\",\"Well, it might look kind of nice,\",\"but you’ll have to build it twice,\",\"oh, you’ll have to build your house\",\"once more.\",\"You’d better build your house upon a rock,\",\"make a good foundation on a solid spot.\",\"Oh, the storms may come and go,\",\"but the peace of God you will know.\",\"Rock of ages, cleft for me,\",\"let me hide myself in Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0040', 40, 'Do you want a pilot?', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, 'Do you want a pilot?
Signal then to Jesus;
do you want a pilot?
Bid Him come on board.
For He will safely guide
across the ocean wide,
until you reach at last
the heavenly harbour.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0040', 'E H Swinstead');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0040', 'E H Swinstead');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0040', 'verse', 1, 0, '[\"Do you want a pilot?\",\"Signal then to Jesus;\",\"do you want a pilot?\",\"Bid Him come on board.\",\"For He will safely guide\",\"across the ocean wide,\",\"until you reach at last\",\"the heavenly harbour.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0041', 41, 'Father, hear the prayer we offer', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Be our strength in hours of weakness,
in our wanderings be our guide;
through endeavour, failure, danger,
Father, always at our side.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0041', 'Love Maria Willis');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0041', 'J L Steiner');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0041', 'verse', 4, 0, '[\"Be our strength in hours of weakness,\",\"in our wanderings be our guide;\",\"through endeavour, failure, danger,\",\"Father, always at our side.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0042', 42, 'Father, I place into Your hands', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Father, I want to be with You
and do the things You do.
Father, I want to speak the words
that You are speaking too.
Father, I want to love the ones
that You will draw to You,
for I know that I am one with You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0042', 'Jenny Hewer');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0042', 'Jenny Hewer');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0042', 'verse', 4, 0, '[\"Father, I want to be with You\",\"and do the things You do.\",\"Father, I want to speak the words\",\"that You are speaking too.\",\"Father, I want to love the ones\",\"that You will draw to You,\",\"for I know that I am one with You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0043', 43, 'Father, lead me day by day', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'May I do the good I know,
be Your loving child below,
then at last in heaven share
life with You that’s free from care.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0043', 'J P Hopps');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0043', 'verse', 5, 0, '[\"May I do the good I know,\",\"be Your loving child below,\",\"then at last in heaven share\",\"life with You that’s free from care.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0044', 44, 'Father, we adore You', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Spirit, we adore You,
lay our lives before You:
how we love You!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0044', 'Terrye Coelho');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0044', 'Terrye Coelho');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0044', 'verse', 3, 0, '[\"Spirit, we adore You,\",\"lay our lives before You:\",\"how we love You!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0045', 45, 'Father, we love You', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Spirit, we love You,
we worship and adore You:
glorify Your name
in all the earth.
Glorify Your name,
glorify Your name,
glorify Your name
in all the earth.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0045', 'Donna Adkins');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0045', 'Donna Adkins');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0045', 'verse', 3, 0, '[\"Spirit, we love You,\",\"we worship and adore You:\",\"glorify Your name\",\"in all the earth.\",\"Glorify Your name,\",\"glorify Your name,\",\"glorify Your name\",\"in all the earth.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0046', 46, 'Follow Me, says Jesus', 'JP', 'en', '1986 Greg Leavers', '', 0, 0, 0, 1, 1, '‘Follow Me,’ says Jesus,
‘I can keep you safe.
I am the good shepherd,
so why not be My sheep?
If you’re lost and lonely
I can keep you safe.
I gave My life to save you,
so come, just follow Me.’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0046', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0046', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0046', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0046', 'verse', 1, 0, '[\"‘Follow Me,’ says Jesus,\",\"‘I can keep you safe.\",\"I am the good shepherd,\",\"so why not be My sheep?\",\"If you’re lost and lonely\",\"I can keep you safe.\",\"I gave My life to save you,\",\"so come, just follow Me.’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0047', 47, 'For I’m building a people of power', 'JP', 'en', '1977 Kingsway\'s Thankyou Music, PO Box 75, Eastbourne, East Sussex BN23 6NW, UK. Used by permission', '', 0, 0, 0, 1, 0, 'For I’m building a people of power
and I’m making a people of praise,
that will move through this land
by My Spirit,
and will glorify My precious name.
Build Your Church, Lord,
make us strong, Lord,
join our hearts, Lord, through Your Son;
make us one, Lord, in Your body,
in the kingdom of Your Son.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0047', 'Dave Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0047', 'Dave Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0047', 'Roger Mayor');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0047', 'verse', 1, 0, '[\"For I’m building a people of power\",\"and I’m making a people of praise,\",\"that will move through this land\",\"by My Spirit,\",\"and will glorify My precious name.\",\"Build Your Church, Lord,\",\"make us strong, Lord,\",\"join our hearts, Lord, through Your Son;\",\"make us one, Lord, in Your body,\",\"in the kingdom of Your Son.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0048', 48, 'For the beauty of the earth', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'For each perfect gift divine
to our race so freely given,
thank You, Lord, that they are mine,
here on earth as gifts from heaven;
Father, unto You we raise
this our sacrifice of praise.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0048', 'Folliott Pierpoint');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0048', 'verse', 4, 0, '[\"For each perfect gift divine\",\"to our race so freely given,\",\"thank You, Lord, that they are mine,\",\"here on earth as gifts from heaven;\",\"Father, unto You we raise\",\"this our sacrifice of praise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0049', 49, 'From the rising of the sun', 'JP', 'en', '', '', 0, 0, 0, 1, 1, '');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0049', 'Paul S Deming');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0049', 'Paul S Deming');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0050', 50, 'Give me oil in my lamp', 'JP', 'en', 'control.', '', 0, 0, 0, 1, 0, 'Give me peace in my heart, keep me resting,
give me peace in my heart, I pray;
give me peace in my heart, keep me resting,
keep me resting till the break of day.
Sing hosanna...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0050', 'A Sevison');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0050', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0050', 'Betty Pulkingham');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0050', 'verse', 4, 0, '[\"Give me peace in my heart, keep me resting,\",\"give me peace in my heart, I pray;\",\"give me peace in my heart, keep me resting,\",\"keep me resting till the break of day.\",\"Sing hosanna...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0051', 51, 'Glory to God in the highest', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'The next time we hear a song
of worship from a heavenly throng,
will be when Jesus comes again,
then with triumph we’ll all sing:
Glory to God...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0051', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0051', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0051', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0051', 'verse', 2, 0, '[\"The next time we hear a song\",\"of worship from a heavenly throng,\",\"will be when Jesus comes again,\",\"then with triumph we’ll all sing:\",\"Glory to God...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0052', 52, 'Glory to You, my God', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Praise God from whom all blessings flow
in heaven above and earth below;
one God, three persons, we adore –
to Him be praise for evermore!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0052', 'Thomas Ken');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0052', 'Thomas Tallis');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0052', 'verse', 6, 0, '[\"Praise God from whom all blessings flow\",\"in heaven above and earth below;\",\"one God, three persons, we adore –\",\"to Him be praise for evermore!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0053', 53, 'God is so good', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'God is so good,
He took my sin,
now I am free,
He’s so good to me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0053', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0053', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0053', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0053', 'verse', 4, 0, '[\"God is so good,\",\"He took my sin,\",\"now I am free,\",\"He’s so good to me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0054', 54, 'God forgave my sin', 'JP', 'en', '1972 Bud John Songs/ CapitolCMGPublishing.com (adm Song Solutions www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'God forgave my sin in Jesus’ name;
I’ve been born again in Jesus’ name,
and in Jesus’ name I come to you
to share His love as He told me to.
He said:
‘Freely, freely you have received,
freely, freely give;
go in My name and because you believe,
others will know that I live.’
All power is given in Jesus’ name
in earth and heaven in Jesus’ name;
and in Jesus’ name I come to you
to share His power as He told me to.
He said...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0054', 'Carol Owens');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0054', 'Carol Owens');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0054', 'verse', 1, 0, '[\"God forgave my sin in Jesus’ name;\",\"I’ve been born again in Jesus’ name,\",\"and in Jesus’ name I come to you\",\"to share His love as He told me to.\",\"He said:\",\"‘Freely, freely you have received,\",\"freely, freely give;\",\"go in My name and because you believe,\",\"others will know that I live.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0054', 'verse', 2, 1, '[\"All power is given in Jesus’ name\",\"in earth and heaven in Jesus’ name;\",\"and in Jesus’ name I come to you\",\"to share His power as He told me to.\",\"He said...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0055', 55, 'God is good', 'JP', 'en', '©  1985 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'God is good – we sing and shout it,
God is good – we celebrate;
God is good – no more we doubt it,
God is good – we know it’s true!
And when I think of His love for me,
my heart fills with praise
and I feel like dancing;
for in His heart there is room for me,
and I run with arms opened wide.
God is good – we sing and shout it,
God is good – we celebrate;
God is good – no more we doubt it,
God is good – we know it’s true! Hey!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0055', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0055', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0055', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0055', 'chorus', 0, 0, '[\"God is good – we sing and shout it,\",\"God is good – we celebrate;\",\"God is good – no more we doubt it,\",\"God is good – we know it’s true!\",\"And when I think of His love for me,\",\"my heart fills with praise\",\"and I feel like dancing;\",\"for in His heart there is room for me,\",\"and I run with arms opened wide.\",\"God is good – we sing and shout it,\",\"God is good – we celebrate;\",\"God is good – no more we doubt it,\",\"God is good – we know it’s true! Hey!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0056', 56, 'God is our guide', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'God is our strength, our rock and our redeemer
in times of trouble and in times of joy.
Lord, may our lives be full of sure thanksgiving,
our lips be full of symphonies of praise.
You gave us love, a risen, living Saviour,
we bring ourselves, a sacrifice of praise.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0056', 'Christopher Porteous');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0056', 'Jean Sibelius');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0056', 'verse', 4, 0, '[\"God is our strength, our rock and our redeemer\",\"in times of trouble and in times of joy.\",\"Lord, may our lives be full of sure thanksgiving,\",\"our lips be full of symphonies of praise.\",\"You gave us love, a risen, living Saviour,\",\"we bring ourselves, a sacrifice of praise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0057', 57, 'God is working His purpose out', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, 'All we can do is nothing worth
unless God blesses the deed;
vainly we hope for the harvest-tide
till God gives life to the seed:
nearer and nearer draws the time,
the time that shall surely be,
when the earth shall be filled
with the glory of God,
as the waters cover the sea.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0057', 'Arthur Campbell Ainger');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0057', 'Millicent Douglas Kingham');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0057', 'verse', 4, 0, '[\"All we can do is nothing worth\",\"unless God blesses the deed;\",\"vainly we hope for the harvest-tide\",\"till God gives life to the seed:\",\"nearer and nearer draws the time,\",\"the time that shall surely be,\",\"when the earth shall be filled\",\"with the glory of God,\",\"as the waters cover the sea.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0058', 58, 'God sent His Son', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'And then one day I’ll cross the river;
I’ll fight life’s final war with pain;
and then as death gives way to victory,
I’ll see the lights of glory and I’ll know He lives.
Because He lives...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0058', 'Gloria Gaither');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0058', 'William J Gaither');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0058', 'William J Gaither');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0058', 'verse', 3, 0, '[\"And then one day I’ll cross the river;\",\"I’ll fight life’s final war with pain;\",\"and then as death gives way to victory,\",\"I’ll see the lights of glory and I’ll know He lives.\",\"Because He lives...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0059', 59, 'God so loved the world', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus showed the world the love of the Father,
Jesus showed the world how we must love.
Alleluia, Jesus, Lord Jesus, Jesus,
alleluia, Jesus, God sent His Son.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0059', 'Peter Horrobin');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0059', 'Peter Horrobin');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0059', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0059', 'verse', 2, 0, '[\"Jesus showed the world the love of the Father,\",\"Jesus showed the world how we must love.\",\"Alleluia, Jesus, Lord Jesus, Jesus,\",\"alleluia, Jesus, God sent His Son.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0060', 60, 'God’s not dead', 'JP', 'en', 'control            ? 1986 in this version Horrobin/Leavers            arrangement: ? 1986 Phil Burt', '', 0, 0, 0, 1, 1, 'God’s not dead (no),
He is alive,
God’s not dead (no),
He is alive,
God’s not dead (no),
He is alive!
Serve Him with my hands,
follow with my feet,
love Him in my heart,
know Him in my life;
for He’s alive in me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0060', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0060', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0060', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0060', 'verse', 1, 0, '[\"God’s not dead (no),\",\"He is alive,\",\"God’s not dead (no),\",\"He is alive,\",\"God’s not dead (no),\",\"He is alive!\",\"Serve Him with my hands,\",\"follow with my feet,\",\"love Him in my heart,\",\"know Him in my life;\",\"for He’s alive in me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0061', 61, 'God, whose farm is all creation', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'All our labour, all our watching,
all our calendar of care,
in these crops of Your creation,
take, O God; they are our prayer.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0061', 'John Arlott');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0061', 'verse', 3, 0, '[\"All our labour, all our watching,\",\"all our calendar of care,\",\"in these crops of Your creation,\",\"take, O God; they are our prayer.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0062', 62, 'God whose Son was once a man', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Pour Your Spirit on the church today,
that Your life through me may flow;
Spirit-filled, I’ll serve Your name
and live the truth I know.
When the Spirit comes, new life is born,
God’s people share in a bright new dawn.
We’ll heal the sick,
we’ll teach God’s word,
we’ll seek the lost,
we’ll obey the Lord.
And it’s all because the Spirit came
that the world will never be the same,
because the Spirit came.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0062', 'Peter Horrobin');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0062', 'Greg Leavers');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0062', 'verse', 3, 0, '[\"Pour Your Spirit on the church today,\",\"that Your life through me may flow;\",\"Spirit-filled, I’ll serve Your name\",\"and live the truth I know.\",\"When the Spirit comes, new life is born,\",\"God’s people share in a bright new dawn.\",\"We’ll heal the sick,\",\"we’ll teach God’s word,\",\"we’ll seek the lost,\",\"we’ll obey the Lord.\",\"And it’s all because the Spirit came\",\"that the world will never be the same,\",\"because the Spirit came.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0063', 63, 'God, who made the earth', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'God, who gave me life
His servant here to be,
has promised in His word
to care for me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0063', 'Sarah Betts Rhodes');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0063', 'Herman von Muller');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0063', 'verse', 5, 0, '[\"God, who gave me life\",\"His servant here to be,\",\"has promised in His word\",\"to care for me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0064', 64, 'Great is Your faithfulness', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Pardon for sin, and a peace everlasting,
Your living presence to cheer and to guide;
strength for today and bright hope for tomorrow,
these are the blessings Your love will provide.
Great is Your faithfulness...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0064', 'Thomas O Chisholm');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0064', 'William Marion Runyan');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0064', 'verse', 3, 0, '[\"Pardon for sin, and a peace everlasting,\",\"Your living presence to cheer and to guide;\",\"strength for today and bright hope for tomorrow,\",\"these are the blessings Your love will provide.\",\"Great is Your faithfulness...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0065', 65, 'Go, tell it on the mountain', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'He still comes to people, His life moves through the lands;
He uses us for speaking, He touches with our hands.
Go, tell it on the mountain...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0065', 'Geoffrey Marshall-Taylor');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0065', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0065', 'Douglas Coombes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0065', 'verse', 5, 0, '[\"He still comes to people, His life moves through the lands;\",\"He uses us for speaking, He touches with our hands.\",\"Go, tell it on the mountain...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0066', 66, 'Hallelujah! for the Lord our God', 'JP', 'en', 'Scripture in Song/Maranatha Music/Universal Music Publishing/Print licence adm Song Solutions Daybreak, www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Hallelujah! for the Lord our God the almighty reigns.
Hallelujah! for the Lord our God the almighty reigns.
Let us rejoice and be glad and give the glory unto Him.
Hallelujah! for the Lord our God the almighty reigns.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0066', 'Dale Garratt');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0066', 'Dale Garratt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0066', 'verse', 1, 0, '[\"Hallelujah! for the Lord our God the almighty reigns.\",\"Hallelujah! for the Lord our God the almighty reigns.\",\"Let us rejoice and be glad and give the glory unto Him.\",\"Hallelujah! for the Lord our God the almighty reigns.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0067', 67, 'Hallelu, hallelu', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'Hallelu, hallelu, hallelu, hallelujah;
we’ll praise the Lord;
hallelu, hallelu, hallelu, hallelujah;
we’ll praise the Lord!
We’ll praise the Lord, hallelujah,
we’ll praise the Lord, hallelujah,
we’ll praise the Lord, hallelujah,
we’ll praise the Lord!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0067', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0067', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0067', 'E J Hume');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0067', 'verse', 1, 0, '[\"Hallelu, hallelu, hallelu, hallelujah;\",\"we’ll praise the Lord;\",\"hallelu, hallelu, hallelu, hallelujah;\",\"we’ll praise the Lord!\",\"We’ll praise the Lord, hallelujah,\",\"we’ll praise the Lord, hallelujah,\",\"we’ll praise the Lord, hallelujah,\",\"we’ll praise the Lord!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0068', 68, 'Hark, the glad sound', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Our glad hosannas, Prince of peace,
Your welcome shall proclaim;
and heaven’s eternal arches ring
with Your belovèd name.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0068', 'Philip Doddridge');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0068', 'Frederick George Baker');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0068', 'verse', 4, 0, '[\"Our glad hosannas, Prince of peace,\",\"Your welcome shall proclaim;\",\"and heaven’s eternal arches ring\",\"with Your belovèd name.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0069', 69, 'Hark! the herald-angels sing', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Hail, the heaven-born Prince of peace!
Hail, the Sun of righteousness!
Light and life to all He brings,
risen with healing in His wings.
Mild He lays His glory by,
born that man no more may die;
born to raise the sons of earth,
born to give them second birth.
Hark! the herald-angels sing,
‘Glory to the new-born King!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0069', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0069', 'Felix Mendelssohn');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0069', 'William H Cummings');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0069', 'verse', 3, 0, '[\"Hail, the heaven-born Prince of peace!\",\"Hail, the Sun of righteousness!\",\"Light and life to all He brings,\",\"risen with healing in His wings.\",\"Mild He lays His glory by,\",\"born that man no more may die;\",\"born to raise the sons of earth,\",\"born to give them second birth.\",\"Hark! the herald-angels sing,\",\"‘Glory to the new-born King!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0070', 70, 'Happiness is to know the Saviour', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Happiness is to be forgiven,
living a life that’s worth the living,
taking a trip that leads to heaven,
happiness is the Lord,
happiness is the Lord,
happiness is the Lord!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0070', 'Ira F Stanphill');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0070', 'Ira F Stanphill');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0070', 'verse', 3, 0, '[\"Happiness is to be forgiven,\",\"living a life that’s worth the living,\",\"taking a trip that leads to heaven,\",\"happiness is the Lord,\",\"happiness is the Lord,\",\"happiness is the Lord!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0071', 71, 'Have you heard the raindrops', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Nobody can live who hasn’t any water,
when the land is dry then nothing much grows;
Jesus gives us life if we drink the living water,
sing it so that everybody knows.
There’s water...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0071', 'Christian Strover');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0071', 'Christian Strover');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0071', 'verse', 3, 0, '[\"Nobody can live who hasn’t any water,\",\"when the land is dry then nothing much grows;\",\"Jesus gives us life if we drink the living water,\",\"sing it so that everybody knows.\",\"There’s water...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0072', 72, 'Have you seen the pussy cat', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Have you seen the children coming home from school?
Have you heard them shout, ‘Hurray!’ (Hurray!)
Have you seen the grown-ups coming home from work,
saying, ‘What a horrible day!’ (What a horrible day!)
Some so big, some so small,
our heavenly Father cares for them all,
some so big, some so small,
our heavenly Father cares.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0072', 'P A Taylor');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0072', 'P A Taylor');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0072', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0072', 'verse', 2, 0, '[\"Have you seen the children coming home from school?\",\"Have you heard them shout, ‘Hurray!’ (Hurray!)\",\"Have you seen the grown-ups coming home from work,\",\"saying, ‘What a horrible day!’ (What a horrible day!)\",\"Some so big, some so small,\",\"our heavenly Father cares for them all,\",\"some so big, some so small,\",\"our heavenly Father cares.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0073', 73, 'He brought me to His banqueting house', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'Jesus is the rock of my salvation...
God loves you...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0073', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0073', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0073', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0073', 'verse', 5, 0, '[\"Jesus is the rock of my salvation...\",\"God loves you...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0074', 74, 'He gave me eyes so I could see', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'He gave me eyes so I could see
the wonders of the world.
Without my eyes I could not see
the other boys and girls.
He gave me ears so I could hear
the wind and rain and sea.
I’ve got to tell it to the world,
He made me!
He gave me lips so I could speak,
and say what’s in my mind.
Without my lips I could not speak
a single word or line.
He made my mind so I could think
and choose what I should be.
I’ve got to tell it to the world,
He made me!
He gave me hands so I could touch,
and hold a thousand things.
I need my hands to help me write,
to help me fetch and bring.
These feet He made so I could run,
He meant me to be free.
I’ve got to tell it to the world,
He made me!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0074', 'Alan Pinnock');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0074', 'Alan Pinnock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0074', 'verse', 1, 0, '[\"He gave me eyes so I could see\",\"the wonders of the world.\",\"Without my eyes I could not see\",\"the other boys and girls.\",\"He gave me ears so I could hear\",\"the wind and rain and sea.\",\"I’ve got to tell it to the world,\",\"He made me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0074', 'verse', 2, 1, '[\"He gave me lips so I could speak,\",\"and say what’s in my mind.\",\"Without my lips I could not speak\",\"a single word or line.\",\"He made my mind so I could think\",\"and choose what I should be.\",\"I’ve got to tell it to the world,\",\"He made me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0074', 'verse', 3, 2, '[\"He gave me hands so I could touch,\",\"and hold a thousand things.\",\"I need my hands to help me write,\",\"to help me fetch and bring.\",\"These feet He made so I could run,\",\"He meant me to be free.\",\"I’ve got to tell it to the world,\",\"He made me!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0075', 75, 'He is Lord, He is Lord', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'He’s my Lord, He’s my Lord,
He is risen from the dead
and He’s my Lord!
And my knee shall bow
and my tongue confess
that Jesus is my Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0075', 'Marvin Frey');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0075', 'Marvin Frey');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0075', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0075', 'verse', 2, 0, '[\"He’s my Lord, He’s my Lord,\",\"He is risen from the dead\",\"and He’s my Lord!\",\"And my knee shall bow\",\"and my tongue confess\",\"that Jesus is my Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0076', 76, 'He made the stars to shine', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'He made the stars to shine,
He made the rolling sea,
He made the mountains high,
and He made me.
But this is why I love Him –
for me He bled and died,
the Lord of all creation
became the crucified.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0076', 'Archie Hall');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0076', 'Archie Hall');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0076', 'verse', 1, 0, '[\"He made the stars to shine,\",\"He made the rolling sea,\",\"He made the mountains high,\",\"and He made me.\",\"But this is why I love Him –\",\"for me He bled and died,\",\"the Lord of all creation\",\"became the crucified.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0077', 77, 'He paid a debt', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'He paid a debt He did not owe,
I owed a debt I could not pay.
I needed someone to wash my sins away,
and now I sing a brand new song,
‘Amazing grace!’ the whole day long,
for Jesus paid a debt that I could never pay.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0077', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0077', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0077', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0077', 'verse', 1, 0, '[\"He paid a debt He did not owe,\",\"I owed a debt I could not pay.\",\"I needed someone to wash my sins away,\",\"and now I sing a brand new song,\",\"‘Amazing grace!’ the whole day long,\",\"for Jesus paid a debt that I could never pay.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0078', 78, 'He’s got the whole wide world', 'JP', 'en', 'HarperCollinsReligious, administered by CopyCare Ltd, PO Box 77, Hailsham, East Sussex BN27 3EF, UK. Used by permission', '', 0, 0, 0, 1, 1, 'He’s got the whole wide world in His hands,
He’s got the whole wide world in His hands,
He’s got the whole wide world in His hands,
He’s got the whole world in His hands.
He’s got everybody here in His hands...
He’s got the tiny little baby in His hands...
He’s got you and me, brother, in His hands...');
