INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0078', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0078', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0078', 'verse', 1, 0, '[\"He’s got the whole wide world in His hands,\",\"He’s got the whole wide world in His hands,\",\"He’s got the whole wide world in His hands,\",\"He’s got the whole world in His hands.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0078', 'verse', 2, 1, '[\"He’s got everybody here in His hands...\"]');
