INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0079', 79, 'He’s great! He’s God', 'JP', 'en', '1986 Peter Horrobin and Greg Leavers            ? 1986 Phil Burt and Greg Leavers', '', 0, 0, 0, 1, 1, 'He’s great! He’s God!
Jesus Christ is Lord.
He’s great! He’s God!
Trust His word.
His word is truth,
for He cannot lie.
His word is truth,
to live by.
His love is strong,
and will never end.
His love is strong,
praise His name.
He lives evermore
as the King of kings.
He lives evermore!
Worship Him.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0079', 'Peter Horrobin');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0079', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0079', 'Phil Burt');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0079', 'Greg Leavers');
