INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0079', 'verse', 2, 1, '[\"His word is truth,\",\"for He cannot lie.\",\"His word is truth,\",\"to live by.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0079', 'verse', 3, 2, '[\"His love is strong,\",\"and will never end.\",\"His love is strong,\",\"praise His name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0079', 'verse', 4, 3, '[\"He lives evermore\",\"as the King of kings.\",\"He lives evermore!\",\"Worship Him.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0080', 80, 'He who would valiant be', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Since, Lord, Thou dost defend
us with Thy Spirit,
we know we at the end
shall life inherit.
Then fancies flee away!
I’ll fear not what men say,
I’ll labour night and day
to be a pilgrim.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0080', 'Percy Dearmer');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0080', 'verse', 3, 0, '[\"Since, Lord, Thou dost defend\",\"us with Thy Spirit,\",\"we know we at the end\",\"shall life inherit.\",\"Then fancies flee away!\",\"I’ll fear not what men say,\",\"I’ll labour night and day\",\"to be a pilgrim.\"]');
