INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0082', 82, 'How great is our God', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'He rolled back the waters
of the mighty Red Sea,
and He said, ‘I’ll never leave you,
put your trust in Me.’');
