INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0083', 83, 'How did Moses cross the Red Sea?', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'How did Moses cross the Red Sea?
How did Moses cross the Red Sea?
How did Moses cross the Red Sea?
How did he get across?
Did he swim? No! No!
Did he row? No! No!
Did he jump? No! No! No! No!
Did he drive? No! No!
Did he fly? No! No!
How did he get across?
God blew with His wind, puff, puff, puff, puff.
He blew just enough, ’nough, ’nough, ’nough, ’nough,
and through the sea He made a path –
that’s how he got across.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0083', 'Hugh Mitchell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0083', 'Hugh Mitchell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0083', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0083', 'verse', 1, 0, '[\"How did Moses cross the Red Sea?\",\"How did Moses cross the Red Sea?\",\"How did Moses cross the Red Sea?\",\"How did he get across?\",\"Did he swim? No! No!\",\"Did he row? No! No!\",\"Did he jump? No! No! No! No!\",\"Did he drive? No! No!\",\"Did he fly? No! No!\",\"How did he get across?\",\"God blew with His wind, puff, puff, puff, puff.\",\"He blew just enough, ’nough, ’nough, ’nough, ’nough,\",\"and through the sea He made a path –\",\"that’s how he got across.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0084', 84, 'How lovely on the mountains', 'JP', 'en', '', '', 0, 0, 0, 1, 0, '');
