INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0085', 85, 'Hushed was the evening hymn', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'O give me Samuel’s mind,
a sweet, unmurmuring faith,
obedient and resigned
to You in life and death,
that I may read with childlike eyes
truths that are hidden from the wise.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0085', 'James Drummond Burns');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0085', 'Arthur Seymour Sullivan');
