INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0086', 86, 'I am trusting You', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I am trusting You, Lord Jesus;
never let me fall;
I am trusting You for ever,
and for all.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0086', 'Frances Ridley Havergal');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0086', 'Ethelbert William Bullinger');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0086', 'verse', 6, 0, '[\"I am trusting You, Lord Jesus;\",\"never let me fall;\",\"I am trusting You for ever,\",\"and for all.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0087', 87, 'I am a lighthouse', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'I am a lighthouse, a shining and bright house,
out in the waves of a stormy sea.
The oil of the Spirit keeps my lamp burning:
Jesus my Lord is the light in me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0087', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0087', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0087', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0087', 'verse', 1, 0, '[\"I am a lighthouse, a shining and bright house,\",\"out in the waves of a stormy sea.\",\"The oil of the Spirit keeps my lamp burning:\",\"Jesus my Lord is the light in me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0088', 88, 'I am so glad', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'If one should ask of me, ‘How can I tell?’
Glory to Jesus, I know very well;
God’s Holy Spirit with mine does agree,
constantly witnessing: Jesus loves me.
I am so glad...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0088', 'Philip Paul Bliss');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0088', 'Philip Paul Bliss');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0088', 'A E Rusbridge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0088', 'verse', 4, 0, '[\"If one should ask of me, ‘How can I tell?’\",\"Glory to Jesus, I know very well;\",\"God’s Holy Spirit with mine does agree,\",\"constantly witnessing: Jesus loves me.\",\"I am so glad...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0089', 89, 'I am the way, the truth and the life', 'JP', 'en', 'control            arrangement:', '', 0, 0, 0, 1, 1, '‘I am the way, the truth and the life,’
that’s what Jesus said.
‘I am the way, the truth and the life,’
that’s what Jesus said.
Without the way there is no going,
without the truth there is no knowing,
without the life there is no living.
‘I am the way, the truth and the life,’
that’s what Jesus said.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0089', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0089', 'D J Crawshaw');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0089', 'verse', 1, 0, '[\"‘I am the way, the truth and the life,’\",\"that’s what Jesus said.\",\"‘I am the way, the truth and the life,’\",\"that’s what Jesus said.\",\"Without the way there is no going,\",\"without the truth there is no knowing,\",\"without the life there is no living.\",\"‘I am the way, the truth and the life,’\",\"that’s what Jesus said.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0090', 90, 'I can run through a troop', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'I can run through a troop
and leap over a wall.
Hallelujah (glory, glory), hallelujah.
He’s my Prince of peace,
He gives power to all.
Hallelujah (glory, glory), hallelujah.
Now there is no condemnation,
Jesus is the rock of my salvation.
I can run through a troop
and leap over a wall.
Hallelujah (glory, glory), hallelujah.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0090', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0090', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0090', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0090', 'verse', 1, 0, '[\"I can run through a troop\",\"and leap over a wall.\",\"Hallelujah (glory, glory), hallelujah.\",\"He’s my Prince of peace,\",\"He gives power to all.\",\"Hallelujah (glory, glory), hallelujah.\",\"Now there is no condemnation,\",\"Jesus is the rock of my salvation.\",\"I can run through a troop\",\"and leap over a wall.\",\"Hallelujah (glory, glory), hallelujah.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0091', 91, 'Lord of the dance', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I danced for the scribe and the pharisee,
but they would not dance
and they wouldn’t follow me.
I danced for the fishermen,
for James and John –
they came with me and the dance went on.
Dance, then...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0091', 'Sydney Carter');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0091', 'Sydney Carter');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0091', 'verse', 2, 0, '[\"I danced for the scribe and the pharisee,\",\"but they would not dance\",\"and they wouldn’t follow me.\",\"I danced for the fishermen,\",\"for James and John –\",\"they came with me and the dance went on.\",\"Dance, then...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0092', 92, 'I do not know what lies ahead', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I do not know the course ahead,
what joys and griefs are there;
but one is near who fully knows,
I’ll trust His loving care:
I know who holds...');
