INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0092', 'verse', 3, 0, '[\"I do not know the course ahead,\",\"what joys and griefs are there;\",\"but one is near who fully knows,\",\"I’ll trust His loving care:\",\"I know who holds...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0093', 93, 'I’ll be still', 'JP', 'en', '1982 Maranatha! Music, administered by CopyCare Ltd, PO Box 77, Hailsham, East Sussex BN27 3EF, UK. Used by permission', '', 0, 0, 0, 1, 1, 'I’ll be still and know that You are God;
I’ll be still and know You are the Lord;
I’ll be still to worship and adore You,
blessèd One, Emmanuel, Jesus.');
