INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0093', 'verse', 1, 0, '[\"I’ll be still and know that You are God;\",\"I’ll be still and know You are the Lord;\",\"I’ll be still to worship and adore You,\",\"blessèd One, Emmanuel, Jesus.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0094', 94, 'If I were a butterfly', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'If I were a wiggly worm,
I’d thank You, Lord, that I could squirm,
and if I were a billy goat,
I’d thank You, Lord, for my strong throat,
and if I were a fuzzy wuzzy bear,
I’d thank You, Lord, for my fuzzy wuzzy hair,
but I just thank You, Father, for making me ‘me’.
For You gave me a heart...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0094', 'Brian Howard');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0094', 'Brian Howard');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0094', 'verse', 3, 0, '[\"If I were a wiggly worm,\",\"I’d thank You, Lord, that I could squirm,\",\"and if I were a billy goat,\",\"I’d thank You, Lord, for my strong throat,\",\"and if I were a fuzzy wuzzy bear,\",\"I’d thank You, Lord, for my fuzzy wuzzy hair,\",\"but I just thank You, Father, for making me ‘me’.\",\"For You gave me a heart...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0095', 95, 'If you see someone', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, 'If Jesus sees you lying in the road,
He won’t leave you there, he’ll give you a hand.
If Jesus sees you crying in the road,
He won’t leave you there, he’ll give you a hand.
Doesn’t matter who you are;
you might be a tramp or a movie star.
Just remember, whoever you are,
that He sees you lying there,
and He sees you crying there.');
