INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0095', 'verse', 2, 0, '[\"If Jesus sees you lying in the road,\",\"He won’t leave you there, he’ll give you a hand.\",\"If Jesus sees you crying in the road,\",\"He won’t leave you there, he’ll give you a hand.\",\"Doesn’t matter who you are;\",\"you might be a tramp or a movie star.\",\"Just remember, whoever you are,\",\"that He sees you lying there,\",\"and He sees you crying there.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0096', 96, 'If you want joy, real joy', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, 'If you want joy, real joy, wonderful joy,
let Jesus come into your heart.
If you want joy, real joy, wonderful joy,
let Jesus come into your heart.
Your sins He’ll take away,
your night He’ll turn to day,
your heart He’ll make over anew,
and then come in to stay.
If you want joy, real joy, wonderful joy,
let Jesus come into your heart.');
