INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0096', 'verse', 1, 0, '[\"If you want joy, real joy, wonderful joy,\",\"let Jesus come into your heart.\",\"If you want joy, real joy, wonderful joy,\",\"let Jesus come into your heart.\",\"Your sins He’ll take away,\",\"your night He’ll turn to day,\",\"your heart He’ll make over anew,\",\"and then come in to stay.\",\"If you want joy, real joy, wonderful joy,\",\"let Jesus come into your heart.\"]');
