INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0098', 98, 'I have decided to follow Jesus', 'JP', 'en', 'control            arrangement:', '', 0, 0, 0, 1, 1, 'Will you decide now to follow Jesus? (3 times)
no turning back, no turning back.');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0098', 'Cliff Barrows');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0098', 'Don Hustad');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0098', 'verse', 4, 0, '[\"Will you decide now to follow Jesus? (3 times)\",\"no turning back, no turning back.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0099', 99, 'I have seen the golden sunshine', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'I have seen the golden sunshine,
I have watched the flowers grow,
I have listened to the song birds
and there’s one thing now I know:
they were all put there for us to share
by someone so divine,
and if you’re a friend of Jesus
(clap, clap, clap, clap)
you’re a friend of mine.
I’ve seen the light, I’ve seen the light,
and that’s why my heart sings.
I’ve known the joy, I’ve known the joy
that loving Jesus brings.
I have seen the morning sunshine,
I have heard the oceans roar,
I have seen the flowers of springtime
and there’s one thing I am sure:
they were all put there for us to share
by someone so divine,
and if you’re a friend of Jesus
(clap, clap, clap, clap)
you’re a friend of mine.
I’ve seen the light...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0099', 'Charlie Chester');
