INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0099', 'Benny Litchfield');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0099', 'verse', 1, 0, '[\"I have seen the golden sunshine,\",\"I have watched the flowers grow,\",\"I have listened to the song birds\",\"and there’s one thing now I know:\",\"they were all put there for us to share\",\"by someone so divine,\",\"and if you’re a friend of Jesus\",\"(clap, clap, clap, clap)\",\"you’re a friend of mine.\",\"I’ve seen the light, I’ve seen the light,\",\"and that’s why my heart sings.\",\"I’ve known the joy, I’ve known the joy\",\"that loving Jesus brings.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0099', 'verse', 2, 1, '[\"I have seen the morning sunshine,\",\"I have heard the oceans roar,\",\"I have seen the flowers of springtime\",\"and there’s one thing I am sure:\",\"they were all put there for us to share\",\"by someone so divine,\",\"and if you’re a friend of Jesus\",\"(clap, clap, clap, clap)\",\"you’re a friend of mine.\",\"I’ve seen the light...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0100', 100, 'I hear the sound', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I hear the sound of the army of the Lord;
I hear the sound of the army of the Lord;
it’s the sound of praise,
it’s the sound of war;
the army of the Lord,
the army of the Lord,
the army of the Lord is marching on.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0100', 'Dave Moody');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0100', 'Dave Moody');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0100', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0100', 'verse', 1, 0, '[\"I hear the sound of the army of the Lord;\",\"I hear the sound of the army of the Lord;\",\"it’s the sound of praise,\",\"it’s the sound of war;\",\"the army of the Lord,\",\"the army of the Lord,\",\"the army of the Lord is marching on.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0101', 101, 'I may never march in the infantry', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'I may never march in the infantry,
ride with the cavalry, shoot with the artillery,
I may never zoom o’er the enemy,
for I’m in the Lord’s army.
I’m in the Lord’s army (Yes, sir!),
I’m in the Lord’s army (Yes, sir!).
I may never march in the infantry,
ride with the cavalry, shoot with the artillery,
I may never zoom o’er the enemy,
for I’m in the Lord’s army.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0101', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0101', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0101', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0101', 'verse', 1, 0, '[\"I may never march in the infantry,\",\"ride with the cavalry, shoot with the artillery,\",\"I may never zoom o’er the enemy,\",\"for I’m in the Lord’s army.\",\"I’m in the Lord’s army (Yes, sir!),\",\"I’m in the Lord’s army (Yes, sir!).\",\"I may never march in the infantry,\",\"ride with the cavalry, shoot with the artillery,\",\"I may never zoom o’er the enemy,\",\"for I’m in the Lord’s army.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0102', 102, 'I met Jesus at the crossroads', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'I met Jesus at the crossroads,
where the two ways meet.
Satan too was standing there,
and he said, ‘Come this way!
Lots and lots of pleasures
I can give to you today.’
But I said, ‘No, there’s Jesus here,
just see what He offers me.
Down here, my sins forgiven,
up there, a home in heaven.
Praise God! That’s the way for me.’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0102', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0102', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0102', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0102', 'verse', 1, 0, '[\"I met Jesus at the crossroads,\",\"where the two ways meet.\",\"Satan too was standing there,\",\"and he said, ‘Come this way!\",\"Lots and lots of pleasures\",\"I can give to you today.’\",\"But I said, ‘No, there’s Jesus here,\",\"just see what He offers me.\",\"Down here, my sins forgiven,\",\"up there, a home in heaven.\",\"Praise God! That’s the way for me.’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0103', 103, 'I met You at the cross', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus, my Lord and King,
Saviour of all,
Jesus the King of kings,
You heard my call –
that I would follow You all of my days,
and that for evermore Your name I’d praise.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0103', 'Eric A Thorn');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0103', 'Roger Jones');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0103', 'verse', 3, 0, '[\"Jesus, my Lord and King,\",\"Saviour of all,\",\"Jesus the King of kings,\",\"You heard my call –\",\"that I would follow You all of my days,\",\"and that for evermore Your name I’d praise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0104', 104, 'I’m feeding on the living bread', 'JP', 'en', 'control            ? 1986 in this version Horrobin/Leavers', '', 0, 0, 0, 1, 1, 'I’m feeding on the living bread,
I’m drinking at the fountain head;
for all who drink, so Jesus said,
will never, never thirst again.
What, never thirst again?
No! never thirst again.
What, never thirst again?
No! never thirst again.
For all who drink, so Jesus said,
will never, never thirst again.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0104', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0104', 'Anon');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0104', 'verse', 1, 0, '[\"I’m feeding on the living bread,\",\"I’m drinking at the fountain head;\",\"for all who drink, so Jesus said,\",\"will never, never thirst again.\",\"What, never thirst again?\",\"No! never thirst again.\",\"What, never thirst again?\",\"No! never thirst again.\",\"For all who drink, so Jesus said,\",\"will never, never thirst again.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0105', 105, 'I’m singing for my Lord', 'JP', 'en', '1952 Zondervan Corporation / Fine Balance Music, administered by CopyCare Ltd, PO Box 77, Hailsham, East Sussex BN27 3EF, UK. Used by permission', '', 0, 0, 0, 1, 1, 'I’m singing for my Lord everywhere I go,
singing of His wondrous love, that the world may know
how He saved a wretch like me by His death on Calvary:
I’m singing for my Lord everywhere I go.
I’m singing, but sometimes heavy is the rod,
for this world is not a friend to the grace of God.
Yet I sing the whole day long, for He fills my heart with song,
I’m singing for my Lord everywhere I go.
I’m singing for the lost just because I know
Jesus Christ, whose precious blood washes white as snow.
If my songs to Him can bring some lost soul I’ll gladly sing:
I’m singing for my Lord everywhere I go.
I’m singing for the saints as they journey home;
soon they’ll reach that happy land where they’ll never roam.
And with me they’ll join and sing praises to our Lord and King:
I’m singing for my Lord everywhere I go.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0105', 'Oswald J Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0105', 'Redd Harper');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0105', 'verse', 1, 0, '[\"I’m singing for my Lord everywhere I go,\",\"singing of His wondrous love, that the world may know\",\"how He saved a wretch like me by His death on Calvary:\",\"I’m singing for my Lord everywhere I go.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0105', 'verse', 2, 1, '[\"I’m singing, but sometimes heavy is the rod,\",\"for this world is not a friend to the grace of God.\",\"Yet I sing the whole day long, for He fills my heart with song,\",\"I’m singing for my Lord everywhere I go.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0105', 'verse', 3, 2, '[\"I’m singing for the lost just because I know\",\"Jesus Christ, whose precious blood washes white as snow.\",\"If my songs to Him can bring some lost soul I’ll gladly sing:\",\"I’m singing for my Lord everywhere I go.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0105', 'verse', 4, 3, '[\"I’m singing for the saints as they journey home;\",\"soon they’ll reach that happy land where they’ll never roam.\",\"And with me they’ll join and sing praises to our Lord and King:\",\"I’m singing for my Lord everywhere I go.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0106', 106, 'I’m special', 'JP', 'en', '1986 Kingsway\'s Thankyou Music, PO Box 75, Eastbourne, East Sussex BN23 6NW, UK. Used by permission', '', 0, 0, 0, 1, 0, 'I’m special because God has loved me,
for He gave the best thing that He had to save me:
His own Son Jesus, crucified to take the blame,
for all the bad things I have done.
Thank You, Jesus, thank You, Lord,
for loving me so much;
I know I don’t deserve anything,
help me feel Your love right now,
to know deep in my heart that I’m Your special friend.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0106', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0106', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0106', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0106', 'verse', 1, 0, '[\"I’m special because God has loved me,\",\"for He gave the best thing that He had to save me:\",\"His own Son Jesus, crucified to take the blame,\",\"for all the bad things I have done.\",\"Thank You, Jesus, thank You, Lord,\",\"for loving me so much;\",\"I know I don’t deserve anything,\",\"help me feel Your love right now,\",\"to know deep in my heart that I’m Your special friend.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0107', 107, 'I’m very glad of God', 'JP', 'en', 'D M Gill. Used by permission', '', 0, 0, 0, 1, 1, 'I’m very glad of God:
His love takes care of me.
In every lovely thing I see
God smiles at me.
I’m very glad of God:
His love takes care of me.
In every lovely sound I hear
God speaks to me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0107', 'Alice M Pullen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0107', 'Alice M Pullen');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0107', 'verse', 1, 0, '[\"I’m very glad of God:\",\"His love takes care of me.\",\"In every lovely thing I see\",\"God smiles at me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0107', 'verse', 2, 1, '[\"I’m very glad of God:\",\"His love takes care of me.\",\"In every lovely sound I hear\",\"God speaks to me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0108', 108, 'In our work and in our play', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Children of the King are we,
may we loyal to Him be:
try to please Him every day,
in our work and in our play.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0108', 'W G Wills');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0108', 'Benjamin Milgrove');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0108', 'verse', 4, 0, '[\"Children of the King are we,\",\"may we loyal to Him be:\",\"try to please Him every day,\",\"in our work and in our play.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0109', 109, 'In my need Jesus found me', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Gracious shepherd that sought me,
precious life-blood that bought me;
out of the night,
into the light and near to God.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0109', 'Gordon Brattle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0109', 'Gordon Brattle');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0109', 'verse', 1, 0, '[\"Gracious shepherd that sought me,\",\"precious life-blood that bought me;\",\"out of the night,\",\"into the light and near to God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0110', 110, 'Infant holy', 'JP', 'en', 'control            arrangement:', '', 0, 0, 0, 1, 1, 'Flocks were sleeping, shepherds keeping
vigil till the morning new,
saw the glory, heard the story –
tidings of a gospel true.
Thus rejoicing, free from sorrow,
praises voicing, greet the morrow:
Christ the babe was born for you;
Christ the babe was born for you!
Words tr. by E M G Reed');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0110', 'A E Rusbridge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0110', 'verse', 2, 0, '[\"Flocks were sleeping, shepherds keeping\",\"vigil till the morning new,\",\"saw the glory, heard the story –\",\"tidings of a gospel true.\",\"Thus rejoicing, free from sorrow,\",\"praises voicing, greet the morrow:\",\"Christ the babe was born for you;\",\"Christ the babe was born for you!\",\"Words tr. by E M G Reed\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0111', 111, 'In the name of Jesus', 'JP', 'en', 'control            arrangement:', '', 0, 0, 0, 1, 1, 'In the name of Jesus,
in the name of Jesus,
we have the victory.
In the name of Jesus,
in the name of Jesus,
demons will have to flee.
Who can tell what God can do?
Who can tell of His love for you?
In the name of Jesus, Jesus,
we have the victory.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0111', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0111', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0111', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0111', 'verse', 1, 0, '[\"In the name of Jesus,\",\"in the name of Jesus,\",\"we have the victory.\",\"In the name of Jesus,\",\"in the name of Jesus,\",\"demons will have to flee.\",\"Who can tell what God can do?\",\"Who can tell of His love for you?\",\"In the name of Jesus, Jesus,\",\"we have the victory.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0112', 112, 'In the stars His handiwork I see', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Then by faith I met Him face to face,
and I felt the wonder of His grace.
Then I knew that He was more than just a god
who didn’t care, who lived away up there.
And now He lives within me day by day,
ever watching o’er me lest I stray,
helping me to find the narrow way.
He’s everything to me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0112', 'Ralph Carmichael');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0112', 'Ralph Carmichael');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0112', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0112', 'verse', 1, 0, '[\"Then by faith I met Him face to face,\",\"and I felt the wonder of His grace.\",\"Then I knew that He was more than just a god\",\"who didn’t care, who lived away up there.\",\"And now He lives within me day by day,\",\"ever watching o’er me lest I stray,\",\"helping me to find the narrow way.\",\"He’s everything to me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0113', 113, 'I serve a risen Saviour', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Rejoice, rejoice, O Christian,
lift up your voice and sing
eternal hallelujahs
to Jesus Christ the King!
The hope of all who seek Him,
the help of all who find,
none other is so loving,
so good and kind.
He lives...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0113', 'Alfred Henry Ackley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0113', 'Alfred Henry Ackley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0113', 'verse', 3, 0, '[\"Rejoice, rejoice, O Christian,\",\"lift up your voice and sing\",\"eternal hallelujahs\",\"to Jesus Christ the King!\",\"The hope of all who seek Him,\",\"the help of all who find,\",\"none other is so loving,\",\"so good and kind.\",\"He lives...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0114', 114, 'Isaiah heard the voice of the Lord', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'Isaiah heard the voice of the Lord
and he said, ‘Here am I, send me!’
He loved to do the will of the Lord,
so he said, ‘Here am I, send me;
here am I, send me anywhere for Thee.’
So when I hear the voice of the Lord
I will say, ‘Here am I, send me!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0114', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0114', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0114', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0114', 'verse', 1, 0, '[\"Isaiah heard the voice of the Lord\",\"and he said, ‘Here am I, send me!’\",\"He loved to do the will of the Lord,\",\"so he said, ‘Here am I, send me;\",\"here am I, send me anywhere for Thee.’\",\"So when I hear the voice of the Lord\",\"I will say, ‘Here am I, send me!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0115', 115, 'I sing a song of the saints of God', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, 'They lived not only in ages past,
there are hundreds of thousands still;
the world is bright with the joyous saints
who love to do Jesus’ will.
You can meet them in school, or in lanes, or at sea,
in church, or in trains, or in shops, or at tea,
for the saints of God began just like me,
and I mean to be one too.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0115', 'L Scott');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0115', 'John Henry Hopkins');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0115', 'verse', 3, 0, '[\"They lived not only in ages past,\",\"there are hundreds of thousands still;\",\"the world is bright with the joyous saints\",\"who love to do Jesus’ will.\",\"You can meet them in school, or in lanes, or at sea,\",\"in church, or in trains, or in shops, or at tea,\",\"for the saints of God began just like me,\",\"and I mean to be one too.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0116', 116, 'It came upon the midnight clear', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'And still the days are hastening on –
by prophets seen of old –
towards the fulness of the time
when comes the age foretold:
then earth and heaven renewed shall see
the Prince of peace, their King;
and all the world repeat the song
which now the angels sing.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0116', 'Edward Hamilton Sears');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0116', 'Arthur Seymour Sullivan');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0116', 'verse', 4, 0, '[\"And still the days are hastening on –\",\"by prophets seen of old –\",\"towards the fulness of the time\",\"when comes the age foretold:\",\"then earth and heaven renewed shall see\",\"the Prince of peace, their King;\",\"and all the world repeat the song\",\"which now the angels sing.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0117', 117, 'It is a thing most wonderful', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'And yet I want to love You, Lord;
O teach me how to grow in grace,
that I may love You more and more,
until I see You face to face.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0117', 'William Walsham How');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0117', 'Thomas Bishop Southgate');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0117', 'verse', 7, 0, '[\"And yet I want to love You, Lord;\",\"O teach me how to grow in grace,\",\"that I may love You more and more,\",\"until I see You face to face.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0118', 118, 'It’s a happy day', 'JP', 'en', '1973 Fred Bock Music Company, administered in Europe (excl Germany) and British Commonwealth (excl Canada) by Kingsway\'s Thankyou Music, PO Box 75, Eastbourne, East Sussex BN23 6NW, UK. Used by permission', '', 0, 0, 0, 1, 0, 'It’s a happy day and I praise God for the weather.
It’s a happy day, living it for my Lord.
It’s a happy day, things are going to get better,
living each day by the promises in God’s word.
It’s a grumpy day and I can’t stand the weather.
It’s a grumpy day, living it for myself.
It’s a grumpy day and things aren’t going to get better,
living each day with my Bible up on my shelf.
It’s a happy day and I praise God for the weather.
It’s a happy day, living it for my Lord.
It’s a happy day, things are going to get better,
living each day by the promises in God’s word.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0118', 'Gary Pfeiffer');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0118', 'Gary Pfeiffer');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0118', 'verse', 1, 0, '[\"It’s a happy day and I praise God for the weather.\",\"It’s a happy day, living it for my Lord.\",\"It’s a happy day, things are going to get better,\",\"living each day by the promises in God’s word.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0118', 'verse', 2, 1, '[\"It’s a grumpy day and I can’t stand the weather.\",\"It’s a grumpy day, living it for myself.\",\"It’s a grumpy day and things aren’t going to get better,\",\"living each day with my Bible up on my shelf.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0118', 'verse', 3, 2, '[\"It’s a happy day and I praise God for the weather.\",\"It’s a happy day, living it for my Lord.\",\"It’s a happy day, things are going to get better,\",\"living each day by the promises in God’s word.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0119', 119, 'It’s me, it’s me', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'It’s me, it’s me, it’s me, O Lord,
standin’ in the need of prayer.
It’s me, it’s me, it’s me, O Lord,
standin’ in the need of prayer.
Not my brother or my sister, but it’s me, O Lord,
standin’ in the need of prayer.
Not my brother or my sister, but it’s me, O Lord,
standin’ in the need of prayer.
It’s me, it’s me...
Not my mother or my father, but it’s me, O Lord,
standin’ in the need of prayer.
Not my mother or my father, but it’s me, O Lord,
standin’ in the need of prayer.
It’s me, it’s me...
Not my stranger or my neighbour, but it’s me, O Lord,
standin’ in the need of prayer.
Not my stranger or my neighbour, but it’s me, O Lord,
standin’ in the need of prayer.
It’s me, it’s me...
arrangement: ? A & C Black Publishers Ltd. From Alleluya.  Used by permission');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0119', 'chorus', 0, 0, '[\"It’s me, it’s me, it’s me, O Lord,\",\"standin’ in the need of prayer.\",\"It’s me, it’s me, it’s me, O Lord,\",\"standin’ in the need of prayer.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0119', 'verse', 1, 1, '[\"Not my brother or my sister, but it’s me, O Lord,\",\"standin’ in the need of prayer.\",\"Not my brother or my sister, but it’s me, O Lord,\",\"standin’ in the need of prayer.\",\"It’s me, it’s me...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0119', 'verse', 2, 2, '[\"Not my mother or my father, but it’s me, O Lord,\",\"standin’ in the need of prayer.\",\"Not my mother or my father, but it’s me, O Lord,\",\"standin’ in the need of prayer.\",\"It’s me, it’s me...\"]');
