INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0120', 120, 'I’ve got peace like a river', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I’ve got peace like a river, peace like a river,
I’ve got peace like a river in my soul;
I’ve got peace like a river, peace like a river,
I’ve got peace like a river in my soul.');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0120', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0120', 'verse', 1, 0, '[\"I’ve got peace like a river, peace like a river,\",\"I’ve got peace like a river in my soul;\",\"I’ve got peace like a river, peace like a river,\",\"I’ve got peace like a river in my soul.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0121', 121, 'I’ve got that joy, joy, joy, joy', 'JP', 'en', 'control                        arrangement: ? 1986 Phil Burt', '', 0, 0, 0, 1, 1, 'I’ve got that joy, joy, joy, joy
down in my heart, (where?)
down in my heart, (where?)
down in my heart.
I’ve got that joy, joy, joy, joy
down in my heart, (where?)
down in my heart to stay.
And I’m so happy,
so very happy,
I’ve got the love of Jesus in my heart,
and I’m so happy,
so very happy,
I’ve got the love of Jesus in my heart.
I’ve got the peace that passes understanding
down in my heart, (where?)
down in my heart, (where?)
down in my heart.
I’ve got the peace that passes understanding
down in my heart, (where?)
down in my heart to stay.
And I’m so happy...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0121', 'G W Cooke');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0121', 'G W Cooke');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0121', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0121', 'verse', 1, 0, '[\"I’ve got that joy, joy, joy, joy\",\"down in my heart, (where?)\",\"down in my heart, (where?)\",\"down in my heart.\",\"I’ve got that joy, joy, joy, joy\",\"down in my heart, (where?)\",\"down in my heart to stay.\",\"And I’m so happy,\",\"so very happy,\",\"I’ve got the love of Jesus in my heart,\",\"and I’m so happy,\",\"so very happy,\",\"I’ve got the love of Jesus in my heart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0121', 'verse', 2, 1, '[\"I’ve got the peace that passes understanding\",\"down in my heart, (where?)\",\"down in my heart, (where?)\",\"down in my heart.\",\"I’ve got the peace that passes understanding\",\"down in my heart, (where?)\",\"down in my heart to stay.\",\"And I’m so happy...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0122', 122, 'I want to live for Jesus every day', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'I’m gonna live for Jesus every day (every day).
I’m gonna live for Jesus, come what may (come what may).
Take the world and all its pleasure,
I’ve got a more enduring treasure.
I’m gonna live for Jesus every day.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0122', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0122', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0122', 'Jeanne Harper');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0122', 'verse', 2, 0, '[\"I’m gonna live for Jesus every day (every day).\",\"I’m gonna live for Jesus, come what may (come what may).\",\"Take the world and all its pleasure,\",\"I’ve got a more enduring treasure.\",\"I’m gonna live for Jesus every day.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0123', 123, 'I will make you fishers of men', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I will make you fishers of men,
fishers of men, fishers of men,
I will make you fishers of men
if you follow Me.
If you follow Me, if you follow Me,
I will make you fishers of men
if you follow Me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0123', 'Harry D Clarke');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0123', 'Harry D Clarke');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0123', 'verse', 1, 0, '[\"I will make you fishers of men,\",\"fishers of men, fishers of men,\",\"I will make you fishers of men\",\"if you follow Me.\",\"If you follow Me, if you follow Me,\",\"I will make you fishers of men\",\"if you follow Me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0124', 124, 'I want to walk with Jesus', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'O Holy Spirit of the Lord,
enter now into this heart of mine;
take full control of my selfish will
and make me wholly Thine!
Follow Him, follow Him...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0124', 'C Simmonds');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0124', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0124', 'verse', 5, 0, '[\"O Holy Spirit of the Lord,\",\"enter now into this heart of mine;\",\"take full control of my selfish will\",\"and make me wholly Thine!\",\"Follow Him, follow Him...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0125', 125, 'I was lost but Jesus found me', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'Glory, glory, alleluia,
come and bless the Lord our King.
Glory, glory, alleluia,
with His praise all heaven rings.
Alleluia...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0125', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0125', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0125', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0125', 'verse', 2, 0, '[\"Glory, glory, alleluia,\",\"come and bless the Lord our King.\",\"Glory, glory, alleluia,\",\"with His praise all heaven rings.\",\"Alleluia...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0126', 126, 'I will sing, I will sing', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'In His name, in His name we have the victory. (3 times)
Alleluia, glory to the Lord.
Allelu, alleluia...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0126', 'Max Dyer');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0126', 'Max Dyer');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0126', 'verse', 6, 0, '[\"In His name, in His name we have the victory. (3 times)\",\"Alleluia, glory to the Lord.\",\"Allelu, alleluia...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0127', 127, 'I will sing the wondrous story', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'He will keep me till the river
rolls its waters at my feet:
then He’ll bear me safely over,
made by grace for glory meet.
Yes, I’ll sing the wondrous story
of the Christ who died for me –
sing it with His saints in glory,
gathered by the crystal sea.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0127', 'Francis Harold Rawley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0127', 'Rowland Hugh Prichard');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0127', 'verse', 3, 0, '[\"He will keep me till the river\",\"rolls its waters at my feet:\",\"then He’ll bear me safely over,\",\"made by grace for glory meet.\",\"Yes, I’ll sing the wondrous story\",\"of the Christ who died for me –\",\"sing it with His saints in glory,\",\"gathered by the crystal sea.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0128', 128, 'Jesus bids us shine', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus bids us shine, then,
for all around;
many kinds of darkness
in the world are found –
sin and want and sorrow –
so we must shine,
you in your small corner
and I in mine.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0128', 'Susan Warner');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0128', 'Edwin Othello Excell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0128', 'verse', 3, 0, '[\"Jesus bids us shine, then,\",\"for all around;\",\"many kinds of darkness\",\"in the world are found –\",\"sin and want and sorrow –\",\"so we must shine,\",\"you in your small corner\",\"and I in mine.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0129', 129, 'Jesus Christ is alive today', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'Jesus Christ is alive today,
I know, I know it’s true.
Sovereign of the universe,
I give Him homage due.
Seated there at God’s right hand,
I am with Him in the promised land.
Jesus lives and reigns in me,
that’s how I know it’s true.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0129', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0129', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0129', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0129', 'verse', 1, 0, '[\"Jesus Christ is alive today,\",\"I know, I know it’s true.\",\"Sovereign of the universe,\",\"I give Him homage due.\",\"Seated there at God’s right hand,\",\"I am with Him in the promised land.\",\"Jesus lives and reigns in me,\",\"that’s how I know it’s true.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0130', 130, 'Jesus Christ is risen today', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'But the pains which He endured, hallelujah!
our salvation have procured, hallelujah!
now in heaven above He’s King, hallelujah!
Where the angels ever sing, ‘hallelujah!’');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0130', 'William Henry Monk');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0130', 'verse', 3, 0, '[\"But the pains which He endured, hallelujah!\",\"our salvation have procured, hallelujah!\",\"now in heaven above He’s King, hallelujah!\",\"Where the angels ever sing, ‘hallelujah!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0131', 131, 'Jesus Christ the Lord is born', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Death from life and life from death,
our salvation story;
let all living things give breath
to Christmas songs of glory,
to Christmas songs of glory!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0131', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0131', 'Geoffrey Shaw');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0131', 'verse', 5, 0, '[\"Death from life and life from death,\",\"our salvation story;\",\"let all living things give breath\",\"to Christmas songs of glory,\",\"to Christmas songs of glory!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0132', 132, 'Jesus died for all the children', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, 'Jesus died for all the children,
all the children of the world.
Red and yellow, black and white,
all are precious in His sight:
Jesus died for all the children of the world.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0132', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0132', 'Anon');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0132', 'verse', 1, 0, '[\"Jesus died for all the children,\",\"all the children of the world.\",\"Red and yellow, black and white,\",\"all are precious in His sight:\",\"Jesus died for all the children of the world.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0133', 133, 'Jesus, how lovely You are', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Alleluia, Jesus is the bridegroom;
alleluia, Jesus will take His bride soon.
Jesus, how lovely...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0133', 'David Bolton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0133', 'David Bolton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0133', 'verse', 4, 0, '[\"Alleluia, Jesus is the bridegroom;\",\"alleluia, Jesus will take His bride soon.\",\"Jesus, how lovely...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0134', 134, 'Jesus’ hands were kind hands', 'JP', 'en', 'Stainer & Bell Ltd. Reprinted by permission', '', 0, 0, 0, 1, 1, 'Jesus’ hands were kind hands,
doing good to all,
healing pain and sickness,
blessing children small,
washing tired feet
and saving those who fall;
Jesus’ hands were kind hands
doing good to all.
Take my hands, Lord Jesus,
let them work for You,
make them strong and gentle,
kind in all I do.
Let me watch You, Jesus,
till I’m gentle too,
till my hands are kind hands,
quick to work for You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0134', 'Margaret Cropper');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0134', 'verse', 1, 0, '[\"Jesus’ hands were kind hands,\",\"doing good to all,\",\"healing pain and sickness,\",\"blessing children small,\",\"washing tired feet\",\"and saving those who fall;\",\"Jesus’ hands were kind hands\",\"doing good to all.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0134', 'verse', 2, 1, '[\"Take my hands, Lord Jesus,\",\"let them work for You,\",\"make them strong and gentle,\",\"kind in all I do.\",\"Let me watch You, Jesus,\",\"till I’m gentle too,\",\"till my hands are kind hands,\",\"quick to work for You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0135', 135, 'Jesus is knocking', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus is knocking, patiently waiting,
outside your heart’s closed door.
Do not reject Him, simply accept Him,
now and for evermore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0135', 'Gordon Brattle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0135', 'Gordon Brattle');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0135', 'verse', 1, 0, '[\"Jesus is knocking, patiently waiting,\",\"outside your heart’s closed door.\",\"Do not reject Him, simply accept Him,\",\"now and for evermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0136', 136, 'Jesus is a friend of mine', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Jesus is the King of kings,
praise Him!
Jesus is the King of kings,
praise Him!
Praise Him! Praise Him!
Jesus is the King of kings,
praise Him!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0136', 'Paul Mazak');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0136', 'Paul Mazak');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0136', 'Judith Barnard');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0136', 'verse', 3, 0, '[\"Jesus is the King of kings,\",\"praise Him!\",\"Jesus is the King of kings,\",\"praise Him!\",\"Praise Him! Praise Him!\",\"Jesus is the King of kings,\",\"praise Him!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0137', 137, 'Jesus is Lord', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus is Lord! O’er sin the mighty conqueror,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0137', 'David J Mansell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0137', 'David J Mansell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0137', 'verse', 3, 0, '[\"Jesus is Lord! O’er sin the mighty conqueror,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0138', 138, 'Jesus, I will come with You', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus, I will come with You,
I will follow in Your way.
I will trust You,
I will bring You all I have today.
Jesus, You’re the way,
Jesus, You’re the truth,
Jesus, You’re the life,
praise Your name.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0138', 'Roger Jones');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0138', 'Roger Jones');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0138', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0138', 'verse', 1, 0, '[\"Jesus, I will come with You,\",\"I will follow in Your way.\",\"I will trust You,\",\"I will bring You all I have today.\",\"Jesus, You’re the way,\",\"Jesus, You’re the truth,\",\"Jesus, You’re the life,\",\"praise Your name.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0139', 139, 'Jesus’ love is very wonderful', 'JP', 'en', 'Scripture Union            Copyright control. arrangement: ? 1986 Phil Burt', '', 0, 0, 0, 1, 1, 'Jesus’ love is very wonderful,
Jesus’ love is very wonderful,
Jesus’ love is very wonderful,
O wonderful love!
So high you can’t get over it,
so low you can’t get under it,
so wide you can’t get round it,
O wonderful love!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0139', 'H W Rattle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0139', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0139', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0139', 'verse', 1, 0, '[\"Jesus’ love is very wonderful,\",\"Jesus’ love is very wonderful,\",\"Jesus’ love is very wonderful,\",\"O wonderful love!\",\"So high you can’t get over it,\",\"so low you can’t get under it,\",\"so wide you can’t get round it,\",\"O wonderful love!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0140', 140, 'Jesus loves me', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus loves me! He will stay
close beside me all the way;
then His little child will take
up to heaven, for His dear sake.
Yes, Jesus loves me...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0140', 'Anna Warner');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0140', 'William Batchelder Bradbury');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0140', 'verse', 3, 0, '[\"Jesus loves me! He will stay\",\"close beside me all the way;\",\"then His little child will take\",\"up to heaven, for His dear sake.\",\"Yes, Jesus loves me...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0141', 141, 'Jesus, name above all names', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus, name above all names,
beautiful Saviour, glorious Lord;
Emmanuel, God is with us,
blessèd Redeemer, living Word.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0141', 'Naida Hearn');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0141', 'Naida Hearn');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0141', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0141', 'verse', 1, 0, '[\"Jesus, name above all names,\",\"beautiful Saviour, glorious Lord;\",\"Emmanuel, God is with us,\",\"blessèd Redeemer, living Word.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0142', 142, 'Jesus said that whosoever will', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'I’m so glad that He included me,
He included me, He included me,
I’m so glad that He included me,
when Jesus said that whosoever will may come.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0142', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0142', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0142', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0142', 'verse', 2, 0, '[\"I’m so glad that He included me,\",\"He included me, He included me,\",\"I’m so glad that He included me,\",\"when Jesus said that whosoever will may come.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0143', 143, 'Joshua fit the battle of Jericho', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Then the ram-sheep’s horns began to blow,
trumpets began to sound.
Joshua commanded the children to shout
and the walls came tumbling down that morning.
Joshua fit the battle...
arrangement:');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0143', 'verse', 3, 0, '[\"Then the ram-sheep’s horns began to blow,\",\"trumpets began to sound.\",\"Joshua commanded the children to shout\",\"and the walls came tumbling down that morning.\",\"Joshua fit the battle...\",\"arrangement:\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0144', 144, 'Joy is the flag', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'Joy is the flag flown high from the castle of my heart,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0144', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0144', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0144', 'E J Hume');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0144', 'verse', 1, 0, '[\"Joy is the flag flown high from the castle of my heart,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0145', 145, 'Jubilate, everybody', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Jubilate, everybody,
serve the Lord in all your ways, and
come before His presence singing:
enter now His courts with praise.
For the Lord our God is gracious,
and His mercy everlasting.
Jubilate, jubilate,
jubilate Deo!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0145', 'Fred Dunn');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0145', 'Fred Dunn');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0145', 'verse', 1, 0, '[\"Jubilate, everybody,\",\"serve the Lord in all your ways, and\",\"come before His presence singing:\",\"enter now His courts with praise.\",\"For the Lord our God is gracious,\",\"and His mercy everlasting.\",\"Jubilate, jubilate,\",\"jubilate Deo!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0146', 146, 'Just as I am', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Just as I am, young, strong and free,
to be the best that I can be,
that others may see You in me,
Lord of my life, I come.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0146', 'Marianne Farningham');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0146', 'Joseph Barnby');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0146', 'verse', 5, 0, '[\"Just as I am, young, strong and free,\",\"to be the best that I can be,\",\"that others may see You in me,\",\"Lord of my life, I come.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0147', 147, 'Keep me shining, Lord', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, 'Keep me shining, Lord,
keep me shining, Lord,
in all I say or do,
that the world may see
Christ lives in me,
and learn to love Him too.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0147', 'Kate Barclay Wilkinson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0147', 'Kate Barclay Wilkinson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0147', 'verse', 1, 0, '[\"Keep me shining, Lord,\",\"keep me shining, Lord,\",\"in all I say or do,\",\"that the world may see\",\"Christ lives in me,\",\"and learn to love Him too.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0148', 148, 'King of kings and Lord of lords', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'King of kings and Lord of lords,
glory, hallelujah!
King of kings and Lord of lords,
glory, hallelujah!
Jesus, Prince of peace,
glory, hallelujah!
Jesus, Prince of peace,
glory, hallelujah!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0148', 'Sophie Conty');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0148', 'Naomi Batya');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0148', 'verse', 1, 0, '[\"King of kings and Lord of lords,\",\"glory, hallelujah!\",\"King of kings and Lord of lords,\",\"glory, hallelujah!\",\"Jesus, Prince of peace,\",\"glory, hallelujah!\",\"Jesus, Prince of peace,\",\"glory, hallelujah!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0149', 149, 'Kum ba yah', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Kum ba yah, my Lord, kum ba yah,
kum ba yah, my Lord, kum ba yah,
kum ba yah, my Lord, kum ba yah,
O Lord, kum ba yah.
Someone’s crying, Lord...
Someone’s singing, Lord...
Someone’s praying, Lord...
Hear our prayer, O Lord, hear our prayer.
Keep our friends, O Lord, in Your care,
keep our friends, O Lord, in Your care,
O Lord, kum ba yah.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0149', 'verse', 1, 0, '[\"Kum ba yah, my Lord, kum ba yah,\",\"kum ba yah, my Lord, kum ba yah,\",\"kum ba yah, my Lord, kum ba yah,\",\"O Lord, kum ba yah.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0149', 'verse', 2, 1, '[\"Someone’s crying, Lord...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0149', 'verse', 3, 2, '[\"Someone’s singing, Lord...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0149', 'verse', 4, 3, '[\"Someone’s praying, Lord...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0149', 'verse', 5, 4, '[\"Hear our prayer, O Lord, hear our prayer.\",\"Keep our friends, O Lord, in Your care,\",\"keep our friends, O Lord, in Your care,\",\"O Lord, kum ba yah.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0150', 150, 'Let’s talk about Jesus', 'JP', 'en', 'control                        arrangement: ? 1986 Phil Burt', '', 0, 0, 0, 1, 1, 'Let’s talk about Jesus, the King of kings is He,
the Lord of lords, supreme through all eternity,
the great I AM, the way, the truth, the life, the door.
Let’s talk about Jesus, more and more.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0150', 'H Buffum');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0150', 'H Buffum');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0150', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0150', 'verse', 1, 0, '[\"Let’s talk about Jesus, the King of kings is He,\",\"the Lord of lords, supreme through all eternity,\",\"the great I AM, the way, the truth, the life, the door.\",\"Let’s talk about Jesus, more and more.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0151', 151, 'Led like a lamb', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'At the right hand of the Father,
now seated on high,
You have begun Your eternal reign
of justice and joy.
Glory, glory, glory, glory.
You’re alive...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0151', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0151', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0151', 'verse', 3, 0, '[\"At the right hand of the Father,\",\"now seated on high,\",\"You have begun Your eternal reign\",\"of justice and joy.\",\"Glory, glory, glory, glory.\",\"You’re alive...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0152', 152, 'Let us praise God together', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Let us serve God together,
let us serve.
Let our lives show His goodness
as we work.
Christ the Lord is the world’s true light,
let us serve Him with all our might.
His name be exalted on high.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0152', 'James E Seddon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0152', 'David Wilson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0152', 'verse', 3, 0, '[\"Let us serve God together,\",\"let us serve.\",\"Let our lives show His goodness\",\"as we work.\",\"Christ the Lord is the world’s true light,\",\"let us serve Him with all our might.\",\"His name be exalted on high.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0153', 153, 'Live, live, live', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, 'Gonna shout and sing,
let the hallelujah ring.
Jesus is living in my soul.
I’m gonna shout and sing,
there’s healing in His wing.
Jesus is living in my soul.
Live, live, live...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0153', 'Marcus Uzilevsky');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0153', 'Marcus Uzilevsky');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0153', 'verse', 3, 0, '[\"Gonna shout and sing,\",\"let the hallelujah ring.\",\"Jesus is living in my soul.\",\"I’m gonna shout and sing,\",\"there’s healing in His wing.\",\"Jesus is living in my soul.\",\"Live, live, live...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0154', 154, 'Let us with a gladsome mind', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Let us then with gladsome mind,
praise the Lord for He is kind!
For His mercies...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0154', 'John Milton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0154', 'John Antes');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0154', 'John Wilkes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0154', 'verse', 4, 0, '[\"Let us then with gladsome mind,\",\"praise the Lord for He is kind!\",\"For His mercies...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0155', 155, 'Lord, dismiss us', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Thanks we give and adoration
for Your gospel’s joyful sound;
may the fruits of Your salvation
in our hearts and lives abound;
so Your presence, so Your presence
will with us be always found.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0155', 'John Fawcett');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0155', 'William Letton Viner');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0155', 'verse', 2, 0, '[\"Thanks we give and adoration\",\"for Your gospel’s joyful sound;\",\"may the fruits of Your salvation\",\"in our hearts and lives abound;\",\"so Your presence, so Your presence\",\"will with us be always found.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0156', 156, 'Lord Jesus Christ', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Lord Jesus Christ, I would come to You,
live my life for You, Son of God;
all Your commands I know are true,
Your many gifts will make me new:
into my life Your power breaks through –
living Lord!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0156', 'Patrick Appleford');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0156', 'Patrick Appleford');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0156', 'verse', 4, 0, '[\"Lord Jesus Christ, I would come to You,\",\"live my life for You, Son of God;\",\"all Your commands I know are true,\",\"Your many gifts will make me new:\",\"into my life Your power breaks through –\",\"living Lord!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0157', 157, 'Lord of all hopefulness', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Lord of all gentleness, Lord of all calm,
whose voice is contentment, whose presence is balm,
be there at our sleeping, and give us, we pray,
Your peace in our hearts, Lord, at the end of the day.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0157', 'Jan Struther');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0157', 'Martin Shaw');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0157', 'verse', 4, 0, '[\"Lord of all gentleness, Lord of all calm,\",\"whose voice is contentment, whose presence is balm,\",\"be there at our sleeping, and give us, we pray,\",\"Your peace in our hearts, Lord, at the end of the day.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0158', 158, 'Love, joy, peace and patience', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Love, joy, peace and patience, kindness,
goodness, meekness, faith, self-control.
These are the fruit of God’s Holy Spirit
and against such there is no law.
Those who belong to Christ should now live this way,
walking in the Spirit each day,
so praise Him, praise Him, give Him all the glory,
walking in the Spirit each day.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0158', 'Andy Silver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0158', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0158', 'verse', 1, 0, '[\"Love, joy, peace and patience, kindness,\",\"goodness, meekness, faith, self-control.\",\"These are the fruit of God’s Holy Spirit\",\"and against such there is no law.\",\"Those who belong to Christ should now live this way,\",\"walking in the Spirit each day,\",\"so praise Him, praise Him, give Him all the glory,\",\"walking in the Spirit each day.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0159', 159, 'Low in the grave He lay', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Death cannot keep his prey,
Jesus, my Saviour,
He tore the bars away,
Jesus, my Lord.
Up from the grave...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0159', 'Robert Lowry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0159', 'Robert Lowry');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0159', 'verse', 3, 0, '[\"Death cannot keep his prey,\",\"Jesus, my Saviour,\",\"He tore the bars away,\",\"Jesus, my Lord.\",\"Up from the grave...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0160', 160, 'Majesty', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Majesty, worship His majesty;
unto Jesus be glory, honour and praise.
Majesty, kingdom authority, flows from His throne
unto His own, His anthem raise.
So exalt, lift up on high the name of Jesus,
magnify, come, glorify Christ Jesus the King.
Majesty, worship His majesty,
Jesus who died, now glorified, King of all kings.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0160', 'Jack Hayford');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0160', 'Jack Hayford');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0160', 'verse', 1, 0, '[\"Majesty, worship His majesty;\",\"unto Jesus be glory, honour and praise.\",\"Majesty, kingdom authority, flows from His throne\",\"unto His own, His anthem raise.\",\"So exalt, lift up on high the name of Jesus,\",\"magnify, come, glorify Christ Jesus the King.\",\"Majesty, worship His majesty,\",\"Jesus who died, now glorified, King of all kings.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0161', 161, 'Make me a channel of Your peace', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Make me a channel of Your peace.
It is in pardoning that we are pardoned,
in giving to all men that we receive;
and in dying that we’re born to eternal life.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0161', 'Sebastian Temple');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0161', 'Sebastian Temple');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0161', 'Betty Pulkingham');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0161', 'verse', 3, 0, '[\"Make me a channel of Your peace.\",\"It is in pardoning that we are pardoned,\",\"in giving to all men that we receive;\",\"and in dying that we’re born to eternal life.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0162', 162, 'Make me a servant', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Make me a servant, humble and meek.
Lord, let me lift up those who are weak.
And may the prayer of my heart always be:
‘Make me a servant, make me a servant,
make me a servant today.’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0162', 'Kelly Willard');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0162', 'Kelly Willard');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0162', 'verse', 1, 0, '[\"Make me a servant, humble and meek.\",\"Lord, let me lift up those who are weak.\",\"And may the prayer of my heart always be:\",\"‘Make me a servant, make me a servant,\",\"make me a servant today.’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0163', 163, 'Make the book live to me', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Make the book live to me, O Lord,
show me Yourself within Your word,
show me myself and show me my Saviour
and make the book live to me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0163', 'R Hudson Pope');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0163', 'R Hudson Pope');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0163', 'verse', 1, 0, '[\"Make the book live to me, O Lord,\",\"show me Yourself within Your word,\",\"show me myself and show me my Saviour\",\"and make the book live to me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0164', 164, 'Mary had a little baby', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Mary had a little baby, Mary had a little baby;
here and there and everywhere the angels sang:
‘Praise the Lord!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0164', 'Andy Silver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0164', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0164', 'verse', 1, 0, '[\"Mary had a little baby, Mary had a little baby;\",\"here and there and everywhere the angels sang:\",\"‘Praise the Lord!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0165', 165, 'May the mind of Christ my Saviour', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'May I run the race before me,
strong and brave onward I go,
looking only unto Jesus,
as in Him I grow.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0165', 'Kate Barclay Wilkinson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0165', 'Arthur Cyril Barham-Gould');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0165', 'verse', 5, 0, '[\"May I run the race before me,\",\"strong and brave onward I go,\",\"looking only unto Jesus,\",\"as in Him I grow.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0166', 166, 'Morning has broken', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Mine is the sunlight!
Mine is the morning,
here in the bright light
of this fair day!
Praise with elation,
praise every morning
God’s re-creation
of the new day!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0166', 'Eleanor Farjeon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0166', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0166', 'verse', 2, 0, '[\"Mine is the sunlight!\",\"Mine is the morning,\",\"here in the bright light\",\"of this fair day!\",\"Praise with elation,\",\"praise every morning\",\"God’s re-creation\",\"of the new day!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0167', 167, 'Mister Noah built an ark', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'Mister Noah built an ark,
the people thought it such a lark.
Mister Noah pleaded so,
but into the ark they would not go.
Down came the rain in torrents (splish, splash),
down came the rain in torrents (splish, splash),
down came the rain in torrents,
and only eight were saved.
The animals went in two by two,
elephant, giraffe and kangaroo.
All were safely stowed away
on that great and awful day.
Down came the rain...
Whenever you see a rainbow,
whenever you see a rainbow,
whenever you see a rainbow,
remember God is love.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0167', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0167', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0167', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0167', 'verse', 1, 0, '[\"Mister Noah built an ark,\",\"the people thought it such a lark.\",\"Mister Noah pleaded so,\",\"but into the ark they would not go.\",\"Down came the rain in torrents (splish, splash),\",\"down came the rain in torrents (splish, splash),\",\"down came the rain in torrents,\",\"and only eight were saved.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0167', 'verse', 2, 1, '[\"The animals went in two by two,\",\"elephant, giraffe and kangaroo.\",\"All were safely stowed away\",\"on that great and awful day.\",\"Down came the rain...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0167', 'chorus', 0, 2, '[\"Whenever you see a rainbow,\",\"whenever you see a rainbow,\",\"whenever you see a rainbow,\",\"remember God is love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0168', 168, 'My faith is like a staff of oak', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'My faith is like a staff of oak,
O let me on it lean!
My faith, it is a sharpened sword,
may falsehood find it keen!
Now fill me with Your Spirit, Lord,
teach and change me through Your word,
and by Your love may I be stirred,
as all true saints have been.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0168', 'Thomas Toke Lynch');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0168', 'verse', 2, 0, '[\"My faith is like a staff of oak,\",\"O let me on it lean!\",\"My faith, it is a sharpened sword,\",\"may falsehood find it keen!\",\"Now fill me with Your Spirit, Lord,\",\"teach and change me through Your word,\",\"and by Your love may I be stirred,\",\"as all true saints have been.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0169', 169, 'My God is so big', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'My God is so big, so strong and so mighty
there’s nothing that He cannot do.
My God is so big, so strong and so mighty
there’s nothing that He cannot do.
He’s called you to live for Him every day
in all that you say and you do.
My God is so big, so strong and so mighty,
He can do all things through you.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0169', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0169', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0169', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0169', 'verse', 2, 0, '[\"My God is so big, so strong and so mighty\",\"there’s nothing that He cannot do.\",\"My God is so big, so strong and so mighty\",\"there’s nothing that He cannot do.\",\"He’s called you to live for Him every day\",\"in all that you say and you do.\",\"My God is so big, so strong and so mighty,\",\"He can do all things through you.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0170', 170, 'My Lord is higher than a mountain', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'My Lord is higher than a mountain,
He is stronger than an army,
He is wiser than any man can tell.
My Lord is faster than a rocket,
can see more than a telescope,
is bigger than the universe as well.
His love is warmer than the burning sun,
closer than the nearest friend,
more real than any truth can be.
My Lord, He knows about the past,
and He knows about the future,
and He also knows all about me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0170', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0170', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0170', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0170', 'verse', 1, 0, '[\"My Lord is higher than a mountain,\",\"He is stronger than an army,\",\"He is wiser than any man can tell.\",\"My Lord is faster than a rocket,\",\"can see more than a telescope,\",\"is bigger than the universe as well.\",\"His love is warmer than the burning sun,\",\"closer than the nearest friend,\",\"more real than any truth can be.\",\"My Lord, He knows about the past,\",\"and He knows about the future,\",\"and He also knows all about me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0171', 171, 'New every morning', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Prepare us, Lord, in Your dear love
for perfect rest with You above,
and help us, this and every day,
to grow more like You as we pray.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0171', 'John Keble');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0171', 'Samuel Webbe');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0171', 'verse', 5, 0, '[\"Prepare us, Lord, in Your dear love\",\"for perfect rest with You above,\",\"and help us, this and every day,\",\"to grow more like You as we pray.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0172', 172, 'Now be strong', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Now be strong and very courageous,
for I have commanded you.
Be not afraid,
be not dismayed;
you will have victory.
I will be with you unto the end,
captain and leader,
guide and friend.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0172', 'J H Cansdale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0172', 'J H Cansdale');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0172', 'verse', 1, 0, '[\"Now be strong and very courageous,\",\"for I have commanded you.\",\"Be not afraid,\",\"be not dismayed;\",\"you will have victory.\",\"I will be with you unto the end,\",\"captain and leader,\",\"guide and friend.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0173', 173, 'Now the day is over', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Glory to the Father,
glory to the Son,
and to the Holy Spirit,
blessing everyone.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0173', 'Sabine Baring-Gould');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0173', 'Sabine Baring-Gould');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0173', 'verse', 6, 0, '[\"Glory to the Father,\",\"glory to the Son,\",\"and to the Holy Spirit,\",\"blessing everyone.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0174', 174, 'Love is come again', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'When our hearts are wintry, grieving or in pain,
Your touch can call us back to life again.
Fields of our hearts that dead and bare have been;
Love is come again, like wheat that springeth green.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0174', 'J M C Crum');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0174', 'Martin Shaw');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0174', 'verse', 4, 0, '[\"When our hearts are wintry, grieving or in pain,\",\"Your touch can call us back to life again.\",\"Fields of our hearts that dead and bare have been;\",\"Love is come again, like wheat that springeth green.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0175', 175, 'Now thank we all our God', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'All praise and thanks to God
the Father now be given,
the Son, and Him who reigns
with Them in highest heaven;
the one eternal God,
whom earth and heaven adore;
for thus it was, is now,
and shall be evermore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0175', 'Martin Rinkart');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0175', 'Johann Crüger');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0175', 'verse', 3, 0, '[\"All praise and thanks to God\",\"the Father now be given,\",\"the Son, and Him who reigns\",\"with Them in highest heaven;\",\"the one eternal God,\",\"whom earth and heaven adore;\",\"for thus it was, is now,\",\"and shall be evermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0176', 176, 'O come, all you faithful', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Yes, Lord, we greet You,
born that happy morning,
Jesus, to You be glory given!
Word of the Father,
then in flesh appearing:
O come, let us adore Him...
Words tr. by Frederick Oakley
Words altered by Peter Horrobin
Words altered by Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0176', 'John Francis Wade');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0176', 'William Henry Monk');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0176', 'verse', 4, 0, '[\"Yes, Lord, we greet You,\",\"born that happy morning,\",\"Jesus, to You be glory given!\",\"Word of the Father,\",\"then in flesh appearing:\",\"O come, let us adore Him...\",\"Words tr. by Frederick Oakley\",\"Words altered by Peter Horrobin\",\"Words altered by Greg Leavers\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0177', 177, 'O come, O come, Emmanuel', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'O come, O come, great Lord of might,
who long ago on Sinai’s height
gave all Your tribes the ancient law
in cloud and majesty and awe.
Rejoice, rejoice...
Words tr. by John Mason Neale
Words in this version by The Jubilate Group');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0177', 'verse', 5, 0, '[\"O come, O come, great Lord of might,\",\"who long ago on Sinai’s height\",\"gave all Your tribes the ancient law\",\"in cloud and majesty and awe.\",\"Rejoice, rejoice...\",\"Words tr. by John Mason Neale\",\"Words in this version by The Jubilate Group\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0178', 178, 'O happy day', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'So God, who heard the solemn vow,
in daily prayer shall hear my voice,
till in my final breath I bow,
and bless the day that fixed my choice.
O happy day...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0178', 'Philip Doddridge');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0178', 'Ron Jones');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0178', 'verse', 4, 0, '[\"So God, who heard the solemn vow,\",\"in daily prayer shall hear my voice,\",\"till in my final breath I bow,\",\"and bless the day that fixed my choice.\",\"O happy day...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0179', 179, 'O Lord my God!', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'When Christ shall come with shout of acclamation
and take me home – what joy shall fill my heart!
Then shall I bow in humble adoration
and there proclaim, my God, how great Thou art!
Then sings my soul...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0179', 'Stuart Wesley Keene Hine');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0179', 'Stuart Wesley Keene Hine');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0179', 'verse', 4, 0, '[\"When Christ shall come with shout of acclamation\",\"and take me home – what joy shall fill my heart!\",\"Then shall I bow in humble adoration\",\"and there proclaim, my God, how great Thou art!\",\"Then sings my soul...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0180', 180, 'O! O! O! how good is the Lord', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'OTHER SUITABLE VERSES MAY BE ADDED
He gives us each other...
He gives us His body...
He gives us His freedom... etc.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0180', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0180', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0180', 'Jeanne Harper');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0180', 'chorus', 0, 0, '[\"OTHER SUITABLE VERSES MAY BE ADDED\",\"He gives us each other...\",\"He gives us His body...\",\"He gives us His freedom... etc.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0181', 181, 'O the love that drew salvation’s plan', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, 'O the love that drew salvation’s plan!
O the grace that brought it down to man!
O the mighty gulf that God did span at Calvary.
Mercy there was great and grace was free,
pardon there was multiplied to me,
there my burdened soul found liberty, at Calvary.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0181', 'William Reed Newell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0181', 'Daniel Brink Towner');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0181', 'verse', 1, 0, '[\"O the love that drew salvation’s plan!\",\"O the grace that brought it down to man!\",\"O the mighty gulf that God did span at Calvary.\",\"Mercy there was great and grace was free,\",\"pardon there was multiplied to me,\",\"there my burdened soul found liberty, at Calvary.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0182', 182, 'O little town of Bethlehem', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'O holy Child of Bethlehem,
descend to us, we pray;
cast out our sin, and enter in;
be born in us today.
We hear the Christmas angels
the great glad tidings tell;
O come to us, abide with us,
our Lord Immanuel.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0182', 'Phillips Brooks');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0182', 'verse', 4, 0, '[\"O holy Child of Bethlehem,\",\"descend to us, we pray;\",\"cast out our sin, and enter in;\",\"be born in us today.\",\"We hear the Christmas angels\",\"the great glad tidings tell;\",\"O come to us, abide with us,\",\"our Lord Immanuel.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0183', 183, 'On Calvary’s tree', 'JP', 'en', 'Kingsway Publications Ltd / Kingsway\'s Thankyou Music, PO Box 75, Eastbourne, East Sussex BN23 6NW, UK. Used by permission            arrangement: ? Norman Warren / The Jubilate Group', '', 0, 0, 0, 1, 1, 'On Calvary’s tree He died for me,
that I His love might know.
To set me free He died for me –
that’s why I love Him so.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0183', 'A W Edsor');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0183', 'A E Walton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0183', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0183', 'verse', 1, 0, '[\"On Calvary’s tree He died for me,\",\"that I His love might know.\",\"To set me free He died for me –\",\"that’s why I love Him so.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0184', 184, 'Oh, the Lord looked down', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'The ark rose up on the bosom of the deep.
After forty days Mr Noah took a peep.
He said, ‘We’re not moving, Lord, where are we at?’
The Lord said, ‘You’re sitting right on Mount Ararat.’
Noah said, ‘Lord, it’s getting nice and dry.’
The Lord said, ‘Noah, see my rainbow in the sky.
Take all your creatures and people the earth,
and be sure you’re not more trouble than you’re worth.’
Noah found grace ...
arrangement:');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0184', 'verse', 4, 0, '[\"The ark rose up on the bosom of the deep.\",\"After forty days Mr Noah took a peep.\",\"He said, ‘We’re not moving, Lord, where are we at?’\",\"The Lord said, ‘You’re sitting right on Mount Ararat.’\",\"Noah said, ‘Lord, it’s getting nice and dry.’\",\"The Lord said, ‘Noah, see my rainbow in the sky.\",\"Take all your creatures and people the earth,\",\"and be sure you’re not more trouble than you’re worth.’\",\"Noah found grace ...\",\"arrangement:\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0185', 185, 'Once in royal David’s city', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Once in royal David’s city,
stood a lowly cattle shed,
where a mother laid her baby,
in a manger for His bed.
Mary was that mother mild,
Jesus Christ her little child.
He came down to earth from heaven,
who is God and Lord of all;
and His shelter was a stable,
and His cradle was a stall:
with the poor and mean and lowly
lived on earth our Saviour holy.
And through all His wondrous childhood
He would honour and obey,
love, and watch the lowly mother,
in whose gentle arms He lay:
Christian children all should be,
kind, obedient, good as He.
For He is our childhood’s pattern:
day by day like us He grew;
He was little, weak, and helpless,
tears and smiles like us He knew;
and He feels for all our sadness,
and He shares in all our gladness.
And our eyes at last shall see Him,
through His own redeeming love;
for that child, so dear and gentle,
is our Lord in heaven above;
and He leads His children on
to the place where He is gone.
Not in that poor lowly stable,
with the oxen standing by,
we shall see Him, but in heaven,
set at God’s right hand on high;
there His children gather round,
bright like stars, with glory crowned.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0185', 'Cecil Frances Alexander');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0185', 'Henry John Gauntlett');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0185', 'verse', 1, 0, '[\"Once in royal David’s city,\",\"stood a lowly cattle shed,\",\"where a mother laid her baby,\",\"in a manger for His bed.\",\"Mary was that mother mild,\",\"Jesus Christ her little child.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0185', 'verse', 2, 1, '[\"He came down to earth from heaven,\",\"who is God and Lord of all;\",\"and His shelter was a stable,\",\"and His cradle was a stall:\",\"with the poor and mean and lowly\",\"lived on earth our Saviour holy.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0185', 'verse', 3, 2, '[\"And through all His wondrous childhood\",\"He would honour and obey,\",\"love, and watch the lowly mother,\",\"in whose gentle arms He lay:\",\"Christian children all should be,\",\"kind, obedient, good as He.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0185', 'verse', 4, 3, '[\"For He is our childhood’s pattern:\",\"day by day like us He grew;\",\"He was little, weak, and helpless,\",\"tears and smiles like us He knew;\",\"and He feels for all our sadness,\",\"and He shares in all our gladness.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0185', 'verse', 5, 4, '[\"And our eyes at last shall see Him,\",\"through His own redeeming love;\",\"for that child, so dear and gentle,\",\"is our Lord in heaven above;\",\"and He leads His children on\",\"to the place where He is gone.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0185', 'verse', 6, 5, '[\"Not in that poor lowly stable,\",\"with the oxen standing by,\",\"we shall see Him, but in heaven,\",\"set at God’s right hand on high;\",\"there His children gather round,\",\"bright like stars, with glory crowned.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0186', 186, 'On Jordan’s bank the Baptist’s cry', 'JP', 'en', '1986 in this version Horrobin/Leavers', '', 0, 0, 0, 1, 1, 'On Jordan’s bank the Baptist’s cry
announces that the Lord is nigh;
come then and listen for he brings
glad tidings from the King of kings.
Then cleansed be every heart from sin;
make straight the way for God within;
prepare we in our hearts a home,
where such a mighty guest may come.
For You are our salvation, Lord,
our refuge and our great reward;
without Your grace we waste away,
like flowers that wither and decay.
To Him who left the throne of heaven
to save mankind, all praise be given;
to God the Father, voices raise,
and Holy Spirit, let us praise.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0186', 'Charles Coffin');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0186', 'William Henry Havergal');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0186', 'verse', 1, 0, '[\"On Jordan’s bank the Baptist’s cry\",\"announces that the Lord is nigh;\",\"come then and listen for he brings\",\"glad tidings from the King of kings.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0186', 'verse', 2, 1, '[\"Then cleansed be every heart from sin;\",\"make straight the way for God within;\",\"prepare we in our hearts a home,\",\"where such a mighty guest may come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0186', 'verse', 3, 2, '[\"For You are our salvation, Lord,\",\"our refuge and our great reward;\",\"without Your grace we waste away,\",\"like flowers that wither and decay.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0186', 'verse', 4, 3, '[\"To Him who left the throne of heaven\",\"to save mankind, all praise be given;\",\"to God the Father, voices raise,\",\"and Holy Spirit, let us praise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0187', 187, 'One day when heaven', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'One day the trumpet will sound for His coming,
one day the skies with His glory will shine;
wonderful day, my beloved ones bringing;
glorious Saviour, this Jesus is mine!
Living, He loved me...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0187', 'J Wilbur Chapman');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0187', 'Charles H Marsh');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0187', 'verse', 5, 0, '[\"One day the trumpet will sound for His coming,\",\"one day the skies with His glory will shine;\",\"wonderful day, my beloved ones bringing;\",\"glorious Saviour, this Jesus is mine!\",\"Living, He loved me...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0188', 188, 'One more step along the world I go', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'You are older than the world can be.
You are younger than the life in me.
Ever old and ever new,
keep me travelling along with you.
And it’s from the old...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0188', 'Sydney Carter');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0188', 'Sydney Carter');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0188', 'Douglas Coombes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0188', 'verse', 5, 0, '[\"You are older than the world can be.\",\"You are younger than the life in me.\",\"Ever old and ever new,\",\"keep me travelling along with you.\",\"And it’s from the old...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0189', 189, 'One, two, three, Jesus loves me', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Nine, ten, it’s time to end,
but instead we’ll sing it again
LAST TIME
(there’s no time to sing it again).');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0189', 'Lisa Mazak');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0189', 'Lisa Mazak');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0189', 'verse', 3, 0, '[\"Nine, ten, it’s time to end,\",\"but instead we’ll sing it again\",\"LAST TIME\",\"(there’s no time to sing it again).\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0190', 190, 'Only a boy called David', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'Only a boy called David,
only a rippling brook;
only a boy called David,
five little stones he took.
Then one little stone went in the sling,
and the sling went round and round,
one little stone went in the sling,
and the sling went round and round.
Round and round and round and round
and round and round and round;
one little stone went up, up, up,
and the giant came tumbling down!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0190', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0190', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0190', 'J H Stringer');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0190', 'verse', 1, 0, '[\"Only a boy called David,\",\"only a rippling brook;\",\"only a boy called David,\",\"five little stones he took.\",\"Then one little stone went in the sling,\",\"and the sling went round and round,\",\"one little stone went in the sling,\",\"and the sling went round and round.\",\"Round and round and round and round\",\"and round and round and round;\",\"one little stone went up, up, up,\",\"and the giant came tumbling down!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0191', 191, 'Our eyes have seen the glory', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'His kingdom is a family
of men of every race,
they live their lives in harmony,
enabled by His grace;
they follow His example
till they see Him face to face,
all hail, ascended King!
Glory, glory...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0191', 'Roland Meredith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0191', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0191', 'verse', 4, 0, '[\"His kingdom is a family\",\"of men of every race,\",\"they live their lives in harmony,\",\"enabled by His grace;\",\"they follow His example\",\"till they see Him face to face,\",\"all hail, ascended King!\",\"Glory, glory...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0192', 192, 'Our Father who is in heaven', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Amen, amen, it shall be so,
hallowed be Your name,
amen, amen, it shall be so,
hallowed be Your name.');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0192', 'Allen Percival');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0192', 'verse', 6, 0, '[\"Amen, amen, it shall be so,\",\"hallowed be Your name,\",\"amen, amen, it shall be so,\",\"hallowed be Your name.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0193', 193, 'Our harvest day is over', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Our clothes and health come also from God’s all-gracious hand;
our happiness is something which He again has planned.
But something more important still comes to us through God’s love –
eternal life, through His dear Son; all praise to God above.
All praise to God above!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0193', 'Eric A Thorn');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0193', 'Roger Jones');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0193', 'verse', 3, 0, '[\"Our clothes and health come also from God’s all-gracious hand;\",\"our happiness is something which He again has planned.\",\"But something more important still comes to us through God’s love –\",\"eternal life, through His dear Son; all praise to God above.\",\"All praise to God above!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0194', 194, 'O sinner man', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'O sinner man, should bin a-praying,
O sinner man, should bin a-praying,
O sinner man, should bin a-praying,
all on that day.
O sinner man...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0194', 'verse', 4, 0, '[\"O sinner man, should bin a-praying,\",\"O sinner man, should bin a-praying,\",\"O sinner man, should bin a-praying,\",\"all on that day.\",\"O sinner man...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0195', 195, 'O when the saints go marching in', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'O when the saints go marching in,
O when the saints go marching in,
O Lord, I want to be among the number
when the saints go marching in!');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0195', 'David Wilson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0195', 'verse', 5, 0, '[\"O when the saints go marching in,\",\"O when the saints go marching in,\",\"O Lord, I want to be among the number\",\"when the saints go marching in!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0196', 196, 'Peace I give to you', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Joy I give to you, I give to you My joy;
joy I give to you, I give to you My joy.
Let it flow...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0196', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0196', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0196', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0196', 'verse', 4, 0, '[\"Joy I give to you, I give to you My joy;\",\"joy I give to you, I give to you My joy.\",\"Let it flow...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0197', 197, 'Peter and James and John', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'The lesson of this story is, ‘listen to the Lord’,
the lesson of this story is, ‘listen to the Lord’,
the lesson of this story is, ‘listen to the Lord’,
wherever you may be.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0197', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0197', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0197', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0197', 'verse', 6, 0, '[\"The lesson of this story is, ‘listen to the Lord’,\",\"the lesson of this story is, ‘listen to the Lord’,\",\"the lesson of this story is, ‘listen to the Lord’,\",\"wherever you may be.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0198', 198, 'Peter and John', 'JP', 'en', 'control            arrangement:', '', 0, 0, 0, 1, 0, 'He went walking and leaping and praising God,
walking and leaping and praising God.
‘In the name of Jesus Christ of Nazareth,
rise up and walk!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0198', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0198', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0198', 'Betty Pulkingham');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0198', 'verse', 3, 0, '[\"He went walking and leaping and praising God,\",\"walking and leaping and praising God.\",\"‘In the name of Jesus Christ of Nazareth,\",\"rise up and walk!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0199', 199, 'Praise God', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Praise God from whom all blessings flow;
praise Him all creatures here below,
praise Him above, you heavenly hosts;
praise Father, Son, and Holy Ghost.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0199', 'Thomas Ken');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0199', 'Jimmy Owens');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0199', 'verse', 1, 0, '[\"Praise God from whom all blessings flow;\",\"praise Him all creatures here below,\",\"praise Him above, you heavenly hosts;\",\"praise Father, Son, and Holy Ghost.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0200', 200, 'Praise Him on the trumpet', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Hallelujah, praise the Lord;
hallelujah, praise the Lord:
let everything that has breath praise the Lord!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0200', 'John Kennett');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0200', 'John Kennett');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0200', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0200', 'verse', 1, 0, '[\"Hallelujah, praise the Lord;\",\"hallelujah, praise the Lord:\",\"let everything that has breath praise the Lord!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0201', 201, 'Praise Him, praise Him, all you little children', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, 'Thank Him, thank Him, all you little children,
God is love, God is love.
Thank Him, thank Him, all you little children,
God is love, God is love.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0201', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0201', 'E Rawdon Bailey');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0201', 'verse', 3, 0, '[\"Thank Him, thank Him, all you little children,\",\"God is love, God is love.\",\"Thank Him, thank Him, all you little children,\",\"God is love, God is love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0202', 202, 'Praise Him, praise Him, praise Him in the morning', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'Serve Him...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0202', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0202', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0202', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0202', 'verse', 4, 0, '[\"Serve Him...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0203', 203, 'Praise Him, praise Him', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Praise Him, praise Him! Jesus, our blessèd Redeemer!
All in heaven, let their hosannas ring!
Jesus, Saviour, reigning for ever and ever:
crown Him, crown Him! Prophet, and Priest, and King!
Christ is coming, over the world victorious,
power and glory unto the Lord belong.
Praise Him...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0203', 'Fanny J Crosby');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0203', 'Chester G Allen');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0203', 'verse', 3, 0, '[\"Praise Him, praise Him! Jesus, our blessèd Redeemer!\",\"All in heaven, let their hosannas ring!\",\"Jesus, Saviour, reigning for ever and ever:\",\"crown Him, crown Him! Prophet, and Priest, and King!\",\"Christ is coming, over the world victorious,\",\"power and glory unto the Lord belong.\",\"Praise Him...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0204', 204, 'Praise, my soul, the King of heaven', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Angels, help us to adore Him;
you behold Him face to face;
sun and moon, bow down before Him;
dwellers all in time and space.
Praise Him! Praise Him!
Praise Him! Praise Him!
Praise with us the God of grace.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0204', 'Henry Francis Lyte');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0204', 'John Goss');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0204', 'verse', 4, 0, '[\"Angels, help us to adore Him;\",\"you behold Him face to face;\",\"sun and moon, bow down before Him;\",\"dwellers all in time and space.\",\"Praise Him! Praise Him!\",\"Praise Him! Praise Him!\",\"Praise with us the God of grace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0205', 205, 'Praise to the Lord our God', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Praise to the Lord our God, let us sing together,
lifting our hearts and our voices to sing
with joy and gladness.
Come along, along, along and sing with praise.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0205', 'Estelle White');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0205', 'Anon');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0205', 'verse', 1, 0, '[\"Praise to the Lord our God, let us sing together,\",\"lifting our hearts and our voices to sing\",\"with joy and gladness.\",\"Come along, along, along and sing with praise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0207', 207, 'Remember all the people', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'God bless the men and women
who serve Him oversea:
God raise up more to help them
to set the nations free,
till all the distant people
in every foreign place
shall understand His kingdom
and come into His grace.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0207', 'Percy Dearmer');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0207', 'verse', 3, 0, '[\"God bless the men and women\",\"who serve Him oversea:\",\"God raise up more to help them\",\"to set the nations free,\",\"till all the distant people\",\"in every foreign place\",\"shall understand His kingdom\",\"and come into His grace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0208', 208, 'Rejoice in the Lord always', 'JP', 'en', 'control            arrangement:', '', 0, 0, 0, 1, 1, 'Rejoice in the Lord always,
and again I say rejoice!
Rejoice in the Lord always,
and again I say rejoice!
Rejoice, rejoice, and again I say rejoice!
Rejoice, rejoice, and again I say rejoice!');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0208', 'Evelyn Tanner');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0208', 'verse', 1, 0, '[\"Rejoice in the Lord always,\",\"and again I say rejoice!\",\"Rejoice in the Lord always,\",\"and again I say rejoice!\",\"Rejoice, rejoice, and again I say rejoice!\",\"Rejoice, rejoice, and again I say rejoice!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0209', 209, 'Ride on, ride on', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Ride on, ride on in majesty,
in lowly pomp ride on to die:
bow Your meek head to mortal pain,
then take, O God, Your power and reign!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0209', 'Henry Hart Milman');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0209', 'William Henry Havergal');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0209', 'verse', 5, 0, '[\"Ride on, ride on in majesty,\",\"in lowly pomp ride on to die:\",\"bow Your meek head to mortal pain,\",\"then take, O God, Your power and reign!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0210', 210, 'The arky, arky song', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'The sun came out and dried up the landy, landy,
the sun came out and dried up the landy, landy.
Everything was fine and dandy, dandy,
children of the Lord.
Rise and shine...');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0210', 'E J Hume');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0210', 'verse', 5, 0, '[\"The sun came out and dried up the landy, landy,\",\"the sun came out and dried up the landy, landy.\",\"Everything was fine and dandy, dandy,\",\"children of the Lord.\",\"Rise and shine...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0211', 211, 'Said Judas to Mary', 'JP', 'en', '', '', 0, 0, 0, 1, 1, '‘My body will hang on the cross of the world
tomorrow,’ He said, ‘and today,
and Martha and Mary will find Me again
and wash all My sorrow away,’ He said,
‘and wash all my sorrow away.’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0211', 'Sydney Carter');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0211', 'Sydney Carter');
