INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0213', 213, 'See, amid the winter snow', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Holy Saviour, born on earth,
teach us by Your lowly birth;
grant that we may ever be
taught by such humility.
Hail, O ever-blessèd morn...');
