INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0215', 215, 'Seek ye first', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Ask and it shall be given unto you,
seek and ye shall find;
knock and the door shall be opened up to you.
Allelu, alleluia.
Ask and it shall...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0215', 'Karen Lafferty');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0215', 'Karen Lafferty');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0215', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0215', 'verse', 3, 0, '[\"Ask and it shall be given unto you,\",\"seek and ye shall find;\",\"knock and the door shall be opened up to you.\",\"Allelu, alleluia.\",\"Ask and it shall...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0216', 216, 'Saviour of the world', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Three days later by God’s power He rose up from the dead,
for the tomb could not hold Jesus, it was as He’d said;
victor over sin and death, He conquered Satan’s power; so let us
celebrate that Jesus is alive for evermore.
Saviour of the world...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0216', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0216', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0216', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0216', 'verse', 3, 0, '[\"Three days later by God’s power He rose up from the dead,\",\"for the tomb could not hold Jesus, it was as He’d said;\",\"victor over sin and death, He conquered Satan’s power; so let us\",\"celebrate that Jesus is alive for evermore.\",\"Saviour of the world...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0217', 217, 'Shalom, my friend', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Shalōm, my friend, shalōm, my friend,
shalōm, shalōm.
Till we meet again, till we meet again,
shalōm, shalōm.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0217', 'Michael Lehr');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0217', 'Michael Metcalf');
