INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0218', 218, 'Sing we the King', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Kingdom of Christ, for your coming we pray;
hasten, O Father, the dawn of the day
when this new song Your creation shall sing,
Satan is conquered and Jesus is King.
Come let us sing...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0218', 'Charles Silvester Horne');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0218', 'Charles Hutchinson Gabriel');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0218', 'verse', 5, 0, '[\"Kingdom of Christ, for your coming we pray;\",\"hasten, O Father, the dawn of the day\",\"when this new song Your creation shall sing,\",\"Satan is conquered and Jesus is King.\",\"Come let us sing...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0219', 219, 'Silent night', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Silent night, holy night!
Son of God, O how bright
love is smiling from Your face!
Strikes for us now the hour of grace,
Saviour, since You are born,
Saviour, since You are born.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0219', 'Joseph Mohr');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0219', 'Franz X Gruber');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0219', 'verse', 3, 0, '[\"Silent night, holy night!\",\"Son of God, O how bright\",\"love is smiling from Your face!\",\"Strikes for us now the hour of grace,\",\"Saviour, since You are born,\",\"Saviour, since You are born.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0220', 220, 'Someone’s brought a loaf of bread', 'JP', 'en', 'control            arrangement: ? 1986 Phil Burt', '', 0, 0, 0, 1, 1, 'Someone’s brought a loaf of bread,
someone’s brought a loaf of bread,
someone’s brought a loaf of bread
to put on the harvest table.
Someone’s brought a jar of jam,
someone’s brought a jar of jam,
someone’s brought a jar of jam
to put on the harvest table.
Other verses may be added
Last verse:
Thank You, Lord, for all Your gifts,
thank You, Lord, for all Your gifts,
thank You, Lord, for all Your gifts
to put on the harvest table.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0220', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0220', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0220', 'verse', 1, 0, '[\"Someone’s brought a loaf of bread,\",\"someone’s brought a loaf of bread,\",\"someone’s brought a loaf of bread\",\"to put on the harvest table.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0220', 'verse', 2, 1, '[\"Someone’s brought a jar of jam,\",\"someone’s brought a jar of jam,\",\"someone’s brought a jar of jam\",\"to put on the harvest table.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0220', 'chorus', 0, 2, '[\"Other verses may be added\",\"Last verse:\",\"Thank You, Lord, for all Your gifts,\",\"thank You, Lord, for all Your gifts,\",\"thank You, Lord, for all Your gifts\",\"to put on the harvest table.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0221', 221, 'Soon, and very soon', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Soon and very soon...
alleluia...
Alleluia, alleluia, alleluia, alleluia.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0221', 'Andrae Crouch');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0221', 'Andrae Crouch');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0221', 'verse', 4, 0, '[\"Soon and very soon...\",\"alleluia...\",\"Alleluia, alleluia, alleluia, alleluia.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0222', 222, 'Spirit of the living God', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Spirit of the living God,
fall afresh on me;
Spirit of the living God,
fall afresh on me;
break me, melt me,
mould me, fill me;
Spirit of the living God,
fall afresh on me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0222', 'Daniel Iverson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0222', 'Daniel Iverson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0222', 'W G Hathaway');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0222', 'verse', 1, 0, '[\"Spirit of the living God,\",\"fall afresh on me;\",\"Spirit of the living God,\",\"fall afresh on me;\",\"break me, melt me,\",\"mould me, fill me;\",\"Spirit of the living God,\",\"fall afresh on me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0223', 223, 'Surely goodness and mercy', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Surely goodness and mercy shall follow me
all the days, all the days of my life;
surely goodness and mercy shall follow me
all the days, all the days of my life.
And I shall dwell in the house of the Lord forever,
and I shall feast at the table spread for me.
Surely goodness and mercy shall follow me
all the days, all the days of my life.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0223', 'Alfred B Smith');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0223', 'John W Peterson');
