INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0223', 'John W Peterson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0223', 'verse', 1, 0, '[\"Surely goodness and mercy shall follow me\",\"all the days, all the days of my life;\",\"surely goodness and mercy shall follow me\",\"all the days, all the days of my life.\",\"And I shall dwell in the house of the Lord forever,\",\"and I shall feast at the table spread for me.\",\"Surely goodness and mercy shall follow me\",\"all the days, all the days of my life.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0224', 224, 'Stand up and bless the Lord', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'So, stand up and bless the Lord your God,
stand up and bless the Lord;
stand up and bless the Lord your God,
stand up.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0224', 'Andy Silver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0224', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0224', 'verse', 1, 0, '[\"So, stand up and bless the Lord your God,\",\"stand up and bless the Lord;\",\"stand up and bless the Lord your God,\",\"stand up.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0225', 225, 'Stand up, clap hands', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Stand up, clap hands, shout, ‘Thank You, Lord,
thank You for the world I’m in.’
Stand up, clap hands, shout, ‘Thank You, Lord,
for happiness and peace within.’
I look around and the sun’s in the sky,
I look around and then I think, ‘Oh, my!’
The world is such a wonderful place,
and all because of the good Lord’s grace.
Stand up, clap hands...
I look around and the creatures I see,
I look around and it amazes me
that every fox and bird and hare
must fit in a special place somewhere.
Stand up, clap hands...
I look around at all the joy I’ve had,
I look around and then it makes me glad
that I can offer thanks and praise
to Him who guides me through my days.
Stand up, clap hands...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0225', 'Roger Dyer');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0225', 'Alan Forest');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0225', 'chorus', 0, 0, '[\"Stand up, clap hands, shout, ‘Thank You, Lord,\",\"thank You for the world I’m in.’\",\"Stand up, clap hands, shout, ‘Thank You, Lord,\",\"for happiness and peace within.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0225', 'verse', 1, 1, '[\"I look around and the sun’s in the sky,\",\"I look around and then I think, ‘Oh, my!’\",\"The world is such a wonderful place,\",\"and all because of the good Lord’s grace.\",\"Stand up, clap hands...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0225', 'verse', 2, 2, '[\"I look around and the creatures I see,\",\"I look around and it amazes me\",\"that every fox and bird and hare\",\"must fit in a special place somewhere.\",\"Stand up, clap hands...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0225', 'verse', 3, 3, '[\"I look around at all the joy I’ve had,\",\"I look around and then it makes me glad\",\"that I can offer thanks and praise\",\"to Him who guides me through my days.\",\"Stand up, clap hands...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0226', 226, 'Stand up! stand up for Jesus', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Stand up! stand up for Jesus!
the fight will not be long;
this day the noise of battle,
the next the victor’s song.
To everyone who conquers
a crown of life shall be;
we with the King of glory
shall reign eternally.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0226', 'George Duffield');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0226', 'George James Webb');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0226', 'verse', 4, 0, '[\"Stand up! stand up for Jesus!\",\"the fight will not be long;\",\"this day the noise of battle,\",\"the next the victor’s song.\",\"To everyone who conquers\",\"a crown of life shall be;\",\"we with the King of glory\",\"shall reign eternally.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0227', 227, 'Tell me the old, old story', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Tell me the same old story,
when you have cause to fear
that this world’s empty glory
is costing me too dear.
Yes, and when that world’s glory
is dawning on my soul,
tell me the old, old story;
‘Christ Jesus makes you whole.’
Tell me the old...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0227', 'Arabella Catherine Hankey');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0227', 'William Howard Doane');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0227', 'verse', 4, 0, '[\"Tell me the same old story,\",\"when you have cause to fear\",\"that this world’s empty glory\",\"is costing me too dear.\",\"Yes, and when that world’s glory\",\"is dawning on my soul,\",\"tell me the old, old story;\",\"‘Christ Jesus makes you whole.’\",\"Tell me the old...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0228', 228, 'Tell me the stories of Jesus', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Gladly I’d hear of His rising
out of the grave,
living and strong and triumphant,
mighty to save:
and how He sends us
all men to bring
stories of Jesus,
Jesus, their King.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0228', 'William Henry Parker');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0228', 'Frederick A Challinor');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0228', 'verse', 6, 0, '[\"Gladly I’d hear of His rising\",\"out of the grave,\",\"living and strong and triumphant,\",\"mighty to save:\",\"and how He sends us\",\"all men to bring\",\"stories of Jesus,\",\"Jesus, their King.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0230', 230, 'Thank You', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Thank You for free and full salvation,
thank You for grace to hold it fast.
Thank You, O Lord, I want to thank You
that I’m free to thank!
Thank You, O Lord, I want to thank You
that I’m free to thank!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0230', 'M G Schneider');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0230', 'M G Schneider');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0230', 'verse', 6, 0, '[\"Thank You for free and full salvation,\",\"thank You for grace to hold it fast.\",\"Thank You, O Lord, I want to thank You\",\"that I’m free to thank!\",\"Thank You, O Lord, I want to thank You\",\"that I’m free to thank!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0231', 231, 'Thank You, thank You, Jesus', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Glory, hallelujah,
glory, hallelujah,
glory, hallelujah in my heart!
Glory, hallelujah,
O glory, hallelujah,
thank You, thank You, Jesus, in my heart.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0231', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0231', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0231', 'Betty Pulkingham');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0231', 'verse', 4, 0, '[\"Glory, hallelujah,\",\"glory, hallelujah,\",\"glory, hallelujah in my heart!\",\"Glory, hallelujah,\",\"O glory, hallelujah,\",\"thank You, thank You, Jesus, in my heart.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0232', 232, 'Thank You, Lord, for this fine day', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Thank You, Lord, for setting us free,
thank You, Lord, for setting us free,
thank You, Lord, for setting us free,
right where we are.
Alleluia...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0232', 'Diane Davis Andrew');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0232', 'Diane Davis Andrew');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0232', 'verse', 4, 0, '[\"Thank You, Lord, for setting us free,\",\"thank You, Lord, for setting us free,\",\"thank You, Lord, for setting us free,\",\"right where we are.\",\"Alleluia...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0233', 233, 'Thank You, God, for sending Jesus', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'Thank You, God, for sending Jesus;
thank You, Jesus, that You came;
Holy Spirit, won’t You tell us
more about His wondrous name?');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0233', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0233', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0233', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0233', 'verse', 1, 0, '[\"Thank You, God, for sending Jesus;\",\"thank You, Jesus, that You came;\",\"Holy Spirit, won’t You tell us\",\"more about His wondrous name?\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0234', 234, 'The best book to read', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, 'The best thing to do is to trust Him,
the best thing to do is to trust Him;
and if you on Him depend,
He will keep you to the end;
Oh, the best thing to do is to trust Him.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0234', 'P Bilhorn');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0234', 'P Bilhorn');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0234', 'verse', 3, 0, '[\"The best thing to do is to trust Him,\",\"the best thing to do is to trust Him;\",\"and if you on Him depend,\",\"He will keep you to the end;\",\"Oh, the best thing to do is to trust Him.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0235', 235, 'Thank You, Jesus', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'You’re coming back again, and we with You shall reign,
thank You, Lord, for loving me.
You’re coming back again...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0235', 'Alison Huntley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0235', 'Alison Huntley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0235', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0235', 'verse', 4, 0, '[\"You’re coming back again, and we with You shall reign,\",\"thank You, Lord, for loving me.\",\"You’re coming back again...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0236', 236, 'The day You gave us', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'So be it, Lord, Your throne shall never,
like earth’s proud empires, pass away;
Your kingdom stands, and grows for ever,
until there dawns that glorious day.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0236', 'John Ellerton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0236', 'Clement Cotterill Scholefield');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0236', 'verse', 5, 0, '[\"So be it, Lord, Your throne shall never,\",\"like earth’s proud empires, pass away;\",\"Your kingdom stands, and grows for ever,\",\"until there dawns that glorious day.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0237', 237, 'The fields are white', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'The Lord’s return may be very soon,
the time is short,
the Lord’s return may be very soon,
the time is short!
Pray to the Lord...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0237', 'Michael Baughen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0237', 'Michael Baughen');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0237', 'verse', 4, 0, '[\"The Lord’s return may be very soon,\",\"the time is short,\",\"the Lord’s return may be very soon,\",\"the time is short!\",\"Pray to the Lord...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0238', 238, 'The first nowell', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Then let us all with one accord
sing praises to our heavenly Lord;
for Christ has our salvation wrought
and with His blood mankind has bought:
Nowell, nowell...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0238', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0238', 'David Willcocks');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0238', 'verse', 4, 0, '[\"Then let us all with one accord\",\"sing praises to our heavenly Lord;\",\"for Christ has our salvation wrought\",\"and with His blood mankind has bought:\",\"Nowell, nowell...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0239', 239, 'The greatest thing', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'The greatest thing in all my life
is serving You;
the greatest thing in all my life
is serving You;
I want to serve You more;
I want to serve You more.
The greatest thing in all my life
is serving You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0239', 'Mark Pendergrass');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0239', 'Mark Pendergrass');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0239', 'verse', 3, 0, '[\"The greatest thing in all my life\",\"is serving You;\",\"the greatest thing in all my life\",\"is serving You;\",\"I want to serve You more;\",\"I want to serve You more.\",\"The greatest thing in all my life\",\"is serving You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0240', 240, 'The joy of the Lord is my strength', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'If you want joy you must jump for it,
if you want joy you must jump for it,
if you want joy you must jump for it,
the joy of the Lord is my strength.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0240', 'Alliene Vale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0240', 'Alliene Vale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0240', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0240', 'verse', 4, 0, '[\"If you want joy you must jump for it,\",\"if you want joy you must jump for it,\",\"if you want joy you must jump for it,\",\"the joy of the Lord is my strength.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0241', 241, 'The King of love', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'And so through all the length of days
Your goodness fails me never;
Good Shepherd, may I sing Your praise
within Your house for ever!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0241', 'Henry Williams Baker');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0241', 'John Bacchus Dykes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0241', 'verse', 6, 0, '[\"And so through all the length of days\",\"Your goodness fails me never;\",\"Good Shepherd, may I sing Your praise\",\"within Your house for ever!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0242', 242, 'The Lord has need of me', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'The Lord has need of me,
His soldier I will be;
He gave Himself my life to win,
and so I mean to follow Him,
and serve Him faithfully.
So although the fight be fierce and long,
I’ll carry on: He makes me strong;
and then one day His face I’ll see,
and O the joy when He says to me,
‘Well done, my brave crusader!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0242', 'Cecil John Allen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0242', 'Cecil John Allen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0242', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0242', 'verse', 1, 0, '[\"The Lord has need of me,\",\"His soldier I will be;\",\"He gave Himself my life to win,\",\"and so I mean to follow Him,\",\"and serve Him faithfully.\",\"So although the fight be fierce and long,\",\"I’ll carry on: He makes me strong;\",\"and then one day His face I’ll see,\",\"and O the joy when He says to me,\",\"‘Well done, my brave crusader!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0243', 243, 'The Lord’s my shepherd', 'JP', 'en', '1986 in this version Horrobin/Leavers', '', 0, 0, 0, 1, 1, 'The Lord’s my shepherd, I’ll not want;
He makes me down to lie
in pastures green; He’s leading me
the quiet waters by.
My soul He does restore again,
and me to walk does make
within the paths of righteousness,
e’en for His own name’s sake.
Yes, though I walk through death’s dark vale,
yet will I fear no ill;
for You are with me, and Your rod
and staff me comfort still.
My table You have furnishèd
in presence of my foes;
my head You now with oil anoint,
and my cup overflows.
Goodness and mercy all my life
shall surely follow me;
and in God’s house for evermore
my dwelling-place shall be.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0243', 'Francis Rous');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0243', 'verse', 1, 0, '[\"The Lord’s my shepherd, I’ll not want;\",\"He makes me down to lie\",\"in pastures green; He’s leading me\",\"the quiet waters by.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0243', 'verse', 2, 1, '[\"My soul He does restore again,\",\"and me to walk does make\",\"within the paths of righteousness,\",\"e’en for His own name’s sake.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0243', 'verse', 3, 2, '[\"Yes, though I walk through death’s dark vale,\",\"yet will I fear no ill;\",\"for You are with me, and Your rod\",\"and staff me comfort still.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0243', 'verse', 4, 3, '[\"My table You have furnishèd\",\"in presence of my foes;\",\"my head You now with oil anoint,\",\"and my cup overflows.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0243', 'verse', 5, 4, '[\"Goodness and mercy all my life\",\"shall surely follow me;\",\"and in God’s house for evermore\",\"my dwelling-place shall be.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0244', 244, 'The Lord is my shepherd', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'The Lord is my shepherd,
I’ll trust in Him always.
He leads me by still waters,
I’ll trust in Him always.
Always, always, I’ll trust in Him always.
Always, always, I’ll trust in Him always.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0244', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0244', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0244', 'verse', 1, 0, '[\"The Lord is my shepherd,\",\"I’ll trust in Him always.\",\"He leads me by still waters,\",\"I’ll trust in Him always.\",\"Always, always, I’ll trust in Him always.\",\"Always, always, I’ll trust in Him always.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0245', 245, 'There is a green hill', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'O dearly, dearly has He loved,
and we must love Him too,
and trust in His redeeming blood,
and try His works to do.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0245', 'Cecil Frances Alexander');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0245', 'William Horsley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0245', 'verse', 5, 0, '[\"O dearly, dearly has He loved,\",\"and we must love Him too,\",\"and trust in His redeeming blood,\",\"and try His works to do.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0246', 246, 'There are hundreds of sparrows', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'There are hundreds of children, thousands, millions,
and yet their names are written on God’s memory;
there are hundreds and thousands, millions of children,
but God knows every one and God knows me,
but God knows every one and God knows me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0246', 'John Gowans');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0246', 'John Larsson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0246', 'verse', 4, 0, '[\"There are hundreds of children, thousands, millions,\",\"and yet their names are written on God’s memory;\",\"there are hundreds and thousands, millions of children,\",\"but God knows every one and God knows me,\",\"but God knows every one and God knows me.\"]');
