INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0249', 249, 'There’s new life in Jesus', 'JP', 'en', 'control                        arrangement: ? 1986 Andy Silver', '', 0, 0, 0, 1, 1, 'There’s new life in Jesus, lift up your heart,
there’s new life in Jesus, lift up your heart.
Lift up your heart, lift up your heart,
there’s new life in Jesus, lift up your heart.
There is healing in His love, lift up your heart,
there is healing in His love, lift up your heart.
Lift up your heart...
There is joy in serving Him, lift up your heart,
there is joy in serving Him, lift up your heart.
Lift up your heart...');
