INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0310', 310, 'And we know that all things', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'And we know that all things,
all things, all things work together for good,
yes, we know that all things,
all things, all things work together for good!
To them that love the Lord,
to them that love the Lord,
to them that love the Lord,
and are called according to His purpose.
And we know that all things,
all things, all things work together for good,
yes, we know that all things,
all things, all things work together for good.
Romans eight, verse twenty-eight.');
