INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0311', 311, 'Celebrate the harvest', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'At harvest time we celebrate
God’s gifts to us of food and drink.
Let’s sing and clap to show our thanks
for all the care God takes of us.
Praise the Lord...
Praise the Lord...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0311', 'S Lesley Scarr');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0311', 'S Lesley Scarr');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0311', 'verse', 5, 0, '[\"At harvest time we celebrate\",\"God’s gifts to us of food and drink.\",\"Let’s sing and clap to show our thanks\",\"for all the care God takes of us.\",\"Praise the Lord...\",\"Praise the Lord...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0312', 312, 'Be careful, little hands', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'Be careful, little hands, what you do,
be careful, little hands, what you do.
There’s a Father up above who is looking down in love,
so be careful, little hands, what you do.');
