INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0313', 313, 'Born in the night', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Hope of the world,
Mary’s child,
You’re coming soon to reign:
King of the earth,
Mary’s child,
walk in our streets again.');
