INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0315', 'verse', 4, 1, '[\"Here are the fruits –\",\"ALL\",\"The fruits of the earth God has given us to share;\",\"red ribbon reminds us Christ died for us all;\",\"a candle for Jesus, the Light of the world;\",\"an orange as round as the world that God made;\",\"Bring your Christingle...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0316', 316, 'Can you be sure', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'You can be sure that God is near;
you can be sure He won’t let you down;
you can be sure He’ll always hear;
and that He’s given Jesus, His Son.
God has promised...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0316', 'Geoffrey Marshall-Taylor');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0316', 'Roger Hurrell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0316', 'verse', 3, 0, '[\"You can be sure that God is near;\",\"you can be sure He won’t let you down;\",\"you can be sure He’ll always hear;\",\"and that He’s given Jesus, His Son.\",\"God has promised...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0317', 317, 'Can you count the stars', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Up in outer space, planets spinning round,
millions more than we can ever see.
It’s hard to understand how God, who made it all,
still cares about someone like you and me.
I’ve got a friend...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0317', 'Paul Field');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0317', 'Paul Field');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0317', 'verse', 2, 0, '[\"Up in outer space, planets spinning round,\",\"millions more than we can ever see.\",\"It’s hard to understand how God, who made it all,\",\"still cares about someone like you and me.\",\"I’ve got a friend...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0318', 318, 'Can you imagine', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Can you imagine how it feels to have
a Friend who never slumbers, never sleeps?
Can you believe that when He comes into
your heart and says He’ll live there, it’s for keeps?
Well, this experience is not imagination;
it’s a fact, oh yes, it’s true.
And I just can’t keep it to myself;
I’ll pass it on to you,
and you, and you, and you.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0318', 'Jeanette Smart');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0318', 'Jeanette Smart');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0318', 'verse', 2, 0, '[\"Can you imagine how it feels to have\",\"a Friend who never slumbers, never sleeps?\",\"Can you believe that when He comes into\",\"your heart and says He’ll live there, it’s for keeps?\",\"Well, this experience is not imagination;\",\"it’s a fact, oh yes, it’s true.\",\"And I just can’t keep it to myself;\",\"I’ll pass it on to you,\",\"and you, and you, and you.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0319', 319, 'Christ be my leader', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Christ be my Saviour in calm as in strife;
death cannot hold me, for He is the life.
Not darkness nor doubting nor sin and its stain
can touch my salvation: with Jesus I reign.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0319', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0319', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0319', 'verse', 3, 0, '[\"Christ be my Saviour in calm as in strife;\",\"death cannot hold me, for He is the life.\",\"Not darkness nor doubting nor sin and its stain\",\"can touch my salvation: with Jesus I reign.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0320', 320, 'Children, join the celebration', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Praise Him now with songs of gladness,
sing triumphant hymns of praise:
Christ the Lord is risen as He said!
Children, join the celebration,
with the hosts of heaven say:
‘Jesus Christ, our Saviour, lives today!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0320', 'Joe E Parks');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0320', 'Joe E Parks');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0320', 'verse', 2, 0, '[\"Praise Him now with songs of gladness,\",\"sing triumphant hymns of praise:\",\"Christ the Lord is risen as He said!\",\"Children, join the celebration,\",\"with the hosts of heaven say:\",\"‘Jesus Christ, our Saviour, lives today!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0321', 321, 'Christmas is a time to love', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Christmas is a time, Christmas is a time,
Christmas is a time to love.
Christmas is a time, Christmas is a time,
Christmas is a time to love.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0321', 'Ernie Rettino');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0321', 'Debbie Rettino');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0321', 'Ernie Rettino');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0321', 'Debbie Rettino');
