INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0322', 322, 'Christmas isn’t Christmas', 'JP', 'en', '1980 Bud John Songs / Alliance Media Ltd, administered by CopyCare Ltd, PO Box 77, Hailsham, East Sussex BN27 3EF, UK. Used by permission', '', 0, 0, 0, 1, 1, 'Christmas isn’t Christmas till it happens in your heart;
somewhere deep inside you is where Christmas really starts.
So give your heart to Jesus; you’ll discover when you do
that it’s Christmas, really Christmas for you.
Jesus brings warmth like a winter fire,
a light like a candle’s glow.
He’s waiting now to come inside
as He did so long ago.
Jesus brings gifts of truth and life,
and makes them bloom and grow.
So welcome Him with a song of joy,
and when He comes, you’ll know,
that Christmas isn’t Christmas till it happens in your heart;
somewhere deep inside you is where Christmas really starts.
So give your heart to Jesus; you’ll discover when you do
that it’s Christmas, really Christmas;
Christmas, really Christmas for you.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0322', 'Jimmy Owens');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0322', 'Carol Owens');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0322', 'Jimmy Owens');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0322', 'Carol Owens');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0322', 'verse', 1, 0, '[\"Christmas isn’t Christmas till it happens in your heart;\",\"somewhere deep inside you is where Christmas really starts.\",\"So give your heart to Jesus; you’ll discover when you do\",\"that it’s Christmas, really Christmas for you.\",\"Jesus brings warmth like a winter fire,\",\"a light like a candle’s glow.\",\"He’s waiting now to come inside\",\"as He did so long ago.\",\"Jesus brings gifts of truth and life,\",\"and makes them bloom and grow.\",\"So welcome Him with a song of joy,\",\"and when He comes, you’ll know,\",\"that Christmas isn’t Christmas till it happens in your heart;\",\"somewhere deep inside you is where Christmas really starts.\",\"So give your heart to Jesus; you’ll discover when you do\",\"that it’s Christmas, really Christmas;\",\"Christmas, really Christmas for you.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0323', 323, 'Come and join the celebration', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Come and join the celebration,
it’s a very special day;
come and share our jubilation,
there’s a new King born today!
See the shepherds
hurry down to Bethlehem;
gaze in wonder
at the Son of God who lay before them.
Come and join...
Wise men journey,
led to worship by a star;
kneel in homage,
bringing precious gifts from lands afar, so
Come and join...
‘God is with us,’
round the world the message bring;
He is with us,
‘Welcome!’ all the bells on earth are pealing.
Come and join...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0323', 'Valerie Collison');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0323', 'Valerie Collison');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0323', 'chorus', 0, 0, '[\"Come and join the celebration,\",\"it’s a very special day;\",\"come and share our jubilation,\",\"there’s a new King born today!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0323', 'verse', 1, 1, '[\"See the shepherds\",\"hurry down to Bethlehem;\",\"gaze in wonder\",\"at the Son of God who lay before them.\",\"Come and join...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0323', 'verse', 2, 2, '[\"Wise men journey,\",\"led to worship by a star;\",\"kneel in homage,\",\"bringing precious gifts from lands afar, so\",\"Come and join...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0323', 'verse', 3, 3, '[\"‘God is with us,’\",\"round the world the message bring;\",\"He is with us,\",\"‘Welcome!’ all the bells on earth are pealing.\",\"Come and join...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0324', 324, 'Come, let us sing for joy', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'BOYS    Splendour and majesty,
GIRLS    splendour and majesty,
BOYS    are before Him,
GIRLS    are before Him.
BOYS    Strength and glory,
GIRLS    strength and glory,
ALL    are in His sanctuary.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0324', 'Ruth Hooke');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0324', 'Ruth Hooke');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0324', 'verse', 1, 0, '[\"BOYS    Splendour and majesty,\",\"GIRLS    splendour and majesty,\",\"BOYS    are before Him,\",\"GIRLS    are before Him.\",\"BOYS    Strength and glory,\",\"GIRLS    strength and glory,\",\"ALL    are in His sanctuary.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0325', 325, 'Come on and celebrate', 'JP', 'en', '© 1984 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Come on and celebrate!
His gift of love we will celebrate –
the Son of God, who loved us
and gave us life.
We’ll shout Your praise, O King:
You give us joy nothing else can bring;
we’ll give to You our offering
in celebration praise.
Come on and celebrate, celebrate,
celebrate and sing,
celebrate and sing to the King.
Come on and celebrate, celebrate,
celebrate and sing,
celebrate and sing to the King!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0325', 'Patricia Morgan');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0325', 'Dave Bankhead');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0325', 'Patricia Morgan');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0325', 'Dave Bankhead');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0325', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0325', 'verse', 1, 0, '[\"Come on and celebrate!\",\"His gift of love we will celebrate –\",\"the Son of God, who loved us\",\"and gave us life.\",\"We’ll shout Your praise, O King:\",\"You give us joy nothing else can bring;\",\"we’ll give to You our offering\",\"in celebration praise.\",\"Come on and celebrate, celebrate,\",\"celebrate and sing,\",\"celebrate and sing to the King.\",\"Come on and celebrate, celebrate,\",\"celebrate and sing,\",\"celebrate and sing to the King!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0326', 326, 'Counting, counting one, two, three', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'God made me very different');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0326', 'Carolyn Keats');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0326', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0326', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0326', 'verse', 2, 0, '[\"God made me very different\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0327', 327, 'Crackers and turkeys', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Christmas morning, the start of the day,
there’s presents to open and new games to play.
This is the Christmas that everyone sees,
but Christmas means more to me.
It’s somebody’s birthday...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0327', 'Ian White');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0327', 'Ian White');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0327', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0327', 'verse', 3, 0, '[\"Christmas morning, the start of the day,\",\"there’s presents to open and new games to play.\",\"This is the Christmas that everyone sees,\",\"but Christmas means more to me.\",\"It’s somebody’s birthday...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0328', 328, 'This is God’s world', 'JP', 'en', '1991 Daybreak Music Ltd', '', 0, 0, 0, 1, 1, 'Don’t know much about the ozone layer,
rain forests seem miles away.
But each of us can be a player,
fight to save the world God has made.
This is God’s world.
This is God’s world,
and you’re a member of the human race.
This is God’s world.
This is God’s world.
Let’s try to make it a better place.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0328', 'Ralph Chambers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0328', 'Paul Field');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0328', 'verse', 1, 0, '[\"Don’t know much about the ozone layer,\",\"rain forests seem miles away.\",\"But each of us can be a player,\",\"fight to save the world God has made.\",\"This is God’s world.\",\"This is God’s world,\",\"and you’re a member of the human race.\",\"This is God’s world.\",\"This is God’s world.\",\"Let’s try to make it a better place.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0329', 329, 'Did you ever talk to God above', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Find the answer in His word; it’s true.
You’ll be strong because He walks with you.
By His faithfulness He’ll change you too.
God answers prayer.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0329', 'Frances Towle Rath');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0329', 'Frances Towle Rath');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0329', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0329', 'verse', 5, 0, '[\"Find the answer in His word; it’s true.\",\"You’ll be strong because He walks with you.\",\"By His faithfulness He’ll change you too.\",\"God answers prayer.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0330', 330, 'In spirit and in truth', 'JP', 'en', '1991 Daybreak Music Ltd', '', 0, 0, 0, 1, 1, 'Even if I don’t like the way things went today,
even if I’m feeling down, I’ll praise You anyway.
If I’m feeling lonely, if I’m feeling bad,
I’ll think about the things You’ve done, and even when I’m sad:
I will worship You in spirit and in truth,
I will worship You in spirit and in truth,
I will worship You in spirit and in truth,
I will worship You in spirit and in truth.
When my life is going great, when everything is right,
help me not to forget You, Lord, or keep You out of sight.
I don’t want to leave You out, not even for a day,
I want to see Your hand at work and hear the words You say.
I will worship You...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0330', 'Sam Horner');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0330', 'Sam Horner');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0330', 'verse', 1, 0, '[\"Even if I don’t like the way things went today,\",\"even if I’m feeling down, I’ll praise You anyway.\",\"If I’m feeling lonely, if I’m feeling bad,\",\"I’ll think about the things You’ve done, and even when I’m sad:\",\"I will worship You in spirit and in truth,\",\"I will worship You in spirit and in truth,\",\"I will worship You in spirit and in truth,\",\"I will worship You in spirit and in truth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0330', 'verse', 2, 1, '[\"When my life is going great, when everything is right,\",\"help me not to forget You, Lord, or keep You out of sight.\",\"I don’t want to leave You out, not even for a day,\",\"I want to see Your hand at work and hear the words You say.\",\"I will worship You...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0331', 331, 'Every day, if you go astray', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus, Saviour, Redeemer and King,
let’s go! and live for Him.
Son of God, our helper and friend,
go! and live for Him.
Jesus, how we thank You,
Jesus, how we love You,
Jesus, help us trust You
till the day You come again.
Jesus, how we thank You,
Jesus, how we love You,
Jesus, help us trust You more.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0331', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0331', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0331', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0331', 'verse', 3, 0, '[\"Jesus, Saviour, Redeemer and King,\",\"let’s go! and live for Him.\",\"Son of God, our helper and friend,\",\"go! and live for Him.\",\"Jesus, how we thank You,\",\"Jesus, how we love You,\",\"Jesus, help us trust You\",\"till the day You come again.\",\"Jesus, how we thank You,\",\"Jesus, how we love You,\",\"Jesus, help us trust You more.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0332', 332, 'Everybody join in singing', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'In our lives God wants to live,
make His presence known.
If we’re sorry He’ll forgive,
then our hearts can be His home.
Everybody join in singing...');
