INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0333', 333, 'Everyone matters to Jesus', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Jump up if you’ve ridden a bike. (Jump)
Wave your arms if you’ve flown in a plane. (Wave)
Clap your hands if you’ve been in a car. (Clap)
Stamp your feet if you’ve been on a train. (Stamp)
Everyone in the whole wide world...');
