INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0334', 334, 'Everywhere He walks with me', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Let His peace now rule in your hearts.
Let His word be rich in you.
Sing psalms and hymns with thanks to God,
praise Him in all that you do.
Everywhere He walks with me...');
