INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0336', 336, 'Father, for our friends we pray', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Though part of their lives has gone,
