INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0337', 337, 'Father God, I wonder', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'I will sing Your praises,
