INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0338', 338, 'Father, Your word', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Father, Your word is like a light in the darkness.
Father, Your word is like a sharp, sharp sword.
Father, Your word is like a stream in the desert.
There’s nothing that compares with the wisdom of Your word.');
