INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0340', 'verse', 1, 0, '[\"For the foolishness of God is wiser than man’s wisdom,\",\"and the weakness of God is stronger than man’s strength.\",\"For the foolishness of God is wiser than man’s wisdom,\",\"and the weakness of God is stronger than man’s strength.\",\"For the foolishness of God is wiser than man’s wisdom,\",\"and the weakness of God is stronger than man’s strength.\",\"For the foolishness of God is wiser than man’s wisdom,\",\"and the weakness of God is stronger than man’s strength.\",\"God knows all about the world, the things we cannot see,\",\"the things that we don’t understand that baffle you and me.\",\"His strength is never-ending and we are weak and small.\",\"His hand supports the universe and He is in control.\",\"For the foolishness of God...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0341', 341, 'The Servant King', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'So let us learn how to serve
and in our lives enthrone Him,
each other’s needs to prefer,
for it is Christ we’re serving.
This is our God...');
