INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0344', 344, 'Girls and boys, leave your toys', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Shepherds came at the fame of Your name,
angels their guide to Bethlehem;
in that place, saw Your face filled with grace,
stood at Your door.
Alleluia...
love evermore.');
