INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0345', 345, 'Give thanks to the Lord', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'When you click your fingers
and you stamp your feet,
when you clap your hands
and you slap your knees,
Give thanks...
Give thanks to the Lord. Amen.');
