INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0346', 'verse', 2, 0, '[\"Help me, Lord, to understand\",\"that I’m a child who’s loved by You.\",\"You’ll protect me, and be with me\",\"in the things I have to do.\",\"Thank You, Lord, that I can trust You,\",\"thank You for the love You bring.\",\"Thank You that You’ll never leave me;\",\"Father God, Your praise I sing.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0347', 347, 'God in His love', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Earth is the Lord’s: it is ours to enjoy it;
ours, as His stewards, to farm and defend.');
