INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0348', 348, 'God loves you', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'We can love others like sisters and brothers,
and that’s the way it should be.
We can love others like sisters and brothers,
and that’s the way it should be.
God loves you...');
