INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0349', 349, 'God loves you so much', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'God loves you so much,
God wants you so much,
God wants to tell you so much
that He put it in a book,
put it in a book for,
put it in a book for you.');
