INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0350', 350, 'God of all mercy', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'God of all mercy,
Your forgiveness and compassion
call forth songs from within
that fill our hearts with gladness.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0350', 'Fiona Inkpen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0350', 'Fiona Inkpen');
