INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0351', 351, 'God told Joshua', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'God said on day seven,
‘Here is what you do:
march around for six times,
then do something new.
When you’re on lap seven,
Jericho look out!
All their walls will crumble when you give a great big SHOUT!!’
God told Joshua...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0351', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0351', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0351', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0351', 'verse', 2, 0, '[\"God said on day seven,\",\"‘Here is what you do:\",\"march around for six times,\",\"then do something new.\",\"When you’re on lap seven,\",\"Jericho look out!\",\"All their walls will crumble when you give a great big SHOUT!!’\",\"God told Joshua...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0352', 352, 'Yesterday, today, forever', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'God is like a Father to us all.
God will always listen when we call.
God’s the one we worship and adore.
Yesterday, today, forever
He is Lord.
Yesterday, today, forever
He is Lord.');
