INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0353', 353, 'God whose love is everywhere', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'See the sign of love appear,
flame of glory, bright and clear,
light for all the world is here;
praise the God of love!
Gloom and darkness, get you gone!
Christ the Light of life has shone;
praise the God of love!');
