INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0353', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0353', 'verse', 4, 0, '[\"See the sign of love appear,\",\"flame of glory, bright and clear,\",\"light for all the world is here;\",\"praise the God of love!\",\"Gloom and darkness, get you gone!\",\"Christ the Light of life has shone;\",\"praise the God of love!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0354', 354, 'Hosanna', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'He’s the Saviour, He’s the Saviour,
we lay our branches down.
He’s the Saviour, He’s the Saviour,
the King is coming to our town.
Hosanna, hosanna today.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0354', 'Ian White');
