INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0355', 355, 'Grace is', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Mercy is when God gives us
the things we don’t deserve.
Mercy is when God gives us
the things we don’t deserve.
He does it because He loves us.
He does it because He loves us.
Mercy is when God gives us
the things we don’t deserve.');
