INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0356', 356, 'Hang on', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'For you have received the power of God.
You have received the power of God.
You have received the power of God
now the Holy Spirit lives within you.');
