INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0357', 'verse', 2, 0, '[\"If it’s milk or meat you need,\",\"why not have a slap-up feed,\",\"and stop looking like a weed and start to grow?\",\"Take the full-of-fitness food,\",\"taste and see that God is good,\",\"come on, feed on what you should and be healthy.\",\"You and me all should be exercising regularly,\",\"standing strong, all day long, giving God the glory.\",\"Feeding on the living bread, not eating crumbs but loaves instead;\",\"standing stronger, living longer, giving God the glory.\",\"You and me all should be exercising regularly,\",\"standing strong, all day long, giving God the glory.\",\"Feeding on the living bread, not eating crumbs but loaves instead;\",\"standing stronger, living longer, giving God the,\",\"giving God the, giving God the glory.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0358', 358, 'Children of God’s family', 'JP', 'en', '1988 Kingsway\'s Thankyou Music, PO Box 75, Eastbourne, East Sussex BN23 6NW, UK. Used by permission', '', 0, 0, 0, 1, 0, 'Heavenly Father, we would sing out Your praise,
You’re everything a Father should be.
Made us Your sons and daughters,
made us Your own, children of God’s family.
We older ones say, ‘Younger ones,
we’ll love and care for you.’
We young ones say to older ones,
‘Our love respects you too.’
We love you.
Heavenly Father...
Father, as a family
we will live forever.
Your Church is made of all ages
who love to be together.
We love you.
Heavenly Father...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0358', 'Ian Smale');
