INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0358', 'verse', 1, 1, '[\"We older ones say, ‘Younger ones,\",\"we’ll love and care for you.’\",\"We young ones say to older ones,\",\"‘Our love respects you too.’\",\"We love you.\",\"Heavenly Father...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0358', 'verse', 2, 2, '[\"Father, as a family\",\"we will live forever.\",\"Your Church is made of all ages\",\"who love to be together.\",\"We love you.\",\"Heavenly Father...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0359', 359, 'That’s good', 'JP', 'en', '1988 Pilot Point Music, administered by CopyCare Ltd, PO Box 77, Hailsham, East Sussex BN27 3EF, UK. Used by permission', '', 0, 0, 0, 1, 1, 'He made the water wet,
He made the land stay dry.
He put twinkle in the stars
and blue in the sky.
And when He was sure
it worked as it should,
God looked at His world and said,
‘That’s good!’
Good, good, good! He said, ‘That’s good!’
Good, good, good! God looked at His world and said,
‘That’s good!’
He put a touch of wag
in a puppy dog’s tail,
then put a little slow
in a silly old snail.
And when He was sure
it worked as it should,
God looked at His world and said,
‘That’s good!’
Good, good, good...
That’s good, that’s good,
(shouted) that’s good!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0359', 'Dennis Allen');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0359', 'Nan Allen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0359', 'Dennis Allen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0359', 'Nan Allen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0359', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0359', 'verse', 1, 0, '[\"He made the water wet,\",\"He made the land stay dry.\",\"He put twinkle in the stars\",\"and blue in the sky.\",\"And when He was sure\",\"it worked as it should,\",\"God looked at His world and said,\",\"‘That’s good!’\",\"Good, good, good! He said, ‘That’s good!’\",\"Good, good, good! God looked at His world and said,\",\"‘That’s good!’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0359', 'verse', 2, 1, '[\"He put a touch of wag\",\"in a puppy dog’s tail,\",\"then put a little slow\",\"in a silly old snail.\",\"And when He was sure\",\"it worked as it should,\",\"God looked at His world and said,\",\"‘That’s good!’\",\"Good, good, good...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0359', 'chorus', 0, 2, '[\"That’s good, that’s good,\",\"(shouted) that’s good!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0360', 360, 'He gives me strength', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'He gives me strength, yes, He gives me strength.
I can do all things through Christ who gives me strength.
Yes, He gives me strength, He gives me strength.
I can do all things through Christ who gives me strength.');
