INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0361', 361, 'Hey, you, do you love Jesus', 'JP', 'en', 'control            arrangement:', '', 0, 0, 0, 1, 1, 'Oh, how I love Jesus.
Oh, how I love Jesus.
Oh, how I love Jesus,
because He first loved me.
Yes, I love Him, this is why I love Him.
Words and music (refrain) by Frederick Whitfield');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0361', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0361', 'verse', 1, 0, '[\"Oh, how I love Jesus.\",\"Oh, how I love Jesus.\",\"Oh, how I love Jesus,\",\"because He first loved me.\",\"Yes, I love Him, this is why I love Him.\",\"Words and music (refrain) by Frederick Whitfield\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0362', 362, 'Hey! Hey! Anybody listening', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Come on, sing out, sing out, sing out, sing out!
Tell the world about His birth now!
Sing out, sing out, sing out, sing out
loud and clear to all the earth now!
If I had a chime I’d ring it,
a finger cymbal ching it,
we’ve got this song let’s sing it,
everywhere, everywhere, everywhere, everywhere.
Hey! Hey!...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0362', 'Richard K Avery');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0362', 'Donald S Marsh');
