INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0362', 'verse', 3, 0, '[\"Come on, sing out, sing out, sing out, sing out!\",\"Tell the world about His birth now!\",\"Sing out, sing out, sing out, sing out\",\"loud and clear to all the earth now!\",\"If I had a chime I’d ring it,\",\"a finger cymbal ching it,\",\"we’ve got this song let’s sing it,\",\"everywhere, everywhere, everywhere, everywhere.\",\"Hey! Hey!...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0363', 363, 'His name was Saul', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'This brought about a change in Saul,
he’d never be the same;
not only had his life been changed
he’d got a different name.
The Lord had given to Paul the task
to go to everyone,
and tell them that the way to God
is only through His Son.
Saul, Saul...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0363', 'Andy Silver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0363', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0363', 'verse', 4, 0, '[\"This brought about a change in Saul,\",\"he’d never be the same;\",\"not only had his life been changed\",\"he’d got a different name.\",\"The Lord had given to Paul the task\",\"to go to everyone,\",\"and tell them that the way to God\",\"is only through His Son.\",\"Saul, Saul...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0364', 364, 'His ways are not our ways', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'He will always love me, He will always care.
He has promised He will help me,
I will never fear.
His ways...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0364', 'Iain Craig');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0364', 'Iain Craig');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0364', 'verse', 3, 0, '[\"He will always love me, He will always care.\",\"He has promised He will help me,\",\"I will never fear.\",\"His ways...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0365', 365, 'Hosanna, hosanna', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Glory, glory, glory to the King of kings;
glory, glory, glory to the King of kings.
Lord, we lift up Your name,
with hearts full of praise.
Be exalted, O Lord my God –
glory to the King of kings.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0365', 'Carl Tuttle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0365', 'Carl Tuttle');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0365', 'verse', 2, 0, '[\"Glory, glory, glory to the King of kings;\",\"glory, glory, glory to the King of kings.\",\"Lord, we lift up Your name,\",\"with hearts full of praise.\",\"Be exalted, O Lord my God –\",\"glory to the King of kings.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0366', 366, 'I am like a house', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I am like a house with two windows and a door,
but underneath I have two legs that reach down to the floor;
two ears to hear what’s happening and a thatched roof up above,
but right inside God’s given me a heart that’s full of love.
So jump up and turn around
and thank the Lord with joyful sound.
So jump up and turn around
and thank the Lord, and now sit down!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0366', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0366', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0366', 'Phil Burt');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0366', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0366', 'verse', 1, 0, '[\"I am like a house with two windows and a door,\",\"but underneath I have two legs that reach down to the floor;\",\"two ears to hear what’s happening and a thatched roof up above,\",\"but right inside God’s given me a heart that’s full of love.\",\"So jump up and turn around\",\"and thank the Lord with joyful sound.\",\"So jump up and turn around\",\"and thank the Lord, and now sit down!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0367', 367, 'We are the Church', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I count if I am ninety, or nine, or just a baby;
there’s one thing I am sure about and I don’t mean maybe:
I am the Church...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0367', 'Richard K Avery');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0367', 'Donald S Marsh');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0367', 'Richard K Avery');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0367', 'Donald S Marsh');
