INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0368', 368, 'I am the resurrection', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I am the resurrection and the life.
I am the resurrection and the life.
He that believes in Me though he may die
yet shall he live again.
And whoever lives and believes in Me,
and whoever lives and believes in Me,
the Bible says in John eleven twenty-five and twenty-six
that we shall never die.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0368', 'Peter Jacobs');
