INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0368', 'Hanneke Jacobs');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0368', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0368', 'verse', 1, 0, '[\"I am the resurrection and the life.\",\"I am the resurrection and the life.\",\"He that believes in Me though he may die\",\"yet shall he live again.\",\"And whoever lives and believes in Me,\",\"and whoever lives and believes in Me,\",\"the Bible says in John eleven twenty-five and twenty-six\",\"that we shall never die.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0369', 369, 'I cast all my cares upon You', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I cast all my cares upon You.
I lay all of my burdens down at Your feet.
And any time that I don’t know what to do,
I will cast all of my cares upon You.
I will cast all my cares upon You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0369', 'Kelly Willard');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0369', 'Kelly Willard');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0369', 'verse', 2, 0, '[\"I cast all my cares upon You.\",\"I lay all of my burdens down at Your feet.\",\"And any time that I don’t know what to do,\",\"I will cast all of my cares upon You.\",\"I will cast all my cares upon You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0370', 370, 'I have a friend', 'JP', 'en', '', '', 0, 0, 0, 1, 1, '‘Don’t be afraid,’ said Jesus, ‘I am with you.’
‘Don’t be afraid,’ said Jesus, ‘I am here.
Now and forever, anywhere you travel,
I shall be with you, I’ll always be near.’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0370', 'Susan Sayers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0370', 'Susan Sayers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0370', 'Gerald Fitzpatrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0370', 'verse', 3, 0, '[\"‘Don’t be afraid,’ said Jesus, ‘I am with you.’\",\"‘Don’t be afraid,’ said Jesus, ‘I am here.\",\"Now and forever, anywhere you travel,\",\"I shall be with you, I’ll always be near.’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0371', 371, 'I look out through the doorway', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I look out through the doorway,
who’s that I see before me?
My young son coming home.
I must run to meet him,
hug him when I greet him,
and say, ‘Son, welcome home.’
We will have a party
and I can’t wait to start.
He must have the very finest food,
the best robe, ring and sandals.
He was lost, but now is found.
Welcome home, son, welcome home.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0371', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0371', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0371', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0371', 'verse', 1, 0, '[\"I look out through the doorway,\",\"who’s that I see before me?\",\"My young son coming home.\",\"I must run to meet him,\",\"hug him when I greet him,\",\"and say, ‘Son, welcome home.’\",\"We will have a party\",\"and I can’t wait to start.\",\"He must have the very finest food,\",\"the best robe, ring and sandals.\",\"He was lost, but now is found.\",\"Welcome home, son, welcome home.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0372', 372, 'I love You, Lord Jesus', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I love You, Lord Jesus,
the King of all things.
You love me, Lord Jesus,
Your love never ends.
To You I am special,
Your promises are true.
You love me, Lord Jesus,
and Lord, I love You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0372', 'Paul Crouch');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0372', 'David Mudie');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0372', 'Paul Crouch');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0372', 'David Mudie');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0372', 'verse', 1, 0, '[\"I love You, Lord Jesus,\",\"the King of all things.\",\"You love me, Lord Jesus,\",\"Your love never ends.\",\"To You I am special,\",\"Your promises are true.\",\"You love me, Lord Jesus,\",\"and Lord, I love You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0373', 373, 'I am a sheep', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'I am a sheep, baa, baa,
and I like to be well fed;
but like a sheep, baa, baa,
I’m a little stupid in the head.
I go astray most every day.
Oh, what a trouble I must be!
I’m glad I’ve got the good shepherd (spoken)
looking after me, ha, ha, ha, ha, baa, baa.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0373', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0373', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0373', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0373', 'chorus', 0, 0, '[\"I am a sheep, baa, baa,\",\"and I like to be well fed;\",\"but like a sheep, baa, baa,\",\"I’m a little stupid in the head.\",\"I go astray most every day.\",\"Oh, what a trouble I must be!\",\"I’m glad I’ve got the good shepherd (spoken)\",\"looking after me, ha, ha, ha, ha, baa, baa.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0374', 374, 'This is my prayer', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I want to love You, Lord;
I want to serve You, Lord;
I want to please You, Lord;
this is my prayer.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0374', 'Doug Holck');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0374', 'Doug Holck');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0374', 'verse', 2, 0, '[\"I want to love You, Lord;\",\"I want to serve You, Lord;\",\"I want to please You, Lord;\",\"this is my prayer.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0375', 375, 'I want to tell you', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus is special (Jesus is special),
I’m special too (I’m special too).
He says He loves me (He says He loves me)
and He loves you (and He loves you).
There’s no-one...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0375', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0375', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0375', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0375', 'verse', 3, 0, '[\"Jesus is special (Jesus is special),\",\"I’m special too (I’m special too).\",\"He says He loves me (He says He loves me)\",\"and He loves you (and He loves you).\",\"There’s no-one...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0376', 376, 'I will wave my hands', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'I will wave my hands in praise and adoration;
I will wave my hands in praise and adoration;
I will wave my hands in praise and adoration,
praise and adoration to the living God.
For He’s given me hands that just love clapping –
one, two, one, two, three –
and He’s given me a voice that just loves shouting, ‘Hallelujah!’
He’s given me feet that just love dancing –
one, two, one, two, three –
and He’s put me in a being that has no trouble seeing
that whatever I am feeling
He is worthy to be praised.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0376', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0376', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0376', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0376', 'verse', 1, 0, '[\"I will wave my hands in praise and adoration;\",\"I will wave my hands in praise and adoration;\",\"I will wave my hands in praise and adoration,\",\"praise and adoration to the living God.\",\"For He’s given me hands that just love clapping –\",\"one, two, one, two, three –\",\"and He’s given me a voice that just loves shouting, ‘Hallelujah!’\",\"He’s given me feet that just love dancing –\",\"one, two, one, two, three –\",\"and He’s put me in a being that has no trouble seeing\",\"that whatever I am feeling\",\"He is worthy to be praised.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0377', 377, 'I’m a footstep follower', 'JP', 'en', '1990 Greg Leavers', '', 0, 0, 0, 1, 1, 'I’m a footstep follower
for Jesus leads the way.
He knows the life that’s best for me:
a plan for every day.
As I walk and talk with Him,
He’ll never let me stray.
I’m a footstep follower
for Jesus leads the way.');
