INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0377', 'verse', 1, 0, '[\"I’m a footstep follower\",\"for Jesus leads the way.\",\"He knows the life that’s best for me:\",\"a plan for every day.\",\"As I walk and talk with Him,\",\"He’ll never let me stray.\",\"I’m a footstep follower\",\"for Jesus leads the way.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0378', 378, 'I’m going to hide God’s word inside my heart', 'JP', 'en', '1988 Maranatha! Music, administered by CopyCare Ltd, PO Box 77, Hailsham, East Sussex BN27 3EF, UK. Used by permission', '', 0, 0, 0, 1, 1, 'I’m going to hide God’s word inside my heart
and learn each verse from memory.
I’m going to hide God’s word inside my heart
until His word is part of me.
God’s word will help me each and every day
to know what is right from what is wrong.
The more that I read it, the more I learn of Him,
and His word will make me strong.
That’s why I’m going to hide God’s word inside my heart
and learn each verse from memory.
I’m going to hide God’s word inside my heart
until His word is part of me,
until His word is part of me.');
