INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0380', 'chorus', 0, 1, '[\"I’m going to stand up, stand up and live for Jesus.\",\"Oo I, I’m going to stand up, stand up and live for Him.\",\"I’m going to give up, give up my life for Jesus.\",\"Oo I, I’m going to give up, give up my life for Him.\",\"Lord, we will live our lives for You,\",\"serve You faithfully, like You want us to.\",\"Lord, You give us the power to live for You,\",\"live for You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0380', 'chorus', 0, 2, '[\"I’m going to stand up...\",\"Let’s take a stand for Jesus,\",\"let’s live our lives for Jesus.\",\"Let’s give it all for Jesus.\",\"Stand up for Jesus! Stand up for Jesus!\",\"Stand up, stand up, stand up, stand up, stand up!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0380', 'chorus', 0, 3, '[\"I’m going to stand up...\",\"I’m going to stand up, I’m going to stand up,\",\"I’m going to stand up, I’m going to stand up.\",\"Stand up!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0381', 381, 'I’m going to take a step of faith', 'JP', 'en', '1990 Greg Leavers', '', 0, 0, 0, 1, 1, 'I’m going to take (clap clap) a step of faith,
I’m going to put my trust in the Lord.
He has the power to carry me through.
If I listen carefully, He’ll tell me what to do.
I’m going to take (clap clap) a step of faith,
and put my trust in the Lord.
I’m going to take (clap clap) a step of faith,
I’m going to put my trust in the Lord.
He made a promise He loves me so,
wherever He might lead me, He’ll never let me go.
I’m going to take (clap clap) a step of faith,
and put my trust in the Lord.');
