INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0381', 'verse', 2, 1, '[\"I’m going to take (clap clap) a step of faith,\",\"I’m going to put my trust in the Lord.\",\"He made a promise He loves me so,\",\"wherever He might lead me, He’ll never let me go.\",\"I’m going to take (clap clap) a step of faith,\",\"and put my trust in the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0382', 382, 'I’m going to set my heart', 'JP', 'en', '1992 Greg Leavers', '', 0, 0, 0, 1, 1, 'I’m going to set my heart
on the precious word of God;
I’m going to feed my heart
on His many promises.
His word helps me in trouble,
it teaches me to praise.
I don’t want to live with a hungry heart;
I’m going to feed on the word of God.');
