INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0384', 384, 'If any man come after Me', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Alleluia! Praise the Lord, worship Him in one accord.
Alleluia! He is King, Master, Lord of everything.
Jesus Christ, Lord of all, loving great and small;
He is the way, truth, and life.');
