INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0385', 385, 'If it pleases the King', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'If it pleases the King,
I want to give my love to Him.
If it honours the Lord,
I will trust in His word.
I need never fear,
for He’ll be ever near.
My love to Him I’ll sing,
if it pleases the King.');
