INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0387', 387, 'If you love Me', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'As the disciples
obeyed and brought Him fish and bread.
So Jesus blessed it and they handed it round
and five thousand men were fed.
If you love Me...');
