INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0388', 388, 'If you climb', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'If you climb (stamp stamp) to the top of a mountain,
if you swim (splish splish) in the ocean blue,
if you’re lost (sniff sniff) in the deepest forest,
Jesus will always find you.');
