INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0389', 389, 'Servant of all', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'If you want to be great in God’s kingdom,
learn to be the servant of all.
If you want to be great in God’s kingdom,
learn to be the servant of all.
