INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0390', 'chorus', 0, 0, '[\"If your empty tum is rumbling\",\"you don’t leave your baked beans (munch munch).\",\"If it’s lightning and it’s thundering\",\"you don’t stand beneath the trees.\",\"And if you climb a high steep hill\",\"you don’t refuse a Coke (pshhh).\",\"And if your best friend’s feeling ill\",\"you don’t treat it like a joke (ha ha).\",\"You don’t run across the high street\",\"if you want to grow old.\",\"You don’t look down at your feet\",\"if you want to score a goal (clap clap).\",\"So don’t forget to pray\",\"if you want to follow God today.\",\"You don’t put your Bible out of sight\",\"if you want to do what’s right.\",\"You don’t put your Bible out of sight\",\"if you want to do what’s right.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0391', 391, 'Show me', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'In everything that I do, show me what Jesus would do.
In everything that I do, show me what Jesus would do.
I will not be afraid, for I can always pray,
show me what Jesus would do.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0391', 'Ian White');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0391', 'Ian White');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0391', 'verse', 1, 0, '[\"In everything that I do, show me what Jesus would do.\",\"In everything that I do, show me what Jesus would do.\",\"I will not be afraid, for I can always pray,\",\"show me what Jesus would do.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0392', 392, 'I’m going to shine, shine, shine', 'JP', 'en', '1990 Daybreak Music Ltd', '', 0, 0, 0, 1, 1, 'I’m going to shine, shine, shine,
a light in the world I’ll be;
I want to shine, shine, shine,
let people see Jesus in me!
I want to glorify the Father
by the things I do;
be the person God has made me,
letting His love flow through!
I’m going to...
And when it’s hard and it’s not so easy
to know and do what’s right;
I’ll trust the Holy Spirit in me,
to help me win each fight!
I’m going to...
Even if I fail Him often
and my light is dim;
He has promised to forgive me,
I can come back to Him!
I’m going to...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0392', 'Alan J Price');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0392', 'Alan J Price');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0392', 'chorus', 0, 0, '[\"I’m going to shine, shine, shine,\",\"a light in the world I’ll be;\",\"I want to shine, shine, shine,\",\"let people see Jesus in me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0392', 'verse', 1, 1, '[\"I want to glorify the Father\",\"by the things I do;\",\"be the person God has made me,\",\"letting His love flow through!\",\"I’m going to...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0392', 'verse', 2, 2, '[\"And when it’s hard and it’s not so easy\",\"to know and do what’s right;\",\"I’ll trust the Holy Spirit in me,\",\"to help me win each fight!\",\"I’m going to...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0392', 'verse', 3, 3, '[\"Even if I fail Him often\",\"and my light is dim;\",\"He has promised to forgive me,\",\"I can come back to Him!\",\"I’m going to...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0393', 393, 'God is near', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Then when I turn off the light,
when I go to sleep at night,
I am always in His sight,
God is near, God is near.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0393', 'Marjorie Allen Anderson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0393', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0393', 'verse', 3, 0, '[\"Then when I turn off the light,\",\"when I go to sleep at night,\",\"I am always in His sight,\",\"God is near, God is near.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0394', 394, 'Into my heart', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Rule in my heart, rule in my heart,
O King of my heart, Lord Jesus.
Make this Your throne, rule there alone;
O King of my heart, Lord Jesus.');
