INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0394', 'Harry D Clarke');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0394', 'verse', 2, 0, '[\"Rule in my heart, rule in my heart,\",\"O King of my heart, Lord Jesus.\",\"Make this Your throne, rule there alone;\",\"O King of my heart, Lord Jesus.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0395', 395, 'It takes an almighty hand', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'And in His hands there is perfection,
that in this land we only taste;
for now we see a poor reflection,
then we shall see Him face to face.
It takes...');
