INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0395', 'Ian White');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0395', 'verse', 4, 0, '[\"And in His hands there is perfection,\",\"that in this land we only taste;\",\"for now we see a poor reflection,\",\"then we shall see Him face to face.\",\"It takes...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0396', 396, 'It was on a starry night', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'On a starry night, on a starry night.');
