INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0414', 414, 'Kids under construction', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Dear Jesus, please make us more patient and kind;
and help us to be more like You.
And make room for all other children of Yours,
for they are still growing up, too. Oh!
Kids under construction...');
