INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0415', 415, 'Creature praise', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Day creatures, night creatures,
left and right creatures,
come now and praise the Lord.
Near creatures, far creatures,
anywhere you are creatures,
come now and praise the Lord.
Sing praise...');
