INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0416', 416, 'Let’s go and tell our friends', 'JP', 'en', '1992 Greg Leavers', '', 0, 0, 0, 1, 1, 'Let’s go and tell our friends that Jesus cares;
let’s go and tell our friends that Jesus cares.
We’ve got to go out and tell how Jesus died for them;
to tell them how He loves them; (that’s right!)
to tell them He’ll forgive them; (that’s true!)
to tell them He’ll be with them; (Amen!)
to tell them that He wants to be their friend.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0416', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0416', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0416', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0416', 'chorus', 0, 0, '[\"Let’s go and tell our friends that Jesus cares;\",\"let’s go and tell our friends that Jesus cares.\",\"We’ve got to go out and tell how Jesus died for them;\",\"to tell them how He loves them; (that’s right!)\",\"to tell them He’ll forgive them; (that’s true!)\",\"to tell them He’ll be with them; (Amen!)\",\"to tell them that He wants to be their friend.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0417', 417, 'Let’s praise God together', 'JP', 'en', '1992 Daybreak Music Ltd', '', 0, 0, 0, 1, 1, 'Let’s praise God together,
let us clap and praise the Lord;
for He loves to hear us –
He is King for evermore.
Jesus, holy is Your name;
high above all others,
power and glory belong to You.
Let’s all dance together,
let us dance and praise the Lord;
for he loves to see us –
He is King for evermore.
Jesus, mighty is Your name;
high above all others,
power and glory belong to You.
Let’s praise God together,
let us clap and praise the Lord;
for He loves to hear us –
He is King for evermore.
Let’s all dance together,
let us dance and praise the Lord;
for he loves to see us –
He is King for evermore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0417', 'Alison Moon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0417', 'Alison Moon');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0417', 'chorus', 0, 0, '[\"Let’s praise God together,\",\"let us clap and praise the Lord;\",\"for He loves to hear us –\",\"He is King for evermore.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0417', 'verse', 1, 1, '[\"Jesus, holy is Your name;\",\"high above all others,\",\"power and glory belong to You.\",\"Let’s all dance together,\",\"let us dance and praise the Lord;\",\"for he loves to see us –\",\"He is King for evermore.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0417', 'verse', 2, 2, '[\"Jesus, mighty is Your name;\",\"high above all others,\",\"power and glory belong to You.\",\"Let’s praise God together,\",\"let us clap and praise the Lord;\",\"for He loves to hear us –\",\"He is King for evermore.\"]');
