INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0418', 418, 'Long ago there was born', 'JP', 'en', 'control            arrangement:', '', 0, 0, 0, 1, 1, 'Jesus came as a child from His Father in heaven,
and has shown us the way to be loving and kind.
While the stars sang above, ‘Lullaby, God is love.’
While the stars sang above, ‘Lullaby, God is love.’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0418', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0418', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0418', 'verse', 2, 0, '[\"Jesus came as a child from His Father in heaven,\",\"and has shown us the way to be loving and kind.\",\"While the stars sang above, ‘Lullaby, God is love.’\",\"While the stars sang above, ‘Lullaby, God is love.’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0419', 419, 'Long, long ago', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'God was very glad to see the different forms of life,
but the part most wonderful was Adam and his wife.
All He wanted them to do was love and serve Him through and through;
God spoke and it was done.');
