INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0420', 420, 'Lord Jesus, You are faithful', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Lord Jesus,
You are so pure,
pure and lovely,
pure and holy;
Lord Jesus.');
