INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0421', 421, 'Lord, make me a mountain', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Lord, make me a mountain, strong and tall for You;
Lord, make me a fountain of water clear and new.
Lord, make me a shepherd that I may feed Your sheep;
Lord, make me the servant of everyone I meet.');
