INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0422', 422, 'Lord, we’ve come to worship You', 'JP', 'en', '1989 Kingsway\'s Thankyou Music, PO Box 75, Eastbourne, East Sussex BN23 6NW, UK. Used by permission', '', 0, 0, 0, 1, 0, 'Lord, we’ve come to worship You;
Lord, we’ve come to praise.
Lord, we’ve come to worship You
in oh, so many ways.
Some of us shout and some of us sing,
and some of us whisper the praise we bring;
but Lord, we all are gathering
to give to You our praise.');
