INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0423', 423, 'Lord, You are brilliant', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Lord, You are brilliant, champion of champions;
to You our thanks and praise we bring.
You see everything, all that we say and do;
You’re incredible, no-one loves us like You.
Lord, You are brilliant, champion of champions;
so we proclaim You are the King.');
