INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0425', 425, 'Love, joy, peace', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'And you’ll have love, joy, peace,
patience, kindness, goodness, faith,
gentleness, and self-control;
this is the fruit of the Spirit.
Love, joy, peace,
patience, kindness, goodness, faith,
gentleness and self-control;
the fruit of the Spirit of God,
the fruit of the Spirit of God.');
