INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0426', 426, 'M-m-m-m-must I really go', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'If I really must, Lord, I’ll be o-b-bedient;
I know You’ll go with me, You’ll s-see me through.
Even when the task is hard or d-d-dangerous,
help me to t-trust in You.');
