INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0429', 429, 'Maybe you can’t draw or sing', 'JP', 'en', '1980 Lillenas Publishing Co, administered by CopyCare Ltd, PO Box 77, Hailsham, East Sussex BN27 3EF, UK. Used by permission', '', 0, 0, 0, 1, 1, 'Maybe you can’t draw or sing or be a football star;
but just remember, be yourself,
He made you like you are.
It’ll be a big thing when Jesus takes control,
even though it seems like something very slim.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0429', 'Carol Gaddy');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0429', 'Carol Gaddy');
