INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0430', 430, 'Mighty in victory', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Mighty in victory, glorious in majesty:
every eye shall see Him when He appears,
coming in the clouds with power and glory.
Hail to the King!
We must be ready, watching and praying,
serving each other, building His kingdom;
then every knee shall bow, then every tongue confess,
Jesus is Lord!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0430', 'Mavis Ford');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0430', 'Mavis Ford');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0430', 'verse', 1, 0, '[\"Mighty in victory, glorious in majesty:\",\"every eye shall see Him when He appears,\",\"coming in the clouds with power and glory.\",\"Hail to the King!\",\"We must be ready, watching and praying,\",\"serving each other, building His kingdom;\",\"then every knee shall bow, then every tongue confess,\",\"Jesus is Lord!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0431', 431, 'Mighty is our God', 'JP', 'en', '', '', 0, 0, 0, 1, 1, '');
