INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0432', 432, 'Noah was the only good man', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'God made a rainbow in the sky
of yellow, blue and red,
so no-one ever would forget
the flood and what He said.
And when we see the rainbow now
remember God’s own words:
that He would never send again
a flood upon the earth.
Noah was...');
