INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0433', 433, 'Now Saul was rejected', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'You may be dressed smartly, your face may be fair,
but God’s not concerned with your clothes or your hair;
your outward appearance is only a part –
when God looks upon you, He looks on your heart.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0433', 'Gillian E Hutchinson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0433', 'Gillian E Hutchinson');
