INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0434', 434, 'O give thanks to the Lord', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'O give thanks to the Lord,
all you His people;
O give thanks to the Lord,
for He is good.
Let us praise, let us thank,
let us celebrate and dance;
O give thanks to the Lord,
for He is good.');
