INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0434', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0434', 'verse', 1, 0, '[\"O give thanks to the Lord,\",\"all you His people;\",\"O give thanks to the Lord,\",\"for He is good.\",\"Let us praise, let us thank,\",\"let us celebrate and dance;\",\"O give thanks to the Lord,\",\"for He is good.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0435', 435, 'O Lord, You’re great', 'JP', 'en', '1985 Kingsway\'s Thankyou Music, PO Box 75, Eastbourne, East Sussex BN23 6NW, UK. Used by permission', '', 0, 0, 0, 1, 0, 'O Lord, You’re great, You are fabulous.
We love You more than any words can sing, sing, sing.
O Lord, You’re great, You are so generous;
You lavish us with gifts when we don’t deserve a thing.
Allelu, alleluia, praise You, Lord.
Alleluia, praise You, Lord, alleluia, praise You, Lord.
Allelu, alleluia, praise You, Lord.
Alleluia, praise You, Lord, alleluia, praise You, Lord.
O Lord, You’re great, You are so powerful;
You hold the mighty universe in Your hand, hand, hand.
O Lord, You’re great, You are so wonderful,
You’ve poured out Your love on this undeserving land.
Allelu, alleluia...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0435', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0435', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0435', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0435', 'verse', 1, 0, '[\"O Lord, You’re great, You are fabulous.\",\"We love You more than any words can sing, sing, sing.\",\"O Lord, You’re great, You are so generous;\",\"You lavish us with gifts when we don’t deserve a thing.\",\"Allelu, alleluia, praise You, Lord.\",\"Alleluia, praise You, Lord, alleluia, praise You, Lord.\",\"Allelu, alleluia, praise You, Lord.\",\"Alleluia, praise You, Lord, alleluia, praise You, Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0435', 'verse', 2, 1, '[\"O Lord, You’re great, You are so powerful;\",\"You hold the mighty universe in Your hand, hand, hand.\",\"O Lord, You’re great, You are so wonderful,\",\"You’ve poured out Your love on this undeserving land.\",\"Allelu, alleluia...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0436', 436, 'Oh, how He loves you and me', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus to Calvary did go,
His love for sinners to show.
What He did there
brought hope from despair.
Oh, how He...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0436', 'Kurt Kaiser');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0436', 'Kurt Kaiser');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0436', 'verse', 2, 0, '[\"Jesus to Calvary did go,\",\"His love for sinners to show.\",\"What He did there\",\"brought hope from despair.\",\"Oh, how He...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0437', 437, 'Oh no! The wine’s all gone', 'JP', 'en', '1991 Greg Leavers', '', 0, 0, 0, 1, 1, 'Oh no! The wine’s all gone!
How can the wedding feast now go on?
Oh dear! What can be done?
Just listen to Jesus, Mary’s Son.
Oh yes! We’ll do what He says –
fill the stone jars with water that’s fresh.
Oh my! They’re pouring it out!
What, wine? That’s a miracle! without a doubt!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0437', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0437', 'Greg Leavers');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0437', 'verse', 1, 0, '[\"Oh no! The wine’s all gone!\",\"How can the wedding feast now go on?\",\"Oh dear! What can be done?\",\"Just listen to Jesus, Mary’s Son.\",\"Oh yes! We’ll do what He says –\",\"fill the stone jars with water that’s fresh.\",\"Oh my! They’re pouring it out!\",\"What, wine? That’s a miracle! without a doubt!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0438', 438, 'Oh, oh, oh, oh', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Praise the Lord.
Praise the Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0438', 'Angela Flynn');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0438', 'Angela Flynn');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0438', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0438', 'verse', 4, 0, '[\"Praise the Lord.\",\"Praise the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0439', 439, 'Oh, yes I am', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I belong to my Father who’s above.
I am kept by His never-ending love.
I will survive the devil’s fiery darts;
and it’s all because of Jesus’ loving heart.
Oh, yes I am...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0439', 'Sam Horner');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0439', 'Sam Horner');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0439', 'verse', 3, 0, '[\"I belong to my Father who’s above.\",\"I am kept by His never-ending love.\",\"I will survive the devil’s fiery darts;\",\"and it’s all because of Jesus’ loving heart.\",\"Oh, yes I am...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0440', 440, 'Old man Noah', 'JP', 'en', 'control            arrangement:', '', 0, 0, 0, 1, 1, 'For forty days they were afloat –
pitter patter, pitter patter, splosh!
But they were safe inside God’s boat –
pitter patter, pitter patter, splosh!
So trust God here, believe God there,
here believe, there trust,
everywhere believe God;
wail, wail here...
flush, flush here...
‘ha ha’ here...
saw, saw here...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0440', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0440', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0440', 'verse', 4, 0, '[\"For forty days they were afloat –\",\"pitter patter, pitter patter, splosh!\",\"But they were safe inside God’s boat –\",\"pitter patter, pitter patter, splosh!\",\"So trust God here, believe God there,\",\"here believe, there trust,\",\"everywhere believe God;\",\"wail, wail here...\",\"flush, flush here...\",\"‘ha ha’ here...\",\"saw, saw here...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0441', 441, 'On Christmas night', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'All out of darkness we have light,
which made the angels sing this night:
all out of darkness we have light,
which made the angels sing this night:
‘Glory to God and peace to men,
now and for evermore. Amen.’');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0441', 'Ralph Vaughan Williams');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0441', 'verse', 4, 0, '[\"All out of darkness we have light,\",\"which made the angels sing this night:\",\"all out of darkness we have light,\",\"which made the angels sing this night:\",\"‘Glory to God and peace to men,\",\"now and for evermore. Amen.’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0442', 442, 'On the road to Damascus', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'On the road to Damascus
yes, I was there when the Lord’s great power He showed.
I watched as Paul
received God’s call
and then on my back he rode!
‘Paul! Paul! Teach the world of Jesus!
Paul! Paul! Teach the world of Jesus!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0442', 'Anthony Welsh');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0442', 'Anthony Welsh');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0442', 'Gerald Fitzpatrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0442', 'verse', 5, 0, '[\"On the road to Damascus\",\"yes, I was there when the Lord’s great power He showed.\",\"I watched as Paul\",\"received God’s call\",\"and then on my back he rode!\",\"‘Paul! Paul! Teach the world of Jesus!\",\"Paul! Paul! Teach the world of Jesus!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0443', 443, 'Once upon a time', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Out he went to find where the missing sheep had strayed;
searching high and low, he was feeling quite dismayed.
Then he thought he heard a noise, it sounded like a bleat –
he’d found the silly, sad and sorry sheep.
‘You’re the sheep...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0443', 'Andy Silver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0443', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0443', 'verse', 3, 0, '[\"Out he went to find where the missing sheep had strayed;\",\"searching high and low, he was feeling quite dismayed.\",\"Then he thought he heard a noise, it sounded like a bleat –\",\"he’d found the silly, sad and sorry sheep.\",\"‘You’re the sheep...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0444', 444, 'Busy little house', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Then Jesus turned and said, ‘Get up and take your bed,
and run along instead!’ from the busy little house.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0444', 'Ian White');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0444', 'Ian White');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0444', 'verse', 8, 0, '[\"Then Jesus turned and said, ‘Get up and take your bed,\",\"and run along instead!’ from the busy little house.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0445', 445, 'One and two and three and four', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'One and two and three and four,
counting sheep in through the door;
fifty-one and fifty-two –
one is lost, what shall I do?
Ninety-eight and ninety-nine,
I will search until I find.
I will keep on looking just because I care.
There he is, caught in some thorns way over there,
he was lost but now is found.
So it’s ninety-eight, ninety-nine, (click fingers) one hundred;
yes, it’s ninety-eight, ninety-nine, (click fingers) one hundred!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0445', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0445', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0445', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0445', 'chorus', 0, 0, '[\"One and two and three and four,\",\"counting sheep in through the door;\",\"fifty-one and fifty-two –\",\"one is lost, what shall I do?\",\"Ninety-eight and ninety-nine,\",\"I will search until I find.\",\"I will keep on looking just because I care.\",\"There he is, caught in some thorns way over there,\",\"he was lost but now is found.\",\"So it’s ninety-eight, ninety-nine, (click fingers) one hundred;\",\"yes, it’s ninety-eight, ninety-nine, (click fingers) one hundred!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0446', 446, 'All God’s faithful children', 'JP', 'en', '1982 Kingsway\'s Thankyou Music, PO Box 75, Eastbourne, East Sussex BN23 6NW, UK. Used by permission', '', 0, 0, 0, 1, 0, 'Praise Him, praise Him,
bring praises to the Lord our God.
All God’s faithful children
must learn to praise Him.
Praise Him, praise Him,
bring praises to the Lord our God.
All God’s faithful children
must learn to praise Him.
Sing hallelu, hallelu,
sing hallelujah to our God.
All God’s faithful children
sing hallelujah God.
Sing hallelu, hallelu,
sing hallelujah to our God.
All God’s faithful children
sing hallelujah God.
Worship Him, worship Him,
bring worship to the Lord our God.
All God’s faithful children
must learn to worship Him.
Worship Him, worship Him,
bring worship to the Lord our God.
All God’s faithful children
must learn to worship Him.
Sing hallelu...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0446', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0446', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0446', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0446', 'verse', 1, 0, '[\"Praise Him, praise Him,\",\"bring praises to the Lord our God.\",\"All God’s faithful children\",\"must learn to praise Him.\",\"Praise Him, praise Him,\",\"bring praises to the Lord our God.\",\"All God’s faithful children\",\"must learn to praise Him.\",\"Sing hallelu, hallelu,\",\"sing hallelujah to our God.\",\"All God’s faithful children\",\"sing hallelujah God.\",\"Sing hallelu, hallelu,\",\"sing hallelujah to our God.\",\"All God’s faithful children\",\"sing hallelujah God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0446', 'verse', 2, 1, '[\"Worship Him, worship Him,\",\"bring worship to the Lord our God.\",\"All God’s faithful children\",\"must learn to worship Him.\",\"Worship Him, worship Him,\",\"bring worship to the Lord our God.\",\"All God’s faithful children\",\"must learn to worship Him.\",\"Sing hallelu...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0447', 447, 'Praise and thanksgiving', 'JP', 'en', 'control                        arrangement:', '', 0, 0, 0, 1, 1, 'Praise and thanksgiving let everyone bring,
unto our Father for every good thing!
All together, joyfully sing!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0447', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0447', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0447', 'Greg Leavers');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0447', 'verse', 1, 0, '[\"Praise and thanksgiving let everyone bring,\",\"unto our Father for every good thing!\",\"All together, joyfully sing!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0448', 448, 'Prayer phone', 'JP', 'en', '', '', 0, 0, 0, 1, 1, '... is like a...
for us to talk to...
... is like a...
for us to talk to...
... is like a...
for us to talk to...
Pick it up and use it every day.
Pick it up and use it every day.
Pick it up and use it every day.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0448', 'Paul Crouch');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0448', 'David Mudie');
