INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0459', 'chorus', 0, 0, '[\"So we’re marching along, singing a song,\",\"we’re in the Lord’s army.\",\"We’re fighting for right as we’re learning what’s wrong,\",\"’cause – we’re in the Lord’s army.\",\"He’s got the victory, so let’s really shout,\",\"we’re in the Lord’s army.\",\"We’re in the Lord’s (yeah), we’re in the Lord’s (right),\",\"we’re in the Lord’s army.\",\"So we’re marching along...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0460', 460, 'Sometimes I’m naughty', 'JP', 'en', '1990 Greg Leavers', '', 0, 0, 0, 1, 1, 'Sometimes I’m naughty,
I know I’ve been bad;
I say such unkind things
and make people sad.
Father, I know I’ve done wrong;
Lord, please forgive me I pray.
I want to say,
I want to say
that I’m so sorry, Lord.
I’m rude to my family,
I want my own way.
I don’t show them kindness
or do what they say.
Father, I know...
In love You forgive me,
I’m glad I’m Your child.
Your Spirit lives in me
to change me inside.
Father, help me today;
help me to please You, I pray.
I want to say,
I want to say
how much I love You, Lord.');
