INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0460', 'verse', 2, 1, '[\"I’m rude to my family,\",\"I want my own way.\",\"I don’t show them kindness\",\"or do what they say.\",\"Father, I know...\"]');
