INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0462', 462, 'What do you do', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Some people march and raise their hands
