INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0464', 464, 'Spies were sent out', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'So when you’re feeling scared or
things are looking blue –
you’ve a job that seems so
difficult to do –
don’t forget His promises
He’s made to help you through:
the Lord says, ‘Don’t be afraid,
I’ll always be with you.’
We’ve got to...');
