INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0465', 465, 'Spirit of God', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Spirit of God, please fill me now to overflowing.
Spirit of God, give me the words You want me to say.
Spirit of God, release my tongue to praise the Holy Son;
Spirit of God, free this spirit of mine.');
