INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0466', 466, 'Standing in Your presence, Lord', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'You have brought us here today,
kept and guided for so long.
There’s no need for tears or sadness,
the joy that You give us, Lord, will make us strong.
Standing in Your presence, Lord,
listening to Your holy law.
Standing in Your presence, Lord,
we will praise You evermore.');
