INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0471', 471, 'In the stable', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'The wise men found the Baby
and gave gifts, one, two, three;
today it is His birthday:
My gift is – LOVE from me.');
