INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0472', 472, 'The Spirit lives', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'The Spirit lives in you and me,
walk, walk in the light;
His light will shine for all to see,
walk, walk in the light.
Walk in the light...');
