INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0473', 473, 'The sower song', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'The word of the Lord is planted in my heart
and I want to see it grow.
The word of the Lord is planted in my heart
and I want you to know.
I won’t let the enemy take it,
or let bad times shake it;
I won’t let other things choke it out, (choke choke choke choke)
’cause I want to let it grow, grow, grow,
’cause I want to let it grow! (last time) (Yeah!)');
