INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0474', 474, 'The word of God', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'The word of God is living and active,
sharper than any double-edged sword.
The word of God is living and active,
sharper than any double-edged sword.');
