INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0475', 475, 'There he stood – Goliath', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Life is filled with problems which may give us cause to fear.
But though they seem like giants, just remember God is near.
He will always help us when we put our trust in Him.
In the name of Jesus we shall win.
‘Not with spear...');
