INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0477', 477, 'Good old Daniel', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, 'There once was a man called Daniel
(good old Daniel).
And Daniel prayed three times a day
(good old Daniel).
But the King’s decree said, ‘Worship me!’
(poor old Daniel).
But Daniel would not bend the knee!
(good old Daniel).
So the gates went ‘crash’ (crash),
and the locks went ‘click’ (click),
and the lions began to roar,
and the lions began to roar.
But they couldn’t eat Daniel if they tried
(good old Daniel),
because the Lord was on his side
(good old Daniel).');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0477', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0477', 'Anon');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0477', 'chorus', 0, 0, '[\"There once was a man called Daniel\",\"(good old Daniel).\",\"And Daniel prayed three times a day\",\"(good old Daniel).\",\"But the King’s decree said, ‘Worship me!’\",\"(poor old Daniel).\",\"But Daniel would not bend the knee!\",\"(good old Daniel).\",\"So the gates went ‘crash’ (crash),\",\"and the locks went ‘click’ (click),\",\"and the lions began to roar,\",\"and the lions began to roar.\",\"But they couldn’t eat Daniel if they tried\",\"(good old Daniel),\",\"because the Lord was on his side\",\"(good old Daniel).\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0478', 478, 'There’s a song for all the children', 'JP', 'en', 'in this version The Jubilate Group', '', 0, 0, 0, 1, 1, 'There’s a song for all the children
that makes the heavens ring,
a song that even angels
can never, never sing;
they praise Him as their maker
and see Him glorified,
but we can call Him Saviour
because for us He died.
There’s a place for all the children
where Jesus reigns in love,
a place of joy and freedom
that nothing can remove;
a home that is more friendly
than any home we know,
where Jesus makes us welcome
because He loves us so.
There’s a friend for all the children
to guide us every day,
whose care is always faithful
and never fades away;
there’s no-one else so loyal –
His friendship stays the same;
He knows us and He loves us,
and Jesus is His name.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0478', 'Albert Midlane');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0478', 'John Stainer');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0478', 'verse', 1, 0, '[\"There’s a song for all the children\",\"that makes the heavens ring,\",\"a song that even angels\",\"can never, never sing;\",\"they praise Him as their maker\",\"and see Him glorified,\",\"but we can call Him Saviour\",\"because for us He died.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0478', 'verse', 2, 1, '[\"There’s a place for all the children\",\"where Jesus reigns in love,\",\"a place of joy and freedom\",\"that nothing can remove;\",\"a home that is more friendly\",\"than any home we know,\",\"where Jesus makes us welcome\",\"because He loves us so.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0478', 'verse', 3, 2, '[\"There’s a friend for all the children\",\"to guide us every day,\",\"whose care is always faithful\",\"and never fades away;\",\"there’s no-one else so loyal –\",\"His friendship stays the same;\",\"He knows us and He loves us,\",\"and Jesus is His name.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0479', 479, 'Think big: an elephant', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Think strong: a tiger’s jaw.
Think stronger: a castle wall.
Think stronger: a hurricane that leaves little standing there at all.
Yet strong, strong, stronger is God!
And He loves us all.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0479', 'Susan Sayers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0479', 'Susan Sayers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0479', 'Frances M Kelly');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0479', 'verse', 3, 0, '[\"Think strong: a tiger’s jaw.\",\"Think stronger: a castle wall.\",\"Think stronger: a hurricane that leaves little standing there at all.\",\"Yet strong, strong, stronger is God!\",\"And He loves us all.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0480', 480, 'This Child', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'This Child, raising the humble and poor;
oh, this Child, making the proud ones to fall;
this Child, filling the hungry with good things;
this heavenly Child.
This Child, heaven come down...
This Child, heaven come down...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0480', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0480', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0480', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0480', 'verse', 3, 0, '[\"This Child, raising the humble and poor;\",\"oh, this Child, making the proud ones to fall;\",\"this Child, filling the hungry with good things;\",\"this heavenly Child.\",\"This Child, heaven come down...\",\"This Child, heaven come down...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0481', 481, 'The Christian Conga', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, '');
