INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0481', 'Anon');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0482', 482, 'Wandering like lost sheep', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Wandering like lost sheep, we were going our own way,
when Jesus the good shepherd found us, led us home,
laid down His life before us that we might all be saved.
We now belong to Jesus, we now belong to Him.
We are His sheep, we are His sheep,
we hear His voice, and follow Him.
We are His sheep, we are His sheep,
we hear His voice, and follow Him.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0482', 'Andy Silver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0482', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0482', 'verse', 1, 0, '[\"Wandering like lost sheep, we were going our own way,\",\"when Jesus the good shepherd found us, led us home,\",\"laid down His life before us that we might all be saved.\",\"We now belong to Jesus, we now belong to Him.\",\"We are His sheep, we are His sheep,\",\"we hear His voice, and follow Him.\",\"We are His sheep, we are His sheep,\",\"we hear His voice, and follow Him.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0483', 483, 'We are soldiers of the King', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'We are soldiers of the King,
of His victory we will sing;
living every hour by the Spirit’s power,
marching in the name of Jesus.
Enemies are all around,
as we praise they’re losing ground;
trusting in God’s word – it’s a mighty sword –
forever friendly, faithful followers fighting for the King.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0483', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0483', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0483', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0483', 'verse', 1, 0, '[\"We are soldiers of the King,\",\"of His victory we will sing;\",\"living every hour by the Spirit’s power,\",\"marching in the name of Jesus.\",\"Enemies are all around,\",\"as we praise they’re losing ground;\",\"trusting in God’s word – it’s a mighty sword –\",\"forever friendly, faithful followers fighting for the King.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0484', 484, 'We need to grow', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'We grow as we learn and share
with others that we know;
these are the things to do
if we really want to grow.
We need to grow...
grow in the knowledge of,
grow in the knowledge of Jesus our Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0484', 'Alan J Price');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0484', 'Alan J Price');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0484', 'verse', 3, 0, '[\"We grow as we learn and share\",\"with others that we know;\",\"these are the things to do\",\"if we really want to grow.\",\"We need to grow...\",\"grow in the knowledge of,\",\"grow in the knowledge of Jesus our Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0485', 485, 'We will praise', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'We will praise, we will praise, we will praise the Lord;
we will praise the Lord because He is good.
We will praise, we will praise, we will praise the Lord,
because His love is everlasting.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0485', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0485', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0485', 'Phil Burt');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0485', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0485', 'verse', 1, 0, '[\"We will praise, we will praise, we will praise the Lord;\",\"we will praise the Lord because He is good.\",\"We will praise, we will praise, we will praise the Lord,\",\"because His love is everlasting.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0486', 486, 'We’ll praise Him on the trumpet', 'JP', 'en', '1984 Kingsway\'s Thankyou Music, PO Box 75, Eastbourne, East Sussex BN23 6NW, UK. Used by permission', '', 0, 0, 0, 1, 0, 'We’ll praise Him on the trumpet and we’ll praise Him on guitar,
we’ll praise Him with a drum and with a harp and a lyre.
We’ll praise Him with our voices ’cause we want to lift Him higher;
and all God’s people shout, ‘Hallelujah!’
Hallelujah, hallelujah, hallelujah, hallelujah.
Hallelujah, hallelujah, and all God’s people shout, ‘Hallelujah!’
We’ll praise Him for His favour and we’ll praise Him for His deeds;
we’ll praise Him – though the road is rough, He’s still the one who leads.
We’ll praise Him for provision as He cares for all our needs,
and all God’s people shout, ‘Hallelujah!’
Hallelujah, hallelujah...
We’ll praise Him that upon a cross the Lamb of God was slain;
we’ll praise Him that He conquered death and now He lives again.
We’ll praise Him – He’s the King of kings who will forever reign,
and all God’s people shout, ‘Hallelujah!’
Hallelujah, hallelujah...
We’ll praise Him that He’s making us the people we should be;
we’ll praise Him that our chains are gone, we’re now completely free.
We’ll praise Him – we don’t know defeat, we live in victory,
and all God’s people shout, ‘Hallelujah!’
Hallelujah, hallelujah...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0486', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0486', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0486', 'Phil Burt');
