INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0487', 487, 'We’re following Jesus', 'JP', 'en', '1990 Integrity\'s Hosanna! Music, administered by Kingsway\'s Thankyou Music, PO Box 75, Eastbourne, East Sussex BN23 6NW, UK. Used by permission', '', 0, 0, 0, 1, 1, 'We’re following Jesus,
just like Matthew, Peter and John.
We’re following Jesus,
just like Thaddeus, Philip and Tom.
We’re following Jesus,
just like Simon, James and Andrew.
Like them, the Lord is calling me and you.
They all loved Him (I want to love Him),
they all served Him (I want to serve Him).
They all knew Him (I want to know Him),
they all followed. (I want to follow).
We’re following...
Jesus taught them (Teach me, Lord),
Jesus led them (Lead me, Lord),
Jesus fed them (Feed me, Lord),
Jesus used them (Use me, Lord).
We’re following...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0487', 'Robert C Evans');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0487', 'Robert C Evans');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0487', 'chorus', 0, 0, '[\"We’re following Jesus,\",\"just like Matthew, Peter and John.\",\"We’re following Jesus,\",\"just like Thaddeus, Philip and Tom.\",\"We’re following Jesus,\",\"just like Simon, James and Andrew.\",\"Like them, the Lord is calling me and you.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0487', 'verse', 1, 1, '[\"They all loved Him (I want to love Him),\",\"they all served Him (I want to serve Him).\",\"They all knew Him (I want to know Him),\",\"they all followed. (I want to follow).\",\"We’re following...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0487', 'verse', 2, 2, '[\"Jesus taught them (Teach me, Lord),\",\"Jesus led them (Lead me, Lord),\",\"Jesus fed them (Feed me, Lord),\",\"Jesus used them (Use me, Lord).\",\"We’re following...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0488', 488, 'What colours God has made', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'So sing my Father’s praise,
the living God is He,
whose colours brighten all our days,
who loves and cares for me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0488', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0488', 'Michael Paget');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0488', 'verse', 5, 0, '[\"So sing my Father’s praise,\",\"the living God is He,\",\"whose colours brighten all our days,\",\"who loves and cares for me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0489', 489, 'What do you give', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'What do you give a God who has everything?
What do you give the maker of the earth?
Give Him your life and let Him guide you;
trust Him in all your ways!
Give Him your heart; He’ll fill it up with praise!
Give Him your heart; He’ll fill it up with praise!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0489', 'Nancy Harrison');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0489', 'Nancy Harrison');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0489', 'verse', 2, 0, '[\"What do you give a God who has everything?\",\"What do you give the maker of the earth?\",\"Give Him your life and let Him guide you;\",\"trust Him in all your ways!\",\"Give Him your heart; He’ll fill it up with praise!\",\"Give Him your heart; He’ll fill it up with praise!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0490', 490, 'It’s a miracle', 'JP', 'en', '1975 Kingsway\'s Thankyou Music, PO Box 75, Eastbourne, East Sussex BN23 6NW, UK. Used by permission', '', 0, 0, 0, 1, 0, 'What drives the stars without making a sound?
Why don’t they crash when they’re spinning around?
What holds me up when the world’s upside down?
I know it’s a miracle!
Who tells the ocean where to stop on the sand?
What keeps the water back from drowning the land?
Who makes the rules I don’t understand?
I know it’s a miracle!
It’s a miracle just to know
God is with me wherever I go.
It’s a miracle as big as can be,
that He can make a miracle of me!
Who shows the birds how to make a good nest?
How can the geese fly so far without rest?
Why do the ducks go south and not west?
I know it’s a miracle!
What makes a brown seed so tiny and dry
burst into green and grow up so high?
And shoot out blossoms of red by and by?
I know it’s a miracle!
It’s a miracle...
When a spring makes a brook and a brook makes a stream,
the stream makes the river water fresh as can be.
Who puts the salt in when it gets to the sea?
I know it’s a miracle!
There are thousands of people in cities I see,
the world must be crowded as crowded can be;
but God knows my name and He cares about me.
I know it’s a miracle!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0490', 'William J Gaither');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0490', 'Gloria Gaither');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0490', 'William J Gaither');
