INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0490', 'verse', 2, 1, '[\"Who shows the birds how to make a good nest?\",\"How can the geese fly so far without rest?\",\"Why do the ducks go south and not west?\",\"I know it’s a miracle!\",\"What makes a brown seed so tiny and dry\",\"burst into green and grow up so high?\",\"And shoot out blossoms of red by and by?\",\"I know it’s a miracle!\",\"It’s a miracle...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0490', 'verse', 3, 2, '[\"When a spring makes a brook and a brook makes a stream,\",\"the stream makes the river water fresh as can be.\",\"Who puts the salt in when it gets to the sea?\",\"I know it’s a miracle!\",\"There are thousands of people in cities I see,\",\"the world must be crowded as crowded can be;\",\"but God knows my name and He cares about me.\",\"I know it’s a miracle!\"]');
