INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0492', 492, 'What made a difference', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'If you’ve decided that your life must change,
then give it to the Lord for Him to rearrange.
He will be your Saviour and friend,
and on His presence you can depend.
You may not be a missionary or travel around,
but all of us can witness to the joy that we’ve found.
Yes, what the Lord could do for Saul,
He’s ready now to do for one and all!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0492', 'Gillian E Hutchinson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0492', 'Gillian E Hutchinson');
