INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0493', 493, 'When I’m feeling lonely', 'JP', 'en', '1991 Greg Leavers', '', 0, 0, 0, 1, 1, 'When I’m feeling lonely, when I’m feeling blue,
when I’m feeling so fed up, I can always talk to You.
Lord, You hear me when I pray;
Lord, You’re near me every day.
Thank You, Lord, You always see me through;
I’ll never, ever, find a friend as good as You.
I’ll never, ever, find a friend as good as You.');
