INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0495', 495, 'When we look up', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'When we look up to the sky
and we see the sparrows fly,
let’s remember that Jesus knows them all.
When we see the lovely trees
and the flowers and the leaves,
let’s remember that Jesus made them all.
J.E.S.U.S. C.A.R.E.S.
Jesus cares for all the things He made:
that means you and me,
our friends and family.
Thank You, Jesus, for caring for me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0495', 'Andy Silver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0495', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0495', 'verse', 1, 0, '[\"When we look up to the sky\",\"and we see the sparrows fly,\",\"let’s remember that Jesus knows them all.\",\"When we see the lovely trees\",\"and the flowers and the leaves,\",\"let’s remember that Jesus made them all.\",\"J.E.S.U.S. C.A.R.E.S.\",\"Jesus cares for all the things He made:\",\"that means you and me,\",\"our friends and family.\",\"Thank You, Jesus, for caring for me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0496', 496, 'Thumbs up', 'JP', 'en', '1991 Daybreak Music Ltd', '', 0, 0, 0, 1, 1, 'When you’re feeling good put your thumbs up.
When you’re feeling bad put them down.
When you’re feeling happy you can smile all day.
When you’re feeling low wear a frown.
But don’t just follow your feelings.
Trust in God and His word.
No matter what you feel put your thumbs up,
put your faith in the Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0496', 'Paul Field');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0496', 'Ralph Chambers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0496', 'Paul Field');
