INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0497', 497, 'When God breathes', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'When God breathes His Spirit in my life;
when God breathes His Spirit in my life;
when God breathes His Spirit in my life,
then I will shine, shine for Him.');
