INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0497', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0497', 'verse', 1, 0, '[\"When God breathes His Spirit in my life;\",\"when God breathes His Spirit in my life;\",\"when God breathes His Spirit in my life,\",\"then I will shine, shine for Him.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0498', 498, 'Cross over the road', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Would you walk by on the other side
when starving children cried?
Would you walk by on the other side,
and would you not provide?
Cross over the road, my friend,
ask the Lord His strength to lend,
His compassion has no end.
Cross over the road.
Cross over the road,
cross over the road.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0498', 'P M Verrall');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0498', 'P M Verrall');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0498', 'verse', 3, 0, '[\"Would you walk by on the other side\",\"when starving children cried?\",\"Would you walk by on the other side,\",\"and would you not provide?\",\"Cross over the road, my friend,\",\"ask the Lord His strength to lend,\",\"His compassion has no end.\",\"Cross over the road.\",\"Cross over the road,\",\"cross over the road.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0499', 499, 'Yet to all who received Him', 'JP', 'en', '', '', 0, 0, 0, 1, 0, 'Yet to all who received Him,
to those who believed in His name,
He gave the right to become the children of God.
Yet to all who received Him,
to those who believed in His name,
He gave the right to become the children of God.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0499', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0499', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0499', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0499', 'verse', 1, 0, '[\"Yet to all who received Him,\",\"to those who believed in His name,\",\"He gave the right to become the children of God.\",\"Yet to all who received Him,\",\"to those who believed in His name,\",\"He gave the right to become the children of God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0500', 500, 'You are holy', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'You are holy, so You hate all we do wrong.
You are loving, for our sin You gave Your Son.
You are Father, the great protector;
You are mighty, the great Creator;
You are faithful, You are wonderful,
You are King and You are God.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0500', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0500', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0500', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0500', 'verse', 1, 0, '[\"You are holy, so You hate all we do wrong.\",\"You are loving, for our sin You gave Your Son.\",\"You are Father, the great protector;\",\"You are mighty, the great Creator;\",\"You are faithful, You are wonderful,\",\"You are King and You are God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0501', 501, 'You can weigh an elephant’s auntie', 'JP', 'en', '1988 Oxford University Press, from New Songs of Praise 4', '', 0, 0, 0, 1, 1, 'You can weigh an elephant’s auntie,
you can weigh a pedigree flea;
but you can’t weigh up all the love
that Jesus has for me, me, me,
that Jesus has for me.
You can measure the length of a wiggly worm,
or the height of a nanny goat’s knee;
but you can’t measure all the love
that Jesus has for me, me, me,
that Jesus has for me.
You can add up two and two, make four,
it’s as easy as A, B, C;
but you can’t add up all the love
that Jesus has for me, me, me,
that Jesus has for me.
You can amaze me by subtraction,
you can even take three from three;
but you can’t take away the love
that Jesus has for me, me, me,
that Jesus has for me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0501', 'Chris Brown');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0501', 'Chris Brown');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0501', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0501', 'verse', 1, 0, '[\"You can weigh an elephant’s auntie,\",\"you can weigh a pedigree flea;\",\"but you can’t weigh up all the love\",\"that Jesus has for me, me, me,\",\"that Jesus has for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0501', 'verse', 2, 1, '[\"You can measure the length of a wiggly worm,\",\"or the height of a nanny goat’s knee;\",\"but you can’t measure all the love\",\"that Jesus has for me, me, me,\",\"that Jesus has for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0501', 'verse', 3, 2, '[\"You can add up two and two, make four,\",\"it’s as easy as A, B, C;\",\"but you can’t add up all the love\",\"that Jesus has for me, me, me,\",\"that Jesus has for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0501', 'verse', 4, 3, '[\"You can amaze me by subtraction,\",\"you can even take three from three;\",\"but you can’t take away the love\",\"that Jesus has for me, me, me,\",\"that Jesus has for me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0502', 502, 'Only Jesus', 'JP', 'en', '1991 Daybreak Music Ltd', '', 0, 0, 0, 1, 1, 'You can’t catch a plane to take you to heaven.
Not even a spaceship can get that far.
You can’t take a hovercraft or helicopter journey
or drive in the fastest racing car.
Only Jesus, only Jesus, only Jesus is the way.
Only Jesus, only Jesus, only Jesus is the way.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0502', 'Ralph Chambers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0502', 'Paul Field');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0502', 'verse', 1, 0, '[\"You can’t catch a plane to take you to heaven.\",\"Not even a spaceship can get that far.\",\"You can’t take a hovercraft or helicopter journey\",\"or drive in the fastest racing car.\",\"Only Jesus, only Jesus, only Jesus is the way.\",\"Only Jesus, only Jesus, only Jesus is the way.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0503', 503, 'You’re my maker', 'JP', 'en', '1991 Joan Robinson', '', 0, 0, 0, 1, 1, 'You’re my maker, You’re my music,
You’re the Master of my life.
You’re my maker, You’re my music,
You’re the Master of my life.
You’re my maker, You’re my music,
You’re the Master of my life,
and I love You, Jesus my Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('JP-0503', 'Joan Robinson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0503', 'Joan Robinson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('JP-0503', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0503', 'verse', 1, 0, '[\"You’re my maker, You’re my music,\",\"You’re the Master of my life.\",\"You’re my maker, You’re my music,\",\"You’re the Master of my life.\",\"You’re my maker, You’re my music,\",\"You’re the Master of my life,\",\"and I love You, Jesus my Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0504', 504, 'And our voices will sing', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'There will be days when we don’t praise
and music can’t be heard,
but God enjoys His children
as they live life by His word.
And our voices will sing...
They will add to our voices and sing.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0504', 'verse', 2, 0, '[\"There will be days when we don’t praise\",\"and music can’t be heard,\",\"but God enjoys His children\",\"as they live life by His word.\",\"And our voices will sing...\",\"They will add to our voices and sing.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0505', 505, 'As for me and my house', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'As for me...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0505', 'verse', 1, 0, '[\"As for me...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0506', 506, 'Autumn days', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Scent of gardens when the rain’s been falling,
and a minnow darting down a stream,
picked-up engine that’s been stuttering and stalling,
and a win for my home team.
So I mustn’t forget...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0506', 'verse', 4, 0, '[\"Scent of gardens when the rain’s been falling,\",\"and a minnow darting down a stream,\",\"picked-up engine that’s been stuttering and stalling,\",\"and a win for my home team.\",\"So I mustn’t forget...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0507', 507, 'Be still, for the presence of the Lord', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Be still,
for the power of the Lord
is moving in this place:
He comes to cleanse and heal,
to minister His grace –
no work too hard for Him.
In faith receive from Him.
Be still,
for the power of the Lord
is moving in this place.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0507', 'verse', 3, 0, '[\"Be still,\",\"for the power of the Lord\",\"is moving in this place:\",\"He comes to cleanse and heal,\",\"to minister His grace –\",\"no work too hard for Him.\",\"In faith receive from Him.\",\"Be still,\",\"for the power of the Lord\",\"is moving in this place.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0508', 508, 'Thank You for loving me', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'So thank You, Lord, for loving me
today and all eternity.
And may my song forever be,
thank You for loving me.
Thank You, Jesus...
Thank You, Jesus...
ﾩ 1995 Out of the Ark Music, Sefton House, 2 Molesey Road, Walton-On-Thames, KT12 4RQ. Used by permission');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0508', 'verse', 4, 0, '[\"So thank You, Lord, for loving me\",\"today and all eternity.\",\"And may my song forever be,\",\"thank You for loving me.\",\"Thank You, Jesus...\",\"Thank You, Jesus...\",\"ﾩ 1995 Out of the Ark Music, Sefton House, 2 Molesey Road, Walton-On-Thames, KT12 4RQ. Used by permission\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0509', 509, 'Bless', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Blessèd be the name of the Lord,
He is worthy to be praised and adored;
so we lift up holy hands in one accord, singing,
‘Blessèd be the name, blessèd be the name,
blessèd be the name of the Lord!’');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0509', 'verse', 1, 0, '[\"Blessèd be the name of the Lord,\",\"He is worthy to be praised and adored;\",\"so we lift up holy hands in one accord, singing,\",\"‘Blessèd be the name, blessèd be the name,\",\"blessèd be the name of the Lord!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0510', 510, 'Bless', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Holy is the name of the Lord,
holy is the name of the Lord,
holy is the name of the Lord most high!
Holy is the name of the Lord,
holy is the name of the Lord,
holy is the name of the Lord most high!
The name of the Lord...
Words and music:');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0510', 'verse', 3, 0, '[\"Holy is the name of the Lord,\",\"holy is the name of the Lord,\",\"holy is the name of the Lord most high!\",\"Holy is the name of the Lord,\",\"holy is the name of the Lord,\",\"holy is the name of the Lord most high!\",\"The name of the Lord...\",\"Words and music:\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0511', 511, 'Harvest samba', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'VOICE 1 REPEAT VERSES 1 & 2
VOICE 2
Thank You for the harvest,
thank You for Your goodness.
For all of the fruit and vegetables
and the wonderful things that grow.
It’s another Harvest Festival...
ﾩ 2002 Out of the Ark Music, Sefton House, 2 Molesey Road, Walton-On-Thames, KT12 4RQ. Used by permission');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0511', 'chorus', 0, 0, '[\"VOICE 1 REPEAT VERSES 1 & 2\",\"VOICE 2\",\"Thank You for the harvest,\",\"thank You for Your goodness.\",\"For all of the fruit and vegetables\",\"and the wonderful things that grow.\",\"It’s another Harvest Festival...\",\"ﾩ 2002 Out of the Ark Music, Sefton House, 2 Molesey Road, Walton-On-Thames, KT12 4RQ. Used by permission\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0512', 512, 'Child in a manger born', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Child in a manger born,
I want to know You more,
know You are near me,
love You more dearly
Jesus, my Lord.
ﾩ 1994 Out of the Ark Music, Sefton House, 2 Molesey Road, Walton-On-Thames, KT12 4RQ. Used by permission');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0512', 'verse', 5, 0, '[\"Child in a manger born,\",\"I want to know You more,\",\"know You are near me,\",\"love You more dearly\",\"Jesus, my Lord.\",\"ﾩ 1994 Out of the Ark Music, Sefton House, 2 Molesey Road, Walton-On-Thames, KT12 4RQ. Used by permission\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0513', 513, 'Do be, do be, do be, do be strong', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Do be, do be, do be, do be strong.
Do what, do what, do what God wants done.
Don’t be afraid, don’t be dismayed,
for the Lord your God is with you.
ﾩ Greg Leavers');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0513', 'verse', 1, 0, '[\"Do be, do be, do be, do be strong.\",\"Do what, do what, do what God wants done.\",\"Don’t be afraid, don’t be dismayed,\",\"for the Lord your God is with you.\",\"ﾩ Greg Leavers\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0514', 514, 'Don’t be afraid', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Doesn’t matter if you’re big or small,
strong or insecure;
there’s no easy way to live for God,
of that you can be sure.
Don’t be afraid...
ﾩ Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0514', 'verse', 2, 0, '[\"Doesn’t matter if you’re big or small,\",\"strong or insecure;\",\"there’s no easy way to live for God,\",\"of that you can be sure.\",\"Don’t be afraid...\",\"ﾩ Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0515', 515, 'Easter jubilation', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Easter jubilation fills the streets and towns,
celebrations have begun.
Hear the music and the dancing now,
join the laughter and the fun!
Oh, raise a joyful shout!...
Hoy!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0515', 'verse', 4, 0, '[\"Easter jubilation fills the streets and towns,\",\"celebrations have begun.\",\"Hear the music and the dancing now,\",\"join the laughter and the fun!\",\"Oh, raise a joyful shout!...\",\"Hoy!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0516', 516, 'Even if you’re lost in space', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Even if I’m lost in space,
Jesus can find me.
He’s bigger than the universe,
He’s all around me.
It doesn’t matter where we are,
even on the farthest star,
there isn’t anywhere too far from Him.
ﾩ 2004 Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0516', 'verse', 1, 0, '[\"Even if I’m lost in space,\",\"Jesus can find me.\",\"He’s bigger than the universe,\",\"He’s all around me.\",\"It doesn’t matter where we are,\",\"even on the farthest star,\",\"there isn’t anywhere too far from Him.\",\"ﾩ 2004 Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0517', 517, 'Every blade of grass', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Every bird that sings,
(every bird that sings,)
every shining sea,
(every shining sea,)
every blooming flower,
(every blooming flower,)
every towering tree,
(every towering tree,)
every single thing
(every single thing)
that Your hands have made
(that Your hands have made)
gives You glory,
(gives You glory,)
gives You praise
(gives You praise).
And I want to praise...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0517', 'verse', 2, 0, '[\"Every bird that sings,\",\"(every bird that sings,)\",\"every shining sea,\",\"(every shining sea,)\",\"every blooming flower,\",\"(every blooming flower,)\",\"every towering tree,\",\"(every towering tree,)\",\"every single thing\",\"(every single thing)\",\"that Your hands have made\",\"(that Your hands have made)\",\"gives You glory,\",\"(gives You glory,)\",\"gives You praise\",\"(gives You praise).\",\"And I want to praise...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0518', 518, 'Every second', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Every ocean, every island,
every hill and every stream,
You’re the God whose power and works
are on display.
Every creature, every planet,
everything that’s ever been,
You’re the God of awesome power
in every way.
You are the Lord...
ﾩ 2005 Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0518', 'verse', 3, 0, '[\"Every ocean, every island,\",\"every hill and every stream,\",\"You’re the God whose power and works\",\"are on display.\",\"Every creature, every planet,\",\"everything that’s ever been,\",\"You’re the God of awesome power\",\"in every way.\",\"You are the Lord...\",\"ﾩ 2005 Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0519', 519, 'Faith as small as a mustard seed', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Do da do da...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0519', 'verse', 1, 0, '[\"Do da do da...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0520', 520, 'Father', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Father, may Your name be honoured,
Father, may Your kingdom come,
and Father, please give us today
all our daily bread.
Father, will You please forgive us,
Father, as we forgive others,
Father, will You lead us safely');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0520', 'verse', 1, 0, '[\"Father, may Your name be honoured,\",\"Father, may Your kingdom come,\",\"and Father, please give us today\",\"all our daily bread.\",\"Father, will You please forgive us,\",\"Father, as we forgive others,\",\"Father, will You lead us safely\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0521', 521, 'Father God', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I want to know You, Lord.
I want to know You more and more.
Take all I am and make it Yours,
Father God.
I want to know You...
ﾩ 2001 Vineyard Songs (UK/Eire), administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0521', 'chorus', 0, 0, '[\"I want to know You, Lord.\",\"I want to know You more and more.\",\"Take all I am and make it Yours,\",\"Father God.\",\"I want to know You...\",\"ﾩ 2001 Vineyard Songs (UK\\/Eire), administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0522', 522, 'Father God, You love me', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Father God, from Your love there is nowhere I can hide.
If I go down into the depths or cross the ocean wide,
there Your love would find me, You’d take me in Your hand.
Your love for me is more than I can ever understand.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0522', 'verse', 2, 0, '[\"Father God, from Your love there is nowhere I can hide.\",\"If I go down into the depths or cross the ocean wide,\",\"there Your love would find me, You’d take me in Your hand.\",\"Your love for me is more than I can ever understand.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0523', 523, 'Father, I can call You Father', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Father, I will serve You,
Father, I will seek Your face,
today, tomorrow and always,
You are my Father.
Father, Father...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0523', 'verse', 3, 0, '[\"Father, I will serve You,\",\"Father, I will seek Your face,\",\"today, tomorrow and always,\",\"You are my Father.\",\"Father, Father...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0524', 524, 'Father, when I think', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Father, when I think of how naughty I can be,
I’m so very glad to know that Jesus died for me.
Your love, I don’t deserve it, but I’d be lost without it,
Jesus, Friend of sinners, be a friend to me.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0524', 'verse', 1, 0, '[\"Father, when I think of how naughty I can be,\",\"I’m so very glad to know that Jesus died for me.\",\"Your love, I don’t deserve it, but I’d be lost without it,\",\"Jesus, Friend of sinners, be a friend to me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0525', 525, 'From the tiny ant', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'From the mongrel dog,');
