INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0526', 526, 'Live my life by faith', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'By faith I take God’s hand,
by faith I understand,
by faith I am made pure,
by faith I can be sure.
For ever I will live...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0526', 'verse', 2, 0, '[\"By faith I take God’s hand,\",\"by faith I understand,\",\"by faith I am made pure,\",\"by faith I can be sure.\",\"For ever I will live...\"]');
