INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0529', 529, 'The Old Testament Song', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Job, Psalms, Proverbs, Ecclesiastes, Song of Songs.
Job, Psalms, Proverbs, Ecclesiastes, Song of Songs.
Isaiah and Jeremiah who also wrote Lamentations.
Ezekiel, Daniel, Hosea, Joel, Amos and Obadiah.
Jonah and Micah, Nahum and the book of Habakkuk.
Zephaniah, Haggai, Zechariah, Malachi:
the prophets of these books.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0529', 'verse', 1, 0, '[\"Job, Psalms, Proverbs, Ecclesiastes, Song of Songs.\",\"Job, Psalms, Proverbs, Ecclesiastes, Song of Songs.\",\"Isaiah and Jeremiah who also wrote Lamentations.\",\"Ezekiel, Daniel, Hosea, Joel, Amos and Obadiah.\",\"Jonah and Micah, Nahum and the book of Habakkuk.\",\"Zephaniah, Haggai, Zechariah, Malachi:\",\"the prophets of these books.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0530', 530, 'Get into the word', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'The Bible is the greatest book,
the one that everyone should read.
Every chapter, every verse
shows us just what God is like,
as Jesus’ face comes shining through.
Get into the word,
get reading the word,
get living the word of God.
I said word of God.
ﾩ 2004 Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0530', 'verse', 2, 0, '[\"The Bible is the greatest book,\",\"the one that everyone should read.\",\"Every chapter, every verse\",\"shows us just what God is like,\",\"as Jesus’ face comes shining through.\",\"Get into the word,\",\"get reading the word,\",\"get living the word of God.\",\"I said word of God.\",\"ﾩ 2004 Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0531', 531, 'Glory and honour', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Glory and honour to You we bring.
Beautiful Saviour Your praise we sing.
Heaven bows down, and worships Your name,
God of creation we praise.
God of creation we praise.
ﾩ 2005 Thankyou Music, administered by worshiptogether.com songs excl. UK and Europe, administered by kingswaysongs.com. tym@kingsway.co.uk. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0531', 'verse', 1, 0, '[\"Glory and honour to You we bring.\",\"Beautiful Saviour Your praise we sing.\",\"Heaven bows down, and worships Your name,\",\"God of creation we praise.\",\"God of creation we praise.\",\"ﾩ 2005 Thankyou Music, administered by worshiptogether.com songs excl. UK and Europe, administered by kingswaysongs.com. tym@kingsway.co.uk. Used by permission.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0532', 532, 'God is as good as His word', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'God is as good as His word,
God is as good as His word,
and His word is good.
His word is good...
His word is good...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0532', 'chorus', 0, 0, '[\"God is as good as His word,\",\"God is as good as His word,\",\"and His word is good.\",\"His word is good...\",\"His word is good...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0533', 533, 'Give thanks with a grateful heart', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'And now...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0533', 'verse', 1, 0, '[\"And now...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0534', 534, 'Children of the cross', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Children of the cross, a shining example,
children of the cross are singing His praise.
Children of the cross are silencing the enemy,
children of the cross are saying the Lord saves.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0534', 'verse', 1, 0, '[\"Children of the cross, a shining example,\",\"children of the cross are singing His praise.\",\"Children of the cross are silencing the enemy,\",\"children of the cross are saying the Lord saves.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0535', 535, 'Whoopah, wahey!', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'God loves me...
God loves me...
God loves me...
God loves me...
God loves us, whoopah, wahey!
God loves you.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0535', 'verse', 1, 0, '[\"God loves me...\",\"God loves me...\",\"God loves me...\",\"God loves me...\",\"God loves us, whoopah, wahey!\",\"God loves you.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0536', 536, 'God made me', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Your face may be black or white,
it doesn’t matter one bit –
God looks at you and announces
to the world:
‘What a star! What a picture!
What a hit!’
God made the chickens...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0536', 'verse', 4, 0, '[\"Your face may be black or white,\",\"it doesn’t matter one bit –\",\"God looks at you and announces\",\"to the world:\",\"‘What a star! What a picture!\",\"What a hit!’\",\"God made the chickens...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0537', 537, 'God with a loving heart', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'He is the God who shows He cares,
He is the one who’s always there,
He is the God with a loving heart.
He is the God whose praise we sing,
He is the Lord of everything,
He is the God with a loving heart.
He is the God with a loving heart.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0537', 'verse', 2, 0, '[\"He is the God who shows He cares,\",\"He is the one who’s always there,\",\"He is the God with a loving heart.\",\"He is the God whose praise we sing,\",\"He is the Lord of everything,\",\"He is the God with a loving heart.\",\"He is the God with a loving heart.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0538', 538, 'God’s love is big', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'God’s love is big! Big!
God’s love is great! Great!
God’s love is fab! Fab!
God’s love is strong! Strong!
God’s love is big! Great! Fab! Strong!
Big! Great! Fab! Strong!
Big! Great! Fab! Strong!
Big! Great! Fab! Strong!
Big! Great! Fab! Strong! Yaee!
God’s love is big...
ﾩ 2005 Vineyard Songs (UK/Eire), administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0538', 'chorus', 0, 0, '[\"God’s love is big! Big!\",\"God’s love is great! Great!\",\"God’s love is fab! Fab!\",\"God’s love is strong! Strong!\",\"God’s love is big! Great! Fab! Strong!\",\"Big! Great! Fab! Strong!\",\"Big! Great! Fab! Strong!\",\"Big! Great! Fab! Strong!\",\"Big! Great! Fab! Strong! Yaee!\",\"God’s love is big...\",\"ﾩ 2005 Vineyard Songs (UK\\/Eire), administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0539', 539, 'Good news', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Good news!
Jesus was born.
Good news!
He died on the cross.
Good news!
He rose again.
Good news!
He’s coming back soon.
Good news!
He’s coming back soon.
Good news!
He’s coming back soon!
ﾩ 1995 Mercy / Vineyard Publishing, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0539', 'verse', 1, 0, '[\"Good news!\",\"Jesus was born.\",\"Good news!\",\"He died on the cross.\",\"Good news!\",\"He rose again.\",\"Good news!\",\"He’s coming back soon.\",\"Good news!\",\"He’s coming back soon.\",\"Good news!\",\"He’s coming back soon!\",\"ﾩ 1995 Mercy \\/ Vineyard Publishing, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0540', 540, 'Grace is', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Mercy is when God does not
give us what we deserve.
Mercy is when God does not
give us what we deserve.
He does it because He loves us;
He does it because He loves us.
Mercy is when God does not
give us what we deserve.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0540', 'verse', 2, 0, '[\"Mercy is when God does not\",\"give us what we deserve.\",\"Mercy is when God does not\",\"give us what we deserve.\",\"He does it because He loves us;\",\"He does it because He loves us.\",\"Mercy is when God does not\",\"give us what we deserve.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0541', 541, 'Hallelujah, my Father', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Hallelujah, my Father,
for giving us Your Son;
sending Him into the world
to be given up for men,
knowing we would bruise Him
and smite Him from the earth.
Hallelujah, my Father,
in His death is my birth;
Hallelujah, my Father,
in His life is my life.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0541', 'verse', 1, 0, '[\"Hallelujah, my Father,\",\"for giving us Your Son;\",\"sending Him into the world\",\"to be given up for men,\",\"knowing we would bruise Him\",\"and smite Him from the earth.\",\"Hallelujah, my Father,\",\"in His death is my birth;\",\"Hallelujah, my Father,\",\"in His life is my life.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0542', 542, 'The greatest miracle', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'If we turn to Jesus and are sorry for our sin,
God’s word makes it plain for all to see:');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0542', 'verse', 2, 0, '[\"If we turn to Jesus and are sorry for our sin,\",\"God’s word makes it plain for all to see:\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0543', 543, 'How great is the love of God', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'How great is the love of God.
How great is the love of God.
How great, (how great,)
how great (how great).
It’s as great as great could ever be.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0543', 'verse', 4, 0, '[\"How great is the love of God.\",\"How great is the love of God.\",\"How great, (how great,)\",\"how great (how great).\",\"It’s as great as great could ever be.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0544', 544, 'Cast your burdens', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Cast your burdens onto Jesus,
He cares for you.
Cast your burdens onto Jesus,
He cares for you.
Higher, higher, higher, higher,
higher, higher, higher,
lift up Jesus higher.
Higher, higher...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0544', 'chorus', 0, 0, '[\"Cast your burdens onto Jesus,\",\"He cares for you.\",\"Cast your burdens onto Jesus,\",\"He cares for you.\",\"Higher, higher, higher, higher,\",\"higher, higher, higher,\",\"lift up Jesus higher.\",\"Higher, higher...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0545', 545, 'Holy, Lord, make us more holy', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Powerful, Lord, make us more powerful,
make us more like Jesus
than we’ve ever been before,
make us more like Jesus
than we’ve ever been before.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0545', 'verse', 3, 0, '[\"Powerful, Lord, make us more powerful,\",\"make us more like Jesus\",\"than we’ve ever been before,\",\"make us more like Jesus\",\"than we’ve ever been before.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0546', 546, 'I can do all, all, all things', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Pray and sing: all things.
Love our King: all things.
Everything: all things,
through Christ who strengthens me.
I can do all...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0546', 'verse', 3, 0, '[\"Pray and sing: all things.\",\"Love our King: all things.\",\"Everything: all things,\",\"through Christ who strengthens me.\",\"I can do all...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0547', 547, 'Child of grace', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I have called you ‘chosen one’.
And I have formed you in my hands.
Felt the warmth of your embrace, My child of grace.
For you are My beloved one.
I have called you by your name.
I am yours and you are Mine, My child of grace.
So come to Me with all your cares.
I see no guilt nor fear or shame.
As I look into your face, My child of grace.
For I am your Father and My love will never change.
I am yours and you are Mine, My child of grace.
I am yours and you are Mine, My child of grace.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0547', 'verse', 2, 0, '[\"I have called you ‘chosen one’.\",\"And I have formed you in my hands.\",\"Felt the warmth of your embrace, My child of grace.\",\"For you are My beloved one.\",\"I have called you by your name.\",\"I am yours and you are Mine, My child of grace.\",\"So come to Me with all your cares.\",\"I see no guilt nor fear or shame.\",\"As I look into your face, My child of grace.\",\"For I am your Father and My love will never change.\",\"I am yours and you are Mine, My child of grace.\",\"I am yours and you are Mine, My child of grace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0548', 548, 'All I know', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I don’t know how You stay the same
when all around is changing,
or why You always care for me,
no matter what I do.
I don’t know how You hear my prayer
when half the world is praying,
but You have promised me it’s true.
All I know is...
ﾩ 2004 Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0548', 'verse', 2, 0, '[\"I don’t know how You stay the same\",\"when all around is changing,\",\"or why You always care for me,\",\"no matter what I do.\",\"I don’t know how You hear my prayer\",\"when half the world is praying,\",\"but You have promised me it’s true.\",\"All I know is...\",\"ﾩ 2004 Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0549', 549, 'I love the sun', 'JP', 'en', 'control', '', 0, 0, 0, 1, 1, 'I love the birds,
they sing to me,
God made the birds,
and God made me.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0549', 'verse', 5, 0, '[\"I love the birds,\",\"they sing to me,\",\"God made the birds,\",\"and God made me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0550', 550, 'God knows my name', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Isn’t it good...
He will finish the work He has begun.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0550', 'verse', 1, 0, '[\"Isn’t it good...\",\"He will finish the work He has begun.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0551', 551, 'I may live in a great big city', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I may live in a great big city,
I may live in a village small,
I may live in a tiny house,
I may live in a tower tall,
I may live in the countryside,
I may live by the sea,
but wherever I live,
I know that Jesus also lives with me,
but wherever I live,
I know Jesus lives with me,
but wherever I live,
I know Jesus lives with me.
ﾩ 1998 Thankyou Music, administered by worshiptogether.com songs excl. UK and Europe, administered by kingswaysongs.com. tym@kingsway.co.uk. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0551', 'verse', 1, 0, '[\"I may live in a great big city,\",\"I may live in a village small,\",\"I may live in a tiny house,\",\"I may live in a tower tall,\",\"I may live in the countryside,\",\"I may live by the sea,\",\"but wherever I live,\",\"I know that Jesus also lives with me,\",\"but wherever I live,\",\"I know Jesus lives with me,\",\"but wherever I live,\",\"I know Jesus lives with me.\",\"ﾩ 1998 Thankyou Music, administered by worshiptogether.com songs excl. UK and Europe, administered by kingswaysongs.com. tym@kingsway.co.uk. Used by permission.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0552', 552, 'I was made to praise You', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I will always praise You,
I will always glorify Your name,
in every circumstance
I’ll find a chance to thank You.
I will always love You,
I will always worship at Your feet,
and I’ll obey You, Lord,
I was made for You.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0552', 'verse', 2, 0, '[\"I will always praise You,\",\"I will always glorify Your name,\",\"in every circumstance\",\"I’ll find a chance to thank You.\",\"I will always love You,\",\"I will always worship at Your feet,\",\"and I’ll obey You, Lord,\",\"I was made for You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0553', 553, 'The best gift', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I’ll share my secrets and my dreams, I’ll show You wonders I have seen,
and I will listen when You speak Your name;
and if You really want me to, I will share my friends with You,
everyone at home and in my school.
I will bring to You...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0553', 'verse', 3, 0, '[\"I’ll share my secrets and my dreams, I’ll show You wonders I have seen,\",\"and I will listen when You speak Your name;\",\"and if You really want me to, I will share my friends with You,\",\"everyone at home and in my school.\",\"I will bring to You...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0554', 554, 'I reach up high', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'May my whole life be a song of praise,
to worship God in every way.
In this song the actions praise His name,
I want my actions every day to do the same.
I reach up high...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0554', 'verse', 2, 0, '[\"May my whole life be a song of praise,\",\"to worship God in every way.\",\"In this song the actions praise His name,\",\"I want my actions every day to do the same.\",\"I reach up high...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0555', 555, 'I’m gonna clap my hands', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'You are the best friend that I could ever know.
I lift my hands to You
’cause You died for me upon the cross.
You took away my sin and shame.
I’m gonna clap my hands...
ﾩ 2001 Vineyard Songs (UK/Eire), administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0555', 'chorus', 0, 0, '[\"You are the best friend that I could ever know.\",\"I lift my hands to You\",\"’cause You died for me upon the cross.\",\"You took away my sin and shame.\",\"I’m gonna clap my hands...\",\"ﾩ 2001 Vineyard Songs (UK\\/Eire), administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0556', 556, 'I’m gonna click', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'I’m gonna click, click, click,
I’m gonna clap, clap, clap,
I’m gonna zoom around the room and praise the Lord!
Because of all He’s done, I’m gonna make Him ‘number one’,
I’m gonna sing, I’m gonna shout and praise the Lord!
ﾩ 1991 Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0556', 'verse', 4, 0, '[\"I’m gonna click, click, click,\",\"I’m gonna clap, clap, clap,\",\"I’m gonna zoom around the room and praise the Lord!\",\"Because of all He’s done, I’m gonna make Him ‘number one’,\",\"I’m gonna sing, I’m gonna shout and praise the Lord!\",\"ﾩ 1991 Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0557', 557, 'So cool', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'RAP
Worship Jesus, worship the King,
He is the Lord of everything.
He is the one who hears me every day,
He never ever leaves me and so I will say,
Jesus! He’s the King of kings,
Jesus! He’s the King of kings,
Jesus! He’s the King of kings.
Let’s get ready to sing 2, 3, 4...
I’m gonna worship...
ﾩ 1995 Scripture Union');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0557', 'verse', 3, 0, '[\"RAP\",\"Worship Jesus, worship the King,\",\"He is the Lord of everything.\",\"He is the one who hears me every day,\",\"He never ever leaves me and so I will say,\",\"Jesus! He’s the King of kings,\",\"Jesus! He’s the King of kings,\",\"Jesus! He’s the King of kings.\",\"Let’s get ready to sing 2, 3, 4...\",\"I’m gonna worship...\",\"ﾩ 1995 Scripture Union\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0558', 558, 'David and Goliath', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Well, Goliath, you can fight me with your spear and with your sword,
but I come against you in the name of the Lord!
And everyone who gathers here will understand
the battle is the Lord’s and it’s in our hands,
the battle is the Lord’s and it’s in our hands!
Well, who’s gonna win,...
ﾩ 1996 Thankyou Music, administered by worshiptogether.com songs excl. UK and Europe, administered by kingswaysongs.com. tym@kingsway.co.uk. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0558', 'verse', 4, 0, '[\"Well, Goliath, you can fight me with your spear and with your sword,\",\"but I come against you in the name of the Lord!\",\"And everyone who gathers here will understand\",\"the battle is the Lord’s and it’s in our hands,\",\"the battle is the Lord’s and it’s in our hands!\",\"Well, who’s gonna win,...\",\"ﾩ 1996 Thankyou Music, administered by worshiptogether.com songs excl. UK and Europe, administered by kingswaysongs.com. tym@kingsway.co.uk. Used by permission.\"]');
