INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0560', 560, 'He’ll be there', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Oh yeah! (He’ll be there)
