INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0561', 'verse', 1, 0, '[\"PART 3\",\"Count your blessings,\",\"name then one by one,\",\"count your blessings,\",\"see what God has done!\",\"ﾩ 1998 Out of the Ark Music Sefton House, 2 Molesey Road, Walton-On-Thames, KT12 4RQ. Used by permission\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0562', 562, 'Creation Song', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'On day seven, God took a rest,
after making animals, humans, fish and birds, sun, moon,
stars, land, plants, seeds, sea and sky, light,
and God was pleased with all He made.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0562', 'verse', 1, 0, '[\"On day seven, God took a rest,\",\"after making animals, humans, fish and birds, sun, moon,\",\"stars, land, plants, seeds, sea and sky, light,\",\"and God was pleased with all He made.\"]');
