INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0564', 564, 'Never, never, never', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus never, never, never turned anyone away.
No! No! No!
Jesus never, never, never turned anyone away.
He never, never, never, never,
never, never, never, never,
never, never, never, never, never
turned anyone away.
No, He never, never, never, never,
never, never, never, never,
never, never, never, never, never
turned anyone away.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0564', 'verse', 1, 0, '[\"Jesus never, never, never turned anyone away.\",\"No! No! No!\",\"Jesus never, never, never turned anyone away.\",\"He never, never, never, never,\",\"never, never, never, never,\",\"never, never, never, never, never\",\"turned anyone away.\",\"No, He never, never, never, never,\",\"never, never, never, never,\",\"never, never, never, never, never\",\"turned anyone away.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0565', 565, 'Jesus is the lighthouse', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Shine your light in me, Lord, I want to live for You,
help me shine for You, Lord, in all I say and do.
I want to be a lighthouse for Jesus every day,
help me make a difference in Your world, I pray!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0565', 'verse', 3, 0, '[\"Shine your light in me, Lord, I want to live for You,\",\"help me shine for You, Lord, in all I say and do.\",\"I want to be a lighthouse for Jesus every day,\",\"help me make a difference in Your world, I pray!\"]');
