INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0568', 568, 'Firm foundation', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Your word is faithful, (Your word is faithful,)
