INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0569', 569, 'In Your name', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'In Your name the blind will see.
