INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0573', 573, 'Lord of the harvest', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'So in all our plenty, help us to see,
the needs all around whatever they be.
