INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0575', 575, 'Shine, Jesus, shine', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'As we gaze on Your kingly brightness
