INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0576', 576, 'Love the Lord your God', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Love the Lord your God with all your heart,
