INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0577', 577, 'Make a joyful noise', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Make a joyful noise to the Lord,
make a joyful noise and sing out loud,
make a joyful noise to the Lord,
sing, sing to the Lord.
Hallelujah, hallelujah,
hallelujah, sing out loud.
Hallelujah, sing, sing to the Lord.');
