INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0579', 579, 'Song of blessing', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'May God bless our teachers,
and all our helpers,
may God show His goodness in all that they do.
We ask for the children,
that God’s hand be on them,
and may we find His peace in this school.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0579', 'verse', 1, 0, '[\"May God bless our teachers,\",\"and all our helpers,\",\"may God show His goodness in all that they do.\",\"We ask for the children,\",\"that God’s hand be on them,\",\"and may we find His peace in this school.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0580', 580, 'May the God of hope', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Father God, I love You...');
