INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0581', 581, 'Shout to the Lord', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'My Jesus, my Saviour,
Lord, there is none like You.
All of my days I want to praise
the wonders of Your mighty love.
My comfort, my shelter,
tower of refuge and strength,
let every breath, all that I am,
never cease to worship You.
Shout to the Lord all the earth, let us sing,
power and majesty, praise to the King.
Mountains bow down and the seas will roar
at the sound of Your name.
I sing for joy at the work of Your hands,
for ever I’ll love You, for ever I’ll stand.
Nothing compares to the promise I have in You.
ﾩ 1993 Hillsong Publishing / Kingsway Music. tym@kingsway.co.uk. For the UK. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0581', 'chorus', 0, 0, '[\"My Jesus, my Saviour,\",\"Lord, there is none like You.\",\"All of my days I want to praise\",\"the wonders of Your mighty love.\",\"My comfort, my shelter,\",\"tower of refuge and strength,\",\"let every breath, all that I am,\",\"never cease to worship You.\",\"Shout to the Lord all the earth, let us sing,\",\"power and majesty, praise to the King.\",\"Mountains bow down and the seas will roar\",\"at the sound of Your name.\",\"I sing for joy at the work of Your hands,\",\"for ever I’ll love You, for ever I’ll stand.\",\"Nothing compares to the promise I have in You.\",\"ﾩ 1993 Hillsong Publishing \\/ Kingsway Music. tym@kingsway.co.uk. For the UK. Used by permission.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0582', 582, 'I’m made in the image of God', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'No matter how big I am,
no matter how small I am.
I could never look odd.
The Lord wants me to know,
that the Bible says it’s so,
I’m made in the image of God.
ﾩ 2001 Thankyou Music, administered by worshiptogether.com songs excl. UK and Europe, administered by kingswaysongs.com. tym@kingsway.co.uk. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0582', 'verse', 1, 0, '[\"No matter how big I am,\",\"no matter how small I am.\",\"I could never look odd.\",\"The Lord wants me to know,\",\"that the Bible says it’s so,\",\"I’m made in the image of God.\",\"ﾩ 2001 Thankyou Music, administered by worshiptogether.com songs excl. UK and Europe, administered by kingswaysongs.com. tym@kingsway.co.uk. Used by permission.\"]');
