INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0584', 584, 'Anyway', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Everything I do,
everything I say,
in every moment, every hour,
teach me, Lord, Your way.
