INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0586', 586, 'O Lord, my God', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'O Lord, my God, to You I give my hands;
O Lord, my God, to You I give my feet;
O Lord, my God, to You I give my everything;
O Lord, my God, to You I give my life.
In You...
Let the praises ring.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0586', 'verse', 2, 0, '[\"O Lord, my God, to You I give my hands;\",\"O Lord, my God, to You I give my feet;\",\"O Lord, my God, to You I give my everything;\",\"O Lord, my God, to You I give my life.\",\"In You...\",\"Let the praises ring.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0587', 587, 'Oi, oi, we are gonna praise the Lord', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Oi, oi, we are gonna praise the Lord.
Oi, oi, we are gonna praise the Lord.
Oi, oi, we are gonna praise the Lord.
He’s an exciting, powerising,
c-colossal, humungousmungous God!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0587', 'verse', 1, 0, '[\"Oi, oi, we are gonna praise the Lord.\",\"Oi, oi, we are gonna praise the Lord.\",\"Oi, oi, we are gonna praise the Lord.\",\"He’s an exciting, powerising,\",\"c-colossal, humungousmungous God!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0588', 588, 'Open the eyes of my heart', 'JP', 'en', '© 1997 Integrity\'s Hosanna! Music (admin by CAPITOL CMG Publishing worldwide excl. the UK which is admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com) Used by Permission', '', 0, 0, 0, 1, 1, 'Open the eyes of my heart, Lord,
open the eyes of my heart.
I want to see You,
I want to see You.
Open the eyes of my heart, Lord,
open the eyes of my heart.
I want to see You,
I want to see You.
To see You high and lifted up,
shining in the light of Your glory.
Pour out Your power and love,
as we sing, ‘Holy, holy, holy.’
Open the eyes of my heart, Lord...
To see You high and lifted up...
Holy, holy, holy,
holy, holy, holy,
holy, holy, holy,
I want to see You.
Holy, holy, holy...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0588', 'chorus', 0, 0, '[\"Open the eyes of my heart, Lord,\",\"open the eyes of my heart.\",\"I want to see You,\",\"I want to see You.\",\"Open the eyes of my heart, Lord,\",\"open the eyes of my heart.\",\"I want to see You,\",\"I want to see You.\",\"To see You high and lifted up,\",\"shining in the light of Your glory.\",\"Pour out Your power and love,\",\"as we sing, ‘Holy, holy, holy.’\",\"Open the eyes of my heart, Lord...\",\"To see You high and lifted up...\",\"Holy, holy, holy,\",\"holy, holy, holy,\",\"holy, holy, holy,\",\"I want to see You.\",\"Holy, holy, holy...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0589', 589, 'Our God is a great big God', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'He’s higher than a skyscraper
and He’s deeper than a submarine.
He’s wider than the universe
and beyond my wildest dreams.
And He’s known me and He’s loved me
since before the world began.
How wonderful to be a part
of God’s amazing plan.
Our God is a great big God...
And He holds us in His hands.
ﾩ 2001 Vineyard Songs (UK/Eire), administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0589', 'chorus', 0, 0, '[\"He’s higher than a skyscraper\",\"and He’s deeper than a submarine.\",\"He’s wider than the universe\",\"and beyond my wildest dreams.\",\"And He’s known me and He’s loved me\",\"since before the world began.\",\"How wonderful to be a part\",\"of God’s amazing plan.\",\"Our God is a great big God...\",\"And He holds us in His hands.\",\"ﾩ 2001 Vineyard Songs (UK\\/Eire), administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0590', 590, 'Peace, perfect peace', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Joy, perfect joy, is the gift of Christ our Lord.
Joy, perfect joy, is the gift of Christ our Lord.
Thus, says the Lord, will the world know My friends.
Joy, perfect joy, is the gift of Christ our Lord.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0590', 'verse', 5, 0, '[\"Joy, perfect joy, is the gift of Christ our Lord.\",\"Joy, perfect joy, is the gift of Christ our Lord.\",\"Thus, says the Lord, will the world know My friends.\",\"Joy, perfect joy, is the gift of Christ our Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0591', 591, 'There isn’t any room', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Rat-a-tat-tat, rat-a-tat-tat,
Yes! Yes! Yes!
There is a little room
and you may stay here,
we have a little place for strangers.
Come in from the night
to the stable so bare
which is full of warmth and friendliness
and safe from dangers.
Yes, there is a little room,
there is a little room,
there is a little room for strangers.
ﾩ A & C Black Publishers Ltd, 38 Soho Square, London W1D 3HB.');
