INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0593', 593, 'God has got a plan', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'God was, and God is with me here,
