INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0596', 596, 'Sometimes I wonder', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Where there is heartache,
