INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0597', 597, 'Stop, look and listen', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Let’s listen to the Spirit
