INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0598', 598, 'Shalom', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'Shalom, shalom,
may peace be with you
