INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0601', 601, 'Black and white', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'The world is black,
the world is white,
it turns by day and then by night,
it turns by night.
It turns so each and every one
can take his station in the sun,
in the sun:
the world is black,
the world is white,
it turns by day and then by night,
it turns by night.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0601', 'verse', 4, 0, '[\"The world is black,\",\"the world is white,\",\"it turns by day and then by night,\",\"it turns by night.\",\"It turns so each and every one\",\"can take his station in the sun,\",\"in the sun:\",\"the world is black,\",\"the world is white,\",\"it turns by day and then by night,\",\"it turns by night.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0602', 602, 'Surrounded by His love', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'The Lord is my Shepherd,
He’s gentle and strong.
I know in His presence
I’ll always belong.
The peace that He gives me
is more than enough.
I will live my life
surrounded by His love.
And I will sing...
Surely...
ﾩ 1997 Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0602', 'verse', 3, 0, '[\"The Lord is my Shepherd,\",\"He’s gentle and strong.\",\"I know in His presence\",\"I’ll always belong.\",\"The peace that He gives me\",\"is more than enough.\",\"I will live my life\",\"surrounded by His love.\",\"And I will sing...\",\"Surely...\",\"ﾩ 1997 Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.\"]');
