INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0604', 604, 'The Lord’s my shepherd', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'The Lord invites me,
He’s prepared a feast,
The Lord invites me
in the presence of my enemies,
the Lord invites me,
His anointed guest,
to Him be all the glory, all the praise!
Surely His love...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0604', 'chorus', 0, 0, '[\"The Lord invites me,\",\"He’s prepared a feast,\",\"The Lord invites me\",\"in the presence of my enemies,\",\"the Lord invites me,\",\"His anointed guest,\",\"to Him be all the glory, all the praise!\",\"Surely His love...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0605', 605, 'More or less', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'There’s nothing, nothing I can do or say
to make God love me less.
I need forgiveness every day,
and Jesus’ righteousness.
But when I turn to Him and pray
He gives His mercy right away,
there’s nothing, nothing I can do or say
to make God love me less,
to make God love me less.
To make God love me more,
to make God love me more.
ﾩ 1999 Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('JP-0605', 'verse', 2, 0, '[\"There’s nothing, nothing I can do or say\",\"to make God love me less.\",\"I need forgiveness every day,\",\"and Jesus’ righteousness.\",\"But when I turn to Him and pray\",\"He gives His mercy right away,\",\"there’s nothing, nothing I can do or say\",\"to make God love me less,\",\"to make God love me less.\",\"To make God love me more,\",\"to make God love me more.\",\"ﾩ 1999 Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('JP-0606', 606, 'Smile', 'JP', 'en', '', '', 0, 0, 0, 1, 1, 'We want to see mile after mile of smiles,
we want to see mile after mile of smiles.
ﾩ 2005 Daybreak Music Ltd, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.');
