INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0025', 'verse', 2, 1, '[\"All to Jesus I surrender,\",\"humbly at His feet I bow;\",\"worldly pleasures all forsaken,\",\"take me, Jesus, take me now.\",\"I surrender all...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0025', 'verse', 3, 2, '[\"All to Jesus I surrender,\",\"make me, Saviour, wholly Thine;\",\"let me feel the Holy Spirit,\",\"truly know that Thou art mine.\",\"I surrender all...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0025', 'verse', 4, 3, '[\"All to Jesus I surrender,\",\"Lord, I give myself to Thee;\",\"fill me with Thy love and power,\",\"let Thy blessing fall on me.\",\"I surrender all...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0025', 'verse', 5, 4, '[\"All to Jesus I surrender,\",\"now I feel the sacred flame;\",\"O the joy of full salvation!\",\"Glory, glory to His name!\",\"I surrender all...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0026', 26, 'All you that pass by', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'All you that pass by,
to Jesus draw nigh;
to you is it nothing that Jesus should die?
Your ransom and peace,
your surety He is,
come, see if there ever was sorrow like His.
He dies to atone
for sins not His own.
Your debt He has paid and your work He has done:
you all may receive
the peace He did leave,
who made intercession, ‘My Father, forgive.’
For you and for me
He prayed on the tree:
the prayer is accepted, the sinner is free.
The sinner am I,
who on Jesus rely,
and come for the pardon God cannot deny.
His death is my plea;
my advocate see,
and hear the blood speak that has answered for me:
He purchased the grace
which now I embrace;
O Father, You know Jesus died in my place!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0026', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0026', 'William Knapp');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0026', 'verse', 1, 0, '[\"All you that pass by,\",\"to Jesus draw nigh;\",\"to you is it nothing that Jesus should die?\",\"Your ransom and peace,\",\"your surety He is,\",\"come, see if there ever was sorrow like His.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0026', 'verse', 2, 1, '[\"He dies to atone\",\"for sins not His own.\",\"Your debt He has paid and your work He has done:\",\"you all may receive\",\"the peace He did leave,\",\"who made intercession, ‘My Father, forgive.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0026', 'verse', 3, 2, '[\"For you and for me\",\"He prayed on the tree:\",\"the prayer is accepted, the sinner is free.\",\"The sinner am I,\",\"who on Jesus rely,\",\"and come for the pardon God cannot deny.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0026', 'verse', 4, 3, '[\"His death is my plea;\",\"my advocate see,\",\"and hear the blood speak that has answered for me:\",\"He purchased the grace\",\"which now I embrace;\",\"O Father, You know Jesus died in my place!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0027', 27, 'Almighty God, we bring You praise', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'Almighty God, we bring You praise
for Your Son, the Word of God;
by whose power the world was made,
by whose blood we are redeemed.
Morning Star, the Father’s glory,
we now worship and adore You;
in our hearts Your light has risen;
Jesus, Lord, we worship You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0027', 'Austin Martin');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0027', 'Austin Martin');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0027', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0027', 'verse', 1, 0, '[\"Almighty God, we bring You praise\",\"for Your Son, the Word of God;\",\"by whose power the world was made,\",\"by whose blood we are redeemed.\",\"Morning Star, the Father’s glory,\",\"we now worship and adore You;\",\"in our hearts Your light has risen;\",\"Jesus, Lord, we worship You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0028', 28, 'Almighty God, our heavenly Father', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'Almighty God, our heavenly Father,
we have sinned against You
and against our fellow men,
in thought and word and deed,
through negligence, through weakness,
through our own deliberate fault.
We are truly sorry,
and repent of all our sins.
For the sake of Your Son Jesus Christ,
who died for us, who died for us, who died for us,
forgive us all that is past;
and grant that we may serve You
in newness of life
Words from the Archbishops’ Council');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0028', 'Chris Rolinson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0028', 'verse', 1, 0, '[\"Almighty God, our heavenly Father,\",\"we have sinned against You\",\"and against our fellow men,\",\"in thought and word and deed,\",\"through negligence, through weakness,\",\"through our own deliberate fault.\",\"We are truly sorry,\",\"and repent of all our sins.\",\"For the sake of Your Son Jesus Christ,\",\"who died for us, who died for us, who died for us,\",\"forgive us all that is past;\",\"and grant that we may serve You\",\"in newness of life\",\"Words from the Archbishops’ Council\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0029', 29, 'Alleluia', 'MP', 'en', 'control                        arrangement ? 1971 Celebration / kingswaysongs.com. tym@kingsway.co.uk. For Europe and Commonwealth (excl. Canada, Australasia and Africa). Used by permission.', '', 0, 0, 0, 1, 0, 'Alleluia (8 times)
How I love Him...
Blessèd Jesus...
My Redeemer...
Jesus is Lord...
Alleluia...');
