INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0030', 'verse', 1, 1, '[\"Jesus is Lord of all the earth,\",\"He is the King of creation.\",\"Alleluia, alleluia...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0030', 'verse', 2, 2, '[\"Spread the good news o’er all the earth,\",\"Jesus has died and has risen.\",\"Alleluia, alleluia...\"]');
