INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0035', 35, 'Angels from the realms of glory', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Angels from the realms of glory,
wing your flight through all the earth;
heralds of creation’s story
now proclaim Messiah’s birth!
Come and worship
Christ, the new-born King;
come and worship,
worship Christ the new-born King.
Shepherds in the fields abiding,
watching by your flocks at night,
God with man is now residing:
see, there shines the infant light!
Come and worship...
Wise men, leave your contemplations!
brighter visions shine afar;
seek in Him the hope of nations,
you have seen His rising star:
Come and worship...
Though an infant now we view Him,
He will share His Father’s throne,
gather all the nations to Him;
every knee shall then bow down:
Come and worship...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0035', 'James Montgomery');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0035', 'verse', 1, 0, '[\"Angels from the realms of glory,\",\"wing your flight through all the earth;\",\"heralds of creation’s story\",\"now proclaim Messiah’s birth!\",\"Come and worship\",\"Christ, the new-born King;\",\"come and worship,\",\"worship Christ the new-born King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0035', 'verse', 2, 1, '[\"Shepherds in the fields abiding,\",\"watching by your flocks at night,\",\"God with man is now residing:\",\"see, there shines the infant light!\",\"Come and worship...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0035', 'verse', 3, 2, '[\"Wise men, leave your contemplations!\",\"brighter visions shine afar;\",\"seek in Him the hope of nations,\",\"you have seen His rising star:\",\"Come and worship...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0035', 'verse', 4, 3, '[\"Though an infant now we view Him,\",\"He will share His Father’s throne,\",\"gather all the nations to Him;\",\"every knee shall then bow down:\",\"Come and worship...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0036', 36, 'Arise, shine', 'MP', 'en', '©  1985 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 1, 'Behold, the darkness shall cover the earth,
and gross darkness the people;
but the Lord shall arise upon thee,
and His glory shall be seen upon thee.
Arise, shine; for thy light is come,
and the glory of the Lord is risen.
O arise, shine; for thy light is come,
and the glory of the Lord is upon thee.
The Gentiles shall come to thy light,
and kings to the brightness of thy rising:
and they shall call thee the city of the Lord,
the Zion of the Holy One of Israel.
Arise, shine...
Lift up thine eyes round about and see,
they gather themselves together;
and they shall come, thy sons from afar,
and thy daughters shall be nursed at thy side.
Arise, shine...
Then shalt thou see and flow together,
and thy heart shall be enlarged;
the abundance of the sea is converted unto thee,
and the nations shall come unto thee.
Arise, shine...
The sun shall no more go down,
neither shall the moon withdraw itself;
but the Lord shall be thine everlasting light,
and the days of thy mourning shall be ended.
Arise, shine...');
