INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0038', 38, 'As we are gathered', 'MP', 'en', '(c) 1979 Authentic Publishing/Adm. by Integritymusic.com, a  division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 1, 'As we are gathered, Jesus is here,
one with each other, Jesus is here;
joined by the Spirit, washed in His blood,
part of the body, the Church of God.
As we are gathered, Jesus is here,
one with each other, Jesus is here.');
