INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0044', 44, 'At Your feet, O Lord', 'MP', 'en', '1983 Christian Fellowship of Columbia, 4600 Christian Fellowship Road, Columbia, MS 65203, USA', '', 0, 0, 0, 1, 1, 'At Your feet, O Lord, we wait for You,
yearning, Lord, hungry, Lord, for more of You.
Bowed before You, Lord, we desire only You:
