INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0045', 'verse', 2, 1, '[\"There we see You stand, mighty risen Lord,\",\"clothed in garments pure and holy, shining bright;\",\"eyes of flashing fire, feet like burnished bronze,\",\"and the sound of many waters is Your voice.\",\"‘I am He that liveth” “’...\"]');
