INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0046', 46, 'Awake, awake, O Zion', 'MP', 'en', '(c) 1982 Authentic Publishing/Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 1, 'Awake, awake, O Zion,
come clothe yourself with strength.
Awake, awake, O Zion,
come clothe yourself with strength.
Put on your garments of splendour,
O Jerusalem;
come sing your songs of joy and triumph,
see that your God reigns.
Awake, awake...
Burst into songs of joy together,
O Jerusalem;
the Lord has comforted His people,
the redeemed Jerusalem.
Awake, awake...');
