INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0048', 48, 'Be still and know', 'MP', 'en', 'control                        arrangement: ? 1983 Roland Fudge', '', 0, 0, 0, 1, 1, 'Be still and know that I am God.
