INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0049', 49, 'Be bold, be strong', 'MP', 'en', '1984 Word Music LLC/Admin. by Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Be bold, be strong,
for the Lord your God is with you;
be bold, be strong,
for the Lord your God is with you!
I am not afraid, (No! No! No!)
I am not dismayed, (Not me!)
for I’m walking in faith and victory:
come on and walk in faith and victory,
for the Lord your God is with you.');
