INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0052', 'verse', 2, 1, '[\"How sweet to hold a new-born baby,\",\"and feel the pride and joy he gives;\",\"but greater still the calm assurance,\",\"this child can face uncertain days because He lives.\",\"Because He lives...\"]');
