INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0053', 53, 'Because Your love is better than life', 'MP', 'en', '©  1981 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Because Your love is better than life,
with my lips I will glorify You;
I will praise You as long as I live,
in Your name I lift my hands.
Because Your Son has given me life,
with my lips I will glorify You,
I will praise You as long as I live,
in Your name I lift my hands.
Because Your Spirit is filling my life,
with my lips I will glorify You,
I will praise You as long as I live,
in Your name I lift my hands.
Because Your love is better than life,
with my lips I will glorify You,
I will praise You as long as I live,
in Your name I lift my hands.');
