INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0054', 54, 'Bind us together, Lord', 'MP', 'en', '©  1977 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Bind us together, Lord,
bind us together
with cords that cannot be broken;
bind us together, Lord,
bind us together,
O bind us together with love.
There is only one God,
there is only one King,
there is only one body –
that is why we sing:
Bind us together...
Made for the glory of God,
purchased by His precious Son.
Born with the right to be clean,
for Jesus the victory has won.
Bind us together...
You are the family of God,
You are the promise divine,
You are God’s chosen desire,
You are the glorious new wine.
Bind us together...');
