INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0055', 55, 'Beneath the cross of Jesus', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Beneath the cross of Jesus
I fain would take my stand –
the shadow of a mighty rock
within a weary land;
a home within a wilderness,
a rest upon the way,');
