INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0056', 56, 'Bless His holy name', 'MP', 'en', '1973 Bud John Songs/ CapitolCMGPublishing.com (adm UK/Eire Song Solutions www.songsolutions.org) All rights reserved. Used by permission.', '', 0, 0, 0, 1, 1, 'Bless the Lord, O my soul,
and all that is within me
bless His holy name.
He has done great things,
He has done great things,
He has done great things,
bless His holy name.
Bless the Lord, O my soul,
and all that is within me
bless His holy name.');
