INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0059', 59, 'Blessèd assurance', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Blessèd assurance, Jesus is mine:
O what a foretaste of glory divine!
Heir of salvation, purchase of God;
born of His Spirit, washed in His blood.
This is my story, this is my song,
praising my Saviour all the day long;
this is my story, this is my song,
praising my Saviour all the day long.
Perfect submission, perfect delight,
visions of rapture burst on my sight;
angels descending, bring from above
echoes of mercy, whispers of love.
This is my story...
Perfect submission, all is at rest,
I in my Saviour am happy and blest;
watching and waiting, looking above,
filled with His goodness, lost in His love.
This is my story...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0059', 'Fanny J Crosby');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0059', 'Phoebe Palmer Knapp');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0059', 'verse', 1, 0, '[\"Blessèd assurance, Jesus is mine:\",\"O what a foretaste of glory divine!\",\"Heir of salvation, purchase of God;\",\"born of His Spirit, washed in His blood.\",\"This is my story, this is my song,\",\"praising my Saviour all the day long;\",\"this is my story, this is my song,\",\"praising my Saviour all the day long.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0059', 'verse', 2, 1, '[\"Perfect submission, perfect delight,\",\"visions of rapture burst on my sight;\",\"angels descending, bring from above\",\"echoes of mercy, whispers of love.\",\"This is my story...\"]');
