INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0060', 60, 'Blest be the tie that binds', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Blest be the tie that binds
our hearts in Christian love;
the fellowship of kindred minds
is like to that above.
Before our Father’s throne
we pour our ardent prayers;
our fears, our hopes, our aims are one,
our comforts and our cares.
We share our mutual woes,
our mutual burdens bear,
and often for each other flows
the sympathizing tear.
When for awhile we part,
this thought will soothe our pain,
that we shall still be joined in heart,
and hope to meet again.
This glorious hope revives
our courage by the way,
while each in expectation lives,
and longs to see the day.
From sorrow, toil, and pain,
and sin we shall be free;
and perfect love and friendship reign
through all eternity.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0060', 'John Fawcett');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0060', 'Johann G Nägeli');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0060', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0060', 'verse', 1, 0, '[\"Blest be the tie that binds\",\"our hearts in Christian love;\",\"the fellowship of kindred minds\",\"is like to that above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0060', 'verse', 2, 1, '[\"Before our Father’s throne\",\"we pour our ardent prayers;\",\"our fears, our hopes, our aims are one,\",\"our comforts and our cares.\"]');
