INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0061', 61, 'Born by the Holy Spirit’s breath', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Born by the Holy Spirit’s breath,
loosed from the law of sin and death,
now cleared in Christ from every claim
no judgement stands against our name.
In us the Spirit makes His home
that we in Him may overcome;
Christ’s risen life, in all its powers,
its all-prevailing strength, is ours.
Sons, then, and heirs of God most high,
we by His Spirit, ‘Father’ cry;
that Spirit with our spirit shares
to frame and breathe our wordless prayers.
One is His love, His purpose one:
to form the likeness of His Son
in all who, called and justified,
shall reign in glory at His side.
Nor death nor life, nor powers unseen,
nor height nor depth can come between;
we know through peril, pain and sword,
the love of God in Christ our Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0061', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0061', 'Noël Tredinnick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0061', 'verse', 1, 0, '[\"Born by the Holy Spirit’s breath,\",\"loosed from the law of sin and death,\",\"now cleared in Christ from every claim\",\"no judgement stands against our name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0061', 'verse', 2, 1, '[\"In us the Spirit makes His home\",\"that we in Him may overcome;\",\"Christ’s risen life, in all its powers,\",\"its all-prevailing strength, is ours.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0061', 'verse', 3, 2, '[\"Sons, then, and heirs of God most high,\",\"we by His Spirit, ‘Father’ cry;\",\"that Spirit with our spirit shares\",\"to frame and breathe our wordless prayers.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0061', 'verse', 4, 3, '[\"One is His love, His purpose one:\",\"to form the likeness of His Son\",\"in all who, called and justified,\",\"shall reign in glory at His side.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0061', 'verse', 5, 4, '[\"Nor death nor life, nor powers unseen,\",\"nor height nor depth can come between;\",\"we know through peril, pain and sword,\",\"the love of God in Christ our Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0062', 62, 'Born in the night', 'MP', 'en', '1973 Stainer & Bell Ltd www.stainer.co.uk', '', 0, 0, 0, 1, 1, 'Born in the night,
Mary’s child,
a long way from Your home;
coming in need,
Mary’s child,
born in a borrowed room.
Clear shining light,
Mary’s child,
Your face lights up our way:
light of the world,
Mary’s child,
dawn on our darkened day.
Truth of our life,
Mary’s child,
You tell us God is good:
prove it is true,
Mary’s child,
go to Your cross of wood.
Hope of the world,
Mary’s child,
You’re coming soon to reign:
King of the earth,
Mary’s child,
walk in our streets again.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0062', 'Geoffrey Ainger');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0062', 'Geoffrey Ainger');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0062', 'verse', 1, 0, '[\"Born in the night,\",\"Mary’s child,\",\"a long way from Your home;\",\"coming in need,\",\"Mary’s child,\",\"born in a borrowed room.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0062', 'verse', 2, 1, '[\"Clear shining light,\",\"Mary’s child,\",\"Your face lights up our way:\",\"light of the world,\",\"Mary’s child,\",\"dawn on our darkened day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0062', 'verse', 3, 2, '[\"Truth of our life,\",\"Mary’s child,\",\"You tell us God is good:\",\"prove it is true,\",\"Mary’s child,\",\"go to Your cross of wood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0062', 'verse', 4, 3, '[\"Hope of the world,\",\"Mary’s child,\",\"You’re coming soon to reign:\",\"King of the earth,\",\"Mary’s child,\",\"walk in our streets again.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0063', 63, 'Break forth into joy', 'MP', 'en', 'control                        arrangement: ? 1983 Roland Fudge', '', 0, 0, 0, 1, 1, 'Break forth into joy, O my soul;
break forth into joy, O my soul.
In the presence of the Lord
there is joy for evermore;
break forth, break forth into joy.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0063', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0063', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0063', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0063', 'verse', 1, 0, '[\"Break forth into joy, O my soul;\",\"break forth into joy, O my soul.\",\"In the presence of the Lord\",\"there is joy for evermore;\",\"break forth, break forth into joy.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0064', 64, 'Break Thou the bread of life', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Break Thou the bread of life,
dear Lord to me,
as Thou didst break the bread
beside the sea;
beyond the sacred page
I seek Thee, Lord;
my spirit longs for Thee,
Thou living Word!
Thou art the bread of life,
O Lord, to me,
Thy holy word the truth
that saveth me;
give me to eat and live
with Thee above,
teach me to love Thy truth,
for Thou art love.
O send Thy Spirit, Lord,
now unto me,
that He may touch my eyes,
and make me see;
show me the truth concealed
within Thy word,
and in Thy book revealed
I see Thee, Lord.
Bless Thou the bread of life
to me, to me,
as Thou didst bless the loaves
by Galilee;
then shall all bondage cease,
all fetters fall,
and I shall find my peace,
my all-in-all!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0064', 'Mary Artemisia Lathbury');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0064', 'Alexander Groves');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0064', 'William Fiske Sherwin');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0064', 'verse', 1, 0, '[\"Break Thou the bread of life,\",\"dear Lord to me,\",\"as Thou didst break the bread\",\"beside the sea;\",\"beyond the sacred page\",\"I seek Thee, Lord;\",\"my spirit longs for Thee,\",\"Thou living Word!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0064', 'verse', 2, 1, '[\"Thou art the bread of life,\",\"O Lord, to me,\",\"Thy holy word the truth\",\"that saveth me;\",\"give me to eat and live\",\"with Thee above,\",\"teach me to love Thy truth,\",\"for Thou art love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0064', 'verse', 3, 2, '[\"O send Thy Spirit, Lord,\",\"now unto me,\",\"that He may touch my eyes,\",\"and make me see;\",\"show me the truth concealed\",\"within Thy word,\",\"and in Thy book revealed\",\"I see Thee, Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0064', 'verse', 4, 3, '[\"Bless Thou the bread of life\",\"to me, to me,\",\"as Thou didst bless the loaves\",\"by Galilee;\",\"then shall all bondage cease,\",\"all fetters fall,\",\"and I shall find my peace,\",\"my all-in-all!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0065', 65, 'Brightest and best', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Brightest and best of the sons of the morning,
dawn on our darkness and lend us Thine aid;
star of the east, the horizon adorning,
guide where our infant Redeemer is laid.
Cold on His cradle the dew-drops are shining;
low lies His head with the beasts of the stall:
angels adore Him, in slumber reclining,
maker and monarch, and Saviour of all.
Say, shall we yield Him, in costly devotion,
odours of Edom, and offerings divine;
gems of the mountain, and pearls of the ocean,
myrrh from the forest, or gold from the mine?
Vainly we offer each ample oblation;
vainly with gifts would His favour secure;
richer by far is the heart’s adoration;
dearer to God are the prayers of the poor.
Brightest and best of the sons of the morning,
dawn on our darkness and lend us Thine aid;
star of the east, the horizon adorning,
guide where our infant Redeemer is laid.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0065', 'Reginald Heber');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0065', 'Joseph Francis Thrupp');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0065', 'verse', 1, 0, '[\"Brightest and best of the sons of the morning,\",\"dawn on our darkness and lend us Thine aid;\",\"star of the east, the horizon adorning,\",\"guide where our infant Redeemer is laid.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0065', 'verse', 2, 1, '[\"Cold on His cradle the dew-drops are shining;\",\"low lies His head with the beasts of the stall:\",\"angels adore Him, in slumber reclining,\",\"maker and monarch, and Saviour of all.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0065', 'verse', 3, 2, '[\"Say, shall we yield Him, in costly devotion,\",\"odours of Edom, and offerings divine;\",\"gems of the mountain, and pearls of the ocean,\",\"myrrh from the forest, or gold from the mine?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0065', 'verse', 4, 3, '[\"Vainly we offer each ample oblation;\",\"vainly with gifts would His favour secure;\",\"richer by far is the heart’s adoration;\",\"dearer to God are the prayers of the poor.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0065', 'verse', 5, 4, '[\"Brightest and best of the sons of the morning,\",\"dawn on our darkness and lend us Thine aid;\",\"star of the east, the horizon adorning,\",\"guide where our infant Redeemer is laid.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0066', 66, 'Broken for me', 'MP', 'en', 'Copyright 1978 Sovereign Music UK. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'Broken for me, broken for you,
the body of Jesus broken for you.
He offered His body, He poured out His soul,
Jesus was broken that we might be whole:
Broken for me...
Come to My table and with Me dine,
eat of My bread and drink of My wine:
Broken for me...
This is My body given for you,
eat it remembering I died for you:
Broken for me...
This is My blood I shed for you,
for your forgiveness, making you new:
Broken for me...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0066', 'Janet Lunt');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0066', 'Janet Lunt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0066', 'chorus', 0, 0, '[\"Broken for me, broken for you,\",\"the body of Jesus broken for you.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0066', 'verse', 1, 1, '[\"He offered His body, He poured out His soul,\",\"Jesus was broken that we might be whole:\",\"Broken for me...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0066', 'verse', 2, 2, '[\"Come to My table and with Me dine,\",\"eat of My bread and drink of My wine:\",\"Broken for me...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0066', 'verse', 3, 3, '[\"This is My body given for you,\",\"eat it remembering I died for you:\",\"Broken for me...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0066', 'verse', 4, 4, '[\"This is My blood I shed for you,\",\"for your forgiveness, making you new:\",\"Broken for me...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0067', 67, 'Breathe on me, breath of God', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Breathe on me, breath of God,
fill me with life anew,
that I may love what Thou dost love,
and do what Thou wouldst do.
Breathe on me, breath of God,
until my heart is pure,
until with Thee I will one will,
to do and to endure.
Breathe on me, breath of God,
till I am wholly Thine,
until this earthly part of me
glows with Thy fire divine.
Breathe on me, breath of God,
so shall I never die,
but live with Thee the perfect life
of Thine eternity.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0067', 'Edwin Hatch');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0067', 'Robert Jackson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0067', 'verse', 1, 0, '[\"Breathe on me, breath of God,\",\"fill me with life anew,\",\"that I may love what Thou dost love,\",\"and do what Thou wouldst do.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0067', 'verse', 2, 1, '[\"Breathe on me, breath of God,\",\"until my heart is pure,\",\"until with Thee I will one will,\",\"to do and to endure.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0067', 'verse', 3, 2, '[\"Breathe on me, breath of God,\",\"till I am wholly Thine,\",\"until this earthly part of me\",\"glows with Thy fire divine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0067', 'verse', 4, 3, '[\"Breathe on me, breath of God,\",\"so shall I never die,\",\"but live with Thee the perfect life\",\"of Thine eternity.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0068', 68, 'Cause me to come', 'MP', 'en', '1974 CCCM Music/Maranatha! Music/ Universal Music Publishing/Print licence adm UK Song Solutions Daybreak  www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Cause me to come to Thy river, O Lord, (3 times)
cause me to come, cause me to drink, cause me to live.
Cause me to drink from Thy river, O Lord, (3 times)
cause me to come, cause me to drink, cause me to live.
Cause me to live by Thy river, O Lord, (3 times)
cause me to come, cause me to drink, cause me to live.');
