INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0068', 'Edward R Miller');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0068', 'verse', 1, 0, '[\"Cause me to come to Thy river, O Lord, (3 times)\",\"cause me to come, cause me to drink, cause me to live.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0068', 'verse', 2, 1, '[\"Cause me to drink from Thy river, O Lord, (3 times)\",\"cause me to come, cause me to drink, cause me to live.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0068', 'verse', 3, 2, '[\"Cause me to live by Thy river, O Lord, (3 times)\",\"cause me to come, cause me to drink, cause me to live.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0069', 69, 'Change my heart, O God', 'MP', 'en', '1982 Mercy/Vineyard Publishing (Admin by Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Change my heart, O God,
make it ever true;
change my heart, O God,
may I be like You.
You are the potter,
I am the clay;
mould me and make me,
this is what I pray.
Change my heart, O God,
make it ever true;
change my heart, O God,
may I be like You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0069', 'Eddie Espinosa');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0069', 'Eddie Espinosa');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0069', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0069', 'verse', 1, 0, '[\"Change my heart, O God,\",\"make it ever true;\",\"change my heart, O God,\",\"may I be like You.\",\"You are the potter,\",\"I am the clay;\",\"mould me and make me,\",\"this is what I pray.\",\"Change my heart, O God,\",\"make it ever true;\",\"change my heart, O God,\",\"may I be like You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0070', 70, 'Children of Jerusalem', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Children of Jerusalem
sang the praise of Jesus’ name;
children, too, of modern days,
join to sing the Saviour’s praise:
Hark, hark, hark! while children’s voices sing,
hark, hark, hark! while children’s voices sing
loud hosannas, loud hosannas,
loud hosannas to our King.
We are taught to love the Lord,
we are taught to read His word,
we are taught the way to heaven;
praise for all to God be given:
Hark, hark, hark...
Parents, teachers, old and young,
all unite to swell the song;
higher and yet higher rise,
till hosannas reach the skies:
Hark, hark, hark...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0070', 'John Henley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0070', 'verse', 1, 0, '[\"Children of Jerusalem\",\"sang the praise of Jesus’ name;\",\"children, too, of modern days,\",\"join to sing the Saviour’s praise:\",\"Hark, hark, hark! while children’s voices sing,\",\"hark, hark, hark! while children’s voices sing\",\"loud hosannas, loud hosannas,\",\"loud hosannas to our King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0070', 'verse', 2, 1, '[\"We are taught to love the Lord,\",\"we are taught to read His word,\",\"we are taught the way to heaven;\",\"praise for all to God be given:\",\"Hark, hark, hark...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0070', 'verse', 3, 2, '[\"Parents, teachers, old and young,\",\"all unite to swell the song;\",\"higher and yet higher rise,\",\"till hosannas reach the skies:\",\"Hark, hark, hark...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0071', 71, 'Child in the manger', 'MP', 'en', 'control            arrangement: ? 1988 Phil Burt', '', 0, 0, 0, 1, 1, 'Child in the manger, infant of Mary,
outcast and stranger, Lord of all!
Child who inherits all our transgressions,
all our demerits on Him fall.
Once the most holy child of salvation
gentle and lowly lived below:
now as our glorious mighty Redeemer,
see Him victorious over each foe.
Prophets foretold Him, infant of wonder;
angels behold Him on His throne:
worthy our Saviour of all their praises;
happy for ever are His own.
Words after by Mary MacDonald');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0071', 'Lachlan Macbean');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0071', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0071', 'verse', 1, 0, '[\"Child in the manger, infant of Mary,\",\"outcast and stranger, Lord of all!\",\"Child who inherits all our transgressions,\",\"all our demerits on Him fall.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0071', 'verse', 2, 1, '[\"Once the most holy child of salvation\",\"gentle and lowly lived below:\",\"now as our glorious mighty Redeemer,\",\"see Him victorious over each foe.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0071', 'verse', 3, 2, '[\"Prophets foretold Him, infant of wonder;\",\"angels behold Him on His throne:\",\"worthy our Saviour of all their praises;\",\"happy for ever are His own.\",\"Words after by Mary MacDonald\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0072', 72, 'Christ is the answer', 'MP', 'en', 'Words and music by T W Maltby', '', 0, 0, 0, 1, 1, 'Christ is the answer to my every need;
Christ is the answer, He is my friend indeed.
Problems of life my spirit may assail,
with Christ my Saviour I need never fail,
for Christ is the answer to my need.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0072', 'verse', 1, 0, '[\"Christ is the answer to my every need;\",\"Christ is the answer, He is my friend indeed.\",\"Problems of life my spirit may assail,\",\"with Christ my Saviour I need never fail,\",\"for Christ is the answer to my need.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0073', 73, 'Christ is made the sure foundation', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Christ is made the sure foundation,
Christ the head and corner-stone
chosen of the Lord and precious,
binding all the Church in one;
holy Zion’s help for ever,
and her confidence alone.
All within that holy city
dearly loved of God on high,
in exultant jubilation
sing, in perfect harmony;
God the One-in-Three adoring
in glad hymns eternally.
We as living stones invoke you:
Come among us, Lord, today!
with Your gracious loving-kindness
hear Your children as we pray;
and the fulness of Your blessing
in our fellowship display.
Here entrust to all Your servants
what we long from You to gain –
that on earth and in the heavens
we one people shall remain,
till united in Your glory
evermore with You we reign.
Praise and honour to the Father,
praise and honour to the Son,
praise and honour to the Spirit,
ever Three and ever One:
one in power and one in glory
while eternal ages run.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0073', 'John Mason Neale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0073', 'Henry Purcell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0073', 'verse', 1, 0, '[\"Christ is made the sure foundation,\",\"Christ the head and corner-stone\",\"chosen of the Lord and precious,\",\"binding all the Church in one;\",\"holy Zion’s help for ever,\",\"and her confidence alone.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0073', 'verse', 2, 1, '[\"All within that holy city\",\"dearly loved of God on high,\",\"in exultant jubilation\",\"sing, in perfect harmony;\",\"God the One-in-Three adoring\",\"in glad hymns eternally.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0073', 'verse', 3, 2, '[\"We as living stones invoke you:\",\"Come among us, Lord, today!\",\"with Your gracious loving-kindness\",\"hear Your children as we pray;\",\"and the fulness of Your blessing\",\"in our fellowship display.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0073', 'verse', 4, 3, '[\"Here entrust to all Your servants\",\"what we long from You to gain –\",\"that on earth and in the heavens\",\"we one people shall remain,\",\"till united in Your glory\",\"evermore with You we reign.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0073', 'verse', 5, 4, '[\"Praise and honour to the Father,\",\"praise and honour to the Son,\",\"praise and honour to the Spirit,\",\"ever Three and ever One:\",\"one in power and one in glory\",\"while eternal ages run.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0074', 74, 'Christ is risen! hallelujah', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Christ is risen! hallelujah!
risen our victorious Head;
sing His praises; hallelujah!
Christ is risen from the dead.
Gratefully our hearts adore Him,
as His light once more appears;
bowing down in joy before Him,
rising up from grief and tears.
Christ is risen! hallelujah!
risen our victorious Head;
sing His praises; hallelujah!
Christ is risen from the dead.
Christ is risen! all the sadness
of His earthly life is o’er;
through the open gates of gladness
He returns to life once more.
Death and hell before Him bending,
He doth rise the victor now,
angels on His steps attending,
glory round His wounded brow.
Christ is risen...
Christ is risen! henceforth never
death or hell shall us enthral;
we are Christ’s, in Him for ever
we have triumphed over all;
all the doubting and dejection
of our trembling hearts have ceased.
’Tis His day of resurrection;
let us rise and keep the feast.
Christ is risen...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0074', 'John Samuel Bewley Monsell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0074', 'Frederick Charles Maker');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0074', 'verse', 1, 0, '[\"Christ is risen! hallelujah!\",\"risen our victorious Head;\",\"sing His praises; hallelujah!\",\"Christ is risen from the dead.\",\"Gratefully our hearts adore Him,\",\"as His light once more appears;\",\"bowing down in joy before Him,\",\"rising up from grief and tears.\",\"Christ is risen! hallelujah!\",\"risen our victorious Head;\",\"sing His praises; hallelujah!\",\"Christ is risen from the dead.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0074', 'verse', 2, 1, '[\"Christ is risen! all the sadness\",\"of His earthly life is o’er;\",\"through the open gates of gladness\",\"He returns to life once more.\",\"Death and hell before Him bending,\",\"He doth rise the victor now,\",\"angels on His steps attending,\",\"glory round His wounded brow.\",\"Christ is risen...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0074', 'verse', 3, 2, '[\"Christ is risen! henceforth never\",\"death or hell shall us enthral;\",\"we are Christ’s, in Him for ever\",\"we have triumphed over all;\",\"all the doubting and dejection\",\"of our trembling hearts have ceased.\",\"’Tis His day of resurrection;\",\"let us rise and keep the feast.\",\"Christ is risen...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0075', 75, 'Christ is surely coming', 'MP', 'en', 'Christopher Idle/The Jubilate Group. www.jubilate.co.uk. Used with permission', '', 0, 0, 0, 1, 1, 'Christ is surely coming, bringing His reward,
Alpha and Omega, First and Last and Lord:
root and stem of David, brilliant Morning Star –
Meet your Judge and Saviour, nations near and far;
meet your Judge and Saviour, nations near and far!
See the holy city! There they enter in,
all by Christ made holy, washed from every sin:
thirsty ones, desiring all He loves to give,
Come for living water, freely drink, and live;
come for living water, freely drink, and live!
Grace be with God’s people! Praise His holy name!
Father, Son, and Spirit, evermore the same:
hear the certain promise from the eternal home:
‘Surely I come quickly!’ – Come, Lord Jesus, come;
‘Surely I come quickly!’ – Come, Lord Jesus, come!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0075', 'Christopher Idle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0075', 'Edward Elgar');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0075', 'Robin Sheldon');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0075', 'verse', 1, 0, '[\"Christ is surely coming, bringing His reward,\",\"Alpha and Omega, First and Last and Lord:\",\"root and stem of David, brilliant Morning Star –\",\"Meet your Judge and Saviour, nations near and far;\",\"meet your Judge and Saviour, nations near and far!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0075', 'verse', 2, 1, '[\"See the holy city! There they enter in,\",\"all by Christ made holy, washed from every sin:\",\"thirsty ones, desiring all He loves to give,\",\"Come for living water, freely drink, and live;\",\"come for living water, freely drink, and live!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0075', 'verse', 3, 2, '[\"Grace be with God’s people! Praise His holy name!\",\"Father, Son, and Spirit, evermore the same:\",\"hear the certain promise from the eternal home:\",\"‘Surely I come quickly!’ – Come, Lord Jesus, come;\",\"‘Surely I come quickly!’ – Come, Lord Jesus, come!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0076', 76, 'Christ the Lord is risen today', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Christ the Lord is risen today;
hallelujah!
sons of men and angels say:
raise your joys and triumphs high;
sing, ye heavens; thou earth, reply:
Love’s redeeming work is done,
fought the fight, the battle won;
Lo! our sun’s eclipse is o’er,
Lo! He sets in blood no more:
Vain the stone, the watch, the seal;
Christ hath burst the gates of hell;
death in vain forbids Him rise;
Christ hath opened paradise;
Lives again our glorious King;
where, O death, is now thy sting?
Once He died our souls to save;
where thy victory, O grave?
Soar we now where Christ hath led,
following our exalted Head;
made like Him, like Him we rise;
ours the cross, the grave, the skies:
Hail the Lord of earth and heaven,
praise to Thee by both be given:
Thee we greet, in triumph sing
Hail, our resurrected King:');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0076', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0076', 'William Henry Monk');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0076', 'verse', 1, 0, '[\"Christ the Lord is risen today;\",\"hallelujah!\",\"sons of men and angels say:\",\"raise your joys and triumphs high;\",\"sing, ye heavens; thou earth, reply:\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0076', 'verse', 2, 1, '[\"Love’s redeeming work is done,\",\"fought the fight, the battle won;\",\"Lo! our sun’s eclipse is o’er,\",\"Lo! He sets in blood no more:\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0076', 'verse', 3, 2, '[\"Vain the stone, the watch, the seal;\",\"Christ hath burst the gates of hell;\",\"death in vain forbids Him rise;\",\"Christ hath opened paradise;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0076', 'verse', 4, 3, '[\"Lives again our glorious King;\",\"where, O death, is now thy sting?\",\"Once He died our souls to save;\",\"where thy victory, O grave?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0076', 'verse', 5, 4, '[\"Soar we now where Christ hath led,\",\"following our exalted Head;\",\"made like Him, like Him we rise;\",\"ours the cross, the grave, the skies:\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0076', 'verse', 6, 5, '[\"Hail the Lord of earth and heaven,\",\"praise to Thee by both be given:\",\"Thee we greet, in triumph sing\",\"Hail, our resurrected King:\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0077', 77, 'Christ triumphant', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Christ triumphant, ever reigning,
Saviour, Master, King,
Lord of heaven, our lives sustaining,
hear us as we sing:
Yours the glory and the crown,
the high renown, the eternal name.
Word incarnate, truth revealing,
Son of Man on earth!
power and majesty concealing
by Your humble birth:
Yours the glory...
Suffering servant, scorned, ill-treated,
victim crucified!
death is through the cross defeated,
sinners justified:
Yours the glory...
Priestly King, enthroned for ever
high in heaven above!
sin and death and hell shall never
stifle hymns of love:
Yours the glory...
So, our hearts and voices raising
through the ages long,
ceaselessly upon You gazing,
this shall be our song:
Yours the glory...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0077', 'Michael Saward');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0077', 'Michael Baughen');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0077', 'verse', 1, 0, '[\"Christ triumphant, ever reigning,\",\"Saviour, Master, King,\",\"Lord of heaven, our lives sustaining,\",\"hear us as we sing:\",\"Yours the glory and the crown,\",\"the high renown, the eternal name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0077', 'verse', 2, 1, '[\"Word incarnate, truth revealing,\",\"Son of Man on earth!\",\"power and majesty concealing\",\"by Your humble birth:\",\"Yours the glory...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0077', 'verse', 3, 2, '[\"Suffering servant, scorned, ill-treated,\",\"victim crucified!\",\"death is through the cross defeated,\",\"sinners justified:\",\"Yours the glory...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0077', 'verse', 4, 3, '[\"Priestly King, enthroned for ever\",\"high in heaven above!\",\"sin and death and hell shall never\",\"stifle hymns of love:\",\"Yours the glory...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0077', 'verse', 5, 4, '[\"So, our hearts and voices raising\",\"through the ages long,\",\"ceaselessly upon You gazing,\",\"this shall be our song:\",\"Yours the glory...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0078', 78, 'Christ the Way of life possess me', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Christ the Way of life possess me,
lift my heart to love and praise;
guide and keep, sustain and bless me,
all my days, all my days.
Well of life, for ever flowing,
make my barren soul and bare
like a watered garden growing
fresh and fair, fresh and fair.
May the Tree of life in splendour');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0078', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0078', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0078', 'verse', 1, 0, '[\"Christ the Way of life possess me,\",\"lift my heart to love and praise;\",\"guide and keep, sustain and bless me,\",\"all my days, all my days.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0078', 'verse', 2, 1, '[\"Well of life, for ever flowing,\",\"make my barren soul and bare\",\"like a watered garden growing\",\"fresh and fair, fresh and fair.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0078', 'verse', 3, 2, '[\"May the Tree of life in splendour\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0079', 79, 'Christ, whose glory fills the skies', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Christ, whose glory fills the skies,
Christ, the true, the only light,
Sun of righteousness, arise,
triumph o’er the shades of night:
Day-spring from on high, be near;
Day-star, in my heart appear.
Dark and cheerless is the morn
unaccompanied by Thee;
joyless is the day’s return,
till Thy mercy’s beams I see;
till they inward light impart,
glad my eyes, and warm my heart.
Visit then this soul of mine;
pierce the gloom of sin and grief;
fill me, radiancy divine;
scatter all my unbelief;
more and more Thyself display,
shining to the perfect day.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0079', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0079', 'William Henry Havergal');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0079', 'verse', 1, 0, '[\"Christ, whose glory fills the skies,\",\"Christ, the true, the only light,\",\"Sun of righteousness, arise,\",\"triumph o’er the shades of night:\",\"Day-spring from on high, be near;\",\"Day-star, in my heart appear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0079', 'verse', 2, 1, '[\"Dark and cheerless is the morn\",\"unaccompanied by Thee;\",\"joyless is the day’s return,\",\"till Thy mercy’s beams I see;\",\"till they inward light impart,\",\"glad my eyes, and warm my heart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0079', 'verse', 3, 2, '[\"Visit then this soul of mine;\",\"pierce the gloom of sin and grief;\",\"fill me, radiancy divine;\",\"scatter all my unbelief;\",\"more and more Thyself display,\",\"shining to the perfect day.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0080', 80, 'Christians, awake!', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Christians, awake! salute the happy morn,
whereon the Saviour of mankind was born;
rise to adore the mystery of love
which hosts of angels chanted from above;
with them the joyful tidings first begun
of God incarnate, and the Virgin’s Son.
Then to the watchful shepherds it was told,
who heard the angelic herald’s voice, ‘Behold,
I bring good tidings of a Saviour’s birth
to you and all the nations upon earth:
this day hath God fulfilled His promised word,
this day is born a Saviour, Christ the Lord.’
He spake; and straightway the celestial choir,
in hymns of joy unknown before conspire;
the praises of redeeming love they sang,
and heaven’s whole orb with hallelujahs rang:
God’s highest glory was their anthem still,
‘On earth be peace, and unto men goodwill.’
To Bethlehem straight the enlightened shepherds ran,
to see the wonder God had wrought for man;
then to their flocks, still praising God, return,
and their glad hearts with holy rapture burn;
amazed, the wondrous tidings they proclaim,
the first apostles of His infant fame.
Then may we hope, the angelic hosts among,
to sing, redeemed, a glad triumphal song:
He that was born upon this joyful day
around us all His glory shall display;
saved by His love, incessant we shall sing
eternal praise to heaven’s almighty King.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0080', 'John Byrom');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0080', 'John Wainwright');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0080', 'verse', 1, 0, '[\"Christians, awake! salute the happy morn,\",\"whereon the Saviour of mankind was born;\",\"rise to adore the mystery of love\",\"which hosts of angels chanted from above;\",\"with them the joyful tidings first begun\",\"of God incarnate, and the Virgin’s Son.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0080', 'verse', 2, 1, '[\"Then to the watchful shepherds it was told,\",\"who heard the angelic herald’s voice, ‘Behold,\",\"I bring good tidings of a Saviour’s birth\",\"to you and all the nations upon earth:\",\"this day hath God fulfilled His promised word,\",\"this day is born a Saviour, Christ the Lord.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0080', 'verse', 3, 2, '[\"He spake; and straightway the celestial choir,\",\"in hymns of joy unknown before conspire;\",\"the praises of redeeming love they sang,\",\"and heaven’s whole orb with hallelujahs rang:\",\"God’s highest glory was their anthem still,\",\"‘On earth be peace, and unto men goodwill.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0080', 'verse', 4, 3, '[\"To Bethlehem straight the enlightened shepherds ran,\",\"to see the wonder God had wrought for man;\",\"then to their flocks, still praising God, return,\",\"and their glad hearts with holy rapture burn;\",\"amazed, the wondrous tidings they proclaim,\",\"the first apostles of His infant fame.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0080', 'verse', 5, 4, '[\"Then may we hope, the angelic hosts among,\",\"to sing, redeemed, a glad triumphal song:\",\"He that was born upon this joyful day\",\"around us all His glory shall display;\",\"saved by His love, incessant we shall sing\",\"eternal praise to heaven’s almighty King.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0081', 81, 'Clap your hands, you people all', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Clap your hands, you people all,
praise the God on whom you call;
lift your voice, and shout His praise,
triumph in His sovereign grace!
Glorious is the Lord most high,
terrible in majesty;
He His sovereign sway maintains,
King o’er all the earth He reigns.
Jesus is gone up on high,
takes His seat above the sky:
shout the angel-choirs aloud,
echoing to the trump of God.
Sons of earth, the triumph join,
praise Him with the host divine;
emulate the heavenly powers,
their victorious Lord is ours.
Shout the God enthroned above,
trumpet forth His conquering love;
praises to our Jesus sing,
praises to our glorious King!
Power is all to Jesus given,
power o’er hell, and earth, and heaven!
Power He now to us imparts;
praise Him with believing hearts.
Wonderful in saving power,
Him let all our hearts adore;
earth and heaven repeat the cry,
‘Glory be to God most high!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0081', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0081', 'Henry Leslie');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0081', 'verse', 1, 0, '[\"Clap your hands, you people all,\",\"praise the God on whom you call;\",\"lift your voice, and shout His praise,\",\"triumph in His sovereign grace!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0081', 'verse', 2, 1, '[\"Glorious is the Lord most high,\",\"terrible in majesty;\",\"He His sovereign sway maintains,\",\"King o’er all the earth He reigns.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0081', 'verse', 3, 2, '[\"Jesus is gone up on high,\",\"takes His seat above the sky:\",\"shout the angel-choirs aloud,\",\"echoing to the trump of God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0081', 'verse', 4, 3, '[\"Sons of earth, the triumph join,\",\"praise Him with the host divine;\",\"emulate the heavenly powers,\",\"their victorious Lord is ours.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0081', 'verse', 5, 4, '[\"Shout the God enthroned above,\",\"trumpet forth His conquering love;\",\"praises to our Jesus sing,\",\"praises to our glorious King!\"]');
