INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0082', 82, 'Cleanse me from my sin', 'MP', 'en', 'SGM Lifewords, 3 Eccleston Street, London, SW1W 9LZ', '', 0, 0, 0, 1, 1, 'Cleanse me from my sin, Lord,
put Thy power within, Lord,
take me as I am, Lord,
and make me all Thine own.
Keep me day by day, Lord,
underneath Thy sway, Lord,
make my heart Thy palace,
and Thy royal throne.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0082', 'R Hudson Pope');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0082', 'R Hudson Pope');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0082', 'verse', 1, 0, '[\"Cleanse me from my sin, Lord,\",\"put Thy power within, Lord,\",\"take me as I am, Lord,\",\"and make me all Thine own.\",\"Keep me day by day, Lord,\",\"underneath Thy sway, Lord,\",\"make my heart Thy palace,\",\"and Thy royal throne.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0083', 83, 'Celebrations', 'MP', 'en', 'Copyright 1972 Chester Music Limited trading as High-Fye Music. All Rights Reserved. International Copyright Secured. Used by Permission of Chester Music Limited trading as High-Fye Music.', '', 0, 0, 0, 1, 1, 'Come and join the celebration,
it’s a very special day;
come and share our jubilation,
there’s a new King born today!
See the shepherds
hurry down to Bethlehem;
gaze in wonder
at the Son of God who lay before them.
Come and join...
Wise men journey,
led to worship by a star,
kneel in homage,
bringing precious gifts from lands afar, so
Come and join...
‘God is with us,’
’round the world the message bring;
He is with us,
‘Welcome!’ all the bells on earth are pealing.
Come and join...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0083', 'Valerie Collison');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0083', 'Valerie Collison');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0083', 'chorus', 0, 0, '[\"Come and join the celebration,\",\"it’s a very special day;\",\"come and share our jubilation,\",\"there’s a new King born today!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0083', 'verse', 1, 1, '[\"See the shepherds\",\"hurry down to Bethlehem;\",\"gaze in wonder\",\"at the Son of God who lay before them.\",\"Come and join...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0083', 'verse', 2, 2, '[\"Wise men journey,\",\"led to worship by a star,\",\"kneel in homage,\",\"bringing precious gifts from lands afar, so\",\"Come and join...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0083', 'verse', 3, 3, '[\"‘God is with us,’\",\"’round the world the message bring;\",\"He is with us,\",\"‘Welcome!’ all the bells on earth are pealing.\",\"Come and join...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0084', 84, 'Come and praise the living God', 'MP', 'en', '©  1982 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Come and praise the living God,
come and worship, come and worship.
He has made you priest and king,
come and worship the living God.
We come not to a mountain of fire and smoke,
not to gloom and darkness or trumpet sound;
we come to the new Jerusalem,
the holy city of God.
Come and praise...
By His voice He shakes the earth,
His judgements known throughout the world.
But we have a city that for ever stands,
the holy city of God.
Come and praise...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0084', 'Mike Kerry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0084', 'Mike Kerry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0084', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0084', 'chorus', 0, 0, '[\"Come and praise the living God,\",\"come and worship, come and worship.\",\"He has made you priest and king,\",\"come and worship the living God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0084', 'verse', 1, 1, '[\"We come not to a mountain of fire and smoke,\",\"not to gloom and darkness or trumpet sound;\",\"we come to the new Jerusalem,\",\"the holy city of God.\",\"Come and praise...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0084', 'verse', 2, 2, '[\"By His voice He shakes the earth,\",\"His judgements known throughout the world.\",\"But we have a city that for ever stands,\",\"the holy city of God.\",\"Come and praise...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0085', 85, 'We worship at Your feet', 'MP', 'en', '1989 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Come and see, come and see,
come and see the King of love;
see the purple robe and crown of thorns He wears.
Soldiers mock, rulers sneer
as He lifts the cruel cross;
lone and friendless now, He climbs towards the hill.
We worship at Your feet,
where wrath and mercy meet,
and a guilty world is washed by love’s pure stream.
For us He was made sin –
oh, help me take it in.
Deep wounds of love cry out, ‘Father, forgive.’
I worship, I worship
the Lamb who was slain.
Come and weep, come and mourn
for your sin that pierced Him there;
so much deeper than the wounds of thorn and nail.
All our pride, all our greed,
all our fallenness and shame;
and the Lord has laid the punishment on Him.
We worship at Your feet...
Man of heaven, born to earth
to restore us to Your heaven.
Here we bow in awe beneath Your searching eyes.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0085', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0085', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0085', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0085', 'verse', 1, 0, '[\"Come and see, come and see,\",\"come and see the King of love;\",\"see the purple robe and crown of thorns He wears.\",\"Soldiers mock, rulers sneer\",\"as He lifts the cruel cross;\",\"lone and friendless now, He climbs towards the hill.\",\"We worship at Your feet,\",\"where wrath and mercy meet,\",\"and a guilty world is washed by love’s pure stream.\",\"For us He was made sin –\",\"oh, help me take it in.\",\"Deep wounds of love cry out, ‘Father, forgive.’\",\"I worship, I worship\",\"the Lamb who was slain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0085', 'verse', 2, 1, '[\"Come and weep, come and mourn\",\"for your sin that pierced Him there;\",\"so much deeper than the wounds of thorn and nail.\",\"All our pride, all our greed,\",\"all our fallenness and shame;\",\"and the Lord has laid the punishment on Him.\",\"We worship at Your feet...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0085', 'verse', 3, 2, '[\"Man of heaven, born to earth\",\"to restore us to Your heaven.\",\"Here we bow in awe beneath Your searching eyes.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0086', 86, 'Come and see the shining hope', 'MP', 'en', 'Christopher Idle/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION             © David Wilson/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'Come and see the shining hope that Christ’s apostle saw:
on the earth, confusion, but in heaven an open door,
where the living creatures praise the Lamb for evermore;
Love has the victory for ever!
Amen, He comes!
to bring His own reward;
amen, praise God!
for justice now restored.
Kingdoms of the world
become the kingdoms of the Lord:
love has the victory for ever!
All the gifts You send us, Lord, are faithful, good, and true;
holiness and righteousness are shown in all You do:
who can see Your greatest gift and fail to worship You?
Love has the victory for ever!
Amen, He comes...
Power and salvation all belong to God on high:
So the mighty multitudes of heaven make their cry,
singing, ‘Alleluia!’ where the echoes never die;
love has the victory for ever!
Amen, He comes...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0086', 'Christopher Idle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0086', 'David G Wilson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0086', 'verse', 1, 0, '[\"Come and see the shining hope that Christ’s apostle saw:\",\"on the earth, confusion, but in heaven an open door,\",\"where the living creatures praise the Lamb for evermore;\",\"Love has the victory for ever!\",\"Amen, He comes!\",\"to bring His own reward;\",\"amen, praise God!\",\"for justice now restored.\",\"Kingdoms of the world\",\"become the kingdoms of the Lord:\",\"love has the victory for ever!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0086', 'verse', 2, 1, '[\"All the gifts You send us, Lord, are faithful, good, and true;\",\"holiness and righteousness are shown in all You do:\",\"who can see Your greatest gift and fail to worship You?\",\"Love has the victory for ever!\",\"Amen, He comes...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0086', 'verse', 3, 2, '[\"Power and salvation all belong to God on high:\",\"So the mighty multitudes of heaven make their cry,\",\"singing, ‘Alleluia!’ where the echoes never die;\",\"love has the victory for ever!\",\"Amen, He comes...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0087', 87, 'Come and praise Him, royal priesthood', 'MP', 'en', '©  1977 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Come and praise Him, royal priesthood,
come and worship, holy nation,
worship Jesus, our Redeemer,
He is precious, King of glory.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0087', 'A Carter');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0087', 'A Carter');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0087', 'Roger Mayor');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0087', 'verse', 1, 0, '[\"Come and praise Him, royal priesthood,\",\"come and worship, holy nation,\",\"worship Jesus, our Redeemer,\",\"He is precious, King of glory.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0088', 88, 'Come, bless the Lord', 'MP', 'en', 'control                        ©  Roger Mayor/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'Come, bless the Lord,
all ye servants of the Lord,
who stand by night
in the house of the Lord;
lift up your hands
in the holy place,
come, bless the Lord,
come, bless the Lord.');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0088', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0088', 'Roger Mayor');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0088', 'verse', 1, 0, '[\"Come, bless the Lord,\",\"all ye servants of the Lord,\",\"who stand by night\",\"in the house of the Lord;\",\"lift up your hands\",\"in the holy place,\",\"come, bless the Lord,\",\"come, bless the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0089', 89, 'Come down, O Love divine', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Come down, O Love divine,
seek Thou this soul of mine
and visit it with Thine own ardour glowing;
O Comforter, draw near,
within my heart appear,
and kindle it, Thy holy flame bestowing.
O let it freely burn,
till earthly passions turn
to dust and ashes, in its heat consuming;
and let Thy glorious light
shine ever on my sight,
and clothe me round, the while my path illuming.
Let holy charity
mine outward vesture be,
and lowliness become mine inner clothing;
true lowliness of heart,
which takes the humbler part,
and o’er its own shortcomings weeps with loathing.
And so the yearning strong,
with which the soul will long,
shall far outpass the power of human telling;
for none can guess its grace,
till he become the place
wherein the Holy Spirit makes His dwelling.
Words after by Bianco da Siena');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0089', 'Richard F Littledale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0089', 'Ralph Vaughan Williams');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0089', 'verse', 1, 0, '[\"Come down, O Love divine,\",\"seek Thou this soul of mine\",\"and visit it with Thine own ardour glowing;\",\"O Comforter, draw near,\",\"within my heart appear,\",\"and kindle it, Thy holy flame bestowing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0089', 'verse', 2, 1, '[\"O let it freely burn,\",\"till earthly passions turn\",\"to dust and ashes, in its heat consuming;\",\"and let Thy glorious light\",\"shine ever on my sight,\",\"and clothe me round, the while my path illuming.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0089', 'verse', 3, 2, '[\"Let holy charity\",\"mine outward vesture be,\",\"and lowliness become mine inner clothing;\",\"true lowliness of heart,\",\"which takes the humbler part,\",\"and o’er its own shortcomings weeps with loathing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0089', 'verse', 4, 3, '[\"And so the yearning strong,\",\"with which the soul will long,\",\"shall far outpass the power of human telling;\",\"for none can guess its grace,\",\"till he become the place\",\"wherein the Holy Spirit makes His dwelling.\",\"Words after by Bianco da Siena\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0090', 90, 'Come, Holy Ghost', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Come, Holy Ghost, our souls inspire,
and lighten with celestial fire:
Thou the anointing Spirit art,
who dost Thy sevenfold gifts impart.
Thy blessèd unction from above
is comfort, life, and fire of love:
enable with perpetual light
the dullness of our blinded sight.
Anoint and cheer our soilèd face
with the abundance of Thy grace:
keep far our foes, give peace at home –
where Thou art guide no ill can come.
Teach us to know the Father, Son,
and Thee, of both, to be but One;
that, through the ages all along,
this, this may be our endless song:
Praise to Thy eternal merit,
Father, Son, and Holy Spirit! Amen.
Words after by R Maurus');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0090', 'J Cosin');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0090', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0090', 'verse', 1, 0, '[\"Come, Holy Ghost, our souls inspire,\",\"and lighten with celestial fire:\",\"Thou the anointing Spirit art,\",\"who dost Thy sevenfold gifts impart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0090', 'verse', 2, 1, '[\"Thy blessèd unction from above\",\"is comfort, life, and fire of love:\",\"enable with perpetual light\",\"the dullness of our blinded sight.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0090', 'verse', 3, 2, '[\"Anoint and cheer our soilèd face\",\"with the abundance of Thy grace:\",\"keep far our foes, give peace at home –\",\"where Thou art guide no ill can come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0090', 'verse', 4, 3, '[\"Teach us to know the Father, Son,\",\"and Thee, of both, to be but One;\",\"that, through the ages all along,\",\"this, this may be our endless song:\",\"Praise to Thy eternal merit,\",\"Father, Son, and Holy Spirit! Amen.\",\"Words after by R Maurus\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0091', 91, 'Come, let us bow down in worship', 'MP', 'en', '1985 Andy Silver', '', 0, 0, 0, 1, 1, 'Come, let us bow down in worship,
let us kneel before the Lord our maker.
Come, let us bow down in worship,
for He is our God and we are His people,
for He is our God, the people of His pasture,
the flock under His care.
Come, let us bow down in worship,
let us kneel before the Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0091', 'Andy Silver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0091', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0091', 'verse', 1, 0, '[\"Come, let us bow down in worship,\",\"let us kneel before the Lord our maker.\",\"Come, let us bow down in worship,\",\"for He is our God and we are His people,\",\"for He is our God, the people of His pasture,\",\"the flock under His care.\",\"Come, let us bow down in worship,\",\"let us kneel before the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0092', 92, 'Come, let us praise the Lord', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Come, let us praise the Lord,
with joy our God acclaim,
His greatness tell abroad
and bless His saving name.
Lift high your songs
before His throne
to Whom alone
all praise belongs.
Our God of matchless worth,
our King beyond compare,
the deepest bounds of earth,
the hills, are in His care.
He all decrees,
Who by His hand
prepared the land
and formed the seas.
In worship bow the knee,
our glorious God confess;
the great Creator, He,
the Lord our righteousness.
He reigns unseen:
His flock He feeds
and gently leads
in pastures green.
Come, hear His voice today,
receive what love imparts;
His holy will obey
and harden not your hearts.
His ways are best;
and lead at last,
all troubles past,
to perfect rest.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0092', 'Timothy Dudley-Smith');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0092', 'verse', 1, 0, '[\"Come, let us praise the Lord,\",\"with joy our God acclaim,\",\"His greatness tell abroad\",\"and bless His saving name.\",\"Lift high your songs\",\"before His throne\",\"to Whom alone\",\"all praise belongs.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0092', 'verse', 2, 1, '[\"Our God of matchless worth,\",\"our King beyond compare,\",\"the deepest bounds of earth,\",\"the hills, are in His care.\",\"He all decrees,\",\"Who by His hand\",\"prepared the land\",\"and formed the seas.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0092', 'verse', 3, 2, '[\"In worship bow the knee,\",\"our glorious God confess;\",\"the great Creator, He,\",\"the Lord our righteousness.\",\"He reigns unseen:\",\"His flock He feeds\",\"and gently leads\",\"in pastures green.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0092', 'verse', 4, 3, '[\"Come, hear His voice today,\",\"receive what love imparts;\",\"His holy will obey\",\"and harden not your hearts.\",\"His ways are best;\",\"and lead at last,\",\"all troubles past,\",\"to perfect rest.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0093', 93, 'Come, let us join our cheerful songs', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Come, let us join our cheerful songs
with angels round the throne;
ten thousand thousand are their tongues,
but all their joys are one.
‘Worthy the Lamb that died!’ they cry,
‘to be exalted thus’;
‘Worthy the Lamb!’ our lips reply,
‘for He was slain for us.’
Jesus is worthy to receive
honour and power divine;
and blessings more than we can give
be, Lord, for ever Thine.
The whole creation join in one,
to bless the sacred name
of Him that sits upon the throne,
and to adore the Lamb.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0093', 'Isaac Watts');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0093', 'Henry Lahee');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0093', 'verse', 1, 0, '[\"Come, let us join our cheerful songs\",\"with angels round the throne;\",\"ten thousand thousand are their tongues,\",\"but all their joys are one.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0093', 'verse', 2, 1, '[\"‘Worthy the Lamb that died!’ they cry,\",\"‘to be exalted thus’;\",\"‘Worthy the Lamb!’ our lips reply,\",\"‘for He was slain for us.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0093', 'verse', 3, 2, '[\"Jesus is worthy to receive\",\"honour and power divine;\",\"and blessings more than we can give\",\"be, Lord, for ever Thine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0093', 'verse', 4, 3, '[\"The whole creation join in one,\",\"to bless the sacred name\",\"of Him that sits upon the throne,\",\"and to adore the Lamb.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0094', 94, 'Come, let us sing', 'MP', 'en', 'Trustees for Methodist Church Purposes. Used with permission.', '', 0, 0, 0, 1, 1, 'Come, let us sing of a wonderful love,
tender and true;
out of the heart of the Father above,
streaming to me and to you:
wonderful love
dwells in the heart of the Father above.
Jesus, the Saviour, this gospel to tell,
joyfully came;
came with the helpless and hopeless to dwell,
sharing their sorrow and shame;
seeking the lost,
saving, redeeming at measureless cost.
Jesus is seeking the wanderers yet;
Why do they roam?
Love only waits to forgive and forget;
Home! weary wanderers, home!
Wonderful love
dwells in the heart of the Father above.
Come to my heart, O Thou wonderful Love,
come and abide,
lifting my life till it rises above
envy and falsehood and pride;
seeking to be
lowly and humble, a learner of Thee.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0094', 'Robert Walmsley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0094', 'Frederick Luke Wiseman');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0094', 'verse', 1, 0, '[\"Come, let us sing of a wonderful love,\",\"tender and true;\",\"out of the heart of the Father above,\",\"streaming to me and to you:\",\"wonderful love\",\"dwells in the heart of the Father above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0094', 'verse', 2, 1, '[\"Jesus, the Saviour, this gospel to tell,\",\"joyfully came;\",\"came with the helpless and hopeless to dwell,\",\"sharing their sorrow and shame;\",\"seeking the lost,\",\"saving, redeeming at measureless cost.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0094', 'verse', 3, 2, '[\"Jesus is seeking the wanderers yet;\",\"Why do they roam?\",\"Love only waits to forgive and forget;\",\"Home! weary wanderers, home!\",\"Wonderful love\",\"dwells in the heart of the Father above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0094', 'verse', 4, 3, '[\"Come to my heart, O Thou wonderful Love,\",\"come and abide,\",\"lifting my life till it rises above\",\"envy and falsehood and pride;\",\"seeking to be\",\"lowly and humble, a learner of Thee.\"]');
