INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0097', 97, 'Come, let us worship our Redeemer', 'MP', 'en', 'HarperCollins Religious/adm Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Come, let us worship our Redeemer,
let us bow down before His throne;
come, let us kneel before our maker:
holy is His name.
Come into His presence with thanksgiving,
make a joyful noise;
for the Lord is a great God:
King above all gods.
Come, let us worship...
We are the people of His pasture,
the sheep of His hand:
for Christ the Lord is our shepherd,
He will lead us home.
Come, let us worship...
All praises be to God the Father,
praise to Christ His Son;
praise be to God the Holy Spirit:
bless the Three-in-One!
Come, let us worship...');
