INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0102', 102, 'Come, Thou long-expected Jesus', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Come, Thou long-expected Jesus,
born to set Thy people free;');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0102', 'Charles Wesley');
