INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0104', 'verse', 1, 1, '[\"Jesus said, ‘Come unto Me\",\"all ye weary, heavy-laden.’\",\"Come to the waters...\"]');
