INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0106', 106, 'Come, you thankful people, come', 'MP', 'en', 'in this version The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'Come, you thankful people, come,
raise the song of harvest home!
fruit and crops are gathered in
safe before the storms begin:
God our maker will provide
for our needs to be supplied;
come, with all His people, come,
raise the song of harvest home!
All the world is God’s own field,
harvests for His praise to yield;
wheat and weeds together sown
here for joy or sorrow grown:
first the blade and then the ear,
then the full corn shall appear –
Lord of harvest, grant that we
wholesome grain and pure may be.
For the Lord our God shall come
and shall bring His harvest home;
He Himself on that great day,
worthless things shall take away,
give His angels charge at last
in the fire the weeds to cast,
but the fruitful ears to store
in His care for evermore.
Even so, Lord, quickly come –
bring Your final harvest home!
gather all Your people in
free from sorrow, free from sin,
there together purified,
ever thankful at Your side –
come, with all Your angels, come,
bring that glorious harvest home!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0106', 'Henry Alford');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0106', 'George Job Elvey');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0106', 'verse', 1, 0, '[\"Come, you thankful people, come,\",\"raise the song of harvest home!\",\"fruit and crops are gathered in\",\"safe before the storms begin:\",\"God our maker will provide\",\"for our needs to be supplied;\",\"come, with all His people, come,\",\"raise the song of harvest home!\"]');
