INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0106', 'verse', 3, 2, '[\"For the Lord our God shall come\",\"and shall bring His harvest home;\",\"He Himself on that great day,\",\"worthless things shall take away,\",\"give His angels charge at last\",\"in the fire the weeds to cast,\",\"but the fruitful ears to store\",\"in His care for evermore.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0106', 'verse', 4, 3, '[\"Even so, Lord, quickly come –\",\"bring Your final harvest home!\",\"gather all Your people in\",\"free from sorrow, free from sin,\",\"there together purified,\",\"ever thankful at Your side –\",\"come, with all Your angels, come,\",\"bring that glorious harvest home!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0108', 108, 'Create in me', 'MP', 'en', '©  1983 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Create in me a clean heart, O God,
and renew a right spirit in me.
Create in me a clean heart, O God,
and renew a right spirit in me.
Wash me, cleanse me, purify me,
make my heart as white as snow.
Create in me a clean heart, O God,
and renew a right spirit in me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0108', 'David Fellingham');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0108', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0108', 'verse', 1, 0, '[\"Create in me a clean heart, O God,\",\"and renew a right spirit in me.\",\"Create in me a clean heart, O God,\",\"and renew a right spirit in me.\",\"Wash me, cleanse me, purify me,\",\"make my heart as white as snow.\",\"Create in me a clean heart, O God,\",\"and renew a right spirit in me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0109', 109, 'Crown Him with many crowns', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Crown Him with many crowns,
the Lamb upon His throne;
Hark! how the heavenly anthem drowns
all music but its own:
awake, my soul, and sing
of Him who died for thee,
and hail Him as thy chosen King
through all eternity.
Crown Him the Son of God
before the worlds began;
and ye who tread where He hath trod,
crown Him the Son of Man,
who every grief hath known
that wrings the human breast,
and takes and bears them for His own,
that all in Him may rest.
Crown Him the Lord of life,
who triumphed o’er the grave,
and rose victorious in the strife,
for those He came to save:
His glories now we sing,
who died and rose on high,
who died eternal life to bring,
and lives that death may die.
Crown Him the Lord of heaven,
enthroned in worlds above;
crown Him the King to whom is given
the wondrous name of Love:
all hail, Redeemer, hail!
for Thou hast died for me;
Thy praise shall never, never fail
throughout eternity.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0109', 'Matthew Bridges');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0109', 'Godfrey Thring');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0109', 'George Job Elvey');
