INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0110', 110, 'Arise, shine', 'MP', 'en', '©  1985 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Darkness like a shroud
covers the earth,
evil like a cloud
covers the people;
but the Lord will rise upon you,
and His glory will appear on you,
nations will come to your light.
Arise, shine, your light has come,
the glory of the Lord has risen on you;
arise, shine, your light has come –
Jesus the Light of the world has come.
Children of the light,
be clean and pure;
rise, you sleepers,
Christ will shine on you:
take the Spirit’s flashing two-edged sword
and with faith declare God’s mighty word;
stand up, and in His strength be strong!
Arise, shine...
Here among us now,
Christ the Light
kindles brighter flames
in our trembling hearts:
Living Word, our lamp, come guide our feet –
as we walk as one in light and peace,
justice and truth shine like the sun.
Arise, shine...
Like a city bright,
so let us blaze;
lights in every street
turning night to day:
and the darkness shall not overcome,
till the fulness of Christ’s kingdom comes,
dawning to God’s eternal day.
Arise, shine, your light has come,
the glory of the Lord has risen on you;
arise, shine, your light has come –
Jesus the Light of the world,
Jesus the Light of the world,
Jesus the Light of the world has come.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0110', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0110', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0110', 'verse', 1, 0, '[\"Darkness like a shroud\",\"covers the earth,\",\"evil like a cloud\",\"covers the people;\",\"but the Lord will rise upon you,\",\"and His glory will appear on you,\",\"nations will come to your light.\",\"Arise, shine, your light has come,\",\"the glory of the Lord has risen on you;\",\"arise, shine, your light has come –\",\"Jesus the Light of the world has come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0110', 'verse', 2, 1, '[\"Children of the light,\",\"be clean and pure;\",\"rise, you sleepers,\",\"Christ will shine on you:\",\"take the Spirit’s flashing two-edged sword\",\"and with faith declare God’s mighty word;\",\"stand up, and in His strength be strong!\",\"Arise, shine...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0110', 'verse', 3, 2, '[\"Here among us now,\",\"Christ the Light\",\"kindles brighter flames\",\"in our trembling hearts:\",\"Living Word, our lamp, come guide our feet –\",\"as we walk as one in light and peace,\",\"justice and truth shine like the sun.\",\"Arise, shine...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0110', 'verse', 4, 3, '[\"Like a city bright,\",\"so let us blaze;\",\"lights in every street\",\"turning night to day:\",\"and the darkness shall not overcome,\",\"till the fulness of Christ’s kingdom comes,\",\"dawning to God’s eternal day.\",\"Arise, shine, your light has come,\",\"the glory of the Lord has risen on you;\",\"arise, shine, your light has come –\",\"Jesus the Light of the world,\",\"Jesus the Light of the world,\",\"Jesus the Light of the world has come.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0111', 111, 'Dear Lord and Father of mankind', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Dear Lord and Father of mankind,
forgive our foolish ways;
re-clothe us in our rightful mind;
in purer lives Thy service find,
in deeper reverence, praise.
In simple trust like theirs who heard,
beside the Syrian sea,
the gracious calling of the Lord,
let us, like them, without a word
rise up and follow Thee.
O Sabbath rest by Galilee!
O calm of hills above,
where Jesus knelt to share with Thee
the silence of eternity,
interpreted by love!
With that deep hush subduing all
our words and works that drown
the tender whisper of Thy call,
as noiseless let Thy blessing fall
as fell Thy manna down.
Drop Thy still dews of quietness,
till all our strivings cease;
take from our souls the strain and stress,
and let our ordered lives confess
the beauty of Thy peace.
Breathe through the heats of our desire
Thy coolness and Thy balm;
let sense be dumb, let flesh retire;
speak through the earthquake, wind, and fire,
O still small voice of calm!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0111', 'John Greenleaf Whittier');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0111', 'Charles Hubert Hastings Parry');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0111', 'verse', 1, 0, '[\"Dear Lord and Father of mankind,\",\"forgive our foolish ways;\",\"re-clothe us in our rightful mind;\",\"in purer lives Thy service find,\",\"in deeper reverence, praise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0111', 'verse', 2, 1, '[\"In simple trust like theirs who heard,\",\"beside the Syrian sea,\",\"the gracious calling of the Lord,\",\"let us, like them, without a word\",\"rise up and follow Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0111', 'verse', 3, 2, '[\"O Sabbath rest by Galilee!\",\"O calm of hills above,\",\"where Jesus knelt to share with Thee\",\"the silence of eternity,\",\"interpreted by love!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0111', 'verse', 4, 3, '[\"With that deep hush subduing all\",\"our words and works that drown\",\"the tender whisper of Thy call,\",\"as noiseless let Thy blessing fall\",\"as fell Thy manna down.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0111', 'verse', 5, 4, '[\"Drop Thy still dews of quietness,\",\"till all our strivings cease;\",\"take from our souls the strain and stress,\",\"and let our ordered lives confess\",\"the beauty of Thy peace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0111', 'verse', 6, 5, '[\"Breathe through the heats of our desire\",\"Thy coolness and Thy balm;\",\"let sense be dumb, let flesh retire;\",\"speak through the earthquake, wind, and fire,\",\"O still small voice of calm!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0112', 112, 'Delight yourself in the Lord', 'MP', 'en', '1985 Andy Silver', '', 0, 0, 0, 1, 1, 'Delight yourself in the Lord,
and He will give you the desires of your heart.
Commit your way to the Lord;
trust in Him and He will make your righteousness shine,
shining like the dawn and like the noon-day sun.
The righteous will dwell in the land for ever,
to share His inheritance.
Delight yourself in the Lord,
and He will give you the desires of your heart.
Commit your way to the Lord,
commit your way to the Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0112', 'Andy Silver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0112', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0112', 'verse', 1, 0, '[\"Delight yourself in the Lord,\",\"and He will give you the desires of your heart.\",\"Commit your way to the Lord;\",\"trust in Him and He will make your righteousness shine,\",\"shining like the dawn and like the noon-day sun.\",\"The righteous will dwell in the land for ever,\",\"to share His inheritance.\",\"Delight yourself in the Lord,\",\"and He will give you the desires of your heart.\",\"Commit your way to the Lord,\",\"commit your way to the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0113', 113, 'Delight yourselves in the Lord', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'Delight yourselves in the Lord,
delight yourselves in the Lord;
for He delights in the praises
of His own people;
for He delights in the praises
of His own people.
Let your well spring up within
and overflow to one another;
let your well spring up within
and overflow to the Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0113', 'David Bolton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0113', 'David Bolton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0113', 'verse', 1, 0, '[\"Delight yourselves in the Lord,\",\"delight yourselves in the Lord;\",\"for He delights in the praises\",\"of His own people;\",\"for He delights in the praises\",\"of His own people.\",\"Let your well spring up within\",\"and overflow to one another;\",\"let your well spring up within\",\"and overflow to the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0114', 114, 'Ding dong! Merrily on high', 'MP', 'en', 'SPCK', '', 0, 0, 0, 1, 1, 'Ding dong! Merrily on high
in heaven the bells are ringing.
Ding dong! Verily the sky
is riven with angels singing:
Gloria, hosanna in excelsis;
gloria, hosanna in excelsis!
E’en so, here below, below,
let steeple bells be swungen;
and i-o, i-o, i-o,
by priest and people sungen!
Gloria...
Pray you, dutifully prime
your matin chime, ye ringers;
may you beautifully rime
your eve-time song, ye singers:
Gloria...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0114', 'George Ratcliffe Woodward');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0114', 'Charles Wood');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0114', 'B V Burnett');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0114', 'verse', 1, 0, '[\"Ding dong! Merrily on high\",\"in heaven the bells are ringing.\",\"Ding dong! Verily the sky\",\"is riven with angels singing:\",\"Gloria, hosanna in excelsis;\",\"gloria, hosanna in excelsis!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0114', 'verse', 2, 1, '[\"E’en so, here below, below,\",\"let steeple bells be swungen;\",\"and i-o, i-o, i-o,\",\"by priest and people sungen!\",\"Gloria...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0114', 'verse', 3, 2, '[\"Pray you, dutifully prime\",\"your matin chime, ye ringers;\",\"may you beautifully rime\",\"your eve-time song, ye singers:\",\"Gloria...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0115', 115, 'Do not be afraid', 'MP', 'en', '1978 Kevin Mayhew Ltd, Buxhall, Stowmarket, Suffolk IP14 3DJ. Used by permission. From Hymns Old and New', '', 0, 0, 0, 1, 1, 'Do not be afraid,
for I have redeemed you.
I have called you by your name;
you are Mine.
When you walk through the waters I’ll be with you;
you will never sink beneath the waves.
Do not be afraid...
When the fire is burning all around you,
you will never be consumed by the flames.
Do not be afraid...
When the fear of loneliness is looming,
then remember I am at your side.
Do not be afraid...
When you dwell in the exile of the stranger,
remember you are precious in My eyes.
Do not be afraid...
You are Mine, O My child; I am your Father,
and I love you with a perfect love.
Do not be afraid...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0115', 'Gerald Markland');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0115', 'Gerald Markland');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0115', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0115', 'chorus', 0, 0, '[\"Do not be afraid,\",\"for I have redeemed you.\",\"I have called you by your name;\",\"you are Mine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0115', 'verse', 1, 1, '[\"When you walk through the waters I’ll be with you;\",\"you will never sink beneath the waves.\",\"Do not be afraid...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0115', 'verse', 2, 2, '[\"When the fire is burning all around you,\",\"you will never be consumed by the flames.\",\"Do not be afraid...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0115', 'verse', 3, 3, '[\"When the fear of loneliness is looming,\",\"then remember I am at your side.\",\"Do not be afraid...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0115', 'verse', 4, 4, '[\"When you dwell in the exile of the stranger,\",\"remember you are precious in My eyes.\",\"Do not be afraid...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0115', 'verse', 5, 5, '[\"You are Mine, O My child; I am your Father,\",\"and I love you with a perfect love.\",\"Do not be afraid...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0116', 116, 'Down from His glory', 'MP', 'en', 'Zondervan Herman Co/Imagem Music/Small Stone Media BV/Song Solutions Daybreak www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Down from His glory, ever-living story,
my God and Saviour came, and Jesus was His name;
born in a manger to His own a stranger,
a man of sorrows, tears and agony!
O how I love Him! how I adore Him!
My breath, my sunshine, my all-in-all!
The great Creator became my Saviour,
and all God’s fulness dwelleth in Him!
What condescension, bringing us redemption,
that in the dead of night, not one faint hope in sight;
God, gracious, tender, laid aside His splendour,
stooping to woo, to win, to save my soul.
O how I love Him...
Without reluctance, flesh and blood, His substance,
He took the form of man, revealed the hidden plan;
O glorious mystery, sacrifice of Calvary!
And now I know He is the great ‘I A');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0116', 'William E Booth-Clibborn');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0116', 'William E Booth-Clibborn');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0116', 'verse', 1, 0, '[\"Down from His glory, ever-living story,\",\"my God and Saviour came, and Jesus was His name;\",\"born in a manger to His own a stranger,\",\"a man of sorrows, tears and agony!\",\"O how I love Him! how I adore Him!\",\"My breath, my sunshine, my all-in-all!\",\"The great Creator became my Saviour,\",\"and all God’s fulness dwelleth in Him!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0116', 'verse', 2, 1, '[\"What condescension, bringing us redemption,\",\"that in the dead of night, not one faint hope in sight;\",\"God, gracious, tender, laid aside His splendour,\",\"stooping to woo, to win, to save my soul.\",\"O how I love Him...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0116', 'verse', 3, 2, '[\"Without reluctance, flesh and blood, His substance,\",\"He took the form of man, revealed the hidden plan;\",\"O glorious mystery, sacrifice of Calvary!\",\"And now I know He is the great ‘I A\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0117', 117, 'Do not be worried and upset', 'MP', 'en', '1980 Bible Society', '', 0, 0, 0, 1, 1, 'Do not be worried and upset.
Believe in God, believe also in Me,
there are many rooms in My Father’s house,
and I’m going to prepare a place,
prepare a place for you.
I am the way, the truth and the life;
no-one goes to the Father except by Me.
I am the way, the truth and the life,
and I’m going to prepare a place,
prepare a place for you.
After I go and prepare a place for you,
I will come back and take you to Myself,
so that you may come and be where I am:
and I’m going to prepare a place,
prepare a place for you.
I am the way, the truth and the life;
no-one goes to the Father except by Me.
I am the way, the truth and the life,
and I’m going to prepare a place,
prepare a place for you;
and I’m going to prepare a place,
prepare a place for you.');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0117', 'G Taylor');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0117', 'verse', 1, 0, '[\"Do not be worried and upset.\",\"Believe in God, believe also in Me,\",\"there are many rooms in My Father’s house,\",\"and I’m going to prepare a place,\",\"prepare a place for you.\",\"I am the way, the truth and the life;\",\"no-one goes to the Father except by Me.\",\"I am the way, the truth and the life,\",\"and I’m going to prepare a place,\",\"prepare a place for you.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0117', 'verse', 2, 1, '[\"After I go and prepare a place for you,\",\"I will come back and take you to Myself,\",\"so that you may come and be where I am:\",\"and I’m going to prepare a place,\",\"prepare a place for you.\",\"I am the way, the truth and the life;\",\"no-one goes to the Father except by Me.\",\"I am the way, the truth and the life,\",\"and I’m going to prepare a place,\",\"prepare a place for you;\",\"and I’m going to prepare a place,\",\"prepare a place for you.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0118', 118, 'Draw near to God', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'Draw near to God
and He’ll draw near to you;
draw near to God
and He’ll draw near to you.
Lift up holy hands to Him
and sing of what He’s done;
open up your hearts to Him
and praise Him for His Son.');
