INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0120', 'verse', 1, 0, '[\"WOMEN\",\"He who dwells, he who dwells\",\"in the shelter of the Most High,\",\"MEN\",\"he who dwells, he who dwells\",\"in the shelter of the Most High\",\"WOMEN\",\"will rest in the shadow,\",\"the shadow of the Almighty,\",\"MEN\",\"will rest in the shadow,\",\"the shadow of the Almighty.\",\"ALL\",\"And I’ll say of the Lord, ‘He is my refuge’;\",\"and I’ll say of the Lord, ‘He is my strength’.\",\"And I’ll make of the Most High One my dwelling-place,\",\"and I’ll say, ‘He is my God’,\",\"I’ll say, ‘He is my God’,\",\"I will say, ‘He is my God in whom I trust’.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0121', 121, 'Emmanuel, Emmanuel', 'MP', 'en', '1976 C.A. Music/Music Services (Admin. by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Emmanuel, Emmanuel,
His name is called Emmanuel –
God with us,
revealed in us –
His name is called Emmanuel.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0121', 'Bob McGee');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0121', 'Bob McGee');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0121', 'verse', 1, 0, '[\"Emmanuel, Emmanuel,\",\"His name is called Emmanuel –\",\"God with us,\",\"revealed in us –\",\"His name is called Emmanuel.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0122', 122, 'Eternal Father, strong to save', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Eternal Father, strong to save,
whose arm hath bound the restless wave,
who bidd’st the mighty ocean deep
its own appointed limits keep:
O hear us when we cry to Thee
for those in peril on the sea.
O Christ, whose voice the waters heard,
and hushed their raging at Thy word,
who walkedst on the foaming deep,
and calm amid the storm didst sleep:
O hear us when we cry to Thee
for those in peril on the sea.
O Holy Spirit, who didst brood
upon the waters dark and rude,
and bid their angry tumult cease,
and give, for wild confusion, peace:
O hear us when we cry to Thee
for those in peril on the sea.
O Trinity of love and power,
our brethren shield in danger’s hour;');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0122', 'William Whiting');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0122', 'John Bacchus Dykes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0122', 'verse', 1, 0, '[\"Eternal Father, strong to save,\",\"whose arm hath bound the restless wave,\",\"who bidd’st the mighty ocean deep\",\"its own appointed limits keep:\",\"O hear us when we cry to Thee\",\"for those in peril on the sea.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0122', 'verse', 2, 1, '[\"O Christ, whose voice the waters heard,\",\"and hushed their raging at Thy word,\",\"who walkedst on the foaming deep,\",\"and calm amid the storm didst sleep:\",\"O hear us when we cry to Thee\",\"for those in peril on the sea.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0122', 'verse', 3, 2, '[\"O Holy Spirit, who didst brood\",\"upon the waters dark and rude,\",\"and bid their angry tumult cease,\",\"and give, for wild confusion, peace:\",\"O hear us when we cry to Thee\",\"for those in peril on the sea.\"]');
