INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0123', 123, 'Eternal God, we come to You', 'MP', 'en', '©  1983 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Eternal God, we come to You,
we come before Your throne;
we enter by a new and living way,
with confidence we come.
We declare Your faithfulness,
Your promises are true;
we will now draw near to worship You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0123', 'David Fellingham');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0123', 'David Fellingham');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0123', 'Roland Fudge');
