INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0124', 124, 'Exalt the Lord our God', 'MP', 'en', 'Scripture in Song/Maranatha Music/Universal Music Publishing/Print licence adm Song Solutions Daybreak, www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Exalt the Lord our God,
exalt the Lord our God,
and worship at His footstool,
worship at His footstool;
holy is He, holy is He.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0124', 'Rick Ridings');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0124', 'Rick Ridings');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0124', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0124', 'verse', 1, 0, '[\"Exalt the Lord our God,\",\"exalt the Lord our God,\",\"and worship at His footstool,\",\"worship at His footstool;\",\"holy is He, holy is He.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0125', 125, 'Faithful vigil ended', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Faithful vigil ended,
watching, waiting cease:
Master, grant Your servant
his discharge in peace.
All the Spirit promised,
all the Father willed,
now these eyes behold it
perfectly fulfilled.
This Your great deliverance
sets Your people free;
Christ their light uplifted
all the nations see.
Christ, Your people’s glory!
Watching, doubting cease:
grant to us Your servants
our discharge in peace.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0125', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0125', 'David G Wilson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0125', 'verse', 1, 0, '[\"Faithful vigil ended,\",\"watching, waiting cease:\",\"Master, grant Your servant\",\"his discharge in peace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0125', 'verse', 2, 1, '[\"All the Spirit promised,\",\"all the Father willed,\",\"now these eyes behold it\",\"perfectly fulfilled.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0125', 'verse', 3, 2, '[\"This Your great deliverance\",\"sets Your people free;\",\"Christ their light uplifted\",\"all the nations see.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0125', 'verse', 4, 3, '[\"Christ, Your people’s glory!\",\"Watching, doubting cease:\",\"grant to us Your servants\",\"our discharge in peace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0126', 126, 'Facing a task unfinished', 'MP', 'en', 'OMF, Station Approach, Borough Green, Sevenoaks, Kent TN15 8BG', '', 0, 0, 0, 1, 1, 'Facing a task unfinished,
that drives us to our knees,
a need that, undiminished,
rebukes our slothful ease,
we who rejoice to know Thee,
renew before Thy throne
the solemn pledge we owe Thee,
to go and make Thee known.
Where other lords beside Thee
hold their unhindered sway,
where forces that defied Thee
defy Thee still today,
with none to heed their crying
for life, and love, and light,
unnumbered souls are dying,
and pass into the night.
We bear the torch that, flaming,
fell from the hands of those
who gave their lives, proclaiming
that Jesus died and rose.
Ours is the same commission,
the same glad message ours;
fired by the same ambition,
to Thee we yield our powers.
O Father who sustained them,
O Spirit who inspired,
Saviour, whose love constrained them
to toil with zeal untired,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0126', 'Frank Houghton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0126', 'Samuel Sebastian Wesley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0126', 'verse', 1, 0, '[\"Facing a task unfinished,\",\"that drives us to our knees,\",\"a need that, undiminished,\",\"rebukes our slothful ease,\",\"we who rejoice to know Thee,\",\"renew before Thy throne\",\"the solemn pledge we owe Thee,\",\"to go and make Thee known.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0126', 'verse', 2, 1, '[\"Where other lords beside Thee\",\"hold their unhindered sway,\",\"where forces that defied Thee\",\"defy Thee still today,\",\"with none to heed their crying\",\"for life, and love, and light,\",\"unnumbered souls are dying,\",\"and pass into the night.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0126', 'verse', 3, 2, '[\"We bear the torch that, flaming,\",\"fell from the hands of those\",\"who gave their lives, proclaiming\",\"that Jesus died and rose.\",\"Ours is the same commission,\",\"the same glad message ours;\",\"fired by the same ambition,\",\"to Thee we yield our powers.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0126', 'verse', 4, 3, '[\"O Father who sustained them,\",\"O Spirit who inspired,\",\"Saviour, whose love constrained them\",\"to toil with zeal untired,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0127', 127, 'Father, although I cannot see', 'MP', 'en', 'Scripture Union            ? Norman Warren, administered by The Jubilate Group, 4 Thorne Park Road, Torquay TQ2 6RX. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'Father, although I cannot see
the future You have planned,
and though the path is sometimes dark
and hard to understand:
yet give me faith, through joy and pain,
to trace Your loving hand.
When I recall that in the past
Your promises have stood
through each perplexing circumstance
and every changing mood,
I rest content that all things work
together for my good.
Whatever, then, the future brings
of good or seeming ill,
I ask for strength to follow You
and grace to trust You still;
and I would look for no reward,
except to do Your will.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0127', 'John Eddison');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0127', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0127', 'verse', 1, 0, '[\"Father, although I cannot see\",\"the future You have planned,\",\"and though the path is sometimes dark\",\"and hard to understand:\",\"yet give me faith, through joy and pain,\",\"to trace Your loving hand.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0127', 'verse', 2, 1, '[\"When I recall that in the past\",\"Your promises have stood\",\"through each perplexing circumstance\",\"and every changing mood,\",\"I rest content that all things work\",\"together for my good.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0127', 'verse', 3, 2, '[\"Whatever, then, the future brings\",\"of good or seeming ill,\",\"I ask for strength to follow You\",\"and grace to trust You still;\",\"and I would look for no reward,\",\"except to do Your will.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0128', 128, 'I will sing Your praises', 'MP', 'en', '©  1984 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Father God, I wonder
how I managed to exist
without the knowledge
of Your parenthood
and Your loving care.
But now I am Your son,
I am adopted in Your family,
and I can never be alone
’cause, Father God,
You’re there beside me.
I will sing Your praises,
I will sing Your praises,
I will sing Your praises for evermore.
I will sing Your praises,
I will sing Your praises,
I will sing Your praises for evermore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0128', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0128', 'Ian Smale');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0128', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0128', 'verse', 1, 0, '[\"Father God, I wonder\",\"how I managed to exist\",\"without the knowledge\",\"of Your parenthood\",\"and Your loving care.\",\"But now I am Your son,\",\"I am adopted in Your family,\",\"and I can never be alone\",\"’cause, Father God,\",\"You’re there beside me.\",\"I will sing Your praises,\",\"I will sing Your praises,\",\"I will sing Your praises for evermore.\",\"I will sing Your praises,\",\"I will sing Your praises,\",\"I will sing Your praises for evermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0129', 129, 'Father God, I love You', 'MP', 'en', 'Joan Robinson, 47 Woodlands Road, Beaumont, Lancaster LA1 2EH', '', 0, 0, 0, 1, 0, 'Father God, I love You,
Father God, I love You,
Father God, I love You,
come into my life.
Jesus, I love You,
Jesus, I love You,
Jesus, I love You,
come into my life.
Spirit, I love You,
Spirit, I love You,
Spirit, I love You,
come into my life.
Alleluia,
alleluia,
alleluia,
alleluia.
(repeat last verse)');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0129', 'Joan Robinson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0129', 'Joan Robinson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0129', 'verse', 1, 0, '[\"Father God, I love You,\",\"Father God, I love You,\",\"Father God, I love You,\",\"come into my life.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0129', 'verse', 2, 1, '[\"Jesus, I love You,\",\"Jesus, I love You,\",\"Jesus, I love You,\",\"come into my life.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0129', 'verse', 3, 2, '[\"Spirit, I love You,\",\"Spirit, I love You,\",\"Spirit, I love You,\",\"come into my life.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0129', 'verse', 4, 3, '[\"Alleluia,\",\"alleluia,\",\"alleluia,\",\"alleluia.\",\"(repeat last verse)\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0130', 130, 'Father God, the Lord, Creator', 'MP', 'en', 'John Richards/Renewal Servicing, PO Box 17, Shepperton, Middlesex TW17 8NU', '', 0, 0, 0, 1, 1, 'Father God, the Lord, Creator,
by whose hand we all are fed,
in Your mercy re-create us
at the breaking of the bread.
Christ our Lord, be present with us,
risen victorious from the dead!
In Your mercy may we know You,
in the breaking of the bread.
Holy Spirit, God’s empowering,
by whose life the Church is led;
in Your mercy, send us strengthened');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0130', 'John Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0130', 'H Albert');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0130', 'verse', 1, 0, '[\"Father God, the Lord, Creator,\",\"by whose hand we all are fed,\",\"in Your mercy re-create us\",\"at the breaking of the bread.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0130', 'verse', 2, 1, '[\"Christ our Lord, be present with us,\",\"risen victorious from the dead!\",\"In Your mercy may we know You,\",\"in the breaking of the bread.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0130', 'verse', 3, 2, '[\"Holy Spirit, God’s empowering,\",\"by whose life the Church is led;\",\"in Your mercy, send us strengthened\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0131', 131, 'Father God, we worship You', 'MP', 'en', '©  1981 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Father God, we worship You,
make us part of all You do.
As You move among us now
we worship You.
Jesus, King, we worship You,
help us listen now to You.
As You move among us now
we worship You.
Spirit pure, we worship You,
with Your fire our zeal renew.
As You move among us now
we worship You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0131', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0131', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0131', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0131', 'verse', 1, 0, '[\"Father God, we worship You,\",\"make us part of all You do.\",\"As You move among us now\",\"we worship You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0131', 'verse', 2, 1, '[\"Jesus, King, we worship You,\",\"help us listen now to You.\",\"As You move among us now\",\"we worship You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0131', 'verse', 3, 2, '[\"Spirit pure, we worship You,\",\"with Your fire our zeal renew.\",\"As You move among us now\",\"we worship You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0132', 132, 'Father, hear the prayer we offer', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Father, hear the prayer we offer:
not for ease that prayer shall be,
but for strength, that we may ever
live our lives courageously.
Not for ever in green pastures
do we ask our way to be:
but by steep and rugged pathways
would we strive to climb to Thee.
Not for ever by still waters
would we idly quiet stay;
but would smite the living fountains');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0132', 'Love Maria Willis');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0132', 'verse', 1, 0, '[\"Father, hear the prayer we offer:\",\"not for ease that prayer shall be,\",\"but for strength, that we may ever\",\"live our lives courageously.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0132', 'verse', 2, 1, '[\"Not for ever in green pastures\",\"do we ask our way to be:\",\"but by steep and rugged pathways\",\"would we strive to climb to Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0132', 'verse', 3, 2, '[\"Not for ever by still waters\",\"would we idly quiet stay;\",\"but would smite the living fountains\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0133', 133, 'Father, I place into Your hands', 'MP', 'en', '©  1975 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Father, I place into Your hands
the things that I can’t do.
Father, I place into Your hands
the times that I’ve been through.
Father, I place into Your hands
the way that I should go,
for I know I always can trust You.
Father, I place into Your hands
my friends and family.
Father, I place into Your hands
the things that trouble me.
Father, I place into Your hands
the person I would be,
for I know I always can trust You.
Father, we love to seek Your face,
we love to hear Your voice.
Father, we love to sing Your praise,
and in Your name rejoice.
Father, we love to walk with You
and in Your presence rest,
for we know we always can trust You.
Father, I want to be with You
and do the things You do.
Father, I want to speak the words
that You are speaking too.
Father, I want to love the ones
that You will draw to You,
for I know that I am one with You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0133', 'Jenny Hewer');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0133', 'Jenny Hewer');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0133', 'verse', 1, 0, '[\"Father, I place into Your hands\",\"the things that I can’t do.\",\"Father, I place into Your hands\",\"the times that I’ve been through.\",\"Father, I place into Your hands\",\"the way that I should go,\",\"for I know I always can trust You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0133', 'verse', 2, 1, '[\"Father, I place into Your hands\",\"my friends and family.\",\"Father, I place into Your hands\",\"the things that trouble me.\",\"Father, I place into Your hands\",\"the person I would be,\",\"for I know I always can trust You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0133', 'verse', 3, 2, '[\"Father, we love to seek Your face,\",\"we love to hear Your voice.\",\"Father, we love to sing Your praise,\",\"and in Your name rejoice.\",\"Father, we love to walk with You\",\"and in Your presence rest,\",\"for we know we always can trust You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0133', 'verse', 4, 3, '[\"Father, I want to be with You\",\"and do the things You do.\",\"Father, I want to speak the words\",\"that You are speaking too.\",\"Father, I want to love the ones\",\"that You will draw to You,\",\"for I know that I am one with You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0134', 134, 'We will crown Him', 'MP', 'en', '©  1985 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Father in heaven,
our voices we raise:
receive our devotion,
receive now our praise
as we sing of the glory
of all that You’ve done –
the greatest love-story
that’s ever been sung.
And we will crown You Lord of all,
yes, we will crown You Lord of all,
for You have won the victory:
yes, we will crown You Lord of all.
Father in heaven,
our lives are Your own;
we’ve been caught by a vision
of Jesus alone –
who came as a servant
to free us from sin:
Father in heaven,
our worship we bring.
And we will crown...
We will sing, ‘Alleluia’,
we will sing to the King,
to our mighty deliverer
our alleluias will ring.
Yes, our praise is resounding
to the Lamb on the throne:
He alone is exalted
through the love He has shown.
And we will crown...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0134', 'Dave Bilbrough');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0134', 'Dave Bilbrough');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0134', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0134', 'verse', 1, 0, '[\"Father in heaven,\",\"our voices we raise:\",\"receive our devotion,\",\"receive now our praise\",\"as we sing of the glory\",\"of all that You’ve done –\",\"the greatest love-story\",\"that’s ever been sung.\",\"And we will crown You Lord of all,\",\"yes, we will crown You Lord of all,\",\"for You have won the victory:\",\"yes, we will crown You Lord of all.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0134', 'verse', 2, 1, '[\"Father in heaven,\",\"our lives are Your own;\",\"we’ve been caught by a vision\",\"of Jesus alone –\",\"who came as a servant\",\"to free us from sin:\",\"Father in heaven,\",\"our worship we bring.\",\"And we will crown...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0134', 'verse', 3, 2, '[\"We will sing, ‘Alleluia’,\",\"we will sing to the King,\",\"to our mighty deliverer\",\"our alleluias will ring.\",\"Yes, our praise is resounding\",\"to the Lamb on the throne:\",\"He alone is exalted\",\"through the love He has shown.\",\"And we will crown...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0135', 135, 'Blessèd be the Lord God Almighty', 'MP', 'en', '1985 Scripture in Song/Maranatha Music/Universal Music Publishing/Print licence adm Song Solutions Daybreak, www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Father in heaven, how we love You,
we lift Your name in all the earth.
May Your kingdom be established in our praises
as Your people declare Your mighty works.
Blessèd be the Lord God almighty,
who was and is and is to come,
blessèd be the Lord God almighty,
who reigns for evermore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0135', 'Bob Fitts');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0135', 'Bob Fitts');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0135', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0135', 'verse', 1, 0, '[\"Father in heaven, how we love You,\",\"we lift Your name in all the earth.\",\"May Your kingdom be established in our praises\",\"as Your people declare Your mighty works.\",\"Blessèd be the Lord God almighty,\",\"who was and is and is to come,\",\"blessèd be the Lord God almighty,\",\"who reigns for evermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0136', 136, 'Father, sending Your anointed Son', 'MP', 'en', '1985 John Richards/Renewal Servicing, PO Box 17, Shepperton, Middlesex TW17 8NU', '', 0, 0, 0, 1, 1, 'Father, sending Your anointed
Son to save, forgive, and heal;
and, through Him, Your Holy Spirit,
to make our salvation real;
Look upon our ills and trouble,
and on those who suffer much.
Send Your Church the Spirit’s unction
in Christ’s name to heal and touch.
Grant forgiveness to the faithful;
bring to unity their prayer;
use it for Your work unhindered,
through both sacrament and care.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0136', 'John Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0136', 'Edward Henry Thorne');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0136', 'verse', 1, 0, '[\"Father, sending Your anointed\",\"Son to save, forgive, and heal;\",\"and, through Him, Your Holy Spirit,\",\"to make our salvation real;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0136', 'verse', 2, 1, '[\"Look upon our ills and trouble,\",\"and on those who suffer much.\",\"Send Your Church the Spirit’s unction\",\"in Christ’s name to heal and touch.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0136', 'verse', 3, 2, '[\"Grant forgiveness to the faithful;\",\"bring to unity their prayer;\",\"use it for Your work unhindered,\",\"through both sacrament and care.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0137', 137, 'Father, make us one', 'MP', 'en', 'Scripture in Song/Maranatha Music/Universal Music Publishing/Print licence adm Song Solutions Daybreak, www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Father, make us one,
Father, make us one,
that the world may know Thou hast sent the Son,
Father, make us one.
Behold how pleasant and how good it is
for brethren to dwell in unity,
for there the Lord commands the blessing,
life for evermore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0137', 'Rick Ridings');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0137', 'Rick Ridings');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0137', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0137', 'verse', 1, 0, '[\"Father, make us one,\",\"Father, make us one,\",\"that the world may know Thou hast sent the Son,\",\"Father, make us one.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0137', 'verse', 2, 1, '[\"Behold how pleasant and how good it is\",\"for brethren to dwell in unity,\",\"for there the Lord commands the blessing,\",\"life for evermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0138', 138, 'Thanks be to God', 'MP', 'en', 'Copyright 1978 Sovereign Music UK. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'Father, never was love so near;
tender, my deepest wounds to heal.
Precious to me,
Your gift of love;
for me You gave
Your only Son.
And now thanks be to God
for His gift beyond words,
the Son whom He loved;
no, He did not withhold Him,
but with Him gave everything;
now He’s everything to me.
Jesus, the heart of God revealed,
with us, feeling the pain we feel.
Cut to the heart,
wounded for me,
taking the blame,
making me clean.
And now thanks be to God...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0138', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0138', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0138', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0138', 'verse', 1, 0, '[\"Father, never was love so near;\",\"tender, my deepest wounds to heal.\",\"Precious to me,\",\"Your gift of love;\",\"for me You gave\",\"Your only Son.\",\"And now thanks be to God\",\"for His gift beyond words,\",\"the Son whom He loved;\",\"no, He did not withhold Him,\",\"but with Him gave everything;\",\"now He’s everything to me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0138', 'verse', 2, 1, '[\"Jesus, the heart of God revealed,\",\"with us, feeling the pain we feel.\",\"Cut to the heart,\",\"wounded for me,\",\"taking the blame,\",\"making me clean.\",\"And now thanks be to God...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0139', 139, 'Father, we adore You', 'MP', 'en', 'CCCM/Maranatha Music/Universal Music Publishing/Print licence adm Song Solutions Daybreak, www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Father, we adore You,
lay our lives before You:
how we love You!
Jesus, we adore You,
lay our lives before You:
how we love You!
Spirit, we adore You,
lay our lives before You:
how we love You!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0139', 'Terrye Coelho');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0139', 'Terrye Coelho');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0139', 'verse', 1, 0, '[\"Father, we adore You,\",\"lay our lives before You:\",\"how we love You!\"]');
