INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0140', 140, 'Father, we adore You', 'MP', 'en', '1982 Shadow Spring Music/Music Services (Admin. by Song Solutnios Copycare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Father, we adore You,
You’ve drawn us to this place;
we bow down before You,
humbly on our face.
All the earth shall worship
at the throne of the King;
of His great and awesome power,
we shall sing!
Jesus, we love You,
because You first loved us;
You reached out and healed us
with Your mighty touch.
All the earth...
Spirit, we need You,
to lift us from this mire;
consume and empower us
with Your holy fire.
All the earth...
Holy is He; blessèd is He;
worthy is He; gracious is He;
faithful is He; awesome is He;
Saviour is He; Master is He;
mighty is He:
have mercy on me.');
