INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0141', 141, 'Father, Your love is precious', 'MP', 'en', '©  1983 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Father, Your love is precious beyond all loves,
Father, Your love overwhelms me.
Father, Your love is precious beyond all loves,
Father, Your love overwhelms me.
So I lift up my hands,
an expression of my love,
and I give You my heart
in joyful obedience.
Father, Your love is precious beyond all loves,
Father, Your love overwhelms me.');
