INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0143', 143, 'Fight the good fight', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Fight the good fight with all thy might;
Christ is thy strength, and Christ thy right.
Lay hold on life, and it shall be
thy joy and crown eternally.
Run the straight race through God’s good grace,
lift up thine eyes, and seek His face;
life with its path before thee lies;
Christ is the way, and Christ the prize.
Cast care aside, lean on thy guide,
His boundless mercy will provide;
lean, and thy trusting soul shall prove
Christ is thy life, and Christ thy love.
Faint not, nor fear, His arm is near,
He changeth not, and thou art dear;
only believe, and thou shalt see
that Christ is all-in-all to thee.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0143', 'John Samuel Bewley Monsell');
