INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0143', 'verse', 2, 1, '[\"Run the straight race through God’s good grace,\",\"lift up thine eyes, and seek His face;\",\"life with its path before thee lies;\",\"Christ is the way, and Christ the prize.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0143', 'verse', 3, 2, '[\"Cast care aside, lean on thy guide,\",\"His boundless mercy will provide;\",\"lean, and thy trusting soul shall prove\",\"Christ is thy life, and Christ thy love.\"]');
