INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0150', 150, 'For His name is exalted', 'MP', 'en', 'Scripture in Song/Maranatha Music/Universal Music Publishing/Print licence adm Song Solutions Daybreak, www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'For His name is exalted,
His glory above heaven and earth.
Holy is the Lord God almighty,
who was and who is and who is to come.
For His name is exalted,
His glory above heaven and earth.
Holy is the Lord God almighty,
who sitteth on the throne and who lives for evermore.');
