INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0151', 151, 'For I’m building a people of power', 'MP', 'en', '©  1977 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'For I’m building a people of power
and I’m making a people of praise,
that will move through this land by My Spirit,
and will glorify My precious name.
Build Your Church, Lord,
make us strong, Lord,
join our hearts, Lord, through Your Son;
make us one, Lord, in Your body,
in the kingdom of Your Son.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0151', 'Dave Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0151', 'Dave Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0151', 'Roger Mayor');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0151', 'verse', 1, 0, '[\"For I’m building a people of power\",\"and I’m making a people of praise,\",\"that will move through this land by My Spirit,\",\"and will glorify My precious name.\",\"Build Your Church, Lord,\",\"make us strong, Lord,\",\"join our hearts, Lord, through Your Son;\",\"make us one, Lord, in Your body,\",\"in the kingdom of Your Son.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0152', 152, 'For the beauty of the earth', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'For the beauty of the earth,
for the beauty of the skies,
for the love which from our birth
over and around us lies;
Father, unto You we raise
this our sacrifice of praise.
For the beauty of each hour
of the day and of the night,
hill and vale, and tree and flower,
sun and moon, and stars of light;
Father, unto You we raise
this our sacrifice of praise.
For the joy of love from God,
that we share on earth below;
for our friends and family,
and the love that they can show;
Father, unto You we raise
this our sacrifice of praise.
For each perfect gift divine
to our race so freely given,
thank You Lord that they are mine,
here on earth as gifts from heaven;
Father, unto You we raise
this our sacrifice of praise.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0152', 'Folliott Pierpoint');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0152', 'Geoffrey Shaw');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0152', 'verse', 1, 0, '[\"For the beauty of the earth,\",\"for the beauty of the skies,\",\"for the love which from our birth\",\"over and around us lies;\",\"Father, unto You we raise\",\"this our sacrifice of praise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0152', 'verse', 2, 1, '[\"For the beauty of each hour\",\"of the day and of the night,\",\"hill and vale, and tree and flower,\",\"sun and moon, and stars of light;\",\"Father, unto You we raise\",\"this our sacrifice of praise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0152', 'verse', 3, 2, '[\"For the joy of love from God,\",\"that we share on earth below;\",\"for our friends and family,\",\"and the love that they can show;\",\"Father, unto You we raise\",\"this our sacrifice of praise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0152', 'verse', 4, 3, '[\"For each perfect gift divine\",\"to our race so freely given,\",\"thank You Lord that they are mine,\",\"here on earth as gifts from heaven;\",\"Father, unto You we raise\",\"this our sacrifice of praise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0153', 153, 'For the fruits of His creation', 'MP', 'en', '1970 Stainer & Bell Ltd www.stainer.co.uk', '', 0, 0, 0, 1, 1, 'For the fruits of His creation,
thanks be to God!
For His gifts to every nation,
thanks be to God!
For the ploughing, sowing, reaping,
silent growth while we are sleeping;
future needs in earth’s safe keeping,
thanks be to God!
In the just reward of labour,
God’s will is done;
in the help we give our neighbour,
God’s will is done;
in our world-wide task of caring
for the hungry and despairing;
in the harvests we are sharing,
God’s will is done.
For the harvests of the Spirit,
thanks be to God!
For the good we all inherit,
thanks be to God!
For the wonders that astound us,
for the truths that still confound us;
most of all, that love has found us,
thanks be to God!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0153', 'Fred Pratt Green');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0153', 'Francis Jackson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0153', 'verse', 1, 0, '[\"For the fruits of His creation,\",\"thanks be to God!\",\"For His gifts to every nation,\",\"thanks be to God!\",\"For the ploughing, sowing, reaping,\",\"silent growth while we are sleeping;\",\"future needs in earth’s safe keeping,\",\"thanks be to God!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0153', 'verse', 2, 1, '[\"In the just reward of labour,\",\"God’s will is done;\",\"in the help we give our neighbour,\",\"God’s will is done;\",\"in our world-wide task of caring\",\"for the hungry and despairing;\",\"in the harvests we are sharing,\",\"God’s will is done.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0153', 'verse', 3, 2, '[\"For the harvests of the Spirit,\",\"thanks be to God!\",\"For the good we all inherit,\",\"thanks be to God!\",\"For the wonders that astound us,\",\"for the truths that still confound us;\",\"most of all, that love has found us,\",\"thanks be to God!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0154', 154, 'For the might of Your arm', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'For the might of Your arm we bless You,
our God, our fathers’ God;
You have kept Your pilgrim people
by the strength of Your staff and rod;
You have called us to the journey
which faithless feet ne’er trod;
For the might of Your arm we bless You,
our God, our fathers’ God.
For the love of Christ constraining,
that bound their hearts as one;
for the faith in truth and freedom
in which their work was done;
for the peace of God’s evangel
wherewith their feet were shod;
For the might...
We are watchers of a beacon
whose light must never die;
we are guardians of an altar
that shows You ever nigh;
we are children of Your freemen
who sleep beneath the sod;
For the might...
May the shadow of Your presence
around our camp be spread;
baptize us with the courage
You gave unto our dead;
O keep us in the pathway
their saintly feet have trod;
For the might...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0154', 'Charles Silvester Horne');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0154', 'verse', 1, 0, '[\"For the might of Your arm we bless You,\",\"our God, our fathers’ God;\",\"You have kept Your pilgrim people\",\"by the strength of Your staff and rod;\",\"You have called us to the journey\",\"which faithless feet ne’er trod;\",\"For the might of Your arm we bless You,\",\"our God, our fathers’ God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0154', 'verse', 2, 1, '[\"For the love of Christ constraining,\",\"that bound their hearts as one;\",\"for the faith in truth and freedom\",\"in which their work was done;\",\"for the peace of God’s evangel\",\"wherewith their feet were shod;\",\"For the might...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0154', 'verse', 3, 2, '[\"We are watchers of a beacon\",\"whose light must never die;\",\"we are guardians of an altar\",\"that shows You ever nigh;\",\"we are children of Your freemen\",\"who sleep beneath the sod;\",\"For the might...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0154', 'verse', 4, 3, '[\"May the shadow of Your presence\",\"around our camp be spread;\",\"baptize us with the courage\",\"You gave unto our dead;\",\"O keep us in the pathway\",\"their saintly feet have trod;\",\"For the might...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0155', 155, 'For this purpose', 'MP', 'en', '©  1985 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'For this purpose Christ was revealed,
to destroy all the works of the evil one.
Christ in us has overcome,
so with gladness we sing
and welcome His kingdom in.
MEN Over sin He has conquered:
WOMEN hallelujah! He has conquered.
MEN Over death victorious:
WOMEN hallelujah! victorious.
MEN Over sickness He has triumphed:
WOMEN hallelujah! He has triumphed.
ALL Jesus reigns over all!
2 In the name of Jesus we stand;
by the power of His blood
we now claim this ground:
Satan has no authority here,
powers of darkness must flee,
for Christ has the victory.
Over sin...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0155', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0155', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0155', 'verse', 1, 0, '[\"For this purpose Christ was revealed,\",\"to destroy all the works of the evil one.\",\"Christ in us has overcome,\",\"so with gladness we sing\",\"and welcome His kingdom in.\",\"MEN Over sin He has conquered:\",\"WOMEN hallelujah! He has conquered.\",\"MEN Over death victorious:\",\"WOMEN hallelujah! victorious.\",\"MEN Over sickness He has triumphed:\",\"WOMEN hallelujah! He has triumphed.\",\"ALL Jesus reigns over all!\",\"2 In the name of Jesus we stand;\",\"by the power of His blood\",\"we now claim this ground:\",\"Satan has no authority here,\",\"powers of darkness must flee,\",\"for Christ has the victory.\",\"Over sin...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0156', 156, 'For unto us a child is born', 'MP', 'en', 'control                        ? 1986 Phil Burt', '', 0, 0, 0, 1, 1, 'For unto us a child is born,
unto us a son is given;
and the government
shall be upon His shoulders.
And His name shall be called
wonderful, counsellor,
the mighty God,
the everlasting Father,
and the Prince of peace is He.');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0156', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0156', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0156', 'verse', 1, 0, '[\"For unto us a child is born,\",\"unto us a son is given;\",\"and the government\",\"shall be upon His shoulders.\",\"And His name shall be called\",\"wonderful, counsellor,\",\"the mighty God,\",\"the everlasting Father,\",\"and the Prince of peace is He.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0157', 157, 'For unto us a child is born', 'MP', 'en', 'Copyright 1984  Restoration Music Sovereignmusic@aol.com', '', 0, 0, 0, 1, 1, 'For unto us a child is born,
unto us a son is given,
and the government shall be upon His shoulder;
for unto us a child is born,
unto us a son is given,
and the government shall be upon His shoulder.
And He will be called wonderful,
wonderful counsellor, mighty God,
the everlasting Father, Prince of peace,
Mighty God.
And there shall be no end
to the increase of His rule,
to the increase of His government and peace;
for He shall sit on David’s throne
upholding righteousness,
our God shall accomplish this.
And He will be called...
For He is the mighty God,
He is the Prince of peace,
the King of kings and Lord of lords:
all honour to the King,
all glory to His name,
for now and for evermore!
And He will be called...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0157', 'David Hadden');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0157', 'David Hadden');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0157', 'verse', 1, 0, '[\"For unto us a child is born,\",\"unto us a son is given,\",\"and the government shall be upon His shoulder;\",\"for unto us a child is born,\",\"unto us a son is given,\",\"and the government shall be upon His shoulder.\",\"And He will be called wonderful,\",\"wonderful counsellor, mighty God,\",\"the everlasting Father, Prince of peace,\",\"Mighty God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0157', 'verse', 2, 1, '[\"And there shall be no end\",\"to the increase of His rule,\",\"to the increase of His government and peace;\",\"for He shall sit on David’s throne\",\"upholding righteousness,\",\"our God shall accomplish this.\",\"And He will be called...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0157', 'verse', 3, 2, '[\"For He is the mighty God,\",\"He is the Prince of peace,\",\"the King of kings and Lord of lords:\",\"all honour to the King,\",\"all glory to His name,\",\"for now and for evermore!\",\"And He will be called...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0158', 158, 'For Thou, O Lord', 'MP', 'en', '1977 Pete Sanchez Jr, 4723 Hickory Downs, Houston, TX 77084, USA', '', 0, 0, 0, 1, 1, 'For Thou, O Lord,
art high above all the earth;
Thou art exalted far above all gods.
For Thou, O Lord,
art high above all the earth;
Thou art exalted far above all gods.
I exalt Thee, I exalt Thee,
I exalt Thee, O Lord;
I exalt Thee, I exalt Thee,
I exalt Thee, O Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0158', 'Pete Sanchez');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0158', 'Pete Sanchez');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0158', 'verse', 1, 0, '[\"For Thou, O Lord,\",\"art high above all the earth;\",\"Thou art exalted far above all gods.\",\"For Thou, O Lord,\",\"art high above all the earth;\",\"Thou art exalted far above all gods.\",\"I exalt Thee, I exalt Thee,\",\"I exalt Thee, O Lord;\",\"I exalt Thee, I exalt Thee,\",\"I exalt Thee, O Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0159', 159, 'Forth in Thy name, O Lord, I go', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Forth in Thy name, O Lord, I go,
my daily labour to pursue,
Thee, only Thee, resolved to know
in all I think, or speak, or do.
The task Thy wisdom hath assigned
O let me cheerfully fulfil;
in all my works Thy presence find,
and prove Thy acceptable will.
Thee may I set at my right hand,
whose eyes my inmost substance see;
and labour on at Thy command,
and offer all my works to Thee.
Give me to bear Thy easy yoke,
and every moment watch and pray,
and still to things eternal look,
and hasten to Thy glorious day.
For Thee delightfully employ
whate’er Thy bounteous grace hath given,
and run my course with even joy,
and closely walk with Thee to heaven.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0159', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0159', 'Orlando Gibbons');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0159', 'verse', 1, 0, '[\"Forth in Thy name, O Lord, I go,\",\"my daily labour to pursue,\",\"Thee, only Thee, resolved to know\",\"in all I think, or speak, or do.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0159', 'verse', 2, 1, '[\"The task Thy wisdom hath assigned\",\"O let me cheerfully fulfil;\",\"in all my works Thy presence find,\",\"and prove Thy acceptable will.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0159', 'verse', 3, 2, '[\"Thee may I set at my right hand,\",\"whose eyes my inmost substance see;\",\"and labour on at Thy command,\",\"and offer all my works to Thee.\"]');
