INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0160', 160, 'Forty days and forty nights', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Forty days and forty nights
Thou wast fasting in the wild;
forty days and forty nights
tempted and yet undefiled.
Sunbeams scorching all the day,
chilly dew-drops nightly shed,
prowling beasts about Thy way,
stones Thy pillow, earth Thy bed.
Let us Thy endurance share
and from earthly greed abstain,
with Thee watching unto prayer,
with Thee strong to suffer pain.
Then if evil on us press,
flesh or spirit to assail,
victor in the wilderness,
may we never faint or fail!
So shall peace divine be ours;
holier gladness ours shall be;
come to us angelic powers,
such as ministered to Thee.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0160', 'George Hunt Smyttan');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0160', 'Martin Herbst');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0160', 'verse', 1, 0, '[\"Forty days and forty nights\",\"Thou wast fasting in the wild;\",\"forty days and forty nights\",\"tempted and yet undefiled.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0160', 'verse', 2, 1, '[\"Sunbeams scorching all the day,\",\"chilly dew-drops nightly shed,\",\"prowling beasts about Thy way,\",\"stones Thy pillow, earth Thy bed.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0160', 'verse', 3, 2, '[\"Let us Thy endurance share\",\"and from earthly greed abstain,\",\"with Thee watching unto prayer,\",\"with Thee strong to suffer pain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0160', 'verse', 4, 3, '[\"Then if evil on us press,\",\"flesh or spirit to assail,\",\"victor in the wilderness,\",\"may we never faint or fail!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0160', 'verse', 5, 4, '[\"So shall peace divine be ours;\",\"holier gladness ours shall be;\",\"come to us angelic powers,\",\"such as ministered to Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0161', 161, 'Freely, for the love He bears us', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Freely, for the love He bears us,
God has made His purpose plain:
Christ has died and Christ is risen,
Christ will come again.
Christ has died, the world’s Redeemer,
Lamb of God for sinners slain:
Christ has died...
Christ is risen, high-ascended,
Lord of all to rule and reign:
Christ has died...
Christ is coming, King of glory,
firmly then the faith maintain:
Christ has died...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0161', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0161', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0161', 'verse', 1, 0, '[\"Freely, for the love He bears us,\",\"God has made His purpose plain:\",\"Christ has died and Christ is risen,\",\"Christ will come again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0161', 'verse', 2, 1, '[\"Christ has died, the world’s Redeemer,\",\"Lamb of God for sinners slain:\",\"Christ has died...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0161', 'verse', 3, 2, '[\"Christ is risen, high-ascended,\",\"Lord of all to rule and reign:\",\"Christ has died...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0161', 'verse', 4, 3, '[\"Christ is coming, King of glory,\",\"firmly then the faith maintain:\",\"Christ has died...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0162', 162, 'The Servant King', 'MP', 'en', '© 1983 Thankyou Music/Adm. by Capitol CMG Publishing worldwide excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'From heaven You came, helpless babe,
entered our world, Your glory veiled,
not to be served but to serve,
and give Your life that we might live.
This is our God, the Servant King,
He calls us now to follow Him,
to bring our lives as a daily offering
of worship to the Servant King.
There in the garden of tears
my heavy load He chose to bear;
His heart with sorrow was torn,
‘Yet not my will but yours,’ He said.
This is our God...
Come see His hands and His feet,
the scars that speak of sacrifice,
hands that flung stars into space
to cruel nails surrendered.
This is our God...
So let us learn how to serve
and in our lives enthrone Him,
each other’s needs to prefer,
for it is Christ we’re serving.
This is our God...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0162', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0162', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0162', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0162', 'verse', 1, 0, '[\"From heaven You came, helpless babe,\",\"entered our world, Your glory veiled,\",\"not to be served but to serve,\",\"and give Your life that we might live.\",\"This is our God, the Servant King,\",\"He calls us now to follow Him,\",\"to bring our lives as a daily offering\",\"of worship to the Servant King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0162', 'verse', 2, 1, '[\"There in the garden of tears\",\"my heavy load He chose to bear;\",\"His heart with sorrow was torn,\",\"‘Yet not my will but yours,’ He said.\",\"This is our God...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0162', 'verse', 3, 2, '[\"Come see His hands and His feet,\",\"the scars that speak of sacrifice,\",\"hands that flung stars into space\",\"to cruel nails surrendered.\",\"This is our God...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0162', 'verse', 4, 3, '[\"So let us learn how to serve\",\"and in our lives enthrone Him,\",\"each other’s needs to prefer,\",\"for it is Christ we’re serving.\",\"This is our God...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0163', 163, 'From the rising of the sun', 'MP', 'en', '© 1976 Integrity\'s Hosanna! Music / adm worldwide by Capitol CMG Publishing excl UK admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, '');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0163', 'Paul S Deming');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0163', 'Paul S Deming');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0164', 164, 'From the sun’s rising', 'MP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 0, 'From the sun’s rising unto the sun’s setting,
Jesus our Lord shall be great in the earth;
and all earth’s kingdoms shall be His dominion –
all of creation shall sing of His worth.
Let every heart, every voice,
every tongue join with spirits ablaze;
one in His love,
we will circle the world
with the song of His praise.
O let all His people rejoice,
and let all the earth hear His voice!
To every tongue, tribe and nation He sends us,
to make disciples, to teach and baptize;
for all authority to Him is given;
now as His witnesses we shall arise.
Let every heart...
Come let us join with the Church from all nations,
cross every border, throw wide every door;
workers with Him as He gathers His harvest,
till earth’s far corners our Saviour adore.
Let every heart...
Let all His people rejoice,
and let all the earth hear His voice!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0164', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0164', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0164', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0164', 'verse', 1, 0, '[\"From the sun’s rising unto the sun’s setting,\",\"Jesus our Lord shall be great in the earth;\",\"and all earth’s kingdoms shall be His dominion –\",\"all of creation shall sing of His worth.\",\"Let every heart, every voice,\",\"every tongue join with spirits ablaze;\",\"one in His love,\",\"we will circle the world\",\"with the song of His praise.\",\"O let all His people rejoice,\",\"and let all the earth hear His voice!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0164', 'verse', 2, 1, '[\"To every tongue, tribe and nation He sends us,\",\"to make disciples, to teach and baptize;\",\"for all authority to Him is given;\",\"now as His witnesses we shall arise.\",\"Let every heart...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0164', 'verse', 3, 2, '[\"Come let us join with the Church from all nations,\",\"cross every border, throw wide every door;\",\"workers with Him as He gathers His harvest,\",\"till earth’s far corners our Saviour adore.\",\"Let every heart...\",\"Let all His people rejoice,\",\"and let all the earth hear His voice!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0165', 165, 'Give me a heart', 'MP', 'en', '1988 Gillian Hutchinson', '', 0, 0, 0, 1, 1, 'Give me a heart that will love the unlovely,
open my eyes to the needy and lost,
help me, O Lord, to show Your love in action,
give, without counting the cost,
give, without counting the cost.
Help me remember I’m empty without You,
help me to find my strength only in You.
I can give nothing unless You first fill me,
Your love alone must shine through,
Your love alone must shine through.
Make me be willing to go where You send me,
make me be ready to answer Your call.
Give me a heart that rejoices to serve You,
sharing the best love of all,
sharing the best love of all.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0165', 'Gillian E Hutchinson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0165', 'Gillian E Hutchinson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0165', 'verse', 1, 0, '[\"Give me a heart that will love the unlovely,\",\"open my eyes to the needy and lost,\",\"help me, O Lord, to show Your love in action,\",\"give, without counting the cost,\",\"give, without counting the cost.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0165', 'verse', 2, 1, '[\"Help me remember I’m empty without You,\",\"help me to find my strength only in You.\",\"I can give nothing unless You first fill me,\",\"Your love alone must shine through,\",\"Your love alone must shine through.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0165', 'verse', 3, 2, '[\"Make me be willing to go where You send me,\",\"make me be ready to answer Your call.\",\"Give me a heart that rejoices to serve You,\",\"sharing the best love of all,\",\"sharing the best love of all.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0166', 166, 'Give me a sight, O Saviour', 'MP', 'en', 'National Young Life Campaign', '', 0, 0, 0, 1, 1, 'Give me a sight, O Saviour,
of Thy wondrous love to me,
of the love that brought Thee down to earth,
to die on Calvary.
O make me understand it,
help me to take it in;
what it meant to Thee,
the Holy One,
to bear away my sin.
Was it the nails, O Saviour,
that bound Thee to the tree?
Nay, ’twas Thine everlasting love,
Thy love for me, for me.
O make me understand...
O wonder of all wonders,
that through Thy death for me
my open sins, my secret sins,
can all forgiven be!
O make me understand...
Then melt my heart, O Saviour,
bend me, yes, break me down,
until I own Thee Conqueror,
and Lord, and Sovereign crown.
O make me understand...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0166', 'Katherine Agnes May Kelly');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0166', 'Katherine Agnes May Kelly');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0166', 'verse', 1, 0, '[\"Give me a sight, O Saviour,\",\"of Thy wondrous love to me,\",\"of the love that brought Thee down to earth,\",\"to die on Calvary.\",\"O make me understand it,\",\"help me to take it in;\",\"what it meant to Thee,\",\"the Holy One,\",\"to bear away my sin.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0166', 'verse', 2, 1, '[\"Was it the nails, O Saviour,\",\"that bound Thee to the tree?\",\"Nay, ’twas Thine everlasting love,\",\"Thy love for me, for me.\",\"O make me understand...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0166', 'verse', 3, 2, '[\"O wonder of all wonders,\",\"that through Thy death for me\",\"my open sins, my secret sins,\",\"can all forgiven be!\",\"O make me understand...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0166', 'verse', 4, 3, '[\"Then melt my heart, O Saviour,\",\"bend me, yes, break me down,\",\"until I own Thee Conqueror,\",\"and Lord, and Sovereign crown.\",\"O make me understand...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0167', 167, 'Give me oil in my lamp', 'MP', 'en', 'A Sevison/Copyright control                        arrangement: ? 1974 Celebration / kingswaysongs.com. tym@kingsway.co.uk. For Europe and Commonwealth (excl. Canada, Australasia and Africa). Used by permission.', '', 0, 0, 0, 1, 0, 'Give me oil in my lamp, keep me burning,
give me oil in my lamp, I pray;
give me oil in my lamp, keep me burning,
keep me burning till the break of day.
Sing hosanna, sing hosanna,
sing hosanna to the King of kings!
Sing hosanna, sing hosanna,
sing hosanna to the King!
Make me a fisher of men, keep me seeking,
make me a fisher of men, I pray;
make me a fisher of men, keep me seeking,
keep me seeking till the break of day.
Sing hosanna...
Give me joy in my heart, keep me singing,
give me joy in my heart, I pray;
give me joy in my heart, keep me singing,
keep me singing till the break of day.
Sing hosanna...
Give me love in my heart, keep me serving,
give me love in my heart, I pray;
give me love in my heart, keep me serving,
keep me serving till the break of day.
Sing hosanna...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0167', 'A Sevison');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0167', 'A Sevison');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0167', 'Betty Pulkingham');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0167', 'verse', 1, 0, '[\"Give me oil in my lamp, keep me burning,\",\"give me oil in my lamp, I pray;\",\"give me oil in my lamp, keep me burning,\",\"keep me burning till the break of day.\",\"Sing hosanna, sing hosanna,\",\"sing hosanna to the King of kings!\",\"Sing hosanna, sing hosanna,\",\"sing hosanna to the King!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0167', 'verse', 2, 1, '[\"Make me a fisher of men, keep me seeking,\",\"make me a fisher of men, I pray;\",\"make me a fisher of men, keep me seeking,\",\"keep me seeking till the break of day.\",\"Sing hosanna...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0167', 'verse', 3, 2, '[\"Give me joy in my heart, keep me singing,\",\"give me joy in my heart, I pray;\",\"give me joy in my heart, keep me singing,\",\"keep me singing till the break of day.\",\"Sing hosanna...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0167', 'verse', 4, 3, '[\"Give me love in my heart, keep me serving,\",\"give me love in my heart, I pray;\",\"give me love in my heart, keep me serving,\",\"keep me serving till the break of day.\",\"Sing hosanna...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0168', 168, 'Give me the faith', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Give me the faith which can remove
and sink the mountain to a plain;
give me the childlike, praying love,
which longs to build Thy house again;
Thy love let it my heart o’erpower,
let it my ransomed soul devour.
I would the precious time redeem,
and longer live for this alone –
to spend and to be spent for them
who have not yet my Saviour known;
fully on these my mission prove,
and only breathe to breathe Thy love.
My talents, gifts, and graces, Lord,
into Thy blessèd hands receive;
and let me live to preach Thy word,
and let me to Thy glory live;
my every sacred moment spend
in publishing the sinners’ friend.
Enlarge, inflame, and fill my heart
with boundless charity divine;
so shall I all my strength exert,
and love them with a zeal like Thine;
and lead them to Thine open side,
the sheep for whom their shepherd died.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0168', 'Charles Wesley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0168', 'verse', 1, 0, '[\"Give me the faith which can remove\",\"and sink the mountain to a plain;\",\"give me the childlike, praying love,\",\"which longs to build Thy house again;\",\"Thy love let it my heart o’erpower,\",\"let it my ransomed soul devour.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0168', 'verse', 2, 1, '[\"I would the precious time redeem,\",\"and longer live for this alone –\",\"to spend and to be spent for them\",\"who have not yet my Saviour known;\",\"fully on these my mission prove,\",\"and only breathe to breathe Thy love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0168', 'verse', 3, 2, '[\"My talents, gifts, and graces, Lord,\",\"into Thy blessèd hands receive;\",\"and let me live to preach Thy word,\",\"and let me to Thy glory live;\",\"my every sacred moment spend\",\"in publishing the sinners’ friend.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0168', 'verse', 4, 3, '[\"Enlarge, inflame, and fill my heart\",\"with boundless charity divine;\",\"so shall I all my strength exert,\",\"and love them with a zeal like Thine;\",\"and lead them to Thine open side,\",\"the sheep for whom their shepherd died.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0169', 169, 'His love endures for ever', 'MP', 'en', 'Sound III/Lorenz Publishing Co (Adm Small Stone Media/Song Solutions www.songsolutions.org) All rights reserved. Used by permission', '', 0, 0, 0, 1, 0, 'Give thanks to the Lord for He is good,
His love endures for ever.
Give thanks to the God of gods,
His love endures for ever.
O give thanks to the Lord of lords,
His love endures for ever.
To Him alone who does great works,
His love endures for ever.
By His understanding made the heavens,
His love endures for ever.
Who made the great and shining lights,
His love endures for ever.
The mighty sun to rule the day,
His love endures for ever.
And the moon and the stars to rule at night,
His love endures for ever.
Hallelujah, hallelu,
the Lord Jehovah reigns.
He is the same from age to age;
His love will never change.
God led His children through the wilderness,
His love endures for ever.
And struck down many mighty kings,
His love endures for ever.
And gave to them an inheritance,
His love endures for ever.
A promised land for Israel,
His love endures for ever.
Hallelujah...
He remembered us in our low estate,
His love endures for ever.
And freed us from our enemies,
His love endures for ever.
To every creature He gives food,
His love endures for ever.
Give thanks to the God of heaven,
His love endures for ever,
His love endures for ever,
His love endures for ever.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0169', 'Mark Hayes');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0169', 'Mark Hayes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0169', 'verse', 1, 0, '[\"Give thanks to the Lord for He is good,\",\"His love endures for ever.\",\"Give thanks to the God of gods,\",\"His love endures for ever.\",\"O give thanks to the Lord of lords,\",\"His love endures for ever.\",\"To Him alone who does great works,\",\"His love endures for ever.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0169', 'verse', 2, 1, '[\"By His understanding made the heavens,\",\"His love endures for ever.\",\"Who made the great and shining lights,\",\"His love endures for ever.\",\"The mighty sun to rule the day,\",\"His love endures for ever.\",\"And the moon and the stars to rule at night,\",\"His love endures for ever.\",\"Hallelujah, hallelu,\",\"the Lord Jehovah reigns.\",\"He is the same from age to age;\",\"His love will never change.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0169', 'verse', 3, 2, '[\"God led His children through the wilderness,\",\"His love endures for ever.\",\"And struck down many mighty kings,\",\"His love endures for ever.\",\"And gave to them an inheritance,\",\"His love endures for ever.\",\"A promised land for Israel,\",\"His love endures for ever.\",\"Hallelujah...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0169', 'verse', 4, 3, '[\"He remembered us in our low estate,\",\"His love endures for ever.\",\"And freed us from our enemies,\",\"His love endures for ever.\",\"To every creature He gives food,\",\"His love endures for ever.\",\"Give thanks to the God of heaven,\",\"His love endures for ever,\",\"His love endures for ever,\",\"His love endures for ever.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0170', 170, 'Give thanks with a grateful heart', 'MP', 'en', '© 1978 Integrity\'s Hosanna! Music/Adm. by Capitol CMG Publishing.com excl. the UK, adm. by  Integritymusic.com. a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'Give thanks with a grateful heart,
give thanks to the Holy One;
give thanks because He’s given
Jesus Christ, His Son.
Give thanks...
And now let the weak say, ‘I am strong’,
let the poor say, ‘I am rich’,
because of what the Lord has done for us;
and now let the weak say, ‘I am strong’,
let the poor say, ‘I am rich’,
because of what the Lord has done for us.
Give thanks...
And now...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0170', 'Henry Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0170', 'Henry Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0170', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0170', 'verse', 1, 0, '[\"Give thanks with a grateful heart,\",\"give thanks to the Holy One;\",\"give thanks because He’s given\",\"Jesus Christ, His Son.\",\"Give thanks...\",\"And now let the weak say, ‘I am strong’,\",\"let the poor say, ‘I am rich’,\",\"because of what the Lord has done for us;\",\"and now let the weak say, ‘I am strong’,\",\"let the poor say, ‘I am rich’,\",\"because of what the Lord has done for us.\",\"Give thanks...\",\"And now...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0171', 171, 'Give to our God immortal praise', 'MP', 'en', 'control', '', 0, 0, 0, 1, 1, 'Give to our God immortal praise;
mercy and truth are all His ways:
wonders of grace to God belong,
repeat His mercies in your song.
Give to the Lord of lords renown;
the King of kings with glory crown:
His mercies ever shall endure,
when lords and kings are known no more.
He built the earth, He spread the sky,
and fixed the starry lights on high:
wonders of grace to God belong,
repeat His mercies in your song.
He fills the sun with morning light,
He bids the moon direct the night:
His mercies ever shall endure,
when suns and moons shall shine no more.
He sent His Son with power to save');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0171', 'Isaac Watts');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0171', 'Francis Duckworth');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0171', 'verse', 1, 0, '[\"Give to our God immortal praise;\",\"mercy and truth are all His ways:\",\"wonders of grace to God belong,\",\"repeat His mercies in your song.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0171', 'verse', 2, 1, '[\"Give to the Lord of lords renown;\",\"the King of kings with glory crown:\",\"His mercies ever shall endure,\",\"when lords and kings are known no more.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0171', 'verse', 3, 2, '[\"He built the earth, He spread the sky,\",\"and fixed the starry lights on high:\",\"wonders of grace to God belong,\",\"repeat His mercies in your song.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0171', 'verse', 4, 3, '[\"He fills the sun with morning light,\",\"He bids the moon direct the night:\",\"His mercies ever shall endure,\",\"when suns and moons shall shine no more.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0171', 'verse', 5, 4, '[\"He sent His Son with power to save\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0172', 172, 'Glorious Father', 'MP', 'en', '©  1987 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Glorious Father, we exalt You;
we worship, honour and adore You;
we delight to be in Your presence, O Lord.
We magnify Your holy name,
and we sing, ‘Come, Lord Jesus,
glorify Your name!’
and we sing, ‘Come, Lord Jesus,
glorify Your name!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0172', 'Danny Reed');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0172', 'Danny Reed');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0172', 'verse', 1, 0, '[\"Glorious Father, we exalt You;\",\"we worship, honour and adore You;\",\"we delight to be in Your presence, O Lord.\",\"We magnify Your holy name,\",\"and we sing, ‘Come, Lord Jesus,\",\"glorify Your name!’\",\"and we sing, ‘Come, Lord Jesus,\",\"glorify Your name!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0173', 173, 'Glorious things of thee are spoken', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Glorious things of thee are spoken,
Zion, city of our God;
He, whose word cannot be broken,
formed thee for His own abode:
on the rock of ages founded,
what can shake thy sure repose?
With salvation’s walls surrounded,
thou may’st smile at all thy foes.
See, the streams of living waters,
springing from eternal love,
well supply thy sons and daughters
and all fear of want remove:
who can faint, while such a river
ever flows their thirst to assuage?
Grace which, like the Lord, the giver,
never fails from age to age.
Saviour, if of Zion’s city
I, through grace, a member am,
let the world deride or pity,
I will glory in Thy name:
fading is the worldling’s pleasure,
all his boasted pomp and show;
solid joys and lasting treasure
none but Zion’s children know.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0173', 'John Newton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0173', 'Franz Joseph Haydn');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0173', 'verse', 1, 0, '[\"Glorious things of thee are spoken,\",\"Zion, city of our God;\",\"He, whose word cannot be broken,\",\"formed thee for His own abode:\",\"on the rock of ages founded,\",\"what can shake thy sure repose?\",\"With salvation’s walls surrounded,\",\"thou may’st smile at all thy foes.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0173', 'verse', 2, 1, '[\"See, the streams of living waters,\",\"springing from eternal love,\",\"well supply thy sons and daughters\",\"and all fear of want remove:\",\"who can faint, while such a river\",\"ever flows their thirst to assuage?\",\"Grace which, like the Lord, the giver,\",\"never fails from age to age.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0173', 'verse', 3, 2, '[\"Saviour, if of Zion’s city\",\"I, through grace, a member am,\",\"let the world deride or pity,\",\"I will glory in Thy name:\",\"fading is the worldling’s pleasure,\",\"all his boasted pomp and show;\",\"solid joys and lasting treasure\",\"none but Zion’s children know.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0174', 174, 'Glory', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Glory, glory in the highest,
glory, to the Almighty;
glory to the Lamb of God,
and glory to the living Word;
glory to the Lamb!
Glory, glory...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0174', 'Danny Daniels');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0174', 'Danny Daniels');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0174', 'verse', 1, 0, '[\"Glory, glory in the highest,\",\"glory, to the Almighty;\",\"glory to the Lamb of God,\",\"and glory to the living Word;\",\"glory to the Lamb!\",\"Glory, glory...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0175', 175, 'Glory be to God in heaven', 'MP', 'en', '1984 John Richards/Renewal Servicing, PO Box 17 Shepperton, Middlesex TW17 8NU', '', 0, 0, 0, 1, 1, 'Glory be to God in heaven,
and to all on earth, His peace;
Lord and Father, King in glory,
gifts of praise in us release,
so our worship and thanksgiving');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0175', 'John Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0175', 'Henry Thomas Smart');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0175', 'verse', 1, 0, '[\"Glory be to God in heaven,\",\"and to all on earth, His peace;\",\"Lord and Father, King in glory,\",\"gifts of praise in us release,\",\"so our worship and thanksgiving\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0176', 176, 'Glory to You, my God', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Glory to You, my God, this night
for all the blessings of the light;
keep me, O keep me, King of kings,
beneath Your own almighty wings.
Forgive me, Lord, through Your dear Son,
the wrong that I this day have done,
that peace with God and man may be,
before I sleep, restored to me.
Teach me to live, that I may dread
the grave as little as my bed;
teach me to die, that so I may
rise glorious at the awesome day.
O may my soul on You repose
and restful sleep my eyelids close;
sleep that shall me more vigorous make
to serve my God when I awake.
If in the night I sleepless lie,
my mind with peaceful thoughts supply;
let no dark dreams disturb my rest,
no powers of evil me molest.
Praise God from whom all blessings flow
in heaven above and earth below;
one God, three persons, we adore –
to Him be praise for evermore!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0176', 'Thomas Ken');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0176', 'Thomas Tallis');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0176', 'verse', 1, 0, '[\"Glory to You, my God, this night\",\"for all the blessings of the light;\",\"keep me, O keep me, King of kings,\",\"beneath Your own almighty wings.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0176', 'verse', 2, 1, '[\"Forgive me, Lord, through Your dear Son,\",\"the wrong that I this day have done,\",\"that peace with God and man may be,\",\"before I sleep, restored to me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0176', 'verse', 3, 2, '[\"Teach me to live, that I may dread\",\"the grave as little as my bed;\",\"teach me to die, that so I may\",\"rise glorious at the awesome day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0176', 'verse', 4, 3, '[\"O may my soul on You repose\",\"and restful sleep my eyelids close;\",\"sleep that shall me more vigorous make\",\"to serve my God when I awake.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0176', 'verse', 5, 4, '[\"If in the night I sleepless lie,\",\"my mind with peaceful thoughts supply;\",\"let no dark dreams disturb my rest,\",\"no powers of evil me molest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0176', 'verse', 6, 5, '[\"Praise God from whom all blessings flow\",\"in heaven above and earth below;\",\"one God, three persons, we adore –\",\"to Him be praise for evermore!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0177', 177, 'Glory to God in the highest', 'MP', 'en', '1986 Greg Leavers', '', 0, 0, 0, 1, 1, 'Glory to God in the highest,
peace upon earth,
Jesus Christ has come to earth;
that’s why we sing,
Jesus the King,
Jesus has come for you.
The shepherds who were sitting there
were suddenly filled with fear;
the dark night was filled with light,
angels singing everywhere.
Glory to God...
The next time we hear a song
of worship from a heavenly throng,
will be when Jesus comes again,
then with triumph we’ll all sing:
Glory to God...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0177', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0177', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0177', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0177', 'chorus', 0, 0, '[\"Glory to God in the highest,\",\"peace upon earth,\",\"Jesus Christ has come to earth;\",\"that’s why we sing,\",\"Jesus the King,\",\"Jesus has come for you.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0177', 'verse', 1, 1, '[\"The shepherds who were sitting there\",\"were suddenly filled with fear;\",\"the dark night was filled with light,\",\"angels singing everywhere.\",\"Glory to God...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0177', 'verse', 2, 2, '[\"The next time we hear a song\",\"of worship from a heavenly throng,\",\"will be when Jesus comes again,\",\"then with triumph we’ll all sing:\",\"Glory to God...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0178', 178, 'Go forth and tell', 'MP', 'en', 'The Representatives of the late  James E Seddon /The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION             ©  John Barnard/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'Go forth and tell! O Church of God, awake!
God’s saving news to all the nations take:
proclaim Christ Jesus, Saviour, Lord and King,
that all the world His worthy praise may sing.
Go forth and tell! God’s love embraces all;
He will in grace respond to all who call:
how shall they call if they have never heard
the gracious invitation of His word?
Go forth and tell! men still in darkness lie;
in wealth or want, in sin they live and die:
give us, O Lord, concern of heart and mind,
a love like Yours which cares for all mankind.
Go forth and tell! the doors are open wide:
share God’s good gifts – let no-one be denied;
live out your life as Christ your Lord shall choose,
your ransomed powers for His sole glory use.
Go forth and tell! O Church of God, arise!
Go in the strength which Christ your Lord supplies;
go till all nations His great name adore
and serve Him, Lord and King for evermore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0178', 'James E Seddon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0178', 'John Barnard');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0178', 'verse', 1, 0, '[\"Go forth and tell! O Church of God, awake!\",\"God’s saving news to all the nations take:\",\"proclaim Christ Jesus, Saviour, Lord and King,\",\"that all the world His worthy praise may sing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0178', 'verse', 2, 1, '[\"Go forth and tell! God’s love embraces all;\",\"He will in grace respond to all who call:\",\"how shall they call if they have never heard\",\"the gracious invitation of His word?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0178', 'verse', 3, 2, '[\"Go forth and tell! men still in darkness lie;\",\"in wealth or want, in sin they live and die:\",\"give us, O Lord, concern of heart and mind,\",\"a love like Yours which cares for all mankind.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0178', 'verse', 4, 3, '[\"Go forth and tell! the doors are open wide:\",\"share God’s good gifts – let no-one be denied;\",\"live out your life as Christ your Lord shall choose,\",\"your ransomed powers for His sole glory use.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0178', 'verse', 5, 4, '[\"Go forth and tell! O Church of God, arise!\",\"Go in the strength which Christ your Lord supplies;\",\"go till all nations His great name adore\",\"and serve Him, Lord and King for evermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0179', 179, 'Go, tell it on the mountain', 'MP', 'en', 'Geoffrey Marshall-Taylor', '', 0, 0, 0, 1, 1, 'Go, tell it on the mountain,
over the hills and everywhere;
go, tell it on the mountain
that Jesus is His name.
He possessed no riches, no home to lay His head;
He saw the needs of others and cared for them instead.
Go tell it on the mountain...
He reached out and touched them, the blind, the deaf, the lame;
He spoke and listened gladly to anyone who came.
Go tell it on the mountain...
Some turned away in anger, with hatred in the eye;
they tried Him and condemned Him, then led Him out to die.
Go tell it on the mountain...
‘Father, now forgive them’ – those were the words He said;
in three more days He was alive and risen from the dead.
Go tell it on the mountain...
He still comes to people, His life moves through the lands;
He uses us for speaking, He touches with our hands.
Go tell it on the mountain...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0179', 'Geoffrey Marshall-Taylor');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0179', 'Douglas Coombes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0179', 'chorus', 0, 0, '[\"Go, tell it on the mountain,\",\"over the hills and everywhere;\",\"go, tell it on the mountain\",\"that Jesus is His name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0179', 'verse', 1, 1, '[\"He possessed no riches, no home to lay His head;\",\"He saw the needs of others and cared for them instead.\",\"Go tell it on the mountain...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0179', 'verse', 2, 2, '[\"He reached out and touched them, the blind, the deaf, the lame;\",\"He spoke and listened gladly to anyone who came.\",\"Go tell it on the mountain...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0179', 'verse', 3, 3, '[\"Some turned away in anger, with hatred in the eye;\",\"they tried Him and condemned Him, then led Him out to die.\",\"Go tell it on the mountain...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0179', 'verse', 4, 4, '[\"‘Father, now forgive them’ – those were the words He said;\",\"in three more days He was alive and risen from the dead.\",\"Go tell it on the mountain...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0179', 'verse', 5, 5, '[\"He still comes to people, His life moves through the lands;\",\"He uses us for speaking, He touches with our hands.\",\"Go tell it on the mountain...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0180', 180, 'God came among us', 'MP', 'en', '© 1982 Authentic Publishing (adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com) Used by Permission', '', 0, 0, 0, 1, 0, 'God came among us, He became a man,
became a baby, though through Him the world began.
He came to earth to bring us peace,
but where is that peace today?
It can be found by those who will let Him direct their way.
He came to serve, to show us how much He cared;
our joys and sorrows He so willingly shared.
He came to earth to bring us joy,
but where is that joy today?
It can be found by those who let Him wash their guilt away.
Death tried to hold Him, but it could not succeed;
He rose again, and now we can be freed.
He longs to give eternal life
to all who will simply receive,
yes, to all who will open their hearts and just believe.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0180', 'Marilyn Baker');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0180', 'Marilyn Baker');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0180', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0180', 'verse', 1, 0, '[\"God came among us, He became a man,\",\"became a baby, though through Him the world began.\",\"He came to earth to bring us peace,\",\"but where is that peace today?\",\"It can be found by those who will let Him direct their way.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0180', 'verse', 2, 1, '[\"He came to serve, to show us how much He cared;\",\"our joys and sorrows He so willingly shared.\",\"He came to earth to bring us joy,\",\"but where is that joy today?\",\"It can be found by those who let Him wash their guilt away.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0180', 'verse', 3, 2, '[\"Death tried to hold Him, but it could not succeed;\",\"He rose again, and now we can be freed.\",\"He longs to give eternal life\",\"to all who will simply receive,\",\"yes, to all who will open their hearts and just believe.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0181', 181, 'God forgave my sin', 'MP', 'en', '1972 Bud John Songs/EMI Christian Music Publishing, administered by Copycare PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.', '', 0, 0, 0, 1, 1, 'God forgave my sin in Jesus’ name;
I’ve been born again in Jesus’ name,
and in Jesus’ name I come to you
to share His love as He told me to.
He said:
‘Freely, freely you have received,
freely, freely give;
go in My name and because you believe,
others will know that I live.’
All power is given in Jesus’ name
in earth and heaven in Jesus’ name;
and in Jesus’ name I come to you
to share His power as He told me to.
He said...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0181', 'Carol Owens');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0181', 'Carol Owens');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0181', 'verse', 1, 0, '[\"God forgave my sin in Jesus’ name;\",\"I’ve been born again in Jesus’ name,\",\"and in Jesus’ name I come to you\",\"to share His love as He told me to.\",\"He said:\",\"‘Freely, freely you have received,\",\"freely, freely give;\",\"go in My name and because you believe,\",\"others will know that I live.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0181', 'verse', 2, 1, '[\"All power is given in Jesus’ name\",\"in earth and heaven in Jesus’ name;\",\"and in Jesus’ name I come to you\",\"to share His power as He told me to.\",\"He said...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0182', 182, 'God has spoken to His people', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'God has spoken to His people, alleluia,
and His words are words of wisdom, alleluia!
Open your ears, O Christian people,
open your ears and hear good news;
open your hearts, O royal priesthood,
God has come to you.
God has spoken...
They who have ears to hear His message,
they who have ears, then let them hear;
they who would learn the way of wisdom,
let them hear God’s word!
God has spoken...
Israel comes to greet the Saviour,
Judah is glad to see His day;');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0182', 'Willard Jabusch');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0182', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0182', 'chorus', 0, 0, '[\"God has spoken to His people, alleluia,\",\"and His words are words of wisdom, alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0182', 'verse', 1, 1, '[\"Open your ears, O Christian people,\",\"open your ears and hear good news;\",\"open your hearts, O royal priesthood,\",\"God has come to you.\",\"God has spoken...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0182', 'verse', 2, 2, '[\"They who have ears to hear His message,\",\"they who have ears, then let them hear;\",\"they who would learn the way of wisdom,\",\"let them hear God’s word!\",\"God has spoken...\"]');
