INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0183', 183, 'God holds the key', 'MP', 'en', 'HarperCollins Religious/adm Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'God holds the key of all unknown,
and I am glad:
if other hands should hold the key,
or if He trusted it to me,
I might be sad, I might be sad.
What if tomorrow’s cares were here
without its rest?
I’d rather He unlocked the day,
and, as the hours swing open, say,
‘My will is best, My will is best.’
The very dimness of my sight
makes me secure;
for, groping in my misty way,
I feel His hand; I hear Him say,
‘My help is sure, My help is sure.’
I cannot read His future plans;
but this I know:
I have the smiling of His face,
and all the refuge of His grace,
while here below, while here below.
Enough: this covers all my wants;
and so I rest!
for what I cannot, He can see,
and in His care I saved shall be,
for ever blest, for ever blest.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0183', 'Joseph Parker');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0183', 'George Coles Stebbins');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0183', 'verse', 1, 0, '[\"God holds the key of all unknown,\",\"and I am glad:\",\"if other hands should hold the key,\",\"or if He trusted it to me,\",\"I might be sad, I might be sad.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0183', 'verse', 2, 1, '[\"What if tomorrow’s cares were here\",\"without its rest?\",\"I’d rather He unlocked the day,\",\"and, as the hours swing open, say,\",\"‘My will is best, My will is best.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0183', 'verse', 3, 2, '[\"The very dimness of my sight\",\"makes me secure;\",\"for, groping in my misty way,\",\"I feel His hand; I hear Him say,\",\"‘My help is sure, My help is sure.’\"]');
