INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0184', 'verse', 2, 1, '[\"God is building a house,\",\"God is building a house,\",\"God is building a house that will stand.\",\"With apostles, prophets, pastors,\",\"with evangelists and teachers,\",\"God is building a house that will stand.\"]');
