INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0198', 198, 'Gracious Spirit', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Gracious Spirit, Holy Ghost,
taught by You, we covet most,
of Your gifts at Pentecost,
holy, heavenly love.
Faith that mountains could remove,
tongues of earth or heaven above,
knowledge, all things, empty prove
without heavenly love.
Though I as a martyr bleed,
give my goods the poor to feed,
all is vain if love I need;
therefore give me love.
Love is kind, and suffers long;
love is meek, and thinks no wrong;
love, than death itself more strong:
therefore give us love.
Prophecy will fade away,
melting in the light of day;
love will ever with us stay:
therefore give us love.
Faith, and hope, and love we see
joining hand in hand, agree;
but the greatest of the three,
and the best, is love.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0198', 'Christopher Wordsworth');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0198', 'John Stainer');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0198', 'verse', 1, 0, '[\"Gracious Spirit, Holy Ghost,\",\"taught by You, we covet most,\",\"of Your gifts at Pentecost,\",\"holy, heavenly love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0198', 'verse', 2, 1, '[\"Faith that mountains could remove,\",\"tongues of earth or heaven above,\",\"knowledge, all things, empty prove\",\"without heavenly love.\"]');
