INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0199', 199, 'Great is the Lord', 'MP', 'en', '1985 Body Songs (Admin. by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Great is the Lord and most worthy of praise,
the city of our God, the holy place,
the joy of the whole earth.
Great is the Lord in whom we have the victory,
He aids us against the enemy,
we bow down on our knees.
And Lord, we want to lift Your name on high,
and Lord, we want to thank You,
for the works You’ve done in our lives;
and Lord, we trust in Your unfailing love,
for You alone are God eternal,
throughout earth and heaven above.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0199', 'Steve McEwan');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0199', 'Steve McEwan');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0199', 'verse', 1, 0, '[\"Great is the Lord and most worthy of praise,\",\"the city of our God, the holy place,\",\"the joy of the whole earth.\",\"Great is the Lord in whom we have the victory,\",\"He aids us against the enemy,\",\"we bow down on our knees.\",\"And Lord, we want to lift Your name on high,\",\"and Lord, we want to thank You,\",\"for the works You’ve done in our lives;\",\"and Lord, we trust in Your unfailing love,\",\"for You alone are God eternal,\",\"throughout earth and heaven above.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0200', 200, 'Great is Thy faithfulness', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Great is Thy faithfulness, O God my Father,
there is no shadow of turning with Thee;
Thou changest not, Thy compassions they fail not,
as Thou hast been Thou for ever wilt be.
Great is Thy faithfulness,
great is Thy faithfulness;
morning by morning
new mercies I see;
all I have needed
Thy hand hath provided –
great is Thy faithfulness, Lord, unto me!
Summer and winter, and spring-time and harvest,
sun, moon and stars in their courses above,
join with all nature in manifold witness
to Thy great faithfulness, mercy and love.
Great is Thy faithfulness...
Pardon for sin, and a peace that endureth,
Thine own dear presence to cheer and to guide;
strength for today and bright hope for tomorrow,
blessings all mine, with ten thousand beside!
Great is Thy faithfulness...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0200', 'Thomas O Chisholm');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0200', 'William Marion Runyan');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0200', 'verse', 1, 0, '[\"Great is Thy faithfulness, O God my Father,\",\"there is no shadow of turning with Thee;\",\"Thou changest not, Thy compassions they fail not,\",\"as Thou hast been Thou for ever wilt be.\",\"Great is Thy faithfulness,\",\"great is Thy faithfulness;\",\"morning by morning\",\"new mercies I see;\",\"all I have needed\",\"Thy hand hath provided –\",\"great is Thy faithfulness, Lord, unto me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0200', 'verse', 2, 1, '[\"Summer and winter, and spring-time and harvest,\",\"sun, moon and stars in their courses above,\",\"join with all nature in manifold witness\",\"to Thy great faithfulness, mercy and love.\",\"Great is Thy faithfulness...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0200', 'verse', 3, 2, '[\"Pardon for sin, and a peace that endureth,\",\"Thine own dear presence to cheer and to guide;\",\"strength for today and bright hope for tomorrow,\",\"blessings all mine, with ten thousand beside!\",\"Great is Thy faithfulness...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0201', 201, 'Guide me, O Thou great Jehovah', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Guide me, O Thou great Jehovah,
pilgrim through this barren land;
I am weak, but Thou art mighty;
hold me with Thy powerful hand:
Bread of heaven,
feed me now and evermore.
Open now the crystal fountain,
whence the healing stream doth flow;
let the fiery, cloudy pillar
lead me all my journey through:
strong deliverer,
be Thou still my strength and shield.
When I tread the verge of Jordan,
bid my anxious fears subside:
death of death, and hell’s destruction,
land me safe on Canaan’s side:
songs of praises
I will ever give to Thee.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0201', 'William Williams');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0201', 'John Hughes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0201', 'verse', 1, 0, '[\"Guide me, O Thou great Jehovah,\",\"pilgrim through this barren land;\",\"I am weak, but Thou art mighty;\",\"hold me with Thy powerful hand:\",\"Bread of heaven,\",\"feed me now and evermore.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0201', 'verse', 2, 1, '[\"Open now the crystal fountain,\",\"whence the healing stream doth flow;\",\"let the fiery, cloudy pillar\",\"lead me all my journey through:\",\"strong deliverer,\",\"be Thou still my strength and shield.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0201', 'verse', 3, 2, '[\"When I tread the verge of Jordan,\",\"bid my anxious fears subside:\",\"death of death, and hell’s destruction,\",\"land me safe on Canaan’s side:\",\"songs of praises\",\"I will ever give to Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0202', 202, 'Hail the day', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Hail the day that sees Him rise,
Alleluia,
to His throne beyond the skies;
Christ, the Lamb for sinners given,
enters now the highest heaven.
There for Him high triumph waits:
lift your heads, eternal gates,
He has conquered death and sin,
take the King of glory in.
See! the heaven its Lord receives,
yet He loves the earth He leaves;
though returning to His throne,
still He calls mankind His own.
Still for us He intercedes,
His prevailing death He pleads,
near Himself prepares our place,
He the first-fruits of our race.
Lord, though parted from our sight,
far beyond the starry height,
lift our hearts that we may rise
one with You beyond the skies.
There with You we shall remain,
share the glory of Your reign,
there Your face unclouded view,
find our heaven of heavens in You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0202', 'Charles Wesley');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0202', 'Thomas Cotterill');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0202', 'Robert Williams');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0202', 'verse', 1, 0, '[\"Hail the day that sees Him rise,\",\"Alleluia,\",\"to His throne beyond the skies;\",\"Christ, the Lamb for sinners given,\",\"enters now the highest heaven.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0202', 'verse', 2, 1, '[\"There for Him high triumph waits:\",\"lift your heads, eternal gates,\",\"He has conquered death and sin,\",\"take the King of glory in.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0202', 'verse', 3, 2, '[\"See! the heaven its Lord receives,\",\"yet He loves the earth He leaves;\",\"though returning to His throne,\",\"still He calls mankind His own.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0202', 'verse', 4, 3, '[\"Still for us He intercedes,\",\"His prevailing death He pleads,\",\"near Himself prepares our place,\",\"He the first-fruits of our race.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0202', 'verse', 5, 4, '[\"Lord, though parted from our sight,\",\"far beyond the starry height,\",\"lift our hearts that we may rise\",\"one with You beyond the skies.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0202', 'verse', 6, 5, '[\"There with You we shall remain,\",\"share the glory of Your reign,\",\"there Your face unclouded view,\",\"find our heaven of heavens in You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0203', 203, 'Hail, Thou once despisèd Jesus', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Hail, Thou once despisèd Jesus,
hail, Thou Galilean King!
Thou didst suffer to release us,
Thou didst free salvation bring.
Hail, Thou agonizing Saviour,
bearer of our sin and shame;
by Thy merits we find favour;
life is given through Thy name.
Paschal Lamb, by God appointed,
all our sins on Thee were laid;
by almighty love anointed,
Thou hast full atonement made.
All Thy people are forgiven
through the virtue of Thy blood;
opened is the gate of heaven,
peace is made ’twixt man and God.
Jesus, hail! enthroned in glory,
there for ever to abide;
all the heavenly hosts adore Thee,
seated at Thy Father’s side:
there for sinners Thou art pleading,
there Thou dost our place prepare;
ever for us interceding,
till in glory we appear.
Worship, honour, power, and blessing,
Thou art worthy to receive;
loudest praises, without ceasing,
meet it is for us to give:
Help, ye bright angelic spirits!
bring your sweetest, noblest lays;
help to sing our Saviour’s merits,
help to chant Immanuel’s praise.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0203', 'John Bakewell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0203', 'Arthur Seymour Sullivan');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0203', 'verse', 1, 0, '[\"Hail, Thou once despisèd Jesus,\",\"hail, Thou Galilean King!\",\"Thou didst suffer to release us,\",\"Thou didst free salvation bring.\",\"Hail, Thou agonizing Saviour,\",\"bearer of our sin and shame;\",\"by Thy merits we find favour;\",\"life is given through Thy name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0203', 'verse', 2, 1, '[\"Paschal Lamb, by God appointed,\",\"all our sins on Thee were laid;\",\"by almighty love anointed,\",\"Thou hast full atonement made.\",\"All Thy people are forgiven\",\"through the virtue of Thy blood;\",\"opened is the gate of heaven,\",\"peace is made ’twixt man and God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0203', 'verse', 3, 2, '[\"Jesus, hail! enthroned in glory,\",\"there for ever to abide;\",\"all the heavenly hosts adore Thee,\",\"seated at Thy Father’s side:\",\"there for sinners Thou art pleading,\",\"there Thou dost our place prepare;\",\"ever for us interceding,\",\"till in glory we appear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0203', 'verse', 4, 3, '[\"Worship, honour, power, and blessing,\",\"Thou art worthy to receive;\",\"loudest praises, without ceasing,\",\"meet it is for us to give:\",\"Help, ye bright angelic spirits!\",\"bring your sweetest, noblest lays;\",\"help to sing our Saviour’s merits,\",\"help to chant Immanuel’s praise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0204', 204, 'Hail to the Lord’s anointed', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Hail to the Lord’s anointed,
great David’s greater Son!
Hail, in the time appointed,
His reign on earth begun!
He comes to break oppression,
to set the captive free,
to take away transgression,
and rule in equity.
He comes with succour speedy
to those who suffer wrong;
to help the poor and needy,
and bid the weak be strong;
to give them songs for sighing,
their darkness turn to light,
whose souls, condemned and dying,
were precious in His sight.
He shall come down like showers
upon the fruitful earth;
Love, joy, and hope, like flowers,
spring in His path to birth:
before Him, on the mountains,
shall peace the herald go,
and righteousness in fountains');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0204', 'James Montgomery');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0204', 'verse', 1, 0, '[\"Hail to the Lord’s anointed,\",\"great David’s greater Son!\",\"Hail, in the time appointed,\",\"His reign on earth begun!\",\"He comes to break oppression,\",\"to set the captive free,\",\"to take away transgression,\",\"and rule in equity.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0204', 'verse', 2, 1, '[\"He comes with succour speedy\",\"to those who suffer wrong;\",\"to help the poor and needy,\",\"and bid the weak be strong;\",\"to give them songs for sighing,\",\"their darkness turn to light,\",\"whose souls, condemned and dying,\",\"were precious in His sight.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0204', 'verse', 3, 2, '[\"He shall come down like showers\",\"upon the fruitful earth;\",\"Love, joy, and hope, like flowers,\",\"spring in His path to birth:\",\"before Him, on the mountains,\",\"shall peace the herald go,\",\"and righteousness in fountains\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0205', 205, 'Hallelujah! for the Lord our God', 'MP', 'en', '1972 Scripture in Song (a division of Integrity Music) / Sovereign Music UK, PO Box 356, Leighton Buzzard LU7 3WP, UK. sovereignmusic@aol.com', '', 0, 0, 0, 1, 1, 'Hallelujah! for the Lord our God the almighty reigns.
Hallelujah! for the Lord our God the almighty reigns.
Let us rejoice and be glad and give the glory unto Him.
Hallelujah! for the Lord our God the almighty reigns.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0205', 'Dale Garratt');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0205', 'Dale Garratt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0205', 'verse', 1, 0, '[\"Hallelujah! for the Lord our God the almighty reigns.\",\"Hallelujah! for the Lord our God the almighty reigns.\",\"Let us rejoice and be glad and give the glory unto Him.\",\"Hallelujah! for the Lord our God the almighty reigns.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0206', 206, 'Hallelujah, my Father', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'Hallelujah, my Father,
for giving us Your Son;
sending Him into the world
to be given up for men,
knowing we would bruise Him
and smite Him from the earth.
Hallelujah, my Father,
in His death is my birth;
Hallelujah, my Father,
in His life is my life.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0206', 'Tim Cullen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0206', 'Tim Cullen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0206', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0206', 'verse', 1, 0, '[\"Hallelujah, my Father,\",\"for giving us Your Son;\",\"sending Him into the world\",\"to be given up for men,\",\"knowing we would bruise Him\",\"and smite Him from the earth.\",\"Hallelujah, my Father,\",\"in His death is my birth;\",\"Hallelujah, my Father,\",\"in His life is my life.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0207', 207, 'Hallelujah! sing to Jesus', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Hallelujah! sing to Jesus,
His the sceptre, His the throne;
hallelujah! His the triumph,
His the victory alone.
Hark! the songs of peaceful Zion
thunder like a mighty flood;
Jesus out of every nation
hath redeemed us by His blood.
Hallelujah! not as orphans
are we left in sorrow now;
hallelujah! He is near us,
faith believes, nor questions how.
Though the cloud from sight received Him
when the forty days were o’er,
shall our hearts forget His promise,
‘I am with you evermore’?
Hallelujah! bread of heaven!
Thou on earth our food, our stay;
Hallelujah! here the sinful
flee to Thee from day to day.
Intercessor, friend of sinners,
earth’s Redeemer, plead for me,
where the songs of all the sinless
sweep across the crystal sea.
Hallelujah! Hallelujah!
Glory be to God on high;
to the Father, and the Saviour,
who has gained the victory;
glory to the Holy Spirit,
fount of love and sanctity.
Hallelujah! Hallelujah!
to the triune Majesty.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0207', 'William Chatterton Dix');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0207', 'Samuel Sebastian Wesley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0207', 'verse', 1, 0, '[\"Hallelujah! sing to Jesus,\",\"His the sceptre, His the throne;\",\"hallelujah! His the triumph,\",\"His the victory alone.\",\"Hark! the songs of peaceful Zion\",\"thunder like a mighty flood;\",\"Jesus out of every nation\",\"hath redeemed us by His blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0207', 'verse', 2, 1, '[\"Hallelujah! not as orphans\",\"are we left in sorrow now;\",\"hallelujah! He is near us,\",\"faith believes, nor questions how.\",\"Though the cloud from sight received Him\",\"when the forty days were o’er,\",\"shall our hearts forget His promise,\",\"‘I am with you evermore’?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0207', 'verse', 3, 2, '[\"Hallelujah! bread of heaven!\",\"Thou on earth our food, our stay;\",\"Hallelujah! here the sinful\",\"flee to Thee from day to day.\",\"Intercessor, friend of sinners,\",\"earth’s Redeemer, plead for me,\",\"where the songs of all the sinless\",\"sweep across the crystal sea.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0207', 'verse', 4, 3, '[\"Hallelujah! Hallelujah!\",\"Glory be to God on high;\",\"to the Father, and the Saviour,\",\"who has gained the victory;\",\"glory to the Holy Spirit,\",\"fount of love and sanctity.\",\"Hallelujah! Hallelujah!\",\"to the triune Majesty.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0208', 208, 'Hallelujah! sing to the Lord', 'MP', 'en', '1985 Mercy/Vineyard Publishing/Song Solutions www.songsolutions.org.uk', '', 0, 0, 0, 1, 1, 'Hallelujah! sing to the Lord songs of praise;
we bless You, Lord,
we give to You glory due Your holy name.
We stretch out our hands,
we stretch out our hands unto You, Lord.
We lift up our voice,
we lift up our voice inviting You into this place.
Hear us, O God,
as one, we bring our praise,
a pleasing sacrifice to You,
O Ancient of Days,
Ancient of Days.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0208', 'Steve Southworth');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0208', 'Gina Southworth');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0208', 'Steve Southworth');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0208', 'Gina Southworth');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0208', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0208', 'verse', 1, 0, '[\"Hallelujah! sing to the Lord songs of praise;\",\"we bless You, Lord,\",\"we give to You glory due Your holy name.\",\"We stretch out our hands,\",\"we stretch out our hands unto You, Lord.\",\"We lift up our voice,\",\"we lift up our voice inviting You into this place.\",\"Hear us, O God,\",\"as one, we bring our praise,\",\"a pleasing sacrifice to You,\",\"O Ancient of Days,\",\"Ancient of Days.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0209', 209, 'Hark, my soul', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Hark, my soul! it is the Lord;
’Tis thy Saviour, hear His word;
Jesus speaks, and speaks to thee,
‘Say, poor sinner, lov’st thou Me?’
‘I delivered thee when bound,
and, when bleeding, healed thy wound;
sought thee wandering, set thee right,
turned thy darkness into light.’
‘Can a woman’s tender care
cease towards the child she bare?
Yes, she may forgetful be,
yet will I remember Thee.’
‘Mine is an unchanging love,
higher than the heights above,
deeper than the depths beneath,
free and faithful, strong as death.’
‘Thou shalt see My glory soon,
when the work of grace is done;
partner of My throne shalt be;
say, poor sinner, lov’st thou Me?’
Lord! it is my chief complaint
that my love is weak and faint;
yet I love Thee, and adore:
O for grace to love Thee more!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0209', 'William Cowper');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0209', 'John Bacchus Dykes');
