INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0209', 'verse', 2, 1, '[\"‘I delivered thee when bound,\",\"and, when bleeding, healed thy wound;\",\"sought thee wandering, set thee right,\",\"turned thy darkness into light.’\"]');
