INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0210', 210, 'Hark, the glad sound', 'MP', 'en', '1986 in this version Horrobin/Leavers', '', 0, 0, 0, 1, 1, 'Hark, the glad sound! the Saviour comes,
the Saviour promised long;
let every heart prepare a throne,
and every voice a song.
He comes, the prisoners to release
in Satan’s bondage held;
the chains of sin before Him break,
the iron fetters yield.
He comes to free the captive mind
where evil thoughts control;
and for the darkness of the blind,
gives light that makes them whole.
He comes the broken heart to bind,
the wounded soul to cure;
and with the treasures of His grace
to enrich the humble poor.
Our glad hosannas, Prince of peace,
Your welcome shall proclaim;
and heaven’s eternal arches ring
with Your belovèd name.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0210', 'Philip Doddridge');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0210', 'Frederick George Baker');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0210', 'verse', 1, 0, '[\"Hark, the glad sound! the Saviour comes,\",\"the Saviour promised long;\",\"let every heart prepare a throne,\",\"and every voice a song.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0210', 'verse', 2, 1, '[\"He comes, the prisoners to release\",\"in Satan’s bondage held;\",\"the chains of sin before Him break,\",\"the iron fetters yield.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0210', 'verse', 3, 2, '[\"He comes to free the captive mind\",\"where evil thoughts control;\",\"and for the darkness of the blind,\",\"gives light that makes them whole.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0210', 'verse', 4, 3, '[\"He comes the broken heart to bind,\",\"the wounded soul to cure;\",\"and with the treasures of His grace\",\"to enrich the humble poor.\"]');
