INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0211', 211, 'Hark! the herald-angels sing', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Hark! the herald-angels sing,
‘Glory to the new-born King!
Peace on earth, and mercy mild,
God and sinners reconciled.’
Joyful, all you nations rise,
join the triumph of the skies;
with the angelic host proclaim,
‘Christ is born in Bethlehem!’
Hark! the herald-angels sing,
‘Glory to the new-born King!’
Christ by highest heaven adored,
Christ, the everlasting Lord,
late in time behold Him come,
offspring of a virgin’s womb!
Veiled in flesh the Godhead see!
Hail, the incarnate Deity!
Pleased as man with man to dwell,
Jesus, our Immanuel.
Hark! the herald-angels sing,
‘Glory to the new-born King!’
Hail, the heaven-born Prince of peace!
Hail, the Sun of righteousness!
Light and life to all He brings,
risen with healing in His wings.
Mild He lays His glory by,
born that man no more may die;
born to raise the sons of earth,
born to give them second birth.
Hark! the herald-angels sing,
‘Glory to the new-born King!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0211', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0211', 'Felix Mendelssohn');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0211', 'William H Cummings');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0211', 'verse', 1, 0, '[\"Hark! the herald-angels sing,\",\"‘Glory to the new-born King!\",\"Peace on earth, and mercy mild,\",\"God and sinners reconciled.’\",\"Joyful, all you nations rise,\",\"join the triumph of the skies;\",\"with the angelic host proclaim,\",\"‘Christ is born in Bethlehem!’\",\"Hark! the herald-angels sing,\",\"‘Glory to the new-born King!’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0211', 'verse', 2, 1, '[\"Christ by highest heaven adored,\",\"Christ, the everlasting Lord,\",\"late in time behold Him come,\",\"offspring of a virgin’s womb!\",\"Veiled in flesh the Godhead see!\",\"Hail, the incarnate Deity!\",\"Pleased as man with man to dwell,\",\"Jesus, our Immanuel.\",\"Hark! the herald-angels sing,\",\"‘Glory to the new-born King!’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0211', 'verse', 3, 2, '[\"Hail, the heaven-born Prince of peace!\",\"Hail, the Sun of righteousness!\",\"Light and life to all He brings,\",\"risen with healing in His wings.\",\"Mild He lays His glory by,\",\"born that man no more may die;\",\"born to raise the sons of earth,\",\"born to give them second birth.\",\"Hark! the herald-angels sing,\",\"‘Glory to the new-born King!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0212', 212, 'Have Thine own way, Lord', 'MP', 'en', 'Feba Radio', '', 0, 0, 0, 1, 1, 'Have Thine own way, Lord,
have Thine own way;
Thou art the potter, I am the clay;
mould me and make me after Thy will,
while I am waiting, yielded and still.
Have Thine own way, Lord,
have Thine own way;
search me and try me, Master, today.
Whiter than snow, Lord, wash me just now,
as in Thy presence humbly I bow.
Have Thine own way, Lord,
have Thine own way;
wounded and weary, help me, I pray.
Power, all power, surely is Thine;
touch me and heal me, Saviour divine.
Have Thine own way, Lord,
have Thine own way;
hold o’er my being absolute sway;
fill with Thy Spirit till all shall see
Christ only, always, living in me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0212', 'Adelaide Addison Pollard');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0212', 'George Coles Stebbins');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0212', 'verse', 1, 0, '[\"Have Thine own way, Lord,\",\"have Thine own way;\",\"Thou art the potter, I am the clay;\",\"mould me and make me after Thy will,\",\"while I am waiting, yielded and still.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0212', 'verse', 2, 1, '[\"Have Thine own way, Lord,\",\"have Thine own way;\",\"search me and try me, Master, today.\",\"Whiter than snow, Lord, wash me just now,\",\"as in Thy presence humbly I bow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0212', 'verse', 3, 2, '[\"Have Thine own way, Lord,\",\"have Thine own way;\",\"wounded and weary, help me, I pray.\",\"Power, all power, surely is Thine;\",\"touch me and heal me, Saviour divine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0212', 'verse', 4, 3, '[\"Have Thine own way, Lord,\",\"have Thine own way;\",\"hold o’er my being absolute sway;\",\"fill with Thy Spirit till all shall see\",\"Christ only, always, living in me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0213', 213, 'He gave me beauty', 'MP', 'en', '©  1984 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission.', '', 0, 0, 0, 1, 0, 'He gave me beauty for ashes,
the oil of joy for mourning,
the garment of praise
for the spirit of heaviness;
that we might be trees of righteousness,
the planting of the Lord,
that He might be glorified.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0213', 'Robert Manzano');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0213', 'Robert Manzano');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0213', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0213', 'verse', 1, 0, '[\"He gave me beauty for ashes,\",\"the oil of joy for mourning,\",\"the garment of praise\",\"for the spirit of heaviness;\",\"that we might be trees of righteousness,\",\"the planting of the Lord,\",\"that He might be glorified.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0214', 214, 'He gave His life', 'MP', 'en', 'Chris Porteous/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION            © Copyright 1982 Sovereign Music UK. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'He gave His life in selfless love,
for sinful man He came;
He had no stain of sin Himself
but bore our guilt and shame:
He took the cup of pain and death,
His blood was freely shed;
we see His body on the cross,
we share the living bread.
He did not come to call the good
but sinners to repent;
it was the lame, the deaf, the blind
for whom His life was spent:
to heal the sick, to find the lost –
it was for such He came,
and round His table all may come
to praise His holy name.
They heard Him call His Father’s name –
then, ‘Finished!’ was His cry;
like them we have forsaken Him
and left Him there to die:
the sins that crucified Him then
are sins His blood has cured;
the love that bound Him to a cross
our freedom has ensured.
His body broken once for us
is glorious now above;
the cup of blessing we receive,
a sharing of His love:
as in His presence we partake,
His dying we proclaim
until the hour of majesty
when Jesus comes again.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0214', 'Christopher Porteous');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0214', 'Andrew Maries');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0214', 'verse', 1, 0, '[\"He gave His life in selfless love,\",\"for sinful man He came;\",\"He had no stain of sin Himself\",\"but bore our guilt and shame:\",\"He took the cup of pain and death,\",\"His blood was freely shed;\",\"we see His body on the cross,\",\"we share the living bread.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0214', 'verse', 2, 1, '[\"He did not come to call the good\",\"but sinners to repent;\",\"it was the lame, the deaf, the blind\",\"for whom His life was spent:\",\"to heal the sick, to find the lost –\",\"it was for such He came,\",\"and round His table all may come\",\"to praise His holy name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0214', 'verse', 3, 2, '[\"They heard Him call His Father’s name –\",\"then, ‘Finished!’ was His cry;\",\"like them we have forsaken Him\",\"and left Him there to die:\",\"the sins that crucified Him then\",\"are sins His blood has cured;\",\"the love that bound Him to a cross\",\"our freedom has ensured.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0214', 'verse', 4, 3, '[\"His body broken once for us\",\"is glorious now above;\",\"the cup of blessing we receive,\",\"a sharing of His love:\",\"as in His presence we partake,\",\"His dying we proclaim\",\"until the hour of majesty\",\"when Jesus comes again.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0215', 215, 'He has showed you, O man', 'MP', 'en', '1987 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'He has showed you, O man, what is good –
and what does the Lord require of you?
He has showed you, O man, what is good –
and what does the Lord require of you,
but to act justly, and to love mercy,
and to walk humbly with your God;
but to act justly, and to love mercy,
and to walk humbly with your God.
He has showed...');
