INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0216', 216, 'He is born, our Lord and Saviour', 'MP', 'en', '1980 Bud John Songs/CapitolCMGPublishing.com (adm UK/Eire Song Solutions www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'He is born, our Lord and Saviour:
He is born, our heavenly King:
give Him honour, give Him glory,
earth rejoice and heaven sing!
Born to be our sanctuary,
born to bring us light and peace;
for our sins to bring forgiveness,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0216', 'Jimmy Owens');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0216', 'Jimmy Owens');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0216', 'verse', 1, 0, '[\"He is born, our Lord and Saviour:\",\"He is born, our heavenly King:\",\"give Him honour, give Him glory,\",\"earth rejoice and heaven sing!\",\"Born to be our sanctuary,\",\"born to bring us light and peace;\",\"for our sins to bring forgiveness,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0217', 217, 'He is exalted', 'MP', 'en', '1985 Mountain Spring Music/Straightway Music/CapitolCMGPublishing.com (adm UK/Eire Song Solutions  www.songsolutions.org) All rights reserved. Used by permission.', '', 0, 0, 0, 1, 1, 'He is exalted,
the King is exalted on high;
I will praise Him.
He is exalted,
for ever exalted
and I will praise His name!
He is the Lord;
for ever His truth shall reign.
Heaven and earth
rejoice in His holy name.
He is exalted,
the King is exalted on high.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0217', 'Twila Paris');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0217', 'Twila Paris');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0217', 'verse', 1, 0, '[\"He is exalted,\",\"the King is exalted on high;\",\"I will praise Him.\",\"He is exalted,\",\"for ever exalted\",\"and I will praise His name!\",\"He is the Lord;\",\"for ever His truth shall reign.\",\"Heaven and earth\",\"rejoice in His holy name.\",\"He is exalted,\",\"the King is exalted on high.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0218', 218, 'He is here, He is here', 'MP', 'en', '1972 Bud John Songs/CapitolCMGPublishing.com (adm UK/Eire Song Solutions www.songsolutions.org) All rights reserved. Used by permission.', '', 0, 0, 0, 1, 1, 'He is here, He is here,
He is moving among us;
He is here, He is here,
as we gather in His name!
He is here, He is here,
and He wants to work a wonder;
He is here as we gather in His name.
He is Lord, He is Lord,
let us worship before Him;
He is Lord, He is Lord,
as we gather in His name!
He is Lord, He is Lord,
let us praise and adore Him
yesterday and today and for evermore the same.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0218', 'Jimmy Owens');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0218', 'Jimmy Owens');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0218', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0218', 'verse', 1, 0, '[\"He is here, He is here,\",\"He is moving among us;\",\"He is here, He is here,\",\"as we gather in His name!\",\"He is here, He is here,\",\"and He wants to work a wonder;\",\"He is here as we gather in His name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0218', 'verse', 2, 1, '[\"He is Lord, He is Lord,\",\"let us worship before Him;\",\"He is Lord, He is Lord,\",\"as we gather in His name!\",\"He is Lord, He is Lord,\",\"let us praise and adore Him\",\"yesterday and today and for evermore the same.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0219', 219, 'He that is in us', 'MP', 'en', '©  1986 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'He that is in us is greater
than he that is in the world;
He that is in us is greater
than he that is in the world.
Therefore I will sing and I will rejoice,
for His Spirit lives in me.
Christ the living One has overcome,
and we share in His victory.
He that is in us...
All the powers of death and hell and sin
lie crushed beneath His feet.
Jesus owns the name above all names,
crowned with honour and majesty.
He that is in us...
(Repeat verse 2, slowly and majestically)');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0219', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0219', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0219', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0219', 'chorus', 0, 0, '[\"He that is in us is greater\",\"than he that is in the world;\",\"He that is in us is greater\",\"than he that is in the world.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0219', 'verse', 1, 1, '[\"Therefore I will sing and I will rejoice,\",\"for His Spirit lives in me.\",\"Christ the living One has overcome,\",\"and we share in His victory.\",\"He that is in us...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0219', 'verse', 2, 2, '[\"All the powers of death and hell and sin\",\"lie crushed beneath His feet.\",\"Jesus owns the name above all names,\",\"crowned with honour and majesty.\",\"He that is in us...\",\"(Repeat verse 2, slowly and majestically)\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0220', 220, 'He is Lord, He is Lord', 'MP', 'en', 'control                        arrangement: ? Roland Fudge', '', 0, 0, 0, 1, 1, 'He is Lord, He is Lord,
He is risen from the dead
and He is Lord!
Every knee shall bow,
every tongue confess
that Jesus Christ is Lord.');
