INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0221', 221, 'God with us', 'MP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'EACH LINE OF VERSE SUNG FIRST
BY LEADER, THEN BY ALL
He walked where I walk,
He stood where I stand,
He felt what I feel,
He understands.
He knows my frailty,
shared my humanity,
tempted in every way,
yet without sin.
God with us, so close to us,
God with us, Immanuel!
One of a hated race,
stung by the prejudice,
suffering injustice,
yet He forgives.
Wept for my wasted years,
paid for my wickedness,
He died in my place,
that I might live.
God with us...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0221', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0221', 'Graham Kendrick');
