INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0221', 'chorus', 0, 0, '[\"EACH LINE OF VERSE SUNG FIRST\",\"BY LEADER, THEN BY ALL\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0221', 'verse', 1, 1, '[\"He walked where I walk,\",\"He stood where I stand,\",\"He felt what I feel,\",\"He understands.\",\"He knows my frailty,\",\"shared my humanity,\",\"tempted in every way,\",\"yet without sin.\",\"God with us, so close to us,\",\"God with us, Immanuel!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0221', 'verse', 2, 2, '[\"One of a hated race,\",\"stung by the prejudice,\",\"suffering injustice,\",\"yet He forgives.\",\"Wept for my wasted years,\",\"paid for my wickedness,\",\"He died in my place,\",\"that I might live.\",\"God with us...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0222', 222, 'Like a lamb', 'MP', 'en', '©  1987 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'He was pierced for our transgressions,
and bruised for our iniquities;
and to bring us peace He was punished,
and by His stripes we are healed.
He was led like a lamb to the slaughter,
although He was innocent of crime;
and cut off from the land of the living,
He paid for the guilt that was mine.
We like sheep have gone astray,
turned each one to his own way,
and the Lord has laid on Him
the iniquity of us all.
We like sheep...');
