INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0223', 223, 'He who dwells', 'MP', 'en', 'Copyright 1988 Sovereign Lifestyle Music Ltd.  Sovereignmusic@aol.com. Used by Permission.', '', 0, 0, 0, 1, 1, '');
