INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0224', 224, 'He who would valiant be', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'He who would valiant be
’gainst all disaster,
let him in constancy
follow the Master.
There’s no discouragement
shall make him once relent,
his first avowed intent
to be a pilgrim.
Who so beset him round
with dismal stories,
do but themselves confound –
his strength the more is.
No foes shall stay his might,
though he with giants fight:
he will make good his right
to be a pilgrim.
Since, Lord, Thou dost defend
us with Thy Spirit,
we know we at the end
shall life inherit.
Then fancies flee away!
I’ll fear not what men say,
I’ll labour night and day
to be a pilgrim.
Words after by John Bunyan');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0224', 'Percy Dearmer');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0224', 'verse', 1, 0, '[\"He who would valiant be\",\"’gainst all disaster,\",\"let him in constancy\",\"follow the Master.\",\"There’s no discouragement\",\"shall make him once relent,\",\"his first avowed intent\",\"to be a pilgrim.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0224', 'verse', 2, 1, '[\"Who so beset him round\",\"with dismal stories,\",\"do but themselves confound –\",\"his strength the more is.\",\"No foes shall stay his might,\",\"though he with giants fight:\",\"he will make good his right\",\"to be a pilgrim.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0224', 'verse', 3, 2, '[\"Since, Lord, Thou dost defend\",\"us with Thy Spirit,\",\"we know we at the end\",\"shall life inherit.\",\"Then fancies flee away!\",\"I’ll fear not what men say,\",\"I’ll labour night and day\",\"to be a pilgrim.\",\"Words after by John Bunyan\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0225', 225, 'He’s got the whole wide world', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'He’s got the whole wide world in His hands,
He’s got the whole wide world in His hands,
He’s got the whole wide world in His hands,
He’s got the whole world in His hands.
He’s got everybody here, in His hands...
He’s got the tiny little baby, in His hands...
He’s got you and me, brother, in His hands...');
