INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0225', 'verse', 1, 0, '[\"He’s got the whole wide world in His hands,\",\"He’s got the whole wide world in His hands,\",\"He’s got the whole wide world in His hands,\",\"He’s got the whole world in His hands.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0225', 'verse', 2, 1, '[\"He’s got everybody here, in His hands...\"]');
