INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0230', 'verse', 2, 1, '[\"Here would I feed upon the bread of God,\",\"here drink with Thee the royal wine of heaven;\",\"here would I lay aside each earthly load,\",\"here taste afresh the calms of sin forgiven.\"]');
