INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0230', 'verse', 4, 3, '[\"I have no help but Thine; nor do I need\",\"another arm save Thine to lean upon;\",\"it is enough, my Lord, enough indeed;\",\"my strength is in Thy might, Thy might alone.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0230', 'verse', 5, 4, '[\"Mine is the sin, but Thine the righteousness;\",\"mine is the guilt, but Thine the cleansing blood;\",\"here is my robe, my refuge, and my peace –\",\"Thy blood, Thy righteousness, O Lord my God.\"]');
