INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0231', 231, 'Hévénu shalom', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Hévénu shalom aléchem,
Hévénu shalom aléchem,
Hévénu shalom aléchem,
Hévénu shalom,
shalom, shalom aléchem.
Because He died and is risen,
because He died and is risen,
because He died and is risen,
we now have peace with God
through Jesus Christ our Lord.
Hévénu shalom...
His peace destroys walls between us,
His peace destroys walls between us,
His peace destroys walls between us,
for only He can reconcile
us both to God.
Hévénu shalom...
‘My peace I give you,’ said Jesus,
‘My peace I give you,’ said Jesus,
‘My peace I give you,’ said Jesus,
‘don’t let your heart be troubled,
do not be afraid.’
Hévénu shalom...
The peace beyond understanding,
the peace beyond understanding,
the peace beyond understanding,
will guard the hearts and minds
of those who pray to Him.
Hévénu shalom...
Words Verses by Michael Baughen
verses ? Michael Baughen, administered by The Jubilate Group, 4 Thorne Park Road, Torquay TQ2 6RX. www.jubilate.co.uk. Used by permission.            arrangement: ? A & C Black (Publishers) Ltd, taken from Alleluya, published by A & C Black (Publishers) Ltd');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0231', 'chorus', 0, 0, '[\"Hévénu shalom aléchem,\",\"Hévénu shalom aléchem,\",\"Hévénu shalom aléchem,\",\"Hévénu shalom,\",\"shalom, shalom aléchem.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0231', 'verse', 1, 1, '[\"Because He died and is risen,\",\"because He died and is risen,\",\"because He died and is risen,\",\"we now have peace with God\",\"through Jesus Christ our Lord.\",\"Hévénu shalom...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0231', 'verse', 2, 2, '[\"His peace destroys walls between us,\",\"His peace destroys walls between us,\",\"His peace destroys walls between us,\",\"for only He can reconcile\",\"us both to God.\",\"Hévénu shalom...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0231', 'verse', 3, 3, '[\"‘My peace I give you,’ said Jesus,\",\"‘My peace I give you,’ said Jesus,\",\"‘My peace I give you,’ said Jesus,\",\"‘don’t let your heart be troubled,\",\"do not be afraid.’\",\"Hévénu shalom...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0231', 'verse', 4, 4, '[\"The peace beyond understanding,\",\"the peace beyond understanding,\",\"the peace beyond understanding,\",\"will guard the hearts and minds\",\"of those who pray to Him.\",\"Hévénu shalom...\",\"Words Verses by Michael Baughen\",\"verses ? Michael Baughen, administered by The Jubilate Group, 4 Thorne Park Road, Torquay TQ2 6RX. www.jubilate.co.uk. Used by permission.            arrangement: ? A & C Black (Publishers) Ltd, taken from Alleluya, published by A & C Black (Publishers) Ltd\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0232', 232, 'His hands were pierced', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'His hands were pierced, the hands that made
the mountain range and everglade;
that washed the stains of sin away
and changed earth’s darkness into day.
His feet were pierced, the feet that trod
the furthest shining star of God;
and left their imprint deep and clear
on every winding pathway here.
His heart was pierced, the heart that burned
to comfort every heart that yearned;
and from it came a cleansing flood,
the river of redeeming blood.
His hands and feet and heart, all three
were pierced for me on Calvary;
and here and now, to Him I bring
my hands, feet, heart, an offering.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0232', 'Douglas Woods');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0232', 'Douglas Woods');
