INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0232', 'verse', 2, 1, '[\"His feet were pierced, the feet that trod\",\"the furthest shining star of God;\",\"and left their imprint deep and clear\",\"on every winding pathway here.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0232', 'verse', 3, 2, '[\"His heart was pierced, the heart that burned\",\"to comfort every heart that yearned;\",\"and from it came a cleansing flood,\",\"the river of redeeming blood.\"]');
