INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0233', 233, 'His name is higher', 'MP', 'en', 'control                        Music arrangement: © Roger Mayor/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'His name is higher than any other,
His name is Jesus, His name is Lord.
His name is wonderful, His name is Counsellor,
His name is Prince of peace, the mighty God.
His name is higher than any other,
His name is Jesus, His name is Lord.');
