INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0234', 234, 'His name is wonderful', 'MP', 'en', '1959', '', 0, 0, 0, 1, 0, 'His name is wonderful,
His name is wonderful,
His name is wonderful,
Jesus my Lord.
He is the mighty King,
Master of everything,
His name is wonderful,
Jesus my Lord.
He’s the great shepherd,
the rock of all ages,
almighty God is He;
bow down before Him,
love and adore Him,
His name is wonderful,
Jesus my Lord!');
