INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0235', 235, 'Hold me, Lord', 'MP', 'en', 'Mercy/Vineyard Publishing (Admin.by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'MEN AND WOMEN IN CANON
Hold me, Lord, in Your arms,
fill me, Lord, with Your Spirit;
touch my heart with Your love,
let my life glorify Your name.
Singing alleluia, singing alleluia,
singing alleluia, singing alleluia,
alleluia, (alleluia), allelu, (allelu),
alleluia, (alleluia), allelu, (allelu).');
