INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0236', 236, 'Holy child', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Holy child, how still You lie!
safe the manger, soft the hay;
faint upon the eastern sky
breaks the dawn of Christmas Day.
Holy child, whose birthday brings
shepherds from their field and fold,
angel-choirs and eastern kings,
myrrh and frankincense and gold:
Holy child, what gift of grace');
