INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0237', 'verse', 2, 1, '[\"Holy, holy, holy! All the saints adore Thee,\",\"casting down their golden crowns around the glassy sea;\",\"cherubim and seraphim falling down before Thee,\",\"which wert, and art, and evermore shall be.\"]');
