INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0238', 'verse', 3, 2, '[\"Precious Jesus, precious Jesus,\",\"we’re so glad that You’ve redeemed us, precious Jesus;\",\"and we lift our hands before You\",\"as a token of our love,\",\"precious Jesus, precious Jesus.\"]');
