INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0239', 239, 'Holy, holy, holy is the Lord', 'MP', 'en', 'control                        Music arrangement: © Norman Warren/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'Holy, holy, holy is the Lord;
holy is the Lord God almighty!
Holy, holy, holy is the Lord;
holy is the Lord God almighty,
who was, and is, and is to come!
Holy, holy, holy is the Lord!
Jesus, Jesus, Jesus is the Lord;
Jesus is the Lord God almighty!
Jesus, Jesus, Jesus is the Lord;
Jesus is the Lord God almighty,
who was, and is, and is to come!
Jesus, Jesus, Jesus is the Lord!
Worthy, worthy, worthy is the Lord;
worthy is the Lord God almighty!
Worthy, worthy, worthy is the Lord;
worthy is the Lord God almighty,
who was, and is, and is to come!
Worthy, worthy, worthy is the Lord!
Glory, glory, glory to the Lord;
glory to the Lord God almighty!
Glory, glory, glory to the Lord;
glory to the Lord God almighty,
who was, and is, and is to come!
Glory, glory, glory to the Lord!');
