INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0262', 262, 'I am waiting for the dawning', 'MP', 'en', 'Trustees for Methodist Church Purposes. Used with permission.', '', 0, 0, 0, 1, 1, 'I am waiting for the dawning
of the bright and blessèd day,
when the darksome night of sorrow
shall have vanished far away:
when for ever with the Saviour
far beyond this vale of tears,
I shall swell the song of worship
through the everlasting years.
I am looking at the brightness –
see, it shineth from afar –
of the clear and joyous beaming
of the bright and morning Star.
Through the dark grey mist of morning
do I see its glorious light;
then away with every shadow
of this sad and weary night.
I am waiting for the coming
of the Lord who died for me;
O His words have thrilled my spirit,
‘I will come again for Thee.’
I can almost hear His footfall,
on the threshold of the door,
and my heart, my heart is longing
to be with Him evermore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0262', 'Samuel Trevor Francis');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0262', 'Maurice L Wostenholm');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0262', 'verse', 1, 0, '[\"I am waiting for the dawning\",\"of the bright and blessèd day,\",\"when the darksome night of sorrow\",\"shall have vanished far away:\",\"when for ever with the Saviour\",\"far beyond this vale of tears,\",\"I shall swell the song of worship\",\"through the everlasting years.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0262', 'verse', 2, 1, '[\"I am looking at the brightness –\",\"see, it shineth from afar –\",\"of the clear and joyous beaming\",\"of the bright and morning Star.\",\"Through the dark grey mist of morning\",\"do I see its glorious light;\",\"then away with every shadow\",\"of this sad and weary night.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0262', 'verse', 3, 2, '[\"I am waiting for the coming\",\"of the Lord who died for me;\",\"O His words have thrilled my spirit,\",\"‘I will come again for Thee.’\",\"I can almost hear His footfall,\",\"on the threshold of the door,\",\"and my heart, my heart is longing\",\"to be with Him evermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0263', 263, 'I am weak but Thou art strong', 'MP', 'en', 'control            arrangement: ? 1983 Roland Fudge', '', 0, 0, 0, 1, 1, 'I am weak but Thou art strong,
Jesus, keep me from all wrong;
I’ll be satisfied as long
as I walk, let me walk, close with Thee.
Just a closer walk with Thee,
grant it Jesus, this my plea;
daily walking close with Thee,
let it be, dear Lord, let it be.
Through this world of toils and snares,
if I falter, Lord, who cares?
Who with me my burden shares?
None but Thee, dear Lord, none but Thee.
Just a closer walk...
When my feeble life is o’er,
time for me will be no more,
guide me gently, safely home,
to Thy kingdom’s shore, to Thy shore.
Just a closer walk...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0263', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0263', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0263', 'verse', 1, 0, '[\"I am weak but Thou art strong,\",\"Jesus, keep me from all wrong;\",\"I’ll be satisfied as long\",\"as I walk, let me walk, close with Thee.\",\"Just a closer walk with Thee,\",\"grant it Jesus, this my plea;\",\"daily walking close with Thee,\",\"let it be, dear Lord, let it be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0263', 'verse', 2, 1, '[\"Through this world of toils and snares,\",\"if I falter, Lord, who cares?\",\"Who with me my burden shares?\",\"None but Thee, dear Lord, none but Thee.\",\"Just a closer walk...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0263', 'verse', 3, 2, '[\"When my feeble life is o’er,\",\"time for me will be no more,\",\"guide me gently, safely home,\",\"to Thy kingdom’s shore, to Thy shore.\",\"Just a closer walk...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0264', 264, 'I believe in Jesus', 'MP', 'en', '1987 Mercy/Vineyard Music Group (Admin.by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'I believe in Jesus,
I believe He is the Son of God.
I believe He died and rose again,
I believe He paid for us all.
And I believe He’s here now,
standing in our midst,
here with the power to heal now,
and the grace to forgive.
I believe in You, Lord,
I believe You are the Son of God.
I believe You died and rose again,
I believe You paid for us all.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0264', 'Marc Nelson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0264', 'Marc Nelson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0264', 'verse', 1, 0, '[\"I believe in Jesus,\",\"I believe He is the Son of God.\",\"I believe He died and rose again,\",\"I believe He paid for us all.\",\"And I believe He’s here now,\",\"standing in our midst,\",\"here with the power to heal now,\",\"and the grace to forgive.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0264', 'verse', 2, 1, '[\"I believe in You, Lord,\",\"I believe You are the Son of God.\",\"I believe You died and rose again,\",\"I believe You paid for us all.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0265', 265, 'I cannot count Your blessings, Lord', 'MP', 'en', '©  1989 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'I cannot count Your blessings, Lord, they’re wonderful;
I can’t begin to measure Your great love;
I cannot count the times You have forgiven me
and changed me by Your Spirit from above.
How I worship You, my Father,
You are wonderful;
how I glorify You, Jesus,
You’re my Lord.
How I praise You, Holy Spirit,
You have changed my life,
and You’re now at work in me
to change the world.
When I was blind You opened up my eyes to see;
when I was dead You gave me life anew;
when I was lost You found me and You rescued me,
and carried me, rejoicing, home with You.
How I worship You...
I cannot count Your mercies, Lord, they’re marvellous;
I can’t begin to measure Your great grace;
I cannot count the times that You have answered me,
whenever I have prayed and sought Your face.
How I worship You...
Whenever I consider what I am to You,
my heart is filled with wonder, love and awe.
I want to share with others that You love them too,
and tell the world of Jesus, more and more.
How I worship You...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0265', 'Phil Rogers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0265', 'Phil Rogers');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0265', 'verse', 1, 0, '[\"I cannot count Your blessings, Lord, they’re wonderful;\",\"I can’t begin to measure Your great love;\",\"I cannot count the times You have forgiven me\",\"and changed me by Your Spirit from above.\",\"How I worship You, my Father,\",\"You are wonderful;\",\"how I glorify You, Jesus,\",\"You’re my Lord.\",\"How I praise You, Holy Spirit,\",\"You have changed my life,\",\"and You’re now at work in me\",\"to change the world.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0265', 'verse', 2, 1, '[\"When I was blind You opened up my eyes to see;\",\"when I was dead You gave me life anew;\",\"when I was lost You found me and You rescued me,\",\"and carried me, rejoicing, home with You.\",\"How I worship You...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0265', 'verse', 3, 2, '[\"I cannot count Your mercies, Lord, they’re marvellous;\",\"I can’t begin to measure Your great grace;\",\"I cannot count the times that You have answered me,\",\"whenever I have prayed and sought Your face.\",\"How I worship You...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0265', 'verse', 4, 3, '[\"Whenever I consider what I am to You,\",\"my heart is filled with wonder, love and awe.\",\"I want to share with others that You love them too,\",\"and tell the world of Jesus, more and more.\",\"How I worship You...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0266', 266, 'I cannot tell', 'MP', 'en', 'The Baptist Union of Great Britain            arrangement: ? 1983 Roland Fudge', '', 0, 0, 0, 1, 1, 'I cannot tell why He, whom angels worship,
should set His love upon the sons of men,
or why, as Shepherd, He should seek the wanderers,
to bring them back, they know not how or when.
But this I know, that He was born of Mary,
when Bethlehem’s manger was His only home,
and that He lived at Nazareth and laboured,
and so the Saviour, Saviour of the world, is come.
I cannot tell how silently He suffered,
as with His peace He graced this place of tears,
or how His heart upon the cross was broken,
the crown of pain to three and thirty years.
But this I know, He heals the broken-hearted,
and stays our sin, and calms our lurking fear,
and lifts the burden from the heavy-laden,
for yet the Saviour, Saviour of the world, is here.
I cannot tell how He will win the nations,
how He will claim His earthly heritage,
how satisfy the needs and aspirations
of east and west, of sinner and of sage.
But this I know, all flesh shall see His glory,
and He shall reap the harvest He has sown,
and some glad day His sun shall shine in splendour
when He the Saviour, Saviour of the world, is known.
I cannot tell how all the lands shall worship,
when, at His bidding, every storm is stilled,
or who can say how great the jubilation
when all the hearts of men with love are filled.
But this I know, the skies will thrill with rapture,
and myriad, myriad human voices sing,
and earth to heaven, and heaven to earth, will answer:
At last the Saviour, Saviour of the world, is King!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0266', 'William Young Fullerton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0266', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0266', 'verse', 1, 0, '[\"I cannot tell why He, whom angels worship,\",\"should set His love upon the sons of men,\",\"or why, as Shepherd, He should seek the wanderers,\",\"to bring them back, they know not how or when.\",\"But this I know, that He was born of Mary,\",\"when Bethlehem’s manger was His only home,\",\"and that He lived at Nazareth and laboured,\",\"and so the Saviour, Saviour of the world, is come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0266', 'verse', 2, 1, '[\"I cannot tell how silently He suffered,\",\"as with His peace He graced this place of tears,\",\"or how His heart upon the cross was broken,\",\"the crown of pain to three and thirty years.\",\"But this I know, He heals the broken-hearted,\",\"and stays our sin, and calms our lurking fear,\",\"and lifts the burden from the heavy-laden,\",\"for yet the Saviour, Saviour of the world, is here.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0266', 'verse', 3, 2, '[\"I cannot tell how He will win the nations,\",\"how He will claim His earthly heritage,\",\"how satisfy the needs and aspirations\",\"of east and west, of sinner and of sage.\",\"But this I know, all flesh shall see His glory,\",\"and He shall reap the harvest He has sown,\",\"and some glad day His sun shall shine in splendour\",\"when He the Saviour, Saviour of the world, is known.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0266', 'verse', 4, 3, '[\"I cannot tell how all the lands shall worship,\",\"when, at His bidding, every storm is stilled,\",\"or who can say how great the jubilation\",\"when all the hearts of men with love are filled.\",\"But this I know, the skies will thrill with rapture,\",\"and myriad, myriad human voices sing,\",\"and earth to heaven, and heaven to earth, will answer:\",\"At last the Saviour, Saviour of the world, is King!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0267', 267, 'I confess', 'MP', 'en', 'Copyright 1981 Sovereign Lifestyle Music Ltd.  Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'I confess that Jesus Christ is Lord,
I confess that Jesus Christ is Lord.
He’s omnipotent, magnificent,
all-glorious, victorious;
I confess that Jesus Christ is Lord.');
