INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0268', 268, 'I delight greatly in the Lord', 'MP', 'en', 'Copyright 1981 Sovereign Lifestyle Music Ltd.  Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'I delight greatly in the Lord,
my soul rejoices in my God.
I delight greatly in the Lord,
my soul rejoices in my God.
For He has clothed me with garments of salvation,
and arrayed me in a robe of righteousness;
He has clothed me with garments of salvation,
and arrayed me in a robe of righteousness.');
