INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0268', 'Chris Bowater');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0268', 'verse', 1, 0, '[\"I delight greatly in the Lord,\",\"my soul rejoices in my God.\",\"I delight greatly in the Lord,\",\"my soul rejoices in my God.\",\"For He has clothed me with garments of salvation,\",\"and arrayed me in a robe of righteousness;\",\"He has clothed me with garments of salvation,\",\"and arrayed me in a robe of righteousness.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0269', 269, 'I do not know what lies ahead', 'MP', 'en', 'New Spring Publishing/Imagem Music/Small Stone Media BV/Song Solutions Daybreak www.songsolutions.org', '', 0, 0, 0, 1, 1, 'I do not know what lies ahead,
the way I cannot see;
yet one stands near to be my guide,
He’ll show the way to me:
I know who holds the future,
and He’ll guide me with His hand;
with God things don’t just happen,
everything by Him is planned.
So as I face tomorrow,
with its problems large and small,
I’ll trust the God of miracles,
give to Him my all.
I do not know how many days
of life are mine to spend;
but one who knows and cares for me
will keep me to the end:
I know who holds...
I do not know the course ahead,
what joys and griefs are there;
but one is near who fully knows,
I’ll trust His loving care:
I know who holds...');
