INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0269', 'verse', 2, 1, '[\"I do not know how many days\",\"of life are mine to spend;\",\"but one who knows and cares for me\",\"will keep me to the end:\",\"I know who holds...\"]');
