INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0270', 'verse', 1, 0, '[\"I get so excited, Lord,\",\"every time I realize\",\"I’m forgiven, I’m forgiven.\",\"Jesus, Lord, You’ve done it all,\",\"You’ve paid the price:\",\"I’m forgiven, I’m forgiven.\",\"Hallelujah, Lord,\",\"my heart just fills with praise,\",\"my feet start dancing, my hands rise up,\",\"and my lips they bless Your name.\",\"I’m forgiven, I’m forgiven, I’m forgiven.\",\"I’m forgiven, I’m forgiven, I’m forgiven.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0270', 'verse', 2, 1, '[\"Living in Your presence, Lord,\",\"is life itself;\",\"I’m forgiven, I’m forgiven.\",\"with the past behind, grace for today,\",\"and a hope to come;\",\"I’m forgiven, I’m forgiven.\",\"Hallelujah...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0271', 271, 'I Worship You', 'MP', 'en', '1982 Shadow Spring Music/Music Services/Admin. by Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'I give You all the honour
and praise that’s due Your name,
for You are the King of glory,
the Creator of all things.
And I worship You,
I give my life to You,
I fall down on my knees.
Yes, I worship You,
I give my life to You,
I fall down on my knees.
As Your Spirit moves upon me now,
You meet my deepest need,
and I lift my hands up to Your throne,
Your mercy I’ve received.
And I worship...
You have broken chains that bound me,
You’ve set this captive free,
I will lift my voice to praise Your name
for all eternity.
And I worship...');
