INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0272', 272, 'I have decided to follow Jesus', 'MP', 'en', 'control                        ©1966 by Cliff Barrows and Don Hustad. Used with permission. All rights reserved.', '', 0, 0, 0, 1, 1, 'I have decided to follow Jesus, (3 times)
no turning back, no turning back.
The world behind me, the cross before me, (3 times)
no turning back, no turning back.
Though none go with me, I still will follow, (3 times)
no turning back, no turning back.
Will you decide now to follow Jesus? (3 times)
no turning back, no turning back.');
