INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0273', 273, 'I hear the sound of the army of the Lord', 'MP', 'en', 'C.A. Music/MSI Music Adm/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'I hear the sound of the army of the Lord;
I hear the sound of the army of the Lord;
it’s the sound of praise,
it’s the sound of war;
the army of the Lord,
the army of the Lord,
the army of the Lord is marching on.');
