INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0276', 276, 'I just want to praise You', 'MP', 'en', '©  1984 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook Worldwide excluding South Africa songs@integritymusic.com. Used by Permission', '', 0, 0, 0, 1, 0, 'I just want to praise You;
lift my hands and say: ‘I love You.’
You are everything to me,
and I exalt Your holy name on high.
I just want to praise You;
lift my hands and say: ‘I love You.’
You are everything to me,
and I exalt Your holy name;
I exalt Your holy name,
I exalt Your holy name on high.');
