INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0277', 277, 'I know I’ll see Jesus some day', 'MP', 'en', '1921 Hope Publishing Company, Carol Stream, IL  60188. All rights reserved. Used by permission.', '', 0, 0, 0, 1, 1, 'Sweet is the hope that is thrilling my soul:
I know I’ll see Jesus some day!
Then what if the dark clouds of sin o’er me roll,
I know I’ll see Jesus some day!
I know I’ll see Jesus some day!
I know I’ll see Jesus some day!
What a joy it will be
when His face I shall see,
I know I’ll see Jesus some day!
Though I must travel by faith not by sight,
I know I’ll see Jesus some day!
No evil can harm me, no foe can affright,
I know I’ll see Jesus some day!
I know I’ll see Jesus...
Darkness is gathering, but hope shines within,
I know I’ll see Jesus some day!
What joy when He comes to wipe out every sin;
I know I’ll see Jesus some day!
I know I’ll see Jesus...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0277', 'Avis M Christiansen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0277', 'Scott Lawrence');
