INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0277', 'verse', 2, 1, '[\"Though I must travel by faith not by sight,\",\"I know I’ll see Jesus some day!\",\"No evil can harm me, no foe can affright,\",\"I know I’ll see Jesus some day!\",\"I know I’ll see Jesus...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0277', 'verse', 3, 2, '[\"Darkness is gathering, but hope shines within,\",\"I know I’ll see Jesus some day!\",\"What joy when He comes to wipe out every sin;\",\"I know I’ll see Jesus some day!\",\"I know I’ll see Jesus...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0279', 279, 'I know not why', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'I know not why God’s wondrous grace
to me has been made known;
nor why – unworthy as I am –
He claimed me for His own.
But, ‘I know whom I have believed;
and am persuaded that He is able
to keep that which I’ve committed
unto Him against that day.’
I know not how this saving faith
to me He did impart;
or how believing in His word
wrought peace upon my heart.
But ‘I know...
I know not how the Spirit moves,
convincing men of sin;
revealing Jesus through the word,
creating faith in Him.
But ‘I know...
I know not what of good or ill
may be reserved for me –
of weary ways or golden days
before His face I see.
But ‘I know...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0279', 'Daniel Webster Whittle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0279', 'James McGranahan');
