INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0280', 'verse', 2, 1, '[\"I lift my hands,\",\"I raise my voice,\",\"I give my life to You my Lord,\",\"and I rejoice.\",\"There are many, many reasons\",\"why I do the things I do,\",\"O but most of all I love You,\",\"most of all I love You,\",\"Jesus, most of all I love You\",\"because You’re You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0280', 'verse', 3, 2, '[\"I lift my hands,\",\"I raise my voice,\",\"I give my love to You my Lord,\",\"and I rejoice.\",\"There are many, many reasons\",\"why I love You like I do,\",\"O but most of all I love You,\",\"most of all I love You,\",\"Jesus, most of all I love You\",\"because You’re You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0281', 281, 'I lift my eyes', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'I lift my eyes
to the quiet hills,
in the press of a busy day;
as green hills stand
in a dusty land,
so God is my strength and stay.
I lift my eyes
to the quiet hills,
to a calm that is mine to share;
secure and still
in the Father’s will
and kept by the Father’s care.
I lift my eyes
to the quiet hills,
with a prayer as I turn to sleep;
by day, by night,
through the dark and light
my Shepherd will guard His sheep.
I lift my eyes
to the quiet hills,
and my heart to the Father’s throne;
in all my ways,
to the end of days
the Lord will preserve His own.');
