INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0282', 282, 'I live, I live', 'MP', 'en', '1976 John T Benson Publishing Co/Small Stone Media BV/Song Solutions www.songsolutions.org', '', 0, 0, 0, 1, 1, 'I live, I live because He is risen,
I live, I live with power over sin;
I live, I live because He is risen,
I live, I live to worship Him.
Thank You Jesus, thank You Jesus,
because You’re alive,
because You’re alive,
because You’re alive I live.');
