INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0285', 'Kathleen Thomerson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0285', 'verse', 1, 0, '[\"I love the name of Jesus,\",\"King of my heart,\",\"He is everything to me.\",\"I bless the name of Jesus,\",\"reign in my life,\",\"show the Father’s love so free.\",\"Spirit of love,\",\"Spirit of power,\",\"shine through eternity.\",\"I love the name of Jesus,\",\"Light of the world,\",\"let me walk each day with Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0285', 'verse', 2, 1, '[\"I love the name of Jesus,\",\"risen above,\",\"and He loves and prays for me.\",\"I bless the name of Jesus,\",\"ruling on high\",\"with a glorious majesty.\",\"Spirit of love,\",\"Spirit of power,\",\"shine through eternity.\",\"I praise the name of Jesus,\",\"Lord of my life,\",\"for He died to set me free.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0285', 'verse', 3, 2, '[\"I love the name of Jesus,\",\"splendour of God,\",\"and His face I long to see.\",\"I bless the name of Jesus,\",\"Shepherd of men;\",\"by His side I now can be.\",\"Spirit of love,\",\"Spirit of power,\",\"shine through eternity.\",\"I praise the name of Jesus,\",\"for He is love,\",\"and that love He gives to me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0286', 286, 'I love You, O Lord, You alone', 'MP', 'en', 'Christopher Idle (b. 1938)/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION            © David Peacock/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'I love You, O Lord, You alone,
my refuge on whom I depend;
my maker, my Saviour, my own,
my hope and my trust without end.
The Lord is my strength and my song,
defender and guide of my ways;
my Master to whom I belong,
my God who shall have all my praise.
The dangers of death gathered round,
the waves of destruction came near;
but in my despairing I found
the Lord who released me from fear.
I called for His help in my pain,
to God my salvation I cried;
He brought me His comfort again,
I live by the strength He supplied.
The earth and the elements shake
with thunder and lightning and hail;
the cliffs and the mountaintops break
and mortals are feeble and pale.
His justice is full and complete,
His mercy to us has no end;
the clouds are a path for His feet,
He comes on the wings of the wind.
My hope is the promise He gives,
my life is secure in His hand;
I shall not be lost, for He lives!
He comes to my side – I shall stand!
Lord God, You are powerful to save,
Your Spirit will spur me to pray;
Your Son has defeated the grave:
I trust and I praise You today!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0286', 'Christopher Idle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0286', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0286', 'verse', 1, 0, '[\"I love You, O Lord, You alone,\",\"my refuge on whom I depend;\",\"my maker, my Saviour, my own,\",\"my hope and my trust without end.\",\"The Lord is my strength and my song,\",\"defender and guide of my ways;\",\"my Master to whom I belong,\",\"my God who shall have all my praise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0286', 'verse', 2, 1, '[\"The dangers of death gathered round,\",\"the waves of destruction came near;\",\"but in my despairing I found\",\"the Lord who released me from fear.\",\"I called for His help in my pain,\",\"to God my salvation I cried;\",\"He brought me His comfort again,\",\"I live by the strength He supplied.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0286', 'verse', 3, 2, '[\"The earth and the elements shake\",\"with thunder and lightning and hail;\",\"the cliffs and the mountaintops break\",\"and mortals are feeble and pale.\",\"His justice is full and complete,\",\"His mercy to us has no end;\",\"the clouds are a path for His feet,\",\"He comes on the wings of the wind.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0286', 'verse', 4, 3, '[\"My hope is the promise He gives,\",\"my life is secure in His hand;\",\"I shall not be lost, for He lives!\",\"He comes to my side – I shall stand!\",\"Lord God, You are powerful to save,\",\"Your Spirit will spur me to pray;\",\"Your Son has defeated the grave:\",\"I trust and I praise You today!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0287', 287, 'I love You, Lord', 'MP', 'en', '1978, 1980 House Of Mercy Music/Maranatha!Music/Universal Music Ltd/ Print licence UK Song Solutions Daybreak www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'I love You, Lord,
and I lift my voice
to worship You,
O my soul rejoice!
Take joy, my King,
in what You hear,
may it be a sweet,
sweet sound in Your ear.');
