INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0289', 289, 'I receive You', 'MP', 'en', '1982 Mercy Vineyard Publishing/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'I receive You, O Spirit of love;
how I need Your healing from above.
I receive You, I receive You,
I receive Your healing from above.
I can feel You, touching me right now;
come reveal Your power on me now.
I can feel You, I can feel You,
I can feel Your power on me now,
I can feel Your power on me now.');
