INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0290', 'verse', 1, 0, '[\"I receive Your love,\",\"I receive Your love,\",\"in my heart I receive Your love, O Lord,\",\"I receive Your love;\",\"by Your Spirit within me\",\"I receive, I receive Your love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0290', 'verse', 2, 1, '[\"I confess Your love,\",\"I confess Your love,\",\"in my heart I confess Your love, O Lord,\",\"I confess Your love;\",\"by Your Spirit within me\",\"I confess, I confess Your love.\"]');
