INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0292', 292, 'Children of the King', 'MP', 'en', 'control (tried BMG, Music sales and Hal Leonard (no response)', '', 0, 0, 0, 1, 1, 'I see perfection as I look in Your eyes, Lord;
there’s no rejection as I look in Your eyes, Lord.
You are a river that is never dry,
You are the star that lights the evening sky,
You are my God and I will follow You,
and now I know just where I’m going to.
We are children, children of the King;
we will praise Your name,
glorify You, magnify You.
Jesus, we can never deny
Your love for us on the cross
now You’ve made us children of the King.
Your Holy Spirit will for ever control me!
I give my present, future, past, to You completely.
You are a river...
now You’ve made us children of the King!f*r');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0292', 'Chris Eaton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0292', 'Chris Eaton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0292', 'Christopher Hayward');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0292', 'verse', 1, 0, '[\"I see perfection as I look in Your eyes, Lord;\",\"there’s no rejection as I look in Your eyes, Lord.\",\"You are a river that is never dry,\",\"You are the star that lights the evening sky,\",\"You are my God and I will follow You,\",\"and now I know just where I’m going to.\",\"We are children, children of the King;\",\"we will praise Your name,\",\"glorify You, magnify You.\",\"Jesus, we can never deny\",\"Your love for us on the cross\",\"now You’ve made us children of the King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0292', 'verse', 2, 1, '[\"Your Holy Spirit will for ever control me!\",\"I give my present, future, past, to You completely.\",\"You are a river...\",\"now You’ve made us children of the King!f*r\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0293', 293, 'I sing the almighty power of God', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'I sing the almighty power of God,
that made the mountains rise,
that spread the flowing seas abroad,
and built the lofty skies.
I sing the wisdom that ordained
the sun to rule the day;
the moon shines full at His command,
and all the stars obey.
I sing the goodness of the Lord,
that filled the earth with food;
He formed the creatures with His word,
and then pronounced them good.
Creatures, as numerous as they be,
are subject to His care;
there’s not a place where we can flee
but God is present there.
Lord, how Thy wonders are displayed
where’er I turn mine eye,
if I survey the ground I tread,
or gaze upon the sky.
God’s hand is my perpetual guard,
He guides me with His eye;
why should I then forget the Lord,
whose love is ever nigh?');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0293', 'Isaac Watts');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0293', 'Thomas Jackson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0293', 'verse', 1, 0, '[\"I sing the almighty power of God,\",\"that made the mountains rise,\",\"that spread the flowing seas abroad,\",\"and built the lofty skies.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0293', 'verse', 2, 1, '[\"I sing the wisdom that ordained\",\"the sun to rule the day;\",\"the moon shines full at His command,\",\"and all the stars obey.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0293', 'verse', 3, 2, '[\"I sing the goodness of the Lord,\",\"that filled the earth with food;\",\"He formed the creatures with His word,\",\"and then pronounced them good.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0293', 'verse', 4, 3, '[\"Creatures, as numerous as they be,\",\"are subject to His care;\",\"there’s not a place where we can flee\",\"but God is present there.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0293', 'verse', 5, 4, '[\"Lord, how Thy wonders are displayed\",\"where’er I turn mine eye,\",\"if I survey the ground I tread,\",\"or gaze upon the sky.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0293', 'verse', 6, 5, '[\"God’s hand is my perpetual guard,\",\"He guides me with His eye;\",\"why should I then forget the Lord,\",\"whose love is ever nigh?\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0294', 294, 'I sing a new song', 'MP', 'en', '1982 Mercy/Vineyard Publishing & Shadow Spring Music/Music Services (Admin. by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'I sing a new song to the Lord, my God,
I lift my voice to Jesus, the King;
and I worship You, I worship You,
I worship You, I worship You.
I bow down my face at the footstool of the Lamb,
I lay down my life at the altar of God;
and I worship You, I worship You,
I worship You, I worship You.');
