INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0297', 297, 'I stand before the presence', 'MP', 'en', '© 1978 Authentic Publishing / Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'I stand before the presence
of the Lord God of hosts,
a child of my Father
and an heir of His grace.
For Jesus paid the debt for me,
the veil was torn in two,
and the Holy of Holies
has become my dwelling-place.');
