INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0298', 298, 'I want to learn to appreciate You', 'MP', 'en', '©  1980 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'I want to learn to appreciate You,
Lord, in every way,
I want to learn to walk with You,
Lord, day by day;
with You always there to guide me,
hand in hand,
there beside me,
walking in the Spirit day by day.');
