INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0299', 299, 'I trust in Thee, O Lord', 'MP', 'en', '1972 Aquila Publishing/copyright control', '', 0, 0, 0, 1, 1, 'I trust in Thee, O Lord;
I say, ‘Thou art my God.’
My times are in Thy hand,
my times are in Thy hand.
Blessèd be the Lord,
for He has wondrously shown
His steadfast love to me,
His steadfast love to me.');
