INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0300', 300, 'I want to see Your face', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'I want to see Your face,
I want to see Your face,
give You the worship of my heart, of my heart,
giving up my life to You.
Knowing You (knowing You),
loving You (loving You), Lord.');
