INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0302', 302, 'I want to walk with Jesus', 'MP', 'en', '1964 C Simmonds            arrangement: ? 1985 Phil Burt', '', 0, 0, 0, 1, 1, 'I want to walk with Jesus Christ,
all the days I live of this life on earth;
to give to Him complete control
of body and of soul.
Follow Him, follow Him,
yield your life to Him –
He has conquered death,
He is King of kings;
accept the joy which He gives to those
who yield their lives to Him.
I want to learn to speak to Him,
to pray to Him, confess my sin,
to open my life and let Him in,
for joy will then be mine.
Follow Him, follow Him...
I want to learn to speak of Him –
my life must show that He lives in me;
my deeds, my thoughts, my words must speak
all of His love for me.
Follow Him, follow Him...
I want to learn to read His word,
for this is how I know the way
to live my life as pleases Him,
in holiness and joy.
Follow Him, follow Him...
O Holy Spirit of the Lord,
enter now into this heart of mine;
take full control of my selfish will
and make me wholly Thine!
Follow Him, follow Him...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0302', 'C Simmonds');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0302', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0302', 'verse', 1, 0, '[\"I want to walk with Jesus Christ,\",\"all the days I live of this life on earth;\",\"to give to Him complete control\",\"of body and of soul.\",\"Follow Him, follow Him,\",\"yield your life to Him –\",\"He has conquered death,\",\"He is King of kings;\",\"accept the joy which He gives to those\",\"who yield their lives to Him.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0302', 'verse', 2, 1, '[\"I want to learn to speak to Him,\",\"to pray to Him, confess my sin,\",\"to open my life and let Him in,\",\"for joy will then be mine.\",\"Follow Him, follow Him...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0302', 'verse', 3, 2, '[\"I want to learn to speak of Him –\",\"my life must show that He lives in me;\",\"my deeds, my thoughts, my words must speak\",\"all of His love for me.\",\"Follow Him, follow Him...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0302', 'verse', 4, 3, '[\"I want to learn to read His word,\",\"for this is how I know the way\",\"to live my life as pleases Him,\",\"in holiness and joy.\",\"Follow Him, follow Him...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0302', 'verse', 5, 4, '[\"O Holy Spirit of the Lord,\",\"enter now into this heart of mine;\",\"take full control of my selfish will\",\"and make me wholly Thine!\",\"Follow Him, follow Him...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0303', 303, 'I want to serve You, Lord', 'MP', 'en', '©  1988 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'I want to serve You, Lord,
in total abandonment,
I want to yield my heart to You;
I want to give my life in all surrender,
I want to live for You alone.
I want to give my all
in total abandonment,
releasing all within my grasp;
I want to live my life in all its fulness,
I want to worship Christ alone.
I want to come to You
in total abandonment –
Lord, will You set my heart ablaze?
I want to love You with all my soul and strength,
I want to give You all my days.');
