INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0304', 304, 'I want to worship the Lord', 'MP', 'en', '© 1986 Authentic Publishing / Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'I want to worship the Lord
with all of my heart,
give Him my all
and not just a part,
lift up my hands
to the King of kings,
praise Him in everything.');
