INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0306', 306, 'I will call upon the Lord', 'MP', 'en', '1981 Sound III/Lorenz Publishing Co/Small Stone Media (adm UK/Eire Song Solutions www.songsolutions.org) All rights reserved.  Used by permission.', '', 0, 0, 0, 1, 1, 'MEN AND WOMEN IN CANON
I will call upon the Lord,
