INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0307', 307, 'He has made me glad', 'MP', 'en', '1976 Maranatha! Praise Inc/Universal Music Publishing/Print licence UK Song Solutions Daybreak www.songsolutions.org', '', 0, 0, 0, 1, 1, 'I will enter His gates
with thanksgiving in my heart,
I will enter His courts with praise;
I will say, ‘This is the day
that the Lord has made,
I will rejoice for He has made me glad.’
He has made me glad, He has made me glad;
I will rejoice for He has made me glad.
He has made me glad, He has made me glad;
I will rejoice for He has made me glad.');
