INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0308', 308, 'Be exalted O God', 'MP', 'en', '1977 Scripture in Song/Maranatha! Music/Universal Music Publishing/Print licence adm Song Solutions Daybreak, www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'I will give thanks to Thee,
O Lord, among the peoples,
I will sing praises to Thee
among the nations.
For Thy steadfast love is great,
is great to the heavens,
and Thy faithfulness, Thy faithfulness,
to the clouds.
Be exalted, O God, above the heavens,
let Thy glory be over all the earth!
Be exalted, O God, above the heavens,
let Thy glory, let Thy glory,
let Thy glory be over all the earth!');
