INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0308', 'verse', 1, 0, '[\"I will give thanks to Thee,\",\"O Lord, among the peoples,\",\"I will sing praises to Thee\",\"among the nations.\",\"For Thy steadfast love is great,\",\"is great to the heavens,\",\"and Thy faithfulness, Thy faithfulness,\",\"to the clouds.\",\"Be exalted, O God, above the heavens,\",\"let Thy glory be over all the earth!\",\"Be exalted, O God, above the heavens,\",\"let Thy glory, let Thy glory,\",\"let Thy glory be over all the earth!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0309', 309, 'I will give You praise', 'MP', 'en', '©  1985 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'I will give You praise,
I will sing Your song,
I will bless Your holy name;
For there is no other God
who is like unto You,
You’re the only way.
Only You are the author of life,
only You can bring the blind their sight,
only You are called Prince of peace,
only You promised You’d never leave,
only You are God.');
