INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0309', 'Tommy Walker');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0309', 'verse', 1, 0, '[\"I will give You praise,\",\"I will sing Your song,\",\"I will bless Your holy name;\",\"For there is no other God\",\"who is like unto You,\",\"You’re the only way.\",\"Only You are the author of life,\",\"only You can bring the blind their sight,\",\"only You are called Prince of peace,\",\"only You promised You’d never leave,\",\"only You are God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0310', 310, 'I will magnify', 'MP', 'en', 'Mercy/Vineyard Publishing/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'I will magnify Thy name above all the earth;
I will magnify Thy name above all the earth.
I will sing unto Thee the praises in my heart;
