INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0310', 'verse', 1, 0, '[\"I will magnify Thy name above all the earth;\",\"I will magnify Thy name above all the earth.\",\"I will sing unto Thee the praises in my heart;\",\"I will sing unto Thee the praises in my heart.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0311', 311, 'I will rejoice, I will rejoice', 'MP', 'en', '©  1982 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'I will rejoice, I will rejoice,
I will rejoice in the Lord with my whole heart;
I will rejoice, I will rejoice,
I will rejoice in the Lord.
You anoint my head with oil,
and my cup surely overflows;
goodness and love shall follow me
all the days that I dwell in Your house.');
