INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0311', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0311', 'verse', 1, 0, '[\"I will rejoice, I will rejoice,\",\"I will rejoice in the Lord with my whole heart;\",\"I will rejoice, I will rejoice,\",\"I will rejoice in the Lord.\",\"You anoint my head with oil,\",\"and my cup surely overflows;\",\"goodness and love shall follow me\",\"all the days that I dwell in Your house.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0312', 312, 'I will rejoice in You', 'MP', 'en', 'control                        arrangement: ? 1987 Phil Burt', '', 0, 0, 0, 1, 1, 'I will rejoice in You and be glad,
I will extol Your love more than wine;
draw me after You and let us run together,
I will rejoice in You and be glad.');
