INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0312', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0312', 'verse', 1, 0, '[\"I will rejoice in You and be glad,\",\"I will extol Your love more than wine;\",\"draw me after You and let us run together,\",\"I will rejoice in You and be glad.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0313', 313, 'I will sing, I will sing', 'MP', 'en', '1974 Celebration / kingswaysongs.com. tym@kingsway.co.uk. For Europe and Commonwealth (excl. Canada, Australasia and Africa). Used by permission.', '', 0, 0, 0, 1, 0, 'I will sing, I will sing a song unto the Lord, (3 times)
alleluia, glory to the Lord.
Allelu, alleluia, glory to the Lord,
allelu, alleluia, glory to the Lord,
allelu, alleluia, glory to the Lord,
alleluia, glory to the Lord.
We will come, we will come as one before the Lord, (3 times)
alleluia, glory to the Lord.
Allelu, alleluia...
If the Son, if the Son shall make you free, (3 times)
you shall be free indeed.
Allelu, alleluia...
They that sow in tears shall reap in joy, (3 times)
alleluia, glory to the Lord!
Allelu, alleluia...
Every knee shall bow and every tongue confess, (3 times)
that Jesus Christ is Lord.
Allelu, alleluia...
In His name, in His name we have the victory. (3 times)
Alleluia, glory to the Lord.
Allelu, alleluia...');
