INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0329', 329, 'In Christ there is no east or west', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'In Christ there is no east or west,
in Him no south or north,
but one great fellowship of love
throughout the whole wide earth.
In Him shall true hearts everywhere
their high communion find:
His service is the golden cord
close-binding all mankind.
Join hands then, brothers of the faith,
whate’er your race may be!
Who serves my Father as a son
is surely kin to me.
In Christ now meet both east and west,
in Him meet south and north,
all Christly souls are one in Him,
throughout the whole wide earth.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0329', 'John Oxenham');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0329', 'William Jones');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0329', 'verse', 1, 0, '[\"In Christ there is no east or west,\",\"in Him no south or north,\",\"but one great fellowship of love\",\"throughout the whole wide earth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0329', 'verse', 2, 1, '[\"In Him shall true hearts everywhere\",\"their high communion find:\",\"His service is the golden cord\",\"close-binding all mankind.\"]');
