INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0330', 330, 'In full and glad surrender', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'In full and glad surrender,
I give myself to Thee,
Thine utterly and only
and evermore to be.
O Son of God, who lov’st me,
I will be Thine alone;
and all I have and am, Lord,
shall henceforth be Thine own!
Reign over me, Lord Jesus,
O make my heart Thy throne;
it shall be Thine, dear Saviour,
it shall be Thine alone.
O come and reign, Lord Jesus,
rule over everything!
and keep me always loyal
and true to Thee, my King.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0330', 'Frances Ridley Havergal');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0330', 'Henry John Gauntlett');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0330', 'verse', 1, 0, '[\"In full and glad surrender,\",\"I give myself to Thee,\",\"Thine utterly and only\",\"and evermore to be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0330', 'verse', 2, 1, '[\"O Son of God, who lov’st me,\",\"I will be Thine alone;\",\"and all I have and am, Lord,\",\"shall henceforth be Thine own!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0330', 'verse', 3, 2, '[\"Reign over me, Lord Jesus,\",\"O make my heart Thy throne;\",\"it shall be Thine, dear Saviour,\",\"it shall be Thine alone.\"]');
