INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0331', 'verse', 2, 1, '[\"Wherever He may guide me,\",\"no want shall turn me back;\",\"my shepherd is beside me,\",\"and nothing can I lack.\",\"His wisdom ever waketh,\",\"His sight is never dim,\",\"He knows the way He taketh,\",\"and I will walk with Him.\"]');
