INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0332', 332, 'In Him we live and move', 'MP', 'en', '© 1986 Integrity’s Hosanna! Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'In Him we live and move and have our being;
in Him we live and move and have our being.
Make a joyful noise, sing unto the Lord,
tell Him of your love, dance before Him;
make a joyful noise, sing unto the Lord,
tell Him of your love, hallelujah!');
