INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0333', 333, 'In loving-kindness Jesus came', 'MP', 'en', 'Feba Radio', '', 0, 0, 0, 1, 1, 'In loving-kindness Jesus came,
my soul in mercy to reclaim,
and from the depths of sin and shame
through grace He lifted me.');
