INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0334', 334, 'In moments like these', 'MP', 'en', '1980 C.A. Music/MSI Music Adm/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'In moments like these I sing out a song,
I sing out a love-song to Jesus;
in moments like these I lift up my hands,
I lift up my hands to the Lord:
singing, ‘I love You, Lord’,
singing, ‘I love You, Lord’,
singing, ‘I love You, Lord,
I love You.’');
