INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0334', 'verse', 1, 0, '[\"In moments like these I sing out a song,\",\"I sing out a love-song to Jesus;\",\"in moments like these I lift up my hands,\",\"I lift up my hands to the Lord:\",\"singing, ‘I love You, Lord’,\",\"singing, ‘I love You, Lord’,\",\"singing, ‘I love You, Lord,\",\"I love You.’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0335', 335, 'In my life, Lord, be glorified', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'In my life, Lord, be glorified, be glorified;
in my life, Lord, be glorified today.
In your Church, Lord, be glorified, be glorified;
in your Church, Lord, be glorified today.');
