INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0336', 336, 'In my need Jesus found me', 'MP', 'en', 'David Brattle', '', 0, 0, 0, 1, 1, 'In my need Jesus found me,
put His strong arm around me,
brought me safe home,
into the shelter of the fold.
Gracious shepherd that sought me,
precious life-blood that bought me;
out of the night,
into the light and near to God.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0336', 'Gordon Brattle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0336', 'Gordon Brattle');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0336', 'verse', 1, 0, '[\"In my need Jesus found me,\",\"put His strong arm around me,\",\"brought me safe home,\",\"into the shelter of the fold.\",\"Gracious shepherd that sought me,\",\"precious life-blood that bought me;\",\"out of the night,\",\"into the light and near to God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0337', 337, 'In the bleak mid-winter', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'In the bleak mid-winter,
frosty wind made moan,
earth stood hard as iron,
water like a stone;
snow had fallen, snow on snow,
snow on snow,
in the bleak mid-winter,
long ago.
Our God, heaven cannot hold Him,
nor earth sustain,
heaven and earth shall flee away
when He comes to reign;
in the bleak mid-winter
a stable-place sufficed
the Lord God almighty,
Jesus Christ.
Angels and archangels
may have gathered there,
cherubim and seraphim
thronged the air;
but His mother only,
in her maiden bliss,
worshipped the Belovèd
with a kiss.
What can I give Him,
poor as I am?
If I were a shepherd,
I would bring a lamb;
if I were a wise man,
I would do my part;
yet what I can I give Him –
give my heart.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0337', 'Christina Georgina Rossetti');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0337', 'Gustav Holst');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0337', 'verse', 1, 0, '[\"In the bleak mid-winter,\",\"frosty wind made moan,\",\"earth stood hard as iron,\",\"water like a stone;\",\"snow had fallen, snow on snow,\",\"snow on snow,\",\"in the bleak mid-winter,\",\"long ago.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0337', 'verse', 2, 1, '[\"Our God, heaven cannot hold Him,\",\"nor earth sustain,\",\"heaven and earth shall flee away\",\"when He comes to reign;\",\"in the bleak mid-winter\",\"a stable-place sufficed\",\"the Lord God almighty,\",\"Jesus Christ.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0337', 'verse', 3, 2, '[\"Angels and archangels\",\"may have gathered there,\",\"cherubim and seraphim\",\"thronged the air;\",\"but His mother only,\",\"in her maiden bliss,\",\"worshipped the Belovèd\",\"with a kiss.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0337', 'verse', 4, 3, '[\"What can I give Him,\",\"poor as I am?\",\"If I were a shepherd,\",\"I would bring a lamb;\",\"if I were a wise man,\",\"I would do my part;\",\"yet what I can I give Him –\",\"give my heart.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0338', 338, 'In the cross of Christ I glory', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'In the cross of Christ I glory,
towering o’er the wrecks of time:
all the light of sacred story
gathers round its head sublime.
When the woes of life o’ertake me,
hopes deceive, and fears annoy,
never shall the cross forsake me;
Lo! it glows with peace and joy.
When the sun of bliss is beaming
light and love upon my way,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0338', 'John Bowring');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0338', 'John Bacchus Dykes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0338', 'verse', 1, 0, '[\"In the cross of Christ I glory,\",\"towering o’er the wrecks of time:\",\"all the light of sacred story\",\"gathers round its head sublime.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0338', 'verse', 2, 1, '[\"When the woes of life o’ertake me,\",\"hopes deceive, and fears annoy,\",\"never shall the cross forsake me;\",\"Lo! it glows with peace and joy.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0338', 'verse', 3, 2, '[\"When the sun of bliss is beaming\",\"light and love upon my way,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0339', 339, 'In the name of Jesus', 'MP', 'en', 'control                        arrangement: ? 1983 Roland Fudge', '', 0, 0, 0, 1, 1, 'In the name of Jesus,
in the name of Jesus,
we have the victory.
In the name of Jesus,
in the name of Jesus,
demons will have to flee.
Who can tell what God can do?
Who can tell of His love for you?
In the name of Jesus, Jesus,
we have the victory.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0339', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0339', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0339', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0339', 'verse', 1, 0, '[\"In the name of Jesus,\",\"in the name of Jesus,\",\"we have the victory.\",\"In the name of Jesus,\",\"in the name of Jesus,\",\"demons will have to flee.\",\"Who can tell what God can do?\",\"Who can tell of His love for you?\",\"In the name of Jesus, Jesus,\",\"we have the victory.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0340', 340, 'Christ is risen', 'MP', 'en', '©  1986 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'In the tomb so cold they laid Him,
death its victim claimed;
powers of hell, they could not hold Him –
back to life He came!
Christ is risen,
(Christ is risen),
death has been conquered,
(death has been conquered),
Christ is risen,
(Christ is risen):
He shall reign for ever!
Hell had spent its fury on Him,
left Him crucified;
yet by blood He boldly conquered,
sin and death defied.
Christ is risen...
Now the fear of death is broken,
Love has won the crown.
Prisoners of the darkness – listen,
walls are tumbling down!
Christ is risen...
Raised from death, to heaven ascending,
Love’s exalted King:
let His song of joy unending
through the nations ring!
Christ is risen...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0340', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0340', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0340', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0340', 'verse', 1, 0, '[\"In the tomb so cold they laid Him,\",\"death its victim claimed;\",\"powers of hell, they could not hold Him –\",\"back to life He came!\",\"Christ is risen,\",\"(Christ is risen),\",\"death has been conquered,\",\"(death has been conquered),\",\"Christ is risen,\",\"(Christ is risen):\",\"He shall reign for ever!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0340', 'verse', 2, 1, '[\"Hell had spent its fury on Him,\",\"left Him crucified;\",\"yet by blood He boldly conquered,\",\"sin and death defied.\",\"Christ is risen...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0340', 'verse', 3, 2, '[\"Now the fear of death is broken,\",\"Love has won the crown.\",\"Prisoners of the darkness – listen,\",\"walls are tumbling down!\",\"Christ is risen...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0340', 'verse', 4, 3, '[\"Raised from death, to heaven ascending,\",\"Love’s exalted King:\",\"let His song of joy unending\",\"through the nations ring!\",\"Christ is risen...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0341', 341, 'The celebration song', 'MP', 'en', 'Scripture in Song/Maranatha Music/ Universal Music Publishing/Print Licence UK Song Solutions Daybreak www.songsolutions.org', '', 0, 0, 0, 1, 1, 'In the presence of Your people
I will praise Your name,
for alone You are holy,
enthroned on the praises of Israel.
Let us celebrate Your goodness
and Your steadfast love;
may Your name be exalted
here on earth and in heaven above!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0341', 'Brent Chambers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0341', 'Brent Chambers');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0341', 'verse', 1, 0, '[\"In the presence of Your people\",\"I will praise Your name,\",\"for alone You are holy,\",\"enthroned on the praises of Israel.\",\"Let us celebrate Your goodness\",\"and Your steadfast love;\",\"may Your name be exalted\",\"here on earth and in heaven above!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0342', 342, 'Infant holy', 'MP', 'en', 'control            arrangement: ? Rosalind Rusbridge/Copyright control', '', 0, 0, 0, 1, 1, 'Infant holy, infant lowly,
for His bed a cattle stall;
oxen lowing, little knowing
Christ the babe is Lord of all.
Swift are winging angels singing,
nowells ringing, tidings bringing:
Christ the babe is Lord of all;
Christ the babe is Lord of all!
Flocks were sleeping, shepherds keeping
vigil till the morning new,
saw the glory, heard the story –
tidings of a gospel true.
Thus rejoicing, free from sorrow,
praises voicing, greet the morrow:
Christ the babe was born for you;
Christ the babe was born for you!
Words tr. by E M G Reed');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0342', 'A E Rusbridge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0342', 'verse', 1, 0, '[\"Infant holy, infant lowly,\",\"for His bed a cattle stall;\",\"oxen lowing, little knowing\",\"Christ the babe is Lord of all.\",\"Swift are winging angels singing,\",\"nowells ringing, tidings bringing:\",\"Christ the babe is Lord of all;\",\"Christ the babe is Lord of all!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0342', 'verse', 2, 1, '[\"Flocks were sleeping, shepherds keeping\",\"vigil till the morning new,\",\"saw the glory, heard the story –\",\"tidings of a gospel true.\",\"Thus rejoicing, free from sorrow,\",\"praises voicing, greet the morrow:\",\"Christ the babe was born for you;\",\"Christ the babe was born for you!\",\"Words tr. by E M G Reed\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0343', 343, 'Is this the Church of our God?', 'MP', 'en', '1987 Anne Horrobin and Stephen Poxon/Copyright control', '', 0, 0, 0, 1, 1, 'Is this the Church of our God?
Is this the Church of the word?
Is this the Church of His Son Jesus Christ?
Is this the Church of His Spirit?
If we’re dependent on Him,
if we believe God’s own word,
if we’re redeemed by the blood of His Son,
if we are filled with His Spirit:
Then this is the Church of our God,
then this is the Church of His word,
then this is the Church of His Son Jesus Christ,
then this is the Church of our Lord.
Yes, this is the Church of our God,
yes, this is the Church of His word,
yes, this is the Church of His Son Jesus Christ,
yes, this is the Church of our Lord!');
