INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0343', 'verse', 2, 1, '[\"If we’re dependent on Him,\",\"if we believe God’s own word,\",\"if we’re redeemed by the blood of His Son,\",\"if we are filled with His Spirit:\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0343', 'verse', 3, 2, '[\"Then this is the Church of our God,\",\"then this is the Church of His word,\",\"then this is the Church of His Son Jesus Christ,\",\"then this is the Church of our Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0343', 'verse', 4, 3, '[\"Yes, this is the Church of our God,\",\"yes, this is the Church of His word,\",\"yes, this is the Church of His Son Jesus Christ,\",\"yes, this is the Church of our Lord!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0344', 344, 'Isn’t He beautiful', 'MP', 'en', 'Mercy/Vineyard Publishing/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Isn’t He beautiful;
beautiful, isn’t He?
Prince of peace,
Son of God,
isn’t He?
Isn’t He wonderful,
wonderful, isn’t He?
Counsellor,
Almighty God,
isn’t He, isn’t He,
isn’t He, isn’t He?
Yes, You are beautiful,
beautiful, yes, You are!
Prince of peace,
Son of God,
yes, You are!
Yes, You are wonderful,
wonderful, yes, You are!
Counsellor,
Almighty God,
yes, You are, yes, You are,
yes, You are, yes, You are,
yes, You are!');
