INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0344', 'verse', 2, 1, '[\"Yes, You are beautiful,\",\"beautiful, yes, You are!\",\"Prince of peace,\",\"Son of God,\",\"yes, You are!\",\"Yes, You are wonderful,\",\"wonderful, yes, You are!\",\"Counsellor,\",\"Almighty God,\",\"yes, You are, yes, You are,\",\"yes, You are, yes, You are,\",\"yes, You are!\"]');
