INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0346', 'verse', 2, 1, '[\"And yet I know that it is true;\",\"He chose a poor and humble lot,\",\"and wept, and toiled, and mourned, and died,\",\"for love of those who loved Him not.\"]');
