INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0346', 'verse', 5, 4, '[\"I cannot tell how He could love\",\"a child so weak and full of sin;\",\"His love must be most wonderful,\",\"if He could die my love to win.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0346', 'verse', 6, 5, '[\"It is most wonderful to know\",\"His love for me so free and sure;\",\"but ’tis more wonderful to see\",\"my love for Him so faint and poor.\"]');
