INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0350', 350, 'It is no longer I that liveth', 'MP', 'en', '©  1980 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'It is no longer I that liveth
but Christ that liveth in me;
it is no longer I that liveth
but Christ that liveth in me.
He lives, He lives,
Jesus is alive in me;
it is no longer I that liveth
but Christ that liveth in me.');
