INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0350', 'Sally Ellis');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0350', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0350', 'verse', 1, 0, '[\"It is no longer I that liveth\",\"but Christ that liveth in me;\",\"it is no longer I that liveth\",\"but Christ that liveth in me.\",\"He lives, He lives,\",\"Jesus is alive in me;\",\"it is no longer I that liveth\",\"but Christ that liveth in me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0351', 351, 'It’s Your blood', 'MP', 'en', 'Mercy/Vineyard Publishing/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'It’s Your blood that cleanses me,
it’s Your blood that gives me life,
it’s Your blood that took my place
in redeeming sacrifice,
and washes me whiter than the snow, than the snow.
My Jesus, God’s precious sacrifice.');
