INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0351', 'Michael Christ');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0351', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0351', 'verse', 1, 0, '[\"It’s Your blood that cleanses me,\",\"it’s Your blood that gives me life,\",\"it’s Your blood that took my place\",\"in redeeming sacrifice,\",\"and washes me whiter than the snow, than the snow.\",\"My Jesus, God’s precious sacrifice.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0352', 352, 'I’ve found a friend', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'I’ve found a friend; O such a friend!
He loved me ere I knew Him;
He drew me with the cords of love,
and thus He bound me to Him:
and round my heart still closely twine
those ties which nought can sever,
for I am His, and He is mine,
for ever and for ever.
I’ve found a friend; O such a friend!
He bled, He died to save me;
and not alone the gift of life,
but His own self He gave me:
nought that I have mine own I call,
I hold it for the giver;
my heart, my strength, my life, my all,
are His, and His for ever.
I’ve found a friend; O such a friend!
all power to Him is given;
to guard me on my onward course,
and bring me safe to heaven.
Eternal glories gleam afar,
to nerve my faint endeavour;
so now to watch, to work, to war,
and then to rest for ever.
I’ve found a friend; O such a friend!
so kind, and true, and tender!
So wise a counsellor and guide,
so mighty a defender!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0352', 'James Grindlay Small');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0352', 'Arthur Seymour Sullivan');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0352', 'verse', 1, 0, '[\"I’ve found a friend; O such a friend!\",\"He loved me ere I knew Him;\",\"He drew me with the cords of love,\",\"and thus He bound me to Him:\",\"and round my heart still closely twine\",\"those ties which nought can sever,\",\"for I am His, and He is mine,\",\"for ever and for ever.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0352', 'verse', 2, 1, '[\"I’ve found a friend; O such a friend!\",\"He bled, He died to save me;\",\"and not alone the gift of life,\",\"but His own self He gave me:\",\"nought that I have mine own I call,\",\"I hold it for the giver;\",\"my heart, my strength, my life, my all,\",\"are His, and His for ever.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0352', 'verse', 3, 2, '[\"I’ve found a friend; O such a friend!\",\"all power to Him is given;\",\"to guard me on my onward course,\",\"and bring me safe to heaven.\",\"Eternal glories gleam afar,\",\"to nerve my faint endeavour;\",\"so now to watch, to work, to war,\",\"and then to rest for ever.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0352', 'verse', 4, 3, '[\"I’ve found a friend; O such a friend!\",\"so kind, and true, and tender!\",\"So wise a counsellor and guide,\",\"so mighty a defender!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0353', 353, 'I’ve got peace like a river', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'I’ve got peace like a river, peace like a river,
I’ve got peace like a river in my soul;
I’ve got peace like a river, peace like a river,
I’ve got peace like a river in my soul.');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0353', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0353', 'verse', 1, 0, '[\"I’ve got peace like a river, peace like a river,\",\"I’ve got peace like a river in my soul;\",\"I’ve got peace like a river, peace like a river,\",\"I’ve got peace like a river in my soul.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0354', 354, 'Jehovah Jireh', 'MP', 'en', 'Lorenz Publishing Co (Adm Small Stone Media BV/Song Solutions www.songsolutions.org). All rights reserved. Used by permission.', '', 0, 0, 0, 1, 1, 'Jehovah Jireh, my provider,
His grace is sufficient for me, for me, for me.
Jehovah Jireh, my provider,
His grace is sufficient for me.
My God shall supply all my need
according to His riches in glory;
He gives His angels charge over me.
Jehovah Jireh cares for me, for me, for me.
Jehovah Jireh cares for me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0354', 'Merla Watson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0354', 'Merla Watson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0354', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0354', 'verse', 1, 0, '[\"Jehovah Jireh, my provider,\",\"His grace is sufficient for me, for me, for me.\",\"Jehovah Jireh, my provider,\",\"His grace is sufficient for me.\",\"My God shall supply all my need\",\"according to His riches in glory;\",\"He gives His angels charge over me.\",\"Jehovah Jireh cares for me, for me, for me.\",\"Jehovah Jireh cares for me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0355', 355, 'Jesus, at Your name', 'MP', 'en', 'Copyright 1982 Sovereign Lifestyle Music Ltd.  Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'Jesus, at Your name we bow the knee,
Jesus, at Your name we bow the knee,
Jesus, at Your name we bow the knee,
and acknowledge You as Lord.
Jesus, at Your name...
You are the Christ, You are the Lord,
through Your Spirit in our lives
we know who You are.
You are the Christ...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0355', 'Chris Bowater');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0355', 'Chris Bowater');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0355', 'verse', 1, 0, '[\"Jesus, at Your name we bow the knee,\",\"Jesus, at Your name we bow the knee,\",\"Jesus, at Your name we bow the knee,\",\"and acknowledge You as Lord.\",\"Jesus, at Your name...\",\"You are the Christ, You are the Lord,\",\"through Your Spirit in our lives\",\"we know who You are.\",\"You are the Christ...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0356', 356, 'Jesus Christ, our great Redeemer', 'MP', 'en', '©  1983 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Jesus Christ, our great Redeemer,
mighty victor and strong deliverer,
King of kings and Lord of lords,
We praise You, praise Your name –
Alleluia, alleluia;
King of kings and Lord of lords –
Alleluia, alleluia!
Your victory is assured.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0356', 'Peter Fung');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0356', 'Diane Fung');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0356', 'Peter Fung');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0356', 'Diane Fung');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0356', 'verse', 1, 0, '[\"Jesus Christ, our great Redeemer,\",\"mighty victor and strong deliverer,\",\"King of kings and Lord of lords,\",\"We praise You, praise Your name –\",\"Alleluia, alleluia;\",\"King of kings and Lord of lords –\",\"Alleluia, alleluia!\",\"Your victory is assured.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0357', 357, 'Jesus Christ is risen today', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus Christ is risen today,
hallelujah!
our triumphant holy day,
who did once, upon the cross,
suffer to redeem our loss.
Hymns of praise then let us sing,
unto Christ, our heavenly King,
who endured the cross and grave,
sinners to redeem and save.
But the pains which He endured,
our salvation have procured,
now in heaven above He’s King,
where the angels ever sing:
Music melody by by Robert Williams');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0357', 'verse', 1, 0, '[\"Jesus Christ is risen today,\",\"hallelujah!\",\"our triumphant holy day,\",\"who did once, upon the cross,\",\"suffer to redeem our loss.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0357', 'verse', 2, 1, '[\"Hymns of praise then let us sing,\",\"unto Christ, our heavenly King,\",\"who endured the cross and grave,\",\"sinners to redeem and save.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0357', 'verse', 3, 2, '[\"But the pains which He endured,\",\"our salvation have procured,\",\"now in heaven above He’s King,\",\"where the angels ever sing:\",\"Music melody by by Robert Williams\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0358', 358, 'Jesus Christ is alive today', 'MP', 'en', 'control                        arrangement: ? 1983 Roland Fudge', '', 0, 0, 0, 1, 1, 'Jesus Christ is alive today,
I know, I know it’s true.
Sovereign of the universe,
I give Him homage due.
Seated there at God’s right hand,
I am with Him in the promised land.
Jesus lives and reigns in me,
that’s how I know it’s true.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0358', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0358', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0358', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0358', 'verse', 1, 0, '[\"Jesus Christ is alive today,\",\"I know, I know it’s true.\",\"Sovereign of the universe,\",\"I give Him homage due.\",\"Seated there at God’s right hand,\",\"I am with Him in the promised land.\",\"Jesus lives and reigns in me,\",\"that’s how I know it’s true.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0359', 359, 'Jesus calls us', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus calls us; o’er the tumult
of our life’s wild restless sea,
day by day His voice is sounding,
saying, ‘Christian, follow me.’
As of old, apostles heard it
by the Galilean lake,
turned from home, and toil, and kindred,
leaving all for His dear sake.
Jesus calls us from the worship
of the vain world’s golden store,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0359', 'Cecil Frances Alexander');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0359', 'Edward Henry Thorne');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0359', 'verse', 1, 0, '[\"Jesus calls us; o’er the tumult\",\"of our life’s wild restless sea,\",\"day by day His voice is sounding,\",\"saying, ‘Christian, follow me.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0359', 'verse', 2, 1, '[\"As of old, apostles heard it\",\"by the Galilean lake,\",\"turned from home, and toil, and kindred,\",\"leaving all for His dear sake.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0359', 'verse', 3, 2, '[\"Jesus calls us from the worship\",\"of the vain world’s golden store,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0360', 360, 'Jesus has sat down', 'MP', 'en', '©  1983 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Jesus has sat down at God’s right hand,
He is reigning now on David’s throne;
God has placed all things beneath His feet,
His enemies will be His footstool.
For the government
is now upon His shoulder,
for the government
is now upon His shoulder;
and of the increase
of His government and peace
there will be no end,
there will be no end,
there will be no end.
God has now exalted Him on high,
given Him a name above all names;
every knee will bow, and tongue confess
that Jesus Christ is Lord.
For the government...
Jesus is now living in His Church:
men who have been purchased by His blood –
they will serve their God, a royal priesthood,
and they will reign on earth.
For the government...
Sound the trumpet – good news to the poor!
Captives will go free, the blind will see,
the kingdom of this world will soon become
the kingdom of our God.
For the government...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0360', 'Jonathan Wallis');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0360', 'Jonathan Wallis');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0360', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0360', 'verse', 1, 0, '[\"Jesus has sat down at God’s right hand,\",\"He is reigning now on David’s throne;\",\"God has placed all things beneath His feet,\",\"His enemies will be His footstool.\",\"For the government\",\"is now upon His shoulder,\",\"for the government\",\"is now upon His shoulder;\",\"and of the increase\",\"of His government and peace\",\"there will be no end,\",\"there will be no end,\",\"there will be no end.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0360', 'verse', 2, 1, '[\"God has now exalted Him on high,\",\"given Him a name above all names;\",\"every knee will bow, and tongue confess\",\"that Jesus Christ is Lord.\",\"For the government...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0360', 'verse', 3, 2, '[\"Jesus is now living in His Church:\",\"men who have been purchased by His blood –\",\"they will serve their God, a royal priesthood,\",\"and they will reign on earth.\",\"For the government...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0360', 'verse', 4, 3, '[\"Sound the trumpet – good news to the poor!\",\"Captives will go free, the blind will see,\",\"the kingdom of this world will soon become\",\"the kingdom of our God.\",\"For the government...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0361', 361, 'Jesus, how lovely You are', 'MP', 'en', '©  1975 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Jesus, how lovely You are!
You are so gentle, so pure and kind,
You shine like the morning star:
Jesus, how lovely You are.
Alleluia, Jesus is my Lord and King;
Alleluia, Jesus is my everything.
Jesus, how lovely...
Alleluia, Jesus died and rose again;
Alleluia, Jesus forgave all my sin.
Jesus, how lovely...
Alleluia, Jesus is meek and lowly;
Alleluia, Jesus is pure and holy.
Jesus, how lovely...
Alleluia, Jesus is the bridegroom;
Alleluia, Jesus will take His bride soon.
Jesus, how lovely...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0361', 'David Bolton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0361', 'David Bolton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0361', 'chorus', 0, 0, '[\"Jesus, how lovely You are!\",\"You are so gentle, so pure and kind,\",\"You shine like the morning star:\",\"Jesus, how lovely You are.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0361', 'verse', 1, 1, '[\"Alleluia, Jesus is my Lord and King;\",\"Alleluia, Jesus is my everything.\",\"Jesus, how lovely...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0361', 'verse', 2, 2, '[\"Alleluia, Jesus died and rose again;\",\"Alleluia, Jesus forgave all my sin.\",\"Jesus, how lovely...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0361', 'verse', 3, 3, '[\"Alleluia, Jesus is meek and lowly;\",\"Alleluia, Jesus is pure and holy.\",\"Jesus, how lovely...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0361', 'verse', 4, 4, '[\"Alleluia, Jesus is the bridegroom;\",\"Alleluia, Jesus will take His bride soon.\",\"Jesus, how lovely...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0362', 362, 'Jesus, I am resting, resting', 'MP', 'en', 'HarperCollinsReligious, administered by Copycare PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.', '', 0, 0, 0, 1, 1, 'Jesus, I am resting, resting,
in the joy of what Thou art;
I am finding out the greatness
of Thy loving heart.
Thou hast bid me gaze upon Thee,
and Thy beauty fills my soul,
for, by Thy transforming power,
Thou hast made me whole.
Jesus, I am resting, resting,
in the joy of what Thou art;
I am finding out the greatness
of Thy loving heart.
O how great Thy loving-kindness,
vaster, broader than the sea!
O how marvellous Thy goodness,
lavished all on me!
Yes, I rest in Thee, Belovèd,
know what wealth of grace is Thine,
know Thy certainty of promise,
and have made it mine.
Jesus, I am resting...
Simply trusting Thee, Lord Jesus,
I behold Thee as Thou art;
and Thy love so pure, so changeless,
satisfies my heart.
Satisfies its deepest longings,
meets, supplies its every need,
compasseth me round with blessings;
Thine is love indeed.
Jesus, I am resting...
Ever lift Thy face upon me,
as I work and wait for Thee;
resting ’neath Thy smile, Lord Jesus,
earth’s dark shadows flee.
Brightness of my Father’s glory,
sunshine of my Father’s face,
keep me ever trusting, resting,
fill me with Thy grace.
Jesus, I am resting...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0362', 'Jean Sophia Pigott');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0362', 'James Mountain');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0362', 'verse', 1, 0, '[\"Jesus, I am resting, resting,\",\"in the joy of what Thou art;\",\"I am finding out the greatness\",\"of Thy loving heart.\",\"Thou hast bid me gaze upon Thee,\",\"and Thy beauty fills my soul,\",\"for, by Thy transforming power,\",\"Thou hast made me whole.\",\"Jesus, I am resting, resting,\",\"in the joy of what Thou art;\",\"I am finding out the greatness\",\"of Thy loving heart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0362', 'verse', 2, 1, '[\"O how great Thy loving-kindness,\",\"vaster, broader than the sea!\",\"O how marvellous Thy goodness,\",\"lavished all on me!\",\"Yes, I rest in Thee, Belovèd,\",\"know what wealth of grace is Thine,\",\"know Thy certainty of promise,\",\"and have made it mine.\",\"Jesus, I am resting...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0362', 'verse', 3, 2, '[\"Simply trusting Thee, Lord Jesus,\",\"I behold Thee as Thou art;\",\"and Thy love so pure, so changeless,\",\"satisfies my heart.\",\"Satisfies its deepest longings,\",\"meets, supplies its every need,\",\"compasseth me round with blessings;\",\"Thine is love indeed.\",\"Jesus, I am resting...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0362', 'verse', 4, 3, '[\"Ever lift Thy face upon me,\",\"as I work and wait for Thee;\",\"resting ’neath Thy smile, Lord Jesus,\",\"earth’s dark shadows flee.\",\"Brightness of my Father’s glory,\",\"sunshine of my Father’s face,\",\"keep me ever trusting, resting,\",\"fill me with Thy grace.\",\"Jesus, I am resting...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0363', 363, 'Jesus, I love You', 'MP', 'en', '©  1986 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Jesus, I love You,
love You more and more each day;
Jesus, I love You,
Your gentle touch renews my heart.
It’s really no wonder why
no other love can satisfy;
Jesus, I love You,
You’ve won this heart of mine!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0363', 'Trish Morgan');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0363', 'Trish Morgan');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0363', 'verse', 1, 0, '[\"Jesus, I love You,\",\"love You more and more each day;\",\"Jesus, I love You,\",\"Your gentle touch renews my heart.\",\"It’s really no wonder why\",\"no other love can satisfy;\",\"Jesus, I love You,\",\"You’ve won this heart of mine!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0364', 364, 'Jesus, I worship You', 'MP', 'en', 'Copyright 1982 Sovereign Lifestyle Music Ltd. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'Jesus, I worship You,
worship, honour and adore Your lovely name;
Jesus, I worship You,
Lord of lords and King of kings,
I worship You;');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0364', 'Chris Bowater');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0364', 'Chris Bowater');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0364', 'verse', 1, 0, '[\"Jesus, I worship You,\",\"worship, honour and adore Your lovely name;\",\"Jesus, I worship You,\",\"Lord of lords and King of kings,\",\"I worship You;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0365', 365, 'Jesus is Lord of all', 'MP', 'en', '© 1983 Authentic Publishing/Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'Jesus is Lord of all,
Satan is under His feet,
Jesus is reigning on high,
and all power is given to Him
in heaven and earth.
We are joined to Him,
Satan is under our feet,
we are seated on high,
and all authority is given
to us through Him.
One day we’ll be like Him,
perfect in every way,
chosen to be His bride,
ruling and reigning with Him
for evermore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0365', 'Marilyn Baker');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0365', 'Marilyn Baker');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0365', 'verse', 1, 0, '[\"Jesus is Lord of all,\",\"Satan is under His feet,\",\"Jesus is reigning on high,\",\"and all power is given to Him\",\"in heaven and earth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0365', 'verse', 2, 1, '[\"We are joined to Him,\",\"Satan is under our feet,\",\"we are seated on high,\",\"and all authority is given\",\"to us through Him.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0365', 'verse', 3, 2, '[\"One day we’ll be like Him,\",\"perfect in every way,\",\"chosen to be His bride,\",\"ruling and reigning with Him\",\"for evermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0366', 366, 'Jesus is King', 'MP', 'en', '© 1982 Authentic Publishing/Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'Jesus is King
and I will extol Him,
give Him the glory,
and honour His name;
He reigns on high,
enthroned in the heavens –
Word of the Father,
exalted for us.
We have a hope
that is steadfast and certain,
gone through the curtain
and touching the throne;
we have a priest
who is there interceding,
pouring His grace
on our lives day by day.
We come to Him,
our Priest and Apostle,
clothed in His glory
and bearing His name,
laying our lives
with gladness before Him –
filled with His Spirit
we worship the King:
‘O Holy One,
our hearts do adore You;
thrilled with Your goodness
we give You our praise!’
Angels in light
with worship surround Him,
Jesus, our Saviour,
for ever the same.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0366', 'Wendy Churchill');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0366', 'Wendy Churchill');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0366', 'verse', 1, 0, '[\"Jesus is King\",\"and I will extol Him,\",\"give Him the glory,\",\"and honour His name;\",\"He reigns on high,\",\"enthroned in the heavens –\",\"Word of the Father,\",\"exalted for us.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0366', 'verse', 2, 1, '[\"We have a hope\",\"that is steadfast and certain,\",\"gone through the curtain\",\"and touching the throne;\",\"we have a priest\",\"who is there interceding,\",\"pouring His grace\",\"on our lives day by day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0366', 'verse', 3, 2, '[\"We come to Him,\",\"our Priest and Apostle,\",\"clothed in His glory\",\"and bearing His name,\",\"laying our lives\",\"with gladness before Him –\",\"filled with His Spirit\",\"we worship the King:\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0366', 'verse', 4, 3, '[\"‘O Holy One,\",\"our hearts do adore You;\",\"thrilled with Your goodness\",\"we give You our praise!’\",\"Angels in light\",\"with worship surround Him,\",\"Jesus, our Saviour,\",\"for ever the same.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0367', 367, 'Jesus is Lord', 'MP', 'en', '©  2003 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Jesus is Lord! Creation’s voice proclaims it,
for by His power each tree and flower was planned and made.
Jesus is Lord! The universe declares it;
sun, moon and stars in heaven cry: ‘Jesus is Lord!’
Jesus is Lord! Jesus is Lord!
Praise Him with hallelujahs, for Jesus is Lord!
Jesus is Lord! Yet from His throne eternal
in flesh He came to die in pain on Calvary’s tree.
Jesus is Lord! From Him all life proceeding,
yet gave His life a ransom thus setting us free.
Jesus is Lord...
Jesus is Lord! O’er sin the mighty conqueror,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0367', 'David J Mansell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0367', 'David J Mansell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0367', 'verse', 1, 0, '[\"Jesus is Lord! Creation’s voice proclaims it,\",\"for by His power each tree and flower was planned and made.\",\"Jesus is Lord! The universe declares it;\",\"sun, moon and stars in heaven cry: ‘Jesus is Lord!’\",\"Jesus is Lord! Jesus is Lord!\",\"Praise Him with hallelujahs, for Jesus is Lord!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0367', 'verse', 2, 1, '[\"Jesus is Lord! Yet from His throne eternal\",\"in flesh He came to die in pain on Calvary’s tree.\",\"Jesus is Lord! From Him all life proceeding,\",\"yet gave His life a ransom thus setting us free.\",\"Jesus is Lord...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0367', 'verse', 3, 2, '[\"Jesus is Lord! O’er sin the mighty conqueror,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0368', 368, 'Jesus is the Lord', 'MP', 'en', '© 1981 Authentic Publishing/Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'Jesus is the Lord, Jesus the Lord reigns,
we will take the kingdoms of this world in His name.
Every tribe and nation, every situation,
must declare that Jesus is the Lord.
For the Lord our God has delivered Him from death
and established Jesus as Lord;
He has given Him the power over all that He has made,
for our God has made Him Christ the Lord.');
