INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0368', 'verse', 1, 0, '[\"Jesus is the Lord, Jesus the Lord reigns,\",\"we will take the kingdoms of this world in His name.\",\"Every tribe and nation, every situation,\",\"must declare that Jesus is the Lord.\",\"For the Lord our God has delivered Him from death\",\"and established Jesus as Lord;\",\"He has given Him the power over all that He has made,\",\"for our God has made Him Christ the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0369', 369, 'Jesus, Jesus, You are my Lord', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus, Jesus,
You are my Lord and my heart’s desire;
Jesus, Jesus,
keep us in Your love.
Jesus, Jesus,
You are my King and my Sovereign Master;
Jesus, Jesus,
I will serve You, Lord.');
