INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0371', 371, 'Agnus Dei', 'MP', 'en', '1974 Celebration / kingswaysongs.com. tym@kingsway.co.uk. For Europe and Commonwealth (excl. Canada, Australasia and Africa). Used by permission.', '', 0, 0, 0, 1, 0, 'Jesus, Lamb of God,
have mercy on us.
Jesus, bearer of our sins,
have mercy on us.
Jesus, Redeemer of the world,
give us your peace,
give us your peace.
Jesus, Lamb of God,
have mercy on us.
Jesus, bearer of our sins,
have mercy on us.
Jesus, Redeemer of the world,
give us your peace.');
