INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0371', 'verse', 1, 0, '[\"Jesus, Lamb of God,\",\"have mercy on us.\",\"Jesus, bearer of our sins,\",\"have mercy on us.\",\"Jesus, Redeemer of the world,\",\"give us your peace,\",\"give us your peace.\",\"Jesus, Lamb of God,\",\"have mercy on us.\",\"Jesus, bearer of our sins,\",\"have mercy on us.\",\"Jesus, Redeemer of the world,\",\"give us your peace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0372', 372, 'Jesus, lover of my soul', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'Jesus, lover of my soul,
let me to Thy bosom fly,
while the nearer waters roll,
while the tempest still is high:
hide me, O my Saviour, hide,
till the storm of life is past;
safe into the haven guide;
O receive my soul at last!
Other refuge have I none,
hangs my helpless soul on Thee;
leave, ah! leave me not alone,
still support and comfort me:
all my trust on Thee is stayed;
all my help from Thee I bring;
cover my defenceless head
with the shadow of Thy wing.
Thou, O Christ, art all I want;
more than all in Thee I find;
raise the fallen, cheer the faint,
heal the sick, and lead the blind.
Just and holy is Thy name,
I am all unrighteousness;
false, and full of sin I am,
Thou art full of truth and grace.
Plenteous grace with Thee is found,
grace to cover all my sin;
let the healing streams abound,
make and keep me pure within.
Thou of life the fountain art,
freely let me take of Thee;
spring Thou up within my heart,
rise to all eternity.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0372', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0372', 'Joseph Parry');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0372', 'verse', 1, 0, '[\"Jesus, lover of my soul,\",\"let me to Thy bosom fly,\",\"while the nearer waters roll,\",\"while the tempest still is high:\",\"hide me, O my Saviour, hide,\",\"till the storm of life is past;\",\"safe into the haven guide;\",\"O receive my soul at last!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0372', 'verse', 2, 1, '[\"Other refuge have I none,\",\"hangs my helpless soul on Thee;\",\"leave, ah! leave me not alone,\",\"still support and comfort me:\",\"all my trust on Thee is stayed;\",\"all my help from Thee I bring;\",\"cover my defenceless head\",\"with the shadow of Thy wing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0372', 'verse', 3, 2, '[\"Thou, O Christ, art all I want;\",\"more than all in Thee I find;\",\"raise the fallen, cheer the faint,\",\"heal the sick, and lead the blind.\",\"Just and holy is Thy name,\",\"I am all unrighteousness;\",\"false, and full of sin I am,\",\"Thou art full of truth and grace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0372', 'verse', 4, 3, '[\"Plenteous grace with Thee is found,\",\"grace to cover all my sin;\",\"let the healing streams abound,\",\"make and keep me pure within.\",\"Thou of life the fountain art,\",\"freely let me take of Thee;\",\"spring Thou up within my heart,\",\"rise to all eternity.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0373', 373, 'Jesus lives', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus lives! thy terrors now
can, O death, no more appal us;
Jesus lives! by this we know,
thou, O grave, canst not enthral us.
Hallelujah!
Jesus lives! henceforth is death
but the gate of life immortal;
this shall calm our trembling breath,
when we pass its gloomy portal.
Hallelujah!
Jesus lives! for us He died;
then, alone to Jesus living,
pure in heart may we abide,
glory to our Saviour giving.
Hallelujah!
Jesus lives! our hearts know well,
naught from us His love shall sever;
life, nor death, nor powers of hell,
tear us from His keeping ever.
Hallelujah!
Jesus lives! to Him the throne
over all the world is given:
may we go where He is gone,
rest and reign with Him in heaven.
Hallelujah!');
