INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0373', 'verse', 3, 2, '[\"Jesus lives! for us He died;\",\"then, alone to Jesus living,\",\"pure in heart may we abide,\",\"glory to our Saviour giving.\",\"Hallelujah!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0373', 'verse', 4, 3, '[\"Jesus lives! our hearts know well,\",\"naught from us His love shall sever;\",\"life, nor death, nor powers of hell,\",\"tear us from His keeping ever.\",\"Hallelujah!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0373', 'verse', 5, 4, '[\"Jesus lives! to Him the throne\",\"over all the world is given:\",\"may we go where He is gone,\",\"rest and reign with Him in heaven.\",\"Hallelujah!\"]');
