INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0376', 'verse', 2, 1, '[\"Jesus taught us how to live in harmony,\",\"Jesus taught us how to live in harmony;\",\"different faces, different races, He made us one –\",\"Jesus taught us how to live in harmony.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0376', 'verse', 3, 2, '[\"Jesus taught us how to be a family,\",\"Jesus taught us how to be a family;\",\"loving one another with the love that He gives –\",\"Jesus taught us how to be a family.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0376', 'verse', 4, 3, '[\"Jesus turned our sorrow into dancing,\",\"Jesus turned our sorrow into dancing,\",\"changed our tears of sadness into rivers of joy –\",\"Jesus turned our sorrow into a dance.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0377', 377, 'Jesus, Prince and Saviour', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus, Prince and Saviour,
Lord of life who died;
Christ, the friend of sinners,
mocked and crucified.
For a world’s salvation,
He His body gave,
lay at last death’s victim,
lifeless in the grave.
Lord of life triumphant,
risen now to reign!
King of endless ages,
Jesus lives again!
In His power and Godhead
every victory won;
pain and passion ended,
all His purpose done.
Christ the Lord is risen!
sighs and sorrows past,
death’s dark night is over,
morning comes at last!
Lord of life...
Resurrection morning!
sinners’ bondage freed;
Christ the Lord is risen –
He is risen indeed!
Jesus, Prince and Saviour,
Lord of life who died,
Christ the King of glory
now is glorified!
Lord of life...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0377', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0377', 'Arthur Seymour Sullivan');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0377', 'verse', 1, 0, '[\"Jesus, Prince and Saviour,\",\"Lord of life who died;\",\"Christ, the friend of sinners,\",\"mocked and crucified.\",\"For a world’s salvation,\",\"He His body gave,\",\"lay at last death’s victim,\",\"lifeless in the grave.\",\"Lord of life triumphant,\",\"risen now to reign!\",\"King of endless ages,\",\"Jesus lives again!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0377', 'verse', 2, 1, '[\"In His power and Godhead\",\"every victory won;\",\"pain and passion ended,\",\"all His purpose done.\",\"Christ the Lord is risen!\",\"sighs and sorrows past,\",\"death’s dark night is over,\",\"morning comes at last!\",\"Lord of life...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0377', 'verse', 3, 2, '[\"Resurrection morning!\",\"sinners’ bondage freed;\",\"Christ the Lord is risen –\",\"He is risen indeed!\",\"Jesus, Prince and Saviour,\",\"Lord of life who died,\",\"Christ the King of glory\",\"now is glorified!\",\"Lord of life...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0378', 378, 'Jesus shall take the highest honour', 'MP', 'en', 'Copyright 1988 Sovereign Lifestyle Music Ltd. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'Jesus shall take the highest honour,
Jesus shall take the highest praise,
let all earth join heaven in exalting
the name which is above all other names.
Let’s bow the knee in humble adoration,
for at His name every knee must bow;
let every tongue confess He is Christ, God’s only Son.
Sovereign Lord, we give You glory now,
for all honour and blessing and power
belongs to You, belongs to You.
All honour and blessing and power
belongs to You, belongs to You,
Lord Jesus Christ, Son of the living God.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0378', 'Chris Bowater');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0378', 'Chris Bowater');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0378', 'verse', 1, 0, '[\"Jesus shall take the highest honour,\",\"Jesus shall take the highest praise,\",\"let all earth join heaven in exalting\",\"the name which is above all other names.\",\"Let’s bow the knee in humble adoration,\",\"for at His name every knee must bow;\",\"let every tongue confess He is Christ, God’s only Son.\",\"Sovereign Lord, we give You glory now,\",\"for all honour and blessing and power\",\"belongs to You, belongs to You.\",\"All honour and blessing and power\",\"belongs to You, belongs to You,\",\"Lord Jesus Christ, Son of the living God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0379', 379, 'Jesus shall reign', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus shall reign where’er the sun
does His successive journeys run;
His kingdom stretch from shore to shore,
till moons shall rise and set no more.
To Him shall endless prayer be made,
and princes throng to crown His head;
His name, like sweet perfume, shall rise
with every morning sacrifice.
People and realms of every tongue
dwell on His love with sweetest song;
and infant voices shall proclaim
their early blessings on His name.
Blessings abound where’er He reigns;
the prisoner leaps to lose his chains,
the weary find eternal rest,
and all the sons of want are blest.
Let every creature rise and bring
the highest honours to our King;
angels descend with songs again,
and earth repeat the loud ‘Amen’.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0379', 'Isaac Watts');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0379', 'verse', 1, 0, '[\"Jesus shall reign where’er the sun\",\"does His successive journeys run;\",\"His kingdom stretch from shore to shore,\",\"till moons shall rise and set no more.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0379', 'verse', 2, 1, '[\"To Him shall endless prayer be made,\",\"and princes throng to crown His head;\",\"His name, like sweet perfume, shall rise\",\"with every morning sacrifice.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0379', 'verse', 3, 2, '[\"People and realms of every tongue\",\"dwell on His love with sweetest song;\",\"and infant voices shall proclaim\",\"their early blessings on His name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0379', 'verse', 4, 3, '[\"Blessings abound where’er He reigns;\",\"the prisoner leaps to lose his chains,\",\"the weary find eternal rest,\",\"and all the sons of want are blest.\"]');
