INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0381', 381, 'Jesus, stand among us', 'MP', 'en', 'Copyright 1988 Sovereign Lifestyle Music Ltd. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 0, 'Jesus, stand among us at the meeting of our lives,
be our sweet agreement at the meeting of our eyes;
O Jesus, we love You, so we gather here,
join our hearts in unity and take away our fear.
So to You we’re gathering out of each and every land,
Christ the love between us at the joining of our hands;
O Jesus, we love You, so we gather here,
join our hearts in unity and take away our fear.');
