INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0382', 382, 'Jesus, take me as I am', 'MP', 'en', '©  1978 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Jesus, take me as I am,
I can come no other way.
Take me deeper into You,
make my flesh life melt away.
Make me like a precious stone,
crystal clear and finely honed,
life of Jesus shining through,
giving glory back to You.');
