INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0384', 384, 'Jesus the Lord', 'MP', 'en', 'Trustees for Methodist Church Purposes. Used with permission.            Music arrangement: YISU NE KAHA (Urdu melody) harmonized and arranged by Francis Brotherton Westbrook (1903-75) by permission of Oxford University Press. All rights reserved.', '', 0, 0, 0, 1, 1, 'Jesus the Lord said: ‘I am the bread,
the bread of life for mankind am I,
