INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0385', 'verse', 2, 1, '[\"Jesus, the name to sinners dear,\",\"the name to sinners given;\",\"it scatters all their guilty fear,\",\"it turns their hell to heaven.\"]');
