INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0392', 'verse', 4, 3, '[\"My Saviour and my Lord,\",\"my Conqueror and my King,\",\"Thy sceptre and Thy sword,\",\"Thy reigning grace I sing:\",\"Thine is the power; behold, I sit\",\"in willing bonds beneath Thy feet.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0392', 'verse', 5, 4, '[\"Now let my soul arise,\",\"and tread the tempter down:\",\"my captain leads me forth\",\"to conquest and a crown:\",\"march on, nor fear to win the day,\",\"though death and hell obstruct the way.\"]');
