INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0393', 393, 'Joy to the world', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Joy to the world, the Lord has come!
let earth receive her King;
let every heart prepare Him room
and heaven and nature sing,
and heaven and nature sing,
and heaven, and heaven and nature sing!
Joy to the earth, the Saviour reigns!
your sweetest songs employ
while fields and streams and hills and plains
repeat the sounding joy,
repeat the sounding joy,
repeat, repeat the sounding joy.
He rules the world with truth and grace,
and makes the nations prove
the glories of His righteousness,
the wonders of His love,
the wonders of His love,
the wonders, wonders of His love.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0393', 'Isaac Watts');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0393', 'George Frideric Handel');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0393', 'Lowell Mason');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0393', 'verse', 1, 0, '[\"Joy to the world, the Lord has come!\",\"let earth receive her King;\",\"let every heart prepare Him room\",\"and heaven and nature sing,\",\"and heaven and nature sing,\",\"and heaven, and heaven and nature sing!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0393', 'verse', 2, 1, '[\"Joy to the earth, the Saviour reigns!\",\"your sweetest songs employ\",\"while fields and streams and hills and plains\",\"repeat the sounding joy,\",\"repeat the sounding joy,\",\"repeat, repeat the sounding joy.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0393', 'verse', 3, 2, '[\"He rules the world with truth and grace,\",\"and makes the nations prove\",\"the glories of His righteousness,\",\"the wonders of His love,\",\"the wonders of His love,\",\"the wonders, wonders of His love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0394', 394, 'Jubilate Deo', 'MP', 'en', '©  1977 Thankyou Music/Adm. by Capitol CMG Publishing worldwide excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Jubilate, everybody,
serve the Lord in all your ways, and
come before His presence singing:
enter now His courts with praise.
For the Lord our God is gracious,
and His mercy everlasting.
Jubilate, jubilate,
jubilate Deo!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0394', 'Fred Dunn');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0394', 'Fred Dunn');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0394', 'verse', 1, 0, '[\"Jubilate, everybody,\",\"serve the Lord in all your ways, and\",\"come before His presence singing:\",\"enter now His courts with praise.\",\"For the Lord our God is gracious,\",\"and His mercy everlasting.\",\"Jubilate, jubilate,\",\"jubilate Deo!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0395', 395, 'Judge eternal', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Judge eternal, throned in splendour,
Lord of lords and King of kings,
with Your living fire of judgement
purge this realm of bitter things;
solace all its wide dominion
with the healing of Your wings.
Still the weary folk are pining
for the hour that brings release;
and the city’s crowded clangour
cries aloud for sin to cease;
and the homesteads and the woodlands
plead in silence for their peace.
Crown, O God, Your own endeavour;
cleave our darkness with Your sword;
feed the faithless and the hungry
with the richness of Your word;
cleanse the body of this nation
through the glory of the Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0395', 'Henry Scott Holland');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0395', 'verse', 1, 0, '[\"Judge eternal, throned in splendour,\",\"Lord of lords and King of kings,\",\"with Your living fire of judgement\",\"purge this realm of bitter things;\",\"solace all its wide dominion\",\"with the healing of Your wings.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0395', 'verse', 2, 1, '[\"Still the weary folk are pining\",\"for the hour that brings release;\",\"and the city’s crowded clangour\",\"cries aloud for sin to cease;\",\"and the homesteads and the woodlands\",\"plead in silence for their peace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0395', 'verse', 3, 2, '[\"Crown, O God, Your own endeavour;\",\"cleave our darkness with Your sword;\",\"feed the faithless and the hungry\",\"with the richness of Your word;\",\"cleanse the body of this nation\",\"through the glory of the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0397', 397, 'King of glory, King of peace', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'King of glory, King of peace,
I will love Thee;
and, that love may never cease,
I will move Thee.
Thou hast granted my request,
Thou hast heard me;
Thou didst note my working breast,
Thou hast spared me.
Wherefore with my utmost art
I will sing Thee,
and the cream of all my heart
I will bring Thee.
Though my sins against me cried,
Thou didst clear me;
and alone, when they replied,
Thou didst hear me.
Seven whole days, not one in seven,
I will praise Thee;
in my heart, though not in heaven,
I can raise Thee.
Small it is, in this poor sort
to enrol Thee:
e’en eternity’s too short
to extol Thee.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0397', 'George Herbert');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0397', 'Joseph David Jones');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0397', 'verse', 1, 0, '[\"King of glory, King of peace,\",\"I will love Thee;\",\"and, that love may never cease,\",\"I will move Thee.\",\"Thou hast granted my request,\",\"Thou hast heard me;\",\"Thou didst note my working breast,\",\"Thou hast spared me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0397', 'verse', 2, 1, '[\"Wherefore with my utmost art\",\"I will sing Thee,\",\"and the cream of all my heart\",\"I will bring Thee.\",\"Though my sins against me cried,\",\"Thou didst clear me;\",\"and alone, when they replied,\",\"Thou didst hear me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0397', 'verse', 3, 2, '[\"Seven whole days, not one in seven,\",\"I will praise Thee;\",\"in my heart, though not in heaven,\",\"I can raise Thee.\",\"Small it is, in this poor sort\",\"to enrol Thee:\",\"e’en eternity’s too short\",\"to extol Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0398', 398, 'King of kings', 'MP', 'en', '1980 Maranatha! Music/Universal Music Publishing/Print Licence UK Song Solutions Daybreak www.songsolutions.org', '', 0, 0, 0, 1, 1, 'King of kings and Lord of lords,
glory, hallelujah!
King of kings and Lord of lords,
glory, hallelujah!
Jesus, Prince of peace,
glory, hallelujah!
Jesus, Prince of peace,
glory, hallelujah!
(may be sung as a roundh’0.08c’)');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0398', 'Sophie Conty');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0398', 'Naomi Batya');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0398', 'chorus', 0, 0, '[\"King of kings and Lord of lords,\",\"glory, hallelujah!\",\"King of kings and Lord of lords,\",\"glory, hallelujah!\",\"Jesus, Prince of peace,\",\"glory, hallelujah!\",\"Jesus, Prince of peace,\",\"glory, hallelujah!\",\"(may be sung as a roundh’0.08c’)\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0399', 399, 'Lead, kindly Light', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Lead, kindly Light, amid the encircling gloom,
lead Thou me on;
the night is dark, and I am far from home;
lead Thou me on.
Keep Thou my feet; I do not ask to see
the distant scene; one step enough for me.
I was not ever thus, nor prayed that Thou
shouldst lead me on;
I loved to choose and see my path; but now
lead Thou me on.
I loved the garish day, and, spite of fears,
pride ruled my will: remember not past years.
So long Thy power has blest me, sure it still
will lead me on
o’er moor and fen, o’er crag and torrent, till
the night is gone;
and with the morn those angel faces smile
which I have loved long since, and lost awhile.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0399', 'John Henry Newman');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0399', 'Charles Henry Purday');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0399', 'verse', 1, 0, '[\"Lead, kindly Light, amid the encircling gloom,\",\"lead Thou me on;\",\"the night is dark, and I am far from home;\",\"lead Thou me on.\",\"Keep Thou my feet; I do not ask to see\",\"the distant scene; one step enough for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0399', 'verse', 2, 1, '[\"I was not ever thus, nor prayed that Thou\",\"shouldst lead me on;\",\"I loved to choose and see my path; but now\",\"lead Thou me on.\",\"I loved the garish day, and, spite of fears,\",\"pride ruled my will: remember not past years.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0399', 'verse', 3, 2, '[\"So long Thy power has blest me, sure it still\",\"will lead me on\",\"o’er moor and fen, o’er crag and torrent, till\",\"the night is gone;\",\"and with the morn those angel faces smile\",\"which I have loved long since, and lost awhile.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0400', 400, 'Lead us, heavenly Father', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Lead us, heavenly Father, lead us
o’er the world’s tempestuous sea;
guard us, guide us, keep us, feed us –
for we have no help but Thee,
yet possessing every blessing
if our God our Father be.
Saviour, breathe forgiveness o’er us:
all our weakness Thou dost know:
Thou didst tread this earth before us,
Thou didst feel its keenest woe;
lone and dreary, faint and weary,
through the desert Thou didst go.
Spirit of our God, descending,
fill our hearts with heavenly joy,
love with every passion blending,
pleasure that can never cloy:
thus provided, pardoned, guided,
nothing can our peace destroy.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0400', 'James Edmeston');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0400', 'Friedrich Filitz');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0400', 'verse', 1, 0, '[\"Lead us, heavenly Father, lead us\",\"o’er the world’s tempestuous sea;\",\"guard us, guide us, keep us, feed us –\",\"for we have no help but Thee,\",\"yet possessing every blessing\",\"if our God our Father be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0400', 'verse', 2, 1, '[\"Saviour, breathe forgiveness o’er us:\",\"all our weakness Thou dost know:\",\"Thou didst tread this earth before us,\",\"Thou didst feel its keenest woe;\",\"lone and dreary, faint and weary,\",\"through the desert Thou didst go.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0400', 'verse', 3, 2, '[\"Spirit of our God, descending,\",\"fill our hearts with heavenly joy,\",\"love with every passion blending,\",\"pleasure that can never cloy:\",\"thus provided, pardoned, guided,\",\"nothing can our peace destroy.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0401', 401, 'Let all that is within me', 'MP', 'en', '1963 Gospel Publishing House/Lorenz Publishing/Small Stone Media, BV Holland (Admin. by Song Solutions www.songsolutions.org)            Music arrangement: © 1974 Celebration / kingswaysongs.com. tym@kingsway.co.uk. For Europe and Commonwealth (excl. Canada, Australasia and Africa). Used by permission.', '', 0, 0, 0, 1, 0, 'Let all that is within me cry, ‘holy’;
let all that is within me cry, ‘holy’;
holy, holy, holy is the Lamb that was slain.
Let all that is within me cry, ‘worthy’;
let all that is within me cry, ‘worthy’;
worthy, worthy, worthy is the Lamb that was slain.
Let all that is within me cry, ‘Jesus’;
let all that is within me cry, ‘Jesus’;
Jesus, Jesus, Jesus is the Lamb that was slain.
Let all that is within me cry, ‘glory’;
let all that is within me cry, ‘glory’;
glory, glory, glory to the Lamb that was slain.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0401', 'Melvin Harrell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0401', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0401', 'Betty Pulkingham');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0401', 'verse', 1, 0, '[\"Let all that is within me cry, ‘holy’;\",\"let all that is within me cry, ‘holy’;\",\"holy, holy, holy is the Lamb that was slain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0401', 'verse', 2, 1, '[\"Let all that is within me cry, ‘worthy’;\",\"let all that is within me cry, ‘worthy’;\",\"worthy, worthy, worthy is the Lamb that was slain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0401', 'verse', 3, 2, '[\"Let all that is within me cry, ‘Jesus’;\",\"let all that is within me cry, ‘Jesus’;\",\"Jesus, Jesus, Jesus is the Lamb that was slain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0401', 'verse', 4, 3, '[\"Let all that is within me cry, ‘glory’;\",\"let all that is within me cry, ‘glory’;\",\"glory, glory, glory to the Lamb that was slain.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0402', 402, 'You’re alive', 'MP', 'en', '©  1983 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Led like a lamb to the slaughter,
in silence and shame,
there on Your back You carried a world
of violence and pain;
Bleeding, dying, bleeding, dying.
You’re alive,
You’re alive,
You have risen!
Alleluia!
And the power
and the glory
is given,
Alleluia!
Jesus, to You.
At break of dawn, poor Mary,
still weeping she came,
when through her grief she heard Your voice,
now speaking her name.
Mary! Master! Mary! Master!
You’re alive...
At the right hand of the Father,
now seated on high,
You have begun Your eternal reign
of justice and joy.
Glory, glory, glory, glory.
You’re alive...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0402', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0402', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0402', 'verse', 1, 0, '[\"Led like a lamb to the slaughter,\",\"in silence and shame,\",\"there on Your back You carried a world\",\"of violence and pain;\",\"Bleeding, dying, bleeding, dying.\",\"You’re alive,\",\"You’re alive,\",\"You have risen!\",\"Alleluia!\",\"And the power\",\"and the glory\",\"is given,\",\"Alleluia!\",\"Jesus, to You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0402', 'verse', 2, 1, '[\"At break of dawn, poor Mary,\",\"still weeping she came,\",\"when through her grief she heard Your voice,\",\"now speaking her name.\",\"Mary! Master! Mary! Master!\",\"You’re alive...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0402', 'verse', 3, 2, '[\"At the right hand of the Father,\",\"now seated on high,\",\"You have begun Your eternal reign\",\"of justice and joy.\",\"Glory, glory, glory, glory.\",\"You’re alive...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0403', 403, 'Let all the earth hear His voice', 'MP', 'en', '©  1985 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Let all the earth hear His voice,
let the people rejoice
at the sound of His name;
let all the valleys and hills burst with joy,
and the trees of the field
clap their hands.
Justice and love He will bring to the world,
His kingdom will never fail;
held like a two-edgèd sword in our hand,
His word and truth shall prevail, shall prevail!
Let all the earth hear His voice,
let the prisoners rejoice –
He is coming to save.
Satan’s dark strongholds crash down
as with prayer we surround,
as the cross we proclaim.
Justice and love...
Let all the earth hear His song;
sing it loud, sing it strong –
it’s the song of His praise.
Silent no more, we cry out –
let the world hear the shout:
in the earth the Lord reigns.
Justice and love...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0403', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0403', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0403', 'verse', 1, 0, '[\"Let all the earth hear His voice,\",\"let the people rejoice\",\"at the sound of His name;\",\"let all the valleys and hills burst with joy,\",\"and the trees of the field\",\"clap their hands.\",\"Justice and love He will bring to the world,\",\"His kingdom will never fail;\",\"held like a two-edgèd sword in our hand,\",\"His word and truth shall prevail, shall prevail!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0403', 'verse', 2, 1, '[\"Let all the earth hear His voice,\",\"let the prisoners rejoice –\",\"He is coming to save.\",\"Satan’s dark strongholds crash down\",\"as with prayer we surround,\",\"as the cross we proclaim.\",\"Justice and love...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0403', 'verse', 3, 2, '[\"Let all the earth hear His song;\",\"sing it loud, sing it strong –\",\"it’s the song of His praise.\",\"Silent no more, we cry out –\",\"let the world hear the shout:\",\"in the earth the Lord reigns.\",\"Justice and love...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0404', 404, 'Let all the world', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Let all the world in every corner sing,
‘My God and King!’
The heavens are not too high;
His praise may thither fly:
the earth is not too low;
His praises there may grow.
Let all the world in every corner sing,
‘My God and King!’
Let all the world in every corner sing,
‘My God and King!’
The Church with psalms must shout,
no door can keep them out:
but, above all, the heart
must bear the longest part.
Let all the world in every corner sing,
‘My God and King!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0404', 'George Herbert');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0404', 'Basil Harwood');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0404', 'verse', 1, 0, '[\"Let all the world in every corner sing,\",\"‘My God and King!’\",\"The heavens are not too high;\",\"His praise may thither fly:\",\"the earth is not too low;\",\"His praises there may grow.\",\"Let all the world in every corner sing,\",\"‘My God and King!’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0404', 'verse', 2, 1, '[\"Let all the world in every corner sing,\",\"‘My God and King!’\",\"The Church with psalms must shout,\",\"no door can keep them out:\",\"but, above all, the heart\",\"must bear the longest part.\",\"Let all the world in every corner sing,\",\"‘My God and King!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0405', 405, 'Let God arise', 'MP', 'en', '©  1984 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Let God arise,
and let His enemies be scattered,
and let those who hate Him
flee before Him;
let God arise,
and let His enemies be scattered,
and let those who hate Him
flee away.');
