INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0406', 406, 'Let it be to me', 'MP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Let it be to me according to Your word;
let it be to me according to Your word.
I am Your servant, no rights shall I demand.
Let it be to me, let it be to me,
let it be to me according to Your word.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0406', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0406', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0406', 'Christopher Norton');
