INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0407', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0407', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0407', 'verse', 1, 0, '[\"Let Me have My way among you,\",\"do not strive, do not strive;\",\"let Me have My way among you,\",\"do not strive, do not strive;\",\"for Mine is the power and the glory\",\"for ever and ever the same.\",\"Let Me have My way among you,\",\"do not strive, do not strive.\"]');
