INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0407', 'verse', 3, 2, '[\"Let My peace rule within your hearts,\",\"do not strive, do not strive;\",\"let My peace rule within your hearts,\",\"do not strive, do not strive;\",\"for Mine is the power and the glory\",\"for ever and ever the same.\",\"Let My peace rule within your hearts,\",\"do not strive, do not strive.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0407', 'verse', 4, 3, '[\"We’ll let Your peace rule within our hearts,\",\"we’ll not strive, we’ll not strive;\",\"we’ll let Your peace rule within our hearts,\",\"we’ll not strive, we’ll not strive;\",\"for Yours is the power and the glory\",\"for ever and ever the same.\",\"We’ll let You have Your way among us,\",\"we’ll not strive, we’ll not strive.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0408', 408, 'Let our praise to You be as incense', 'MP', 'en', '1974 Scripture in Song/Maranatha Music/ Universal Music Publishing/Print Licence UK Song Solutions Daybreak www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Let our praise to You be as incense,
let our praise to You be as pillars of Your throne;
let our praise to You be as incense,
as we come before You and worship You alone.
As we see You in Your splendour,
as we gaze upon Your majesty,
as we join the hosts of angels,
and proclaim together Your holiness.
Let our praise to You...
Holy, holy, holy;
holy is the Lord!
Holy, holy, holy;
holy is the Lord!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0408', 'Brent Chambers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0408', 'Brent Chambers');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0408', 'verse', 1, 0, '[\"Let our praise to You be as incense,\",\"let our praise to You be as pillars of Your throne;\",\"let our praise to You be as incense,\",\"as we come before You and worship You alone.\",\"As we see You in Your splendour,\",\"as we gaze upon Your majesty,\",\"as we join the hosts of angels,\",\"and proclaim together Your holiness.\",\"Let our praise to You...\",\"Holy, holy, holy;\",\"holy is the Lord!\",\"Holy, holy, holy;\",\"holy is the Lord!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0409', 409, 'Let saints on earth', 'MP', 'en', 'in this version The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'Let saints on earth together sing
with those whose work is done;
for all the servants of our King
in earth and heaven, are one.
One family, we live in Him,
one Church above, beneath,
though now divided by the stream,
the narrow stream of death.
One army of the living God,
to His command we bow;
part of His host have crossed the flood
and part are crossing now.
But all unite in Christ their head,
and love to sing His praise:
Lord of the living and the dead,
direct our earthly ways!
So shall we join our friends above
who have obtained the prize;
and on the eagle wings of love
to joys celestial rise.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0409', 'Charles Wesley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0409', 'verse', 1, 0, '[\"Let saints on earth together sing\",\"with those whose work is done;\",\"for all the servants of our King\",\"in earth and heaven, are one.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0409', 'verse', 2, 1, '[\"One family, we live in Him,\",\"one Church above, beneath,\",\"though now divided by the stream,\",\"the narrow stream of death.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0409', 'verse', 3, 2, '[\"One army of the living God,\",\"to His command we bow;\",\"part of His host have crossed the flood\",\"and part are crossing now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0409', 'verse', 4, 3, '[\"But all unite in Christ their head,\",\"and love to sing His praise:\",\"Lord of the living and the dead,\",\"direct our earthly ways!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0409', 'verse', 5, 4, '[\"So shall we join our friends above\",\"who have obtained the prize;\",\"and on the eagle wings of love\",\"to joys celestial rise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0410', 410, 'Let the beauty of Jesus', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Let the beauty of Jesus be seen in me,
all His wondrous compassion and purity:
O Thou Spirit divine,
all my nature refine,
till the beauty of Jesus be seen in me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0410', 'Albert Orsborn');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0410', 'Tom Jones');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0410', 'verse', 1, 0, '[\"Let the beauty of Jesus be seen in me,\",\"all His wondrous compassion and purity:\",\"O Thou Spirit divine,\",\"all my nature refine,\",\"till the beauty of Jesus be seen in me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0411', 411, 'Let there be love', 'MP', 'en', '©  1979 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Let there be love shared among us,
let there be love in our eyes;
may now Your love sweep this nation,
cause us, O Lord, to arise:
give us a fresh understanding
of brotherly love that is real;
let there be love shared among us,
let there be love.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0411', 'Dave Bilbrough');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0411', 'Dave Bilbrough');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0411', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0411', 'verse', 1, 0, '[\"Let there be love shared among us,\",\"let there be love in our eyes;\",\"may now Your love sweep this nation,\",\"cause us, O Lord, to arise:\",\"give us a fresh understanding\",\"of brotherly love that is real;\",\"let there be love shared among us,\",\"let there be love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0412', 412, 'Let’s just praise the Lord', 'MP', 'en', '© 1972 William J Gaither Inc (Adm. in UK  by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Let’s just praise the Lord!
Praise the Lord!
Let’s just lift our hearts* to heaven
and praise the Lord;
Let’s just praise the Lord!
Praise the Lord!
Let’s just lift our hearts* to heaven
and praise the Lord!
* Alternative lyrics, ‘voices’, ‘hands’.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0412', 'Gloria Gaither');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0412', 'William J Gaither');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0412', 'William J Gaither');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0412', 'verse', 1, 0, '[\"Let’s just praise the Lord!\",\"Praise the Lord!\",\"Let’s just lift our hearts* to heaven\",\"and praise the Lord;\",\"Let’s just praise the Lord!\",\"Praise the Lord!\",\"Let’s just lift our hearts* to heaven\",\"and praise the Lord!\",\"* Alternative lyrics, ‘voices’, ‘hands’.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0413', 413, 'Let us acknowledge the Lord', 'MP', 'en', '1986 Andy Silver', '', 0, 0, 0, 1, 1, 'Let us acknowledge the Lord,
let us press on to acknowledge Him,
let us acknowledge the Lord.
Let us acknowledge Him
as surely as the sun rises;
He will appear, He will come to us
like the winter rains,
like the spring rains
that water the earth.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0413', 'Andy Silver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0413', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0413', 'verse', 1, 0, '[\"Let us acknowledge the Lord,\",\"let us press on to acknowledge Him,\",\"let us acknowledge the Lord.\",\"Let us acknowledge Him\",\"as surely as the sun rises;\",\"He will appear, He will come to us\",\"like the winter rains,\",\"like the spring rains\",\"that water the earth.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0414', 414, 'Let us break bread together', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'TRADITIONAL VERSION
Let us break bread together on our knees,
let us break bread together on our knees:
When I fall on my knees,
with my face to the rising sun,
O Lord, have mercy on me!
Let us drink wine together on our knees,
let us drink wine together on our knees:
When I fall...
Let us praise God together on our knees,
let us praise God together on our knees:
When I fall...
ALTERNATIVE VERSION
Let us praise God together, let us praise;
let us praise God together all our days:
He is faithful in all His ways,
He is worthy of all our praise,
His name be exalted on high!
Let us seek God together, let us pray;
let us seek His forgiveness as we pray:
He will cleanse us from all sin,
He will help us the fight to win,
His name be exalted on high!
Let us serve God together, Him obey;
let our lives show His goodness through each day:
Christ the Lord is the world’s true light –
let us serve Him with all our might,
His name be exalted on high!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0414', 'James E Seddon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0414', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0414', 'chorus', 0, 0, '[\"TRADITIONAL VERSION\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0414', 'verse', 1, 1, '[\"Let us break bread together on our knees,\",\"let us break bread together on our knees:\",\"When I fall on my knees,\",\"with my face to the rising sun,\",\"O Lord, have mercy on me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0414', 'verse', 2, 2, '[\"Let us drink wine together on our knees,\",\"let us drink wine together on our knees:\",\"When I fall...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0414', 'verse', 3, 3, '[\"Let us praise God together on our knees,\",\"let us praise God together on our knees:\",\"When I fall...\",\"ALTERNATIVE VERSION\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0414', 'verse', 1, 4, '[\"Let us praise God together, let us praise;\",\"let us praise God together all our days:\",\"He is faithful in all His ways,\",\"He is worthy of all our praise,\",\"His name be exalted on high!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0414', 'verse', 2, 5, '[\"Let us seek God together, let us pray;\",\"let us seek His forgiveness as we pray:\",\"He will cleanse us from all sin,\",\"He will help us the fight to win,\",\"His name be exalted on high!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0414', 'verse', 3, 6, '[\"Let us serve God together, Him obey;\",\"let our lives show His goodness through each day:\",\"Christ the Lord is the world’s true light –\",\"let us serve Him with all our might,\",\"His name be exalted on high!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0415', 415, 'Let us with a gladsome mind', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Let us with a gladsome mind
praise the Lord for He is kind;
For His mercies shall endure,
ever faithful, ever sure.
He, with all-commanding might,
filled the new-made world with light:
For His mercies...
All things living He doth feed,
His full hand supplies their need:
For His mercies...
He His chosen race did bless
in the wasteland wilderness:
For His mercies...
He hath, with a piteous eye,
looked upon our misery:
For His mercies...
Let us then with gladsome mind,
praise the Lord for He is kind!
For His mercies...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0415', 'John Milton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0415', 'John Antes');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0415', 'John Wilkes');
