INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0415', 'verse', 2, 1, '[\"He, with all-commanding might,\",\"filled the new-made world with light:\",\"For His mercies...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0415', 'verse', 3, 2, '[\"All things living He doth feed,\",\"His full hand supplies their need:\",\"For His mercies...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0415', 'verse', 4, 3, '[\"He His chosen race did bless\",\"in the wasteland wilderness:\",\"For His mercies...\"]');
