INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0415', 'verse', 6, 5, '[\"Let us then with gladsome mind,\",\"praise the Lord for He is kind!\",\"For His mercies...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0416', 416, 'Lift Jesus higher', 'MP', 'en', 'control                        arrangement: ? 1986 Phil Burt', '', 0, 0, 0, 1, 1, 'Lift Jesus higher, lift Jesus higher,
lift Him up for the world to see.
He said, ‘If I be lifted up from the earth
I will draw all men unto me.’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0416', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0416', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0416', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0416', 'verse', 1, 0, '[\"Lift Jesus higher, lift Jesus higher,\",\"lift Him up for the world to see.\",\"He said, ‘If I be lifted up from the earth\",\"I will draw all men unto me.’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0417', 417, 'Lift high the cross', 'MP', 'en', 'Hymns Ancient & Modern Ltd            ? in this version The Jubilate Group, 4 Thorne Park Road, Torquay TQ2 6RX. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'Lift high the cross,
the love of Christ proclaim
till all the world
adores His sacred name!
Come, Christians, follow where the captain trod,
the King victorious, Christ, the Son of God:
Lift high the cross...
Each new-born soldier of the crucified
bears on his brow the seal of Him who died:
Lift high the cross...
This is the sign that Satan’s armies fear
and angels veil their faces to revere:
Lift high the cross...
Saved by the cross on which their Lord was slain,
see Adam’s children their lost home regain:
Lift high the cross...
From north and south, from east and west they raise
in growing unison their songs of praise:
Lift high the cross...
Let every race and every language tell
of Him who saves our souls from death and hell!
Lift high the cross...
O Lord, once lifted on the tree of pain,
draw all the world to seek You once again:
Lift high the cross...
Set up Your throne, that earth’s despair may cease
beneath the shadow of its healing peace:
Lift high the cross...');
