INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0417', 'verse', 1, 1, '[\"Come, Christians, follow where the captain trod,\",\"the King victorious, Christ, the Son of God:\",\"Lift high the cross...\"]');
