INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0429', 'chorus', 0, 0, '[\"Lord, have mercy, Lord, have mercy,\",\"Lord, have mercy on Your people.\",\"Lord, have mercy, Lord, have mercy,\",\"Lord, have mercy on Your people.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0429', 'verse', 1, 1, '[\"Give me the heart of stone within you,\",\"and I’ll give you a heart of flesh.\",\"Clean water I will use to cleanse all your wounds,\",\"My Spirit I give to you.\",\"Lord, have mercy...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0429', 'verse', 2, 2, '[\"You’ll find Me near the broken-hearted,\",\"those crushed in spirit I will save.\",\"So turn to Me for My pardon is great,\",\"My word will heal all your wounds.\",\"Lord, have mercy...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0430', 430, 'Lord, have mercy on us', 'MP', 'en', '©  1986 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Lord, have mercy on us,
come and heal our land;
cleanse with Your fire,
heal with Your touch:
humbly we bow
and call upon You now,
O Lord, have mercy on us,
O Lord, have mercy on us.
Lord, have mercy on us...
O Lord, have mercy on us.');
