INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0430', 'verse', 1, 0, '[\"Lord, have mercy on us,\",\"come and heal our land;\",\"cleanse with Your fire,\",\"heal with Your touch:\",\"humbly we bow\",\"and call upon You now,\",\"O Lord, have mercy on us,\",\"O Lord, have mercy on us.\",\"Lord, have mercy on us...\",\"O Lord, have mercy on us.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0431', 431, 'Lord, enthroned in heavenly splendour', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Lord, enthroned in heavenly splendour,
glorious first-born from the dead,
You alone our strong defender,
lifting up Your people’s head.
Alleluia, alleluia,
Jesus, true and living bread!
Prince of life, for us now living,
by Your body souls are healed;
Prince of peace, Your pardon giving,
by Your blood our peace is sealed.
Alleluia, alleluia,
Word of God in flesh revealed.
Paschal Lamb! Your offering, finished
once for all when You were slain,
in its fulness undiminished
shall for evermore remain,
Alleluia, alleluia,
cleansing souls from every stain.
Great High Priest of our profession,
through the veil You entered in,
by Your mighty intercession
grace and mercy there to win,
Alleluia, alleluia,
only sacrifice for sin.
Life-imparting heavenly manna,
stricken rock with streaming side,
heaven and earth with loud hosanna
worship You, the Lamb who died,
Alleluia, alleluia,
risen, ascended, glorified!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0431', 'George Hugh Bourne');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0431', 'George Clement Martin');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0431', 'verse', 1, 0, '[\"Lord, enthroned in heavenly splendour,\",\"glorious first-born from the dead,\",\"You alone our strong defender,\",\"lifting up Your people’s head.\",\"Alleluia, alleluia,\",\"Jesus, true and living bread!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0431', 'verse', 2, 1, '[\"Prince of life, for us now living,\",\"by Your body souls are healed;\",\"Prince of peace, Your pardon giving,\",\"by Your blood our peace is sealed.\",\"Alleluia, alleluia,\",\"Word of God in flesh revealed.\"]');
