INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0431', 'verse', 5, 4, '[\"Life-imparting heavenly manna,\",\"stricken rock with streaming side,\",\"heaven and earth with loud hosanna\",\"worship You, the Lamb who died,\",\"Alleluia, alleluia,\",\"risen, ascended, glorified!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0432', 432, 'Lord, I love You', 'MP', 'en', '1990 Mercy Vineyard Publishing/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Lord, I love You,
You alone did hear my cry;
only You can mend
this broken heart of mine.
Yes, I love You,
and there is no doubt,
Lord, You’ve touched me');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0432', 'Eddie Espinosa');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0432', 'Eddie Espinosa');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0432', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0432', 'verse', 1, 0, '[\"Lord, I love You,\",\"You alone did hear my cry;\",\"only You can mend\",\"this broken heart of mine.\",\"Yes, I love You,\",\"and there is no doubt,\",\"Lord, You’ve touched me\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0434', 434, 'Lord, it is eventide', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Lord, it is eventide: the light of day is waning;
far o’er the golden land earth’s voices faint and fall;
lowly we pray to You for strength and love sustaining,
lowly we ask of You Your peace upon us all.
O grant unto our souls
light that grows not pale with day’s decrease,
love that never can fail till life shall cease;
joy no trial can mar,
hope that shines afar,
faith serene as a star, and Christ’s own peace.
Lord, it is eventide: we turn to You for healing,
like those of Galilee who came at close of day;
speak to our waiting souls, their hidden needs revealing;
touch us with hands divine that take our sin away.
O grant unto our souls
light that grows...
Saviour, You know of every trial and temptation,
know of the wilfulness and waywardness of youth,
help us to hold to You, our strength and our salvation,
help us to find in You the one eternal truth.
O grant unto our souls
light that grows...
Lord, it is eventide: our hearts await Your giving,
wait for that peace divine that none can take away,
peace that shall lift our souls to loftier heights of living,
till we abide with You in everlasting day.
O grant unto our souls
light that grows...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0434', 'Colin Sterne');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0434', 'Henry Ernest Nichol');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0434', 'verse', 1, 0, '[\"Lord, it is eventide: the light of day is waning;\",\"far o’er the golden land earth’s voices faint and fall;\",\"lowly we pray to You for strength and love sustaining,\",\"lowly we ask of You Your peace upon us all.\",\"O grant unto our souls\",\"light that grows not pale with day’s decrease,\",\"love that never can fail till life shall cease;\",\"joy no trial can mar,\",\"hope that shines afar,\",\"faith serene as a star, and Christ’s own peace.\"]');
