INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0434', 'verse', 3, 2, '[\"Saviour, You know of every trial and temptation,\",\"know of the wilfulness and waywardness of youth,\",\"help us to hold to You, our strength and our salvation,\",\"help us to find in You the one eternal truth.\",\"O grant unto our souls\",\"light that grows...\"]');
