INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0436', 436, 'Lord, make me a mountain', 'MP', 'en', 'Song Solutions Daybreak www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Lord, make me a mountain standing tall for You,
strong and free and holy in everything I do.
Lord, make me a river of water pure and sweet,
Lord, make me the servant of everyone I meet.
Lord, make me a candle shining with Your light,
steadfastly unflickering, standing for the right.
Lord, make me a fire burning strong for You,
Lord, make me be humble in everything I do.
Lord, make me a mountain, strong and tall for You,
Lord, make me a fountain of water clear and new,
Lord, make me a shepherd that I may feed Your sheep,
Lord, make me the servant of everyone I meet.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0436', 'Paul Field');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0436', 'Paul Field');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0436', 'verse', 1, 0, '[\"Lord, make me a mountain standing tall for You,\",\"strong and free and holy in everything I do.\",\"Lord, make me a river of water pure and sweet,\",\"Lord, make me the servant of everyone I meet.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0436', 'verse', 2, 1, '[\"Lord, make me a candle shining with Your light,\",\"steadfastly unflickering, standing for the right.\",\"Lord, make me a fire burning strong for You,\",\"Lord, make me be humble in everything I do.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0436', 'verse', 3, 2, '[\"Lord, make me a mountain, strong and tall for You,\",\"Lord, make me a fountain of water clear and new,\",\"Lord, make me a shepherd that I may feed Your sheep,\",\"Lord, make me the servant of everyone I meet.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0437', 437, 'Lord, make me an instrument', 'MP', 'en', '1977 Zion Song, administered by Copycare PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.', '', 0, 0, 0, 1, 1, 'Lord, make me an instrument,
an instrument of worship;
I lift up my hands in Your name.
Lord, make me an instrument,
an instrument of worship;
I lift up my hands in Your name.
I’ll sing You a love-song,
a love-song of worship;
I lift up my hands in Your name.
I’ll sing You a love-song,
a love-song to Jesus;
I lift up my hands in Your name.
Lord, make us a symphony,
a symphony of worship;
we lift up our hands in Your name.
Lord, make us a symphony,
a symphony of worship;
we lift up our hands in Your name.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0437', 'Robert Bicknell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0437', 'Robert Bicknell');
