INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0437', 'verse', 2, 1, '[\"I’ll sing You a love-song,\",\"a love-song of worship;\",\"I lift up my hands in Your name.\",\"I’ll sing You a love-song,\",\"a love-song to Jesus;\",\"I lift up my hands in Your name.\"]');
