INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0438', 438, 'Lord, may we see', 'MP', 'en', 'Chris Porteous/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION            Music arrangement: © 1983 Roland Fudge', '', 0, 0, 0, 1, 1, 'Lord, may we see Your hands and side,
touch You and feel Your presence near;
Lord, could our eyes behold those clouds
and watch You rising disappear.
Help us to pray for Your return,
to watch until You come to reign;
and be Your witnesses through the world,
to speak and glorify Your name.
Lord, unto You we lift our eyes,
help us to live as You desire.
Bring down upon us power to win
through tongues of Holy Spirit, fire.
Lord, breathe upon us to receive
the grace and love Your Spirit gives;
and may we know You with us now
because in us Your Spirit lives.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0438', 'Christopher Porteous');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0438', 'Charles Hubert Hastings Parry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0438', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0438', 'verse', 1, 0, '[\"Lord, may we see Your hands and side,\",\"touch You and feel Your presence near;\",\"Lord, could our eyes behold those clouds\",\"and watch You rising disappear.\",\"Help us to pray for Your return,\",\"to watch until You come to reign;\",\"and be Your witnesses through the world,\",\"to speak and glorify Your name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0438', 'verse', 2, 1, '[\"Lord, unto You we lift our eyes,\",\"help us to live as You desire.\",\"Bring down upon us power to win\",\"through tongues of Holy Spirit, fire.\",\"Lord, breathe upon us to receive\",\"the grace and love Your Spirit gives;\",\"and may we know You with us now\",\"because in us Your Spirit lives.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0440', 440, 'Lord of creation', 'MP', 'en', 'Mrs J Tyrrell            ©  John Barnard/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'Lord of creation, to You be all praise!
Most mighty Your working, most wondrous Your ways!
Your glory and might are beyond us to tell,
and yet in the heart of the humble You dwell.
Lord of all power, I give You my will,
in joyful obedience Your tasks to fulfil;
Your bondage is freedom, Your service is song,
and, held in Your keeping, my weakness is strong.
Lord of all wisdom, I give You my mind,
rich truth that surpasses man’s knowledge to find;
what eye has not seen and what ear has not heard
is taught by Your Spirit and shines from Your word.
Lord of all bounty, I give You my heart;
I praise and adore You for all You impart,
Your love to inspire me, Your counsel to guide,
Your presence to cheer me, whatever betide.
Lord of all being, I give You my all;
for if I disown You I stumble and fall;
but, sworn in glad service Your word to obey,
I walk in Your freedom to the end of the way.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0440', 'Jack C Winslow');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0440', 'John Barnard');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0440', 'verse', 1, 0, '[\"Lord of creation, to You be all praise!\",\"Most mighty Your working, most wondrous Your ways!\",\"Your glory and might are beyond us to tell,\",\"and yet in the heart of the humble You dwell.\"]');
