INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0445', 445, 'Shine, Jesus, shine', 'MP', 'en', '1987 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Lord, the light of Your love is shining,
in the midst of the darkness, shining:
Jesus, Light of the world, shine upon us;
set us free by the truth You now bring us –
shine on me, shine on me.
Shine, Jesus, shine,
fill this land with the Father’s glory;
blaze, Spirit, blaze,
set our hearts on fire.
Flow, river, flow,
flood the nations with grace and mercy;
send forth Your word, Lord,
and let there be light!
Lord, I come to Your awesome presence,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0445', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0445', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0445', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0445', 'verse', 1, 0, '[\"Lord, the light of Your love is shining,\",\"in the midst of the darkness, shining:\",\"Jesus, Light of the world, shine upon us;\",\"set us free by the truth You now bring us –\",\"shine on me, shine on me.\",\"Shine, Jesus, shine,\",\"fill this land with the Father’s glory;\",\"blaze, Spirit, blaze,\",\"set our hearts on fire.\",\"Flow, river, flow,\",\"flood the nations with grace and mercy;\",\"send forth Your word, Lord,\",\"and let there be light!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0445', 'verse', 2, 1, '[\"Lord, I come to Your awesome presence,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0446', 446, 'Lord, Thy word abideth', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Lord, Thy word abideth,
and our footsteps guideth;
who its truth believeth
light and joy receiveth.
Who can tell the pleasure,
who recount the treasure,
by Thy word imparted
to the simple-hearted?
When the storms are o’er us,
and dark clouds before us,
then its light directeth,
and our way protecteth.
When our foes are near us,
then Thy word doth cheer us,
word of consolation,
message of salvation.
Word of mercy, giving
succour to the living;
word of life, supplying
comfort to the dying.
O that we discerning
its most holy learning,
Lord, may love and fear Thee,
evermore be near Thee!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0446', 'Henry Williams Baker');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0446', 'William Henry Monk');
