INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0446', 'verse', 2, 1, '[\"Who can tell the pleasure,\",\"who recount the treasure,\",\"by Thy word imparted\",\"to the simple-hearted?\"]');
