INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0447', 447, 'Lord, You are more precious', 'MP', 'en', '© 1982 Integrity\'s Hosanna! Music / adm worldwide by Capitol CMG Publishing excl UK admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 1, 'Lord, You are more precious than silver,
Lord, You are more costly than gold;
Lord, You are more beautiful than diamonds,
and nothing I desire compares with You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0447', 'Lynn DeShazo');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0447', 'Lynn DeShazo');
