INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0447', 'verse', 1, 0, '[\"Lord, You are more precious than silver,\",\"Lord, You are more costly than gold;\",\"Lord, You are more beautiful than diamonds,\",\"and nothing I desire compares with You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0448', 448, 'Heal our nation', 'MP', 'en', '©  1986 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Lord, we long for You to move in power.
There’s a hunger deep within our hearts,
to see healing in our nation.
Send Your Spirit to revive us:
Heal our nation!
Heal our nation!
Heal our nation!
Pour out Your Spirit on this land!
Lord, we hear Your Spirit coming closer,
a mighty wave to break upon our land,
bringing justice, and forgiveness,
God, we cry to You, ‘Revive us’:
Heal our nation...');
