INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0448', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0448', 'verse', 1, 0, '[\"Lord, we long for You to move in power.\",\"There’s a hunger deep within our hearts,\",\"to see healing in our nation.\",\"Send Your Spirit to revive us:\",\"Heal our nation!\",\"Heal our nation!\",\"Heal our nation!\",\"Pour out Your Spirit on this land!\"]');
