INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0457', 'verse', 2, 1, '[\"He comes the broken hearts to heal,\",\"the prisoners to free;\",\"the deaf shall hear, the lame shall dance,\",\"the blind shall see.\",\"Make way...\"]');
