INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0458', 458, 'Man of Sorrows', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Man of Sorrows! what a name
for the Son of God, who came
ruined sinners to reclaim!
Hallelujah! what a Saviour!
Bearing shame and scoffing rude,
in my place condemned He stood;
sealed my pardon with His blood;
hallelujah! what a Saviour!
Guilty, vile and helpless we;
spotless Lamb of God was He:
full atonement – can it be?
hallelujah! what a Saviour!
Lifted up was He to die,
‘It is finished!’ was His cry;
now in heaven exalted high;
hallelujah! what a Saviour!
When He comes, our glorious King,
all His ransomed home to bring,
then anew this song we’ll sing:
‘Hallelujah! what a Saviour!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0458', 'Philip Paul Bliss');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0458', 'Philip Paul Bliss');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0458', 'verse', 1, 0, '[\"Man of Sorrows! what a name\",\"for the Son of God, who came\",\"ruined sinners to reclaim!\",\"Hallelujah! what a Saviour!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0458', 'verse', 2, 1, '[\"Bearing shame and scoffing rude,\",\"in my place condemned He stood;\",\"sealed my pardon with His blood;\",\"hallelujah! what a Saviour!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0458', 'verse', 3, 2, '[\"Guilty, vile and helpless we;\",\"spotless Lamb of God was He:\",\"full atonement – can it be?\",\"hallelujah! what a Saviour!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0458', 'verse', 4, 3, '[\"Lifted up was He to die,\",\"‘It is finished!’ was His cry;\",\"now in heaven exalted high;\",\"hallelujah! what a Saviour!\"]');
