INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0460', 460, 'Benediction', 'MP', 'en', '1982 Cliff Barrows', '', 0, 0, 0, 1, 1, 'May God’s blessing surround you each day,
as you trust Him and walk in His way.
May His presence within guard and keep you from sin,
go in peace, go in joy, go in love.');
