INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0461', 461, 'May our worship be acceptable', 'MP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'May our worship be acceptable
in Your sight, O Lord;
may our worship be acceptable
in Your sight, O Lord;
may the words of my mouth be pure,
and the meditation of my heart;
may our worship be acceptable
in Your sight, O Lord.');
