INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0463', 463, 'May the mind of Christ my Saviour', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'May the mind of Christ my Saviour
live in me from day to day,
by His love and power controlling
all I do and say.
May the word of God dwell richly
in my heart from hour to hour,
so that all may see I triumph
only through His power.
May the peace of God my Father
rule my life in everything,
that I may be calm to comfort
sick and sorrowing.
May the love of Jesus fill me,
as the waters fill the sea;
Him exalting, self abasing,
this is victory.
May I run the race before me,
strong and brave to face the foe,
looking only unto Jesus,
as I onward go.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0463', 'Kate Barclay Wilkinson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0463', 'Arthur Cyril Barham-Gould');
