INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0463', 'verse', 2, 1, '[\"May the word of God dwell richly\",\"in my heart from hour to hour,\",\"so that all may see I triumph\",\"only through His power.\"]');
