INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0472', 472, 'My heart overflows', 'MP', 'en', '© 1979 Authentic Publishing / Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'My heart overflows with a goodly theme,
I will address my verses to the King;
my heart overflows with praise to my God,
I’ll give Him the love of my heart.
For He is Lord of all the earth, He’s risen above,
He’s seated at God’s right hand;
and from Him and through Him and to Him are all things,
that His glory might fill the land.
My heart overflows...
For He has chosen Mount Zion as His resting-place,
He says, ‘Here will I dwell,
I will abundantly bless and satisfy,
and her saints will shout for joy.’
My heart overflows...
‘Lift up your eyes round about and see,
your heart shall thrill and rejoice,
for the abundance of the nations is coming to you,
I am glorifying My house.’
My heart overflows...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0472', 'Carolyn Govier');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0472', 'Carolyn Govier');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0472', 'chorus', 0, 0, '[\"My heart overflows with a goodly theme,\",\"I will address my verses to the King;\",\"my heart overflows with praise to my God,\",\"I’ll give Him the love of my heart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0472', 'verse', 1, 1, '[\"For He is Lord of all the earth, He’s risen above,\",\"He’s seated at God’s right hand;\",\"and from Him and through Him and to Him are all things,\",\"that His glory might fill the land.\",\"My heart overflows...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0472', 'verse', 2, 2, '[\"For He has chosen Mount Zion as His resting-place,\",\"He says, ‘Here will I dwell,\",\"I will abundantly bless and satisfy,\",\"and her saints will shout for joy.’\",\"My heart overflows...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0472', 'verse', 3, 3, '[\"‘Lift up your eyes round about and see,\",\"your heart shall thrill and rejoice,\",\"for the abundance of the nations is coming to you,\",\"I am glorifying My house.’\",\"My heart overflows...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0473', 473, 'My hope is built on nothing less', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'My hope is built on nothing less
than Jesus’ blood and righteousness;
no merit of my own I claim,
but wholly trust in Jesus’ name.
On Christ, the solid rock, I stand –
all other ground is sinking sand,
all other ground is sinking sand.
When weary in this earthly race,
I rest on His unchanging grace;
in every wild and stormy gale
my anchor holds and will not fail.
On Christ, the solid rock...
His vow, His covenant and blood
are my defence against the flood;
when earthly hopes are swept away
He will uphold me on that day.
On Christ, the solid rock...
When the last trumpet’s voice shall sound,
O may I then in Him be found!
clothed in His righteousness alone,
faultless to stand before His throne.
On Christ, the solid rock...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0473', 'Edward Mote');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0473', 'Henri Frederick Hemy');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0473', 'James George Walton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0473', 'verse', 1, 0, '[\"My hope is built on nothing less\",\"than Jesus’ blood and righteousness;\",\"no merit of my own I claim,\",\"but wholly trust in Jesus’ name.\",\"On Christ, the solid rock, I stand –\",\"all other ground is sinking sand,\",\"all other ground is sinking sand.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0473', 'verse', 2, 1, '[\"When weary in this earthly race,\",\"I rest on His unchanging grace;\",\"in every wild and stormy gale\",\"my anchor holds and will not fail.\",\"On Christ, the solid rock...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0473', 'verse', 3, 2, '[\"His vow, His covenant and blood\",\"are my defence against the flood;\",\"when earthly hopes are swept away\",\"He will uphold me on that day.\",\"On Christ, the solid rock...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0473', 'verse', 4, 3, '[\"When the last trumpet’s voice shall sound,\",\"O may I then in Him be found!\",\"clothed in His righteousness alone,\",\"faultless to stand before His throne.\",\"On Christ, the solid rock...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0474', 474, 'My life is Yours', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'My life is Yours, O Lord,
my life is Yours, O Lord;
so do as You will,
do what is pleasing to You,
for my life belongs to You.
Teach me the fear of the Lord,
let me see Your righteousness;
I will kneel before You
and worship Christ my King.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0474', 'Ruth Hooke');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0474', 'Ruth Hooke');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0474', 'verse', 1, 0, '[\"My life is Yours, O Lord,\",\"my life is Yours, O Lord;\",\"so do as You will,\",\"do what is pleasing to You,\",\"for my life belongs to You.\",\"Teach me the fear of the Lord,\",\"let me see Your righteousness;\",\"I will kneel before You\",\"and worship Christ my King.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0475', 475, 'My Lord, He is the fairest of the fair', 'MP', 'en', '©  1978 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'My Lord, He is the fairest of the fair,
He is the lily of the valley,
the bright and morning star;
His love is written deep within my heart,
He is the never-ending fountain
of everlasting life:
and He lives, He lives,
He lives, He lives in me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0475', 'Joan Parsons');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0475', 'Joan Parsons');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0475', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0475', 'verse', 1, 0, '[\"My Lord, He is the fairest of the fair,\",\"He is the lily of the valley,\",\"the bright and morning star;\",\"His love is written deep within my heart,\",\"He is the never-ending fountain\",\"of everlasting life:\",\"and He lives, He lives,\",\"He lives, He lives in me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0476', 476, 'My Lord, what love is this', 'MP', 'en', '1989 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'My Lord, what love is this
that pays so dearly,
that I, the guilty one,
may go free!
Amazing love, O what sacrifice,
the Son of God given for me.
My debt He pays, and my death He dies,
that I might live, that I might live.
And so, they watched Him die
despised, rejected:
but O the blood He shed
flowed for me!
Amazing love...
And now this love of Christ
shall flow like rivers;
come wash your guilt away,
live again!
Amazing love...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0476', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0476', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0476', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0476', 'verse', 1, 0, '[\"My Lord, what love is this\",\"that pays so dearly,\",\"that I, the guilty one,\",\"may go free!\",\"Amazing love, O what sacrifice,\",\"the Son of God given for me.\",\"My debt He pays, and my death He dies,\",\"that I might live, that I might live.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0476', 'verse', 2, 1, '[\"And so, they watched Him die\",\"despised, rejected:\",\"but O the blood He shed\",\"flowed for me!\",\"Amazing love...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0476', 'verse', 3, 2, '[\"And now this love of Christ\",\"shall flow like rivers;\",\"come wash your guilt away,\",\"live again!\",\"Amazing love...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0477', 477, 'My peace', 'MP', 'en', 'Copyright 1975 Sovereign Music UK. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'My peace I give unto you,
it’s a peace that the world cannot give,
it’s a peace that the world cannot understand:
peace to know, peace to live,
My peace I give unto you.
My joy I give unto you,
it’s a joy that the world cannot give,
it’s a joy that the world cannot understand:
joy to know, joy to live,
My joy I give unto you.
My love I give unto you,
it’s a love that the world cannot give,
it’s a love that the world cannot understand:
love to know, love to live,
My love I give unto you.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0477', 'Keith Routledge');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0477', 'Keith Routledge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0477', 'verse', 1, 0, '[\"My peace I give unto you,\",\"it’s a peace that the world cannot give,\",\"it’s a peace that the world cannot understand:\",\"peace to know, peace to live,\",\"My peace I give unto you.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0477', 'verse', 2, 1, '[\"My joy I give unto you,\",\"it’s a joy that the world cannot give,\",\"it’s a joy that the world cannot understand:\",\"joy to know, joy to live,\",\"My joy I give unto you.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0477', 'verse', 3, 2, '[\"My love I give unto you,\",\"it’s a love that the world cannot give,\",\"it’s a love that the world cannot understand:\",\"love to know, love to live,\",\"My love I give unto you.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0478', 478, 'My song is love unknown', 'MP', 'en', 'Trustees of the John Ireland Trust, John Ireland Charitable Trust,‬‬ 217 Imperial Apartments, ‬‬South Western House‬‬, Southampton, SO14 3AL.‬‬', '', 0, 0, 0, 1, 1, 'My song is love unknown;
my Saviour’s love to me;
love to the loveless shown,
that they might lovely be.
O who am I,
that for my sake,
my Lord should take
frail flesh, and die?
He came from His blest throne,
salvation to bestow;
but men made strange, and none
the longed-for Christ would know.
But O my friend,
my friend indeed,
who at my need
His life did spend.
Sometimes they strew His way,
and His sweet praises sing;
resounding all the day,
hosannas to their King.
Then: ‘Crucify!’
is all their breath,
and for His death
they thirst and cry.
Why, what hath my Lord done?
What makes this rage and spite?
He made the lame to run,
He gave the blind their sight.
Sweet injuries!
yet they at these
themselves displease,
and ’gainst Him rise.
They rise and needs will have
my dear Lord made away:
a murderer they save,
the Prince of life they slay.
Yet cheerful He
to suffering goes,
that He His foes');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0478', 'Samuel Crossman');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0478', 'John Ireland');
