INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0479', 479, 'My soul doth magnify the Lord', 'MP', 'en', 'control                        arrangement: ? 1975 Celebration / kingswaysongs.com. tym@kingsway.co.uk. For Europe and Commonwealth (excl. Canada, Australasia and Africa). Used by permission.', '', 0, 0, 0, 1, 0, 'My soul doth magnify the Lord,
and my spirit hath rejoiced in God my Saviour.
For He that is mighty hath done great things,
and holy is His name.
My soul doth magnify the Lord,
my soul doth magnify the Lord,
and my spirit hath rejoiced in God my Saviour.
For He that is mighty hath done great things,
and holy is His name.
My soul doth magnify the Lord,
my soul doth magnify the Lord,
and my spirit hath rejoiced in God my Saviour.
For He that is mighty hath done great things,
