INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0479', 'verse', 1, 0, '[\"My soul doth magnify the Lord,\",\"and my spirit hath rejoiced in God my Saviour.\",\"For He that is mighty hath done great things,\",\"and holy is His name.\",\"My soul doth magnify the Lord,\",\"my soul doth magnify the Lord,\",\"and my spirit hath rejoiced in God my Saviour.\",\"For He that is mighty hath done great things,\",\"and holy is His name.\",\"My soul doth magnify the Lord,\",\"my soul doth magnify the Lord,\",\"and my spirit hath rejoiced in God my Saviour.\",\"For He that is mighty hath done great things,\",\"and holy is His name.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0480', 480, 'New every morning', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'New every morning is the love
our waking and uprising prove:
through sleep and darkness safely brought,
restored to life and power and thought.
New mercies, each returning day,
surround Your people as they pray:
new dangers past, new sins forgiven,
new thoughts of God, new hopes of heaven.
If in our daily life our mind
be set to honour all we find,
new treasures still, of countless price,
God will provide for sacrifice.
The trivial round, the common task,
will give us all we ought to ask:
room to deny ourselves, a road
to bring us daily nearer God.
Prepare us, Lord, in Your dear love
for perfect rest with You above,
and help us, this and every day,
to grow more like You as we pray.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0480', 'John Keble');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0480', 'Samuel Webbe');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0480', 'verse', 1, 0, '[\"New every morning is the love\",\"our waking and uprising prove:\",\"through sleep and darkness safely brought,\",\"restored to life and power and thought.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0480', 'verse', 2, 1, '[\"New mercies, each returning day,\",\"surround Your people as they pray:\",\"new dangers past, new sins forgiven,\",\"new thoughts of God, new hopes of heaven.\"]');
