INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0481', 481, 'Name of all majesty', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Name of all majesty,
fathomless mystery,
King of the ages
by angels adored;
power and authority,
splendour and dignity,
bow to His mastery,
Jesus is Lord!
Child of our destiny,
God from eternity,
love of the Father
on sinners outpoured;
see now what God has done
sending His only Son,
Christ the belovèd One,
Jesus is Lord!
Saviour of Calvary,
costliest victory,
darkness defeated
and Eden restored;
born as a man to die,
nailed to a cross on high,
cold in the grave to lie,
Jesus is Lord!
Source of all sovereignty,
light, immortality,
life everlasting
and heaven assured;
so with the ransomed, we
praise Him eternally,
Christ in His majesty –
Jesus is Lord!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0481', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0481', 'Michael Baughen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0481', 'Noël Tredinnick');
