INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0483', 483, 'No weapon formed', 'MP', 'en', '1982 Christian Fellowship of Columbia, Missouri, USA', '', 0, 0, 0, 1, 1, 'No weapon formed, or army or king,
shall be able to stand
against the Lord and His anointed.
All principalities and powers
shall crumble before the Lord;
and men’s hearts shall be released,
and they shall come unto the Lord.
No weapon formed, or army or king,
shall be able to stand
against the Lord and His anointed.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0483', 'Tom Dowell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0483', 'Tom Dowell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0483', 'verse', 1, 0, '[\"No weapon formed, or army or king,\",\"shall be able to stand\",\"against the Lord and His anointed.\",\"All principalities and powers\",\"shall crumble before the Lord;\",\"and men’s hearts shall be released,\",\"and they shall come unto the Lord.\",\"No weapon formed, or army or king,\",\"shall be able to stand\",\"against the Lord and His anointed.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0484', 484, 'Now dawns the Sun of righteousness', 'MP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Now dawns the Sun of righteousness,
and the darkness will never
His brightness dim;
true light that lights the hearts of men,
only Son of the Father,
Jesus Christ.
Tell out, tell out the news,
on every street proclaim,
a child is born, a Son is given
and Jesus is His name!
Tell out, tell out the news,
our Saviour Christ has come,
in every tribe and nation,
let songs of praise be sung,
let songs of praise be sung!
Laughter and joy He will increase,
all our burdens be lifted,
oppression cease;
the blood-stained battle-dress be burned,
and the art of our warfare
never more be learned.
Tell out...
So let us go, His witnesses,
spreading news of His kingdom
of righteousness,
till the whole world has heard the song,
till the harvest is gathered,
then the end shall come.
Tell out...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0484', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0484', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0484', 'Christopher Norton');
