INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0484', 'verse', 2, 1, '[\"Laughter and joy He will increase,\",\"all our burdens be lifted,\",\"oppression cease;\",\"the blood-stained battle-dress be burned,\",\"and the art of our warfare\",\"never more be learned.\",\"Tell out...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0484', 'verse', 3, 2, '[\"So let us go, His witnesses,\",\"spreading news of His kingdom\",\"of righteousness,\",\"till the whole world has heard the song,\",\"till the harvest is gathered,\",\"then the end shall come.\",\"Tell out...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0485', 485, 'Now I have found the ground', 'MP', 'en', '1987 in this version Horrobin/Leavers            ? Copyright control', '', 0, 0, 0, 1, 1, 'Now I have found the ground wherein
sure my soul’s anchor may remain –
the wounds of Jesus, for my sin
before the world’s foundation slain;
whose mercy shall unshaken stay,
when heaven and earth are fled away.
Father, Your everlasting grace
our human thought surpassing far,
Your heart still melts with tenderness,
Your arms of love still open are:
returning sinners will receive
eternal life as they believe.
Your love, eternal hope, no less,
my sins consumed at Calvary!
Covered is my unrighteousness,
no spot of guilt remains on me,
while Jesu’s blood through earth and skies
mercy, free, boundless mercy! cries.
Though waves and storms go o’er my head,
though strength, and health, and friends be gone,
though joys be withered all and dead,
though every comfort be withdrawn,
on this my steadfast soul relies –
Father, Your mercy never dies!
Fixed on this ground will I remain,
though my heart fail and flesh decay;
this anchor shall my soul sustain,
when earth’s foundations melt away:
mercy’s full power I then shall prove,
loved with an everlasting love.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0485', 'Johann Andreas Rothe');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0485', 'Alfred Beer');
