INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0486', 486, 'Now thank we all our God', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Now thank we all our God,
with hearts, and hands, and voices;
who wondrous things hath done,
in whom His world rejoices;
Who, from our mothers’ arms,
hath blest us on our way
with countless gifts of love,
and still is ours today.
O may this bounteous God
through all our life be near us,
with ever-joyful hearts
and blessèd peace to cheer us;
and keep us in His grace,
and guide us when perplexed,
and free us from all ills
in this world and the next.
All praise and thanks to God
the Father now be given,
the Son, and Him who reigns
with Them in highest heaven;
the one eternal God,
whom heaven and earth adore;
for thus it was, is now,
and shall be evermore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0486', 'Martin Rinkart');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0486', 'Johann Crüger');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0486', 'verse', 1, 0, '[\"Now thank we all our God,\",\"with hearts, and hands, and voices;\",\"who wondrous things hath done,\",\"in whom His world rejoices;\",\"Who, from our mothers’ arms,\",\"hath blest us on our way\",\"with countless gifts of love,\",\"and still is ours today.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0486', 'verse', 2, 1, '[\"O may this bounteous God\",\"through all our life be near us,\",\"with ever-joyful hearts\",\"and blessèd peace to cheer us;\",\"and keep us in His grace,\",\"and guide us when perplexed,\",\"and free us from all ills\",\"in this world and the next.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0486', 'verse', 3, 2, '[\"All praise and thanks to God\",\"the Father now be given,\",\"the Son, and Him who reigns\",\"with Them in highest heaven;\",\"the one eternal God,\",\"whom heaven and earth adore;\",\"for thus it was, is now,\",\"and shall be evermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0487', 487, 'Not what these hands have done', 'MP', 'en', 'Copyright Novello & Co Ltd. All Rights Reserved. International Copyright Secured. Used by permission of Novello & Company Limited.', '', 0, 0, 0, 1, 0, 'Not what these hands have done
can save this guilty soul,
not what this toiling flesh has borne
can make my spirit whole.
Not what I feel or do
can give me peace with God;
not all my prayers, and sighs, and tears
can bear my awful load.
Thy work alone, O Christ,
can ease this weight of sin;
Thy blood alone, O Lamb of God,
can give me peace within.
Thy love to me, O God,
not mine, O Lord, to Thee,
can rid me of this dark unrest,
and set my spirit free.
Thy grace alone, O God,
to me can pardon speak;
Thy power alone, O Son of God,
can this sore bondage break.
I bless the Christ of God,
I rest on love divine,
and with unfaltering lip and heart,
I call this Saviour mine.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0487', 'Horatius Bonar');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0487', 'Joseph C Bridge');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0487', 'Joseph C. Bridges');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0487', 'verse', 1, 0, '[\"Not what these hands have done\",\"can save this guilty soul,\",\"not what this toiling flesh has borne\",\"can make my spirit whole.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0487', 'verse', 2, 1, '[\"Not what I feel or do\",\"can give me peace with God;\",\"not all my prayers, and sighs, and tears\",\"can bear my awful load.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0487', 'verse', 3, 2, '[\"Thy work alone, O Christ,\",\"can ease this weight of sin;\",\"Thy blood alone, O Lamb of God,\",\"can give me peace within.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0487', 'verse', 4, 3, '[\"Thy love to me, O God,\",\"not mine, O Lord, to Thee,\",\"can rid me of this dark unrest,\",\"and set my spirit free.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0487', 'verse', 5, 4, '[\"Thy grace alone, O God,\",\"to me can pardon speak;\",\"Thy power alone, O Son of God,\",\"can this sore bondage break.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0487', 'verse', 6, 5, '[\"I bless the Christ of God,\",\"I rest on love divine,\",\"and with unfaltering lip and heart,\",\"I call this Saviour mine.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0488', 488, 'O Breath of Life', 'MP', 'en', 'E A P Head/Copyright control            Copyright control', '', 0, 0, 0, 1, 1, 'O Breath of Life, come sweeping through us,
revive Your Church with life and power;
O Breath of Life, come, cleanse, renew us
and fit Your Church to meet this hour.
O Breath of Love, come breathe within us,
renewing thought and will and heart;
come, Love of Christ, afresh to win us,
revive Your Church in every part!
O Wind of God, come bend us, break us
till humbly we confess our need;
then, in Your tenderness remake us,
revive, restore – for this we plead.
Revive us, Lord; is zeal abating
while harvest fields are vast and white?
Revive us, Lord, the world is waiting –
equip Thy Church to spread the light.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0488', 'Elizabeth Ann Porter Head');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0488', 'Mary Jane Hammond');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0488', 'verse', 1, 0, '[\"O Breath of Life, come sweeping through us,\",\"revive Your Church with life and power;\",\"O Breath of Life, come, cleanse, renew us\",\"and fit Your Church to meet this hour.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0488', 'verse', 2, 1, '[\"O Breath of Love, come breathe within us,\",\"renewing thought and will and heart;\",\"come, Love of Christ, afresh to win us,\",\"revive Your Church in every part!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0488', 'verse', 3, 2, '[\"O Wind of God, come bend us, break us\",\"till humbly we confess our need;\",\"then, in Your tenderness remake us,\",\"revive, restore – for this we plead.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0488', 'verse', 4, 3, '[\"Revive us, Lord; is zeal abating\",\"while harvest fields are vast and white?\",\"Revive us, Lord, the world is waiting –\",\"equip Thy Church to spread the light.\"]');
