INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0490', 490, 'O come, let us adore Him', 'MP', 'en', 'control            arrangement: ? 1983 Roland Fudge', '', 0, 0, 0, 1, 1, 'O come, let us adore Him,
O come, let us adore Him,
O come, let us adore Him,
Christ the Lord.
We’ll give Him all the glory...
For He alone is worthy...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0490', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0490', 'John Francis Wade');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0490', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0490', 'verse', 1, 0, '[\"O come, let us adore Him,\",\"O come, let us adore Him,\",\"O come, let us adore Him,\",\"Christ the Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0490', 'verse', 2, 1, '[\"We’ll give Him all the glory...\"]');
