INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0491', 491, 'O come, all you faithful', 'MP', 'en', '1986 in this version Horrobin/Leavers', '', 0, 0, 0, 1, 1, 'O come, all you faithful,
joyful and triumphant,
O come now, O come now to Bethlehem;
come and behold Him,
born the King of angels:
O come, let us adore Him,
O come, let us adore Him,
O come, let us adore Him,
Christ the Lord!
True God of true God,
light of light eternal,
He, who abhors not the virgin’s womb;
Son of the Father,
begotten not created:
O come, let us adore Him...
Sing like the angels,
sing in exultation,
sing with the citizens of heaven above,
‘Glory to God,
glory in the highest’:
O come, let us adore Him...
Yes, Lord, we greet You,
born that/this happy morning,
Jesus, to You be glory given!
Word of the Father,
then/now in flesh appearing:
O come, let us adore Him...
Words tr. by Frederick Oakley
Words altered by Peter Horrobin
Words altered by Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0491', 'John Francis Wade');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0491', 'William Henry Monk');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0491', 'verse', 1, 0, '[\"O come, all you faithful,\",\"joyful and triumphant,\",\"O come now, O come now to Bethlehem;\",\"come and behold Him,\",\"born the King of angels:\",\"O come, let us adore Him,\",\"O come, let us adore Him,\",\"O come, let us adore Him,\",\"Christ the Lord!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0491', 'verse', 2, 1, '[\"True God of true God,\",\"light of light eternal,\",\"He, who abhors not the virgin’s womb;\",\"Son of the Father,\",\"begotten not created:\",\"O come, let us adore Him...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0491', 'verse', 3, 2, '[\"Sing like the angels,\",\"sing in exultation,\",\"sing with the citizens of heaven above,\",\"‘Glory to God,\",\"glory in the highest’:\",\"O come, let us adore Him...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0491', 'verse', 4, 3, '[\"Yes, Lord, we greet You,\",\"born that\\/this happy morning,\",\"Jesus, to You be glory given!\",\"Word of the Father,\",\"then\\/now in flesh appearing:\",\"O come, let us adore Him...\",\"Words tr. by Frederick Oakley\",\"Words altered by Peter Horrobin\",\"Words altered by Greg Leavers\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0492', 492, 'O come, let us worship', 'MP', 'en', '© 1981 Authentic Publishing / Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'O come, let us worship and bow down,
let us kneel before the Lord our King;
let us whisper His name, wonderful name,
Jesus our Lord and King.
For He is Lord of all the earth,
His glory outshines the sun;
see Him clothed in His robes of righteousness,
God’s belovèd Son.
O come, let us worship and bow down,
let us kneel before the Lord our King;
let us whisper His name, wonderful name,
Jesus our Lord and King.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0492', 'Iain Anderson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0492', 'Iain Anderson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0492', 'verse', 1, 0, '[\"O come, let us worship and bow down,\",\"let us kneel before the Lord our King;\",\"let us whisper His name, wonderful name,\",\"Jesus our Lord and King.\",\"For He is Lord of all the earth,\",\"His glory outshines the sun;\",\"see Him clothed in His robes of righteousness,\",\"God’s belovèd Son.\",\"O come, let us worship and bow down,\",\"let us kneel before the Lord our King;\",\"let us whisper His name, wonderful name,\",\"Jesus our Lord and King.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0493', 493, 'O come, O come, Emmanuel', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O come, O come, Emmanuel,
and ransom captive Israel,
that mourns in lonely exile here
until the Son of God appear.
Rejoice, rejoice! Emmanuel
shall come to thee, O Israel.
O come, O come, Thou Lord of might,
who to Thy tribes, on Sinai’s height
in ancient times didst give the law
in cloud and majesty and awe.
Rejoice, rejoice...
O come, Thou rod of Jesse, free
Thine own from Satan’s tyranny;');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0493', 'verse', 1, 0, '[\"O come, O come, Emmanuel,\",\"and ransom captive Israel,\",\"that mourns in lonely exile here\",\"until the Son of God appear.\",\"Rejoice, rejoice! Emmanuel\",\"shall come to thee, O Israel.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0493', 'verse', 2, 1, '[\"O come, O come, Thou Lord of might,\",\"who to Thy tribes, on Sinai’s height\",\"in ancient times didst give the law\",\"in cloud and majesty and awe.\",\"Rejoice, rejoice...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0493', 'verse', 3, 2, '[\"O come, Thou rod of Jesse, free\",\"Thine own from Satan’s tyranny;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0494', 494, 'O for a closer walk with God', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O for a closer walk with God,
a calm and heavenly frame,
a light to shine upon the road
that leads me to the Lamb.
Where is the blessèdness I knew
when I first saw the Lord?
Where is that soul-refreshing view
of Jesus and His word?
What peaceful hours I once enjoyed!
how sweet their memory still!
But they have left an aching void
the world can never fill.
Return, O holy Dove! return,
sweet messenger of rest!
I hate the sins that made Thee mourn,
and drove Thee from my breast.
The dearest idol I have known,
whate’er that idol be,
help me to tear it from Thy throne,
and worship only Thee.
So shall my walk be close with God,
calm and serene my frame;
so purer light shall mark the road
that leads me to the Lamb.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0494', 'William Cowper');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0494', 'verse', 1, 0, '[\"O for a closer walk with God,\",\"a calm and heavenly frame,\",\"a light to shine upon the road\",\"that leads me to the Lamb.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0494', 'verse', 2, 1, '[\"Where is the blessèdness I knew\",\"when I first saw the Lord?\",\"Where is that soul-refreshing view\",\"of Jesus and His word?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0494', 'verse', 3, 2, '[\"What peaceful hours I once enjoyed!\",\"how sweet their memory still!\",\"But they have left an aching void\",\"the world can never fill.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0494', 'verse', 4, 3, '[\"Return, O holy Dove! return,\",\"sweet messenger of rest!\",\"I hate the sins that made Thee mourn,\",\"and drove Thee from my breast.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0494', 'verse', 5, 4, '[\"The dearest idol I have known,\",\"whate’er that idol be,\",\"help me to tear it from Thy throne,\",\"and worship only Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0494', 'verse', 6, 5, '[\"So shall my walk be close with God,\",\"calm and serene my frame;\",\"so purer light shall mark the road\",\"that leads me to the Lamb.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0495', 495, 'O for a heart to praise my God', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O for a heart to praise my God,
a heart from sin set free,
a heart that always feels Thy blood
so freely shed for me.
A heart resigned, submissive, meek,
my great Redeemer’s throne;
where only Christ is heard to speak,
where Jesus reigns alone:
A humble, lowly, contrite heart,
believing, true, and clean;
which neither life nor death can part');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0495', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0495', 'Isaac Smith');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0495', 'verse', 1, 0, '[\"O for a heart to praise my God,\",\"a heart from sin set free,\",\"a heart that always feels Thy blood\",\"so freely shed for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0495', 'verse', 2, 1, '[\"A heart resigned, submissive, meek,\",\"my great Redeemer’s throne;\",\"where only Christ is heard to speak,\",\"where Jesus reigns alone:\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0495', 'verse', 3, 2, '[\"A humble, lowly, contrite heart,\",\"believing, true, and clean;\",\"which neither life nor death can part\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0496', 496, 'O for a thousand tongues to sing', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O for a thousand tongues to sing
my great Redeemer’s praise,
the glories of my God and King,
the triumphs of His grace!
Jesus! the name that charms our fears,
that bids our sorrows cease;
’tis music in the sinner’s ears,
’tis life, and health, and peace.
He breaks the power of cancelled sin,
He sets the prisoner free;
His blood can make the foulest clean;
His blood availed for me.
He speaks, and, listening to His voice,
new life the dead receive,
the mournful, broken hearts rejoice,
the humble poor believe.
Hear Him, ye deaf; His praise, ye dumb,
your loosened tongues employ:
ye blind, behold your Saviour come;
and leap, ye lame, for joy.
My gracious Master, and my God,
assist me to proclaim,
to spread through all the earth abroad,
the honours of Thy name.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0496', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0496', 'Thomas Jarman');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0496', 'verse', 1, 0, '[\"O for a thousand tongues to sing\",\"my great Redeemer’s praise,\",\"the glories of my God and King,\",\"the triumphs of His grace!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0496', 'verse', 2, 1, '[\"Jesus! the name that charms our fears,\",\"that bids our sorrows cease;\",\"’tis music in the sinner’s ears,\",\"’tis life, and health, and peace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0496', 'verse', 3, 2, '[\"He breaks the power of cancelled sin,\",\"He sets the prisoner free;\",\"His blood can make the foulest clean;\",\"His blood availed for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0496', 'verse', 4, 3, '[\"He speaks, and, listening to His voice,\",\"new life the dead receive,\",\"the mournful, broken hearts rejoice,\",\"the humble poor believe.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0496', 'verse', 5, 4, '[\"Hear Him, ye deaf; His praise, ye dumb,\",\"your loosened tongues employ:\",\"ye blind, behold your Saviour come;\",\"and leap, ye lame, for joy.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0496', 'verse', 6, 5, '[\"My gracious Master, and my God,\",\"assist me to proclaim,\",\"to spread through all the earth abroad,\",\"the honours of Thy name.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0497', 497, 'O give thanks to the Lord', 'MP', 'en', '©  1980 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'O give thanks to the Lord,
all you His people,
O give thanks to the Lord,
for He is good.
Let us praise, let us thank,
let us celebrate and dance;
O give thanks to the Lord,
for He is good.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0497', 'Joanne Pond');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0497', 'Joanne Pond');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0497', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0497', 'verse', 1, 0, '[\"O give thanks to the Lord,\",\"all you His people,\",\"O give thanks to the Lord,\",\"for He is good.\",\"Let us praise, let us thank,\",\"let us celebrate and dance;\",\"O give thanks to the Lord,\",\"for He is good.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0498', 498, 'O God, our help in ages past', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O God, our help in ages past,
our hope for years to come,
our shelter from the stormy blast,
and our eternal home.
Under the shadow of Your throne
Your saints have dwelt secure;
sufficient is Your arm alone,
and our defence is sure.
Before the hills in order stood,
or earth received her frame,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0498', 'Isaac Watts');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0498', 'William Croft');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0498', 'verse', 1, 0, '[\"O God, our help in ages past,\",\"our hope for years to come,\",\"our shelter from the stormy blast,\",\"and our eternal home.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0498', 'verse', 2, 1, '[\"Under the shadow of Your throne\",\"Your saints have dwelt secure;\",\"sufficient is Your arm alone,\",\"and our defence is sure.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0498', 'verse', 3, 2, '[\"Before the hills in order stood,\",\"or earth received her frame,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0499', 499, 'O happy day', 'MP', 'en', 'Ron Jones', '', 0, 0, 0, 1, 1, 'O happy day! that fixed my choice
on Thee, my Saviour and my God!
Well may this glowing heart rejoice,
and tell its raptures all abroad.
O happy day! O happy day!
when Jesus washed my sins away;
He taught me how to watch and pray,
and live rejoicing every day; (hallelujah!)
O happy day! O happy day!
when Jesus washed my sins away.
’Tis done, the great transaction’s done!
I am my Lord’s and He is mine!
He drew me, and I followed on,
charmed to confess the voice divine.
O happy day...
Now rest, my long-divided heart,
fixed on this blissful centre, rest;
nor ever from the Lord depart,
with Him of every good possessed.
O happy day...
High heaven, that heard the solemn vow,
that vow renewed shall daily hear;
till in life’s latest hour I bow,
and bless in death a bond so dear.
O happy day...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0499', 'Philip Doddridge');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0499', 'Ron Jones');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0499', 'verse', 1, 0, '[\"O happy day! that fixed my choice\",\"on Thee, my Saviour and my God!\",\"Well may this glowing heart rejoice,\",\"and tell its raptures all abroad.\",\"O happy day! O happy day!\",\"when Jesus washed my sins away;\",\"He taught me how to watch and pray,\",\"and live rejoicing every day; (hallelujah!)\",\"O happy day! O happy day!\",\"when Jesus washed my sins away.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0499', 'verse', 2, 1, '[\"’Tis done, the great transaction’s done!\",\"I am my Lord’s and He is mine!\",\"He drew me, and I followed on,\",\"charmed to confess the voice divine.\",\"O happy day...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0499', 'verse', 3, 2, '[\"Now rest, my long-divided heart,\",\"fixed on this blissful centre, rest;\",\"nor ever from the Lord depart,\",\"with Him of every good possessed.\",\"O happy day...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0499', 'verse', 4, 3, '[\"High heaven, that heard the solemn vow,\",\"that vow renewed shall daily hear;\",\"till in life’s latest hour I bow,\",\"and bless in death a bond so dear.\",\"O happy day...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0500', 500, 'O Holy Spirit, breathe on me', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O Holy Spirit, breathe on me,
O Holy Spirit, breathe on me,
and cleanse away my sin,
fill me with love within:
O Holy Spirit, breathe on me!
O Holy Spirit, fill my life,
O Holy Spirit, fill my life,
take all my pride from me,
give me humility:
O Holy Spirit, breathe on me!
O Holy Spirit, make me new,
O Holy Spirit, make me new,
make Jesus real to me,
give me His purity:
O Holy Spirit, breathe on me!
O Holy Spirit, wind of God,
O Holy Spirit, wind of God,
give me Your power today,
to live for You always:
O Holy Spirit, breathe on me!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0500', 'Norman Warren');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0500', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0500', 'verse', 1, 0, '[\"O Holy Spirit, breathe on me,\",\"O Holy Spirit, breathe on me,\",\"and cleanse away my sin,\",\"fill me with love within:\",\"O Holy Spirit, breathe on me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0500', 'verse', 2, 1, '[\"O Holy Spirit, fill my life,\",\"O Holy Spirit, fill my life,\",\"take all my pride from me,\",\"give me humility:\",\"O Holy Spirit, breathe on me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0500', 'verse', 3, 2, '[\"O Holy Spirit, make me new,\",\"O Holy Spirit, make me new,\",\"make Jesus real to me,\",\"give me His purity:\",\"O Holy Spirit, breathe on me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0500', 'verse', 4, 3, '[\"O Holy Spirit, wind of God,\",\"O Holy Spirit, wind of God,\",\"give me Your power today,\",\"to live for You always:\",\"O Holy Spirit, breathe on me!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0501', 501, 'O Jesus, I have promised', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O Jesus, I have promised
to serve Thee to the end;
be Thou for ever near me,
my Master and my friend.
I shall not fear the battle
if Thou art by my side,
nor wander from the pathway
if Thou wilt be my guide.
O let me feel Thee near me;
the world is ever near;
I see the sights that dazzle,
the tempting sounds I hear;
my foes are ever near me,
around me and within;
but, Jesus, draw Thou nearer,
and shield my soul from sin.
O let me hear Thee speaking
in accents clear and still,
above the storms of passion,
the murmurs of self-will;
O speak to reassure me,
to hasten or control;
O speak, and make me listen,
Thou guardian of my soul.
O Jesus, Thou hast promised,
to all who follow Thee,
that where Thou art in glory
there shall Thy servant be;
and, Jesus, I have promised
to serve Thee to the end;
O give me grace to follow
my Master and my friend.
O let me see Thy footmarks,
and in them plant mine own;
my hope to follow duly
is in Thy strength alone;
O guide me, call me, draw me,
uphold me to the end;
and then in heaven receive me,
my Saviour and my friend!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0501', 'John Ernest Bode');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0501', 'James William Elliott');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0501', 'verse', 1, 0, '[\"O Jesus, I have promised\",\"to serve Thee to the end;\",\"be Thou for ever near me,\",\"my Master and my friend.\",\"I shall not fear the battle\",\"if Thou art by my side,\",\"nor wander from the pathway\",\"if Thou wilt be my guide.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0501', 'verse', 2, 1, '[\"O let me feel Thee near me;\",\"the world is ever near;\",\"I see the sights that dazzle,\",\"the tempting sounds I hear;\",\"my foes are ever near me,\",\"around me and within;\",\"but, Jesus, draw Thou nearer,\",\"and shield my soul from sin.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0501', 'verse', 3, 2, '[\"O let me hear Thee speaking\",\"in accents clear and still,\",\"above the storms of passion,\",\"the murmurs of self-will;\",\"O speak to reassure me,\",\"to hasten or control;\",\"O speak, and make me listen,\",\"Thou guardian of my soul.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0501', 'verse', 4, 3, '[\"O Jesus, Thou hast promised,\",\"to all who follow Thee,\",\"that where Thou art in glory\",\"there shall Thy servant be;\",\"and, Jesus, I have promised\",\"to serve Thee to the end;\",\"O give me grace to follow\",\"my Master and my friend.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0501', 'verse', 5, 4, '[\"O let me see Thy footmarks,\",\"and in them plant mine own;\",\"my hope to follow duly\",\"is in Thy strength alone;\",\"O guide me, call me, draw me,\",\"uphold me to the end;\",\"and then in heaven receive me,\",\"my Saviour and my friend!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0502', 502, 'O let the Son of God enfold you', 'MP', 'en', '1979 Mercy/Vineyard Publishing (Admin. by Song Solutions www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'O let the Son of God enfold you
with His Spirit and His love;
let Him fill your heart and satisfy your soul.
O let Him have the things that hold you,
and His Spirit, like a dove,
will descend upon your life and make you whole.
Jesus, O Jesus,
come and fill Your lambs;
Jesus, O Jesus,
come and fill Your lambs.
O come and sing this song with gladness,
as your hearts are filled with joy;
lift your hands in sweet surrender to His name.
O give Him all your tears and sadness,
give Him all your years of pain,
and you’ll enter into life in Jesus’ name.
Jesus, O Jesus...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0502', 'John Wimber');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0502', 'John Wimber');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0502', 'verse', 1, 0, '[\"O let the Son of God enfold you\",\"with His Spirit and His love;\",\"let Him fill your heart and satisfy your soul.\",\"O let Him have the things that hold you,\",\"and His Spirit, like a dove,\",\"will descend upon your life and make you whole.\",\"Jesus, O Jesus,\",\"come and fill Your lambs;\",\"Jesus, O Jesus,\",\"come and fill Your lambs.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0502', 'verse', 2, 1, '[\"O come and sing this song with gladness,\",\"as your hearts are filled with joy;\",\"lift your hands in sweet surrender to His name.\",\"O give Him all your tears and sadness,\",\"give Him all your years of pain,\",\"and you’ll enter into life in Jesus’ name.\",\"Jesus, O Jesus...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0504', 504, 'O Lord, have mercy on me', 'MP', 'en', 'Mercy/Vineyard Publishing/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'O Lord, have mercy on me, and heal me;
O Lord, have mercy on me, and free me.
Place my feet upon a rock,
put a new song in my heart, in my heart,
O Lord, have mercy on me.
O Lord, may Your love and Your grace protect me;
O Lord, may Your ways and Your truth direct me.
Place my feet upon a rock,
put a new song in my heart, in my heart,
O Lord, have mercy on me.
Place my feet upon a rock,
put a new song in my heart, in my heart,
O Lord, have mercy on me,
O Lord, have mercy on me, on me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0504', 'Carl Tuttle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0504', 'Carl Tuttle');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0504', 'verse', 1, 0, '[\"O Lord, have mercy on me, and heal me;\",\"O Lord, have mercy on me, and free me.\",\"Place my feet upon a rock,\",\"put a new song in my heart, in my heart,\",\"O Lord, have mercy on me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0504', 'verse', 2, 1, '[\"O Lord, may Your love and Your grace protect me;\",\"O Lord, may Your ways and Your truth direct me.\",\"Place my feet upon a rock,\",\"put a new song in my heart, in my heart,\",\"O Lord, have mercy on me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0504', 'chorus', 0, 2, '[\"Place my feet upon a rock,\",\"put a new song in my heart, in my heart,\",\"O Lord, have mercy on me,\",\"O Lord, have mercy on me, on me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0505', 505, 'O Lord, most Holy God', 'MP', 'en', '© 1980 Authentic Publishing / Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'O Lord, most Holy God,
great are Your purposes,
great is Your will for us,
great is Your love.
And we rejoice in You,
and we will sing to You,
O Father, have Your way,
Your will be done.
For You are building
a temple without hands,
a city without walls,
enclosed by fire.
A place for You to dwell,
built out of living stones,
shaped by a Father’s hand
and joined in love.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0505', 'Wendy Churchill');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0505', 'Wendy Churchill');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0505', 'verse', 1, 0, '[\"O Lord, most Holy God,\",\"great are Your purposes,\",\"great is Your will for us,\",\"great is Your love.\",\"And we rejoice in You,\",\"and we will sing to You,\",\"O Father, have Your way,\",\"Your will be done.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0505', 'verse', 2, 1, '[\"For You are building\",\"a temple without hands,\",\"a city without walls,\",\"enclosed by fire.\",\"A place for You to dwell,\",\"built out of living stones,\",\"shaped by a Father’s hand\",\"and joined in love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0506', 506, 'How great Thou art', 'MP', 'en', '© 1949 and 1953 by the Stuart Hine Trust. All rights in the USA its territories and possessions, except print rights, administered by Capitol CMG Publishing. USA, North, Central and South America print rights administered by Hope Publishing Company. All other non US Americas rights administered by the Stuart Hine Trust. Rest of the world rights administered by Integrity Music Europe songs@integritymusic.com', '', 0, 0, 0, 1, 0, 'O Lord my God! when I in awesome wonder
consider all the works Thy hand hath made,
I see the stars, I hear the mighty thunder,
the power throughout the universe displayed;
Then sings my soul, my Saviour God, to Thee,
how great Thou art, how great Thou art!
Then sings my soul, my Saviour God, to Thee,
how great Thou art, how great Thou art!
When through the woods and forest glades I wander
and hear the birds sing sweetly in the trees;
when I look down from lofty mountain grandeur,
and hear the brook, and feel the gentle breeze;
Then sings my soul...
And when I think that God His Son not sparing,
sent Him to die – I scarce can take it in,
that on the cross my burden gladly bearing,
He bled and died to take away my sin:
Then sings my soul...
When Christ shall come with shout of acclamation
and take me home – what joy shall fill my heart!
Then shall I bow in humble adoration
and there proclaim, my God, how great Thou art!
Then sings my soul...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0506', 'Stuart Wesley Keene Hine');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0506', 'Stuart Wesley Keene Hine');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0506', 'verse', 1, 0, '[\"O Lord my God! when I in awesome wonder\",\"consider all the works Thy hand hath made,\",\"I see the stars, I hear the mighty thunder,\",\"the power throughout the universe displayed;\",\"Then sings my soul, my Saviour God, to Thee,\",\"how great Thou art, how great Thou art!\",\"Then sings my soul, my Saviour God, to Thee,\",\"how great Thou art, how great Thou art!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0506', 'verse', 2, 1, '[\"When through the woods and forest glades I wander\",\"and hear the birds sing sweetly in the trees;\",\"when I look down from lofty mountain grandeur,\",\"and hear the brook, and feel the gentle breeze;\",\"Then sings my soul...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0506', 'verse', 3, 2, '[\"And when I think that God His Son not sparing,\",\"sent Him to die – I scarce can take it in,\",\"that on the cross my burden gladly bearing,\",\"He bled and died to take away my sin:\",\"Then sings my soul...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0506', 'verse', 4, 3, '[\"When Christ shall come with shout of acclamation\",\"and take me home – what joy shall fill my heart!\",\"Then shall I bow in humble adoration\",\"and there proclaim, my God, how great Thou art!\",\"Then sings my soul...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0507', 507, 'We will magnify', 'MP', 'en', '©  1982 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'O Lord our God, how majestic is Your name,
the earth is filled with Your glory.
O Lord our God, You are robed in majesty,
You’ve set Your glory above the heavens.
We will magnify, we will magnify
the Lord enthroned in Zion;
We will magnify, we will magnify
the Lord enthroned in Zion.
O Lord our God, You have established a throne,
You reign in righteousness and splendour.
O Lord our God, the skies are ringing with Your praise,
soon those on earth will come to worship.
We will magnify...
O Lord our God, the world was made at Your command,
in You all things now hold together.
Now to Him who sits on the throne and to the Lamb,
be praise and glory and power for ever.
We will magnify...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0507', 'Phil Lawson Johnston');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0507', 'Phil Lawson Johnston');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0507', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0507', 'verse', 1, 0, '[\"O Lord our God, how majestic is Your name,\",\"the earth is filled with Your glory.\",\"O Lord our God, You are robed in majesty,\",\"You’ve set Your glory above the heavens.\",\"We will magnify, we will magnify\",\"the Lord enthroned in Zion;\",\"We will magnify, we will magnify\",\"the Lord enthroned in Zion.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0507', 'verse', 2, 1, '[\"O Lord our God, You have established a throne,\",\"You reign in righteousness and splendour.\",\"O Lord our God, the skies are ringing with Your praise,\",\"soon those on earth will come to worship.\",\"We will magnify...\"]');
