INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0508', 508, 'O Lord, our Lord', 'MP', 'en', '1981 Meadowgreen Music Company/CapitolCMGPublishing.com (adm UK/Eire Song Solutions www.songsolutions.org) All rights reserved. Used by permission.', '', 0, 0, 0, 1, 1, 'O Lord, our Lord,
how majestic is Your name in all the earth;
O Lord, our Lord,
how majestic is Your name in all the earth;
O Lord, we praise Your name;
O Lord, we magnify Your name.
Prince of peace, mighty God,
O Lord God almighty!');
