INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0508', 'Michael W Smith');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0508', 'verse', 1, 0, '[\"O Lord, our Lord,\",\"how majestic is Your name in all the earth;\",\"O Lord, our Lord,\",\"how majestic is Your name in all the earth;\",\"O Lord, we praise Your name;\",\"O Lord, we magnify Your name.\",\"Prince of peace, mighty God,\",\"O Lord God almighty!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0509', 509, 'O Lord, the clouds are gathering', 'MP', 'en', '1987 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'O Lord, the clouds are gathering,
the fire of judgement burns.
How we have fallen!
O Lord, You stand appalled to see
Your laws of love so scorned
and lives so broken.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0509', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0509', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0509', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0509', 'verse', 1, 0, '[\"O Lord, the clouds are gathering,\",\"the fire of judgement burns.\",\"How we have fallen!\",\"O Lord, You stand appalled to see\",\"Your laws of love so scorned\",\"and lives so broken.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0510', 510, 'O Lord, You are my light', 'MP', 'en', '©  1983 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'O Lord, You are my light,
O Lord, You are my salvation;
You have delivered me from all my fear,
for You are the defence of my life.
For my life is hidden with Christ in God,
You have concealed me in Your love;
You’ve lifted me up, placed my feet on a rock;
I will shout for joy in the house of God.
O Lord, You are my light...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0510', 'David Fellingham');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0510', 'David Fellingham');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0510', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0510', 'verse', 1, 0, '[\"O Lord, You are my light,\",\"O Lord, You are my salvation;\",\"You have delivered me from all my fear,\",\"for You are the defence of my life.\",\"For my life is hidden with Christ in God,\",\"You have concealed me in Your love;\",\"You’ve lifted me up, placed my feet on a rock;\",\"I will shout for joy in the house of God.\",\"O Lord, You are my light...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0511', 511, 'O Lord, Your tenderness', 'MP', 'en', '©  1986 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'O Lord, Your tenderness –
melting all my bitterness!
O Lord, I receive Your love.
O Lord, Your loveliness,
changing all my ugliness,
O Lord, I receive Your love,
O Lord, I receive Your love,
O Lord, I receive Your love.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0511', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0511', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0511', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0511', 'verse', 1, 0, '[\"O Lord, Your tenderness –\",\"melting all my bitterness!\",\"O Lord, I receive Your love.\",\"O Lord, Your loveliness,\",\"changing all my ugliness,\",\"O Lord, I receive Your love,\",\"O Lord, I receive Your love,\",\"O Lord, I receive Your love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0512', 512, 'O Lord, You’ve done great things', 'MP', 'en', '© 1979 Authentic Publishing / Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'O Lord, You’ve done great things, and I will praise You,
I will extol You and magnify Your name.
O Lord, You’ve done great things, and I will praise You,
I will extol You and magnify Your name.
I will sing praises unto You and remember Your goodness,
my past is forgiven and now I have life;
You crown me with steadfast love and tender mercy,
I’ll do Your will and bless You, O Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0512', 'Carolyn Govier');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0512', 'Carolyn Govier');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0512', 'verse', 1, 0, '[\"O Lord, You’ve done great things, and I will praise You,\",\"I will extol You and magnify Your name.\",\"O Lord, You’ve done great things, and I will praise You,\",\"I will extol You and magnify Your name.\",\"I will sing praises unto You and remember Your goodness,\",\"my past is forgiven and now I have life;\",\"You crown me with steadfast love and tender mercy,\",\"I’ll do Your will and bless You, O Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0513', 513, 'O Lord, You’re beautiful', 'MP', 'en', '1980 Birdwing Music / Keith Green Est. /Universal Music - Brentwood Benson Publ/CapitolCMGPublishing.com (adm UK/EIRE Song Solutions  www.songsolutions.org) All rights reserved. Used by permission.', '', 0, 0, 0, 1, 1, 'O Lord, You’re beautiful,
Your face is all I seek;
for when Your eyes are on this child,
Your grace abounds to me.
O Lord, please light the fire
that once burned bright and clear;
replace the lamp of my first love
that burns with holy fear!
I want to take Your word and shine it all around,
but first help me just to live it, Lord!
And when I’m doing well,
help me to never seek a crown,
for my reward is giving glory to You.
O Lord, You’re beautiful,
Your face is all I seek;
for when Your eyes are on this child,
Your grace abounds to me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0513', 'Keith Green');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0513', 'Keith Green');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0513', 'verse', 1, 0, '[\"O Lord, You’re beautiful,\",\"Your face is all I seek;\",\"for when Your eyes are on this child,\",\"Your grace abounds to me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0513', 'verse', 2, 1, '[\"O Lord, please light the fire\",\"that once burned bright and clear;\",\"replace the lamp of my first love\",\"that burns with holy fear!\",\"I want to take Your word and shine it all around,\",\"but first help me just to live it, Lord!\",\"And when I’m doing well,\",\"help me to never seek a crown,\",\"for my reward is giving glory to You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0513', 'verse', 3, 2, '[\"O Lord, You’re beautiful,\",\"Your face is all I seek;\",\"for when Your eyes are on this child,\",\"Your grace abounds to me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0514', 514, 'O love of God', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O love of God, how strong and true!
eternal and yet ever new;
uncomprehended and unbought,
beyond all knowledge and all thought.
O heavenly love, how precious still,
in days of weariness and ill,
in nights of pain and helplessness,
to heal, to comfort, and to bless!
O wide-embracing, wondrous love,
we see You in the sky above;
we see You in the earth below,
in seas that swell and streams that flow.
We see You best in Him who came
to bear for us the cross of shame,
sent by the Father from on high,
our life to live, our death to die.
We see Your power to bless and save
e’en in the darkness of the grave;
still more in resurrection-light,
we see the fulness of Your might.
O love of God, our shield and stay
through all the perils of our way;
eternal Love, in You we rest,
for ever safe, for ever blest!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0514', 'Horatius Bonar');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0514', 'John Henry Maunder');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0514', 'verse', 1, 0, '[\"O love of God, how strong and true!\",\"eternal and yet ever new;\",\"uncomprehended and unbought,\",\"beyond all knowledge and all thought.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0514', 'verse', 2, 1, '[\"O heavenly love, how precious still,\",\"in days of weariness and ill,\",\"in nights of pain and helplessness,\",\"to heal, to comfort, and to bless!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0514', 'verse', 3, 2, '[\"O wide-embracing, wondrous love,\",\"we see You in the sky above;\",\"we see You in the earth below,\",\"in seas that swell and streams that flow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0514', 'verse', 4, 3, '[\"We see You best in Him who came\",\"to bear for us the cross of shame,\",\"sent by the Father from on high,\",\"our life to live, our death to die.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0514', 'verse', 5, 4, '[\"We see Your power to bless and save\",\"e’en in the darkness of the grave;\",\"still more in resurrection-light,\",\"we see the fulness of Your might.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0514', 'verse', 6, 5, '[\"O love of God, our shield and stay\",\"through all the perils of our way;\",\"eternal Love, in You we rest,\",\"for ever safe, for ever blest!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0515', 515, 'O Love that wilt not let me go', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O Love that wilt not let me go,
I rest my weary soul in Thee;
I give Thee back the life I owe,
that in Thine ocean depths its flow
may richer, fuller be.
O Light that followest all my way,
I yield my flickering torch to Thee;
my heart restores its borrowed ray,
that in Thy sunshine’s blaze its day
may brighter, fairer be.
O Joy that seekest me through pain,
I cannot close my heart to Thee;
I trace the rainbow through the rain,
and feel the promise is not vain
that morn shall tearless be.
O cross that liftest up my head,
I dare not ask to fly from thee;
I lay in dust life’s glory dead,
and from the ground there blossoms red
life that shall endless be.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0515', 'George Matheson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0515', 'Arthur Lister Peace');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0515', 'verse', 1, 0, '[\"O Love that wilt not let me go,\",\"I rest my weary soul in Thee;\",\"I give Thee back the life I owe,\",\"that in Thine ocean depths its flow\",\"may richer, fuller be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0515', 'verse', 2, 1, '[\"O Light that followest all my way,\",\"I yield my flickering torch to Thee;\",\"my heart restores its borrowed ray,\",\"that in Thy sunshine’s blaze its day\",\"may brighter, fairer be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0515', 'verse', 3, 2, '[\"O Joy that seekest me through pain,\",\"I cannot close my heart to Thee;\",\"I trace the rainbow through the rain,\",\"and feel the promise is not vain\",\"that morn shall tearless be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0515', 'verse', 4, 3, '[\"O cross that liftest up my head,\",\"I dare not ask to fly from thee;\",\"I lay in dust life’s glory dead,\",\"and from the ground there blossoms red\",\"life that shall endless be.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0516', 516, 'O my Saviour, lifted', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O my Saviour, lifted');
