INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0517', 517, 'O perfect Love', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O perfect Love, all human thought transcending,
lowly we kneel in prayer before Your throne,
that theirs may be the love which knows no ending,
whom You for evermore now join as one.
O perfect Life, be now their full assurance
of tender charity, and steadfast faith,
of patient hope, and quiet brave endurance,
with childlike trust that fears nor pain nor death.
Grant them the joy which brightens earthly sorrow;
grant them the peace which calms all earthly strife;
and to life’s day the glorious unknown morrow
that dawns upon eternal love and life.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0517', 'Dorothy Gurney');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0517', 'Joseph Barnby');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0517', 'verse', 1, 0, '[\"O perfect Love, all human thought transcending,\",\"lowly we kneel in prayer before Your throne,\",\"that theirs may be the love which knows no ending,\",\"whom You for evermore now join as one.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0517', 'verse', 2, 1, '[\"O perfect Life, be now their full assurance\",\"of tender charity, and steadfast faith,\",\"of patient hope, and quiet brave endurance,\",\"with childlike trust that fears nor pain nor death.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0517', 'verse', 3, 2, '[\"Grant them the joy which brightens earthly sorrow;\",\"grant them the peace which calms all earthly strife;\",\"and to life’s day the glorious unknown morrow\",\"that dawns upon eternal love and life.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0518', 518, 'O praise ye the Lord!', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O praise ye the Lord!
praise Him in the height;
rejoice in His word,
ye angels of light;
ye heavens adore Him
by whom ye were made,
and worship before Him,
in brightness arrayed.
O praise ye the Lord!
praise Him upon earth,
in tuneful accord,
ye sons of new birth;
praise Him who has brought you
His grace from above,
praise Him who has taught you
to sing of His love.
O praise ye the Lord!
all things that give sound;
each jubilant chord,
re-echo around;
loud organs, His glory
forth tell in deep tone,
and sweet harp, the story
of what He has done.
O praise ye the Lord!
thanksgiving and song
to Him be outpoured
all ages along:
for love in creation,
for heaven restored,
for grace of salvation,
O praise ye the Lord!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0518', 'Henry Williams Baker');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0518', 'Henry John Gauntlett');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0518', 'verse', 1, 0, '[\"O praise ye the Lord!\",\"praise Him in the height;\",\"rejoice in His word,\",\"ye angels of light;\",\"ye heavens adore Him\",\"by whom ye were made,\",\"and worship before Him,\",\"in brightness arrayed.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0518', 'verse', 2, 1, '[\"O praise ye the Lord!\",\"praise Him upon earth,\",\"in tuneful accord,\",\"ye sons of new birth;\",\"praise Him who has brought you\",\"His grace from above,\",\"praise Him who has taught you\",\"to sing of His love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0518', 'verse', 3, 2, '[\"O praise ye the Lord!\",\"all things that give sound;\",\"each jubilant chord,\",\"re-echo around;\",\"loud organs, His glory\",\"forth tell in deep tone,\",\"and sweet harp, the story\",\"of what He has done.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0518', 'verse', 4, 3, '[\"O praise ye the Lord!\",\"thanksgiving and song\",\"to Him be outpoured\",\"all ages along:\",\"for love in creation,\",\"for heaven restored,\",\"for grace of salvation,\",\"O praise ye the Lord!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0519', 519, 'O Saviour Christ, I now confess', 'MP', 'en', '1986 Glyn L Taylor', '', 0, 0, 0, 1, 1, 'O Saviour Christ, I now confess
You are my Lord, my righteousness,
I follow Your example true,
and daily seek to be like You.
These waters have no power, I know,
to cleanse from sin or grace bestow.
’Tis in obedience to my Lord
that I am blest and He’s adored.
Buried with Christ, I die to sin,
His risen life and power within.
And victory is to me assured
as I surrender to the Lord.
’Tis one more step along the road
that leads me onward with my Lord.
Now fill me with the Spirit’s power,
make this a pentecostal hour.
Baptizing nations in Your name,
Father, Son, Spirit – still the same.
In full alignment to the Lord,
their guide, their strength – the Living Word.
Then, only then, shall all men hear
the news, that Christ’s return is near.
And men shall greet their coming Lord
by heaven and earth, for e’er adored.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0519', 'Glyn L Taylor');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0519', 'verse', 1, 0, '[\"O Saviour Christ, I now confess\",\"You are my Lord, my righteousness,\",\"I follow Your example true,\",\"and daily seek to be like You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0519', 'verse', 2, 1, '[\"These waters have no power, I know,\",\"to cleanse from sin or grace bestow.\",\"’Tis in obedience to my Lord\",\"that I am blest and He’s adored.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0519', 'verse', 3, 2, '[\"Buried with Christ, I die to sin,\",\"His risen life and power within.\",\"And victory is to me assured\",\"as I surrender to the Lord.\"]');
