INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0519', 'verse', 5, 4, '[\"Baptizing nations in Your name,\",\"Father, Son, Spirit – still the same.\",\"In full alignment to the Lord,\",\"their guide, their strength – the Living Word.\"]');
