INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0520', 520, 'O sacred head, once wounded', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O sacred head, once wounded,
with grief and pain weighed down,
how scornfully surrounded
with thorns, Thine only crown!
How pale art Thou with anguish,
with sore abuse and scorn!
How does that visage languish,
which once was bright as morn!
O Lord of life and glory,
what bliss till now was Thine!
I read the wondrous story,
I joy to call Thee mine.
Thy grief and Thy compassion
were all for sinners’ gain;
mine, mine was the transgression,
but Thine the deadly pain.
What language shall I borrow
to praise Thee, heavenly friend,
for this, Thy dying sorrow,
Thy pity without end?
Lord, make me Thine for ever,
nor let me faithless prove;
O let me never, never
abuse such dying love!
Be near me, Lord, when dying;
O show Thyself to me;
and, for my succour flying,
come, Lord, to set me free:
these eyes, new faith receiving,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0520', 'Paul Gerhardt');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0520', 'Johann Sebastian Bach');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0520', 'verse', 1, 0, '[\"O sacred head, once wounded,\",\"with grief and pain weighed down,\",\"how scornfully surrounded\",\"with thorns, Thine only crown!\",\"How pale art Thou with anguish,\",\"with sore abuse and scorn!\",\"How does that visage languish,\",\"which once was bright as morn!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0520', 'verse', 2, 1, '[\"O Lord of life and glory,\",\"what bliss till now was Thine!\",\"I read the wondrous story,\",\"I joy to call Thee mine.\",\"Thy grief and Thy compassion\",\"were all for sinners’ gain;\",\"mine, mine was the transgression,\",\"but Thine the deadly pain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0520', 'verse', 3, 2, '[\"What language shall I borrow\",\"to praise Thee, heavenly friend,\",\"for this, Thy dying sorrow,\",\"Thy pity without end?\",\"Lord, make me Thine for ever,\",\"nor let me faithless prove;\",\"O let me never, never\",\"abuse such dying love!\"]');
