INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0521', 521, 'O teach me what it meaneth', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O teach me what it meaneth,
that cross uplifted high,
with One, the Man of Sorrows,
condemned to bleed and die!
O teach me what it cost Thee
to make a sinner whole;
and teach me, Saviour, teach me
the value of a soul!
O teach me what it meaneth,
that sacred crimson tide,
the blood and water flowing');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0521', 'Lucy Ann Bennett');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0521', 'Chrétian Urhan');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0521', 'verse', 1, 0, '[\"O teach me what it meaneth,\",\"that cross uplifted high,\",\"with One, the Man of Sorrows,\",\"condemned to bleed and die!\",\"O teach me what it cost Thee\",\"to make a sinner whole;\",\"and teach me, Saviour, teach me\",\"the value of a soul!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0521', 'verse', 2, 1, '[\"O teach me what it meaneth,\",\"that sacred crimson tide,\",\"the blood and water flowing\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0522', 522, 'O the deep, deep love of Jesus!', 'MP', 'en', 'D Evans', '', 0, 0, 0, 1, 1, 'O the deep, deep love of Jesus!
Vast, unmeasured, boundless, free;
rolling as a mighty ocean
in its fulness over me.
Underneath me, all around me,
is the current of Thy love;
leading onward, leading homeward,
to my glorious rest above.
O the deep, deep love of Jesus!
Spread His praise from shore to shore,
how He loveth, ever loveth,
changeth never, nevermore;
how He watches o’er His loved ones,
died to call them all His own;
how for them He intercedeth,
watches over them from the throne.
O the deep, deep love of Jesus!
Love of every love the best:
’tis an ocean vast of blessing,
’tis a haven sweet of rest.
O the deep, deep love of Jesus!
’tis a heaven of heavens to me;
and it lifts me up to glory,
for it lifts me up to Thee.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0522', 'Samuel Trevor Francis');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0522', 'Thomas John Williams');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0522', 'verse', 1, 0, '[\"O the deep, deep love of Jesus!\",\"Vast, unmeasured, boundless, free;\",\"rolling as a mighty ocean\",\"in its fulness over me.\",\"Underneath me, all around me,\",\"is the current of Thy love;\",\"leading onward, leading homeward,\",\"to my glorious rest above.\"]');
