INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0522', 'verse', 3, 2, '[\"O the deep, deep love of Jesus!\",\"Love of every love the best:\",\"’tis an ocean vast of blessing,\",\"’tis a haven sweet of rest.\",\"O the deep, deep love of Jesus!\",\"’tis a heaven of heavens to me;\",\"and it lifts me up to glory,\",\"for it lifts me up to Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0523', 523, 'O the valleys shall ring', 'MP', 'en', '©  1980 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'O the valleys shall ring with the sound of praise,
and the lion shall lie with the lamb.
Of His government there shall be no end,
and His glory shall fill the earth.
May Your will be done, may Your kingdom come!
let it rule, let it reign in our lives.
There’s a shout in the camp as we answer the call,
Hail the King! Hail the Lord of lords!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0523', 'Dave Bilbrough');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0523', 'Dave Bilbrough');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0523', 'Andy Silver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0523', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0523', 'verse', 1, 0, '[\"O the valleys shall ring with the sound of praise,\",\"and the lion shall lie with the lamb.\",\"Of His government there shall be no end,\",\"and His glory shall fill the earth.\",\"May Your will be done, may Your kingdom come!\",\"let it rule, let it reign in our lives.\",\"There’s a shout in the camp as we answer the call,\",\"Hail the King! Hail the Lord of lords!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0524', 524, 'O the bitter shame and sorrow', 'MP', 'en', 'in this version The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'O the bitter shame and sorrow
that a time could ever be
when I let the Saviour’s pity
plead in vain, and proudly answered,
‘None of You and all of me!’
Yet You found me; there I saw You
dying and in agony,
heard You pray, ‘Forgive them, Father’,
and my wistful heart said faintly,
‘Some of You and some of me.’
Day by day Your tender mercy,
healing, helping, full and free,
firm and strong, with endless patience
brought me lower, while I whispered,
‘More of You and less of me.’
Higher than the highest heaven,
deeper than the deepest sea,
Lord, Your love at last has conquered:
grant me now my spirit’s longing,
‘All of You and none of me!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0524', 'Theodore Monod');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0524', 'Charles John Vincent');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0524', 'verse', 1, 0, '[\"O the bitter shame and sorrow\",\"that a time could ever be\",\"when I let the Saviour’s pity\",\"plead in vain, and proudly answered,\",\"‘None of You and all of me!’\"]');
