INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0525', 525, 'O Thou who camest from above', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O Thou who camest from above
the pure, celestial fire to impart,
kindle a flame of sacred love
on the mean altar of my heart.
There let it for Thy glory burn,
with inextinguishable blaze;
and, trembling, to its source return
in humble love and fervent praise.
Jesus, confirm my heart’s desire
to work and speak and think for Thee;
still let me guard the holy fire,
and still stir up Thy gift in me;
Ready for all Thy perfect will,
my acts of faith and love repeat,
till death Thine endless mercies seal,
and make the sacrifice complete.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0525', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0525', 'Samuel Stanley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0525', 'verse', 1, 0, '[\"O Thou who camest from above\",\"the pure, celestial fire to impart,\",\"kindle a flame of sacred love\",\"on the mean altar of my heart.\"]');
