INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0530', 530, 'Rock of my salvation', 'MP', 'en', 'Scripture in Song/Maranatha Music/ Universal Music Publishing/Print Licence UK Song Solutions Daybreak www.songsolutions.org', '', 0, 0, 0, 1, 1, 'O I will sing unto You with joy, O Lord,
for You’re the rock of my salvation;
come before You with thanksgiving,
and extol You with a song.
For You’re the greatest King above all else,
You hold the depths of the earth in Your hand.
O I will sing unto You with joy, O Lord,
for You’re the rock of my salvation.
O I will sing unto You...
O I will sing unto You with joy, O Lord,
for You’re the rock of my salvation.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0530', 'Shona Pink-Martin');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0530', 'Shona Pink-Martin');
