INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0530', 'verse', 1, 0, '[\"O I will sing unto You with joy, O Lord,\",\"for You’re the rock of my salvation;\",\"come before You with thanksgiving,\",\"and extol You with a song.\",\"For You’re the greatest King above all else,\",\"You hold the depths of the earth in Your hand.\",\"O I will sing unto You with joy, O Lord,\",\"for You’re the rock of my salvation.\",\"O I will sing unto You...\",\"O I will sing unto You with joy, O Lord,\",\"for You’re the rock of my salvation.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0531', 531, 'O Lord, I turn my mind to You', 'MP', 'en', '1989 Greg Leavers            ? 1989 Greg Leavers and Phil Burt', '', 0, 0, 0, 1, 1, 'O Lord, I turn my mind to You
right away from the things that today I’ve been through.
I’m so sorry, Lord, when they’ve clouded the way
and then have stopped me trusting You.
O Lord, I turn my eyes to You
and see love in Your eyes as You look towards me.
I’m so unworthy, Lord, yet You died for me;
all I can say is, ‘I love You.’
O Lord, please speak Your word to me,
just the message I need, out of Your loving heart.
May I grasp Your truth that will set my heart free');
