INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0532', 532, 'O! O! O! how good is the Lord', 'MP', 'en', 'control                        arrangement: ? 1974 Jeanne Harper/Copyright control', '', 0, 0, 0, 1, 1, 'O! O! O! how good is the Lord,
O! O! O! how good is the Lord,
O! O! O! how good is the Lord,
I never will forget what He has done for me.
He gives me salvation, how good is the Lord,
He gives me salvation, how good is the Lord,
He gives me salvation, how good is the Lord,
I never will forget what He has done for me.
O! O! O!...
He gives me His blessings...
O! O! O!...
He gives me His Spirit...
O! O! O!...
He gives me His healing...
O! O! O!...
He gives me His glory...
O! O! O!...');
