INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0533', 533, 'Oft in danger', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Oft in danger, oft in woe,
onward, Christians, onward go;
bear the toil, maintain the strife,
strengthened with the bread of life.
Onward, Christians, onward go!
join the war, and face the foe;
will ye flee in danger’s hour?
know ye not your captain’s power?
Let your drooping hearts be glad;
march in heavenly armour clad;
fight, nor think the battle long,
victory soon shall tune your song.
Let not sorrow dim your eye,
soon shall every tear be dry;
let not fears your course impede,
great your strength, if great your need.
Onward then in battle move;
more than conquerors ye shall prove;
though opposed by many a foe,
Christian soldiers, onward go.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0533', 'Henry Kirke White');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0533', 'Henry John Gauntlett');
