INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0534', 534, 'O the joy of Your forgiveness', 'MP', 'en', '©  1988 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'O the joy of Your forgiveness,
slowly sweeping over me;
now in heartfelt adoration,
this praise I’ll bring to You, my King;
I’ll worship You, my Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0534', 'Dave Bilbrough');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0534', 'Dave Bilbrough');
