INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0535', 535, 'O what a mystery I see', 'MP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'O what a mystery I see,
what marvellous design,
that God should come as one of us,
a Son in David’s line.
Flesh of our flesh, of woman born,
our humanness He owns;
and for a world of wickedness
His guiltless blood atones.
This perfect Man, incarnate God,
by selfless sacrifice
destroyed our sinful history,
all fallen Adam’s curse.
In Him the curse to blessing turns,
my barren spirit flowers,
as over the shattered power of sin
the cross of Jesus towers.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0535', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0535', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0535', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0535', 'verse', 1, 0, '[\"O what a mystery I see,\",\"what marvellous design,\",\"that God should come as one of us,\",\"a Son in David’s line.\",\"Flesh of our flesh, of woman born,\",\"our humanness He owns;\",\"and for a world of wickedness\",\"His guiltless blood atones.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0535', 'verse', 2, 1, '[\"This perfect Man, incarnate God,\",\"by selfless sacrifice\",\"destroyed our sinful history,\",\"all fallen Adam’s curse.\",\"In Him the curse to blessing turns,\",\"my barren spirit flowers,\",\"as over the shattered power of sin\",\"the cross of Jesus towers.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0536', 536, 'The Old Rugged Cross', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'On a hill far away stood an old rugged cross,
the emblem of suffering and shame;
and I love that old cross where the dearest and best
for a world of lost sinners was slain.
So I’ll cherish the old rugged cross
till my trophies at last I lay down;
I will cling to the old rugged cross
and exchange it some day for a crown.
O, the old rugged cross, so despised by the world,
has a wondrous attraction for me;
for the dear Lamb of God left His glory above
to bear it to dark Calvary.
So I’ll cherish...
In the old rugged cross, stained with blood so divine,
a wondrous beauty I see;
for ’twas on that old cross Jesus suffered and died
to pardon and sanctify me.
So I’ll cherish...
To the old rugged cross I will ever be true,
its shame and reproach gladly bear;
then He’ll call me some day to my home far away,
when His glory for ever I’ll share.
So I’ll cherish...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0536', 'George Bennard');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0536', 'George Bennard');
