INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0545', 545, 'Open our eyes, Lord', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Open our eyes, Lord,
we want to see Jesus –
to reach out and touch Him
and say that we love Him.
Open our ears, Lord,
and help us to listen:
O open our eyes, Lord,
we want to see Jesus!');
