INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0546', 546, 'Open Thou mine eyes', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Open Thou mine eyes,
