INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0547', 547, 'Open your eyes', 'MP', 'en', 'Shadow Spring/MSI Music Ad/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Open your eyes,
see the glory of the King;
lift up your voice,
and His praises sing!
I love You, Lord,
I will proclaim:
alleluia!
I bless Your name.');
