INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0549', 549, 'Our eyes have seen the glory', 'MP', 'en', 'Roland Meredith            arrangement: ? 1987 Phil Burt', '', 0, 0, 0, 1, 1, 'Our eyes have seen the glory
of our Saviour, Christ the Lord;
He is seated at His Father’s side
