INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0550', 550, 'Our Father in heaven', 'MP', 'en', '1980 The Archbishops\' Council            ? 1983 John Marsh', '', 0, 0, 0, 1, 1, 'Our Father in heaven,
hallowed be Your name,
Your kingdom come,
Your will be done,
on earth as in heaven.
Give us today our daily bread,
forgive us our sins,
as we forgive those who sin against us.
Lead us not into temptation,
but deliver us from evil.
For the kingdom, the power,
and the glory are Yours,
now and for ever, amen.
For the kingdom, the power,
and the glory are Yours,
now and for ever, amen.');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0550', 'John Marsh');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0550', 'verse', 1, 0, '[\"Our Father in heaven,\",\"hallowed be Your name,\",\"Your kingdom come,\",\"Your will be done,\",\"on earth as in heaven.\",\"Give us today our daily bread,\",\"forgive us our sins,\",\"as we forgive those who sin against us.\",\"Lead us not into temptation,\",\"but deliver us from evil.\",\"For the kingdom, the power,\",\"and the glory are Yours,\",\"now and for ever, amen.\",\"For the kingdom, the power,\",\"and the glory are Yours,\",\"now and for ever, amen.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0551', 551, 'Out of my bondage', 'MP', 'en', 'Harper Collins Religious (admin. by Song Solutions Copycare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Out of my bondage, sorrow, and night,
Jesus, I come: Jesus, I come;
into Your freedom, gladness, and light,
Jesus, I come to You.
Out of my sickness into Your health,
out of my want and into Your wealth,
out of my sin and into Yourself,
Jesus, I come to You.
Out of my shameful failure and loss,
Jesus, I come: Jesus, I come;
into the glorious gain of Your cross,
Jesus, I come to You.
Out of earth’s sorrows into Your balm,
out of life’s storm and into Your calm,
out of distress to jubilant psalm,
Jesus, I come to You.
Out of unrest and arrogant pride,
Jesus, I come: Jesus, I come;
into Your blessèd will to abide,
Jesus, I come to You.
Out of myself to dwell in Your love,
out of despair into joy from above,
upward for ever on wings like a dove,
Jesus, I come to You.
Out of the fear and dread of the tomb,
Jesus, I come: Jesus, I come;
into the joy and light of Your home,
Jesus, I come to You.
Out of the depths of ruin untold,
into the peace of Your sheltering fold,
ever Your glorious face to behold,
Jesus, I come to You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0551', 'William True Sleeper');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0551', 'George Coles Stebbins');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0551', 'verse', 1, 0, '[\"Out of my bondage, sorrow, and night,\",\"Jesus, I come: Jesus, I come;\",\"into Your freedom, gladness, and light,\",\"Jesus, I come to You.\",\"Out of my sickness into Your health,\",\"out of my want and into Your wealth,\",\"out of my sin and into Yourself,\",\"Jesus, I come to You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0551', 'verse', 2, 1, '[\"Out of my shameful failure and loss,\",\"Jesus, I come: Jesus, I come;\",\"into the glorious gain of Your cross,\",\"Jesus, I come to You.\",\"Out of earth’s sorrows into Your balm,\",\"out of life’s storm and into Your calm,\",\"out of distress to jubilant psalm,\",\"Jesus, I come to You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0551', 'verse', 3, 2, '[\"Out of unrest and arrogant pride,\",\"Jesus, I come: Jesus, I come;\",\"into Your blessèd will to abide,\",\"Jesus, I come to You.\",\"Out of myself to dwell in Your love,\",\"out of despair into joy from above,\",\"upward for ever on wings like a dove,\",\"Jesus, I come to You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0551', 'verse', 4, 3, '[\"Out of the fear and dread of the tomb,\",\"Jesus, I come: Jesus, I come;\",\"into the joy and light of Your home,\",\"Jesus, I come to You.\",\"Out of the depths of ruin untold,\",\"into the peace of Your sheltering fold,\",\"ever Your glorious face to behold,\",\"Jesus, I come to You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0552', 552, 'Our Father who is in heaven', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Our Father who is in heaven,
hallowed be Your name,
Your Kingdom come, Your will be done,
hallowed be Your name.
On earth as it is in heaven,
hallowed be Your name,
give us this day our daily bread,
hallowed be Your name.
Forgive us all our trespasses,
hallowed be Your name,
as we forgive those who trespass against us,
hallowed be Your name.
And lead us not into temptation,
hallowed be Your name,
but deliver us from all that is evil,
hallowed be Your name.
For Yours is the kingdom, the power and the glory,
hallowed be Your name,
for ever and for ever,
hallowed be Your name.
Amen, amen, it shall be so,
hallowed be Your name,
amen, amen, it shall be so,
hallowed be Your name.');
