INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0552', 'verse', 4, 3, '[\"And lead us not into temptation,\",\"hallowed be Your name,\",\"but deliver us from all that is evil,\",\"hallowed be Your name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0552', 'verse', 5, 4, '[\"For Yours is the kingdom, the power and the glory,\",\"hallowed be Your name,\",\"for ever and for ever,\",\"hallowed be Your name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0552', 'verse', 6, 5, '[\"Amen, amen, it shall be so,\",\"hallowed be Your name,\",\"amen, amen, it shall be so,\",\"hallowed be Your name.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0553', 553, 'Peace I give to you', 'MP', 'en', '©  1979 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Peace I give to you, I give to you My peace;
peace I give to you, I give to you My peace.
Let it flow to one another,
let it flow, let it flow;
let it flow to one another,
let it flow, let it flow.
Love I give to you, I give to you My love;
love I give to you, I give to you My love.
Let it flow...
Hope I give to you, I give to you My hope;
hope I give to you, I give to you My hope.
Let it flow...
Joy I give to you, I give to you My joy;
joy I give to you, I give to you My joy.
Let it flow...');
