INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0554', 554, 'Peace is flowing like a river', 'MP', 'en', 'control                        arrangement: ? 1974 Celebration / kingswaysongs.com. tym@kingsway.co.uk. For Europe and Commonwealth (excl. Canada, Australasia and Africa). Used by permission.', '', 0, 0, 0, 1, 0, 'Peace is flowing like a river,
flowing out through you and me,
spreading out into the desert,
setting all the captives free,
setting all the captives free.
Love is flowing...
Joy is flowing...
Faith is flowing...
Hope is flowing... etc.');
