INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0556', 556, 'Peace to you', 'MP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Peace to you,
we bless you now
in the name of the Lord,
Peace to you.
We bless you now
in the name of the Prince of peace.
Peace to you, peace to you,
peace to you, peace to you.');
