INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0557', 557, 'Praise God from whom all blessings flow', 'MP', 'en', 'Music 1972 Bud John Songs/CapitolCMGPublishing.com (adm UK/Eire Song Solutions  www.songsolutions.org) All rights reserved. Used by permission.', '', 0, 0, 0, 1, 1, 'Praise God from whom all blessings flow;
praise Him all creatures here below,
praise Him above, ye heavenly host;
praise Father, Son, and Holy Ghost.');
