INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0557', 'Jimmy Owens');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0557', 'verse', 1, 0, '[\"Praise God from whom all blessings flow;\",\"praise Him all creatures here below,\",\"praise Him above, ye heavenly host;\",\"praise Father, Son, and Holy Ghost.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0558', 558, 'Praise Him on the trumpet', 'MP', 'en', '©  1981 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Praise Him on the trumpet, the psaltery and harp;
praise Him on the timbrel and the dance;
praise Him with stringed instruments too;
praise Him on the loud cymbals,
praise Him on the loud cymbals;
let everything that has breath praise the Lord!
Hallelujah, praise the Lord;
hallelujah, praise the Lord:
let everything that has breath praise the Lord!
Hallelujah, praise the Lord;
hallelujah, praise the Lord:
let everything that has breath praise the Lord!');
