INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0558', 'verse', 1, 0, '[\"Praise Him on the trumpet, the psaltery and harp;\",\"praise Him on the timbrel and the dance;\",\"praise Him with stringed instruments too;\",\"praise Him on the loud cymbals,\",\"praise Him on the loud cymbals;\",\"let everything that has breath praise the Lord!\",\"Hallelujah, praise the Lord;\",\"hallelujah, praise the Lord:\",\"let everything that has breath praise the Lord!\",\"Hallelujah, praise the Lord;\",\"hallelujah, praise the Lord:\",\"let everything that has breath praise the Lord!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0559', 559, 'Praise Him, praise Him', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Praise Him, praise Him! Jesus, our blessèd Redeemer!
Sing, O earth – His wonderful love proclaim!
Hail Him! hail Him! highest archangels in glory;
strength and honour give to his holy name!
Like a shepherd, Jesus will guard His children,
in His arms He carries them all day long.
Praise Him, praise Him!
tell of His excellent greatness;
Praise Him, praise Him
ever in joyful song!
Praise Him, praise Him! Jesus, our blessèd Redeemer!
for our sins He suffered, and bled, and died;
He – our rock, our hope of eternal salvation,
hail Him, hail Him! Jesus the crucified!
Sound His praises – Jesus who bore our sorrows,
love unbounded, wonderful, deep and strong.
Praise Him...
Praise Him, praise Him! Jesus, our blessèd Redeemer!
heavenly portals, loud with hosannas ring!
Jesus, Saviour, reigneth for ever and ever:
crown Him, crown Him! Prophet, and Priest, and King!
Christ is coming, over the world victorious,
power and glory unto the Lord belong.
Praise Him...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0559', 'Fanny J Crosby');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0559', 'Chester G Allen');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0559', 'verse', 1, 0, '[\"Praise Him, praise Him! Jesus, our blessèd Redeemer!\",\"Sing, O earth – His wonderful love proclaim!\",\"Hail Him! hail Him! highest archangels in glory;\",\"strength and honour give to his holy name!\",\"Like a shepherd, Jesus will guard His children,\",\"in His arms He carries them all day long.\",\"Praise Him, praise Him!\",\"tell of His excellent greatness;\",\"Praise Him, praise Him\",\"ever in joyful song!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0559', 'verse', 2, 1, '[\"Praise Him, praise Him! Jesus, our blessèd Redeemer!\",\"for our sins He suffered, and bled, and died;\",\"He – our rock, our hope of eternal salvation,\",\"hail Him, hail Him! Jesus the crucified!\",\"Sound His praises – Jesus who bore our sorrows,\",\"love unbounded, wonderful, deep and strong.\",\"Praise Him...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0559', 'verse', 3, 2, '[\"Praise Him, praise Him! Jesus, our blessèd Redeemer!\",\"heavenly portals, loud with hosannas ring!\",\"Jesus, Saviour, reigneth for ever and ever:\",\"crown Him, crown Him! Prophet, and Priest, and King!\",\"Christ is coming, over the world victorious,\",\"power and glory unto the Lord belong.\",\"Praise Him...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0560', 560, 'Praise, my soul, the King of heaven', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Praise, my soul, the King of heaven;
to His feet thy tribute bring;
ransomed, healed, restored, forgiven,
who like thee His praise should sing?
Praise Him! Praise Him!
Praise Him! Praise Him!
Praise the everlasting King.
Praise Him for His grace and favour
to our fathers, in distress;
praise Him still the same for ever,
slow to chide, and swift to bless.
Praise Him! Praise Him!
Praise Him! Praise Him!
Glorious in His faithfulness.
Father-like He tends and spares us;
well our feeble frame He knows;
in His hands He gently bears us,
rescues us from all our foes.
Praise Him! Praise Him!
Praise Him! Praise Him!
Widely as His mercy flows.
Angels, help us to adore Him;
ye behold Him face to face;
sun and moon, bow down before Him;
dwellers all in time and space.
Praise Him! Praise Him!
Praise Him! Praise Him!
Praise with us the God of grace.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0560', 'Henry Francis Lyte');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0560', 'John Goss');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0560', 'verse', 1, 0, '[\"Praise, my soul, the King of heaven;\",\"to His feet thy tribute bring;\",\"ransomed, healed, restored, forgiven,\",\"who like thee His praise should sing?\",\"Praise Him! Praise Him!\",\"Praise Him! Praise Him!\",\"Praise the everlasting King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0560', 'verse', 2, 1, '[\"Praise Him for His grace and favour\",\"to our fathers, in distress;\",\"praise Him still the same for ever,\",\"slow to chide, and swift to bless.\",\"Praise Him! Praise Him!\",\"Praise Him! Praise Him!\",\"Glorious in His faithfulness.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0560', 'verse', 3, 2, '[\"Father-like He tends and spares us;\",\"well our feeble frame He knows;\",\"in His hands He gently bears us,\",\"rescues us from all our foes.\",\"Praise Him! Praise Him!\",\"Praise Him! Praise Him!\",\"Widely as His mercy flows.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0560', 'verse', 4, 3, '[\"Angels, help us to adore Him;\",\"ye behold Him face to face;\",\"sun and moon, bow down before Him;\",\"dwellers all in time and space.\",\"Praise Him! Praise Him!\",\"Praise Him! Praise Him!\",\"Praise with us the God of grace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0561', 561, 'Praise the Lord', 'MP', 'en', '1980 Bible Society', '', 0, 0, 0, 1, 0, 'Praise the Lord!
Praise Him in His temple!
Praise Him for the mighty things He has done!
Praise the Lord!
Praise Him for His greatness!
Praise Him with trumpets, harps and lyres.
All living creatures, praise! O praise,
O praise, praise the Lord!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0561', 'Lee Abbey Music Workshop');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0561', 'Lee Abbey Music Workshop');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0561', 'verse', 1, 0, '[\"Praise the Lord!\",\"Praise Him in His temple!\",\"Praise Him for the mighty things He has done!\",\"Praise the Lord!\",\"Praise Him for His greatness!\",\"Praise Him with trumpets, harps and lyres.\",\"All living creatures, praise! O praise,\",\"O praise, praise the Lord!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0562', 562, 'Praise the Lord', 'MP', 'en', '©  1977 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 1, 'Praise the Lord,
praise God in His sanctuary,
praise Him in His mighty heavens;
praise Him for His greatness,
and praise Him for His power.
Praise the Lord...
Praise Him with the sound of trumpets,
praise Him with the harp and lyre,
praise Him with the tambourine and with dancing;
let everything that has breath praise the Lord.
Praise the Lord...
Praise Him with the clash of cymbals,
praise Him with the strings and flute,
praise Him with the tambourine and with dancing;
let everything that has breath praise the Lord.
Praise the Lord...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0562', 'David Hadden');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0562', 'David Hadden');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0562', 'chorus', 0, 0, '[\"Praise the Lord,\",\"praise God in His sanctuary,\",\"praise Him in His mighty heavens;\",\"praise Him for His greatness,\",\"and praise Him for His power.\",\"Praise the Lord...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0562', 'verse', 1, 1, '[\"Praise Him with the sound of trumpets,\",\"praise Him with the harp and lyre,\",\"praise Him with the tambourine and with dancing;\",\"let everything that has breath praise the Lord.\",\"Praise the Lord...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0562', 'verse', 2, 2, '[\"Praise Him with the clash of cymbals,\",\"praise Him with the strings and flute,\",\"praise Him with the tambourine and with dancing;\",\"let everything that has breath praise the Lord.\",\"Praise the Lord...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0563', 563, 'Praise to the Holiest', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Praise to the Holiest in the height,
and in the depth be praise;
in all His words most wonderful;
most sure in all His ways.
O loving wisdom of our God!
when all was sin and shame,
a second Adam to the fight,
and to the rescue came.
O wisest love! that flesh and blood
which did in Adam fail,
should strive afresh against the foe,
should strive and should prevail.
And that a higher gift than grace
should flesh and blood refine,
God’s presence, and His very self
and essence all-divine.
O generous love! that He, who smote
in man for man the foe,
the double agony in man
for man should undergo.
And in the garden secretly,
and on the cross on high,
should teach His brethren, and inspire
to suffer and to die.
Praise to the Holiest in the height
and in the depth be praise:
in all His words most wonderful;
most sure in all His ways.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0563', 'John Henry Newman');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0563', 'John Bacchus Dykes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0563', 'verse', 1, 0, '[\"Praise to the Holiest in the height,\",\"and in the depth be praise;\",\"in all His words most wonderful;\",\"most sure in all His ways.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0563', 'verse', 2, 1, '[\"O loving wisdom of our God!\",\"when all was sin and shame,\",\"a second Adam to the fight,\",\"and to the rescue came.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0563', 'verse', 3, 2, '[\"O wisest love! that flesh and blood\",\"which did in Adam fail,\",\"should strive afresh against the foe,\",\"should strive and should prevail.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0563', 'verse', 4, 3, '[\"And that a higher gift than grace\",\"should flesh and blood refine,\",\"God’s presence, and His very self\",\"and essence all-divine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0563', 'verse', 5, 4, '[\"O generous love! that He, who smote\",\"in man for man the foe,\",\"the double agony in man\",\"for man should undergo.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0563', 'verse', 6, 5, '[\"And in the garden secretly,\",\"and on the cross on high,\",\"should teach His brethren, and inspire\",\"to suffer and to die.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0563', 'verse', 7, 6, '[\"Praise to the Holiest in the height\",\"and in the depth be praise:\",\"in all His words most wonderful;\",\"most sure in all His ways.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0564', 564, 'Praise to the Lord', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Praise to the Lord, the Almighty, the King of creation;
O my soul, praise Him, for He is thy health and salvation;
all ye who hear,
brothers and sisters, draw near,
praise Him in glad adoration.
Praise to the Lord, who o’er all things so wondrously reigneth,
shelters thee under His wings, yea, so gently sustaineth:
hast thou not seen?
all that is needful hath been
granted in what He ordaineth.
Praise to the Lord, who doth prosper thy work, and defend thee!
surely His goodness and mercy here daily attend thee.
Ponder anew
what the Almighty can do,
who with His love doth befriend thee.
Praise to the Lord! O let all that is in me adore Him!
All that hath life and breath come now with praises before Him!
Let the amen
sound from His people again:
gladly for aye we adore Him.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0564', 'Joachim Neander');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0564', 'verse', 1, 0, '[\"Praise to the Lord, the Almighty, the King of creation;\",\"O my soul, praise Him, for He is thy health and salvation;\",\"all ye who hear,\",\"brothers and sisters, draw near,\",\"praise Him in glad adoration.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0564', 'verse', 2, 1, '[\"Praise to the Lord, who o’er all things so wondrously reigneth,\",\"shelters thee under His wings, yea, so gently sustaineth:\",\"hast thou not seen?\",\"all that is needful hath been\",\"granted in what He ordaineth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0564', 'verse', 3, 2, '[\"Praise to the Lord, who doth prosper thy work, and defend thee!\",\"surely His goodness and mercy here daily attend thee.\",\"Ponder anew\",\"what the Almighty can do,\",\"who with His love doth befriend thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0564', 'verse', 4, 3, '[\"Praise to the Lord! O let all that is in me adore Him!\",\"All that hath life and breath come now with praises before Him!\",\"Let the amen\",\"sound from His people again:\",\"gladly for aye we adore Him.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0565', 565, 'Praise You, Lord', 'MP', 'en', '1977 Thankyou Music, administered by worshiptogether.com songs excl. UK and Europe, administered by kingswaysongs.com. tym@kingsway.co.uk. Used by permission.', '', 0, 0, 0, 1, 0, 'Praise You, Lord,
for the wonder of Your healing;
praise You, Lord,
for Your love so freely given;
out-pouring, anointing,
flowing in to heal our wounds –
praise You, Lord,
for Your love for me.
Praise You, Lord,
for Your gift of liberation;
praise You, Lord,
You have set the captives free;
the chains that bind are broken
by the sharpness of Your sword –
praise You, Lord,
You gave Your life for me.
Praise You, Lord,
You have borne the depths of sorrow;
praise You, Lord,
for Your anguish on the tree;
the nails that tore Your body
and the pain that tore Your soul –
praise You, Lord,
Your tears, they fell for me.
Praise You, Lord,
You have turned our thorns to roses;
glory, Lord, as they bloom upon Your brow;
the path of pain is hallowed,
for Your love has made it sweet –
praise You, Lord,
and may I love You now.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0565', 'Nettie Rose');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0565', 'Nettie Rose');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0565', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0565', 'verse', 1, 0, '[\"Praise You, Lord,\",\"for the wonder of Your healing;\",\"praise You, Lord,\",\"for Your love so freely given;\",\"out-pouring, anointing,\",\"flowing in to heal our wounds –\",\"praise You, Lord,\",\"for Your love for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0565', 'verse', 2, 1, '[\"Praise You, Lord,\",\"for Your gift of liberation;\",\"praise You, Lord,\",\"You have set the captives free;\",\"the chains that bind are broken\",\"by the sharpness of Your sword –\",\"praise You, Lord,\",\"You gave Your life for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0565', 'verse', 3, 2, '[\"Praise You, Lord,\",\"You have borne the depths of sorrow;\",\"praise You, Lord,\",\"for Your anguish on the tree;\",\"the nails that tore Your body\",\"and the pain that tore Your soul –\",\"praise You, Lord,\",\"Your tears, they fell for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0565', 'verse', 4, 3, '[\"Praise You, Lord,\",\"You have turned our thorns to roses;\",\"glory, Lord, as they bloom upon Your brow;\",\"the path of pain is hallowed,\",\"for Your love has made it sweet –\",\"praise You, Lord,\",\"and may I love You now.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0566', 566, 'Praise the name of Jesus', 'MP', 'en', '1976 Latter Rain Music/CapitolCMGPublishing.com (adm UK/Eire Song Solutions) All rights reserved. Used by permission.', '', 0, 0, 0, 1, 1, 'Praise the name of Jesus,
praise the name of Jesus,
He’s my rock, He’s my fortress,
He’s my deliverer,
in Him will I trust;
praise the name of Jesus.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0566', 'Roy Hicks');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0566', 'Roy Hicks');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0566', 'verse', 1, 0, '[\"Praise the name of Jesus,\",\"praise the name of Jesus,\",\"He’s my rock, He’s my fortress,\",\"He’s my deliverer,\",\"in Him will I trust;\",\"praise the name of Jesus.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0567', 567, 'Prayer is the soul’s sincere desire', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Prayer is the soul’s sincere desire,
uttered or unexpressed,
the motion of a hidden fire
that trembles in the breast.
Prayer is the burden of a sigh,
the falling of a tear,
the upward glancing of an eye,
when none but God is near.
Prayer is the simplest form of speech
that infant lips can try;
prayer the sublimest strains that reach
the majesty on high.
Prayer is the contrite sinner’s voice,
returning from his ways;
while angels in their songs rejoice,
and cry, ‘Behold, he prays!’
Prayer is the Christian’s vital breath,
the Christian’s native air,
his watchword at the gates of death;
he enters heaven with prayer.
No prayer is made on earth alone;
the Holy Spirit pleads;
and Jesus on the eternal throne,
for sinners intercedes.
O Thou by whom we come to God,
the life, the truth, the way,
the path of prayer Thyself hast trod;
Lord, teach us how to pray!');
