INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0568', 'verse', 2, 1, '[\"I’m justified, I’m justified,\",\"it’s just as if I’d never sinned;\",\"and once I knew such guilty fear,\",\"but now I know His peace within.\",\"Justified, I’m justified,\",\"it’s all because my Jesus died;\",\"I’m justified, I’m justified by God,\",\"hallelujah!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0568', 'verse', 3, 2, '[\"I’ll magnify, I’ll magnify,\",\"I’ll magnify His name for ever;\",\"wear the robe of righteousness\",\"and bless the name of Jesus, Saviour;\",\"magnify the One who died,\",\"the One who reigns for me on high;\",\"I’ll magnify, I’ll magnify my God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0569', 569, 'Reach out and touch the Lord', 'MP', 'en', 'Gospel Publishing House/Lorenz Publishing Co/Small Stone Media BV/Song Solutions www.songsolutions.org All rights reserved.', '', 0, 0, 0, 1, 1, 'Reach out and touch the Lord as He goes by;
you’ll find He’s not too busy to hear your heart’s cry.
He’s passing by this moment, your needs to supply;
reach out and touch the Lord as He goes by.');
