INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0570', 570, 'Reign in me', 'MP', 'en', 'Copyright 1985 Sovereign Lifestyle Music Ltd.  Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'Reign in me, sovereign Lord, reign in me,
reign in me, sovereign Lord, reign in me.
Captivate my heart,
let Your kingdom come,
establish there Your throne,
let Your will be done!
Reign in me, sovereign Lord, reign in me.
Reign in me, sovereign Lord, reign in me.');
