INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0571', 571, 'Reigning in all splendour', 'MP', 'en', '©  1984 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Reigning in all splendour –
victorious love;
Christ Jesus the Saviour,
transcendent above.
All earthly dominions
and kingdoms shall fall,
for His name is Jesus
and He is the Lord.
He is Lord, He is Lord,
He is Lord, He is Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0571', 'Dave Bilbrough');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0571', 'Dave Bilbrough');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0571', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0571', 'verse', 1, 0, '[\"Reigning in all splendour –\",\"victorious love;\",\"Christ Jesus the Saviour,\",\"transcendent above.\",\"All earthly dominions\",\"and kingdoms shall fall,\",\"for His name is Jesus\",\"and He is the Lord.\",\"He is Lord, He is Lord,\",\"He is Lord, He is Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0572', 572, 'Rejoice!', 'MP', 'en', '©  1983 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Rejoice, rejoice! Christ is in you –
the hope of glory in our hearts.
He lives, He lives!
His breath is in you.
Arise! A mighty army we arise!
Now is the time for us to march upon the land –
into our hands He will give the ground we claim;
He rides in majesty to lead us into victory,
the world shall see that Christ is Lord.
Rejoice, rejoice...
God is at work in us, His purpose to perform –
building a kingdom of power not of words;
where things impossible by faith shall be made possible:
let’s give the glory to Him now.
Rejoice, rejoice...
Though we are weak, His grace is everything we need –
we’re made of clay, but this treasure is within;
He turns our weaknesses into His opportunities,
so that the glory goes to Him.
Rejoice, rejoice...
We arise! We arise! We arise!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0572', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0572', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0572', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0572', 'chorus', 0, 0, '[\"Rejoice, rejoice! Christ is in you –\",\"the hope of glory in our hearts.\",\"He lives, He lives!\",\"His breath is in you.\",\"Arise! A mighty army we arise!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0572', 'verse', 1, 1, '[\"Now is the time for us to march upon the land –\",\"into our hands He will give the ground we claim;\",\"He rides in majesty to lead us into victory,\",\"the world shall see that Christ is Lord.\",\"Rejoice, rejoice...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0572', 'verse', 2, 2, '[\"God is at work in us, His purpose to perform –\",\"building a kingdom of power not of words;\",\"where things impossible by faith shall be made possible:\",\"let’s give the glory to Him now.\",\"Rejoice, rejoice...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0572', 'verse', 3, 3, '[\"Though we are weak, His grace is everything we need –\",\"we’re made of clay, but this treasure is within;\",\"He turns our weaknesses into His opportunities,\",\"so that the glory goes to Him.\",\"Rejoice, rejoice...\",\"We arise! We arise! We arise!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0573', 573, 'Rejoice and be glad', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Rejoice and be glad! the Redeemer has come:
go, look on His cradle, His cross, and His tomb.
Sound His praises, tell the story of Him who was slain;
sound His praises, tell with gladness He now lives again.
Rejoice and be glad! it is sunshine at last;
the clouds have departed, the shadows are past.
Sound His praises...
Rejoice and be glad! for the blood has been shed;
redemption is finished, the price has been paid.
Sound His praises...
Rejoice and be glad! now the pardon is free;
the just for the unjust has died on the tree.
Sound His praises...
Rejoice and be glad! for the Lamb that was slain
o’er death is triumphant, and now lives again.
Sound His praises...
Rejoice and be glad! for our King is on high;
He pleads now for us on His throne in the sky.
Sound His praises...
Rejoice and be glad! for He’s coming again;
He’ll come in great glory, the Lamb that was slain.
Sound His praises...');
