INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0574', 574, 'Rejoice, rejoice, rejoice', 'MP', 'en', 'Copyright 1986 Sovereign Lifestyle Music Ltd. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'Rejoice, rejoice, rejoice,
rejoice, rejoice, rejoice;
my soul rejoices in the Lord.
Rejoice...
My soul magnifies the Lord,
and my spirit rejoices in God my Saviour;
my soul magnifies the Lord,
and my spirit rejoices in my God.
Rejoice...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0574', 'Chris Bowater');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0574', 'Chris Bowater');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0574', 'verse', 1, 0, '[\"Rejoice, rejoice, rejoice,\",\"rejoice, rejoice, rejoice;\",\"my soul rejoices in the Lord.\",\"Rejoice...\",\"My soul magnifies the Lord,\",\"and my spirit rejoices in God my Saviour;\",\"my soul magnifies the Lord,\",\"and my spirit rejoices in my God.\",\"Rejoice...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0575', 575, 'Rejoice, the Lord is King!', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Rejoice, the Lord is King!
your Lord and King adore;
mortals, give thanks and sing,
and triumph evermore:
Lift up your heart, lift up your voice;
rejoice, again I say, rejoice.
Jesus the Saviour reigns,
the God of truth and love;
when He had purged our stains,
He took His seat above:
Lift up your heart...
His kingdom cannot fail,
He rules o’er earth and heaven;
the keys of death and hell
are to our Jesus given:
Lift up your heart...
He sits at God’s right hand,
till all His foes submit,
and bow to His command,
and fall beneath His feet:
Lift up your heart...
Rejoice in glorious hope;
Jesus the Judge shall come,
and take His servants up
to their eternal home:
We soon shall hear the archangel’s voice;
the trump of God shall sound, rejoice!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0575', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0575', 'George Frideric Handel');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0575', 'verse', 1, 0, '[\"Rejoice, the Lord is King!\",\"your Lord and King adore;\",\"mortals, give thanks and sing,\",\"and triumph evermore:\",\"Lift up your heart, lift up your voice;\",\"rejoice, again I say, rejoice.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0575', 'verse', 2, 1, '[\"Jesus the Saviour reigns,\",\"the God of truth and love;\",\"when He had purged our stains,\",\"He took His seat above:\",\"Lift up your heart...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0575', 'verse', 3, 2, '[\"His kingdom cannot fail,\",\"He rules o’er earth and heaven;\",\"the keys of death and hell\",\"are to our Jesus given:\",\"Lift up your heart...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0575', 'verse', 4, 3, '[\"He sits at God’s right hand,\",\"till all His foes submit,\",\"and bow to His command,\",\"and fall beneath His feet:\",\"Lift up your heart...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0575', 'verse', 5, 4, '[\"Rejoice in glorious hope;\",\"Jesus the Judge shall come,\",\"and take His servants up\",\"to their eternal home:\",\"We soon shall hear the archangel’s voice;\",\"the trump of God shall sound, rejoice!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0576', 576, 'Rejoice, the Lord is risen!', 'MP', 'en', '1986 M C and M M Austin', '', 0, 0, 0, 1, 1, 'Rejoice, the Lord is risen!
He is the King of glory;
mighty Redeemer,
He has made us His own:
rejoice, the Lord is risen!
opened, the gate of heaven:
bow down before Him
for He comes to claim His own!
Glory to the King of kings!
Glory to the Lord of lords!
Jesus, we proclaim
that You are Lord enthroned in majesty!
Glory to the King of kings!
Glory to the Lord of lords!
Jesus, You are reigning
now on high for evermore!
Rejoice, the Lord is risen!
We are His holy nation,
ransomed, forgiven,
washed in His precious blood:
rejoice, the Lord is risen!
Worthy His new creation,
perfect and spotless,
as the Lamb upon the throne.
Glory to the King...
Rejoice, the Lord is risen!
Blessing and honour give Him;
wisdom, authority,
belong to His name:
rejoice, the Lord is risen!
Angels and saints adore Him,
worship and praise Him,
singing, ‘Jesus Christ is Lord!’
Glory to the King...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0576', 'Moira Austin');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0576', 'Moira Austin');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0576', 'verse', 1, 0, '[\"Rejoice, the Lord is risen!\",\"He is the King of glory;\",\"mighty Redeemer,\",\"He has made us His own:\",\"rejoice, the Lord is risen!\",\"opened, the gate of heaven:\",\"bow down before Him\",\"for He comes to claim His own!\",\"Glory to the King of kings!\",\"Glory to the Lord of lords!\",\"Jesus, we proclaim\",\"that You are Lord enthroned in majesty!\",\"Glory to the King of kings!\",\"Glory to the Lord of lords!\",\"Jesus, You are reigning\",\"now on high for evermore!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0576', 'verse', 2, 1, '[\"Rejoice, the Lord is risen!\",\"We are His holy nation,\",\"ransomed, forgiven,\",\"washed in His precious blood:\",\"rejoice, the Lord is risen!\",\"Worthy His new creation,\",\"perfect and spotless,\",\"as the Lamb upon the throne.\",\"Glory to the King...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0576', 'verse', 3, 2, '[\"Rejoice, the Lord is risen!\",\"Blessing and honour give Him;\",\"wisdom, authority,\",\"belong to His name:\",\"rejoice, the Lord is risen!\",\"Angels and saints adore Him,\",\"worship and praise Him,\",\"singing, ‘Jesus Christ is Lord!’\",\"Glory to the King...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0577', 577, 'Rejoice in the Lord always', 'MP', 'en', 'control', '', 0, 0, 0, 1, 1, 'Rejoice in the Lord always,
and again I say rejoice!
Rejoice in the Lord always,
and again I say rejoice!
Rejoice, rejoice, and again I say rejoice!
Rejoice, rejoice, and again I say rejoice!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0577', 'verse', 1, 0, '[\"Rejoice in the Lord always,\",\"and again I say rejoice!\",\"Rejoice in the Lord always,\",\"and again I say rejoice!\",\"Rejoice, rejoice, and again I say rejoice!\",\"Rejoice, rejoice, and again I say rejoice!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0578', 578, 'Revive Thy work, O Lord', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Revive Thy work, O Lord,
Thy mighty arm make bare;
speak with the voice that wakes the dead
and make Thy people hear.
Revive Thy work, O Lord,
disturb this sleep of death;
quicken the smouldering embers now
by Thine almighty breath.
Revive Thy work, O Lord,
create soul-thirst for Thee;
and hungering for the bread of life
O may our spirits be!
Revive Thy work, O Lord,
exalt Thy precious name;
and, by the Holy Ghost, our love
for Thee and Thine inflame.
Revive Thy work, O Lord,
give pentecostal showers;
the glory shall be all Thine own,
the blessing, Lord, be ours.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0578', 'Albert Midlane');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0578', 'William Henry Havergal');
