INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0578', 'verse', 2, 1, '[\"Revive Thy work, O Lord,\",\"disturb this sleep of death;\",\"quicken the smouldering embers now\",\"by Thine almighty breath.\"]');
