INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0578', 'verse', 4, 3, '[\"Revive Thy work, O Lord,\",\"exalt Thy precious name;\",\"and, by the Holy Ghost, our love\",\"for Thee and Thine inflame.\"]');
