INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0579', 579, 'Restore, O Lord', 'MP', 'en', '©  1981 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Restore, O Lord,
the honour of Your name!
In works of sovereign power
come shake the earth again,
that men may see,
and come with reverent fear
to the living God,
whose kingdom shall outlast the years.
Restore, O Lord,
in all the earth Your fame,
and in our time revive
the Church that bears Your name,
and in Your anger,
Lord, remember mercy,
O living God,
whose mercy shall outlast the years.
Bend us, O Lord,
where we are hard and cold,
in Your refiner’s fire;
come purify the gold:
though suffering comes,
and evil crouches near,
still our living God
is reigning, He is reigning here.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0579', 'Graham Kendrick');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0579', 'Chris Rolinson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0579', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0579', 'Chris Rolinson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0579', 'verse', 1, 0, '[\"Restore, O Lord,\",\"the honour of Your name!\",\"In works of sovereign power\",\"come shake the earth again,\",\"that men may see,\",\"and come with reverent fear\",\"to the living God,\",\"whose kingdom shall outlast the years.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0579', 'verse', 2, 1, '[\"Restore, O Lord,\",\"in all the earth Your fame,\",\"and in our time revive\",\"the Church that bears Your name,\",\"and in Your anger,\",\"Lord, remember mercy,\",\"O living God,\",\"whose mercy shall outlast the years.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0579', 'verse', 3, 2, '[\"Bend us, O Lord,\",\"where we are hard and cold,\",\"in Your refiner’s fire;\",\"come purify the gold:\",\"though suffering comes,\",\"and evil crouches near,\",\"still our living God\",\"is reigning, He is reigning here.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0580', 580, 'Ride on, ride on in majesty', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Ride on, ride on in majesty!
Hark, all the tribes, ‘Hosanna!’ cry,
O Saviour meek, pursue Your road
with palms and scattered garments strowed.
Ride on, ride on in majesty!
in lowly pomp ride on to die:
O Christ, Your triumphs now begin
o’er captive death and conquered sin.
Ride on, ride on in majesty!
The angel armies of the sky
look down with sad and wondering eyes
to see the approaching sacrifice.
Ride on, ride on in majesty!
Your last and fiercest strife is nigh;
the Father on His sapphire throne
awaits His own anointed Son.
Ride on, ride on in majesty!
in lowly pomp ride on to die;
bow Your meek head to mortal pain,
then take, O God, Your power, and reign.');
