INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0580', 'verse', 2, 1, '[\"Ride on, ride on in majesty!\",\"in lowly pomp ride on to die:\",\"O Christ, Your triumphs now begin\",\"o’er captive death and conquered sin.\"]');
