INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0581', 581, 'River, wash over me', 'MP', 'en', '©  1980 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'River, wash over me,
cleanse me and make me new;
bathe me, refresh me and fill me anew –
river, wash over me.
Spirit, watch over me,
lead me to Jesus’ feet;
cause me to worship and fill me anew –
Spirit, watch over me.
Jesus, rule over me,
reign over all my heart;
teach me to praise You and fill me anew –
Jesus, rule over me.');
