INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0583', 583, 'Safe in the shadow of the Lord', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Safe in the shadow of the Lord
beneath His hand and power,
I trust in Him,
I trust in Him,
my fortress and my tower.
My hope is set on God alone
though Satan spreads his snare;
I trust in Him,
I trust in Him,
to keep me in His care.
From fears and phantoms of the night,');
