INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0583', 'verse', 2, 1, '[\"My hope is set on God alone\",\"though Satan spreads his snare;\",\"I trust in Him,\",\"I trust in Him,\",\"to keep me in His care.\"]');
