INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0584', 584, 'Saviour, again to Thy dear name', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Saviour, again to Thy dear name we raise
with one accord our parting hymn of praise;
we stand to bless Thee ere our worship cease,
then, lowly kneeling, wait Thy word of peace.
Grant us Thy peace upon our homeward way;
with Thee began, with Thee shall end the day;
guard Thou the lips from sin, the hearts from shame,
that in this house have called upon Thy name.
Grant us Thy peace, Lord, through the coming night;
turn Thou for us its darkness into light;');
