INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0589', 'verse', 1, 0, '[\"See Him lying on a bed of straw:\",\"a draughty stable with an open door;\",\"Mary cradling the babe she bore –\",\"the Prince of glory is His name.\",\"O now carry me to Bethlehem\",\"to see the Lord appear to men –\",\"just as poor as was the stable then,\",\"the Prince of glory when He came.\"]');
