INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0590', 590, 'Seek ye first', 'MP', 'en', '1972 CCCM Music/Maranatha!Music/Universal Music /Print licence UK Song Solutions Daybreak  www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Seek ye first the kingdom of God,
and His righteousness,
and all these things shall be added unto you.
Allelu, alleluia.
Seek ye first...
Man shall not live by bread alone,
but by every word
that proceeds from the mouth of God.
Allelu, alleluia.
Man shall not...
Ask and it shall be given unto you,
seek and ye shall find;
knock and the door shall be opened up to you.
Allelu, alleluia.
Ask and it shall...');
