INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0591', 591, 'Peace like a river', 'MP', 'en', '©  1978 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Seek ye the Lord, all ye people,
turn to Him while He is near;
let the wicked forsake his own way,
and call on Him while He may hear.
Ho, everyone who is thirsty,
come to the waters of life;
come and drink of the milk and the wine,
come without money and price.
And there is peace like a river,
and glory divine,
if you’ll come to the water,
if you’ll taste of His wine.
There is love ever flowing,
and joy ever full;
and there’s life everlasting
for us all.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0591', 'Joan Parsons');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0591', 'Joan Parsons');
