INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0591', 'verse', 1, 0, '[\"Seek ye the Lord, all ye people,\",\"turn to Him while He is near;\",\"let the wicked forsake his own way,\",\"and call on Him while He may hear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0591', 'verse', 2, 1, '[\"Ho, everyone who is thirsty,\",\"come to the waters of life;\",\"come and drink of the milk and the wine,\",\"come without money and price.\",\"And there is peace like a river,\",\"and glory divine,\",\"if you’ll come to the water,\",\"if you’ll taste of His wine.\",\"There is love ever flowing,\",\"and joy ever full;\",\"and there’s life everlasting\",\"for us all.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0592', 592, 'See Him on the cross', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'See Him on the cross of shame
dying for me,
bearing all my guilt and pain,
dying for me.
And how I love You,
Jesus my Redeemer;
You gave Your life for me, O Lord,
now I give my life to You.
Jesus lives, Jesus lives,
Jesus lives in me:
I will praise Your name.
They laid Him in a garden tomb,
and sealed it with a stone.
Mary wept her tears of grief –
her precious Lord had gone:
‘And how I love You,
Jesus my Redeemer’;
then she looked – the stone was rolled away –
He had triumphed over death.
Jesus lives...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0592', 'Ruth Hooke');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0592', 'Ruth Hooke');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0592', 'verse', 1, 0, '[\"See Him on the cross of shame\",\"dying for me,\",\"bearing all my guilt and pain,\",\"dying for me.\",\"And how I love You,\",\"Jesus my Redeemer;\",\"You gave Your life for me, O Lord,\",\"now I give my life to You.\",\"Jesus lives, Jesus lives,\",\"Jesus lives in me:\",\"I will praise Your name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0592', 'verse', 2, 1, '[\"They laid Him in a garden tomb,\",\"and sealed it with a stone.\",\"Mary wept her tears of grief –\",\"her precious Lord had gone:\",\"‘And how I love You,\",\"Jesus my Redeemer’;\",\"then she looked – the stone was rolled away –\",\"He had triumphed over death.\",\"Jesus lives...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0593', 593, 'Send forth the gospel', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Send forth the gospel! Let it run
southward and northward, east and west:
tell all the earth Christ died and lives,
He offers pardon, life, and rest.
Send forth Your gospel, mighty Lord!
Out of the chaos bring to birth
Your own creation’s promised hope;
the better days of heaven on earth.
Send forth Your gospel, gracious Lord!
Yours was the blood for sinners shed;
Your voice still pleads in human hearts;
to You may all Your sheep be led.
Send forth Your gospel, holy Lord!
Kindle in us love’s sacred flame;
love giving all and grudging naught
for Jesus’ sake, in Jesus’ name.
Send forth the gospel! Tell it out!
Go, brothers, at the Master’s call;
prepare His way, who comes to reign
the King of kings and Lord of all.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0593', 'Henry Elliott Fox');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0593', 'William Henry Gladstone');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0593', 'verse', 1, 0, '[\"Send forth the gospel! Let it run\",\"southward and northward, east and west:\",\"tell all the earth Christ died and lives,\",\"He offers pardon, life, and rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0593', 'verse', 2, 1, '[\"Send forth Your gospel, mighty Lord!\",\"Out of the chaos bring to birth\",\"Your own creation’s promised hope;\",\"the better days of heaven on earth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0593', 'verse', 3, 2, '[\"Send forth Your gospel, gracious Lord!\",\"Yours was the blood for sinners shed;\",\"Your voice still pleads in human hearts;\",\"to You may all Your sheep be led.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0593', 'verse', 4, 3, '[\"Send forth Your gospel, holy Lord!\",\"Kindle in us love’s sacred flame;\",\"love giving all and grudging naught\",\"for Jesus’ sake, in Jesus’ name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0593', 'verse', 5, 4, '[\"Send forth the gospel! Tell it out!\",\"Go, brothers, at the Master’s call;\",\"prepare His way, who comes to reign\",\"the King of kings and Lord of all.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0594', 594, 'Send me out from here', 'MP', 'en', 'Harper Collins Religious (admin. by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Send me out from here, Lord,
to serve a world in need;
may I know no man by the coat he wears,
but the heart that Jesus sees.
And may the light of Your face
shine upon me, Lord –
You have filled my heart with the greatest joy
and my cup is overflowing.
Go now and carry the news to all creation –
every race and every tongue;
take no purse with you, take nothing to eat
for He will supply your every need.
Send me out...
Go now, bearing the light, living for others,
fearlessly walking into the night;
take no thought for your lives – like lambs among wolves –
full of the Spirit, ready to die.
f*(fCSend me out...f*r
f*(fC...nd my cupf*r
f*(fCis overflowing with joy!f*r');
