INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0594', 'verse', 1, 1, '[\"Go now and carry the news to all creation –\",\"every race and every tongue;\",\"take no purse with you, take nothing to eat\",\"for He will supply your every need.\",\"Send me out...\"]');
