INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0595', 595, 'Set my spirit free', 'MP', 'en', 'control                        arrangement: ? 1987 Phil Burt', '', 0, 0, 0, 1, 1, 'Set my spirit free
that I might worship You;
set my spirit free
that I might praise Your name.
Let all bondage go
and let deliverance flow;
set my spirit free to worship You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0595', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0595', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0595', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0595', 'verse', 1, 0, '[\"Set my spirit free\",\"that I might worship You;\",\"set my spirit free\",\"that I might praise Your name.\",\"Let all bondage go\",\"and let deliverance flow;\",\"set my spirit free to worship You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0596', 596, 'Show Your power, O Lord', 'MP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Show Your power, O Lord,
demonstrate the justice of Your kingdom;
prove Your mighty word,
vindicate Your name
before a watching world.
Awesome are Your deeds, O Lord –
renew them for this hour.
Show Your power, O Lord,
among the people now.
Show Your power, O Lord,
cause Your Church to rise and take action;
let all fear be gone;
powers of the age to come
are breaking through.
We Your people are ready to serve,
to arise and to obey.
Show Your power, O Lord,
and set the people –
show Your power, O Lord,
and set the people –
show Your power, O Lord,
and set the people free!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0596', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0596', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0596', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0596', 'verse', 1, 0, '[\"Show Your power, O Lord,\",\"demonstrate the justice of Your kingdom;\",\"prove Your mighty word,\",\"vindicate Your name\",\"before a watching world.\",\"Awesome are Your deeds, O Lord –\",\"renew them for this hour.\",\"Show Your power, O Lord,\",\"among the people now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0596', 'verse', 2, 1, '[\"Show Your power, O Lord,\",\"cause Your Church to rise and take action;\",\"let all fear be gone;\",\"powers of the age to come\",\"are breaking through.\",\"We Your people are ready to serve,\",\"to arise and to obey.\",\"Show Your power, O Lord,\",\"and set the people –\",\"show Your power, O Lord,\",\"and set the people –\",\"show Your power, O Lord,\",\"and set the people free!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0597', 597, 'Silent night', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Silent night, holy night!
Sleeps the world; hid from sight,
Mary and Joseph in stable bare
watched o’er the child belovèd and fair
sleeping in heavenly rest,
sleeping in heavenly rest.
Silent night, holy night!
Shepherds first saw the light,
heard resounding clear and long,
far and near, the angel-song:
‘Christ the Redeemer is here,
Christ the Redeemer is here.’
Silent night, holy night!
Son of God, O how bright
love is smiling from Your face!
Strikes for us now the hour of grace,
Saviour, since You are born,
Saviour, since You are born.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0597', 'Joseph Mohr');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0597', 'Franz X Gruber');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0597', 'verse', 1, 0, '[\"Silent night, holy night!\",\"Sleeps the world; hid from sight,\",\"Mary and Joseph in stable bare\",\"watched o’er the child belovèd and fair\",\"sleeping in heavenly rest,\",\"sleeping in heavenly rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0597', 'verse', 2, 1, '[\"Silent night, holy night!\",\"Shepherds first saw the light,\",\"heard resounding clear and long,\",\"far and near, the angel-song:\",\"‘Christ the Redeemer is here,\",\"Christ the Redeemer is here.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0597', 'verse', 3, 2, '[\"Silent night, holy night!\",\"Son of God, O how bright\",\"love is smiling from Your face!\",\"Strikes for us now the hour of grace,\",\"Saviour, since You are born,\",\"Saviour, since You are born.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0598', 598, 'Peter and John went to pray', 'MP', 'en', 'control                        arrangement: ? 1974 Celebration / kingswaysongs.com. tym@kingsway.co.uk. For Europe and Commonwealth (excl. Canada, Australasia and Africa). Used by permission.', '', 0, 0, 0, 1, 0, 'Peter and John went to pray,
they met a lame man on the way;
he asked for alms and held out his palms,
and this is what Peter did say:
‘Silver and gold have I none,
but such as I have give I thee.
In the name of Jesus Christ of Nazareth,
rise up and walk!’
He went walking and leaping and praising God,
walking and leaping and praising God.
‘In the name of Jesus Christ of Nazareth,
rise up and walk!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0598', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0598', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0598', 'Betty Pulkingham');
