INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0598', 'verse', 2, 1, '[\"‘Silver and gold have I none,\",\"but such as I have give I thee.\",\"In the name of Jesus Christ of Nazareth,\",\"rise up and walk!’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0598', 'verse', 3, 2, '[\"He went walking and leaping and praising God,\",\"walking and leaping and praising God.\",\"‘In the name of Jesus Christ of Nazareth,\",\"rise up and walk!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0599', 599, 'Sing a new song to the Lord', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Sing a new song to the Lord,
He to whom wonders belong;
rejoice in His triumph and tell of His power,
O sing to the Lord a new song!
Now to the ends of the earth,
see His salvation is shown;
and still He remembers His mercy and truth,
unchanging in love to His own.
Sing a new song and rejoice,
publish His praises abroad;
let voices in chorus, with trumpet and horn,
resound for the joy of the Lord!
Join with the hills and the sea,
thunders of praise to prolong;
in judgement and justice He comes to the earth,
O sing to the Lord a new song!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0599', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0599', 'David G Wilson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0599', 'verse', 1, 0, '[\"Sing a new song to the Lord,\",\"He to whom wonders belong;\",\"rejoice in His triumph and tell of His power,\",\"O sing to the Lord a new song!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0599', 'verse', 2, 1, '[\"Now to the ends of the earth,\",\"see His salvation is shown;\",\"and still He remembers His mercy and truth,\",\"unchanging in love to His own.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0599', 'verse', 3, 2, '[\"Sing a new song and rejoice,\",\"publish His praises abroad;\",\"let voices in chorus, with trumpet and horn,\",\"resound for the joy of the Lord!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0599', 'verse', 4, 3, '[\"Join with the hills and the sea,\",\"thunders of praise to prolong;\",\"in judgement and justice He comes to the earth,\",\"O sing to the Lord a new song!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0600', 600, 'Sing to God new songs of worship', 'MP', 'en', 'Michael A Baughen /The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'Sing to God new songs of worship –
all His deeds are marvellous;
He has brought salvation to us
with His hand and holy arm:
He has shown to all the nations
righteousness and saving power;
He recalled His truth and mercy
to His people Israel.
Sing to God new songs of worship –
earth has seen His victory;
let the lands of earth be joyful
praising Him with thankfulness:
sound upon the harp His praises,
play to Him with melody;
let the trumpets sound His triumph,
show your joy to God the King!
Sing to God new songs of worship –
let the sea now make a noise;
all on earth and in the waters
sound your praises to the Lord:
let the hills be joyful together,
let the rivers clap their hands,
for with righteousness and justice
He will come to judge the earth.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0600', 'Michael Baughen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0600', 'Ludwig van Beethoven');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0600', 'verse', 1, 0, '[\"Sing to God new songs of worship –\",\"all His deeds are marvellous;\",\"He has brought salvation to us\",\"with His hand and holy arm:\",\"He has shown to all the nations\",\"righteousness and saving power;\",\"He recalled His truth and mercy\",\"to His people Israel.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0600', 'verse', 2, 1, '[\"Sing to God new songs of worship –\",\"earth has seen His victory;\",\"let the lands of earth be joyful\",\"praising Him with thankfulness:\",\"sound upon the harp His praises,\",\"play to Him with melody;\",\"let the trumpets sound His triumph,\",\"show your joy to God the King!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0600', 'verse', 3, 2, '[\"Sing to God new songs of worship –\",\"let the sea now make a noise;\",\"all on earth and in the waters\",\"sound your praises to the Lord:\",\"let the hills be joyful together,\",\"let the rivers clap their hands,\",\"for with righteousness and justice\",\"He will come to judge the earth.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0601', 601, 'Sing alleluia to the Lord', 'MP', 'en', '1974 Linda Stassen/New Song Ministries, PO Box 11662, Costa Mesa, CA 92627, USA', '', 0, 0, 0, 1, 1, 'Sing alleluia to the Lord,
sing alleluia to the Lord,
sing alleluia, sing alleluia,
sing alleluia to the Lord!
Jesus is risen from the dead,
Jesus is risen from the dead,
Jesus is risen, Jesus is risen,
Jesus is risen from the dead!
Jesus is Lord of heaven and earth,
Jesus is Lord of heaven and earth,
Jesus is Lord, Jesus is Lord,
Jesus is Lord of heaven and earth.
Jesus is coming for His own,
Jesus is coming for His own,
Jesus is coming, Jesus is coming,
Jesus is coming for His own.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0601', 'Linda Stassen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0601', 'Linda Stassen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0601', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0601', 'verse', 1, 0, '[\"Sing alleluia to the Lord,\",\"sing alleluia to the Lord,\",\"sing alleluia, sing alleluia,\",\"sing alleluia to the Lord!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0601', 'verse', 2, 1, '[\"Jesus is risen from the dead,\",\"Jesus is risen from the dead,\",\"Jesus is risen, Jesus is risen,\",\"Jesus is risen from the dead!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0601', 'verse', 3, 2, '[\"Jesus is Lord of heaven and earth,\",\"Jesus is Lord of heaven and earth,\",\"Jesus is Lord, Jesus is Lord,\",\"Jesus is Lord of heaven and earth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0601', 'verse', 4, 3, '[\"Jesus is coming for His own,\",\"Jesus is coming for His own,\",\"Jesus is coming, Jesus is coming,\",\"Jesus is coming for His own.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0602', 602, 'Sing we the King', 'MP', 'en', 'control', '', 0, 0, 0, 1, 1, 'Sing we the King who is coming to reign,
glory to Jesus, the Lamb that was slain;
life and salvation His empire shall bring,
joy to the nations when Jesus is King.
Come, let us sing: praise to our King.
Jesus our King, Jesus our King:
this is our song, who to Jesus belong:
glory to Jesus, to Jesus our King.
All men shall dwell in His marvellous light,
races long severed His love shall unite;
justice and truth from His sceptre shall spring,
wrong shall be ended when Jesus is King.
Come, let us sing...
All shall be well in His kingdom of peace,
freedom shall flourish and wisdom increase;
foe shall be friend when His triumph we sing,
sword shall be sickle when Jesus is King.
Come, let us sing...
Souls shall be saved from the burden of sin;
doubt shall not darken His witness within;
hell hath no terrors, and death hath no sting;
love is victorious, when Jesus is King.
Come, let us sing...
Kingdom of Christ, for thy coming we pray,
hasten, O Father, the dawn of the day;
when this new song Thy creation shall sing,
Satan is vanquished and Jesus is King.
Come, let us sing...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0602', 'Charles Silvester Horne');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0602', 'Charles Hutchinson Gabriel');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0602', 'verse', 1, 0, '[\"Sing we the King who is coming to reign,\",\"glory to Jesus, the Lamb that was slain;\",\"life and salvation His empire shall bring,\",\"joy to the nations when Jesus is King.\",\"Come, let us sing: praise to our King.\",\"Jesus our King, Jesus our King:\",\"this is our song, who to Jesus belong:\",\"glory to Jesus, to Jesus our King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0602', 'verse', 2, 1, '[\"All men shall dwell in His marvellous light,\",\"races long severed His love shall unite;\",\"justice and truth from His sceptre shall spring,\",\"wrong shall be ended when Jesus is King.\",\"Come, let us sing...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0602', 'verse', 3, 2, '[\"All shall be well in His kingdom of peace,\",\"freedom shall flourish and wisdom increase;\",\"foe shall be friend when His triumph we sing,\",\"sword shall be sickle when Jesus is King.\",\"Come, let us sing...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0602', 'verse', 4, 3, '[\"Souls shall be saved from the burden of sin;\",\"doubt shall not darken His witness within;\",\"hell hath no terrors, and death hath no sting;\",\"love is victorious, when Jesus is King.\",\"Come, let us sing...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0602', 'verse', 5, 4, '[\"Kingdom of Christ, for thy coming we pray,\",\"hasten, O Father, the dawn of the day;\",\"when this new song Thy creation shall sing,\",\"Satan is vanquished and Jesus is King.\",\"Come, let us sing...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0603', 603, 'So freely', 'MP', 'en', '©  1983 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'So freely
flows the endless love You give to me;
so freely,
not dependent on my part.
As I am reaching out,
reveal the love within Your heart;
as I am reaching out,
reveal the love within Your heart.
Completely –
that’s the way You give Your love to me,
completely,
not dependent on my part.
As I am reaching out,
reveal the love within Your heart,
as I am reaching out,
reveal the love within Your heart.
So easy,
I receive the love You give to me;
so easy,
not dependent on my part.
Flowing out to me –
the love within Your heart;
flowing out to me –
the love within Your heart.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0603', 'Dave Bilbrough');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0603', 'Dave Bilbrough');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0603', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0603', 'verse', 1, 0, '[\"So freely\",\"flows the endless love You give to me;\",\"so freely,\",\"not dependent on my part.\",\"As I am reaching out,\",\"reveal the love within Your heart;\",\"as I am reaching out,\",\"reveal the love within Your heart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0603', 'verse', 2, 1, '[\"Completely –\",\"that’s the way You give Your love to me,\",\"completely,\",\"not dependent on my part.\",\"As I am reaching out,\",\"reveal the love within Your heart,\",\"as I am reaching out,\",\"reveal the love within Your heart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0603', 'verse', 3, 2, '[\"So easy,\",\"I receive the love You give to me;\",\"so easy,\",\"not dependent on my part.\",\"Flowing out to me –\",\"the love within Your heart;\",\"flowing out to me –\",\"the love within Your heart.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0604', 604, 'Soldiers of Christ, arise', 'MP', 'en', 'Bernard Naylor/Copyright control', '', 0, 0, 0, 1, 1, 'Soldiers of Christ, arise,
and put your armour on,
strong in the strength which God supplies
through His eternal Son.
Strong in the Lord of hosts,
and in His mighty power;
who in the strength of Jesus trusts
is more than conqueror.
Stand then in His great might,
with all His strength endued;
and take, to arm you for the fight,
the panoply of God:
to keep your armour bright,
attend with constant care,
still walking in your Captain’s sight
and watching unto prayer.
From strength to strength go on,
wrestle and fight and pray;
tread all the powers of darkness down
and win the well-fought day.
That, having all things done,
and all your conflicts past,
ye may o’ercome through Christ alone,
and stand entire at last.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0604', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0604', 'Edward Woodall Naylor');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0604', 'verse', 1, 0, '[\"Soldiers of Christ, arise,\",\"and put your armour on,\",\"strong in the strength which God supplies\",\"through His eternal Son.\",\"Strong in the Lord of hosts,\",\"and in His mighty power;\",\"who in the strength of Jesus trusts\",\"is more than conqueror.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0604', 'verse', 2, 1, '[\"Stand then in His great might,\",\"with all His strength endued;\",\"and take, to arm you for the fight,\",\"the panoply of God:\",\"to keep your armour bright,\",\"attend with constant care,\",\"still walking in your Captain’s sight\",\"and watching unto prayer.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0604', 'verse', 3, 2, '[\"From strength to strength go on,\",\"wrestle and fight and pray;\",\"tread all the powers of darkness down\",\"and win the well-fought day.\",\"That, having all things done,\",\"and all your conflicts past,\",\"ye may o’ercome through Christ alone,\",\"and stand entire at last.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0605', 605, 'Soon, and very soon', 'MP', 'en', '1976 Crouch Music/Bud John Songs/CapitolCMGPublishing.com (Adm UK/Eire Song Solutions www.songsolutions.org) All rights reserved. Used by permission.', '', 0, 0, 0, 1, 1, 'Soon, and very soon,
we are going to see the King;
soon, and very soon,
we are going to see the King;
soon, and very soon,
we are going to see the King;
alleluia, alleluia,
we’re going to see the King!
No more crying there...
alleluia...
No more dying there...
alleluia...
Alleluia, alleluia, alleluia, alleluia.
Soon and very soon...
alleluia...
Alleluia, alleluia, alleluia, alleluia.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0605', 'Andrae Crouch');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0605', 'Andrae Crouch');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0605', 'verse', 1, 0, '[\"Soon, and very soon,\",\"we are going to see the King;\",\"soon, and very soon,\",\"we are going to see the King;\",\"soon, and very soon,\",\"we are going to see the King;\",\"alleluia, alleluia,\",\"we’re going to see the King!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0605', 'verse', 2, 1, '[\"No more crying there...\",\"alleluia...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0605', 'verse', 3, 2, '[\"No more dying there...\",\"alleluia...\",\"Alleluia, alleluia, alleluia, alleluia.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0605', 'verse', 4, 3, '[\"Soon and very soon...\",\"alleluia...\",\"Alleluia, alleluia, alleluia, alleluia.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0606', 606, 'Soften my heart', 'MP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Soften my heart, Lord, soften my heart;');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0606', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0606', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0606', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0606', 'verse', 1, 0, '[\"Soften my heart, Lord, soften my heart;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0607', 607, 'Souls of men, why will ye scatter', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Souls of men, why will ye scatter
like a crowd of frightened sheep?
Foolish hearts, why will ye wander');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0607', 'Frederick William Faber');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0607', 'John Stainer');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0607', 'verse', 1, 0, '[\"Souls of men, why will ye scatter\",\"like a crowd of frightened sheep?\",\"Foolish hearts, why will ye wander\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0608', 608, 'Speak, Lord, in the stillness', 'MP', 'en', 'SIM (incorporating AEF)', '', 0, 0, 0, 1, 1, 'Speak, Lord, in the stillness,
while I wait on Thee;
hushed my heart to listen
in expectancy.
Speak, O blessèd Master,
in this quiet hour;
let me see Thy face, Lord,
feel Thy touch of power.
For the words Thou speakest,
they are life indeed;
living bread from heaven,
now my spirit feed!
All to Thee is yielded,
I am not my own;
blissful, glad surrender –
I am Thine alone.
Speak, Thy servant heareth!
be not silent, Lord;
waits my soul upon Thee
for the quickening word!
Fill me with the knowledge
of Thy glorious will;
all Thine own good pleasure
in Thy child fulfil.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0608', 'Emily Mary Crawford');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0608', 'Harold Green');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0608', 'verse', 1, 0, '[\"Speak, Lord, in the stillness,\",\"while I wait on Thee;\",\"hushed my heart to listen\",\"in expectancy.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0608', 'verse', 2, 1, '[\"Speak, O blessèd Master,\",\"in this quiet hour;\",\"let me see Thy face, Lord,\",\"feel Thy touch of power.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0608', 'verse', 3, 2, '[\"For the words Thou speakest,\",\"they are life indeed;\",\"living bread from heaven,\",\"now my spirit feed!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0608', 'verse', 4, 3, '[\"All to Thee is yielded,\",\"I am not my own;\",\"blissful, glad surrender –\",\"I am Thine alone.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0608', 'verse', 5, 4, '[\"Speak, Thy servant heareth!\",\"be not silent, Lord;\",\"waits my soul upon Thee\",\"for the quickening word!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0608', 'verse', 6, 5, '[\"Fill me with the knowledge\",\"of Thy glorious will;\",\"all Thine own good pleasure\",\"in Thy child fulfil.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0609', 609, 'Spirit of God', 'MP', 'en', 'Copyright 1978 Sovereign Lifestyle Music Ltd. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'Spirit of God, show me Jesus;
remove the darkness, let truth shine through.
Spirit of God, show me Jesus;
reveal the fulness of His love to me!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0609', 'Chris Bowater');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0609', 'Chris Bowater');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0609', 'verse', 1, 0, '[\"Spirit of God, show me Jesus;\",\"remove the darkness, let truth shine through.\",\"Spirit of God, show me Jesus;\",\"reveal the fulness of His love to me!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0610', 610, 'Spirit of God divine', 'MP', 'en', '1984 Colin Preston, 81 Howth Drive, Woodley, Reading, Berkshire, UK', '', 0, 0, 0, 1, 1, 'Spirit of God divine,
fill this heart of mine
with holy flame,
to praise the name
of Jesus my Lord.
Fill me again,
fill me again,
fill me again,
O Spirit of the Lord.
Spirit of God divine,
fill this mouth of mine
with holy praise,
to set the earth ablaze
and glorify Your name.
Fill me again...
Spirit of God divine,
take this heart of mine
to Your throne this day;
help me, I pray,
my offering to give.
Fill me again...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0610', 'Colin Preston');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0610', 'Colin Preston');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0610', 'Chris Mitchell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0610', 'verse', 1, 0, '[\"Spirit of God divine,\",\"fill this heart of mine\",\"with holy flame,\",\"to praise the name\",\"of Jesus my Lord.\",\"Fill me again,\",\"fill me again,\",\"fill me again,\",\"O Spirit of the Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0610', 'verse', 2, 1, '[\"Spirit of God divine,\",\"fill this mouth of mine\",\"with holy praise,\",\"to set the earth ablaze\",\"and glorify Your name.\",\"Fill me again...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0610', 'verse', 3, 2, '[\"Spirit of God divine,\",\"take this heart of mine\",\"to Your throne this day;\",\"help me, I pray,\",\"my offering to give.\",\"Fill me again...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0611', 611, 'Spirit of holiness', 'MP', 'en', 'Christopher Idle/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION            Music arrangement : ©  John Barnard/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'Spirit of holiness,
wisdom and faithfulness,
Wind of the Lord,
blowing strongly and free;
strength of our serving
and joy of our worshipping,
Spirit of God,
bring Your fulness to me!
You came to interpret and teach us effectively
all that the Saviour has spoken and done;
to glorify Jesus is all Your activity,
promise and gift of the Father and Son:
Spirit of holiness...
You came with Your gifts to supply all our poverty,
pouring Your love on the church in her need;
You came with Your fruit for our growth to maturity,
richly refreshing the souls that You feed:
Spirit of holiness...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0611', 'Christopher Idle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0611', 'John Barnard');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0611', 'chorus', 0, 0, '[\"Spirit of holiness,\",\"wisdom and faithfulness,\",\"Wind of the Lord,\",\"blowing strongly and free;\",\"strength of our serving\",\"and joy of our worshipping,\",\"Spirit of God,\",\"bring Your fulness to me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0611', 'verse', 1, 1, '[\"You came to interpret and teach us effectively\",\"all that the Saviour has spoken and done;\",\"to glorify Jesus is all Your activity,\",\"promise and gift of the Father and Son:\",\"Spirit of holiness...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0611', 'verse', 2, 2, '[\"You came with Your gifts to supply all our poverty,\",\"pouring Your love on the church in her need;\",\"You came with Your fruit for our growth to maturity,\",\"richly refreshing the souls that You feed:\",\"Spirit of holiness...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0612', 612, 'Spirit of the living God', 'MP', 'en', 'Copyright 1984 Restoration Music Sovereignmusic@aol.com', '', 0, 0, 0, 1, 1, 'Spirit of the living God,
fall afresh on me;
Spirit of the living God,
fall afresh on me;
fill me anew, fill me anew;
Spirit of the Lord,
fall afresh on me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0612', 'Paul Armstrong');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0612', 'Paul Armstrong');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0612', 'verse', 1, 0, '[\"Spirit of the living God,\",\"fall afresh on me;\",\"Spirit of the living God,\",\"fall afresh on me;\",\"fill me anew, fill me anew;\",\"Spirit of the Lord,\",\"fall afresh on me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0613', 613, 'Spirit of the living God', 'MP', 'en', '1935 Birdwing Music/CapitolCMGPublishing.com (adm UK/Eire Song Solutions www.songsolutions.org ) All rights reserved. Used by permission.', '', 0, 0, 0, 1, 1, 'Spirit of the living God,
fall afresh on me;
Spirit of the living God,
fall afresh on me;
break me, melt me,
mould me, fill me;
Spirit of the living God,
fall afresh on me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0613', 'Daniel Iverson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0613', 'Daniel Iverson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0613', 'W G Hathaway');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0613', 'verse', 1, 0, '[\"Spirit of the living God,\",\"fall afresh on me;\",\"Spirit of the living God,\",\"fall afresh on me;\",\"break me, melt me,\",\"mould me, fill me;\",\"Spirit of the living God,\",\"fall afresh on me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0614', 614, 'Spirit divine', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Spirit divine, attend our prayers,
and make this house Thy home;
descend with all Thy gracious powers,
O come, great Spirit, come!
Come as the light; to us reveal
our emptiness and woe;
and lead us in those paths of life
where all the righteous go.
Come as the fire; and purge our hearts
like sacrificial flame;
let our whole soul an offering be
to our Redeemer’s name.
Come as the dove; and spread Thy wings,
the wings of perfect love;
and let Thy Church on earth become
blest as the Church above.
Spirit divine, attend our prayers,
make a lost world Thy home;
descend with all Thy gracious powers,
O come, great Spirit, come!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0614', 'Andrew Reed');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0614', 'Anon');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0614', 'verse', 1, 0, '[\"Spirit divine, attend our prayers,\",\"and make this house Thy home;\",\"descend with all Thy gracious powers,\",\"O come, great Spirit, come!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0614', 'verse', 2, 1, '[\"Come as the light; to us reveal\",\"our emptiness and woe;\",\"and lead us in those paths of life\",\"where all the righteous go.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0614', 'verse', 3, 2, '[\"Come as the fire; and purge our hearts\",\"like sacrificial flame;\",\"let our whole soul an offering be\",\"to our Redeemer’s name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0614', 'verse', 4, 3, '[\"Come as the dove; and spread Thy wings,\",\"the wings of perfect love;\",\"and let Thy Church on earth become\",\"blest as the Church above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0614', 'verse', 5, 4, '[\"Spirit divine, attend our prayers,\",\"make a lost world Thy home;\",\"descend with all Thy gracious powers,\",\"O come, great Spirit, come!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0615', 615, 'Stand up and bless the Lord', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Stand up and bless the Lord,
ye people of His choice;
stand up and bless the Lord your God,
with heart and soul and voice.
Though high above all praise,
above all blessing high;
who would not fear His holy name?
and laud and magnify?
O for the living flame');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0615', 'James Montgomery');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0615', 'verse', 1, 0, '[\"Stand up and bless the Lord,\",\"ye people of His choice;\",\"stand up and bless the Lord your God,\",\"with heart and soul and voice.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0615', 'verse', 2, 1, '[\"Though high above all praise,\",\"above all blessing high;\",\"who would not fear His holy name?\",\"and laud and magnify?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0615', 'verse', 3, 2, '[\"O for the living flame\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0616', 616, 'Stand up and bless the Lord', 'MP', 'en', '1986 Andy Silver', '', 0, 0, 0, 1, 1, 'Stand up and bless the Lord your God,
stand up and bless the Lord;
His name is exalted above all names;
stand up and bless the Lord.
For our God is good to us,
always ready to forgive;
He is gracious and merciful,
slow to anger and very kind.
So, stand up and bless the Lord your God,
stand up and bless the Lord;
stand up and bless the Lord your God,
stand up.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0616', 'Andy Silver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0616', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0616', 'verse', 1, 0, '[\"Stand up and bless the Lord your God,\",\"stand up and bless the Lord;\",\"His name is exalted above all names;\",\"stand up and bless the Lord.\",\"For our God is good to us,\",\"always ready to forgive;\",\"He is gracious and merciful,\",\"slow to anger and very kind.\",\"So, stand up and bless the Lord your God,\",\"stand up and bless the Lord;\",\"stand up and bless the Lord your God,\",\"stand up.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0617', 617, 'Stand up! stand up for Jesus', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Stand up! stand up for Jesus!
ye soldiers of the cross,
lift high His royal banner;
it must not suffer loss.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0617', 'George Duffield');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0617', 'George James Webb');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0617', 'verse', 1, 0, '[\"Stand up! stand up for Jesus!\",\"ye soldiers of the cross,\",\"lift high His royal banner;\",\"it must not suffer loss.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0618', 618, 'Sun of my soul', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Sun of my soul, my Saviour dear,
it is not night if You are near;
O may no earth-born cloud arise
to hide You from Your servant’s eyes.
When the soft dews of kindly sleep
my wearied eyelids gently steep,
be my last thought, how sweet to rest
for ever on my Saviour’s breast!
Abide with me from morn till eve,
for without You I cannot live;
abide with me when night is nigh,
for without You I dare not die.
If some poor wandering child of Yours
have spurned today Your holy voice,
now, Lord, the gracious work begin;
let them no more be ruled by sin.
Watch by the sick; enrich the poor
with blessings from Your boundless store;
be every mourner’s sleep tonight,
like infant’s slumbers, pure and light.
Come near and bless us when we wake,
ere through the world our way we take;
till in the ocean of Your love
we lose ourselves in heaven above.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0618', 'John Keble');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0618', 'Herbert Stanley Oakley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0618', 'verse', 1, 0, '[\"Sun of my soul, my Saviour dear,\",\"it is not night if You are near;\",\"O may no earth-born cloud arise\",\"to hide You from Your servant’s eyes.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0618', 'verse', 2, 1, '[\"When the soft dews of kindly sleep\",\"my wearied eyelids gently steep,\",\"be my last thought, how sweet to rest\",\"for ever on my Saviour’s breast!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0618', 'verse', 3, 2, '[\"Abide with me from morn till eve,\",\"for without You I cannot live;\",\"abide with me when night is nigh,\",\"for without You I dare not die.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0618', 'verse', 4, 3, '[\"If some poor wandering child of Yours\",\"have spurned today Your holy voice,\",\"now, Lord, the gracious work begin;\",\"let them no more be ruled by sin.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0618', 'verse', 5, 4, '[\"Watch by the sick; enrich the poor\",\"with blessings from Your boundless store;\",\"be every mourner’s sleep tonight,\",\"like infant’s slumbers, pure and light.\"]');
