INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0619', 619, 'Such love', 'MP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Such love, pure as the whitest snow;
such love weeps for the shame I know;
such love, paying the debt I owe;
O Jesus, such love.
Such love, stilling my restlessness;
such love, filling my emptiness;
such love, showing me holiness;
O Jesus, such love.
Such love springs from eternity;
such love, streaming through history;
such love, fountain of life to me;
O Jesus, such love.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0619', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0619', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0619', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0619', 'verse', 1, 0, '[\"Such love, pure as the whitest snow;\",\"such love weeps for the shame I know;\",\"such love, paying the debt I owe;\",\"O Jesus, such love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0619', 'verse', 2, 1, '[\"Such love, stilling my restlessness;\",\"such love, filling my emptiness;\",\"such love, showing me holiness;\",\"O Jesus, such love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0619', 'verse', 3, 2, '[\"Such love springs from eternity;\",\"such love, streaming through history;\",\"such love, fountain of life to me;\",\"O Jesus, such love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0620', 620, 'Sweet is the work', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Sweet is the work, my God, my King,
to praise Thy name, give thanks and sing,
to show Thy love by morning light,
and talk of all Thy truth at night.
Sweet is the day of sacred rest,
no mortal cares disturb my breast;
O may my heart in tune be found,
like David’s harp of solemn sound.
My heart shall triumph in the Lord,
and bless His works, and bless His word;
Thy works of grace, how bright they shine,
how deep Thy counsels, how divine!
And I shall share a glorious part,
when grace has well refined my heart,
and fresh supplies of joy are shed,
like holy oil, to cheer my head.
Then shall I see and hear and know
all I desired or wished below;
and every power find sweet employ
in that eternal world of joy.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0620', 'Isaac Watts');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0620', 'Handel Parker');
