INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0620', 'verse', 2, 1, '[\"Sweet is the day of sacred rest,\",\"no mortal cares disturb my breast;\",\"O may my heart in tune be found,\",\"like David’s harp of solemn sound.\"]');
