INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0621', 621, 'Swing wide the gates', 'MP', 'en', 'Copyright 1986 Sovereign Lifestyle Music Ltd. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'Swing wide the gates,
let the King come in.
Swing wide the gates,
make a way for Him.
Swing wide the gates,
let the King come in.
Swing wide the gates,
make a way for Him.
Here He comes,
the King of glory;
here He comes,
mighty in victory;
here He comes
in splendour and majesty.
Swing wide the gates,
swing wide the gates,
let the King come in.
Swing wide the gates,
swing wide the gates,
let the King come in.');
