INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0621', 'Chris Bowater');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0621', 'verse', 1, 0, '[\"Swing wide the gates,\",\"let the King come in.\",\"Swing wide the gates,\",\"make a way for Him.\",\"Swing wide the gates,\",\"let the King come in.\",\"Swing wide the gates,\",\"make a way for Him.\",\"Here He comes,\",\"the King of glory;\",\"here He comes,\",\"mighty in victory;\",\"here He comes\",\"in splendour and majesty.\",\"Swing wide the gates,\",\"swing wide the gates,\",\"let the King come in.\",\"Swing wide the gates,\",\"swing wide the gates,\",\"let the King come in.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0622', 622, 'Take, eat, this is My body', 'MP', 'en', '©  1985 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Take, eat, this is My body,
broken for you;
for I am come that you might have life;
eat of My flesh and live,
eat of My flesh and live.
My blood was shed for many,
taking away your sin,
and if I shall make you free then
you shall be free indeed,
you shall be free indeed.
Take, eat...
Though your sins be as scarlet
they shall be white as snow,
though they be red like crimson
they shall be as wool,
they shall be as wool.
Take, eat...
For God so loved the world
He gave His only Son,
that whosoever believeth on Him
might have everlasting life,
might have everlasting life.
Take, eat...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0622', 'Paul Simmons');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0622', 'Paul Simmons');
