INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0622', 'verse', 2, 2, '[\"Though your sins be as scarlet\",\"they shall be white as snow,\",\"though they be red like crimson\",\"they shall be as wool,\",\"they shall be as wool.\",\"Take, eat...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0622', 'verse', 3, 3, '[\"For God so loved the world\",\"He gave His only Son,\",\"that whosoever believeth on Him\",\"might have everlasting life,\",\"might have everlasting life.\",\"Take, eat...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0623', 623, 'Take heart and praise our God', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Take heart and praise our God;
rejoice and clap your hands –
His power our foe subdued,
His mercy ever stands:
Let trumpets sound and people sing,
The Lord through all the earth is King!
Take heart, but sing with fear,
exalt His worthy name;
with mind alert and clear
now celebrate His fame:
Let trumpets sound...
Take heart for future days,
for tasks as yet unknown –
the God whose name we praise
is seated on the throne:
Let trumpets sound...
Take heart and trust in God
the Father and the Son –
God is our strength and shield,
His Spirit guides us on:
Let trumpets sound...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0623', 'David Mowbray');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0623', 'Charles Steggall');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0623', 'verse', 1, 0, '[\"Take heart and praise our God;\",\"rejoice and clap your hands –\",\"His power our foe subdued,\",\"His mercy ever stands:\",\"Let trumpets sound and people sing,\",\"The Lord through all the earth is King!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0623', 'verse', 2, 1, '[\"Take heart, but sing with fear,\",\"exalt His worthy name;\",\"with mind alert and clear\",\"now celebrate His fame:\",\"Let trumpets sound...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0623', 'verse', 3, 2, '[\"Take heart for future days,\",\"for tasks as yet unknown –\",\"the God whose name we praise\",\"is seated on the throne:\",\"Let trumpets sound...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0623', 'verse', 4, 3, '[\"Take heart and trust in God\",\"the Father and the Son –\",\"God is our strength and shield,\",\"His Spirit guides us on:\",\"Let trumpets sound...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0624', 624, 'Take my life, and let it be', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Take my life, and let it be
consecrated, Lord, to Thee;
take my moments and my days,
let them flow in ceaseless praise.
Take my hands, and let them move
at the impulse of Thy love;
take my feet, and let them be
swift and beautiful for Thee.
Take my voice, and let me sing
always, only, for my King;
take my lips, and let them be
filled with messages from Thee.
Take my silver and my gold,
not a mite would I withhold;
take my intellect, and use
every power as Thou shalt choose.
Take my will, and make it Thine;
it shall be no longer mine:
take my heart, it is Thine own;
it shall be Thy royal throne.
Take my love; my Lord, I pour
at Thy feet its treasure store:
take myself, and I will be
ever, only, all, for Thee.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0624', 'Frances Ridley Havergal');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0624', 'Wolfgang Amadeus Mozart');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0624', 'verse', 1, 0, '[\"Take my life, and let it be\",\"consecrated, Lord, to Thee;\",\"take my moments and my days,\",\"let them flow in ceaseless praise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0624', 'verse', 2, 1, '[\"Take my hands, and let them move\",\"at the impulse of Thy love;\",\"take my feet, and let them be\",\"swift and beautiful for Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0624', 'verse', 3, 2, '[\"Take my voice, and let me sing\",\"always, only, for my King;\",\"take my lips, and let them be\",\"filled with messages from Thee.\"]');
