INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0624', 'verse', 5, 4, '[\"Take my will, and make it Thine;\",\"it shall be no longer mine:\",\"take my heart, it is Thine own;\",\"it shall be Thy royal throne.\"]');
