INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0625', 625, 'Take time to be holy', 'MP', 'en', 'Harper Collins Religious (admin. by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Take time to be holy, speak oft with Thy Lord;
abide in Him always, and feed on His word.
Make friends of God’s children, help those who are weak;
forgetting in nothing His blessing to seek.
Take time to be holy, the world rushes on;
spend much time in secret with Jesus alone –
by looking to Jesus, like Him thou shalt be!
Thy friends in thy conduct His likeness shall see.
Take time to be holy, let Him be thy guide;
and run not before Him, whatever betide;
in joy or in sorrow still follow thy Lord,
and, looking to Jesus, still trust in His word.
Take time to be holy, be calm in thy soul;
each thought and each temper beneath His control;
thus led by His Spirit to fountains of love,
thou soon shalt be fitted for service above.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0625', 'William Dunn Longstaff');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0625', 'George Coles Stebbins');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0625', 'Eugene L Clark');
