INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0625', 'verse', 2, 1, '[\"Take time to be holy, the world rushes on;\",\"spend much time in secret with Jesus alone –\",\"by looking to Jesus, like Him thou shalt be!\",\"Thy friends in thy conduct His likeness shall see.\"]');
