INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0626', 626, 'Teach me Thy way', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Teach me Thy way, O Lord,
teach me Thy way!
Thy gracious aid afford,
teach me Thy way!
Help me to walk aright,
more by faith, less by sight;
lead me with heavenly light:
teach me Thy way!
When doubts and fears arise,
teach me Thy way!
When storms o’erspread the skies,
teach me Thy way!
Shine through the cloud and rain,
through sorrow, toil, and pain;
make Thou my pathway plain:
teach me Thy way!
Long as my life shall last,
teach me Thy way!
Where’er my lot be cast,
teach me Thy way!
Until the race is run,
until the journey’s done,
until the crown is won,
teach me Thy way!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0626', 'Benjamin Mansell Ramsey');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0626', 'Benjamin Mansell Ramsey');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0626', 'verse', 1, 0, '[\"Teach me Thy way, O Lord,\",\"teach me Thy way!\",\"Thy gracious aid afford,\",\"teach me Thy way!\",\"Help me to walk aright,\",\"more by faith, less by sight;\",\"lead me with heavenly light:\",\"teach me Thy way!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0626', 'verse', 2, 1, '[\"When doubts and fears arise,\",\"teach me Thy way!\",\"When storms o’erspread the skies,\",\"teach me Thy way!\",\"Shine through the cloud and rain,\",\"through sorrow, toil, and pain;\",\"make Thou my pathway plain:\",\"teach me Thy way!\"]');
