INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0633', 'Alison Revell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0633', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0633', 'verse', 1, 0, '[\"Thank You, Jesus, thank You, Jesus,\",\"thank You, Lord, for loving me.\",\"Thank You, Jesus...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0633', 'verse', 2, 1, '[\"You went to Calvary, there You died for me,\",\"thank You, Lord, for loving me.\",\"You went to Calvary...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0633', 'verse', 3, 2, '[\"You rose up from the grave, to me new life You gave,\",\"thank You, Lord, for loving me.\",\"You rose up from the grave...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0633', 'verse', 4, 3, '[\"You’re coming back again, and we with You shall reign,\",\"thank You, Lord, for loving me.\",\"You’re coming back again...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0634', 634, 'Thank You, Jesus, for Your love', 'MP', 'en', '©  1978 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Thank You, Jesus, for Your love to me;
thank You, Jesus, for Your grace so free.
I’ll lift my voice to praise Your name,
praise You again and again:
You are everything,
You are my Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0634', 'Alison Revell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0634', 'Alison Revell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0634', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0634', 'verse', 1, 0, '[\"Thank You, Jesus, for Your love to me;\",\"thank You, Jesus, for Your grace so free.\",\"I’ll lift my voice to praise Your name,\",\"praise You again and again:\",\"You are everything,\",\"You are my Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0635', 635, 'Thank You, Lord', 'MP', 'en', '1987 Greg Leavers and Phil Burt', '', 0, 0, 0, 1, 1, 'SELECT VERSES AS APPROPRIATE
f*r*N1f*    Thank You, Lord, thank You, Lord,
that nothing can separate us from Your love.
*N2    Thank You, Lord, thank You, Lord,
that there is no condemnation when we’re in You.
CONFESSION VERSES
*N3    Search my heart, search my heart,
and show me the sin I need to confess to You.
*N4    Sorry, Lord, sorry, Lord,
I humbly now ask forgiveness for my sin.
*N5    Cleanse me, Lord, cleanse me, Lord,
through Your precious blood make my heart clean before You.
*N6    Thank You, Lord, thank You, Lord
that You’ve now removed the guilt of all my sin.
COMMUNION
*N7    Take this bread, take this bread,
for this is Christ’s body which was broken for you.
*N8    Thank You, Lord, thank You, Lord
for dying on Calvary so that I can know You.
*N9    Take this cup, take this cup
and drink it remembering Jesus Christ died for you.
Thank You, Lord, thank You, Lord,
that through Your shed blood we are made one with God.
PRAISE AND WORSHIP
Fill me, Lord, fill me, Lord,
so that I might learn to live through Your power alone.
We love You, we love You,
we open our hearts in adoration to You.
Holy Lord, holy Lord,
Your name is far higher than any other name.
Worthy Lord, worthy Lord,
we offer our sacrifice of worship to You.
Reigning King, reigning King,
You’re glorious in majesty, almighty in power.');
