INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0635', 'verse', 10, 1, '[\"Thank You, Lord, thank You, Lord,\",\"that through Your shed blood we are made one with God.\",\"PRAISE AND WORSHIP\"]');
