INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0636', 636, 'Thank You, Lord, for Your presence', 'MP', 'en', '1986 Roland Fudge', '', 0, 0, 0, 1, 1, 'Thank You, Lord, for Your presence here,
thank You, Lord, thank You, Lord.
Thank You, Lord, You remove all fear,
thank You, Lord, thank You, Lord.
For the love that You showed
as You poured out Your life,
we thank You, we bless You,
Christ Jesus our Lord,
we thank You, Lord, thank You, Lord.
Thank You, Lord...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0636', 'Roland Fudge');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0636', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0636', 'verse', 1, 0, '[\"Thank You, Lord, for Your presence here,\",\"thank You, Lord, thank You, Lord.\",\"Thank You, Lord, You remove all fear,\",\"thank You, Lord, thank You, Lord.\",\"For the love that You showed\",\"as You poured out Your life,\",\"we thank You, we bless You,\",\"Christ Jesus our Lord,\",\"we thank You, Lord, thank You, Lord.\",\"Thank You, Lord...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0637', 637, 'Thanks be to God', 'MP', 'en', '1978 Sovereign Music UK, PO Box 356, Leighton Buzzard LU7 3WP, UK. sovereignmusic@aol.com', '', 0, 0, 0, 1, 1, 'Thanks be to God
who gives us the victory,
gives us the victory
through our Lord Jesus Christ;
thanks be to God
who gives us the victory,
gives us the victory
through our Lord Jesus Christ.
He is able to keep us from falling,
and to set us free from sin:
so let us each live up to our calling,
and commit our way to Him.
Thanks be to God...
Jesus knows all about our temptations –
He has had to bear them too;
He will show us how to escape them,
if we trust Him He will lead us through.
Thanks be to God...
He has led us from the power of darkness
to the kingdom of His blessèd Son:
so let us join in praise together,
and rejoice in what the Lord has done.
Thanks be to God...
Praise the Lord for sending Jesus
to the cross of Calvary:
now He’s risen, reigns in power,
and death is swallowed up in victory.
Thanks be to God...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0637', 'Robert Stoodley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0637', 'Robert Stoodley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0637', 'chorus', 0, 0, '[\"Thanks be to God\",\"who gives us the victory,\",\"gives us the victory\",\"through our Lord Jesus Christ;\",\"thanks be to God\",\"who gives us the victory,\",\"gives us the victory\",\"through our Lord Jesus Christ.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0637', 'verse', 1, 1, '[\"He is able to keep us from falling,\",\"and to set us free from sin:\",\"so let us each live up to our calling,\",\"and commit our way to Him.\",\"Thanks be to God...\"]');
