INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0637', 'verse', 3, 3, '[\"He has led us from the power of darkness\",\"to the kingdom of His blessèd Son:\",\"so let us join in praise together,\",\"and rejoice in what the Lord has done.\",\"Thanks be to God...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0637', 'verse', 4, 4, '[\"Praise the Lord for sending Jesus\",\"to the cross of Calvary:\",\"now He’s risen, reigns in power,\",\"and death is swallowed up in victory.\",\"Thanks be to God...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0638', 638, 'Thank You, God, for sending Jesus', 'MP', 'en', 'control                        arrangement: ? 1987 Phil Burt', '', 0, 0, 0, 1, 0, 'Thank You, God, for sending Jesus;
thank You, Jesus, that You came;
Holy Spirit, won’t You teach us
more about His wondrous name?');
