INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0645', 'Thomas Olivers');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0645', 'verse', 1, 0, '[\"The God of Abraham praise,\",\"who reigns enthroned above,\",\"Ancient of everlasting days,\",\"and God of love.\",\"Jehovah, great I A\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0646', 646, 'The greatest thing in all my life', 'MP', 'en', '1977 Candle Company Music/Sparrow Song/Universal Music - Brentwood Benson Songs/CapitolCMGPublishing.com (adm UK/Eire Song Solutions  www.songsolutions.org) All rights reserved. Used by permission.', '', 0, 0, 0, 1, 1, 'The greatest thing in all my life
is knowing You;
the greatest thing in all my life
is knowing You;
I want to know You more;
I want to know You more.
The greatest thing in all my life
is knowing You.
The greatest thing in all my life
is loving You;
the greatest thing in all my life
is loving You;
I want to love You more;
I want to love You more.
The greatest thing in all my life
is loving You.
The greatest thing in all my life
is serving You;
the greatest thing in all my life
is serving You;
I want to serve You more;
I want to serve You more.
The greatest thing in all my life
is serving You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0646', 'Mark Pendergrass');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0646', 'Mark Pendergrass');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0646', 'verse', 1, 0, '[\"The greatest thing in all my life\",\"is knowing You;\",\"the greatest thing in all my life\",\"is knowing You;\",\"I want to know You more;\",\"I want to know You more.\",\"The greatest thing in all my life\",\"is knowing You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0646', 'verse', 2, 1, '[\"The greatest thing in all my life\",\"is loving You;\",\"the greatest thing in all my life\",\"is loving You;\",\"I want to love You more;\",\"I want to love You more.\",\"The greatest thing in all my life\",\"is loving You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0646', 'verse', 3, 2, '[\"The greatest thing in all my life\",\"is serving You;\",\"the greatest thing in all my life\",\"is serving You;\",\"I want to serve You more;\",\"I want to serve You more.\",\"The greatest thing in all my life\",\"is serving You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0647', 647, 'The head that once was crowned', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'The head that once was crowned with thorns
is crowned with glory now;
a royal diadem adorns
the mighty victor’s brow.
The highest place that heaven affords
is His by sovereign right;
the King of kings and Lord of lords,
He reigns in perfect light.
The joy of all who dwell above,
the joy of all below,
to whom He manifests His love,
and grants His name to know.
To them the cross, with all its shame,
with all its grace is given;
their name an everlasting name,
their joy the joy of heaven.
They suffer with their Lord below;
they reign with Him above;
their profit and their joy, to know
the mystery of His love.
The cross He bore is life and health,
though shame and death to Him:
His people’s hope, His people’s wealth,
their everlasting theme.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0647', 'Thomas Kelly');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0647', 'Jeremiah Clarke');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0647', 'verse', 1, 0, '[\"The head that once was crowned with thorns\",\"is crowned with glory now;\",\"a royal diadem adorns\",\"the mighty victor’s brow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0647', 'verse', 2, 1, '[\"The highest place that heaven affords\",\"is His by sovereign right;\",\"the King of kings and Lord of lords,\",\"He reigns in perfect light.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0647', 'verse', 3, 2, '[\"The joy of all who dwell above,\",\"the joy of all below,\",\"to whom He manifests His love,\",\"and grants His name to know.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0647', 'verse', 4, 3, '[\"To them the cross, with all its shame,\",\"with all its grace is given;\",\"their name an everlasting name,\",\"their joy the joy of heaven.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0647', 'verse', 5, 4, '[\"They suffer with their Lord below;\",\"they reign with Him above;\",\"their profit and their joy, to know\",\"the mystery of His love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0647', 'verse', 6, 5, '[\"The cross He bore is life and health,\",\"though shame and death to Him:\",\"His people’s hope, His people’s wealth,\",\"their everlasting theme.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0648', 648, 'Let us adore', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'The heavens declare the glory of God,
and the heavens proclaim the work of His hands;
and day after day they pour forth speech,
and night after night they display what He knows.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0648', 'Andy Silver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0648', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0648', 'verse', 1, 0, '[\"The heavens declare the glory of God,\",\"and the heavens proclaim the work of His hands;\",\"and day after day they pour forth speech,\",\"and night after night they display what He knows.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0649', 649, 'The King of love', 'MP', 'en', '(c) 1997 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'The King of love my shepherd is,
whose goodness faileth never;
I nothing lack if I am His
and He is mine for ever.
Where streams of living water flow
my ransomed soul He leadeth,
and where the verdant pastures grow
with food celestial feedeth.
Perverse and foolish oft I strayed;
but yet in love He sought me,
and on His shoulder gently laid,
and home rejoicing brought me.
In death’s dark vale I fear no ill
with Thee, dear Lord, beside me;
Thy rod and staff my comfort still,
Thy cross before to guide me.
Thou spread’st a table in my sight;
Thy unction grace bestoweth;
and O what transport of delight');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0649', 'Henry Williams Baker');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0649', 'John Bacchus Dykes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0649', 'verse', 1, 0, '[\"The King of love my shepherd is,\",\"whose goodness faileth never;\",\"I nothing lack if I am His\",\"and He is mine for ever.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0649', 'verse', 2, 1, '[\"Where streams of living water flow\",\"my ransomed soul He leadeth,\",\"and where the verdant pastures grow\",\"with food celestial feedeth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0649', 'verse', 3, 2, '[\"Perverse and foolish oft I strayed;\",\"but yet in love He sought me,\",\"and on His shoulder gently laid,\",\"and home rejoicing brought me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0649', 'verse', 4, 3, '[\"In death’s dark vale I fear no ill\",\"with Thee, dear Lord, beside me;\",\"Thy rod and staff my comfort still,\",\"Thy cross before to guide me.\"]');
