INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0650', 650, 'The King is among us', 'MP', 'en', '©  1981 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'The King is among us,
His Spirit is here:
let’s draw near and worship,
let songs fill the air!
He looks down upon us,
delight in His face,
enjoying His children’s love,
enthralled by our praise.
For each child is special,
accepted and loved –
a love gift from Jesus
to His Father above.
And now He is giving
His gifts to us all;
for no-one is worthless
and each one is called.
The Spirit’s anointing
on all flesh comes down,
and we shall be channels
for works like His own:
We come now believing
Your promise of power,
for we are Your people
and this is Your hour.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0650', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0650', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0650', 'Chris Rolinson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0650', 'verse', 1, 0, '[\"The King is among us,\",\"His Spirit is here:\",\"let’s draw near and worship,\",\"let songs fill the air!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0650', 'verse', 2, 1, '[\"He looks down upon us,\",\"delight in His face,\",\"enjoying His children’s love,\",\"enthralled by our praise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0650', 'verse', 3, 2, '[\"For each child is special,\",\"accepted and loved –\",\"a love gift from Jesus\",\"to His Father above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0650', 'verse', 4, 3, '[\"And now He is giving\",\"His gifts to us all;\",\"for no-one is worthless\",\"and each one is called.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0650', 'verse', 5, 4, '[\"The Spirit’s anointing\",\"on all flesh comes down,\",\"and we shall be channels\",\"for works like His own:\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0650', 'verse', 6, 5, '[\"We come now believing\",\"Your promise of power,\",\"for we are Your people\",\"and this is Your hour.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0651', 651, 'The kingdom of God', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'The kingdom of God
is justice and joy,
for Jesus restores
what sin would destroy;
God’s power and glory
in Jesus we know,
and here and hereafter
the kingdom shall grow.
The kingdom of God
is mercy and grace,
the captives are freed,
the sinners find place,
the outcast are welcomed
God’s banquet to share,
and hope is awakened
in place of despair.
The kingdom of God
is challenge and choice,
believe the good news,
repent and rejoice!
His love for us sinners
brought Christ to His cross,
our crisis of judgement
for gain or for loss.
God’s kingdom is come,
the gift and the goal,
in Jesus begun,
in heaven made whole;
the heirs of the kingdom
shall answer His call,
and all things cry, ‘Glory!’
to God all-in-all!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0651', 'Bryn Rees');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0651', 'verse', 1, 0, '[\"The kingdom of God\",\"is justice and joy,\",\"for Jesus restores\",\"what sin would destroy;\",\"God’s power and glory\",\"in Jesus we know,\",\"and here and hereafter\",\"the kingdom shall grow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0651', 'verse', 2, 1, '[\"The kingdom of God\",\"is mercy and grace,\",\"the captives are freed,\",\"the sinners find place,\",\"the outcast are welcomed\",\"God’s banquet to share,\",\"and hope is awakened\",\"in place of despair.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0651', 'verse', 3, 2, '[\"The kingdom of God\",\"is challenge and choice,\",\"believe the good news,\",\"repent and rejoice!\",\"His love for us sinners\",\"brought Christ to His cross,\",\"our crisis of judgement\",\"for gain or for loss.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0651', 'verse', 4, 3, '[\"God’s kingdom is come,\",\"the gift and the goal,\",\"in Jesus begun,\",\"in heaven made whole;\",\"the heirs of the kingdom\",\"shall answer His call,\",\"and all things cry, ‘Glory!’\",\"to God all-in-all!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0652', 652, 'The light of Christ', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'The light of Christ
has come into the world;
the light of Christ
has come into the world.
All men must be born again
to see the kingdom of God;
the water and the Spirit
bring new life in God’s love.
The light of Christ...
God gave up His only Son
out of love for the world,
so that all men who believe in Him
will live for ever.
The light of Christ...
The light of God has come to us
so that we might have salvation;');
