INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0652', 'verse', 2, 2, '[\"God gave up His only Son\",\"out of love for the world,\",\"so that all men who believe in Him\",\"will live for ever.\",\"The light of Christ...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0652', 'verse', 3, 3, '[\"The light of God has come to us\",\"so that we might have salvation;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0653', 653, 'The Lord has given', 'MP', 'en', 'control                        arrangement: ? 1987 Phil Burt', '', 0, 0, 0, 1, 1, 'The Lord has given a land of good things,
I will press on and make them mine;
I’ll know His power, I’ll know His glory,
and in His kingdom I will shine.
With the high praises of God in our mouth,
and a two-edged sword in our hand,
we’ll march right on to the victory side,
right into Canaan’s land.
Gird up your armour, ye sons of Zion,
gird up your armour, let’s go to war;
we’ll win the battle with great rejoicing
and so we’ll praise Him more and more.
With the high praises...
We’ll bind their kings in chains and fetters,
we’ll bind their nobles tight in iron,
to execute God’s written judgement –
march on to glory, sons of Zion!
With the high praises...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0653', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0653', 'Anon');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0653', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0653', 'verse', 1, 0, '[\"The Lord has given a land of good things,\",\"I will press on and make them mine;\",\"I’ll know His power, I’ll know His glory,\",\"and in His kingdom I will shine.\",\"With the high praises of God in our mouth,\",\"and a two-edged sword in our hand,\",\"we’ll march right on to the victory side,\",\"right into Canaan’s land.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0653', 'verse', 2, 1, '[\"Gird up your armour, ye sons of Zion,\",\"gird up your armour, let’s go to war;\",\"we’ll win the battle with great rejoicing\",\"and so we’ll praise Him more and more.\",\"With the high praises...\"]');
