INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0654', 654, 'The Lord has led forth', 'MP', 'en', 'Copyright 1982 Sovereign Lifestyle Music Ltd.. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'The Lord has led forth His people with joy,
and His chosen ones with singing, singing;
the Lord has led forth His people with joy,
and His chosen ones with singing.
He has given to them the lands of the nations,
to possess the fruit and keep His laws,
and praise, praise His name.
The Lord has led forth His people with joy,
and His chosen ones with singing, singing;
the Lord has led forth His people with joy,
and His chosen ones with singing.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0654', 'Chris Bowater');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0654', 'Chris Bowater');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0654', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0654', 'verse', 1, 0, '[\"The Lord has led forth His people with joy,\",\"and His chosen ones with singing, singing;\",\"the Lord has led forth His people with joy,\",\"and His chosen ones with singing.\",\"He has given to them the lands of the nations,\",\"to possess the fruit and keep His laws,\",\"and praise, praise His name.\",\"The Lord has led forth His people with joy,\",\"and His chosen ones with singing, singing;\",\"the Lord has led forth His people with joy,\",\"and His chosen ones with singing.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0655', 655, 'The Lord is a great and mighty King', 'MP', 'en', '1973 GIA Publications Inc, 7404 S Mason Avenue, Chicago, IL 60638, USA', '', 0, 0, 0, 1, 0, 'The Lord is a great and mighty King,
just and gentle with everything;
so with happiness we sing,
and let His praises ring.
We are His voice, we His song;
let us praise Him all day long. Alleluia.
The Lord is a great...
We are His body here on earth;');
