INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0655', 'verse', 1, 1, '[\"We are His voice, we His song;\",\"let us praise Him all day long. Alleluia.\",\"The Lord is a great...\"]');
