INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0657', 657, 'The Lord is King', 'MP', 'en', '© 1983 Thankyou Music/Adm. by CAPITOL CMG Publishing worldwide excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'The Lord is King,
He is mighty in battle,
working wonders,
glorious in majesty.
The Lord is King –
so majestic in power!
His right hand
has shattered the enemy.
A This is my God
and I will praise Him;
B this is my God
and I will praise Him:
A My strength and song
and my salvation,
B my strength and song
and my salvation.
(The singers may divide at f*rAf*i and B)');
