INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0657', 'verse', 1, 0, '[\"The Lord is King,\",\"He is mighty in battle,\",\"working wonders,\",\"glorious in majesty.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0657', 'verse', 2, 1, '[\"The Lord is King –\",\"so majestic in power!\",\"His right hand\",\"has shattered the enemy.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0657', 'verse', 3, 2, '[\"A This is my God\",\"and I will praise Him;\",\"B this is my God\",\"and I will praise Him:\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0657', 'verse', 4, 3, '[\"A My strength and song\",\"and my salvation,\",\"B my strength and song\",\"and my salvation.\",\"(The singers may divide at f*rAf*i and B)\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0658', 658, 'The Lord is my strength', 'MP', 'en', '1982 Roland Fudge', '', 0, 0, 0, 1, 1, 'The Lord is my strength and my song,
the Lord is my strength and my song,
and He has become my salvation.
Sing to the Lord, for He has done marvellous things;
sing to the Lord, for He has done marvellous things;
sing to the Lord, sing to the Lord,
sing to the Lord, for He has done marvellous things.
The Lord is my strength and my song,
the Lord is my strength and my song,
and He has become my salvation.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0658', 'Roland Fudge');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0658', 'Roland Fudge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0658', 'verse', 1, 0, '[\"The Lord is my strength and my song,\",\"the Lord is my strength and my song,\",\"and He has become my salvation.\",\"Sing to the Lord, for He has done marvellous things;\",\"sing to the Lord, for He has done marvellous things;\",\"sing to the Lord, sing to the Lord,\",\"sing to the Lord, for He has done marvellous things.\",\"The Lord is my strength and my song,\",\"the Lord is my strength and my song,\",\"and He has become my salvation.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0659', 659, 'The Lord reigns', 'MP', 'en', '©  1979 Authentic Publishing / Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'The Lord reigns, the Lord reigns,
He is robed in majesty,
the Lord is robed in majesty,
and He is girded with strength.
The Lord has established the world,
it shall never be moved;
Thy throne is established of old,
Thou art from everlasting.
The Lord reigns...
The floods have lifted up, O Lord,
lifted up their voice;
mightier than the thunder of the waves,
the Lord on high is mighty.
The Lord reigns...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0659', 'Angela Browning');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0659', 'Angela Browning');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0659', 'chorus', 0, 0, '[\"The Lord reigns, the Lord reigns,\",\"He is robed in majesty,\",\"the Lord is robed in majesty,\",\"and He is girded with strength.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0659', 'verse', 1, 1, '[\"The Lord has established the world,\",\"it shall never be moved;\",\"Thy throne is established of old,\",\"Thou art from everlasting.\",\"The Lord reigns...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0659', 'verse', 2, 2, '[\"The floods have lifted up, O Lord,\",\"lifted up their voice;\",\"mightier than the thunder of the waves,\",\"the Lord on high is mighty.\",\"The Lord reigns...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0660', 660, 'The Lord’s my shepherd', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'The Lord’s my shepherd, I’ll not want;
He makes me down to lie
in pastures green; He leadeth me
the quiet waters by.
My soul He doth restore again,
and me to walk doth make
within the paths of righteousness,
e’en for His own name’s sake.
Yea, though I walk through death’s dark vale,
yet will I fear none ill;
for Thou art with me, and Thy rod
and staff me comfort still.
My table Thou hast furnishèd
in presence of my foes;
my head Thou dost with oil anoint,
and my cup overflows.
Goodness and mercy all my life
shall surely follow me;
and in God’s house for evermore
my dwelling-place shall be.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0660', 'Francis Rous');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0660', 'verse', 1, 0, '[\"The Lord’s my shepherd, I’ll not want;\",\"He makes me down to lie\",\"in pastures green; He leadeth me\",\"the quiet waters by.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0660', 'verse', 2, 1, '[\"My soul He doth restore again,\",\"and me to walk doth make\",\"within the paths of righteousness,\",\"e’en for His own name’s sake.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0660', 'verse', 3, 2, '[\"Yea, though I walk through death’s dark vale,\",\"yet will I fear none ill;\",\"for Thou art with me, and Thy rod\",\"and staff me comfort still.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0660', 'verse', 4, 3, '[\"My table Thou hast furnishèd\",\"in presence of my foes;\",\"my head Thou dost with oil anoint,\",\"and my cup overflows.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0660', 'verse', 5, 4, '[\"Goodness and mercy all my life\",\"shall surely follow me;\",\"and in God’s house for evermore\",\"my dwelling-place shall be.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0661', 661, 'The Lord’s Prayer', 'MP', 'en', 'control            Words by Anon. Music by Jospeh Lees © 1905 Ascherberg Hopwood & Crew Ltd, London W6 8BS. Reproduced by permission of Faber Music Ltd. All Rights Reserved.', '', 0, 0, 0, 1, 1, 'Our Father which art in heaven,
hallowèd be Thy name,
Thy kingdom come,
Thy will be done,
in earth, as it is in heaven.
Give us this day our daily bread;
forgive us our trespasses
as we forgive them who trespass against us.
And lead us not into temptation,
but deliver us from evil.
For Thine is the kingdom,
the power and the glory
for ever and ever.
Amen, amen.');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0661', 'Joseph Lees');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0661', 'verse', 1, 0, '[\"Our Father which art in heaven,\",\"hallowèd be Thy name,\",\"Thy kingdom come,\",\"Thy will be done,\",\"in earth, as it is in heaven.\",\"Give us this day our daily bread;\",\"forgive us our trespasses\",\"as we forgive them who trespass against us.\",\"And lead us not into temptation,\",\"but deliver us from evil.\",\"For Thine is the kingdom,\",\"the power and the glory\",\"for ever and ever.\",\"Amen, amen.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0662', 662, 'The love of Christ who died for me', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'The love of Christ who died for me
is more than mind can know,
His mercy measureless and free
to meet the debt I owe.
He came my sinful cause to plead,
He laid His glories by,
for me a homeless life to lead,
a shameful death to die.
My sins I only see in part,
my self-regarding ways;
the secret places of my heart
lie bare before His gaze.
For me the price of sin He paid;
my sins beyond recall
are all alike on Jesus laid,
He died to bear them all.
O living Lord of life, for whom
the heavens held their breath,
to see, triumphant from the tomb,
a love that conquers death.
Possess my heart that it may be
Your kingdom without end,
O Christ who died for love of me
and lives to be my friend.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0662', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0662', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0662', 'verse', 1, 0, '[\"The love of Christ who died for me\",\"is more than mind can know,\",\"His mercy measureless and free\",\"to meet the debt I owe.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0662', 'verse', 2, 1, '[\"He came my sinful cause to plead,\",\"He laid His glories by,\",\"for me a homeless life to lead,\",\"a shameful death to die.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0662', 'verse', 3, 2, '[\"My sins I only see in part,\",\"my self-regarding ways;\",\"the secret places of my heart\",\"lie bare before His gaze.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0662', 'verse', 4, 3, '[\"For me the price of sin He paid;\",\"my sins beyond recall\",\"are all alike on Jesus laid,\",\"He died to bear them all.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0662', 'verse', 5, 4, '[\"O living Lord of life, for whom\",\"the heavens held their breath,\",\"to see, triumphant from the tomb,\",\"a love that conquers death.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0662', 'verse', 6, 5, '[\"Possess my heart that it may be\",\"Your kingdom without end,\",\"O Christ who died for love of me\",\"and lives to be my friend.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0663', 663, 'The price is paid', 'MP', 'en', '©  1983 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'The price is paid:
come, let us enter in
to all that Jesus died
to make our own.
For every sin
more than enough He gave,
and bought our freedom');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0663', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0663', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0663', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0663', 'verse', 1, 0, '[\"The price is paid:\",\"come, let us enter in\",\"to all that Jesus died\",\"to make our own.\",\"For every sin\",\"more than enough He gave,\",\"and bought our freedom\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0664', 664, 'The Spirit lives', 'MP', 'en', 'Kevin Mayhew Ltd, Buxhall, Stowmarket, Suffolk IP14 3DJ. Used by permission. From Hymns Old and New', '', 0, 0, 0, 1, 1, 'The Spirit lives to set us free,
walk, walk in the light;
He binds us all in unity,
walk, walk in the light.
Walk in the light,
walk in the light,
walk in the light,
walk in the light of the Lord.
Jesus promised life to all,
walk, walk in the light;
the dead were wakened by His call,
walk, walk in the light.
Walk in the light...
He died in pain on Calvary,
walk, walk in the light;
to save the lost like you and me,
walk, walk in the light.
Walk in the light...
We know His death was not the end,
walk, walk in the light;
He gave His Spirit to be our friend,
walk, walk in the light.
Walk in the light...
By Jesus’ love our wounds are healed,
walk, walk in the light;
the Father’s kindness is revealed,
walk, walk in the light.
Walk in the light...
The Spirit lives in you and me,
walk, walk in the light;
His light will shine for all to see,
walk, walk in the light.
Walk in the light...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0664', 'Damien Lundy');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0664', 'Damien Lundy');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0664', 'verse', 1, 0, '[\"The Spirit lives to set us free,\",\"walk, walk in the light;\",\"He binds us all in unity,\",\"walk, walk in the light.\",\"Walk in the light,\",\"walk in the light,\",\"walk in the light,\",\"walk in the light of the Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0664', 'verse', 2, 1, '[\"Jesus promised life to all,\",\"walk, walk in the light;\",\"the dead were wakened by His call,\",\"walk, walk in the light.\",\"Walk in the light...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0664', 'verse', 3, 2, '[\"He died in pain on Calvary,\",\"walk, walk in the light;\",\"to save the lost like you and me,\",\"walk, walk in the light.\",\"Walk in the light...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0664', 'verse', 4, 3, '[\"We know His death was not the end,\",\"walk, walk in the light;\",\"He gave His Spirit to be our friend,\",\"walk, walk in the light.\",\"Walk in the light...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0664', 'verse', 5, 4, '[\"By Jesus’ love our wounds are healed,\",\"walk, walk in the light;\",\"the Father’s kindness is revealed,\",\"walk, walk in the light.\",\"Walk in the light...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0664', 'verse', 6, 5, '[\"The Spirit lives in you and me,\",\"walk, walk in the light;\",\"His light will shine for all to see,\",\"walk, walk in the light.\",\"Walk in the light...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0665', 665, 'The Spirit of the Lord', 'MP', 'en', 'Copyright 1985 Sovereign Lifestyle Music Ltd.  Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'The Spirit of the Lord,
the sovereign Lord, is on me,
because He has anointed me
to preach good news to the poor:
Proclaiming Jesus, only Jesus –
it is Jesus, Saviour, healer and baptizer,
and the mighty King, the victor and deliverer –
He is Lord, He is Lord, He is Lord.
And He has called on me
to bind up all the broken hearts,
to minister release to every
captivated soul:
Proclaiming Jesus...
Let righteousness arise
and blossom as a garden;
let praise begin to spring in every
tongue and nation:
Proclaiming Jesus...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0665', 'Chris Bowater');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0665', 'Chris Bowater');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0665', 'verse', 1, 0, '[\"The Spirit of the Lord,\",\"the sovereign Lord, is on me,\",\"because He has anointed me\",\"to preach good news to the poor:\",\"Proclaiming Jesus, only Jesus –\",\"it is Jesus, Saviour, healer and baptizer,\",\"and the mighty King, the victor and deliverer –\",\"He is Lord, He is Lord, He is Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0665', 'verse', 2, 1, '[\"And He has called on me\",\"to bind up all the broken hearts,\",\"to minister release to every\",\"captivated soul:\",\"Proclaiming Jesus...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0665', 'verse', 3, 2, '[\"Let righteousness arise\",\"and blossom as a garden;\",\"let praise begin to spring in every\",\"tongue and nation:\",\"Proclaiming Jesus...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0666', 666, 'The steadfast love of the Lord', 'MP', 'en', '1974 Celebration / kingswaysongs.com. tym@kingsway.co.uk. For Europe and Commonwealth (excl. Canada, Australasia and Africa). Used by permission.', '', 0, 0, 0, 1, 0, 'The steadfast love of the Lord never ceases,
His mercies never come to an end;
they are new every morning, new every morning:
great is Thy faithfulness, O Lord,
great is Thy faithfulness.
The Lord is my portion, says my soul,
therefore I will hope in Him.
The steadfast love...
The Lord is good to those who wait for Him,
to the soul that seeks Him:
it is good that we should wait quietly
for the salvation of the Lord.
The steadfast love...
The Lord will not cast off for ever,
but will have compassion:
for He does not willingly afflict
or grieve the sons of men.
The steadfast love...
So let us examine all our ways,
and return to the Lord:
let us lift up our hearts and hands
to God in heaven.
The steadfast love...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0666', 'Edith McNeill');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0666', 'Edith McNeill');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0666', 'chorus', 0, 0, '[\"The steadfast love of the Lord never ceases,\",\"His mercies never come to an end;\",\"they are new every morning, new every morning:\",\"great is Thy faithfulness, O Lord,\",\"great is Thy faithfulness.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0666', 'verse', 1, 1, '[\"The Lord is my portion, says my soul,\",\"therefore I will hope in Him.\",\"The steadfast love...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0666', 'verse', 2, 2, '[\"The Lord is good to those who wait for Him,\",\"to the soul that seeks Him:\",\"it is good that we should wait quietly\",\"for the salvation of the Lord.\",\"The steadfast love...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0666', 'verse', 3, 3, '[\"The Lord will not cast off for ever,\",\"but will have compassion:\",\"for He does not willingly afflict\",\"or grieve the sons of men.\",\"The steadfast love...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0666', 'verse', 4, 4, '[\"So let us examine all our ways,\",\"and return to the Lord:\",\"let us lift up our hearts and hands\",\"to God in heaven.\",\"The steadfast love...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0667', 667, 'The feast is ready', 'MP', 'en', '1989 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'The trumpets sound, the angels sing,
the feast is ready to begin;
the gates of heaven are open wide,
and Jesus welcomes you inside.
The trumpets sound...
Sing with thankfulness songs of pure delight,
come and revel in heaven’s love and light;
take your place at the table of the King,
the feast is ready to begin,
the feast is ready to begin.
Tables are laden with good things,
O taste the peace and joy He brings;
He’ll fill you up with love divine,
He’ll turn your water into wine.
Sing with thankfulness...
The hungry heart He satisfies,
offers the poor His paradise;
now hear all heaven and earth applaud
the amazing goodness of the Lord.
Sing with thankfulness...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0667', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0667', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0667', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0667', 'verse', 1, 0, '[\"The trumpets sound, the angels sing,\",\"the feast is ready to begin;\",\"the gates of heaven are open wide,\",\"and Jesus welcomes you inside.\",\"The trumpets sound...\",\"Sing with thankfulness songs of pure delight,\",\"come and revel in heaven’s love and light;\",\"take your place at the table of the King,\",\"the feast is ready to begin,\",\"the feast is ready to begin.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0667', 'verse', 2, 1, '[\"Tables are laden with good things,\",\"O taste the peace and joy He brings;\",\"He’ll fill you up with love divine,\",\"He’ll turn your water into wine.\",\"Sing with thankfulness...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0667', 'verse', 3, 2, '[\"The hungry heart He satisfies,\",\"offers the poor His paradise;\",\"now hear all heaven and earth applaud\",\"the amazing goodness of the Lord.\",\"Sing with thankfulness...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0668', 668, 'The world was in darkness', 'MP', 'en', 'New Spring Publishing/Imagem Music/Small Stone Media BV/Song Solutions Daybreak www.songsolutions.org', '', 0, 0, 0, 1, 1, 'The world was in darkness, in sin and shame;
mankind was lost, and then Jesus came.
He carried our sins to Calvary’s tree,
He hung there, and bled there, for you and me.
Thank You, Lord, for saving my soul.
Thank You, Lord, for making me whole.
Thank You, Lord, for giving to me
Thy great salvation so rich and free.
Lord Jesus came down from His throne on high;
ready to live and willing to die.
For all of the pain and the suffering He bore,
I’ll love Him and thank Him for evermore.
Thank You, Lord...
To You I surrender my all today,
the debt I owe, I ne’er could repay,
I’ll serve You with joy wherever You lead,
with this great assurance, You’ll meet my need.
Thank You, Lord...
Words verses 1 and 2 by Seth Sykes
Words verse 3 by Glyn L Taylor');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0668', 'Richard Maxwell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0668', 'William Wirges');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0668', 'Seth Sykes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0668', 'verse', 1, 0, '[\"The world was in darkness, in sin and shame;\",\"mankind was lost, and then Jesus came.\",\"He carried our sins to Calvary’s tree,\",\"He hung there, and bled there, for you and me.\",\"Thank You, Lord, for saving my soul.\",\"Thank You, Lord, for making me whole.\",\"Thank You, Lord, for giving to me\",\"Thy great salvation so rich and free.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0668', 'verse', 2, 1, '[\"Lord Jesus came down from His throne on high;\",\"ready to live and willing to die.\",\"For all of the pain and the suffering He bore,\",\"I’ll love Him and thank Him for evermore.\",\"Thank You, Lord...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0668', 'verse', 3, 2, '[\"To You I surrender my all today,\",\"the debt I owe, I ne’er could repay,\",\"I’ll serve You with joy wherever You lead,\",\"with this great assurance, You’ll meet my need.\",\"Thank You, Lord...\",\"Words verses 1 and 2 by Seth Sykes\",\"Words verse 3 by Glyn L Taylor\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0669', 669, 'Then I saw a new heaven and earth', 'MP', 'en', 'Christopher Idle (b. 1938)/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION             © Norman Warren/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'Then I saw a new heaven and earth,
for the first had passed away;
and the holy city, come down from God,
like a bride on her wedding day:
and I know how He loves His own,
for I heard His great voice tell,
they would be His people, and He their God,
and among them He came to dwell.
He will wipe away every tear,
even death shall die at last;
there’ll be no more sorrow, or grief, or pain,
they belong to the world that’s past:
and the One on the throne said, ‘Look!
I am making all things new’;
He is A and Z, He is First and Last,
and His words are exact and true.
So the thirsty can drink their fill
at the fountain giving life;
but the gates are shut on all evil things,
on deceit and decay and strife:
with foundations and walls and towers,
like a jewel the city shines;
with its streets of gold and its gates of pearl,
in a glory where each combines.
As they measured its length and breadth
I could see no temple there,
for its only temple is God the Lord
and the Lamb in that city fair:
and it needs neither sun nor moon
in a place which knows no night,
for the city’s lamp is the Lamb Himself
and the glory of God its light.
And I saw by the sacred stream
flowing water, crystal clear;
and the tree of life with its healing leaves
and its fruit growing all the year:
so the worshippers of the Lamb
bear His name, and see His face;
and they reign and serve and for ever live
to the praise of His glorious grace.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0669', 'Christopher Idle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0669', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0669', 'verse', 1, 0, '[\"Then I saw a new heaven and earth,\",\"for the first had passed away;\",\"and the holy city, come down from God,\",\"like a bride on her wedding day:\",\"and I know how He loves His own,\",\"for I heard His great voice tell,\",\"they would be His people, and He their God,\",\"and among them He came to dwell.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0669', 'verse', 2, 1, '[\"He will wipe away every tear,\",\"even death shall die at last;\",\"there’ll be no more sorrow, or grief, or pain,\",\"they belong to the world that’s past:\",\"and the One on the throne said, ‘Look!\",\"I am making all things new’;\",\"He is A and Z, He is First and Last,\",\"and His words are exact and true.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0669', 'verse', 3, 2, '[\"So the thirsty can drink their fill\",\"at the fountain giving life;\",\"but the gates are shut on all evil things,\",\"on deceit and decay and strife:\",\"with foundations and walls and towers,\",\"like a jewel the city shines;\",\"with its streets of gold and its gates of pearl,\",\"in a glory where each combines.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0669', 'verse', 4, 3, '[\"As they measured its length and breadth\",\"I could see no temple there,\",\"for its only temple is God the Lord\",\"and the Lamb in that city fair:\",\"and it needs neither sun nor moon\",\"in a place which knows no night,\",\"for the city’s lamp is the Lamb Himself\",\"and the glory of God its light.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0669', 'verse', 5, 4, '[\"And I saw by the sacred stream\",\"flowing water, crystal clear;\",\"and the tree of life with its healing leaves\",\"and its fruit growing all the year:\",\"so the worshippers of the Lamb\",\"bear His name, and see His face;\",\"and they reign and serve and for ever live\",\"to the praise of His glorious grace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0670', 670, 'The strife is o’er', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'The strife is o’er, the battle done;
the victory of life is won;
the song of triumph has begun:
hallelujah!
The powers of death have done their worst,
but Christ their legions has dispersed;
let shouts of holy joy outburst:
hallelujah!
The three sad days have quickly sped:
He rises glorious from the dead;
all glory to our risen Head:
hallelujah!
He broke the bonds of death and hell;
the bars from heaven’s high portals fell;
let hymns of praise His triumph tell:
hallelujah!
Lord, by the stripes which wounded Thee,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0670', 'verse', 1, 0, '[\"The strife is o’er, the battle done;\",\"the victory of life is won;\",\"the song of triumph has begun:\",\"hallelujah!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0670', 'verse', 2, 1, '[\"The powers of death have done their worst,\",\"but Christ their legions has dispersed;\",\"let shouts of holy joy outburst:\",\"hallelujah!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0670', 'verse', 3, 2, '[\"The three sad days have quickly sped:\",\"He rises glorious from the dead;\",\"all glory to our risen Head:\",\"hallelujah!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0670', 'verse', 4, 3, '[\"He broke the bonds of death and hell;\",\"the bars from heaven’s high portals fell;\",\"let hymns of praise His triumph tell:\",\"hallelujah!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0670', 'verse', 5, 4, '[\"Lord, by the stripes which wounded Thee,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0671', 671, 'There is a fountain', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'There is a fountain filled with blood
drawn from Emmanuel’s veins;
and sinners, plunged beneath that flood,
lose all their guilty stains.
The dying thief rejoiced to see
that fountain in his day;
and there may I, as vile as he,
wash all my sins away.
Dear dying Lamb! Your precious blood
shall never lose its power,
till all the ransomed Church of God
be saved, to sin no more.
E’er since, by faith, I saw the stream
Your flowing wounds supply,
redeeming love has been my theme,
and shall be till I die.
Then in a nobler, sweeter song,
I’ll sing Your power to save,
when this poor lisping, stammering tongue
lies silent in the grave.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0671', 'William Cowper');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0671', 'verse', 1, 0, '[\"There is a fountain filled with blood\",\"drawn from Emmanuel’s veins;\",\"and sinners, plunged beneath that flood,\",\"lose all their guilty stains.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0671', 'verse', 2, 1, '[\"The dying thief rejoiced to see\",\"that fountain in his day;\",\"and there may I, as vile as he,\",\"wash all my sins away.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0671', 'verse', 3, 2, '[\"Dear dying Lamb! Your precious blood\",\"shall never lose its power,\",\"till all the ransomed Church of God\",\"be saved, to sin no more.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0671', 'verse', 4, 3, '[\"E’er since, by faith, I saw the stream\",\"Your flowing wounds supply,\",\"redeeming love has been my theme,\",\"and shall be till I die.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0671', 'verse', 5, 4, '[\"Then in a nobler, sweeter song,\",\"I’ll sing Your power to save,\",\"when this poor lisping, stammering tongue\",\"lies silent in the grave.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0672', 672, 'The Saviour’s name', 'MP', 'en', 'Salvationist Publishing & Supplies (Admin. by Song Solutions Copycare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'There is a name I love to hear,
I love to speak its worth;
it sounds like music in my ear,
the sweetest name on earth.
O how I love the Saviour’s name,
O how I love the Saviour’s name,
O how I love the Saviour’s name,
the sweetest name on earth.
It tells me of a Saviour’s love,
who died to set me free;
it tells me of His precious blood,
the sinner’s perfect plea.
O how I love...
It tells of One whose loving heart
can feel my deepest woe,
who in my sorrow bears a part
that none can bear below.
O how I love...
It bids my trembling heart rejoice,
it dries each rising tear;
it tells me in a ‘still, small voice’
to trust and never fear.
O how I love...
Jesus, the name I love so well,
the name I love to hear!
No saints on earth its worth can tell,
no heart conceive how dear!
O how I love...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0672', 'Frederick Whitfield');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0672', 'W H Rudd');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0672', 'verse', 1, 0, '[\"There is a name I love to hear,\",\"I love to speak its worth;\",\"it sounds like music in my ear,\",\"the sweetest name on earth.\",\"O how I love the Saviour’s name,\",\"O how I love the Saviour’s name,\",\"O how I love the Saviour’s name,\",\"the sweetest name on earth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0672', 'verse', 2, 1, '[\"It tells me of a Saviour’s love,\",\"who died to set me free;\",\"it tells me of His precious blood,\",\"the sinner’s perfect plea.\",\"O how I love...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0672', 'verse', 3, 2, '[\"It tells of One whose loving heart\",\"can feel my deepest woe,\",\"who in my sorrow bears a part\",\"that none can bear below.\",\"O how I love...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0672', 'verse', 4, 3, '[\"It bids my trembling heart rejoice,\",\"it dries each rising tear;\",\"it tells me in a ‘still, small voice’\",\"to trust and never fear.\",\"O how I love...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0672', 'verse', 5, 4, '[\"Jesus, the name I love so well,\",\"the name I love to hear!\",\"No saints on earth its worth can tell,\",\"no heart conceive how dear!\",\"O how I love...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0673', 673, 'There is a Redeemer', 'MP', 'en', '1982 Birdwing Music /Ears To Hear Music /Universal Music - Brentwood Benson Publ/CapitolCMGPublishing.com (adm UK/Eire Song Solutions www.songsolutions.org) All rights reserved. Used by permission.', '', 0, 0, 0, 1, 1, 'There is a Redeemer,
Jesus, God’s own Son,
precious Lamb of God, Messiah,
Holy One.
Thank You, O my Father,
for giving us Your Son,
and leaving Your Spirit
till the work on earth is done.
Jesus, my Redeemer,
name above all names,
precious Lamb of God, Messiah,
O for sinners slain:
Thank You...
When I stand in glory
I will see His face,
and there I’ll serve my King for ever
in that holy place.
Thank You...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0673', 'Melody Green');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0673', 'Melody Green');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0673', 'verse', 1, 0, '[\"There is a Redeemer,\",\"Jesus, God’s own Son,\",\"precious Lamb of God, Messiah,\",\"Holy One.\",\"Thank You, O my Father,\",\"for giving us Your Son,\",\"and leaving Your Spirit\",\"till the work on earth is done.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0673', 'verse', 2, 1, '[\"Jesus, my Redeemer,\",\"name above all names,\",\"precious Lamb of God, Messiah,\",\"O for sinners slain:\",\"Thank You...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0673', 'verse', 3, 2, '[\"When I stand in glory\",\"I will see His face,\",\"and there I’ll serve my King for ever\",\"in that holy place.\",\"Thank You...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0674', 674, 'There is a green hill', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'There is a green hill far away
without a city wall,
where the dear Lord was crucified,
who died to save us all.
We may not know, we cannot tell
what pains He had to bear;
but we believe it was for us
He hung and suffered there.
He died that we might be forgiven,
He died to make us good,
that we might go at last to heaven,
saved by His precious blood.
There was no other good enough
to pay the price of sin;
He only could unlock the gate
of heaven, and let us in.
O dearly, dearly has He loved,
and we must love Him too,
and trust in His redeeming blood,
and try His works to do.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0674', 'Cecil Frances Alexander');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0674', 'William Horsley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0674', 'verse', 1, 0, '[\"There is a green hill far away\",\"without a city wall,\",\"where the dear Lord was crucified,\",\"who died to save us all.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0674', 'verse', 2, 1, '[\"We may not know, we cannot tell\",\"what pains He had to bear;\",\"but we believe it was for us\",\"He hung and suffered there.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0674', 'verse', 3, 2, '[\"He died that we might be forgiven,\",\"He died to make us good,\",\"that we might go at last to heaven,\",\"saved by His precious blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0674', 'verse', 4, 3, '[\"There was no other good enough\",\"to pay the price of sin;\",\"He only could unlock the gate\",\"of heaven, and let us in.\"]');
