INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0675', 675, 'There is no condemnation', 'MP', 'en', '©  1978 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'There is no condemnation for those who are in Christ,
for the Spirit of life in Christ has set me free.
O He’s alive, He’s alive, He’s alive,
O He’s alive, He’s alive, He’s alive,
praise the Lord.
If the Spirit of Him who raised Christ from the dead
be born in you, then He will give you life.
O He’s alive...
If God be for us, who can be against us?
For He who sent His Son will freely give us all things.
O He’s alive...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0675', 'Joan Parsons');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0675', 'Joan Parsons');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0675', 'Andy Silver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0675', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0675', 'verse', 1, 0, '[\"There is no condemnation for those who are in Christ,\",\"for the Spirit of life in Christ has set me free.\",\"O He’s alive, He’s alive, He’s alive,\",\"O He’s alive, He’s alive, He’s alive,\",\"praise the Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0675', 'verse', 2, 1, '[\"If the Spirit of Him who raised Christ from the dead\",\"be born in you, then He will give you life.\",\"O He’s alive...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0675', 'verse', 3, 2, '[\"If God be for us, who can be against us?\",\"For He who sent His Son will freely give us all things.\",\"O He’s alive...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0676', 676, 'There is no love like the love of Jesus', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'There is no love like the love of Jesus,
never to fade or fall,
till into the fold of the peace of God
He has gathered us all.
Jesus’ love, precious love,
boundless and pure and free!
O turn to that love, weary wandering soul,
Jesus pleadeth with thee.
There is no heart like the heart of Jesus,
filled with a tender love,
no throb nor throe that our hearts can know
but He feels it above.
Jesus’ love...
O let us hark to the voice of Jesus!
O may we never roam,
till safe we rest on His loving breast
in the dear heavenly home.
Jesus’ love...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0676', 'W E Littlewood');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0676', 'Theodore Edson Perkins');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0676', 'verse', 1, 0, '[\"There is no love like the love of Jesus,\",\"never to fade or fall,\",\"till into the fold of the peace of God\",\"He has gathered us all.\",\"Jesus’ love, precious love,\",\"boundless and pure and free!\",\"O turn to that love, weary wandering soul,\",\"Jesus pleadeth with thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0676', 'verse', 2, 1, '[\"There is no heart like the heart of Jesus,\",\"filled with a tender love,\",\"no throb nor throe that our hearts can know\",\"but He feels it above.\",\"Jesus’ love...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0676', 'verse', 3, 2, '[\"O let us hark to the voice of Jesus!\",\"O may we never roam,\",\"till safe we rest on His loving breast\",\"in the dear heavenly home.\",\"Jesus’ love...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0677', 677, 'There is none holy as the Lord', 'MP', 'en', '1976 Scripture In Song/Maranatha! Music/Universal Music Publishing/Print licence UK Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'There is none holy as the Lord,
there is none beside Thee;
neither is there any rock like our God,
there is none holy as the Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0677', 'Gary Garrett');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0677', 'Gary Garrett');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0677', 'verse', 1, 0, '[\"There is none holy as the Lord,\",\"there is none beside Thee;\",\"neither is there any rock like our God,\",\"there is none holy as the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0678', 678, 'There’s a quiet understanding', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'There’s a quiet understanding
when we’re gathered in the Spirit,
it’s a promise that He gives us,
when we gather in His name.
There’s a love we feel in Jesus,
there’s a manna that He feeds us,
it’s a promise that He gives us
when we gather in His name.
And we know when we’re together,
sharing love and understanding,
that our brothers and our sisters
feel the oneness that He brings.
Thank You, thank You, thank You, Jesus,
for the way You love and feed us,
for the many ways You lead us;
thank You, thank You, Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0678', 'Tedd Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0678', 'Tedd Smith');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0678', 'verse', 1, 0, '[\"There’s a quiet understanding\",\"when we’re gathered in the Spirit,\",\"it’s a promise that He gives us,\",\"when we gather in His name.\",\"There’s a love we feel in Jesus,\",\"there’s a manna that He feeds us,\",\"it’s a promise that He gives us\",\"when we gather in His name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0678', 'verse', 2, 1, '[\"And we know when we’re together,\",\"sharing love and understanding,\",\"that our brothers and our sisters\",\"feel the oneness that He brings.\",\"Thank You, thank You, thank You, Jesus,\",\"for the way You love and feed us,\",\"for the many ways You lead us;\",\"thank You, thank You, Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0679', 679, 'There’s a light upon the mountains', 'MP', 'en', 'Trustees for Methodist Church Purposes. Used with permission.', '', 0, 0, 0, 1, 0, 'There’s a light upon the mountains, and the day is at the spring,
when our eyes shall see the beauty and the glory of the King;
weary was our heart with waiting, and the night-watch seemed so long;kx
but His triumph-day is breaking, and we hail it with a song.
In the fading of the starlight we can see the coming morn;
and the lights of men are paling in the splendours of the dawn:
for the eastern skies are glowing as with light of hidden fire,
and the hearts of men are stirring with the throbs of deep desire.
There’s a hush of expectation, and a quiet in the air;
and the breath of God is moving in the fervent breath of prayer:
for the suffering, dying Jesus is the Christ upon the throne,
and the travail of our spirit is the travail of His own.
He is breaking down the barriers, He is casting up the way;
He is calling for His angels to build up the gates of day:
but His angels here are human, not the shining hosts above;
for the drum-beats of His army are the heart-beats of our love.
Hark! we hear a distant music, and it comes with fuller swell;
’tis the triumph-song of Jesus, of our King, Immanuel:
Zion, go ye forth to meet Him; and, my soul, be swift to bring
all thy sweetness and thy dearest for the triumph of our King!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0679', 'Henry Burton');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0679', 'Maurice L Wostenholm');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0679', 'verse', 1, 0, '[\"There’s a light upon the mountains, and the day is at the spring,\",\"when our eyes shall see the beauty and the glory of the King;\",\"weary was our heart with waiting, and the night-watch seemed so long;kx\",\"but His triumph-day is breaking, and we hail it with a song.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0679', 'verse', 2, 1, '[\"In the fading of the starlight we can see the coming morn;\",\"and the lights of men are paling in the splendours of the dawn:\",\"for the eastern skies are glowing as with light of hidden fire,\",\"and the hearts of men are stirring with the throbs of deep desire.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0679', 'verse', 3, 2, '[\"There’s a hush of expectation, and a quiet in the air;\",\"and the breath of God is moving in the fervent breath of prayer:\",\"for the suffering, dying Jesus is the Christ upon the throne,\",\"and the travail of our spirit is the travail of His own.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0679', 'verse', 4, 3, '[\"He is breaking down the barriers, He is casting up the way;\",\"He is calling for His angels to build up the gates of day:\",\"but His angels here are human, not the shining hosts above;\",\"for the drum-beats of His army are the heart-beats of our love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0679', 'verse', 5, 4, '[\"Hark! we hear a distant music, and it comes with fuller swell;\",\"’tis the triumph-song of Jesus, of our King, Immanuel:\",\"Zion, go ye forth to meet Him; and, my soul, be swift to bring\",\"all thy sweetness and thy dearest for the triumph of our King!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0680', 680, 'There’s a song for all the children', 'MP', 'en', 'in this version The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'There’s a song for all the children
that makes the heavens ring,
a song that even angels
can never never sing;
they praise Him as their maker
and see Him glorified,
but we can call Him Saviour
because for us He died.
There’s a place for all the children
where Jesus reigns in love,
a place of joy and freedom
that nothing can remove;
a home that is more friendly
than any home we know,
where Jesus makes us welcome
because He loves us so.
There’s a friend for all the children
to guide us every day,
whose care is always faithful
and never fades away;
there’s no-one else so loyal –
His friendship stays the same;
He knows us and He loves us,
and Jesus is His name.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0680', 'Albert Midlane');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0680', 'John Stainer');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0680', 'verse', 1, 0, '[\"There’s a song for all the children\",\"that makes the heavens ring,\",\"a song that even angels\",\"can never never sing;\",\"they praise Him as their maker\",\"and see Him glorified,\",\"but we can call Him Saviour\",\"because for us He died.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0680', 'verse', 2, 1, '[\"There’s a place for all the children\",\"where Jesus reigns in love,\",\"a place of joy and freedom\",\"that nothing can remove;\",\"a home that is more friendly\",\"than any home we know,\",\"where Jesus makes us welcome\",\"because He loves us so.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0680', 'verse', 3, 2, '[\"There’s a friend for all the children\",\"to guide us every day,\",\"whose care is always faithful\",\"and never fades away;\",\"there’s no-one else so loyal –\",\"His friendship stays the same;\",\"He knows us and He loves us,\",\"and Jesus is His name.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0681', 681, 'Battle Hymn', 'MP', 'en', '©  1978 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 1, 'There’s a sound on the wind like a victory song;
listen now, let it rest on your soul.
It’s a song that I learned from a heavenly King,
it’s a song of a battle royal.
There’s a loud shout of victory that leaps from our hearts,
as we wait for our conquering King.
There’s a triumph resounding from dark ages past,
to the victory song we now sing.
Come on, heaven’s children,
the city is in sight.
There will be no sadness
on the other side.
There’ll be crowns for the conquerors and white robes to wear,
there will be no more sorrow or pain;
and the battles of earth shall be lost in the sight,
of the glorious Lamb that was slain.
Now the King of the ages approaches the earth,
He will burst through the gates of the sky;
and all men shall bow down to His beautiful name;
we shall rise with a shout, we shall fly!
Come on...
(repeat verse 4)');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0681', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0681', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0681', 'verse', 1, 0, '[\"There’s a sound on the wind like a victory song;\",\"listen now, let it rest on your soul.\",\"It’s a song that I learned from a heavenly King,\",\"it’s a song of a battle royal.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0681', 'verse', 2, 1, '[\"There’s a loud shout of victory that leaps from our hearts,\",\"as we wait for our conquering King.\",\"There’s a triumph resounding from dark ages past,\",\"to the victory song we now sing.\",\"Come on, heaven’s children,\",\"the city is in sight.\",\"There will be no sadness\",\"on the other side.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0681', 'verse', 3, 2, '[\"There’ll be crowns for the conquerors and white robes to wear,\",\"there will be no more sorrow or pain;\",\"and the battles of earth shall be lost in the sight,\",\"of the glorious Lamb that was slain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0681', 'verse', 4, 3, '[\"Now the King of the ages approaches the earth,\",\"He will burst through the gates of the sky;\",\"and all men shall bow down to His beautiful name;\",\"we shall rise with a shout, we shall fly!\",\"Come on...\",\"(repeat verse 4)\"]');
