INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0683', 'verse', 3, 2, '[\"There is grace enough for thousands\",\"of new worlds as great as this;\",\"there is room for fresh creations\",\"in that upper home of bliss.\"]');
