INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0684', 684, 'There’s no greater name', 'MP', 'en', 'Michael A Baughen /The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'There’s no greater name than Jesus,
name of Him who came to save us;
in that saving name so gracious
every knee shall bow.
Let everything that’s beneath the ground,
let everything in the world around,
let everything exalted on high
bow at Jesus’ name.
In our minds, by faith professing,
in our hearts, by inward blessing,
on our tongues, by words confessing,
Jesus Christ is Lord.');
