INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0684', 'verse', 2, 1, '[\"Let everything that’s beneath the ground,\",\"let everything in the world around,\",\"let everything exalted on high\",\"bow at Jesus’ name.\"]');
