INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0685', 685, 'Therefore the redeemed of the Lord', 'MP', 'en', 'Scripture In Song/Maranatha! Music/Universal Music Publishing/Print licence UK Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Therefore the redeemed of the Lord shall return,
and come with singing unto Zion,
and everlasting joy shall be upon their head.
Therefore the redeemed of the Lord shall return,
and come with singing unto Zion,
and everlasting joy shall be upon their head.
They shall obtain gladness and joy,
and sorrow and mourning shall flee away.
Therefore the redeemed of the Lord shall return,
and come with singing unto Zion,
and everlasting joy shall be upon their head.');
