INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0685', 'verse', 1, 0, '[\"Therefore the redeemed of the Lord shall return,\",\"and come with singing unto Zion,\",\"and everlasting joy shall be upon their head.\",\"Therefore the redeemed of the Lord shall return,\",\"and come with singing unto Zion,\",\"and everlasting joy shall be upon their head.\",\"They shall obtain gladness and joy,\",\"and sorrow and mourning shall flee away.\",\"Therefore the redeemed of the Lord shall return,\",\"and come with singing unto Zion,\",\"and everlasting joy shall be upon their head.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0686', 686, 'Therefore we lift our hearts', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Therefore we lift our hearts in praise,
sing to the living God who saves,
for grace poured out for you and me.
There for everyone to see,
there on the hill at Calvary,
Jesus died for you and me.
There for sad and broken men
He rose up from the grave again,
and reigns on high for you and me.
There for such great pain and cost
the Spirit came at Pentecost,
and comes in power for you and me.
Therefore we lift our hearts in praise,
sing to the living God who saves,
for grace poured out for you and me.');
