INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0687', 'Norman Warren');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0687', 'verse', 1, 0, '[\"These are the facts as we have received them,\",\"these are the truths that the Christian believes,\",\"this is the basis of all of our preaching:\",\"Christ died for sinners and rose from the tomb.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0687', 'verse', 2, 1, '[\"These are the facts as we have received them:\",\"Christ has fulfilled what the Scriptures foretold,\",\"Adam’s whole family in death had been sleeping,\",\"Christ through His rising restores us to life.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0687', 'verse', 3, 2, '[\"These are the facts as we have received them:\",\"we, with our Saviour, have died on the cross;\",\"now, having risen, our Jesus lives in us,\",\"gives us His Spirit and makes us His home.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0687', 'verse', 4, 3, '[\"These are the facts as we have received them:\",\"we shall be changed in the blink of an eye,\",\"trumpets shall sound as we face life immortal,\",\"this is the victory through Jesus our Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0687', 'verse', 5, 4, '[\"These are the facts as we have received them,\",\"these are the truths that the Christian believes,\",\"this is the basis of all of our preaching:\",\"Christ died for sinners and rose from the tomb.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0688', 688, 'They that wait upon the Lord', 'MP', 'en', '1987 Andy Silver', '', 0, 0, 0, 1, 1, 'They that wait upon the Lord
shall renew their strength,
and mount on eagles’ wings.
They that wait upon the Lord
shall renew their strength,
and mount on eagles’ wings.
They will run and not grow weary,
they will walk and not be faint.
Those whose hope is in the Lord
shall renew their strength.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0688', 'Andy Silver');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0688', 'Andy Silver');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0688', 'verse', 1, 0, '[\"They that wait upon the Lord\",\"shall renew their strength,\",\"and mount on eagles’ wings.\",\"They that wait upon the Lord\",\"shall renew their strength,\",\"and mount on eagles’ wings.\",\"They will run and not grow weary,\",\"they will walk and not be faint.\",\"Those whose hope is in the Lord\",\"shall renew their strength.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0689', 689, 'Thine be the glory', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Thine be the glory, risen, conquering Son,
endless is the victory Thou o’er death hast won;
angels in bright raiment rolled the stone away,
kept the folded grave-clothes where Thy body lay.
Thine be the glory, risen, conquering Son,
endless is the victory Thou o’er death hast won.
Lo! Jesus meets us, risen from the tomb;
lovingly He greets us, scatters fear and gloom;
let the Church with gladness hymns of triumph sing,
for her Lord now liveth; death hath lost its sting.
Thine be the glory...
No more we doubt Thee, glorious Prince of life;
life is nought without Thee: aid us in our strife;
make us more than conquerors, through Thy deathless love:
bring us safe through Jordan to Thy home above.
Thine be the glory...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0689', 'Edmond Budry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0689', 'George Frideric Handel');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0689', 'verse', 1, 0, '[\"Thine be the glory, risen, conquering Son,\",\"endless is the victory Thou o’er death hast won;\",\"angels in bright raiment rolled the stone away,\",\"kept the folded grave-clothes where Thy body lay.\",\"Thine be the glory, risen, conquering Son,\",\"endless is the victory Thou o’er death hast won.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0689', 'verse', 2, 1, '[\"Lo! Jesus meets us, risen from the tomb;\",\"lovingly He greets us, scatters fear and gloom;\",\"let the Church with gladness hymns of triumph sing,\",\"for her Lord now liveth; death hath lost its sting.\",\"Thine be the glory...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0689', 'verse', 3, 2, '[\"No more we doubt Thee, glorious Prince of life;\",\"life is nought without Thee: aid us in our strife;\",\"make us more than conquerors, through Thy deathless love:\",\"bring us safe through Jordan to Thy home above.\",\"Thine be the glory...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0690', 690, 'This Child', 'MP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'This Child secretly comes in the night,
oh, this Child, hiding a heavenly light,
oh, this Child, coming to us like a stranger,
this heavenly Child.
This Child, heaven come down now to be with us here,
heavenly love and mercy appear,
softly in awe and wonder come near
to this heavenly Child.
This Child, rising on us like the sun,
oh, this Child, given to light everyone,
oh, this Child, guiding our feet on the pathway
to peace on earth.
This Child, heaven come down...
This Child, raising the humble and poor,
oh, this Child, making the proud ones to fall;
this Child, filling the hungry with good things,
this heavenly Child.
This Child, heaven come down...
This Child, heaven come down...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0690', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0690', 'Graham Kendrick');
