INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0690', 'verse', 2, 1, '[\"This Child, rising on us like the sun,\",\"oh, this Child, given to light everyone,\",\"oh, this Child, guiding our feet on the pathway\",\"to peace on earth.\",\"This Child, heaven come down...\"]');
