INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0720', 'verse', 1, 0, '[\"We believe in God the Father,\",\"maker of the universe,\",\"and in Christ His Son our Saviour,\",\"come to us by virgin birth.\",\"We believe He died to save us,\",\"bore our sins, was crucified;\",\"then from death He rose victorious,\",\"ascended to the Father’s side.\",\"Jesus, Lord of all, Lord of all;\",\"Jesus, Lord of all, Lord of all;\",\"Jesus, Lord of all, Lord of all;\",\"Jesus, Lord of all, Lord of all;\",\"name above all names,\",\"name above all names!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0720', 'verse', 2, 1, '[\"We believe He sends His Spirit\",\"on His Church with gifts of power;\",\"God, His word of truth affirming,\",\"sends us to the nations now.\",\"He will come again in glory,\",\"judge the living and the dead:\",\"every knee shall bow before Him,\",\"then must every tongue confess.\",\"Jesus, Lord of all...\",\"Name above all names!\"]');
