INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0723', 723, 'We come as guests invited', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'We come as guests invited
when Jesus bids us dine,
His friends on earth united
to share the bread and wine;
the bread of life is broken,
the wine is freely poured
for us, in solemn token
of Christ our dying Lord.
We eat and drink, receiving');
