INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0725', 'verse', 1, 1, '[\"Behold, our Saviour comes!\",\"behold the Son of our God!\",\"He offers Himself, and He comes among us,\",\"a lowly servant to all.\",\"We cry, ‘Hosanna...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0725', 'verse', 2, 2, '[\"Children wave their palms\",\"as the King of all kings rides by;\",\"should we forget to praise our God,\",\"the very stones would sing.\",\"We cry, ‘Hosanna...\"]');
