INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0726', 726, 'We declare Your majesty', 'MP', 'en', '©  1984 Thankyou Music/Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com for UK & Europe only. Used by permission.', '', 0, 0, 0, 1, 0, 'We declare Your majesty,
we proclaim that Your name is exalted;
for You reign magnificently, rule victoriously,
and Your power is shown throughout the earth.
And we exclaim, ‘Our God is mighty!’
lift up Your name, for You are holy.
Sing it again, all honour and glory –
in adoration we bow before Your throne!');
