INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0728', 728, 'We have a gospel to proclaim', 'MP', 'en', 'Edward Joseph Burns', '', 0, 0, 0, 1, 1, 'We have a gospel to proclaim,
good news for men in all the earth;
the gospel of a saviour’s name:
we sing His glory, tell His worth.
Tell of His birth at Bethlehem,
not in a royal house or hall
but in a stable dark and dim:
the Word made flesh, a light for all.
Tell of His death at Calvary,
hated by those He came to save;
in lonely suffering on the cross
for all He loved, His life He gave.
Tell of that glorious Easter morn:
empty the tomb, for He was free;
He broke the power of death and hell
that we might share His victory.
Tell of His reign at God’s right hand,
by all creation glorified;
He sends His Spirit on His Church
to live for Him, the Lamb who died.
Now we rejoice to name Him king:
Jesus is Lord of all the earth;
this gospel-message we proclaim:
we sing His glory, tell His worth.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0728', 'Edward Joseph Burns');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0728', 'verse', 1, 0, '[\"We have a gospel to proclaim,\",\"good news for men in all the earth;\",\"the gospel of a saviour’s name:\",\"we sing His glory, tell His worth.\"]');
