INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0729', 'Anon');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0729', 'verse', 1, 0, '[\"We have come into His house,\",\"and gathered in His name to worship Him.\",\"We have come into His house,\",\"and gathered in His name to worship Him.\",\"We have come into His house,\",\"and gathered in His name to worship Christ the Lord,\",\"worship Him, Christ the Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0729', 'verse', 2, 1, '[\"So forget about yourself\",\"and concentrate on Him and worship Him.\",\"So forget about yourself\",\"and concentrate on Him and worship Him.\",\"So forget about yourself\",\"and concentrate on Him and worship Christ the Lord,\",\"worship Him, Christ the Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0729', 'verse', 3, 2, '[\"Let us lift up holy hands\",\"and magnify His name and worship Him.\",\"Let us lift up holy hands\",\"and magnify His name and worship Him.\",\"Let us lift up holy hands\",\"and magnify His name and worship Christ the Lord,\",\"worship Him, Christ the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0730', 730, 'We have heard a joyful sound', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'We have heard a joyful sound:
Jesus saves!
Spread the gladness all around:
Jesus saves!
Bear the news to every land,
climb the steeps and cross the waves;
Onward! ’tis our Lord’s command:
Jesus saves!
Sing above the battle’s strife:
Jesus saves!
By His death and endless life,
Jesus saves!
Sing it softly through the gloom,
when the heart for mercy craves;
sing in triumph o’er the tomb:
Jesus saves!
Give the winds a mighty voice:
Jesus saves!
Let the nations now rejoice:
Jesus saves!
Shout salvation full and free
to every strand that ocean laves –
this our song of victory:
Jesus saves!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0730', 'Priscilla Jane Owens');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0730', 'Josiah Booth');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0730', 'verse', 1, 0, '[\"We have heard a joyful sound:\",\"Jesus saves!\",\"Spread the gladness all around:\",\"Jesus saves!\",\"Bear the news to every land,\",\"climb the steeps and cross the waves;\",\"Onward! ’tis our Lord’s command:\",\"Jesus saves!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0730', 'verse', 2, 1, '[\"Sing above the battle’s strife:\",\"Jesus saves!\",\"By His death and endless life,\",\"Jesus saves!\",\"Sing it softly through the gloom,\",\"when the heart for mercy craves;\",\"sing in triumph o’er the tomb:\",\"Jesus saves!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0730', 'verse', 3, 2, '[\"Give the winds a mighty voice:\",\"Jesus saves!\",\"Let the nations now rejoice:\",\"Jesus saves!\",\"Shout salvation full and free\",\"to every strand that ocean laves –\",\"this our song of victory:\",\"Jesus saves!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0731', 731, 'We love the place, O God', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'We love the place, O God,
wherein Thine honour dwells;
the joy of Thine abode
all earthly joy excels.
It is the house of prayer,
wherein Thy servants meet;
and Thou, O Lord, art there,
Thy chosen flock to greet.
We love the word of life,
the word that tells of peace,
of comfort in the strife,
and joys that never cease.
We love to sing below
of mercies freely given;
but O we long to know
the triumph-song of heaven.
Lord Jesus, give us grace,
on earth to love Thee more,
in heaven to see Thy face,
and with Thy saints adore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0731', 'William Bullock');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0731', 'Henry Williams Baker');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0731', 'Henry Lascelles Jenner');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0731', 'verse', 1, 0, '[\"We love the place, O God,\",\"wherein Thine honour dwells;\",\"the joy of Thine abode\",\"all earthly joy excels.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0731', 'verse', 2, 1, '[\"It is the house of prayer,\",\"wherein Thy servants meet;\",\"and Thou, O Lord, art there,\",\"Thy chosen flock to greet.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0731', 'verse', 3, 2, '[\"We love the word of life,\",\"the word that tells of peace,\",\"of comfort in the strife,\",\"and joys that never cease.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0731', 'verse', 4, 3, '[\"We love to sing below\",\"of mercies freely given;\",\"but O we long to know\",\"the triumph-song of heaven.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0731', 'verse', 5, 4, '[\"Lord Jesus, give us grace,\",\"on earth to love Thee more,\",\"in heaven to see Thy face,\",\"and with Thy saints adore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0732', 732, 'We plough the fields', 'MP', 'en', '1986 in this version Horrobin/Leavers', '', 0, 0, 0, 1, 1, 'We plough the fields and scatter
the good seed on the land,
but it is fed and watered
by God’s almighty hand;
He sends the snow in winter,
the warmth to swell the grain,
the breezes and the sunshine
and soft refreshing rain.
All good gifts around us
are sent from heaven above,
then thank the Lord, O thank the Lord,
for all His love.
He only is the maker
of all things near and far;
He paints the wayside flower,
He lights the evening star;
the wind and waves obey Him,
by Him the birds are fed;
much more to us, His children,
He gives our daily bread.
All good gifts...
We thank You then, O Father,
for all things bright and good,
the seed-time and the harvest,
our life, our health, our food.
Accept the gifts we offer
for all Your love imparts;
we come now, Lord, to give You
our humble, thankful hearts.
All good gifts...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0732', 'Matthias Claudius');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0732', 'Jonathan Abraham Peter Schulz');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0732', 'verse', 1, 0, '[\"We plough the fields and scatter\",\"the good seed on the land,\",\"but it is fed and watered\",\"by God’s almighty hand;\",\"He sends the snow in winter,\",\"the warmth to swell the grain,\",\"the breezes and the sunshine\",\"and soft refreshing rain.\",\"All good gifts around us\",\"are sent from heaven above,\",\"then thank the Lord, O thank the Lord,\",\"for all His love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0732', 'verse', 2, 1, '[\"He only is the maker\",\"of all things near and far;\",\"He paints the wayside flower,\",\"He lights the evening star;\",\"the wind and waves obey Him,\",\"by Him the birds are fed;\",\"much more to us, His children,\",\"He gives our daily bread.\",\"All good gifts...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0732', 'verse', 3, 2, '[\"We thank You then, O Father,\",\"for all things bright and good,\",\"the seed-time and the harvest,\",\"our life, our health, our food.\",\"Accept the gifts we offer\",\"for all Your love imparts;\",\"we come now, Lord, to give You\",\"our humble, thankful hearts.\",\"All good gifts...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0733', 733, 'We praise You, we bless You', 'MP', 'en', '1987 in this version Horrobin/Leavers', '', 0, 0, 0, 1, 1, 'We praise You, we bless You, our Saviour divine,
all power and dominion are Yours for all time!
We sing of Your mercy with joyful acclaim,
for You have redeemed us: all praise to Your name!
All honour and praise to Your excellent name,
Your love is unchanging – for ever the same!
We bless and adore You, O Saviour and King;
with joy and thanksgiving Your praises we sing!
The strength of the hills and the depths of the sea,
the earth and its fulness, Yours always shall be;
and yet to the lowly You listen with care,
so ready their humble petitions to hear.
Your infinite goodness our tongues shall employ;
You give to us richly all things to enjoy;
we’ll follow Your footsteps, we’ll rest in Your love,
and soon we shall praise You in mansions above!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0733', 'Fanny J Crosby');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0733', 'verse', 1, 0, '[\"We praise You, we bless You, our Saviour divine,\",\"all power and dominion are Yours for all time!\",\"We sing of Your mercy with joyful acclaim,\",\"for You have redeemed us: all praise to Your name!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0733', 'verse', 2, 1, '[\"All honour and praise to Your excellent name,\",\"Your love is unchanging – for ever the same!\",\"We bless and adore You, O Saviour and King;\",\"with joy and thanksgiving Your praises we sing!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0733', 'verse', 3, 2, '[\"The strength of the hills and the depths of the sea,\",\"the earth and its fulness, Yours always shall be;\",\"and yet to the lowly You listen with care,\",\"so ready their humble petitions to hear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0733', 'verse', 4, 3, '[\"Your infinite goodness our tongues shall employ;\",\"You give to us richly all things to enjoy;\",\"we’ll follow Your footsteps, we’ll rest in Your love,\",\"and soon we shall praise You in mansions above!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0734', 734, 'We really want to thank You, Lord', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'We really want to thank You, Lord,
we really want to bless Your name:
hallelujah! Jesus is our King!
We thank You, Lord, for Your gift to us,
Your life so rich beyond compare,
the gift of Your body here on earth
of which we sing and share.
We really want...
We thank You, Lord, for our life together,
to live and move in the love of Christ,
Your tenderness which sets us free
to serve You with our lives.
We really want...
Praise God from whom all blessings flow,
praise Him all creatures here below,
praise Him above, you heavenly host,
praise Father, Son and Holy Ghost.
We really want...');
