INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0734', 'verse', 1, 1, '[\"We thank You, Lord, for Your gift to us,\",\"Your life so rich beyond compare,\",\"the gift of Your body here on earth\",\"of which we sing and share.\",\"We really want...\"]');
