INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0736', 736, 'We see the Lord', 'MP', 'en', 'control                        arrangement: ? 1974 Celebration / kingswaysongs.com. tym@kingsway.co.uk. For Europe and Commonwealth (excl. Canada, Australasia and Africa). Used by permission.', '', 0, 0, 0, 1, 0, 'We see the Lord,
we see the Lord,
and He is high and lifted up,
and His train fills the temple;
He is high and lifted up,
and His train fills the temple.
The angels cry, ‘Holy’,
the angels cry, ‘Holy’,
the angels cry, ‘Holy is the Lord.’');
