INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0737', 737, 'We shall stand', 'MP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'We shall stand, with our feet on the rock;
whatever men may say, we’ll lift Your name up high –
and we shall walk through the darkest night;
setting our faces like flint,
we’ll walk into the light!
Lord, You have chosen me for fruitfulness
to be transformed into Your likeness:
I’m going to fight on through till I see You
face to face.
We shall stand...
Lord, as Your witnesses You’ve appointed us,
and with Your Holy Spirit anointed us:
and so I’ll fight on through till I see You
face to face.
We shall stand...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0737', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0737', 'Graham Kendrick');
