INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0738', 'verse', 4, 3, '[\"It makes the coward spirit brave,\",\"and nerves the feeble arm for fight;\",\"it takes the terror from the grave,\",\"and gilds the bed of death with light.\"]');
