INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0739', 739, 'We will sing of our Redeemer', 'MP', 'en', 'David Brattle', '', 0, 0, 0, 1, 1, 'We will sing of our Redeemer,
He’s our King:
all His glory, all His praise
to you we bring;
with our hearts and with our voices
Him we sing,
we love the Lord, we love His word;
He’s our King.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0739', 'Gordon Brattle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0739', 'Gordon Brattle');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0739', 'verse', 1, 0, '[\"We will sing of our Redeemer,\",\"He’s our King:\",\"all His glory, all His praise\",\"to you we bring;\",\"with our hearts and with our voices\",\"Him we sing,\",\"we love the Lord, we love His word;\",\"He’s our King.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0740', 740, 'We three kings of Orient are', 'MP', 'en', '1986 in this version Horrobin/Leavers', '', 0, 0, 0, 1, 1, 'We three kings of Orient are,
bearing gifts we travel afar,
field and fountain, moor and mountain,
following yonder star:
O star of wonder, star of night,
star with royal beauty bright,
westward leading, still proceeding,
guide us to the perfect light.
Born a King on Bethlehem plain,
gold I bring to crown Him again:
King for ever, ceasing never,
over us all to reign.
O star of wonder...
Frankincense for Jesus have I,
God on earth yet Priest on high;
prayer and praising all men raising:
worship is earth’s reply.
O star of wonder...
Myrrh is mine: its bitter perfume
tells of His death and Calvary’s gloom;
sorrowing, sighing, bleeding, dying,
sealed in a stone-cold tomb.
O star of wonder...
Glorious now, behold Him arise,
King, and God, and sacrifice!
Heaven sings out, ‘Alleluia!’,
‘Amen!’ the earth replies.
O star of wonder...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0740', 'John H Hopkins');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0740', 'John H Hopkins');
