INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0741', 741, 'We Your people', 'MP', 'en', 'Serious Music UK Ltd', '', 0, 0, 0, 1, 1, 'We Your people bow before You
broken and ashamed;
we have turned on Your creation,
crushed the life You freely gave.
Lord, have mercy on Your children
weeping and in fear:
for You are our God and Saviour,
Father, in Your love draw near.
Father, in this hour of danger
we will turn to You:
O forgive us, Lord, forgive us
and our lives and faith renew.
Pour Your Holy Spirit on us,
set our hearts aflame:
all shall see Your power in the nations,
may we bring glory to Your name.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0741', 'Adrian Snell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0741', 'Adrian Snell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0741', 'verse', 1, 0, '[\"We Your people bow before You\",\"broken and ashamed;\",\"we have turned on Your creation,\",\"crushed the life You freely gave.\"]');
