INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0749', 749, 'What child is this', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'What child is this, who, laid to rest,
on Mary’s lap is sleeping?
Whom angels greet with anthems sweet,
while shepherds watch are keeping?
This, this is Christ the King,
whom shepherds guard and angels sing:
haste, haste to bring Him praise,
the babe, the Son of Mary.
Why lies He in such mean estate,
where ox and ass are feeding?
Good Christian fear: for sinners here
the silent Word is pleading.
This, this is Christ...
So bring Him incense, gold, and myrrh,
come, peasant, king, to own Him.
The King of kings salvation brings,
let loving hearts enthrone Him.
This, this is Christ...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0749', 'William Chatterton Dix');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0749', 'verse', 1, 0, '[\"What child is this, who, laid to rest,\",\"on Mary’s lap is sleeping?\",\"Whom angels greet with anthems sweet,\",\"while shepherds watch are keeping?\",\"This, this is Christ the King,\",\"whom shepherds guard and angels sing:\",\"haste, haste to bring Him praise,\",\"the babe, the Son of Mary.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0749', 'verse', 2, 1, '[\"Why lies He in such mean estate,\",\"where ox and ass are feeding?\",\"Good Christian fear: for sinners here\",\"the silent Word is pleading.\",\"This, this is Christ...\"]');
