INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0751', 751, 'When all Your mercies', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'When all Your mercies, O my God,
my rising soul surveys,
transported with the view, I’m lost
in wonder, love, and praise.
Unnumbered comforts on my soul
Your tender care bestowed,
before my infant heart conceived');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0751', 'Joseph Addison');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0751', 'Frederick Arthur Gore Ouseley');
