INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0752', 'verse', 2, 1, '[\"When He comes His reign shall bring peace;\",\"when He comes all fighting shall cease.\",\"Men shall hammer their spears into pruning hooks\",\"and prepare for battle no more.\",\"When He comes, when He comes.\",\"And on that day there will be laughter;\",\"on that day joy ever after, no more tears:\",\"for the Lord will wipe them all away.\",\"And on that day, men shall be brothers,\",\"reconciled to God and each other;\",\"the world shall see the King in His glory,\",\"when He comes.\"]');
