INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0759', 'verse', 2, 1, '[\"On that bright and cloudless morning when the dead in Christ shall rise,\",\"and the glory of His resurrection share;\",\"when His chosen ones shall gather to their home beyond the skies,\",\"and the roll is called up yonder, I’ll be there.\",\"When the roll is called...\"]');
