INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0762', 762, 'Wherever I am', 'MP', 'en', 'control                         Music arrangement: © David Peacock /The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'Wherever I am, I’ll praise Him,
whenever I can, I’ll praise Him;
for His love surrounds me like a sea;
I’ll praise the name of Jesus,
lift up the name of Jesus,
for the name of Jesus lifted me.');
