INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0764', 764, 'While shepherds watched', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'While shepherds watched their flocks by night,
all seated on the ground,
the angel of the Lord came down
and glory shone around.
‘Fear not,’ said he – for mighty dread
had seized their troubled mind –
‘Glad tidings of great joy I bring
to you and all mankind:
‘To you in David’s town this day
is born of David’s line,
a Saviour, who is Christ the Lord.
And this shall be the sign:
‘The heavenly babe you there shall find
to human view displayed,
all meanly wrapped in swaddling bands,
and in a manger laid.’
Thus spake the angel; and forthwith
appeared a shining throng
of angels praising God, who thus
addressed their joyful song:
‘All glory be to God on high,
and to the earth be peace;
goodwill henceforth from heaven to men
begin and never cease!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0764', 'Nahum Tate');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0764', 'verse', 1, 0, '[\"While shepherds watched their flocks by night,\",\"all seated on the ground,\",\"the angel of the Lord came down\",\"and glory shone around.\"]');
