INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0764', 'verse', 3, 2, '[\"‘To you in David’s town this day\",\"is born of David’s line,\",\"a Saviour, who is Christ the Lord.\",\"And this shall be the sign:\"]');
