INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0766', 766, 'Who can sound the depths of sorrow', 'MP', 'en', '1988 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Who can sound the depths of sorrow
in the father heart of God,
for the children we’ve rejected,
for the lives so deeply scarred?
And each light that we’ve extinguished
has brought darkness to our land:
upon the nation, upon the nation
have mercy, Lord!
We have scorned the truth You gave us,
we have bowed to other lords,
we have sacrificed the children
on the altars of our gods.
O let truth again shine on us,
let Your holy fear descend:
upon the nation, upon the nation
have mercy, Lord!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0766', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0766', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0766', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0766', 'verse', 1, 0, '[\"Who can sound the depths of sorrow\",\"in the father heart of God,\",\"for the children we’ve rejected,\",\"for the lives so deeply scarred?\",\"And each light that we’ve extinguished\",\"has brought darkness to our land:\",\"upon the nation, upon the nation\",\"have mercy, Lord!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0766', 'verse', 2, 1, '[\"We have scorned the truth You gave us,\",\"we have bowed to other lords,\",\"we have sacrificed the children\",\"on the altars of our gods.\",\"O let truth again shine on us,\",\"let Your holy fear descend:\",\"upon the nation, upon the nation\",\"have mercy, Lord!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0767', 767, 'Who is He, in yonder stall', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Who is He, in yonder stall,
at whose feet the shepherds fall?
’Tis the Lord! O wondrous story!
’Tis the Lord! the King of glory!
At His feet we humbly fall;
crown Him, crown Him Lord of all.
Who is He, in yonder cot,
bending to His toilsome lot?
’Tis the Lord...
Who is He, in deep distress,
fasting in the wilderness?
’Tis the Lord...
Who is He, that stands and weeps
at the grave where Lazarus sleeps?
’Tis the Lord...
Lo, at midnight, who is He
prays in dark Gethsemane?
’Tis the Lord...
Who is He, in Calvary’s throes,
asks for blessings on His foes?
’Tis the Lord...
Who is He that from the grave
comes to heal and help and save?
’Tis the Lord...
Who is He that from His throne
rules through all the worlds alone?
’Tis the Lord...');
