INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0768', 768, 'Who is like unto Thee', 'MP', 'en', '© 1975 Integrity\'s Hosanna! Music / adm worldwide by Capitol CMG Publishing excl UK admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com) Used by Permission', '', 0, 0, 0, 1, 0, 'Who is like unto Thee,
O Lord among gods?
Who is like unto Thee?
Glorious in holiness,
fearful in praises,
doing wonders;
who is like unto Thee?');
