INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0775', 775, 'With my heart I worship You', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'With my heart I worship You, Jesus, Jesus;
with my heart I worship You, Jesus, Jesus:
You gave all in love for me,
saved me for eternity;
with my heart I worship You.');
