INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0776', 776, 'Wonderful counsellor, the mighty God', 'MP', 'en', '©  1980 Authentic Music / Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'Wonderful counsellor,
the mighty God,
the everlasting Father,
the Prince of peace,
the Prince of peace,
the everlasting Father,
the mighty God.
Wonderful counsellor,
wonderful counsellor,
wonderful is the name of Jesus,
wonderful counsellor,
wonderful counsellor,
wonderful is the name of Jesus.');
