INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0777', 777, 'Wonderful counsellor, Jesus', 'MP', 'en', '1972 CCCM Music/Maranatha!Music/Universal Music /Print licence UK Song Solutions Daybreak  www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Wonderful counsellor, Jesus:
search me, know me, Jesus;
lead me, guide me, Jesus –
Wonderful counsellor, Jesus.
Mighty God, Son of God, Jesus;
name above all other names, Jesus:
glorify, magnify Jesus –
mighty God, Son of God, Jesus.
Everlasting Father, Jesus;
Holy and unchangeable, Jesus:
fill me with Your presence, Jesus –
everlasting Father, Jesus.
Prince of peace, rule my heart, Jesus;
know my every anxious thought, Jesus;
calm my fears, dry my tears, Jesus –
Prince of peace, rule my heart, Jesus.
Wonderful counsellor, Jesus;
mighty God, Son of God, Jesus;
everlasting Father, Jesus –
Prince of peace, rule my heart, Jesus.');
