INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0777', 'verse', 2, 1, '[\"Mighty God, Son of God, Jesus;\",\"name above all other names, Jesus:\",\"glorify, magnify Jesus –\",\"mighty God, Son of God, Jesus.\"]');
