INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0777', 'verse', 5, 4, '[\"Wonderful counsellor, Jesus;\",\"mighty God, Son of God, Jesus;\",\"everlasting Father, Jesus –\",\"Prince of peace, rule my heart, Jesus.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0778', 778, 'Within the veil', 'MP', 'en', '©  1978 Genesis Music / Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'Within the veil I now would come,
into the holy place to look upon Thy face.
I see such beauty there, no other can compare,
I worship Thee, my Lord, within the veil.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0778', 'Ruth Dryden');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0778', 'Ruth Dryden');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0778', 'verse', 1, 0, '[\"Within the veil I now would come,\",\"into the holy place to look upon Thy face.\",\"I see such beauty there, no other can compare,\",\"I worship Thee, my Lord, within the veil.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0779', 779, 'Worthy art Thou, O Lord', 'MP', 'en', '©  1979 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Worthy art Thou, O Lord, our God, of honour and power,
for You are reigning now on high, hallelujah.
Jesus is Lord of all the earth,
hallelujah, hallelujah, hallelujah.');
