INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0780', 780, 'Worthy is the Lamb', 'MP', 'en', '2000 Wondrous Worship (Adm Music Service/Song Solutions www.songsolutions.org). All rights reserved Used by permission.                        arrangement: ? Roland Fudge', '', 0, 0, 0, 1, 1, 'Worthy is the Lamb;
worthy is the Lamb;
worthy is the Lamb;
worthy is the Lamb.
Holy is the Lamb...
Precious is the Lamb...
Praises to the Lamb...
Glory to the Lamb...
Jesus is our Lamb...');
