INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0781', 781, 'Worthy is the Lamb seated', 'MP', 'en', 'Copyright 1983 Restoration Music Sovereignmusic@aol.com', '', 0, 0, 0, 1, 1, 'Worthy is the Lamb seated on the throne,
worthy is the Lamb who was slain,
to receive power and riches,
and wisdom and strength,
honour and glory,
glory and praise,
for ever and evermore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0781', 'David Hadden');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0781', 'David Hadden');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0781', 'verse', 1, 0, '[\"Worthy is the Lamb seated on the throne,\",\"worthy is the Lamb who was slain,\",\"to receive power and riches,\",\"and wisdom and strength,\",\"honour and glory,\",\"glory and praise,\",\"for ever and evermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0782', 782, 'Worthy, O worthy are You, Lord', 'MP', 'en', 'The Servants of the Word/Administered by Coltaman International, 8 Marshfoot Lane, Hailsham, BN27 2RA, UK', '', 0, 0, 0, 1, 1, 'Worthy, O worthy are You, Lord,
worthy to be thanked and praised
and worshipped and adored;
worthy, O worthy are You, Lord,
worthy to be thanked and praised
and worshipped and adored.
Singing, ‘Hallelujah!
Lamb upon the throne,
we worship and adore You,
make Your glory known.
Hallelujah,
glory to the King:
You’re more than a conqueror,
You’re Lord of everything!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0782', 'Mark S Kinzer');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0782', 'Mark S Kinzer');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0782', 'verse', 1, 0, '[\"Worthy, O worthy are You, Lord,\",\"worthy to be thanked and praised\",\"and worshipped and adored;\",\"worthy, O worthy are You, Lord,\",\"worthy to be thanked and praised\",\"and worshipped and adored.\",\"Singing, ‘Hallelujah!\",\"Lamb upon the throne,\",\"we worship and adore You,\",\"make Your glory known.\",\"Hallelujah,\",\"glory to the King:\",\"You’re more than a conqueror,\",\"You’re Lord of everything!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0783', 783, 'Ye holy angels bright', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Ye holy angels bright,
who wait at God’s right hand,
or through the realms of light
fly at your Lord’s command,
assist our song,
or else the theme
too high doth seem
for mortal tongue.
Ye blessèd souls at rest,
who see your Saviour’s face,
whose glory, e’en the least
is far above our grace,
God’s praises sound,
as in His sight
with sweet delight
ye do abound.
Ye saints, who toil below,
adore your heavenly King,
and onward as ye go
some joyful anthem sing;
take what He gives
and praise Him still,
through good and ill,
who ever lives!
My soul, bear thou thy part,
triumph in God above:
and with a well-tuned heart
sing thou the songs of love!
Let all thy days
till life shall end,
whate’er He send,
be filled with praise.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0783', 'Richard Baxter');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0783', 'John Darwall');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0783', 'verse', 1, 0, '[\"Ye holy angels bright,\",\"who wait at God’s right hand,\",\"or through the realms of light\",\"fly at your Lord’s command,\",\"assist our song,\",\"or else the theme\",\"too high doth seem\",\"for mortal tongue.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0783', 'verse', 2, 1, '[\"Ye blessèd souls at rest,\",\"who see your Saviour’s face,\",\"whose glory, e’en the least\",\"is far above our grace,\",\"God’s praises sound,\",\"as in His sight\",\"with sweet delight\",\"ye do abound.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0783', 'verse', 3, 2, '[\"Ye saints, who toil below,\",\"adore your heavenly King,\",\"and onward as ye go\",\"some joyful anthem sing;\",\"take what He gives\",\"and praise Him still,\",\"through good and ill,\",\"who ever lives!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0783', 'verse', 4, 3, '[\"My soul, bear thou thy part,\",\"triumph in God above:\",\"and with a well-tuned heart\",\"sing thou the songs of love!\",\"Let all thy days\",\"till life shall end,\",\"whate’er He send,\",\"be filled with praise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0784', 784, 'Ye servants of God', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Ye servants of God,
your Master proclaim,
and publish abroad
His wonderful name;
the name all-victorious
of Jesus extol;
His kingdom is glorious,
and rules over all.
God ruleth on high,
almighty to save;
and still He is nigh,
His presence we have;
the great congregation
His triumph shall sing,
ascribing salvation
to Jesus our King.
‘Salvation to God
who sits on the throne’,
let all cry aloud,
and honour the Son:
the praises of Jesus
the angels proclaim,
fall down on their faces,
and worship the Lamb.
Then let us adore,
and give Him His right –
all glory and power,
all wisdom and might:
all honour and blessing,
with angels above;
and thanks never-ceasing,
and infinite love.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0784', 'Charles Wesley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0784', 'Charles Hubert Hastings Parry');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0784', 'verse', 1, 0, '[\"Ye servants of God,\",\"your Master proclaim,\",\"and publish abroad\",\"His wonderful name;\",\"the name all-victorious\",\"of Jesus extol;\",\"His kingdom is glorious,\",\"and rules over all.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0784', 'verse', 2, 1, '[\"God ruleth on high,\",\"almighty to save;\",\"and still He is nigh,\",\"His presence we have;\",\"the great congregation\",\"His triumph shall sing,\",\"ascribing salvation\",\"to Jesus our King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0784', 'verse', 3, 2, '[\"‘Salvation to God\",\"who sits on the throne’,\",\"let all cry aloud,\",\"and honour the Son:\",\"the praises of Jesus\",\"the angels proclaim,\",\"fall down on their faces,\",\"and worship the Lamb.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0784', 'verse', 4, 3, '[\"Then let us adore,\",\"and give Him His right –\",\"all glory and power,\",\"all wisdom and might:\",\"all honour and blessing,\",\"with angels above;\",\"and thanks never-ceasing,\",\"and infinite love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0785', 785, 'Yes, power belongs to You, O Lord', 'MP', 'en', '1984 Colin Preston, 81 Howth Drive, Woodley, Reading, Berks, UK', '', 0, 0, 0, 1, 1, 'Yes, power belongs to You, O Lord,
in You we put our trust;
You are sovereign over all,
great are You.
Great in Your mercy, Lord,
great in Your love,
a mighty warrior in whom we trust.
Glorify Your name,
glorify Your name,
glorify Your name.
Don’t worry about the opposition,
for I stand with the few;
the proud, the violent godless man
will know I stand with you.
Yes, power belongs...
Do not fear nor be dismayed,
the battle is not yours;
you shall not need to fight, but stand
and see salvation of the Lord.
Yes, power belongs...
Be still and know that I am God,
and wait upon My word,
responding to My Spirit’s voice,
with your breath and praise do war.
Yes, power belongs...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0785', 'Colin Preston');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0785', 'Colin Preston');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0785', 'Chris Mitchell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0785', 'chorus', 0, 0, '[\"Yes, power belongs to You, O Lord,\",\"in You we put our trust;\",\"You are sovereign over all,\",\"great are You.\",\"Great in Your mercy, Lord,\",\"great in Your love,\",\"a mighty warrior in whom we trust.\",\"Glorify Your name,\",\"glorify Your name,\",\"glorify Your name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0785', 'verse', 1, 1, '[\"Don’t worry about the opposition,\",\"for I stand with the few;\",\"the proud, the violent godless man\",\"will know I stand with you.\",\"Yes, power belongs...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0785', 'verse', 2, 2, '[\"Do not fear nor be dismayed,\",\"the battle is not yours;\",\"you shall not need to fight, but stand\",\"and see salvation of the Lord.\",\"Yes, power belongs...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0785', 'verse', 3, 3, '[\"Be still and know that I am God,\",\"and wait upon My word,\",\"responding to My Spirit’s voice,\",\"with your breath and praise do war.\",\"Yes, power belongs...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0786', 786, 'Yes, God is good', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Yes, God is good – in earth and sky,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0786', 'John Hampden Gurney');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0786', 'verse', 1, 0, '[\"Yes, God is good – in earth and sky,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0787', 787, 'Yesterday, today, for ever', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Yesterday, today, for ever,
Jesus is the same;
all may change, but Jesus never,
glory to His name!
Glory to His name!
Glory to His name!
All may change, but Jesus never,
glory to His name!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0787', 'Albert B Simpson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0787', 'James H Burke');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0787', 'verse', 1, 0, '[\"Yesterday, today, for ever,\",\"Jesus is the same;\",\"all may change, but Jesus never,\",\"glory to His name!\",\"Glory to His name!\",\"Glory to His name!\",\"All may change, but Jesus never,\",\"glory to His name!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0788', 788, 'I stand in awe', 'MP', 'en', '1987 People of Destiny International, administered by Copycare PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.', '', 0, 0, 0, 1, 0, 'You are beautiful beyond description,
too marvellous for words,
too wonderful for comprehension,
like nothing ever seen or heard.
Who can grasp Your infinite wisdom?
Who can fathom the depth of Your love?
You are beautiful beyond description,
Majesty, enthroned above.
And I stand, I stand in awe of You;
I stand, I stand in awe of You.
Holy God, to whom all praise is due,
I stand in awe of You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0788', 'Mark Altrogge');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0788', 'Mark Altrogge');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0788', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0788', 'verse', 1, 0, '[\"You are beautiful beyond description,\",\"too marvellous for words,\",\"too wonderful for comprehension,\",\"like nothing ever seen or heard.\",\"Who can grasp Your infinite wisdom?\",\"Who can fathom the depth of Your love?\",\"You are beautiful beyond description,\",\"Majesty, enthroned above.\",\"And I stand, I stand in awe of You;\",\"I stand, I stand in awe of You.\",\"Holy God, to whom all praise is due,\",\"I stand in awe of You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0789', 789, 'You are coming', 'MP', 'en', 'in this version Horrobin/Leavers', '', 0, 0, 0, 1, 1, 'You are coming, O my Saviour,
You are coming, O my King,
in Your beauty all-resplendent,
in Your glory all-transcendent –
well may we rejoice and sing:
coming soon, my living Lord,
heralds sing Your glorious praise;
coming! now on earth adored,
songs of triumph we shall raise.
You are coming, You are coming,
we shall meet You on Your way,
we shall see You, we shall see You,
we shall bless You, we shall show You
all our hearts could never say.
What an anthem that will be,
ringing out eternally,
earth’s and heaven’s praises meet,
at Your own all-glorious feet!
O the joy to see You reigning,
You, my own belovèd Lord!
Every tongue Your name confessing,
worship, honour, glory, blessing
brought to You with glad accord –
You, my Master and my friend,
vindicated and enthroned,
unto earth’s remotest end
glorified, adored, and owned!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0789', 'Frances Ridley Havergal');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0789', 'William Henry Monk');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0789', 'verse', 1, 0, '[\"You are coming, O my Saviour,\",\"You are coming, O my King,\",\"in Your beauty all-resplendent,\",\"in Your glory all-transcendent –\",\"well may we rejoice and sing:\",\"coming soon, my living Lord,\",\"heralds sing Your glorious praise;\",\"coming! now on earth adored,\",\"songs of triumph we shall raise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0789', 'verse', 2, 1, '[\"You are coming, You are coming,\",\"we shall meet You on Your way,\",\"we shall see You, we shall see You,\",\"we shall bless You, we shall show You\",\"all our hearts could never say.\",\"What an anthem that will be,\",\"ringing out eternally,\",\"earth’s and heaven’s praises meet,\",\"at Your own all-glorious feet!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0789', 'verse', 3, 2, '[\"O the joy to see You reigning,\",\"You, my own belovèd Lord!\",\"Every tongue Your name confessing,\",\"worship, honour, glory, blessing\",\"brought to You with glad accord –\",\"You, my Master and my friend,\",\"vindicated and enthroned,\",\"unto earth’s remotest end\",\"glorified, adored, and owned!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0790', 790, 'Hosanna to the Son of David', 'MP', 'en', '1978 Authentic Publishing, administered by CopyCare, PO Box 77, Hailsham BN27 3EF, UK. music@copycare.com. Used by permission.', '', 0, 0, 0, 1, 1, 'You are the King of glory,
You are the Prince of peace,
You are the Lord of heaven and earth,
You’re the Son of righteousness.
Angels bow down before You,
worship and adore,
for You have the words of eternal life,
You are Jesus Christ the Lord.
Hosanna to the Son of David!
Hosanna to the King of kings!
Glory in the highest heaven,
for Jesus the Messiah reigns!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0790', 'Mavis Ford');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0790', 'Mavis Ford');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0790', 'verse', 1, 0, '[\"You are the King of glory,\",\"You are the Prince of peace,\",\"You are the Lord of heaven and earth,\",\"You’re the Son of righteousness.\",\"Angels bow down before You,\",\"worship and adore,\",\"for You have the words of eternal life,\",\"You are Jesus Christ the Lord.\",\"Hosanna to the Son of David!\",\"Hosanna to the King of kings!\",\"Glory in the highest heaven,\",\"for Jesus the Messiah reigns!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0791', 791, 'You are the mighty King', 'MP', 'en', 'Mercy/Vineyard Publishing/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'You are the mighty King,
the living Word;
Master of everything –
You are the Lord.
And I praise Your name,
and I praise Your name.
You are almighty God,
Saviour and Lord;
wonderful counsellor,
You are the Lord.
And I praise Your name,
and I praise Your name.
You are the Prince of peace,
Emmanuel;
everlasting Father,
You are the Lord.
And I love Your name,
and I love Your name.
You are the mighty King,
the living Word;
Master of everything,
You are the Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0791', 'Eddie Espinosa');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0791', 'Eddie Espinosa');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0791', 'Roger Mayor');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0791', 'verse', 1, 0, '[\"You are the mighty King,\",\"the living Word;\",\"Master of everything –\",\"You are the Lord.\",\"And I praise Your name,\",\"and I praise Your name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0791', 'verse', 2, 1, '[\"You are almighty God,\",\"Saviour and Lord;\",\"wonderful counsellor,\",\"You are the Lord.\",\"And I praise Your name,\",\"and I praise Your name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0791', 'verse', 3, 2, '[\"You are the Prince of peace,\",\"Emmanuel;\",\"everlasting Father,\",\"You are the Lord.\",\"And I love Your name,\",\"and I love Your name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0791', 'verse', 4, 3, '[\"You are the mighty King,\",\"the living Word;\",\"Master of everything,\",\"You are the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0792', 792, 'You are the vine', 'MP', 'en', '1985 Mercy/Vineyard Publishing/ Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'You are the vine,
we are the branches,
keep us abiding in You.
You are the vine,
we are the branches,
keep us abiding in You.
Then we’ll grow in Your love,
then we’ll go in Your name,
that the world will surely know
that You have power to heal and to save.
You are the vine,
we are the branches,
keep us abiding in You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0792', 'Danny Daniels');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0792', 'Randy Rigby');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0792', 'Danny Daniels');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0792', 'Randy Rigby');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0792', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0792', 'verse', 1, 0, '[\"You are the vine,\",\"we are the branches,\",\"keep us abiding in You.\",\"You are the vine,\",\"we are the branches,\",\"keep us abiding in You.\",\"Then we’ll grow in Your love,\",\"then we’ll go in Your name,\",\"that the world will surely know\",\"that You have power to heal and to save.\",\"You are the vine,\",\"we are the branches,\",\"keep us abiding in You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0793', 793, 'You are my hiding-place', 'MP', 'en', '1981 CCCM Music/Maranatha! Music/Universal Music Publishing/Print licence UK Song Solutions Daybreak www.songsolutions.org', '', 0, 0, 0, 1, 1, 'You are my hiding-place,
You always fill my heart
with songs of deliverance
whenever I am afraid.
I will trust in You,
I will trust in You,
let the weak say:
‘I am strong in the strength of my God.’');
