INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0793', 'Michael Ledner');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0793', 'verse', 1, 0, '[\"You are my hiding-place,\",\"You always fill my heart\",\"with songs of deliverance\",\"whenever I am afraid.\",\"I will trust in You,\",\"I will trust in You,\",\"let the weak say:\",\"‘I am strong in the strength of my God.’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0794', 794, 'You are worthy', 'MP', 'en', '1982 Millennium Dawn Music/Sovereign Music UK, PO Box 356, Leighton Buzzard LU7 3WP, UK. sovereignmusic@aol.com', '', 0, 0, 0, 1, 1, 'You are worthy, Lord,
You are worthy, so I lift my heart,
I lift my voice and cry, ‘Holy’.
You have saved me, and I love You,
Jesus, evermore
I live to praise Your name.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0794', 'John Daniel Lawtum');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0794', 'John Daniel Lawtum');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0794', 'verse', 1, 0, '[\"You are worthy, Lord,\",\"You are worthy, so I lift my heart,\",\"I lift my voice and cry, ‘Holy’.\",\"You have saved me, and I love You,\",\"Jesus, evermore\",\"I live to praise Your name.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0795', 795, 'I really want to worship You', 'MP', 'en', '1985 Thankyou Music, administered by worshiptogether.com songs excl. UK and Europe, administered by kingswaysongs.com. tym@kingsway.co.uk. Used by permission.', '', 0, 0, 0, 1, 0, 'You laid aside Your majesty,
gave up everything for me,
suffered at the hands of those You had created;
You took all my guilt and shame,
when You died and rose again;
now today You reign in heaven and earth exalted.
I really want to worship You, my Lord,
You have won my heart and I am Yours.
For ever and ever I will love You.
You are the only one who died for me,
gave Your life to set me free,
so I lift my voice to You in adoration.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0795', 'Noel Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0795', 'Noel Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0795', 'Roger Mayor');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0795', 'verse', 1, 0, '[\"You laid aside Your majesty,\",\"gave up everything for me,\",\"suffered at the hands of those You had created;\",\"You took all my guilt and shame,\",\"when You died and rose again;\",\"now today You reign in heaven and earth exalted.\",\"I really want to worship You, my Lord,\",\"You have won my heart and I am Yours.\",\"For ever and ever I will love You.\",\"You are the only one who died for me,\",\"gave Your life to set me free,\",\"so I lift my voice to You in adoration.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0796', 796, 'You shall go out with joy', 'MP', 'en', '1975 Lillenas Publishing Company/Msi Music Adm/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'You shall go out with joy
and be led forth with peace,
and the mountains and the hills
shall break forth before you.
There’ll be shouts of joy
and the trees of the field
shall clap, shall clap their hands,
and the trees of the field
shall clap their hands,
and the trees of the field
shall clap their hands,
and the trees of the field
shall clap their hands,
and you’ll go out with joy.');
