INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0797', 797, 'Your love is to me', 'MP', 'en', '© 1982 Authentic Publishing/Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'Your love is to me like an ever-flowing stream,
Your love is to me like an ever-flowing stream,
Your love is to me like an ever-flowing stream
reaching out, Lord.
Lord, we need Your love,
yes, we need Your love,
we need Your love to make it through;
Lord, we need Your love,
yes, we need Your love,
we need Your love to make it through.');
