INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0797', 'Phil Burt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0797', 'verse', 1, 0, '[\"Your love is to me like an ever-flowing stream,\",\"Your love is to me like an ever-flowing stream,\",\"Your love is to me like an ever-flowing stream\",\"reaching out, Lord.\",\"Lord, we need Your love,\",\"yes, we need Your love,\",\"we need Your love to make it through;\",\"Lord, we need Your love,\",\"yes, we need Your love,\",\"we need Your love to make it through.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0798', 798, 'Yours, Lord, is the greatness', 'MP', 'en', '©  1984 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Yours, Lord, is the greatness,
the power, the glory;
Yours, Lord, is the greatness,
the victory, the majesty.
For everything in heaven and earth is Yours,
You are the King, supreme over all.
Yours, Lord...
All riches and honour come from You;
You are our God, You make us strong.
Yours, Lord...
And now, our God, we give You thanks,
we praise Your glorious name.
Yours, Lord...');
