INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0798', 'verse', 1, 1, '[\"For everything in heaven and earth is Yours,\",\"You are the King, supreme over all.\",\"Yours, Lord...\"]');
