INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0799', 799, 'Knowing You', 'MP', 'en', '1993 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 0, 'All I once held dear,
built my life upon,
all this world reveres,
and wars to own,
all I once thought gain
I have counted loss;
spent and worthless now,
compared to this:
Knowing You, Jesus,
knowing You,
there is no greater thing.
You’re my all,
You’re the best,
You’re my joy, my righteousness,
and I love You, Lord.
Now my heart’s desire
is to know You more,
to be found in You
and known as Yours,
to possess by faith
what I could not earn,
all-surpassing gift
of righteousness.
Knowing You...
Oh, to know the power
of Your risen life,
and to know You in
Your sufferings,
to become like You
in Your death, my Lord,
so with You to live
and never die.
Knowing You...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0799', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0799', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0799', 'verse', 1, 0, '[\"All I once held dear,\",\"built my life upon,\",\"all this world reveres,\",\"and wars to own,\",\"all I once thought gain\",\"I have counted loss;\",\"spent and worthless now,\",\"compared to this:\",\"Knowing You, Jesus,\",\"knowing You,\",\"there is no greater thing.\",\"You’re my all,\",\"You’re the best,\",\"You’re my joy, my righteousness,\",\"and I love You, Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0799', 'verse', 2, 1, '[\"Now my heart’s desire\",\"is to know You more,\",\"to be found in You\",\"and known as Yours,\",\"to possess by faith\",\"what I could not earn,\",\"all-surpassing gift\",\"of righteousness.\",\"Knowing You...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0799', 'verse', 3, 2, '[\"Oh, to know the power\",\"of Your risen life,\",\"and to know You in\",\"Your sufferings,\",\"to become like You\",\"in Your death, my Lord,\",\"so with You to live\",\"and never die.\",\"Knowing You...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0800', 800, 'All-consuming, all-embracing', 'MP', 'en', 'Copyright 1993 Sovereign Lifestyle Music Ltd.  Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'All-consuming, all-embracing,
fervent God of love, enthral me.
All-consuming, all-embracing,
fervent God of love, enthral me,
’til all that I am and I desire
is wholly, only owned, controlled by You.');
