INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0805', 805, 'At the foot of the cross', 'MP', 'en', '1993 Vertical Worship Songs/Sovereign Music UK, PO Box 356, Leighton Buzzard LU7 3WP, UK. sovereignmusic@aol.com', '', 0, 0, 0, 1, 1, 'At the foot of the cross –
I can hardly take it in
that the King of all creation
was dying for my sin.
Oh, the pain and agony
and the thorns that pierced Your head,
and the hardness of my sinful heart
that left You there for dead!
And oh, what mercy I have found
at the cross of Calvary!
I will never know Your loneliness,
all on account of me.
And I will bow my knee before Your throne,
for Your love has set me free;
and I will give my life to You, dear Lord,
and praise Your majesty,
and praise Your majesty,
and praise Your majesty.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0805', 'Kathryn Scott');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0805', 'Kathryn Scott');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0805', 'verse', 1, 0, '[\"At the foot of the cross –\",\"I can hardly take it in\",\"that the King of all creation\",\"was dying for my sin.\",\"Oh, the pain and agony\",\"and the thorns that pierced Your head,\",\"and the hardness of my sinful heart\",\"that left You there for dead!\",\"And oh, what mercy I have found\",\"at the cross of Calvary!\",\"I will never know Your loneliness,\",\"all on account of me.\",\"And I will bow my knee before Your throne,\",\"for Your love has set me free;\",\"and I will give my life to You, dear Lord,\",\"and praise Your majesty,\",\"and praise Your majesty,\",\"and praise Your majesty.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0806', 806, 'God of the poor', 'MP', 'en', '1993 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Beauty for brokenness,
hope for despair,
Lord, in Your suffering world
this is our prayer.
Bread for the children,
justice, joy, peace,
sunrise to sunset,
Your kingdom increase!
Shelter for fragile lives,
cures for their ills,
work for the craftsmen,
trade for their skills;
land for the dispossessed,
rights for the weak,
voices to plead the cause
of those who can’t speak.
God of the poor,
friend of the weak,
give us compassion we pray:
melt our cold hearts,
let tears fall like rain;
come, change our love');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0806', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0806', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0806', 'verse', 1, 0, '[\"Beauty for brokenness,\",\"hope for despair,\",\"Lord, in Your suffering world\",\"this is our prayer.\",\"Bread for the children,\",\"justice, joy, peace,\",\"sunrise to sunset,\",\"Your kingdom increase!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0806', 'verse', 2, 1, '[\"Shelter for fragile lives,\",\"cures for their ills,\",\"work for the craftsmen,\",\"trade for their skills;\",\"land for the dispossessed,\",\"rights for the weak,\",\"voices to plead the cause\",\"of those who can’t speak.\",\"God of the poor,\",\"friend of the weak,\",\"give us compassion we pray:\",\"melt our cold hearts,\",\"let tears fall like rain;\",\"come, change our love\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0807', 807, 'Behold the Lord', 'MP', 'en', '©  1991 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Behold the Lord upon His throne:
His face is shining like the sun.
With eyes blazing fire,
and feet glowing bronze,
His voice like mighty water roars.
Holy, holy, Lord God almighty:
holy, holy! We stand in awe of You.
The First, the Last, the living One,
laid down His life for all the world.
Behold He now lives for evermore,
and holds the keys of death and hell!
Holy, holy, Lord God almighty:
holy, holy! We bow before Your throne.
So let our praises ever ring,
to Jesus Christ, our glorious King.
All Heaven and earth resound as we cry,
‘Worthy is the Son of God!’
Holy, holy, Lord God almighty:
holy, holy! We fall down at Your feet.');
