INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0807', 'verse', 1, 0, '[\"Behold the Lord upon His throne:\",\"His face is shining like the sun.\",\"With eyes blazing fire,\",\"and feet glowing bronze,\",\"His voice like mighty water roars.\",\"Holy, holy, Lord God almighty:\",\"holy, holy! We stand in awe of You.\"]');
