INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0808', 808, 'Blessèd be the name of the Lord', 'MP', 'en', '1987 Mercy/Vineyard Publishing/ Adm.by Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Blessèd be the name of the Lord,
blessèd be the name of the Lord.
Blessèd be the name of the Lord,
blessèd be the name of the Lord.
For He is our rock, for He is our rock, He is the Lord.
