INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0810', 810, 'By Your side', 'MP', 'en', '©  1989 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'By Your side I would stay,
in Your arms I would lay.
Jesus, lover of my soul,
nothing from You I withhold.
Lord, I love You
and adore You.
What more can I say?
You cause my love
to grow stronger
with every passing day.
Lord, I love You...');
