INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0811', 'verse', 1, 0, '[\"Called to a battle,\",\"heavenly war.\",\"Though we may struggle,\",\"victory is sure.\",\"Death will not triumph,\",\"though we may die.\",\"Jesus has promised\",\"our eternal life.\",\"By the blood of the Lamb\",\"we shall overcome,\",\"see the accuser thrown down.\",\"By the word of the Lord\",\"we shall overcome.\",\"Raise a victory cry\",\"like thunder in the skies,\",\"thunder in the skies.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0811', 'verse', 2, 1, '[\"Standing together,\",\"moving as one,\",\"we are God’s army\",\"called to overcome.\",\"We are commissioned:\",\"Jesus says ‘Go!’\",\"In every nation\",\"let His love be known.\",\"By the blood of the Lamb...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0812', 812, 'Christ is risen', 'MP', 'en', '1989 Thankyou Music, administered by worshiptogether.com songs excl. UK and Europe, administered by kingswaysongs.com. tym@kingsway.co.uk. Used by permission.', '', 0, 0, 0, 1, 0, 'Christ is risen –
alleluia, alleluia!
Christ is risen –
risen indeed, alleluia!
Love’s work is done,
the battle is won.
Where now, O death, is your sting?
He rose again
to rule and to reign,
Jesus our conquering King.
Christ is risen...
Lord over sin,
Lord over death,
at His feet Satan must fall!
Every knee bow!
All will confess
Jesus is Lord over all!
Christ is risen...
Tell it abroad,
‘Jesus is Lord!’
Shout it and let your praise ring!
Gladly we raise
our songs of praise –
worship is our offering.
Christ is risen...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0812', 'Chris Rolinson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0812', 'Chris Rolinson');
