INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0814', 814, 'City of God, how broad and far', 'MP', 'en', 'HarperCollins Religious/adm Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'City of God, how broad and far
outspread thy walls sublime!
The true thy chartered freemen are
of every age and clime.
One holy Church, one army strong,
one steadfast, high intent;
one working band, one harvest-song,
one King omnipotent.
How purely hath thy speech come down');
