INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0815', 815, 'Closer to You', 'MP', 'en', '©  1991 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Closer to You, Lord, and closer still,
’til I am wholly in Your will,
Closer to hear Your beating heart,
and understand what You impart.
O Breath of life, come purify
this heart of mine, and satisfy;
my deep desire is to worship You –
Lord of my life, come closer still.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0815', 'Trish Morgan');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0815', 'Trish Morgan');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0815', 'verse', 1, 0, '[\"Closer to You, Lord, and closer still,\",\"’til I am wholly in Your will,\",\"Closer to hear Your beating heart,\",\"and understand what You impart.\",\"O Breath of life, come purify\",\"this heart of mine, and satisfy;\",\"my deep desire is to worship You –\",\"Lord of my life, come closer still.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0816', 816, 'King of the nations', 'MP', 'en', '1992 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 0, 'Come, let us worship Jesus,
King of nations, Lord of all,
magnificent and glorious,
just and merciful.
Lavish our heart’s affection,
deepest love and highest praise,
voice, race and language blending,
all the world amazed.
Jesus, King of the nations,
Jesus, Lord of all.
Jesus, King of the nations,
Lord of all!
Bring tributes from the nations,
come in joyful cavalcades.
One thunderous acclamation,
one banner raised.
Come, Lord and fill Your temple,
glorify Your dwelling-place,
’til nations see Your splendour,
and seek Your face.
Jesus, King of the nations...
Fear God and give Him glory,
for His hour of judgement comes.
Creator, Lord almighty,
worship Him alone.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0816', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0816', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0816', 'verse', 1, 0, '[\"Come, let us worship Jesus,\",\"King of nations, Lord of all,\",\"magnificent and glorious,\",\"just and merciful.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0816', 'verse', 2, 1, '[\"Lavish our heart’s affection,\",\"deepest love and highest praise,\",\"voice, race and language blending,\",\"all the world amazed.\",\"Jesus, King of the nations,\",\"Jesus, Lord of all.\",\"Jesus, King of the nations,\",\"Lord of all!\"]');
