INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0816', 'verse', 4, 3, '[\"Come, Lord and fill Your temple,\",\"glorify Your dwelling-place,\",\"’til nations see Your splendour,\",\"and seek Your face.\",\"Jesus, King of the nations...\"]');
