INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0817', 817, 'Confidence, we have confidence', 'MP', 'en', 'Copyright 1994 Sovereign Lifestyle Music Ltd.  Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'Confidence, we have confidence
to come, to ask for mercy.
Confidence, we have confidence
to come, to ask for mercy.
Merciful God, we cry, ‘Don’t pass us by.’
Merciful God, we pray, ‘Don’t turn away’;
in Your love remember mercy,
in Your love remember mercy.');
