INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0818', 818, 'Come, Holy Spirit', 'MP', 'en', '1992, 1995 WGRG The Iona Community, 4th Floor, Savoy House, 140 Sauchiehall Street, Glasgow G2 3DH', '', 0, 0, 0, 1, 1, 'ALL
Come, Holy Spirit,
descend on us,
descend on us;
we gather here in Jesus’ name.
SOLO
(Come, Holy Spirit...)
(Come, Breath of Heaven...)
(Come, Word of Mercy...)');
