INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0836', 'verse', 4, 4, '[\"Above His creation the Father presides:\",\"the pulse of the planets, the rhythm of tides,\",\"the moon makes the seasons, the day follows night,\",\"yet He knows every beat of my heart.\",\"God is great...\"]');
