INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0837', 837, 'His banner over me', 'MP', 'en', '1991 Mercy/Vineyard Publishing (Admin.by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'MEN    He brought me to His banqueting table,
WOMEN    He brought me to His banqueting table,
MEN    He brought me to His banqueting table,
WOMEN    He brought me to His banqueting table,
ALL    and His banner over me is love.
MEN    I am my beloved’s and He is mine,
WOMEN    I am my beloved’s and He is mine,
MEN    I am my beloved’s and He is mine,
WOMEN    I am my beloved’s and He is mine,
ALL    and His banner over me is love,
yes, His banner over me is love.
ALL    And we can feel the love of God in this place,
we believe Your goodness, we receive Your grace.
We delight ourselves at Your table, O God,
You do all things well, just look at our lives.
MEN    He brought me to His banqueting table...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0837', 'Kevin Prosch');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0837', 'Kevin Prosch');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0837', 'verse', 1, 0, '[\"MEN    He brought me to His banqueting table,\",\"WOMEN    He brought me to His banqueting table,\",\"MEN    He brought me to His banqueting table,\",\"WOMEN    He brought me to His banqueting table,\",\"ALL    and His banner over me is love.\",\"MEN    I am my beloved’s and He is mine,\",\"WOMEN    I am my beloved’s and He is mine,\",\"MEN    I am my beloved’s and He is mine,\",\"WOMEN    I am my beloved’s and He is mine,\",\"ALL    and His banner over me is love,\",\"yes, His banner over me is love.\",\"ALL    And we can feel the love of God in this place,\",\"we believe Your goodness, we receive Your grace.\",\"We delight ourselves at Your table, O God,\",\"You do all things well, just look at our lives.\",\"MEN    He brought me to His banqueting table...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0838', 838, 'He has been given', 'MP', 'en', '©  1992 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'He has been given
a name above all names
in earth and Heaven,
let all creation claim
that Jesus Christ is King and Lord of all.
He is the victor
over Satan’s reign,
His blood has triumphed
over sin and shame –
Jesus Christ is King and Lord of all.
He is the likeness of Jehovah,
through whom the world was made.
By His word the universe is sustained,
every power is subject to His name.
The name of Jesus
in victory will resound,
in every nation
let the good news sound:
Jesus Christ is King and Lord of all.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0838', 'David Fellingham');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0838', 'David Fellingham');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0838', 'verse', 1, 0, '[\"He has been given\",\"a name above all names\",\"in earth and Heaven,\",\"let all creation claim\",\"that Jesus Christ is King and Lord of all.\",\"He is the victor\",\"over Satan’s reign,\",\"His blood has triumphed\",\"over sin and shame –\",\"Jesus Christ is King and Lord of all.\",\"He is the likeness of Jehovah,\",\"through whom the world was made.\",\"By His word the universe is sustained,\",\"every power is subject to His name.\",\"The name of Jesus\",\"in victory will resound,\",\"in every nation\",\"let the good news sound:\",\"Jesus Christ is King and Lord of all.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0839', 839, 'He has risen', 'MP', 'en', '©  1993 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'He has risen, He has risen,
He has risen, Jesus is alive!
When the life flowed from His body,
seemed like Jesus’ mission failed;
but His sacrifice accomplished
victory over sin and hell.
He has risen...
In the grave God did not leave Him
for His body to decay;
raised to life – the great awakening –
Satan’s power He overcame.
He has risen...
If there were no resurrection
we ourselves could not be raised,
but the Son of God is living,
so our hope is not in vain.
He has risen...
When the Lord rides out of Heaven,
mighty angels at His side,
they will sound the final trumpet,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0839', 'Gerald Coates');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0839', 'Noel Richards');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0839', 'Tricia Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0839', 'Gerald Coates');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0839', 'Noel Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0839', 'Tricia Richards');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0839', 'chorus', 0, 0, '[\"He has risen, He has risen,\",\"He has risen, Jesus is alive!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0839', 'verse', 1, 1, '[\"When the life flowed from His body,\",\"seemed like Jesus’ mission failed;\",\"but His sacrifice accomplished\",\"victory over sin and hell.\",\"He has risen...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0839', 'verse', 2, 2, '[\"In the grave God did not leave Him\",\"for His body to decay;\",\"raised to life – the great awakening –\",\"Satan’s power He overcame.\",\"He has risen...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0839', 'verse', 3, 3, '[\"If there were no resurrection\",\"we ourselves could not be raised,\",\"but the Son of God is living,\",\"so our hope is not in vain.\",\"He has risen...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0839', 'verse', 4, 4, '[\"When the Lord rides out of Heaven,\",\"mighty angels at His side,\",\"they will sound the final trumpet,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0840', 840, 'Heaven’s throne ascending', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Heaven’s throne ascending,
death’s dominion ending,
Christ the strong to save!
Now in glory seated,
work on earth completed,
risen from the grave!
Join to praise through all our days
Christ the Lord of love who sought us,
and in dying bought us.
Powers of darkness broken,
earth from sleep awoken,
and to life reborn!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0840', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0840', 'Johann Sebastian Bach');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0840', 'verse', 1, 0, '[\"Heaven’s throne ascending,\",\"death’s dominion ending,\",\"Christ the strong to save!\",\"Now in glory seated,\",\"work on earth completed,\",\"risen from the grave!\",\"Join to praise through all our days\",\"Christ the Lord of love who sought us,\",\"and in dying bought us.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0840', 'verse', 2, 1, '[\"Powers of darkness broken,\",\"earth from sleep awoken,\",\"and to life reborn!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0841', 841, 'Here in Your presence, Lord', 'MP', 'en', '1995 Greg Leavers', '', 0, 0, 0, 1, 1, 'Here in Your presence, Lord,
Your love is so strong, so sure.
Safe in Your presence, Lord,
I rest in You so secure.
I worship, I worship,
Jesus, I worship You.
Here in Your presence, Lord,
Your power and love break through.
Safe in Your presence, Lord,
I’m fixing my eyes on You.
I worship...
Here in Your presence, Lord,
I kneel before Your throne.
Safe in Your presence, Lord,
You tell me that I’m Your own.
I worship...
I worship...
I worship...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0841', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0841', 'Greg Leavers');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0841', 'verse', 1, 0, '[\"Here in Your presence, Lord,\",\"Your love is so strong, so sure.\",\"Safe in Your presence, Lord,\",\"I rest in You so secure.\",\"I worship, I worship,\",\"Jesus, I worship You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0841', 'verse', 2, 1, '[\"Here in Your presence, Lord,\",\"Your power and love break through.\",\"Safe in Your presence, Lord,\",\"I’m fixing my eyes on You.\",\"I worship...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0841', 'verse', 3, 2, '[\"Here in Your presence, Lord,\",\"I kneel before Your throne.\",\"Safe in Your presence, Lord,\",\"You tell me that I’m Your own.\",\"I worship...\",\"I worship...\",\"I worship...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0842', 842, 'Here is bread, here is wine', 'MP', 'en', '1991 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Here is bread, here is wine,
Christ is with us – He is with us;
break the bread, drink the wine –
Christ is with us here.
Here is grace, here is peace,
Christ is with us – He is with us;
know His grace, find His peace –
feast on Jesus here.
In this bread there is healing,
in this cup there’s life for ever;
in this moment, by the Spirit
Christ is with us here.
Here we are, joined in one,
Christ is with us – He is with us;
We’ll proclaim, ’til He comes –
Jesus crucified.
In this bread...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0842', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0842', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0842', 'verse', 1, 0, '[\"Here is bread, here is wine,\",\"Christ is with us – He is with us;\",\"break the bread, drink the wine –\",\"Christ is with us here.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0842', 'verse', 2, 1, '[\"Here is grace, here is peace,\",\"Christ is with us – He is with us;\",\"know His grace, find His peace –\",\"feast on Jesus here.\",\"In this bread there is healing,\",\"in this cup there’s life for ever;\",\"in this moment, by the Spirit\",\"Christ is with us here.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0842', 'verse', 3, 2, '[\"Here we are, joined in one,\",\"Christ is with us – He is with us;\",\"We’ll proclaim, ’til He comes –\",\"Jesus crucified.\",\"In this bread...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0843', 843, 'Show Your power', 'MP', 'en', '1991 Mercy/Vineyard Publishing (Adm. by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'He is the Lord and He reigns on high;
He is the Lord,
spoke into the darkness, created the light;
He is the Lord.
Who is like unto Him, never ending in days?
He is the Lord,
and He comes in power when we call on His name;
He is the Lord.
Show Your power, O Lord our God,
show Your power, O Lord our God,
our God.
Your gospel, O Lord, is the hope for our nation;
You are the Lord.
It’s the power of God for our salvation;
You are the Lord.
We ask not for riches but look to the cross;
You are the Lord,
and for our inheritance give us the lost;
You are the Lord.
Send Your power, O Lord our God,
send Your power, O Lord our God.
our God.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0843', 'Kevin Prosch');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0843', 'Kevin Prosch');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0843', 'verse', 1, 0, '[\"He is the Lord and He reigns on high;\",\"He is the Lord,\",\"spoke into the darkness, created the light;\",\"He is the Lord.\",\"Who is like unto Him, never ending in days?\",\"He is the Lord,\",\"and He comes in power when we call on His name;\",\"He is the Lord.\",\"Show Your power, O Lord our God,\",\"show Your power, O Lord our God,\",\"our God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0843', 'verse', 2, 1, '[\"Your gospel, O Lord, is the hope for our nation;\",\"You are the Lord.\",\"It’s the power of God for our salvation;\",\"You are the Lord.\",\"We ask not for riches but look to the cross;\",\"You are the Lord,\",\"and for our inheritance give us the lost;\",\"You are the Lord.\",\"Send Your power, O Lord our God,\",\"send Your power, O Lord our God.\",\"our God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0844', 844, 'Only The Blood', 'MP', 'en', 'Mercy/Vineyard Publishing/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Holiness is Your life in me,
making me clean through Your blood;
holiness is Your fire in me,
purging my heart like a flood.
I know You are perfect in holiness;
Your life in me, setting me free,
making me holy:
Only the blood of Jesus
covers all of my sin;
only the life of Jesus
renews me from within.
Your blood is enough –
Your mercy complete;
Your work of atonement paid for my debts,
making me holy:
only the blood of Jesus.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0844', 'Brian Doerksen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0844', 'Brian Doerksen');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0844', 'verse', 1, 0, '[\"Holiness is Your life in me,\",\"making me clean through Your blood;\",\"holiness is Your fire in me,\",\"purging my heart like a flood.\",\"I know You are perfect in holiness;\",\"Your life in me, setting me free,\",\"making me holy:\",\"Only the blood of Jesus\",\"covers all of my sin;\",\"only the life of Jesus\",\"renews me from within.\",\"Your blood is enough –\",\"Your mercy complete;\",\"Your work of atonement paid for my debts,\",\"making me holy:\",\"only the blood of Jesus.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0845', 845, 'Holy and majestic', 'MP', 'en', '1994 The Tehillah Trust', '', 0, 0, 0, 1, 1, 'Holy and majestic,
awesome God of power,
my heart will always praise You.
Your holy name I honour.
Bowing down before You,
I really do adore You –
what can I do but love You,
holy Lord, worthy Lord?
Because You are my Father,
You beckon me to enter,
to come into Your presence
and gaze upon Your glory.
Bowing down before You...
Your wondrous grace protects me;
Your perfect love surrounds me;
You clothe me in Your beauty;
I know Your depths of mercy.
Bowing down before You...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0845', 'Julian A Perkins');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0845', 'Julian A Perkins');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0845', 'verse', 1, 0, '[\"Holy and majestic,\",\"awesome God of power,\",\"my heart will always praise You.\",\"Your holy name I honour.\",\"Bowing down before You,\",\"I really do adore You –\",\"what can I do but love You,\",\"holy Lord, worthy Lord?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0845', 'verse', 2, 1, '[\"Because You are my Father,\",\"You beckon me to enter,\",\"to come into Your presence\",\"and gaze upon Your glory.\",\"Bowing down before You...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0845', 'verse', 3, 2, '[\"Your wondrous grace protects me;\",\"Your perfect love surrounds me;\",\"You clothe me in Your beauty;\",\"I know Your depths of mercy.\",\"Bowing down before You...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0846', 846, 'Lead me to the cross', 'MP', 'en', '1991 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'How can I be free from sin –
lead me to the cross of Jesus –');
