INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0846', 'verse', 1, 0, '[\"How can I be free from sin –\",\"lead me to the cross of Jesus –\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0847', 847, 'That the world may believe', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'How do we start to touch the broken hearts,
the barren lives, the lonely and bereaved?
Lord, in Your name we shall go forth:
Your healing power for ever is the same!
That the world may believe,
that the world may believe,
that the world may believe in You!
We shall proclaim the love of Jesus Christ –
a man of sorrows, yet a man divine;
His worthiness, His loveliness,
His faithfulness for ever we will sing!
That the world may believe...
And so we go into a lonely world
where fear reigns and sorrow fills the air;
yet, as we go Your Spirit comes –
Your cleansing power You give to us to share!
That the world may believe...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0847', 'Chris Rolinson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0847', 'Chris Rolinson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0847', 'verse', 1, 0, '[\"How do we start to touch the broken hearts,\",\"the barren lives, the lonely and bereaved?\",\"Lord, in Your name we shall go forth:\",\"Your healing power for ever is the same!\",\"That the world may believe,\",\"that the world may believe,\",\"that the world may believe in You!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0847', 'verse', 2, 1, '[\"We shall proclaim the love of Jesus Christ –\",\"a man of sorrows, yet a man divine;\",\"His worthiness, His loveliness,\",\"His faithfulness for ever we will sing!\",\"That the world may believe...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0847', 'verse', 3, 2, '[\"And so we go into a lonely world\",\"where fear reigns and sorrow fills the air;\",\"yet, as we go Your Spirit comes –\",\"Your cleansing power You give to us to share!\",\"That the world may believe...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0848', 848, 'How long, O Lord', 'MP', 'en', 'Barbara Woollett/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION            © 1991 Harper Collins Religious (Admin by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'How long, O Lord, willh’32u’You forget
an answer to my prayer?
No tokens of Your love I see,
Your face is turned away from me;
I wrestle with despair.
How long, O Lord, will You forsake
and leave me in this way?
When will You come to my relief?
My heart is overwhelmed with grief,
by evil night and day.
How long, O Lord – but You forgive,
with mercy from above.
I find that all Your ways are just,
I learn to praise You and to trust
in Your unfailing love.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0848', 'Barbara Woollett');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0848', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0848', 'verse', 1, 0, '[\"How long, O Lord, willh’32u’You forget\",\"an answer to my prayer?\",\"No tokens of Your love I see,\",\"Your face is turned away from me;\",\"I wrestle with despair.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0848', 'verse', 2, 1, '[\"How long, O Lord, will You forsake\",\"and leave me in this way?\",\"When will You come to my relief?\",\"My heart is overwhelmed with grief,\",\"by evil night and day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0848', 'verse', 3, 2, '[\"How long, O Lord – but You forgive,\",\"with mercy from above.\",\"I find that all Your ways are just,\",\"I learn to praise You and to trust\",\"in Your unfailing love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0849', 849, 'How wonderful', 'MP', 'en', '©  1994 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'How wonderful, how glorious
is the love of God,
bringing healing, forgiveness,
wonderful love.
Let celebration echo through this land;
we bring reconciliation,
we bring hope to every man.
How wonderful...
We proclaim the kingdom of our God is here.
Come and join the heavenly anthem
ringing loud and ringing clear.
How wonderful...
Listen to the music as His praises fill the air;
with joy and with gladness
tell the people everywhere.
How wonderful...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0849', 'Dave Bilbrough');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0849', 'Dave Bilbrough');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0849', 'chorus', 0, 0, '[\"How wonderful, how glorious\",\"is the love of God,\",\"bringing healing, forgiveness,\",\"wonderful love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0849', 'verse', 1, 1, '[\"Let celebration echo through this land;\",\"we bring reconciliation,\",\"we bring hope to every man.\",\"How wonderful...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0849', 'verse', 2, 2, '[\"We proclaim the kingdom of our God is here.\",\"Come and join the heavenly anthem\",\"ringing loud and ringing clear.\",\"How wonderful...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0849', 'verse', 3, 3, '[\"Listen to the music as His praises fill the air;\",\"with joy and with gladness\",\"tell the people everywhere.\",\"How wonderful...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0850', 850, 'We are more than conquerors', 'MP', 'en', 'Copyright 1983 Restoration Music Sovereignmusic@aol.com', '', 0, 0, 0, 1, 1, 'I am persuaded that neither death, nor life,
nor angels, principalities, nor powers,
nor things that are now, nor things that are to come,
can separate us from the love of Christ.
We are more than conquerors,
we are more than conquerors,
we are more than conquerors
through Christ, through Christ.
We know that all things work together for our good,
for good to those who love the Lord.
For God has called us to be just like His Son,
to live and walk according to His word.
We are more than conquerors...
If God is for us, who against us can prevail?
No-one can bring a charge against His chosen ones.
And there will be no separation from our Lord –
He has justified us through His precious blood.
We are more than conquerors...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0850', 'David Hadden');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0850', 'David Hadden');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0850', 'verse', 1, 0, '[\"I am persuaded that neither death, nor life,\",\"nor angels, principalities, nor powers,\",\"nor things that are now, nor things that are to come,\",\"can separate us from the love of Christ.\",\"We are more than conquerors,\",\"we are more than conquerors,\",\"we are more than conquerors\",\"through Christ, through Christ.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0850', 'verse', 2, 1, '[\"We know that all things work together for our good,\",\"for good to those who love the Lord.\",\"For God has called us to be just like His Son,\",\"to live and walk according to His word.\",\"We are more than conquerors...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0850', 'verse', 3, 2, '[\"If God is for us, who against us can prevail?\",\"No-one can bring a charge against His chosen ones.\",\"And there will be no separation from our Lord –\",\"He has justified us through His precious blood.\",\"We are more than conquerors...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0851', 851, 'At the cross', 'MP', 'en', 'Mercy/Vineyard Publishing/Adm Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'ALL
I know a place,
a wonderful place,
where accused and condemned
find mercy and grace;
where the wrongs we have done
and the wrongs done to us
were nailed there with Him,
there on the cross.
MEN    At the cross,
WOMEN    at the cross,
ALL    He died for our sin.
MEN    At the cross,
WOMEN    at the cross,
ALL    He gave us life again.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0851', 'Randy Butler');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0851', 'Terry Butler');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0851', 'Randy Butler');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0851', 'Terry Butler');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0851', 'verse', 1, 0, '[\"ALL\",\"I know a place,\",\"a wonderful place,\",\"where accused and condemned\",\"find mercy and grace;\",\"where the wrongs we have done\",\"and the wrongs done to us\",\"were nailed there with Him,\",\"there on the cross.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0851', 'chorus', 0, 1, '[\"MEN    At the cross,\",\"WOMEN    at the cross,\",\"ALL    He died for our sin.\",\"MEN    At the cross,\",\"WOMEN    at the cross,\",\"ALL    He gave us life again.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0852', 852, 'I know it was Your love for me', 'MP', 'en', 'Geoff Twigg/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'I know it was Your love for me
that led You, Lord, to Calvary;
I know it was the sin,
the state that I was in,
that caused You suffering and pain.
Lord Jesus, through Your broken heart
You’ve given me a brand new start;
O, help me to be true –
and in eternity with You
I’ll never break Your heart again.
And while I live upon this earth,
I want to show the world Your worth –
this love was meant to share,
to comfort and to care
for those who thought themselves alone.
You gave Your life at endless cost
to serve the world and save the lost;
and Your Spirit, ever-living,
is continually giving');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0852', 'Geoff Twigg');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0852', 'Geoff Twigg');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0852', 'Richard J Hubbard');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0852', 'verse', 1, 0, '[\"I know it was Your love for me\",\"that led You, Lord, to Calvary;\",\"I know it was the sin,\",\"the state that I was in,\",\"that caused You suffering and pain.\",\"Lord Jesus, through Your broken heart\",\"You’ve given me a brand new start;\",\"O, help me to be true –\",\"and in eternity with You\",\"I’ll never break Your heart again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0852', 'verse', 2, 1, '[\"And while I live upon this earth,\",\"I want to show the world Your worth –\",\"this love was meant to share,\",\"to comfort and to care\",\"for those who thought themselves alone.\",\"You gave Your life at endless cost\",\"to serve the world and save the lost;\",\"and Your Spirit, ever-living,\",\"is continually giving\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0853', 853, 'I love to hear the story', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'I love to hear the story
which angel voices tell,
how once the King of glory
came down on earth to dwell.
I am both weak and sinful,
but this I surely know,
the Lord came down to save me
because He loved me so.
I’m glad my blessèd Saviour
was once a child like me,
to show how pure and holy
His little ones might be;
and if I try to follow
His footsteps here below,
He never will forget me
because He loves me so.
To tell His love and mercy
my sweetest songs I’ll raise;
and though I cannot see Him,
I know He hears my praise;
for He Himself has promised
that even I may go
to sing among His angels,
because He loves me so.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0853', 'E H Miller');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0853', 'Basil Harwood');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0853', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0853', 'verse', 1, 0, '[\"I love to hear the story\",\"which angel voices tell,\",\"how once the King of glory\",\"came down on earth to dwell.\",\"I am both weak and sinful,\",\"but this I surely know,\",\"the Lord came down to save me\",\"because He loved me so.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0853', 'verse', 2, 1, '[\"I’m glad my blessèd Saviour\",\"was once a child like me,\",\"to show how pure and holy\",\"His little ones might be;\",\"and if I try to follow\",\"His footsteps here below,\",\"He never will forget me\",\"because He loves me so.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0853', 'verse', 3, 2, '[\"To tell His love and mercy\",\"my sweetest songs I’ll raise;\",\"and though I cannot see Him,\",\"I know He hears my praise;\",\"for He Himself has promised\",\"that even I may go\",\"to sing among His angels,\",\"because He loves me so.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0854', 854, 'I should be getting to know You', 'MP', 'en', 'Geoff Twigg/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'I should be getting to know You:
You’re my Father, I’m Your child –
I should be getting to know You,
the touch of Your hand,
the warmth of Your smile.
Help me to listen to Your word
and then to act on what I’ve heard;
help me to know that Your love for me is sure –
O draw me closer, my Father and my Lord.
I should be getting to know You:
for, despite the wrong I do,
Lord, You still want me to know You.
You know in my heart I mean to be true:
teach me to love Your holy ways
and walk within them all my days,
remaining loyal to You, my faithful Friend,
because I know that Your love will never end.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0854', 'Geoff Twigg');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0854', 'Geoff Twigg');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0854', 'Richard J Hubbard');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0854', 'verse', 1, 0, '[\"I should be getting to know You:\",\"You’re my Father, I’m Your child –\",\"I should be getting to know You,\",\"the touch of Your hand,\",\"the warmth of Your smile.\",\"Help me to listen to Your word\",\"and then to act on what I’ve heard;\",\"help me to know that Your love for me is sure –\",\"O draw me closer, my Father and my Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0854', 'verse', 2, 1, '[\"I should be getting to know You:\",\"for, despite the wrong I do,\",\"Lord, You still want me to know You.\",\"You know in my heart I mean to be true:\",\"teach me to love Your holy ways\",\"and walk within them all my days,\",\"remaining loyal to You, my faithful Friend,\",\"because I know that Your love will never end.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0855', 855, 'Arms of love', 'MP', 'en', '1991 Mercy/Vineyard Pub/Vineyard Songs Canada/ION Publishing (All adm. by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'I sing a simple song of love
to my Saviour, to my Jesus.
I’m grateful for the things You’ve done,
my loving Saviour, O precious Jesus.
My heart is glad that You’ve called me Your own,
there’s no place I’d rather be
than in Your arms of love,
in Your arms of love,
holding me still, holding me near
in Your arms of love.
I sing a simple song of love...
My heart is glad...
(last time)
holding me still, holding me near,
holding me still, holding me near
in Your arms of love.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0855', 'Craig Musseau');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0855', 'Craig Musseau');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0855', 'verse', 1, 0, '[\"I sing a simple song of love\",\"to my Saviour, to my Jesus.\",\"I’m grateful for the things You’ve done,\",\"my loving Saviour, O precious Jesus.\",\"My heart is glad that You’ve called me Your own,\",\"there’s no place I’d rather be\",\"than in Your arms of love,\",\"in Your arms of love,\",\"holding me still, holding me near\",\"in Your arms of love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0855', 'chorus', 0, 1, '[\"I sing a simple song of love...\",\"My heart is glad...\",\"(last time)\",\"holding me still, holding me near,\",\"holding me still, holding me near\",\"in Your arms of love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0856', 856, 'I sing this song', 'MP', 'en', '1994 Ed Pirie', '', 0, 0, 0, 1, 1, '');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0856', 'Ed Pirie');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0856', 'Ed Pirie');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0857', 857, 'Here I am, Lord', 'MP', 'en', '1993, Bernadette Farrell. Published by OCP. 5536 NE Hassalo, Portland, OR 97213 All rights reserved. Used with permission.', '', 0, 0, 0, 1, 1, 'I, the Lord of sea and sky,
I have heard My people cry.
All who dwell in dark and sin
My hand will save.
I who made the stars of night,
I will make their darkness bright.
Who will bear My light to them?
Whom shall I send?
Here I am, Lord.
Is it I, Lord?
I have heard You calling in the night.
I will go, Lord,
if You lead me.
I will hold Your people in my heart.
I, the Lord of snow and rain,
I have borne My people’s pain.
I have wept for love of them.
They turn away.
I will break their hearts of stone,
give them hearts for love alone.
I will speak My word to them.
Whom shall I send?
Here I am, Lord...
I, the Lord of wind and flame,
I will tend the poor and lame.
I will set a feast for them.
My hand will save.
Finest bread I will provide
till their hearts are satisfied.
I will give My life to them.
Whom shall I send?
Here I am, Lord...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0857', 'Daniel Schutte');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0857', 'Daniel Schutte');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0857', 'verse', 1, 0, '[\"I, the Lord of sea and sky,\",\"I have heard My people cry.\",\"All who dwell in dark and sin\",\"My hand will save.\",\"I who made the stars of night,\",\"I will make their darkness bright.\",\"Who will bear My light to them?\",\"Whom shall I send?\",\"Here I am, Lord.\",\"Is it I, Lord?\",\"I have heard You calling in the night.\",\"I will go, Lord,\",\"if You lead me.\",\"I will hold Your people in my heart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0857', 'verse', 2, 1, '[\"I, the Lord of snow and rain,\",\"I have borne My people’s pain.\",\"I have wept for love of them.\",\"They turn away.\",\"I will break their hearts of stone,\",\"give them hearts for love alone.\",\"I will speak My word to them.\",\"Whom shall I send?\",\"Here I am, Lord...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0857', 'verse', 3, 2, '[\"I, the Lord of wind and flame,\",\"I will tend the poor and lame.\",\"I will set a feast for them.\",\"My hand will save.\",\"Finest bread I will provide\",\"till their hearts are satisfied.\",\"I will give My life to them.\",\"Whom shall I send?\",\"Here I am, Lord...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0858', 858, 'I want to know You', 'MP', 'en', '1990 Mercy/Vineyard Publishing/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'I want to know You,
Lord, I must know You.
I want to be found in You,
I want to be clothed in Your truth.
So I fix my eyes on You,
Lord, I must see You.
I put my faith in You,
I spend my life on You.
I want to know You,
I want to love You,
I want to know You more,
Jesus, Jesus.
I want to know You...
I want to know You...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0858', 'Brian Doerksen');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0858', 'Cindy Rethmeier');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0858', 'Brian Doerksen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0858', 'Cindy Rethmeier');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0858', 'chorus', 0, 0, '[\"I want to know You,\",\"Lord, I must know You.\",\"I want to be found in You,\",\"I want to be clothed in Your truth.\",\"So I fix my eyes on You,\",\"Lord, I must see You.\",\"I put my faith in You,\",\"I spend my life on You.\",\"I want to know You,\",\"I want to love You,\",\"I want to know You more,\",\"Jesus, Jesus.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0858', 'chorus', 0, 1, '[\"I want to know You...\",\"I want to know You...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0859', 859, 'In my generation', 'MP', 'en', '© 1986 Sovereign Grace Praise/ adm worldwide by Capitol CMG Publishing excl UK admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'I want to serve the purpose of God in my generation.
I want to serve the purpose of God while I am alive.
I want to give my life for something that’ll last for ever:
Oh, I delight, I delight to do Your will.
What is on Your heart?
Show me what to do.
Let me know Your will,
and I will follow You.
What is on Your heart...
I want to build with silver and gold in my generation.
I want to build with silver and gold while I am alive.
I want to give my life for something that’ll last for ever:
Oh, I delight, I delight to do Your will.
What is on Your heart...
I want to see the kingdom of God in my generation.
I want to see the kingdom of God while I am alive.
I want to give my life for something that’ll last for ever:
Oh, I delight, I delight to do Your will.
What is on Your heart...
I want to see the Lord come again in my generation.
I want to see the Lord come again while I am alive.
I want to give my life for something that’ll last for ever.
Oh, I delight, I delight to do Your will.
What is on Your heart...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0859', 'Mark Altrogge');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0859', 'Mark Altrogge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0859', 'verse', 1, 0, '[\"I want to serve the purpose of God in my generation.\",\"I want to serve the purpose of God while I am alive.\",\"I want to give my life for something that’ll last for ever:\",\"Oh, I delight, I delight to do Your will.\",\"What is on Your heart?\",\"Show me what to do.\",\"Let me know Your will,\",\"and I will follow You.\",\"What is on Your heart...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0859', 'verse', 2, 1, '[\"I want to build with silver and gold in my generation.\",\"I want to build with silver and gold while I am alive.\",\"I want to give my life for something that’ll last for ever:\",\"Oh, I delight, I delight to do Your will.\",\"What is on Your heart...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0859', 'verse', 3, 2, '[\"I want to see the kingdom of God in my generation.\",\"I want to see the kingdom of God while I am alive.\",\"I want to give my life for something that’ll last for ever:\",\"Oh, I delight, I delight to do Your will.\",\"What is on Your heart...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0859', 'verse', 4, 3, '[\"I want to see the Lord come again in my generation.\",\"I want to see the Lord come again while I am alive.\",\"I want to give my life for something that’ll last for ever.\",\"Oh, I delight, I delight to do Your will.\",\"What is on Your heart...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0860', 860, 'Cry mercy', 'MP', 'en', '©  1994 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'I will cry mercy, I will cry mercy
for this land, O God.
I will cry justice, I will cry justice
for this land, O God,
for this land, O God.
Let Your tears flow from my eyes;
let Your passion melt my heart of stone.
Let Your beauty be seen in my life;
let Your heartbeat be my own.
So I’ll cry mercy for this nation,
let us see healing for the people,
and I’ll cry justice for this nation, O God.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0860', 'Steve Bassett');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0860', 'Sue Rinaldi');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0860', 'Steve Bassett');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0860', 'Sue Rinaldi');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0860', 'Stuart Townend');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0860', 'verse', 1, 0, '[\"I will cry mercy, I will cry mercy\",\"for this land, O God.\",\"I will cry justice, I will cry justice\",\"for this land, O God,\",\"for this land, O God.\",\"Let Your tears flow from my eyes;\",\"let Your passion melt my heart of stone.\",\"Let Your beauty be seen in my life;\",\"let Your heartbeat be my own.\",\"So I’ll cry mercy for this nation,\",\"let us see healing for the people,\",\"and I’ll cry justice for this nation, O God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0861', 861, 'If you are encouraged', 'MP', 'en', '1993 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'If you are encouraged in your union with Christ,
finding consolation in His love,
compassion, warmth and friendship in the Spirit’s flow of life;
this is how you make my joy complete:
By being of the same mind,
and loving with the same love,
united in the Spirit,
with the same goal in sight,
by being of the same mind,
and loving with the same love,
united in the Spirit,
to the glory of Christ.
Be sure you do nothing out of selfishness or pride,
never seeing past your own concerns,
but humbly keep the interests of each other in your hearts,
seeing them as better than yourselves:
By being of the same mind...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0861', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0861', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0861', 'verse', 1, 0, '[\"If you are encouraged in your union with Christ,\",\"finding consolation in His love,\",\"compassion, warmth and friendship in the Spirit’s flow of life;\",\"this is how you make my joy complete:\",\"By being of the same mind,\",\"and loving with the same love,\",\"united in the Spirit,\",\"with the same goal in sight,\",\"by being of the same mind,\",\"and loving with the same love,\",\"united in the Spirit,\",\"to the glory of Christ.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0861', 'verse', 2, 1, '[\"Be sure you do nothing out of selfishness or pride,\",\"never seeing past your own concerns,\",\"but humbly keep the interests of each other in your hearts,\",\"seeing them as better than yourselves:\",\"By being of the same mind...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0862', 862, 'I’ll go in the strength of the Lord', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'I’ll go in the strength of the Lord,
in paths He has marked for my feet;
I’ll follow the light of His word,
nor shrink from the dangers I meet.
His presence my steps shall attend,
His fulness my wants shall supply;
on Him, ’til my journey shall end,
my unwavering faith will rely.
I’ll go, (I’ll go,) I’ll go in the strength,
I’ll go in the strength of the Lord (I’ll go).
I’ll go, (I’ll go,) I’ll go in the strength,
I’ll go in the strength of the Lord.
I’ll go in the strength of the Lord,
to work He appoints me to do;
in joy which His smile doth afford
my soul shall its vigour renew.
His wisdom shall guard me from harm,
His power my sufficiency prove;
I’ll trust His omnipotent arm,
and prove His unchangeable love.
I’ll go...
I’ll go in the strength of the Lord,
to conflicts which faith will require;
His grace as my shield and reward,
my courage and zeal shall inspire.
Since He gives the word of command
to meet and encounter the foe,
with His sword of truth in my hand
to suffer and triumph I’ll go.
I’ll go...
I’ll go in the strength of the Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0862', 'Edward Turney');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0862', 'Ivor Bosanko');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0862', 'verse', 1, 0, '[\"I’ll go in the strength of the Lord,\",\"in paths He has marked for my feet;\",\"I’ll follow the light of His word,\",\"nor shrink from the dangers I meet.\",\"His presence my steps shall attend,\",\"His fulness my wants shall supply;\",\"on Him, ’til my journey shall end,\",\"my unwavering faith will rely.\",\"I’ll go, (I’ll go,) I’ll go in the strength,\",\"I’ll go in the strength of the Lord (I’ll go).\",\"I’ll go, (I’ll go,) I’ll go in the strength,\",\"I’ll go in the strength of the Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0862', 'verse', 2, 1, '[\"I’ll go in the strength of the Lord,\",\"to work He appoints me to do;\",\"in joy which His smile doth afford\",\"my soul shall its vigour renew.\",\"His wisdom shall guard me from harm,\",\"His power my sufficiency prove;\",\"I’ll trust His omnipotent arm,\",\"and prove His unchangeable love.\",\"I’ll go...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0862', 'verse', 3, 2, '[\"I’ll go in the strength of the Lord,\",\"to conflicts which faith will require;\",\"His grace as my shield and reward,\",\"my courage and zeal shall inspire.\",\"Since He gives the word of command\",\"to meet and encounter the foe,\",\"with His sword of truth in my hand\",\"to suffer and triumph I’ll go.\",\"I’ll go...\",\"I’ll go in the strength of the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0863', 863, 'I’m living my life for Jesus', 'MP', 'en', '1987 Salvationist Publishing & Supplies (Admin. by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'I’m living my life for Jesus –
His love and His grace I’ve seen;
and now that I live for Jesus,
life has a new-found theme.
My life has a new-found intention,
I follow a purposeful aim,
and life has a new-found dimension –
I witness that I’m born again.
I’m living my life for Jesus –
His love and His grace I’ve seen;
and now that I live for Jesus,
life has a new-found theme.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0863', 'Keith Banks');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0863', 'Keith Banks');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0863', 'verse', 1, 0, '[\"I’m living my life for Jesus –\",\"His love and His grace I’ve seen;\",\"and now that I live for Jesus,\",\"life has a new-found theme.\",\"My life has a new-found intention,\",\"I follow a purposeful aim,\",\"and life has a new-found dimension –\",\"I witness that I’m born again.\",\"I’m living my life for Jesus –\",\"His love and His grace I’ve seen;\",\"and now that I live for Jesus,\",\"life has a new-found theme.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0864', 864, 'I worship You, almighty God', 'MP', 'en', '© 1983 Integrity\'s Hosanna! Music / adm worldwide by Capitol CMG Publishing excl UK admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'I worship You, almighty God,
there is none like You.
I worship You, O Prince of Peace,
that is what I love to do.
I give You praise,
for You are my righteousness.
I worship You, almighty God,
there is none like You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0864', 'Sondra Corbett');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0864', 'Sondra Corbett');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0864', 'verse', 1, 0, '[\"I worship You, almighty God,\",\"there is none like You.\",\"I worship You, O Prince of Peace,\",\"that is what I love to do.\",\"I give You praise,\",\"for You are my righteousness.\",\"I worship You, almighty God,\",\"there is none like You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0865', 865, 'In the Lord I’ll be ever thankful', 'MP', 'en', 'Ateliers et Presses de Taizé, 71250 Taizé, France.', '', 0, 0, 0, 1, 1, 'In the Lord I’ll be ever thankful,
in the Lord I will rejoice.
Trust in God,
do not be afraid.
Our hearts untroubled,
the Lord is near,
our hearts untroubled,
the Lord is near.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0865', 'Taizé Community');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0865', 'Jacques Berthier');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0865', 'verse', 1, 0, '[\"In the Lord I’ll be ever thankful,\",\"in the Lord I will rejoice.\",\"Trust in God,\",\"do not be afraid.\",\"Our hearts untroubled,\",\"the Lord is near,\",\"our hearts untroubled,\",\"the Lord is near.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0866', 866, 'Where it matters, there you’ll find us', 'MP', 'en', 'Mrs B Perry/The Jubilate Group            ? 1993 Chris Rolinson, administered by The Jubilate Group, 4 Thorne Park Road, Torquay TQ2 6RX. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'In the streets of every city,
bringing hope and healing strife,
living out the Saviour’s pity,
caring for each precious life.
Through the world, in every nation,
serving Christ, with lives made whole;
in His name we speak salvation
grace for every seeking soul;
Where it matters, there you’ll find us,
where it matters, there you’ll find us
serving Jesus;
where it matters, there you’ll find us
in the service of our Lord.
In our daily time of praying,
thanking God for sins forgiven,
hearing what His voice is saying,
tasting now the joys of Heaven.
At His table, there you’ll find us
pouring wine and sharing bread;
‘Christ has died’ these gifts remind us,
‘Christ is risen from the dead’.
Where it matters...
God of city, and of nation,
Lord ascended, coming King;
with resounding exultation
of Your faithfulness we sing.
Where it matters...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0866', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0866', 'Chris Rolinson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0866', 'verse', 1, 0, '[\"In the streets of every city,\",\"bringing hope and healing strife,\",\"living out the Saviour’s pity,\",\"caring for each precious life.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0866', 'verse', 2, 1, '[\"Through the world, in every nation,\",\"serving Christ, with lives made whole;\",\"in His name we speak salvation\",\"grace for every seeking soul;\",\"Where it matters, there you’ll find us,\",\"where it matters, there you’ll find us\",\"serving Jesus;\",\"where it matters, there you’ll find us\",\"in the service of our Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0866', 'verse', 3, 2, '[\"In our daily time of praying,\",\"thanking God for sins forgiven,\",\"hearing what His voice is saying,\",\"tasting now the joys of Heaven.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0866', 'verse', 4, 3, '[\"At His table, there you’ll find us\",\"pouring wine and sharing bread;\",\"‘Christ has died’ these gifts remind us,\",\"‘Christ is risen from the dead’.\",\"Where it matters...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0866', 'verse', 5, 4, '[\"God of city, and of nation,\",\"Lord ascended, coming King;\",\"with resounding exultation\",\"of Your faithfulness we sing.\",\"Where it matters...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0867', 867, 'Let the living waters flow', 'MP', 'en', '1994 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Is anyone thirsty – anyone?
Is anyone thirsty?
Is anyone thirsty – anyone?
Is anyone thirsty?
Jesus said:
‘Let them come to me and drink,
let them come to me.’
Oh, let the living waters flow,
oh, let the living waters flow,
let the river of Your Spirit flow through me;
oh, let the living waters flow,
oh, let the living waters flow,
let the river of Your Spirit flow through me.
Flow through me, flow through me,
flow through me, flow through me.
Let the living waters flow,
let the living waters flow,
let the living waters flow,
let the living waters flow.
Oh, let the living waters flow...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0867', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0867', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0867', 'chorus', 0, 0, '[\"Is anyone thirsty – anyone?\",\"Is anyone thirsty?\",\"Is anyone thirsty – anyone?\",\"Is anyone thirsty?\",\"Jesus said:\",\"‘Let them come to me and drink,\",\"let them come to me.’\",\"Oh, let the living waters flow,\",\"oh, let the living waters flow,\",\"let the river of Your Spirit flow through me;\",\"oh, let the living waters flow,\",\"oh, let the living waters flow,\",\"let the river of Your Spirit flow through me.\",\"Flow through me, flow through me,\",\"flow through me, flow through me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0867', 'chorus', 0, 1, '[\"Let the living waters flow,\",\"let the living waters flow,\",\"let the living waters flow,\",\"let the living waters flow.\",\"Oh, let the living waters flow...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0868', 868, 'Cry of my heart', 'MP', 'en', '1991 Mercy/Vineyard Pub/ Adm.by Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'It is the cry of my heart to follow You,
it is the cry of my heart to be close to You;
it is the cry of my heart to follow
all of the days of my life.
It is the cry of my heart...
Teach me Your holy ways, O Lord,
so I can walk in Your truth;
teach me Your holy ways, O Lord,
and make me wholly devoted to You.
Oh, oh, oh.
It is the cry of my heart...
Open my eyes so I can see
the wonderful things that You do;
open my heart up more and more
and make it wholly devoted to You.
Oh, oh, oh.
It is the cry of my heart...
all of the days of my life,
all of the days of my life,
all of the days of my life.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0868', 'Terry Butler');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0868', 'Terry Butler');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0868', 'chorus', 0, 0, '[\"It is the cry of my heart to follow You,\",\"it is the cry of my heart to be close to You;\",\"it is the cry of my heart to follow\",\"all of the days of my life.\",\"It is the cry of my heart...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0868', 'verse', 1, 1, '[\"Teach me Your holy ways, O Lord,\",\"so I can walk in Your truth;\",\"teach me Your holy ways, O Lord,\",\"and make me wholly devoted to You.\",\"Oh, oh, oh.\",\"It is the cry of my heart...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0868', 'verse', 2, 2, '[\"Open my eyes so I can see\",\"the wonderful things that You do;\",\"open my heart up more and more\",\"and make it wholly devoted to You.\",\"Oh, oh, oh.\",\"It is the cry of my heart...\",\"all of the days of my life,\",\"all of the days of my life,\",\"all of the days of my life.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0869', 869, 'In Your arms of love', 'MP', 'en', 'Chris Rolinson/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'In Your arms of love so tender,
we would our whole lives surrender:
captured by Your precious love,
we worship You.
Standing on this ground so holy,
gazing on the King so mighty –
crucified yet robed in glory:
Jesus Christ.
Holy Lord, we bow before You;
humbly we would seek to know You:
Lord, reveal Yourself so we might
worship You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0869', 'Chris Rolinson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0869', 'Chris Rolinson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0869', 'verse', 1, 0, '[\"In Your arms of love so tender,\",\"we would our whole lives surrender:\",\"captured by Your precious love,\",\"we worship You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0869', 'verse', 2, 1, '[\"Standing on this ground so holy,\",\"gazing on the King so mighty –\",\"crucified yet robed in glory:\",\"Jesus Christ.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0869', 'verse', 3, 2, '[\"Holy Lord, we bow before You;\",\"humbly we would seek to know You:\",\"Lord, reveal Yourself so we might\",\"worship You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0870', 870, 'Jesus is our God', 'MP', 'en', '©  1991 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Jesus is the name we honour;
Jesus is the name we praise.
Majestic name above all other names,
the highest heaven and earth proclaim that Jesus is our God.
We will glorify,
we will lift Him high,
we will give Him honour and praise.
We will glorify...
Jesus is the name we worship;
Jesus is the name we trust.
He is the King above all other kings,
let all creation stand and sing that Jesus is our God.
We will glorify...
Jesus is the Father’s splendour;
Jesus is the Father’s joy.
He will return to reign in majesty,
and every eye at last will see that Jesus is our God.
We will glorify...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0870', 'Phil Lawson Johnston');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0870', 'Phil Lawson Johnston');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0870', 'verse', 1, 0, '[\"Jesus is the name we honour;\",\"Jesus is the name we praise.\",\"Majestic name above all other names,\",\"the highest heaven and earth proclaim that Jesus is our God.\",\"We will glorify,\",\"we will lift Him high,\",\"we will give Him honour and praise.\",\"We will glorify...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0870', 'verse', 2, 1, '[\"Jesus is the name we worship;\",\"Jesus is the name we trust.\",\"He is the King above all other kings,\",\"let all creation stand and sing that Jesus is our God.\",\"We will glorify...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0870', 'verse', 3, 2, '[\"Jesus is the Father’s splendour;\",\"Jesus is the Father’s joy.\",\"He will return to reign in majesty,\",\"and every eye at last will see that Jesus is our God.\",\"We will glorify...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0871', 871, 'Lord of all', 'MP', 'en', '1988 Integrity\'s Hosanna! Music, administered by Sovereign Music UK, PO Box 356, Leighton Buzzard LU7 3WP, UK. sovereignmusic@aol.com', '', 0, 0, 0, 1, 0, 'Jesus Christ is the Lord of all, Lord of all the earth,
Jesus Christ is the Lord of all, Lord of all the earth.
Jesus Christ is the Lord of all...
Only one God over the nations, only one Lord of all;
in no other name is there salvation, Jesus is Lord of all.
Jesus Christ is Lord of all,
Jesus Christ is Lord of all;
Jesus Christ is Lord of all,
Jesus Christ is Lord of all.
Jesus Christ is the Lord of all...
Only one God...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0871', 'Gerrit Gustafson');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0871', 'Steve Israel');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0871', 'Gerrit Gustafson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0871', 'Steve Israel');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0871', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0871', 'verse', 1, 0, '[\"Jesus Christ is the Lord of all, Lord of all the earth,\",\"Jesus Christ is the Lord of all, Lord of all the earth.\",\"Jesus Christ is the Lord of all...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0871', 'chorus', 0, 1, '[\"Only one God over the nations, only one Lord of all;\",\"in no other name is there salvation, Jesus is Lord of all.\",\"Jesus Christ is Lord of all,\",\"Jesus Christ is Lord of all;\",\"Jesus Christ is Lord of all,\",\"Jesus Christ is Lord of all.\",\"Jesus Christ is the Lord of all...\",\"Only one God...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0872', 872, 'Jesus, Jesus, holy and anointed One', 'MP', 'en', '1988 Mercy/Vineyard Publishing (Admin. by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Jesus, Jesus,
holy and anointed One, Jesus;
Jesus, Jesus,
risen and exalted One, Jesus:
Your name is like honey on my lips,
Your Spirit like water to my soul;
Your word is a lamp unto my feet –
Jesus, I love You, I love You.
Jesus, Jesus...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0872', 'John Barnett');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0872', 'John Barnett');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0872', 'verse', 1, 0, '[\"Jesus, Jesus,\",\"holy and anointed One, Jesus;\",\"Jesus, Jesus,\",\"risen and exalted One, Jesus:\",\"Your name is like honey on my lips,\",\"Your Spirit like water to my soul;\",\"Your word is a lamp unto my feet –\",\"Jesus, I love You, I love You.\",\"Jesus, Jesus...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0873', 873, 'Jesus, restore to us again', 'MP', 'en', '1992 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Jesus, restore to us again
the gospel of Your holy name,
that comes with power, not words alone,
owned, signed and sealed from Heaven’s throne.
Spirit and word in one agreed;
the promise to the power wed.
The word is near, here in our mouths
and in our hearts, the word of faith –
proclaim it on the Spirit’s breath:
‘Jesus!’
Your word, O Lord, eternal stands,
fixed and unchanging in the heavens.
The Word made flesh to earth came down
to heal our world with nail-pierced hands.
Among us here You lived and breathed,
You are the message we received.
The word is near...
Spirit of truth, lead us, we pray,
into all truth as we obey,
and as God’s will we gladly choose,
Your ancient power again will prove
Christ’s teaching truly comes from God –
He is indeed the living Word.
The word is near...
Upon the heights of this dark land
with Moses and Elijah stand:
reveal Your glory once again,
show us Your face, declare Your name –
prophets and laws in You complete
where promises and power meet.
The word is near...
Grant us in this decisive hour
to know the Scriptures and the power;
the knowledge in experience prove,
the power that moves and works by love.
May word and work join hands as one,
the word go forth, the Spirit come.
The word is near...
The word is near...
‘Jesus!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0873', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0873', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0873', 'verse', 1, 0, '[\"Jesus, restore to us again\",\"the gospel of Your holy name,\",\"that comes with power, not words alone,\",\"owned, signed and sealed from Heaven’s throne.\",\"Spirit and word in one agreed;\",\"the promise to the power wed.\",\"The word is near, here in our mouths\",\"and in our hearts, the word of faith –\",\"proclaim it on the Spirit’s breath:\",\"‘Jesus!’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0873', 'verse', 2, 1, '[\"Your word, O Lord, eternal stands,\",\"fixed and unchanging in the heavens.\",\"The Word made flesh to earth came down\",\"to heal our world with nail-pierced hands.\",\"Among us here You lived and breathed,\",\"You are the message we received.\",\"The word is near...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0873', 'verse', 3, 2, '[\"Spirit of truth, lead us, we pray,\",\"into all truth as we obey,\",\"and as God’s will we gladly choose,\",\"Your ancient power again will prove\",\"Christ’s teaching truly comes from God –\",\"He is indeed the living Word.\",\"The word is near...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0873', 'verse', 4, 3, '[\"Upon the heights of this dark land\",\"with Moses and Elijah stand:\",\"reveal Your glory once again,\",\"show us Your face, declare Your name –\",\"prophets and laws in You complete\",\"where promises and power meet.\",\"The word is near...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0873', 'verse', 5, 4, '[\"Grant us in this decisive hour\",\"to know the Scriptures and the power;\",\"the knowledge in experience prove,\",\"the power that moves and works by love.\",\"May word and work join hands as one,\",\"the word go forth, the Spirit come.\",\"The word is near...\",\"The word is near...\",\"‘Jesus!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0874', 874, 'Jesus, there’s no-one like You', 'MP', 'en', '1993 Sound Impression, 44 Adelaide Road, Chichester, West Sussex PO19 4NF, UK', '', 0, 0, 0, 1, 1, 'Jesus, there’s no-one like You.
Jesus, there’s no-one like You.
You are the Saviour, You are the King,
You are the answer to everything.
Jesus, there’s no-one like You.
All You have made
will praise Your name,
the glory of the Father is Yours.
Jesus, there’s no-one like You.
Jesus, there’s no-one like You.
You give us life, You give us peace,
Your precious blood has set us free.
Jesus, there’s no-one like You.
All You have made...
Jesus, there’s no-one like You.
Jesus, there’s no-one like You.
You bring healing and release,
so mighty are Your deeds.
Jesus, there’s no-one like You.
All You have made...
Jesus, (O Jesus,)
We praise Jesus (only Jesus).');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0874', 'Alun Leppitt');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0874', 'Alun Leppitt');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0874', 'verse', 1, 0, '[\"Jesus, there’s no-one like You.\",\"Jesus, there’s no-one like You.\",\"You are the Saviour, You are the King,\",\"You are the answer to everything.\",\"Jesus, there’s no-one like You.\",\"All You have made\",\"will praise Your name,\",\"the glory of the Father is Yours.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0874', 'verse', 2, 1, '[\"Jesus, there’s no-one like You.\",\"Jesus, there’s no-one like You.\",\"You give us life, You give us peace,\",\"Your precious blood has set us free.\",\"Jesus, there’s no-one like You.\",\"All You have made...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0874', 'verse', 3, 2, '[\"Jesus, there’s no-one like You.\",\"Jesus, there’s no-one like You.\",\"You bring healing and release,\",\"so mighty are Your deeds.\",\"Jesus, there’s no-one like You.\",\"All You have made...\",\"Jesus, (O Jesus,)\",\"We praise Jesus (only Jesus).\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0875', 875, 'Jesus, take Your rightful place', 'MP', 'en', '1990 Karen David/Ellel Ministries Ltd', '', 0, 0, 0, 1, 1, 'Jesus, take Your rightful place in my life.
I give You complete control.
As I lay my life afresh before You,
cleanse me and make me whole.
Jesus, take Your rightful place in my heart.
Be seated on the throne.
As I lift my voice in adoration,
I worship You alone.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0875', 'Karen David');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0875', 'Karen David');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0875', 'verse', 1, 0, '[\"Jesus, take Your rightful place in my life.\",\"I give You complete control.\",\"As I lay my life afresh before You,\",\"cleanse me and make me whole.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0875', 'verse', 2, 1, '[\"Jesus, take Your rightful place in my heart.\",\"Be seated on the throne.\",\"As I lift my voice in adoration,\",\"I worship You alone.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0876', 876, 'Let the song go round the earth', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Let the song go round the earth,
Jesus Christ is Lord!
Sound His praises, tell His worth,
be His name adored;
every clime and every tongue
join the grand, the glorious song!
Let the song go round the earth!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0876', 'S G Stock');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0876', 'S G Stock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0876', 'verse', 1, 0, '[\"Let the song go round the earth,\",\"Jesus Christ is Lord!\",\"Sound His praises, tell His worth,\",\"be His name adored;\",\"every clime and every tongue\",\"join the grand, the glorious song!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0876', 'verse', 2, 1, '[\"Let the song go round the earth!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0877', 877, 'Let us draw near to God', 'MP', 'en', '©  1992 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Let us draw near to God
in full assurance of faith,
knowing that as we draw near to Him,
He will draw near to us.
In the Holy Place
we stand in confidence,
knowing our lives are cleansed
in the blood of the Lamb,
we will worship and adore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0877', 'David Fellingham');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0877', 'David Fellingham');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0877', 'verse', 1, 0, '[\"Let us draw near to God\",\"in full assurance of faith,\",\"knowing that as we draw near to Him,\",\"He will draw near to us.\",\"In the Holy Place\",\"we stand in confidence,\",\"knowing our lives are cleansed\",\"in the blood of the Lamb,\",\"we will worship and adore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0878', 878, 'Lord God almighty', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Lord God almighty, Father of all mercies,
well-spring of goodness, fount of all things living,
we now Your children, blessed by loving kindness,
come with thanksgiving.
Hear us who praise You, first for our creation,
formed in Your likeness, breath and being gaining;
then for our keeping, life in all its fulness
daily sustaining.
But above all things, for the gift of Jesus,
love past comparing, source of our salvation;
humbly we bring You, for a world’s redeeming,
our adoration.
So in thanksgiving for the hope of glory,
love, grace and mercy all our days attending,
more than our lips, Lord, let our living praise You,
ages unending.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0878', 'Timothy Dudley-Smith');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0878', 'verse', 1, 0, '[\"Lord God almighty, Father of all mercies,\",\"well-spring of goodness, fount of all things living,\",\"we now Your children, blessed by loving kindness,\",\"come with thanksgiving.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0878', 'verse', 2, 1, '[\"Hear us who praise You, first for our creation,\",\"formed in Your likeness, breath and being gaining;\",\"then for our keeping, life in all its fulness\",\"daily sustaining.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0878', 'verse', 3, 2, '[\"But above all things, for the gift of Jesus,\",\"love past comparing, source of our salvation;\",\"humbly we bring You, for a world’s redeeming,\",\"our adoration.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0878', 'verse', 4, 3, '[\"So in thanksgiving for the hope of glory,\",\"love, grace and mercy all our days attending,\",\"more than our lips, Lord, let our living praise You,\",\"ages unending.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0879', 879, 'Lord, help me to know Your presence', 'MP', 'en', 'Geoff Twigg/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'Lord, help me to know Your presence
in all I do today,
Lord, help me declare Your praises
in everything I say;
live in my heart
and fill every part
with Your Holy Spirit’s flame –
O let the world see Jesus in me,
and glorify Your name!
Lord, may I become like Jesus
in everything I do:
then, if any action pleases,
glory will come to You.
Lord, may my mind
and will be refined
by Your Holy Spirit’s flame –
O let the world see Jesus in me
and glorify Your name!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0879', 'Geoff Twigg');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0879', 'Geoff Twigg');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0879', 'Richard J Hubbard');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0879', 'verse', 1, 0, '[\"Lord, help me to know Your presence\",\"in all I do today,\",\"Lord, help me declare Your praises\",\"in everything I say;\",\"live in my heart\",\"and fill every part\",\"with Your Holy Spirit’s flame –\",\"O let the world see Jesus in me,\",\"and glorify Your name!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0879', 'verse', 2, 1, '[\"Lord, may I become like Jesus\",\"in everything I do:\",\"then, if any action pleases,\",\"glory will come to You.\",\"Lord, may my mind\",\"and will be refined\",\"by Your Holy Spirit’s flame –\",\"O let the world see Jesus in me\",\"and glorify Your name!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0880', 880, 'The power of Your love', 'MP', 'en', '1992 Word Music, LLC /Song Solutions CopyCare; Maranatha Music/Universal Music/Print licence UK Song Solutions Daybreak  www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Lord, I come to You,
let my heart be changed, renewed,
flowing from the grace that I’ve found in You.
And, Lord, I’ve come to know
the weaknesses I see in me
will be stripped away
by the power of Your love.
Hold me close,
let Your love surround me;
bring me near,
draw me to Your side.
And as I wait,
I’ll rise up like the eagle,
and I will soar with You,
Your Spirit leads me on
in the power of Your love.
Lord, unveil my eyes,
let me see You face to face,
the knowledge of Your love as You live in me.
Lord, renew my mind,
as Your will unfolds in my life
in living every day
in the power of Your love.
Hold me close...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0880', 'Geoff Bullock');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0880', 'Geoff Bullock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0880', 'verse', 1, 0, '[\"Lord, I come to You,\",\"let my heart be changed, renewed,\",\"flowing from the grace that I’ve found in You.\",\"And, Lord, I’ve come to know\",\"the weaknesses I see in me\",\"will be stripped away\",\"by the power of Your love.\",\"Hold me close,\",\"let Your love surround me;\",\"bring me near,\",\"draw me to Your side.\",\"And as I wait,\",\"I’ll rise up like the eagle,\",\"and I will soar with You,\",\"Your Spirit leads me on\",\"in the power of Your love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0880', 'verse', 2, 1, '[\"Lord, unveil my eyes,\",\"let me see You face to face,\",\"the knowledge of Your love as You live in me.\",\"Lord, renew my mind,\",\"as Your will unfolds in my life\",\"in living every day\",\"in the power of Your love.\",\"Hold me close...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0881', 881, 'You came from Heaven to earth', 'MP', 'en', '1989', '', 0, 0, 0, 1, 1, 'Lord, I lift Your name on high,
Lord, I love to sing Your praises;
I’m so glad You’re in my life,
I’m so glad You came to save us.
You came from Heaven to earth
to show the way,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0881', 'Rick Founds');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0881', 'Rick Founds');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0881', 'verse', 1, 0, '[\"Lord, I lift Your name on high,\",\"Lord, I love to sing Your praises;\",\"I’m so glad You’re in my life,\",\"I’m so glad You came to save us.\",\"You came from Heaven to earth\",\"to show the way,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0882', 882, 'Lord of all hopefulness', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Lord of all hopefulness, Lord of all joy,
whose trust, ever child-like, no cares could destroy,
be there at our waking, and give us, we pray,
Your bliss in our hearts, Lord, at the break of the day.
Lord of all eagerness, Lord of all faith,
whose strong hands were skilled at the plane and the lathe,
be there at our labours, and give us, we pray,
Your strength in our hearts, Lord, at the noon of the day.
Lord of all kindliness, Lord of all grace,
Your hands swift to welcome, Your arms to embrace,
be there at our homing, and give us, we pray,
Your love in our hearts, Lord, at the eve of the day.
Lord of all gentleness, Lord of all calm,
whose voice is contentment, whose presence is balm,
be there at our sleeping, and give us, we pray,
Your peace in our hearts, Lord, at the end of the day.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0882', 'Jan Struther');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0882', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0882', 'verse', 1, 0, '[\"Lord of all hopefulness, Lord of all joy,\",\"whose trust, ever child-like, no cares could destroy,\",\"be there at our waking, and give us, we pray,\",\"Your bliss in our hearts, Lord, at the break of the day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0882', 'verse', 2, 1, '[\"Lord of all eagerness, Lord of all faith,\",\"whose strong hands were skilled at the plane and the lathe,\",\"be there at our labours, and give us, we pray,\",\"Your strength in our hearts, Lord, at the noon of the day.\"]');
