INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0883', 883, 'Lord of Lords', 'MP', 'en', '1983 Whole Armor and Full Armor Publishing Companies/Dixon Music, administered by TKO Publishing Ltd, PO Box 130, Hove, East Sussex BN3 6QU. All rights reserved. Used by permission.', '', 0, 0, 0, 1, 1, 'Lord of lords, King of kings,
Maker of Heaven and earth and all good things,
we give You glory.
Lord Jehovah, Son of Man,
precious Prince of Peace and the great ‘I');
