INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0884', 884, 'Lord, teach us to pray', 'MP', 'en', 'Geoff Twigg/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'Lord, teach us to pray;
let us know Your will every day.
Give us the grace
to go on seeking Your face,
in obedience to all that You say,
in obedience to all that You say.
Lord, help us to see
with the eyes of faith, and believe.
Give us Your heart to care
for the world in our prayer,
and a vision of what it should be,
and a vision of what it should be.');
