INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0884', 'Geoff Twigg');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0884', 'Richard J Hubbard');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0884', 'verse', 1, 0, '[\"Lord, teach us to pray;\",\"let us know Your will every day.\",\"Give us the grace\",\"to go on seeking Your face,\",\"in obedience to all that You say,\",\"in obedience to all that You say.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0884', 'verse', 2, 1, '[\"Lord, help us to see\",\"with the eyes of faith, and believe.\",\"Give us Your heart to care\",\"for the world in our prayer,\",\"and a vision of what it should be,\",\"and a vision of what it should be.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0885', 885, 'Go in Your name', 'MP', 'en', '©  1993 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Lord, we come in adoration,
lay our lives before You now,
we are here to reach the nations,
to tell the world of Jesus’ power.
We would seek Your awesome glory,
all the gifts that You endow.
Called to reach this generation,
and now is the appointed hour to:
Go in Your name,
go and proclaim Your kingdom.
Go in Your name,
for we have been chosen
to tell all creation
that Jesus is King of all kings.
We believe that You have spoken
through Your Son to all the earth,
given us this great commission
to spread the news of all Your worth.
Set apart to serve You only,
let our lives display Your love;
Hearts infused that tell the story
of God come down from Heaven above.
Go in Your name...
Grant to us a fresh anointing,
Holy Spirit, be our guide;
satisfy our deepest longing –
Jesus Christ, be glorified.
Every tribe and every people
hear the message that we bring;
Christ has triumphed over evil,
bow the knee and worship Him.
Go in Your name...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0885', 'Dave Bilbrough');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0885', 'Dave Bilbrough');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0885', 'verse', 1, 0, '[\"Lord, we come in adoration,\",\"lay our lives before You now,\",\"we are here to reach the nations,\",\"to tell the world of Jesus’ power.\",\"We would seek Your awesome glory,\",\"all the gifts that You endow.\",\"Called to reach this generation,\",\"and now is the appointed hour to:\",\"Go in Your name,\",\"go and proclaim Your kingdom.\",\"Go in Your name,\",\"for we have been chosen\",\"to tell all creation\",\"that Jesus is King of all kings.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0885', 'verse', 2, 1, '[\"We believe that You have spoken\",\"through Your Son to all the earth,\",\"given us this great commission\",\"to spread the news of all Your worth.\",\"Set apart to serve You only,\",\"let our lives display Your love;\",\"Hearts infused that tell the story\",\"of God come down from Heaven above.\",\"Go in Your name...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0885', 'verse', 3, 2, '[\"Grant to us a fresh anointing,\",\"Holy Spirit, be our guide;\",\"satisfy our deepest longing –\",\"Jesus Christ, be glorified.\",\"Every tribe and every people\",\"hear the message that we bring;\",\"Christ has triumphed over evil,\",\"bow the knee and worship Him.\",\"Go in Your name...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0886', 886, 'Lord, when the storms of life arise', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Lord, when the storms of life arise,
be near to keep me yet,
my chosen portion and my prize
in whom alone my refuge lies,
on whom my hope is set,
on whom my hope is set.
In God alone securely stand
His saints for ever blessed,
who shelter safe beneath His hand
as in a fair and pleasant land,
and in His presence rest,
and in His presence rest.
Lord of our life, our strength and stay,
whom yet unseen we love,
uphold us in the narrow way
and guide our footsteps night and day
with wisdom from above,
with wisdom from above.
So shall the path of life be shown,
the prayers of faith ascend;
until we know as we are known,
and sing before the Father’s throne
the songs that never end,
the songs that never end.');
