INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0886', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0886', 'verse', 1, 0, '[\"Lord, when the storms of life arise,\",\"be near to keep me yet,\",\"my chosen portion and my prize\",\"in whom alone my refuge lies,\",\"on whom my hope is set,\",\"on whom my hope is set.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0886', 'verse', 2, 1, '[\"In God alone securely stand\",\"His saints for ever blessed,\",\"who shelter safe beneath His hand\",\"as in a fair and pleasant land,\",\"and in His presence rest,\",\"and in His presence rest.\"]');
