INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0886', 'verse', 4, 3, '[\"So shall the path of life be shown,\",\"the prayers of faith ascend;\",\"until we know as we are known,\",\"and sing before the Father’s throne\",\"the songs that never end,\",\"the songs that never end.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0887', 887, 'Lord, You have my heart', 'MP', 'en', '©  1992 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Lord, You have my heart,
and I will search for Yours;
Jesus, take my life and lead me on.
Lord, You have my heart,
and I will search for Yours;
let me be to You a sacrifice.
MEN    And I will praise You, Lord,
WOMEN    I will praise You, Lord,
MEN    and I will sing of love come down,
WOMEN    I will sing of love come down,
MEN    and as You show Your face,
WOMEN    show Your face,
ALL    we’ll see Your glory here.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0887', 'Martin J Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0887', 'Martin J Smith');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0887', 'verse', 1, 0, '[\"Lord, You have my heart,\",\"and I will search for Yours;\",\"Jesus, take my life and lead me on.\",\"Lord, You have my heart,\",\"and I will search for Yours;\",\"let me be to You a sacrifice.\",\"MEN    And I will praise You, Lord,\",\"WOMEN    I will praise You, Lord,\",\"MEN    and I will sing of love come down,\",\"WOMEN    I will sing of love come down,\",\"MEN    and as You show Your face,\",\"WOMEN    show Your face,\",\"ALL    we’ll see Your glory here.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0888', 888, 'Loving shepherd of Thy sheep', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Loving shepherd of Thy sheep,
keep Thy lamb, in safety keep;
nothing can Thy power withstand,
none can pluck me from Thy hand.
Loving Saviour, thou didst give
Thine own life that we might live;
and the hands outstretched to bless
bear the cruel nails’ impress.
I would bless Thee every day,
gladly all Thy will obey,
like Thy blessed ones above,
happy in Thy precious love.
Loving shepherd, ever near,
teach Thy lamb Thy voice to hear;
suffer not my steps to stray');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0888', 'J E Leeson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0888', 'L G Hayne');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0888', 'verse', 1, 0, '[\"Loving shepherd of Thy sheep,\",\"keep Thy lamb, in safety keep;\",\"nothing can Thy power withstand,\",\"none can pluck me from Thy hand.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0888', 'verse', 2, 1, '[\"Loving Saviour, thou didst give\",\"Thine own life that we might live;\",\"and the hands outstretched to bless\",\"bear the cruel nails’ impress.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0888', 'verse', 3, 2, '[\"I would bless Thee every day,\",\"gladly all Thy will obey,\",\"like Thy blessed ones above,\",\"happy in Thy precious love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0888', 'verse', 4, 3, '[\"Loving shepherd, ever near,\",\"teach Thy lamb Thy voice to hear;\",\"suffer not my steps to stray\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0889', 889, 'More about Jesus', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'More about Jesus would I know;
more of His grace to others show,
more of His saving fulness see,
more of His love, who died for me.
More, more about Jesus,
more, more about Jesus;
more of His saving fulness see,
more of His love, who died for me.
More about Jesus let me learn,
more of His holy will discern;
Spirit of God, my teacher be,
showing the things of Christ to me.
More, more about Jesus...
More about Jesus, in His word
holding communion with my Lord;
hearing His voice in every line,
making each faithful saying mine.
More, more about Jesus...
More about Jesus, on His throne,
riches in glory all His own;
more of His kingdom’s sure increase;
more of His coming, Prince of Peace.
More, more about Jesus...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0889', 'E E Hewitt');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0889', 'J R Sweney');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0889', 'verse', 1, 0, '[\"More about Jesus would I know;\",\"more of His grace to others show,\",\"more of His saving fulness see,\",\"more of His love, who died for me.\",\"More, more about Jesus,\",\"more, more about Jesus;\",\"more of His saving fulness see,\",\"more of His love, who died for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0889', 'verse', 2, 1, '[\"More about Jesus let me learn,\",\"more of His holy will discern;\",\"Spirit of God, my teacher be,\",\"showing the things of Christ to me.\",\"More, more about Jesus...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0889', 'verse', 3, 2, '[\"More about Jesus, in His word\",\"holding communion with my Lord;\",\"hearing His voice in every line,\",\"making each faithful saying mine.\",\"More, more about Jesus...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0889', 'verse', 4, 3, '[\"More about Jesus, on His throne,\",\"riches in glory all His own;\",\"more of His kingdom’s sure increase;\",\"more of His coming, Prince of Peace.\",\"More, more about Jesus...\"]');
