INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0891', 891, 'Mighty God, everlasting Father', 'MP', 'en', 'Copyright 1991 Sovereign Lifestyle Music Ltd. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'Mighty God, everlasting Father,
wonderful counsellor,
You’re the Prince of Peace.
Mighty God...
You are Lord of heaven,
You are called Emmanuel;
God is now with us,
ever present to deliver.
You are God eternal,
You are Lord of all the earth;
love has come to us,
bringing us new birth.
Mighty God...
A light to those in darkness,
and a guide to paths of peace;
love and mercy dawns,
grace, forgiveness and salvation.
Light for revelation,
glory to Your people;
Son of the Most High,
God’s love gift to all.');
