INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0891', 'verse', 1, 1, '[\"You are Lord of heaven,\",\"You are called Emmanuel;\",\"God is now with us,\",\"ever present to deliver.\",\"You are God eternal,\",\"You are Lord of all the earth;\",\"love has come to us,\",\"bringing us new birth.\",\"Mighty God...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0891', 'verse', 2, 2, '[\"A light to those in darkness,\",\"and a guide to paths of peace;\",\"love and mercy dawns,\",\"grace, forgiveness and salvation.\",\"Light for revelation,\",\"glory to Your people;\",\"Son of the Most High,\",\"God’s love gift to all.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0892', 892, 'More love, more power', 'MP', 'en', '1987 Mercy/Vineyard Pub/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'MEN    More love,
WOMEN    more love,
MEN    more power,
WOMEN    more power,
ALL    more of You in my life.
MEN    More love...
ALL    And I will worship You
with all of my heart,
and I will worship You
with all of my mind,
and I will worship You
with all of my strength,
for You are my Lord.
MEN    More love...
MEN    More love...
ALL    And I will seek Your face
with all of my heart,
and I will seek Your face
with all of my mind,
and I will seek Your face
with all of my strength,
for You are my Lord,
for You are my Lord,
You are my Lord.');
