INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0892', 'Jude del Hierro');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0892', 'verse', 1, 0, '[\"MEN    More love,\",\"WOMEN    more love,\",\"MEN    more power,\",\"WOMEN    more power,\",\"ALL    more of You in my life.\",\"MEN    More love...\",\"ALL    And I will worship You\",\"with all of my heart,\",\"and I will worship You\",\"with all of my mind,\",\"and I will worship You\",\"with all of my strength,\",\"for You are my Lord.\",\"MEN    More love...\",\"MEN    More love...\",\"ALL    And I will seek Your face\",\"with all of my heart,\",\"and I will seek Your face\",\"with all of my mind,\",\"and I will seek Your face\",\"with all of my strength,\",\"for You are my Lord,\",\"for You are my Lord,\",\"You are my Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0893', 893, 'All the glory', 'MP', 'en', '1991 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'My heart is full of admiration
for You, my Lord, my God and King;
Your excellence my inspiration,
Your words of grace have made my spirit sing.
You love what’s right and hate all evil,
therefore Your God sets You on high;
and on Your head pours oil of gladness,
while fragrance fills Your royal palaces.
All the glory, honour and power
belong to You, belong to You.
Jesus, Saviour, anointed One,
I worship You, I worship You.
Your throne, O God, will last for ever;
justice will be Your royal decree:
in majesty, ride out victorious
for righteousness, truth and humility.
All the glory...
All the glory...
I worship You, I worship You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0893', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0893', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0893', 'verse', 1, 0, '[\"My heart is full of admiration\",\"for You, my Lord, my God and King;\",\"Your excellence my inspiration,\",\"Your words of grace have made my spirit sing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0893', 'verse', 2, 1, '[\"You love what’s right and hate all evil,\",\"therefore Your God sets You on high;\",\"and on Your head pours oil of gladness,\",\"while fragrance fills Your royal palaces.\",\"All the glory, honour and power\",\"belong to You, belong to You.\",\"Jesus, Saviour, anointed One,\",\"I worship You, I worship You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0893', 'verse', 3, 2, '[\"Your throne, O God, will last for ever;\",\"justice will be Your royal decree:\",\"in majesty, ride out victorious\",\"for righteousness, truth and humility.\",\"All the glory...\",\"All the glory...\",\"I worship You, I worship You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0894', 894, 'My Jesus, I love Thee', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'My Jesus, I love Thee, I know Thou art mine,
for Thee all the pleasures of sin I resign;
my gracious Redeemer, my Saviour art Thou,
if ever I loved Thee, my Jesus, ’tis now.
I love Thee because Thou hast first lovèd me,
and purchased my pardon on Calvary’s tree;
I love Thee for wearing the thorns on Thy brow,
if ever I loved Thee, my Jesus, ’tis now.
I’ll love Thee in life, I will love Thee in death,
and praise Thee as long as Thou lendest me breath;
and say, when the death-dew lies cold on my brow:
if ever I loved Thee, my Jesus, ’tis now.
In mansions of glory and endless delight,
I’ll ever adore Thee and dwell in Thy sight;
I’ll sing with the glittering crown on my brow:
if ever I loved Thee, my Jesus, ’tis now.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0894', 'W R Featherstone');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0894', 'A J Gordon');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0894', 'verse', 1, 0, '[\"My Jesus, I love Thee, I know Thou art mine,\",\"for Thee all the pleasures of sin I resign;\",\"my gracious Redeemer, my Saviour art Thou,\",\"if ever I loved Thee, my Jesus, ’tis now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0894', 'verse', 2, 1, '[\"I love Thee because Thou hast first lovèd me,\",\"and purchased my pardon on Calvary’s tree;\",\"I love Thee for wearing the thorns on Thy brow,\",\"if ever I loved Thee, my Jesus, ’tis now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0894', 'verse', 3, 2, '[\"I’ll love Thee in life, I will love Thee in death,\",\"and praise Thee as long as Thou lendest me breath;\",\"and say, when the death-dew lies cold on my brow:\",\"if ever I loved Thee, my Jesus, ’tis now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0894', 'verse', 4, 3, '[\"In mansions of glory and endless delight,\",\"I’ll ever adore Thee and dwell in Thy sight;\",\"I’ll sing with the glittering crown on my brow:\",\"if ever I loved Thee, my Jesus, ’tis now.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0895', 895, 'My life is in You, Lord', 'MP', 'en', '© 1986 Integrity\'s Hosanna! Music / adm worldwide by Capitol CMG Publishing excl UK admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'My life is in You, Lord,
my strength is in You, Lord,
my hope is in You, Lord,
in You, it’s in You.
My life is in You, Lord,
my strength is in You, Lord,
my hope is in You, Lord,
in You, it’s in You.
My life is in You, Lord...
I will praise You with all of my life,
I will praise You with all of my strength,
with all of my life,
with all of my strength.
All of my hope is in You.
My life is in You...
I will praise You...
My life is in You...
in You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0895', 'Daniel Gardner');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0895', 'Daniel Gardner');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0895', 'chorus', 0, 0, '[\"My life is in You, Lord,\",\"my strength is in You, Lord,\",\"my hope is in You, Lord,\",\"in You, it’s in You.\",\"My life is in You, Lord,\",\"my strength is in You, Lord,\",\"my hope is in You, Lord,\",\"in You, it’s in You.\",\"My life is in You, Lord...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0895', 'chorus', 0, 1, '[\"I will praise You with all of my life,\",\"I will praise You with all of my strength,\",\"with all of my life,\",\"with all of my strength.\",\"All of my hope is in You.\",\"My life is in You...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0895', 'chorus', 0, 2, '[\"I will praise You...\",\"My life is in You...\",\"in You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0896', 896, 'Restorer of my soul', 'MP', 'en', '©  1991 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'My lips shall praise You,
my great Redeemer;
my heart will worship,
almighty Saviour.
You take all my guilt away,
turn the darkest night to brightest day;
You are the Restorer of my soul.
My lips...
Love that conquers every fear!
In the midst of trouble You draw near,
You are the Restorer of my soul.
My lips...
You’re the source of happiness,
bringing peace when I am in distress;
You are the Restorer of my soul.
My lips...
Almighty Saviour,
almighty Saviour,
almighty Saviour.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0896', 'Noel Richards');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0896', 'Tricia Richards');
