INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0896', 'verse', 1, 1, '[\"You take all my guilt away,\",\"turn the darkest night to brightest day;\",\"You are the Restorer of my soul.\",\"My lips...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0896', 'verse', 2, 2, '[\"Love that conquers every fear!\",\"In the midst of trouble You draw near,\",\"You are the Restorer of my soul.\",\"My lips...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0896', 'verse', 3, 3, '[\"You’re the source of happiness,\",\"bringing peace when I am in distress;\",\"You are the Restorer of my soul.\",\"My lips...\",\"Almighty Saviour,\",\"almighty Saviour,\",\"almighty Saviour.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0897', 897, 'My peace I leave with you', 'MP', 'en', '', '', 0, 0, 0, 1, 1, '‘My peace I leave with you’, this is His promise;
‘My peace I give to you’, this is His word.
Let not our hearts be sad, troubled or uncertain;
‘My peace I leave with you.’
Lord Jesus, grant to us that peace enduring,
not as the world imparts – unsure, untrue;
but inward happiness past our understanding –
‘My peace I leave with you.’
O may this peace be known throughout all nations,
that strife and enmity on earth may cease,
and ways of peace replace weapons of destruction –
‘My peace I leave with you.’
O happy prophecy! O blessèd promise!
O may we always strive to make it true;
and may we never lose our dear Master’s message –
‘My peace I leave with you.’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0897', 'Brian Thomas');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0897', 'Brian Thomas');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0897', 'verse', 1, 0, '[\"‘My peace I leave with you’, this is His promise;\",\"‘My peace I give to you’, this is His word.\",\"Let not our hearts be sad, troubled or uncertain;\",\"‘My peace I leave with you.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0897', 'verse', 2, 1, '[\"Lord Jesus, grant to us that peace enduring,\",\"not as the world imparts – unsure, untrue;\",\"but inward happiness past our understanding –\",\"‘My peace I leave with you.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0897', 'verse', 3, 2, '[\"O may this peace be known throughout all nations,\",\"that strife and enmity on earth may cease,\",\"and ways of peace replace weapons of destruction –\",\"‘My peace I leave with you.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0897', 'verse', 4, 3, '[\"O happy prophecy! O blessèd promise!\",\"O may we always strive to make it true;\",\"and may we never lose our dear Master’s message –\",\"‘My peace I leave with you.’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0898', 898, 'No other name', 'MP', 'en', '© 1988 Integrity\'s Hosanna! Music / adm worldwide by Capitol CMG Publishing excl UK admin by Integritymusic.com, a division of David C Cook  songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'No other name but the name of Jesus,
no other name but the name of the Lord;
no other name but the name of Jesus
is worthy of glory,
and worthy of honour,
and worthy of power and all praise.
No other name...
His name is exalted far above the earth,
His name is high above the heavens;
His name is exalted far above the earth –
give glory and honour and praises to His name.
No other name...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0898', 'Robert Gay');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0898', 'Robert Gay');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0898', 'chorus', 0, 0, '[\"No other name but the name of Jesus,\",\"no other name but the name of the Lord;\",\"no other name but the name of Jesus\",\"is worthy of glory,\",\"and worthy of honour,\",\"and worthy of power and all praise.\",\"No other name...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0898', 'chorus', 0, 1, '[\"His name is exalted far above the earth,\",\"His name is high above the heavens;\",\"His name is exalted far above the earth –\",\"give glory and honour and praises to His name.\",\"No other name...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0899', 899, 'Only You', 'MP', 'en', '1988 Mercy/Vineyard Publishing/Vineyard Songs Canada/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'No-one but You, Lord,
can satisfy the longing in my heart.
Nothing I do, Lord,
can take the place of drawing near to You.
Only You can fill my deepest longing,
only You can breathe in me new life;
only You can fill my heart with laughter,
only You can answer my heart’s cry.
Father, I love You,
come, satisfy the longing in my heart.
Fill me, overwhelm me,
until I know Your love deep in my heart.
Only You...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0899', 'Andy Park');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0899', 'Andy Park');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0899', 'verse', 1, 0, '[\"No-one but You, Lord,\",\"can satisfy the longing in my heart.\",\"Nothing I do, Lord,\",\"can take the place of drawing near to You.\",\"Only You can fill my deepest longing,\",\"only You can breathe in me new life;\",\"only You can fill my heart with laughter,\",\"only You can answer my heart’s cry.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0899', 'verse', 2, 1, '[\"Father, I love You,\",\"come, satisfy the longing in my heart.\",\"Fill me, overwhelm me,\",\"until I know Your love deep in my heart.\",\"Only You...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0900', 900, 'Nothing shall separate us', 'MP', 'en', '1989 Thankyou Music, administered by worshiptogether.com songs excl. UK and Europe, administered by kingswaysongs.com. tym@kingsway.co.uk. Used by permission.', '', 0, 0, 0, 1, 0, 'Nothing shall separate us from the love of God.
Nothing shall separate us from the love of God.
God did not spare His only Son,
gave Him to save us all.
Sin’s price was met by Jesus’ death
and Heaven’s mercy falls.
Nothing shall separate us...
Up from the grave Jesus was raised
to sit at God’s right hand;
pleading our cause in Heaven’s courts –
forgiven we can stand.
Nothing shall separate us...
Now by God’s grace we have embraced
a life set free from sin;
we shall deny all that destroys
our union with Him.
Nothing shall separate us...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0900', 'Noel Richards');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0900', 'Tricia Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0900', 'Noel Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0900', 'Tricia Richards');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0900', 'chorus', 0, 0, '[\"Nothing shall separate us from the love of God.\",\"Nothing shall separate us from the love of God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0900', 'verse', 1, 1, '[\"God did not spare His only Son,\",\"gave Him to save us all.\",\"Sin’s price was met by Jesus’ death\",\"and Heaven’s mercy falls.\",\"Nothing shall separate us...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0900', 'verse', 2, 2, '[\"Up from the grave Jesus was raised\",\"to sit at God’s right hand;\",\"pleading our cause in Heaven’s courts –\",\"forgiven we can stand.\",\"Nothing shall separate us...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0900', 'verse', 3, 3, '[\"Now by God’s grace we have embraced\",\"a life set free from sin;\",\"we shall deny all that destroys\",\"our union with Him.\",\"Nothing shall separate us...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0901', 901, 'Now is Christ risen from the dead', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Now is Christ risen from the dead,
now are the powers of darkness fled,
Alleluia, alleluia!
Gone is the night of sin and gloom,
Jesus is risen from the tomb.
Alleluia, alleluia,
alleluia, alleluia,
alleluia!
Now is Christ risen from the dead,
empty there lies His narrow bed,
Alleluia, alleluia!
Christ and His cross have won the day,
come, see the grave in which He lay.
Alleluia, alleluia,
alleluia, alleluia,
alleluia!
Now is Christ risen from the dead,
He who His blood for sinners shed,
Alleluia, alleluia!
In Him who died to bear our sins
our resurrection-life begins.
Alleluia, alleluia,
alleluia, alleluia,
alleluia!
Now is Christ risen from the dead,
risen and reigning as He said,
Alleluia, alleluia!
Praise Him who light and life restored,
praise Him, our ever-living Lord!
Alleluia, alleluia,
alleluia, alleluia,
alleluia!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0901', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0901', 'David Peacock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0901', 'verse', 1, 0, '[\"Now is Christ risen from the dead,\",\"now are the powers of darkness fled,\",\"Alleluia, alleluia!\",\"Gone is the night of sin and gloom,\",\"Jesus is risen from the tomb.\",\"Alleluia, alleluia,\",\"alleluia, alleluia,\",\"alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0901', 'verse', 2, 1, '[\"Now is Christ risen from the dead,\",\"empty there lies His narrow bed,\",\"Alleluia, alleluia!\",\"Christ and His cross have won the day,\",\"come, see the grave in which He lay.\",\"Alleluia, alleluia,\",\"alleluia, alleluia,\",\"alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0901', 'verse', 3, 2, '[\"Now is Christ risen from the dead,\",\"He who His blood for sinners shed,\",\"Alleluia, alleluia!\",\"In Him who died to bear our sins\",\"our resurrection-life begins.\",\"Alleluia, alleluia,\",\"alleluia, alleluia,\",\"alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0901', 'verse', 4, 3, '[\"Now is Christ risen from the dead,\",\"risen and reigning as He said,\",\"Alleluia, alleluia!\",\"Praise Him who light and life restored,\",\"praise Him, our ever-living Lord!\",\"Alleluia, alleluia,\",\"alleluia, alleluia,\",\"alleluia!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0902', 902, 'Jesus, let me meet You in Your word', 'MP', 'en', '1991, 1993 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Now in reverence and awe
we gather round Your word;
in wonder we draw near
to mysteries that angels strain to hear,
that prophets dimly saw:
so let Your Spirit shine upon the page
and teach me;
open up my eyes, with truth to free me,
light to chase the lies.
Lord Jesus, let me meet You in Your word;
Lord Jesus, let me meet You in Your word.
Lord, Your truth cannot be chained;
it searches everything –
my secrets, my desires.
Your word is like a hammer and a fire –
it breaks, it purifies:
so let Your Spirit shine into my heart
and teach me;
open up my eyes...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0902', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0902', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0902', 'Steve Thompson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0902', 'verse', 1, 0, '[\"Now in reverence and awe\",\"we gather round Your word;\",\"in wonder we draw near\",\"to mysteries that angels strain to hear,\",\"that prophets dimly saw:\",\"so let Your Spirit shine upon the page\",\"and teach me;\",\"open up my eyes, with truth to free me,\",\"light to chase the lies.\",\"Lord Jesus, let me meet You in Your word;\",\"Lord Jesus, let me meet You in Your word.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0902', 'verse', 2, 1, '[\"Lord, Your truth cannot be chained;\",\"it searches everything –\",\"my secrets, my desires.\",\"Your word is like a hammer and a fire –\",\"it breaks, it purifies:\",\"so let Your Spirit shine into my heart\",\"and teach me;\",\"open up my eyes...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0903', 903, 'Now the fruit of the Spirit', 'MP', 'en', 'Salvationist Publishing & Supplies (Admin. by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Now the fruit of the Spirit is patience,
and the fruit of the Spirit is peace,
the fruit of the Spirit is gentleness,
and joy that will never cease.
The gift of the Spirit is healing,
and hope for the darkest hour,
the gift of the Spirit is love, yes, love,
and power, and power.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0903', 'John Larsson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0903', 'John Larsson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0903', 'verse', 1, 0, '[\"Now the fruit of the Spirit is patience,\",\"and the fruit of the Spirit is peace,\",\"the fruit of the Spirit is gentleness,\",\"and joy that will never cease.\",\"The gift of the Spirit is healing,\",\"and hope for the darkest hour,\",\"the gift of the Spirit is love, yes, love,\",\"and power, and power.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0904', 904, 'O Lord, I want to sing Your praises', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'O Lord, I want to sing Your praises,
I want to praise Your name every day;
O Lord, I want to sing Your praises,
I want to praise Your name every day.
Alleluia, allelu-, alleluia, allelu-!
O Lord, I want to sing Your praises,
I want to praise Your name every day;
O Lord, I want to sing Your praises,
I want to praise Your name every day.
Alleluia, allelu-, alleluia, allelu-!
Alleluia!
God, You are my God,
and I will seek You;
I am satisfied when I find Your love.
God, You are my God,
and I will seek You;
I am satisfied when I find Your love.
And I will praise You as long as I live,
for Your love is better than life;
in Your name I will lift up my hands,
for Your love is better than life.
Alleluia, allelu-, alleluia, allelu-!
O Lord, I want to sing Your praises,
I want to praise Your name every day;
O Lord, I want to sing Your praises,
I want to praise Your name every day.
Alleluia, allelu-, alleluia, allelu-!
Alleluia!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0904', 'Andy Park');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0904', 'Stuart Townend');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0904', 'verse', 1, 0, '[\"O Lord, I want to sing Your praises,\",\"I want to praise Your name every day;\",\"O Lord, I want to sing Your praises,\",\"I want to praise Your name every day.\",\"Alleluia, allelu-, alleluia, allelu-!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0904', 'verse', 2, 1, '[\"O Lord, I want to sing Your praises,\",\"I want to praise Your name every day;\",\"O Lord, I want to sing Your praises,\",\"I want to praise Your name every day.\",\"Alleluia, allelu-, alleluia, allelu-!\",\"Alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0904', 'verse', 3, 2, '[\"God, You are my God,\",\"and I will seek You;\",\"I am satisfied when I find Your love.\",\"God, You are my God,\",\"and I will seek You;\",\"I am satisfied when I find Your love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0904', 'verse', 4, 3, '[\"And I will praise You as long as I live,\",\"for Your love is better than life;\",\"in Your name I will lift up my hands,\",\"for Your love is better than life.\",\"Alleluia, allelu-, alleluia, allelu-!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0904', 'verse', 5, 4, '[\"O Lord, I want to sing Your praises,\",\"I want to praise Your name every day;\",\"O Lord, I want to sing Your praises,\",\"I want to praise Your name every day.\",\"Alleluia, allelu-, alleluia, allelu-!\",\"Alleluia!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0905', 905, 'O Christ the King of glory', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O Christ the King of glory,
who chose the way of loss
to share our human story,
to bear that bitter cross;
by loving self-surrender,
by all the pains You bore,
You won for us the splendour
of life for evermore.
May God, whose care unsleeping
holds all beneath His hand,
enfold within His keeping
the Church in every land.
Through doubtings and denials,
through grief to glory come,
through all their fiery trials
He leads His children home.
O Lord of life, ascended
to glory from the grave,
Your grace be still extended
to help and heal and save.
O Captain of salvation,
in mercy bring to birth
Your new redeemed creation');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0905', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0905', 'Roger Mayor');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0905', 'verse', 1, 0, '[\"O Christ the King of glory,\",\"who chose the way of loss\",\"to share our human story,\",\"to bear that bitter cross;\",\"by loving self-surrender,\",\"by all the pains You bore,\",\"You won for us the splendour\",\"of life for evermore.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0905', 'verse', 2, 1, '[\"May God, whose care unsleeping\",\"holds all beneath His hand,\",\"enfold within His keeping\",\"the Church in every land.\",\"Through doubtings and denials,\",\"through grief to glory come,\",\"through all their fiery trials\",\"He leads His children home.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0905', 'verse', 3, 2, '[\"O Lord of life, ascended\",\"to glory from the grave,\",\"Your grace be still extended\",\"to help and heal and save.\",\"O Captain of salvation,\",\"in mercy bring to birth\",\"Your new redeemed creation\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0906', 906, 'Father me', 'MP', 'en', '1992 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'O Father of the fatherless
in whom all families are blessed,
I love the way You father me.
You gave me life, forgave the past;
now in Your arms I’m safe at last –
I love the way You father me.
Father me, for ever You’ll father me;
and in Your embrace I’ll be
for ever secure.
I love the way You father me,
I love the way You father me.
When bruised and broken I draw near,
You hold me close and dry my tears,
I love the way You father me.
At last my fearful heart is still,
surrendered to Your perfect will –
I love the way You father me.
Father me...
If in my foolishness I stray,
returning empty and ashamed,
I love the way You father me.
Exchanging for my wretchedness
Your radiant robes of righteousness –
I love the way You father me.
Father me...
And when I look into Your eyes,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0906', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0906', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0906', 'verse', 1, 0, '[\"O Father of the fatherless\",\"in whom all families are blessed,\",\"I love the way You father me.\",\"You gave me life, forgave the past;\",\"now in Your arms I’m safe at last –\",\"I love the way You father me.\",\"Father me, for ever You’ll father me;\",\"and in Your embrace I’ll be\",\"for ever secure.\",\"I love the way You father me,\",\"I love the way You father me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0906', 'verse', 2, 1, '[\"When bruised and broken I draw near,\",\"You hold me close and dry my tears,\",\"I love the way You father me.\",\"At last my fearful heart is still,\",\"surrendered to Your perfect will –\",\"I love the way You father me.\",\"Father me...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0906', 'verse', 3, 2, '[\"If in my foolishness I stray,\",\"returning empty and ashamed,\",\"I love the way You father me.\",\"Exchanging for my wretchedness\",\"Your radiant robes of righteousness –\",\"I love the way You father me.\",\"Father me...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0906', 'verse', 4, 3, '[\"And when I look into Your eyes,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0907', 907, 'O God of Bethel', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'O God of Bethel, by whose hand
Thy people still are fed,
who through this weary pilgrimage
hast all our fathers led.
Our vows, our prayers, we now present
before Thy throne of grace;
God of our fathers, be the God
of their succeeding race.
Through each perplexing path of life
our wandering footsteps guide;
give us each day our daily bread,
and raiment fit provide.
O spread Thy covering wings around,
’til all our wanderings cease,
and at our Father’s loved abode
our souls arrive in peace.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0907', 'Philip Doddridge');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0907', 'J Logan');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0907', 'verse', 1, 0, '[\"O God of Bethel, by whose hand\",\"Thy people still are fed,\",\"who through this weary pilgrimage\",\"hast all our fathers led.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0907', 'verse', 2, 1, '[\"Our vows, our prayers, we now present\",\"before Thy throne of grace;\",\"God of our fathers, be the God\",\"of their succeeding race.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0907', 'verse', 3, 2, '[\"Through each perplexing path of life\",\"our wandering footsteps guide;\",\"give us each day our daily bread,\",\"and raiment fit provide.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0907', 'verse', 4, 3, '[\"O spread Thy covering wings around,\",\"’til all our wanderings cease,\",\"and at our Father’s loved abode\",\"our souls arrive in peace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0908', 908, 'O Lord, hear my prayer', 'MP', 'en', 'Ateliers et Presses de Taizé, 71250 Taizé, France.', '', 0, 0, 0, 1, 1, 'O Lord, hear my prayer;
O Lord, hear my prayer:
when I call, answer me –
O Lord, hear my prayer;
O Lord, hear my prayer;
come and listen to me.
O Lord...');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0908', 'Jacques Berthier');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0908', 'verse', 1, 0, '[\"O Lord, hear my prayer;\",\"O Lord, hear my prayer:\",\"when I call, answer me –\",\"O Lord, hear my prayer;\",\"O Lord, hear my prayer;\",\"come and listen to me.\",\"O Lord...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0909', 909, 'O Lord, the refuge', 'MP', 'en', 'Basil E Bridge            ©  Harper Collins Religious (admin. by Song Solutions Copycare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'O Lord, the refuge of each generation,
You reigned before the universe began;
we bear Your stamp, the marks of Your creation,
and yet how frail we are, how brief life’s span.
One thousand years like yesterday in passing,
our fleeting lives like half-remembered dreams,
or weeds that flower at noon but die by evening –
so, Lord, to You our transient glory seems.
O Holy Lord, forgive our self-deceiving –
our secret sins are clear before Your face:
grant us release, the joy of those believing
they are restored by Your eternal grace.
Time rushes on: give us a heart of wisdom
that seeks Your will and follows Your commands;
show us Your deeds, Your glory to our children,
work out Your timeless purpose through our hands.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0909', 'Basil E Bridge');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0909', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0909', 'verse', 1, 0, '[\"O Lord, the refuge of each generation,\",\"You reigned before the universe began;\",\"we bear Your stamp, the marks of Your creation,\",\"and yet how frail we are, how brief life’s span.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0909', 'verse', 2, 1, '[\"One thousand years like yesterday in passing,\",\"our fleeting lives like half-remembered dreams,\",\"or weeds that flower at noon but die by evening –\",\"so, Lord, to You our transient glory seems.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0909', 'verse', 3, 2, '[\"O Holy Lord, forgive our self-deceiving –\",\"our secret sins are clear before Your face:\",\"grant us release, the joy of those believing\",\"they are restored by Your eternal grace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0909', 'verse', 4, 3, '[\"Time rushes on: give us a heart of wisdom\",\"that seeks Your will and follows Your commands;\",\"show us Your deeds, Your glory to our children,\",\"work out Your timeless purpose through our hands.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0910', 910, 'O Lord, whose saving name', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O Lord, whose saving name
is life and health and rest,
to whom the children came
and in Your arms were blessed,
we seek Your face;
Your love be shown,
Your presence known
within this place.
That love be ours to share
with tenderness and skill,
with science, faith and prayer
to work Your sovereign will;
we praise You, Lord,
for banished pain,
for strength again,
for health restored.
When deepest shadows fall
to quench life’s fading spark,
be near us when we call,
walk with us through the dark,
our Light and Way,
by grief and loss,
and bitter cross,
to endless day.
In God our hope is set,
beneath whose rule alone
is peace from fear and fret
and strength beyond our own.
His kingdom stands,
and those this day
for whom we pray
are in His hands.
Join every heart to bring
our praise to God above,
whom children’s voices sing
and whom unseen we love.
O God of grace,
for evermore
Your blessings pour
upon this place.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0910', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0910', 'John Darwall');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0910', 'Roger Mayor');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0910', 'verse', 1, 0, '[\"O Lord, whose saving name\",\"is life and health and rest,\",\"to whom the children came\",\"and in Your arms were blessed,\",\"we seek Your face;\",\"Your love be shown,\",\"Your presence known\",\"within this place.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0910', 'verse', 2, 1, '[\"That love be ours to share\",\"with tenderness and skill,\",\"with science, faith and prayer\",\"to work Your sovereign will;\",\"we praise You, Lord,\",\"for banished pain,\",\"for strength again,\",\"for health restored.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0910', 'verse', 3, 2, '[\"When deepest shadows fall\",\"to quench life’s fading spark,\",\"be near us when we call,\",\"walk with us through the dark,\",\"our Light and Way,\",\"by grief and loss,\",\"and bitter cross,\",\"to endless day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0910', 'verse', 4, 3, '[\"In God our hope is set,\",\"beneath whose rule alone\",\"is peace from fear and fret\",\"and strength beyond our own.\",\"His kingdom stands,\",\"and those this day\",\"for whom we pray\",\"are in His hands.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0910', 'verse', 5, 4, '[\"Join every heart to bring\",\"our praise to God above,\",\"whom children’s voices sing\",\"and whom unseen we love.\",\"O God of grace,\",\"for evermore\",\"Your blessings pour\",\"upon this place.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0911', 911, 'The Comforter has come', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'O spread the tidings round
wherever man is found,
wherever human hearts
and human woes abound;
let every Christian tongue
proclaim the joyful sound:
the Comforter has come!
The Comforter has come,
the Comforter has come,
the Holy Ghost from Heaven,
the Father’s promise given,
O spread the tidings round
wherever man is found:
the Comforter has come!
Lo, the great King of kings
with healing in His wings
to every captive soul
a full deliverance brings;
and through the vacant cells
the song of triumph rings:
the Comforter has come!
The Comforter has come...
O boundless love divine!
How shall this tongue of mine
to wondering mortals tell
the matchless grace divine –
that I, a child of hell,
should in His image shine!
The Comforter has come!
The Comforter has come...
Sing, ’til the echoes fly
above the vaulted sky,
and all the saints above
to all below reply,
in strains of endless love,
the song that ne’er will die:
The Comforter has come!
The Comforter has come...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0911', 'F Bottome');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0911', 'William James Kirkpatrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0911', 'verse', 1, 0, '[\"O spread the tidings round\",\"wherever man is found,\",\"wherever human hearts\",\"and human woes abound;\",\"let every Christian tongue\",\"proclaim the joyful sound:\",\"the Comforter has come!\",\"The Comforter has come,\",\"the Comforter has come,\",\"the Holy Ghost from Heaven,\",\"the Father’s promise given,\",\"O spread the tidings round\",\"wherever man is found:\",\"the Comforter has come!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0911', 'verse', 2, 1, '[\"Lo, the great King of kings\",\"with healing in His wings\",\"to every captive soul\",\"a full deliverance brings;\",\"and through the vacant cells\",\"the song of triumph rings:\",\"the Comforter has come!\",\"The Comforter has come...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0911', 'verse', 3, 2, '[\"O boundless love divine!\",\"How shall this tongue of mine\",\"to wondering mortals tell\",\"the matchless grace divine –\",\"that I, a child of hell,\",\"should in His image shine!\",\"The Comforter has come!\",\"The Comforter has come...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0911', 'verse', 4, 3, '[\"Sing, ’til the echoes fly\",\"above the vaulted sky,\",\"and all the saints above\",\"to all below reply,\",\"in strains of endless love,\",\"the song that ne’er will die:\",\"The Comforter has come!\",\"The Comforter has come...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0912', 912, 'I was made for this', 'MP', 'en', '1995 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Oh, I was made for this:
to know Your tender kiss,
to know a love divine,
to know this love is mine.
And I was made to laugh,
and I was made to sing,
given the gift of life:
You gave me everything.
My feet were made to dance,
my spirit made to soar,
my life is not by chance,
You give me more and more.
For I was made for You,
and I have made my choice,
and all that stole my joy,
I left it at the cross.
So I will celebrate
and drink Your cup of joy,
I will give thanks each day and sing.
My joy is found in You
and You are all my joy,
oh, I was made for this.
When I was far away
You ran to welcome me,
I felt Your warm embrace;
I saw Your smiling face.
And when You rescued me
I saw my destiny:
to worship You, my Lord,
to be a friend of God.
So I will celebrate...
I was made to love You, Jesus,
I was made for this.
I was made to love You, Jesus,
I was made for this.
So I will celebrate...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0912', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0912', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0912', 'verse', 1, 0, '[\"Oh, I was made for this:\",\"to know Your tender kiss,\",\"to know a love divine,\",\"to know this love is mine.\",\"And I was made to laugh,\",\"and I was made to sing,\",\"given the gift of life:\",\"You gave me everything.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0912', 'verse', 2, 1, '[\"My feet were made to dance,\",\"my spirit made to soar,\",\"my life is not by chance,\",\"You give me more and more.\",\"For I was made for You,\",\"and I have made my choice,\",\"and all that stole my joy,\",\"I left it at the cross.\",\"So I will celebrate\",\"and drink Your cup of joy,\",\"I will give thanks each day and sing.\",\"My joy is found in You\",\"and You are all my joy,\",\"oh, I was made for this.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0912', 'verse', 3, 2, '[\"When I was far away\",\"You ran to welcome me,\",\"I felt Your warm embrace;\",\"I saw Your smiling face.\",\"And when You rescued me\",\"I saw my destiny:\",\"to worship You, my Lord,\",\"to be a friend of God.\",\"So I will celebrate...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0912', 'chorus', 0, 3, '[\"I was made to love You, Jesus,\",\"I was made for this.\",\"I was made to love You, Jesus,\",\"I was made for this.\",\"So I will celebrate...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0913', 913, 'One thing I ask', 'MP', 'en', 'Mercy/Vineyard Publishing/Vineyard Songs Canada/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'One thing I ask, one thing I seek,
that I may dwell in Your house, O Lord,
all of my days, all of my life –
that I may see You, Lord.
Hear me, O Lord, hear me when I cry;
Lord, do not hide Your face from me:
You have been my strength,
You have been my shield,
and You will lift me up.
One thing I ask,
one thing I desire
is to see You,
is to see You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0913', 'Andy Park');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0913', 'Andy Park');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0913', 'verse', 1, 0, '[\"One thing I ask, one thing I seek,\",\"that I may dwell in Your house, O Lord,\",\"all of my days, all of my life –\",\"that I may see You, Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0913', 'verse', 2, 1, '[\"Hear me, O Lord, hear me when I cry;\",\"Lord, do not hide Your face from me:\",\"You have been my strength,\",\"You have been my shield,\",\"and You will lift me up.\",\"One thing I ask,\",\"one thing I desire\",\"is to see You,\",\"is to see You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0914', 914, 'Only by grace', 'MP', 'en', '© 1990 Integrity\'s Hosanna! Music / adm worldwide by Capitol CMG Publishing excl UK admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Only by grace can we enter,
only by grace can we stand;
not by our human endeavour,
but by the blood of the Lamb.
Into Your presence You call us,
You call us to come;
into Your presence You draw us,
and now by Your grace we come,
now by Your grace we come.
Lord, if You mark our transgressions who would stand?
Thanks to Your grace we are cleansed by the blood of the Lamb.
Lord, if You mark...
Only by grace...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0914', 'Gerrit Gustafson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0914', 'Gerrit Gustafson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0914', 'verse', 1, 0, '[\"Only by grace can we enter,\",\"only by grace can we stand;\",\"not by our human endeavour,\",\"but by the blood of the Lamb.\",\"Into Your presence You call us,\",\"You call us to come;\",\"into Your presence You draw us,\",\"and now by Your grace we come,\",\"now by Your grace we come.\",\"Lord, if You mark our transgressions who would stand?\",\"Thanks to Your grace we are cleansed by the blood of the Lamb.\",\"Lord, if You mark...\",\"Only by grace...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0915', 915, 'Open our eyes, O Lord', 'MP', 'en', '1976 CCCM Music/Maranatha! Music/Music Services/Universal Music/Print Licence UK Song Solutions Daybreak www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Open our eyes, O Lord, we pray,
enlighten heart and mind;
that as we read Your word today
we may its treasures find.
Open our ears, that, small and still,
Your voice be clearly heard,
to guide our steps and cleanse our will
according to Your word.
Open our lives to love’s embrace,
our dear redeeming Lord:
Your word of life and truth and grace
within our souls be stored.
Open our lips, O Lord, in praise
to tell what love imparts:
the work of grace about our ways,
your word within our hearts.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0915', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0915', 'Jeremiah Clarke');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0915', 'verse', 1, 0, '[\"Open our eyes, O Lord, we pray,\",\"enlighten heart and mind;\",\"that as we read Your word today\",\"we may its treasures find.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0915', 'verse', 2, 1, '[\"Open our ears, that, small and still,\",\"Your voice be clearly heard,\",\"to guide our steps and cleanse our will\",\"according to Your word.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0915', 'verse', 3, 2, '[\"Open our lives to love’s embrace,\",\"our dear redeeming Lord:\",\"Your word of life and truth and grace\",\"within our souls be stored.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0915', 'verse', 4, 3, '[\"Open our lips, O Lord, in praise\",\"to tell what love imparts:\",\"the work of grace about our ways,\",\"your word within our hearts.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0916', 916, 'All-embracing love', 'MP', 'en', 'Serious Music UK Ltd            © EMI UK; Ragstar Music/Adm by Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Out of a heart of love
You gave creation birth;
with grace and power and might,
You formed a perfect earth.
Such a mighty God,
in majesty arrayed,
and yet You know each step I take');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0916', 'Phil Thomson');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0916', 'Paul Field');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0916', 'verse', 1, 0, '[\"Out of a heart of love\",\"You gave creation birth;\",\"with grace and power and might,\",\"You formed a perfect earth.\",\"Such a mighty God,\",\"in majesty arrayed,\",\"and yet You know each step I take\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0917', 917, 'The Lord’s prayer', 'MP', 'en', '1994 Lawson Spiller/Copyright control', '', 0, 0, 0, 1, 1, 'Our dear Father who art in Heaven,
hallowèd be Your name,
Your kingdom come,
Your will be done
on earth as it is in Heaven.
Give us this day our daily bread,
and forgive our debts as we forgive our debtors,
and lead us not into temptation
but deliver us from the evil one,
for Yours is the kingdom,
Yours is the power,
Yours is the glory
for ever. Amen.');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0917', 'Lawson Spiller');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0917', 'Julian A Perkins');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0917', 'verse', 1, 0, '[\"Our dear Father who art in Heaven,\",\"hallowèd be Your name,\",\"Your kingdom come,\",\"Your will be done\",\"on earth as it is in Heaven.\",\"Give us this day our daily bread,\",\"and forgive our debts as we forgive our debtors,\",\"and lead us not into temptation\",\"but deliver us from the evil one,\",\"for Yours is the kingdom,\",\"Yours is the power,\",\"Yours is the glory\",\"for ever. Amen.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0918', 918, 'Overwhelmed by love', 'MP', 'en', '©  1994 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Overwhelmed by love,
deeper than oceans,
high as the heavens;
ever-living God,
Your love has rescued me.
All my sin was laid
on Your dear Son,
Your precious one.
All my debt He paid –
great is Your love for me.
No-one could ever earn Your love,
Your grace and mercy is free.
Lord, these words are true –
so is my love for You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0918', 'Noel Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0918', 'Noel Richards');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0918', 'verse', 1, 0, '[\"Overwhelmed by love,\",\"deeper than oceans,\",\"high as the heavens;\",\"ever-living God,\",\"Your love has rescued me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0918', 'verse', 2, 1, '[\"All my sin was laid\",\"on Your dear Son,\",\"Your precious one.\",\"All my debt He paid –\",\"great is Your love for me.\",\"No-one could ever earn Your love,\",\"Your grace and mercy is free.\",\"Lord, these words are true –\",\"so is my love for You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0919', 919, 'You’re the holy Lord almighty', 'MP', 'en', 'Mercy/Vineyard Publishing/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 0, 'Part the waters that surround me,
may the wind and waves be still.
Pierce the soul of my confusion,
clear the mist and rend the veil.
See the longing in my spirit,
know that I choose to be Yours.
Lord, I’m hungry and I’m thirsting
to be filled and to be used.
You’re the holy Lord almighty
and I come to seek Your face,
You’re my light, my hope, my mercy,
and Jesus is Your name.
Part the waters...
You’re the holy Lord almighty...
You’re the holy Lord almighty...
and Jesus is Your name.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0919', 'Rick Cole');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0919', 'Rick Cole');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0919', 'chorus', 0, 0, '[\"Part the waters that surround me,\",\"may the wind and waves be still.\",\"Pierce the soul of my confusion,\",\"clear the mist and rend the veil.\",\"See the longing in my spirit,\",\"know that I choose to be Yours.\",\"Lord, I’m hungry and I’m thirsting\",\"to be filled and to be used.\",\"You’re the holy Lord almighty\",\"and I come to seek Your face,\",\"You’re my light, my hope, my mercy,\",\"and Jesus is Your name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0919', 'chorus', 0, 1, '[\"Part the waters...\",\"You’re the holy Lord almighty...\",\"You’re the holy Lord almighty...\",\"and Jesus is Your name.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0920', 920, 'Praise the Lord, you heavens', 'MP', 'en', 'Harper Collins Religious (admin. by Song Solutions Copycare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Praise the Lord, you heavens, adore Him –
praise Him, angels in the height!
Sun and moon, rejoice before Him;
praise Him, all you stars and light!
Praise the Lord, for He has spoken:
worlds His mighty voice obeyed;
laws, which never shall be broken,
for their guidance He has made.
Praise the Lord, for He is glorious!
Never shall His promise fail.
God has made His saints victorious,
sin and death shall not prevail.
Praise the God of our salvation!
Hosts on high, his power proclaim;
Heaven and earth and all creation,
laud and magnify His name!
Worship, honour, glory, blessing,
Lord, we offer to Your name.
Young and old, Your praise expressing,
join their Saviour to proclaim.
As the saints in Heaven adore You,
we would bow before Your throne,
As Your angels serve before You,
so on earth Your will be done.
Words v. 3 by E Osler');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0920', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0920', 'verse', 1, 0, '[\"Praise the Lord, you heavens, adore Him –\",\"praise Him, angels in the height!\",\"Sun and moon, rejoice before Him;\",\"praise Him, all you stars and light!\",\"Praise the Lord, for He has spoken:\",\"worlds His mighty voice obeyed;\",\"laws, which never shall be broken,\",\"for their guidance He has made.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0920', 'verse', 2, 1, '[\"Praise the Lord, for He is glorious!\",\"Never shall His promise fail.\",\"God has made His saints victorious,\",\"sin and death shall not prevail.\",\"Praise the God of our salvation!\",\"Hosts on high, his power proclaim;\",\"Heaven and earth and all creation,\",\"laud and magnify His name!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0920', 'verse', 3, 2, '[\"Worship, honour, glory, blessing,\",\"Lord, we offer to Your name.\",\"Young and old, Your praise expressing,\",\"join their Saviour to proclaim.\",\"As the saints in Heaven adore You,\",\"we would bow before Your throne,\",\"As Your angels serve before You,\",\"so on earth Your will be done.\",\"Words v. 3 by E Osler\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0921', 921, 'Refiner’s fire', 'MP', 'en', '1990 Vineyard Songs/Song Solutions Copycare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Purify my heart,
let me be as gold and precious silver;
purify my heart,
let me be as gold, pure gold.
Refiner’s fire, my heart’s one desire
is to be holy,
set apart for You, Lord;
I choose to be holy,
set apart for You, my Master,
ready to do Your will.
Purify my heart,
cleanse me from within and make me holy;
purify my heart,
cleanse me from my sin, deep within.
Refiner’s fire...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0921', 'Brian Doerksen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0921', 'Brian Doerksen');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0921', 'verse', 1, 0, '[\"Purify my heart,\",\"let me be as gold and precious silver;\",\"purify my heart,\",\"let me be as gold, pure gold.\",\"Refiner’s fire, my heart’s one desire\",\"is to be holy,\",\"set apart for You, Lord;\",\"I choose to be holy,\",\"set apart for You, my Master,\",\"ready to do Your will.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0921', 'verse', 2, 1, '[\"Purify my heart,\",\"cleanse me from within and make me holy;\",\"purify my heart,\",\"cleanse me from my sin, deep within.\",\"Refiner’s fire...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0922', 922, 'Rumours of angels', 'MP', 'en', '1994 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'Rumours of angels,
visions of light,
new star appearing,
piercing the night.
Town full of strangers
sleeps in the gloom.
God comes among us;
there is no room.
Rumours of angels,
songs in the night,
deep in the danger,
unquenchable light.
World full of strangers
sleeps in the gloom.
God comes among us;
there is no room.
And the years of our sorrow
have rolled on and on,
and the wars of our pride never cease.
We have ravaged the earth
with our envy and greed –
tell me, when will we welcome His peace?
When will we welcome His peace?
Hearts full of longing,
eyes filled with tears,
nations are waiting
at the end of the years.
Empires are falling,
judgements appear.
God comes among us;
His kingdom is near.
And the years of our sorrow...
And the years of our sorrow...
Oh, when will we welcome the Prince of Peace?');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0922', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0922', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0922', 'verse', 1, 0, '[\"Rumours of angels,\",\"visions of light,\",\"new star appearing,\",\"piercing the night.\",\"Town full of strangers\",\"sleeps in the gloom.\",\"God comes among us;\",\"there is no room.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0922', 'verse', 2, 1, '[\"Rumours of angels,\",\"songs in the night,\",\"deep in the danger,\",\"unquenchable light.\",\"World full of strangers\",\"sleeps in the gloom.\",\"God comes among us;\",\"there is no room.\",\"And the years of our sorrow\",\"have rolled on and on,\",\"and the wars of our pride never cease.\",\"We have ravaged the earth\",\"with our envy and greed –\",\"tell me, when will we welcome His peace?\",\"When will we welcome His peace?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0922', 'verse', 3, 2, '[\"Hearts full of longing,\",\"eyes filled with tears,\",\"nations are waiting\",\"at the end of the years.\",\"Empires are falling,\",\"judgements appear.\",\"God comes among us;\",\"His kingdom is near.\",\"And the years of our sorrow...\",\"And the years of our sorrow...\",\"Oh, when will we welcome the Prince of Peace?\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0923', 923, 'Here am I, my Lord', 'MP', 'en', 'Salvationist Publishing & Supplies/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'WOMEN    See how the world groans beneath sin’s spell!
Lord, who will go? Lord, who will go?
ALL    Someone must care for them, someone tell,
tell of Christ, tell of His power to set men free!
Here am I, my Lord! Send me, send me!
I am wanting to be what You want me to be!
Use me when and wherever and how You best see;
Here am I, my Lord, send me!
MEN    How can I go with my sin and shame?
Great God on high! Lord, who am I?
ALL    Cleanse now my heart with the living flame!
Make me pure, O make me strong – Lord, I will go.
Here am I, my Lord...
ALL    Make me a servant to serve just You –
Lord, I’ll obey, use me, I pray!
Teach me to speak – may my life ring true!
All my words and all my actions pleasing You!
Here am I, my Lord...
Here am I, my Lord...
Here am I, my Lord, send me!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0923', 'Howard Davies');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0923', 'Howard Davies');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0923', 'verse', 1, 0, '[\"WOMEN    See how the world groans beneath sin’s spell!\",\"Lord, who will go? Lord, who will go?\",\"ALL    Someone must care for them, someone tell,\",\"tell of Christ, tell of His power to set men free!\",\"Here am I, my Lord! Send me, send me!\",\"I am wanting to be what You want me to be!\",\"Use me when and wherever and how You best see;\",\"Here am I, my Lord, send me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0923', 'verse', 2, 1, '[\"MEN    How can I go with my sin and shame?\",\"Great God on high! Lord, who am I?\",\"ALL    Cleanse now my heart with the living flame!\",\"Make me pure, O make me strong – Lord, I will go.\",\"Here am I, my Lord...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0923', 'verse', 3, 2, '[\"ALL    Make me a servant to serve just You –\",\"Lord, I’ll obey, use me, I pray!\",\"Teach me to speak – may my life ring true!\",\"All my words and all my actions pleasing You!\",\"Here am I, my Lord...\",\"Here am I, my Lord...\",\"Here am I, my Lord, send me!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0924', 924, 'Salvation belongs to our God', 'MP', 'en', 'Copyright 1985 Restoration Music Sovereignmusic@aol.com', '', 0, 0, 0, 1, 1, 'Salvation belongs to our God,
who sits on the throne,
and unto the Lamb.
Praise and glory,
wisdom and thanks,
honour and power and strength
be to our God for ever and ever,
be to our God for ever and ever,
be to our God for ever and ever,
amen.
And we, the redeemed, shall be strong
in purpose and unity,
declaring aloud:
praise and glory,
wisdom and thanks,
honour and power and strength
be to our God...');
