INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0924', 'Pat Turner');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0924', 'verse', 1, 0, '[\"Salvation belongs to our God,\",\"who sits on the throne,\",\"and unto the Lamb.\",\"Praise and glory,\",\"wisdom and thanks,\",\"honour and power and strength\",\"be to our God for ever and ever,\",\"be to our God for ever and ever,\",\"be to our God for ever and ever,\",\"amen.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0924', 'verse', 2, 1, '[\"And we, the redeemed, shall be strong\",\"in purpose and unity,\",\"declaring aloud:\",\"praise and glory,\",\"wisdom and thanks,\",\"honour and power and strength\",\"be to our God...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0925', 925, 'See His glory', 'MP', 'en', 'Copyright 1986 Sovereign Lifestyle Music Ltd. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'See His glory, see His glory,
see His glory now appear.
See His glory, see His glory,
see His glory now appear.
God of light, holiness and truth,
power and might –
see His glory, see it now appear.
Now we declare our God is good,
and His mercies endure for ever.
Now we declare our God is good,
and His mercies endure for ever.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0925', 'Chris Bowater');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0925', 'Chris Bowater');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0925', 'verse', 1, 0, '[\"See His glory, see His glory,\",\"see His glory now appear.\",\"See His glory, see His glory,\",\"see His glory now appear.\",\"God of light, holiness and truth,\",\"power and might –\",\"see His glory, see it now appear.\",\"Now we declare our God is good,\",\"and His mercies endure for ever.\",\"Now we declare our God is good,\",\"and His mercies endure for ever.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0926', 926, 'Shalom, shalom', 'MP', 'en', 'Harper Collins Religious (admin. by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Shalom, shalom,
peace to His people;
shalom, shalom,
the grace of God be with you,
now and for ever!
The love of God be with you,
a boundless love without measure:
a love you daily must treasure,
now and for ever.
Shalom, shalom...
The grace of God be with you,
a boundless grace without measure:
His grace and favour we treasure,
now and for ever.
Shalom, shalom...
The peace of God be with you,
a quiet calm without measure:
God’s loving peace you must treasure,
now and for ever.
Shalom, shalom...');
