INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0929', 929, 'Sing to the Lord a joyful song', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Sing to the Lord a joyful song,
lift up your hearts, your voices raise;
to us His gracious gifts belong,
to Him our songs of love and praise.
For life and love, for rest and food,
for daily help and nightly care,
sing to the Lord, for He is good,
and praise His name, for it is fair.
For strength to those who on Him wait
His truth to prove, His will to do,
praise ye our God, for He is great,
trust in His name, for it is true.
For joys untold, that from above
cheer those who love His sweet employ,
sing to our God, for He is love,
exalt His name, for it is joy.
Sing to the Lord of Heaven and earth,
whom angels serve and saints adore,
the Father, Son and Holy Ghost,
to whom be praise for evermore.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0929', 'William Smallwood');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0929', 'John Samuel Bewley Monsell');
