INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0929', 'verse', 3, 2, '[\"For strength to those who on Him wait\",\"His truth to prove, His will to do,\",\"praise ye our God, for He is great,\",\"trust in His name, for it is true.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0929', 'verse', 4, 3, '[\"For joys untold, that from above\",\"cheer those who love His sweet employ,\",\"sing to our God, for He is love,\",\"exalt His name, for it is joy.\"]');
