INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0933', 933, 'Stir my heart', 'MP', 'en', '©  1988 Authentic Publishing / Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'Stir my heart, O Lord,
let Your holy fire burn;
spark a flame within me,
strengthen my desire:
may my heart, O Lord,
be so tender in Your hand;
breathe Your life within me,
stir my heart, O Lord.');
