INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0933', 'Steve Bassett');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0933', 'verse', 1, 0, '[\"Stir my heart, O Lord,\",\"let Your holy fire burn;\",\"spark a flame within me,\",\"strengthen my desire:\",\"may my heart, O Lord,\",\"be so tender in Your hand;\",\"breathe Your life within me,\",\"stir my heart, O Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0934', 934, 'Sweet feast of love divine', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Sweet feast of love divine!
’Tis grace that makes us free
to feed upon this bread and wine
in memory, Lord, of Thee.
Here every welcome guest
waits, Lord, from Thee to learn
the secrets of Thy Father’s breast,
and all Thy grace discern.
Here conscience ends its strife,
and faith delights to prove
the sweetness of the bread of life,
the fulness of Thy love.
Thy blood that flowed for sin,
in symbol here we see,
and feel the blessed pledge within,
that we are loved of Thee.
But if this glimpse of love
is so divinely sweet,
what will it be, O Lord, above,
Thy gladdening smile to meet;
To see Thee face to face,
Thy perfect likeness wear,
and all Thy ways of wondrous grace
Through endless years declare!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0934', 'E Denny');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0934', 'verse', 1, 0, '[\"Sweet feast of love divine!\",\"’Tis grace that makes us free\",\"to feed upon this bread and wine\",\"in memory, Lord, of Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0934', 'verse', 2, 1, '[\"Here every welcome guest\",\"waits, Lord, from Thee to learn\",\"the secrets of Thy Father’s breast,\",\"and all Thy grace discern.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0934', 'verse', 3, 2, '[\"Here conscience ends its strife,\",\"and faith delights to prove\",\"the sweetness of the bread of life,\",\"the fulness of Thy love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0934', 'verse', 4, 3, '[\"Thy blood that flowed for sin,\",\"in symbol here we see,\",\"and feel the blessed pledge within,\",\"that we are loved of Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0934', 'verse', 5, 4, '[\"But if this glimpse of love\",\"is so divinely sweet,\",\"what will it be, O Lord, above,\",\"Thy gladdening smile to meet;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0934', 'verse', 6, 5, '[\"To see Thee face to face,\",\"Thy perfect likeness wear,\",\"and all Thy ways of wondrous grace\",\"Through endless years declare!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0935', 935, 'Take up your cross', 'MP', 'en', '', '', 0, 0, 0, 1, 1, '‘Take up your cross!’ the Saviour said,
‘if you would my disciple be;
deny yourself, the world forsake
and humbly follow after me.’
Take up your cross – let not its weight
fill your weak spirit with alarm:
His strength shall bear your spirit up,
and brace your heart, and nerve your arm.
Take up your cross, nor heed the shame,
nor let your foolish pride rebel:
your Lord for you the cross endured
to save your soul from death and hell.
Take up your cross, then, in His strength,
and calmly every danger brave;
’twill guide you to a better home,
and lead to victory o’er the grave.
Take up your cross, and follow Christ,
nor think ’til death to lay it down;
for only he who bears the cross
may hope to wear the glorious crown.
To You, great Lord, the One-in-three,
all praise for evermore ascend:
O grant us in our home to see
the heavenly life that knows no end.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0935', 'C W Everest');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0935', 'Felix Mendelssohn');
