INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0935', 'verse', 3, 2, '[\"Take up your cross, nor heed the shame,\",\"nor let your foolish pride rebel:\",\"your Lord for you the cross endured\",\"to save your soul from death and hell.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0935', 'verse', 4, 3, '[\"Take up your cross, then, in His strength,\",\"and calmly every danger brave;\",\"’twill guide you to a better home,\",\"and lead to victory o’er the grave.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0935', 'verse', 5, 4, '[\"Take up your cross, and follow Christ,\",\"nor think ’til death to lay it down;\",\"for only he who bears the cross\",\"may hope to wear the glorious crown.\"]');
