INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0951', 951, 'My desire', 'MP', 'en', '©  1991 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'To be in Your presence,
to sit at Your feet,
where Your love surrounds me,
and makes me complete:
this is my desire, O Lord,
this is my desire.
This is my desire, O Lord,
this is my desire.
To rest in Your presence,
not rushing away,
to cherish each moment –
here I would stay:
this is my desire...');
