INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0952', 952, 'Touch my life', 'MP', 'en', '1994 Song Solutions Daybreak www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Touch my life, O Lord my God;
holy fire, come.
Touch my lips that I might speak
of the wonders of Your Son.
Touch my heart, O Lord my God,
cleanse me with Your blood.
Fill me with Your Spirit, Lord,
flow through me like a flood.
Your Spirit’s anointing I desire:
the power of God.
To demonstrate justice, Lord, I need
the power of God.
To tell of Your healing and release,
the power of God.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0952', 'Derek Bond');
