INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0952', 'verse', 2, 1, '[\"Touch my heart, O Lord my God,\",\"cleanse me with Your blood.\",\"Fill me with Your Spirit, Lord,\",\"flow through me like a flood.\",\"Your Spirit’s anointing I desire:\",\"the power of God.\",\"To demonstrate justice, Lord, I need\",\"the power of God.\",\"To tell of Your healing and release,\",\"the power of God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0953', 953, 'To Your majesty', 'MP', 'en', '©  1988 Authentic Publishing / Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'To Your majesty and Your beauty I surrender,
to Your holiness and Your love I surrender,
for You are an awesome God who is mighty,
You deserve my deepest praise:
with all of my heart, with all of my life, I surrender.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0953', 'Sue Rinaldi');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0953', 'Steve Bassett');
