INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0953', 'verse', 1, 0, '[\"To Your majesty and Your beauty I surrender,\",\"to Your holiness and Your love I surrender,\",\"for You are an awesome God who is mighty,\",\"You deserve my deepest praise:\",\"with all of my heart, with all of my life, I surrender.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0954', 954, 'Siyahamba', 'MP', 'en', '1990 WGRG The Iona Community, 4th Floor, Savoy House, 140 Sauchiehall Street, Glasgow G2 3DH            verses 2 and 3 © Copyright  Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'We are marching in the light of God,
we are marching in the light of God,
we are marching in the light of God,
we are marching in the light of God (the light of God)!
We are marching (marching,
we are marching, marching,) – Oh,
we are marching in the light of God
(the light of God)!
We are marching (marching,
we are marching, marching,) – Oh,
we are marching in the light of God!
We are living in the love of God...
We are moving in the power of God...
Words English text verse 1 by Anders Nyberg
Words English text verses 2 and 3 by Andrew Maries
Music arrangement by Anders Nyberg');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0954', 'verse', 1, 0, '[\"We are marching in the light of God,\",\"we are marching in the light of God,\",\"we are marching in the light of God,\",\"we are marching in the light of God (the light of God)!\",\"We are marching (marching,\",\"we are marching, marching,) – Oh,\",\"we are marching in the light of God\",\"(the light of God)!\",\"We are marching (marching,\",\"we are marching, marching,) – Oh,\",\"we are marching in the light of God!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0954', 'verse', 2, 1, '[\"We are living in the love of God...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0954', 'verse', 3, 2, '[\"We are moving in the power of God...\",\"Words English text verse 1 by Anders Nyberg\",\"Words English text verses 2 and 3 by Andrew Maries\",\"Music arrangement by Anders Nyberg\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0955', 955, 'Go forth in His name', 'MP', 'en', '1990 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'We are His children, the fruit of His suffering,
saved and redeemed by His blood;
called to be holy, a light to the nations:
clothed with His power, filled with His love.
Go forth in His name,
proclaiming ‘Jesus reigns!’
Now is the time for the Church to arise
and proclaim Him, ‘Jesus,
Saviour, Redeemer and Lord.’
Go forth in His name...
Countless the souls that are stumbling in darkness:
why do we sleep in the light?
Jesus commands us to go, make disciples –
this is our cause, this is our fight.
Go forth in His name...
Listen, the wind of the Spirit is blowing,
the end of the age is so near;
powers in the earth and the heavens are shaking,
Jesus our Lord soon shall appear!
Go forth in His name...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0955', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0955', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0955', 'verse', 1, 0, '[\"We are His children, the fruit of His suffering,\",\"saved and redeemed by His blood;\",\"called to be holy, a light to the nations:\",\"clothed with His power, filled with His love.\",\"Go forth in His name,\",\"proclaiming ‘Jesus reigns!’\",\"Now is the time for the Church to arise\",\"and proclaim Him, ‘Jesus,\",\"Saviour, Redeemer and Lord.’\",\"Go forth in His name...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0955', 'verse', 2, 1, '[\"Countless the souls that are stumbling in darkness:\",\"why do we sleep in the light?\",\"Jesus commands us to go, make disciples –\",\"this is our cause, this is our fight.\",\"Go forth in His name...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0955', 'verse', 3, 2, '[\"Listen, the wind of the Spirit is blowing,\",\"the end of the age is so near;\",\"powers in the earth and the heavens are shaking,\",\"Jesus our Lord soon shall appear!\",\"Go forth in His name...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0956', 956, 'We turn to Christ alone', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'We turn to Christ alone,
the Son of God divine,
to bow the knee before His throne,
to bear His name and sign;
to bear His name and sign
and walk the narrow way,
to make His love and glory known,
His word and will obey.
We turn from self and sin
in penitence and shame;
we trust, to make us clean within,
the power of Jesus’ name;
the power of Jesus’ name,
whose cross is strong to save,
who gave His life our life to win');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0956', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0956', 'Joseph Parry');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0956', 'verse', 1, 0, '[\"We turn to Christ alone,\",\"the Son of God divine,\",\"to bow the knee before His throne,\",\"to bear His name and sign;\",\"to bear His name and sign\",\"and walk the narrow way,\",\"to make His love and glory known,\",\"His word and will obey.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0956', 'verse', 2, 1, '[\"We turn from self and sin\",\"in penitence and shame;\",\"we trust, to make us clean within,\",\"the power of Jesus’ name;\",\"the power of Jesus’ name,\",\"whose cross is strong to save,\",\"who gave His life our life to win\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0957', 957, 'We want to see Jesus lifted high', 'MP', 'en', '©  1993 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'We want to see Jesus lifted high,
a banner that flies across this land,
that all men might see the truth and know
He is the way to Heaven.
We want to see Jesus lifted high...
We want to see,
we want to see,
we want to see Jesus lifted high,
we want to see,
we want to see,
we want to see Jesus lifted high.
Step by step we’re moving forward,
little by little taking ground,
every prayer a powerful weapon,
strongholds come tumbling down and down and down and down.
We want to see Jesus lifted high...
We’re gonna see,
we’re gonna see,
we’re gonna see Jesus lifted high,
we’re gonna see,
we’re gonna see
we’re gonna see Jesus lifted high.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0957', 'Doug Horley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0957', 'Doug Horley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0957', 'verse', 1, 0, '[\"We want to see Jesus lifted high,\",\"a banner that flies across this land,\",\"that all men might see the truth and know\",\"He is the way to Heaven.\",\"We want to see Jesus lifted high...\",\"We want to see,\",\"we want to see,\",\"we want to see Jesus lifted high,\",\"we want to see,\",\"we want to see,\",\"we want to see Jesus lifted high.\",\"Step by step we’re moving forward,\",\"little by little taking ground,\",\"every prayer a powerful weapon,\",\"strongholds come tumbling down and down and down and down.\",\"We want to see Jesus lifted high...\",\"We’re gonna see,\",\"we’re gonna see,\",\"we’re gonna see Jesus lifted high,\",\"we’re gonna see,\",\"we’re gonna see\",\"we’re gonna see Jesus lifted high.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0958', 958, 'Welcome, King of kings', 'MP', 'en', '©  1991 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Welcome, King of kings!
How great is Your name!
You come in majesty
for ever to reign.
You rule the nations,
they shake at the sound of Your name –
to You is given all power,
and You shall reign.
Welcome, King of kings...
Let all creation bow down
at the sound of Your name.
Let every tongue now confess
the Lord God reigns.
Welcome, King of kings...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0958', 'Noel Richards');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0958', 'Noel Richards');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0958', 'chorus', 0, 0, '[\"Welcome, King of kings!\",\"How great is Your name!\",\"You come in majesty\",\"for ever to reign.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0958', 'verse', 1, 1, '[\"You rule the nations,\",\"they shake at the sound of Your name –\",\"to You is given all power,\",\"and You shall reign.\",\"Welcome, King of kings...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0958', 'verse', 2, 2, '[\"Let all creation bow down\",\"at the sound of Your name.\",\"Let every tongue now confess\",\"the Lord God reigns.\",\"Welcome, King of kings...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0959', 959, 'What kind of greatness', 'MP', 'en', '1994 Make Way Music. www.grahamkendrick.co.uk.', '', 0, 0, 0, 1, 1, 'What kind of greatness can this be,
that chose to be made small,
exchanging untold majesty
for a world so pitiful?
That God should come as one of us
I’ll never understand –
the more I hear the story told,
the more amazed I am.
Oh, what else can I do
but kneel and worship You,
and come just as I am,
my whole life an offering.
The One in whom we live and move
in swaddling clothes lies bound.
The voice that cried ‘Let there be light!’,
asleep without a sound.
The One who strode among the stars,
and called each one by name,
lies helpless in a mother’s arms
and must learn to walk again.
Oh, what else can I do...
What greater love could He have shown
to shamed humanity?
Yet human pride hates to believe
in such deep humility.
But nations now may see His grace
and know that He is near,
when His meek heart, His words, His works
are incarnate in us here.
Oh, what else can I do...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0959', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0959', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0959', 'verse', 1, 0, '[\"What kind of greatness can this be,\",\"that chose to be made small,\",\"exchanging untold majesty\",\"for a world so pitiful?\",\"That God should come as one of us\",\"I’ll never understand –\",\"the more I hear the story told,\",\"the more amazed I am.\",\"Oh, what else can I do\",\"but kneel and worship You,\",\"and come just as I am,\",\"my whole life an offering.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0959', 'verse', 2, 1, '[\"The One in whom we live and move\",\"in swaddling clothes lies bound.\",\"The voice that cried ‘Let there be light!’,\",\"asleep without a sound.\",\"The One who strode among the stars,\",\"and called each one by name,\",\"lies helpless in a mother’s arms\",\"and must learn to walk again.\",\"Oh, what else can I do...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0959', 'verse', 3, 2, '[\"What greater love could He have shown\",\"to shamed humanity?\",\"Yet human pride hates to believe\",\"in such deep humility.\",\"But nations now may see His grace\",\"and know that He is near,\",\"when His meek heart, His words, His works\",\"are incarnate in us here.\",\"Oh, what else can I do...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0960', 960, 'Whatever is true', 'MP', 'en', '1991 Vineyard Songs Canada/Song Solutions CopyCare  www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Whatever is true, whatever is right,
whatever is pure, whatever is lovely,
we will fix our thoughts on these things.
Jesus, You’re true, Jesus, You’re right,
Jesus, You’re pure, You are lovely.
We will fix our thoughts on You.
MEN    Jesus,
WOMEN    Jesus,
MEN    who is like You,
WOMEN    who is like You?
MEN    Jesus,
WOMEN    Jesus,
MEN    who is like You,
WOMEN    who is like You?
MEN    Jesus...
ALL    who is like You?');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0960', 'Brian Doerksen');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0960', 'Craig Musseau');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0960', 'Brian Doerksen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0960', 'Craig Musseau');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0960', 'verse', 1, 0, '[\"Whatever is true, whatever is right,\",\"whatever is pure, whatever is lovely,\",\"we will fix our thoughts on these things.\",\"Jesus, You’re true, Jesus, You’re right,\",\"Jesus, You’re pure, You are lovely.\",\"We will fix our thoughts on You.\",\"MEN    Jesus,\",\"WOMEN    Jesus,\",\"MEN    who is like You,\",\"WOMEN    who is like You?\",\"MEN    Jesus,\",\"WOMEN    Jesus,\",\"MEN    who is like You,\",\"WOMEN    who is like You?\",\"MEN    Jesus...\",\"ALL    who is like You?\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0961', 961, 'When I lift up my voice', 'MP', 'en', 'Mrs B Perry/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION            Copyright ©  1988 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a div. of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'When I lift up my voice,
and I cry to the Lord,
and I pour out my troubles before Him;
when I see no-one cares,
and I walk all alone,
and my spirit grows weary within me,
then I sing:
‘You are my refuge,
I will praise Your name;
You are so good to me, O Lord!’
Then I sing...
‘You are so good to me,
You are so good to me,
You are so good to me, O Lord!’
Then He’ll come to my side
and He’ll answer my prayers,
and He’ll set my soul free from its prison;
then the righteous will see
and they’ll gather around
all because of His goodness towards me.
Then they’ll sing:
‘You are our refuge,
we will praise Your name;
You are so good to us, O Lord!’
Then they’ll sing...
‘You are so good to us,
You are so good to us,
You are so good to us, O Lord!’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0961', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0961', 'Chris Rolinson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0961', 'verse', 1, 0, '[\"When I lift up my voice,\",\"and I cry to the Lord,\",\"and I pour out my troubles before Him;\",\"when I see no-one cares,\",\"and I walk all alone,\",\"and my spirit grows weary within me,\",\"then I sing:\",\"‘You are my refuge,\",\"I will praise Your name;\",\"You are so good to me, O Lord!’\",\"Then I sing...\",\"‘You are so good to me,\",\"You are so good to me,\",\"You are so good to me, O Lord!’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0961', 'verse', 2, 1, '[\"Then He’ll come to my side\",\"and He’ll answer my prayers,\",\"and He’ll set my soul free from its prison;\",\"then the righteous will see\",\"and they’ll gather around\",\"all because of His goodness towards me.\",\"Then they’ll sing:\",\"‘You are our refuge,\",\"we will praise Your name;\",\"You are so good to us, O Lord!’\",\"Then they’ll sing...\",\"‘You are so good to us,\",\"You are so good to us,\",\"You are so good to us, O Lord!’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0962', 962, 'When my sorrows cover me', 'MP', 'en', 'Mrs B Perry/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION            Copyright ©  1987 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a div. of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'When my sorrows cover me, save me, O God;
when my friends abandon me,
when I seek what cannot be,
when I look and cannot see,
save me, O God,
save me, O God.
You know all my guilty fears, thank You, O God.
You have heard with open ears,
You have seen my contrite tears,
You will bless my future years,
thank You, O God,
thank You, O God,
thank You, O God.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0962', 'Michael Perry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0962', 'Chris Rolinson');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0962', 'verse', 1, 0, '[\"When my sorrows cover me, save me, O God;\",\"when my friends abandon me,\",\"when I seek what cannot be,\",\"when I look and cannot see,\",\"save me, O God,\",\"save me, O God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0962', 'verse', 2, 1, '[\"You know all my guilty fears, thank You, O God.\",\"You have heard with open ears,\",\"You have seen my contrite tears,\",\"You will bless my future years,\",\"thank You, O God,\",\"thank You, O God,\",\"thank You, O God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0963', 963, 'With undivided heart', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'With undivided heart and ceaseless songs
give thanks to God.
To Him all majesty and praise belongs:
give thanks to God.
His love and truth proclaim,
His mercy still the same;
and for His holy name
give thanks to God.
Exalt His name and His eternal word,
He is our God.
Before His throne our every prayer is heard,
He is our God.
Let kings declare His praise,
sing of His words and ways,
for through eternal days
He is our God.
He reigns in glory from His throne above,
He is the Lord:
and in our weakness meets us with His love:
He is the Lord.
His purpose cannot fail,
though fears and foes assail,
His love shall still prevail,
He is the Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0963', 'Timothy Dudley-Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0963', 'Greg Leavers');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0963', 'verse', 1, 0, '[\"With undivided heart and ceaseless songs\",\"give thanks to God.\",\"To Him all majesty and praise belongs:\",\"give thanks to God.\",\"His love and truth proclaim,\",\"His mercy still the same;\",\"and for His holy name\",\"give thanks to God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0963', 'verse', 2, 1, '[\"Exalt His name and His eternal word,\",\"He is our God.\",\"Before His throne our every prayer is heard,\",\"He is our God.\",\"Let kings declare His praise,\",\"sing of His words and ways,\",\"for through eternal days\",\"He is our God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0963', 'verse', 3, 2, '[\"He reigns in glory from His throne above,\",\"He is the Lord:\",\"and in our weakness meets us with His love:\",\"He is the Lord.\",\"His purpose cannot fail,\",\"though fears and foes assail,\",\"His love shall still prevail,\",\"He is the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0964', 964, 'With all my heart', 'MP', 'en', '1992 Roger Mayor, administered by The Jubilate Group, 4 Thorne Park Road, Torquay TQ2 6RX. www.jubilate.co.uk. Used by permission.', '', 0, 0, 0, 1, 1, 'With all my heart
I’ll sing praises to You my King,
with all my being,
exalt Your name!
Words never can express
my heartfelt thankfulness,
but this I now confess,
‘I love You, Lord.’
With all my heart...
‘I’ll serve You, Lord.’');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0964', 'Roger Mayor');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0964', 'Roger Mayor');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0964', 'verse', 1, 0, '[\"With all my heart\",\"I’ll sing praises to You my King,\",\"with all my being,\",\"exalt Your name!\",\"Words never can express\",\"my heartfelt thankfulness,\",\"but this I now confess,\",\"‘I love You, Lord.’\",\"With all my heart...\",\"‘I’ll serve You, Lord.’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0965', 965, 'Wonderful counsellor', 'MP', 'en', 'Salvationist Publishing and Supplies/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 0, 'Wonderful counsellor, mighty God among us,
everlasting Father, Prince who rules in peace.
To us a child is born, to us a son is given,
to those who walked in darkness the light has come.
Son of God, Son of Man, Word of God incarnate,
suffering Saviour, glorious risen Lord.
For God so loved the world He gave His only son;
no more we walk in darkness, the light has come.
King of kings, Lord of lords, Son of God exalted;
name above every name, Lamb upon the throne.
This king will come again, the Father’s only son;
no more a world in darkness, the light will come.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0965', 'Chick Yuill');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0965', 'Chick Yuill');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0965', 'verse', 1, 0, '[\"Wonderful counsellor, mighty God among us,\",\"everlasting Father, Prince who rules in peace.\",\"To us a child is born, to us a son is given,\",\"to those who walked in darkness the light has come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0965', 'verse', 2, 1, '[\"Son of God, Son of Man, Word of God incarnate,\",\"suffering Saviour, glorious risen Lord.\",\"For God so loved the world He gave His only son;\",\"no more we walk in darkness, the light has come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0965', 'verse', 3, 2, '[\"King of kings, Lord of lords, Son of God exalted;\",\"name above every name, Lamb upon the throne.\",\"This king will come again, the Father’s only son;\",\"no more a world in darkness, the light will come.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0966', 966, 'Wonderful grace', 'MP', 'en', '1986 HarperCollins Religious (Admin. by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Wonderful grace
that gives what I don’t deserve,
pays me what Christ has earned,
then lets me go free.
Wonderful grace
that gives me the time to change,
washes away the stains
that once covered me.
And all that I have
I lay at the feet
of the wonderful Saviour
who loves me.
Wonderful love
that held in the face of death,
breathed in its latest breath
forgiveness for me.
Wonderful love,
whose power can break every chain,
giving us life again
and setting us free.
And all that I have...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0966', 'John Pantry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0966', 'John Pantry');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0966', 'Christopher Norton');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0966', 'verse', 1, 0, '[\"Wonderful grace\",\"that gives what I don’t deserve,\",\"pays me what Christ has earned,\",\"then lets me go free.\",\"Wonderful grace\",\"that gives me the time to change,\",\"washes away the stains\",\"that once covered me.\",\"And all that I have\",\"I lay at the feet\",\"of the wonderful Saviour\",\"who loves me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0966', 'verse', 2, 1, '[\"Wonderful love\",\"that held in the face of death,\",\"breathed in its latest breath\",\"forgiveness for me.\",\"Wonderful love,\",\"whose power can break every chain,\",\"giving us life again\",\"and setting us free.\",\"And all that I have...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0967', 967, 'At Calvary', 'MP', 'en', 'control', '', 0, 0, 0, 1, 1, 'Years I spent in vanity and pride,
caring not my Lord was crucified,
knowing not it was for me He died on Calvary.
Mercy there was great and grace was free,
pardon there was multiplied to me,
there my burdened soul found liberty,
at Calvary.
By God’s word at last my sin I learned,
then I trembled at the law I’d spurned,
’til my guilty soul imploring turned to Calvary.
Mercy there was great...
Now I’ve given to Jesus everything,
now I gladly own Him as my King,
now my raptured soul can only sing of Calvary.
Mercy there was great...
Oh, the love that drew salvation’s plan!
Oh, the grace that brought it down to man!
Oh, the mighty gulf that God did span at Calvary!
Mercy there was great...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0967', 'William Reed Newell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0967', 'Daniel Brink Towner');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0967', 'verse', 1, 0, '[\"Years I spent in vanity and pride,\",\"caring not my Lord was crucified,\",\"knowing not it was for me He died on Calvary.\",\"Mercy there was great and grace was free,\",\"pardon there was multiplied to me,\",\"there my burdened soul found liberty,\",\"at Calvary.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0967', 'verse', 2, 1, '[\"By God’s word at last my sin I learned,\",\"then I trembled at the law I’d spurned,\",\"’til my guilty soul imploring turned to Calvary.\",\"Mercy there was great...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0967', 'verse', 3, 2, '[\"Now I’ve given to Jesus everything,\",\"now I gladly own Him as my King,\",\"now my raptured soul can only sing of Calvary.\",\"Mercy there was great...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0967', 'verse', 4, 3, '[\"Oh, the love that drew salvation’s plan!\",\"Oh, the grace that brought it down to man!\",\"Oh, the mighty gulf that God did span at Calvary!\",\"Mercy there was great...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0968', 968, 'Triumph of Your grace', 'MP', 'en', '1993 Steve Chua', '', 0, 0, 0, 1, 1, 'You are the rock on which we stand,
we place our lives into Your hands,
at the foot of the cross we acknowledge You as Lord,
Jesus, victorious King of kings.
We give glory and praises to Your name,
we will lift You high above the earth
in the triumph of Your grace.
We give glory...
Secure and steadfast in Your love,
we stand in the power of Your blood,
with Your Spirit of truth anointing our desire
to fight against the powers of this age.
We give glory...
Not fashioned by the pattern of this world,
we take our cross and Jesus we will serve,
as we offer our lives as a holy sacrifice,
refine us, Lord, and set Your Church ablaze.
We give glory...
in the triumph of Your grace.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0968', 'Steve Chua');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0968', 'Steve Chua');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0968', 'Daniel Chua');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0968', 'verse', 1, 0, '[\"You are the rock on which we stand,\",\"we place our lives into Your hands,\",\"at the foot of the cross we acknowledge You as Lord,\",\"Jesus, victorious King of kings.\",\"We give glory and praises to Your name,\",\"we will lift You high above the earth\",\"in the triumph of Your grace.\",\"We give glory...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0968', 'verse', 2, 1, '[\"Secure and steadfast in Your love,\",\"we stand in the power of Your blood,\",\"with Your Spirit of truth anointing our desire\",\"to fight against the powers of this age.\",\"We give glory...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0968', 'verse', 3, 2, '[\"Not fashioned by the pattern of this world,\",\"we take our cross and Jesus we will serve,\",\"as we offer our lives as a holy sacrifice,\",\"refine us, Lord, and set Your Church ablaze.\",\"We give glory...\",\"in the triumph of Your grace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0969', 969, 'I’m for ever grateful', 'MP', 'en', '© 1986 Sovereign Grace Praise / Adm. by Capitol CMG Publishing excl. UK, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 1, 'You did not wait for me to draw near to You,
but You clothed Yourself in frail humanity.
You did not wait for me to cry out to You,
but You let me hear Your voice calling me,
and I’m for ever grateful to You,
I’m for ever grateful for the cross,
I’m for ever grateful to You,
that You came to seek and save the lost.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0969', 'Mark Altrogge');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0969', 'Mark Altrogge');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0969', 'verse', 1, 0, '[\"You did not wait for me to draw near to You,\",\"but You clothed Yourself in frail humanity.\",\"You did not wait for me to cry out to You,\",\"but You let me hear Your voice calling me,\",\"and I’m for ever grateful to You,\",\"I’m for ever grateful for the cross,\",\"I’m for ever grateful to You,\",\"that You came to seek and save the lost.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0970', 970, 'You make my heart feel glad', 'MP', 'en', '©  1990 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'You make my heart feel glad,
You make my heart feel glad,
Jesus, You bring me joy,
You make my heart feel glad.
Lord, Your love brings healing
and a peace into my heart,
I want to give myself in praise to You.
Though I’ve been through heartache
You have understood my tears.
O Lord, I will give thanks to You.
You make my heart feel glad...
When I look around me,
and I see the life You made,
all creation shouts aloud in praise.
I realize Your greatness,
how majestic is Your name,
O Lord, I love You more each day.
You make my heart feel glad...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0970', 'Trish Morgan');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0970', 'Sue Rinaldi');
