INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0970', 'Sue Rinaldi');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0970', 'chorus', 0, 0, '[\"You make my heart feel glad,\",\"You make my heart feel glad,\",\"Jesus, You bring me joy,\",\"You make my heart feel glad.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0970', 'verse', 1, 1, '[\"Lord, Your love brings healing\",\"and a peace into my heart,\",\"I want to give myself in praise to You.\",\"Though I’ve been through heartache\",\"You have understood my tears.\",\"O Lord, I will give thanks to You.\",\"You make my heart feel glad...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0970', 'verse', 2, 2, '[\"When I look around me,\",\"and I see the life You made,\",\"all creation shouts aloud in praise.\",\"I realize Your greatness,\",\"how majestic is Your name,\",\"O Lord, I love You more each day.\",\"You make my heart feel glad...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0971', 971, 'You have been given', 'MP', 'en', '© 1987 Sovereign Grace Praise / Adm. by Capitol CMG Publishing excl. UK, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'You have been given the name above all names,
and we worship You, yes, we worship You.
You have been given the name above all names,
and we worship You, yes, we worship You.
We are Your people, made for Your glory,
and we worship You, yes, we worship You.
We are Your people, made for Your glory,
and we worship You, yes, we worship You.
You have redeemed us from every nation
and we worship You, yes, we worship You.
You have redeemed us from every nation
and we worship You, yes, we worship You.');
