INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0971', 'Bob Kauflin');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0971', 'verse', 1, 0, '[\"You have been given the name above all names,\",\"and we worship You, yes, we worship You.\",\"You have been given the name above all names,\",\"and we worship You, yes, we worship You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0971', 'verse', 2, 1, '[\"We are Your people, made for Your glory,\",\"and we worship You, yes, we worship You.\",\"We are Your people, made for Your glory,\",\"and we worship You, yes, we worship You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0971', 'verse', 3, 2, '[\"You have redeemed us from every nation\",\"and we worship You, yes, we worship You.\",\"You have redeemed us from every nation\",\"and we worship You, yes, we worship You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0972', 972, 'Yours for ever! God of love', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Yours for ever! God of love,
hear us from Your throne above;
Yours for ever may we be,
here and in eternity.
Yours for ever! Lord of life,
shield us through our earthly strife;
You the life, the truth, the way,
guide us to the realms of day.
Yours for ever! O how blessed
they who find in You their rest!
Saviour, guardian, heavenly friend,
O defend us to the end.
Yours for ever! Shepherd, keep
us Your frail and trembling sheep;
safe alone beneath Your care,
let us all Your goodness share.
Yours for ever! You our guide,
all our wants by You supplied,
all our sins by You forgiven,
lead us, Lord, from earth to Heaven.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0972', 'M F Maude');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0972', 'W D Maclagan');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0972', 'verse', 1, 0, '[\"Yours for ever! God of love,\",\"hear us from Your throne above;\",\"Yours for ever may we be,\",\"here and in eternity.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0972', 'verse', 2, 1, '[\"Yours for ever! Lord of life,\",\"shield us through our earthly strife;\",\"You the life, the truth, the way,\",\"guide us to the realms of day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0972', 'verse', 3, 2, '[\"Yours for ever! O how blessed\",\"they who find in You their rest!\",\"Saviour, guardian, heavenly friend,\",\"O defend us to the end.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0972', 'verse', 4, 3, '[\"Yours for ever! Shepherd, keep\",\"us Your frail and trembling sheep;\",\"safe alone beneath Your care,\",\"let us all Your goodness share.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0972', 'verse', 5, 4, '[\"Yours for ever! You our guide,\",\"all our wants by You supplied,\",\"all our sins by You forgiven,\",\"lead us, Lord, from earth to Heaven.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0973', 973, 'All that I am', 'MP', 'en', '©  1994 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'All that I am I lay before You;
all I possess, Lord, I confess
is nothing without You.
Saviour and King, I now enthrone You;
take my life, my living sacrifice to You.
Lord, be the strength within my weakness;
be the supply in every need,
that I may prove Your promises to me,
faithful and true in word and deed.
All that I am...
Into Your hands I place the future;
the past is nailed to Calvary,
that I may live in resurrection power,
no longer I, but Christ in me.
All that I am...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0973', 'James Wright');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0973', 'James Wright');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0973', 'chorus', 0, 0, '[\"All that I am I lay before You;\",\"all I possess, Lord, I confess\",\"is nothing without You.\",\"Saviour and King, I now enthrone You;\",\"take my life, my living sacrifice to You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0973', 'verse', 1, 1, '[\"Lord, be the strength within my weakness;\",\"be the supply in every need,\",\"that I may prove Your promises to me,\",\"faithful and true in word and deed.\",\"All that I am...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0973', 'verse', 2, 2, '[\"Into Your hands I place the future;\",\"the past is nailed to Calvary,\",\"that I may live in resurrection power,\",\"no longer I, but Christ in me.\",\"All that I am...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0974', 974, 'Awesome in this place', 'MP', 'en', '© 1992 Integrity\'s Hosanna! Music (Adm. by Capitol CMG Publishing excl. UK, adm. by  Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 1, 'As I come into Your presence,
past the gates of praise,
into Your sanctuary
till we’re standing face to face;
I look upon Your countenance,
I see the fullness of Your grace,
and I can only bow down and say:
You are awesome in this place, mighty God.
You are awesome in this place, Abba Father.
You are worthy of all praise,
to You our hands we raise.
You are awesome in this place, mighty God.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0974', 'Dave Billington');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0974', 'Dave Billington');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0974', 'chorus', 0, 0, '[\"As I come into Your presence,\",\"past the gates of praise,\",\"into Your sanctuary\",\"till we’re standing face to face;\",\"I look upon Your countenance,\",\"I see the fullness of Your grace,\",\"and I can only bow down and say:\",\"You are awesome in this place, mighty God.\",\"You are awesome in this place, Abba Father.\",\"You are worthy of all praise,\",\"to You our hands we raise.\",\"You are awesome in this place, mighty God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0975', 975, 'Before the throne of God above', 'MP', 'en', '© 1997 Sovereign Grace Praise (admin by CAPITOL CMG Publishing worldwide excl. the UK which is admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com ) Used by permission', '', 0, 0, 0, 1, 0, 'Before the throne of God above
I have a strong, a perfect plea,
a great High Priest whose name is Love,
who ever lives and pleads for me.
My name is graven on His hands,
my name is written on His heart;
I know that while in heaven He stands
no tongue can bid me thence depart,
no tongue can bid me thence depart.
When Satan tempts me to despair,
and tells me of the guilt within,
upward I look and see Him there
who made an end to all my sin.
Because the sinless Saviour died,
my sinful soul is counted free;
for God the just is satisfied
to look on Him and pardon me,
to look on Him and pardon me.
Behold Him there! The risen lamb,
my perfect, spotless righteousness;
the great unchangeable;
I AM  the King of glory and of grace!
One with Himself I cannot die,
my soul is purchased with His blood;
my life is hid with Christ on high,
with Christ my Saviour and my God,
with Christ my Saviour and my God.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0975', 'Charitie L Bancroft');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0975', 'Vikki Cook');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0975', 'verse', 1, 0, '[\"Before the throne of God above\",\"I have a strong, a perfect plea,\",\"a great High Priest whose name is Love,\",\"who ever lives and pleads for me.\",\"My name is graven on His hands,\",\"my name is written on His heart;\",\"I know that while in heaven He stands\",\"no tongue can bid me thence depart,\",\"no tongue can bid me thence depart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0975', 'verse', 2, 1, '[\"When Satan tempts me to despair,\",\"and tells me of the guilt within,\",\"upward I look and see Him there\",\"who made an end to all my sin.\",\"Because the sinless Saviour died,\",\"my sinful soul is counted free;\",\"for God the just is satisfied\",\"to look on Him and pardon me,\",\"to look on Him and pardon me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0975', 'verse', 3, 2, '[\"Behold Him there! The risen lamb,\",\"my perfect, spotless righteousness;\",\"the great unchangeable;\",\"I AM  the King of glory and of grace!\",\"One with Himself I cannot die,\",\"my soul is purchased with His blood;\",\"my life is hid with Christ on high,\",\"with Christ my Saviour and my God,\",\"with Christ my Saviour and my God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0976', 976, 'Ancient of Days', 'MP', 'en', '©  1992 Integrity\'s Hosanna! Music & Integrity\'s Praise!  Music/Adm. by Capitol CMG Publishing worldwide excl the UK, adm. by Integritymusic.com,  a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 1, 'Blessing and honour, glory and power
be unto the Ancient of Days;');
