INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0985', 'Carol Owen');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0985', 'verse', 1, 0, '[\"He is the mighty God,\",\"He is the risen King,\",\"He is the Lord of lords.\",\"He is the first and last,\",\"He is holy, He is true,\",\"He is the Lord of lords.\",\"And we know He’s coming back again\",\"in power and glory.\",\"He is coming back again\",\"to claim His people.\",\"He is coming back again\",\"to bring His children home with Him,\",\"home with Him.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0985', 'verse', 2, 1, '[\"He is the one who gave\",\"His life for all the world,\",\"He is the Lord of lords,\",\"who rose up from the grave,\",\"defeated death and hell;\",\"He is the Lord of lords.\",\"And we know...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0985', 'verse', 3, 2, '[\"He’s coming in the clouds\",\"and every eye shall see\",\"He is the Lord of lords;\",\"then every knee shall bow\",\"and every tongue proclaim\",\"He is the Lord of lords.\",\"And we know...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0986', 986, 'He’s given me a garment of praise', 'MP', 'en', 'Copyright 1994 Restoration Music. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'He’s given me a garment of praise
instead of a spirit of despair,
He’s given me a garment of praise
instead of a spirit of despair.
(repeat)
A crown of beauty instead of ashes,
the oil of gladness instead of mourning,
my soul rejoices as I delight myself in God.
He’s given me a garment of praise
instead of a spirit of despair.
He’s given me...');
