INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0995', 995, 'Once again', 'MP', 'en', '©  1995 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by PermissionCopyright ©  1995 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Jesus Christ, I think upon Your sacrifice;
You became nothing, poured out to death.
Many times I’ve wondered at Your gift of life,
and I’m in that place once again,
I’m in that place once again.
And once again I look upon
the cross where You died,
I’m humbled by Your mercy
and I’m broken inside.
Once again I thank You,
once again I pour out my life.
Now You are exalted to the highest place,
King of the heavens, where one day I’ll bow,
but for now, I marvel at this saving grace
and I’m full of praise once again,
I’m full of praise once again.
And once again...
Thank You for the cross,
thank You for the cross,
thank You for the cross, my friend.
(repeat)
And once again...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0995', 'Matt Redman');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0995', 'Matt Redman');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0995', 'verse', 1, 0, '[\"Jesus Christ, I think upon Your sacrifice;\",\"You became nothing, poured out to death.\",\"Many times I’ve wondered at Your gift of life,\",\"and I’m in that place once again,\",\"I’m in that place once again.\",\"And once again I look upon\",\"the cross where You died,\",\"I’m humbled by Your mercy\",\"and I’m broken inside.\",\"Once again I thank You,\",\"once again I pour out my life.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0995', 'verse', 2, 1, '[\"Now You are exalted to the highest place,\",\"King of the heavens, where one day I’ll bow,\",\"but for now, I marvel at this saving grace\",\"and I’m full of praise once again,\",\"I’m full of praise once again.\",\"And once again...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0995', 'chorus', 0, 2, '[\"Thank You for the cross,\",\"thank You for the cross,\",\"thank You for the cross, my friend.\",\"(repeat)\",\"And once again...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0996', 996, 'This kingdom', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus, God’s righteousness revealed,
the Son of Man, the Son of God,
His kingdom comes.
Jesus, redemption’s sacrifice,
now glorified, now justified,
His kingdom comes.
And His kingdom will know no end,
and its glory shall know no bounds,
for the majesty and power
of this kingdom’s King has come,
and this kingdom’s reign,
and this kingdom’s rule,
and this kingdom’s power and authority,
Jesus, God’s righteousness revealed.
Jesus, the expression of God’s love,
the grace of God, the word of God,
revealed to us.
Jesus, God’s holiness displayed,
now glorifed, now justified,
His kingdom comes.
And His kingdom will know no end...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0996', 'Geoff Bullock');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0996', 'Geoff Bullock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0996', 'verse', 1, 0, '[\"Jesus, God’s righteousness revealed,\",\"the Son of Man, the Son of God,\",\"His kingdom comes.\",\"Jesus, redemption’s sacrifice,\",\"now glorified, now justified,\",\"His kingdom comes.\",\"And His kingdom will know no end,\",\"and its glory shall know no bounds,\",\"for the majesty and power\",\"of this kingdom’s King has come,\",\"and this kingdom’s reign,\",\"and this kingdom’s rule,\",\"and this kingdom’s power and authority,\",\"Jesus, God’s righteousness revealed.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0996', 'verse', 2, 1, '[\"Jesus, the expression of God’s love,\",\"the grace of God, the word of God,\",\"revealed to us.\",\"Jesus, God’s holiness displayed,\",\"now glorifed, now justified,\",\"His kingdom comes.\",\"And His kingdom will know no end...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0997', 997, 'Jesus, lover of my soul', 'MP', 'en', '©  1995 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 1, 'Jesus, lover of my soul,
all-consuming fire is in Your gaze.
Jesus, I want You to know
I will follow You all my days.
For no-one else in history is like You,
and history itself belongs to You.
Alpha and Omega, You have loved me,
and I will share eternity with You.
It’s all about You, Jesus,
and all this is for You,
for Your glory and Your fame.
It’s not about me,
as if You should do things my way;
You alone are God,
and I surrender to Your ways.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0997', 'Paul Oakley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0997', 'Paul Oakley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0997', 'chorus', 0, 0, '[\"Jesus, lover of my soul,\",\"all-consuming fire is in Your gaze.\",\"Jesus, I want You to know\",\"I will follow You all my days.\",\"For no-one else in history is like You,\",\"and history itself belongs to You.\",\"Alpha and Omega, You have loved me,\",\"and I will share eternity with You.\",\"It’s all about You, Jesus,\",\"and all this is for You,\",\"for Your glory and Your fame.\",\"It’s not about me,\",\"as if You should do things my way;\",\"You alone are God,\",\"and I surrender to Your ways.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0998', 998, 'Jesus, what a beautiful name', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'Jesus, what a beautiful name.
Son of God, Son of Man,
Lamb that was slain.
Joy and peace, strength and hope,
grace that blows all fear away.
Jesus, what a beautiful name.
Jesus, what a beautiful name.
Truth revealed, my future sealed,
healed my pain.
Love and freedom, life and warmth,
grace that blows all fear away.
Jesus, what a beautiful name.
Jesus, what a beautiful name.
Rescued my soul, my stronghold,
lifts me from shame.
Forgiveness, security, power and love,
grace that blows all fear away.
Jesus, what a beautiful name.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-0998', 'Tanya Riches');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0998', 'Tanya Riches');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0998', 'verse', 1, 0, '[\"Jesus, what a beautiful name.\",\"Son of God, Son of Man,\",\"Lamb that was slain.\",\"Joy and peace, strength and hope,\",\"grace that blows all fear away.\",\"Jesus, what a beautiful name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0998', 'verse', 2, 1, '[\"Jesus, what a beautiful name.\",\"Truth revealed, my future sealed,\",\"healed my pain.\",\"Love and freedom, life and warmth,\",\"grace that blows all fear away.\",\"Jesus, what a beautiful name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0998', 'verse', 3, 2, '[\"Jesus, what a beautiful name.\",\"Rescued my soul, my stronghold,\",\"lifts me from shame.\",\"Forgiveness, security, power and love,\",\"grace that blows all fear away.\",\"Jesus, what a beautiful name.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-0999', 999, 'Firm foundation', 'MP', 'en', '© 1994 Integrity’s Hosanna! Music/Integrity’s Praise! Music (Adm. by Capitol CMG Publishing excl. UK, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Jesus, You’re my firm foundation,
I know I can stand secure;
Jesus, You’re my firm foundation,
I put my hope in Your holy word,
I put my hope in Your holy word.
I have a living hope, (I have a living hope,)
I have a future; (I have a future;)
God has a plan for me, (God has a plan for me,)
of this I’m sure,
of this I’m sure.
Jesus, You’re my firm foundation...
Your word is faithful, (Your word is faithful,)
mighty in power, (mighty in power,)
God will deliver me, (God will deliver me,)
of this I’m sure,
of this I’m sure.
Jesus, You’re my firm foundation...');
