INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-0999', 'Jamie Harvill');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0999', 'chorus', 0, 0, '[\"Jesus, You’re my firm foundation,\",\"I know I can stand secure;\",\"Jesus, You’re my firm foundation,\",\"I put my hope in Your holy word,\",\"I put my hope in Your holy word.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0999', 'verse', 1, 1, '[\"I have a living hope, (I have a living hope,)\",\"I have a future; (I have a future;)\",\"God has a plan for me, (God has a plan for me,)\",\"of this I’m sure,\",\"of this I’m sure.\",\"Jesus, You’re my firm foundation...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-0999', 'verse', 2, 2, '[\"Your word is faithful, (Your word is faithful,)\",\"mighty in power, (mighty in power,)\",\"God will deliver me, (God will deliver me,)\",\"of this I’m sure,\",\"of this I’m sure.\",\"Jesus, You’re my firm foundation...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1000', 1000, 'King of kings, majesty', 'MP', 'en', 'Copyright 1996 Sovereign Lifestyle Music Ltd. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 1, 1, 'King of kings, majesty,
God of heaven living in me,
gentle Saviour, closest friend,
strong deliverer, beginning and end,
all within me falls at Your throne.
Your majesty, I can but bow.
I lay my all before You now.
In royal robes I don’t deserve
I live to serve Your majesty.
Earth and heaven worship You,
love eternal, faithful and true,
who bought the nations, ransomed souls,
brought this sinner near to Your throne;
all within me cries out in praise.
Your majesty, I can but bow.
I lay my all before You now.
In royal robes I don’t deserve
I live to serve Your majesty,
I live to serve Your majesty.');
