INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1002', 'verse', 2, 1, '[\"Nothing has silenced this gospel of Christ;\",\"it echoes down through the ages.\",\"Blood of the martyrs has made Your church strong;\",\"in this dark world the light still shines.\",\"For You we live, and for You we may die;\",\"through us may Jesus be seen.\",\"For You alone we will offer our lives;\",\"in this dark world our light will shine.\"]');
