INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1074', 1074, 'It is good to praise the Lord', 'MP', 'en', '© 1985 Integrity\'s Hosanna! Music /adm worldwide by Capitol CMG Publishing excl UK admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'It is good to praise the Lord
and make music to Your name,
O God most high;
to proclaim Your love and faithfulness
all the day and through the night.
Lai lai lai
lai lai lai lai lai,
lai lai lai lai,
lai lai lai lai lai lai lai,
lai lai lai lai lai lai lai lai lai,
lai lai lai lai lai lai lai.
May I dwell in Your courts, O Lord,
then to flourish like the trees of Lebanon,
planted in the house of Adonai,
there to live for ever more.
Lai lai lai
lai lai lai lai lai,
lai lai lai lai,
lai lai lai lai lai lai lai,
lai lai lai lai lai lai lai lai lai,
