INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1076', 1076, 'Be the centre', 'MP', 'en', '1999 Vineyard Songs UK (Adm. by Song Solutions Copycare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Jesus, be the centre,
be my source, be my light, Jesus.
Jesus, be the centre,
be my hope, be my song, Jesus.
Be the fire in my heart,
be the wind in these sails,
be the reason that I live,
Jesus, Jesus.
Jesus, be my vision,
be my path, be my guide, Jesus.
Be the fire in my heart...');
