INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1077', 1077, 'Jesus, closer than a friend', 'MP', 'en', 'Resource Christian Music Pty/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Jesus, closer than a friend,
Jesus, with me to the end,
Jesus, taking all my pain,
wiping all my tears away,
turning them to healing rain.
For nothing can separate us');
