INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1078', 'verse', 2, 1, '[\"Jesus is Lord – whose word sustains the stars and planets,\",\"yet in His wisdom laid aside His crown.\",\"Jesus the man, who washed our feet, who bore our suffering,\",\"became a curse to bring salvation’s plan.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1078', 'verse', 3, 2, '[\"Jesus is Lord – the tomb is gloriously empty!\",\"Not even death could crush this King of love!\",\"The price is paid, the chains are loosed, and we’re forgiven,\",\"and we can run into the arms of God.\"]');
