INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1079', 1079, 'Jesus, hope of the nations', 'MP', 'en', '© 2002 Integrity\'s Hosanna! Music /adm worldwide by Capitol CMG Publishing excl UK admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Jesus, hope of the nations;
Jesus, comfort for all who mourn,
You are the source
of heaven’s hope on earth.
Jesus, light in the darkness,
Jesus, truth in each circumstance,
You are the source
of heaven’s light on earth.
In history, You lived and died,
You broke the chains, You rose to life.
You are the Hope, living in us,
You are the Rock, in whom we trust.
You are the Light,
shining for all the world to see.
You rose from the dead, conquering fear,
our Prince of Peace, drawing us near.
Jesus, our Hope,
living for all who will receive,
Lord, we believe.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1079', 'Brian Doerksen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1079', 'Brian Doerksen');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1079', 'verse', 1, 0, '[\"Jesus, hope of the nations;\",\"Jesus, comfort for all who mourn,\",\"You are the source\",\"of heaven’s hope on earth.\",\"Jesus, light in the darkness,\",\"Jesus, truth in each circumstance,\",\"You are the source\",\"of heaven’s light on earth.\",\"In history, You lived and died,\",\"You broke the chains, You rose to life.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1079', 'chorus', 0, 1, '[\"You are the Hope, living in us,\",\"You are the Rock, in whom we trust.\",\"You are the Light,\",\"shining for all the world to see.\",\"You rose from the dead, conquering fear,\",\"our Prince of Peace, drawing us near.\",\"Jesus, our Hope,\",\"living for all who will receive,\",\"Lord, we believe.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1080', 1080, 'Jesus, only You', 'MP', 'en', '1997 Greg Leavers', '', 0, 0, 0, 1, 1, 'Jesus, only You,
no one else will do.
Only You can satisfy
my heart’s desire and deepest cry
for more of You, Jesus,
for more of You.
Jesus, only You...
Whatever way You choose,
Lord, change me.
Whatever way You choose,
Jesus, fill me.
I want to live my life for You,
do in me all You need to do.
Whatever way You choose,
Lord, let it be more of You.
Jesus, only You...
For less of me, Jesus,
and more of You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1080', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1080', 'Greg Leavers');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1080', 'chorus', 0, 0, '[\"Jesus, only You,\",\"no one else will do.\",\"Only You can satisfy\",\"my heart’s desire and deepest cry\",\"for more of You, Jesus,\",\"for more of You.\",\"Jesus, only You...\",\"Whatever way You choose,\",\"Lord, change me.\",\"Whatever way You choose,\",\"Jesus, fill me.\",\"I want to live my life for You,\",\"do in me all You need to do.\",\"Whatever way You choose,\",\"Lord, let it be more of You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1080', 'chorus', 0, 1, '[\"Jesus, only You...\",\"For less of me, Jesus,\",\"and more of You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1081', 1081, 'Jesus, Your name', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Jesus, Your name is power,
Jesus, Your name is might.
Jesus, Your name will break every stronghold,
Jesus, Your name is life.
Jesus, Your name is healing,
Jesus, Your name gives sight.
Jesus, Your name will free every captive,
Jesus, Your name is life.
Jesus, Your name is holy,
Jesus, Your name brings light.
Jesus, Your name above every other,
Jesus, Your name is life.
Jesus, Your name is power,
Jesus, Your name is might.
Jesus, Your name will break every stronghold,
Jesus, Your name is life.');
