INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1082', 'verse', 1, 1, '[\"Your ways of love have won my heart,\",\"and brought me joy unending.\",\"Your saving power at work in me,\",\"bringing peace and the hope of glory.\",\"King of the ages...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1082', 'verse', 2, 2, '[\"Your arms of love are reaching out\",\"to every soul that seeks You;\",\"Your light will shine in all the earth,\",\"bringing grace and a great salvation.\",\"King of the ages...\"]');
