INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1083', 'verse', 2, 1, '[\"Feeling Your touch\",\"gives me such peace, Lord.\",\"I love You so much,\",\"I know You’ll lead me.\",\"Wherever I go I’ll be under Your wing,\",\"For I am a child of the King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1083', 'chorus', 0, 2, '[\"You will finish the work You’ve begun in me,\",\"I’m adopted, a son in Your family!\",\"You’ve drawn me with kindness and love\",\"into this holy place.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1083', 'verse', 3, 3, '[\"What can I say?\",\"Your lavish mercy\",\"turned night into day –\",\"my guilt has gone now.\",\"For ever I’ll stand in Your presence and sing,\",\"For I am a child of the King.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1084', 1084, 'Let the redeemed', 'MP', 'en', '2004 Greg Leavers', '', 0, 0, 0, 1, 1, 'Let the redeemed, the redeemed of the Lord
enter His gates with thanksgiving in their hearts;
let the redeemed, the redeemed of the Lord
come into His courts with a shout of praise!
Let His house be filled with the sound of singing;
let His house overflow with praise.
Let His house be filled with songs of freedom,
celebrate the Lord’s amazing grace!
Let the redeemed...
Let His children celebrate with dancing;
let His children clap their hands with joy.
Let His children celebrate salvation,
for His love and mercy never fail.
Let the redeemed...
Praise the Lord, the Rock of our salvation!
Praise the Lord, for He alone is God!
Praise the Lord, let all creation praise Him!
Let everything that has breath praise the Lord.
Let the redeemed...
Lord, You sit enthroned as King for ever,
ruler of the heavens and the earth.
In Your house Your children all cry, ‘Glory!’
Glory – for the Lord Almighty reigns.
Let the redeemed...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1084', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1084', 'Greg Leavers');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1084', 'chorus', 0, 0, '[\"Let the redeemed, the redeemed of the Lord\",\"enter His gates with thanksgiving in their hearts;\",\"let the redeemed, the redeemed of the Lord\",\"come into His courts with a shout of praise!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1084', 'verse', 1, 1, '[\"Let His house be filled with the sound of singing;\",\"let His house overflow with praise.\",\"Let His house be filled with songs of freedom,\",\"celebrate the Lord’s amazing grace!\",\"Let the redeemed...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1084', 'verse', 2, 2, '[\"Let His children celebrate with dancing;\",\"let His children clap their hands with joy.\",\"Let His children celebrate salvation,\",\"for His love and mercy never fail.\",\"Let the redeemed...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1084', 'verse', 3, 3, '[\"Praise the Lord, the Rock of our salvation!\",\"Praise the Lord, for He alone is God!\",\"Praise the Lord, let all creation praise Him!\",\"Let everything that has breath praise the Lord.\",\"Let the redeemed...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1084', 'verse', 4, 4, '[\"Lord, You sit enthroned as King for ever,\",\"ruler of the heavens and the earth.\",\"In Your house Your children all cry, ‘Glory!’\",\"Glory – for the Lord Almighty reigns.\",\"Let the redeemed...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1085', 1085, 'What the Lord has done in me', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'Let the weak say, ‘I am strong’,
let the poor say, ‘I am rich’,
let the blind say, ‘I can see,
it’s what the Lord has done in me’.
Let the weak say...
Hosanna, hosanna
to the Lamb that was slain!
Hosanna, hosanna,
Jesus died and rose again.
Hosanna...
Into the river I will wade;
there my sins are washed away.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1085', 'Reuben Morgan');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1085', 'Reuben Morgan');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1085', 'Chris Mitchell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1085', 'verse', 1, 0, '[\"Let the weak say, ‘I am strong’,\",\"let the poor say, ‘I am rich’,\",\"let the blind say, ‘I can see,\",\"it’s what the Lord has done in me’.\",\"Let the weak say...\",\"Hosanna, hosanna\",\"to the Lamb that was slain!\",\"Hosanna, hosanna,\",\"Jesus died and rose again.\",\"Hosanna...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1085', 'verse', 2, 1, '[\"Into the river I will wade;\",\"there my sins are washed away.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1086', 1086, 'Light of the World', 'MP', 'en', '©  2000 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook, songs@integritymusic.com Used by Permission.', '', 0, 0, 0, 1, 0, 'Light of the world, You stepped down into darkness,
opened my eyes, let me see
beauty that made this heart adore You,
hope of a life spent with You.
So here I am to worship,
here I am to bow down,
here I am to say that You’re my God:
You’re altogether lovely,
altogether worthy,
altogether wonderful to me.
King of all days, O so highly exalted,
glorious in heaven above,
humbly You came to the earth You created,
all for love’s sake became poor.
So here I am to worship...
So here I am to worship...
And I’ll never know how much it cost
to see my sin upon that cross.
And I’ll never know how much it cost
to see my sin upon that cross.
So here I am to worship...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1086', 'Tim Hughes');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1086', 'Tim Hughes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1086', 'verse', 1, 0, '[\"Light of the world, You stepped down into darkness,\",\"opened my eyes, let me see\",\"beauty that made this heart adore You,\",\"hope of a life spent with You.\",\"So here I am to worship,\",\"here I am to bow down,\",\"here I am to say that You’re my God:\",\"You’re altogether lovely,\",\"altogether worthy,\",\"altogether wonderful to me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1086', 'verse', 2, 1, '[\"King of all days, O so highly exalted,\",\"glorious in heaven above,\",\"humbly You came to the earth You created,\",\"all for love’s sake became poor.\",\"So here I am to worship...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1086', 'chorus', 0, 2, '[\"So here I am to worship...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1086', 'chorus', 0, 3, '[\"And I’ll never know how much it cost\",\"to see my sin upon that cross.\",\"And I’ll never know how much it cost\",\"to see my sin upon that cross.\",\"So here I am to worship...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1087', 1087, 'What a faithful God', 'MP', 'en', '©  1989 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Lord, I come before Your throne of grace,
I find rest in Your presence, and fullness of joy.
In worship and wonder I behold Your face,
singing ‘What a faithful God have I’.
What a faithful God have I,
what a faithful God.
What a faithful God have I,
faithful in every way.
Lord of mercy, You have heard my cry,
through the storm You’re the beacon,
my song in the night.
In the shelter of Your wings hear my heart’s reply,
singing ‘What a faithful God have I’.
What a faithful God have I...
Lord, all sovereign, granting peace from heaven,
let me comfort those who suffer
with the comfort You have given.
I will tell of Your great love for as long as I live,
singing ‘What a faithful God have I’.
What a faithful God have I...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1087', 'Robert Critchley');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1087', 'Dawn Critchley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1087', 'Robert Critchley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1087', 'Dawn Critchley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1087', 'verse', 1, 0, '[\"Lord, I come before Your throne of grace,\",\"I find rest in Your presence, and fullness of joy.\",\"In worship and wonder I behold Your face,\",\"singing ‘What a faithful God have I’.\",\"What a faithful God have I,\",\"what a faithful God.\",\"What a faithful God have I,\",\"faithful in every way.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1087', 'verse', 2, 1, '[\"Lord of mercy, You have heard my cry,\",\"through the storm You’re the beacon,\",\"my song in the night.\",\"In the shelter of Your wings hear my heart’s reply,\",\"singing ‘What a faithful God have I’.\",\"What a faithful God have I...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1087', 'verse', 3, 2, '[\"Lord, all sovereign, granting peace from heaven,\",\"let me comfort those who suffer\",\"with the comfort You have given.\",\"I will tell of Your great love for as long as I live,\",\"singing ‘What a faithful God have I’.\",\"What a faithful God have I...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1088', 1088, 'Lord, lead us into battle', 'MP', 'en', 'Shadow Spring Music/MSI Music Adm/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Lord, lead us into battle,
let us glorify Your name.
Holy Spirit, You have set our hearts aflame,
we will never be the same.
Lord, fill us with the vision
to see the Church as one.
Break our hearts, release us from our pride;
Father, glorify Your bride.
Oh, how I love You, Jesus,
what a joy to sing Your praise.
I have placed my hope in You and You alone,
I’ve found healing in Your name.
Lord, teach us how to worship,
may it never be in vain.
Draw us into the throne room of the King;
in Your power rule and reign.
Oh, how I love You...
Oh, how I love You...
I have placed my hope in You and You alone,
I’ve found healing in Your name.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1088', 'Carl Tuttle');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1088', 'Carl Tuttle');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1088', 'verse', 1, 0, '[\"Lord, lead us into battle,\",\"let us glorify Your name.\",\"Holy Spirit, You have set our hearts aflame,\",\"we will never be the same.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1088', 'verse', 2, 1, '[\"Lord, fill us with the vision\",\"to see the Church as one.\",\"Break our hearts, release us from our pride;\",\"Father, glorify Your bride.\",\"Oh, how I love You, Jesus,\",\"what a joy to sing Your praise.\",\"I have placed my hope in You and You alone,\",\"I’ve found healing in Your name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1088', 'verse', 3, 2, '[\"Lord, teach us how to worship,\",\"may it never be in vain.\",\"Draw us into the throne room of the King;\",\"in Your power rule and reign.\",\"Oh, how I love You...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1088', 'chorus', 0, 3, '[\"Oh, how I love You...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1088', 'chorus', 0, 4, '[\"I have placed my hope in You and You alone,\",\"I’ve found healing in Your name.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1089', 1089, 'God of wonders', 'MP', 'en', '2000 Storm Boy Music &  Meaux Mercy/EMICMP/Small Stone Media BV Holland & New Spring Publishing/Imagem/Small Stone Media BV Holland (Admin by Song Solutions www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Lord of all creation,
of water, earth and sky,
the heavens are Your tabernacle;
glory to the Lord on high.
God of wonders beyond our galaxy,
You are holy, holy;
the universe declares Your majesty.
You are holy, holy;
Lord of heaven and earth,
Lord of heaven and earth.
Early in the morning
I will celebrate the light,
and as I stumble in the darkness
I will call Your name by night.
God of wonders...
Hallelujah to the Lord of heaven and earth! (3 times)');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1089', 'Marc Byrd');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1089', 'Steve Hindalong');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1089', 'Marc Byrd');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1089', 'Steve Hindalong');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1089', 'verse', 1, 0, '[\"Lord of all creation,\",\"of water, earth and sky,\",\"the heavens are Your tabernacle;\",\"glory to the Lord on high.\",\"God of wonders beyond our galaxy,\",\"You are holy, holy;\",\"the universe declares Your majesty.\",\"You are holy, holy;\",\"Lord of heaven and earth,\",\"Lord of heaven and earth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1089', 'verse', 2, 1, '[\"Early in the morning\",\"I will celebrate the light,\",\"and as I stumble in the darkness\",\"I will call Your name by night.\",\"God of wonders...\",\"Hallelujah to the Lord of heaven and earth! (3 times)\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1090', 1090, 'Lord of the heavens', 'MP', 'en', '1999 Greg Leavers', '', 0, 0, 0, 1, 1, 'Lord of the heavens,
Lord of the earth,
You are the Lord of the universe.
Lord of creation,
Lord over all,
before Your throne everyone must fall.
There is none like You,
there is none like You.
Come, let us bow down in worship,
let’s kneel before our Maker,
for He is our God.
He is our God.
Lord of the heavens...
There is none like You,
there is none like You,
there is none like You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1090', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1090', 'Greg Leavers');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1090', 'verse', 1, 0, '[\"Lord of the heavens,\",\"Lord of the earth,\",\"You are the Lord of the universe.\",\"Lord of creation,\",\"Lord over all,\",\"before Your throne everyone must fall.\",\"There is none like You,\",\"there is none like You.\",\"Come, let us bow down in worship,\",\"let’s kneel before our Maker,\",\"for He is our God.\",\"He is our God.\",\"Lord of the heavens...\",\"There is none like You,\",\"there is none like You,\",\"there is none like You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1091', 1091, 'Lord, you are so precious to me', 'MP', 'en', '©  1986 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Lord, You are so precious to me,
Lord, You are so precious to me
and I love You, yes I love You
because You first loved me.
Lord, You are so gracious to me...
Lord, You are a father to me...
Lord, You are so faithful to me...
Lord, You are so loving to me...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1091', 'Graham Kendrick');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1091', 'Graham Kendrick');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1091', 'verse', 1, 0, '[\"Lord, You are so precious to me,\",\"Lord, You are so precious to me\",\"and I love You, yes I love You\",\"because You first loved me.\",\"Lord, You are so gracious to me...\",\"Lord, You are a father to me...\",\"Lord, You are so faithful to me...\",\"Lord, You are so loving to me...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1092', 1092, 'Dwelling places', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'Lovely are Your dwelling places;
thirsty, I come after You.
Jesus, my joy, my reward:
Your love’s restoring my soul.
Now I’m Yours and You are mine,
and from my heart a song will rise:
I love You, I love You, I love You.
I love You, I love You, I love You.
I love You, I love You, I love You
and my heart will follow wholly after You.
Jesus, there is none beside You.
Righteous ruler of the earth,
nations will come and bow down,
name over all names.
I sing You praises
and all that I can say to you is
I love You, I love You, I love You.
I love You, I love You, I love You.
I love You, I love You, I love You
and my heart will follow wholly.
I love You...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1092', 'Miriam Webster');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1092', 'Miriam Webster');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1092', 'verse', 1, 0, '[\"Lovely are Your dwelling places;\",\"thirsty, I come after You.\",\"Jesus, my joy, my reward:\",\"Your love’s restoring my soul.\",\"Now I’m Yours and You are mine,\",\"and from my heart a song will rise:\",\"I love You, I love You, I love You.\",\"I love You, I love You, I love You.\",\"I love You, I love You, I love You\",\"and my heart will follow wholly after You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1092', 'verse', 2, 1, '[\"Jesus, there is none beside You.\",\"Righteous ruler of the earth,\",\"nations will come and bow down,\",\"name over all names.\",\"I sing You praises\",\"and all that I can say to you is\",\"I love You, I love You, I love You.\",\"I love You, I love You, I love You.\",\"I love You, I love You, I love You\",\"and my heart will follow wholly.\",\"I love You...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1093', 1093, 'May the blessing of the Lord our God', 'MP', 'en', '© 1986 Authentic Publishing / Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'May the blessing of the Lord our God
rest upon you day by day;
may He keep and guide you
every step of the way;
and may you know His peace
deep within your heart,
and may His love control
all you do and say.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1093', 'Marilyn Baker');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1093', 'Marilyn Baker');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1093', 'verse', 1, 0, '[\"May the blessing of the Lord our God\",\"rest upon you day by day;\",\"may He keep and guide you\",\"every step of the way;\",\"and may you know His peace\",\"deep within your heart,\",\"and may His love control\",\"all you do and say.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1094', 1094, 'Shout to the north', 'MP', 'en', '©1995 Curious? Music/Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 1, 0, 'Men of faith, rise up and sing
of the great and glorious King;
you are strong when you feel weak,
in your brokenness complete.
Shout to the north and the south,
sing to the east and the west:
Jesus is Saviour to all,
Lord of heaven and earth.
Rise up women of the truth,
stand and sing to broken hearts,
who can know the healing power
of our glorious King of love.
Shout to the north...
We’ve been through fire,
we’ve been through rain;
we’ve been refined
by the power of His name.
We’ve fallen deeper in love with You,
You’ve burned the truth on our lips.
Shout to the north...
Rise up church with broken wings;
fill this place with songs again,
of our God who reigns on high:
by His grace again we’ll fly.
Shout to the north...
Lord of heaven and earth. (3 times)');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1094', 'Martin J Smith');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1094', 'Martin J Smith');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1094', 'verse', 1, 0, '[\"Men of faith, rise up and sing\",\"of the great and glorious King;\",\"you are strong when you feel weak,\",\"in your brokenness complete.\",\"Shout to the north and the south,\",\"sing to the east and the west:\",\"Jesus is Saviour to all,\",\"Lord of heaven and earth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1094', 'verse', 2, 1, '[\"Rise up women of the truth,\",\"stand and sing to broken hearts,\",\"who can know the healing power\",\"of our glorious King of love.\",\"Shout to the north...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1094', 'chorus', 0, 2, '[\"We’ve been through fire,\",\"we’ve been through rain;\",\"we’ve been refined\",\"by the power of His name.\",\"We’ve fallen deeper in love with You,\",\"You’ve burned the truth on our lips.\",\"Shout to the north...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1094', 'verse', 3, 3, '[\"Rise up church with broken wings;\",\"fill this place with songs again,\",\"of our God who reigns on high:\",\"by His grace again we’ll fly.\",\"Shout to the north...\",\"Lord of heaven and earth. (3 times)\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1095', 1095, 'O my soul, arise and bless your Maker', 'MP', 'en', '(c) 1999 Thankyou Music/Adm. CAPITOL CMG Publishing worldwide excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'O my soul, arise and bless your Maker,
for He is your Master and your friend.
Slow to wrath but rich in tender mercy;
worship the Saviour Jesus.
King of grace, His love is overwhelming;
Bread of life, He’s all I’ll ever need,
for His blood has purchased me for ever:
bought at the cross of Jesus.
And I will sing for all my days
of heaven’s love come down.
Each breath I take will speak His praise
until He calls me home.
When I wake, I know that He is with me;
when I’m weak, I know that He is strong.
Though I fall, His arm is there to lean on;
safe on the rock of Jesus.
Stir in me the songs that You are singing;
fill my gaze with things as yet unseen.
Give me faith to move in works of power,
making me more like Jesus.
And I will sing for all my days...
Then one day I’ll see him as he sees me,
face to face, the Lover and the loved;
no more words, the longing will be over:
there with my precious Jesus.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1095', 'Stuart Townend');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1095', 'Stuart Townend');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1095', 'verse', 1, 0, '[\"O my soul, arise and bless your Maker,\",\"for He is your Master and your friend.\",\"Slow to wrath but rich in tender mercy;\",\"worship the Saviour Jesus.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1095', 'verse', 2, 1, '[\"King of grace, His love is overwhelming;\",\"Bread of life, He’s all I’ll ever need,\",\"for His blood has purchased me for ever:\",\"bought at the cross of Jesus.\",\"And I will sing for all my days\",\"of heaven’s love come down.\",\"Each breath I take will speak His praise\",\"until He calls me home.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1095', 'verse', 3, 2, '[\"When I wake, I know that He is with me;\",\"when I’m weak, I know that He is strong.\",\"Though I fall, His arm is there to lean on;\",\"safe on the rock of Jesus.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1095', 'verse', 4, 3, '[\"Stir in me the songs that You are singing;\",\"fill my gaze with things as yet unseen.\",\"Give me faith to move in works of power,\",\"making me more like Jesus.\",\"And I will sing for all my days...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1095', 'verse', 5, 4, '[\"Then one day I’ll see him as he sees me,\",\"face to face, the Lover and the loved;\",\"no more words, the longing will be over:\",\"there with my precious Jesus.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1096', 1096, 'O sacred King', 'MP', 'en', '©  1999 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'O sacred King, O holy King,
how can I honour You rightly,
honour that’s right for Your name?
O sacred friend, O holy friend,
I don’t take what You give lightly,
friendship instead of disgrace.
For it’s the mystery of the universe,
You’re the God of holiness,
yet You welcome souls like me.
And with the blessing of Your Father’s heart
You discipline the ones You love,
there’s kindness in Your majesty.
Jesus, those who recognize Your power
know just how wonderful You are,
that You draw near.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1096', 'Matt Redman');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1096', 'Matt Redman');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1096', 'verse', 1, 0, '[\"O sacred King, O holy King,\",\"how can I honour You rightly,\",\"honour that’s right for Your name?\",\"O sacred friend, O holy friend,\",\"I don’t take what You give lightly,\",\"friendship instead of disgrace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1096', 'chorus', 0, 1, '[\"For it’s the mystery of the universe,\",\"You’re the God of holiness,\",\"yet You welcome souls like me.\",\"And with the blessing of Your Father’s heart\",\"You discipline the ones You love,\",\"there’s kindness in Your majesty.\",\"Jesus, those who recognize Your power\",\"know just how wonderful You are,\",\"that You draw near.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1097', 1097, 'How good it is', 'MP', 'en', '©  2000 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'O God of love,
I come to You again,
knowing I’ll find mercy.
I can’t explain
all the things I see,
but I’ll trust in You.
In every moment You are there,
watching over, You hear my prayer.
You go before me, You’re behind me,
nothing’s hidden from You.
How good it is to be loved by You,
how good it is.
How good it is to be loved by You,
how good it is.
O God of strength,
Your hand is on my life,
bringing peace to me.
You know my frame,
You know how I am made,
You planned all my days.
Hand of mercy, hand of love,
giving power to overcome.
If all beneath me falls away,
I know that You are God.
How good it is...
Who can stand against us?
In my weakness You are strong.
Your word is everlasting,
I will praise You, faithful One.
How good it is...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1097', 'Louise Fellingham');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1097', 'Nathan Fellingham');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1097', 'Louise Fellingham');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1097', 'Nathan Fellingham');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1097', 'verse', 1, 0, '[\"O God of love,\",\"I come to You again,\",\"knowing I’ll find mercy.\",\"I can’t explain\",\"all the things I see,\",\"but I’ll trust in You.\",\"In every moment You are there,\",\"watching over, You hear my prayer.\",\"You go before me, You’re behind me,\",\"nothing’s hidden from You.\",\"How good it is to be loved by You,\",\"how good it is.\",\"How good it is to be loved by You,\",\"how good it is.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1097', 'verse', 2, 1, '[\"O God of strength,\",\"Your hand is on my life,\",\"bringing peace to me.\",\"You know my frame,\",\"You know how I am made,\",\"You planned all my days.\",\"Hand of mercy, hand of love,\",\"giving power to overcome.\",\"If all beneath me falls away,\",\"I know that You are God.\",\"How good it is...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1097', 'chorus', 0, 2, '[\"Who can stand against us?\",\"In my weakness You are strong.\",\"Your word is everlasting,\",\"I will praise You, faithful One.\",\"How good it is...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1098', 1098, 'Humble King', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Oh, kneel me down again, here at Your feet;
show me how much You love humility.
O Spirit, be the star that leads me to
the humble heart of love I see in You.
You are the God of the broken,
the friend of the weak;
You wash the feet of the weary,
embrace the ones in need.
I want to be like You, Jesus,
to have this heart in me.
You are the God of the humble,
You are the humble King.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1098', 'Brenton Brown');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1098', 'Brenton Brown');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1098', 'Chris Mitchell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1098', 'verse', 1, 0, '[\"Oh, kneel me down again, here at Your feet;\",\"show me how much You love humility.\",\"O Spirit, be the star that leads me to\",\"the humble heart of love I see in You.\",\"You are the God of the broken,\",\"the friend of the weak;\",\"You wash the feet of the weary,\",\"embrace the ones in need.\",\"I want to be like You, Jesus,\",\"to have this heart in me.\",\"You are the God of the humble,\",\"You are the humble King.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1099', 1099, 'Oh, the mercy of God', 'MP', 'en', 'Geoff Bullock Music/CopyCare Pacific Pty Ltd/Song Solutions www.songsolutions.org All Rights reserved.', '', 0, 0, 0, 1, 0, 'Oh, the mercy of God, the glory of grace,
that You chose to redeem us, to forgive and restore,
and You call us Your children, chosen in Him
to be holy and blameless to the glory of God.
To the praise of His glorious grace,
to the praise of His glory and power;
to Him be all glory, honour and praise
for ever and ever and ever, amen.
Oh, the richness of grace, the depths of His love,
in Him is redemption, the forgiveness of sin.
You called us as righteous, predestined in Him
for the praise of His glory, included in Christ.
To the praise...
Oh, the glory of God expressed in His Son,
His image and likeness revealed to us all;
the plea of the ages completed in Christ,
that we be presented perfected in Him.
To the praise...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1099', 'Geoff Bullock');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1099', 'Geoff Bullock');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1099', 'verse', 1, 0, '[\"Oh, the mercy of God, the glory of grace,\",\"that You chose to redeem us, to forgive and restore,\",\"and You call us Your children, chosen in Him\",\"to be holy and blameless to the glory of God.\",\"To the praise of His glorious grace,\",\"to the praise of His glory and power;\",\"to Him be all glory, honour and praise\",\"for ever and ever and ever, amen.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1099', 'verse', 2, 1, '[\"Oh, the richness of grace, the depths of His love,\",\"in Him is redemption, the forgiveness of sin.\",\"You called us as righteous, predestined in Him\",\"for the praise of His glory, included in Christ.\",\"To the praise...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1099', 'verse', 3, 2, '[\"Oh, the glory of God expressed in His Son,\",\"His image and likeness revealed to us all;\",\"the plea of the ages completed in Christ,\",\"that we be presented perfected in Him.\",\"To the praise...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1100', 1100, 'Open the eyes of my heart', 'MP', 'en', '1997 Integrity\'s Hosanna! Music, administered by Sovereign Music UK, PO Box 356, Leighton Buzzard LU7 3WP, UK. sovereignmusic@aol.com', '', 0, 0, 0, 1, 0, 'Open the eyes of my heart, Lord,
open the eyes of my heart.
I want to see You,
I want to see You.
Open the eyes of my heart, Lord,
open the eyes of my heart.
I want to see You,
I want to see You.
To see You high and lifted up,
shining in the light of Your glory.
Pour out Your power and love,
as we sing, ‘Holy, holy, holy.’
Open the eyes of my heart, Lord...
To see You high and lifted up...
Holy, holy, holy,
holy, holy, holy,
holy, holy, holy,
I want to see You.
Holy, holy, holy...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1100', 'Paul Baloche');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1100', 'Paul Baloche');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1100', 'chorus', 0, 0, '[\"Open the eyes of my heart, Lord,\",\"open the eyes of my heart.\",\"I want to see You,\",\"I want to see You.\",\"Open the eyes of my heart, Lord,\",\"open the eyes of my heart.\",\"I want to see You,\",\"I want to see You.\",\"To see You high and lifted up,\",\"shining in the light of Your glory.\",\"Pour out Your power and love,\",\"as we sing, ‘Holy, holy, holy.’\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1100', 'chorus', 0, 1, '[\"Open the eyes of my heart, Lord...\",\"To see You high and lifted up...\",\"Holy, holy, holy,\",\"holy, holy, holy,\",\"holy, holy, holy,\",\"I want to see You.\",\"Holy, holy, holy...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1101', 1101, 'Lord, reign in me', 'MP', 'en', '1998 Vineyard Songs (Admin. by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Over all the earth You reign on high,
every mountain stream, every sunset sky.
But my one request, Lord, my only aim
is that you’d reign in me again.
Lord, reign in me, reign in Your power,
over all my dreams, in my darkest hour.
You are the Lord of all I am,
so won’t You reign in me again.
Over every thought, over every word,
may my life reflect the beauty of my Lord;
’cause You mean more to me than any earthly thing,
so won’t You reign in me again.
Lord, reign in me...
Lord, reign in me...
won’t You reign in me again,
won’t You reign in me again.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1101', 'Brenton Brown');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1101', 'Brenton Brown');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1101', 'verse', 1, 0, '[\"Over all the earth You reign on high,\",\"every mountain stream, every sunset sky.\",\"But my one request, Lord, my only aim\",\"is that you’d reign in me again.\",\"Lord, reign in me, reign in Your power,\",\"over all my dreams, in my darkest hour.\",\"You are the Lord of all I am,\",\"so won’t You reign in me again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1101', 'verse', 2, 1, '[\"Over every thought, over every word,\",\"may my life reflect the beauty of my Lord;\",\"’cause You mean more to me than any earthly thing,\",\"so won’t You reign in me again.\",\"Lord, reign in me...\",\"Lord, reign in me...\",\"won’t You reign in me again,\",\"won’t You reign in me again.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1102', 1102, 'Great in power', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Praise Him, you heavens, and all that’s above.
Praise Him, you angels and heavenly hosts.
Let the whole earth praise Him.
Praise Him, the sun, moon and bright shining stars.
Praise Him, you heavens and waters and skies.
Let the whole earth praise Him.
Great in power, great in glory,
great in mercy, King of heaven.
Great in battle, great in wonder,
great in Zion, King over all the earth.
Praise Him, you heavens...
Great in power...
Great in power...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1102', 'Russell Fragar');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1102', 'Russell Fragar');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1102', 'verse', 1, 0, '[\"Praise Him, you heavens, and all that’s above.\",\"Praise Him, you angels and heavenly hosts.\",\"Let the whole earth praise Him.\",\"Praise Him, the sun, moon and bright shining stars.\",\"Praise Him, you heavens and waters and skies.\",\"Let the whole earth praise Him.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1102', 'chorus', 0, 1, '[\"Great in power, great in glory,\",\"great in mercy, King of heaven.\",\"Great in battle, great in wonder,\",\"great in Zion, King over all the earth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1102', 'chorus', 0, 2, '[\"Praise Him, you heavens...\",\"Great in power...\",\"Great in power...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1103', 1103, 'Psalm 134', 'MP', 'en', '© 1985 Little Misty Music (Admin worldwide by Integritymusic.com, a division of David C Cook songs@integritymusic.com) Used by Permission', '', 0, 0, 0, 1, 0, 'Praise the Lord,
all you servants of the Lord,
who minister by night within His house.
Lift up your hands
within the sanctuary,
and praise the Lord.
May the Lord,
the Maker of heaven and earth,
may this Lord bless you from Zion;
lift up your hands
within the sanctuary
and praise the Lord.
We praise You, Lord,
we praise You, Lord;
hallelujah, we praise You, Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1103', 'Ian White');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1103', 'Ian White');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1103', 'verse', 1, 0, '[\"Praise the Lord,\",\"all you servants of the Lord,\",\"who minister by night within His house.\",\"Lift up your hands\",\"within the sanctuary,\",\"and praise the Lord.\",\"May the Lord,\",\"the Maker of heaven and earth,\",\"may this Lord bless you from Zion;\",\"lift up your hands\",\"within the sanctuary\",\"and praise the Lord.\",\"We praise You, Lord,\",\"we praise You, Lord;\",\"hallelujah, we praise You, Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1104', 1104, 'Praise to Christ, the Lord incarnate', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Praise to Christ, the Lord incarnate,
gift of God by human birth:
He it is who came among us,
shared our life and showed our worth;
ours the turmoil He encountered,
ours the fight He made His own;
now within our hearts His Spirit
makes His way of freedom known.
Praise to Christ our Saviour and our King.
Praise to Christ our King.
Praise to Christ, the Man of Sorrows,
tasting death for our release:
His the cup of bitter anguish,
ours the pardon, ours the peace;
His the blood that seals forgiveness,
ours the weight of guilt He bore –
so by death and resurrection
Christ has opened heaven’s door.
Praise to Christ...
Praise to Christ, the Priest eternal:
still for us He intercedes;
still He sees our pains and problems –
how He understands our needs!
Yesterday, today, for ever,
always He remains the same:
pledged to bring us to the Father,
strong in grace, and free from blame.
Praise to Christ...
Praise to Christ...
Words and music adapted by by Graham Kendrick');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1104', 'Martin E Leckebusch');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1104', 'verse', 1, 0, '[\"Praise to Christ, the Lord incarnate,\",\"gift of God by human birth:\",\"He it is who came among us,\",\"shared our life and showed our worth;\",\"ours the turmoil He encountered,\",\"ours the fight He made His own;\",\"now within our hearts His Spirit\",\"makes His way of freedom known.\",\"Praise to Christ our Saviour and our King.\",\"Praise to Christ our King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1104', 'verse', 2, 1, '[\"Praise to Christ, the Man of Sorrows,\",\"tasting death for our release:\",\"His the cup of bitter anguish,\",\"ours the pardon, ours the peace;\",\"His the blood that seals forgiveness,\",\"ours the weight of guilt He bore –\",\"so by death and resurrection\",\"Christ has opened heaven’s door.\",\"Praise to Christ...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1104', 'verse', 3, 2, '[\"Praise to Christ, the Priest eternal:\",\"still for us He intercedes;\",\"still He sees our pains and problems –\",\"how He understands our needs!\",\"Yesterday, today, for ever,\",\"always He remains the same:\",\"pledged to bring us to the Father,\",\"strong in grace, and free from blame.\",\"Praise to Christ...\",\"Praise to Christ...\",\"Words and music adapted by by Graham Kendrick\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1105', 1105, 'Resurrection hymn', 'MP', 'en', '© 2003 Thankyou Music/Adm. CAPITOL CMG Publishing worldwide excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'See, what a morning, gloriously bright,
with the dawning of hope in Jerusalem;
folded the grave clothes, tomb filled with light,
as the angels announce Christ is risen!
See God’s salvation plan,
wrought in love, borne in pain, paid in sacrifice,
fulfilled in Christ the Man,
for He lives: Christ is risen from the dead!
See Mary weeping, ‘Where is He laid?’
as in sorrow she turns from the empty tomb;
hears a voice speaking, calling her name;
it’s the Master, the Lord raised to life again!
The voice that spans the years,
speaking life, stirring hope, bringing peace to us,
will sound till He appears,
for He lives: Christ is risen from the dead!
One with the Father, Ancient of days,
through the Spirit, who clothes faith with certainty,
honour and blessing, glory and praise
to the King crowned with power and authority!
And we are raised with Him,
death is dead, love has won, Christ has conquered;
and we shall reign with Him,
for He lives: Christ is risen from the dead!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1105', 'Stuart Townend');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1105', 'Keith Getty');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1105', 'Stuart Townend');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1105', 'Keith Getty');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1105', 'verse', 1, 0, '[\"See, what a morning, gloriously bright,\",\"with the dawning of hope in Jerusalem;\",\"folded the grave clothes, tomb filled with light,\",\"as the angels announce Christ is risen!\",\"See God’s salvation plan,\",\"wrought in love, borne in pain, paid in sacrifice,\",\"fulfilled in Christ the Man,\",\"for He lives: Christ is risen from the dead!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1105', 'verse', 2, 1, '[\"See Mary weeping, ‘Where is He laid?’\",\"as in sorrow she turns from the empty tomb;\",\"hears a voice speaking, calling her name;\",\"it’s the Master, the Lord raised to life again!\",\"The voice that spans the years,\",\"speaking life, stirring hope, bringing peace to us,\",\"will sound till He appears,\",\"for He lives: Christ is risen from the dead!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1105', 'verse', 3, 2, '[\"One with the Father, Ancient of days,\",\"through the Spirit, who clothes faith with certainty,\",\"honour and blessing, glory and praise\",\"to the King crowned with power and authority!\",\"And we are raised with Him,\",\"death is dead, love has won, Christ has conquered;\",\"and we shall reign with Him,\",\"for He lives: Christ is risen from the dead!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1106', 1106, 'Precious child', 'MP', 'en', '1989 Mercy/Vineyard Publishing  Vineyard Songs Canada/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Show me, dear Lord, how You see me in Your eyes,
so that I can realise Your great love for me.
Teach me, O Lord, that I am precious in Your sight,
that as a father loves his child, so You love me.
I am Yours because You have chosen me.
I’m Your child because You’ve called my name,
and Your steadfast love will never change;
I will always be Your precious child.
Show me, dear Lord, that I can never earn Your love,
that a gift cannot be earned, only given.
Teach me, O Lord, that Your love will never fade,
that I can never drive away Your great mercy.
I am Yours...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1106', 'Andy Park');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1106', 'Andy Park');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1106', 'verse', 1, 0, '[\"Show me, dear Lord, how You see me in Your eyes,\",\"so that I can realise Your great love for me.\",\"Teach me, O Lord, that I am precious in Your sight,\",\"that as a father loves his child, so You love me.\",\"I am Yours because You have chosen me.\",\"I’m Your child because You’ve called my name,\",\"and Your steadfast love will never change;\",\"I will always be Your precious child.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1106', 'verse', 2, 1, '[\"Show me, dear Lord, that I can never earn Your love,\",\"that a gift cannot be earned, only given.\",\"Teach me, O Lord, that Your love will never fade,\",\"that I can never drive away Your great mercy.\",\"I am Yours...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1107', 1107, 'Sovereign Lord', 'MP', 'en', '1989 Mercy/Vineyard Publishing  Vineyard Songs Canada/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 0, 'Sovereign Lord, over all,
You are reigning for ever.
Worship flows from our lips,
we have come for just one glimpse.
And we sing hallelujah,
hallelujah, hallelujah.
Majesty, reign in me,
Your right hand enfolding me.
Earth applaud, heavens sing
at the sight of Christ the King.
Lord of lords, now enthroned,
who can stand in Your presence?
Fire of love, holy One,
You burn brighter than the sun.
And we sing hallelujah,
hallelujah, hallelujah.
Majesty...
Majesty...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1107', 'Martyn Layzell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1107', 'Martyn Layzell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1107', 'verse', 1, 0, '[\"Sovereign Lord, over all,\",\"You are reigning for ever.\",\"Worship flows from our lips,\",\"we have come for just one glimpse.\",\"And we sing hallelujah,\",\"hallelujah, hallelujah.\",\"Majesty, reign in me,\",\"Your right hand enfolding me.\",\"Earth applaud, heavens sing\",\"at the sight of Christ the King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1107', 'verse', 2, 1, '[\"Lord of lords, now enthroned,\",\"who can stand in Your presence?\",\"Fire of love, holy One,\",\"You burn brighter than the sun.\",\"And we sing hallelujah,\",\"hallelujah, hallelujah.\",\"Majesty...\",\"Majesty...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1108', 1108, 'I simply live for you', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'Say the word, and I will sing for You.
Over oceans deep I will follow.
If each star was a song,
and every breath of wind, praise,
it would still fail by far
to say all my heart could say.
I simply live, I simply live for You.
Say the word...
As the glory of Your presence now fills this place,
in worship we will meet You face to face.
There is nothing in this world
to which You can be compared,
glory to glory, praise upon praise.
You bind the brokenhearted and save all my tears,
and by Your word you set the captives free.
There is nothing in this world that You cannot do.
I simply live, I simply live for You.
Say the word...
As the glory of Your presence...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1108', 'Russell Fragar');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1108', 'Russell Fragar');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1108', 'Chris Mitchell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1108', 'verse', 1, 0, '[\"Say the word, and I will sing for You.\",\"Over oceans deep I will follow.\",\"If each star was a song,\",\"and every breath of wind, praise,\",\"it would still fail by far\",\"to say all my heart could say.\",\"I simply live, I simply live for You.\",\"Say the word...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1108', 'chorus', 0, 1, '[\"As the glory of Your presence now fills this place,\",\"in worship we will meet You face to face.\",\"There is nothing in this world\",\"to which You can be compared,\",\"glory to glory, praise upon praise.\",\"You bind the brokenhearted and save all my tears,\",\"and by Your word you set the captives free.\",\"There is nothing in this world that You cannot do.\",\"I simply live, I simply live for You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1108', 'chorus', 0, 2, '[\"Say the word...\",\"As the glory of Your presence...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1109', 1109, 'Worthy is the Lamb', 'MP', 'en', '2000 Darlene Zschech/Hillsong Publishing / Kingsway Music. tym@kingsway.co.uk. For the UK. Used by permission.', '', 0, 0, 0, 1, 1, 'Thank you for the cross, Lord,
thank You for the price You paid.
Bearing all my sin and shame,
in love You came
and gave amazing grace.
Thank You for this love, Lord,
thank You for the nail-pierced hands.
Washed me in Your cleansing flow,
now all I know,
Your forgiveness and embrace.
Worthy is the Lamb
seated on the throne.
Crown You now with many crowns,
You reign victorious.
High and lifted up,
Jesus, Son of God,
the darling of heaven crucified.
Worthy is the Lamb,
worthy is the Lamb.
Thank you for the cross...
Worthy is the Lamb...
Worthy is the Lamb. (4 times)
Worthy is the Lamb...
Worthy is the Lamb. (6 times)');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1109', 'Darlene Zschech');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1109', 'Darlene Zschech');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1109', 'verse', 1, 0, '[\"Thank you for the cross, Lord,\",\"thank You for the price You paid.\",\"Bearing all my sin and shame,\",\"in love You came\",\"and gave amazing grace.\",\"Thank You for this love, Lord,\",\"thank You for the nail-pierced hands.\",\"Washed me in Your cleansing flow,\",\"now all I know,\",\"Your forgiveness and embrace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1109', 'chorus', 0, 1, '[\"Worthy is the Lamb\",\"seated on the throne.\",\"Crown You now with many crowns,\",\"You reign victorious.\",\"High and lifted up,\",\"Jesus, Son of God,\",\"the darling of heaven crucified.\",\"Worthy is the Lamb,\",\"worthy is the Lamb.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1109', 'chorus', 0, 2, '[\"Thank you for the cross...\",\"Worthy is the Lamb...\",\"Worthy is the Lamb. (4 times)\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1109', 'chorus', 0, 3, '[\"Worthy is the Lamb...\",\"Worthy is the Lamb. (6 times)\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1110', 1110, 'Thank You for the blood', 'MP', 'en', '©  1999 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Thank You, thank You for the blood that You shed,
standing in its blessing we sing these freedom songs.
Thank You, thank You for the battle You won,
standing in Your victory we sing salvation’s song,
we sing salvation’s song.
You have opened a way to the Father,
where before we could never have come.
Jesus, count us as Yours now for ever,
as we sing these freedom songs.
Thank You...
We sing of all You’ve done,
we sing of all You’ve done,
we sing of all You’ve done for us,
won for us, paid for us.
We sing of all You’ve done...
Thank You...
We sing of all You’ve done...
We sing of all You’ve done...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1110', 'Matt Redman');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1110', 'Matt Redman');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1110', 'verse', 1, 0, '[\"Thank You, thank You for the blood that You shed,\",\"standing in its blessing we sing these freedom songs.\",\"Thank You, thank You for the battle You won,\",\"standing in Your victory we sing salvation’s song,\",\"we sing salvation’s song.\",\"You have opened a way to the Father,\",\"where before we could never have come.\",\"Jesus, count us as Yours now for ever,\",\"as we sing these freedom songs.\",\"Thank You...\",\"We sing of all You’ve done,\",\"we sing of all You’ve done,\",\"we sing of all You’ve done for us,\",\"won for us, paid for us.\",\"We sing of all You’ve done...\",\"Thank You...\",\"We sing of all You’ve done...\",\"We sing of all You’ve done...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1111', 1111, 'The Lord is gracious and compassionate', 'MP', 'en', 'Vineyard Songs (UK/Eire)/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'The Lord is gracious and compassionate,
slow to anger and rich in love.
The Lord is gracious and compassionate,
slow to anger and rich in love.
The Lord is good to all,
He has compassion on all that He has made.
As far as the east is from the west,
that’s how far He has removed our transgressions from us.
As far as the east is from the west,
that’s how far He has removed our transgressions from us.
Praise the Lord, O my soul, praise the Lord.
Praise the Lord, O my soul, praise the Lord.
The Lord is gracious...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1111', 'Graham Ord');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1111', 'Graham Ord');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1111', 'verse', 1, 0, '[\"The Lord is gracious and compassionate,\",\"slow to anger and rich in love.\",\"The Lord is gracious and compassionate,\",\"slow to anger and rich in love.\",\"The Lord is good to all,\",\"He has compassion on all that He has made.\",\"As far as the east is from the west,\",\"that’s how far He has removed our transgressions from us.\",\"As far as the east is from the west,\",\"that’s how far He has removed our transgressions from us.\",\"Praise the Lord, O my soul, praise the Lord.\",\"Praise the Lord, O my soul, praise the Lord.\",\"The Lord is gracious...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1112', 1112, 'The Lord your God in the midst of you', 'MP', 'en', '2004 Greg Leavers', '', 0, 0, 0, 1, 1, 'The Lord your God in the midst of you is mighty,
the Lord your God in the midst of you is mighty.
He’s a victorious warrior, a powerful deliverer,
the Lord your God in the midst of you is mighty.
Mighty, mighty, mighty is the Lord,
mighty, mighty, mighty is the Lord.
The Lord your God in the midst of you is gracious,
the Lord your God in the midst of you is gracious.
Rejoicing over you with shouts of joy,
singing over you deliverance songs.
The Lord your God in the midst of you is gracious.
Gracious, gracious, gracious is the Lord,
gracious, gracious, gracious is the Lord.
The Lord your God in the midst of you is holy,
the Lord your God in the midst of you is holy.
So pure and righteous in all His ways,
He’s worthy of the highest praise.
The Lord your God in the midst of you is holy.
Holy, holy, holy is the Lord,
holy, holy, holy is the Lord.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1112', 'Greg Leavers');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1112', 'Greg Leavers');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1112', 'verse', 1, 0, '[\"The Lord your God in the midst of you is mighty,\",\"the Lord your God in the midst of you is mighty.\",\"He’s a victorious warrior, a powerful deliverer,\",\"the Lord your God in the midst of you is mighty.\",\"Mighty, mighty, mighty is the Lord,\",\"mighty, mighty, mighty is the Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1112', 'verse', 2, 1, '[\"The Lord your God in the midst of you is gracious,\",\"the Lord your God in the midst of you is gracious.\",\"Rejoicing over you with shouts of joy,\",\"singing over you deliverance songs.\",\"The Lord your God in the midst of you is gracious.\",\"Gracious, gracious, gracious is the Lord,\",\"gracious, gracious, gracious is the Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1112', 'verse', 3, 2, '[\"The Lord your God in the midst of you is holy,\",\"the Lord your God in the midst of you is holy.\",\"So pure and righteous in all His ways,\",\"He’s worthy of the highest praise.\",\"The Lord your God in the midst of you is holy.\",\"Holy, holy, holy is the Lord,\",\"holy, holy, holy is the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1113', 1113, 'The Lord your God is with you', 'MP', 'en', '1996 Karen David/Ellel Ministries Ltd.', '', 0, 0, 0, 1, 1, 'The Lord your God is with you,
His power gives you victory;
the Lord your God is with you,
His power gives you victory.
The Lord your God is with you...
The Lord will take delight in you,
and in His love will give you new life.
He will sing and be joyful over you.
The Lord your God is with you...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1113', 'Karen David');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1113', 'Karen David');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1113', 'verse', 1, 0, '[\"The Lord your God is with you,\",\"His power gives you victory;\",\"the Lord your God is with you,\",\"His power gives you victory.\",\"The Lord your God is with you...\",\"The Lord will take delight in you,\",\"and in His love will give you new life.\",\"He will sing and be joyful over you.\",\"The Lord your God is with you...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1114', 1114, 'Outrageous grace', 'MP', 'en', '©  2000 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 1, 'There’s a lot of pain, but a lot more healing,
there’s a lot of trouble, but a lot more peace.
There’s a lot of hate, but a lot more loving,
there’s a lot of sin, but a lot more grace.
Oh, outrageous grace! Oh, outrageous grace!
Love unfurled by heaven’s hand.
Oh, outrageous grace! Oh, outrageous grace!
Through my Jesus I can stand.
There’s a lot of fear, but a lot more freedom,
there’s a lot of darkness, but a lot more light.
There’s a lot of cloud, but a lot more vision,
there’s a lot of perishing, but a lot more life.
Oh, outrageous grace...
There’s an enemy that seeks to kill what it can’t control.
It twists and turns, making mountains out of molehills.
But when I call on the Lord who is worthy of praise,
I run to Him and I am saved.
Oh, outrageous grace...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1114', 'Godfrey Birtill');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1114', 'Godfrey Birtill');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1114', 'verse', 1, 0, '[\"There’s a lot of pain, but a lot more healing,\",\"there’s a lot of trouble, but a lot more peace.\",\"There’s a lot of hate, but a lot more loving,\",\"there’s a lot of sin, but a lot more grace.\",\"Oh, outrageous grace! Oh, outrageous grace!\",\"Love unfurled by heaven’s hand.\",\"Oh, outrageous grace! Oh, outrageous grace!\",\"Through my Jesus I can stand.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1114', 'verse', 2, 1, '[\"There’s a lot of fear, but a lot more freedom,\",\"there’s a lot of darkness, but a lot more light.\",\"There’s a lot of cloud, but a lot more vision,\",\"there’s a lot of perishing, but a lot more life.\",\"Oh, outrageous grace...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1114', 'verse', 3, 2, '[\"There’s an enemy that seeks to kill what it can’t control.\",\"It twists and turns, making mountains out of molehills.\",\"But when I call on the Lord who is worthy of praise,\",\"I run to Him and I am saved.\",\"Oh, outrageous grace...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1115', 1115, 'There is a day', 'MP', 'en', '(c) 2001 Thankyou Music/Adm. by Capitol CMG Publishing, excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'There is a day that all creation’s waiting for,
a day of freedom and liberation for the earth.
And on that day, the Lord will come to meet His bride.
And when we see Him in an instant we’ll be changed.
The trumpet sounds, and the dead will then be raised
by His power, never to perish again.
Once only flesh, now clothed with immortality;
death has now been swallowed up in victory.
We will meet Him in the air
and then we will be like Him
for we will see Him as He is, oh yeah.
Then all hurt and pain will cease,
and we’ll be with Him for ever,
and in His glory we will live, oh yeah, oh yeah.
So lift your eyes to the things as yet unseen,
that will remain now for all eternity.
Though trouble’s hard, it’s only momentary.
And it’s achieving our future glory.
We will meet Him in the air...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1115', 'Nathan Fellingham');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1115', 'Nathan Fellingham');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1115', 'verse', 1, 0, '[\"There is a day that all creation’s waiting for,\",\"a day of freedom and liberation for the earth.\",\"And on that day, the Lord will come to meet His bride.\",\"And when we see Him in an instant we’ll be changed.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1115', 'verse', 2, 1, '[\"The trumpet sounds, and the dead will then be raised\",\"by His power, never to perish again.\",\"Once only flesh, now clothed with immortality;\",\"death has now been swallowed up in victory.\",\"We will meet Him in the air\",\"and then we will be like Him\",\"for we will see Him as He is, oh yeah.\",\"Then all hurt and pain will cease,\",\"and we’ll be with Him for ever,\",\"and in His glory we will live, oh yeah, oh yeah.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1115', 'verse', 3, 2, '[\"So lift your eyes to the things as yet unseen,\",\"that will remain now for all eternity.\",\"Though trouble’s hard, it’s only momentary.\",\"And it’s achieving our future glory.\",\"We will meet Him in the air...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1116', 1116, 'There is a higher throne', 'MP', 'en', '© 2002 Thankyou Music/Adm. by CAPITOL CMG Publishing worldwide excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'There is a higher throne
than all this world has known,
where faithful ones from every tongue
will one day come.
Before the Son we’ll stand,
made faultless through the Lamb;
believing hearts find promised grace:
salvation comes.
Hear heaven’s voices sing,
their thunderous anthem rings
through emerald courts and sapphire skies,
their praises rise.
All glory, wisdom, power,
strength, thanks and honour are
to God, our King who reigns on high
for ever more.
And there we’ll find our home,
our life before the throne;
we’ll honour Him in perfect song
where we belong.
He’ll wipe each tear-stained eye,
as thirst and hunger die;
the Lamb becomes our Shepherd King:
we’ll reign with Him.
Hear heaven’s voices sing...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1116', 'Kristyn Lennox');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1116', 'Keith Getty');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1116', 'Kristyn Lennox');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1116', 'Keith Getty');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1116', 'verse', 1, 0, '[\"There is a higher throne\",\"than all this world has known,\",\"where faithful ones from every tongue\",\"will one day come.\",\"Before the Son we’ll stand,\",\"made faultless through the Lamb;\",\"believing hearts find promised grace:\",\"salvation comes.\",\"Hear heaven’s voices sing,\",\"their thunderous anthem rings\",\"through emerald courts and sapphire skies,\",\"their praises rise.\",\"All glory, wisdom, power,\",\"strength, thanks and honour are\",\"to God, our King who reigns on high\",\"for ever more.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1116', 'verse', 2, 1, '[\"And there we’ll find our home,\",\"our life before the throne;\",\"we’ll honour Him in perfect song\",\"where we belong.\",\"He’ll wipe each tear-stained eye,\",\"as thirst and hunger die;\",\"the Lamb becomes our Shepherd King:\",\"we’ll reign with Him.\",\"Hear heaven’s voices sing...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1117', 1117, 'Jesus, friend of sinners', 'MP', 'en', '©  1998 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'There is a voice that must be heard,
there is a song that must be sung;
there is a name that must be lifted high.
There is a treasure more than gold,
there is a King upon the throne;
there is one whose praise will fill the skies.
His name is Jesus, friend of sinners,
Jesus, Jesus, friend of mine.
There is a peace that calms our fears,
there is a love stronger than death;
there is a hope that goes beyond the grave.
There is a friend who won’t let go,
there is a heart that beats for you;
there is one name by which we are saved.
His name is Jesus...
His name is Jesus...
When I was captive to my fears,
You were the one who came to me,
You set me free.
His name is Jesus...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1117', 'Paul Oakley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1117', 'Paul Oakley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1117', 'verse', 1, 0, '[\"There is a voice that must be heard,\",\"there is a song that must be sung;\",\"there is a name that must be lifted high.\",\"There is a treasure more than gold,\",\"there is a King upon the throne;\",\"there is one whose praise will fill the skies.\",\"His name is Jesus, friend of sinners,\",\"Jesus, Jesus, friend of mine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1117', 'verse', 2, 1, '[\"There is a peace that calms our fears,\",\"there is a love stronger than death;\",\"there is a hope that goes beyond the grave.\",\"There is a friend who won’t let go,\",\"there is a heart that beats for you;\",\"there is one name by which we are saved.\",\"His name is Jesus...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1117', 'chorus', 0, 2, '[\"His name is Jesus...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1117', 'chorus', 0, 3, '[\"When I was captive to my fears,\",\"You were the one who came to me,\",\"You set me free.\",\"His name is Jesus...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1118', 1118, 'Consuming Fire', 'MP', 'en', '©  2002 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'There must be more than this:
O Breath of God, come breathe within.
There must be more than this:
Spirit of God, we wait for You.
Fill us anew, we pray;
fill us anew, we pray.
Consuming fire, fan into flame
a passion for Your name.
Spirit of God, fall in this place.
Lord, have Your way,
Lord, have Your way with us.
Come like a rushing wind,
clothe us in power from on high.
Now set the captives free;
leave us abandoned to Your praise.
Lord, let Your glory fall,
Lord, let Your glory fall.
Consuming fire...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1118', 'Tim Hughes');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1118', 'Tim Hughes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1118', 'verse', 1, 0, '[\"There must be more than this:\",\"O Breath of God, come breathe within.\",\"There must be more than this:\",\"Spirit of God, we wait for You.\",\"Fill us anew, we pray;\",\"fill us anew, we pray.\",\"Consuming fire, fan into flame\",\"a passion for Your name.\",\"Spirit of God, fall in this place.\",\"Lord, have Your way,\",\"Lord, have Your way with us.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1118', 'verse', 2, 1, '[\"Come like a rushing wind,\",\"clothe us in power from on high.\",\"Now set the captives free;\",\"leave us abandoned to Your praise.\",\"Lord, let Your glory fall,\",\"Lord, let Your glory fall.\",\"Consuming fire...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1119', 1119, 'Breathe', 'MP', 'en', '1995 Mercy/Vineyard Publishing/ Adm.by Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'This is the air I breathe,
this is the air I breathe;
Your holy presence living in me.
This is my daily bread,
this is my daily bread;
Your very word spoken to me.
And I, I’m desperate for You,
and I, I’m lost without You.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1119', 'Marie Barnett');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1119', 'Marie Barnett');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1119', 'verse', 1, 0, '[\"This is the air I breathe,\",\"this is the air I breathe;\",\"Your holy presence living in me.\",\"This is my daily bread,\",\"this is my daily bread;\",\"Your very word spoken to me.\",\"And I, I’m desperate for You,\",\"and I, I’m lost without You.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1120', 1120, 'Anthem of the free', 'MP', 'en', '©  2003 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'This is the anthem of the free,
this is the song of the redeemed,
Jesus, Your praises rising higher and higher and higher.
We’ll sing it loud, we’ll sing it strong,
we’ll sing it all around the world,
Jesus, Your praise will last for ever and ever and ever.
Hear the sound of the free,
hear the cry of liberty,
we will rejoice in You,
we will rejoice.
As we sing of all You’ve done
and the wonders of your love,
we will rejoice in You,
we will rejoice.
Rising up around the earth
is a heavenly song of Your endless worth,
growing louder and louder and louder.
This is the anthem of the free...
Then one day Your heavenly song
will drown all music but its own. (4 times)');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1120', 'Matt Redman');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1120', 'Matt Redman');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1120', 'verse', 1, 0, '[\"This is the anthem of the free,\",\"this is the song of the redeemed,\",\"Jesus, Your praises rising higher and higher and higher.\",\"We’ll sing it loud, we’ll sing it strong,\",\"we’ll sing it all around the world,\",\"Jesus, Your praise will last for ever and ever and ever.\",\"Hear the sound of the free,\",\"hear the cry of liberty,\",\"we will rejoice in You,\",\"we will rejoice.\",\"As we sing of all You’ve done\",\"and the wonders of your love,\",\"we will rejoice in You,\",\"we will rejoice.\",\"Rising up around the earth\",\"is a heavenly song of Your endless worth,\",\"growing louder and louder and louder.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1120', 'chorus', 0, 1, '[\"This is the anthem of the free...\",\"Then one day Your heavenly song\",\"will drown all music but its own. (4 times)\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1121', 1121, 'Holy ground', 'MP', 'en', '1983 Songchannel Music Co/Meadowgreen Music Company/CapitolCMGPublishing.com (adm UK/Eire Song Solutions www.songsolutions.org) All rights reserved. Used by permission.', '', 0, 0, 0, 1, 1, 'We are standing on holy ground,
and I know that there are angels all around.
Let us praise Jesus now.
We are standing in His presence on holy ground.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1121', 'Geron Davis');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1121', 'Geron Davis');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1121', 'verse', 1, 0, '[\"We are standing on holy ground,\",\"and I know that there are angels all around.\",\"Let us praise Jesus now.\",\"We are standing in His presence on holy ground.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1122', 1122, 'Be unto your name', 'MP', 'en', '© 1998 Integrity\'s Hosanna! Music (Adm. by Capitol CMG Publishing excl. UK, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'We are a moment, You are for ever
Lord of the ages, God before time.
We are a vapour, You are eternal,
love everlasting, reigning on high.
Holy, holy, Lord God almighty.
Worthy is the Lamb that was slain.
Highest praises, honour and glory
be unto Your name, be unto Your name.
We are a moment...
Holy, holy...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1122', 'Lynn DeShazo');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1122', 'Gary Sadler');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1122', 'Lynn DeShazo');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1122', 'Gary Sadler');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1122', 'verse', 1, 0, '[\"We are a moment, You are for ever\",\"Lord of the ages, God before time.\",\"We are a vapour, You are eternal,\",\"love everlasting, reigning on high.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1122', 'chorus', 0, 1, '[\"Holy, holy, Lord God almighty.\",\"Worthy is the Lamb that was slain.\",\"Highest praises, honour and glory\",\"be unto Your name, be unto Your name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1122', 'chorus', 0, 2, '[\"We are a moment...\",\"Holy, holy...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1123', 1123, 'We bow down', 'MP', 'en', '©  1996 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'We bow down and confess
You are Lord in this place.
We bow down and confess
You are Lord in this place.
You are all I need;
it’s Your face I seek.
In the presence of Your light
we bow down, we bow down.
We bow down and confess...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1123', 'Viola Grafstrom');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1123', 'Viola Grafstrom');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1123', 'verse', 1, 0, '[\"We bow down and confess\",\"You are Lord in this place.\",\"We bow down and confess\",\"You are Lord in this place.\",\"You are all I need;\",\"it’s Your face I seek.\",\"In the presence of Your light\",\"we bow down, we bow down.\",\"We bow down and confess...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1124', 1124, 'We fall down', 'MP', 'en', '© 1998 worshiptogether.com Songs/sixsteps Music/Vamos Publishing (Adm. by Capitol CMG Publishing worldwide excl. UK & Europe, admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com ) Used by permission', '', 0, 0, 0, 1, 0, 'We fall down, we lay our crowns
at the feet of Jesus.
The greatness of mercy and love,
at the feet of Jesus.
And we cry holy, holy, holy.
And we cry holy, holy, holy.
And we cry holy, holy,
holy is the Lamb.
We fall down...
And we cry holy...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1124', 'Chris Tomlin');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1124', 'Chris Tomlin');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1124', 'verse', 1, 0, '[\"We fall down, we lay our crowns\",\"at the feet of Jesus.\",\"The greatness of mercy and love,\",\"at the feet of Jesus.\",\"And we cry holy, holy, holy.\",\"And we cry holy, holy, holy.\",\"And we cry holy, holy,\",\"holy is the Lamb.\",\"We fall down...\",\"And we cry holy...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1125', 1125, 'Touching heaven, changing earth', 'MP', 'en', '', '', 0, 0, 0, 1, 0, 'We will seek Your face, almighty God,
turn and pray for You to heal our land.
Father, let revival start in us,
then every heart will know Your kingdom come.
Lifting up the name of the Lord
in power and in unity,
we will see the nations turn,
touching heaven, changing earth,
touching heaven, changing earth.
Never looking back, we’ll run the race;
giving You our lives, we’ll gain the prize.
We will take the harvest given us,
though we sow in tears, we’ll reap in joy.
Lifting up the name of the Lord...
Send revival, send revival,
send revival to us.
Send revival, send revival,
send revival to us.
Lifting up the name of the Lord...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1125', 'Reuben Morgan');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1125', 'Reuben Morgan');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1125', 'verse', 1, 0, '[\"We will seek Your face, almighty God,\",\"turn and pray for You to heal our land.\",\"Father, let revival start in us,\",\"then every heart will know Your kingdom come.\",\"Lifting up the name of the Lord\",\"in power and in unity,\",\"we will see the nations turn,\",\"touching heaven, changing earth,\",\"touching heaven, changing earth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1125', 'verse', 2, 1, '[\"Never looking back, we’ll run the race;\",\"giving You our lives, we’ll gain the prize.\",\"We will take the harvest given us,\",\"though we sow in tears, we’ll reap in joy.\",\"Lifting up the name of the Lord...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1125', 'chorus', 0, 2, '[\"Send revival, send revival,\",\"send revival to us.\",\"Send revival, send revival,\",\"send revival to us.\",\"Lifting up the name of the Lord...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1126', 1126, 'When I survey', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'When I survey the wondrous cross
on which the Prince of glory died,
my richest gain I count but loss,
and pour contempt on all my pride.
Forbid it, Lord, that I should boast,
save in the death of Christ my God:
all the vain things that charm me most,
I sacrifice them to His blood.
See from His head, His hands, His feet,
sorrow and love flow mingled down:
did e’er such love and sorrow meet,
or thorns compose so rich a crown?
Were the whole realm of Nature mine,
that were an offering far too small;
love so amazing, so divine,
demands my soul, my life, my all!');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1126', 'Isaac Watts');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1126', 'Dave Bainbridge');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1126', 'Joanne Hogg');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1126', 'Terl Bryant');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1126', 'verse', 1, 0, '[\"When I survey the wondrous cross\",\"on which the Prince of glory died,\",\"my richest gain I count but loss,\",\"and pour contempt on all my pride.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1126', 'verse', 2, 1, '[\"Forbid it, Lord, that I should boast,\",\"save in the death of Christ my God:\",\"all the vain things that charm me most,\",\"I sacrifice them to His blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1126', 'verse', 3, 2, '[\"See from His head, His hands, His feet,\",\"sorrow and love flow mingled down:\",\"did e’er such love and sorrow meet,\",\"or thorns compose so rich a crown?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1126', 'verse', 4, 3, '[\"Were the whole realm of Nature mine,\",\"that were an offering far too small;\",\"love so amazing, so divine,\",\"demands my soul, my life, my all!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1127', 1127, 'There is a new song', 'MP', 'en', '(c) 2001 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'When I was lost You came and rescued me;
reached down into the pit and lifted me.
O Lord, such love!
I was as far from You as I could be.
You know all the things I’ve ever done,
but Jesus’ blood has cancelled every one.
O Lord, such grace!
to qualify me as Your own.
There is a new song in my mouth,
there is a deep cry in my heart,
a hymn of praise to almighty God,
hallelujah!
And now I stand firm on this rock,
my life is hidden now with Christ in God,
the old has gone and the new has come,
hallelujah!
Your love has lifted me.
Now I have come into Your family,
for the Son of God has died for me.
O Lord, such peace!
I am as loved by You as I could be.
In the full assurance of Your love,
now with every confidence we come.
O Lord, such joy!
to know that You delight in us.
There is a new song in my mouth...
Many are the wonders You have done,
and many are the things that You have planned.
How beautiful the grace that gives to us
all that we don’t deserve,
all that we cannot earn,
but is a gift of love.
There is a new song in my mouth...
Your love has lifted me.
Your love has lifted me.
Your love has lifted me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1127', 'Kate Simmonds');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1127', 'Miles Simmonds');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1127', 'Kate Simmonds');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1127', 'Miles Simmonds');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1127', 'verse', 1, 0, '[\"When I was lost You came and rescued me;\",\"reached down into the pit and lifted me.\",\"O Lord, such love!\",\"I was as far from You as I could be.\",\"You know all the things I’ve ever done,\",\"but Jesus’ blood has cancelled every one.\",\"O Lord, such grace!\",\"to qualify me as Your own.\",\"There is a new song in my mouth,\",\"there is a deep cry in my heart,\",\"a hymn of praise to almighty God,\",\"hallelujah!\",\"And now I stand firm on this rock,\",\"my life is hidden now with Christ in God,\",\"the old has gone and the new has come,\",\"hallelujah!\",\"Your love has lifted me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1127', 'verse', 2, 1, '[\"Now I have come into Your family,\",\"for the Son of God has died for me.\",\"O Lord, such peace!\",\"I am as loved by You as I could be.\",\"In the full assurance of Your love,\",\"now with every confidence we come.\",\"O Lord, such joy!\",\"to know that You delight in us.\",\"There is a new song in my mouth...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1127', 'chorus', 0, 2, '[\"Many are the wonders You have done,\",\"and many are the things that You have planned.\",\"How beautiful the grace that gives to us\",\"all that we don’t deserve,\",\"all that we cannot earn,\",\"but is a gift of love.\",\"There is a new song in my mouth...\",\"Your love has lifted me.\",\"Your love has lifted me.\",\"Your love has lifted me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1128', 1128, 'River of fire', 'MP', 'en', '©  1995 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Who paints the skies into glorious day?
Only the splendour of Jesus.
Who breathes His life into fists of clay?
Only the splendour of Jesus.
Who shapes the valleys and brings the rain?
Only the splendour of Jesus.
Who makes the desert to live again?
Only the splendour of Jesus.
Teach every nation His marvellous ways;
each generation shall sing His praise.
He is wonderful, He is glorious,
clothed in righteousness, full of tenderness.
Come and worship Him, He’s the Prince of life,
He will cleanse our hearts in His river of fire.
Who hears the cry of the barren one?
Only the mercy of Jesus.
Who breaks the curse of the heart of stone?
Only the mercy of Jesus.
Who storms the prison and sets men free?
Only the mercy of Jesus.
Purchasing souls for eternity?
Only the mercy of Jesus.
Teach every nation His marvellous ways.
Each generation shall sing His praise.
He is wonderful...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1128', 'Stuart Townend');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1128', 'Stuart Townend');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1128', 'verse', 1, 0, '[\"Who paints the skies into glorious day?\",\"Only the splendour of Jesus.\",\"Who breathes His life into fists of clay?\",\"Only the splendour of Jesus.\",\"Who shapes the valleys and brings the rain?\",\"Only the splendour of Jesus.\",\"Who makes the desert to live again?\",\"Only the splendour of Jesus.\",\"Teach every nation His marvellous ways;\",\"each generation shall sing His praise.\",\"He is wonderful, He is glorious,\",\"clothed in righteousness, full of tenderness.\",\"Come and worship Him, He’s the Prince of life,\",\"He will cleanse our hearts in His river of fire.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1128', 'verse', 2, 1, '[\"Who hears the cry of the barren one?\",\"Only the mercy of Jesus.\",\"Who breaks the curse of the heart of stone?\",\"Only the mercy of Jesus.\",\"Who storms the prison and sets men free?\",\"Only the mercy of Jesus.\",\"Purchasing souls for eternity?\",\"Only the mercy of Jesus.\",\"Teach every nation His marvellous ways.\",\"Each generation shall sing His praise.\",\"He is wonderful...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1129', 1129, 'Love incarnate', 'MP', 'en', '© 2002 Thankyou Music/Adm. by CapitolCMGPublishing.com excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'With a prayer You fed the hungry,
with a cry You stilled the storm;
with a look You had compassion
on the desperate and forlorn.
With a touch You healed the leper,
with a shout You raised the dead;
with a word expelled the demons,
with a blessing broke the bread.
Love incarnate, love divine,
captivate this heart of mine
till all I do speaks of You.
As a sheep before the shearer
You were silent in Your pain;
You endured humiliation
at the hands of those You’d made.
And as hell unleashed its fury
You were lifted on a tree,
crying, ’Father God, forgive them,
place their punishment on me.’
Love incarnate, love divine...
I will feed the poor and hungry,
I will stand up for the truth;
I will take my cross and follow
to the corners of the earth.
And I ask that You so fill me
with Your peace, Your power, Your breath,
that I never love my life so much
to shrink from facing death.
Love incarnate, love divine...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1129', 'Stuart Townend');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1129', 'Stuart Townend');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1129', 'verse', 1, 0, '[\"With a prayer You fed the hungry,\",\"with a cry You stilled the storm;\",\"with a look You had compassion\",\"on the desperate and forlorn.\",\"With a touch You healed the leper,\",\"with a shout You raised the dead;\",\"with a word expelled the demons,\",\"with a blessing broke the bread.\",\"Love incarnate, love divine,\",\"captivate this heart of mine\",\"till all I do speaks of You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1129', 'verse', 2, 1, '[\"As a sheep before the shearer\",\"You were silent in Your pain;\",\"You endured humiliation\",\"at the hands of those You’d made.\",\"And as hell unleashed its fury\",\"You were lifted on a tree,\",\"crying, ’Father God, forgive them,\",\"place their punishment on me.’\",\"Love incarnate, love divine...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1129', 'verse', 3, 2, '[\"I will feed the poor and hungry,\",\"I will stand up for the truth;\",\"I will take my cross and follow\",\"to the corners of the earth.\",\"And I ask that You so fill me\",\"with Your peace, Your power, Your breath,\",\"that I never love my life so much\",\"to shrink from facing death.\",\"Love incarnate, love divine...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1130', 1130, 'Beautiful One', 'MP', 'en', '©  2002 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Wonderful, so wonderful is Your unfailing love;
Your cross has spoken mercy over me.
No eye has seen, no ear has heard,
no heart could fully know
how glorious, how beautiful You are.
Beautiful One, I love You,
beautiful One, I adore,
beautiful One, my soul must sing.
Powerful, so powerful, Your glory fills the skies;
Your mighty work displayed for all to see.
The beauty of Your majesty awakes my heart to sing
how wonderful, how marvellous You are.
Beautiful One, I love You...
You opened my eyes to Your wonders anew,
You captured this heart with Your love,
’cause nothing on earth is as beautiful as You.
You opened my eyes...
Beautiful One, I love You...
My soul, my soul must sing,
my soul, my soul must sing,
my soul, my soul must sing,
beautiful One.
My soul, my soul must sing...
Beautiful One, I love You...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1130', 'Tim Hughes');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1130', 'Tim Hughes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1130', 'verse', 1, 0, '[\"Wonderful, so wonderful is Your unfailing love;\",\"Your cross has spoken mercy over me.\",\"No eye has seen, no ear has heard,\",\"no heart could fully know\",\"how glorious, how beautiful You are.\",\"Beautiful One, I love You,\",\"beautiful One, I adore,\",\"beautiful One, my soul must sing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1130', 'verse', 2, 1, '[\"Powerful, so powerful, Your glory fills the skies;\",\"Your mighty work displayed for all to see.\",\"The beauty of Your majesty awakes my heart to sing\",\"how wonderful, how marvellous You are.\",\"Beautiful One, I love You...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1130', 'chorus', 0, 2, '[\"You opened my eyes to Your wonders anew,\",\"You captured this heart with Your love,\",\"’cause nothing on earth is as beautiful as You.\",\"You opened my eyes...\",\"Beautiful One, I love You...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1130', 'chorus', 0, 3, '[\"My soul, my soul must sing,\",\"my soul, my soul must sing,\",\"my soul, my soul must sing,\",\"beautiful One.\",\"My soul, my soul must sing...\",\"Beautiful One, I love You...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1131', 1131, 'Worthy, You are worthy', 'MP', 'en', '(c) 1999 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Worthy, you are worthy,
much more worthy than I’ve known;
I cannot imagine
just how glorious You are.
I cannot begin to tell
how deep a love You bring;
Lord, my ears have heard of You,
but now my eyes have seen.
You’re worthy, You’re worthy, You’re worthy,
You’re worthy to be praised,
for ever and a day.
You’re worthy...
Glory, I give glory
to the One who saved my soul.
You found me and You freed me');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1131', 'Matt Redman');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1131', 'Matt Redman');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1131', 'verse', 1, 0, '[\"Worthy, you are worthy,\",\"much more worthy than I’ve known;\",\"I cannot imagine\",\"just how glorious You are.\",\"I cannot begin to tell\",\"how deep a love You bring;\",\"Lord, my ears have heard of You,\",\"but now my eyes have seen.\",\"You’re worthy, You’re worthy, You’re worthy,\",\"You’re worthy to be praised,\",\"for ever and a day.\",\"You’re worthy...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1131', 'verse', 2, 1, '[\"Glory, I give glory\",\"to the One who saved my soul.\",\"You found me and You freed me\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1132', 1132, 'Let my words be few', 'MP', 'en', '(c) 2000 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'You are God in heaven,
and here I am on earth;
so I’ll let my words be few:
Jesus, I am so in love with You.
And I’ll stand in awe of You,
yes, I’ll stand in awe of You.
And I’ll let my words be few:
Jesus, I am so in love with You.
The simplest of all love songs
I want to bring to You,
so I’ll let my words be few:
Jesus, I am so in love with You.
And I’ll stand in awe of You...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1132', 'Matt Redman');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1132', 'Beth Redman');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1132', 'Matt Redman');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1132', 'Beth Redman');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1132', 'verse', 1, 0, '[\"You are God in heaven,\",\"and here I am on earth;\",\"so I’ll let my words be few:\",\"Jesus, I am so in love with You.\",\"And I’ll stand in awe of You,\",\"yes, I’ll stand in awe of You.\",\"And I’ll let my words be few:\",\"Jesus, I am so in love with You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1132', 'verse', 2, 1, '[\"The simplest of all love songs\",\"I want to bring to You,\",\"so I’ll let my words be few:\",\"Jesus, I am so in love with You.\",\"And I’ll stand in awe of You...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1133', 1133, 'You are holy', 'MP', 'en', '1997 Reuben Morgan/Hillsong Publishing / Kingsway Music. tym@kingsway.co.uk. For the UK. Used by permission.', '', 0, 0, 0, 1, 0, 'You are holy, holy,
Lord, there is none like You.
You are holy, holy,
Glory to You alone.
You are holy, holy...
I’ll sing Your praises for ever,
deeper in love with You.
Here in Your courts
where I’m close to Your throne,
I’ve found where I belong.
I’ll sing Your praises for ever...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1133', 'Reuben Morgan');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1133', 'Reuben Morgan');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1133', 'verse', 1, 0, '[\"You are holy, holy,\",\"Lord, there is none like You.\",\"You are holy, holy,\",\"Glory to You alone.\",\"You are holy, holy...\",\"I’ll sing Your praises for ever,\",\"deeper in love with You.\",\"Here in Your courts\",\"where I’m close to Your throne,\",\"I’ve found where I belong.\",\"I’ll sing Your praises for ever...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1134', 1134, 'You are my anchor', 'MP', 'en', '©  2001 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'You are my anchor, my light and my salvation.
You are my refuge, my heart will not fear.
Though my foes surround me on every hand,
they will stumble and fall while in grace I stand.
In my day of trouble, You hide me and set me above
to sing this song of love.
One thing I will ask of You, this will I pray:
to dwell in Your house, O Lord, every day;
to gaze upon Your lovely face,
and rest in the Father’s embrace.
Teach me Your way, Lord,
make straight the path before me.
Do not forsake me, my hope is in You.
As I walk through life I am confident
I will see Your goodness with every step,
and my heart directs me to seek You in all that I do,
so I will wait for You.
One thing I will ask of You...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1134', 'Stuart Townend');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1134', 'Stuart Townend');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1134', 'verse', 1, 0, '[\"You are my anchor, my light and my salvation.\",\"You are my refuge, my heart will not fear.\",\"Though my foes surround me on every hand,\",\"they will stumble and fall while in grace I stand.\",\"In my day of trouble, You hide me and set me above\",\"to sing this song of love.\",\"One thing I will ask of You, this will I pray:\",\"to dwell in Your house, O Lord, every day;\",\"to gaze upon Your lovely face,\",\"and rest in the Father’s embrace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1134', 'verse', 2, 1, '[\"Teach me Your way, Lord,\",\"make straight the path before me.\",\"Do not forsake me, my hope is in You.\",\"As I walk through life I am confident\",\"I will see Your goodness with every step,\",\"and my heart directs me to seek You in all that I do,\",\"so I will wait for You.\",\"One thing I will ask of You...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1135', 1135, 'You are my king', 'MP', 'en', 'Mercy/Vineyard Publishing/Vineyard Songs Canada/Song Solutions CopyCare www.songsolutions.org', '', 0, 0, 0, 1, 1, 'You are my King (You are my King),
and I love You.
You are my King (You are my King),
and I worship You,
kneeling before You now,
all of my life I gladly give to You.
You are my King...
Placing my hopes and dreams
in Your hands.
I give my heart to You.
I love You, love You, Jesus.
Yes, I love You, love You, Jesus,
my King.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1135', 'Brian Doerksen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1135', 'Brian Doerksen');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1135', 'verse', 1, 0, '[\"You are my King (You are my King),\",\"and I love You.\",\"You are my King (You are my King),\",\"and I worship You,\",\"kneeling before You now,\",\"all of my life I gladly give to You.\",\"You are my King...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1135', 'chorus', 0, 1, '[\"Placing my hopes and dreams\",\"in Your hands.\",\"I give my heart to You.\",\"I love You, love You, Jesus.\",\"Yes, I love You, love You, Jesus,\",\"my King.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1136', 1136, 'You are righteous', 'MP', 'en', 'Wondrous Worship (Adm Music Service/Song Solutions www.songsolutions.org). All rights reserved Used by permission.', '', 0, 0, 0, 1, 0, 'You are righteous, You love justice,
and those who honour You will see Your face.
I will arise and lift my eyes
to see Your majesty, Your holiness.
And all I am will bless You.
My hope is in the name of the Lord,
where my help comes from.
You’re my strength, my song.
My trust is in the name of the Lord.
I will sing Your praise,
You are faithful.
You are righteous...
My hope is in the name...
My hope is in the name...
You are faithful,
You are faithful,
You are faithful.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1136', 'Darlene Zschech');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1136', 'Darlene Zschech');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1136', 'verse', 1, 0, '[\"You are righteous, You love justice,\",\"and those who honour You will see Your face.\",\"I will arise and lift my eyes\",\"to see Your majesty, Your holiness.\",\"And all I am will bless You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1136', 'chorus', 0, 1, '[\"My hope is in the name of the Lord,\",\"where my help comes from.\",\"You’re my strength, my song.\",\"My trust is in the name of the Lord.\",\"I will sing Your praise,\",\"You are faithful.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1136', 'chorus', 0, 2, '[\"You are righteous...\",\"My hope is in the name...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1136', 'chorus', 0, 3, '[\"My hope is in the name...\",\"You are faithful,\",\"You are faithful,\",\"You are faithful.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1137', 1137, 'You are the Lord', 'MP', 'en', '© 2002 Integrity\'s Hosanna! Music (adm worldwide by Capitol CMG Publishing excl UK admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com)/Song Solutions Daybreak/Mick Goss Designee (Used by Permission', '', 0, 0, 0, 1, 1, 'You are the Lord, the King of heaven
and all the earth, You’ll reign for ever.
First and the last, You are glorious.
Before Your throne the elders fall,
and angels sing: ‘Almighty God’.
Bright Morning Star,
You are glorious, You are glorious.
To You the nations will come,
every tribe, every tongue,
and worship before You,
the Ancient of days,
the Name above all names,
who is worthy of all our praise.
You are glorious.
Yeah, You are glorious.
You are the Lord...
To you...
Glorious, glorious.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1137', 'Eoghan Heaslip');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1137', 'Mick Goss');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1137', 'Eoghan Heaslip');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1137', 'Mick Goss');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1137', 'verse', 1, 0, '[\"You are the Lord, the King of heaven\",\"and all the earth, You’ll reign for ever.\",\"First and the last, You are glorious.\",\"Before Your throne the elders fall,\",\"and angels sing: ‘Almighty God’.\",\"Bright Morning Star,\",\"You are glorious, You are glorious.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1137', 'chorus', 0, 1, '[\"To You the nations will come,\",\"every tribe, every tongue,\",\"and worship before You,\",\"the Ancient of days,\",\"the Name above all names,\",\"who is worthy of all our praise.\",\"You are glorious.\",\"Yeah, You are glorious.\",\"You are the Lord...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1137', 'chorus', 0, 2, '[\"To you...\",\"Glorious, glorious.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1138', 1138, 'Your name is holy', 'MP', 'en', '1999 Vineyard Songs UK/Eire (Admin. by Song Solutions CopyCare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'You are the sovereign ‘I Am’,
Your name is holy.
You are the pure spotless Lamb,
Your name is holy.
You are the almighty One,
Your name is holy.
You are the Christ, God’s own Son,
Your name is holy.
In Your name, there is mercy for sin,
safety within,
in Your holy name.
In Your name, strength to remain,
to stand in spite of pain,
in Your holy name.
You are the sovereign ‘I Am’...
You are the almighty One...
Your name is holy,
Your name is holy.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1138', 'Brian Doerksen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1138', 'Brian Doerksen');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1138', 'verse', 1, 0, '[\"You are the sovereign ‘I Am’,\",\"Your name is holy.\",\"You are the pure spotless Lamb,\",\"Your name is holy.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1138', 'verse', 2, 1, '[\"You are the almighty One,\",\"Your name is holy.\",\"You are the Christ, God’s own Son,\",\"Your name is holy.\",\"In Your name, there is mercy for sin,\",\"safety within,\",\"in Your holy name.\",\"In Your name, strength to remain,\",\"to stand in spite of pain,\",\"in Your holy name.\",\"You are the sovereign ‘I Am’...\",\"You are the almighty One...\",\"Your name is holy,\",\"Your name is holy.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1139', 1139, 'Lost in wonder', 'MP', 'en', '©  2002 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'You chose the cross with every breath,
the perfect life, the perfect death:
You chose the cross.
A crown of thorns You wore for us,
and crowned us with eternal life:
You chose the cross.
And though Your soul was overwhelmed with pain,
obedience to death You overcame.
I’m lost in wonder,
I’m lost in love,
I’m lost in praise for evermore.
Because of Jesus’ unfailing love,
I am forgiven,
I am restored.
You loosed the cords of sinfulness
and broke the chains of my disgrace:
You chose the cross.
Up from the grave victorious
You rose again so glorious:
You chose the cross.
The sorrow that surrounded You was mine,
‘Yet not my will but Yours be done,’ You said.
I’m lost in wonder...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1139', 'Martyn Layzell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1139', 'Martyn Layzell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1139', 'verse', 1, 0, '[\"You chose the cross with every breath,\",\"the perfect life, the perfect death:\",\"You chose the cross.\",\"A crown of thorns You wore for us,\",\"and crowned us with eternal life:\",\"You chose the cross.\",\"And though Your soul was overwhelmed with pain,\",\"obedience to death You overcame.\",\"I’m lost in wonder,\",\"I’m lost in love,\",\"I’m lost in praise for evermore.\",\"Because of Jesus’ unfailing love,\",\"I am forgiven,\",\"I am restored.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1139', 'verse', 2, 1, '[\"You loosed the cords of sinfulness\",\"and broke the chains of my disgrace:\",\"You chose the cross.\",\"Up from the grave victorious\",\"You rose again so glorious:\",\"You chose the cross.\",\"The sorrow that surrounded You was mine,\",\"‘Yet not my will but Yours be done,’ You said.\",\"I’m lost in wonder...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1140', 1140, 'Praise You', 'MP', 'en', '©  2002 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'You gave Your only Son,
came down from heaven above,
endured the cross, so I might know
this love that reached for me,
a love that sets me free,
Your sacrifice has saved my soul.
Today I’m reminded of Your grace;
always living now to sing Your praise,
Your praise.
Praise You, Jesus, I praise You,
I lift my hands and sing.
Embrace You, I will embrace You,
My Saviour and my King, my King.
I could not earn this love,
such undeserved love;
Jesus, I know You are the way.
You paid the price for me,
Your blood was shed for me,
and in Your mercy took my place.
Today I’m reminded...
Praise You, Jesus...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1140', 'Martyn Layzell');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1140', 'Martyn Layzell');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1140', 'verse', 1, 0, '[\"You gave Your only Son,\",\"came down from heaven above,\",\"endured the cross, so I might know\",\"this love that reached for me,\",\"a love that sets me free,\",\"Your sacrifice has saved my soul.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1140', 'chorus', 0, 1, '[\"Today I’m reminded of Your grace;\",\"always living now to sing Your praise,\",\"Your praise.\",\"Praise You, Jesus, I praise You,\",\"I lift my hands and sing.\",\"Embrace You, I will embrace You,\",\"My Saviour and my King, my King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1140', 'verse', 2, 2, '[\"I could not earn this love,\",\"such undeserved love;\",\"Jesus, I know You are the way.\",\"You paid the price for me,\",\"Your blood was shed for me,\",\"and in Your mercy took my place.\",\"Today I’m reminded...\",\"Praise You, Jesus...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1141', 1141, 'Across the lands', 'MP', 'en', '(c) 2002 Thankyou Music/Adm. by Capitol CMG Publishing worldwide excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'You’re the word of God the Father,');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1141', 'Stuart Townend');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1141', 'Keith Getty');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1141', 'Stuart Townend');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1141', 'Keith Getty');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1141', 'verse', 1, 0, '[\"You’re the word of God the Father,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1142', 1142, 'I will run to you', 'MP', 'en', 'Wondrous Worship (Adm Music Service/Song Solutions www.songsolutions.org). All rights reserved Used by permission.', '', 0, 0, 0, 1, 0, 'Your eye is on the sparrow,
and Your hand, it comforts me.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1142', 'Darlene Zschech');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1142', 'Darlene Zschech');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1142', 'verse', 1, 0, '[\"Your eye is on the sparrow,\",\"and Your hand, it comforts me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1143', 1143, 'Hallelujah', 'MP', 'en', '2000 Vineyard Songs (Admin.by Song Solutions Copycare www.songsolutions.org)', '', 0, 0, 0, 1, 1, 'Your love is amazing,
steady and unchanging;
Your love is a mountain
firm beneath my feet.
Your love is a mystery,
how You gently lift me;
when I am surrounded,
Your love carries me.
Hallelujah, hallelujah,
hallelujah, Your love makes me sing.
Hallelujah, hallelujah,
hallelujah, Your love makes me sing.
Your love is surprising,
I can feel it rising,
all the joy that’s growing
deep inside of me.
Every time I see You,
all Your goodness shines through,
and I can feel this God song
rising up in me.
Hallelujah...
Your love is amazing...
Hallelujah...
Yes, You make me sing,
Lord, You make me sing, sing, sing,
how You make me sing.
Hallelujah...
Lord, You make me sing,
how You make me sing.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1143', 'Brenton Brown');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1143', 'Brian Doerksen');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1143', 'Brenton Brown');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1143', 'Brian Doerksen');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1143', 'verse', 1, 0, '[\"Your love is amazing,\",\"steady and unchanging;\",\"Your love is a mountain\",\"firm beneath my feet.\",\"Your love is a mystery,\",\"how You gently lift me;\",\"when I am surrounded,\",\"Your love carries me.\",\"Hallelujah, hallelujah,\",\"hallelujah, Your love makes me sing.\",\"Hallelujah, hallelujah,\",\"hallelujah, Your love makes me sing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1143', 'verse', 2, 1, '[\"Your love is surprising,\",\"I can feel it rising,\",\"all the joy that’s growing\",\"deep inside of me.\",\"Every time I see You,\",\"all Your goodness shines through,\",\"and I can feel this God song\",\"rising up in me.\",\"Hallelujah...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1143', 'verse', 3, 2, '[\"Your love is amazing...\",\"Hallelujah...\",\"Yes, You make me sing,\",\"Lord, You make me sing, sing, sing,\",\"how You make me sing.\",\"Hallelujah...\",\"Lord, You make me sing,\",\"how You make me sing.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1144', 1144, 'Draw me near to you', 'MP', 'en', '©  2000 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 1, 'Your love is better than wine,
Your name like sweetest perfume;
oh, that You would kiss me
with the kisses of Your mouth
and draw me, draw me after You.
I hear You whisper my name,
And like a moth to the flame
I fly into the fire of Your intimate love
as You draw me, draw me after You.
(Come and draw me deeper.)
Draw me after You,
draw me after you,
draw me after you
and let us run together.
Draw me after you...
Your love is better than wine...
Draw me after You...
Jesus, You’re the One,
Jesus, You’re the One,
Jesus, You’re the One
that I will love for ever.
Jesus, You’re the One,
Jesus, You’re the One,
Jesus, You’re the One
that I will love for ever more.
So amazing, so divine,
I am Yours and You are mine.
For such love there are no words,
’cause loving You is heaven on earth.
Jesus, You’re the One...');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1144', 'Robert Critchley');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1144', 'Robert Critchley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1144', 'chorus', 0, 0, '[\"Your love is better than wine,\",\"Your name like sweetest perfume;\",\"oh, that You would kiss me\",\"with the kisses of Your mouth\",\"and draw me, draw me after You.\",\"I hear You whisper my name,\",\"And like a moth to the flame\",\"I fly into the fire of Your intimate love\",\"as You draw me, draw me after You.\",\"(Come and draw me deeper.)\",\"Draw me after You,\",\"draw me after you,\",\"draw me after you\",\"and let us run together.\",\"Draw me after you...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1144', 'chorus', 0, 1, '[\"Your love is better than wine...\",\"Draw me after You...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1144', 'chorus', 0, 2, '[\"Jesus, You’re the One,\",\"Jesus, You’re the One,\",\"Jesus, You’re the One\",\"that I will love for ever.\",\"Jesus, You’re the One,\",\"Jesus, You’re the One,\",\"Jesus, You’re the One\",\"that I will love for ever more.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1144', 'chorus', 0, 3, '[\"So amazing, so divine,\",\"I am Yours and You are mine.\",\"For such love there are no words,\",\"’cause loving You is heaven on earth.\",\"Jesus, You’re the One...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1145', 1145, 'God is great', 'MP', 'en', '', '', 0, 0, 0, 1, 1, '1 All creation cries to You,
worshipping in spirit and in truth.
Glory to the Faithful One,
Jesus Christ, God’s Son.
2 All creation gives You praise,
You alone are truly great,
You alone are God who reigns
for eternity.
God is great, and His praise
fills the earth, fills the heavens,
and Your name will be praised
through all the world.
God is great, sing His praise
all the earth, all the heavens,
’cause we’re living for the glory of Your name,
the glory of Your name.
3 All to You, O God we bring.
Jesus, teach us how to live.
Let Your fire burn in us
that all may hear,
and all may see.
God is great...
‘Holy is the Lord,’
the whole earth sings,
the whole earth sings.
(4 times)
God is great...
Words and Music: Marty Sampson
Words & Music by Marty Sampson © 2001 Hillsong Music Publishing CCLI: 3375851');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1145', 'verse', 1, 0, '[\"1 All creation cries to You,\",\"worshipping in spirit and in truth.\",\"Glory to the Faithful One,\",\"Jesus Christ, God’s Son.\",\"2 All creation gives You praise,\",\"You alone are truly great,\",\"You alone are God who reigns\",\"for eternity.\",\"God is great, and His praise\",\"fills the earth, fills the heavens,\",\"and Your name will be praised\",\"through all the world.\",\"God is great, sing His praise\",\"all the earth, all the heavens,\",\"’cause we’re living for the glory of Your name,\",\"the glory of Your name.\",\"3 All to You, O God we bring.\",\"Jesus, teach us how to live.\",\"Let Your fire burn in us\",\"that all may hear,\",\"and all may see.\",\"God is great...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1145', 'chorus', 0, 1, '[\"‘Holy is the Lord,’\",\"the whole earth sings,\",\"the whole earth sings.\",\"(4 times)\",\"God is great...\",\"Words and Music: Marty Sampson\",\"Words & Music by Marty Sampson © 2001 Hillsong Music Publishing CCLI: 3375851\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1146', 1146, 'Each perfect gift has come from You', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'All I am I offer to You,
all I have is Yours.
My all I give away;
take this life I lay before You.
Each perfect gift has come from You,
yet I cling tightly.
And I pray, O Lord, release my grip,
so I give gladly.
All I am...
Your fingerprints reveal the plan
for this world’s story.
We have no other purpose than
to give You glory.
All I am...
For I am broken, but I am chosen,
for You have spoken grace to me.
Yes, I am broken, but I am chosen,
for You have spoken grace to me.
All I am...
Your footsteps mark the path of peace
but this road is narrow;
it leads me only to a cross,
Lord, I will follow.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1146', 'chorus', 0, 0, '[\"All I am I offer to You,\",\"all I have is Yours.\",\"My all I give away;\",\"take this life I lay before You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1146', 'verse', 1, 1, '[\"Each perfect gift has come from You,\",\"yet I cling tightly.\",\"And I pray, O Lord, release my grip,\",\"so I give gladly.\",\"All I am...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1146', 'verse', 2, 2, '[\"Your fingerprints reveal the plan\",\"for this world’s story.\",\"We have no other purpose than\",\"to give You glory.\",\"All I am...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1146', 'chorus', 0, 3, '[\"For I am broken, but I am chosen,\",\"for You have spoken grace to me.\",\"Yes, I am broken, but I am chosen,\",\"for You have spoken grace to me.\",\"All I am...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1146', 'verse', 3, 4, '[\"Your footsteps mark the path of peace\",\"but this road is narrow;\",\"it leads me only to a cross,\",\"Lord, I will follow.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1147', 1147, 'All I have', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'All I have, all I am, I lay down before Your throne,
for this I seek, to see the glory of the Lord.
To live is Christ, to die is gain, I give my all to bring You fame,
I live for this, to see the glory of the Lord.
For Your glory, for Your glory,
let me live, let me live.
For Your glory, for Your glory,
let me live.
The things behind, I will leave, for I know I will receive
the final prize, to see the glory of the Lord.
I long to hear my Father say: ‘You have done well, you’ve kept the faith,
now enter in and see the glory of the Lord.’
For Your glory...
This I pray for, this I long for,
this I hope for, this I live for.
This I pray for, this I long for;
to see Your glory come on earth.
For Your glory...
Words and Music: Matt Osgood
Words and music: ©  Matt Osgood/RESOUND/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1147', 'verse', 1, 0, '[\"All I have, all I am, I lay down before Your throne,\",\"for this I seek, to see the glory of the Lord.\",\"To live is Christ, to die is gain, I give my all to bring You fame,\",\"I live for this, to see the glory of the Lord.\",\"For Your glory, for Your glory,\",\"let me live, let me live.\",\"For Your glory, for Your glory,\",\"let me live.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1147', 'verse', 2, 1, '[\"The things behind, I will leave, for I know I will receive\",\"the final prize, to see the glory of the Lord.\",\"I long to hear my Father say: ‘You have done well, you’ve kept the faith,\",\"now enter in and see the glory of the Lord.’\",\"For Your glory...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1147', 'chorus', 0, 2, '[\"This I pray for, this I long for,\",\"this I hope for, this I live for.\",\"This I pray for, this I long for;\",\"to see Your glory come on earth.\",\"For Your glory...\",\"Words and Music: Matt Osgood\",\"Words and music: ©  Matt Osgood\\/RESOUND\\/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1148', 1148, 'Ever faithful God', 'MP', 'en', '©  2005 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'All glory to the King of ages.
All glory to the King of kings.
His name is love, His name is Jesus,
enthroned above in majesty.
Into this world You came to save us,
You bore the cross, You took my sin.
You shone Your light into my darkness,
unveiled the truth, this mystery.
You are my God, You are my Saviour,
You are the Rock on which I stand.
Ever faithful God, I cling to You,
in every way You’ve shown that You are good.
There’s no other love compares with You,
forever strong, forever true.
Ever faithful God, I cling to You.
You are the end of all my searching,
You pour Your grace on all my need.
Unfailing love, unending mercy
are found in You, the Prince of peace.
You are my God, You are my Saviour,
You are the Rock on which I stand.
Ever faithful God...
You are my God, You are my Saviour,
You are the Rock on which I stand.
You are my God, You are my Saviour,
Eternal One, the great ‘I Am’.
Ever faithful God...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1148', 'verse', 1, 0, '[\"All glory to the King of ages.\",\"All glory to the King of kings.\",\"His name is love, His name is Jesus,\",\"enthroned above in majesty.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1148', 'verse', 2, 1, '[\"Into this world You came to save us,\",\"You bore the cross, You took my sin.\",\"You shone Your light into my darkness,\",\"unveiled the truth, this mystery.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1148', 'chorus', 0, 2, '[\"You are my God, You are my Saviour,\",\"You are the Rock on which I stand.\",\"Ever faithful God, I cling to You,\",\"in every way You’ve shown that You are good.\",\"There’s no other love compares with You,\",\"forever strong, forever true.\",\"Ever faithful God, I cling to You.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1148', 'verse', 3, 3, '[\"You are the end of all my searching,\",\"You pour Your grace on all my need.\",\"Unfailing love, unending mercy\",\"are found in You, the Prince of peace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1148', 'chorus', 0, 4, '[\"You are my God, You are my Saviour,\",\"You are the Rock on which I stand.\",\"Ever faithful God...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1148', 'chorus', 0, 5, '[\"You are my God, You are my Saviour,\",\"You are the Rock on which I stand.\",\"You are my God, You are my Saviour,\",\"Eternal One, the great ‘I Am’.\",\"Ever faithful God...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1149', 1149, 'All shall be well', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'All shall be well! For on our Easter skies
see Christ the sun of righteousness arise.
All shall be well! The sacrifice is made;
the sinner freed, the price of pardon paid.
All shall be well! The cross and passion past;
dark night is done, bright morning come at last.
All shall be well! Within our Father’s plan
death has no more dominion over man.
Jesus alive! Rejoice and sing again,
‘All shall be well for evermore, Amen!’
\'All shall be well\'  by Timothy Dudley-Smith (b. 1926) © Timothy Dudley-Smith in Europe and Africa. © Hope Publishing Company in the United States of America and the rest of the world. Reproduced by permission of Oxford University Press. All rights reserved.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1149', 'verse', 1, 0, '[\"All shall be well! For on our Easter skies\",\"see Christ the sun of righteousness arise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1149', 'verse', 2, 1, '[\"All shall be well! The sacrifice is made;\",\"the sinner freed, the price of pardon paid.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1149', 'verse', 3, 2, '[\"All shall be well! The cross and passion past;\",\"dark night is done, bright morning come at last.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1149', 'verse', 4, 3, '[\"All shall be well! Within our Father’s plan\",\"death has no more dominion over man.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1149', 'verse', 5, 4, '[\"Jesus alive! Rejoice and sing again,\",\"‘All shall be well for evermore, Amen!’\",\"\'All shall be well\'  by Timothy Dudley-Smith (b. 1926) © Timothy Dudley-Smith in Europe and Africa. © Hope Publishing Company in the United States of America and the rest of the world. Reproduced by permission of Oxford University Press. All rights reserved.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1150', 1150, 'The voice of hope', 'MP', 'en', '©  2002 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'As high as the heavens are above the earth,
so high are Your ways to mine.
Ways so perfect they never fail me,
I know You are good all the time!
And through the storm yet I will praise You,
despite it all yet I will sing;
through good or bad yet I will worship,
for You remain the same King of kings.
You are the voice of hope,
the anchor of my soul.
Where there seems to be no way,
You make it possible.
You are the Prince of peace,
amidst adversity
my lips will shout for joy
to You the Most High!
You were the One before time began;
there’s nothing beyond Your control.
My confidence, my assurance,
rest in Your unchanging word!
And through the storm yet I will praise You,
despite it all yet I will sing;
through good or bad yet I will worship,
for You remain the same King of kings.
You are the voice...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1150', 'verse', 1, 0, '[\"As high as the heavens are above the earth,\",\"so high are Your ways to mine.\",\"Ways so perfect they never fail me,\",\"I know You are good all the time!\",\"And through the storm yet I will praise You,\",\"despite it all yet I will sing;\",\"through good or bad yet I will worship,\",\"for You remain the same King of kings.\",\"You are the voice of hope,\",\"the anchor of my soul.\",\"Where there seems to be no way,\",\"You make it possible.\",\"You are the Prince of peace,\",\"amidst adversity\",\"my lips will shout for joy\",\"to You the Most High!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1150', 'verse', 2, 1, '[\"You were the One before time began;\",\"there’s nothing beyond Your control.\",\"My confidence, my assurance,\",\"rest in Your unchanging word!\",\"And through the storm yet I will praise You,\",\"despite it all yet I will sing;\",\"through good or bad yet I will worship,\",\"for You remain the same King of kings.\",\"You are the voice...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1151', 1151, 'My chains are gone', 'MP', 'en', '© 2006 worshiptogether.com Songs/sixsteps Music/Vamos Publishing (Admin by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com) Used by permission.', '', 0, 0, 0, 1, 0, 'Amazing grace! How sweet the sound
that saved a wretch like me;
I once was lost, but now am found,
was blind, but now I see.
’Twas grace that taught my heart to fear,
and grace my fears relieved;
how precious did that grace appear
the hour I first believed.
My chains are gone, I’ve been set free,
my God, my Saviour has ransomed me.
And like a flood His mercy reigns,
unending love, amazing grace.
The Lord has promised good to me,
His word my hope secures;
He will my shield and portion be
as long as life endures.
My chains are gone...
My chains are gone...
The earth shall soon dissolve like snow,
the sun forbear to shine.
But God who called me here below
will be forever mine.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1151', 'verse', 1, 0, '[\"Amazing grace! How sweet the sound\",\"that saved a wretch like me;\",\"I once was lost, but now am found,\",\"was blind, but now I see.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1151', 'verse', 2, 1, '[\"’Twas grace that taught my heart to fear,\",\"and grace my fears relieved;\",\"how precious did that grace appear\",\"the hour I first believed.\",\"My chains are gone, I’ve been set free,\",\"my God, my Saviour has ransomed me.\",\"And like a flood His mercy reigns,\",\"unending love, amazing grace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1151', 'verse', 3, 2, '[\"The Lord has promised good to me,\",\"His word my hope secures;\",\"He will my shield and portion be\",\"as long as life endures.\",\"My chains are gone...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1151', 'chorus', 0, 3, '[\"My chains are gone...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1151', 'verse', 4, 4, '[\"The earth shall soon dissolve like snow,\",\"the sun forbear to shine.\",\"But God who called me here below\",\"will be forever mine.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1152', 1152, 'Your name', 'MP', 'en', '© 2006 Integrity\'s Hosanna! Music & Vertical Worship Songs(admin by CAPITOL CMG Publishing worldwide excl. the UK which is admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com ) Used by Permission', '', 0, 0, 0, 1, 0, 'As morning dawns and evening fades,
You inspire songs of praise
that rise from earth to touch Your heart,
and glorify Your name.
Your name is a strong and mighty tower.
Your name is a shelter like no other.
Your name, let the nations sing it louder,
’cause nothing has the power to save
but Your name.
Jesus, in Your name we pray,
come and fill our hearts today.
Lord, give us strength to live for You
and glorify Your name.
Your name...
Your name...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1152', 'verse', 1, 0, '[\"As morning dawns and evening fades,\",\"You inspire songs of praise\",\"that rise from earth to touch Your heart,\",\"and glorify Your name.\",\"Your name is a strong and mighty tower.\",\"Your name is a shelter like no other.\",\"Your name, let the nations sing it louder,\",\"’cause nothing has the power to save\",\"but Your name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1152', 'verse', 2, 1, '[\"Jesus, in Your name we pray,\",\"come and fill our hearts today.\",\"Lord, give us strength to live for You\",\"and glorify Your name.\",\"Your name...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1152', 'chorus', 0, 2, '[\"Your name...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1153', 1153, 'As one in Christ the Lord', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'As one in Christ the Lord
His glories here proclaim,
exalt His holy word,
His everlasting name:
let love and praise
unite our powers
for we are Christ’s
and Christ is ours.
On Him our hope is set,
whose cross is strong to save;
nor shall our hearts forget
that empty Easter grave:
with Him we rise,
our sins forgiven,
to share with Him
the life of heaven.
Be ours to use aright
the gifts of thought and mind,
in scripture take delight,
and God’s approval find:
till through the Spirit
and the word
there stands revealed
the living Lord.
Whom Jesus calls He sends,
to make His mercies known:
ambassadors and friends,
the heralds of His throne.
His word of truth
and life declare:
with all the world
His gospel share.
To follow Christ our aim,
in Him to stand complete,
that all may hear His name
and bow before His feet:
the faith to keep,
the race to run,
and hear at last
the Lord’s ‘Well done!’
\'As one in Christ the Lord\'  by Timothy Dudley-Smith (b. 1926) © Timothy Dudley-Smith in Europe and Africa. © Hope Publishing Company in the United States of America and the rest of the world. Reproduced by permission of Oxford University Press. All rights reserved.            Music arrangement: © David Peacock /The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1153', 'verse', 1, 0, '[\"As one in Christ the Lord\",\"His glories here proclaim,\",\"exalt His holy word,\",\"His everlasting name:\",\"let love and praise\",\"unite our powers\",\"for we are Christ’s\",\"and Christ is ours.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1153', 'verse', 2, 1, '[\"On Him our hope is set,\",\"whose cross is strong to save;\",\"nor shall our hearts forget\",\"that empty Easter grave:\",\"with Him we rise,\",\"our sins forgiven,\",\"to share with Him\",\"the life of heaven.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1153', 'verse', 3, 2, '[\"Be ours to use aright\",\"the gifts of thought and mind,\",\"in scripture take delight,\",\"and God’s approval find:\",\"till through the Spirit\",\"and the word\",\"there stands revealed\",\"the living Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1153', 'verse', 4, 3, '[\"Whom Jesus calls He sends,\",\"to make His mercies known:\",\"ambassadors and friends,\",\"the heralds of His throne.\",\"His word of truth\",\"and life declare:\",\"with all the world\",\"His gospel share.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1153', 'verse', 5, 4, '[\"To follow Christ our aim,\",\"in Him to stand complete,\",\"that all may hear His name\",\"and bow before His feet:\",\"the faith to keep,\",\"the race to run,\",\"and hear at last\",\"the Lord’s ‘Well done!’\",\"\'As one in Christ the Lord\'  by Timothy Dudley-Smith (b. 1926) © Timothy Dudley-Smith in Europe and Africa. © Hope Publishing Company in the United States of America and the rest of the world. Reproduced by permission of Oxford University Press. All rights reserved.            Music arrangement: © David Peacock \\/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1154', 1154, 'How long?', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'As we bring our songs of love today,
do you hear a sound more glorious?
Like the mighty roar of ocean waves,
many witnesses surround us.
It’s a harmony of costly praise');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1154', 'verse', 1, 0, '[\"As we bring our songs of love today,\",\"do you hear a sound more glorious?\",\"Like the mighty roar of ocean waves,\",\"many witnesses surround us.\",\"It’s a harmony of costly praise\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1155', 1155, 'Beauty unspoken', 'MP', 'en', '©  2007 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Beauty unspoken,
glory unchanging,
maker of the stars above.
God uncreated,
made Yourself nothing;
carrying the cross for love.
Thank You, God,
thank You, God,
thank You, God,
for saving me.
Light in the darkness,
one with the Father,
the beginning and the end.
Lifter of burdens,
bruised and forsaken,
Jesus Christ the sinner’s friend.
Thank You, God...
You are love never ending,
Your grace overwhelming;
crucified for me.
And this blood, never failing,
Your mercy unveiling,
given Lord for me.
You are love...
Thank You, God...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1155', 'verse', 1, 0, '[\"Beauty unspoken,\",\"glory unchanging,\",\"maker of the stars above.\",\"God uncreated,\",\"made Yourself nothing;\",\"carrying the cross for love.\",\"Thank You, God,\",\"thank You, God,\",\"thank You, God,\",\"for saving me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1155', 'verse', 2, 1, '[\"Light in the darkness,\",\"one with the Father,\",\"the beginning and the end.\",\"Lifter of burdens,\",\"bruised and forsaken,\",\"Jesus Christ the sinner’s friend.\",\"Thank You, God...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1155', 'chorus', 0, 2, '[\"You are love never ending,\",\"Your grace overwhelming;\",\"crucified for me.\",\"And this blood, never failing,\",\"Your mercy unveiling,\",\"given Lord for me.\",\"You are love...\",\"Thank You, God...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1156', 1156, 'So You would come', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Before the world began
you were on His mind,
and every tear you cry
is precious in His eyes.
Because of His great love,
He gave His only Son;
everything was done
so you would come.
Nothing you can do
could make Him love you more,
and nothing that you’ve done
could make Him close the door.
Because of His great love,
He gave His only Son;
everything was done
so you would come.
Come to the Father
though your gift is small,
broken hearts, broken lives,
He will take them all.
The power of the word,
the power of His blood,
everything was done
so you would come.
Words & Music by Russell Fragar © 1996 Hillsong Music Publishing CCLI: 2109042');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1156', 'verse', 1, 0, '[\"Before the world began\",\"you were on His mind,\",\"and every tear you cry\",\"is precious in His eyes.\",\"Because of His great love,\",\"He gave His only Son;\",\"everything was done\",\"so you would come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1156', 'verse', 2, 1, '[\"Nothing you can do\",\"could make Him love you more,\",\"and nothing that you’ve done\",\"could make Him close the door.\",\"Because of His great love,\",\"He gave His only Son;\",\"everything was done\",\"so you would come.\",\"Come to the Father\",\"though your gift is small,\",\"broken hearts, broken lives,\",\"He will take them all.\",\"The power of the word,\",\"the power of His blood,\",\"everything was done\",\"so you would come.\",\"Words & Music by Russell Fragar © 1996 Hillsong Music Publishing CCLI: 2109042\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1157', 1157, 'The Communion hymn', 'MP', 'en', '© 2006 Thankyou Music/Adm. by Capitol CMG Publishing worldwide excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Behold the Lamb who bears our sins away,
slain for us: and we remember
the promise made that all who come in faith
find forgiveness at the cross.
So we share in this bread of life,
and we drink of His sacrifice,
as a sign of our bonds of peace
around the table of the King.
The body of our Saviour, Jesus Christ,
torn for you: eat and remember
the wounds that heal, the death that brings us life,
paid the price to make us one.
So we share in this bread of life,
and we drink of His sacrifice,
as a sign of our bonds of love
around the table of the King.
The blood that cleanses every stain of sin,
shed for you: drink and remember
He drained death’s cup that all may enter in
to receive the life of God.
So we share in this bread of life,
and we drink of His sacrifice,
as a sign of our bonds of grace
around the table of the King.
And so with thankfulness and faith we rise
to respond, and to remember
our call to follow in the steps of Christ
as His body here on earth.
As we share in His suffering,
we proclaim: Christ will come again!
And we’ll join in the feast of heaven
around the table of the King.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1157', 'verse', 1, 0, '[\"Behold the Lamb who bears our sins away,\",\"slain for us: and we remember\",\"the promise made that all who come in faith\",\"find forgiveness at the cross.\",\"So we share in this bread of life,\",\"and we drink of His sacrifice,\",\"as a sign of our bonds of peace\",\"around the table of the King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1157', 'verse', 2, 1, '[\"The body of our Saviour, Jesus Christ,\",\"torn for you: eat and remember\",\"the wounds that heal, the death that brings us life,\",\"paid the price to make us one.\",\"So we share in this bread of life,\",\"and we drink of His sacrifice,\",\"as a sign of our bonds of love\",\"around the table of the King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1157', 'verse', 3, 2, '[\"The blood that cleanses every stain of sin,\",\"shed for you: drink and remember\",\"He drained death’s cup that all may enter in\",\"to receive the life of God.\",\"So we share in this bread of life,\",\"and we drink of His sacrifice,\",\"as a sign of our bonds of grace\",\"around the table of the King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1157', 'verse', 4, 3, '[\"And so with thankfulness and faith we rise\",\"to respond, and to remember\",\"our call to follow in the steps of Christ\",\"as His body here on earth.\",\"As we share in His suffering,\",\"we proclaim: Christ will come again!\",\"And we’ll join in the feast of heaven\",\"around the table of the King.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1158', 1158, 'Beneath the cross of Jesus', 'MP', 'en', '© 2005 Thankyou Music/Adm. by worshiptogether.com Songs excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Beneath the cross of Jesus,
I find a place to stand;
and wonder at such mercy
that calls me as I am.
For hands that should discard me
hold wounds which tell me ‘Come’.
Beneath the cross of Jesus
my unworthy soul is won.
Beneath the cross of Jesus
His family is my own;
once strangers chasing selfish dreams,
now one through grace alone.
How could I now dishonour
the ones that You have loved?
Beneath the cross of Jesus
see the children called by God.
Beneath the cross of Jesus,
the path before the crown,
we follow in His footsteps
where promised hope is found.
How great the joy before us –
to be His perfect bride.
Beneath the cross of Jesus
we will gladly live our lives.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1158', 'verse', 1, 0, '[\"Beneath the cross of Jesus,\",\"I find a place to stand;\",\"and wonder at such mercy\",\"that calls me as I am.\",\"For hands that should discard me\",\"hold wounds which tell me ‘Come’.\",\"Beneath the cross of Jesus\",\"my unworthy soul is won.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1158', 'verse', 2, 1, '[\"Beneath the cross of Jesus\",\"His family is my own;\",\"once strangers chasing selfish dreams,\",\"now one through grace alone.\",\"How could I now dishonour\",\"the ones that You have loved?\",\"Beneath the cross of Jesus\",\"see the children called by God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1158', 'verse', 3, 2, '[\"Beneath the cross of Jesus,\",\"the path before the crown,\",\"we follow in His footsteps\",\"where promised hope is found.\",\"How great the joy before us –\",\"to be His perfect bride.\",\"Beneath the cross of Jesus\",\"we will gladly live our lives.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1159', 1159, 'Blessed are the people', 'MP', 'en', '©  2007 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Blessèd are the people who know the joyful sound.
Blessèd are the people who know the joyful sound.
Hear the sound of the trumpets, hear the voice of the Lord,
it’s the year of God’s favour and salvation joy.
Blessèd are the people who know the joyful sound.
Oh, can you hear it, can you hear it,
can you hear it, can you hear it?
It’s the sound of revival.
Blessèd are the people who know that God is good.
Blessèd are the people who know that God is good,
who know the joy of forgiveness, all their sins washed away.
Hear the sound of the gospel, it’s still breaking the chains.
Blessèd are the people who know that God is good.
Oh, can you hear it...
Hear the sound of creation.
See the seasons, how they change.
The sustainer of all life
is breathing hope in our hearts once again.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1159', 'verse', 1, 0, '[\"Blessèd are the people who know the joyful sound.\",\"Blessèd are the people who know the joyful sound.\",\"Hear the sound of the trumpets, hear the voice of the Lord,\",\"it’s the year of God’s favour and salvation joy.\",\"Blessèd are the people who know the joyful sound.\",\"Oh, can you hear it, can you hear it,\",\"can you hear it, can you hear it?\",\"It’s the sound of revival.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1159', 'verse', 2, 1, '[\"Blessèd are the people who know that God is good.\",\"Blessèd are the people who know that God is good,\",\"who know the joy of forgiveness, all their sins washed away.\",\"Hear the sound of the gospel, it’s still breaking the chains.\",\"Blessèd are the people who know that God is good.\",\"Oh, can you hear it...\",\"Hear the sound of creation.\",\"See the seasons, how they change.\",\"The sustainer of all life\",\"is breathing hope in our hearts once again.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1160', 1160, 'Raise your voices', 'MP', 'en', 'Song Solutions Daybreak www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Break our hearts and break our silence,
may this flesh spring from the word.
Shake the dust, awaken lives that
speak for those who are never heard.
Raise your voices,
cry out, cry out to Him
Raise your voices,
cry out, cry out to Him now.
Cease your singing, end your dancing
offer no more sacrifice.
Strain to hear the sounds of justice
rising up to fight for life.
Raise your voices...
Spirit of the Lord, fall afresh on me,
fill me with the love I know I need.
Spirit of the Lord, fall afresh on me,
fill me with the love I know I need.
To preach good news to the poor,
sight to the blind.
Freedom, shout freedom.
Raise your voices...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1160', 'verse', 1, 0, '[\"Break our hearts and break our silence,\",\"may this flesh spring from the word.\",\"Shake the dust, awaken lives that\",\"speak for those who are never heard.\",\"Raise your voices,\",\"cry out, cry out to Him\",\"Raise your voices,\",\"cry out, cry out to Him now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1160', 'verse', 2, 1, '[\"Cease your singing, end your dancing\",\"offer no more sacrifice.\",\"Strain to hear the sounds of justice\",\"rising up to fight for life.\",\"Raise your voices...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1160', 'chorus', 0, 2, '[\"Spirit of the Lord, fall afresh on me,\",\"fill me with the love I know I need.\",\"Spirit of the Lord, fall afresh on me,\",\"fill me with the love I know I need.\",\"To preach good news to the poor,\",\"sight to the blind.\",\"Freedom, shout freedom.\",\"Raise your voices...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1161', 1161, 'We are blessed', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Bring heaven to earth, Lord,
bring peace where there’s fear;
bring life where there’s death, Lord,
bring joy in these tears.
Bring love where there’s lust, Lord,
bring hope where there’s pain;
bring rest where there’s chaos,
bring faith where there’s fame.
You invite us to partner with You,
to see Your kingdom come.
We are blessed,
to bless a world in pieces.
We are loved,
to love where love is not.
We are changed,
to be the change You promised.
We are freed,
to be Your hands, O God.
Bring home to the homeless,
bring keys to the chained;
bring worth to the purchased,
and touch to the shamed.
Bring flesh from Your word, Lord,
bring truth where there’s spin;
bring risk where there’s safety,
and grace where there’s sin.
In the broken, we shall see restored
the image of our King.
We are blessed...
Lord, we cry out to You,
change the atmosphere;
breathe new life
in all who gather here.
Lord, we cry out...
We are blessed...
Bring justice to profit,
bring patience to growth;
bring wisdom to progress,
plant trees in this road.
Bring freedom from debt, Lord,
an end to excess;
bring closer Your kingdom
by quiet success.
May we grow in the knowledge of You
through every heart and face.
We are blessed...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1161', 'verse', 1, 0, '[\"Bring heaven to earth, Lord,\",\"bring peace where there’s fear;\",\"bring life where there’s death, Lord,\",\"bring joy in these tears.\",\"Bring love where there’s lust, Lord,\",\"bring hope where there’s pain;\",\"bring rest where there’s chaos,\",\"bring faith where there’s fame.\",\"You invite us to partner with You,\",\"to see Your kingdom come.\",\"We are blessed,\",\"to bless a world in pieces.\",\"We are loved,\",\"to love where love is not.\",\"We are changed,\",\"to be the change You promised.\",\"We are freed,\",\"to be Your hands, O God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1161', 'verse', 2, 1, '[\"Bring home to the homeless,\",\"bring keys to the chained;\",\"bring worth to the purchased,\",\"and touch to the shamed.\",\"Bring flesh from Your word, Lord,\",\"bring truth where there’s spin;\",\"bring risk where there’s safety,\",\"and grace where there’s sin.\",\"In the broken, we shall see restored\",\"the image of our King.\",\"We are blessed...\",\"Lord, we cry out to You,\",\"change the atmosphere;\",\"breathe new life\",\"in all who gather here.\",\"Lord, we cry out...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1161', 'chorus', 0, 2, '[\"We are blessed...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1161', 'verse', 3, 3, '[\"Bring justice to profit,\",\"bring patience to growth;\",\"bring wisdom to progress,\",\"plant trees in this road.\",\"Bring freedom from debt, Lord,\",\"an end to excess;\",\"bring closer Your kingdom\",\"by quiet success.\",\"May we grow in the knowledge of You\",\"through every heart and face.\",\"We are blessed...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1162', 1162, 'Would You move', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Could it be that God could move
into this, our neighbourhood;
O Lord, would You come?
The universe too small a place
to even give You breathing space,
O Lord, would You come?
Hear Your people cry today.
Hear from heaven, change our ways.
Lift our focus in this place:
we’re desperate for Your face,
we’re desperate for Your face.
Would You move in power,
till we cannot move?
Would You cloud our vision
to see only You?
Would You breathe through here
blowing out the dust?
Would You make Your dwelling
right here with us?
When the battle steals our soul,
we return to be made whole;
O Lord, would You come?
When disasters strike our faith,
we ask why, but ask for grace;
O Lord, would You come?
Hear Your people...
Would You move in power...
Hear Your people...
Would You move in power...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1162', 'verse', 1, 0, '[\"Could it be that God could move\",\"into this, our neighbourhood;\",\"O Lord, would You come?\",\"The universe too small a place\",\"to even give You breathing space,\",\"O Lord, would You come?\",\"Hear Your people cry today.\",\"Hear from heaven, change our ways.\",\"Lift our focus in this place:\",\"we’re desperate for Your face,\",\"we’re desperate for Your face.\",\"Would You move in power,\",\"till we cannot move?\",\"Would You cloud our vision\",\"to see only You?\",\"Would You breathe through here\",\"blowing out the dust?\",\"Would You make Your dwelling\",\"right here with us?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1162', 'verse', 2, 1, '[\"When the battle steals our soul,\",\"we return to be made whole;\",\"O Lord, would You come?\",\"When disasters strike our faith,\",\"we ask why, but ask for grace;\",\"O Lord, would You come?\",\"Hear Your people...\",\"Would You move in power...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1162', 'chorus', 0, 2, '[\"Hear Your people...\",\"Would You move in power...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1163', 1163, 'A touching place', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Christ’s is the world in which we move,
Christ’s are the folk we’re summoned to love,
Christ’s is the voice that calls us to care,
and Christ is the One who meets us here.
To the lost Christ shows His face.
To the unloved He gives His embrace.
To those who cry in pain or disgrace,
Christ makes, with His friends, a touching place.
Feel for the people we most avoid:
strange, or bereaved, or never employed.
Feel for the women and feel for the men
who fear that their living is all in vain.
To the lost...
Feel for the parents who’ve lost their child.
Feel for the woman whom men have defiled.
Feel for the baby for whom there’s no breast,
and feel for the weary who find no rest.
To the lost...
Feel for the lives by life confused,
riddled with doubt, in loving abused.
Feel for the lonely heart, conscious of sin,
which longs to be pure but fears to begin.
To the lost...');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1163', 'verse', 1, 0, '[\"Christ’s is the world in which we move,\",\"Christ’s are the folk we’re summoned to love,\",\"Christ’s is the voice that calls us to care,\",\"and Christ is the One who meets us here.\",\"To the lost Christ shows His face.\",\"To the unloved He gives His embrace.\",\"To those who cry in pain or disgrace,\",\"Christ makes, with His friends, a touching place.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1163', 'verse', 2, 1, '[\"Feel for the people we most avoid:\",\"strange, or bereaved, or never employed.\",\"Feel for the women and feel for the men\",\"who fear that their living is all in vain.\",\"To the lost...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1163', 'verse', 3, 2, '[\"Feel for the parents who’ve lost their child.\",\"Feel for the woman whom men have defiled.\",\"Feel for the baby for whom there’s no breast,\",\"and feel for the weary who find no rest.\",\"To the lost...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1163', 'verse', 4, 3, '[\"Feel for the lives by life confused,\",\"riddled with doubt, in loving abused.\",\"Feel for the lonely heart, conscious of sin,\",\"which longs to be pure but fears to begin.\",\"To the lost...\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1164', 1164, 'Come, O Fount of every blessing', 'MP', 'en', 'IN THIS VERSION PRAISE TRUST            Music arrangement: © David Peacock /The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION', '', 0, 0, 0, 1, 1, 'Come, O Fount of every blessing,
tune my heart to sing Your grace;
streams of mercy, never ceasing,
call for songs of loudest praise:
songs of God’s abundant treasure,
sung by angel tongues above,
songs that tell the boundless measure
of my Lord’s unchanging love!
I remember God’s great mercy:
by His help I’ve safely come;
and I know He will not fail me,
but will surely bring me home.
Jesus sought me when a stranger
wandering far away from God,
and, to rescue me from danger,
shed for me His precious blood.
Through God’s grace I am His debtor –
daily I this thought renew!
Let that grace, Lord, like a fetter
bind my wandering heart to You.
Prone to wander, Lord, I feel it,
prone to leave the God I love!
Take my heart, O take and seal it,
seal it from Your courts above!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1164', 'verse', 1, 0, '[\"Come, O Fount of every blessing,\",\"tune my heart to sing Your grace;\",\"streams of mercy, never ceasing,\",\"call for songs of loudest praise:\",\"songs of God’s abundant treasure,\",\"sung by angel tongues above,\",\"songs that tell the boundless measure\",\"of my Lord’s unchanging love!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1164', 'verse', 2, 1, '[\"I remember God’s great mercy:\",\"by His help I’ve safely come;\",\"and I know He will not fail me,\",\"but will surely bring me home.\",\"Jesus sought me when a stranger\",\"wandering far away from God,\",\"and, to rescue me from danger,\",\"shed for me His precious blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1164', 'verse', 3, 2, '[\"Through God’s grace I am His debtor –\",\"daily I this thought renew!\",\"Let that grace, Lord, like a fetter\",\"bind my wandering heart to You.\",\"Prone to wander, Lord, I feel it,\",\"prone to leave the God I love!\",\"Take my heart, O take and seal it,\",\"seal it from Your courts above!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1165', 1165, 'Crown of glory, crown of thorns,', 'MP', 'en', 'Song Solutions Daybreak www.songsolutions.org', '', 0, 0, 0, 1, 1, 'Crown of glory, crown of thorns,
Saviour of the world was born
to die for us in sacrifice,
and rise and wear the crown of life.
Prince of peace a pauper came
with riches sure enough,
to light the true, eternal flame:
the Father’s heart of love.
Son of God and Son of man,
You walked among us here,
You knew the fragile hearts we are,
You shared our joy and tears.
Crown of glory...
King of love, You bore our sin
that nailed You to the cross;
the tears of God, shed to reclaim
the broken and the lost.
Lord of light from darkness shone
in power to rise again,
for death has no dominion now,
the King of life shall reign.
Crown of glory...
God with us, Emmanuel,
the Shepherd and the Lamb;');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1165', 'chorus', 0, 0, '[\"Crown of glory, crown of thorns,\",\"Saviour of the world was born\",\"to die for us in sacrifice,\",\"and rise and wear the crown of life.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1165', 'verse', 1, 1, '[\"Prince of peace a pauper came\",\"with riches sure enough,\",\"to light the true, eternal flame:\",\"the Father’s heart of love.\",\"Son of God and Son of man,\",\"You walked among us here,\",\"You knew the fragile hearts we are,\",\"You shared our joy and tears.\",\"Crown of glory...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1165', 'verse', 2, 2, '[\"King of love, You bore our sin\",\"that nailed You to the cross;\",\"the tears of God, shed to reclaim\",\"the broken and the lost.\",\"Lord of light from darkness shone\",\"in power to rise again,\",\"for death has no dominion now,\",\"the King of life shall reign.\",\"Crown of glory...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1165', 'verse', 3, 3, '[\"God with us, Emmanuel,\",\"the Shepherd and the Lamb;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1166', 1166, 'Crucified to save me', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Crucified to save me,
crucified to wash me clean;
Your love and life were poured out,
given that I could be set free.
Blood and water flowed,
spilt that I might know Your love.
Take me back to the cross,
take me back, show me more of the cost.
Let Your Spirit come and turn my eyes
to see Your perfect sacrifice.
You walked a path of brokenness,
You walked the path that was my own.
I’ll take my cross and follow You
and demonstrate the love You’ve shown.
Lead me to that place
where I see Your grace and love.
Take me back...
Show me more of Calvary,
oh, lead me to that place.
I’m humbled by this mystery,
I bow before such grace.
Words and music: © Chris Gasson/RESOUND/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1166', 'verse', 1, 0, '[\"Crucified to save me,\",\"crucified to wash me clean;\",\"Your love and life were poured out,\",\"given that I could be set free.\",\"Blood and water flowed,\",\"spilt that I might know Your love.\",\"Take me back to the cross,\",\"take me back, show me more of the cost.\",\"Let Your Spirit come and turn my eyes\",\"to see Your perfect sacrifice.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1166', 'verse', 2, 1, '[\"You walked a path of brokenness,\",\"You walked the path that was my own.\",\"I’ll take my cross and follow You\",\"and demonstrate the love You’ve shown.\",\"Lead me to that place\",\"where I see Your grace and love.\",\"Take me back...\",\"Show me more of Calvary,\",\"oh, lead me to that place.\",\"I’m humbled by this mystery,\",\"I bow before such grace.\",\"Words and music: © Chris Gasson\\/RESOUND\\/The Jubilate Group. www.jubilate.co.uk. USED BY PERMISSION\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1167', 1167, 'You never let go', 'MP', 'en', '© 2005 Thankyou Music/Adm. by CapitolCMGPublishing.com worldwide excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 1, 0, 'Even though I walk through the valley
of the shadow of death,
Your perfect love is casting out fear.
And even when I’m caught in the middle
of the storms of this life,
I won’t turn back, I know You are near.
And I will fear no evil,
for my God is with me.
And if my God is with me,
whom then shall I fear,
whom then shall I fear?
Oh no, You never let go,
through the calm and through the storm.
Oh no, You never let go,
in every high and every low.
Oh no, You never let go,
Lord, You never let go of me.
And I can see a light that is coming
for the heart that holds on,
a glorious light beyond all compare.
And there will be an end to these troubles,
but until that day comes
we’ll live to know You here on the earth.
And I will fear no evil,
for my God is with me.
And if my God is with me,
whom then shall I fear,
whom then shall I fear?
Oh no, You never let go...
Yes, I can see a light that is coming
for the heart that holds on,
and there will be an end to these troubles,
but until that day comes,
still I will praise You,
still I will praise You.
Yes, I can see a light...
Oh no, You never let go...
Oh no, You never let go...
Even though I walk . .');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1167', 'verse', 1, 0, '[\"Even though I walk through the valley\",\"of the shadow of death,\",\"Your perfect love is casting out fear.\",\"And even when I’m caught in the middle\",\"of the storms of this life,\",\"I won’t turn back, I know You are near.\",\"And I will fear no evil,\",\"for my God is with me.\",\"And if my God is with me,\",\"whom then shall I fear,\",\"whom then shall I fear?\",\"Oh no, You never let go,\",\"through the calm and through the storm.\",\"Oh no, You never let go,\",\"in every high and every low.\",\"Oh no, You never let go,\",\"Lord, You never let go of me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1167', 'verse', 2, 1, '[\"And I can see a light that is coming\",\"for the heart that holds on,\",\"a glorious light beyond all compare.\",\"And there will be an end to these troubles,\",\"but until that day comes\",\"we’ll live to know You here on the earth.\",\"And I will fear no evil,\",\"for my God is with me.\",\"And if my God is with me,\",\"whom then shall I fear,\",\"whom then shall I fear?\",\"Oh no, You never let go...\",\"Yes, I can see a light that is coming\",\"for the heart that holds on,\",\"and there will be an end to these troubles,\",\"but until that day comes,\",\"still I will praise You,\",\"still I will praise You.\",\"Yes, I can see a light...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1167', 'chorus', 0, 2, '[\"Oh no, You never let go...\",\"Oh no, You never let go...\",\"Even though I walk . .\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1168', 1168, 'Saviour, He can move the mountains – Mighty to save', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Everyone needs compassion,
love that’s never failing;
let mercy fall on me.
Everyone needs forgiveness,
the kindness of a saviour;
the hope of nations.
Saviour,
He can move the mountains,
my God is mighty to save,
He is mighty to save.
Forever,
author of salvation,
He rose and conquered the grave,
Jesus conquered the grave.
So take me as You find me,
all my fears and failures,
fill my life again.
I give my life to follow
everything I believe in,
now I surrender.
Saviour...
Shine your light
and let the whole world see,
we’re singing
for the glory of the risen King,
Jesus.
Shine your light...
Saviour...
Shine your light...
Words & Music by Ben Fielding & Reuben Morgan © 2006 Hillsong Music Publishing (APRA). CCLI: 4591782');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1168', 'verse', 1, 0, '[\"Everyone needs compassion,\",\"love that’s never failing;\",\"let mercy fall on me.\",\"Everyone needs forgiveness,\",\"the kindness of a saviour;\",\"the hope of nations.\",\"Saviour,\",\"He can move the mountains,\",\"my God is mighty to save,\",\"He is mighty to save.\",\"Forever,\",\"author of salvation,\",\"He rose and conquered the grave,\",\"Jesus conquered the grave.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1168', 'verse', 2, 1, '[\"So take me as You find me,\",\"all my fears and failures,\",\"fill my life again.\",\"I give my life to follow\",\"everything I believe in,\",\"now I surrender.\",\"Saviour...\",\"Shine your light\",\"and let the whole world see,\",\"we’re singing\",\"for the glory of the risen King,\",\"Jesus.\",\"Shine your light...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1168', 'chorus', 0, 2, '[\"Saviour...\",\"Shine your light...\",\"Words & Music by Ben Fielding & Reuben Morgan © 2006 Hillsong Music Publishing (APRA). CCLI: 4591782\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1169', 1169, 'Everlasting', 'MP', 'en', '© 2004 Integrity\'s Hosanna! Music  (adm worldwide by Capitol CMG Publishing excl UK admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com) Used by Permission', '', 0, 0, 0, 1, 0, '');
