INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1171', 1171, 'Give thanks to the Lord', 'MP', 'en', '', '', 0, 0, 0, 1, 1, 'Give thanks to the Lord
(give thanks to the Lord),
