INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1171', 'verse', 2, 1, '[\"Give thanks to the Lord\",\"(give thanks to the Lord),\",\"He’s been good to us\",\"(He’s been good to us).\",\"Listens when we call\",\"(Listens when we call),\",\"faithful when we fall\",\"(faithful when we fall).\",\"Mercy from Your throne\",\"(mercy from Your throne),\",\"hope in Christ alone\",\"(hope in Christ alone).\",\"Great is the Lord and most worthy of praise,\",\"great is the Lord Most High.\",\"Great is the Lord and most worthy of praise,\",\"great is the Lord Most High.\"]');
