INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1220', 'verse', 2, 1, '[\"O the cross of Jesus,\",\"O the cross of Jesus,\",\"O the cross of Jesus,\",\"His death brings life to me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1220', 'verse', 3, 2, '[\"O the love of Jesus,\",\"O the love of Jesus,\",\"O the love of Jesus,\",\"He freely gives to me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1220', 'verse', 4, 3, '[\"O the blood of Jesus,\",\"O the blood of Jesus,\",\"O the blood of Jesus,\",\"it washes white as snow.\",\"vv. 2 and 3 Ken Barker: Word Music LLC\\/Song Solutions CopyCare www.songsolutions.org\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1221', 1221, 'Hosanna', 'MP', 'en', '2006 Sony/ATV Music Publishing Australia (Aust. & NZ Only), Hillsong Music Publishing (APRA) (Rest of World)', '', 0, 0, 0, 1, 1, 'Praise is rising,
eyes are turning to You,
we turn to You.
Hope is rising,
hearts are yearning for You,
we long for You.
’Cause when we see You,
we find strength to face the day;
in Your presence
all our fears are washed away, washed away.
Hosanna, hosanna,
You are the God who saves us,
worthy of all our praises.
Hosanna, hosanna,
come have Your way among us,
we welcome You here Lord Jesus.
Hear the sound of hearts
returning to You,
we turn to You.
In Your kingdom
broken lives
are made new,
You make us new.
’Cause when we see You,
we find strength to face the day;
in Your presence
all our fears are washed away, washed away.
Hosanna, hosanna...
Hosanna, hosanna.
Hosanna, hosanna.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1221', 'Brooke Ligertwood');
