INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1254', 'chorus', 0, 1, '[\"‘Love each other, one another,\",\"love each other in the way that I have loved you.\",\"Walk together, and whatever comes,\",\"love each other in the way that I have loved you, have\"]');
