INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1325', 'verse', 1, 0, '[\"1 Light in my darkness,\",\"peace for my soul,\",\"You are my rescue,\",\"You never let go.\",\"Light in my darkness...\",\"All my hope is in You,\",\"all my strength is in You,\",\"with every breath\",\"my soul will rest in You.\",\"2 Here in my weakness,\",\"always the same,\",\"Your love is my shelter,\",\"Your life is my way.\",\"All my hope is in You...\",\"All my hope is in You...\",\"Constant Saviour, friend for ever,\",\"Lord, You have my heart.\",\"Sure foundation, never failing,\",\"Lord, You have my heart.\",\"Constant Saviour...\",\"All my hope is in You...\",\"All the earth beneath You,\",\"all my life before You,\",\"with every breath\",\"my soul will rest in You,\",\"with every breath\",\"my soul will rest in You.\",\"Reuben Morgan and Jason Ingram\",\"THIS FROM SONG SELECT WEBSITE:© 2011 Hillsong Music Publishing (Admin. by HMTR Limited)Sony\\/ATV Timber Publishing (Admin. by Sony\\/ATV Music Publishing)West Main Music (Admin. by Sony\\/ATV Music Publishing)Windsor Hill Music (Admin. by Sony\\/ATV Music Publishing) THIS FROM SONY\\/ATV: All My Hope Written by Jason Ingram and Reuben Morgan Published by Sony\\/ ATV Timber Publishing FROM MUSIC SALES: All My Hope (Light In My Darkness)Words & Music by Jason Ingram & Reuben Morgan © Copyright 2012 Sony\\/ATV Timber Publishing \\/Windsor Hill Music\\/West Main Music Sony\\/ATV Music Publishing Limited All Rights Reserved. International Copyright Secured.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1326', 1326, 'Lift up his name', 'MP', 'en', '© 2009 Integrity Worship Music / adm worldwide by Capitol CMG Publishing excl UK, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 1, '1 Lift up his name within the sanctuary,
lift up His name among the people
who are gathered here to sing His praise,
who are gathered here to sing His praise.
Holy is our God. Holy is Your name;
mighty are Your works and deeds
and wondrous are Your ways.
All that You have made
shall return and give You glory, Lord.
2 The earth, the sky, the sea and all within them,
this universe, beyond the sight of mortal man,
all subject to His reign,
all creation subject to His reign.
Holy is our God...
3 The great ‘I Am’, no end and no beginning,
You were and are, and evermore You shall be.
All my days are in Your hands,
all my days are in Your hands.
Holy is our God. Holy is Your name;
mighty are Your works and deeds
and wondrous are Your ways.
All that You have made
shall return and give You glory,
Holy is our God...
... give You glory, give You glory,
give You glory, Lord.
Robin Mark');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1326', 'verse', 1, 0, '[\"1 Lift up his name within the sanctuary,\",\"lift up His name among the people\",\"who are gathered here to sing His praise,\",\"who are gathered here to sing His praise.\",\"Holy is our God. Holy is Your name;\",\"mighty are Your works and deeds\",\"and wondrous are Your ways.\",\"All that You have made\",\"shall return and give You glory, Lord.\",\"2 The earth, the sky, the sea and all within them,\",\"this universe, beyond the sight of mortal man,\",\"all subject to His reign,\",\"all creation subject to His reign.\",\"Holy is our God...\",\"3 The great ‘I Am’, no end and no beginning,\",\"You were and are, and evermore You shall be.\",\"All my days are in Your hands,\",\"all my days are in Your hands.\",\"Holy is our God. Holy is Your name;\",\"mighty are Your works and deeds\",\"and wondrous are Your ways.\",\"All that You have made\",\"shall return and give You glory,\",\"Holy is our God...\",\"... give You glory, give You glory,\",\"give You glory, Lord.\",\"Robin Mark\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1327', 1327, 'Lord, hear our cry', 'MP', 'en', '© 2004 Vertical Worship Songs /  adm worldwide by Capitol CMG Publishing excl UK admin by Integritymusic.com, a division of David C Cook, songs@integritymusic.com Used by Permission.', '', 0, 0, 0, 0, 1, 'Lord, hear our cry, come, heal our land.
Breathe life into these dry and thirsty souls.
Lord, hear our prayer, forgive our sin.
As we call on Your name,
would You make this a place
for Your glory to dwell?
Open the blind eyes,
unlock the deaf ears,
come to Your people
as we draw near.
Hear us from heaven,
touch our generation.
We are Your people
crying out in desperation.
Lord, hear our cry...
Open the blind eyes...
Hear us from heaven,
hear us from heaven,
hear us from heaven.
Hear us from heaven...
Hear us from heaven...
Hear us from heaven...
Open the blind eyes...
Jared Anderson Vertical Worship Songs / Integrity');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1327', 'chorus', 0, 0, '[\"Lord, hear our cry, come, heal our land.\",\"Breathe life into these dry and thirsty souls.\",\"Lord, hear our prayer, forgive our sin.\",\"As we call on Your name,\",\"would You make this a place\",\"for Your glory to dwell?\",\"Open the blind eyes,\",\"unlock the deaf ears,\",\"come to Your people\",\"as we draw near.\",\"Hear us from heaven,\",\"touch our generation.\",\"We are Your people\",\"crying out in desperation.\",\"Lord, hear our cry...\",\"Open the blind eyes...\",\"Hear us from heaven,\",\"hear us from heaven,\",\"hear us from heaven.\",\"Hear us from heaven...\",\"Hear us from heaven...\",\"Hear us from heaven...\",\"Open the blind eyes...\",\"Jared Anderson Vertical Worship Songs \\/ Integrity\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1328', 1328, 'Lord, I Come', 'MP', 'en', '© 2007 Integrity’s Praise! Music (Adm. by Capitol CMG Publishing.com excl. the UK, adm. by Integritymusic.com. a division of David C Cook songs@integritymusic.com)/Parachute Music. Used by permission', '', 0, 0, 0, 0, 1, '1 Lord, I come into Your holy place,
stand in awe of Your cleansing grace.
Who am I, that You would care for me?
I glorify the One who died for me.
Glorify, glorify,
let Your name be lifted up and glorified.
Let the earth tremble at Your name.
Let Your name be lifted up and glorified.
2 Into Your hands I commit my life,
day by day, as a living sacrifice.
Who am I, that You would care for me?
I glorify the One who died for me.
Glorify, glorify...
Glorify, glorify...
Shaun Grifﬁths');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1328', 'verse', 1, 0, '[\"1 Lord, I come into Your holy place,\",\"stand in awe of Your cleansing grace.\",\"Who am I, that You would care for me?\",\"I glorify the One who died for me.\",\"Glorify, glorify,\",\"let Your name be lifted up and glorified.\",\"Let the earth tremble at Your name.\",\"Let Your name be lifted up and glorified.\",\"2 Into Your hands I commit my life,\",\"day by day, as a living sacrifice.\",\"Who am I, that You would care for me?\",\"I glorify the One who died for me.\",\"Glorify, glorify...\",\"Glorify, glorify...\",\"Shaun Grifﬁths\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1329', 1329, 'Loved before the dawn of time', 'MP', 'en', '(c) 2007 Thankyou Music (Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com) Used by Permission', '', 0, 0, 0, 0, 1, '1 Loved before the dawn of time,
chosen by my Maker,
hidden in my Saviour:
I am His and He is mine,
cherished for eternity.
2 When I’m stained with guilt and sin,
He is there to lift me,
heal me and forgive me;
gives me strength to stand again,
stronger than I was before.
So with every breath that I am given
I will sing salvation’s song;
and I’ll join the chorus of creation
giving praise to Christ alone.
3 All the claims of Satan’s curse
lifted through His offering,
satisfied through suffering;
all the blessings He deserves
poured on my unworthy soul.
So with every breath...
Singing glory, honour, wisdom, power
to the Lamb upon the throne;
hallelujah, I will lift Him high.
Singing glory, honour, wisdom, power
to the Lamb upon the throne;
hallelujah, I will sing
with every breath that I am given,
I will sing salvation’s song,
and I’ll join the chorus of creation
giving praise to Christ alone.
4 Stars will fade and mountains fall;
Christ will shine for ever,
love’s unfading splendour.
Earth and heaven will bow in awe,
joining in salvation’s song.
Stuart Townend / Andrew Small');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1329', 'verse', 1, 0, '[\"1 Loved before the dawn of time,\",\"chosen by my Maker,\",\"hidden in my Saviour:\",\"I am His and He is mine,\",\"cherished for eternity.\",\"2 When I’m stained with guilt and sin,\",\"He is there to lift me,\",\"heal me and forgive me;\",\"gives me strength to stand again,\",\"stronger than I was before.\",\"So with every breath that I am given\",\"I will sing salvation’s song;\",\"and I’ll join the chorus of creation\",\"giving praise to Christ alone.\",\"3 All the claims of Satan’s curse\",\"lifted through His offering,\",\"satisfied through suffering;\",\"all the blessings He deserves\",\"poured on my unworthy soul.\",\"So with every breath...\",\"Singing glory, honour, wisdom, power\",\"to the Lamb upon the throne;\",\"hallelujah, I will lift Him high.\",\"Singing glory, honour, wisdom, power\",\"to the Lamb upon the throne;\",\"hallelujah, I will sing\",\"with every breath that I am given,\",\"I will sing salvation’s song,\",\"and I’ll join the chorus of creation\",\"giving praise to Christ alone.\",\"4 Stars will fade and mountains fall;\",\"Christ will shine for ever,\",\"love’s unfading splendour.\",\"Earth and heaven will bow in awe,\",\"joining in salvation’s song.\",\"Stuart Townend \\/ Andrew Small\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1330', 1330, 'Majesty of heaven', 'MP', 'en', '©  2010 Thankyou Music/Said and Done Music/Sixsteps Music/Vamos Publishing/worshiptogether.com songs (dm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com) Used by Permission', '', 0, 0, 0, 0, 0, '1 Majesty of heaven,
Your glory fills the skies;
light of the world,
You are Lord of all.
2 Humbled by Your presence,
amazed by who You are;
nothing compares,
You are Lord of all.
To You the nations bow down;
to You creation cries out: ‘Majesty’.
All things You hold together,
Your name will stand for ever;
majesty, You are majesty.
3 Merciful and mighty,
my heart is overwhelmed;
You stand alone,
You are Lord of all.
To You the nations bow down...
Your name above all others,
high and exalted.
Your kingdom shall reign for ever,
high and exalted.
Your name above all others...
To You the nations bow down...
...You are majesty.
Chris Tomlin / Jesse Reeves / Matt Redman');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1330', 'verse', 1, 0, '[\"1 Majesty of heaven,\",\"Your glory fills the skies;\",\"light of the world,\",\"You are Lord of all.\",\"2 Humbled by Your presence,\",\"amazed by who You are;\",\"nothing compares,\",\"You are Lord of all.\",\"To You the nations bow down;\",\"to You creation cries out: ‘Majesty’.\",\"All things You hold together,\",\"Your name will stand for ever;\",\"majesty, You are majesty.\",\"3 Merciful and mighty,\",\"my heart is overwhelmed;\",\"You stand alone,\",\"You are Lord of all.\",\"To You the nations bow down...\",\"Your name above all others,\",\"high and exalted.\",\"Your kingdom shall reign for ever,\",\"high and exalted.\",\"Your name above all others...\",\"To You the nations bow down...\",\"...You are majesty.\",\"Chris Tomlin \\/ Jesse Reeves \\/ Matt Redman\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1331', 1331, 'Magnificent, all-glorious Lord', 'MP', 'en', '©  2005 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 0, 'Magnificent, all-glorious Lord.
Omnipotent, victorious,
sovereign Master, King for ever.
Most marvellous, all-radiant God.
In excellence pre-eminent,
sovereign Master, King for ever.
Your thoughts to bless unlimited.
Surpassing grace, transcending love,
You are in all Your ways most wonderful;
and all Your ways are ever sure and true
in all You do.
Magnificent...
Your thoughts to bless...
Chris Bowater');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1331', 'verse', 1, 0, '[\"Magnificent, all-glorious Lord.\",\"Omnipotent, victorious,\",\"sovereign Master, King for ever.\",\"Most marvellous, all-radiant God.\",\"In excellence pre-eminent,\",\"sovereign Master, King for ever.\",\"Your thoughts to bless unlimited.\",\"Surpassing grace, transcending love,\",\"You are in all Your ways most wonderful;\",\"and all Your ways are ever sure and true\",\"in all You do.\",\"Magnificent...\",\"Your thoughts to bless...\",\"Chris Bowater\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1332', 1332, 'Man of sorrows', 'MP', 'en', '2006 Hillsong Music Publishing (APRA).', '', 0, 0, 0, 0, 1, '1 Man of sorrows, Lamb of God,
by His own betrayed.
The sin of man and wrath of God
has been on Jesus laid.
Silent as He stood accused,
beaten, mocked and scorned.
Bowing to the Father’s will,
He took a crown of thorns.
Oh, that rugged cross, my salvation,
where Your love poured out over me.
Now my soul cries out, hallelujah,
praise and honour unto Thee.
3 Sent of heaven, God’s own Son
to purchase and redeem,
and reconcile the very ones
who nailed Him to that tree.
Oh, that rugged cross…
Now my debt is paid, it is paid in full
by the precious blood that my Jesus spilled.
Now the curse of sin has no hold on me.
Whom the Son sets free, oh, is free indeed.
Now my debt is paid...
Oh, that rugged cross...
4 See, the stone is rolled away,
behold the empty tomb.
Hallelujah, God be praised,
He’s risen from the grave.
Oh, that rugged cross...
... praise and honour unto Thee.
Matt Crocker, Brooke Ligertwood');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1332', 'Matt Crocker & Brooke Ligertwood');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1332', 'Matt Crocker & Brooke Ligertwood');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1332', 'verse', 1, 0, '[\"1 Man of sorrows, Lamb of God,\",\"by His own betrayed.\",\"The sin of man and wrath of God\",\"has been on Jesus laid.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1332', 'verse', 2, 1, '[\"Silent as He stood accused,\",\"beaten, mocked and scorned.\",\"Bowing to the Father’s will,\",\"He took a crown of thorns.\",\"Oh, that rugged cross, my salvation,\",\"where Your love poured out over me.\",\"Now my soul cries out, hallelujah,\",\"praise and honour unto Thee.\",\"3 Sent of heaven, God’s own Son\",\"to purchase and redeem,\",\"and reconcile the very ones\",\"who nailed Him to that tree.\",\"Oh, that rugged cross…\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1332', 'chorus', 0, 2, '[\"Now my debt is paid, it is paid in full\",\"by the precious blood that my Jesus spilled.\",\"Now the curse of sin has no hold on me.\",\"Whom the Son sets free, oh, is free indeed.\",\"Now my debt is paid...\",\"Oh, that rugged cross...\",\"4 See, the stone is rolled away,\",\"behold the empty tomb.\",\"Hallelujah, God be praised,\",\"He’s risen from the grave.\",\"Oh, that rugged cross...\",\"... praise and honour unto Thee.\",\"Matt Crocker, Brooke Ligertwood\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1333', 1333, 'My goal is God himself', 'MP', 'en', 'Copyright 2009 Sovereign Lifestyle Music Ltd. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 0, 1, '1 My goal is God Himself, not joy, not peace.
Not even blessing, but Himself, my God.
My goal is God with every breath I breathe.
Please accept the praise I bring,
fulfil my deepest prayer.
2 So faith bounds forward to its goal in God.
And love can trust in Christ to lead me there.
Upheld by Him, my soul is following hard.
Please accept the praise that I bring,
fulfil my deepest prayer.
No matter if the way is sometimes dark.
No matter though the cost is often great.
He knows the best way I shall reach the mark.
Please accept the praise that I bring,
fulfil my deepest prayer.
3 One thing I know, I cannot turn away.
One thing I do, I press towards my Lord.
My God, my glory, here from day to day.
Please accept the praise that I bring,
fulfil my deepest prayer,
fulfil my deepest prayer.');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1333', 'Frederick Brook & adapted by Chris Bowater');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1333', 'Chris Bowater');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1333', 'verse', 1, 0, '[\"1 My goal is God Himself, not joy, not peace.\",\"Not even blessing, but Himself, my God.\",\"My goal is God with every breath I breathe.\",\"Please accept the praise I bring,\",\"fulfil my deepest prayer.\",\"2 So faith bounds forward to its goal in God.\",\"And love can trust in Christ to lead me there.\",\"Upheld by Him, my soul is following hard.\",\"Please accept the praise that I bring,\",\"fulfil my deepest prayer.\",\"No matter if the way is sometimes dark.\",\"No matter though the cost is often great.\",\"He knows the best way I shall reach the mark.\",\"Please accept the praise that I bring,\",\"fulfil my deepest prayer.\",\"3 One thing I know, I cannot turn away.\",\"One thing I do, I press towards my Lord.\",\"My God, my glory, here from day to day.\",\"Please accept the praise that I bring,\",\"fulfil my deepest prayer,\",\"fulfil my deepest prayer.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1334', 1334, 'My hope is built', 'MP', 'en', '2011 Hillsong Music Publishing (APRA).', '', 0, 0, 0, 0, 1, '1 My hope is built on nothing less
than Jesus’ blood and righteousness.
I dare not trust the sweetest frame,
but wholly trust in Jesus’ name.
My hope is built...
Christ alone, cornerstone,
weak made strong in the Saviour’s love.
Through the storm He is Lord,
Lord of all.
2 When darkness seems to hide His face,
I rest on His unchanging grace.
In every high and stormy gale,
my anchor holds within the veil,
my anchor holds within the veil.
Christ alone, cornerstone,
weak made strong in the Saviour’s love.
Through the storm He is Lord,
Lord of all.
He is Lord, Lord of all.
Christ alone...
Christ alone...
3 When He shall come with trumpet sound,
oh, may I then in Him be found.
Dressed in His righteousness alone,
faultless stand before the throne.
Christ alone...
(x4)
Edward Mote, Eric Liljero, Jonas Myrin, Reuben Morgan, William Batchelder Bradbury');
INSERT INTO tblSongWriters (SongId, Name) VALUES ('MP-1334', 'Jonas Myrin, Reuben Morgan & Eric Liliero');
INSERT INTO tblSongComposers (SongId, Name) VALUES ('MP-1334', 'Jonas Myrin, Reuben Morgan & Eric Liliero');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1334', 'verse', 1, 0, '[\"1 My hope is built on nothing less\",\"than Jesus’ blood and righteousness.\",\"I dare not trust the sweetest frame,\",\"but wholly trust in Jesus’ name.\",\"My hope is built...\",\"Christ alone, cornerstone,\",\"weak made strong in the Saviour’s love.\",\"Through the storm He is Lord,\",\"Lord of all.\",\"2 When darkness seems to hide His face,\",\"I rest on His unchanging grace.\",\"In every high and stormy gale,\",\"my anchor holds within the veil,\",\"my anchor holds within the veil.\",\"Christ alone, cornerstone,\",\"weak made strong in the Saviour’s love.\",\"Through the storm He is Lord,\",\"Lord of all.\",\"He is Lord, Lord of all.\",\"Christ alone...\",\"Christ alone...\",\"3 When He shall come with trumpet sound,\",\"oh, may I then in Him be found.\",\"Dressed in His righteousness alone,\",\"faultless stand before the throne.\",\"Christ alone...\",\"(x4)\",\"Edward Mote, Eric Liljero, Jonas Myrin, Reuben Morgan, William Batchelder Bradbury\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1335', 1335, 'My Saviour, Redeemer', 'MP', 'en', '', '', 0, 0, 0, 0, 1, 'My Saviour, Redeemer,
lifted me from the miry clay.
Almighty, for ever,
I will never be the same,
’cause You came near,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1335', 'chorus', 0, 0, '[\"My Saviour, Redeemer,\",\"lifted me from the miry clay.\",\"Almighty, for ever,\",\"I will never be the same,\",\"’cause You came near,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1336', 1336, 'Now unto the King who reigns over all', 'MP', 'en', '(c) 2009 Thankyou Music/Said And Done Music (Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com songs@integritymusic.com) SHOUT! Publishing. Used by Permission', '', 0, 0, 0, 0, 1, '1 Now unto the King who reigns over all
and never changes or turns;
unfailing justice, unfading grace,
whose promises remain.
Yes, Your promises remain.
Now unto the King...
The heavens ring, the saints all sing,
‘Great is Your faithfulness.’');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1336', 'verse', 1, 0, '[\"1 Now unto the King who reigns over all\",\"and never changes or turns;\",\"unfailing justice, unfading grace,\",\"whose promises remain.\",\"Yes, Your promises remain.\",\"Now unto the King...\",\"The heavens ring, the saints all sing,\",\"‘Great is Your faithfulness.’\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1337', 1337, 'Not to us, O  Lord,', 'MP', 'en', '©  2005 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 0, 'Not to us, O Lord,
but to Your name be glory.
Not to us be praise,
but Your great name we raise.
High above, lifted up,
You deserve the place of honour.
Holy One, glorious Christ,
You deserve our hearts’ devotion.
Not to us,O Lord...
Christ the King, heaven’s Lamb,
Jesus, You alone are worthy
to receive the offering
of forgiven hearts in worship.
Ransomed, healed, restored, forgiven,
who like we His praise should sing?
Ransomed, healed, restored, forgiven,
praise the everlasting King,
praise the everlasting King.
Chris Bowater');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1337', 'verse', 1, 0, '[\"Not to us, O Lord,\",\"but to Your name be glory.\",\"Not to us be praise,\",\"but Your great name we raise.\",\"High above, lifted up,\",\"You deserve the place of honour.\",\"Holy One, glorious Christ,\",\"You deserve our hearts’ devotion.\",\"Not to us,O Lord...\",\"Christ the King, heaven’s Lamb,\",\"Jesus, You alone are worthy\",\"to receive the offering\",\"of forgiven hearts in worship.\",\"Ransomed, healed, restored, forgiven,\",\"who like we His praise should sing?\",\"Ransomed, healed, restored, forgiven,\",\"praise the everlasting King,\",\"praise the everlasting King.\",\"Chris Bowater\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1338', 1338, 'Now when peace like a river', 'MP', 'en', '©  2011 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook, songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 1, '1 Now when peace like a river
attendeth my soul,
and when sorrows like sea billows roll,
then whatever my lot,
You have taught me to say,
it is well, it is well with my soul.
It is well with my soul,
when the storms of winter blow
and the cares of this world take their toll.
In the heat of the day
there is grace enough to say,
it is well, it is well with my soul.
2 And when Satan should tempt me,
and trials should come,
let this blessèd assurance control,
for He sees every weakness
and knows every fear,
and has shed His own blood
for my soul.
It is well with my soul...
... It is well, it is well with my soul.
(x2)
Stuart Townend / Phil Baggaley / H. Spafford');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1338', 'verse', 1, 0, '[\"1 Now when peace like a river\",\"attendeth my soul,\",\"and when sorrows like sea billows roll,\",\"then whatever my lot,\",\"You have taught me to say,\",\"it is well, it is well with my soul.\",\"It is well with my soul,\",\"when the storms of winter blow\",\"and the cares of this world take their toll.\",\"In the heat of the day\",\"there is grace enough to say,\",\"it is well, it is well with my soul.\",\"2 And when Satan should tempt me,\",\"and trials should come,\",\"let this blessèd assurance control,\",\"for He sees every weakness\",\"and knows every fear,\",\"and has shed His own blood\",\"for my soul.\",\"It is well with my soul...\",\"... It is well, it is well with my soul.\",\"(x2)\",\"Stuart Townend \\/ Phil Baggaley \\/ H. Spafford\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1339', 1339, 'O blessed lamb, once slain', 'MP', 'en', '', '', 0, 0, 0, 0, 1, '1 O blessed lamb, once slain,
will reign for evermore.
His hands, once bound, now save.
Our God will never fail.
He is Lord, He is Lord,
sings my soul, He is the Lord.
And He lives, yes, He lives,
I’m alive ’cause Jesus lives.
2 ’Tis at the cross of Christ,
where earth and heaven meet,
where sin is overcome.
To God the victory!
He is Lord, He is Lord,
sings my soul, He is the Lord.
And He lives, yes, He lives,
I’m alive ’cause Jesus lives.
And now, let the earth resound with praise,
for our Saviour God, He reigns.
He is high and lifted up.
Arise, for the King of glory waits.
He is coming back again,
He is coming back again.
He is Lord...
And now...
He is coming back again,
He is coming back again,
He is coming back again.
(x2)
Ben Fielding
Words & Music by Ben Fielding © 2008 Hillsong Publishing CCLI: 5065918');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1339', 'verse', 1, 0, '[\"1 O blessed lamb, once slain,\",\"will reign for evermore.\",\"His hands, once bound, now save.\",\"Our God will never fail.\",\"He is Lord, He is Lord,\",\"sings my soul, He is the Lord.\",\"And He lives, yes, He lives,\",\"I’m alive ’cause Jesus lives.\",\"2 ’Tis at the cross of Christ,\",\"where earth and heaven meet,\",\"where sin is overcome.\",\"To God the victory!\",\"He is Lord, He is Lord,\",\"sings my soul, He is the Lord.\",\"And He lives, yes, He lives,\",\"I’m alive ’cause Jesus lives.\",\"And now, let the earth resound with praise,\",\"for our Saviour God, He reigns.\",\"He is high and lifted up.\",\"Arise, for the King of glory waits.\",\"He is coming back again,\",\"He is coming back again.\",\"He is Lord...\",\"And now...\",\"He is coming back again,\",\"He is coming back again,\",\"He is coming back again.\",\"(x2)\",\"Ben Fielding\",\"Words & Music by Ben Fielding © 2008 Hillsong Publishing CCLI: 5065918\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1340', 1340, 'O God, You are my God', 'MP', 'en', 'control as MP25', '', 0, 0, 0, 0, 1, 'O God,You are my God,
and I will ever praise You;
O God, You are my God,
and I will ever praise You.
I will seek You in the morning,
I will learn to walk in Your ways;
and step by step You leadme,
and I will follow You all of my days.
David (Beaker) Strasser');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1340', 'verse', 1, 0, '[\"O God,You are my God,\",\"and I will ever praise You;\",\"O God, You are my God,\",\"and I will ever praise You.\",\"I will seek You in the morning,\",\"I will learn to walk in Your ways;\",\"and step by step You leadme,\",\"and I will follow You all of my days.\",\"David (Beaker) Strasser\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1341', 1341, 'O God beyond all praising', 'MP', 'en', '', '', 0, 0, 0, 0, 1, '1 O God beyond all praising,
we worship You today
and sing the love amazing
that songs cannot repay;
for we can only wonder
at every gift You send,
at blessings without number
and mercies without end:
we lift our hearts before You
and wait upon Your word,
we honour and adore You,
our great and mighty Lord.
2 Then hear, O gracious Saviour,
accept the love we bring,
that we who know Your favour
may serve You as our king;
and whether our tomorrows
be filled with good or ill,
we’ll triumph through our sorrows
and rise to bless You still;
to marvel at Your beauty
and glory in Your ways,
and make a joyful duty
our sacrifice of praise!
Gustav Holst
out of copyright');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1341', 'verse', 1, 0, '[\"1 O God beyond all praising,\",\"we worship You today\",\"and sing the love amazing\",\"that songs cannot repay;\",\"for we can only wonder\",\"at every gift You send,\",\"at blessings without number\",\"and mercies without end:\",\"we lift our hearts before You\",\"and wait upon Your word,\",\"we honour and adore You,\",\"our great and mighty Lord.\",\"2 Then hear, O gracious Saviour,\",\"accept the love we bring,\",\"that we who know Your favour\",\"may serve You as our king;\",\"and whether our tomorrows\",\"be filled with good or ill,\",\"we’ll triumph through our sorrows\",\"and rise to bless You still;\",\"to marvel at Your beauty\",\"and glory in Your ways,\",\"and make a joyful duty\",\"our sacrifice of praise!\",\"Gustav Holst\",\"out of copyright\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1342', 1342, 'O Lord, You’ve searched me and You know my way', 'MP', 'en', '', '', 0, 0, 0, 0, 1, '1 O Lord, You’ve searched me and You know my way
You know my way.
Even when I fail You,
I know You love me.
2 Your holy presence,
surrounding me.
In every season
I know You love me,
I know You love me.
At the cross I bow my knee,
where Your blood was shed for me.
There’s no greater love than this.
You have overcome the grave.
Your glory fills the highest place.
What can separate me now?
3 You go before me,
You shield my way.
Your hand upholds me.
I know You love me.
At the cross...
At the cross...
You tore the veil, You made a way,
when You said that it is done.
You tore the veil, You made a way,
when You said that it is done.
4 And when the earth fades,
falls from my eyes,
and You stand before me,
I know You love me.
At the cross...
At the cross...
You tore the veil, You made a way,
when You said that it is done.
You tore the veil, You made a way,
when You said that it is done.
Reuben Morgan and Darlene Zschech
[From Hillsong] Words & Music by Reuben Morgan & Darlene Zschech © 2006 Wondrous Worship (Admin. by Music Services, Inc.) & Hillsong Music Publishing CCLI: 4591816 [From Song Solutions]  (c) Hillsong Music Publishing; Wondrous Worship/MSI Music Adm/Song Solutions CopyCare www.songsolutions.org');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1342', 'verse', 1, 0, '[\"1 O Lord, You’ve searched me and You know my way\",\"You know my way.\",\"Even when I fail You,\",\"I know You love me.\",\"2 Your holy presence,\",\"surrounding me.\",\"In every season\",\"I know You love me,\",\"I know You love me.\",\"At the cross I bow my knee,\",\"where Your blood was shed for me.\",\"There’s no greater love than this.\",\"You have overcome the grave.\",\"Your glory fills the highest place.\",\"What can separate me now?\",\"3 You go before me,\",\"You shield my way.\",\"Your hand upholds me.\",\"I know You love me.\",\"At the cross...\",\"At the cross...\",\"You tore the veil, You made a way,\",\"when You said that it is done.\",\"You tore the veil, You made a way,\",\"when You said that it is done.\",\"4 And when the earth fades,\",\"falls from my eyes,\",\"and You stand before me,\",\"I know You love me.\",\"At the cross...\",\"At the cross...\",\"You tore the veil, You made a way,\",\"when You said that it is done.\",\"You tore the veil, You made a way,\",\"when You said that it is done.\",\"Reuben Morgan and Darlene Zschech\",\"[From Hillsong] Words & Music by Reuben Morgan & Darlene Zschech © 2006 Wondrous Worship (Admin. by Music Services, Inc.) & Hillsong Music Publishing CCLI: 4591816 [From Song Solutions]  (c) Hillsong Music Publishing; Wondrous Worship\\/MSI Music Adm\\/Song Solutions CopyCare www.songsolutions.org\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1343', 1343, 'O God, You search me and know me', 'MP', 'en', '', '', 0, 0, 0, 0, 1, 'O God,You search me and You know me.
All my thoughts lie open to Your gaze.
When I walk or lie down You are before me:
ever the maker and keeper of my days.
2 You know my resting and my rising.
You discern my purpose from afar,
and with love everlasting You besiege me:
in every moment of life or death, You are.
3 Before a word is on my tongue, Lord,
You have known its meaning through and through.
You are with me beyond my understanding:
God of my present, my past and future, too.
4 Although Your Spirit is upon me,
still I search for shelter from Your light.
There is nowhere on earth I can escape You:
even the darkness is radiant in Your sight.
5 For You created me and shaped me,
gave me life within my mother’s womb.
For the wonder of who I am, I praise You:
safe in Your hands, all creation is made new.
Bernadette Farrell
Words and music: © 1992, Bernadette Farrell. Published by OCP, 5536 NE Hassalo, Portland, OR 97213. All rights reserved.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1343', 'verse', 1, 0, '[\"O God,You search me and You know me.\",\"All my thoughts lie open to Your gaze.\",\"When I walk or lie down You are before me:\",\"ever the maker and keeper of my days.\",\"2 You know my resting and my rising.\",\"You discern my purpose from afar,\",\"and with love everlasting You besiege me:\",\"in every moment of life or death, You are.\",\"3 Before a word is on my tongue, Lord,\",\"You have known its meaning through and through.\",\"You are with me beyond my understanding:\",\"God of my present, my past and future, too.\",\"4 Although Your Spirit is upon me,\",\"still I search for shelter from Your light.\",\"There is nowhere on earth I can escape You:\",\"even the darkness is radiant in Your sight.\",\"5 For You created me and shaped me,\",\"gave me life within my mother’s womb.\",\"For the wonder of who I am, I praise You:\",\"safe in Your hands, all creation is made new.\",\"Bernadette Farrell\",\"Words and music: © 1992, Bernadette Farrell. Published by OCP, 5536 NE Hassalo, Portland, OR 97213. All rights reserved.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1344', 1344, 'Oh, how could it be', 'MP', 'en', '©  2009 Thankyou Music/Said and Done Music/sixsteps Music/Spiritandsong.com (Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com) / Icel (Song Solutions Daybreak). Used by Permission', '', 0, 0, 0, 0, 1, 'Oh, how could it be
that my God would welcome me
into this mystery?
Say, ‘Take this bread, take this wine,’
now the simple made divine
for any to receive.
By Your mercy we come to Your table;
by Your grace You are making us faithful.
Lord, we remember You,
and remembrance leads us to worship.
And as we worship You,
our worship leads to communion.
We respond to Your invitation;
we remember You.
2 See His body, His blood –
know that He has overcome
every trial we will face.
None too lost to be saved,
none too broken or ashamed;
all are welcome in this place.
By Your mercy...
Dying, You destroyed our death.
Rising, You restored our life.
Lord Jesus, come in glory,
Lord Jesus, come in glory.
Dying, You destroyed our death...
... Lord Jesus, come in glory.
By Your mercy we come to Your table;
by Your grace You are making us faithful.
Lord, we remember You,
and remembrance leads us to worship.
And as we worship You,
our worship leads to communion.
We respond to Your invitation,
we respond to Your invitation,
we remember You.
Matt Redman / Matt Maher');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1344', 'verse', 1, 0, '[\"Oh, how could it be\",\"that my God would welcome me\",\"into this mystery?\",\"Say, ‘Take this bread, take this wine,’\",\"now the simple made divine\",\"for any to receive.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1344', 'chorus', 0, 1, '[\"By Your mercy we come to Your table;\",\"by Your grace You are making us faithful.\",\"Lord, we remember You,\",\"and remembrance leads us to worship.\",\"And as we worship You,\",\"our worship leads to communion.\",\"We respond to Your invitation;\",\"we remember You.\",\"2 See His body, His blood –\",\"know that He has overcome\",\"every trial we will face.\",\"None too lost to be saved,\",\"none too broken or ashamed;\",\"all are welcome in this place.\",\"By Your mercy...\",\"Dying, You destroyed our death.\",\"Rising, You restored our life.\",\"Lord Jesus, come in glory,\",\"Lord Jesus, come in glory.\",\"Dying, You destroyed our death...\",\"... Lord Jesus, come in glory.\",\"By Your mercy we come to Your table;\",\"by Your grace You are making us faithful.\",\"Lord, we remember You,\",\"and remembrance leads us to worship.\",\"And as we worship You,\",\"our worship leads to communion.\",\"We respond to Your invitation,\",\"we respond to Your invitation,\",\"we remember You.\",\"Matt Redman \\/ Matt Maher\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1345', 1345, 'Our God be praised, and on His Name be blessing (words)', 'MP', 'en', '', '', 0, 0, 0, 0, 0, '1 Our God be praised,
and on His name be blessing;
how rich in mercy to redeem, how swift to save!
He heals and pardons those who come
their sin confessing;
praise be to God, who rescues from the grave!
2 High as the heavens, see His mercy towering!
He sets our sins as far as east is from the west.
Our days are brief as short-lived
summer meadows’ flowering,
yet in His love we are for ever blest.
3 May children’s children learn that love amazing,
all creatures bow before His universal throne;
His whole dominion join in everlasting praising:
glory to God, my soul, and God alone!
Timothy Dudley-Smith
\'Our God be praised, and on His Name be blessing\' by Timothy Dudley-Smith (b. 1926) © Timothy Dudley-Smith in Europe and Africa. © Hope Publishing Company in the United States of America and the rest of the world. Reproduced by permission of Oxford University Press. All rights reserved.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1345', 'verse', 1, 0, '[\"1 Our God be praised,\",\"and on His name be blessing;\",\"how rich in mercy to redeem, how swift to save!\",\"He heals and pardons those who come\",\"their sin confessing;\",\"praise be to God, who rescues from the grave!\",\"2 High as the heavens, see His mercy towering!\",\"He sets our sins as far as east is from the west.\",\"Our days are brief as short-lived\",\"summer meadows’ flowering,\",\"yet in His love we are for ever blest.\",\"3 May children’s children learn that love amazing,\",\"all creatures bow before His universal throne;\",\"His whole dominion join in everlasting praising:\",\"glory to God, my soul, and God alone!\",\"Timothy Dudley-Smith\",\"\'Our God be praised, and on His Name be blessing\' by Timothy Dudley-Smith (b. 1926) © Timothy Dudley-Smith in Europe and Africa. © Hope Publishing Company in the United States of America and the rest of the world. Reproduced by permission of Oxford University Press. All rights reserved.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1346', 1346, 'One more step along the world I go', 'MP', 'en', '1971 Stainer & Bell Ltd www.stainer.co.uk', '', 0, 0, 0, 0, 1, '1 One more step along the world I go,
one more step along the world I go;');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1346', 'verse', 1, 0, '[\"1 One more step along the world I go,\",\"one more step along the world I go;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1347', 1347, 'Our God, He lives forever', 'MP', 'en', '', '', 0, 0, 0, 0, 1, '1 Our God, He lives for ever,
He reigns in power and love.
Let earth bow down before Him,
for He is exalted.
We look to Yahweh, Yahweh,
for ever Yahweh,Yahweh.
2 Our hope is God Almighty,
His love is greater than all.
Lift high the God of heaven,
give all the honour.
We look to Yahweh, Yahweh,
our hope is Yahweh, Yahweh.
He shall reign for ever,
He shall reign for ever,
He shall reign for ever and ever.
And He shall reign for ever,
He shall reign for ever,
He shall reign for ever and ever,
our God.
We look to Yahweh, Yahweh,
for ever Yahweh, Yahweh.
We look to Yahweh, Yahweh,
our hope is Yahweh, Yahweh.
(x2)
He shall reign for ever,
He shall reign for ever,
He shall reign for ever and ever.
And he shall reign...
He shall reign...
He shall reign for ever.
He shall reign for ever.
He shall reign for ever and ever,
our God.
Reuben Morgan
Words & Music by Reuben Morgan © 2009 Hillsong Music Publishing CCLI 5409086');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1347', 'verse', 1, 0, '[\"1 Our God, He lives for ever,\",\"He reigns in power and love.\",\"Let earth bow down before Him,\",\"for He is exalted.\",\"We look to Yahweh, Yahweh,\",\"for ever Yahweh,Yahweh.\",\"2 Our hope is God Almighty,\",\"His love is greater than all.\",\"Lift high the God of heaven,\",\"give all the honour.\",\"We look to Yahweh, Yahweh,\",\"our hope is Yahweh, Yahweh.\",\"He shall reign for ever,\",\"He shall reign for ever,\",\"He shall reign for ever and ever.\",\"And He shall reign for ever,\",\"He shall reign for ever,\",\"He shall reign for ever and ever,\",\"our God.\",\"We look to Yahweh, Yahweh,\",\"for ever Yahweh, Yahweh.\",\"We look to Yahweh, Yahweh,\",\"our hope is Yahweh, Yahweh.\",\"(x2)\",\"He shall reign for ever,\",\"He shall reign for ever,\",\"He shall reign for ever and ever.\",\"And he shall reign...\",\"He shall reign...\",\"He shall reign for ever.\",\"He shall reign for ever.\",\"He shall reign for ever and ever,\",\"our God.\",\"Reuben Morgan\",\"Words & Music by Reuben Morgan © 2009 Hillsong Music Publishing CCLI 5409086\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1348', 1348, 'Praise God from whom all blessings ﬂow', 'MP', 'en', '', '', 0, 0, 0, 0, 1, 'Praise God from whom all blessings flow,
praise Him all creatures here below.
Praise Him above, You heavenly host,
praise Father, Son and Holy Ghost.
Praise God...
Give glory to the Father,
give glory to the Son,
give glory to the Spirit,
while endless ages run.
‘Worthy the Lamb,’ all heaven cries,
‘to be exalted thus’:
‘Worthy the Lamb,’ our hearts reply,
‘for He was slain for us.’
Praise God from whom all blessings flow,
praise Him all creatures here below.
Praise Him above, You heavenly host,
praise Father, Son and Holy Ghost.
Give glory to the Father...
Praise God...
Praise God from whom all blessings flow,
praise God from whom all blessings flow.
(x4)
Praise God...
Praise God...
Andy Piercy / David Clifton
IQ Music Ltd as MP25');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1348', 'chorus', 0, 0, '[\"Praise God from whom all blessings flow,\",\"praise Him all creatures here below.\",\"Praise Him above, You heavenly host,\",\"praise Father, Son and Holy Ghost.\",\"Praise God...\",\"Give glory to the Father,\",\"give glory to the Son,\",\"give glory to the Spirit,\",\"while endless ages run.\",\"‘Worthy the Lamb,’ all heaven cries,\",\"‘to be exalted thus’:\",\"‘Worthy the Lamb,’ our hearts reply,\",\"‘for He was slain for us.’\",\"Praise God from whom all blessings flow,\",\"praise Him all creatures here below.\",\"Praise Him above, You heavenly host,\",\"praise Father, Son and Holy Ghost.\",\"Give glory to the Father...\",\"Praise God...\",\"Praise God from whom all blessings flow,\",\"praise God from whom all blessings flow.\",\"(x4)\",\"Praise God...\",\"Praise God...\",\"Andy Piercy \\/ David Clifton\",\"IQ Music Ltd as MP25\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1349', 1349, 'See His love', 'MP', 'en', '©  2005 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 0, 'See His love nailed to a cross,
perfect and blameless life
given as sacrifice.
See Him there all in the name of love,
broken, yet glorious,
all for the sake of us.
This is Jesus in His glory,
king of heaven, dying for me.
It is finished, He has done it.
Death is beaten, heaven beckons me.
2 Greater love no one could ever show,
mercy so undeserved,
freedom I should not know.
All my sin, all of my hidden shame,
died with Him on the cross,
eternity won for us.
This is Jesus...
Such love, such love,
such love is this for me.
(x4)
This is Jesus...
Tom Lockley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1349', 'chorus', 0, 0, '[\"See His love nailed to a cross,\",\"perfect and blameless life\",\"given as sacrifice.\",\"See Him there all in the name of love,\",\"broken, yet glorious,\",\"all for the sake of us.\",\"This is Jesus in His glory,\",\"king of heaven, dying for me.\",\"It is finished, He has done it.\",\"Death is beaten, heaven beckons me.\",\"2 Greater love no one could ever show,\",\"mercy so undeserved,\",\"freedom I should not know.\",\"All my sin, all of my hidden shame,\",\"died with Him on the cross,\",\"eternity won for us.\",\"This is Jesus...\",\"Such love, such love,\",\"such love is this for me.\",\"(x4)\",\"This is Jesus...\",\"Tom Lockley\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1350', 1350, 'Speak, O Lord as we come to You', 'MP', 'en', '© 2005 Thankyou Music/Adm. byCapitol CMG Publishing worldwide, excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 0, '1 Speak, O Lord, as we come to You
to receive the food of Your holy word.
Take Your truth, plant it deep in us;
shape and fashion us in Your likeness,
that the light of Christ might be seen today
in our acts of love and our deeds of faith.
Speak, O Lord, and fulfil in us
all Your purposes, for Your glory.
2 Teach us, Lord, full obedience,
holy reverence, true humility.
Test our thoughts and our attitudes
in the radiance of Your purity.
Cause our faith to rise, cause our eyes to see
Your majestic love and authority.
Words of power that can never fail;
let their truth prevail over unbelief.
3 Speak, O Lord, and renew our minds;
help us grasp the heights of Your plans for us.
Truths unchanged from the dawn of time
that will echo down through eternity.
And by grace we’ll stand on Your promises,
and by faith we’ll walk as You walk with us.
Speak, O Lord, till Your church is built
and the earth is filled with Your glory.
Keith Getty, Stuart Townend');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1350', 'verse', 1, 0, '[\"1 Speak, O Lord, as we come to You\",\"to receive the food of Your holy word.\",\"Take Your truth, plant it deep in us;\",\"shape and fashion us in Your likeness,\",\"that the light of Christ might be seen today\",\"in our acts of love and our deeds of faith.\",\"Speak, O Lord, and fulfil in us\",\"all Your purposes, for Your glory.\",\"2 Teach us, Lord, full obedience,\",\"holy reverence, true humility.\",\"Test our thoughts and our attitudes\",\"in the radiance of Your purity.\",\"Cause our faith to rise, cause our eyes to see\",\"Your majestic love and authority.\",\"Words of power that can never fail;\",\"let their truth prevail over unbelief.\",\"3 Speak, O Lord, and renew our minds;\",\"help us grasp the heights of Your plans for us.\",\"Truths unchanged from the dawn of time\",\"that will echo down through eternity.\",\"And by grace we’ll stand on Your promises,\",\"and by faith we’ll walk as You walk with us.\",\"Speak, O Lord, till Your church is built\",\"and the earth is filled with Your glory.\",\"Keith Getty, Stuart Townend\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1351', 1351, 'Spirit of God unseen as the wind (words)', 'MP', 'en', '', '', 0, 0, 0, 0, 0, 'Spirit of God, unseen as the wind,
gentle as is the dove:
teach us the truth and help us believe,
show us the Saviour’s love!
1 You spoke to us – long, long ago –
gave us the written word;
we read it still, needing its truth,
through it God’s voice is heard.
Spirit of God, unseen as the wind...
2 Without Your help, we fail our Lord,
we cannot live His way;
we need Your power, we need Your strength,
following Christ each day.
Spirit of God, unseen as the wind...
Margaret Old
Scripture Union as MP25');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1351', 'chorus', 0, 0, '[\"Spirit of God, unseen as the wind,\",\"gentle as is the dove:\",\"teach us the truth and help us believe,\",\"show us the Saviour’s love!\",\"1 You spoke to us – long, long ago –\",\"gave us the written word;\",\"we read it still, needing its truth,\",\"through it God’s voice is heard.\",\"Spirit of God, unseen as the wind...\",\"2 Without Your help, we fail our Lord,\",\"we cannot live His way;\",\"we need Your power, we need Your strength,\",\"following Christ each day.\",\"Spirit of God, unseen as the wind...\",\"Margaret Old\",\"Scripture Union as MP25\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1352', 1352, 'Thank You for the way that You love us', 'MP', 'en', '© 2009 Integrity Worship Music /LeadWorship Songs (Adm. by Capitol CMG Publishing excl. UK, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com) / Word Music Publishing. Used by Permission', '', 0, 0, 0, 0, 1, 'Thank You for the way
that You love us,
how You love us.
Thank You for the way
You have made us.
We were created
for Your pleasure,
for Your presence,
for the glory of Your name.
Thank You for the way
that You love us.
Jesus, faithful king,
Lord, with grateful hearts we sing,
how great is the love,
how great is the love of our Saviour.
The weight of the cross,
the curse of our shame;
You carried it all
and rose from the grave.
How great is the love of our Saviour,
of our Saviour.
2 Thank You for the grace
that has saved us;
You forgave us.
Thank You for the way
You have freed us.
We have been ransomed,
we’ve been rescued,
we’ve been purchased
with the price of Your own life.
Thank You for the way
that You love us.
Jesus, faithful king...
Thank You for the way
that You love us,
how You love us.
(x4)
Thank You for the way
that You love us.
Jesus, faithful king,
Lord, with grateful hearts we sing,
how great is the love,
how great is the love of our Saviour.
The weight of the cross,
the curse of our shame;
You carried it all
and rose from the grave.
How great is the love of our Saviour,
of our Saviour.
Paul Baloche / Meredith Andrew / Jacob Sooter');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1352', 'chorus', 0, 0, '[\"Thank You for the way\",\"that You love us,\",\"how You love us.\",\"Thank You for the way\",\"You have made us.\",\"We were created\",\"for Your pleasure,\",\"for Your presence,\",\"for the glory of Your name.\",\"Thank You for the way\",\"that You love us.\",\"Jesus, faithful king,\",\"Lord, with grateful hearts we sing,\",\"how great is the love,\",\"how great is the love of our Saviour.\",\"The weight of the cross,\",\"the curse of our shame;\",\"You carried it all\",\"and rose from the grave.\",\"How great is the love of our Saviour,\",\"of our Saviour.\",\"2 Thank You for the grace\",\"that has saved us;\",\"You forgave us.\",\"Thank You for the way\",\"You have freed us.\",\"We have been ransomed,\",\"we’ve been rescued,\",\"we’ve been purchased\",\"with the price of Your own life.\",\"Thank You for the way\",\"that You love us.\",\"Jesus, faithful king...\",\"Thank You for the way\",\"that You love us,\",\"how You love us.\",\"(x4)\",\"Thank You for the way\",\"that You love us.\",\"Jesus, faithful king,\",\"Lord, with grateful hearts we sing,\",\"how great is the love,\",\"how great is the love of our Saviour.\",\"The weight of the cross,\",\"the curse of our shame;\",\"You carried it all\",\"and rose from the grave.\",\"How great is the love of our Saviour,\",\"of our Saviour.\",\"Paul Baloche \\/ Meredith Andrew \\/ Jacob Sooter\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1353', 1353, 'The perfect wisdom of our God (50%)', 'MP', 'en', '(c) 2011 Thankyou Music (Adm. by Capitol CMG Publishing worldwide excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook, songs@integritymusic.com) / Getty Music (info@gettymusic.com) Used by Permission', '', 0, 0, 0, 0, 0, '1 The perfect wisdom of our God,
revealed in all the universe:
all things created by His hand,
and held together at His command.
He knows the mysteries of the seas,
the secrets of the stars are His;
He guides the planets on their way
and turns the earth through another day.
2 The matchless wisdom of His ways
that mark the path of righteousness;
His word a lamp unto my feet,
His Spirit teaching and guiding me.
And, oh, the mystery of the cross,
that God should suffer for the lost,
so that the fool might shame the wise
and all the glory might go to Christ.
3 O grant me wisdom from above,
to pray for peace and cling to love,
and teach me humbly to receive
the sun and rain of Your sovereignty.
Each strand of sorrow has a place
within this tapestry of grace;
so through the trials I choose to say:
‘Your perfect will in Your perfect way.’
Each strand of sorrow has a place
within this tapestry of grace;
so through the trials I choose to say:
‘Your perfect will in Your perfect way.’
Stuart Townend / Keith Getty');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1353', 'verse', 1, 0, '[\"1 The perfect wisdom of our God,\",\"revealed in all the universe:\",\"all things created by His hand,\",\"and held together at His command.\",\"He knows the mysteries of the seas,\",\"the secrets of the stars are His;\",\"He guides the planets on their way\",\"and turns the earth through another day.\",\"2 The matchless wisdom of His ways\",\"that mark the path of righteousness;\",\"His word a lamp unto my feet,\",\"His Spirit teaching and guiding me.\",\"And, oh, the mystery of the cross,\",\"that God should suffer for the lost,\",\"so that the fool might shame the wise\",\"and all the glory might go to Christ.\",\"3 O grant me wisdom from above,\",\"to pray for peace and cling to love,\",\"and teach me humbly to receive\",\"the sun and rain of Your sovereignty.\",\"Each strand of sorrow has a place\",\"within this tapestry of grace;\",\"so through the trials I choose to say:\",\"‘Your perfect will in Your perfect way.’\",\"Each strand of sorrow has a place\",\"within this tapestry of grace;\",\"so through the trials I choose to say:\",\"‘Your perfect will in Your perfect way.’\",\"Stuart Townend \\/ Keith Getty\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1354', 1354, 'The Church of God shall stand (music)', 'MP', 'en', '1999 LINDA MAWSON/PRAISE TRUST', '', 0, 0, 0, 0, 1, 'The Church of God shall stand
though troubles rage without,
where hope is built on shifting sand
and faith is lost in doubt.
In Christ shall all be well;
His promises endure;
before the very gates of hell
His Church shall stand secure.
2 The word of God shall stand,
His truth for this our day:
that word His providence has planned
shall never pass away.
The voice of God is heard');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1354', 'verse', 1, 0, '[\"The Church of God shall stand\",\"though troubles rage without,\",\"where hope is built on shifting sand\",\"and faith is lost in doubt.\",\"In Christ shall all be well;\",\"His promises endure;\",\"before the very gates of hell\",\"His Church shall stand secure.\",\"2 The word of God shall stand,\",\"His truth for this our day:\",\"that word His providence has planned\",\"shall never pass away.\",\"The voice of God is heard\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1355', 1355, 'The precious blood of Jesus Christ', 'MP', 'en', '', '', 0, 0, 0, 0, 1, '1 The precious blood of Jesus Christ redeems.
Forgiven, I’m alive, restored, set free.
Your majesty resides inside of me.
For ever I believe, for ever I believe.
2 Arrested by Your truth and righteousness,
Your grace has overwhelmed my brokenness.
Convicted by Your Spirit, led by Your word,
Your love will never fail, Your love will never fail.
I know You gave the world
Your only Son for us
to know Your name,
to live within the Saviour’s love.
And He took my place,
knowing He’d be crucified.
And You loved, You loved
a people undeserving.
’Cause I know You gave the world...
’Cause I know You gave the world...
Arrested by Your truth and righteousness,
Your grace has overwhelmed my brokenness.
Convicted by Your Spirit, led by Your word,
Your love will never fail, Your love will never fail.
I know You gave the world
Your only Son for us
to know Your name,
to live within the Saviour’s love.
And He took my place,
knowing He’d be crucified.
And You loved,You loved
a people undeserving.
’Cause I know You gave the world...
’Cause I know You gave the world...
’Cause I know You gave the world...
Matt Crocker
Words & Music by Matt Crocker © 2007 Hillsong Music Publishing (APRA). CCLI: 4869919');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1355', 'verse', 1, 0, '[\"1 The precious blood of Jesus Christ redeems.\",\"Forgiven, I’m alive, restored, set free.\",\"Your majesty resides inside of me.\",\"For ever I believe, for ever I believe.\",\"2 Arrested by Your truth and righteousness,\",\"Your grace has overwhelmed my brokenness.\",\"Convicted by Your Spirit, led by Your word,\",\"Your love will never fail, Your love will never fail.\",\"I know You gave the world\",\"Your only Son for us\",\"to know Your name,\",\"to live within the Saviour’s love.\",\"And He took my place,\",\"knowing He’d be crucified.\",\"And You loved, You loved\",\"a people undeserving.\",\"’Cause I know You gave the world...\",\"’Cause I know You gave the world...\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1355', 'chorus', 0, 1, '[\"Arrested by Your truth and righteousness,\",\"Your grace has overwhelmed my brokenness.\",\"Convicted by Your Spirit, led by Your word,\",\"Your love will never fail, Your love will never fail.\",\"I know You gave the world\",\"Your only Son for us\",\"to know Your name,\",\"to live within the Saviour’s love.\",\"And He took my place,\",\"knowing He’d be crucified.\",\"And You loved,You loved\",\"a people undeserving.\",\"’Cause I know You gave the world...\",\"’Cause I know You gave the world...\",\"’Cause I know You gave the world...\",\"Matt Crocker\",\"Words & Music by Matt Crocker © 2007 Hillsong Music Publishing (APRA). CCLI: 4869919\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1356', 1356, 'The sun cannot compare', 'MP', 'en', '© 2003 Integrity\'s Hosanna! Music / adm worldwide by Capitol CMG Publishing excl UK admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 1, 'The Sun cannot compare
to the glory of Your love;
there is no shadow in Your presence;
no mortal man would dare
to stand before Your throne,
before the holy One of heaven;
it’s only by Your blood,
and it’s only through Your mercy,
Lord, I come.
I bring an offering of worship to my king;
no one on earth deserves
the praises that I sing.
Jesus, may You receive
the honour that You’re due;
O Lord, I bring an offering to You.
I bring an offering to You.
The sun cannot compare...
I bring an offering...
I bring an offering...
O Lord, I bring an offering to You.
O Lord, I bring an offering to You;
O Lord, I bring an offering to You;
I bring an offering to You.
Paul Baloche');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1356', 'chorus', 0, 0, '[\"The Sun cannot compare\",\"to the glory of Your love;\",\"there is no shadow in Your presence;\",\"no mortal man would dare\",\"to stand before Your throne,\",\"before the holy One of heaven;\",\"it’s only by Your blood,\",\"and it’s only through Your mercy,\",\"Lord, I come.\",\"I bring an offering of worship to my king;\",\"no one on earth deserves\",\"the praises that I sing.\",\"Jesus, may You receive\",\"the honour that You’re due;\",\"O Lord, I bring an offering to You.\",\"I bring an offering to You.\",\"The sun cannot compare...\",\"I bring an offering...\",\"I bring an offering...\",\"O Lord, I bring an offering to You.\",\"O Lord, I bring an offering to You;\",\"O Lord, I bring an offering to You;\",\"I bring an offering to You.\",\"Paul Baloche\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1357', 1357, 'The word of God', 'MP', 'en', '©  2012 Thankyou Music (Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com) / HBC Worship Music / Sony/ATV Cross Keys Publishing. Used by Permission', '', 0, 0, 0, 0, 1, 'The word of God is light in my darkness,
hope for the hopeless, strong and true.
The word of God is strength for the weary,
a shield for those who trust in You,
a shield for those who trust in You.
Everything will fade, everything will fade,
the heavens and the earth will pass away,
but You will remain, yes, You will remain always.
Jesus, faithful Word of God,
the anchor of my heart;
You’re everything You say You are.
Greater than my deepest needs,
the ground beneath my feet,
Your promises won’t fail me now.
The word of God is light in my darkness,
hope for the hopeless, strong and true.
The word of God is strength for the weary,
a shield for those who trust in You,
a shield for those who trust in You.
Everything will fade, everything will fade,
the heavens and the earth will pass away,
but You will remain, yes, You will remain always.
Jesus, faithful Word of God...
You will not fail us,
You will not fail us,
You will not fail us,
O Word of God.
You will not fail us...
Andi Rozier / Brenton Brown');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1357', 'chorus', 0, 0, '[\"The word of God is light in my darkness,\",\"hope for the hopeless, strong and true.\",\"The word of God is strength for the weary,\",\"a shield for those who trust in You,\",\"a shield for those who trust in You.\",\"Everything will fade, everything will fade,\",\"the heavens and the earth will pass away,\",\"but You will remain, yes, You will remain always.\",\"Jesus, faithful Word of God,\",\"the anchor of my heart;\",\"You’re everything You say You are.\",\"Greater than my deepest needs,\",\"the ground beneath my feet,\",\"Your promises won’t fail me now.\",\"The word of God is light in my darkness,\",\"hope for the hopeless, strong and true.\",\"The word of God is strength for the weary,\",\"a shield for those who trust in You,\",\"a shield for those who trust in You.\",\"Everything will fade, everything will fade,\",\"the heavens and the earth will pass away,\",\"but You will remain, yes, You will remain always.\",\"Jesus, faithful Word of God...\",\"You will not fail us,\",\"You will not fail us,\",\"You will not fail us,\",\"O Word of God.\",\"You will not fail us...\",\"Andi Rozier \\/ Brenton Brown\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1358', 1358, 'There is a hope', 'MP', 'en', '(c) 2007 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 0, 'There is a hope that burns within my heart,
that gives me strength for every passing day;
a glimpse of glory now revealed in meagre part,
yet drives all doubt away:
I stand in Christ, with sins forgiven,
and Christ in me, the hope of heaven!
My highest calling and my deepest joy,
to make His will my home.
There is a hope that lifts my weary head,
a consolation strong against despair,
that when the world has plunged me
in its deepest pit,
I find the Saviour there!
Through present sufferings, future’s fear,
He whispers ‘Courage!’ in my ear.
For I am safe in everlasting arms
and they will lead me home.
There is a hope that stands the test of time,
that lifts my eyes beyond the beckoning grave,
to see the matchless beauty of a day divine
when I behold His face!
When sufferings cease and sorrows die,
and every longing satisfied,
then joy unspeakable will flood my soul,
for I am truly home.
Stuart Townend / Mark Edwards THANK YOU Music');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1358', 'verse', 1, 0, '[\"There is a hope that burns within my heart,\",\"that gives me strength for every passing day;\",\"a glimpse of glory now revealed in meagre part,\",\"yet drives all doubt away:\",\"I stand in Christ, with sins forgiven,\",\"and Christ in me, the hope of heaven!\",\"My highest calling and my deepest joy,\",\"to make His will my home.\",\"There is a hope that lifts my weary head,\",\"a consolation strong against despair,\",\"that when the world has plunged me\",\"in its deepest pit,\",\"I find the Saviour there!\",\"Through present sufferings, future’s fear,\",\"He whispers ‘Courage!’ in my ear.\",\"For I am safe in everlasting arms\",\"and they will lead me home.\",\"There is a hope that stands the test of time,\",\"that lifts my eyes beyond the beckoning grave,\",\"to see the matchless beauty of a day divine\",\"when I behold His face!\",\"When sufferings cease and sorrows die,\",\"and every longing satisfied,\",\"then joy unspeakable will flood my soul,\",\"for I am truly home.\",\"Stuart Townend \\/ Mark Edwards THANK YOU Music\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1359', 1359, 'There is an everlasting kindness', 'MP', 'en', '© 2008 Thankyou Music/Adm. by Capitol CMG Publishing worldwide excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 1, 'There is an everlasting kindness
You lavished on us,
when the radiance of heaven came to rescue the lost.
You called the sheep without a shepherd
to leave their distress,
for Your streams of forgiveness
and the shade of Your rest.
2 And with compassion for the hurting
You reached out Your hand,
as the lame ran to meet You
and the dead breathed again.
You saw behind the eyes of sorrow
and shared in our tears;
heard the sigh of the weary, let the children draw near.
What boundless love, what fathomless grace
You have shown us, O God of compassion.
Each day we live an offering of praise
as we show to the world Your compassion.
3 We stood beneath the cross of Calvary
and gazed on Your face,
at the thorns of oppression and wounds of disgrace;
for surely You have borne our suffering
and carried our grief,
as You pardoned the scoffer
and showed grace to the thief.
What boundless love...
4 How beautiful the feet that carry this gospel of peace
to the fields of injustice and the valleys of need;
to be a voice of hope and healing, to answer the cries
of the hungry and helpless with the mercy of Christ.
What boundless love...
Keith and Kristyn Getty / Stuart Townend THANK YOU Music');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1359', 'chorus', 0, 0, '[\"There is an everlasting kindness\",\"You lavished on us,\",\"when the radiance of heaven came to rescue the lost.\",\"You called the sheep without a shepherd\",\"to leave their distress,\",\"for Your streams of forgiveness\",\"and the shade of Your rest.\",\"2 And with compassion for the hurting\",\"You reached out Your hand,\",\"as the lame ran to meet You\",\"and the dead breathed again.\",\"You saw behind the eyes of sorrow\",\"and shared in our tears;\",\"heard the sigh of the weary, let the children draw near.\",\"What boundless love, what fathomless grace\",\"You have shown us, O God of compassion.\",\"Each day we live an offering of praise\",\"as we show to the world Your compassion.\",\"3 We stood beneath the cross of Calvary\",\"and gazed on Your face,\",\"at the thorns of oppression and wounds of disgrace;\",\"for surely You have borne our suffering\",\"and carried our grief,\",\"as You pardoned the scoffer\",\"and showed grace to the thief.\",\"What boundless love...\",\"4 How beautiful the feet that carry this gospel of peace\",\"to the fields of injustice and the valleys of need;\",\"to be a voice of hope and healing, to answer the cries\",\"of the hungry and helpless with the mercy of Christ.\",\"What boundless love...\",\"Keith and Kristyn Getty \\/ Stuart Townend THANK YOU Music\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1360', 1360, 'There is strength', 'MP', 'en', '©  2010 Thankyou Music/worshiptogether.com (Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com) / Jack Mooring Music/Meaux Jeaux Music. Used by Permission', '', 0, 0, 0, 0, 1, 'There is strength within the sorrow,
there is beauty in our tears;
You meet us in our mourning
with a love that casts out fear.
You are working in our waiting,
sanctifying us;
when beyond our understanding,
You’re teaching us to trust.
Your plans are still to prosper,
You’ve not forgotten us;
You’re with us in the fire and the flood.
Faithful for ever, perfect in love,
You are sovereign over us.
2 You are wisdom unimagined;
who could understand Your ways,
reigning high above the heavens,
reaching down in endless grace?
You’re the lifter of the lowly,
compassionate and kind;
You surround and You uphold me
and Your promises are my delight.
Your plans are still to prosper...
Even when the enemy means for evil,
You turn it for our good;
You turn it for our good and for Your glory.
Even in the valley You are faithful,
You’re working for our good,
You’re working for our good and for Your glory.
Even when...
Your plans are still to prosper...
Faithful for ever, perfect in love,
You are sovereign over us.
Aaron Keyes / Jack Mooring / Bryan Brown');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1360', 'chorus', 0, 0, '[\"There is strength within the sorrow,\",\"there is beauty in our tears;\",\"You meet us in our mourning\",\"with a love that casts out fear.\",\"You are working in our waiting,\",\"sanctifying us;\",\"when beyond our understanding,\",\"You’re teaching us to trust.\",\"Your plans are still to prosper,\",\"You’ve not forgotten us;\",\"You’re with us in the fire and the flood.\",\"Faithful for ever, perfect in love,\",\"You are sovereign over us.\",\"2 You are wisdom unimagined;\",\"who could understand Your ways,\",\"reigning high above the heavens,\",\"reaching down in endless grace?\",\"You’re the lifter of the lowly,\",\"compassionate and kind;\",\"You surround and You uphold me\",\"and Your promises are my delight.\",\"Your plans are still to prosper...\",\"Even when the enemy means for evil,\",\"You turn it for our good;\",\"You turn it for our good and for Your glory.\",\"Even in the valley You are faithful,\",\"You’re working for our good,\",\"You’re working for our good and for Your glory.\",\"Even when...\",\"Your plans are still to prosper...\",\"Faithful for ever, perfect in love,\",\"You are sovereign over us.\",\"Aaron Keyes \\/ Jack Mooring \\/ Bryan Brown\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1361', 1361, 'This is how we know', 'MP', 'en', '(c) 2009 Thankyou Music/Said And Done Music/Adm. By CAPITOL CMG Publishing worldwide excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 0, 1, 'This is how we know,
this is how we know what love is:
just one look at Your cross.
And this is where we see,
this is where we see how love works,
for You surrendered Your all.
And this is how we know
that You have loved us first,
and this is where we chose
to love You in return.
For You so loved the world
that You gave Your only son.
Love amazing, so divine,
we will love You in return.
For this life that You give,
for this death that You have died,
love amazing, so divine –
we will love You in reply, Lord.
This is how we know,
this is how we know what love is:
just one look at Your cross.
And this is where we see,
this is where we see how love works,
for You surrendered Your all.
And this is how we know
that You have loved us first,
and this is where we chose
to love You in return.
For You so loved the world...
For You so loved the world...
And our love will be loud,
our love will be strong;
our love should be hands and feet
that serve You in this world.
So let it stay true and let it endure,
that You will be glorified and worshipped
and adored.
For You so loved the world...
Saviour of the world.
King Jesus, we love You,
for we have been loved.
(x4)
We have been loved.
Matt and Beth Redman');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1361', 'chorus', 0, 0, '[\"This is how we know,\",\"this is how we know what love is:\",\"just one look at Your cross.\",\"And this is where we see,\",\"this is where we see how love works,\",\"for You surrendered Your all.\",\"And this is how we know\",\"that You have loved us first,\",\"and this is where we chose\",\"to love You in return.\",\"For You so loved the world\",\"that You gave Your only son.\",\"Love amazing, so divine,\",\"we will love You in return.\",\"For this life that You give,\",\"for this death that You have died,\",\"love amazing, so divine –\",\"we will love You in reply, Lord.\",\"This is how we know,\",\"this is how we know what love is:\",\"just one look at Your cross.\",\"And this is where we see,\",\"this is where we see how love works,\",\"for You surrendered Your all.\",\"And this is how we know\",\"that You have loved us first,\",\"and this is where we chose\",\"to love You in return.\",\"For You so loved the world...\",\"For You so loved the world...\",\"And our love will be loud,\",\"our love will be strong;\",\"our love should be hands and feet\",\"that serve You in this world.\",\"So let it stay true and let it endure,\",\"that You will be glorified and worshipped\",\"and adored.\",\"For You so loved the world...\",\"Saviour of the world.\",\"King Jesus, we love You,\",\"for we have been loved.\",\"(x4)\",\"We have been loved.\",\"Matt and Beth Redman\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1362', 1362, 'Water You turned into wine', 'MP', 'en', '© 2010 Thankyou Music/worshiptogether.com Songs/sixsteps Music/Vamos Publishing/Said And Done Music/Adm by Integritymusic.com, a division', '', 0, 0, 0, 0, 1, 'Water You turned into wine,
opened the eyes of the blind;
there’s no one like You,
none like You.
Into the darkness You shine,
out of the ashes we rise.
There’s no one like You,
none like You.
Our God is greater, our God is stronger;
God, You are higher than any other.
Our God is healer, awesome in power,
our God, our God.
(repeat verse 2)
Our God is greater...
Our God is greater...
And if our God is for us,
then who could ever stop us;
and if our God is with us,
then what could stand against?
And if our God is for us...
What could stand against?
Our God is greater, our God is stronger;
God, You are higher than any other.
Our God is healer, awesome in power,
our God, our God.
Our God is greater...
Chris Tomlin, Jesse Reeves, Jonas Myrin, Matt Redman');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1362', 'chorus', 0, 0, '[\"Water You turned into wine,\",\"opened the eyes of the blind;\",\"there’s no one like You,\",\"none like You.\",\"Into the darkness You shine,\",\"out of the ashes we rise.\",\"There’s no one like You,\",\"none like You.\",\"Our God is greater, our God is stronger;\",\"God, You are higher than any other.\",\"Our God is healer, awesome in power,\",\"our God, our God.\",\"(repeat verse 2)\",\"Our God is greater...\",\"Our God is greater...\",\"And if our God is for us,\",\"then who could ever stop us;\",\"and if our God is with us,\",\"then what could stand against?\",\"And if our God is for us...\",\"What could stand against?\",\"Our God is greater, our God is stronger;\",\"God, You are higher than any other.\",\"Our God is healer, awesome in power,\",\"our God, our God.\",\"Our God is greater...\",\"Chris Tomlin, Jesse Reeves, Jonas Myrin, Matt Redman\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1363', 1363, 'Wake every heart', 'MP', 'en', '(c) 2006 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 1, 'Wake every heart and every tongue
to sing the new eternal song,
and crown Him King of glory now,
confess Him Lord of all.
You are the highest,
You are the greatest,
You are the Lord of all.
Angels will worship,
nations will bow down
to the Lord of all.
2 The day will come when all will sing
and glorify our matchless King.
Your name unrivalled stands alone.
You are the Lord of all.
You are the highest...
Let every heart, let every tongue
sing of Your name, sing of Your name.
Let every heart, let every tongue
sing, sing, sing.
Let every heart...
You are the highest...
We’re lifting You higher,
higher and higher,
lifting You higher,
higher and higher,
lifting You higher,
higher and higher,
O Lord.
We’re lifting You higher...
You are the highest...
Nick Herbert and Tim Hughes');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1363', 'chorus', 0, 0, '[\"Wake every heart and every tongue\",\"to sing the new eternal song,\",\"and crown Him King of glory now,\",\"confess Him Lord of all.\",\"You are the highest,\",\"You are the greatest,\",\"You are the Lord of all.\",\"Angels will worship,\",\"nations will bow down\",\"to the Lord of all.\",\"2 The day will come when all will sing\",\"and glorify our matchless King.\",\"Your name unrivalled stands alone.\",\"You are the Lord of all.\",\"You are the highest...\",\"Let every heart, let every tongue\",\"sing of Your name, sing of Your name.\",\"Let every heart, let every tongue\",\"sing, sing, sing.\",\"Let every heart...\",\"You are the highest...\",\"We’re lifting You higher,\",\"higher and higher,\",\"lifting You higher,\",\"higher and higher,\",\"lifting You higher,\",\"higher and higher,\",\"O Lord.\",\"We’re lifting You higher...\",\"You are the highest...\",\"Nick Herbert and Tim Hughes\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1364', 1364, 'We believe You’re a God who can mend', 'MP', 'en', '©  2008 Thankyou Music/Livingstone Collective /Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 1, 'We believe You’re a God
who can mend the broken,
turn sorrow to joy.
We believe You’re a God
who can heal our diseases,
repair what’s destroyed.
Jesus died and then rose victorious,
now in triumph His life He offers.
So breathe on us now,
come, breathe on us now,
come, pour out Your love from heaven.
Come, breathe on us now,
let this be the hour,
come, Lord and change us for ever.
We believe You’re a God
who can free the captive,
change darkness to light.
We believe You’re a God
who can rescue the sinner,
turn death into life.
Bringing peace to the restless soul,
giving purpose and making whole.
So breathe on us now,
come, breathe on us now,
come, pour out Your love from heaven.
Come, breathe on us now,
let this be the hour,
come, Lord and change us for ever.
Life-giving Spirit, come in this moment.
Blessing from heaven, show us Your power.
So breathe on us now,
come, breathe on us now,
come, pour out Your love from heaven.
Come, breathe on us now,
let this be the hour,
come, Lord and change us.
Come, breathe on us now...
He will wipe tears from your eyes,
He will restore what’s been lost,
and He’ll give back what’s been taken.
He will give sight to the blind,
He will give strength to the weak,
and He will care for the broken.
He knows your deepest need,
and there is mercy to meet
all of your deepest longings.
A taste of heaven on earth
now freely given to us;
the Father’s glory come down.
If you call on His name
then I know He will save;
He will not ever abandon.
He will not ever abandon.
Lou and Nathan Fellingham and Busbee');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1364', 'chorus', 0, 0, '[\"We believe You’re a God\",\"who can mend the broken,\",\"turn sorrow to joy.\",\"We believe You’re a God\",\"who can heal our diseases,\",\"repair what’s destroyed.\",\"Jesus died and then rose victorious,\",\"now in triumph His life He offers.\",\"So breathe on us now,\",\"come, breathe on us now,\",\"come, pour out Your love from heaven.\",\"Come, breathe on us now,\",\"let this be the hour,\",\"come, Lord and change us for ever.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1364', 'chorus', 0, 1, '[\"We believe You’re a God\",\"who can free the captive,\",\"change darkness to light.\",\"We believe You’re a God\",\"who can rescue the sinner,\",\"turn death into life.\",\"Bringing peace to the restless soul,\",\"giving purpose and making whole.\",\"So breathe on us now,\",\"come, breathe on us now,\",\"come, pour out Your love from heaven.\",\"Come, breathe on us now,\",\"let this be the hour,\",\"come, Lord and change us for ever.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1364', 'chorus', 0, 2, '[\"Life-giving Spirit, come in this moment.\",\"Blessing from heaven, show us Your power.\",\"So breathe on us now,\",\"come, breathe on us now,\",\"come, pour out Your love from heaven.\",\"Come, breathe on us now,\",\"let this be the hour,\",\"come, Lord and change us.\",\"Come, breathe on us now...\",\"He will wipe tears from your eyes,\",\"He will restore what’s been lost,\",\"and He’ll give back what’s been taken.\",\"He will give sight to the blind,\",\"He will give strength to the weak,\",\"and He will care for the broken.\",\"He knows your deepest need,\",\"and there is mercy to meet\",\"all of your deepest longings.\",\"A taste of heaven on earth\",\"now freely given to us;\",\"the Father’s glory come down.\",\"If you call on His name\",\"then I know He will save;\",\"He will not ever abandon.\",\"He will not ever abandon.\",\"Lou and Nathan Fellingham and Busbee\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1365', 1365, 'We’re looking to Your promise of old', 'MP', 'en', '©  1996 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 1, 'We’re looking to Your promise of old,
that if we pray and humble ourselves,
You will come and heal our land,
You will come, You will come.
2 We’re looking to the promise
You made,
that if we turn and look to Your face,
You will come and heal our land,
You will come, You will come to us.
Lord, send revival, start with me.
For I am one of unclean lips,
and my eyes have seen the King.
Your glory I have glimpsed:
send revival, start with me.
Matt Redman');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1365', 'chorus', 0, 0, '[\"We’re looking to Your promise of old,\",\"that if we pray and humble ourselves,\",\"You will come and heal our land,\",\"You will come, You will come.\",\"2 We’re looking to the promise\",\"You made,\",\"that if we turn and look to Your face,\",\"You will come and heal our land,\",\"You will come, You will come to us.\",\"Lord, send revival, start with me.\",\"For I am one of unclean lips,\",\"and my eyes have seen the King.\",\"Your glory I have glimpsed:\",\"send revival, start with me.\",\"Matt Redman\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1366', 1366, 'What a friend I’ve found', 'MP', 'en', '© 1996 Curious? Music/Adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by permission', '', 0, 0, 0, 0, 0, 'What a friend I’ve found,
closer than a brother:
I have felt Your touch,
more intimate than lovers.
Jesus, Jesus, Jesus
friend for ever.
2 What a hope I’ve found,
more faithful than a mother.
It would break my heart
to ever lose each other.
Jesus, Jesus...
Martin Smith');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1366', 'chorus', 0, 0, '[\"What a friend I’ve found,\",\"closer than a brother:\",\"I have felt Your touch,\",\"more intimate than lovers.\",\"Jesus, Jesus, Jesus\",\"friend for ever.\",\"2 What a hope I’ve found,\",\"more faithful than a mother.\",\"It would break my heart\",\"to ever lose each other.\",\"Jesus, Jesus...\",\"Martin Smith\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1367', 1367, 'What glories wait on God’s appointed time (words)', 'MP', 'en', '', '', 0, 0, 0, 0, 0, 'What glories wait on God’s appointed time,
what freedom from our bondage to decay!
We shall be raised to heaven’s height sublime,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1367', 'verse', 1, 0, '[\"What glories wait on God’s appointed time,\",\"what freedom from our bondage to decay!\",\"We shall be raised to heaven’s height sublime,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1368', 1368, 'What grace is mine', 'MP', 'en', '©  2008 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 0, 'What grace is mine, that He who dwells
in endless light
called through the night to find my distant soul,
and from His scars poured mercy
that would plead for me,
that I might live and in His name be known?
So I will go wherever He is calling me.
I lose my life to find my life in Him.
I give my all to gain the hope that never dies.
I bow my heart, take up my cross and follow Him.
2 What grace is mine to know His breath alive in me?
Beneath His wings, my wakened soul may soar.
All fear can flee, for death’s dark night is overcome:
my Saviour lives and reigns for ever more.
So I will go...
... I bow my heart, take up my cross and follow Him.
Kristyn Getty');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1368', 'chorus', 0, 0, '[\"What grace is mine, that He who dwells\",\"in endless light\",\"called through the night to find my distant soul,\",\"and from His scars poured mercy\",\"that would plead for me,\",\"that I might live and in His name be known?\",\"So I will go wherever He is calling me.\",\"I lose my life to find my life in Him.\",\"I give my all to gain the hope that never dies.\",\"I bow my heart, take up my cross and follow Him.\",\"2 What grace is mine to know His breath alive in me?\",\"Beneath His wings, my wakened soul may soar.\",\"All fear can flee, for death’s dark night is overcome:\",\"my Saviour lives and reigns for ever more.\",\"So I will go...\",\"... I bow my heart, take up my cross and follow Him.\",\"Kristyn Getty\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1369', 1369, 'What heart could hold the weight of Your love', 'MP', 'en', '©  2011 Thankyou Music/Said And Done Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com)/SHOUT! Music Publishing/Sony/ATV Timber Publishing. Used by Permisison', '', 0, 0, 0, 0, 1, 'What heart could hold the weight of Your love,
and know the heights of Your great worth?
What eyes could look on Your glorious face,
shining like the sun?
What heart could hold...
You are holy, holy, holy,
God most high and God most worthy.
You are holy, holy, holy,
Jesus, You are, Jesus, You are.
2 Your name alone has power to raise us.
Your light will shine when all else fades.
Our eyes will look on Your glorious face,
shining like the sun.
Who is like You, God?
You are holy...
You are holy...
... Jesus, You are, Jesus, You are.
Who shall we say You are?
You’re the living God.
Who shall we say You are?
You’re the great ‘I Am’.
The highest name of all,
You’re all You say You are.
You are holy...
... Jesus, You are, Jesus, You are.
. . . Jesus, You are, Jesus, You are.
3 And You will come again in glory
to judge the living and the dead.
All eyes will look on Your glorious face,
shining like the sun.
Who is like You, God?
You are holy...
... Jesus,You are, Jesus You are.
Matt Redman / Jonas Myrin / Jason Ingram');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1369', 'chorus', 0, 0, '[\"What heart could hold the weight of Your love,\",\"and know the heights of Your great worth?\",\"What eyes could look on Your glorious face,\",\"shining like the sun?\",\"What heart could hold...\",\"You are holy, holy, holy,\",\"God most high and God most worthy.\",\"You are holy, holy, holy,\",\"Jesus, You are, Jesus, You are.\",\"2 Your name alone has power to raise us.\",\"Your light will shine when all else fades.\",\"Our eyes will look on Your glorious face,\",\"shining like the sun.\",\"Who is like You, God?\",\"You are holy...\",\"You are holy...\",\"... Jesus, You are, Jesus, You are.\",\"Who shall we say You are?\",\"You’re the living God.\",\"Who shall we say You are?\",\"You’re the great ‘I Am’.\",\"The highest name of all,\",\"You’re all You say You are.\",\"You are holy...\",\"... Jesus, You are, Jesus, You are.\",\". . . Jesus, You are, Jesus, You are.\",\"3 And You will come again in glory\",\"to judge the living and the dead.\",\"All eyes will look on Your glorious face,\",\"shining like the sun.\",\"Who is like You, God?\",\"You are holy...\",\"... Jesus,You are, Jesus You are.\",\"Matt Redman \\/ Jonas Myrin \\/ Jason Ingram\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1370', 1370, 'When I shall reach my home in glory', 'MP', 'en', '', '', 0, 0, 0, 0, 1, 'When I shall reach my home in glory,
and see my Saviour face to face
this shall be all my song and story,
a sinner saved by grace.
Saved by grace (saved by grace),
saved by grace (saved by grace).
For ever I’ll tell the story (story of love).
How Jesus saved (how Jesus saved)
me by His grace (me by His grace)
and brought me to His glory.
2 I’ll tell how by His blood He bought me,
with all our lost and ransomed race;
and how tenderly He sought me
and saved me by His grace.
Saved by grace...
3 I’ll tell them how His Spirit sealed me
and cleansed me from each sinful trace;
and how when sick and worn He healed me,
and saved me by His grace.
Saved by grace…
4 I’ll sing how lovingly He led me
at last to yonder heavenly place;
and how He shepherded and fed me,
and kept me by His grace.
Saved by grace...
5 Yes,when I reach my home in glory,
and see my Saviour face to face;
this shall be all my song and story,
a sinner saved by grace.
Saved by grace...
A B Simpson
out of copyright');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1370', 'chorus', 0, 0, '[\"When I shall reach my home in glory,\",\"and see my Saviour face to face\",\"this shall be all my song and story,\",\"a sinner saved by grace.\",\"Saved by grace (saved by grace),\",\"saved by grace (saved by grace).\",\"For ever I’ll tell the story (story of love).\",\"How Jesus saved (how Jesus saved)\",\"me by His grace (me by His grace)\",\"and brought me to His glory.\",\"2 I’ll tell how by His blood He bought me,\",\"with all our lost and ransomed race;\",\"and how tenderly He sought me\",\"and saved me by His grace.\",\"Saved by grace...\",\"3 I’ll tell them how His Spirit sealed me\",\"and cleansed me from each sinful trace;\",\"and how when sick and worn He healed me,\",\"and saved me by His grace.\",\"Saved by grace…\",\"4 I’ll sing how lovingly He led me\",\"at last to yonder heavenly place;\",\"and how He shepherded and fed me,\",\"and kept me by His grace.\",\"Saved by grace...\",\"5 Yes,when I reach my home in glory,\",\"and see my Saviour face to face;\",\"this shall be all my song and story,\",\"a sinner saved by grace.\",\"Saved by grace...\",\"A B Simpson\",\"out of copyright\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1371', 1371, 'When I stand before Your throne', 'MP', 'en', '©  2011 Thankyou Music/Said And Done Music/A Thousand Generations  Publishing/worshiptogether.com songs/Worship Together Music/sixsteps Music/sixsteps Songs (Admin by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com) / SHOUT! Music Publishing /Chrysalis Music. Used by Permission', '', 0, 0, 0, 0, 1, 'When I stand before Your throne,
dressed in glory not my own,
what a joy I’ll sing of on that day.
No more tears or broken dreams,
forgotten is the minor key;
everything as it was meant to be.
And we will worship, worship.
For ever in Your presence we will sing.
We will worship, worship You;
an endless hallelujah to the King.
I will see You as You are,
love You with unsinning heart,
and see how much You paid to bring me home.
Not till then, Lord, shall I know,
not till then, how much I owe;
everything I am before Your throne.
And we will worship...
No more tears, no more shame,
no more sin and sorrow ever known again.
No more fears, no more pain,
we will see You face to face,
see You face to face.
And we will worship...
And we will worship...
Matt Redman, Jonas Myrin, Chris Tomlin');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1371', 'chorus', 0, 0, '[\"When I stand before Your throne,\",\"dressed in glory not my own,\",\"what a joy I’ll sing of on that day.\",\"No more tears or broken dreams,\",\"forgotten is the minor key;\",\"everything as it was meant to be.\",\"And we will worship, worship.\",\"For ever in Your presence we will sing.\",\"We will worship, worship You;\",\"an endless hallelujah to the King.\",\"I will see You as You are,\",\"love You with unsinning heart,\",\"and see how much You paid to bring me home.\",\"Not till then, Lord, shall I know,\",\"not till then, how much I owe;\",\"everything I am before Your throne.\",\"And we will worship...\",\"No more tears, no more shame,\",\"no more sin and sorrow ever known again.\",\"No more fears, no more pain,\",\"we will see You face to face,\",\"see You face to face.\",\"And we will worship...\",\"And we will worship...\",\"Matt Redman, Jonas Myrin, Chris Tomlin\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1372', 1372, 'When Your Spirit leads give me grace to follow', 'MP', 'en', 'Copyright 1996 Sovereign Lifestyle Music Ltd. Sovereignmusic@aol.com. Used by Permission', '', 0, 0, 0, 0, 0, 'When Your Spirit leads
give me grace to follow.
When Your Spirit speaks
give me ears to hear.
Where Your Spirit reigns
there is liberty.
Teach me, Lord, to live
in the life of Your Spirit.
Teach me, Lord, to live
in the life of Your Spirit.
2 When Your Spirit moves
may my heart be open.
When Your Spirit comes
may my heart receive.
Where Your Spirit reigns...
Chris Bowater');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1372', 'chorus', 0, 0, '[\"When Your Spirit leads\",\"give me grace to follow.\",\"When Your Spirit speaks\",\"give me ears to hear.\",\"Where Your Spirit reigns\",\"there is liberty.\",\"Teach me, Lord, to live\",\"in the life of Your Spirit.\",\"Teach me, Lord, to live\",\"in the life of Your Spirit.\",\"2 When Your Spirit moves\",\"may my heart be open.\",\"When Your Spirit comes\",\"may my heart receive.\",\"Where Your Spirit reigns...\",\"Chris Bowater\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1373', 1373, 'Who breaks the power', 'MP', 'en', '', '', 0, 0, 0, 0, 0, 'Who breaks the power of sin and darkness?
Whose love is mighty and so much stronger?
The King of glory, the King above all kings.
Who shakes the whole earth with holy thunder?
Who leaves us breathless in awe and wonder?
The King of glory, the King above all kings.
This is amazing grace, this is unfailing love,
that You would take my place,
that You would bear my cross.
You would lay down Your life,
that I would be set free:
Jesus, I sing for all that You’ve done for me,
all that You’ve done for me.
2 Who brings our chaos back into order?
Who makes the orphan a son and daughter?
The King of glory, the King above all kings.
Who rules the nations with truth and justice,
shines like the sun in all of its brilliance?
The King of glory, the King above all kings.
This is amazing grace...
Worthy is the Lamb who was slain,
and worthy is the King who conquered the grave.
(x4)
... worthy, worthy, worthy.
This is amazing grace, this is unfailing love,
that You would take my place,
that You would bear my cross.
You would lay down Your life,
that I would be set free.
Jesus, I sing for all that You’ve done for me.
Josh Farro / Phil Wickham / Jeremy Riddle
(c) Bethel Music Publishing/Song Solutions CopyCare; Phil Wickham Music/Seems Like Music/Sing My Songs/Simpleville Music/SMall Stone Media BV/Song Solutions Daybreak www.songsolutions.org; Warner Chappell Music');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1373', 'chorus', 0, 0, '[\"Who breaks the power of sin and darkness?\",\"Whose love is mighty and so much stronger?\",\"The King of glory, the King above all kings.\",\"Who shakes the whole earth with holy thunder?\",\"Who leaves us breathless in awe and wonder?\",\"The King of glory, the King above all kings.\",\"This is amazing grace, this is unfailing love,\",\"that You would take my place,\",\"that You would bear my cross.\",\"You would lay down Your life,\",\"that I would be set free:\",\"Jesus, I sing for all that You’ve done for me,\",\"all that You’ve done for me.\",\"2 Who brings our chaos back into order?\",\"Who makes the orphan a son and daughter?\",\"The King of glory, the King above all kings.\",\"Who rules the nations with truth and justice,\",\"shines like the sun in all of its brilliance?\",\"The King of glory, the King above all kings.\",\"This is amazing grace...\",\"Worthy is the Lamb who was slain,\",\"and worthy is the King who conquered the grave.\",\"(x4)\",\"... worthy, worthy, worthy.\",\"This is amazing grace, this is unfailing love,\",\"that You would take my place,\",\"that You would bear my cross.\",\"You would lay down Your life,\",\"that I would be set free.\",\"Jesus, I sing for all that You’ve done for me.\",\"Josh Farro \\/ Phil Wickham \\/ Jeremy Riddle\",\"(c) Bethel Music Publishing\\/Song Solutions CopyCare; Phil Wickham Music\\/Seems Like Music\\/Sing My Songs\\/Simpleville Music\\/SMall Stone Media BV\\/Song Solutions Daybreak www.songsolutions.org; Warner Chappell Music\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1374', 1374, 'Who has the power to raise the dead?', 'MP', 'en', '© 2013 Thankyou Music/worshiptogether.com Songs/Worship Together Music/sixsteps Music/Sixsteps Songs/Said and Done Music/A Thousand Generations Publishing/Sweater Weather Music (Adm. by Capitol CMG Publishing worldwide excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com)/Sony/ATV Cross Keys Publishing. Used by Permission.', '', 0, 0, 0, 0, 1, 'Who has the power to raise the dead?
Who can save us from our sin?
He is our hope, our righteousness:
Jesus, only Jesus.
2 And who can make the blind to see?
Who holds the keys that set us free?
He paid it all to bring us peace:
Jesus, only Jesus.
Holy King, almighty Lord,
saints and angels all adore;
I join with them and bow before
Jesus, only Jesus.
3 Who can command the highest praise?
Who has the name above all names?
You stand alone, I stand amazed.
Jesus, only Jesus.
Holy King, almighty Lord,
saints and angels all adore;
I join with them and bow before
Jesus, only Jesus.
You will command the highest praise.
Yours is the name above all names.
You stand alone, I stand amazed.
Jesus, only Jesus.
Holy King...
Chris Tomlin / Nathan / Nockels / Kristian Stanﬁll / Tony Wood / Matt Redman / Christy Nockels');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1374', 'chorus', 0, 0, '[\"Who has the power to raise the dead?\",\"Who can save us from our sin?\",\"He is our hope, our righteousness:\",\"Jesus, only Jesus.\",\"2 And who can make the blind to see?\",\"Who holds the keys that set us free?\",\"He paid it all to bring us peace:\",\"Jesus, only Jesus.\",\"Holy King, almighty Lord,\",\"saints and angels all adore;\",\"I join with them and bow before\",\"Jesus, only Jesus.\",\"3 Who can command the highest praise?\",\"Who has the name above all names?\",\"You stand alone, I stand amazed.\",\"Jesus, only Jesus.\",\"Holy King, almighty Lord,\",\"saints and angels all adore;\",\"I join with them and bow before\",\"Jesus, only Jesus.\",\"You will command the highest praise.\",\"Yours is the name above all names.\",\"You stand alone, I stand amazed.\",\"Jesus, only Jesus.\",\"Holy King...\",\"Chris Tomlin \\/ Nathan \\/ Nockels \\/ Kristian Stanﬁll \\/ Tony Wood \\/ Matt Redman \\/ Christy Nockels\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1375', 1375, 'Who, O Lord, could save', 'MP', 'en', '© 2009 Thankyou Music/Said And Done Music (Adm. by CAPTIOL CMG Publishing worldwide excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com) / SHOUT! Publishing. Used by Permission', '', 0, 0, 0, 0, 1, 'Who, O Lord, could save themselves,
their own soul could heal?
Our shame was deeper than the sea;
Your grace is deeper still.
(repeat verse 1)
And You alone can rescue,
You alone can save.
You alone can lift us from the grave.
You came down to find us,
led us out of death.
To You alone belongs the highest praise.
2 You, O Lord, have made a way,
the great divide You healed;
for when our hearts were far away,
Your love went further still.
Yes, Your love goes further still!
And You alone...
... to You alone belongs the highest praise.
To You alone belongs the highest praise.
We lift up our eyes, lift up our eyes,
You’re the giver of life.
(x8)
And You alone...
... to You alone belongs the highest praise.
To You alone belongs the highest praise.
Jonas Myrin, Matt Redman');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1375', 'chorus', 0, 0, '[\"Who, O Lord, could save themselves,\",\"their own soul could heal?\",\"Our shame was deeper than the sea;\",\"Your grace is deeper still.\",\"(repeat verse 1)\",\"And You alone can rescue,\",\"You alone can save.\",\"You alone can lift us from the grave.\",\"You came down to find us,\",\"led us out of death.\",\"To You alone belongs the highest praise.\",\"2 You, O Lord, have made a way,\",\"the great divide You healed;\",\"for when our hearts were far away,\",\"Your love went further still.\",\"Yes, Your love goes further still!\",\"And You alone...\",\"... to You alone belongs the highest praise.\",\"To You alone belongs the highest praise.\",\"We lift up our eyes, lift up our eyes,\",\"You’re the giver of life.\",\"(x8)\",\"And You alone...\",\"... to You alone belongs the highest praise.\",\"To You alone belongs the highest praise.\",\"Jonas Myrin, Matt Redman\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1376', 1376, 'Worthy is the Lamb', 'MP', 'en', '© 2004 Gateway Create Publishing/Integrity\'s Praise! Music (adm by CAPTIOL CMG Publishing worldwide excl UK admin by Integritymusic.com, a division of David C Cook, songs@integritymusic.com) Used by Permission', '', 0, 0, 0, 0, 1, 'Worthy is the Lamb who was slain;
holy, holy is He.
Sing a new song to Him who sits on
heaven’s mercy seat.
(repeat verse 1)
Holy, holy, holy is the Lord God almighty,
who was and is and is to come.
With all creation I sing
praise to the King of kings;
You are my everything
and I will adore You.
2 Clothed in rainbows of living colour,
flashes of lightning, rolls of thunder.
Blessing and honour,
strength and glory and power be
to You, the only wise King.
Holy, holy, holy...
3 Filled with wonder, awestruck wonder,
at the mention of Your name.
Jesus, Your name is power,
breath and living water;
such a marvellous mystery.
Holy, holy, holy...
Jennie Lee Riddle');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1376', 'chorus', 0, 0, '[\"Worthy is the Lamb who was slain;\",\"holy, holy is He.\",\"Sing a new song to Him who sits on\",\"heaven’s mercy seat.\",\"(repeat verse 1)\",\"Holy, holy, holy is the Lord God almighty,\",\"who was and is and is to come.\",\"With all creation I sing\",\"praise to the King of kings;\",\"You are my everything\",\"and I will adore You.\",\"2 Clothed in rainbows of living colour,\",\"flashes of lightning, rolls of thunder.\",\"Blessing and honour,\",\"strength and glory and power be\",\"to You, the only wise King.\",\"Holy, holy, holy...\",\"3 Filled with wonder, awestruck wonder,\",\"at the mention of Your name.\",\"Jesus, Your name is power,\",\"breath and living water;\",\"such a marvellous mystery.\",\"Holy, holy, holy...\",\"Jennie Lee Riddle\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1377', 1377, 'You choose the humble', 'MP', 'en', '© 2011 Integrity Worship Music/Leadworship Songs (admin by CAPITOL CMG Publishing worldwide excl. the UK which is admin by Integritymusic.com, a division of David C Cook songs@integritymusic.com ) Used by Permission', '', 0, 0, 0, 0, 1, 'You choose the humble and raise them high;
You choose the weak and make them strong;
You heal the brokenness inside and give us life.
The same love that set the captives free,
the same love that opened eyes to see
is calling us all by name.
You are calling us all by name.
The same God that spread the heavens wide,
the same God that was crucified
is calling us all by name;
You are calling us all by name.
You take the faithless one aside
and speak the words, ‘You are mine’;
You call the cynic and the proud,
‘Come to me now.’
The same love...
...oh, oh, oh, oh.
(x2)
You’re calling, You’re calling,
You’re calling us to the cross.
(x4)
The same love...
...oh, oh, oh, oh
(x2)
You’re calling, You’re calling,
You’re calling us to the cross.
(x2)
Paul Baloche / Michael Rossback');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1377', 'chorus', 0, 0, '[\"You choose the humble and raise them high;\",\"You choose the weak and make them strong;\",\"You heal the brokenness inside and give us life.\",\"The same love that set the captives free,\",\"the same love that opened eyes to see\",\"is calling us all by name.\",\"You are calling us all by name.\",\"The same God that spread the heavens wide,\",\"the same God that was crucified\",\"is calling us all by name;\",\"You are calling us all by name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1377', 'chorus', 0, 1, '[\"You take the faithless one aside\",\"and speak the words, ‘You are mine’;\",\"You call the cynic and the proud,\",\"‘Come to me now.’\",\"The same love...\",\"...oh, oh, oh, oh.\",\"(x2)\",\"You’re calling, You’re calling,\",\"You’re calling us to the cross.\",\"(x4)\",\"The same love...\",\"...oh, oh, oh, oh\",\"(x2)\",\"You’re calling, You’re calling,\",\"You’re calling us to the cross.\",\"(x2)\",\"Paul Baloche \\/ Michael Rossback\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1378', 1378, 'You hold the brokenhearted', 'MP', 'en', '©  2007 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 1, 'You hold the broken-hearted,
You stand beside the weak.
You go to those in darkness,
and so must we.
2 Your heart is for the outcast,
for those we call the least.
You lift the broken spirit
and so must we.
God of hope, God of futures,
You can take a broken heart and make it sing.
God of life, new tomorrows,
You can shine the light that changes everything.
3 You go to those forgotten,
the faces we don’t see.
You give Your life to save them
and so must we.
God of hope...
God who speaks, opens graves,
with one word our God saves!
(x2)
God of hope...
James Gregory / Guy Bastable');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1378', 'chorus', 0, 0, '[\"You hold the broken-hearted,\",\"You stand beside the weak.\",\"You go to those in darkness,\",\"and so must we.\",\"2 Your heart is for the outcast,\",\"for those we call the least.\",\"You lift the broken spirit\",\"and so must we.\",\"God of hope, God of futures,\",\"You can take a broken heart and make it sing.\",\"God of life, new tomorrows,\",\"You can shine the light that changes everything.\",\"3 You go to those forgotten,\",\"the faces we don’t see.\",\"You give Your life to save them\",\"and so must we.\",\"God of hope...\",\"God who speaks, opens graves,\",\"with one word our God saves!\",\"(x2)\",\"God of hope...\",\"James Gregory \\/ Guy Bastable\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1379', 1379, 'You deserve the glory', 'MP', 'en', '', '', 0, 0, 0, 0, 1, 'You deserve the glory and the honour,
Lord, we lift our hands in worship
as we lift Your holy name.
You deserve the glory and the honour,
Lord, we lift our hands in worship
as we lift Your holy name.
For You are great,
You do miracles so great,
there is no one else like You,
there is no one else like You.
For You are great,
You do miracles so great,
there is no one else like You,
there is no one else like You.
You deserve the glory...
For You are great...
You are great...
For You are great...
There is no one else like You.
Eva Lena Hellmark
1992 Eva-Lena Hellmark (Admin. by Song Solutions CopyCare www.songsolutions.org');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1379', 'chorus', 0, 0, '[\"You deserve the glory and the honour,\",\"Lord, we lift our hands in worship\",\"as we lift Your holy name.\",\"You deserve the glory and the honour,\",\"Lord, we lift our hands in worship\",\"as we lift Your holy name.\",\"For You are great,\",\"You do miracles so great,\",\"there is no one else like You,\",\"there is no one else like You.\",\"For You are great,\",\"You do miracles so great,\",\"there is no one else like You,\",\"there is no one else like You.\",\"You deserve the glory...\",\"For You are great...\",\"You are great...\",\"For You are great...\",\"There is no one else like You.\",\"Eva Lena Hellmark\",\"1992 Eva-Lena Hellmark (Admin. by Song Solutions CopyCare www.songsolutions.org\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1380', 1380, 'You reach beyond imagination', 'MP', 'en', '©  2008 Thankyou Music/Trinity Publishing (Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com) Used by Permission', '', 0, 0, 0, 0, 1, 'You reach beyond imagination
with a love outside of understanding.
You touch the lives of all Your children
with beauty and goodness.
You know my words before they’re spoken,
You hear each cry, my every passion.
You draw me close and lead me into
Your beauty and goodness.
Wonderful, intimate,
beautiful God of love.
You’ve always been faithful
in the way that You father me.
You reach beyond imagination
with a love outside of understanding.
You touch the lives of all Your children
with beauty and goodness.
You know my words before they’re spoken,
You hear each cry, my every passion.
You draw me close and lead me into
Your beauty and goodness.
Wonderful, intimate...
Our God is good,
our God is faithful,
our God is strong,
our God is able.
(x2)
He is wonderful, intimate...
Eoghan Heaslip / David Gate');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1380', 'verse', 1, 0, '[\"You reach beyond imagination\",\"with a love outside of understanding.\",\"You touch the lives of all Your children\",\"with beauty and goodness.\",\"You know my words before they’re spoken,\",\"You hear each cry, my every passion.\",\"You draw me close and lead me into\",\"Your beauty and goodness.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1380', 'chorus', 0, 1, '[\"Wonderful, intimate,\",\"beautiful God of love.\",\"You’ve always been faithful\",\"in the way that You father me.\",\"You reach beyond imagination\",\"with a love outside of understanding.\",\"You touch the lives of all Your children\",\"with beauty and goodness.\",\"You know my words before they’re spoken,\",\"You hear each cry, my every passion.\",\"You draw me close and lead me into\",\"Your beauty and goodness.\",\"Wonderful, intimate...\",\"Our God is good,\",\"our God is faithful,\",\"our God is strong,\",\"our God is able.\",\"(x2)\",\"He is wonderful, intimate...\",\"Eoghan Heaslip \\/ David Gate\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1381', 1381, 'You’re not a God created', 'MP', 'en', 'control', '', 0, 0, 0, 0, 1, 'You’re not a god created
by human hands.
You’re not a god dependent
on any mortal man.
You’re not a god in need
of anything we can give.
By Your plan, that’s just the way it is.
(repeat verse 1)
You are God alone,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1381', 'chorus', 0, 0, '[\"You’re not a god created\",\"by human hands.\",\"You’re not a god dependent\",\"on any mortal man.\",\"You’re not a god in need\",\"of anything we can give.\",\"By Your plan, that’s just the way it is.\",\"(repeat verse 1)\",\"You are God alone,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1382', 1382, 'You stood before creation', 'MP', 'en', '', '', 0, 0, 0, 0, 1, 'You stood before creation,
eternity in Your hand;
You spoke the earth into motion,
my soul now to stand.
2 You stood before my failure
and carried the cross for my shame;
my sin weighed upon Your shoulders,
my soul now to stand.
So what can I say,
and what could I do,
but offer this heart, O God,
completely to You?
3 So I’ll walk upon salvation,
Your Spirit alive in me;
this life to declare Your promise:
my soul now to stand.
So what can I say...
So what can I say...
So I’ll stand with arms high and heart abandoned,
in awe of the One who gave it all.
I’ll stand, my soul, Lord, to You surrendered;
all I am is Yours.
(x4)
So what can I say...
Joel Houston
Words & Music by Joel Houston © 2005 Hillsong Music Publishing (APRA) CCLI: 4705248');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1382', 'chorus', 0, 0, '[\"You stood before creation,\",\"eternity in Your hand;\",\"You spoke the earth into motion,\",\"my soul now to stand.\",\"2 You stood before my failure\",\"and carried the cross for my shame;\",\"my sin weighed upon Your shoulders,\",\"my soul now to stand.\",\"So what can I say,\",\"and what could I do,\",\"but offer this heart, O God,\",\"completely to You?\",\"3 So I’ll walk upon salvation,\",\"Your Spirit alive in me;\",\"this life to declare Your promise:\",\"my soul now to stand.\",\"So what can I say...\",\"So what can I say...\",\"So I’ll stand with arms high and heart abandoned,\",\"in awe of the One who gave it all.\",\"I’ll stand, my soul, Lord, to You surrendered;\",\"all I am is Yours.\",\"(x4)\",\"So what can I say...\",\"Joel Houston\",\"Words & Music by Joel Houston © 2005 Hillsong Music Publishing (APRA) CCLI: 4705248\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1383', 1383, 'Your grace is enough', 'MP', 'en', '', '', 0, 0, 0, 0, 1, 'Your grace is enough,
more than I need.
At Your word I will believe.
I wait for You,
draw near again.
Let Your Spirit make me new.
And I will fall at Your feet,
I will fall at Your feet
and I will worship You here.
2 Your presence in me,
Jesus, light the way
by the power of Your word.
I am restored,
I am redeemed.
By Your Spirit I am free.
And I will fall...
Freely You gave it all for us,
surrendered Your life upon that cross.
Great is the love poured out for all.
This is our God.
Lifted on high from death to life,
for ever our God is glorified.
Servant and King, rescued the world.
This is our God.
And I will fall at Your feet,
I will fall at Your feet
and I will worship You here.
Freely You gave...
Reuben Morgan
Words & Music by Reuben Morgan © 2008 Hillsong Music Publishing CCLI:  5060834');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1383', 'chorus', 0, 0, '[\"Your grace is enough,\",\"more than I need.\",\"At Your word I will believe.\",\"I wait for You,\",\"draw near again.\",\"Let Your Spirit make me new.\",\"And I will fall at Your feet,\",\"I will fall at Your feet\",\"and I will worship You here.\",\"2 Your presence in me,\",\"Jesus, light the way\",\"by the power of Your word.\",\"I am restored,\",\"I am redeemed.\",\"By Your Spirit I am free.\",\"And I will fall...\",\"Freely You gave it all for us,\",\"surrendered Your life upon that cross.\",\"Great is the love poured out for all.\",\"This is our God.\",\"Lifted on high from death to life,\",\"for ever our God is glorified.\",\"Servant and King, rescued the world.\",\"This is our God.\",\"And I will fall at Your feet,\",\"I will fall at Your feet\",\"and I will worship You here.\",\"Freely You gave...\",\"Reuben Morgan\",\"Words & Music by Reuben Morgan © 2008 Hillsong Music Publishing CCLI:  5060834\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1384', 1384, 'Your love, shining like the sun', 'MP', 'en', '©  1999 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 1, 'Your love, shining like the sun,
pouring like the rain,
raging like the storm,
refreshing me again.
Ooh, I receive Your love.
2 Your grace frees me from the past,
it purges every sin,
it purifies my heart
and heals me from within.
Ooh, I receive Your grace.
Pour over me, pour over me,
let Your rain flood this thirsty soul.
Pour over me Your waves of love,
pour over me.
3 I come and lay my burden down
gladly at Your feet,
I’m opening up my heart,
come, make this joy complete.
Ooh, I receive Your peace.
Pour over me...
Stuart Townend');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1384', 'chorus', 0, 0, '[\"Your love, shining like the sun,\",\"pouring like the rain,\",\"raging like the storm,\",\"refreshing me again.\",\"Ooh, I receive Your love.\",\"2 Your grace frees me from the past,\",\"it purges every sin,\",\"it purifies my heart\",\"and heals me from within.\",\"Ooh, I receive Your grace.\",\"Pour over me, pour over me,\",\"let Your rain flood this thirsty soul.\",\"Pour over me Your waves of love,\",\"pour over me.\",\"3 I come and lay my burden down\",\"gladly at Your feet,\",\"I’m opening up my heart,\",\"come, make this joy complete.\",\"Ooh, I receive Your peace.\",\"Pour over me...\",\"Stuart Townend\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('MP-1385', 1385, 'Your name, stronger than I Know', 'MP', 'en', '©  1998 Thankyou Music/Adm. by Capitol CMG Publishing excl. UK & Europe, adm. by Integritymusic.com, a division of David C Cook songs@integritymusic.com Used by Permission', '', 0, 0, 0, 0, 0, 'Your name, stronger than I know,
deeper than a thousand words
could say.
Your name, Your name,
fire in my soul,
healing for a hurting heart today,
Your name, Your name.
And my heart will bow and my spirit soar,
and my soul cries out to the Lord of all.
To my God and King, to my Prince of peace,
I will lift my voice in praise unto Your name,
unto Your name.
Your name, all creation knows
the one who gave it life with breath alone,
Your name. Your name,
glory now displayed:
all the earth belongs to You alone,
Your name, Your name.
And the mountains bow
and the seas will roar,
and the rocks cry out, all creation calls
to the holy One, to the Son of God,
we will lift our voice in praise: worship Your name,
worship Your name.
3 Your name, higher than them all;
holy One of God, the Lord of lords,
Your name. Your name,
heaven’s only Son,
high and lifted up for ever more,
Your name, Your name.
And the nations bow and their kingdoms fall;
every king and priest, every prince and lord,
falling to their knees will acknowledge You.
We will lift our voice in praise: honour Your name,
honour Your name.
Andy Bromley');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('MP-1385', 'verse', 1, 0, '[\"Your name, stronger than I know,\",\"deeper than a thousand words\",\"could say.\",\"Your name, Your name,\",\"fire in my soul,\",\"healing for a hurting heart today,\",\"Your name, Your name.\",\"And my heart will bow and my spirit soar,\",\"and my soul cries out to the Lord of all.\",\"To my God and King, to my Prince of peace,\",\"I will lift my voice in praise unto Your name,\",\"unto Your name.\",\"Your name, all creation knows\",\"the one who gave it life with breath alone,\",\"Your name. Your name,\",\"glory now displayed:\",\"all the earth belongs to You alone,\",\"Your name, Your name.\",\"And the mountains bow\",\"and the seas will roar,\",\"and the rocks cry out, all creation calls\",\"to the holy One, to the Son of God,\",\"we will lift our voice in praise: worship Your name,\",\"worship Your name.\",\"3 Your name, higher than them all;\",\"holy One of God, the Lord of lords,\",\"Your name. Your name,\",\"heaven’s only Son,\",\"high and lifted up for ever more,\",\"Your name, Your name.\",\"And the nations bow and their kingdoms fall;\",\"every king and priest, every prince and lord,\",\"falling to their knees will acknowledge You.\",\"We will lift our voice in praise: honour Your name,\",\"honour Your name.\",\"Andy Bromley\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0001', 1, 'Praise to the Lord', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Praise to the Lord, the Almighty, the King of creation!
O my soul, praise Him, for He is thy health and salvation!
All ye who hear,
Now to His temple draw near;
Join ye in glad adoration!
Praise to the Lord, who o\'er all things so wondrously reigneth,
Shieldeth thee under His wings, yea, so gently sustaineth!
Hast thou not seen
How thy desires e\'er have been
Granted in what He ordaineth?
Praise to the Lord, who doth prosper thy work and defend thee;
Surely His goodness and mercy here daily attend thee.
Ponder anew
What the Almighty can do
If with His love He befriend thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0001', 'verse', 1, 0, '[\"Praise to the Lord, the Almighty, the King of creation!\",\"O my soul, praise Him, for He is thy health and salvation!\",\"All ye who hear,\",\"Now to His temple draw near;\",\"Join ye in glad adoration!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0001', 'verse', 2, 1, '[\"Praise to the Lord, who o\'er all things so wondrously reigneth,\",\"Shieldeth thee under His wings, yea, so gently sustaineth!\",\"Hast thou not seen\",\"How thy desires e\'er have been\",\"Granted in what He ordaineth?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0001', 'verse', 3, 2, '[\"Praise to the Lord, who doth prosper thy work and defend thee;\",\"Surely His goodness and mercy here daily attend thee.\",\"Ponder anew\",\"What the Almighty can do\",\"If with His love He befriend thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0002', 2, 'All Creatures of Our God and King', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'All creatures of our God and King,
Lift up your voice with us and sing:
Alleluia! Alleluia!
O burning sun with golden beam
And silver moon with softer gleam:
Oh, praise Him! Oh, praise Him!
Alleluia, alleluia, alleluia!
O rushing wind and breezes soft,
O clouds that ride the winds aloft:
Oh, praise Him! Alleluia!
O rising morn, in praise rejoice,
O lights of evening, find a voice.
O flowing waters, pure and clear,
Make music for your Lord to hear.
Oh, praise Him! Alleluia!
O fire so masterful and bright,
Providing us with warmth and light,
Let all things their Creator bless,
And worship Him in humbleness,
Oh, praise Him! Alleluia!
Oh, praise the Father, praise the Son,
And praise the Spirit, three in One!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0002', 'verse', 1, 0, '[\"All creatures of our God and King,\",\"Lift up your voice with us and sing:\",\"Alleluia! Alleluia!\",\"O burning sun with golden beam\",\"And silver moon with softer gleam:\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0002', 'chorus', 0, 1, '[\"Oh, praise Him! Oh, praise Him!\",\"Alleluia, alleluia, alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0002', 'verse', 2, 2, '[\"O rushing wind and breezes soft,\",\"O clouds that ride the winds aloft:\",\"Oh, praise Him! Alleluia!\",\"O rising morn, in praise rejoice,\",\"O lights of evening, find a voice.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0002', 'verse', 3, 3, '[\"O flowing waters, pure and clear,\",\"Make music for your Lord to hear.\",\"Oh, praise Him! Alleluia!\",\"O fire so masterful and bright,\",\"Providing us with warmth and light,\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0002', 'verse', 4, 4, '[\"Let all things their Creator bless,\",\"And worship Him in humbleness,\",\"Oh, praise Him! Alleluia!\",\"Oh, praise the Father, praise the Son,\",\"And praise the Spirit, three in One!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0003', 3, 'God Himself Is With Us', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'God Himself is with us; Let us all adore Him,
And with awe appear before Him.
God is here within us; Soul, in silence fear Him,
Humbly, fervently draw near Him.
Now His own who have known God, in worship lowly,
Yield their spirits wholly.
Come, abide within me; Let my soul, like Mary,
Be Thine earthly sanctuary.
Come, in-dwelling Spirit, With transfigured splendor;
Love and honor will I render.
Where I go here below, Let me bow before Thee,
Know Thee and adore Thee.
Gladly we surrender Earth\'s deceitful treasures,
Pride of life, and sinful pleasures:
Gladly, Lord, we offer Thine to be forever,
Soul and life and each endeavor.
Thou alone shalt be known Lord of all our being,
Life\'s true way decreeing.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0003', 'verse', 1, 0, '[\"God Himself is with us; Let us all adore Him,\",\"And with awe appear before Him.\",\"God is here within us; Soul, in silence fear Him,\",\"Humbly, fervently draw near Him.\",\"Now His own who have known God, in worship lowly,\",\"Yield their spirits wholly.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0003', 'verse', 2, 1, '[\"Come, abide within me; Let my soul, like Mary,\",\"Be Thine earthly sanctuary.\",\"Come, in-dwelling Spirit, With transfigured splendor;\",\"Love and honor will I render.\",\"Where I go here below, Let me bow before Thee,\",\"Know Thee and adore Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0003', 'verse', 3, 2, '[\"Gladly we surrender Earth\'s deceitful treasures,\",\"Pride of life, and sinful pleasures:\",\"Gladly, Lord, we offer Thine to be forever,\",\"Soul and life and each endeavor.\",\"Thou alone shalt be known Lord of all our being,\",\"Life\'s true way decreeing.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0004', 4, 'Praise My Soul the King of Heaven', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Praise, my soul, the King of heaven;
To His feet thy tribute bring.
Ransomed, healed, restored, forgiven,
Who like thee His praise should sing?
Praise Him, praise Him, Alleluia,
Praise the everlasting King.
Praise Him for His grace and favor
To our fathers in distress.
Praise Him, still the same forever,
Slow to chide and swift to bless;
Praise Him, praise Him, Alleluia,
Glorious in His faithfulness.
Tenderly He shields and spares us;
Well our feeble frame He knows.
In His hands He gently bears us,
Rescues us from all our foes.
Praise Him, praise Him, Alleluia,
Widely as His mercy flows.
Angels, help us to adore Him:
Ye behold Him face to face;
Sun and moon, bow down before Him:
Dwellers all in time and space.
Praise Him, praise Him, Alleluia,
Praise with us the God of grace.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0004', 'verse', 1, 0, '[\"Praise, my soul, the King of heaven;\",\"To His feet thy tribute bring.\",\"Ransomed, healed, restored, forgiven,\",\"Who like thee His praise should sing?\",\"Praise Him, praise Him, Alleluia,\",\"Praise the everlasting King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0004', 'verse', 2, 1, '[\"Praise Him for His grace and favor\",\"To our fathers in distress.\",\"Praise Him, still the same forever,\",\"Slow to chide and swift to bless;\",\"Praise Him, praise Him, Alleluia,\",\"Glorious in His faithfulness.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0004', 'verse', 3, 2, '[\"Tenderly He shields and spares us;\",\"Well our feeble frame He knows.\",\"In His hands He gently bears us,\",\"Rescues us from all our foes.\",\"Praise Him, praise Him, Alleluia,\",\"Widely as His mercy flows.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0004', 'verse', 4, 3, '[\"Angels, help us to adore Him:\",\"Ye behold Him face to face;\",\"Sun and moon, bow down before Him:\",\"Dwellers all in time and space.\",\"Praise Him, praise Him, Alleluia,\",\"Praise with us the God of grace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0005', 5, 'All My Hope On God Is Founded', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'All my hope on God is founded;
He doth still my trust renew,
Me through change and chance He guideth,
Only good and only true.
God unknown, He alone
Calls my heart to be His own.
Pride of man and earthly glory,
Sword and crown betray his trust;
What with care and toil he buildeth,
Tower and temple fall to dust.
But God\'s power, hour by hour,
Is my temple and my tower.
God\'s great goodness aye endureth,
Deep His wisdom, passing thought:
Splendor, light, and life attend Him,
Beauty springeth out of naught.
Love doth stand at His hand;
Joy doth wait on His command.
Still from man to God eternal
Sacrifice of praise be done,
High above all praises praising
For the gift of Christ His son.
Christ doth call one and all:
Ye who follow shall not fall.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0005', 'verse', 1, 0, '[\"All my hope on God is founded;\",\"He doth still my trust renew,\",\"Me through change and chance He guideth,\",\"Only good and only true.\",\"God unknown, He alone\",\"Calls my heart to be His own.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0005', 'verse', 2, 1, '[\"Pride of man and earthly glory,\",\"Sword and crown betray his trust;\",\"What with care and toil he buildeth,\",\"Tower and temple fall to dust.\",\"But God\'s power, hour by hour,\",\"Is my temple and my tower.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0005', 'verse', 3, 2, '[\"God\'s great goodness aye endureth,\",\"Deep His wisdom, passing thought:\",\"Splendor, light, and life attend Him,\",\"Beauty springeth out of naught.\",\"Love doth stand at His hand;\",\"Joy doth wait on His command.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0005', 'verse', 4, 3, '[\"Still from man to God eternal\",\"Sacrifice of praise be done,\",\"High above all praises praising\",\"For the gift of Christ His son.\",\"Christ doth call one and all:\",\"Ye who follow shall not fall.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0006', 6, 'O Worship the Lord', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O worship the Lord in the beauty of holiness,
Bow down before Him, His glory proclaim;
With gold of obedience, and incense of lowliness,
Kneel and adore Him; the Lord is His name.
Low at His feet lay thy burden of carefulness;
High on His heart He will bear it for thee,
Comfort thy sorrows and answer thy prayerfulness,
Guiding thy steps as may best for thee be.
Fear not to enter His courts in the slenderness
Of the poor wealth thou wouldst reckon as thine.
Truth in its beauty and love in its tenderness,
These are the offerings to lay on His shrine.
These, though we bring them in trembling and fearfulness,
He will accept for the name that is dear;
Mornings of joy give for evenings of tearfulness,
Trust for our trembling, and hope for our fear.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0006', 'verse', 1, 0, '[\"O worship the Lord in the beauty of holiness,\",\"Bow down before Him, His glory proclaim;\",\"With gold of obedience, and incense of lowliness,\",\"Kneel and adore Him; the Lord is His name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0006', 'verse', 2, 1, '[\"Low at His feet lay thy burden of carefulness;\",\"High on His heart He will bear it for thee,\",\"Comfort thy sorrows and answer thy prayerfulness,\",\"Guiding thy steps as may best for thee be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0006', 'verse', 3, 2, '[\"Fear not to enter His courts in the slenderness\",\"Of the poor wealth thou wouldst reckon as thine.\",\"Truth in its beauty and love in its tenderness,\",\"These are the offerings to lay on His shrine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0006', 'verse', 4, 3, '[\"These, though we bring them in trembling and fearfulness,\",\"He will accept for the name that is dear;\",\"Mornings of joy give for evenings of tearfulness,\",\"Trust for our trembling, and hope for our fear.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0007', 7, 'The Lord in Zion Reigneth', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'The Lord in Zion reigneth,
Let all the world rejoice,
And come before His throne of grace
With tuneful heart and voice;
The Lord in Zion reigneth,
And there His praise shall ring,
To Him shall princes bend the knee
And kings their glory bring.
The Lord in Zion reigneth,
And who so great as He?
The depths of earth are in His hands;
He rules the mighty sea,
O crown His name with honor,
And let His standard wave,
Till distant isles beyond the deep
Shall own His power to save.
The Lord in Zion reigneth,
These hours to Him belong;
O enter now His temple gates,
And fill His courts with song;
Beneath His royal banner
Let every creature fall,
Exalt the King of heaven and earth,
And crown Him Lord of all.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0007', 'verse', 1, 0, '[\"The Lord in Zion reigneth,\",\"Let all the world rejoice,\",\"And come before His throne of grace\",\"With tuneful heart and voice;\",\"The Lord in Zion reigneth,\",\"And there His praise shall ring,\",\"To Him shall princes bend the knee\",\"And kings their glory bring.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0007', 'verse', 2, 1, '[\"The Lord in Zion reigneth,\",\"And who so great as He?\",\"The depths of earth are in His hands;\",\"He rules the mighty sea,\",\"O crown His name with honor,\",\"And let His standard wave,\",\"Till distant isles beyond the deep\",\"Shall own His power to save.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0007', 'verse', 3, 2, '[\"The Lord in Zion reigneth,\",\"These hours to Him belong;\",\"O enter now His temple gates,\",\"And fill His courts with song;\",\"Beneath His royal banner\",\"Let every creature fall,\",\"Exalt the King of heaven and earth,\",\"And crown Him Lord of all.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0008', 8, 'We Gather Together', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'We gather together to ask the Lord\'s blessing;
He chastens and hastens His will to make known;
The wicked oppressing now cease from distressing,
Sing praises to His name; He forgets not His own.
Beside us to guide us, our God with us joining,
Ordaining, maintaining His kingdom divine;
So from the beginning the fight we were winning;
Thou, Lord, wast at our side; all glory be Thine!
We all do extol Thee, Thou Leader triumphant,
And pray that Thou still our Defender wilt be.
Let Thy congregation escape tribulation;
Thy name be ever praised! O Lord, make us free!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0008', 'verse', 1, 0, '[\"We gather together to ask the Lord\'s blessing;\",\"He chastens and hastens His will to make known;\",\"The wicked oppressing now cease from distressing,\",\"Sing praises to His name; He forgets not His own.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0008', 'verse', 2, 1, '[\"Beside us to guide us, our God with us joining,\",\"Ordaining, maintaining His kingdom divine;\",\"So from the beginning the fight we were winning;\",\"Thou, Lord, wast at our side; all glory be Thine!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0008', 'verse', 3, 2, '[\"We all do extol Thee, Thou Leader triumphant,\",\"And pray that Thou still our Defender wilt be.\",\"Let Thy congregation escape tribulation;\",\"Thy name be ever praised! O Lord, make us free!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0009', 9, 'Let All the World in Every Corner Sing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Let all the world in every corner sing,
My God and King!
The heavens are not too high,
His praise may thither fly;
The earth is not too low,
His praises there may grow.
Let all the world in every corner sing,
My God and King!
Let all the world in every corner sing,
My God and King!
The church with psalms must shout,
No door can keep them out;
But, above all, the heart
Must bear the longest part.
Let all the world in every corner sing,
My God and King!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0009', 'verse', 1, 0, '[\"Let all the world in every corner sing,\",\"My God and King!\",\"The heavens are not too high,\",\"His praise may thither fly;\",\"The earth is not too low,\",\"His praises there may grow.\",\"Let all the world in every corner sing,\",\"My God and King!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0009', 'verse', 2, 1, '[\"Let all the world in every corner sing,\",\"My God and King!\",\"The church with psalms must shout,\",\"No door can keep them out;\",\"But, above all, the heart\",\"Must bear the longest part.\",\"Let all the world in every corner sing,\",\"My God and King!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0010', 10, 'Come, Christians, Join to Sing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Come, Christians, join to sing,
Alleluia! Amen!
Loud praise to Christ our King;
Alleluia! Amen!
Let all, with heart and voice,
Before His throne rejoice;
Praise is His gracious choice:
Alleluia! Amen!
Come, lift your hearts on high;
Alleluia! Amen!
Let praises fill the sky;
Alleluia! Amen!
He is our Guide and Friend;
To us He\'ll condescend;
His love shall never end:
Alleluia! Amen!
Praise yet our Christ again;
Alleluia! Amen!
Life shall not end the strain;
Alleluia! Amen!
On heaven\'s blissful shore
His goodness we\'ll adore,
Singing forevermore,
Alleluia! Amen!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0010', 'verse', 1, 0, '[\"Come, Christians, join to sing,\",\"Alleluia! Amen!\",\"Loud praise to Christ our King;\",\"Alleluia! Amen!\",\"Let all, with heart and voice,\",\"Before His throne rejoice;\",\"Praise is His gracious choice:\",\"Alleluia! Amen!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0010', 'verse', 2, 1, '[\"Come, lift your hearts on high;\",\"Alleluia! Amen!\",\"Let praises fill the sky;\",\"Alleluia! Amen!\",\"He is our Guide and Friend;\",\"To us He\'ll condescend;\",\"His love shall never end:\",\"Alleluia! Amen!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0010', 'verse', 3, 2, '[\"Praise yet our Christ again;\",\"Alleluia! Amen!\",\"Life shall not end the strain;\",\"Alleluia! Amen!\",\"On heaven\'s blissful shore\",\"His goodness we\'ll adore,\",\"Singing forevermore,\",\"Alleluia! Amen!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0011', 11, 'The God of Abraham Praise', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'The God of Abraham praise,
Who reigns enthroned above;
Ancient of everlasting days,
And God of love;
Jehovah! Great I AM!
By earth and heaven confessed;
I bow and bless the sacred name,
Forever blest.
The God of Abraham praise,
At whose supreme command');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0011', 'verse', 1, 0, '[\"The God of Abraham praise,\",\"Who reigns enthroned above;\",\"Ancient of everlasting days,\",\"And God of love;\",\"Jehovah! Great I AM!\",\"By earth and heaven confessed;\",\"I bow and bless the sacred name,\",\"Forever blest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0011', 'verse', 2, 1, '[\"The God of Abraham praise,\",\"At whose supreme command\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0012', 12, 'Joyful, Joyful, We Adore Thee', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Joyful, joyful, we adore Thee,
God of glory, Lord of love;
Hearts unfold like flow\'rs before Thee,
Hail Thee as the sun above.
Melt the clouds of sin and sadness,
Drive the dark of doubt away;
Giver of immortal gladness,
Fill us with the light of day!
All Thy works with joy surround Thee,
Earth and heav\'n reflect Thy rays,
Stars and angels sing around Thee,
Center of unbroken praise;
Field and forest, vale and mountain,
Bloss\'ming meadow, flashing sea,
Chanting bird and flowing fountain
Call us to rejoice in Thee.
Thou art giving and forgiving,
Ever blessing, ever blest,
Wellspring of the joy of living,
Ocean-depth of happy rest!
Thou the Father, Christ our Brother;
All who live in love are Thine:
Teach us how to love each other,
Lift us to the joy divine.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0012', 'verse', 1, 0, '[\"Joyful, joyful, we adore Thee,\",\"God of glory, Lord of love;\",\"Hearts unfold like flow\'rs before Thee,\",\"Hail Thee as the sun above.\",\"Melt the clouds of sin and sadness,\",\"Drive the dark of doubt away;\",\"Giver of immortal gladness,\",\"Fill us with the light of day!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0012', 'verse', 2, 1, '[\"All Thy works with joy surround Thee,\",\"Earth and heav\'n reflect Thy rays,\",\"Stars and angels sing around Thee,\",\"Center of unbroken praise;\",\"Field and forest, vale and mountain,\",\"Bloss\'ming meadow, flashing sea,\",\"Chanting bird and flowing fountain\",\"Call us to rejoice in Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0012', 'verse', 3, 2, '[\"Thou art giving and forgiving,\",\"Ever blessing, ever blest,\",\"Wellspring of the joy of living,\",\"Ocean-depth of happy rest!\",\"Thou the Father, Christ our Brother;\",\"All who live in love are Thine:\",\"Teach us how to love each other,\",\"Lift us to the joy divine.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0013', 13, 'New Songs of Celebration Render', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'New songs of celebration render
To Him who has great wonders done.
Love sits enthroned in ageless splendor:
Come, and adore the mighty One.
He has made known His great salvation
Which all His friends with joy confess:
He has revealed to every nation
His everlasting righteousness.
Joyfully, heartily resounding,
Let every instrument and voice
Peal out the praise of grace abounding,
Calling the whole world to rejoice.
Trumpets and organs, set in motion
Such sounds as make the heavens ring;
All things that live in earth and ocean,
Make music for your mighty King.
Rivers and seas and torrents roaring,
Honor the Lord with wild acclaim;
Mountains and stones look up adoring,
And find a voice to praise His name.
Righteous, commanding, ever glorious,
Praises be His that never cease:
Just is our God, whose truth victorious
Establishes the world in peace.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0013', 'verse', 1, 0, '[\"New songs of celebration render\",\"To Him who has great wonders done.\",\"Love sits enthroned in ageless splendor:\",\"Come, and adore the mighty One.\",\"He has made known His great salvation\",\"Which all His friends with joy confess:\",\"He has revealed to every nation\",\"His everlasting righteousness.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0013', 'verse', 2, 1, '[\"Joyfully, heartily resounding,\",\"Let every instrument and voice\",\"Peal out the praise of grace abounding,\",\"Calling the whole world to rejoice.\",\"Trumpets and organs, set in motion\",\"Such sounds as make the heavens ring;\",\"All things that live in earth and ocean,\",\"Make music for your mighty King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0013', 'verse', 3, 2, '[\"Rivers and seas and torrents roaring,\",\"Honor the Lord with wild acclaim;\",\"Mountains and stones look up adoring,\",\"And find a voice to praise His name.\",\"Righteous, commanding, ever glorious,\",\"Praises be His that never cease:\",\"Just is our God, whose truth victorious\",\"Establishes the world in peace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0014', 14, 'Let Us Praise the Name of the Lord', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Let us praise the name of the Lord!
Give Him glory, Amen.
Amen, amen, Amen, amen.
Go ye into all the world,
Aleluia, Amen.
Amen, amen, Amen, amen.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0014', 'verse', 1, 0, '[\"Let us praise the name of the Lord!\",\"Give Him glory, Amen.\",\"Amen, amen, Amen, amen.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0014', 'verse', 2, 1, '[\"Go ye into all the world,\",\"Aleluia, Amen.\",\"Amen, amen, Amen, amen.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0015', 15, 'My Maker and My King', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'My Maker and my King,
To Thee my all I owe;
Thy sovereign bounty is the spring
Whence all my blessings flow;
Thy sovereign bounty is the spring
Whence all my blessings flow.
The creature of Thy hand,
On Thee alone I live;
My God, Thy benefits demand
More praise than I can give.
My God, Thy benefits demand
More praise than I can give.
Lord, what can I impart
When all is Thine before?
Thy love demands a thankful heart;
The gift, alas! how poor.
Thy love demands a thankful heart;
The gift, alas! how poor.
O! let Thy grace inspire
My soul with strength divine;
Let every word and each desire
And all my days be Thine.
Let every word and each desire
And all my days be Thine.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0015', 'verse', 1, 0, '[\"My Maker and my King,\",\"To Thee my all I owe;\",\"Thy sovereign bounty is the spring\",\"Whence all my blessings flow;\",\"Thy sovereign bounty is the spring\",\"Whence all my blessings flow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0015', 'verse', 2, 1, '[\"The creature of Thy hand,\",\"On Thee alone I live;\",\"My God, Thy benefits demand\",\"More praise than I can give.\",\"My God, Thy benefits demand\",\"More praise than I can give.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0015', 'verse', 3, 2, '[\"Lord, what can I impart\",\"When all is Thine before?\",\"Thy love demands a thankful heart;\",\"The gift, alas! how poor.\",\"Thy love demands a thankful heart;\",\"The gift, alas! how poor.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0015', 'verse', 4, 3, '[\"O! let Thy grace inspire\",\"My soul with strength divine;\",\"Let every word and each desire\",\"And all my days be Thine.\",\"Let every word and each desire\",\"And all my days be Thine.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0016', 16, 'All People That on Earth Do Dwell', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'All people that on earth do dwell,
Sing to the Lord with cheerful voice;
Him serve with mirth, His praise forth tell,
Come ye before Him and rejoice.
Know that the Lord is God indeed;
Without our aid He did us make;
We are His folk, He doth us feed,
And for His sheep He doth us take.
O enter then His gates with praise,
Approach with joy His courts unto;
Praise, laud, and bless His name always,
For it is seemly so to do.
For why the Lord our God is good,
His mercy is forever sure;
His truth at all times firmly stood,
And shall from age to age endure.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0016', 'verse', 1, 0, '[\"All people that on earth do dwell,\",\"Sing to the Lord with cheerful voice;\",\"Him serve with mirth, His praise forth tell,\",\"Come ye before Him and rejoice.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0016', 'verse', 2, 1, '[\"Know that the Lord is God indeed;\",\"Without our aid He did us make;\",\"We are His folk, He doth us feed,\",\"And for His sheep He doth us take.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0016', 'verse', 3, 2, '[\"O enter then His gates with praise,\",\"Approach with joy His courts unto;\",\"Praise, laud, and bless His name always,\",\"For it is seemly so to do.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0016', 'verse', 4, 3, '[\"For why the Lord our God is good,\",\"His mercy is forever sure;\",\"His truth at all times firmly stood,\",\"And shall from age to age endure.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0017', 17, 'Lord of All Being, Throned Afar', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lord of all being, throned afar,
Thy glory flames from sun and star;
Center and soul of every sphere,
Yet to each loving heart how near!
Yet to each loving heart how near!
Sun of our life, Thy quickening ray
Sheds on our path the glow of day;
Star of our hope, Thy softened light
Cheers the long watches of the night,
Cheers the long watches of the night.
Our midnight is Thy smile withdrawn;
Our noontide is Thy gracious dawn;
Our rainbow arch, Thy mercy\'s sign;
All, save the clouds of sin, are Thine,
All, save the clouds of sin, are Thine.
Lord of all life, below, above,
Whose light is truth, whose warmth is love,
Before Thy everblazing throne
We ask no luster of our own,
We ask no luster of our own.
Grant us Thy truth to make us free,
And kindling hearts that burn for Thee;
Till all Thy living altars claim
One holy light, one heavenly flame!
One holy light, one heavenly flame.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0017', 'verse', 1, 0, '[\"Lord of all being, throned afar,\",\"Thy glory flames from sun and star;\",\"Center and soul of every sphere,\",\"Yet to each loving heart how near!\",\"Yet to each loving heart how near!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0017', 'verse', 2, 1, '[\"Sun of our life, Thy quickening ray\",\"Sheds on our path the glow of day;\",\"Star of our hope, Thy softened light\",\"Cheers the long watches of the night,\",\"Cheers the long watches of the night.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0017', 'verse', 3, 2, '[\"Our midnight is Thy smile withdrawn;\",\"Our noontide is Thy gracious dawn;\",\"Our rainbow arch, Thy mercy\'s sign;\",\"All, save the clouds of sin, are Thine,\",\"All, save the clouds of sin, are Thine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0017', 'verse', 4, 3, '[\"Lord of all life, below, above,\",\"Whose light is truth, whose warmth is love,\",\"Before Thy everblazing throne\",\"We ask no luster of our own,\",\"We ask no luster of our own.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0017', 'verse', 5, 4, '[\"Grant us Thy truth to make us free,\",\"And kindling hearts that burn for Thee;\",\"Till all Thy living altars claim\",\"One holy light, one heavenly flame!\",\"One holy light, one heavenly flame.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0018', 18, 'O Morning Star How Fair and Bright', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O Morning Star, how fair and bright!
You shine with God\'s own truth and light,
Aglow with grace and mercy!
Of Jacob\'s race, King David\'s Son,
Our Lord and Master, You have won
Our hearts to serve You only!
Lowly, Holy!
Great and glorious, all victorious,
Rich in blessing!
Rule and might o\'er all possessing!
Lord, when You look on us in love,
At once there falls from God above
A ray of purest pleasure.
Your Word and Spirit, flesh and blood
Refresh our souls with heav\'nly food.
You are our dearest treasure!
Let Your mercy
Warm and cheer us!
O draw near us!
For You teach us
God\'s own love through You has reached us.
Almighty Father, in Your Son
You loved us, when not yet begun
Was this old earth\'s foundation!
Your Son has ransomed us in love
To live in Him here and above:
This is Your great salvation.
Alleluia! Christ the living, to us giving
Life forever,
Keeps us Yours
and fails us never!
O let the harps break forth in sound!
Our joy be all with music crowned,
Our voices gaily blending!
For Christ goes with us all the way-
Today, tomorrow, every day!
His love is never ending!
Sing out! ring out!
Jubilation! exultation!
Tell the story!
Great is He,
the King of glory!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0018', 'verse', 1, 0, '[\"O Morning Star, how fair and bright!\",\"You shine with God\'s own truth and light,\",\"Aglow with grace and mercy!\",\"Of Jacob\'s race, King David\'s Son,\",\"Our Lord and Master, You have won\",\"Our hearts to serve You only!\",\"Lowly, Holy!\",\"Great and glorious, all victorious,\",\"Rich in blessing!\",\"Rule and might o\'er all possessing!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0018', 'verse', 2, 1, '[\"Lord, when You look on us in love,\",\"At once there falls from God above\",\"A ray of purest pleasure.\",\"Your Word and Spirit, flesh and blood\",\"Refresh our souls with heav\'nly food.\",\"You are our dearest treasure!\",\"Let Your mercy\",\"Warm and cheer us!\",\"O draw near us!\",\"For You teach us\",\"God\'s own love through You has reached us.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0018', 'verse', 3, 2, '[\"Almighty Father, in Your Son\",\"You loved us, when not yet begun\",\"Was this old earth\'s foundation!\",\"Your Son has ransomed us in love\",\"To live in Him here and above:\",\"This is Your great salvation.\",\"Alleluia! Christ the living, to us giving\",\"Life forever,\",\"Keeps us Yours\",\"and fails us never!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0018', 'verse', 4, 3, '[\"O let the harps break forth in sound!\",\"Our joy be all with music crowned,\",\"Our voices gaily blending!\",\"For Christ goes with us all the way-\",\"Today, tomorrow, every day!\",\"His love is never ending!\",\"Sing out! ring out!\",\"Jubilation! exultation!\",\"Tell the story!\",\"Great is He,\",\"the King of glory!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0019', 19, 'O Sing a New Song to the Lord', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O sing a new song to the Lord
For marvels He has done;
His right hand and His holy arm
The victory have won.
With harp, with harp and voice of psalms
Unto Jehovah sing;
Let trumpets and the echoing horn
Acclaim the Lord our King!
Let seas with all their creatures roar,
The world and dwellers there,
And let the rivers clap their hands,
The hills their joy declare.
Before the Lord: because He comes,
To judge the earth comes He;
He\'ll judge the world with righteousness,
His folk with equity.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0019', 'verse', 1, 0, '[\"O sing a new song to the Lord\",\"For marvels He has done;\",\"His right hand and His holy arm\",\"The victory have won.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0019', 'verse', 2, 1, '[\"With harp, with harp and voice of psalms\",\"Unto Jehovah sing;\",\"Let trumpets and the echoing horn\",\"Acclaim the Lord our King!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0019', 'verse', 3, 2, '[\"Let seas with all their creatures roar,\",\"The world and dwellers there,\",\"And let the rivers clap their hands,\",\"The hills their joy declare.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0019', 'verse', 4, 3, '[\"Before the Lord: because He comes,\",\"To judge the earth comes He;\",\"He\'ll judge the world with righteousness,\",\"His folk with equity.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0020', 20, 'O Praise Ye the Lord', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O praise ye the Lord!
Praise Him in the height;
Rejoice in His word,
Ye angels of light;
Ye heavens, adore Him
By whom ye were made,
And worship before Him,
In brightness arrayed.
O praise ye the Lord!
Praise Him upon earth,
In tuneful accord:
Ye sons of new birth;
Praise Him who hath brought you
His grace from above,
Praise Him who hath taught you
To sing of His love.
O praise ye the Lord,
All things that give sound;
Each jubilant chord,
Re-echo around;
Loud organs His glory
Forth tell in deep tone,
And sweet harp, the story
Of what He hath done.
O praise ye the Lord!
Thanksgiving and song
To Him be out-poured
All ages along:
For love in creation,
For heaven restored.
For grace of salvation,
O praise ye the Lord!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0020', 'verse', 1, 0, '[\"O praise ye the Lord!\",\"Praise Him in the height;\",\"Rejoice in His word,\",\"Ye angels of light;\",\"Ye heavens, adore Him\",\"By whom ye were made,\",\"And worship before Him,\",\"In brightness arrayed.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0020', 'verse', 2, 1, '[\"O praise ye the Lord!\",\"Praise Him upon earth,\",\"In tuneful accord:\",\"Ye sons of new birth;\",\"Praise Him who hath brought you\",\"His grace from above,\",\"Praise Him who hath taught you\",\"To sing of His love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0020', 'verse', 3, 2, '[\"O praise ye the Lord,\",\"All things that give sound;\",\"Each jubilant chord,\",\"Re-echo around;\",\"Loud organs His glory\",\"Forth tell in deep tone,\",\"And sweet harp, the story\",\"Of what He hath done.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0020', 'verse', 4, 3, '[\"O praise ye the Lord!\",\"Thanksgiving and song\",\"To Him be out-poured\",\"All ages along:\",\"For love in creation,\",\"For heaven restored.\",\"For grace of salvation,\",\"O praise ye the Lord!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0021', 21, 'Immortal, Invisible, God Only Wise', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Immortal, invisible, God only wise,
In light inaccessible hid from our eyes.
Most blessed, most glorious, the Ancient of Days,
Almighty, victorious, Thy great name we praise.
Unresting, unhasting, and silent as light,
Nor wanting, nor wasting, Thou rulest in might;
Thy justice, like mountains, high soaring above
Thy clouds, which are fountains of goodness and love.
To all life Thou givest to both great and small;
In all life Thou livest, the true life of all;
We blossom and flourish, like leaves on the tree,
Then wither and perish; but naught changeth Thee.
Great Father of glory, pure Father of light,
Thine angels adore Thee, all veiling their sight;
All laud we would render; O help us to see
\'Tis only the splendor of light hideth Thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0021', 'verse', 1, 0, '[\"Immortal, invisible, God only wise,\",\"In light inaccessible hid from our eyes.\",\"Most blessed, most glorious, the Ancient of Days,\",\"Almighty, victorious, Thy great name we praise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0021', 'verse', 2, 1, '[\"Unresting, unhasting, and silent as light,\",\"Nor wanting, nor wasting, Thou rulest in might;\",\"Thy justice, like mountains, high soaring above\",\"Thy clouds, which are fountains of goodness and love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0021', 'verse', 3, 2, '[\"To all life Thou givest to both great and small;\",\"In all life Thou livest, the true life of all;\",\"We blossom and flourish, like leaves on the tree,\",\"Then wither and perish; but naught changeth Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0021', 'verse', 4, 3, '[\"Great Father of glory, pure Father of light,\",\"Thine angels adore Thee, all veiling their sight;\",\"All laud we would render; O help us to see\",\"\'Tis only the splendor of light hideth Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0022', 22, 'God Is Our Song', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'God is our Song, and every singer blest
Who praising Him finds energy and rest.
All who praise God with unaffected joy
Give back to us the wisdom we destroy,
Give back to us the wisdom we destroy.
God is our Song, for Jesus comes to save;
While praising Him we offer all we have.
New songs we sing, in ventures new unite,
When Jesus leads us upward into light,
When Jesus leads us upward into light.
This is the Song no conflict ever drowns;
Who praises God our human wrath disowns.
Love knows what rich complexities of sound
God builds upon a simple common ground,
God builds upon a simple common ground.
God is our Silence when no songs are sung,
When ecstasy or sorrow stills the tongue.
Glorious the faith which silently obeys
Until we find again the voice of praise,
Until we find again the voice of praise.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0022', 'verse', 1, 0, '[\"God is our Song, and every singer blest\",\"Who praising Him finds energy and rest.\",\"All who praise God with unaffected joy\",\"Give back to us the wisdom we destroy,\",\"Give back to us the wisdom we destroy.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0022', 'verse', 2, 1, '[\"God is our Song, for Jesus comes to save;\",\"While praising Him we offer all we have.\",\"New songs we sing, in ventures new unite,\",\"When Jesus leads us upward into light,\",\"When Jesus leads us upward into light.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0022', 'verse', 3, 2, '[\"This is the Song no conflict ever drowns;\",\"Who praises God our human wrath disowns.\",\"Love knows what rich complexities of sound\",\"God builds upon a simple common ground,\",\"God builds upon a simple common ground.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0022', 'verse', 4, 3, '[\"God is our Silence when no songs are sung,\",\"When ecstasy or sorrow stills the tongue.\",\"Glorious the faith which silently obeys\",\"Until we find again the voice of praise,\",\"Until we find again the voice of praise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0023', 23, 'Now the Joyful Bells A-Ringing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Now the joyful bells a-ring,
All ye mountains of the Lord!
Lift our hearts like birds a-winging,
All ye mountains, praise the Lord!
Now our festal season bringing
Kinsmen all to bide and board,
Sets our cheery voices singing:
All ye mountains, praise the Lord!
Dear our home as dear none other;
Where the mountains praise the Lord!
Gladly here our care we smother;
Where the mountains praise the Lord!
Here we know that Christ our brother
Binds us all as by a cord:
He was born of Mary mother
Where the mountains praise the Lord!
Cold the year, new whiteness wearing,
All ye mountains, praise the Lord!
Peace, good will to us a-bearing,
All ye mountains praise the Lord!
Now we all God\'s goodness sharing
Break the bread and sheath the sword:
Bright our hearts the signal flaring,
All ye mountains, praise the Lord!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0023', 'verse', 1, 0, '[\"Now the joyful bells a-ring,\",\"All ye mountains of the Lord!\",\"Lift our hearts like birds a-winging,\",\"All ye mountains, praise the Lord!\",\"Now our festal season bringing\",\"Kinsmen all to bide and board,\",\"Sets our cheery voices singing:\",\"All ye mountains, praise the Lord!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0023', 'verse', 2, 1, '[\"Dear our home as dear none other;\",\"Where the mountains praise the Lord!\",\"Gladly here our care we smother;\",\"Where the mountains praise the Lord!\",\"Here we know that Christ our brother\",\"Binds us all as by a cord:\",\"He was born of Mary mother\",\"Where the mountains praise the Lord!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0023', 'verse', 3, 2, '[\"Cold the year, new whiteness wearing,\",\"All ye mountains, praise the Lord!\",\"Peace, good will to us a-bearing,\",\"All ye mountains praise the Lord!\",\"Now we all God\'s goodness sharing\",\"Break the bread and sheath the sword:\",\"Bright our hearts the signal flaring,\",\"All ye mountains, praise the Lord!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0024', 24, 'Every Star Shall Sing A Carol', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Every star shall sing a carol;
Every creature, high or low,
Come and praise the King of heaven
By whatever name you know.
God above, Man below,
Holy is the name I know.
When the King of all creation
Had a cradle on the earth,
Holy was the human body,
Holy was the human birth.
Every star and every planet,
Every creature, high or low,
Come and praise the King of heaven
By whatever name you know.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0024', 'verse', 1, 0, '[\"Every star shall sing a carol;\",\"Every creature, high or low,\",\"Come and praise the King of heaven\",\"By whatever name you know.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0024', 'chorus', 0, 1, '[\"God above, Man below,\",\"Holy is the name I know.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0024', 'verse', 2, 2, '[\"When the King of all creation\",\"Had a cradle on the earth,\",\"Holy was the human body,\",\"Holy was the human birth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0024', 'verse', 3, 3, '[\"Every star and every planet,\",\"Every creature, high or low,\",\"Come and praise the King of heaven\",\"By whatever name you know.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0025', 25, 'Praise the Lord, His Glories Show', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Praise the Lord, His glories show,
Alleluia!
Saints within His courts below,
Alleluia!
Angels \'round His throne above,
Alleluia!
All that see and share His love.
Alleluia!
Earth to heaven and heaven to earth,
Alleluia!
Tell His wonders, sing His worth,
Alleluia!
Age to age and shore to shore,
Alleluia!
Praise Him, praise Him evermore!
Alleluia!
Praise the Lord, His mercies trace,
Alleluia!
Praise His providence and grace,
Alleluia!
All that He for man hath done,
Alleluia!
All He sends us through His Son.
Alleluia!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0025', 'verse', 1, 0, '[\"Praise the Lord, His glories show,\",\"Alleluia!\",\"Saints within His courts below,\",\"Alleluia!\",\"Angels \'round His throne above,\",\"Alleluia!\",\"All that see and share His love.\",\"Alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0025', 'verse', 2, 1, '[\"Earth to heaven and heaven to earth,\",\"Alleluia!\",\"Tell His wonders, sing His worth,\",\"Alleluia!\",\"Age to age and shore to shore,\",\"Alleluia!\",\"Praise Him, praise Him evermore!\",\"Alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0025', 'verse', 3, 2, '[\"Praise the Lord, His mercies trace,\",\"Alleluia!\",\"Praise His providence and grace,\",\"Alleluia!\",\"All that He for man hath done,\",\"Alleluia!\",\"All He sends us through His Son.\",\"Alleluia!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0026', 26, 'Praise the Lord! You Heavens Adore Him', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Praise the Lord! you heavens, adore Him;
Praise Him, angels in the height;
Sun and moon, rejoice before Him,
Praise Him, all you stars of light.
Praise the Lord, for He has spoken;
Worlds His mighty voice obeyed;
Laws which never shall be broken
For their guidance He has made.
Praise the Lord! for He is glorious;
Never shall His promise fail.
God has made His saints victorious;
Sin and death shall not prevail.
Praise the God of our salvation!
Hosts on high, His power proclaim;
Heaven and earth and all creation,
Laud and magnify His name.
Worship, honor, glory, blessing,
Lord, we offer as our gift.
Young and old, Your praise expressing,
Our glad songs to You we lift.
All the saints in heaven adore You,
We would join their glad acclaim;
As Your angels serve before You,
So on earth we praise Your name.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0026', 'verse', 1, 0, '[\"Praise the Lord! you heavens, adore Him;\",\"Praise Him, angels in the height;\",\"Sun and moon, rejoice before Him,\",\"Praise Him, all you stars of light.\",\"Praise the Lord, for He has spoken;\",\"Worlds His mighty voice obeyed;\",\"Laws which never shall be broken\",\"For their guidance He has made.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0026', 'verse', 2, 1, '[\"Praise the Lord! for He is glorious;\",\"Never shall His promise fail.\",\"God has made His saints victorious;\",\"Sin and death shall not prevail.\",\"Praise the God of our salvation!\",\"Hosts on high, His power proclaim;\",\"Heaven and earth and all creation,\",\"Laud and magnify His name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0026', 'verse', 3, 2, '[\"Worship, honor, glory, blessing,\",\"Lord, we offer as our gift.\",\"Young and old, Your praise expressing,\",\"Our glad songs to You we lift.\",\"All the saints in heaven adore You,\",\"We would join their glad acclaim;\",\"As Your angels serve before You,\",\"So on earth we praise Your name.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0027', 27, 'Rejoice, Ye Pure in Heart!', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Rejoice, ye pure in heart!
Rejoice, give thanks, and sing;
Your festal banner wave on high,
The cross of Christ your King.
Rejoice!
Rejoice!
Rejoice, give thanks, and sing!
With voice as full and strong
As ocean\'s surging praise,
Send forth the sturdy hymns of old,
The psalms of ancient days.
With all the angel choirs,
With all the saints on earth
Pour out the strains of joy and bliss,
True rapture, noblest mirth.
Yes, on through life\'s long path,
Still chanting as ye go;');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0027', 'verse', 1, 0, '[\"Rejoice, ye pure in heart!\",\"Rejoice, give thanks, and sing;\",\"Your festal banner wave on high,\",\"The cross of Christ your King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0027', 'chorus', 0, 1, '[\"Rejoice!\",\"Rejoice!\",\"Rejoice, give thanks, and sing!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0027', 'verse', 2, 2, '[\"With voice as full and strong\",\"As ocean\'s surging praise,\",\"Send forth the sturdy hymns of old,\",\"The psalms of ancient days.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0027', 'verse', 3, 3, '[\"With all the angel choirs,\",\"With all the saints on earth\",\"Pour out the strains of joy and bliss,\",\"True rapture, noblest mirth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0027', 'verse', 4, 4, '[\"Yes, on through life\'s long path,\",\"Still chanting as ye go;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0028', 28, 'Praise We the Lord', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Praise we the Lord, who made all beauty
For all our senses to enjoy;
Owe we our humble thanks and duty
That simple pleasures never cloy;
Praise we the Lord, who made all beauty
For all our senses to enjoy.
Praise Him who loves to see young lovers,
Fresh hearts that swell with youthful pride;
Thank Him who sends the sun above us,
As bridegroom fit to meet his bride;
Praise Him who loves to see young lovers,
Fresh hearts that swell with youthful pride.
Praise Him who by a simple flower
Lifts up our hearts to things above;
Thank Him who gives to each one power
To find a friend to know and love;
Praise Him who by a simple flower
Lifts up our hearts to things above.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0028', 'verse', 1, 0, '[\"Praise we the Lord, who made all beauty\",\"For all our senses to enjoy;\",\"Owe we our humble thanks and duty\",\"That simple pleasures never cloy;\",\"Praise we the Lord, who made all beauty\",\"For all our senses to enjoy.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0028', 'verse', 2, 1, '[\"Praise Him who loves to see young lovers,\",\"Fresh hearts that swell with youthful pride;\",\"Thank Him who sends the sun above us,\",\"As bridegroom fit to meet his bride;\",\"Praise Him who loves to see young lovers,\",\"Fresh hearts that swell with youthful pride.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0028', 'verse', 3, 2, '[\"Praise Him who by a simple flower\",\"Lifts up our hearts to things above;\",\"Thank Him who gives to each one power\",\"To find a friend to know and love;\",\"Praise Him who by a simple flower\",\"Lifts up our hearts to things above.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0029', 29, 'Sing Praise to God', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Sing praise to God who reigns above,
The God of all creation,
The God of power, the God of love,
The God of our salvation
With healing balm my soul He fills,
And every faithless murmur stills;
To God all praise and glory!
What God\'s almighty power hath made
His gracious mercy keepeth;
By morning glow or evening shade,
His watchful eye ne\'er sleepeth,
Within the kingdom of His might,
Lo! all is just, and all is right:
To God all praise and glory!
The Lord is never far away,
Throughout all grief distressing
An everpresent help and stay,
Our peace, and joy, and blessing.
As with a mother\'s tender hand,
He leads His own, His chosen band;
To God all praise and glory!
Then all my gladsome way along,
I sing aloud Thy praises,
That men may hear the grateful song
My voice unwearied raises:
Be joyful in the Lord, my heart!
Both soul and body bear your part!
To God all praise and glory!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0029', 'verse', 1, 0, '[\"Sing praise to God who reigns above,\",\"The God of all creation,\",\"The God of power, the God of love,\",\"The God of our salvation\",\"With healing balm my soul He fills,\",\"And every faithless murmur stills;\",\"To God all praise and glory!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0029', 'verse', 2, 1, '[\"What God\'s almighty power hath made\",\"His gracious mercy keepeth;\",\"By morning glow or evening shade,\",\"His watchful eye ne\'er sleepeth,\",\"Within the kingdom of His might,\",\"Lo! all is just, and all is right:\",\"To God all praise and glory!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0029', 'verse', 3, 2, '[\"The Lord is never far away,\",\"Throughout all grief distressing\",\"An everpresent help and stay,\",\"Our peace, and joy, and blessing.\",\"As with a mother\'s tender hand,\",\"He leads His own, His chosen band;\",\"To God all praise and glory!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0029', 'verse', 4, 3, '[\"Then all my gladsome way along,\",\"I sing aloud Thy praises,\",\"That men may hear the grateful song\",\"My voice unwearied raises:\",\"Be joyful in the Lord, my heart!\",\"Both soul and body bear your part!\",\"To God all praise and glory!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0030', 30, 'Holy God, We Praise Your Name', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Holy God, we praise Your name;
Lord of all, we bow before You!
All on earth Your scepter claim,
All in heaven above adore You;
Infinite Your vast domain.
Everlasting is Your reign.
Hark! the loud celestial hymn
Angel choirs above are raising,
Cherubim and seraphim,
In unceasing chorus praising;
Fill the heavens with sweet accord:
Holy, holy, holy, Lord.
Holy Father, Holy Son,
Holy Spirit, three we name You;
While in essence only one,
Undivided God we claim You;
And adoring bend the knee,
While we own the mystery.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0030', 'verse', 1, 0, '[\"Holy God, we praise Your name;\",\"Lord of all, we bow before You!\",\"All on earth Your scepter claim,\",\"All in heaven above adore You;\",\"Infinite Your vast domain.\",\"Everlasting is Your reign.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0030', 'verse', 2, 1, '[\"Hark! the loud celestial hymn\",\"Angel choirs above are raising,\",\"Cherubim and seraphim,\",\"In unceasing chorus praising;\",\"Fill the heavens with sweet accord:\",\"Holy, holy, holy, Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0030', 'verse', 3, 2, '[\"Holy Father, Holy Son,\",\"Holy Spirit, three we name You;\",\"While in essence only one,\",\"Undivided God we claim You;\",\"And adoring bend the knee,\",\"While we own the mystery.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0031', 31, 'Tell Out My Soul', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Tell out, my soul, the greatness of the Lord:
Unnumbered blessings give my spirit voice;
Tender to me the promise of His word;
In God my Savior shall my heart rejoice.
Tell out, my soul, the greatness of His name:
Make known His might, the deeds His arm has done;
His mercy sure, from age to age the same;
His holy name, the Lord, the Mighty One.
Tell out, my soul, the greatness of His might:
Pow\'rs and dominions lay their glory by;
Proud hearts and stubborn wills are put to flight,
The hungry fed, the humble lifted high.
Tell out, my soul, the glories of His word:
Firm is His promise, and His mercy sure.
Tell out, my soul, the greatness of the Lord
To children\'s children and forever more.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0031', 'verse', 1, 0, '[\"Tell out, my soul, the greatness of the Lord:\",\"Unnumbered blessings give my spirit voice;\",\"Tender to me the promise of His word;\",\"In God my Savior shall my heart rejoice.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0031', 'verse', 2, 1, '[\"Tell out, my soul, the greatness of His name:\",\"Make known His might, the deeds His arm has done;\",\"His mercy sure, from age to age the same;\",\"His holy name, the Lord, the Mighty One.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0031', 'verse', 3, 2, '[\"Tell out, my soul, the greatness of His might:\",\"Pow\'rs and dominions lay their glory by;\",\"Proud hearts and stubborn wills are put to flight,\",\"The hungry fed, the humble lifted high.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0031', 'verse', 4, 3, '[\"Tell out, my soul, the glories of His word:\",\"Firm is His promise, and His mercy sure.\",\"Tell out, my soul, the greatness of the Lord\",\"To children\'s children and forever more.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0032', 32, 'When in Our Music God Is Glorified', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'When in our music God is glorified,
And adoration leaves no room for pride,
It is as though the whole creation cried:
Alleluia!
How oft, in making music, we have found
A new dimension in the world of sound,
As worship moved us to a more profound
Alleluia!
And did not Jesus sing a psalm that night
When utmost evil strove against the light?
Then let us sing for whom He won the fight:
Alleluia!
Let every instrument be used for praise;
Let all rejoice who have a voice to raise;
And may God give us faith to sing always:
Alleluia!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0032', 'verse', 1, 0, '[\"When in our music God is glorified,\",\"And adoration leaves no room for pride,\",\"It is as though the whole creation cried:\",\"Alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0032', 'verse', 2, 1, '[\"How oft, in making music, we have found\",\"A new dimension in the world of sound,\",\"As worship moved us to a more profound\",\"Alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0032', 'verse', 3, 2, '[\"And did not Jesus sing a psalm that night\",\"When utmost evil strove against the light?\",\"Then let us sing for whom He won the fight:\",\"Alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0032', 'verse', 4, 3, '[\"Let every instrument be used for praise;\",\"Let all rejoice who have a voice to raise;\",\"And may God give us faith to sing always:\",\"Alleluia!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0033', 33, 'Sing A New Song to the Lord', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Sing a new song to the Lord,
He to whom wonders belong.
Rejoice in His triumph and tell of His power.
O sing a new song to the Lord.
Now to the ends of the earth
See His salvation is shown.
And still He remembers His mercy and truth,
Unchanging in love to His own.
Sing a new song and rejoice.
Publish His praises abroad.
Let voices in chorus with trumpet and horn,
Resound for the joy of the Lord.
Join with the hills and the sea,
Thunders of praise to prolong.
In judgment and justice
He comes to the earth.
O sing a new song to the Lord.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0033', 'verse', 1, 0, '[\"Sing a new song to the Lord,\",\"He to whom wonders belong.\",\"Rejoice in His triumph and tell of His power.\",\"O sing a new song to the Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0033', 'verse', 2, 1, '[\"Now to the ends of the earth\",\"See His salvation is shown.\",\"And still He remembers His mercy and truth,\",\"Unchanging in love to His own.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0033', 'verse', 3, 2, '[\"Sing a new song and rejoice.\",\"Publish His praises abroad.\",\"Let voices in chorus with trumpet and horn,\",\"Resound for the joy of the Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0033', 'verse', 4, 3, '[\"Join with the hills and the sea,\",\"Thunders of praise to prolong.\",\"In judgment and justice\",\"He comes to the earth.\",\"O sing a new song to the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0034', 34, 'Wake the Song', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Wake the song of joy and gladness;
Hither bring your noblest lays;
Banish every thought of sadness,
Pouring forth your highest praise.
Sing to Him whose care has brought us
Once again with friends to meet,
And whose loving voice has taught us
Of the way to Jesus\' feet.
Wake the song, wake the song,
The song of joy and gladness,
Wake the song, wake the song,
The song of Jubilee.
Joyfully with songs and banners,
We will greet the festal day;
Shout aloud our glad hosannas,
And our grateful homage pay.
We will chant our Savior\'s glory
While our thoughts we raise above,
Telling still \"the old, old story,\"
Precious theme redeeming love!
Thanks to Thee, O holy Father,
For the mercies of the year;
May each heart, as here we gather,
Swell with gratitude sincere.
Thanks to Thee, O loving Savior,
For redemption through Thy blood.
Breathe upon us, Holy Spirit,
Sweetly draw us near to God.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0034', 'verse', 1, 0, '[\"Wake the song of joy and gladness;\",\"Hither bring your noblest lays;\",\"Banish every thought of sadness,\",\"Pouring forth your highest praise.\",\"Sing to Him whose care has brought us\",\"Once again with friends to meet,\",\"And whose loving voice has taught us\",\"Of the way to Jesus\' feet.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0034', 'chorus', 0, 1, '[\"Wake the song, wake the song,\",\"The song of joy and gladness,\",\"Wake the song, wake the song,\",\"The song of Jubilee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0034', 'verse', 2, 2, '[\"Joyfully with songs and banners,\",\"We will greet the festal day;\",\"Shout aloud our glad hosannas,\",\"And our grateful homage pay.\",\"We will chant our Savior\'s glory\",\"While our thoughts we raise above,\",\"Telling still \\\"the old, old story,\\\"\",\"Precious theme redeeming love!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0034', 'verse', 3, 3, '[\"Thanks to Thee, O holy Father,\",\"For the mercies of the year;\",\"May each heart, as here we gather,\",\"Swell with gratitude sincere.\",\"Thanks to Thee, O loving Savior,\",\"For redemption through Thy blood.\",\"Breathe upon us, Holy Spirit,\",\"Sweetly draw us near to God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0035', 35, 'With Songs and Honors', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'With songs and honors sounding loud,
Address the Lord on high;
Over the heavens He spreads His cloud,
And waters veil the sky.
He sends His showers of blessing down
To cheer the plains below;
He makes the grass the mountains crown,
And corn in valleys grow.
His steady counsels change the face
Of the declining year;
He bids the sun cut short his race,
And wintry days appear.
He sends His word, and melts the snow;
The fields no longer mourn;
He calls the warmer gales to blow,
And bids the spring return.
The changing wind, the flying cloud,
Obey His mighty word:
With songs and honors sounding loud
Praise ye the sovereign Lord!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0035', 'verse', 1, 0, '[\"With songs and honors sounding loud,\",\"Address the Lord on high;\",\"Over the heavens He spreads His cloud,\",\"And waters veil the sky.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0035', 'verse', 2, 1, '[\"He sends His showers of blessing down\",\"To cheer the plains below;\",\"He makes the grass the mountains crown,\",\"And corn in valleys grow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0035', 'verse', 3, 2, '[\"His steady counsels change the face\",\"Of the declining year;\",\"He bids the sun cut short his race,\",\"And wintry days appear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0035', 'verse', 4, 3, '[\"He sends His word, and melts the snow;\",\"The fields no longer mourn;\",\"He calls the warmer gales to blow,\",\"And bids the spring return.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0035', 'verse', 5, 4, '[\"The changing wind, the flying cloud,\",\"Obey His mighty word:\",\"With songs and honors sounding loud\",\"Praise ye the sovereign Lord!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0036', 36, 'O Thou in Whose Presence', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O Thou in whose presence my soul takes delight,
On whom in affliction I call,
My comfort by day and my song in the night,
My hope, my salvation, my all!
His voice, as the sound of the dulcimer sweet,
Is heard through the shadows of death;
The cedars of Lebanon bow at His feet,
The air is perfumed with His breath.
His lips, as a fountain of righteousness flow,
To water the gardens of grace;');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0036', 'verse', 1, 0, '[\"O Thou in whose presence my soul takes delight,\",\"On whom in affliction I call,\",\"My comfort by day and my song in the night,\",\"My hope, my salvation, my all!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0036', 'verse', 2, 1, '[\"His voice, as the sound of the dulcimer sweet,\",\"Is heard through the shadows of death;\",\"The cedars of Lebanon bow at His feet,\",\"The air is perfumed with His breath.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0036', 'verse', 3, 2, '[\"His lips, as a fountain of righteousness flow,\",\"To water the gardens of grace;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0037', 37, 'O Sing, My Soul, Your Maker\'s Praise', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O sing my soul, your Maker\'s praise
In grateful hymns ascending;
Whose steadfast love has crowned your days
With heav\'nly gifts unending.
I sought the Lord, He heard my cry;
His holy angels hover nigh
The tents of those who love Him.
The Lord is good to those who seek
His face in time of sorrow,
Pro\'viding comfort to the weak
And grace for each tomorrow.
Though grief may tarry for a night,
The morn shall break in joy and light
With blessings from His presence.
The Lord will turn His face in peace
When troubled souls draw near Him;
His lovingkindness shall not cease
To those who trust and fear Him.
Our God will not forsake His own;
Eternal is His heav\'nly throne;
His kingdom stands forever.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0037', 'verse', 1, 0, '[\"O sing my soul, your Maker\'s praise\",\"In grateful hymns ascending;\",\"Whose steadfast love has crowned your days\",\"With heav\'nly gifts unending.\",\"I sought the Lord, He heard my cry;\",\"His holy angels hover nigh\",\"The tents of those who love Him.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0037', 'verse', 2, 1, '[\"The Lord is good to those who seek\",\"His face in time of sorrow,\",\"Pro\'viding comfort to the weak\",\"And grace for each tomorrow.\",\"Though grief may tarry for a night,\",\"The morn shall break in joy and light\",\"With blessings from His presence.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0037', 'verse', 3, 2, '[\"The Lord will turn His face in peace\",\"When troubled souls draw near Him;\",\"His lovingkindness shall not cease\",\"To those who trust and fear Him.\",\"Our God will not forsake His own;\",\"Eternal is His heav\'nly throne;\",\"His kingdom stands forever.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0038', 38, 'Arise My Soul Arise', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Arise, my soul, arise!
Stretch forth to things eternal
And hasten to the feet of your Redeemer God.
Though hid from mortal eyes,
He dwells in light supernal;
Yet worship Him in humbleness and call Him Lord.
His banquet of love
Awaits you above;
Yet here He grants a foretaste of the feast to come!
Rejoice, my soul, rejoice,
To heav\'n lift up your voice:
Alleluia, alleluia, alleluia!
Now hear the harps of heav\'n!
Oh, hear the song victorious,
The never-ending anthem sounding through the sky!
To mortals is not giv\'n
To join in strains so glorious;
Yet here on earth we too can sing our praises high!
He bought with His blood
The ransomed of God;
To Him be ever lasting pow\'r and victory.
And let the great amen
Resound through heav\'n again.
Alleluia, alleluia, alleluia!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0038', 'verse', 1, 0, '[\"Arise, my soul, arise!\",\"Stretch forth to things eternal\",\"And hasten to the feet of your Redeemer God.\",\"Though hid from mortal eyes,\",\"He dwells in light supernal;\",\"Yet worship Him in humbleness and call Him Lord.\",\"His banquet of love\",\"Awaits you above;\",\"Yet here He grants a foretaste of the feast to come!\",\"Rejoice, my soul, rejoice,\",\"To heav\'n lift up your voice:\",\"Alleluia, alleluia, alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0038', 'verse', 2, 1, '[\"Now hear the harps of heav\'n!\",\"Oh, hear the song victorious,\",\"The never-ending anthem sounding through the sky!\",\"To mortals is not giv\'n\",\"To join in strains so glorious;\",\"Yet here on earth we too can sing our praises high!\",\"He bought with His blood\",\"The ransomed of God;\",\"To Him be ever lasting pow\'r and victory.\",\"And let the great amen\",\"Resound through heav\'n again.\",\"Alleluia, alleluia, alleluia!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0039', 39, 'Lord, in the Morning', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lord, in the morning Thou shalt hear
My voice ascending high;
To Thee will I direct my prayer,
To Thee lift up mine eye;
Up to the hills where Christ is gone
To plead for all His saints,
Presenting at His Father\'s throne
Our songs and our complaints.
O may Thy Spirit guide my feet
In ways of righteousness;
Make every path of duty straight
And plain before my face.
The men that love and fear Thy name
Shall see their hopes fulfilled;
The mighty God will compass them
With favor as a shield.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0039', 'verse', 1, 0, '[\"Lord, in the morning Thou shalt hear\",\"My voice ascending high;\",\"To Thee will I direct my prayer,\",\"To Thee lift up mine eye;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0039', 'verse', 2, 1, '[\"Up to the hills where Christ is gone\",\"To plead for all His saints,\",\"Presenting at His Father\'s throne\",\"Our songs and our complaints.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0039', 'verse', 3, 2, '[\"O may Thy Spirit guide my feet\",\"In ways of righteousness;\",\"Make every path of duty straight\",\"And plain before my face.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0039', 'verse', 4, 3, '[\"The men that love and fear Thy name\",\"Shall see their hopes fulfilled;\",\"The mighty God will compass them\",\"With favor as a shield.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0040', 40, 'The  Dawn of God\'s Dear Sabbath', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'The dawn of God\'s dear Sabbath
Breaks o\'er the earth again,
As some sweet summer morning
After a night of pain;
It comes as cooling showers
To some exhausted land,
As shade of clustered palm trees
\'Mid weary wastes of sand.
Lord, we would bring for offering,
Though marred with earthly soil,
A week of earnest labor,
Of steady, faithful toil,
Fair fruits of self-denial,
Of strong, deep love to Thee,
Fostered by Thine own Spirit,
In true humility.
And we would bring our burden
Of sinful thought and deed,
In Thy pure presence kneeling,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0040', 'verse', 1, 0, '[\"The dawn of God\'s dear Sabbath\",\"Breaks o\'er the earth again,\",\"As some sweet summer morning\",\"After a night of pain;\",\"It comes as cooling showers\",\"To some exhausted land,\",\"As shade of clustered palm trees\",\"\'Mid weary wastes of sand.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0040', 'verse', 2, 1, '[\"Lord, we would bring for offering,\",\"Though marred with earthly soil,\",\"A week of earnest labor,\",\"Of steady, faithful toil,\",\"Fair fruits of self-denial,\",\"Of strong, deep love to Thee,\",\"Fostered by Thine own Spirit,\",\"In true humility.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0040', 'verse', 3, 2, '[\"And we would bring our burden\",\"Of sinful thought and deed,\",\"In Thy pure presence kneeling,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0041', 41, 'O Splendor of God\'s Glory Bright', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O splendor of God\'s glory bright,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0041', 'verse', 1, 0, '[\"O splendor of God\'s glory bright,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0042', 42, 'Now That the Daylight Fills the Sky', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Now that the daylight fills the sky,
We lift our hearts to God on high,
That He, in all we do or say,
Would keep us free from harm today;
Would guard our hearts and tongues from strife;');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0042', 'verse', 1, 0, '[\"Now that the daylight fills the sky,\",\"We lift our hearts to God on high,\",\"That He, in all we do or say,\",\"Would keep us free from harm today;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0042', 'verse', 2, 1, '[\"Would guard our hearts and tongues from strife;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0043', 43, 'When Morning Gilds the Skies', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'When morning gilds the skies,
My heart awaking cries,
May Jesus Christ be praised!
Alike at work and prayer,
To Jesus I repair;
May Jesus Christ be praised!
Whene\'er the sweet church bell
Peals over hill and dell,
May Jesus Christ be praised!
O hark to what it sings,
As joyously it rings,
May Jesus Christ be praised!
The night becomes as day,
When from the heart we say,
May Jesus Christ be praised!
The pow\'rs of darkness fear,
When this sweet chant they hear,
May Jesus Christ be praised!
Ye nations of mankind,
In this your concord find,
May Jesus Christ be praised!
Let all the earth around
Ring joyous with the sound,
May Jesus Christ be praised!
In heaven\'s eternal bliss
The loveliest strain is this,
May Jesus Christ be praised!
Let earth, and sea, and sky');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0043', 'verse', 1, 0, '[\"When morning gilds the skies,\",\"My heart awaking cries,\",\"May Jesus Christ be praised!\",\"Alike at work and prayer,\",\"To Jesus I repair;\",\"May Jesus Christ be praised!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0043', 'verse', 2, 1, '[\"Whene\'er the sweet church bell\",\"Peals over hill and dell,\",\"May Jesus Christ be praised!\",\"O hark to what it sings,\",\"As joyously it rings,\",\"May Jesus Christ be praised!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0043', 'verse', 3, 2, '[\"The night becomes as day,\",\"When from the heart we say,\",\"May Jesus Christ be praised!\",\"The pow\'rs of darkness fear,\",\"When this sweet chant they hear,\",\"May Jesus Christ be praised!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0043', 'verse', 4, 3, '[\"Ye nations of mankind,\",\"In this your concord find,\",\"May Jesus Christ be praised!\",\"Let all the earth around\",\"Ring joyous with the sound,\",\"May Jesus Christ be praised!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0043', 'verse', 5, 4, '[\"In heaven\'s eternal bliss\",\"The loveliest strain is this,\",\"May Jesus Christ be praised!\",\"Let earth, and sea, and sky\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0044', 44, 'Morning Has Broken', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Morning has broken like the first morning,
Blackbird has spoken like the first bird.
Praise for the singing! Praise for the morning!
Praise for them springing fresh from the Word!
Sweet the rain\'s new fall sunlit from heaven,
Like the first dew fall on the first grass.
Praise for the sweetness of the wet garden,
Sprung in completeness where His feet pass.
Mine is the sunlight! Mine is the morning
Born of the one light Eden saw play!
Praise with elation, Praise every morning,
God\'s recreation of the new day!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0044', 'verse', 1, 0, '[\"Morning has broken like the first morning,\",\"Blackbird has spoken like the first bird.\",\"Praise for the singing! Praise for the morning!\",\"Praise for them springing fresh from the Word!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0044', 'verse', 2, 1, '[\"Sweet the rain\'s new fall sunlit from heaven,\",\"Like the first dew fall on the first grass.\",\"Praise for the sweetness of the wet garden,\",\"Sprung in completeness where His feet pass.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0044', 'verse', 3, 2, '[\"Mine is the sunlight! Mine is the morning\",\"Born of the one light Eden saw play!\",\"Praise with elation, Praise every morning,\",\"God\'s recreation of the new day!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0045', 45, 'Open Now Thy Gates of Beauty', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Open now Thy gates of beauty,
Zion, let me enter there,
Where my soul in joyful duty
Waits for God who answers prayer.
Oh, how blessed is this place,
Filled with solace, light, and grace!
Gracious God, I come before Thee;
Come Thou also unto me;
Where we find Thee and adore Thee,
There a heav\'n on earth must be.
To my heart, oh, enter Thou,
Let it be Thy temple now!
Here Thy praise is gladly chanted,
Here Thy seed is duly sown;
Let my soul, where it is planted,
Bring forth precious sheaves alone.
So that all I hear may be
Fruitful unto life in me.
Thou my faith increase and quicken,
Let me keep Thy gift divine;
Howsoe\'er temptations thicken,
May Thy Word still o\'er me shine
As my guiding star through life,
As my comfort in all strife.
Speak, O God, and I will hear Thee,
Let Thy will be done indeed;
May I, undisturbed, draw near Thee
While Thou dost Thy people feed
Here of life the fountain flows;
Here is balm for all our woes.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0045', 'verse', 1, 0, '[\"Open now Thy gates of beauty,\",\"Zion, let me enter there,\",\"Where my soul in joyful duty\",\"Waits for God who answers prayer.\",\"Oh, how blessed is this place,\",\"Filled with solace, light, and grace!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0045', 'verse', 2, 1, '[\"Gracious God, I come before Thee;\",\"Come Thou also unto me;\",\"Where we find Thee and adore Thee,\",\"There a heav\'n on earth must be.\",\"To my heart, oh, enter Thou,\",\"Let it be Thy temple now!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0045', 'verse', 3, 2, '[\"Here Thy praise is gladly chanted,\",\"Here Thy seed is duly sown;\",\"Let my soul, where it is planted,\",\"Bring forth precious sheaves alone.\",\"So that all I hear may be\",\"Fruitful unto life in me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0045', 'verse', 4, 3, '[\"Thou my faith increase and quicken,\",\"Let me keep Thy gift divine;\",\"Howsoe\'er temptations thicken,\",\"May Thy Word still o\'er me shine\",\"As my guiding star through life,\",\"As my comfort in all strife.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0045', 'verse', 5, 4, '[\"Speak, O God, and I will hear Thee,\",\"Let Thy will be done indeed;\",\"May I, undisturbed, draw near Thee\",\"While Thou dost Thy people feed\",\"Here of life the fountain flows;\",\"Here is balm for all our woes.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0046', 46, 'Abide With Me, \'Tis Eventide', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Abide with me, \'tis eventide!
The day is past and gone;
The shadows of the evening fall;
The night is coming on!
Within my heart a welcome guest,
Within my home abide;
O Savior, stay this night with me;
Behold, \'tis eventide!
O Savior, stay this night with me;
Behold, \'tis eventide.
Abide with me, \'tis eventide!
Thy walk today with me
Has made my heart within me burn,
As I communed with Thee.
Thy earnest words have filled my soul
And kept me near Thy side;
Abide with me, \'tis eventide!
And lone will be the night,
If I cannot commune with Thee,
Nor find in Thee my light.
The darkness of the world, I fear,
Would in my home abide;');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0046', 'verse', 1, 0, '[\"Abide with me, \'tis eventide!\",\"The day is past and gone;\",\"The shadows of the evening fall;\",\"The night is coming on!\",\"Within my heart a welcome guest,\",\"Within my home abide;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0046', 'chorus', 0, 1, '[\"O Savior, stay this night with me;\",\"Behold, \'tis eventide!\",\"O Savior, stay this night with me;\",\"Behold, \'tis eventide.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0046', 'verse', 2, 2, '[\"Abide with me, \'tis eventide!\",\"Thy walk today with me\",\"Has made my heart within me burn,\",\"As I communed with Thee.\",\"Thy earnest words have filled my soul\",\"And kept me near Thy side;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0046', 'verse', 3, 3, '[\"Abide with me, \'tis eventide!\",\"And lone will be the night,\",\"If I cannot commune with Thee,\",\"Nor find in Thee my light.\",\"The darkness of the world, I fear,\",\"Would in my home abide;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0047', 47, 'God, Who Made the Earth and Heaven', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'God, who made the earth and heaven,
Darkness and light:
You the day for work have given,
For rest the night.
May Your angel guards defend us,
Slumber sweet Your mercy send us,
Holy dreams and hopes attend us
All through the night.
And when morn again shall call us
To run life\'s way,
May we still, whate\'er befall us,
Your will obey.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0047', 'verse', 1, 0, '[\"God, who made the earth and heaven,\",\"Darkness and light:\",\"You the day for work have given,\",\"For rest the night.\",\"May Your angel guards defend us,\",\"Slumber sweet Your mercy send us,\",\"Holy dreams and hopes attend us\",\"All through the night.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0047', 'verse', 2, 1, '[\"And when morn again shall call us\",\"To run life\'s way,\",\"May we still, whate\'er befall us,\",\"Your will obey.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0048', 48, 'Softly Now the Light of Day', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Softly now the light of day
Fades upon our sight away;
Free from care, from labor free,
Lord, we would commune with Thee.
Thou, whose all-pervading eye
Nought escapes, without, within,
Pardon each infirmity,
Open fault, and secret sin.
Soon from us the light of day
Shall forever pass away;
Then, from sin and sorrow free,
Take us, Lord, to dwell with Thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0048', 'verse', 1, 0, '[\"Softly now the light of day\",\"Fades upon our sight away;\",\"Free from care, from labor free,\",\"Lord, we would commune with Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0048', 'verse', 2, 1, '[\"Thou, whose all-pervading eye\",\"Nought escapes, without, within,\",\"Pardon each infirmity,\",\"Open fault, and secret sin.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0048', 'verse', 3, 2, '[\"Soon from us the light of day\",\"Shall forever pass away;\",\"Then, from sin and sorrow free,\",\"Take us, Lord, to dwell with Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0049', 49, 'Savior, Breathe an Evening Blessing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Savior, breathe an evening blessing,
Ere repose our spirits seal;
Sin and want we come confessing;
Thou canst save, and Thou canst heal.
Though the night be dark and dreary,
Darkness cannot hide from Thee;
Thou art He who, never weary,
Watchest where Thy people be.
Though destruction walk around us,
Though the arrow past us fly,
Angel guards from Thee surround us,
We are safe if Thou art nigh.
Should swift death this night o\'ertake us,
And our couch become our tomb,
May the morn of glory wake us,
Clad in light and deathless bloom.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0049', 'verse', 1, 0, '[\"Savior, breathe an evening blessing,\",\"Ere repose our spirits seal;\",\"Sin and want we come confessing;\",\"Thou canst save, and Thou canst heal.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0049', 'verse', 2, 1, '[\"Though the night be dark and dreary,\",\"Darkness cannot hide from Thee;\",\"Thou art He who, never weary,\",\"Watchest where Thy people be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0049', 'verse', 3, 2, '[\"Though destruction walk around us,\",\"Though the arrow past us fly,\",\"Angel guards from Thee surround us,\",\"We are safe if Thou art nigh.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0049', 'verse', 4, 3, '[\"Should swift death this night o\'ertake us,\",\"And our couch become our tomb,\",\"May the morn of glory wake us,\",\"Clad in light and deathless bloom.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0050', 50, 'Abide With Me', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Abide with me; fast falls the eventide;
The darkness deepens; Lord, with me abide!
When other helpers fail, and comforts flee,
Help of the helpless, O abide with me!
Swift to its close ebbs out life\'s little day;
Earth\'s joys grow dim, its glories pass away;
Change and decay in all around I see;
O Thou, who changest not, abide with me!
I need Thy presence every passing hour;
What but Thy grace can foil the tempter\'s power?
Who like Thyself my guide and stay can be?
Through cloud and sunshine, O abide with me!
I fear no foe, with Thee at hand to bless;
Ills have no weight, and tears no bitterness:
Where is death\'s sting? where, grave, thy victory?
I triumph still if Thou abide with me!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0050', 'verse', 1, 0, '[\"Abide with me; fast falls the eventide;\",\"The darkness deepens; Lord, with me abide!\",\"When other helpers fail, and comforts flee,\",\"Help of the helpless, O abide with me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0050', 'verse', 2, 1, '[\"Swift to its close ebbs out life\'s little day;\",\"Earth\'s joys grow dim, its glories pass away;\",\"Change and decay in all around I see;\",\"O Thou, who changest not, abide with me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0050', 'verse', 3, 2, '[\"I need Thy presence every passing hour;\",\"What but Thy grace can foil the tempter\'s power?\",\"Who like Thyself my guide and stay can be?\",\"Through cloud and sunshine, O abide with me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0050', 'verse', 4, 3, '[\"I fear no foe, with Thee at hand to bless;\",\"Ills have no weight, and tears no bitterness:\",\"Where is death\'s sting? where, grave, thy victory?\",\"I triumph still if Thou abide with me!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0051', 51, 'Day Is Dying in the West', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Day is dying in the west;
Heaven is touching earth with rest;
Wait and worship while the night
Sets the evening lamps alight
Through all the sky.
Holy, holy, holy,
Lord God of Hosts!
Heaven and earth are full of Thee;
Heaven and earth are praising Thee,
O Lord most high!
Lord of life, beneath the dome
Of the universe, Thy home,
Gather us who seek Thy face
To the fold of Thy embrace,
For Thou art nigh.
While the deepening shadows fall,
Heart of love enfolding all,
Thro\' the glory and the grace
Of the stars that veil Thy face,
Our hearts ascend.
When forever from our sight
Pass the stars, the day, the night,
Lord of angels, on our eyes
Let eternal morning rise
And shadows end.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0051', 'verse', 1, 0, '[\"Day is dying in the west;\",\"Heaven is touching earth with rest;\",\"Wait and worship while the night\",\"Sets the evening lamps alight\",\"Through all the sky.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0051', 'chorus', 0, 1, '[\"Holy, holy, holy,\",\"Lord God of Hosts!\",\"Heaven and earth are full of Thee;\",\"Heaven and earth are praising Thee,\",\"O Lord most high!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0051', 'verse', 2, 2, '[\"Lord of life, beneath the dome\",\"Of the universe, Thy home,\",\"Gather us who seek Thy face\",\"To the fold of Thy embrace,\",\"For Thou art nigh.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0051', 'verse', 3, 3, '[\"While the deepening shadows fall,\",\"Heart of love enfolding all,\",\"Thro\' the glory and the grace\",\"Of the stars that veil Thy face,\",\"Our hearts ascend.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0051', 'verse', 4, 4, '[\"When forever from our sight\",\"Pass the stars, the day, the night,\",\"Lord of angels, on our eyes\",\"Let eternal morning rise\",\"And shadows end.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0052', 52, 'Now the Day Is Over', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Now the day is over;
Night is drawing nigh,
Shadows of the evening
Steal across the sky.
Father, give the weary
Calm and sweet repose;
With your tenderest blessing
May our eyelids close.
Through the long night-watches,
May your angels spread
Their white wings above me,
Watching round my bed.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0052', 'verse', 1, 0, '[\"Now the day is over;\",\"Night is drawing nigh,\",\"Shadows of the evening\",\"Steal across the sky.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0052', 'verse', 2, 1, '[\"Father, give the weary\",\"Calm and sweet repose;\",\"With your tenderest blessing\",\"May our eyelids close.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0052', 'verse', 3, 2, '[\"Through the long night-watches,\",\"May your angels spread\",\"Their white wings above me,\",\"Watching round my bed.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0053', 53, 'All Praise to Thee', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'All praise to Thee, my God, this night,
For all the blessings of the light!
Keep me, O keep me, King of kings,
Beneath Thine own almighty wings.
Forgive me, Lord, for Thy dear Son,
The ill that I this day have done,
That with the world, myself, and Thee,
I, ere I sleep, at peace may be.
O may my soul on Thee repose;
And with sweet sleep mine eyelids close,
Sleep, that may me more vigorous make
To serve my God when I awake.
Praise God, from whom all blessings flow;
Praise Him, all creatures here below;
Praise Him above, ye heavenly host;
Praise Father, Son, and Holy Ghost.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0053', 'verse', 1, 0, '[\"All praise to Thee, my God, this night,\",\"For all the blessings of the light!\",\"Keep me, O keep me, King of kings,\",\"Beneath Thine own almighty wings.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0053', 'verse', 2, 1, '[\"Forgive me, Lord, for Thy dear Son,\",\"The ill that I this day have done,\",\"That with the world, myself, and Thee,\",\"I, ere I sleep, at peace may be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0053', 'verse', 3, 2, '[\"O may my soul on Thee repose;\",\"And with sweet sleep mine eyelids close,\",\"Sleep, that may me more vigorous make\",\"To serve my God when I awake.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0053', 'verse', 4, 3, '[\"Praise God, from whom all blessings flow;\",\"Praise Him, all creatures here below;\",\"Praise Him above, ye heavenly host;\",\"Praise Father, Son, and Holy Ghost.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0054', 54, 'O Gladsome Light', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O gladsome light
Of God the Father\'s face,
The eternal splendor wearing;
Celestial, holy, blest,
Our Savior, Jesus Christ,
Joyful in Thine appearing.
Now e\'er day fadeth quite,
We see the ev\'ning light,
Our wonted hymn ourpouring;
Father of might unknown,
Thee His incarnate Son,
And Holy Spirit adoring.
To Thee of right belongs
All praise of holy songs,
O Son of God, lifegiver;
Thee therefore, O most high,
The world doth glorify
And shall exalt for ever.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0054', 'verse', 1, 0, '[\"O gladsome light\",\"Of God the Father\'s face,\",\"The eternal splendor wearing;\",\"Celestial, holy, blest,\",\"Our Savior, Jesus Christ,\",\"Joyful in Thine appearing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0054', 'verse', 2, 1, '[\"Now e\'er day fadeth quite,\",\"We see the ev\'ning light,\",\"Our wonted hymn ourpouring;\",\"Father of might unknown,\",\"Thee His incarnate Son,\",\"And Holy Spirit adoring.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0054', 'verse', 3, 2, '[\"To Thee of right belongs\",\"All praise of holy songs,\",\"O Son of God, lifegiver;\",\"Thee therefore, O most high,\",\"The world doth glorify\",\"And shall exalt for ever.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0055', 55, 'Jesus Tender Shepherd Hear Me', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Jesus, tender Shepherd, hear me,
Bless Thy little lamb tonight;
Through the darkness be Thou near me;
Watch my sleep till morning light.
All this day Thy hand has led me,
And I thank Thee for Thy care;
Thou hast clothed me, warmed and fed me;
Listen to my evening prayer.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0055', 'verse', 1, 0, '[\"Jesus, tender Shepherd, hear me,\",\"Bless Thy little lamb tonight;\",\"Through the darkness be Thou near me;\",\"Watch my sleep till morning light.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0055', 'verse', 2, 1, '[\"All this day Thy hand has led me,\",\"And I thank Thee for Thy care;\",\"Thou hast clothed me, warmed and fed me;\",\"Listen to my evening prayer.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0056', 56, 'The Day Thou Gavest', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'The day Thou gavest, Lord, is ended,
The darkness falls at Thy behest;
To Thee our morning hymns ascended,
Thy praise shall hallow now our rest.
We thank Thee that Thy church, unsleeping,
While earth rolls onward into light,
Through all the world her watch is keeping,
And rests not now by day or night.
As o\'er each continent and island
The dawn leads on another day,
The voice of prayer is never silent,
Nor die the strains of praise away.
So be it, Lord; Thy throne shall never,
Like earth\'s proud empires, pass away;
Thy kingdom stands, and grows forever,
Till all Thy creatures own Thy sway.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0056', 'verse', 1, 0, '[\"The day Thou gavest, Lord, is ended,\",\"The darkness falls at Thy behest;\",\"To Thee our morning hymns ascended,\",\"Thy praise shall hallow now our rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0056', 'verse', 2, 1, '[\"We thank Thee that Thy church, unsleeping,\",\"While earth rolls onward into light,\",\"Through all the world her watch is keeping,\",\"And rests not now by day or night.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0056', 'verse', 3, 2, '[\"As o\'er each continent and island\",\"The dawn leads on another day,\",\"The voice of prayer is never silent,\",\"Nor die the strains of praise away.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0056', 'verse', 4, 3, '[\"So be it, Lord; Thy throne shall never,\",\"Like earth\'s proud empires, pass away;\",\"Thy kingdom stands, and grows forever,\",\"Till all Thy creatures own Thy sway.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0057', 57, 'Now All the Woods Are Sleeping', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Now all the woods are sleeping,
And night and stillness creeping
O\'er city, man, and beast;
But thou, my heart, awake thee,
To pray\'r awhile betake thee,
And praise thy Maker ere thou rest.
My Jesus, stay Thou by me,
And let no foe come nigh me,
Safe sheltered by Thy wing;
But would the foe alarm me,
O let him never harm me,
But still Thine angels round me sing!
My loved ones, rest securely,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0057', 'verse', 1, 0, '[\"Now all the woods are sleeping,\",\"And night and stillness creeping\",\"O\'er city, man, and beast;\",\"But thou, my heart, awake thee,\",\"To pray\'r awhile betake thee,\",\"And praise thy Maker ere thou rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0057', 'verse', 2, 1, '[\"My Jesus, stay Thou by me,\",\"And let no foe come nigh me,\",\"Safe sheltered by Thy wing;\",\"But would the foe alarm me,\",\"O let him never harm me,\",\"But still Thine angels round me sing!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0057', 'verse', 3, 2, '[\"My loved ones, rest securely,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0058', 58, 'Hark the Vesper Hymn Is Stealing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Hark! the vesper hymn is stealing
O\'er the waters soft and clear;
Jubilate, Jubilate, Jubilate, Amen.
Nearer yet, and nearer pealing,
Soft it breaks upon the ear.
Jubilate, Jubilate, Jubilate, Amen.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0058', 'verse', 1, 0, '[\"Hark! the vesper hymn is stealing\",\"O\'er the waters soft and clear;\",\"Jubilate, Jubilate, Jubilate, Amen.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0058', 'verse', 2, 1, '[\"Nearer yet, and nearer pealing,\",\"Soft it breaks upon the ear.\",\"Jubilate, Jubilate, Jubilate, Amen.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0059', 59, 'Great Our Joy As Now We Gather', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Great our joy as now we gather
Where the Master makes us one:
Where we worship God the Father
Thro\' the Spirit of His Son.
All who search for His church
Find it where His will is done.
Precious is the tie that binds us
To our God when faith grows cold;
Precious all that now reminds us
He is still our safe stronghold.
Faithful love serves to prove
Here the Shepherd has His fold.
May we learn from Christ\'s example
How to use this house of prayer:
He who loved and cleansed His temple
Wants us all to worship there.
God the Son shuts out none:
In His Kingdom all may share.
Lord, inspire us with Your vision
Of a world which must be won!
Glorious is the church\'s mission,
Long endeavored, scarce begun!
Faithful now- this is how
God\'s eternal will is done.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0059', 'verse', 1, 0, '[\"Great our joy as now we gather\",\"Where the Master makes us one:\",\"Where we worship God the Father\",\"Thro\' the Spirit of His Son.\",\"All who search for His church\",\"Find it where His will is done.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0059', 'verse', 2, 1, '[\"Precious is the tie that binds us\",\"To our God when faith grows cold;\",\"Precious all that now reminds us\",\"He is still our safe stronghold.\",\"Faithful love serves to prove\",\"Here the Shepherd has His fold.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0059', 'verse', 3, 2, '[\"May we learn from Christ\'s example\",\"How to use this house of prayer:\",\"He who loved and cleansed His temple\",\"Wants us all to worship there.\",\"God the Son shuts out none:\",\"In His Kingdom all may share.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0059', 'verse', 4, 3, '[\"Lord, inspire us with Your vision\",\"Of a world which must be won!\",\"Glorious is the church\'s mission,\",\"Long endeavored, scarce begun!\",\"Faithful now- this is how\",\"God\'s eternal will is done.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0060', 60, 'Blessed Jesus, at Thy Word', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Blessed Jesus, at Thy word
We are gathered all to hear Thee;
Let our hearts and souls be stirred
Now to seek and love and fear Thee;
By Thy teachings sweet and holy,
Drawn from earth to love Thee solely.
All our knowledge, sense, and sight
Lie in deepest darkness shrouded,
Till Thy Spirit breaks our night
With the beams of truth unclouded.
Thou alone to God canst win us;
Thou must work all good within us.
Glorious Lord, Thyself impart!
Light of light, from God proceeding,
Open Thou our ears and heart,
Help us by Thy Spirit\'s pleading,
Hear the cry Thy people raises,
Hear, and bless our prayers and praises.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0060', 'verse', 1, 0, '[\"Blessed Jesus, at Thy word\",\"We are gathered all to hear Thee;\",\"Let our hearts and souls be stirred\",\"Now to seek and love and fear Thee;\",\"By Thy teachings sweet and holy,\",\"Drawn from earth to love Thee solely.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0060', 'verse', 2, 1, '[\"All our knowledge, sense, and sight\",\"Lie in deepest darkness shrouded,\",\"Till Thy Spirit breaks our night\",\"With the beams of truth unclouded.\",\"Thou alone to God canst win us;\",\"Thou must work all good within us.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0060', 'verse', 3, 2, '[\"Glorious Lord, Thyself impart!\",\"Light of light, from God proceeding,\",\"Open Thou our ears and heart,\",\"Help us by Thy Spirit\'s pleading,\",\"Hear the cry Thy people raises,\",\"Hear, and bless our prayers and praises.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0061', 61, 'God Is Here', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'God is here! As we His people
Meet to offer praise and prayer,
May we find in fuller measure
What it is in Christ we share.
Here, as in the world around us,
All our varied skills and arts
Wait the coming of the Spirit
Into open minds and hearts.
Here are symbols to remind us
Of our lifelong need of grace;
Here are table, font, and pulpit;
Here the Word has central place.
Here in honesty of preaching,
Here in silence, as in speech,
Here, in newness and renewal,
God the Spirit comes to each.
Here our children find a welcome
In the Shepherd\'s flock and fold,
Here, as bread and wine are taken
Christ sustains us as of old.
Here the servants of the Servant
Seek in worship to explore
What it means in daily living
To believe and to adore.
Lord of all, of church and kingdom,
In age of change and doubt
Keep us faithful to the gospel,
Help us work Your purpose out.
Here, in this day\'s dedication,
All we have to give, receive,
We, who cannot live without You,
We adore You! we believe!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0061', 'verse', 1, 0, '[\"God is here! As we His people\",\"Meet to offer praise and prayer,\",\"May we find in fuller measure\",\"What it is in Christ we share.\",\"Here, as in the world around us,\",\"All our varied skills and arts\",\"Wait the coming of the Spirit\",\"Into open minds and hearts.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0061', 'verse', 2, 1, '[\"Here are symbols to remind us\",\"Of our lifelong need of grace;\",\"Here are table, font, and pulpit;\",\"Here the Word has central place.\",\"Here in honesty of preaching,\",\"Here in silence, as in speech,\",\"Here, in newness and renewal,\",\"God the Spirit comes to each.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0061', 'verse', 3, 2, '[\"Here our children find a welcome\",\"In the Shepherd\'s flock and fold,\",\"Here, as bread and wine are taken\",\"Christ sustains us as of old.\",\"Here the servants of the Servant\",\"Seek in worship to explore\",\"What it means in daily living\",\"To believe and to adore.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0061', 'verse', 4, 3, '[\"Lord of all, of church and kingdom,\",\"In age of change and doubt\",\"Keep us faithful to the gospel,\",\"Help us work Your purpose out.\",\"Here, in this day\'s dedication,\",\"All we have to give, receive,\",\"We, who cannot live without You,\",\"We adore You! we believe!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0062', 62, 'How Lovely Is Thy Dwelling Place', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'How lovely is Thy dwelling place,
O Lord of hosts to me!
The tabernacles of Thy grace
How pleasant, Lord, they be!
My thirsty soul longs ardently,
Yea, faints Thy courts to see;
My very heart and flesh cry out,
O living God, for Thee.
Behold the sparrow findeth out
A house wherein to rest;
The swallow also, for herself
Provided hath a nest.
Ev\'n Thine own altars, where she safe
Her young ones forth may bring,
O Thou, almighty Lord of hosts,
Who art my God and King.
Hest are they in Thy house that dwell,
They ever give Thee praise.
Blest is the man whose strength Thou art,
In whose heart are Thy ways.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0062', 'verse', 1, 0, '[\"How lovely is Thy dwelling place,\",\"O Lord of hosts to me!\",\"The tabernacles of Thy grace\",\"How pleasant, Lord, they be!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0062', 'verse', 2, 1, '[\"My thirsty soul longs ardently,\",\"Yea, faints Thy courts to see;\",\"My very heart and flesh cry out,\",\"O living God, for Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0062', 'verse', 3, 2, '[\"Behold the sparrow findeth out\",\"A house wherein to rest;\",\"The swallow also, for herself\",\"Provided hath a nest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0062', 'verse', 4, 3, '[\"Ev\'n Thine own altars, where she safe\",\"Her young ones forth may bring,\",\"O Thou, almighty Lord of hosts,\",\"Who art my God and King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0062', 'verse', 5, 4, '[\"Hest are they in Thy house that dwell,\",\"They ever give Thee praise.\",\"Blest is the man whose strength Thou art,\",\"In whose heart are Thy ways.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0063', 63, 'O Come, Let Us Sing to the Lord', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O come, let us sing to the Lord,
Come let us every one
A joyful noise make to the Rock
Of our salvation.
Let us before His presence come
With glad and thankful voice;
Let us sing psalms of praise to Him,
And make a joyful noise.
For God, a great God and great King,
Above all gods, He is;
The depths of earth are in His hand,
The strength of hills is His.
To Him the ocean vast belongs,
For He the sea did make;
The dry land also from His hands,
Its form at first did take.
O come, bow down and worship Him,
And kneeling, humbly pray,
Come to our Maker and our God,
And hear His voice today.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0063', 'verse', 1, 0, '[\"O come, let us sing to the Lord,\",\"Come let us every one\",\"A joyful noise make to the Rock\",\"Of our salvation.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0063', 'verse', 2, 1, '[\"Let us before His presence come\",\"With glad and thankful voice;\",\"Let us sing psalms of praise to Him,\",\"And make a joyful noise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0063', 'verse', 3, 2, '[\"For God, a great God and great King,\",\"Above all gods, He is;\",\"The depths of earth are in His hand,\",\"The strength of hills is His.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0063', 'verse', 4, 3, '[\"To Him the ocean vast belongs,\",\"For He the sea did make;\",\"The dry land also from His hands,\",\"Its form at first did take.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0063', 'verse', 5, 4, '[\"O come, bow down and worship Him,\",\"And kneeling, humbly pray,\",\"Come to our Maker and our God,\",\"And hear His voice today.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0064', 64, 'Lord, Dismiss Us With Thy Blessing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lord, dismiss us with Thy blessing;
Fill our hearts with joy and peace;
Let us each, Thy love possessing,
Triumph in redeeming grace.
O refresh us, O refresh us,
Traveling through this wilderness.
Thanks we give, and adoration,
For Thy gospel\'s joyful sound.
May the fruits of Thy salvation
In our hearts and lives abound.
Ever faithful, ever faithful
To the truth may we be found.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0064', 'verse', 1, 0, '[\"Lord, dismiss us with Thy blessing;\",\"Fill our hearts with joy and peace;\",\"Let us each, Thy love possessing,\",\"Triumph in redeeming grace.\",\"O refresh us, O refresh us,\",\"Traveling through this wilderness.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0064', 'verse', 2, 1, '[\"Thanks we give, and adoration,\",\"For Thy gospel\'s joyful sound.\",\"May the fruits of Thy salvation\",\"In our hearts and lives abound.\",\"Ever faithful, ever faithful\",\"To the truth may we be found.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0065', 65, 'God Be With You', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'God be with you till we meet again;
By His counsels guide, uphold you,
With His sheep securely fold you;
God be with you till we meet again.
Till we meet, till we meet,
Till we meet at Jesus\' feet,
Till we meet, till we meet,
God be with you till we meet again.
God be with you till we meet again;
\'Neath His wings protecting hide you,
Daily manna still provide you;
God be with you till we meet again.
God be with you till we meet again;
When life\'s perils thick confound you,
Put His arms unfailing round you;
God be with you till we meet again.
God be with you till we meet again;
Keep love\'s banner floating o\'er you,
Smite death\'s threatening wave before you;
God be with you till we meet again.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0065', 'verse', 1, 0, '[\"God be with you till we meet again;\",\"By His counsels guide, uphold you,\",\"With His sheep securely fold you;\",\"God be with you till we meet again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0065', 'chorus', 0, 1, '[\"Till we meet, till we meet,\",\"Till we meet at Jesus\' feet,\",\"Till we meet, till we meet,\",\"God be with you till we meet again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0065', 'verse', 2, 2, '[\"God be with you till we meet again;\",\"\'Neath His wings protecting hide you,\",\"Daily manna still provide you;\",\"God be with you till we meet again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0065', 'verse', 3, 3, '[\"God be with you till we meet again;\",\"When life\'s perils thick confound you,\",\"Put His arms unfailing round you;\",\"God be with you till we meet again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0065', 'verse', 4, 4, '[\"God be with you till we meet again;\",\"Keep love\'s banner floating o\'er you,\",\"Smite death\'s threatening wave before you;\",\"God be with you till we meet again.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0066', 66, 'God Be With You', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'God be with you till we meet again;
By His counsels guide, uphold you,
With His sheep securely fold you:
God be with you till we meet again.
God be with you till we meet again;
Neath His wings securely hide you,
Daily manna still provide you:
God be with you till we meet again.
God be with you till we meet again;
When life\'s perils thick confound you,
