INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0066', 'verse', 1, 0, '[\"God be with you till we meet again;\",\"By His counsels guide, uphold you,\",\"With His sheep securely fold you:\",\"God be with you till we meet again.\"]');
