INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0150', 'verse', 3, 3, '[\"Who is He, the gathering throng\",\"Greet with loud triumphant song?\",\"\'Tis the Lord, O wondrous story,\",\"\'Tis the Lord, the King of glory!\"]');
