INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0221', 221, 'Rejoice, the Lord Is King', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Rejoice, the Lord is King!
Your Lord and King adore!
Rejoice, give thanks, and sing,
And triumph evermore:
Lift up your heart, lift up your voice!
Rejoice, again I say, rejoice!
Jesus, the Savior, reigns,
The God of truth and love;
When He had purged our stains,
He took His seat above:
Lift up your heart, lift up your voice!
Rejoice, again I say, rejoice!
His kingdom cannot fail,
He rules o\'er earth and heaven;
The keys of death and grave
Are to our Jesus given:
Lift up your heart, lift up your voice!
Rejoice, again I say, rejoice!
Rejoice, in glorious hope!
Our Lord the judge shall come,
And take His servants up
To their eternal home:
Lift up your heart, lift up your voice!
Rejoice, again I say, rejoice!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0221', 'verse', 1, 0, '[\"Rejoice, the Lord is King!\",\"Your Lord and King adore!\",\"Rejoice, give thanks, and sing,\",\"And triumph evermore:\",\"Lift up your heart, lift up your voice!\",\"Rejoice, again I say, rejoice!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0221', 'verse', 2, 1, '[\"Jesus, the Savior, reigns,\",\"The God of truth and love;\",\"When He had purged our stains,\",\"He took His seat above:\",\"Lift up your heart, lift up your voice!\",\"Rejoice, again I say, rejoice!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0221', 'verse', 3, 2, '[\"His kingdom cannot fail,\",\"He rules o\'er earth and heaven;\",\"The keys of death and grave\",\"Are to our Jesus given:\",\"Lift up your heart, lift up your voice!\",\"Rejoice, again I say, rejoice!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0221', 'verse', 4, 3, '[\"Rejoice, in glorious hope!\",\"Our Lord the judge shall come,\",\"And take His servants up\",\"To their eternal home:\",\"Lift up your heart, lift up your voice!\",\"Rejoice, again I say, rejoice!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0222', 222, 'Hark Ten Thousand Harps and Voices', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Hark! ten thousand harps and voices
Sound the note of praise above;
Jesus reigns, and heaven rejoices,
Jesus reigns, the God of love:
See, He sits on yonder throne;
Jesus rules the world alone.
Alleluia! Alleluia!
Alleluia! Amen.
King of glory, reign forever,
Thine an everlasting crown;
Nothing from Thy love shall sever
Those whom Thou hast made Thine own;
Happy objects of Thy grace,
Destined to behold Thy face.
Alleluia! Alleluia!
Alleluia! Amen.
Savior, hasten Thine appearing;
Bring, O bring the glorious day,
When, the awful summons hearing,
Heaven and earth shall pass away:
Then, with golden harps we\'ll sing,
\"Glory, glory to our King!\"
Alleluia! Alleluia!
Alleluia! Amen.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0222', 'verse', 1, 0, '[\"Hark! ten thousand harps and voices\",\"Sound the note of praise above;\",\"Jesus reigns, and heaven rejoices,\",\"Jesus reigns, the God of love:\",\"See, He sits on yonder throne;\",\"Jesus rules the world alone.\",\"Alleluia! Alleluia!\",\"Alleluia! Amen.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0222', 'verse', 2, 1, '[\"King of glory, reign forever,\",\"Thine an everlasting crown;\",\"Nothing from Thy love shall sever\",\"Those whom Thou hast made Thine own;\",\"Happy objects of Thy grace,\",\"Destined to behold Thy face.\",\"Alleluia! Alleluia!\",\"Alleluia! Amen.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0222', 'verse', 3, 2, '[\"Savior, hasten Thine appearing;\",\"Bring, O bring the glorious day,\",\"When, the awful summons hearing,\",\"Heaven and earth shall pass away:\",\"Then, with golden harps we\'ll sing,\",\"\\\"Glory, glory to our King!\\\"\",\"Alleluia! Alleluia!\",\"Alleluia! Amen.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0223', 223, 'Crown Him With Many Crowns', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Crown Him with many crowns,
The Lamb upon His throne;
Hark! how the heavenly anthem drowns
All music but its own!
Awake, my soul, and sing
Of Him who died for thee;
And hail Him as thy matchless King
Through all eternity.
Crown Him the Lord of love!
Behold His hands and side,
Those wounds, yet visible above,
In beauty glorified;
No angel in the sky
Can fully bear that sight,
But downward bends his wondering eye
At mysteries so great.
Crown Him the Lord of peace!
Whose hand a scepter sways');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0223', 'verse', 1, 0, '[\"Crown Him with many crowns,\",\"The Lamb upon His throne;\",\"Hark! how the heavenly anthem drowns\",\"All music but its own!\",\"Awake, my soul, and sing\",\"Of Him who died for thee;\",\"And hail Him as thy matchless King\",\"Through all eternity.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0223', 'verse', 2, 1, '[\"Crown Him the Lord of love!\",\"Behold His hands and side,\",\"Those wounds, yet visible above,\",\"In beauty glorified;\",\"No angel in the sky\",\"Can fully bear that sight,\",\"But downward bends his wondering eye\",\"At mysteries so great.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0223', 'verse', 3, 2, '[\"Crown Him the Lord of peace!\",\"Whose hand a scepter sways\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0224', 224, 'Seek Ye First the Kingdom', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Seek ye first the kingdom, \'Tis your Father\'s will.
So the voice of Jesus bids us follow still.
Savior, we would hear Thee, Follow, find, and see;
And in life\'s adventure Thy disciples be.
As for hidden treasure, Or for matchless pearl,
When at last discovered, some will sell their all:
So, when breaks the vision of that kingdom fair,
Ours shall be its riches and its beauty rare.
As the silent leaven works its secret way,
Or as grows the seed grain through the night and day;
Lord, so be the increase, peaceable but sure,
Of Thy word within us, And Thy kingdom\'s power.
As the tender seedling grows up tall and strong,
And the birds of heaven to its branches throng;
So shall all God\'s children, from the east and west,
Gather to His kingdom, In its shadow rest.
Humblest shall be greatest, poor in spirit reign;
Home shall come the childlike, born through Thee again
Eager hearts arrive there on the pilgrim\'s road,
Hail! the kingdom glorious of the living God!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0224', 'verse', 1, 0, '[\"Seek ye first the kingdom, \'Tis your Father\'s will.\",\"So the voice of Jesus bids us follow still.\",\"Savior, we would hear Thee, Follow, find, and see;\",\"And in life\'s adventure Thy disciples be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0224', 'verse', 2, 1, '[\"As for hidden treasure, Or for matchless pearl,\",\"When at last discovered, some will sell their all:\",\"So, when breaks the vision of that kingdom fair,\",\"Ours shall be its riches and its beauty rare.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0224', 'verse', 3, 2, '[\"As the silent leaven works its secret way,\",\"Or as grows the seed grain through the night and day;\",\"Lord, so be the increase, peaceable but sure,\",\"Of Thy word within us, And Thy kingdom\'s power.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0224', 'verse', 4, 3, '[\"As the tender seedling grows up tall and strong,\",\"And the birds of heaven to its branches throng;\",\"So shall all God\'s children, from the east and west,\",\"Gather to His kingdom, In its shadow rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0224', 'verse', 5, 4, '[\"Humblest shall be greatest, poor in spirit reign;\",\"Home shall come the childlike, born through Thee again\",\"Eager hearts arrive there on the pilgrim\'s road,\",\"Hail! the kingdom glorious of the living God!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0225', 225, 'God Is Working His Purpose Out', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'God is working His purpose out
As year suceeds to year;
God is working His purpose out,
And the time is drawing near;
Nearer and nearer draws the time,
The time that shall surely be
When the earth shall be filled with the glory of God
As the waters cover the sea.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0225', 'verse', 1, 0, '[\"God is working His purpose out\",\"As year suceeds to year;\",\"God is working His purpose out,\",\"And the time is drawing near;\",\"Nearer and nearer draws the time,\",\"The time that shall surely be\",\"When the earth shall be filled with the glory of God\",\"As the waters cover the sea.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0226', 226, 'Lift Up Your Heads', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lift up your heads, ye mighty gates!
Behold the King of glory waits;
The King of kings is drawing near,
The Savior of the world is here.
The Lord is just, a helper tried;
Mercy is ever at His side;
His kingly crown is holiness,
His scepter, pity in distress.
O blest the land, the city blest,
Where Christ the Ruler is confessed!
O happy hearts and happy homes
To whom this King in triumph comes!
Fling wide the portals of your heart;
Make it a temple, set apart');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0226', 'verse', 1, 0, '[\"Lift up your heads, ye mighty gates!\",\"Behold the King of glory waits;\",\"The King of kings is drawing near,\",\"The Savior of the world is here.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0226', 'verse', 2, 1, '[\"The Lord is just, a helper tried;\",\"Mercy is ever at His side;\",\"His kingly crown is holiness,\",\"His scepter, pity in distress.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0226', 'verse', 3, 2, '[\"O blest the land, the city blest,\",\"Where Christ the Ruler is confessed!\",\"O happy hearts and happy homes\",\"To whom this King in triumph comes!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0226', 'verse', 4, 3, '[\"Fling wide the portals of your heart;\",\"Make it a temple, set apart\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0227', 227, 'Jesus Shall Reign', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Jesus shall reign where e\'r the sun
Does its successive journeys run;
His kingdom stretch from shore to shore,
Till moons shall wax and wane no more.
People and realms of every tongue
Dwell on His love with sweetest song;
And infant voices shall proclaim
Their earthly blessings on His name.
Blessings abound where e\'r He reigns:
The pris\'ners leap to lose their chains,
The weary find eternal rest,
And all who suffer want are blest.
Let every creature rise and bring
Honors peculiar to our King;
Angels descend with songs again,
And earth repeat the loud amen.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0227', 'verse', 1, 0, '[\"Jesus shall reign where e\'r the sun\",\"Does its successive journeys run;\",\"His kingdom stretch from shore to shore,\",\"Till moons shall wax and wane no more.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0227', 'verse', 2, 1, '[\"People and realms of every tongue\",\"Dwell on His love with sweetest song;\",\"And infant voices shall proclaim\",\"Their earthly blessings on His name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0227', 'verse', 3, 2, '[\"Blessings abound where e\'r He reigns:\",\"The pris\'ners leap to lose their chains,\",\"The weary find eternal rest,\",\"And all who suffer want are blest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0227', 'verse', 4, 3, '[\"Let every creature rise and bring\",\"Honors peculiar to our King;\",\"Angels descend with songs again,\",\"And earth repeat the loud amen.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0228', 228, 'A Hymn of Glory Let Us Sing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'A hymn of glory let us sing;
New hymns thro\'out the world shall ring
Alleluia! Alleluia!
Christ, by a road before untrod,
Ascends unto the throne of God.
Alleluia! Alleluia!
Alleluia, alleluia, alleluia!
O Lord, our homeward pathway bend,
That our unwearied hearts ascend.
Alleluia! Alleluia!
Where, seated on Your Father\'s throne,
You reign as King of kings alone.
Alleluia! Alleluia!
Alleluia, alleluia, alleluia!
Give us Your joy on earth, O Lord,
In heav\'n to be our great reward.
Alleluia! Alleluia!
When throned with You forever, we
Shall praise Your name eternally.
Alleluia! Alleluia!
Alleluia, alleluia, alleluia!
O risen Christ, ascended Lord,
All praise to You let earth accord:
Alleluia! Alleluia!
You are, while endless ages run,
With Father and with Spirit one.
Alleluia! Alleluia!
Alleluia, alleluia, alleluia!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0228', 'verse', 1, 0, '[\"A hymn of glory let us sing;\",\"New hymns thro\'out the world shall ring\",\"Alleluia! Alleluia!\",\"Christ, by a road before untrod,\",\"Ascends unto the throne of God.\",\"Alleluia! Alleluia!\",\"Alleluia, alleluia, alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0228', 'verse', 2, 1, '[\"O Lord, our homeward pathway bend,\",\"That our unwearied hearts ascend.\",\"Alleluia! Alleluia!\",\"Where, seated on Your Father\'s throne,\",\"You reign as King of kings alone.\",\"Alleluia! Alleluia!\",\"Alleluia, alleluia, alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0228', 'verse', 3, 2, '[\"Give us Your joy on earth, O Lord,\",\"In heav\'n to be our great reward.\",\"Alleluia! Alleluia!\",\"When throned with You forever, we\",\"Shall praise Your name eternally.\",\"Alleluia! Alleluia!\",\"Alleluia, alleluia, alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0228', 'verse', 4, 3, '[\"O risen Christ, ascended Lord,\",\"All praise to You let earth accord:\",\"Alleluia! Alleluia!\",\"You are, while endless ages run,\",\"With Father and with Spirit one.\",\"Alleluia! Alleluia!\",\"Alleluia, alleluia, alleluia!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0229', 229, 'All Hail the Power of Jesus\' Name', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'All hail the power of Jesus\' name!
Let angels prostrate fall;
Bring forth the royal diadem,
And crown Him Lord of all!
Bring forth the royal diadem,
And crown Him Lord of all.
Ye seed of Israel\'s chosen race,
Ye ransomed of the fall,
Hail Him who saves you by His grace,
And crown Him Lord of all!
Hail Him who saves you by His grace,
And crown Him Lord of all.
Let every kindred, every tribe,
On this terrestrial ball,
To Him all majesty ascribe,
And crown Him Lord of all!
To Him all majesty ascribe,
And crown Him Lord of all.
Oh, that with yonder sacred throng
We at His feet may fall,
Join in the everlasting song,
And crown Him Lord of all!
Join in the everlasting song,
And crown Him Lord of all.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0229', 'verse', 1, 0, '[\"All hail the power of Jesus\' name!\",\"Let angels prostrate fall;\",\"Bring forth the royal diadem,\",\"And crown Him Lord of all!\",\"Bring forth the royal diadem,\",\"And crown Him Lord of all.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0229', 'verse', 2, 1, '[\"Ye seed of Israel\'s chosen race,\",\"Ye ransomed of the fall,\",\"Hail Him who saves you by His grace,\",\"And crown Him Lord of all!\",\"Hail Him who saves you by His grace,\",\"And crown Him Lord of all.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0229', 'verse', 3, 2, '[\"Let every kindred, every tribe,\",\"On this terrestrial ball,\",\"To Him all majesty ascribe,\",\"And crown Him Lord of all!\",\"To Him all majesty ascribe,\",\"And crown Him Lord of all.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0229', 'verse', 4, 3, '[\"Oh, that with yonder sacred throng\",\"We at His feet may fall,\",\"Join in the everlasting song,\",\"And crown Him Lord of all!\",\"Join in the everlasting song,\",\"And crown Him Lord of all.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0230', 230, 'All Glory, Laud, and Honor', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'All glory, laud, and honor
To Thee, Redeemer, King,
To whom the lips of children
Made sweet hosannas ring.
Thou art the King of Israel,
Thou, David\'s royal Son,
Who in the Lord\'s name comest,
The King and Blessed One.
The company of angels
Are praising Thee on high,
And mortal men and all things
Created make reply.
The people of the Hebrews
With palms before Thee went;
Our praise and prayer and anthems
Before Thee we present.
To Thee, before Thy passion,
They sang their hymns of praise;
To Thee, now high exalted,
Our melody we raise.
Thou didst accept their praises;
Accept the praise we bring,
Who in all good delightest,
Thou good and gracious King.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0230', 'verse', 1, 0, '[\"All glory, laud, and honor\",\"To Thee, Redeemer, King,\",\"To whom the lips of children\",\"Made sweet hosannas ring.\",\"Thou art the King of Israel,\",\"Thou, David\'s royal Son,\",\"Who in the Lord\'s name comest,\",\"The King and Blessed One.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0230', 'verse', 2, 1, '[\"The company of angels\",\"Are praising Thee on high,\",\"And mortal men and all things\",\"Created make reply.\",\"The people of the Hebrews\",\"With palms before Thee went;\",\"Our praise and prayer and anthems\",\"Before Thee we present.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0230', 'verse', 3, 2, '[\"To Thee, before Thy passion,\",\"They sang their hymns of praise;\",\"To Thee, now high exalted,\",\"Our melody we raise.\",\"Thou didst accept their praises;\",\"Accept the praise we bring,\",\"Who in all good delightest,\",\"Thou good and gracious King.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0231', 231, 'Bless Be the King', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Bless be the King whose coming
Is in the name of God!
For Him let doors be opened,
No hearts against Him barred!
Not robed in royal splendor,
In power and pomp comes He;
But clad as are the poorest,
Such His humility.
Bless be the King whose coming
Is in the name of God!
By those who truly listen
His voice is truly heard;
Pity the proud and haughty
Who have not learned to heed
The Christ who is the promise,
Who has atonement made.
Bless be the King whose coming
Is in the name of God!
He only to the humble
Reveals the face of God
All power is His, all glory!
All things are in His hand,
All ages and all peoples,
Till time itself shall end.
Bless be the King whose coming
Is in the name of God!
He offers to the burdened
The rest and grace they need.
Gentle is He and humbled!
And light His yoke shall be,
For He would have us bear it
So He can make us free!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0231', 'verse', 1, 0, '[\"Bless be the King whose coming\",\"Is in the name of God!\",\"For Him let doors be opened,\",\"No hearts against Him barred!\",\"Not robed in royal splendor,\",\"In power and pomp comes He;\",\"But clad as are the poorest,\",\"Such His humility.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0231', 'verse', 2, 1, '[\"Bless be the King whose coming\",\"Is in the name of God!\",\"By those who truly listen\",\"His voice is truly heard;\",\"Pity the proud and haughty\",\"Who have not learned to heed\",\"The Christ who is the promise,\",\"Who has atonement made.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0231', 'verse', 3, 2, '[\"Bless be the King whose coming\",\"Is in the name of God!\",\"He only to the humble\",\"Reveals the face of God\",\"All power is His, all glory!\",\"All things are in His hand,\",\"All ages and all peoples,\",\"Till time itself shall end.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0231', 'verse', 4, 3, '[\"Bless be the King whose coming\",\"Is in the name of God!\",\"He offers to the burdened\",\"The rest and grace they need.\",\"Gentle is He and humbled!\",\"And light His yoke shall be,\",\"For He would have us bear it\",\"So He can make us free!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0232', 232, 'At the Name of Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'At the name of Jesus
Every knee shall bow,
Every tongue confess Him
King of glory now;
\'Tis the Father\'s pleasure
We should call Him Lord,
Who from the beginning
Was the mighty Word.
At His voice creation
Sprang at once to sight,
All the angel faces,
All the hosts of light,
Thrones and dominations
Stars upon their way,
All the heavenly orders
In their great array.
Humbled for a season,
To receive a name');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0232', 'verse', 1, 0, '[\"At the name of Jesus\",\"Every knee shall bow,\",\"Every tongue confess Him\",\"King of glory now;\",\"\'Tis the Father\'s pleasure\",\"We should call Him Lord,\",\"Who from the beginning\",\"Was the mighty Word.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0232', 'verse', 2, 1, '[\"At His voice creation\",\"Sprang at once to sight,\",\"All the angel faces,\",\"All the hosts of light,\",\"Thrones and dominations\",\"Stars upon their way,\",\"All the heavenly orders\",\"In their great array.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0232', 'verse', 3, 2, '[\"Humbled for a season,\",\"To receive a name\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0233', 233, 'Christ, Whose Glory Fills the Skies', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Christ, whose glory fills the skies,
Christ, the true, the only light,
Sun of Righteousness, a rise,
Triumph o\'er the shades of night;
Day-spring from on high, be near;
Day-star, in my heart appear.
Dark and cheerless is the morn
Unaccompanied by Thee;
Joyless is the day\'s return
Till Thy mercy\'s beams I see;
Till they inward light impart,
Cheer my eyes and warm my heart.
Visit, then, this soul of mine;
Pierce the gloom of sin and grief;
Fill me, Radiancy divine;
Scatter all my unbelief;
More and more Thyself display,
Shining to the perfect day.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0233', 'verse', 1, 0, '[\"Christ, whose glory fills the skies,\",\"Christ, the true, the only light,\",\"Sun of Righteousness, a rise,\",\"Triumph o\'er the shades of night;\",\"Day-spring from on high, be near;\",\"Day-star, in my heart appear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0233', 'verse', 2, 1, '[\"Dark and cheerless is the morn\",\"Unaccompanied by Thee;\",\"Joyless is the day\'s return\",\"Till Thy mercy\'s beams I see;\",\"Till they inward light impart,\",\"Cheer my eyes and warm my heart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0233', 'verse', 3, 2, '[\"Visit, then, this soul of mine;\",\"Pierce the gloom of sin and grief;\",\"Fill me, Radiancy divine;\",\"Scatter all my unbelief;\",\"More and more Thyself display,\",\"Shining to the perfect day.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0234', 234, 'Christ Is the Worlds Light', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Christ is the world\'s Light,
He and none other;
Born in our darkness, He became our brother.
If we have seen Him, we have seen the Father:
Glory to God on high!
Christ is the world\'s Peace,
He and none other;
No one can serve Him and despise another.
Who else unites us one in God the Father?
Glory to God on high!
Christ is the world\'s Life,
He and none other;
Sold once for silver, murdered here, our brother,
He who redeems us reigns with God the Father.
Glory to God on high!
Give God the glory,
God and none other;
Give God the glory, Spirit, Son, and Father;
Give God the glory, God in Man my brother;
Glory to God on high!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0234', 'verse', 1, 0, '[\"Christ is the world\'s Light,\",\"He and none other;\",\"Born in our darkness, He became our brother.\",\"If we have seen Him, we have seen the Father:\",\"Glory to God on high!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0234', 'verse', 2, 1, '[\"Christ is the world\'s Peace,\",\"He and none other;\",\"No one can serve Him and despise another.\",\"Who else unites us one in God the Father?\",\"Glory to God on high!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0234', 'verse', 3, 2, '[\"Christ is the world\'s Life,\",\"He and none other;\",\"Sold once for silver, murdered here, our brother,\",\"He who redeems us reigns with God the Father.\",\"Glory to God on high!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0234', 'verse', 4, 3, '[\"Give God the glory,\",\"God and none other;\",\"Give God the glory, Spirit, Son, and Father;\",\"Give God the glory, God in Man my brother;\",\"Glory to God on high!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0235', 235, 'Christ Is Made the Sure Foundation', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Christ is made the sure foundation,
Christ, our head and cornerstone,
Chosen of the Lord and precious,
Binding all the Church in one;
Holy Zion\'s help forever
And our confidence alone.
To this temple where we call You,
Come, O Lord of hosts, and stay;
Come, with all Your loving kindness,
Hear Your people as they pray;
And Your fullest benediction
Shed within these walls today.
Grant, we pray to all Your faithful
All the gifts they ask to gain;
What they gain from You forever
With the blessed to retain;
And hereafter in Your glory
Evermore with You to reign.
Praise and honor to the Father,
Praise and honor to the Son,
Praise and honor to the Spirit,
Ever three and ever one:
One in might and one in glory
While unending ages run!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0235', 'verse', 1, 0, '[\"Christ is made the sure foundation,\",\"Christ, our head and cornerstone,\",\"Chosen of the Lord and precious,\",\"Binding all the Church in one;\",\"Holy Zion\'s help forever\",\"And our confidence alone.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0235', 'verse', 2, 1, '[\"To this temple where we call You,\",\"Come, O Lord of hosts, and stay;\",\"Come, with all Your loving kindness,\",\"Hear Your people as they pray;\",\"And Your fullest benediction\",\"Shed within these walls today.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0235', 'verse', 3, 2, '[\"Grant, we pray to all Your faithful\",\"All the gifts they ask to gain;\",\"What they gain from You forever\",\"With the blessed to retain;\",\"And hereafter in Your glory\",\"Evermore with You to reign.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0235', 'verse', 4, 3, '[\"Praise and honor to the Father,\",\"Praise and honor to the Son,\",\"Praise and honor to the Spirit,\",\"Ever three and ever one:\",\"One in might and one in glory\",\"While unending ages run!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0236', 236, 'I Love Thee', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I love Thee, I love Thee, I love Thee, my Lord;
I love Thee, my Savior, I love Thee, my God.
I love Thee, I love Thee, and that Thou dost know;
But how much I love Thee my actions will show.
I\'m happy, I\'m happy, O, wondrous account!
My joys are immortal, I stand on the mount!
I gaze on my treasure and long to be there,
With Jesus and angels, and kindred so dear.
O Jesus, my Savior, with Thee I am blest,
My life and salvation, my joy and my rest:
Thy name be my theme, and Thy love be my song;
Thy grace shall inspire both my heart and my tongue.
O, who\'s like my Savior? He\'s Salem\'s bright King;
He smiles, and He loves me, and helps me to sing.
I\'ll praise Him, I\'ll praise Him, with notes loud and clear,
While rivers of pleasure my spirit do cheer.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0236', 'verse', 1, 0, '[\"I love Thee, I love Thee, I love Thee, my Lord;\",\"I love Thee, my Savior, I love Thee, my God.\",\"I love Thee, I love Thee, and that Thou dost know;\",\"But how much I love Thee my actions will show.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0236', 'verse', 2, 1, '[\"I\'m happy, I\'m happy, O, wondrous account!\",\"My joys are immortal, I stand on the mount!\",\"I gaze on my treasure and long to be there,\",\"With Jesus and angels, and kindred so dear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0236', 'verse', 3, 2, '[\"O Jesus, my Savior, with Thee I am blest,\",\"My life and salvation, my joy and my rest:\",\"Thy name be my theme, and Thy love be my song;\",\"Thy grace shall inspire both my heart and my tongue.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0236', 'verse', 4, 3, '[\"O, who\'s like my Savior? He\'s Salem\'s bright King;\",\"He smiles, and He loves me, and helps me to sing.\",\"I\'ll praise Him, I\'ll praise Him, with notes loud and clear,\",\"While rivers of pleasure my spirit do cheer.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0237', 237, 'In the Cross of Christ I Glory', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'In the cross of Christ I glory,
Towering o\'er the wrecks of time;
All the light of sacred story
Gathers round its head sublime.
When the woes of life o\'ertake me,
Hopes deceive, and fears annoy,
Never shall the cross forsake me;
Lo! it glows with peace and joy.
When the sun of bliss is beaming
Light and love upon my way,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0237', 'verse', 1, 0, '[\"In the cross of Christ I glory,\",\"Towering o\'er the wrecks of time;\",\"All the light of sacred story\",\"Gathers round its head sublime.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0237', 'verse', 2, 1, '[\"When the woes of life o\'ertake me,\",\"Hopes deceive, and fears annoy,\",\"Never shall the cross forsake me;\",\"Lo! it glows with peace and joy.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0237', 'verse', 3, 2, '[\"When the sun of bliss is beaming\",\"Light and love upon my way,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0238', 238, 'How Sweet the Name!', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'How sweet the name of Jesus sounds
In a believer\'s ear!
It soothes his sorrows, heals his wounds,
And drives away his fear.
It makes the wounded spirit whole,
And calms the troubled breast;
Tis manna to the hungry soul,
And to the weary, rest.
Dear name, the rock on which I build,
My shield and hiding place,
My never-failing treasury, filled
With boundless stores of grace.
Jesus! my Shepherd, Guardian, Friend,
My Prophet, Priest, and King.
My Lord, my life, my way, my end!
Accept the praise I bring.
Weak is the effort of my heart,
And cold my warmest thought;
But when I see Thee as Thou art,
I\'ll praise Thee as I ought.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0238', 'verse', 1, 0, '[\"How sweet the name of Jesus sounds\",\"In a believer\'s ear!\",\"It soothes his sorrows, heals his wounds,\",\"And drives away his fear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0238', 'verse', 2, 1, '[\"It makes the wounded spirit whole,\",\"And calms the troubled breast;\",\"Tis manna to the hungry soul,\",\"And to the weary, rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0238', 'verse', 3, 2, '[\"Dear name, the rock on which I build,\",\"My shield and hiding place,\",\"My never-failing treasury, filled\",\"With boundless stores of grace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0238', 'verse', 4, 3, '[\"Jesus! my Shepherd, Guardian, Friend,\",\"My Prophet, Priest, and King.\",\"My Lord, my life, my way, my end!\",\"Accept the praise I bring.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0238', 'verse', 5, 4, '[\"Weak is the effort of my heart,\",\"And cold my warmest thought;\",\"But when I see Thee as Thou art,\",\"I\'ll praise Thee as I ought.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0239', 239, 'Jesus, Priceless Treasure', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Jesus, priceless treasure,
Source of purest pleasure,
Truest Friend to me:
Ah! how long I\'ve panted,
And my heart has fainted,
Thirsting, Lord, for Thee.
Thine I am, O spotless Lamb,
I will suffer naught to hide Thee,
Nought I ask beside Thee.
In Thine arm I rest me;
Foes who would molest me
Cannot reach me here;
Though the earth be shaking,
Every heart be quaking,
Jesus calms my fear;
Sin and hell in conflict fell
With their bitter storms assail me:
Jesus will not fail me.
Hence all fears and sadness!
For the Lord of gladness,
Jesus enters in;
Those who love the Father,
Tho\' the storms may gather,
Still have peace within;
Yea, whate\'er I here must bear,
Still in Thee lies purest pleasure,
Jesus, priceless treasure!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0239', 'verse', 1, 0, '[\"Jesus, priceless treasure,\",\"Source of purest pleasure,\",\"Truest Friend to me:\",\"Ah! how long I\'ve panted,\",\"And my heart has fainted,\",\"Thirsting, Lord, for Thee.\",\"Thine I am, O spotless Lamb,\",\"I will suffer naught to hide Thee,\",\"Nought I ask beside Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0239', 'verse', 2, 1, '[\"In Thine arm I rest me;\",\"Foes who would molest me\",\"Cannot reach me here;\",\"Though the earth be shaking,\",\"Every heart be quaking,\",\"Jesus calms my fear;\",\"Sin and hell in conflict fell\",\"With their bitter storms assail me:\",\"Jesus will not fail me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0239', 'verse', 3, 2, '[\"Hence all fears and sadness!\",\"For the Lord of gladness,\",\"Jesus enters in;\",\"Those who love the Father,\",\"Tho\' the storms may gather,\",\"Still have peace within;\",\"Yea, whate\'er I here must bear,\",\"Still in Thee lies purest pleasure,\",\"Jesus, priceless treasure!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0240', 240, 'Fairest Lord Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Fairest Lord Jesus,
Ruler of all nature,
O Thou of God and man the Son!
Thee will I cherish,
Thee will I honor,
Thou art my glory, joy, and crown.
Fair are the meadows,
Fairer still the woodlands,
Robed in the blooming garb of spring;
Jesus is fairer,
Jesus is purer,
Who makes the woeful heart to sing.
Fair is the sunshine,
Fairer still the moonlight,
And all the twinkling, starry host;
Jesus shines brighter,
Jesus shines purer
Than all the angels heaven can boast.
Beautiful Savior,
Lord of the nations,
Son of God and Son of Man!
Glory and honor,
Praise, adoration,
Now and forevermore be Thine!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0240', 'verse', 1, 0, '[\"Fairest Lord Jesus,\",\"Ruler of all nature,\",\"O Thou of God and man the Son!\",\"Thee will I cherish,\",\"Thee will I honor,\",\"Thou art my glory, joy, and crown.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0240', 'verse', 2, 1, '[\"Fair are the meadows,\",\"Fairer still the woodlands,\",\"Robed in the blooming garb of spring;\",\"Jesus is fairer,\",\"Jesus is purer,\",\"Who makes the woeful heart to sing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0240', 'verse', 3, 2, '[\"Fair is the sunshine,\",\"Fairer still the moonlight,\",\"And all the twinkling, starry host;\",\"Jesus shines brighter,\",\"Jesus shines purer\",\"Than all the angels heaven can boast.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0240', 'verse', 4, 3, '[\"Beautiful Savior,\",\"Lord of the nations,\",\"Son of God and Son of Man!\",\"Glory and honor,\",\"Praise, adoration,\",\"Now and forevermore be Thine!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0241', 241, 'Jesus, the Very Thought of Thee', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Jesus, the very thought of Thee,
With sweetness fills my breast;
But sweeter far Thy face to see,
And in Thy presence rest.
No voice can sing, no heart can frame,
Nor can the memory find
A sweeter sound than Jesus\' name,
The Savior of mankind.
O hope of every contrite heart!
O joy of all the meek,
To those who fall, how kind Thou art!
How good to those who seek!
But what to those who find? Ah! this
Nor tongue nor pen can show:
The love of Jesus; what it is,
None but His loved ones know.
Jesus, our only joy be Thou,
As Thou our prize wilt be;
In Thee be all our glory now,
And through eternity.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0241', 'verse', 1, 0, '[\"Jesus, the very thought of Thee,\",\"With sweetness fills my breast;\",\"But sweeter far Thy face to see,\",\"And in Thy presence rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0241', 'verse', 2, 1, '[\"No voice can sing, no heart can frame,\",\"Nor can the memory find\",\"A sweeter sound than Jesus\' name,\",\"The Savior of mankind.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0241', 'verse', 3, 2, '[\"O hope of every contrite heart!\",\"O joy of all the meek,\",\"To those who fall, how kind Thou art!\",\"How good to those who seek!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0241', 'verse', 4, 3, '[\"But what to those who find? Ah! this\",\"Nor tongue nor pen can show:\",\"The love of Jesus; what it is,\",\"None but His loved ones know.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0241', 'verse', 5, 4, '[\"Jesus, our only joy be Thou,\",\"As Thou our prize wilt be;\",\"In Thee be all our glory now,\",\"And through eternity.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0242', 242, 'Jesus, Thou Joy of Loving Hearts', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Jesus, Thou joy of loving hearts!
Thou fount of life! Thou light of men!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0242', 'verse', 1, 0, '[\"Jesus, Thou joy of loving hearts!\",\"Thou fount of life! Thou light of men!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0243', 243, 'King of Glory, King of Peace', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'King of glory, King of peace,
I will love Thee;
And that love may never cease,
I will move Thee.
Thou hast granted my request,
Thou hast heard me;
Thou didst note my working breast,
Thou hast spared me.
Wherefore with my utmost art
I will sing Thee,
And the cream of all my heart
I will bring Thee.
Though my sins against me cried,
Thou didst clear me;
And alone, when they replied,
Thou didst hear me.
Seven whole days, not one in seven,
I will praise Thee;
In my heart, though not in heav\'n,
I can raise Thee.
Small it is, in this poor sort
To enroll Thee:
Ev\'n eternity\'s too short
To extol Thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0243', 'verse', 1, 0, '[\"King of glory, King of peace,\",\"I will love Thee;\",\"And that love may never cease,\",\"I will move Thee.\",\"Thou hast granted my request,\",\"Thou hast heard me;\",\"Thou didst note my working breast,\",\"Thou hast spared me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0243', 'verse', 2, 1, '[\"Wherefore with my utmost art\",\"I will sing Thee,\",\"And the cream of all my heart\",\"I will bring Thee.\",\"Though my sins against me cried,\",\"Thou didst clear me;\",\"And alone, when they replied,\",\"Thou didst hear me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0243', 'verse', 3, 2, '[\"Seven whole days, not one in seven,\",\"I will praise Thee;\",\"In my heart, though not in heav\'n,\",\"I can raise Thee.\",\"Small it is, in this poor sort\",\"To enroll Thee:\",\"Ev\'n eternity\'s too short\",\"To extol Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0244', 244, 'My Song Shall Be of Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'My song shall be of Jesus,
His mercy crowns my days,
He fills my cup with blessings,
And tunes my heart to praise;
My song shall be of Jesus,
The precious Lamb of God,
Who gave Himself my ransom,
And bought me with His blood.
My song shall be of Jesus,
When sitting at His feet,
I call to mind His goodness
And know my joy\'s complete;
My song shall be of Jesus,
Whatever ills befall,
I\'ll sing the grace that saves me,
And triumphs over all.
My song shall be of Jesus,
While pressing on my way
To where my home shines glorious
In pure and perfect day.
And when my soul shall enter
The many mansions fair,
A song of praise to Jesus
I\'ll sing forever there.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0244', 'verse', 1, 0, '[\"My song shall be of Jesus,\",\"His mercy crowns my days,\",\"He fills my cup with blessings,\",\"And tunes my heart to praise;\",\"My song shall be of Jesus,\",\"The precious Lamb of God,\",\"Who gave Himself my ransom,\",\"And bought me with His blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0244', 'verse', 2, 1, '[\"My song shall be of Jesus,\",\"When sitting at His feet,\",\"I call to mind His goodness\",\"And know my joy\'s complete;\",\"My song shall be of Jesus,\",\"Whatever ills befall,\",\"I\'ll sing the grace that saves me,\",\"And triumphs over all.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0244', 'verse', 3, 2, '[\"My song shall be of Jesus,\",\"While pressing on my way\",\"To where my home shines glorious\",\"In pure and perfect day.\",\"And when my soul shall enter\",\"The many mansions fair,\",\"A song of praise to Jesus\",\"I\'ll sing forever there.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0245', 245, 'More About Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'More about Jesus I would know,
More of His grace to others show;
More of His saving fullness see,
More of His love who died for me.
More, more about Jesus,
More, more about Jesus;
More of His saving fullness see,
More of His love who died for me.
More about Jesus let me learn,
More of His holy will discern;
Spirit of God, my teacher be,
Showing the things of Christ to me.
More about Jesus; in His word,
Holding communion with my Lord,
Hearing His voice in every line,
Making each faithful saying mine.
More about Jesus; on His throne,
Riches in glory all His own;
More of His kingdom\'s sure increase;
More of His coming, Prince of Peace.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0245', 'verse', 1, 0, '[\"More about Jesus I would know,\",\"More of His grace to others show;\",\"More of His saving fullness see,\",\"More of His love who died for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0245', 'chorus', 0, 1, '[\"More, more about Jesus,\",\"More, more about Jesus;\",\"More of His saving fullness see,\",\"More of His love who died for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0245', 'verse', 2, 2, '[\"More about Jesus let me learn,\",\"More of His holy will discern;\",\"Spirit of God, my teacher be,\",\"Showing the things of Christ to me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0245', 'verse', 3, 3, '[\"More about Jesus; in His word,\",\"Holding communion with my Lord,\",\"Hearing His voice in every line,\",\"Making each faithful saying mine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0245', 'verse', 4, 4, '[\"More about Jesus; on His throne,\",\"Riches in glory all His own;\",\"More of His kingdom\'s sure increase;\",\"More of His coming, Prince of Peace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0246', 246, 'Worthy, Worthy Is the Lamb', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Worthy, worthy is the Lamb,
Worthy, worthy is the Lamb;
Worthy, worthy is the Lamb
That was slain.
Glory, hallelujah!
Praise Him, hallelujah!
Glory, hallelujah
To the Lamb!
Savior, let Thy kingdom come!
Now the power of sin consume;
Bring Thy blest millennium,
Holy Lamb.
Thus may we each moment feel,
Love Him, serve Him, praise Him still,
Till we all on Zion\'s hill
See the Lamb.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0246', 'verse', 1, 0, '[\"Worthy, worthy is the Lamb,\",\"Worthy, worthy is the Lamb;\",\"Worthy, worthy is the Lamb\",\"That was slain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0246', 'chorus', 0, 1, '[\"Glory, hallelujah!\",\"Praise Him, hallelujah!\",\"Glory, hallelujah\",\"To the Lamb!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0246', 'verse', 2, 2, '[\"Savior, let Thy kingdom come!\",\"Now the power of sin consume;\",\"Bring Thy blest millennium,\",\"Holy Lamb.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0246', 'verse', 3, 3, '[\"Thus may we each moment feel,\",\"Love Him, serve Him, praise Him still,\",\"Till we all on Zion\'s hill\",\"See the Lamb.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0247', 247, 'Come My Way', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Come, my Way, my Truth, my Life:
Such a Way, as gives us breath;
Such a Truth, as ends all strife;
Such a Life, as killeth death.
Come, my Light, my Feast, my Strength:
Such a Light, as shows a feast;
Such a Feast, as mends in length;
Such a Strength, as makes His guest.
Come, my Joy, my Love, my Heart:
Such a Joy, as none can move;
Such a Love, as none can part;
Such a Heart, as joys in love.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0247', 'verse', 1, 0, '[\"Come, my Way, my Truth, my Life:\",\"Such a Way, as gives us breath;\",\"Such a Truth, as ends all strife;\",\"Such a Life, as killeth death.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0247', 'verse', 2, 1, '[\"Come, my Light, my Feast, my Strength:\",\"Such a Light, as shows a feast;\",\"Such a Feast, as mends in length;\",\"Such a Strength, as makes His guest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0247', 'verse', 3, 2, '[\"Come, my Joy, my Love, my Heart:\",\"Such a Joy, as none can move;\",\"Such a Love, as none can part;\",\"Such a Heart, as joys in love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0248', 248, 'O, How I Love Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'There is a name I love to hear,
I love to sing its worth;
It sounds like music in my ear,
The sweetest name on earth.
O, how I love Jesus,
O, how I love Jesus,
O, how I love Jesus
Because He first loved me!
It tells me of a Savior\'s love,
Who died to set me free;
It tells me of His precious blood,
The sinner\'s perfect plea.
It tells of One whose loving heart
Can feel my deepest woe,
Who in each sorrow bears a part
That none can bear below.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0248', 'verse', 1, 0, '[\"There is a name I love to hear,\",\"I love to sing its worth;\",\"It sounds like music in my ear,\",\"The sweetest name on earth.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0248', 'chorus', 0, 1, '[\"O, how I love Jesus,\",\"O, how I love Jesus,\",\"O, how I love Jesus\",\"Because He first loved me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0248', 'verse', 2, 2, '[\"It tells me of a Savior\'s love,\",\"Who died to set me free;\",\"It tells me of His precious blood,\",\"The sinner\'s perfect plea.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0248', 'verse', 3, 3, '[\"It tells of One whose loving heart\",\"Can feel my deepest woe,\",\"Who in each sorrow bears a part\",\"That none can bear below.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0249', 249, 'Praise Him! Praise Him!', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Praise Him! praise Him! Jesus, our blessed Redeemer!
Sing, O earth; His wonderful love proclaim!
Hail Him! hail Him! highest archangels in glory;
Strength and honor give to His holy name!
Like a shepherd, Jesus will guard His children,
In His arms He carries them all day long;
Praise Him! praise Him! tell of His excellent greatness;
Praise Him! praise Him ever in joyful song!
Praise Him! praise Him! Jesus, our blessed Redeemer!
For our sins He suffered, and bled and died;
He our Rock, our hope of eternal salvation,
Hail Him! hail Him! Jesus, the crucified.
Sound His praises! Jesus who bore our sorrows,
Love unbounded, wonderful, deep and strong;
Praise Him! praise Him! Jesus, our blessed Redeemer!
Heavenly portals, loud with hosannas ring!
Jesus, Savior, reigneth forever and ever;
Crown Him! crown Him! Prophet, and Priest, and King!
Christ is coming over the world victorious,
Power and glory unto the Lord belong;');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0249', 'verse', 1, 0, '[\"Praise Him! praise Him! Jesus, our blessed Redeemer!\",\"Sing, O earth; His wonderful love proclaim!\",\"Hail Him! hail Him! highest archangels in glory;\",\"Strength and honor give to His holy name!\",\"Like a shepherd, Jesus will guard His children,\",\"In His arms He carries them all day long;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0249', 'chorus', 0, 1, '[\"Praise Him! praise Him! tell of His excellent greatness;\",\"Praise Him! praise Him ever in joyful song!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0249', 'verse', 2, 2, '[\"Praise Him! praise Him! Jesus, our blessed Redeemer!\",\"For our sins He suffered, and bled and died;\",\"He our Rock, our hope of eternal salvation,\",\"Hail Him! hail Him! Jesus, the crucified.\",\"Sound His praises! Jesus who bore our sorrows,\",\"Love unbounded, wonderful, deep and strong;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0249', 'verse', 3, 3, '[\"Praise Him! praise Him! Jesus, our blessed Redeemer!\",\"Heavenly portals, loud with hosannas ring!\",\"Jesus, Savior, reigneth forever and ever;\",\"Crown Him! crown Him! Prophet, and Priest, and King!\",\"Christ is coming over the world victorious,\",\"Power and glory unto the Lord belong;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0250', 250, 'O for a Thousand Tongues to Sing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O for a thousand tongues to sing
My great Redeemer\'s praise,
The glories of my God and King,
The triumphs of His grace!
My gracious Master and my God,
Assist me to proclaim
To spread thro\' all the earth abroad
The honors of Thy name.
Jesus! the name that charms our fears,
That bids our sorrows cease,
\'Tis music in the sinners\' ears,
Tis life, and health, and peace.
He breaks the power of canceled sin,
He sets the prisoner free;
His blood can make the foulest clean;
His blood availed for me.
He speaks, and listening to His voice,
New life the dead receive;
The mournful, broken hearts rejoice;
The humble poor, believe.
Hear Him, ye deaf; His praise, ye dumb,
Your loosened tongues employ;
Ye blind, behold your Savior come;
And leap, ye lame, for joy.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0250', 'verse', 1, 0, '[\"O for a thousand tongues to sing\",\"My great Redeemer\'s praise,\",\"The glories of my God and King,\",\"The triumphs of His grace!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0250', 'verse', 2, 1, '[\"My gracious Master and my God,\",\"Assist me to proclaim\",\"To spread thro\' all the earth abroad\",\"The honors of Thy name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0250', 'verse', 3, 2, '[\"Jesus! the name that charms our fears,\",\"That bids our sorrows cease,\",\"\'Tis music in the sinners\' ears,\",\"Tis life, and health, and peace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0250', 'verse', 4, 3, '[\"He breaks the power of canceled sin,\",\"He sets the prisoner free;\",\"His blood can make the foulest clean;\",\"His blood availed for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0250', 'verse', 5, 4, '[\"He speaks, and listening to His voice,\",\"New life the dead receive;\",\"The mournful, broken hearts rejoice;\",\"The humble poor, believe.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0250', 'verse', 6, 5, '[\"Hear Him, ye deaf; His praise, ye dumb,\",\"Your loosened tongues employ;\",\"Ye blind, behold your Savior come;\",\"And leap, ye lame, for joy.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0251', 251, 'He Lives', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I serve a risen Savior, He\'s in the world today;
I know that He is living, whatever men may say;
I see His hand of mercy, I hear His voice of cheer
And just the time I need Him He\'s always near.
He lives, He lives, Christ Jesus lives today!
He walks with me and talks with me
along life\'s narrow way.
He lives, He lives, salvation to impart!
You ask me how I know He lives?
He lives within my heart.
In all the world around me I see His loving care,
And tho\' my heart grows weary I never will despair;
I know that He is leading thru all the stormy blast,
The day of His appearing will come at last.
Rejoice, rejoice, O Christian, lift up your voice and sing,
Eternal hallelujahs to Jesus Christ the King!
The hope of all who seek Him, the help of all who find,
None other is so loving, so good and kind.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0251', 'verse', 1, 0, '[\"I serve a risen Savior, He\'s in the world today;\",\"I know that He is living, whatever men may say;\",\"I see His hand of mercy, I hear His voice of cheer\",\"And just the time I need Him He\'s always near.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0251', 'chorus', 0, 1, '[\"He lives, He lives, Christ Jesus lives today!\",\"He walks with me and talks with me\",\"along life\'s narrow way.\",\"He lives, He lives, salvation to impart!\",\"You ask me how I know He lives?\",\"He lives within my heart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0251', 'verse', 2, 2, '[\"In all the world around me I see His loving care,\",\"And tho\' my heart grows weary I never will despair;\",\"I know that He is leading thru all the stormy blast,\",\"The day of His appearing will come at last.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0251', 'verse', 3, 3, '[\"Rejoice, rejoice, O Christian, lift up your voice and sing,\",\"Eternal hallelujahs to Jesus Christ the King!\",\"The hope of all who seek Him, the help of all who find,\",\"None other is so loving, so good and kind.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0252', 252, 'Come, Let Us Sing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Come, let us sing the song of songs;
The angels first began the strain;
The homage which to Christ belongs:
\"Worthy the Lamb, for He was slain!\"
Slain to redeem us by His blood,
To cleanse from every sinful stain,
And make us kings and priests to God:
\"Worthy the Lamb, for He was slain!\"
To Him who suffered on the tree,
Our souls, at His soul\'s price, to gain,
Blessing, and praise, and glory be:
\"Worthy the Lamb, for He was slain!\"
To Him, enthroned by filial right
All power in heaven and earth proclaim,
Honor, and majesty, and might:
\"Worthy the Lamb, for He was slain!\"
Long as we live, and when we die,
And while in heaven with Him we reign,
This song our song of songs shall be:
\"Worthy the Lamb, for He was slain!\"');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0252', 'verse', 1, 0, '[\"Come, let us sing the song of songs;\",\"The angels first began the strain;\",\"The homage which to Christ belongs:\",\"\\\"Worthy the Lamb, for He was slain!\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0252', 'verse', 2, 1, '[\"Slain to redeem us by His blood,\",\"To cleanse from every sinful stain,\",\"And make us kings and priests to God:\",\"\\\"Worthy the Lamb, for He was slain!\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0252', 'verse', 3, 2, '[\"To Him who suffered on the tree,\",\"Our souls, at His soul\'s price, to gain,\",\"Blessing, and praise, and glory be:\",\"\\\"Worthy the Lamb, for He was slain!\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0252', 'verse', 4, 3, '[\"To Him, enthroned by filial right\",\"All power in heaven and earth proclaim,\",\"Honor, and majesty, and might:\",\"\\\"Worthy the Lamb, for He was slain!\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0252', 'verse', 5, 4, '[\"Long as we live, and when we die,\",\"And while in heaven with Him we reign,\",\"This song our song of songs shall be:\",\"\\\"Worthy the Lamb, for He was slain!\\\"\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0253', 253, 'There\'s No Other Name Like Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'There\'s no other name like Jesus,
\'Tis the dearest name we know,
\'Tis the angel\'s joy in Heaven,
\'Tis the Christian\'s joy below.
Sweet name, dear name,
There\'s no other name like Jesus;
Sweet name, dear name,
There\'s no other name like Jesus.
There\'s no other name like Jesus
When the heart with grief is sad,
There\'s no other name like Jesus
When the heart is free and glad.
\'Tis the hope that I shall see Him
When in glory He appears,
\'Tis the hope to hear His welcome
That my fainting spirit cheers.
If He wills that I should labor
In His vineyard day by day,
Then \'tis well if only Jesus
Blesses all I do or say.
If He wills that death\'s cold finger
Touch my feeble, mortal clay,
Then \'tis well if only Jesus
Is my dying trust and stay.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0253', 'verse', 1, 0, '[\"There\'s no other name like Jesus,\",\"\'Tis the dearest name we know,\",\"\'Tis the angel\'s joy in Heaven,\",\"\'Tis the Christian\'s joy below.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0253', 'chorus', 0, 1, '[\"Sweet name, dear name,\",\"There\'s no other name like Jesus;\",\"Sweet name, dear name,\",\"There\'s no other name like Jesus.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0253', 'verse', 2, 2, '[\"There\'s no other name like Jesus\",\"When the heart with grief is sad,\",\"There\'s no other name like Jesus\",\"When the heart is free and glad.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0253', 'verse', 3, 3, '[\"\'Tis the hope that I shall see Him\",\"When in glory He appears,\",\"\'Tis the hope to hear His welcome\",\"That my fainting spirit cheers.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0253', 'verse', 4, 4, '[\"If He wills that I should labor\",\"In His vineyard day by day,\",\"Then \'tis well if only Jesus\",\"Blesses all I do or say.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0253', 'verse', 5, 5, '[\"If He wills that death\'s cold finger\",\"Touch my feeble, mortal clay,\",\"Then \'tis well if only Jesus\",\"Is my dying trust and stay.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0254', 254, 'The Great Physician Now Is Near', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'The Great Physician now is near,
The sympathizing Jesus;
He speaks, the drooping heart to cheer,
O hear the voice of Jesus!
Sweetest note in seraph song,
Sweetest name on mortal tongue,
Sweetest carol ever sung;
Jesus, blessed Jesus!
All glory to the dying Lamb!
I now believe in Jesus;
I love the blessed Savior\'s name,
I love the name of Jesus.
His name dispels my guilt and fear;
No other name but Jesus;
O how my soul delights to hear
The precious name of Jesus!
And when He comes to bring the crown
The crown of life and glory
Then by His side we will sit down,
And tell redemption\'s story.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0254', 'verse', 1, 0, '[\"The Great Physician now is near,\",\"The sympathizing Jesus;\",\"He speaks, the drooping heart to cheer,\",\"O hear the voice of Jesus!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0254', 'chorus', 0, 1, '[\"Sweetest note in seraph song,\",\"Sweetest name on mortal tongue,\",\"Sweetest carol ever sung;\",\"Jesus, blessed Jesus!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0254', 'verse', 2, 2, '[\"All glory to the dying Lamb!\",\"I now believe in Jesus;\",\"I love the blessed Savior\'s name,\",\"I love the name of Jesus.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0254', 'verse', 3, 3, '[\"His name dispels my guilt and fear;\",\"No other name but Jesus;\",\"O how my soul delights to hear\",\"The precious name of Jesus!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0254', 'verse', 4, 4, '[\"And when He comes to bring the crown\",\"The crown of life and glory\",\"Then by His side we will sit down,\",\"And tell redemption\'s story.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0255', 255, 'I Cannot Tell Why', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I cannot tell why He whom angels worship
Should set His love upon the souls of men,
Or why as Shepherd He should seek the wanderers,
To bring them back, they know not how nor when.
But this I know that He was born of Mary
When Bethlehem\'s manger was His only home,
And that He lived at Nazareth and labored;
And so the Savior, Savior of the world, has come.
I cannot tell how silently He suffered
As with His peace He graced this place of tears,
Nor how His heart upon the cross was broken,
The crown of pain to three and thirty years.
But this I know He heals the broken hearted
And stays our sin and calms our lurking fear,
And lifts the burden from the heavy laden;
For still the Savior, Savior of the world, is here.
I cannot tell how He will win the nations,
How He will claim His earthly heritage,
How satisfy the needs and aspirations
Of east and west, of sinner and of sage.
But this I know all flesh shall see His glory,
And He shall reap the harvest He has sown,
And some glad day His sun will shine in splendor
When He the Savior, Savior of the world, is known.
I cannot tell how all the lands shall worship,
When at His biding every storm is stilled,
Or who can say how great the jubilation
When all our hearts with love for Him are filled.
But this I know the skies shall sound His praises,
Ten thousand thousand human voices sing,
And earth to heaven, and heaven to earth will answer,
At last the Savior, Savior of the world, is King!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0255', 'verse', 1, 0, '[\"I cannot tell why He whom angels worship\",\"Should set His love upon the souls of men,\",\"Or why as Shepherd He should seek the wanderers,\",\"To bring them back, they know not how nor when.\",\"But this I know that He was born of Mary\",\"When Bethlehem\'s manger was His only home,\",\"And that He lived at Nazareth and labored;\",\"And so the Savior, Savior of the world, has come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0255', 'verse', 2, 1, '[\"I cannot tell how silently He suffered\",\"As with His peace He graced this place of tears,\",\"Nor how His heart upon the cross was broken,\",\"The crown of pain to three and thirty years.\",\"But this I know He heals the broken hearted\",\"And stays our sin and calms our lurking fear,\",\"And lifts the burden from the heavy laden;\",\"For still the Savior, Savior of the world, is here.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0255', 'verse', 3, 2, '[\"I cannot tell how He will win the nations,\",\"How He will claim His earthly heritage,\",\"How satisfy the needs and aspirations\",\"Of east and west, of sinner and of sage.\",\"But this I know all flesh shall see His glory,\",\"And He shall reap the harvest He has sown,\",\"And some glad day His sun will shine in splendor\",\"When He the Savior, Savior of the world, is known.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0255', 'verse', 4, 3, '[\"I cannot tell how all the lands shall worship,\",\"When at His biding every storm is stilled,\",\"Or who can say how great the jubilation\",\"When all our hearts with love for Him are filled.\",\"But this I know the skies shall sound His praises,\",\"Ten thousand thousand human voices sing,\",\"And earth to heaven, and heaven to earth will answer,\",\"At last the Savior, Savior of the world, is King!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0256', 256, 'Ye Servants of God', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Ye servants of God, your Master proclaim,
And publish abroad His wonderful name;
The name all victorious of Jesus extol;
His kingdom is glorious, He rules over all.
God ruleth on high, almighty to save;
And still He is nigh His presence we have;
The great congregation His triumph shall sing,
Ascribing salvation to Jesus our King.
\"Salvation to God, Who sits on the throne,\"
Let all cry aloud, and honor the Son;
The praises of Jesus the angels proclaim,
Fall down on their faces, and worship the Lamb.
Then let us adore, and give Him His right,
All glory and power, all wisdom and might,
All honor and blessing, with angels above,
And thanks never ceasing, for infinite love.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0256', 'verse', 1, 0, '[\"Ye servants of God, your Master proclaim,\",\"And publish abroad His wonderful name;\",\"The name all victorious of Jesus extol;\",\"His kingdom is glorious, He rules over all.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0256', 'verse', 2, 1, '[\"God ruleth on high, almighty to save;\",\"And still He is nigh His presence we have;\",\"The great congregation His triumph shall sing,\",\"Ascribing salvation to Jesus our King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0256', 'verse', 3, 2, '[\"\\\"Salvation to God, Who sits on the throne,\\\"\",\"Let all cry aloud, and honor the Son;\",\"The praises of Jesus the angels proclaim,\",\"Fall down on their faces, and worship the Lamb.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0256', 'verse', 4, 3, '[\"Then let us adore, and give Him His right,\",\"All glory and power, all wisdom and might,\",\"All honor and blessing, with angels above,\",\"And thanks never ceasing, for infinite love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0257', 257, 'Come Down, O Love Divine', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Come down, O Love divine,
Seek Thou this soul of mine,
And visit it with Thine own ardor glowing;
O Comforter, draw near,
Within my heart appear,
And kindle it, Thy holy flame bestowing.
O let it freely burn,
Till earthly passions turn
To dust and ashes in its heat consuming;
And let Thy glorious light
Shine ever on my sight,
And clothe me round, the while my path illuming.
Let holy charity
Mine outward vesture be,
And lowliness become my inner clothing;
True lowliness of heart
Which takes the humbler part,
And o\'er its own shortcomings weeps with loathing.
And so the yearning strong,
With which the soul will long,
Shall far outpass the power of human telling;
For none can guess its grace,
Till he become the place
Where in the Holy Spirit makes His dwelling.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0257', 'verse', 1, 0, '[\"Come down, O Love divine,\",\"Seek Thou this soul of mine,\",\"And visit it with Thine own ardor glowing;\",\"O Comforter, draw near,\",\"Within my heart appear,\",\"And kindle it, Thy holy flame bestowing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0257', 'verse', 2, 1, '[\"O let it freely burn,\",\"Till earthly passions turn\",\"To dust and ashes in its heat consuming;\",\"And let Thy glorious light\",\"Shine ever on my sight,\",\"And clothe me round, the while my path illuming.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0257', 'verse', 3, 2, '[\"Let holy charity\",\"Mine outward vesture be,\",\"And lowliness become my inner clothing;\",\"True lowliness of heart\",\"Which takes the humbler part,\",\"And o\'er its own shortcomings weeps with loathing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0257', 'verse', 4, 3, '[\"And so the yearning strong,\",\"With which the soul will long,\",\"Shall far outpass the power of human telling;\",\"For none can guess its grace,\",\"Till he become the place\",\"Where in the Holy Spirit makes His dwelling.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0258', 258, 'Baptize Us Anew', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Baptize us anew
With power from on high,
With love, O refresh us!
Dear Savior, draw nigh.
We humbly beseech Thee, Lord Jesus, we pray,
With love and the Spirit baptize us today.
Unworthy we cry,
Unholy, unclean,
O wash us and cleanse us');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0258', 'verse', 1, 0, '[\"Baptize us anew\",\"With power from on high,\",\"With love, O refresh us!\",\"Dear Savior, draw nigh.\",\"We humbly beseech Thee, Lord Jesus, we pray,\",\"With love and the Spirit baptize us today.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0258', 'verse', 2, 1, '[\"Unworthy we cry,\",\"Unholy, unclean,\",\"O wash us and cleanse us\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0259', 259, 'Draw Us in the Spirits Tether', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Draw us in the Spirit\'s tether,
For when humbly in Thy name,
Two or three are met together,
Thou art in the midst of them;
Alleluia! Alleluia!
Touch we now Thy garment\'s hem.
As the brethren used to gather
In the name of Christ to sup,
Then with thanks to God the Father
Break the bread and bless the cup,
Alleluia! Alleluia!
So knit Thou our friendship up.
All our meals and all our living
Make us sacraments of Thee,
That by caring, helping, giving,
We may true disciples be.
Alleluia! Alleluia!
We will serve Thee faithfully.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0259', 'verse', 1, 0, '[\"Draw us in the Spirit\'s tether,\",\"For when humbly in Thy name,\",\"Two or three are met together,\",\"Thou art in the midst of them;\",\"Alleluia! Alleluia!\",\"Touch we now Thy garment\'s hem.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0259', 'verse', 2, 1, '[\"As the brethren used to gather\",\"In the name of Christ to sup,\",\"Then with thanks to God the Father\",\"Break the bread and bless the cup,\",\"Alleluia! Alleluia!\",\"So knit Thou our friendship up.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0259', 'verse', 3, 2, '[\"All our meals and all our living\",\"Make us sacraments of Thee,\",\"That by caring, helping, giving,\",\"We may true disciples be.\",\"Alleluia! Alleluia!\",\"We will serve Thee faithfully.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0260', 260, 'Hover O\'er Me, Holy Spirit', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Hover o\'er me, Holy Spirit,
Bathe my trembling heart and brow;
Fill me with Thy hallowed presence,
Come, O come and fill me now.
Fill me now, fill me now,
Jesus, come and fill me now.
Fill me with Thy hallowed presence,
Come, O come and fill me now.
Thou canst fill me, gracious Spirit,
Though I cannot tell Thee how;
But I need Thee, greatly need Thee;
Come, O come and fill me now.
I am weakness, full of weakness;
At Thy sacred feet I bow;
Blest, divine, eternal Spirit,
Fill with love, and fill me now.
Cleanse and comfort, bless and save me;
Bathe, O, bathe my heart and brow;
Thou art comforting and saving,
Thou art sweetly filling now.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0260', 'verse', 1, 0, '[\"Hover o\'er me, Holy Spirit,\",\"Bathe my trembling heart and brow;\",\"Fill me with Thy hallowed presence,\",\"Come, O come and fill me now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0260', 'chorus', 0, 1, '[\"Fill me now, fill me now,\",\"Jesus, come and fill me now.\",\"Fill me with Thy hallowed presence,\",\"Come, O come and fill me now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0260', 'verse', 2, 2, '[\"Thou canst fill me, gracious Spirit,\",\"Though I cannot tell Thee how;\",\"But I need Thee, greatly need Thee;\",\"Come, O come and fill me now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0260', 'verse', 3, 3, '[\"I am weakness, full of weakness;\",\"At Thy sacred feet I bow;\",\"Blest, divine, eternal Spirit,\",\"Fill with love, and fill me now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0260', 'verse', 4, 4, '[\"Cleanse and comfort, bless and save me;\",\"Bathe, O, bathe my heart and brow;\",\"Thou art comforting and saving,\",\"Thou art sweetly filling now.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0261', 261, 'The Spirit of the Lord Revealed', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'The Spirit of the Lord revealed
His will to saints of old;
Their heart and mind lips unsealed
His glory to unfold.
Amid the gloom of ancient night
They hailed the dawning Word,
And in the coming of the light
Proclaimed the coming Lord.
The prophets passed; at length there came
To sojourn and abide,
The Word incarnate, to whose name
The prophets testified;
And He, the twilight overpast,
Himself, the Light of light,
As man with man, revealed at last
The Father to our sight.
Eternal Spirit, who dost speak
To mind and conscience still,
That we in this our day, may seek
To do our Father\'s will,
To us the word of life impart,
Of Christ, the living way;
Give us the quiet, humble heart
To hear and to obey.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0261', 'verse', 1, 0, '[\"The Spirit of the Lord revealed\",\"His will to saints of old;\",\"Their heart and mind lips unsealed\",\"His glory to unfold.\",\"Amid the gloom of ancient night\",\"They hailed the dawning Word,\",\"And in the coming of the light\",\"Proclaimed the coming Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0261', 'verse', 2, 1, '[\"The prophets passed; at length there came\",\"To sojourn and abide,\",\"The Word incarnate, to whose name\",\"The prophets testified;\",\"And He, the twilight overpast,\",\"Himself, the Light of light,\",\"As man with man, revealed at last\",\"The Father to our sight.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0261', 'verse', 3, 2, '[\"Eternal Spirit, who dost speak\",\"To mind and conscience still,\",\"That we in this our day, may seek\",\"To do our Father\'s will,\",\"To us the word of life impart,\",\"Of Christ, the living way;\",\"Give us the quiet, humble heart\",\"To hear and to obey.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0262', 262, 'Sweet Sweet Spirit', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'There\'s a sweet, sweet spirit in this place,
And I know that it\'s the spirit of the Lord;
There are sweet expressions on each face
And I know they feel the presence of the Lord.
Sweet Holy Spirit,
Sweet Heavenly Dove,
Stay right here with us
Filling us with Your love,
And for these blessings we lift our hearts in praise,Without a doubt we\'ll know that we have been revived
When we shall leave this place.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0262', 'verse', 1, 0, '[\"There\'s a sweet, sweet spirit in this place,\",\"And I know that it\'s the spirit of the Lord;\",\"There are sweet expressions on each face\",\"And I know they feel the presence of the Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0262', 'chorus', 0, 1, '[\"Sweet Holy Spirit,\",\"Sweet Heavenly Dove,\",\"Stay right here with us\",\"Filling us with Your love,\",\"And for these blessings we lift our hearts in praise,Without a doubt we\'ll know that we have been revived\",\"When we shall leave this place.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0263', 263, 'Fire of God Thou Sacred Flame', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Fire of God, Thou sacred flame,
Spirit who in splendor came,
Let Thy heat my soul refine
Till it glows with love divine.
Breath of God, that swept in power
In the pentecostal hour,
Holy Breath, be Thou in me
Source of vital energy.
Strength of God, Thy might within
Conquers sorrow, pain, and sin:
Fortify from evil\'s art
All the gateways of my heart.
Truth of God, Thy piercing rays
Penetrate my secret ways.
May the light that shames my sin
Guide me holier paths to win.
Love of God, Thy grace profound
Knoweth neither age nor bound:
Come, my heart\'s own guest to be,
Dwell forevermore in me.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0263', 'verse', 1, 0, '[\"Fire of God, Thou sacred flame,\",\"Spirit who in splendor came,\",\"Let Thy heat my soul refine\",\"Till it glows with love divine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0263', 'verse', 2, 1, '[\"Breath of God, that swept in power\",\"In the pentecostal hour,\",\"Holy Breath, be Thou in me\",\"Source of vital energy.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0263', 'verse', 3, 2, '[\"Strength of God, Thy might within\",\"Conquers sorrow, pain, and sin:\",\"Fortify from evil\'s art\",\"All the gateways of my heart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0263', 'verse', 4, 3, '[\"Truth of God, Thy piercing rays\",\"Penetrate my secret ways.\",\"May the light that shames my sin\",\"Guide me holier paths to win.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0263', 'verse', 5, 4, '[\"Love of God, Thy grace profound\",\"Knoweth neither age nor bound:\",\"Come, my heart\'s own guest to be,\",\"Dwell forevermore in me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0264', 264, 'O for That Flame of Living Fire', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O for that flame of living fire
Which shone so bright in saints of old;
Which bade their souls to heaven aspire,
Calm in distress, in danger bold!
Where is that spirit, Lord, which dwelt
In Abram\'s breast, and sealed him Thine?
Which made Paul\'s heart with sorrow melt,
And glow with energy divine?
That spirit which from age to age
Proclaimed Thy love, and taught Thy ways?
Brightened Isaiah\'s vivid page,
And breathed in David\'s hallowed lays?
Is not Thy grace as mighty now
As when Elijah felt its power?
When glory beamed from Moses\' brow,
Or Job endured the trying hour?
Remember, Lord, the ancient days;
Renew Thy work, Thy grace restore;
And while to Thee our hearts we raise,
On us Thy Holy Spirit pour.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0264', 'verse', 1, 0, '[\"O for that flame of living fire\",\"Which shone so bright in saints of old;\",\"Which bade their souls to heaven aspire,\",\"Calm in distress, in danger bold!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0264', 'verse', 2, 1, '[\"Where is that spirit, Lord, which dwelt\",\"In Abram\'s breast, and sealed him Thine?\",\"Which made Paul\'s heart with sorrow melt,\",\"And glow with energy divine?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0264', 'verse', 3, 2, '[\"That spirit which from age to age\",\"Proclaimed Thy love, and taught Thy ways?\",\"Brightened Isaiah\'s vivid page,\",\"And breathed in David\'s hallowed lays?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0264', 'verse', 4, 3, '[\"Is not Thy grace as mighty now\",\"As when Elijah felt its power?\",\"When glory beamed from Moses\' brow,\",\"Or Job endured the trying hour?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0264', 'verse', 5, 4, '[\"Remember, Lord, the ancient days;\",\"Renew Thy work, Thy grace restore;\",\"And while to Thee our hearts we raise,\",\"On us Thy Holy Spirit pour.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0265', 265, 'Breathe on Me, Breath of God', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Breathe on me, Breath of God,
Fill me with life anew,
That I may love what Thou dost love,
And do what Thou wouldst do.
Breathe on me, Breath of God,
Until my heart is pure,
Until with Thee I will one will,
To do and to endure.
Breathe on me, Breath of God,
Till I am wholly Thine,
Until this earthly part of me
Glows with Thy fire divine.
Breathe on me, Breath of God,
So shall I constant be,
And live with Thee the perfect life
Of Thine eternity.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0265', 'verse', 1, 0, '[\"Breathe on me, Breath of God,\",\"Fill me with life anew,\",\"That I may love what Thou dost love,\",\"And do what Thou wouldst do.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0265', 'verse', 2, 1, '[\"Breathe on me, Breath of God,\",\"Until my heart is pure,\",\"Until with Thee I will one will,\",\"To do and to endure.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0265', 'verse', 3, 2, '[\"Breathe on me, Breath of God,\",\"Till I am wholly Thine,\",\"Until this earthly part of me\",\"Glows with Thy fire divine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0265', 'verse', 4, 3, '[\"Breathe on me, Breath of God,\",\"So shall I constant be,\",\"And live with Thee the perfect life\",\"Of Thine eternity.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0266', 266, 'Spirit of God', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Spirit of God! descend upon my heart;
Wean it from earth; through all its pulses move;
Stoop to my weakness, mighty as Thou art,
And make me love Thee as I ought to love.
I ask no dream, no prophet ecstasies;
No sudden rending of the veil of clay;
No angel visitant, no op\'ning skies;
But take the dimness of my soul away.
Hast Thou not bid us love Thee, God and King?
All, all Thine own, soul, heart, and strength, and mind;
I see Thy cross, there teach my heart to cling:
O let me seek Thee, and O let me find!
Teach me to feel that Thou art always nigh;
Teach me the struggles of the soul to bear;
To check the rising doubt, the rebel sigh;
Teach me the patience of unanswered prayer.
Teach me to love Thee as Thine angels love,
One holy passion filling all my frame;
The baptism of the heav\'n-descended dove,
My heart an altar, and Thy love the flame.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0266', 'verse', 1, 0, '[\"Spirit of God! descend upon my heart;\",\"Wean it from earth; through all its pulses move;\",\"Stoop to my weakness, mighty as Thou art,\",\"And make me love Thee as I ought to love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0266', 'verse', 2, 1, '[\"I ask no dream, no prophet ecstasies;\",\"No sudden rending of the veil of clay;\",\"No angel visitant, no op\'ning skies;\",\"But take the dimness of my soul away.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0266', 'verse', 3, 2, '[\"Hast Thou not bid us love Thee, God and King?\",\"All, all Thine own, soul, heart, and strength, and mind;\",\"I see Thy cross, there teach my heart to cling:\",\"O let me seek Thee, and O let me find!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0266', 'verse', 4, 3, '[\"Teach me to feel that Thou art always nigh;\",\"Teach me the struggles of the soul to bear;\",\"To check the rising doubt, the rebel sigh;\",\"Teach me the patience of unanswered prayer.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0266', 'verse', 5, 4, '[\"Teach me to love Thee as Thine angels love,\",\"One holy passion filling all my frame;\",\"The baptism of the heav\'n-descended dove,\",\"My heart an altar, and Thy love the flame.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0267', 267, 'Spirit Divine', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Spirit divine, attend our prayers,
And make this house Thy home;
Descend with all Thy gracious powers,
O come, great Spirit, come!
Come as the light; to us reveal
Our emptiness and woe,
And lead us in those paths of life
Whereon the righteous go.
Come as the fire, and purge our hearts
Like sacrificial flame;
Let our whole soul an off\'ring be
To our Redeemer\'s name.
Come as the dove, and spread Thy wings,
The wings of peaceful love;
And let Thy church on earth become
Blest as the church above.
Spirit divine, attend our prayers,
Make a lost world Thy home;
Descend with all Thy gracious powers,
O come, great Spirit, come!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0267', 'verse', 1, 0, '[\"Spirit divine, attend our prayers,\",\"And make this house Thy home;\",\"Descend with all Thy gracious powers,\",\"O come, great Spirit, come!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0267', 'verse', 2, 1, '[\"Come as the light; to us reveal\",\"Our emptiness and woe,\",\"And lead us in those paths of life\",\"Whereon the righteous go.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0267', 'verse', 3, 2, '[\"Come as the fire, and purge our hearts\",\"Like sacrificial flame;\",\"Let our whole soul an off\'ring be\",\"To our Redeemer\'s name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0267', 'verse', 4, 3, '[\"Come as the dove, and spread Thy wings,\",\"The wings of peaceful love;\",\"And let Thy church on earth become\",\"Blest as the church above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0267', 'verse', 5, 4, '[\"Spirit divine, attend our prayers,\",\"Make a lost world Thy home;\",\"Descend with all Thy gracious powers,\",\"O come, great Spirit, come!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0268', 268, 'Holy Spirit, Light Divine', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Holy Spirit, light divine,
Shine upon this heart of mine,
Chase the shades of night away,
Turn my darkness into day.
Holy Spirit, power divine,
Cleanse this guilty heart of mine;
Long has sin, without control,
Held dominion o\'er my soul.
Holy Ghost, with joy divine,
Cheer this saddened heart of mine,
Bid my many woes depart,
Heal my wounded, bleeding heart.
Holy Spirit, all divine,
Dwell within this heart of mine,
Cast down every idol throne,
Reign supreme, and reign alone.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0268', 'verse', 1, 0, '[\"Holy Spirit, light divine,\",\"Shine upon this heart of mine,\",\"Chase the shades of night away,\",\"Turn my darkness into day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0268', 'verse', 2, 1, '[\"Holy Spirit, power divine,\",\"Cleanse this guilty heart of mine;\",\"Long has sin, without control,\",\"Held dominion o\'er my soul.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0268', 'verse', 3, 2, '[\"Holy Ghost, with joy divine,\",\"Cheer this saddened heart of mine,\",\"Bid my many woes depart,\",\"Heal my wounded, bleeding heart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0268', 'verse', 4, 3, '[\"Holy Spirit, all divine,\",\"Dwell within this heart of mine,\",\"Cast down every idol throne,\",\"Reign supreme, and reign alone.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0269', 269, 'Come, Holy Spirit', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Come, Holy Spirit, heavenly Dove,
With all Thy quickening powers;
Kindle a flame of sacred love
In these cold hearts of ours.
O raise our thoughts from things below,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0269', 'verse', 1, 0, '[\"Come, Holy Spirit, heavenly Dove,\",\"With all Thy quickening powers;\",\"Kindle a flame of sacred love\",\"In these cold hearts of ours.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0269', 'verse', 2, 1, '[\"O raise our thoughts from things below,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0270', 270, 'O Holy Dove of God Descending', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O holy Dove of God descending,
You are the love that knows no ending.
All of our shattered dreams You\'re mending:
Spirit, now live in me.
O holy Wind of God now blowing,
You are the seed that God is sowing.
You are the life that starts us growing:
Spirit, now live in me.
O holy Rain of God now falling,
You make the Word of God enthralling,
You are that inner voice now calling:
Spirit, now live in me.
O holy Flame of God now burning,
You are the power of Christ returning.
You are the answer to our yearning:
Spirit, now live in me.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0270', 'verse', 1, 0, '[\"O holy Dove of God descending,\",\"You are the love that knows no ending.\",\"All of our shattered dreams You\'re mending:\",\"Spirit, now live in me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0270', 'verse', 2, 1, '[\"O holy Wind of God now blowing,\",\"You are the seed that God is sowing.\",\"You are the life that starts us growing:\",\"Spirit, now live in me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0270', 'verse', 3, 2, '[\"O holy Rain of God now falling,\",\"You make the Word of God enthralling,\",\"You are that inner voice now calling:\",\"Spirit, now live in me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0270', 'verse', 4, 3, '[\"O holy Flame of God now burning,\",\"You are the power of Christ returning.\",\"You are the answer to our yearning:\",\"Spirit, now live in me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0271', 271, 'Break Thou the Bread of Life', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Break Thou the bread of life,
Dear Lord, to me,
As Thou didst break the loaves
Beside the sea;
Beyond the sacred page
I seek Thee, Lord;
My spirit pants for Thee,
O living Word.
Bless Thou the truth, dear Lord,
To me, to me,
As Thou didst bless the bread
By Galilee;
Then shall all bondage cease,
All fetters fall;
And I shall find my peace,
My all in all.
Thou art the bread of life,
O Lord, to me;
Thy holy Word the truth
That saveth me;
Give me to eat and live
With Thee above;
Teach me to love Thy truth,
For Thou art love.
Spirit and life are they,
Words Thou dost speak;
I hasten to obey,
But I am weak;
Thou art my only help,
Thou art my life;
Heeding Thy holy Word
I win the strife.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0271', 'verse', 1, 0, '[\"Break Thou the bread of life,\",\"Dear Lord, to me,\",\"As Thou didst break the loaves\",\"Beside the sea;\",\"Beyond the sacred page\",\"I seek Thee, Lord;\",\"My spirit pants for Thee,\",\"O living Word.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0271', 'verse', 2, 1, '[\"Bless Thou the truth, dear Lord,\",\"To me, to me,\",\"As Thou didst bless the bread\",\"By Galilee;\",\"Then shall all bondage cease,\",\"All fetters fall;\",\"And I shall find my peace,\",\"My all in all.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0271', 'verse', 3, 2, '[\"Thou art the bread of life,\",\"O Lord, to me;\",\"Thy holy Word the truth\",\"That saveth me;\",\"Give me to eat and live\",\"With Thee above;\",\"Teach me to love Thy truth,\",\"For Thou art love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0271', 'verse', 4, 3, '[\"Spirit and life are they,\",\"Words Thou dost speak;\",\"I hasten to obey,\",\"But I am weak;\",\"Thou art my only help,\",\"Thou art my life;\",\"Heeding Thy holy Word\",\"I win the strife.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0272', 272, 'Give Me the Bible', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Give me the Bible, star of gladness gleaming,
To cheer the wanderer lone and tempest tossed,
No storm can hide that peaceful radiance beaming,
Since Jesus came to seek and save the lost.
Give me the Bible; holy message shining,
Thy light shall guide me in the narrow way.
Precept and promise, law and love combining,
\'Till night shall vanish in eternal day.
Give me the Bible when my heart is broken,
When sin and grief have filled my soul with fear;
Give me the precious words by Jesus spoken,
Hold up faith\'s lamp to show my Savior near.
Give me the Bible, all my steps enlighten,
Teach me the danger of these realms below;
That lamp of safety, o\'er the gloom shall brighten,
That light alone the path of peace can show.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0272', 'verse', 1, 0, '[\"Give me the Bible, star of gladness gleaming,\",\"To cheer the wanderer lone and tempest tossed,\",\"No storm can hide that peaceful radiance beaming,\",\"Since Jesus came to seek and save the lost.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0272', 'chorus', 0, 1, '[\"Give me the Bible; holy message shining,\",\"Thy light shall guide me in the narrow way.\",\"Precept and promise, law and love combining,\",\"\'Till night shall vanish in eternal day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0272', 'verse', 2, 2, '[\"Give me the Bible when my heart is broken,\",\"When sin and grief have filled my soul with fear;\",\"Give me the precious words by Jesus spoken,\",\"Hold up faith\'s lamp to show my Savior near.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0272', 'verse', 3, 3, '[\"Give me the Bible, all my steps enlighten,\",\"Teach me the danger of these realms below;\",\"That lamp of safety, o\'er the gloom shall brighten,\",\"That light alone the path of peace can show.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0273', 273, 'Lord, I Have Made Thy Word My Choice', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lord, I have made Thy word my choice,
My lasting heritage;
There shall my noblest pow\'rs rejoice,
My warmest thoughts engage.
I\'ll read the histories of Thy love,
And keep Thy laws in sight;
While through Thy promises I rove,
With ever fresh delight.
In this broad land of wealth unknown,
Where springs of life arise,
Seeds of immortal bliss are sown,
And hidden glory lies.
The best relief that mourners have,
It makes our sorrows blest;
Our fairest hope beyond the grave,
And our eternal rest.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0273', 'verse', 1, 0, '[\"Lord, I have made Thy word my choice,\",\"My lasting heritage;\",\"There shall my noblest pow\'rs rejoice,\",\"My warmest thoughts engage.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0273', 'verse', 2, 1, '[\"I\'ll read the histories of Thy love,\",\"And keep Thy laws in sight;\",\"While through Thy promises I rove,\",\"With ever fresh delight.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0273', 'verse', 3, 2, '[\"In this broad land of wealth unknown,\",\"Where springs of life arise,\",\"Seeds of immortal bliss are sown,\",\"And hidden glory lies.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0273', 'verse', 4, 3, '[\"The best relief that mourners have,\",\"It makes our sorrows blest;\",\"Our fairest hope beyond the grave,\",\"And our eternal rest.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0274', 274, 'O Word of God Incarnate', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O Word of God Incarnate,
O Wisdom from on high,
O Truth unchanged, unchanging,
O Light of our dark sky,
We praise Thee for the radiance
That from the hallowed page,
A lantern to our footsteps,
Shines on from age to age.
The church from her dear Master
Received the gift divine,
And still that light she lifteth
O\'er all the earth to shine.
It is the golden casket,
Where gems of truth are stored
It is the heaven-drawn picture
Of Christ, the living Word.
It floateth like a banner
Before God\'s host unfurled
It shineth like a beacon
Above the darkling world.
It is the chart and compass
That o\'er life\'s surging sea,
\'Mid mists and rocks and quicksands,
Still guides, O Christ, to Thee.
O make Thy church, dear Savior,
A lamp of purest gold,
To bear before the nations
Thy true light, as of old.
O teach Thy wandering pilgrims
By this their path to trace,
Till, clouds and darkness ended,
They see Thee face to face.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0274', 'verse', 1, 0, '[\"O Word of God Incarnate,\",\"O Wisdom from on high,\",\"O Truth unchanged, unchanging,\",\"O Light of our dark sky,\",\"We praise Thee for the radiance\",\"That from the hallowed page,\",\"A lantern to our footsteps,\",\"Shines on from age to age.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0274', 'verse', 2, 1, '[\"The church from her dear Master\",\"Received the gift divine,\",\"And still that light she lifteth\",\"O\'er all the earth to shine.\",\"It is the golden casket,\",\"Where gems of truth are stored\",\"It is the heaven-drawn picture\",\"Of Christ, the living Word.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0274', 'verse', 3, 2, '[\"It floateth like a banner\",\"Before God\'s host unfurled\",\"It shineth like a beacon\",\"Above the darkling world.\",\"It is the chart and compass\",\"That o\'er life\'s surging sea,\",\"\'Mid mists and rocks and quicksands,\",\"Still guides, O Christ, to Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0274', 'verse', 4, 3, '[\"O make Thy church, dear Savior,\",\"A lamp of purest gold,\",\"To bear before the nations\",\"Thy true light, as of old.\",\"O teach Thy wandering pilgrims\",\"By this their path to trace,\",\"Till, clouds and darkness ended,\",\"They see Thee face to face.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0275', 275, 'O God of Light', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O God of light, Your Word, a lamp unfailing,
Shall pierce the darkness of our earthbound way
And show your grace, Your plan for us unveiling,
And guide our footsteps to the perfect day.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0275', 'verse', 1, 0, '[\"O God of light, Your Word, a lamp unfailing,\",\"Shall pierce the darkness of our earthbound way\",\"And show your grace, Your plan for us unveiling,\",\"And guide our footsteps to the perfect day.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0276', 276, 'Thanks to God', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Thanks to God whose Word was spoken
In the deed that made the earth.
His the voice that called a nation;
His the fires that tried her worth.
God has spoken;
Praise Him for His open Word.
Thanks to God whose Word incarnate
Glorified the flesh of man.
Deeds and words and death and rising
Tell the grace in heaven\'s plan.
God has spoken;
Praise Him for His open Word.
Thanks to God whose Word is answered
By the Spirit\'s voice wihin.
Here we drink of joy unmeasured,
Life redeemed from death and sin.
God is speaking;
Praise Him for His open Word.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0276', 'verse', 1, 0, '[\"Thanks to God whose Word was spoken\",\"In the deed that made the earth.\",\"His the voice that called a nation;\",\"His the fires that tried her worth.\",\"God has spoken;\",\"Praise Him for His open Word.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0276', 'verse', 2, 1, '[\"Thanks to God whose Word incarnate\",\"Glorified the flesh of man.\",\"Deeds and words and death and rising\",\"Tell the grace in heaven\'s plan.\",\"God has spoken;\",\"Praise Him for His open Word.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0276', 'verse', 3, 2, '[\"Thanks to God whose Word is answered\",\"By the Spirit\'s voice wihin.\",\"Here we drink of joy unmeasured,\",\"Life redeemed from death and sin.\",\"God is speaking;\",\"Praise Him for His open Word.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0277', 277, 'For Your Holy Book We Thank You', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'For Your holy book we thank You,
And for all who served You well,
Writing, guarding, and translating,
That its pages might forth tell
Your strong love and tender care
For Your people everywhere.
For Your holy book we thank You,
And for those who work today,
That the people of all nations,
Reading it and foll\'wing, may
Know Your love and tender care
For Your people everywhere.
For Your holy book we thank You,
May its message be our guide,
May we understand the wisdom
Of the laws it will provide:
And Your love and tender care
For Your people everywhere.
For Your holy book we thank You,
May its message in our hearts
Lead us now to see in Jesus
All the grace Your word imparts:
All Your love and tender care
For Your people everywhere.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0277', 'verse', 1, 0, '[\"For Your holy book we thank You,\",\"And for all who served You well,\",\"Writing, guarding, and translating,\",\"That its pages might forth tell\",\"Your strong love and tender care\",\"For Your people everywhere.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0277', 'verse', 2, 1, '[\"For Your holy book we thank You,\",\"And for those who work today,\",\"That the people of all nations,\",\"Reading it and foll\'wing, may\",\"Know Your love and tender care\",\"For Your people everywhere.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0277', 'verse', 3, 2, '[\"For Your holy book we thank You,\",\"May its message be our guide,\",\"May we understand the wisdom\",\"Of the laws it will provide:\",\"And Your love and tender care\",\"For Your people everywhere.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0277', 'verse', 4, 3, '[\"For Your holy book we thank You,\",\"May its message in our hearts\",\"Lead us now to see in Jesus\",\"All the grace Your word imparts:\",\"All Your love and tender care\",\"For Your people everywhere.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0278', 278, 'Lord Jesus Once You Spoke to Men', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lord Jesus, once You spoke to men
Upon the mountain and the plain,
O help us listen now as then
And wonder at Your words again.
We all have secret fears to face,
Our minds and motives to amend.
We seek Your truth, we need Your grace,
Our living Lord and present friend.
The gospel speaks; and we receive
Your light, Your love, Your own command.
O help us live what we believe,
In daily word of heart and hand.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0278', 'verse', 1, 0, '[\"Lord Jesus, once You spoke to men\",\"Upon the mountain and the plain,\",\"O help us listen now as then\",\"And wonder at Your words again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0278', 'verse', 2, 1, '[\"We all have secret fears to face,\",\"Our minds and motives to amend.\",\"We seek Your truth, we need Your grace,\",\"Our living Lord and present friend.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0278', 'verse', 3, 2, '[\"The gospel speaks; and we receive\",\"Your light, Your love, Your own command.\",\"O help us live what we believe,\",\"In daily word of heart and hand.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0279', 279, 'Only Trust Him', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Come, every soul by sin oppressed,
There\'s mercy with the Lord,
And He will surely give you rest,
By trusting in His word.
Only trust Him, only trust Him,
Only trust Him now;
He will save you, He will save you,
He will save you now.
For Jesus shed His precious blood
Rich blessings to bestow;
Plunge now into the crimson flood
That washes white as snow.
Yes, Jesus is the truth, the way,
That leads you into rest;
Believe in Him without delay,
And you are fully blest.
Come, then, and join this holy band,
And on to glory go,
To dwell in that celestial land,
Where joys immortal flow.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0279', 'verse', 1, 0, '[\"Come, every soul by sin oppressed,\",\"There\'s mercy with the Lord,\",\"And He will surely give you rest,\",\"By trusting in His word.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0279', 'chorus', 0, 1, '[\"Only trust Him, only trust Him,\",\"Only trust Him now;\",\"He will save you, He will save you,\",\"He will save you now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0279', 'verse', 2, 2, '[\"For Jesus shed His precious blood\",\"Rich blessings to bestow;\",\"Plunge now into the crimson flood\",\"That washes white as snow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0279', 'verse', 3, 3, '[\"Yes, Jesus is the truth, the way,\",\"That leads you into rest;\",\"Believe in Him without delay,\",\"And you are fully blest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0279', 'verse', 4, 4, '[\"Come, then, and join this holy band,\",\"And on to glory go,\",\"To dwell in that celestial land,\",\"Where joys immortal flow.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0280', 280, 'Come, Ye Sinners', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Come, ye sinners poor and needy,
Weak and wounded, sick and sore;
Jesus ready stands to save you,
Full of pity, love, and power.
I will arise and go to Jesus,
He will embrace me in His arms;
In the arms of my dear Savior,
O there are ten thousand charms.
Come, ye thirsty, come, and welcome,
God\'s free bounty glorify;
True belief and true repentance,
Every grace that brings you nigh.
Let not conscience make you linger,
Nor of fitness fondly dream;
All the fitness He requireth
Is to feel your need of Him.
Lo! th\' incarnate God, ascended,
Pleads the merit of His blood;
Venture on Him, venture wholly,
Let no other trust intrude.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0280', 'verse', 1, 0, '[\"Come, ye sinners poor and needy,\",\"Weak and wounded, sick and sore;\",\"Jesus ready stands to save you,\",\"Full of pity, love, and power.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0280', 'chorus', 0, 1, '[\"I will arise and go to Jesus,\",\"He will embrace me in His arms;\",\"In the arms of my dear Savior,\",\"O there are ten thousand charms.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0280', 'verse', 2, 2, '[\"Come, ye thirsty, come, and welcome,\",\"God\'s free bounty glorify;\",\"True belief and true repentance,\",\"Every grace that brings you nigh.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0280', 'verse', 3, 3, '[\"Let not conscience make you linger,\",\"Nor of fitness fondly dream;\",\"All the fitness He requireth\",\"Is to feel your need of Him.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0280', 'verse', 4, 4, '[\"Lo! th\' incarnate God, ascended,\",\"Pleads the merit of His blood;\",\"Venture on Him, venture wholly,\",\"Let no other trust intrude.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0281', 281, 'I Gave My Life for Thee', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I gave My life for thee,
My precious blood I shed,
That thou might\'st ransomed be,
And quickened from the dead;
I gave, I gave My life for thee,
What hast thou given for Me?
I gave, I gave My life for thee,
What hast thou given for Me?
My Father\'s house of light,
My glory circled throne,
I left for earthly night,
For wanderings sad and lone;
I left, I left it all for thee,
Hast thou left aught for Me?
I left, I left it all for thee,
Hast thou left aught for Me?
I suffered much for thee,
More than thy tongue can tell,
Of bitterest agony,
To rescue thee from hell;
I\'ve borne, I\'ve borne it all for thee,
What hast thou borne for Me?
I\'ve borne, I\'ve borne it all for thee,
What hast thou borne for Me?');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0281', 'verse', 1, 0, '[\"I gave My life for thee,\",\"My precious blood I shed,\",\"That thou might\'st ransomed be,\",\"And quickened from the dead;\",\"I gave, I gave My life for thee,\",\"What hast thou given for Me?\",\"I gave, I gave My life for thee,\",\"What hast thou given for Me?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0281', 'verse', 2, 1, '[\"My Father\'s house of light,\",\"My glory circled throne,\",\"I left for earthly night,\",\"For wanderings sad and lone;\",\"I left, I left it all for thee,\",\"Hast thou left aught for Me?\",\"I left, I left it all for thee,\",\"Hast thou left aught for Me?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0281', 'verse', 3, 2, '[\"I suffered much for thee,\",\"More than thy tongue can tell,\",\"Of bitterest agony,\",\"To rescue thee from hell;\",\"I\'ve borne, I\'ve borne it all for thee,\",\"What hast thou borne for Me?\",\"I\'ve borne, I\'ve borne it all for thee,\",\"What hast thou borne for Me?\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0282', 282, 'I Hear Thy Welcome Voice', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I hear Thy welcome voice,
That calls me, Lord, to Thee;
For cleansing in Thy precious blood,
That flowed on Calvary.
I am coming, Lord!
Coming now to Thee!
Wash me, cleanse me, in the blood
That flowed on Calvary.
Though coming weak and vile,
Thou dost my strength assure;
Thou dost my vileness fully cleanse,
Till spotless all, and pure.
\'Tis Jesus calls me on
To perfect faith and love,
To perfect hope, and peace, and trust,
For earth and heaven above.
All hail, atoning blood!
All hail, redeeming grace!
All hail! the gift of Christ, our Lord,
Our Strength and Righteousness.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0282', 'verse', 1, 0, '[\"I hear Thy welcome voice,\",\"That calls me, Lord, to Thee;\",\"For cleansing in Thy precious blood,\",\"That flowed on Calvary.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0282', 'chorus', 0, 1, '[\"I am coming, Lord!\",\"Coming now to Thee!\",\"Wash me, cleanse me, in the blood\",\"That flowed on Calvary.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0282', 'verse', 2, 2, '[\"Though coming weak and vile,\",\"Thou dost my strength assure;\",\"Thou dost my vileness fully cleanse,\",\"Till spotless all, and pure.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0282', 'verse', 3, 3, '[\"\'Tis Jesus calls me on\",\"To perfect faith and love,\",\"To perfect hope, and peace, and trust,\",\"For earth and heaven above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0282', 'verse', 4, 4, '[\"All hail, atoning blood!\",\"All hail, redeeming grace!\",\"All hail! the gift of Christ, our Lord,\",\"Our Strength and Righteousness.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0283', 283, 'O Jesus, Thou Art Standing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O Jesus, Thou art standing
Outside the fast-closed door,
In lowly patience waiting
To pass the threshold o\'er:
O shame, professing Christian,
His name and sign who bear,
O shame, thrice shame upon us,
To keep Him standing there!
O Jesus, Thou art knocking;
And, lo, that hand is scarred,
And thorns Thy brow encircle,
And tears Thy face have marred.
O love that passeth knowledge,
So patiently to wait!
O sin that hath no equal,
So fast to bar the gate!
O Jesus, Thou art pleading
In accents meek and low,
\"I died for you, My children,
And will ye treat Me so?\"
O Lord, with shame and sorrow
We open now the door;
Dear Savior, enter, enter,
And leave us nevermore.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0283', 'verse', 1, 0, '[\"O Jesus, Thou art standing\",\"Outside the fast-closed door,\",\"In lowly patience waiting\",\"To pass the threshold o\'er:\",\"O shame, professing Christian,\",\"His name and sign who bear,\",\"O shame, thrice shame upon us,\",\"To keep Him standing there!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0283', 'verse', 2, 1, '[\"O Jesus, Thou art knocking;\",\"And, lo, that hand is scarred,\",\"And thorns Thy brow encircle,\",\"And tears Thy face have marred.\",\"O love that passeth knowledge,\",\"So patiently to wait!\",\"O sin that hath no equal,\",\"So fast to bar the gate!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0283', 'verse', 3, 2, '[\"O Jesus, Thou art pleading\",\"In accents meek and low,\",\"\\\"I died for you, My children,\",\"And will ye treat Me so?\\\"\",\"O Lord, with shame and sorrow\",\"We open now the door;\",\"Dear Savior, enter, enter,\",\"And leave us nevermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0284', 284, 'For You I Am Praying', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I have a Savior, He\'s pleading in glory,
A dear, loving Savior, though earth friends be few;
And now He is watching in tenderness o\'er me,
But oh that my Savior were your Savior, too.
For you I am praying,
For you I am praying,
For you I am praying,
I\'m praying for you.
I have a Father; to me He has given
A hope for eternity, blessed and true;
And soon He will call me to meet Him in heaven,
But oh that He\'d let me bring you with me, too!
I have a robe; \'tis resplendent in whiteness,
Awaiting in glory my wondering view;
Oh, when I receive it, all shining in brightness,
Dear friend, could I see you receiving one, you!
When Jesus has found you, tell others the story,
That my loving Savior is your Savior, too;
Then pray that your Savior will bring them to glory,
And prayer will be answered; \'twas answered for you!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0284', 'verse', 1, 0, '[\"I have a Savior, He\'s pleading in glory,\",\"A dear, loving Savior, though earth friends be few;\",\"And now He is watching in tenderness o\'er me,\",\"But oh that my Savior were your Savior, too.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0284', 'chorus', 0, 1, '[\"For you I am praying,\",\"For you I am praying,\",\"For you I am praying,\",\"I\'m praying for you.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0284', 'verse', 2, 2, '[\"I have a Father; to me He has given\",\"A hope for eternity, blessed and true;\",\"And soon He will call me to meet Him in heaven,\",\"But oh that He\'d let me bring you with me, too!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0284', 'verse', 3, 3, '[\"I have a robe; \'tis resplendent in whiteness,\",\"Awaiting in glory my wondering view;\",\"Oh, when I receive it, all shining in brightness,\",\"Dear friend, could I see you receiving one, you!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0284', 'verse', 4, 4, '[\"When Jesus has found you, tell others the story,\",\"That my loving Savior is your Savior, too;\",\"Then pray that your Savior will bring them to glory,\",\"And prayer will be answered; \'twas answered for you!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0285', 285, 'Jesus Calls Us', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Jesus calls us; o\'er the tumult
Of our life\'s wild, restless sea,
Day by day His sweet voice soundeth,
Saying, \"Christian, follow Me.\"
Jesus calls us from the worship
Of the vain world\'s golden store,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0285', 'verse', 1, 0, '[\"Jesus calls us; o\'er the tumult\",\"Of our life\'s wild, restless sea,\",\"Day by day His sweet voice soundeth,\",\"Saying, \\\"Christian, follow Me.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0285', 'verse', 2, 1, '[\"Jesus calls us from the worship\",\"Of the vain world\'s golden store,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0286', 286, 'Wonderful Words of Life', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Sing them over again to me,
Wonderful words of life;
Let me more of their beauty see,
Wonderful words of life.
Words of life and beauty,
Teach me faith and duty;
Beautiful words, wonderful words,
Wonderful words of life,
Beautiful words, wonderful words,
Wonderful words of life.
Christ, the blessed One, gives to all
Wonderful words of life;
Sinner, list to the loving call,
Wonderful words of life.
All so freely given,
Wooing us to heaven;
Sweetly echo the gospel call,
Wonderful words of life;
Offer pardon and peace to all,
Wonderful words of life.
Jesus, only Savior,
Sanctify forever;');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0286', 'verse', 1, 0, '[\"Sing them over again to me,\",\"Wonderful words of life;\",\"Let me more of their beauty see,\",\"Wonderful words of life.\",\"Words of life and beauty,\",\"Teach me faith and duty;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0286', 'chorus', 0, 1, '[\"Beautiful words, wonderful words,\",\"Wonderful words of life,\",\"Beautiful words, wonderful words,\",\"Wonderful words of life.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0286', 'verse', 2, 2, '[\"Christ, the blessed One, gives to all\",\"Wonderful words of life;\",\"Sinner, list to the loving call,\",\"Wonderful words of life.\",\"All so freely given,\",\"Wooing us to heaven;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0286', 'verse', 3, 3, '[\"Sweetly echo the gospel call,\",\"Wonderful words of life;\",\"Offer pardon and peace to all,\",\"Wonderful words of life.\",\"Jesus, only Savior,\",\"Sanctify forever;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0287', 287, 'Softly and Tenderly', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Softly and tenderly Jesus is calling,
Calling for you and for me;
At the heart\'s portal He\'s waiting and watching,
Watching for you and for me.
Come home, come home,
Ye who are weary, come home;
Earnestly, tenderly Jesus is calling,
Calling, O sinner, come home!
Why should we tarry when Jesus is pleading,
Pleading for you and for me?
Why should we linger and heed not His mercies,
Mercies for you and for me?
Think of the wonderful love He has promised,
Promised for you and for me;
Though we have sinned, He has mercy and pardon,
Pardon for you and for me.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0287', 'verse', 1, 0, '[\"Softly and tenderly Jesus is calling,\",\"Calling for you and for me;\",\"At the heart\'s portal He\'s waiting and watching,\",\"Watching for you and for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0287', 'chorus', 0, 1, '[\"Come home, come home,\",\"Ye who are weary, come home;\",\"Earnestly, tenderly Jesus is calling,\",\"Calling, O sinner, come home!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0287', 'verse', 2, 2, '[\"Why should we tarry when Jesus is pleading,\",\"Pleading for you and for me?\",\"Why should we linger and heed not His mercies,\",\"Mercies for you and for me?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0287', 'verse', 3, 3, '[\"Think of the wonderful love He has promised,\",\"Promised for you and for me;\",\"Though we have sinned, He has mercy and pardon,\",\"Pardon for you and for me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0288', 288, 'I Am Going to Calvary', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I am going to Calvary.
Would you like to come with Me
All the way and back again?
You must follow the Leader then.
You must follow the Leader,
You must follow the Leader,
All the way and back again,
You must follow the Leader.
If I wear a thorny crown,
If the soldiers knock Me down
Can I really be a king?
Love will answer everything
If you follow the Leader,
If you follow the Leader,
Love will answer everything
If you follow the Leader.
When I go along the road,
I shall lift a heavy load.
I will carry a cross for you.
You will learn to carry it too
When you follow the Leader,
When you follow the Leader,
You will learn to carry it too
If you follow the Leader.
I am going to stretch My hands,
Reaching out to all the lands.
Can I really be a king?
Love\'s the Lord of everything,
When you follow the Leader,
When you follow the Leader,
Love\'s the Lord of everything
When you follow the Leader.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0288', 'verse', 1, 0, '[\"I am going to Calvary.\",\"Would you like to come with Me\",\"All the way and back again?\",\"You must follow the Leader then.\",\"You must follow the Leader,\",\"You must follow the Leader,\",\"All the way and back again,\",\"You must follow the Leader.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0288', 'verse', 2, 1, '[\"If I wear a thorny crown,\",\"If the soldiers knock Me down\",\"Can I really be a king?\",\"Love will answer everything\",\"If you follow the Leader,\",\"If you follow the Leader,\",\"Love will answer everything\",\"If you follow the Leader.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0288', 'verse', 3, 2, '[\"When I go along the road,\",\"I shall lift a heavy load.\",\"I will carry a cross for you.\",\"You will learn to carry it too\",\"When you follow the Leader,\",\"When you follow the Leader,\",\"You will learn to carry it too\",\"If you follow the Leader.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0288', 'verse', 4, 3, '[\"I am going to stretch My hands,\",\"Reaching out to all the lands.\",\"Can I really be a king?\",\"Love\'s the Lord of everything,\",\"When you follow the Leader,\",\"When you follow the Leader,\",\"Love\'s the Lord of everything\",\"When you follow the Leader.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0289', 289, 'The Savior Is Waiting', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'The Savior is waiting to enter your heart,
Why don\'t you let Him come in?
There\'s nothing in this world to keep you apart,
What is your answer to Him?
Time after time He has waited before,
And now He is waiting again
To see if you\'re willing to open the door:
O how He wants to come in.
If you\'ll take one step toward the Savior, my friend,
You\'ll find His arms open wide;
Receive Him, and all of your darkness will end,
Within your heart He\'ll abide.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0289', 'verse', 1, 0, '[\"The Savior is waiting to enter your heart,\",\"Why don\'t you let Him come in?\",\"There\'s nothing in this world to keep you apart,\",\"What is your answer to Him?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0289', 'chorus', 0, 1, '[\"Time after time He has waited before,\",\"And now He is waiting again\",\"To see if you\'re willing to open the door:\",\"O how He wants to come in.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0289', 'verse', 2, 2, '[\"If you\'ll take one step toward the Savior, my friend,\",\"You\'ll find His arms open wide;\",\"Receive Him, and all of your darkness will end,\",\"Within your heart He\'ll abide.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0290', 290, 'Turn Your Eyes Upon Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O soul, are you weary and troubled?
No light in the darkness you see?
There\'s light for a look at the Savior,
And life more abundant and free!
Turn your eyes upon Jesus,
Look full in His wonderful face;
And the things of earth will grow strangely dim
In the light of His glory and grace.
Through death into life everlasting
He passed, and we follow Him there;
Over us sin no more hath dominion,
For more than conqu\'rors we are!
His word shall not fail you He promised;
Believe Him and all will be well:
Then go to a world that is dying,
His perfect salvation to tell!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0290', 'verse', 1, 0, '[\"O soul, are you weary and troubled?\",\"No light in the darkness you see?\",\"There\'s light for a look at the Savior,\",\"And life more abundant and free!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0290', 'chorus', 0, 1, '[\"Turn your eyes upon Jesus,\",\"Look full in His wonderful face;\",\"And the things of earth will grow strangely dim\",\"In the light of His glory and grace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0290', 'verse', 2, 2, '[\"Through death into life everlasting\",\"He passed, and we follow Him there;\",\"Over us sin no more hath dominion,\",\"For more than conqu\'rors we are!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0290', 'verse', 3, 3, '[\"His word shall not fail you He promised;\",\"Believe Him and all will be well:\",\"Then go to a world that is dying,\",\"His perfect salvation to tell!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0291', 291, 'We Have Not Known Thee', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'We have not known Thee as we ought,
Nor learned Thy wisdom, grace, and power;
The things of earth have led our thought,
And trifles of the passing hour.
Lord, give us light Thy truth to see,
And make us wise in knowing Thee.
We have not feared Thee as we ought,
Nor bowed beneath Thine awful eye,
Nor guarded deed, and word, and thought,
Remembering that God was nigh.
Lord, give us faith to know Thee near,
And grant the grace of holy fear.
We have not loved Thee as we ought,
Nor cared that we are loved by Thee;
Thy presence we have coldly sought,
And feebly longed Thy face to see.
Lord, give a pure and loving heart
To feel and own the love Thou art.
We have not served Thee as we ought;
Alas! the duties left undone,
The work with little fervor wrought,
The battles lost, or scarcely won!
Lord, give the zeal, and give the might,
For Thee to toil, for Thee to fight.
When shall we know Thee as we ought,
And fear, and love, and serve aright!
When shall we, out of trial brought,
Be perfect in the land of light!
Lord, may we day by day prepare
To see Thy face, and serve Thee there.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0291', 'verse', 1, 0, '[\"We have not known Thee as we ought,\",\"Nor learned Thy wisdom, grace, and power;\",\"The things of earth have led our thought,\",\"And trifles of the passing hour.\",\"Lord, give us light Thy truth to see,\",\"And make us wise in knowing Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0291', 'verse', 2, 1, '[\"We have not feared Thee as we ought,\",\"Nor bowed beneath Thine awful eye,\",\"Nor guarded deed, and word, and thought,\",\"Remembering that God was nigh.\",\"Lord, give us faith to know Thee near,\",\"And grant the grace of holy fear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0291', 'verse', 3, 2, '[\"We have not loved Thee as we ought,\",\"Nor cared that we are loved by Thee;\",\"Thy presence we have coldly sought,\",\"And feebly longed Thy face to see.\",\"Lord, give a pure and loving heart\",\"To feel and own the love Thou art.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0291', 'verse', 4, 3, '[\"We have not served Thee as we ought;\",\"Alas! the duties left undone,\",\"The work with little fervor wrought,\",\"The battles lost, or scarcely won!\",\"Lord, give the zeal, and give the might,\",\"For Thee to toil, for Thee to fight.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0291', 'verse', 5, 4, '[\"When shall we know Thee as we ought,\",\"And fear, and love, and serve aright!\",\"When shall we, out of trial brought,\",\"Be perfect in the land of light!\",\"Lord, may we day by day prepare\",\"To see Thy face, and serve Thee there.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0292', 292, 'Jesus, I Come', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Out of my bondage, sorrow and night,
Jesus, I come, Jesus, I come;
Into Thy freedom, gladness and light,
Jesus, I come to Thee;
Out of my sickness into Thy health,
Out of my want and into Thy wealth,
Out of my sin and into Thyself,
Jesus, I come to Thee.
Out of my shameful failure and loss,
Jesus, I come, Jesus, I come;
Into the glorious gain of Thy cross,
Jesus, I come to Thee;
Out of earth\'s sorrows into Thy balm,
Out of life\'s storms and into Thy calm,
Out of distress to jubilant psalm,
Jesus, I come to Thee.
Out of unrest and arrogant pride,
Jesus, I come, Jesus, I come;
Into Thy blessed will to abide,
Jesus, I come to Thee;
Out of myself to dwell in Thy love,
Out of despair into raptures above,
Upward for aye on wings like a dove,
Jesus, I come to Thee.
Out of the fear and dread of the tomb,
Jesus, I come, Jesus, I come;
Into the joy and light of Thy home,
Jesus, I come to Thee;
Out of the depths of ruin untold,
Into the peace of Thy sheltering fold,
Ever Thy glorious face to behold,
Jesus, I come to Thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0292', 'verse', 1, 0, '[\"Out of my bondage, sorrow and night,\",\"Jesus, I come, Jesus, I come;\",\"Into Thy freedom, gladness and light,\",\"Jesus, I come to Thee;\",\"Out of my sickness into Thy health,\",\"Out of my want and into Thy wealth,\",\"Out of my sin and into Thyself,\",\"Jesus, I come to Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0292', 'verse', 2, 1, '[\"Out of my shameful failure and loss,\",\"Jesus, I come, Jesus, I come;\",\"Into the glorious gain of Thy cross,\",\"Jesus, I come to Thee;\",\"Out of earth\'s sorrows into Thy balm,\",\"Out of life\'s storms and into Thy calm,\",\"Out of distress to jubilant psalm,\",\"Jesus, I come to Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0292', 'verse', 3, 2, '[\"Out of unrest and arrogant pride,\",\"Jesus, I come, Jesus, I come;\",\"Into Thy blessed will to abide,\",\"Jesus, I come to Thee;\",\"Out of myself to dwell in Thy love,\",\"Out of despair into raptures above,\",\"Upward for aye on wings like a dove,\",\"Jesus, I come to Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0292', 'verse', 4, 3, '[\"Out of the fear and dread of the tomb,\",\"Jesus, I come, Jesus, I come;\",\"Into the joy and light of Thy home,\",\"Jesus, I come to Thee;\",\"Out of the depths of ruin untold,\",\"Into the peace of Thy sheltering fold,\",\"Ever Thy glorious face to behold,\",\"Jesus, I come to Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0293', 293, 'Heavenly Father, Bless Us Now', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Heavenly Father, bless us now;
At the cross of Christ we bow;
Take our guilt and grief away;
Hear and heal us now, we pray.
Now, O Lord, this very hour,
Send Thy grace and show Thy power;
While we rest upon Thy word,
Come, and bless us now, O Lord!
Mercy now, O Lord, we plead
In this hour of utter need;
Turn us not away unblest;
Calm our anguish into rest.
O Thou loving, blessed One,
Rising o\'er us like the sun,
Light and life art Thou within:
Savior, Thou, from every sin!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0293', 'verse', 1, 0, '[\"Heavenly Father, bless us now;\",\"At the cross of Christ we bow;\",\"Take our guilt and grief away;\",\"Hear and heal us now, we pray.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0293', 'verse', 2, 1, '[\"Now, O Lord, this very hour,\",\"Send Thy grace and show Thy power;\",\"While we rest upon Thy word,\",\"Come, and bless us now, O Lord!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0293', 'verse', 3, 2, '[\"Mercy now, O Lord, we plead\",\"In this hour of utter need;\",\"Turn us not away unblest;\",\"Calm our anguish into rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0293', 'verse', 4, 3, '[\"O Thou loving, blessed One,\",\"Rising o\'er us like the sun,\",\"Light and life art Thou within:\",\"Savior, Thou, from every sin!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0294', 294, 'Power in the Blood', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Would you be free from the burden of sin?
There\'s pow\'r in the blood, pow\'r in the blood;
Would you o\'er evil a victory win?
There\'s wonderful pow\'r in the blood.
There is pow\'r, pow\'r, wonder-working pow\'r
In the blood of the Lamb;
There is pow\'r, pow\'r, wonder-working pow\'r
In the precious blood of the Lamb.
Would you be free from your passion and pride?
There\'s pow\'r in the blood, pow\'r in the blood;
Come for a cleansing to Calvary\'s tide?
There\'s wonderful pow\'r in the blood.
Would you do service for Jesus your King?
There\'s pow\'r in the blood, pow\'r in the blood;
Would you live daily His praises to sing?
There\'s wonderful pow\'r in the blood.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0294', 'verse', 1, 0, '[\"Would you be free from the burden of sin?\",\"There\'s pow\'r in the blood, pow\'r in the blood;\",\"Would you o\'er evil a victory win?\",\"There\'s wonderful pow\'r in the blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0294', 'chorus', 0, 1, '[\"There is pow\'r, pow\'r, wonder-working pow\'r\",\"In the blood of the Lamb;\",\"There is pow\'r, pow\'r, wonder-working pow\'r\",\"In the precious blood of the Lamb.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0294', 'verse', 2, 2, '[\"Would you be free from your passion and pride?\",\"There\'s pow\'r in the blood, pow\'r in the blood;\",\"Come for a cleansing to Calvary\'s tide?\",\"There\'s wonderful pow\'r in the blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0294', 'verse', 3, 3, '[\"Would you do service for Jesus your King?\",\"There\'s pow\'r in the blood, pow\'r in the blood;\",\"Would you live daily His praises to sing?\",\"There\'s wonderful pow\'r in the blood.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0295', 295, 'Chief of Sinners', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Chief of sinners though I be,
Jesus shed His blood for me;
Died that I might live on high,
Died that I might never die;
As the branch is to the vine,
I am His, and He is mine.
O the height of Jesus\' love!
Higher than the heaven above,
Deeper than the deepest sea,
Lasting as eternity;
Love that found me; wondrous thought!
Found me when I sought Him not!
Chief of sinners though I be,
Christ is all in all to me;
All my wants to Him are known,
All my sorrows are His own;
Safe with Him from earthly strife,
He sustains the hidden life.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0295', 'verse', 1, 0, '[\"Chief of sinners though I be,\",\"Jesus shed His blood for me;\",\"Died that I might live on high,\",\"Died that I might never die;\",\"As the branch is to the vine,\",\"I am His, and He is mine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0295', 'verse', 2, 1, '[\"O the height of Jesus\' love!\",\"Higher than the heaven above,\",\"Deeper than the deepest sea,\",\"Lasting as eternity;\",\"Love that found me; wondrous thought!\",\"Found me when I sought Him not!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0295', 'verse', 3, 2, '[\"Chief of sinners though I be,\",\"Christ is all in all to me;\",\"All my wants to Him are known,\",\"All my sorrows are His own;\",\"Safe with Him from earthly strife,\",\"He sustains the hidden life.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0296', 296, 'Lord, I\'m Coming Home', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I\'ve wandered far away from God,
Now I\'m coming home;
The paths of sin too long I\'ve trod;
Lord, I\'m coming home.
Coming home, coming home
Nevermore to roam;
Open wide Thine arms of love;
Lord, I\'m coming home.
I\'ve wasted many precious years,
Now I\'m coming home;
I now repent with bitter tears;
Lord, I\'m coming home.
I\'m tired of sin and straying, Lord,
Now I\'m coming home;
I\'ll trust Thy love, believe Thy word;
Lord, I\'m coming home.
My only hope, my only plea,
Now I\'m coming home;
That Jesus died, and died for me;
Lord, I\'m coming home.
I need His cleansing blood I know,
Now I\'m coming home;
O wash me whiter than the snow;
Lord, I\'m coming home.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0296', 'verse', 1, 0, '[\"I\'ve wandered far away from God,\",\"Now I\'m coming home;\",\"The paths of sin too long I\'ve trod;\",\"Lord, I\'m coming home.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0296', 'chorus', 0, 1, '[\"Coming home, coming home\",\"Nevermore to roam;\",\"Open wide Thine arms of love;\",\"Lord, I\'m coming home.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0296', 'verse', 2, 2, '[\"I\'ve wasted many precious years,\",\"Now I\'m coming home;\",\"I now repent with bitter tears;\",\"Lord, I\'m coming home.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0296', 'verse', 3, 3, '[\"I\'m tired of sin and straying, Lord,\",\"Now I\'m coming home;\",\"I\'ll trust Thy love, believe Thy word;\",\"Lord, I\'m coming home.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0296', 'verse', 4, 4, '[\"My only hope, my only plea,\",\"Now I\'m coming home;\",\"That Jesus died, and died for me;\",\"Lord, I\'m coming home.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0296', 'verse', 5, 5, '[\"I need His cleansing blood I know,\",\"Now I\'m coming home;\",\"O wash me whiter than the snow;\",\"Lord, I\'m coming home.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0297', 297, 'God Be Merciful to Me', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'God, be merciful to me,
On Thy grace I rest my plea;
Plenteous in compassion Thou,
Blot out my transgressions now;
Wash me, make me pure within,
Cleanse, O cleanse me from my sin,
Wash me, make me pure within,
Cleanse, O cleanse me from my sin.
I am evil, born in sin;
Thou desirest truth within.
Thou alone my Savior art,
Teach Thy wisdom to my heart;
Make me pure, Thy grace bestow,
Wash me whiter than the snow,
Make me pure, Thy grace bestow,
Wash me whiter than the snow.
Gracious God, my heart renew,
Make my spirit right and true;
Cast me not away from Thee,
Let Thy Spirit dwell in me;
Thy salvation\'s joy impart,
Steadfast make my willing heart,
Thy salvation\'s joy impart,
Steadfast make my willing heart.
Sinners then shall learn from me
And return, O God, to Thee;
Savior, all my guilt remove,
And my tongue shall sing Thy love;
Touch my silent lips, O Lord,
And my mouth shall praise accord,
Touch my silent lips, O Lord,
And my mouth shall praise accord.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0297', 'verse', 1, 0, '[\"God, be merciful to me,\",\"On Thy grace I rest my plea;\",\"Plenteous in compassion Thou,\",\"Blot out my transgressions now;\",\"Wash me, make me pure within,\",\"Cleanse, O cleanse me from my sin,\",\"Wash me, make me pure within,\",\"Cleanse, O cleanse me from my sin.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0297', 'verse', 2, 1, '[\"I am evil, born in sin;\",\"Thou desirest truth within.\",\"Thou alone my Savior art,\",\"Teach Thy wisdom to my heart;\",\"Make me pure, Thy grace bestow,\",\"Wash me whiter than the snow,\",\"Make me pure, Thy grace bestow,\",\"Wash me whiter than the snow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0297', 'verse', 3, 2, '[\"Gracious God, my heart renew,\",\"Make my spirit right and true;\",\"Cast me not away from Thee,\",\"Let Thy Spirit dwell in me;\",\"Thy salvation\'s joy impart,\",\"Steadfast make my willing heart,\",\"Thy salvation\'s joy impart,\",\"Steadfast make my willing heart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0297', 'verse', 4, 3, '[\"Sinners then shall learn from me\",\"And return, O God, to Thee;\",\"Savior, all my guilt remove,\",\"And my tongue shall sing Thy love;\",\"Touch my silent lips, O Lord,\",\"And my mouth shall praise accord,\",\"Touch my silent lips, O Lord,\",\"And my mouth shall praise accord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0298', 298, 'I Lay My Sins On Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I lay my sins on Jesus,
The spotless Lamb of God;
He bears them all, and frees us');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0298', 'verse', 1, 0, '[\"I lay my sins on Jesus,\",\"The spotless Lamb of God;\",\"He bears them all, and frees us\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0299', 299, 'Forgive Our Sins As We Forgive', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, '\"Forgive our sins as we forgive,\"
You taught us, Lord, to pray;
But You alone can grant us grace
To live the words we say.
How can Your pardon reach and bless
The unforgiving heart
That broods on wrongs and will not let
Old bitterness depart?
In blazing light Your cross reveals
The truth we dimly knew:
How trifling others\' debts to us;
How great our debt to You!
Lord, cleanse the depths within our souls
And bid resentment cease;
Then, by Your mercy reconciled,
Our lives will spread Your peace.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0299', 'verse', 1, 0, '[\"\\\"Forgive our sins as we forgive,\\\"\",\"You taught us, Lord, to pray;\",\"But You alone can grant us grace\",\"To live the words we say.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0299', 'verse', 2, 1, '[\"How can Your pardon reach and bless\",\"The unforgiving heart\",\"That broods on wrongs and will not let\",\"Old bitterness depart?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0299', 'verse', 3, 2, '[\"In blazing light Your cross reveals\",\"The truth we dimly knew:\",\"How trifling others\' debts to us;\",\"How great our debt to You!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0299', 'verse', 4, 3, '[\"Lord, cleanse the depths within our souls\",\"And bid resentment cease;\",\"Then, by Your mercy reconciled,\",\"Our lives will spread Your peace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0300', 300, 'Rock of Ages', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Rock of Ages, cleft for me,
Let me hide myself in Thee;
Let the water and the blood,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0300', 'verse', 1, 0, '[\"Rock of Ages, cleft for me,\",\"Let me hide myself in Thee;\",\"Let the water and the blood,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0301', 301, 'Nearer, Still Nearer', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Nearer, still nearer, close to Thy heart,
Draw me, my Savior, so precious Thou art;
Fold me, O fold me close to Thy breast,
Shelter me safe in that haven of rest,
Shelter me safe in that haven of rest.
Nearer, still nearer, nothing I bring,
Nought as an offering to Jesus my King
Only my sinful now contrite heart;
Grant me the cleansing Thy blood doth impart,
Grant me the cleansing Thy blood doth impart.
Nearer, still nearer, Lord, to be Thine;
Sin, with its follies, I gladly resign,
All of its pleasures, pomp and its pride;
Give me but Jesus, my Lord crucified,
Give me but Jesus, my Lord crucified.
Nearer, still nearer, while life shall last;
Till safe in glory my anchor is cast;
Through endless ages, ever to be,
Nearer, my Savior, still nearer to Thee,
Nearer, my Savior, still nearer to Thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0301', 'verse', 1, 0, '[\"Nearer, still nearer, close to Thy heart,\",\"Draw me, my Savior, so precious Thou art;\",\"Fold me, O fold me close to Thy breast,\",\"Shelter me safe in that haven of rest,\",\"Shelter me safe in that haven of rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0301', 'verse', 2, 1, '[\"Nearer, still nearer, nothing I bring,\",\"Nought as an offering to Jesus my King\",\"Only my sinful now contrite heart;\",\"Grant me the cleansing Thy blood doth impart,\",\"Grant me the cleansing Thy blood doth impart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0301', 'verse', 3, 2, '[\"Nearer, still nearer, Lord, to be Thine;\",\"Sin, with its follies, I gladly resign,\",\"All of its pleasures, pomp and its pride;\",\"Give me but Jesus, my Lord crucified,\",\"Give me but Jesus, my Lord crucified.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0301', 'verse', 4, 3, '[\"Nearer, still nearer, while life shall last;\",\"Till safe in glory my anchor is cast;\",\"Through endless ages, ever to be,\",\"Nearer, my Savior, still nearer to Thee,\",\"Nearer, my Savior, still nearer to Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0302', 302, 'Deeper Yet', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'In the blood from the cross
I have been washed from sin;
But to be free from dross,
Still I would enter in.
Deeper yet, deeper yet,
Into the crimson flood;
Deeper yet, deeper yet,
Under the precious blood.
Day by day, hour by hour,
Blessings are sent to me;
But for more of His power
Ever my prayer shall be.
Near to Christ I would live,
Following Him each day;
What I ask He will give;
So then with faith I pray.
Now I have peace, sweet peace,
While in this world of sin;
But to pray I\'ll not cease
Till I am pure within.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0302', 'verse', 1, 0, '[\"In the blood from the cross\",\"I have been washed from sin;\",\"But to be free from dross,\",\"Still I would enter in.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0302', 'chorus', 0, 1, '[\"Deeper yet, deeper yet,\",\"Into the crimson flood;\",\"Deeper yet, deeper yet,\",\"Under the precious blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0302', 'verse', 2, 2, '[\"Day by day, hour by hour,\",\"Blessings are sent to me;\",\"But for more of His power\",\"Ever my prayer shall be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0302', 'verse', 3, 3, '[\"Near to Christ I would live,\",\"Following Him each day;\",\"What I ask He will give;\",\"So then with faith I pray.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0302', 'verse', 4, 4, '[\"Now I have peace, sweet peace,\",\"While in this world of sin;\",\"But to pray I\'ll not cease\",\"Till I am pure within.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0303', 303, 'Beneath the Cross of Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Beneath the cross of Jesus
I fain would take my stand,
The shadow of a mighty rock
Within a weary land;
A home within the wilderness,
A rest upon the way,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0303', 'verse', 1, 0, '[\"Beneath the cross of Jesus\",\"I fain would take my stand,\",\"The shadow of a mighty rock\",\"Within a weary land;\",\"A home within the wilderness,\",\"A rest upon the way,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0304', 304, 'Faith of Our Fathers', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Faith of our fathers! living still
In spite of dungeon, fire, and sword,
O how our hearts beat high with joy
Whene\'er we hear that glorious word.
Faith of our fathers! holy faith!
We will be true to thee till death.
Our fathers, chained in prisons dark,
Were still in heart and conscience free;
How sweet would be their children\'s fate,
If they, like them, could die for thee!
Faith of our fathers! holy faith!
We will be true to thee till death.
Faith of our fathers! we will love
Both friend and foe in all our strife,
And preach thee, too, as love knows how,
By kindly words and virtuous life.
Faith of our fathers! holy faith!
We will be true to thee till death.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0304', 'verse', 1, 0, '[\"Faith of our fathers! living still\",\"In spite of dungeon, fire, and sword,\",\"O how our hearts beat high with joy\",\"Whene\'er we hear that glorious word.\",\"Faith of our fathers! holy faith!\",\"We will be true to thee till death.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0304', 'verse', 2, 1, '[\"Our fathers, chained in prisons dark,\",\"Were still in heart and conscience free;\",\"How sweet would be their children\'s fate,\",\"If they, like them, could die for thee!\",\"Faith of our fathers! holy faith!\",\"We will be true to thee till death.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0304', 'verse', 3, 2, '[\"Faith of our fathers! we will love\",\"Both friend and foe in all our strife,\",\"And preach thee, too, as love knows how,\",\"By kindly words and virtuous life.\",\"Faith of our fathers! holy faith!\",\"We will be true to thee till death.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0305', 305, 'Give Me Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'In the morning when I rise,
In the morning when I rise,
In the morning when I rise,
Give me Jesus.
Give me Jesus, Give me Jesus,
You may have all this world,
Give me Jesus.
Dark midnight was my cry,
Dark midnight was my cry,
Dark midnight was my cry,
Give me Jesus.
Just about the break of day,
Just about the break of day,
Just about the break of day,
Give me Jesus.
Oh, when I come to die,
Oh, when I come to die,
Oh, when I come to die,
Give me Jesus.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0305', 'verse', 1, 0, '[\"In the morning when I rise,\",\"In the morning when I rise,\",\"In the morning when I rise,\",\"Give me Jesus.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0305', 'chorus', 0, 1, '[\"Give me Jesus, Give me Jesus,\",\"You may have all this world,\",\"Give me Jesus.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0305', 'verse', 2, 2, '[\"Dark midnight was my cry,\",\"Dark midnight was my cry,\",\"Dark midnight was my cry,\",\"Give me Jesus.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0305', 'verse', 3, 3, '[\"Just about the break of day,\",\"Just about the break of day,\",\"Just about the break of day,\",\"Give me Jesus.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0305', 'verse', 4, 4, '[\"Oh, when I come to die,\",\"Oh, when I come to die,\",\"Oh, when I come to die,\",\"Give me Jesus.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0306', 306, 'Draw Me Nearer', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I am Thine, O Lord, I have heard Thy voice,
And it told Thy love to me;
But I long to rise in the arms of faith,
And be closer drawn to Thee.
Draw me nearer, nearer, blessed Lord,
To the cross where Thou hast died;
Draw me nearer, nearer, nearer, blessed Lord,
To Thy precious, bleeding side.
Consecrate me now to Thy service, Lord,
By the power of grace divine;
May my soul look up with a steadfast hope
And my will be lost in Thine.
O the pure delight of a single hour
That before Thy throne I spend,
When I kneel in prayer, and with Thee, my God,
I commune as friend with friend!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0306', 'verse', 1, 0, '[\"I am Thine, O Lord, I have heard Thy voice,\",\"And it told Thy love to me;\",\"But I long to rise in the arms of faith,\",\"And be closer drawn to Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0306', 'chorus', 0, 1, '[\"Draw me nearer, nearer, blessed Lord,\",\"To the cross where Thou hast died;\",\"Draw me nearer, nearer, nearer, blessed Lord,\",\"To Thy precious, bleeding side.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0306', 'verse', 2, 2, '[\"Consecrate me now to Thy service, Lord,\",\"By the power of grace divine;\",\"May my soul look up with a steadfast hope\",\"And my will be lost in Thine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0306', 'verse', 3, 3, '[\"O the pure delight of a single hour\",\"That before Thy throne I spend,\",\"When I kneel in prayer, and with Thee, my God,\",\"I commune as friend with friend!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0307', 307, 'I Am Coming to the Cross', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I am coming to the cross;
I am poor, and weak, and blind
I am counting all but dross;
I shall full salvation find.
I am trusting, Lord, in Thee,
O Thou Lamb of Calvary;
Humbly at Thy cross I bow;
Save me, Jesus, save me now.
Long my heart has sighed for Thee;
Long has evil reigned within;
Jesus sweetly speaks to me,
\"I will cleanse you from all sin.\"
Here I give my all to Thee;
Friends, and time, and earthly store;
Soul and body Thine to be,
Wholly Thine forevermore.
Jesus comes! He fills my soul!
Perfected in Him I am;
I am every whit made whole;
Glory, glory to the Lamb!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0307', 'verse', 1, 0, '[\"I am coming to the cross;\",\"I am poor, and weak, and blind\",\"I am counting all but dross;\",\"I shall full salvation find.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0307', 'chorus', 0, 1, '[\"I am trusting, Lord, in Thee,\",\"O Thou Lamb of Calvary;\",\"Humbly at Thy cross I bow;\",\"Save me, Jesus, save me now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0307', 'verse', 2, 2, '[\"Long my heart has sighed for Thee;\",\"Long has evil reigned within;\",\"Jesus sweetly speaks to me,\",\"\\\"I will cleanse you from all sin.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0307', 'verse', 3, 3, '[\"Here I give my all to Thee;\",\"Friends, and time, and earthly store;\",\"Soul and body Thine to be,\",\"Wholly Thine forevermore.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0307', 'verse', 4, 4, '[\"Jesus comes! He fills my soul!\",\"Perfected in Him I am;\",\"I am every whit made whole;\",\"Glory, glory to the Lamb!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0308', 308, 'Wholly Thine', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I would be, dear Savior, wholly Thine;
Teach me how, teach me how;
I would do Thy will, O Lord, not mine;
Help me, help me now.
Wholly Thine, wholly Thine,
Wholly Thine, this is my vow;
Wholly Thine, wholly Thine,
Wholly Thine, O Lord, just now.
What is worldly pleasure, wealth, or fame,
Without Thee, without Thee?
I will leave them all for Thy dear name,
This my wealth shall be.
As I cast earth\'s transient joys behind,
Come Thou near, come Thou near;
In Thy presence all in all I find,
\'Tis my comfort here.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0308', 'verse', 1, 0, '[\"I would be, dear Savior, wholly Thine;\",\"Teach me how, teach me how;\",\"I would do Thy will, O Lord, not mine;\",\"Help me, help me now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0308', 'chorus', 0, 1, '[\"Wholly Thine, wholly Thine,\",\"Wholly Thine, this is my vow;\",\"Wholly Thine, wholly Thine,\",\"Wholly Thine, O Lord, just now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0308', 'verse', 2, 2, '[\"What is worldly pleasure, wealth, or fame,\",\"Without Thee, without Thee?\",\"I will leave them all for Thy dear name,\",\"This my wealth shall be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0308', 'verse', 3, 3, '[\"As I cast earth\'s transient joys behind,\",\"Come Thou near, come Thou near;\",\"In Thy presence all in all I find,\",\"\'Tis my comfort here.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0309', 309, 'I Surrender All', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'All to Jesus I surrender,
All to Him I freely give;
I will ever love and trust Him,
In His presence daily live;
I surrender all,
I surrender all;
All to Thee, my blessed Savior,
I surrender all.
All to Jesus I surrender;
Humbly at His feet I bow,
Worldly pleasures all forsaken;
Take me, Jesus, take me now;
All to Jesus I surrender;
Make me, Savior, wholly Thine;
Let me feel the Holy Spirit,
Truly know that Thou art mine;
All to Jesus I surrender;
Now I feel the sacred flame.
O the joy of full salvation!
Glory, glory to His name!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0309', 'verse', 1, 0, '[\"All to Jesus I surrender,\",\"All to Him I freely give;\",\"I will ever love and trust Him,\",\"In His presence daily live;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0309', 'chorus', 0, 1, '[\"I surrender all,\",\"I surrender all;\",\"All to Thee, my blessed Savior,\",\"I surrender all.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0309', 'verse', 2, 2, '[\"All to Jesus I surrender;\",\"Humbly at His feet I bow,\",\"Worldly pleasures all forsaken;\",\"Take me, Jesus, take me now;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0309', 'verse', 3, 3, '[\"All to Jesus I surrender;\",\"Make me, Savior, wholly Thine;\",\"Let me feel the Holy Spirit,\",\"Truly know that Thou art mine;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0309', 'verse', 4, 4, '[\"All to Jesus I surrender;\",\"Now I feel the sacred flame.\",\"O the joy of full salvation!\",\"Glory, glory to His name!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0310', 310, 'I Would Draw Nearer to Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I would draw nearer to Jesus,
In His sweet presence abide,
Constantly trying to serve Him,
Safe and secure at His side.
I would draw nearer to Jesus,
I would draw nearer to Him;
Fully surrendered each moment,
I would draw nearer to Him.
I would draw nearer to Jesus,
Nothing withholding from Him,
Knowing He loves to be gracious,
I would draw nearer to Him.
I would draw nearer to Jesus,
Seeking His strength to be true,
Willing to tell of His goodness,
Gladly His blest will to do.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0310', 'verse', 1, 0, '[\"I would draw nearer to Jesus,\",\"In His sweet presence abide,\",\"Constantly trying to serve Him,\",\"Safe and secure at His side.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0310', 'chorus', 0, 1, '[\"I would draw nearer to Jesus,\",\"I would draw nearer to Him;\",\"Fully surrendered each moment,\",\"I would draw nearer to Him.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0310', 'verse', 2, 2, '[\"I would draw nearer to Jesus,\",\"Nothing withholding from Him,\",\"Knowing He loves to be gracious,\",\"I would draw nearer to Him.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0310', 'verse', 3, 3, '[\"I would draw nearer to Jesus,\",\"Seeking His strength to be true,\",\"Willing to tell of His goodness,\",\"Gladly His blest will to do.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0311', 311, 'I Would Be Like Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Earthly pleasures vainly call me;
I would be like Jesus;
Nothing worldly shall enthrall me;
I would be like Jesus.
Be like Jesus, this my song,
In the home and in the throng,
Be like Jesus, all day long!
I would be like Jesus.
He has broken every fetter,
I would be like Jesus;
That my soul may serve Him better,
I would be like Jesus.
All the way from earth to glory,
I would be like Jesus;
Telling o\'er and o\'er the story,
I would be like Jesus.
That in heaven He may meet me,
I would be like Jesus;
That His words \"Well done\" may greet me,
I would be like Jesus.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0311', 'verse', 1, 0, '[\"Earthly pleasures vainly call me;\",\"I would be like Jesus;\",\"Nothing worldly shall enthrall me;\",\"I would be like Jesus.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0311', 'chorus', 0, 1, '[\"Be like Jesus, this my song,\",\"In the home and in the throng,\",\"Be like Jesus, all day long!\",\"I would be like Jesus.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0311', 'verse', 2, 2, '[\"He has broken every fetter,\",\"I would be like Jesus;\",\"That my soul may serve Him better,\",\"I would be like Jesus.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0311', 'verse', 3, 3, '[\"All the way from earth to glory,\",\"I would be like Jesus;\",\"Telling o\'er and o\'er the story,\",\"I would be like Jesus.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0311', 'verse', 4, 4, '[\"That in heaven He may meet me,\",\"I would be like Jesus;\",\"That His words \\\"Well done\\\" may greet me,\",\"I would be like Jesus.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0312', 312, 'Near the Cross', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Jesus, keep me near the cross;
There a precious fountain
Free to all, a healing stream,
Flows from Calvary\'s mountain.
In the cross, in the cross,
Be my glory ever,
Till my raptured soul shall find
Rest beyond the river.
Near the cross, a trembling soul,
Love and mercy found me;
There the bright and Morning Star
Sheds its beams around me.
Near the cross! O Lamb of God,
Bring its scenes before me;
Help me walk from day to day,
With its shadows o\'er me.
Near the cross I\'ll watch and wait,
Hoping, trusting ever,
Till I reach the golden strand,
Just beyond the river.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0312', 'verse', 1, 0, '[\"Jesus, keep me near the cross;\",\"There a precious fountain\",\"Free to all, a healing stream,\",\"Flows from Calvary\'s mountain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0312', 'chorus', 0, 1, '[\"In the cross, in the cross,\",\"Be my glory ever,\",\"Till my raptured soul shall find\",\"Rest beyond the river.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0312', 'verse', 2, 2, '[\"Near the cross, a trembling soul,\",\"Love and mercy found me;\",\"There the bright and Morning Star\",\"Sheds its beams around me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0312', 'verse', 3, 3, '[\"Near the cross! O Lamb of God,\",\"Bring its scenes before me;\",\"Help me walk from day to day,\",\"With its shadows o\'er me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0312', 'verse', 4, 4, '[\"Near the cross I\'ll watch and wait,\",\"Hoping, trusting ever,\",\"Till I reach the golden strand,\",\"Just beyond the river.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0313', 313, 'Just as I Am', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Just as I am, without one plea,
But that Thy blood was shed for me,
And that Thou bid\'st me come to Thee,
O Lamb of God, I come.
Just as I am, and waiting not
To rid my soul of one dark blot,
To Thee whose blood can cleanse each spot,
O Lamb of God, I come.
Just as I am, though tossed about
With many a conflict, many a doubt;
\"Fightings within, and fears without,\"
O Lamb of God, I come.
Just as I am, poor, wretched, blind;
Sight, riches, healing of the mind,
Yea, all I need, in Thee I find,
O Lamb of God, I come.
Just as I am, Thou wilt receive,
Wilt welcome, pardon, cleanse, relieve;
Because Thy promise I believe,
O Lamb of God, I come.
Just as I am, Thy love I own
Has broken every barrier down;
Now to be Thine, and Thine alone,
O Lamb of God, I come.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0313', 'verse', 1, 0, '[\"Just as I am, without one plea,\",\"But that Thy blood was shed for me,\",\"And that Thou bid\'st me come to Thee,\",\"O Lamb of God, I come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0313', 'verse', 2, 1, '[\"Just as I am, and waiting not\",\"To rid my soul of one dark blot,\",\"To Thee whose blood can cleanse each spot,\",\"O Lamb of God, I come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0313', 'verse', 3, 2, '[\"Just as I am, though tossed about\",\"With many a conflict, many a doubt;\",\"\\\"Fightings within, and fears without,\\\"\",\"O Lamb of God, I come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0313', 'verse', 4, 3, '[\"Just as I am, poor, wretched, blind;\",\"Sight, riches, healing of the mind,\",\"Yea, all I need, in Thee I find,\",\"O Lamb of God, I come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0313', 'verse', 5, 4, '[\"Just as I am, Thou wilt receive,\",\"Wilt welcome, pardon, cleanse, relieve;\",\"Because Thy promise I believe,\",\"O Lamb of God, I come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0313', 'verse', 6, 5, '[\"Just as I am, Thy love I own\",\"Has broken every barrier down;\",\"Now to be Thine, and Thine alone,\",\"O Lamb of God, I come.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0314', 314, 'Just as I Am', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Just as I am, without one plea
But that Thy blood was shed for me
And that Thou bid\'st me come to Thee
O Lamb of God, I come, I come.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0314', 'verse', 1, 0, '[\"Just as I am, without one plea\",\"But that Thy blood was shed for me\",\"And that Thou bid\'st me come to Thee\",\"O Lamb of God, I come, I come.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0315', 315, 'O for a Closer Walk!', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O, for a closer walk with God!
A calm and heavenly frame,
A light to shine upon the road
That leads me to the Lamb.
Return, O holy Dove! return,
Sweet messenger of rest;
I hate the sins that made Thee mourn,
And drove Thee from my breast.
What peaceful hours I once enjoyed!
How sweet their memory still!
But they have left an aching void
The world can never till.
The dearest idol I have known,
Whate\'er that idol be,
Help me to tear it from Thy throne,
And worship only Thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0315', 'verse', 1, 0, '[\"O, for a closer walk with God!\",\"A calm and heavenly frame,\",\"A light to shine upon the road\",\"That leads me to the Lamb.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0315', 'verse', 2, 1, '[\"Return, O holy Dove! return,\",\"Sweet messenger of rest;\",\"I hate the sins that made Thee mourn,\",\"And drove Thee from my breast.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0315', 'verse', 3, 2, '[\"What peaceful hours I once enjoyed!\",\"How sweet their memory still!\",\"But they have left an aching void\",\"The world can never till.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0315', 'verse', 4, 3, '[\"The dearest idol I have known,\",\"Whate\'er that idol be,\",\"Help me to tear it from Thy throne,\",\"And worship only Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0316', 316, 'Live Out Thy Life Within Me', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Live out Thy life within me,
O Jesus, King of kings!
Be Thou Thyself the answer
To all my questionings;
Live out Thy life within me,
In all things have Thy way!
I, the transparent medium
Thy glory to display.
The temple has been yielded,
And purified of sin;
Let Thy Shekinah glory
Now shine forth from within,
And all the earth keep silence,
The body henceforth be
Thy silent, gentle servant,
Moved only as by Thee.
Its members every moment
Held subject to Thy call,
Ready to have Thee use them,
Or not be used at all;
Held without restless longing,
Or strain, or stress, or fret,
Or chafings at Thy dealings,
Or thoughts of vain regret.
But restful, calm, and pliant,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0316', 'verse', 1, 0, '[\"Live out Thy life within me,\",\"O Jesus, King of kings!\",\"Be Thou Thyself the answer\",\"To all my questionings;\",\"Live out Thy life within me,\",\"In all things have Thy way!\",\"I, the transparent medium\",\"Thy glory to display.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0316', 'verse', 2, 1, '[\"The temple has been yielded,\",\"And purified of sin;\",\"Let Thy Shekinah glory\",\"Now shine forth from within,\",\"And all the earth keep silence,\",\"The body henceforth be\",\"Thy silent, gentle servant,\",\"Moved only as by Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0316', 'verse', 3, 2, '[\"Its members every moment\",\"Held subject to Thy call,\",\"Ready to have Thee use them,\",\"Or not be used at all;\",\"Held without restless longing,\",\"Or strain, or stress, or fret,\",\"Or chafings at Thy dealings,\",\"Or thoughts of vain regret.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0316', 'verse', 4, 3, '[\"But restful, calm, and pliant,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0317', 317, 'Lead Me to Calvary', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'King of my life, I crown Thee now,
Thine shall the glory be;
Lest I forget Thy thorn-crowned brow,
Lead me to Calvary.
Lest I forget Gethsemane;
Lest I forget Thine agony;
Lest I forget Thy love for me,
Lead me to Calvary.
Show me the tomb where Thou wast laid,
Tenderly mourned and wept;
Angels in robes of light arrayed
Guarded Thee whilst Thou slept.
Let me like Mary, thru the gloom,
Come with a gift to Thee;
Show to me now the empty tomb,
Lead me to Calvary.
May I be willing, Lord, to bear
Daily my cross for Thee;
Even Thy cup of grief to share,
Thou hast borne all for me.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0317', 'verse', 1, 0, '[\"King of my life, I crown Thee now,\",\"Thine shall the glory be;\",\"Lest I forget Thy thorn-crowned brow,\",\"Lead me to Calvary.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0317', 'chorus', 0, 1, '[\"Lest I forget Gethsemane;\",\"Lest I forget Thine agony;\",\"Lest I forget Thy love for me,\",\"Lead me to Calvary.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0317', 'verse', 2, 2, '[\"Show me the tomb where Thou wast laid,\",\"Tenderly mourned and wept;\",\"Angels in robes of light arrayed\",\"Guarded Thee whilst Thou slept.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0317', 'verse', 3, 3, '[\"Let me like Mary, thru the gloom,\",\"Come with a gift to Thee;\",\"Show to me now the empty tomb,\",\"Lead me to Calvary.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0317', 'verse', 4, 4, '[\"May I be willing, Lord, to bear\",\"Daily my cross for Thee;\",\"Even Thy cup of grief to share,\",\"Thou hast borne all for me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0318', 318, 'Whiter Than Snow', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lord Jesus, I long to be perfectly whole;
I want Thee forever to live in my soul;
Break down every idol, cast out every foe;
Now wash me, and I shall be whiter than snow.
Whiter than snow, yes whiter than snow;
Now wash me, and I shall be whiter than snow.
Lord Jesus, look down from Thy throne in the skies,
And help me to make a complete sacrifice;
I give up myself, and whatever I know,
Now wash me, and I shall be whiter than snow.
Lord Jesus, for this I most humbly entreat;
I wait, blessed Lord, at Thy crucified feet,
By faith, for my cleansing; I see Thy blood flow,
Now wash me, and I shall be whiter than snow.
Lord Jesus, Thou seest I patiently wait;
Come now, and within me a new heart create;
To those who have sought Thee, Thou never said\'st No;
Now wash me, and I shall be whiter than snow.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0318', 'verse', 1, 0, '[\"Lord Jesus, I long to be perfectly whole;\",\"I want Thee forever to live in my soul;\",\"Break down every idol, cast out every foe;\",\"Now wash me, and I shall be whiter than snow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0318', 'chorus', 0, 1, '[\"Whiter than snow, yes whiter than snow;\",\"Now wash me, and I shall be whiter than snow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0318', 'verse', 2, 2, '[\"Lord Jesus, look down from Thy throne in the skies,\",\"And help me to make a complete sacrifice;\",\"I give up myself, and whatever I know,\",\"Now wash me, and I shall be whiter than snow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0318', 'verse', 3, 3, '[\"Lord Jesus, for this I most humbly entreat;\",\"I wait, blessed Lord, at Thy crucified feet,\",\"By faith, for my cleansing; I see Thy blood flow,\",\"Now wash me, and I shall be whiter than snow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0318', 'verse', 4, 4, '[\"Lord Jesus, Thou seest I patiently wait;\",\"Come now, and within me a new heart create;\",\"To those who have sought Thee, Thou never said\'st No;\",\"Now wash me, and I shall be whiter than snow.\"]');
