INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0320', 320, 'Lord of Creation', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lord of creation, to You be all praise!
Most mighty Your working, most wondrous Your ways!
Your glory and might are beyond us to tell,
And yet in the heart of the humble You dwell.
Lord of all power, I give You my will,
In joyful obedience Your tasks to fulfill.
Your bondage is freedom; Your service is song;
And held in Your keeping, my weakness is strong.
Lord of all wisdom, I give You my mind,
Rich truth that surpasses man\'s knowledge to find;
What eye has not seen and what ear has not heard
Is taught by Your Spirit and shines from Your Word.
Lord of all being, I give You my all;
If I ever disown You, I stumble and fall;
But led in Your service Your word to obey,
I\'ll walk in Your freedom to the end of the way.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0320', 'verse', 1, 0, '[\"Lord of creation, to You be all praise!\",\"Most mighty Your working, most wondrous Your ways!\",\"Your glory and might are beyond us to tell,\",\"And yet in the heart of the humble You dwell.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0320', 'verse', 2, 1, '[\"Lord of all power, I give You my will,\",\"In joyful obedience Your tasks to fulfill.\",\"Your bondage is freedom; Your service is song;\",\"And held in Your keeping, my weakness is strong.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0320', 'verse', 3, 2, '[\"Lord of all wisdom, I give You my mind,\",\"Rich truth that surpasses man\'s knowledge to find;\",\"What eye has not seen and what ear has not heard\",\"Is taught by Your Spirit and shines from Your Word.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0320', 'verse', 4, 3, '[\"Lord of all being, I give You my all;\",\"If I ever disown You, I stumble and fall;\",\"But led in Your service Your word to obey,\",\"I\'ll walk in Your freedom to the end of the way.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0321', 321, 'My Jesus, I Love Thee', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'My Jesus, I love Thee, I know Thou art mine;
For Thee all the follies of sin I resign;
My gracious Redeemer, my Savior art Thou;
If ever I loved Thee, my Jesus, \'tis now.
I love Thee because Thou hast first loved me,
And purchased my pardon on Calvary\'s tree;
I love Thee for wearing the thorns on Thy brow;
If ever I loved Thee, my Jesus, \'tis now.
I\'ll love Thee in life, I will love Thee \'til death,
And praise Thee as long as Thou lendest me breath;
And say when the death dew lies cold on my brow,
If ever I loved Thee, my Jesus, \'tis now.
In mansions of glory and endless delight,
I\'ll ever adore Thee in heaven so bright;
I\'ll sing with the glittering crown on my brow,
If ever I loved Thee, my Jesus, \'tis now.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0321', 'verse', 1, 0, '[\"My Jesus, I love Thee, I know Thou art mine;\",\"For Thee all the follies of sin I resign;\",\"My gracious Redeemer, my Savior art Thou;\",\"If ever I loved Thee, my Jesus, \'tis now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0321', 'verse', 2, 1, '[\"I love Thee because Thou hast first loved me,\",\"And purchased my pardon on Calvary\'s tree;\",\"I love Thee for wearing the thorns on Thy brow;\",\"If ever I loved Thee, my Jesus, \'tis now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0321', 'verse', 3, 2, '[\"I\'ll love Thee in life, I will love Thee \'til death,\",\"And praise Thee as long as Thou lendest me breath;\",\"And say when the death dew lies cold on my brow,\",\"If ever I loved Thee, my Jesus, \'tis now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0321', 'verse', 4, 3, '[\"In mansions of glory and endless delight,\",\"I\'ll ever adore Thee in heaven so bright;\",\"I\'ll sing with the glittering crown on my brow,\",\"If ever I loved Thee, my Jesus, \'tis now.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0322', 322, 'Nothing Between', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Nothing between my soul and the Savior,
Naught of this world\'s delusive dream:
I have renounced all sinful pleasure-
Jesus is mine!
There\'s nothing between.
Nothing between my soul and the Savior,
So that His blessed face may be seen;
Nothing preventing the least of His favor:
Keep the way clear!
Let nothing between.
Nothing between, like worldly pleasure:
Habits of life, though harmless they seem,
Must not my heart from Him ever sever-
He is my all!
There\'s nothing between.
Nothing between, e\'en many hard trials,
Though the whole world against me convene;
Watching with prayer and much self-denial-
Triumph at last,
With nothing between!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0322', 'verse', 1, 0, '[\"Nothing between my soul and the Savior,\",\"Naught of this world\'s delusive dream:\",\"I have renounced all sinful pleasure-\",\"Jesus is mine!\",\"There\'s nothing between.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0322', 'chorus', 0, 1, '[\"Nothing between my soul and the Savior,\",\"So that His blessed face may be seen;\",\"Nothing preventing the least of His favor:\",\"Keep the way clear!\",\"Let nothing between.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0322', 'verse', 2, 2, '[\"Nothing between, like worldly pleasure:\",\"Habits of life, though harmless they seem,\",\"Must not my heart from Him ever sever-\",\"He is my all!\",\"There\'s nothing between.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0322', 'verse', 3, 3, '[\"Nothing between, e\'en many hard trials,\",\"Though the whole world against me convene;\",\"Watching with prayer and much self-denial-\",\"Triumph at last,\",\"With nothing between!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0323', 323, 'O for a Heart to Praise My God!', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O for a heart to praise my God!
A heart from sin set free,
A heart that always feels Thy blood,
So freely shed for me.
A heart resigned, submissive, meek,
My dear Redeemer\'s throne,
Where only Christ is heard to speak,
Where Jesus reigns alone.
A heart in every thought renewed,
And full of love divine,
Perfect, and right, and pure, and good,
A copy, Lord, of Thine.
Thy nature, gracious Lord, impart;
Come quickly from above;
Write Thy new name upon my heart,
Thy new, best name of Love.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0323', 'verse', 1, 0, '[\"O for a heart to praise my God!\",\"A heart from sin set free,\",\"A heart that always feels Thy blood,\",\"So freely shed for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0323', 'verse', 2, 1, '[\"A heart resigned, submissive, meek,\",\"My dear Redeemer\'s throne,\",\"Where only Christ is heard to speak,\",\"Where Jesus reigns alone.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0323', 'verse', 3, 2, '[\"A heart in every thought renewed,\",\"And full of love divine,\",\"Perfect, and right, and pure, and good,\",\"A copy, Lord, of Thine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0323', 'verse', 4, 3, '[\"Thy nature, gracious Lord, impart;\",\"Come quickly from above;\",\"Write Thy new name upon my heart,\",\"Thy new, best name of Love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0324', 324, 'Just as I Am, Thine Own to Be', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Just as I am, Thine own to be,
Friend of the young, who lovest me,
To consecrate myself to Thee,
O Jesus Christ, I come.
In the glad morning of my day,
My life to give, my vows to pay,
With no reserve and no delay,
With all my heart I come.
I would live ever in the light;
I would work ever for the right;
I would serve Thee with all my might;
Therefore, to Thee I come.
Just as I am, young, strong, and free,
To be the best that I can be
For truth, and righteousness, and Thee,
Lord of my life, I come.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0324', 'verse', 1, 0, '[\"Just as I am, Thine own to be,\",\"Friend of the young, who lovest me,\",\"To consecrate myself to Thee,\",\"O Jesus Christ, I come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0324', 'verse', 2, 1, '[\"In the glad morning of my day,\",\"My life to give, my vows to pay,\",\"With no reserve and no delay,\",\"With all my heart I come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0324', 'verse', 3, 2, '[\"I would live ever in the light;\",\"I would work ever for the right;\",\"I would serve Thee with all my might;\",\"Therefore, to Thee I come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0324', 'verse', 4, 3, '[\"Just as I am, young, strong, and free,\",\"To be the best that I can be\",\"For truth, and righteousness, and Thee,\",\"Lord of my life, I come.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0325', 325, 'Jesus, I My Cross Have Taken', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Jesus, I my cross have taken,
All to leave and follow Thee;
All things else I have forsaken;
Thou from hence my all shalt be.
Perish every fond ambition,
All I\'ve sought, or hoped, or known;
Yet how rich is my condition,
While I prove the Lord my own.
Let the world despise and leave me;
They have left my Savior, too;
Human hearts and looks deceive me;
Thou art faithful, Thou art true.
O, \'tis not in grief to harm me,
While Thy love is left to me;
O, \'twere not in joy to charm me,
If that love be hid from me.
Soul, then know thy full salvation;
Rise o\'er sin, and fear, and care;
Joy to find in every station
Something still to do or bear.
Think what Spirit dwells within thee;
Think what Father\'s smiles are thine;
Think that Jesus died to win thee;
Child of Heaven, canst thou repine?
Haste thee on from grace to glory,
Armed by faith and winged by prayer;
Heaven\'s eternal day\'s before thee;
God\'s own hand shall guide thee there.
Soon shall close thy earthly mission,
Soon shall pass thy pilgrim days;
Hope shall change to glad fruition,
Faith to sight, and prayer to praise.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0325', 'verse', 1, 0, '[\"Jesus, I my cross have taken,\",\"All to leave and follow Thee;\",\"All things else I have forsaken;\",\"Thou from hence my all shalt be.\",\"Perish every fond ambition,\",\"All I\'ve sought, or hoped, or known;\",\"Yet how rich is my condition,\",\"While I prove the Lord my own.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0325', 'verse', 2, 1, '[\"Let the world despise and leave me;\",\"They have left my Savior, too;\",\"Human hearts and looks deceive me;\",\"Thou art faithful, Thou art true.\",\"O, \'tis not in grief to harm me,\",\"While Thy love is left to me;\",\"O, \'twere not in joy to charm me,\",\"If that love be hid from me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0325', 'verse', 3, 2, '[\"Soul, then know thy full salvation;\",\"Rise o\'er sin, and fear, and care;\",\"Joy to find in every station\",\"Something still to do or bear.\",\"Think what Spirit dwells within thee;\",\"Think what Father\'s smiles are thine;\",\"Think that Jesus died to win thee;\",\"Child of Heaven, canst thou repine?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0325', 'verse', 4, 3, '[\"Haste thee on from grace to glory,\",\"Armed by faith and winged by prayer;\",\"Heaven\'s eternal day\'s before thee;\",\"God\'s own hand shall guide thee there.\",\"Soon shall close thy earthly mission,\",\"Soon shall pass thy pilgrim days;\",\"Hope shall change to glad fruition,\",\"Faith to sight, and prayer to praise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0326', 326, 'Open My Eyes That I May See', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Open my eyes, that I may see
Glimpses of truth Thou hast for me;
Place in my hands the wonderful key
That shall unclasp and set me free.
Silently now I wait for Thee,
Ready, my God, Thy will to see;
Open my eyes, illumine me,
Spirit divine!
Open my ears, that I may hear
Voices of truth Thou sendest clear;
And while the wave-notes fall on my ear,
Everything false will disappear.
Silently now I wait for Thee,
Ready, my God, Thy will to see;
Open my ears, illumine me,
Spirit divine!
Open my mouth, and let me bear
Gladly the warm truth ev\'rywhere;
Open my heart, and let me prepare
Love with Thy children thus to share.
Silently now I wait for Thee,
Ready, my God, Thy will to see;
Open my heart, illumine me,
Spirit divine!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0326', 'verse', 1, 0, '[\"Open my eyes, that I may see\",\"Glimpses of truth Thou hast for me;\",\"Place in my hands the wonderful key\",\"That shall unclasp and set me free.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0326', 'chorus', 0, 1, '[\"Silently now I wait for Thee,\",\"Ready, my God, Thy will to see;\",\"Open my eyes, illumine me,\",\"Spirit divine!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0326', 'verse', 2, 2, '[\"Open my ears, that I may hear\",\"Voices of truth Thou sendest clear;\",\"And while the wave-notes fall on my ear,\",\"Everything false will disappear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0326', 'chorus', 0, 3, '[\"Silently now I wait for Thee,\",\"Ready, my God, Thy will to see;\",\"Open my ears, illumine me,\",\"Spirit divine!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0326', 'verse', 3, 4, '[\"Open my mouth, and let me bear\",\"Gladly the warm truth ev\'rywhere;\",\"Open my heart, and let me prepare\",\"Love with Thy children thus to share.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0326', 'chorus', 0, 5, '[\"Silently now I wait for Thee,\",\"Ready, my God, Thy will to see;\",\"Open my heart, illumine me,\",\"Spirit divine!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0327', 327, 'I\'d Rather Have Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I\'d rather have Jesus than silver or gold,
I\'d rather be His than have riches untold;
I\'d rather have Jesus than houses or lands,
I\'d rather be led by His nail-pierced hand.
Than to be the king of a vast domain
Or be held in sin\'s dread sway;
I\'d rather have Jesus than anything
This world affords today.
I\'d rather have Jesus than men\'s applause,
I\'d rather be faithful to His dear cause;
I\'d rather have Jesus than worldwide fame,
I\'d rather be true to His holy name.
He\'s fairer than lilies of rarest bloom,
He\'s sweeter than honey from out the comb;
He\'s all that my hungering spirit needs,
I\'d rather have Jesus and let Him lead.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0327', 'verse', 1, 0, '[\"I\'d rather have Jesus than silver or gold,\",\"I\'d rather be His than have riches untold;\",\"I\'d rather have Jesus than houses or lands,\",\"I\'d rather be led by His nail-pierced hand.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0327', 'chorus', 0, 1, '[\"Than to be the king of a vast domain\",\"Or be held in sin\'s dread sway;\",\"I\'d rather have Jesus than anything\",\"This world affords today.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0327', 'verse', 2, 2, '[\"I\'d rather have Jesus than men\'s applause,\",\"I\'d rather be faithful to His dear cause;\",\"I\'d rather have Jesus than worldwide fame,\",\"I\'d rather be true to His holy name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0327', 'verse', 3, 3, '[\"He\'s fairer than lilies of rarest bloom,\",\"He\'s sweeter than honey from out the comb;\",\"He\'s all that my hungering spirit needs,\",\"I\'d rather have Jesus and let Him lead.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0328', 328, 'Must Jesus Bear the Cross Alone', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Must Jesus bear the cross alone,
And all the world go free?
No, there\'s a cross for every one,
And there\'s a cross for me.
The consecrated cross I\'ll bear,
Till He shall set me free;
And then go home my crown to wear,
For there\'s a crown for me.
Upon the crystal pavement, down
At Jesus\' pierced feet,
With joy I\'ll cast my golden crown,
And His dear name repeat.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0328', 'verse', 1, 0, '[\"Must Jesus bear the cross alone,\",\"And all the world go free?\",\"No, there\'s a cross for every one,\",\"And there\'s a cross for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0328', 'verse', 2, 1, '[\"The consecrated cross I\'ll bear,\",\"Till He shall set me free;\",\"And then go home my crown to wear,\",\"For there\'s a crown for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0328', 'verse', 3, 2, '[\"Upon the crystal pavement, down\",\"At Jesus\' pierced feet,\",\"With joy I\'ll cast my golden crown,\",\"And His dear name repeat.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0329', 329, 'Take the World, but Give Me Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Take the world, but give me Jesus;
All its joys are but a name,
But His love abideth ever,
Through eternal years the same.
Oh, the height and depth of mercy!
Oh, the length and breadth of love!
Oh, the fullness of redemption,
Pledge of endless life above.
Take the world, but give me Jesus,
Sweetest comfort of my soul;
With my Savior watching o\'er me,
I can sing, though billows roll.
Take the world, but give me Jesus;
Let me view His constant smile;
Then throughout my pilgrim journey
Light will cheer me all the while.
Take the world, but give me Jesus;
In His cross my trust shall be,
Till, with clearer, brighter vision,
Face to face my Lord I see.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0329', 'verse', 1, 0, '[\"Take the world, but give me Jesus;\",\"All its joys are but a name,\",\"But His love abideth ever,\",\"Through eternal years the same.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0329', 'chorus', 0, 1, '[\"Oh, the height and depth of mercy!\",\"Oh, the length and breadth of love!\",\"Oh, the fullness of redemption,\",\"Pledge of endless life above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0329', 'verse', 2, 2, '[\"Take the world, but give me Jesus,\",\"Sweetest comfort of my soul;\",\"With my Savior watching o\'er me,\",\"I can sing, though billows roll.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0329', 'verse', 3, 3, '[\"Take the world, but give me Jesus;\",\"Let me view His constant smile;\",\"Then throughout my pilgrim journey\",\"Light will cheer me all the while.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0329', 'verse', 4, 4, '[\"Take the world, but give me Jesus;\",\"In His cross my trust shall be,\",\"Till, with clearer, brighter vision,\",\"Face to face my Lord I see.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0330', 330, 'Take My Life and Let It Be', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Take my life, and let it be
Consecrated, Lord, to Thee;
Take my hands, and let them move
At the impulse of Thy love,
At the impulse of Thy love.
Take my feet, and let them be
Swift and beautiful for Thee;
Take my voice, and let me sing
Always, only, for my King,
Always, only, for my King.
Take my lips, and let them be
Filled with messages from Thee;
Take my silver and my gold,
Not a mite would I withhold,
Not a mite would I withhold.
Take my will and make it Thine;
It shall be no longer mine;
Take my heart, it is Thine own!
It shall be Thy royal throne,
It shall be Thy royal throne.
Take my love; my Lord, I pour
At Thy feet its treasure store;
Take myself, and I will be,
Ever, only, all for Thee,
Ever, only; all for Thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0330', 'verse', 1, 0, '[\"Take my life, and let it be\",\"Consecrated, Lord, to Thee;\",\"Take my hands, and let them move\",\"At the impulse of Thy love,\",\"At the impulse of Thy love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0330', 'verse', 2, 1, '[\"Take my feet, and let them be\",\"Swift and beautiful for Thee;\",\"Take my voice, and let me sing\",\"Always, only, for my King,\",\"Always, only, for my King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0330', 'verse', 3, 2, '[\"Take my lips, and let them be\",\"Filled with messages from Thee;\",\"Take my silver and my gold,\",\"Not a mite would I withhold,\",\"Not a mite would I withhold.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0330', 'verse', 4, 3, '[\"Take my will and make it Thine;\",\"It shall be no longer mine;\",\"Take my heart, it is Thine own!\",\"It shall be Thy royal throne,\",\"It shall be Thy royal throne.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0330', 'verse', 5, 4, '[\"Take my love; my Lord, I pour\",\"At Thy feet its treasure store;\",\"Take myself, and I will be,\",\"Ever, only, all for Thee,\",\"Ever, only; all for Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0331', 331, 'O Jesus I Have Promised', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O Jesus, I have promised to serve thee to the end;
be thou forever near me, my Master and my friend.
I shall not fear the battle if thou art by my side,
nor wander from the pathway if thou wilt be my guide.
O let me feel thee near me! The world is ever near;
I see the sights that dazzle, the tempting sounds I hear;
my foes are ever near me, around me and within;
but Jesus, draw thou nearer, and shield my soul from sin.
O Jesus, thou hast promised to all who follow thee
that where thou art in glory there shall thy servant be.
And Jesus, I have promised to serve thee to the end;
O give me grace to follow, my Master and my Friend.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0331', 'verse', 1, 0, '[\"O Jesus, I have promised to serve thee to the end;\",\"be thou forever near me, my Master and my friend.\",\"I shall not fear the battle if thou art by my side,\",\"nor wander from the pathway if thou wilt be my guide.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0331', 'verse', 2, 1, '[\"O let me feel thee near me! The world is ever near;\",\"I see the sights that dazzle, the tempting sounds I hear;\",\"my foes are ever near me, around me and within;\",\"but Jesus, draw thou nearer, and shield my soul from sin.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0331', 'verse', 3, 2, '[\"O Jesus, thou hast promised to all who follow thee\",\"that where thou art in glory there shall thy servant be.\",\"And Jesus, I have promised to serve thee to the end;\",\"O give me grace to follow, my Master and my Friend.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0332', 332, 'The Cleansing Wave', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O now I see the crimson wave,
The fountain deep and wide;
Jesus, my Lord, mighty to save,
Points to His wounded side.
The cleansing stream I see, I see,
I plunge, and O, it cleanseth me!
O praise the Lord! it cleanseth me,
It cleanseth me, yes, cleanseth me.
I see the new creation rise,
I hear the speaking blood;
It speaks; polluted nature dies,
Sinks \'neath the cleansing flood.
I rise to walk in heaven\'s own light,
Above the world and sin;
With heart made pure and garments white,
And Christ enthroned within.
Amazing grace! \'tis heaven below
To feel the blood applied,
And Jesus, only Jesus, know,
My Jesus crucified.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0332', 'verse', 1, 0, '[\"O now I see the crimson wave,\",\"The fountain deep and wide;\",\"Jesus, my Lord, mighty to save,\",\"Points to His wounded side.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0332', 'chorus', 0, 1, '[\"The cleansing stream I see, I see,\",\"I plunge, and O, it cleanseth me!\",\"O praise the Lord! it cleanseth me,\",\"It cleanseth me, yes, cleanseth me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0332', 'verse', 2, 2, '[\"I see the new creation rise,\",\"I hear the speaking blood;\",\"It speaks; polluted nature dies,\",\"Sinks \'neath the cleansing flood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0332', 'verse', 3, 3, '[\"I rise to walk in heaven\'s own light,\",\"Above the world and sin;\",\"With heart made pure and garments white,\",\"And Christ enthroned within.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0332', 'verse', 4, 4, '[\"Amazing grace! \'tis heaven below\",\"To feel the blood applied,\",\"And Jesus, only Jesus, know,\",\"My Jesus crucified.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0333', 333, 'On Jordan\'s Banks the Baptist\'s Cry', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'On Jordan\'s banks the Baptist\'s cry
Announces that the Lord is nigh;
Awake and hearken, for he brings
Glad tidings of the King of kings!
Then cleansed be every life from sin;
Make straight the way for God within,
And let us all our hearts prepare
For Christ to come and enter there.
We hail You as our Savior, Lord,
Our refuge and our great reward;
Without Your grace we waste away
Like flow\'rs that wither and decay.
Stretch forth Your hand, our health restore,
And make us rise to fall no more;
Oh, let Your face upon us shine
And fill the world with love divine.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0333', 'verse', 1, 0, '[\"On Jordan\'s banks the Baptist\'s cry\",\"Announces that the Lord is nigh;\",\"Awake and hearken, for he brings\",\"Glad tidings of the King of kings!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0333', 'verse', 2, 1, '[\"Then cleansed be every life from sin;\",\"Make straight the way for God within,\",\"And let us all our hearts prepare\",\"For Christ to come and enter there.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0333', 'verse', 3, 2, '[\"We hail You as our Savior, Lord,\",\"Our refuge and our great reward;\",\"Without Your grace we waste away\",\"Like flow\'rs that wither and decay.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0333', 'verse', 4, 3, '[\"Stretch forth Your hand, our health restore,\",\"And make us rise to fall no more;\",\"Oh, let Your face upon us shine\",\"And fill the world with love divine.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0334', 334, 'Come, Thou Fount of Every Blessing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Come, Thou Fount of every blessing,
Tune my heart to sing Thy grace;
Streams of mercy, never ceasing,
Call for songs of loudest praise.
Teach me ever to adore Thee,
May I still Thy goodness prove,
While the hope of endless glory
Fills my heart with joy and love.
Here I raise my Ebenezer,
Hither by Thy help I\'ve come,
And I hope by Thy good pleasure
Safely to arrive at home.
Jesus sought me when a stranger,
Wandering from the fold of God;
He to rescue me from danger
Interposed His precious blood.
O, to grace how great a debtor
Daily I\'m constrained to be!
Let Thy goodness, like a fetter,
Bind me closer still to Thee.
Prone to wander, Lord, I feel it,
Prone to leave the God I love;
Here\'s my heart O, take and seal it;
Seal it for Thy courts above.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0334', 'verse', 1, 0, '[\"Come, Thou Fount of every blessing,\",\"Tune my heart to sing Thy grace;\",\"Streams of mercy, never ceasing,\",\"Call for songs of loudest praise.\",\"Teach me ever to adore Thee,\",\"May I still Thy goodness prove,\",\"While the hope of endless glory\",\"Fills my heart with joy and love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0334', 'verse', 2, 1, '[\"Here I raise my Ebenezer,\",\"Hither by Thy help I\'ve come,\",\"And I hope by Thy good pleasure\",\"Safely to arrive at home.\",\"Jesus sought me when a stranger,\",\"Wandering from the fold of God;\",\"He to rescue me from danger\",\"Interposed His precious blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0334', 'verse', 3, 2, '[\"O, to grace how great a debtor\",\"Daily I\'m constrained to be!\",\"Let Thy goodness, like a fetter,\",\"Bind me closer still to Thee.\",\"Prone to wander, Lord, I feel it,\",\"Prone to leave the God I love;\",\"Here\'s my heart O, take and seal it;\",\"Seal it for Thy courts above.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0335', 335, 'What a Wonderful Savior', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Christ has for sin atonement made,
What a wonderful Savior!
We are redeemed! the price is paid!
What a wonderful Savior!
What a wonderful Savior is Jesus, my Jesus!
What a wonderful Savior is Jesus, my Lord!
I praise Him for the cleansing blood,
What a wonderful Savior!
That reconciled my soul to God;
What a wonderful Savior!
He walks beside me all the way,
What a wonderful Savior!
And keeps me faithful day by day;
What a wonderful Savior!
He gives me overcoming power,
What a wonderful Savior!
And triumph in each trying hour;
What a wonderful Savior!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0335', 'verse', 1, 0, '[\"Christ has for sin atonement made,\",\"What a wonderful Savior!\",\"We are redeemed! the price is paid!\",\"What a wonderful Savior!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0335', 'chorus', 0, 1, '[\"What a wonderful Savior is Jesus, my Jesus!\",\"What a wonderful Savior is Jesus, my Lord!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0335', 'verse', 2, 2, '[\"I praise Him for the cleansing blood,\",\"What a wonderful Savior!\",\"That reconciled my soul to God;\",\"What a wonderful Savior!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0335', 'verse', 3, 3, '[\"He walks beside me all the way,\",\"What a wonderful Savior!\",\"And keeps me faithful day by day;\",\"What a wonderful Savior!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0335', 'verse', 4, 4, '[\"He gives me overcoming power,\",\"What a wonderful Savior!\",\"And triumph in each trying hour;\",\"What a wonderful Savior!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0336', 336, 'There Is a Fountain', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'There is a fountain filled with blood,
Drawn from Immanuel\'s veins;
And sinners plunged beneath that flood,
Lose all their guilty stains
Lose all their guilty stains,
Lose all their guilty stains;
And sinners plunged beneath that flood,
Lose all their guilty stains.
The dying thief rejoiced to see
That fountain in his day;
And there may I, though vile as he,
Wash all my sins away,
Wash all my sins away,
Wash all my sins away;
And there may I, though vile as he,
Wash all my sins away.
Thou dying Lamb! Thy precious blood
Shall never lose its power
Till all the ransomed church of God
Are saved, to sin no more,
Are saved, to sin no more,
Are saved, to sin no more;
Till all the ransomed church of God
Are saved, to sin no more.
E\'er since by faith I saw the stream
Thy flowing wounds supply,
Redeeming love has been my theme,
And shall be till I die,
And shall be till I die,
And shall be till I die;
Redeeming love has been my theme,
And shall be till I die.
Lord, I believe Thou hast prepared,
Unworthy though I be,
For me a blood-bought, free reward,
A golden harp for me!
A golden harp for me!
A golden harp for me!
For me a blood-bought, free reward,
A golden harp for me!
There in a nobler, sweeter song,
I\'ll sing Thy power to save,
When this poor lisping, stammering tongue
Is ransomed from the grave,
Is ransomed from the grave,
Is ransomed from the grave;
When this poor lisping, stammering tongue
Is ransomed from the grave.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0336', 'verse', 1, 0, '[\"There is a fountain filled with blood,\",\"Drawn from Immanuel\'s veins;\",\"And sinners plunged beneath that flood,\",\"Lose all their guilty stains\",\"Lose all their guilty stains,\",\"Lose all their guilty stains;\",\"And sinners plunged beneath that flood,\",\"Lose all their guilty stains.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0336', 'verse', 2, 1, '[\"The dying thief rejoiced to see\",\"That fountain in his day;\",\"And there may I, though vile as he,\",\"Wash all my sins away,\",\"Wash all my sins away,\",\"Wash all my sins away;\",\"And there may I, though vile as he,\",\"Wash all my sins away.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0336', 'verse', 3, 2, '[\"Thou dying Lamb! Thy precious blood\",\"Shall never lose its power\",\"Till all the ransomed church of God\",\"Are saved, to sin no more,\",\"Are saved, to sin no more,\",\"Are saved, to sin no more;\",\"Till all the ransomed church of God\",\"Are saved, to sin no more.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0336', 'verse', 4, 3, '[\"E\'er since by faith I saw the stream\",\"Thy flowing wounds supply,\",\"Redeeming love has been my theme,\",\"And shall be till I die,\",\"And shall be till I die,\",\"And shall be till I die;\",\"Redeeming love has been my theme,\",\"And shall be till I die.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0336', 'verse', 5, 4, '[\"Lord, I believe Thou hast prepared,\",\"Unworthy though I be,\",\"For me a blood-bought, free reward,\",\"A golden harp for me!\",\"A golden harp for me!\",\"A golden harp for me!\",\"For me a blood-bought, free reward,\",\"A golden harp for me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0336', 'verse', 6, 5, '[\"There in a nobler, sweeter song,\",\"I\'ll sing Thy power to save,\",\"When this poor lisping, stammering tongue\",\"Is ransomed from the grave,\",\"Is ransomed from the grave,\",\"Is ransomed from the grave;\",\"When this poor lisping, stammering tongue\",\"Is ransomed from the grave.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0337', 337, 'Redeemed!', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Redeemed! how I love to proclaim it!
Redeemed by the blood of the Lamb;
Redeemed through His infinite mercy,
His child, and forever, I am.
Redeemed, redeemed,
Redeemed by the blood of the Lamb;
Redeemed, redeemed,
His child, and forever, I am.
Redeemed! and so happy in Jesus!
No language my rapture can tell;
I know that the light of His presence
With me doth continually dwell.
I know there\'s a crown that is waiting
In yonder bright mansion for me;
And soon, with the saints made perfect,
At home with the Lord I shall be.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0337', 'verse', 1, 0, '[\"Redeemed! how I love to proclaim it!\",\"Redeemed by the blood of the Lamb;\",\"Redeemed through His infinite mercy,\",\"His child, and forever, I am.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0337', 'chorus', 0, 1, '[\"Redeemed, redeemed,\",\"Redeemed by the blood of the Lamb;\",\"Redeemed, redeemed,\",\"His child, and forever, I am.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0337', 'verse', 2, 2, '[\"Redeemed! and so happy in Jesus!\",\"No language my rapture can tell;\",\"I know that the light of His presence\",\"With me doth continually dwell.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0337', 'verse', 3, 3, '[\"I know there\'s a crown that is waiting\",\"In yonder bright mansion for me;\",\"And soon, with the saints made perfect,\",\"At home with the Lord I shall be.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0338', 338, 'Redeemed', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Redeemed, how I love to proclaim it!
Redeemed by the blood of the Lamb;
Redeemed thro\' His infinite mercy,
His child, and forever, I am.
Redeemed, redeemed,
Redeemed by the blood of the Lamb;
Redeemed, how I love to proclaim it!
His child and forever I am.
I think of my blessed Redeemer,
I think of Him all the day long;
I sing, for I cannot be silent;
His love is the theme of my song.
I know I shall see in His beauty
The King in whose law I delight,
Who lovingly guardeth my footsteps,
And giveth me songs in the night.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0338', 'verse', 1, 0, '[\"Redeemed, how I love to proclaim it!\",\"Redeemed by the blood of the Lamb;\",\"Redeemed thro\' His infinite mercy,\",\"His child, and forever, I am.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0338', 'chorus', 0, 1, '[\"Redeemed, redeemed,\",\"Redeemed by the blood of the Lamb;\",\"Redeemed, how I love to proclaim it!\",\"His child and forever I am.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0338', 'verse', 2, 2, '[\"I think of my blessed Redeemer,\",\"I think of Him all the day long;\",\"I sing, for I cannot be silent;\",\"His love is the theme of my song.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0338', 'verse', 3, 3, '[\"I know I shall see in His beauty\",\"The King in whose law I delight,\",\"Who lovingly guardeth my footsteps,\",\"And giveth me songs in the night.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0339', 339, 'God Is My Strong Salvation', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'God is my strong salvation,
What foe have I to fear?
In darkness and temptation,
My Light, my Help, is near:
Though hosts encamp around me,
Firm in the fight I stand;
What terror can confound me,
With God at my right hand?
Place on the Lord reliance;
My soul with courage wait;
His truth be thine affiance,
When faint and desolate.
His might thy heart shall strengthen,
His love thy joy increase;
Mercy thy days shall lengthen;
The Lord will give thee peace.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0339', 'verse', 1, 0, '[\"God is my strong salvation,\",\"What foe have I to fear?\",\"In darkness and temptation,\",\"My Light, my Help, is near:\",\"Though hosts encamp around me,\",\"Firm in the fight I stand;\",\"What terror can confound me,\",\"With God at my right hand?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0339', 'verse', 2, 1, '[\"Place on the Lord reliance;\",\"My soul with courage wait;\",\"His truth be thine affiance,\",\"When faint and desolate.\",\"His might thy heart shall strengthen,\",\"His love thy joy increase;\",\"Mercy thy days shall lengthen;\",\"The Lord will give thee peace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0340', 340, 'Jesus Saves', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'We have heard a joyful sound,
Jesus saves, Jesus saves;
Spread the gladness all around,
Jesus saves, Jesus saves;
Bear the news to every land,
Climb the steeps and cross the waves,
Onward, \'tis our Lord\'s command,
Jesus saves, Jesus saves.
Waft it on the rolling tide,
Jesus saves, Jesus saves;
Tell to sinners, far and wide,
Jesus saves, Jesus saves;
Sing, ye islands of the sea.
Echo back, ye ocean caves,
Earth shall keep her jubilee,
Jesus saves, Jesus saves.
Sing above the battle\'s strife,
Jesus saves, Jesus saves;
By His death and endless life,
Jesus saves, Jesus saves;
Sing it softly through the gloom,
When the heart for mercy craves,
Sing in triumph o\'er the tomb,
Jesus saves, Jesus saves.
Give the winds a mighty voice,
Jesus saves, Jesus saves;
Let the nations now rejoice,
Jesus saves, Jesus saves;
Shout salvation full and free,
Highest hills and deepest caves,
This our song of victory,
Jesus saves, Jesus saves.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0340', 'verse', 1, 0, '[\"We have heard a joyful sound,\",\"Jesus saves, Jesus saves;\",\"Spread the gladness all around,\",\"Jesus saves, Jesus saves;\",\"Bear the news to every land,\",\"Climb the steeps and cross the waves,\",\"Onward, \'tis our Lord\'s command,\",\"Jesus saves, Jesus saves.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0340', 'verse', 2, 1, '[\"Waft it on the rolling tide,\",\"Jesus saves, Jesus saves;\",\"Tell to sinners, far and wide,\",\"Jesus saves, Jesus saves;\",\"Sing, ye islands of the sea.\",\"Echo back, ye ocean caves,\",\"Earth shall keep her jubilee,\",\"Jesus saves, Jesus saves.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0340', 'verse', 3, 2, '[\"Sing above the battle\'s strife,\",\"Jesus saves, Jesus saves;\",\"By His death and endless life,\",\"Jesus saves, Jesus saves;\",\"Sing it softly through the gloom,\",\"When the heart for mercy craves,\",\"Sing in triumph o\'er the tomb,\",\"Jesus saves, Jesus saves.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0340', 'verse', 4, 3, '[\"Give the winds a mighty voice,\",\"Jesus saves, Jesus saves;\",\"Let the nations now rejoice,\",\"Jesus saves, Jesus saves;\",\"Shout salvation full and free,\",\"Highest hills and deepest caves,\",\"This our song of victory,\",\"Jesus saves, Jesus saves.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0341', 341, 'To God Be the Glory', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'To God be the glory, great things He hath done;
So loved He the world that He gave us His Son,
Who yielded His life an atonement for sin,
And opened the life gate that all may go in.
Praise the Lord, praise the Lord,
Let the earth hear His voice;
Praise the Lord, praise, the Lord,
Let the people rejoice;
O come to the Father, through Jesus the Son,
And give Him the glory, great things He hath done.
O perfect redemption, the purchase of blood,
To every believer the promise of God;
The vilest offender who truly believes,
That moment from Jesus a pardon receives.
Great things He hath taught us, great things He hath done,
And great our rejoicing through Jesus the Son;
But purer, and higher, and greater will be
Our wonder, our transport, when Jesus we see.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0341', 'verse', 1, 0, '[\"To God be the glory, great things He hath done;\",\"So loved He the world that He gave us His Son,\",\"Who yielded His life an atonement for sin,\",\"And opened the life gate that all may go in.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0341', 'chorus', 0, 1, '[\"Praise the Lord, praise the Lord,\",\"Let the earth hear His voice;\",\"Praise the Lord, praise, the Lord,\",\"Let the people rejoice;\",\"O come to the Father, through Jesus the Son,\",\"And give Him the glory, great things He hath done.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0341', 'verse', 2, 2, '[\"O perfect redemption, the purchase of blood,\",\"To every believer the promise of God;\",\"The vilest offender who truly believes,\",\"That moment from Jesus a pardon receives.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0341', 'verse', 3, 3, '[\"Great things He hath taught us, great things He hath done,\",\"And great our rejoicing through Jesus the Son;\",\"But purer, and higher, and greater will be\",\"Our wonder, our transport, when Jesus we see.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0342', 342, 'Is This A Day of New Beginnings', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Is this a day of new beginnings,
Time to remember and move on,
Time to believe what love is bringing,
Laying to rest the pain that\'s gone?
How can the seasons of a planet
Mindlessly spinning round its sun
With just a human name and number
Say that some new thing has begun?
Yet thro\' the life and death of Jesus
Love\'s mighty Spirit, now as then,
Can make for us a world of difference
As faith and hope are born again.
Then let us, with the Spirit\'s daring,
Step from the past and leave behind
Its disappointment, guilt, and grieving,
Seeking new paths, and sure to find.
Christ is alive, and goes before us
To show and share what love can do.
This is a day of new beginnings;
Our God is making all things new.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0342', 'verse', 1, 0, '[\"Is this a day of new beginnings,\",\"Time to remember and move on,\",\"Time to believe what love is bringing,\",\"Laying to rest the pain that\'s gone?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0342', 'verse', 2, 1, '[\"How can the seasons of a planet\",\"Mindlessly spinning round its sun\",\"With just a human name and number\",\"Say that some new thing has begun?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0342', 'verse', 3, 2, '[\"Yet thro\' the life and death of Jesus\",\"Love\'s mighty Spirit, now as then,\",\"Can make for us a world of difference\",\"As faith and hope are born again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0342', 'verse', 4, 3, '[\"Then let us, with the Spirit\'s daring,\",\"Step from the past and leave behind\",\"Its disappointment, guilt, and grieving,\",\"Seeking new paths, and sure to find.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0342', 'verse', 5, 4, '[\"Christ is alive, and goes before us\",\"To show and share what love can do.\",\"This is a day of new beginnings;\",\"Our God is making all things new.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0343', 343, 'I Will Sing of My Redeemer', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I will sing of my Redeemer,
And His wondrous love to me;
On the cruel cross He suffered');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0343', 'verse', 1, 0, '[\"I will sing of my Redeemer,\",\"And His wondrous love to me;\",\"On the cruel cross He suffered\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0344', 344, 'I Love Your Kingdom, Lord', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I love Your kingdom, Lord,
The house of Your abode,
The Church our blest Redeemer saved
With His own precious blood.
I love Your Church, O God!
Her walls before Thee stand
Dear as the apple of Thine eye,
And graven on Thy hand.
Beyond my highest joy
I prize its heavenly ways,
Its sweet communion, solemn vows,
Its hymns of love and praise.
Sure as Your truth shall last,
To Zion shall be given
The brightest glories earth can yield,
And brighter bliss of heaven.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0344', 'verse', 1, 0, '[\"I love Your kingdom, Lord,\",\"The house of Your abode,\",\"The Church our blest Redeemer saved\",\"With His own precious blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0344', 'verse', 2, 1, '[\"I love Your Church, O God!\",\"Her walls before Thee stand\",\"Dear as the apple of Thine eye,\",\"And graven on Thy hand.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0344', 'verse', 3, 2, '[\"Beyond my highest joy\",\"I prize its heavenly ways,\",\"Its sweet communion, solemn vows,\",\"Its hymns of love and praise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0344', 'verse', 4, 3, '[\"Sure as Your truth shall last,\",\"To Zion shall be given\",\"The brightest glories earth can yield,\",\"And brighter bliss of heaven.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0345', 345, 'Christ Is the World\'s True Light', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'In Christ all races meet,
Their ancient feuds forgetting,
The whole round world complete,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0345', 'verse', 1, 0, '[\"In Christ all races meet,\",\"Their ancient feuds forgetting,\",\"The whole round world complete,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0346', 346, 'Lord Who Dost Give to Thy Church', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lord, who dost give to Thy church for its healing
Gifts, and the grace to sustain and renew,
Hear as we pray that today and each morrow
We to Thy purpose may show ourselves true.
Clear be the voices of preachers and prophets
Fearlessly speaking the word of the Lord,
Word of redemption thro\' God\'s Son incarnate,
Blessing for cursing, and peace for the sword.
Tender and wise be the hearts of the pastors,
Guiding and guarding the souls in their care,
Firm with the wayward, a strength to the doubting,
Helping the needy their burdens to bear.
May those who teach grow in knowledge and patience,
Guiding to wisdom the young and the old,
Training for worship and witness and service,
Foes to all falsehood, in truthfulness bold.
Lord, ever give to us gifts in due measure,
Each needing other, and all having worth;
So to the Father, the Son, and the Spirit,
Glory be shown by the church here on earth.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0346', 'verse', 1, 0, '[\"Lord, who dost give to Thy church for its healing\",\"Gifts, and the grace to sustain and renew,\",\"Hear as we pray that today and each morrow\",\"We to Thy purpose may show ourselves true.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0346', 'verse', 2, 1, '[\"Clear be the voices of preachers and prophets\",\"Fearlessly speaking the word of the Lord,\",\"Word of redemption thro\' God\'s Son incarnate,\",\"Blessing for cursing, and peace for the sword.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0346', 'verse', 3, 2, '[\"Tender and wise be the hearts of the pastors,\",\"Guiding and guarding the souls in their care,\",\"Firm with the wayward, a strength to the doubting,\",\"Helping the needy their burdens to bear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0346', 'verse', 4, 3, '[\"May those who teach grow in knowledge and patience,\",\"Guiding to wisdom the young and the old,\",\"Training for worship and witness and service,\",\"Foes to all falsehood, in truthfulness bold.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0346', 'verse', 5, 4, '[\"Lord, ever give to us gifts in due measure,\",\"Each needing other, and all having worth;\",\"So to the Father, the Son, and the Spirit,\",\"Glory be shown by the church here on earth.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0347', 347, 'Built On the Rock', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Built on the Rock the Church shall stand,
Even when steeples are falling;
Crumbled have spires in every land,
Bells still are chiming and calling-
Calling the young and old to rest,
Calling the souls of those distressed,
Longing for life everlasting.
Not in our temples made with hands
God, the Almighty, is dwelling;
High in the heav\'ns His temple stands,
All earthly temples excelling.
Yet He who dwells in heav\'n above
Deigns to abide with us in love,
Making our bodies His temple.
We are God\'s house of living stones,
Built for His own habitation;
He fills our hearts, His humble thrones,
Granting us life and salvation.
Were two or three to seek His face,
He in their midst would show His grace,
Blessings upon them bestowing.
Yet in this house, an earthly frame,
Jesus His children is blessing;
Hither we come to praise His name,
Faith in our Savior confessing.
Jesus to us His Spirit sent,
Making with us His covenant,
Granting His children the kingdom.
Thro\' all the passing years, O Lord,
Grant that, when church bells are ringing,
Many may come to hear God\'s Word
Where He this promise is bringing:
I know My own, My own know Me:
You, not the world, My face shall see;
My peace I leave with you. Amen.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0347', 'verse', 1, 0, '[\"Built on the Rock the Church shall stand,\",\"Even when steeples are falling;\",\"Crumbled have spires in every land,\",\"Bells still are chiming and calling-\",\"Calling the young and old to rest,\",\"Calling the souls of those distressed,\",\"Longing for life everlasting.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0347', 'verse', 2, 1, '[\"Not in our temples made with hands\",\"God, the Almighty, is dwelling;\",\"High in the heav\'ns His temple stands,\",\"All earthly temples excelling.\",\"Yet He who dwells in heav\'n above\",\"Deigns to abide with us in love,\",\"Making our bodies His temple.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0347', 'verse', 3, 2, '[\"We are God\'s house of living stones,\",\"Built for His own habitation;\",\"He fills our hearts, His humble thrones,\",\"Granting us life and salvation.\",\"Were two or three to seek His face,\",\"He in their midst would show His grace,\",\"Blessings upon them bestowing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0347', 'verse', 4, 3, '[\"Yet in this house, an earthly frame,\",\"Jesus His children is blessing;\",\"Hither we come to praise His name,\",\"Faith in our Savior confessing.\",\"Jesus to us His Spirit sent,\",\"Making with us His covenant,\",\"Granting His children the kingdom.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0347', 'verse', 5, 4, '[\"Thro\' all the passing years, O Lord,\",\"Grant that, when church bells are ringing,\",\"Many may come to hear God\'s Word\",\"Where He this promise is bringing:\",\"I know My own, My own know Me:\",\"You, not the world, My face shall see;\",\"My peace I leave with you. Amen.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0348', 348, 'The Church Has One Foundation', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'The church has one foundation,
\'Tis Jesus Christ her Lord;
She is His new creation,
By water and the word;');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0348', 'verse', 1, 0, '[\"The church has one foundation,\",\"\'Tis Jesus Christ her Lord;\",\"She is His new creation,\",\"By water and the word;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0349', 349, 'God Is Love', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'God is love, and where true love is
God Himself is there.
Here in Christ we gather, love of Christ our calling.
Christ, our love, is with us, gladness be His greeting.
Let us fear Him, yes, and love Him, God eternal.
Loving Him, let each love Christ in all his brethren.
When we Christians gather, members of one body,
Let there be in us no discord but one spirit.
Banished now be anger, strife, and every quarrel.
Christ, our God, be always present here among us.
Grant us love\'s fulfillment, joy with all the blessed,
When we see Your face, O Savior, in its glory.
Shine on us, O purest Light of all creation,
Be our bliss while endless ages sing Your praises.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0349', 'chorus', 0, 0, '[\"God is love, and where true love is\",\"God Himself is there.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0349', 'verse', 1, 1, '[\"Here in Christ we gather, love of Christ our calling.\",\"Christ, our love, is with us, gladness be His greeting.\",\"Let us fear Him, yes, and love Him, God eternal.\",\"Loving Him, let each love Christ in all his brethren.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0349', 'verse', 2, 2, '[\"When we Christians gather, members of one body,\",\"Let there be in us no discord but one spirit.\",\"Banished now be anger, strife, and every quarrel.\",\"Christ, our God, be always present here among us.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0349', 'verse', 3, 3, '[\"Grant us love\'s fulfillment, joy with all the blessed,\",\"When we see Your face, O Savior, in its glory.\",\"Shine on us, O purest Light of all creation,\",\"Be our bliss while endless ages sing Your praises.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0350', 350, 'Blest Be the Tie That Binds', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Blest be the tie that binds
Our hearts in Christian love!
The fellowship of kindred minds
Is like to that above.
Before our Father\'s throne
We pour our ardent prayers;
Our fears, our hopes, our aims are one,
Our comforts, and our cares.
We share our mutual woes,
Our mutual burdens bear,
And often for each other flows
The sympathizing tear.
When we asunder part,
It gives us inward pain;
But we shall still be joined in heart,
And hope to meet again.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0350', 'verse', 1, 0, '[\"Blest be the tie that binds\",\"Our hearts in Christian love!\",\"The fellowship of kindred minds\",\"Is like to that above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0350', 'verse', 2, 1, '[\"Before our Father\'s throne\",\"We pour our ardent prayers;\",\"Our fears, our hopes, our aims are one,\",\"Our comforts, and our cares.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0350', 'verse', 3, 2, '[\"We share our mutual woes,\",\"Our mutual burdens bear,\",\"And often for each other flows\",\"The sympathizing tear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0350', 'verse', 4, 3, '[\"When we asunder part,\",\"It gives us inward pain;\",\"But we shall still be joined in heart,\",\"And hope to meet again.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0351', 351, 'Thy Hand, O God Has Guided', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Thy hand, O God, has guided
Thy flock from age to age;
The wondrous tale is written
Full clear on every page;
Our fathers owned Thy goodness,
And we their deeds record;
And both of this bear witness,
One Church, one faith, one Lord.
Thy heralds brought glad tidings
To greatest as to least;
They bade men rise and hasten
To share the great King\'s feast:
And this was all their teaching,
In every deed and word,
To all alike proclaiming
One Church, one faith, one Lord.
When shadows thick were falling,
And all seemed sunk in night,
Thou, Lord, did send Thy servants,
Thy chosen sons of light.
On them and on Thy people
Thy plenteous grace was poured,
And this was still their message:
One Church, one faith, one Lord.
Thy mercy will not fail us,
Nor leave Thy work undone;
With Thy right hand to help us,
The vict\'ry shall be won;
And then by men and angels
Thy name shall be adored,
And this shall be their anthem:
One Church, one faith, one Lord.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0351', 'verse', 1, 0, '[\"Thy hand, O God, has guided\",\"Thy flock from age to age;\",\"The wondrous tale is written\",\"Full clear on every page;\",\"Our fathers owned Thy goodness,\",\"And we their deeds record;\",\"And both of this bear witness,\",\"One Church, one faith, one Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0351', 'verse', 2, 1, '[\"Thy heralds brought glad tidings\",\"To greatest as to least;\",\"They bade men rise and hasten\",\"To share the great King\'s feast:\",\"And this was all their teaching,\",\"In every deed and word,\",\"To all alike proclaiming\",\"One Church, one faith, one Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0351', 'verse', 3, 2, '[\"When shadows thick were falling,\",\"And all seemed sunk in night,\",\"Thou, Lord, did send Thy servants,\",\"Thy chosen sons of light.\",\"On them and on Thy people\",\"Thy plenteous grace was poured,\",\"And this was still their message:\",\"One Church, one faith, one Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0351', 'verse', 4, 3, '[\"Thy mercy will not fail us,\",\"Nor leave Thy work undone;\",\"With Thy right hand to help us,\",\"The vict\'ry shall be won;\",\"And then by men and angels\",\"Thy name shall be adored,\",\"And this shall be their anthem:\",\"One Church, one faith, one Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0352', 352, 'This Is My Will', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'This is My will, My one command,
That love should dwell among you all.
This is My will that you should love
As I have shown that I love you.
No greater love a man can have
Than that he die to save his friends.
You are My friends if you obey
What I command that you should do.
You chose not Me, but I chose you
That you should go and bear much fruit.
I chose you out that you in Me
Should bear much fruit that will abide.
All that I ask My Father, dear,
For My name\'s sake you shall receive.
This is My will, My one command,
That love should dwell in each, in all.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0352', 'verse', 1, 0, '[\"This is My will, My one command,\",\"That love should dwell among you all.\",\"This is My will that you should love\",\"As I have shown that I love you.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0352', 'verse', 2, 1, '[\"No greater love a man can have\",\"Than that he die to save his friends.\",\"You are My friends if you obey\",\"What I command that you should do.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0352', 'verse', 3, 2, '[\"You chose not Me, but I chose you\",\"That you should go and bear much fruit.\",\"I chose you out that you in Me\",\"Should bear much fruit that will abide.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0352', 'verse', 4, 3, '[\"All that I ask My Father, dear,\",\"For My name\'s sake you shall receive.\",\"This is My will, My one command,\",\"That love should dwell in each, in all.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0353', 353, 'Father Help Your People', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Father, help Your people in this world to build
Something of Your kingdom and to do Your will,
Lead us to discover partnership in love;
Bless our ways of sharing and our pride remove.
Lord of desk and altar, bind our lives in one,
That in work and worship love may set the tone.
Give us grace to listen, clarity of speech;
Make us truly thankful for the gifts of each.
Holy is the setting of each room and yard,
Lecture hall and kitchen, office, shop, and ward.
Holy is the rhythm of our working hours;
Hallow then our purpose, energy, and pow\'rs.
Strengthen, Lord, for service hand and heart and brain;
Help us good relations daily to maintain.
Let the living presence of the servant Christ
Heighten our devotion, make our life a feast.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0353', 'verse', 1, 0, '[\"Father, help Your people in this world to build\",\"Something of Your kingdom and to do Your will,\",\"Lead us to discover partnership in love;\",\"Bless our ways of sharing and our pride remove.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0353', 'verse', 2, 1, '[\"Lord of desk and altar, bind our lives in one,\",\"That in work and worship love may set the tone.\",\"Give us grace to listen, clarity of speech;\",\"Make us truly thankful for the gifts of each.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0353', 'verse', 3, 2, '[\"Holy is the setting of each room and yard,\",\"Lecture hall and kitchen, office, shop, and ward.\",\"Holy is the rhythm of our working hours;\",\"Hallow then our purpose, energy, and pow\'rs.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0353', 'verse', 4, 3, '[\"Strengthen, Lord, for service hand and heart and brain;\",\"Help us good relations daily to maintain.\",\"Let the living presence of the servant Christ\",\"Heighten our devotion, make our life a feast.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0354', 354, 'Thy Love O God', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Thy love, O God, has all mankind created,
And led Thy people to this present hour;
In Christ we see life\'s glory consummated;
Thy Spirit manifests His living power.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0354', 'verse', 1, 0, '[\"Thy love, O God, has all mankind created,\",\"And led Thy people to this present hour;\",\"In Christ we see life\'s glory consummated;\",\"Thy Spirit manifests His living power.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0355', 355, 'Where Cross the Crowded Ways of Life', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Where cross the crowded ways of life,
Where sound the cries of race and clan,
Above the noise of selfish strife,
We hear Your voice, O Son of Man.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0355', 'verse', 1, 0, '[\"Where cross the crowded ways of life,\",\"Where sound the cries of race and clan,\",\"Above the noise of selfish strife,\",\"We hear Your voice, O Son of Man.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0356', 356, 'All Who Love and Serve Youre City', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'All who love and serve your city,
All who bear its daily stress,
All who cry for peace and justice,
All who curse and all who bless.
In your day of loss and sorrow,
In your day of helpless strife,
Honor, peace, and love retreating,
Seek the Lord, who is your life.
For all days are days of judgment,
And the Lord is waiting still,
Drawing near His friends who spurn Him,
Off\'ring peace from Calv\'ry\'s hill.
Risen Lord, shall yet the city
Be the city of despair?
Come today, our judge, our glory;
Be its name \"The Lord is there!\"');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0356', 'verse', 1, 0, '[\"All who love and serve your city,\",\"All who bear its daily stress,\",\"All who cry for peace and justice,\",\"All who curse and all who bless.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0356', 'verse', 2, 1, '[\"In your day of loss and sorrow,\",\"In your day of helpless strife,\",\"Honor, peace, and love retreating,\",\"Seek the Lord, who is your life.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0356', 'verse', 3, 2, '[\"For all days are days of judgment,\",\"And the Lord is waiting still,\",\"Drawing near His friends who spurn Him,\",\"Off\'ring peace from Calv\'ry\'s hill.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0356', 'verse', 4, 3, '[\"Risen Lord, shall yet the city\",\"Be the city of despair?\",\"Come today, our judge, our glory;\",\"Be its name \\\"The Lord is there!\\\"\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0357', 357, 'Come, Labor On', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Come, labor on.
Who dares stand idle on the harvest plain
While all around him waves the golden grain?
And to each servant does the Master say,
\"Go work today.\"
Come, labor on.
Claim the high calling angels cannot share;
To young and old the gospel gladness bear;
Redeem the time; its hours too swiftly fly.
The night draws nigh.
Come, labor on.
No time for rest; till glows the western sky,
Till the long shadows o\'er our pathway lie,
And a glad sound comes with the setting sun,
\"Well done, well done!\"');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0357', 'verse', 1, 0, '[\"Come, labor on.\",\"Who dares stand idle on the harvest plain\",\"While all around him waves the golden grain?\",\"And to each servant does the Master say,\",\"\\\"Go work today.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0357', 'verse', 2, 1, '[\"Come, labor on.\",\"Claim the high calling angels cannot share;\",\"To young and old the gospel gladness bear;\",\"Redeem the time; its hours too swiftly fly.\",\"The night draws nigh.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0357', 'verse', 3, 2, '[\"Come, labor on.\",\"No time for rest; till glows the western sky,\",\"Till the long shadows o\'er our pathway lie,\",\"And a glad sound comes with the setting sun,\",\"\\\"Well done, well done!\\\"\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0358', 358, 'Far and Near the Fields Are Teeming', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Far and near the fields are teeming
With the sheaves of ripened grain;
Far and near their gold is gleaming
O\'er the sunny slope and plain.
Lord of harvest, send forth reapers!
Hear us, Lord, to Thee we cry;
Send them now the sheaves to gather,
Ere the harvest-time pass by.
Send them forth with morn\'s first beaming,
Send them in the noontide\'s glare;
When the sun\'s last rays are streaming,
Bid them gather everywhere.
O thou, whom thy Lord is sending,
Gather now the sheaves of gold;
Heavenward then at evening wending
Thou shalt come with joy untold.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0358', 'verse', 1, 0, '[\"Far and near the fields are teeming\",\"With the sheaves of ripened grain;\",\"Far and near their gold is gleaming\",\"O\'er the sunny slope and plain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0358', 'chorus', 0, 1, '[\"Lord of harvest, send forth reapers!\",\"Hear us, Lord, to Thee we cry;\",\"Send them now the sheaves to gather,\",\"Ere the harvest-time pass by.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0358', 'verse', 2, 2, '[\"Send them forth with morn\'s first beaming,\",\"Send them in the noontide\'s glare;\",\"When the sun\'s last rays are streaming,\",\"Bid them gather everywhere.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0358', 'verse', 3, 3, '[\"O thou, whom thy Lord is sending,\",\"Gather now the sheaves of gold;\",\"Heavenward then at evening wending\",\"Thou shalt come with joy untold.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0359', 359, 'Hark! the Voice of Jesus Calling', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Hark! the voice of Jesus calling,
\"Who will go and work today?
Fields are white, the harvest waiting,
Who will bear the sheaves away?\"
Loud and long the Master calleth,
Rich reward He offers free;
Who will answer, gladly saying,
\"Here am I, O Lord, send me\"?
If you cannot cross the ocean
And the heathen lands explore,
You can find the heathen nearer,
You can help them at your door;
If you cannot speak like angels,
If you cannot preach like Paul,
You can tell the love of Jesus,
You can say He died for all.
If you cannot be the watchman,
Standing high on Zion\'s wall,
Pointing out the path to heaven,
Offering life and peace to all;
With your prayers and with your bounties
You can do what Heaven demands,
You can be like faithful Aaron,
Holding up the prophet\'s hands.
While the souls of men are dying,
And the Master calls for you,
Let none hear you idly saying,
\"There is nothing I can do!\"
Gladly take the task He gives you,
Let His work your pleasure be;
Answer quickly when He calleth,
\"Here am I, O Lord, send me.\"');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0359', 'verse', 1, 0, '[\"Hark! the voice of Jesus calling,\",\"\\\"Who will go and work today?\",\"Fields are white, the harvest waiting,\",\"Who will bear the sheaves away?\\\"\",\"Loud and long the Master calleth,\",\"Rich reward He offers free;\",\"Who will answer, gladly saying,\",\"\\\"Here am I, O Lord, send me\\\"?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0359', 'verse', 2, 1, '[\"If you cannot cross the ocean\",\"And the heathen lands explore,\",\"You can find the heathen nearer,\",\"You can help them at your door;\",\"If you cannot speak like angels,\",\"If you cannot preach like Paul,\",\"You can tell the love of Jesus,\",\"You can say He died for all.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0359', 'verse', 3, 2, '[\"If you cannot be the watchman,\",\"Standing high on Zion\'s wall,\",\"Pointing out the path to heaven,\",\"Offering life and peace to all;\",\"With your prayers and with your bounties\",\"You can do what Heaven demands,\",\"You can be like faithful Aaron,\",\"Holding up the prophet\'s hands.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0359', 'verse', 4, 3, '[\"While the souls of men are dying,\",\"And the Master calls for you,\",\"Let none hear you idly saying,\",\"\\\"There is nothing I can do!\\\"\",\"Gladly take the task He gives you,\",\"Let His work your pleasure be;\",\"Answer quickly when He calleth,\",\"\\\"Here am I, O Lord, send me.\\\"\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0360', 360, 'From the Eastern Mountains', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, '');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0361', 361, 'Hark! \'Tis the Shepherd\'s Voice I Hear', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Hark! \'tis the Shepherd\'s voice I hear,
Out in the desert dark and drear,
Calling the sheep who\'ve gone astray,
Far from the Shepherd\'s fold away.
Bring them in,
Bring them in,
Bring them in from the fields of sin,
Bring them in,
Bring them in,
Bring the wanderers to Jesus.
Who\'ll go and help the Shepherd kind,
Help Him the wandering ones to find?
Who\'ll bring them back into the fold,
Where they\'ll be sheltered from the cold?
Out in the desert hear their cry,
Out on the mountain wild and high,
Hark! \'tis the Master speaks to thee,
\"Go, find My sheep where\'er they be.\"');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0361', 'verse', 1, 0, '[\"Hark! \'tis the Shepherd\'s voice I hear,\",\"Out in the desert dark and drear,\",\"Calling the sheep who\'ve gone astray,\",\"Far from the Shepherd\'s fold away.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0361', 'chorus', 0, 1, '[\"Bring them in,\",\"Bring them in,\",\"Bring them in from the fields of sin,\",\"Bring them in,\",\"Bring them in,\",\"Bring the wanderers to Jesus.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0361', 'verse', 2, 2, '[\"Who\'ll go and help the Shepherd kind,\",\"Help Him the wandering ones to find?\",\"Who\'ll bring them back into the fold,\",\"Where they\'ll be sheltered from the cold?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0361', 'verse', 3, 3, '[\"Out in the desert hear their cry,\",\"Out on the mountain wild and high,\",\"Hark! \'tis the Master speaks to thee,\",\"\\\"Go, find My sheep where\'er they be.\\\"\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0362', 362, 'Lift High the Cross', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lift high the Cross, the love of Christ proclaim,
Till all the world adore His sacred name.
Come, Christians, follow where our Captain trod,
Our King victorious, Christ, the Son of God.
Led on their way by this triumphant sign,
The hosts of God in conqu\'ring ranks combine.
All newborn soldiers of the Crucified
Bear on their brows the seal of Him who died.
O Lord, once lifted on the glorious tree,
As Thou hast promised, draw men unto Thee.
So shall our song of triumph ever be:
Praise to the Crucified for victory!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0362', 'chorus', 0, 0, '[\"Lift high the Cross, the love of Christ proclaim,\",\"Till all the world adore His sacred name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0362', 'verse', 1, 1, '[\"Come, Christians, follow where our Captain trod,\",\"Our King victorious, Christ, the Son of God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0362', 'verse', 2, 2, '[\"Led on their way by this triumphant sign,\",\"The hosts of God in conqu\'ring ranks combine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0362', 'verse', 3, 3, '[\"All newborn soldiers of the Crucified\",\"Bear on their brows the seal of Him who died.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0362', 'verse', 4, 4, '[\"O Lord, once lifted on the glorious tree,\",\"As Thou hast promised, draw men unto Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0362', 'verse', 5, 5, '[\"So shall our song of triumph ever be:\",\"Praise to the Crucified for victory!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0363', 363, 'Lord, Whose Love In Humble Service', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lord, whose love in humble service
Bore the weight of human need,
Who upon the cross, forsaken,
Worked Your mercy\'s perfect deed:
We, Your servants, bring the worship
Not of voice alone, but heart;
Consecrating to Your purpose
Every gift which You impart.
Still Your children wander homeless;
Still the hungry cry for bread;
Still the captives long for freedom;
Still in grief we mourn our dead.
As You, Lord, in deep compassion
Healed the sick and freed the soul,
By Your Spirit send Your power
To our world to make it whole.
As we worship, grant us vision,
Till your love\'s revealing light
In its height and depth and greatness
Dawns upon our quickened sight,
Making known the needs and burdens
Your compassion bids us bear,
Stirring us to ardent service,
Your abundant life to share.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0363', 'verse', 1, 0, '[\"Lord, whose love in humble service\",\"Bore the weight of human need,\",\"Who upon the cross, forsaken,\",\"Worked Your mercy\'s perfect deed:\",\"We, Your servants, bring the worship\",\"Not of voice alone, but heart;\",\"Consecrating to Your purpose\",\"Every gift which You impart.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0363', 'verse', 2, 1, '[\"Still Your children wander homeless;\",\"Still the hungry cry for bread;\",\"Still the captives long for freedom;\",\"Still in grief we mourn our dead.\",\"As You, Lord, in deep compassion\",\"Healed the sick and freed the soul,\",\"By Your Spirit send Your power\",\"To our world to make it whole.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0363', 'verse', 3, 2, '[\"As we worship, grant us vision,\",\"Till your love\'s revealing light\",\"In its height and depth and greatness\",\"Dawns upon our quickened sight,\",\"Making known the needs and burdens\",\"Your compassion bids us bear,\",\"Stirring us to ardent service,\",\"Your abundant life to share.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0364', 364, 'O Jesus Christ, to You', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O Jesus Christ, to You may hymns be rising
In every city for Your love and care;
Inspire our worship, grant the glad surprising
That Your blest Spirit brings men everywhere.
Grant us new courage, sacrificial, humble,
Strong in Your strength to venture and to dare,
To lift the fallen, guide the feet that stumble,
Seek out the lonely and God\'s mercy share.
Show us Your Spirit, brooding o\'er each city,
As You did weep above Jerusalem,
Seeking to gather all in love and pity,
And healing those who touch Your garment\'s hem.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0364', 'verse', 1, 0, '[\"O Jesus Christ, to You may hymns be rising\",\"In every city for Your love and care;\",\"Inspire our worship, grant the glad surprising\",\"That Your blest Spirit brings men everywhere.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0364', 'verse', 2, 1, '[\"Grant us new courage, sacrificial, humble,\",\"Strong in Your strength to venture and to dare,\",\"To lift the fallen, guide the feet that stumble,\",\"Seek out the lonely and God\'s mercy share.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0364', 'verse', 3, 2, '[\"Show us Your Spirit, brooding o\'er each city,\",\"As You did weep above Jerusalem,\",\"Seeking to gather all in love and pity,\",\"And healing those who touch Your garment\'s hem.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0365', 365, 'O Zion, Haste', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O Zion, haste, thy mission high fulfilling,
To tell to all the world that God is light;
That He who made all nations is not willing
One soul should perish, lost in shades of night.
Publish glad tidings,
Tidings of peace,
Tidings of Jesus,
Redemption and release.
Proclaim to every people, tongue, and nation
That God, in whom they live and move, is love;
Tell how He stooped to save His lost creation,
And died on earth that man might live above.
Give of thy sons to bear the message glorious;
Give of thy wealth to speed them on their way;
Pour out thy soul for them in prayer victorious;
And all thou spendest Jesus will repay.
He comes again; O Zion, ere thou meet Him,
Make known to every heart His saving grace;
Let none whom He hath ransomed fail to greet Him,
Through thy neglect, unfit to see His face.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0365', 'verse', 1, 0, '[\"O Zion, haste, thy mission high fulfilling,\",\"To tell to all the world that God is light;\",\"That He who made all nations is not willing\",\"One soul should perish, lost in shades of night.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0365', 'chorus', 0, 1, '[\"Publish glad tidings,\",\"Tidings of peace,\",\"Tidings of Jesus,\",\"Redemption and release.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0365', 'verse', 2, 2, '[\"Proclaim to every people, tongue, and nation\",\"That God, in whom they live and move, is love;\",\"Tell how He stooped to save His lost creation,\",\"And died on earth that man might live above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0365', 'verse', 3, 3, '[\"Give of thy sons to bear the message glorious;\",\"Give of thy wealth to speed them on their way;\",\"Pour out thy soul for them in prayer victorious;\",\"And all thou spendest Jesus will repay.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0365', 'verse', 4, 4, '[\"He comes again; O Zion, ere thou meet Him,\",\"Make known to every heart His saving grace;\",\"Let none whom He hath ransomed fail to greet Him,\",\"Through thy neglect, unfit to see His face.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0366', 366, 'O Where Are the Reapers?', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O where are the reapers that garner in
The sheaves of the good from the fields of sin?
With sickles of truth must the work be done,
And no one may rest till the \"harvest home.\"
Where are the reapers? O who will come
And share in the glory of the \"harvest home\"?
O who will help us to garner in
The sheaves of good from the fields of sin?
The fields all are ripening, and far and wide
The world now is waiting the harvest tide:
But reapers are few, and the work is great,
And much will be lost should the harvest wait.
So come with your sickles, ye sons of men,
And gather together the golden grain;
Toil on till the Lord of the harvest come,
Then share ye His joy in the \"harvest home.\"');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0366', 'verse', 1, 0, '[\"O where are the reapers that garner in\",\"The sheaves of the good from the fields of sin?\",\"With sickles of truth must the work be done,\",\"And no one may rest till the \\\"harvest home.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0366', 'chorus', 0, 1, '[\"Where are the reapers? O who will come\",\"And share in the glory of the \\\"harvest home\\\"?\",\"O who will help us to garner in\",\"The sheaves of good from the fields of sin?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0366', 'verse', 2, 2, '[\"The fields all are ripening, and far and wide\",\"The world now is waiting the harvest tide:\",\"But reapers are few, and the work is great,\",\"And much will be lost should the harvest wait.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0366', 'verse', 3, 3, '[\"So come with your sickles, ye sons of men,\",\"And gather together the golden grain;\",\"Toil on till the Lord of the harvest come,\",\"Then share ye His joy in the \\\"harvest home.\\\"\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0367', 367, 'Rescue the Perishing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Rescue the perishing,
Care for the dying;
Snatch them in pity from sin and the grave;
Weep o\'er the erring one,
Lift up the fallen,
Tell them of Jesus, the mighty to save.
Rescue the perishing,
Care for the dying;
Jesus is merciful,
Jesus will save.
Though they are slighting Him,
Still He is waiting,
Waiting the penitent child to receive.
Plead with them earnestly,
Plead with them gently;
He will forgive if they only believe.
Rescue the perishing,
Duty demands it;
Strength for thy labor the Lord will provide;
Back to the narrow way
Patiently win them;
Tell the poor wanderer a Savior has died.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0367', 'verse', 1, 0, '[\"Rescue the perishing,\",\"Care for the dying;\",\"Snatch them in pity from sin and the grave;\",\"Weep o\'er the erring one,\",\"Lift up the fallen,\",\"Tell them of Jesus, the mighty to save.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0367', 'chorus', 0, 1, '[\"Rescue the perishing,\",\"Care for the dying;\",\"Jesus is merciful,\",\"Jesus will save.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0367', 'verse', 2, 2, '[\"Though they are slighting Him,\",\"Still He is waiting,\",\"Waiting the penitent child to receive.\",\"Plead with them earnestly,\",\"Plead with them gently;\",\"He will forgive if they only believe.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0367', 'verse', 3, 3, '[\"Rescue the perishing,\",\"Duty demands it;\",\"Strength for thy labor the Lord will provide;\",\"Back to the narrow way\",\"Patiently win them;\",\"Tell the poor wanderer a Savior has died.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0368', 368, 'Watchman, Blow the Gospel Trumpet', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Watchman, blow the gospel trumpet,
Every soul a warning give;
Whosoever hears the message
May repent, and turn and live.
Blow the trumpet, trusty watchman,
Blow it loud o\'er land and sea;
God commissions, sound the message!
Every captive may be free.
Sound it loud o\'er every hilltop,
Gloomy shade and sunny plain;
Ocean depths repeat the message,
Full salvation\'s glad refrain.
Sound it in the hedge and highway,
Earth\'s dark spots where exiles roam;
Let it tell all things are ready,
Father waits to welcome home.
Sound it for the heavy laden,
Weary, longing to be free;
Sound a Savior\'s invitation,
Sweetly saying, \"Come to me.\"');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0368', 'verse', 1, 0, '[\"Watchman, blow the gospel trumpet,\",\"Every soul a warning give;\",\"Whosoever hears the message\",\"May repent, and turn and live.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0368', 'chorus', 0, 1, '[\"Blow the trumpet, trusty watchman,\",\"Blow it loud o\'er land and sea;\",\"God commissions, sound the message!\",\"Every captive may be free.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0368', 'verse', 2, 2, '[\"Sound it loud o\'er every hilltop,\",\"Gloomy shade and sunny plain;\",\"Ocean depths repeat the message,\",\"Full salvation\'s glad refrain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0368', 'verse', 3, 3, '[\"Sound it in the hedge and highway,\",\"Earth\'s dark spots where exiles roam;\",\"Let it tell all things are ready,\",\"Father waits to welcome home.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0368', 'verse', 4, 4, '[\"Sound it for the heavy laden,\",\"Weary, longing to be free;\",\"Sound a Savior\'s invitation,\",\"Sweetly saying, \\\"Come to me.\\\"\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0369', 369, 'Bringing in the Sheaves', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Sowing in the morning, sowing seeds of kindness,
Sowing in the noontide and the dewy eve;
Waiting for the harvest, and the time of reaping,
We shall come rejoicing, bringing in the sheaves.
Bringing in the sheaves,
Bringing in the sheaves,
We shall come rejoicing,
Bringing in the sheaves;
Bringing in the sheaves,
Bringing in the sheaves,
We shall come rejoicing,
Bringing in the sheaves.
Sowing in the sunshine, sowing in the shadows,
Fearing neither clouds nor winter\'s chilling breeze;
By and by the harvest, and the labor ended,
We shall come rejoicing, bringing in the sheaves.
Going forth with weeping, sowing for the Master,
Though the loss sustained our spirit often grieves;
When our weeping\'s over, He will bid us welcome,
We shall come rejoicing, bringing in the sheaves.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0369', 'verse', 1, 0, '[\"Sowing in the morning, sowing seeds of kindness,\",\"Sowing in the noontide and the dewy eve;\",\"Waiting for the harvest, and the time of reaping,\",\"We shall come rejoicing, bringing in the sheaves.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0369', 'chorus', 0, 1, '[\"Bringing in the sheaves,\",\"Bringing in the sheaves,\",\"We shall come rejoicing,\",\"Bringing in the sheaves;\",\"Bringing in the sheaves,\",\"Bringing in the sheaves,\",\"We shall come rejoicing,\",\"Bringing in the sheaves.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0369', 'verse', 2, 2, '[\"Sowing in the sunshine, sowing in the shadows,\",\"Fearing neither clouds nor winter\'s chilling breeze;\",\"By and by the harvest, and the labor ended,\",\"We shall come rejoicing, bringing in the sheaves.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0369', 'verse', 3, 3, '[\"Going forth with weeping, sowing for the Master,\",\"Though the loss sustained our spirit often grieves;\",\"When our weeping\'s over, He will bid us welcome,\",\"We shall come rejoicing, bringing in the sheaves.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0370', 370, 'Christ for the World', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Christ for the world we sing;
The world to Christ we bring
With loving zeal;
The poor and them that mourn,
The faint and overborne,
Sin-sick and sorrow-worn,
Whom Christ doth heal.
Christ for the world we sing;
The world to Christ we bring
With fervent prayer;
The wayward and the lost,
By restless passions tossed,
Redeemed at countless cost');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0370', 'verse', 1, 0, '[\"Christ for the world we sing;\",\"The world to Christ we bring\",\"With loving zeal;\",\"The poor and them that mourn,\",\"The faint and overborne,\",\"Sin-sick and sorrow-worn,\",\"Whom Christ doth heal.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0370', 'verse', 2, 1, '[\"Christ for the world we sing;\",\"The world to Christ we bring\",\"With fervent prayer;\",\"The wayward and the lost,\",\"By restless passions tossed,\",\"Redeemed at countless cost\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0371', 371, 'Lift Him Up', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lift Him up, \'tis He that bids you,
Let the dying look and live;
To all weary, thirsting sinners,
Living waters will He give;
And though once so meek and lowly,
Yet the Prince of heaven was He;
And the blind, who grope in darkness,
Through the blood of Christ shall see.
Lift Him up, the risen Savior,
High amid the waiting throng;
Lift Him up, \'tis He that speaketh,
Now He bids you flee from wrong.
Lift Him up, this precious Savior,
Let the multitude behold
They with willing hearts shall seek Him,
He will draw them to His fold;
They shall gather from the wayside,
Hastening on with joyous feet,
They shall bear the cross of Jesus,
And shall find salvation sweet.
Lift Him up in all His glory,
\'Tis the Son of God on high;
Lift Him up, His love shall draw them,
E\'en the careless shall draw nigh;
Let them hear again the story
Of the cross, the death of shame;
And from tongue to tongue repeat it;
Mighty throngs shall bless His name.
O then lift Him up in singing,
Lift the Savior up in prayer;
He, the glorious Redeemer,
All the sins of men did bear,
Yes, the young shall bow before Him,
And the old their voices raise;
All the deaf shall hear hosannah;
And the dumb shall shout His praise.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0371', 'verse', 1, 0, '[\"Lift Him up, \'tis He that bids you,\",\"Let the dying look and live;\",\"To all weary, thirsting sinners,\",\"Living waters will He give;\",\"And though once so meek and lowly,\",\"Yet the Prince of heaven was He;\",\"And the blind, who grope in darkness,\",\"Through the blood of Christ shall see.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0371', 'chorus', 0, 1, '[\"Lift Him up, the risen Savior,\",\"High amid the waiting throng;\",\"Lift Him up, \'tis He that speaketh,\",\"Now He bids you flee from wrong.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0371', 'verse', 2, 2, '[\"Lift Him up, this precious Savior,\",\"Let the multitude behold\",\"They with willing hearts shall seek Him,\",\"He will draw them to His fold;\",\"They shall gather from the wayside,\",\"Hastening on with joyous feet,\",\"They shall bear the cross of Jesus,\",\"And shall find salvation sweet.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0371', 'verse', 3, 3, '[\"Lift Him up in all His glory,\",\"\'Tis the Son of God on high;\",\"Lift Him up, His love shall draw them,\",\"E\'en the careless shall draw nigh;\",\"Let them hear again the story\",\"Of the cross, the death of shame;\",\"And from tongue to tongue repeat it;\",\"Mighty throngs shall bless His name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0371', 'verse', 4, 4, '[\"O then lift Him up in singing,\",\"Lift the Savior up in prayer;\",\"He, the glorious Redeemer,\",\"All the sins of men did bear,\",\"Yes, the young shall bow before Him,\",\"And the old their voices raise;\",\"All the deaf shall hear hosannah;\",\"And the dumb shall shout His praise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0372', 372, 'How Beauteous Are Their Feet', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'How beauteous are their feet
Who stand on Zion\'s hill;
Who bring salvation on their tongues,
And words of peace reveal!
How charming is their voice,
So sweet the tidings are:
\"Zion, behold thy Savior King;
He reigns and triumphs here!\"
How happy are our ears,
That hear the joyful sound
Which kings and prophets waited for,
And sought, but never found!
How blessed are our eyes,
That see this heavenly light;
Prophets and kings desired it long,
But died without the sight!
The watchmen join their voice,
And tuneful notes employ;
Jerusalem breaks forth in songs,
And deserts learn the joy.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0372', 'verse', 1, 0, '[\"How beauteous are their feet\",\"Who stand on Zion\'s hill;\",\"Who bring salvation on their tongues,\",\"And words of peace reveal!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0372', 'verse', 2, 1, '[\"How charming is their voice,\",\"So sweet the tidings are:\",\"\\\"Zion, behold thy Savior King;\",\"He reigns and triumphs here!\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0372', 'verse', 3, 2, '[\"How happy are our ears,\",\"That hear the joyful sound\",\"Which kings and prophets waited for,\",\"And sought, but never found!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0372', 'verse', 4, 3, '[\"How blessed are our eyes,\",\"That see this heavenly light;\",\"Prophets and kings desired it long,\",\"But died without the sight!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0372', 'verse', 5, 4, '[\"The watchmen join their voice,\",\"And tuneful notes employ;\",\"Jerusalem breaks forth in songs,\",\"And deserts learn the joy.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0373', 373, 'Seeking the Lost', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Seeking the lost; yes, kindly entreating
Wanderers on the mountain astray;
\"Come unto Me,\" His message repeating,
Words of the Master speaking today.
Going afar upon the mountain,
Bringing the wand\'rer back again, back again,
Into the fold of my Redeemer,
Jesus, the Lamb for sinners slain, for sinners slain.
Seeking the lost; and pointing to Jesus
Souls that are weak and hearts that are sore,
Leading them forth in ways of salvation,
Showing the path to life evermore.
Thus I would go on missions of mercy,
Following Christ from day unto day,
Cheering the faint and raising the fallen,
Pointing the lost to Jesus, the Way.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0373', 'verse', 1, 0, '[\"Seeking the lost; yes, kindly entreating\",\"Wanderers on the mountain astray;\",\"\\\"Come unto Me,\\\" His message repeating,\",\"Words of the Master speaking today.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0373', 'chorus', 0, 1, '[\"Going afar upon the mountain,\",\"Bringing the wand\'rer back again, back again,\",\"Into the fold of my Redeemer,\",\"Jesus, the Lamb for sinners slain, for sinners slain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0373', 'verse', 2, 2, '[\"Seeking the lost; and pointing to Jesus\",\"Souls that are weak and hearts that are sore,\",\"Leading them forth in ways of salvation,\",\"Showing the path to life evermore.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0373', 'verse', 3, 3, '[\"Thus I would go on missions of mercy,\",\"Following Christ from day unto day,\",\"Cheering the faint and raising the fallen,\",\"Pointing the lost to Jesus, the Way.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0374', 374, 'Jesus, With Thy Church Abide', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Jesus, with Thy church abide;
Be her Savior, Lord, and Guide,
While on earth her faith is tried:
We beseech Thee, hear us.
May her voice be ever clear,
Warning of a judgment near,
Telling of a Savior dear:
We beseech Thee, hear us.
May she guide the poor and blind,
Seek the lost until she find,
And the broken-hearted bind:
We beseech Thee, hear us.
May she holy triumphs win,
Overthrow the hosts of sin,
Gather all the nations in:
We beseech Thee, hear us.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0374', 'verse', 1, 0, '[\"Jesus, with Thy church abide;\",\"Be her Savior, Lord, and Guide,\",\"While on earth her faith is tried:\",\"We beseech Thee, hear us.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0374', 'verse', 2, 1, '[\"May her voice be ever clear,\",\"Warning of a judgment near,\",\"Telling of a Savior dear:\",\"We beseech Thee, hear us.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0374', 'verse', 3, 2, '[\"May she guide the poor and blind,\",\"Seek the lost until she find,\",\"And the broken-hearted bind:\",\"We beseech Thee, hear us.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0374', 'verse', 4, 3, '[\"May she holy triumphs win,\",\"Overthrow the hosts of sin,\",\"Gather all the nations in:\",\"We beseech Thee, hear us.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0375', 375, 'Work, For the Night Is Coming', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Work, for the night is coming;
Work through the morning hours;
Work while the dew is sparkling;
Work \'mid springing flowers;
Work while the day grows brighter,
Under the glowing sun;
Work, for the night is coming,
When man\'s work is done.
Work, for the night is coming;
Work through the sunny noon;
Fill brightest hours with labor,
Rest comes sure and soon;
Give every flying minute
Something to keep in store;
Work, for the night is coming,
When man works no more.
Work, for the night is coming:
Under the sunset skies,
While their bright tints are glowing,
Work for the daylight flies;
Work till the last beam fadeth,
Fadeth to shine no more;
Work, for the Lord is coming,
When man\'s work is o\'er.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0375', 'verse', 1, 0, '[\"Work, for the night is coming;\",\"Work through the morning hours;\",\"Work while the dew is sparkling;\",\"Work \'mid springing flowers;\",\"Work while the day grows brighter,\",\"Under the glowing sun;\",\"Work, for the night is coming,\",\"When man\'s work is done.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0375', 'verse', 2, 1, '[\"Work, for the night is coming;\",\"Work through the sunny noon;\",\"Fill brightest hours with labor,\",\"Rest comes sure and soon;\",\"Give every flying minute\",\"Something to keep in store;\",\"Work, for the night is coming,\",\"When man works no more.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0375', 'verse', 3, 2, '[\"Work, for the night is coming:\",\"Under the sunset skies,\",\"While their bright tints are glowing,\",\"Work for the daylight flies;\",\"Work till the last beam fadeth,\",\"Fadeth to shine no more;\",\"Work, for the Lord is coming,\",\"When man\'s work is o\'er.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0376', 376, 'All Things Are Thine', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'All things are Thine; no gift have we,
Lord of all gifts, to offer Thee;
And hence with grateful hearts today,
Thine own before Thy feet we lay.
Thy will was in the builder\'s thought;
Thy hand unseen amidst us wrought;
Thro\' mortal motive, scheme and plan,
Thy wise, eternal purpose ran.
No lack Thy perfect fullness knew;
For human needs and longings grew
This house of prayer; this home of rest.
Here may Thy saints be often blessed.
In weakness and in want we call
On Thee, for whom the heav\'ns are small;
Thy glory is Thy children\'s good,
Thy joy Thy tender Fatherhood.
O Father! deign these walls to bless;
Make this the abode of righteousness,
And let these doors a gateway be
To lead us from ourselves to Thee!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0376', 'verse', 1, 0, '[\"All things are Thine; no gift have we,\",\"Lord of all gifts, to offer Thee;\",\"And hence with grateful hearts today,\",\"Thine own before Thy feet we lay.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0376', 'verse', 2, 1, '[\"Thy will was in the builder\'s thought;\",\"Thy hand unseen amidst us wrought;\",\"Thro\' mortal motive, scheme and plan,\",\"Thy wise, eternal purpose ran.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0376', 'verse', 3, 2, '[\"No lack Thy perfect fullness knew;\",\"For human needs and longings grew\",\"This house of prayer; this home of rest.\",\"Here may Thy saints be often blessed.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0376', 'verse', 4, 3, '[\"In weakness and in want we call\",\"On Thee, for whom the heav\'ns are small;\",\"Thy glory is Thy children\'s good,\",\"Thy joy Thy tender Fatherhood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0376', 'verse', 5, 4, '[\"O Father! deign these walls to bless;\",\"Make this the abode of righteousness,\",\"And let these doors a gateway be\",\"To lead us from ourselves to Thee!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0377', 377, 'Go Forth Go Forth With Christ', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Go forth, go forth with Christ,
Who called you to this day,
He who has led, will lead
And keep you in His way:
His word is fast, His promise sure
To all who serve Him and endure.
Go forth, go forth with Christ,
With purpose not your own,
Each vict\'ry you shall gain
Through Him your Lord alone:
To guard you in fidelity
His Spirit shall your strength\'ner be.
Go forth, go forth with Christ,
His Priesthood you shall share,
Who bought us by His blood
To be His servants here:
Walk in the way your Savior trod,
Go forth with Him, go forth with God.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0377', 'verse', 1, 0, '[\"Go forth, go forth with Christ,\",\"Who called you to this day,\",\"He who has led, will lead\",\"And keep you in His way:\",\"His word is fast, His promise sure\",\"To all who serve Him and endure.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0377', 'verse', 2, 1, '[\"Go forth, go forth with Christ,\",\"With purpose not your own,\",\"Each vict\'ry you shall gain\",\"Through Him your Lord alone:\",\"To guard you in fidelity\",\"His Spirit shall your strength\'ner be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0377', 'verse', 3, 2, '[\"Go forth, go forth with Christ,\",\"His Priesthood you shall share,\",\"Who bought us by His blood\",\"To be His servants here:\",\"Walk in the way your Savior trod,\",\"Go forth with Him, go forth with God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0378', 378, 'Go, Preach My Gospel', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, '\"Go, preach My gospel,\" saith the Lord;
\"Bid the whole world My grace receive;
He shall be saved who trusts My word,
And they condemned who disbelieve.
\"I\'ll make your great commission known,
And ye shall prove My gospel true
By all the works that I have done,
By all the wonders ye shall do.
\"Teach all the nations My commands;
I\'m with you till the world shall end;
All power is vested in My hands;
I can destroy, and I defend.\"
He spake, and light shone round His head;
On a brigh cloud to heaven He rode;
They to the farthest nations spread
The grace of their ascended Lord.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0378', 'verse', 1, 0, '[\"\\\"Go, preach My gospel,\\\" saith the Lord;\",\"\\\"Bid the whole world My grace receive;\",\"He shall be saved who trusts My word,\",\"And they condemned who disbelieve.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0378', 'verse', 2, 1, '[\"\\\"I\'ll make your great commission known,\",\"And ye shall prove My gospel true\",\"By all the works that I have done,\",\"By all the wonders ye shall do.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0378', 'verse', 3, 2, '[\"\\\"Teach all the nations My commands;\",\"I\'m with you till the world shall end;\",\"All power is vested in My hands;\",\"I can destroy, and I defend.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0378', 'verse', 4, 3, '[\"He spake, and light shone round His head;\",\"On a brigh cloud to heaven He rode;\",\"They to the farthest nations spread\",\"The grace of their ascended Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0379', 379, 'We Give This Child to You', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'We give this child to You,
Our precious gift of love.
Help us to lead each step aright
With guidance from above.
O bless each child of Yours,
And grant when they are grown,
They will have learned to love Your way,
And choose it for their own.
We give ourselves to You,
And may Your Spirit fill
Our hearts and home, that all we do
Be subject to Your will.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0379', 'verse', 1, 0, '[\"We give this child to You,\",\"Our precious gift of love.\",\"Help us to lead each step aright\",\"With guidance from above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0379', 'verse', 2, 1, '[\"O bless each child of Yours,\",\"And grant when they are grown,\",\"They will have learned to love Your way,\",\"And choose it for their own.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0379', 'verse', 3, 2, '[\"We give ourselves to You,\",\"And may Your Spirit fill\",\"Our hearts and home, that all we do\",\"Be subject to Your will.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0380', 380, 'Welcome, Day of Sweet Repose', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Welcome, day of sweet repose!
Blessed be thy sacred hours!
We would trust the One who knows
All our weak and failing powers.
Welcome, day in Eden born!
Holy rest for sinless man!
Like the dawning of fair morn
Come thy hours to us again.
Welcome, day blessed by our Lord!
Toil shall cease and anxious care.
Day commanded by His word,
Day for song and praise and prayer.
Welcome, day our Savior kept!
Keeping, wrought our righteousness,
Day God bids us ne\'er forget,
Day of days His name to bless.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0380', 'verse', 1, 0, '[\"Welcome, day of sweet repose!\",\"Blessed be thy sacred hours!\",\"We would trust the One who knows\",\"All our weak and failing powers.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0380', 'verse', 2, 1, '[\"Welcome, day in Eden born!\",\"Holy rest for sinless man!\",\"Like the dawning of fair morn\",\"Come thy hours to us again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0380', 'verse', 3, 2, '[\"Welcome, day blessed by our Lord!\",\"Toil shall cease and anxious care.\",\"Day commanded by His word,\",\"Day for song and praise and prayer.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0380', 'verse', 4, 3, '[\"Welcome, day our Savior kept!\",\"Keeping, wrought our righteousness,\",\"Day God bids us ne\'er forget,\",\"Day of days His name to bless.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0381', 381, 'Holy Sabbath Day of Rest', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Holy Sabbath day of rest,
By our Master richly blest,
God-created and divine,
Set aside for holy time.
Yes, the holy Sabbath rest,
By our God divinely blest,
It to us a sign shall be
Throughout all eternity.
Seek not pleasures of this earth,
With its folly, noise, and mirth,
There are better things in store,
Over on the other shore.
As the Sabbath draweth on
Friday eve at set of sun,
Christian household then should meet,
Sing and pray at Jesus\' feet,
Asking Him for saving grace,
Also vict\'ry in the race,
And to help us by His pow\'r,
To keep holy every hour.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0381', 'verse', 1, 0, '[\"Holy Sabbath day of rest,\",\"By our Master richly blest,\",\"God-created and divine,\",\"Set aside for holy time.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0381', 'chorus', 0, 1, '[\"Yes, the holy Sabbath rest,\",\"By our God divinely blest,\",\"It to us a sign shall be\",\"Throughout all eternity.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0381', 'verse', 2, 2, '[\"Seek not pleasures of this earth,\",\"With its folly, noise, and mirth,\",\"There are better things in store,\",\"Over on the other shore.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0381', 'verse', 3, 3, '[\"As the Sabbath draweth on\",\"Friday eve at set of sun,\",\"Christian household then should meet,\",\"Sing and pray at Jesus\' feet,\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0381', 'verse', 4, 4, '[\"Asking Him for saving grace,\",\"Also vict\'ry in the race,\",\"And to help us by His pow\'r,\",\"To keep holy every hour.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0382', 382, 'O Day of Rest and Gladness', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O day of rest and gladness,
O day of joy and light,
O balm of care and sadness,
Most beautiful, most bright;
On thee, the high and lowly,
Who bend before the throne,
Sing, holy, holy, holy,
To the Eternal One.
Thou art a port protected');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0382', 'verse', 1, 0, '[\"O day of rest and gladness,\",\"O day of joy and light,\",\"O balm of care and sadness,\",\"Most beautiful, most bright;\",\"On thee, the high and lowly,\",\"Who bend before the throne,\",\"Sing, holy, holy, holy,\",\"To the Eternal One.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0382', 'verse', 2, 1, '[\"Thou art a port protected\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0383', 383, 'O Day of Rest and Gladness', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O day of rest and gladness,
O day of joy and light,
O balm of care and sadness,
Most beautiful, most bright;
On thee, the high and lowly,
Who bend before the throne,
Sing, Holy, holy, holy,
To the Eternal One.
Thou art a port protected');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0383', 'verse', 1, 0, '[\"O day of rest and gladness,\",\"O day of joy and light,\",\"O balm of care and sadness,\",\"Most beautiful, most bright;\",\"On thee, the high and lowly,\",\"Who bend before the throne,\",\"Sing, Holy, holy, holy,\",\"To the Eternal One.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0383', 'verse', 2, 1, '[\"Thou art a port protected\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0384', 384, 'Safely Through Another Week', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Safely through another week
God has brought us on our way;
Let us now a blessing seek,
Waiting in His courts today;
Day of all the week the best,
Emblem of eternal rest;
Day of all the week the best,
Emblem of eternal rest.
While we seek supplies of grace
Through the dear Redeemer\'s name,
Show Thy reconciling face,
Take away our sin and shame;');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0384', 'verse', 1, 0, '[\"Safely through another week\",\"God has brought us on our way;\",\"Let us now a blessing seek,\",\"Waiting in His courts today;\",\"Day of all the week the best,\",\"Emblem of eternal rest;\",\"Day of all the week the best,\",\"Emblem of eternal rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0384', 'verse', 2, 1, '[\"While we seek supplies of grace\",\"Through the dear Redeemer\'s name,\",\"Show Thy reconciling face,\",\"Take away our sin and shame;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0385', 385, 'Crowning Jewel of Creation', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Crowning jewel of creation,
Blest and hallowed, sanctified;
Time and changes all transcending,
Shared forever, glorified.
Blessed Sabbath made for man,
Gift from the Creator\'s hand.
Sin and sickness, prayer and weeping
Cease at close of earthly days;
But Thy Sabbath is eternal,
Joyful thanks to Thee we raise!
Teach us Lord, in storm or sunshine
How to truly rest in Thee,
May Thy Sabbath peace enfold us
And our shelter ever be.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0385', 'verse', 1, 0, '[\"Crowning jewel of creation,\",\"Blest and hallowed, sanctified;\",\"Time and changes all transcending,\",\"Shared forever, glorified.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0385', 'chorus', 0, 1, '[\"Blessed Sabbath made for man,\",\"Gift from the Creator\'s hand.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0385', 'verse', 2, 2, '[\"Sin and sickness, prayer and weeping\",\"Cease at close of earthly days;\",\"But Thy Sabbath is eternal,\",\"Joyful thanks to Thee we raise!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0385', 'verse', 3, 3, '[\"Teach us Lord, in storm or sunshine\",\"How to truly rest in Thee,\",\"May Thy Sabbath peace enfold us\",\"And our shelter ever be.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0386', 386, 'The Sacred Anthem', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'The sacred anthem slowly rang
Across the fields of praise,
When earth\'s first Sabbath made complete
All creatures and all days.
Walking with God, there,
Woman and man together share
The blessed Sabbath mood;
And in that green and golden world
Know all God\'s works are good.
But now in our diminished lives
We sing a blemished song;
The earth is worn and disarrayed
And all our work goes wrong.
Still in our worship,
Joining in praise and fellowship,
By Sabbath radiance blessed,
We put our doubt and fear away
And rest within God\'s rest.
And arching over time and space
The Lord of Sabbaths wills
Renewal for the weary earth
And healing for our ills.
Hearts will rejoice then;
There will be no more weeping, when
We know and shall be known.
With hosts of the redeemed we\'ll sing
Around God\'s shining throne.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0386', 'verse', 1, 0, '[\"The sacred anthem slowly rang\",\"Across the fields of praise,\",\"When earth\'s first Sabbath made complete\",\"All creatures and all days.\",\"Walking with God, there,\",\"Woman and man together share\",\"The blessed Sabbath mood;\",\"And in that green and golden world\",\"Know all God\'s works are good.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0386', 'verse', 2, 1, '[\"But now in our diminished lives\",\"We sing a blemished song;\",\"The earth is worn and disarrayed\",\"And all our work goes wrong.\",\"Still in our worship,\",\"Joining in praise and fellowship,\",\"By Sabbath radiance blessed,\",\"We put our doubt and fear away\",\"And rest within God\'s rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0386', 'verse', 3, 2, '[\"And arching over time and space\",\"The Lord of Sabbaths wills\",\"Renewal for the weary earth\",\"And healing for our ills.\",\"Hearts will rejoice then;\",\"There will be no more weeping, when\",\"We know and shall be known.\",\"With hosts of the redeemed we\'ll sing\",\"Around God\'s shining throne.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0387', 387, 'Come O Sabbath Day', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Come, O Sabbath day, and bring
Peace and healing on thy wing;
And to every troubled breast
Speak of the divine behest:
Thou shalt rest, Thou shalt rest!
Earthly longings bid retire,
Quench the passions\' hurtful fire;
To the wayward, sin oppressed,
Bring thou thy divine behest:
Thou shalt rest, Thou shalt rest!
Wipe from every cheek the tear,
Banish care and silence fear;
All things working for the best,
Teach us the divine behest:
Thou shalt rest, Thou shalt rest!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0387', 'verse', 1, 0, '[\"Come, O Sabbath day, and bring\",\"Peace and healing on thy wing;\",\"And to every troubled breast\",\"Speak of the divine behest:\",\"Thou shalt rest, Thou shalt rest!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0387', 'verse', 2, 1, '[\"Earthly longings bid retire,\",\"Quench the passions\' hurtful fire;\",\"To the wayward, sin oppressed,\",\"Bring thou thy divine behest:\",\"Thou shalt rest, Thou shalt rest!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0387', 'verse', 3, 2, '[\"Wipe from every cheek the tear,\",\"Banish care and silence fear;\",\"All things working for the best,\",\"Teach us the divine behest:\",\"Thou shalt rest, Thou shalt rest!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0388', 388, 'Don\'t Forget the Sabbath', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Don\'t forget the Sabbath,
The Lord our God hath blest,
Of all the week the brightest,
Of all the week the best;
It brings repose from labor,
It tells of joy divine,
Its beams of light descending,
With heavenly beauty shine.
Welcome, welcome, ever welcome,
Blessed Sabbath day.
Welcome, welcome, ever welcome,
Blessed Sabbath day.
Keep the Sabbath holy,
And worship Him today,
Who said to His disciples,
\"I am the living way;\"
And if we meekly follow
Our Savior here below,
He\'ll give us of the fountain
Whose streams eternal flow.
Day of sacred pleasure!
Its golden hours we\'ll spend
In thankful hymns to Jesus,
The children\'s dearest Friend;
O gentle loving Savior,
How good and kind Thou art,
How precious is Thy promise
To dwell in every heart!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0388', 'verse', 1, 0, '[\"Don\'t forget the Sabbath,\",\"The Lord our God hath blest,\",\"Of all the week the brightest,\",\"Of all the week the best;\",\"It brings repose from labor,\",\"It tells of joy divine,\",\"Its beams of light descending,\",\"With heavenly beauty shine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0388', 'chorus', 0, 1, '[\"Welcome, welcome, ever welcome,\",\"Blessed Sabbath day.\",\"Welcome, welcome, ever welcome,\",\"Blessed Sabbath day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0388', 'verse', 2, 2, '[\"Keep the Sabbath holy,\",\"And worship Him today,\",\"Who said to His disciples,\",\"\\\"I am the living way;\\\"\",\"And if we meekly follow\",\"Our Savior here below,\",\"He\'ll give us of the fountain\",\"Whose streams eternal flow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0388', 'verse', 3, 3, '[\"Day of sacred pleasure!\",\"Its golden hours we\'ll spend\",\"In thankful hymns to Jesus,\",\"The children\'s dearest Friend;\",\"O gentle loving Savior,\",\"How good and kind Thou art,\",\"How precious is Thy promise\",\"To dwell in every heart!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0389', 389, 'Light of Light, Enlighten Me', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Light of light, enlighten me,
Now anew the day is dawning;
Sun of grace, the shadows flee;
Brighten Thou my Sabbath morning;
With Thy joyous sunshine blest,
Happy is my day of rest.
Let me with my heart today,
Holy, holy, holy, singing,
Rapt awhile from earth away,
All my soul to Thee up springing,
Have a foretaste inward given
How they worship Thee in heaven.
Hence all care, all vanity!
For the day to God is holy;
Come, Thou glorious Majesty,
Deign to fill this temple lowly;
Nought today my soul shall move,
Simply resting in Thy love.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0389', 'verse', 1, 0, '[\"Light of light, enlighten me,\",\"Now anew the day is dawning;\",\"Sun of grace, the shadows flee;\",\"Brighten Thou my Sabbath morning;\",\"With Thy joyous sunshine blest,\",\"Happy is my day of rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0389', 'verse', 2, 1, '[\"Let me with my heart today,\",\"Holy, holy, holy, singing,\",\"Rapt awhile from earth away,\",\"All my soul to Thee up springing,\",\"Have a foretaste inward given\",\"How they worship Thee in heaven.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0389', 'verse', 3, 2, '[\"Hence all care, all vanity!\",\"For the day to God is holy;\",\"Come, Thou glorious Majesty,\",\"Deign to fill this temple lowly;\",\"Nought today my soul shall move,\",\"Simply resting in Thy love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0390', 390, 'We Love Thy Sabbath, Lord', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'We love Thy Sabbath, Lord,
And worship at Thy will;
Oh may these hours sweet peace afford
And deeper faith instill.
Thine angels sang for joy
Creation\'s work to see;
We too, this day, would raise our hearts
In grateful praise to Thee.
Praise for Thy wondrous love,
That sealed this sacred day,
A sign that all may understand
We own Thy sovereign sway.
O great Creator King,
Through Thy redeeming grace,
Renew and sanctify our hearts
That we may see Thy face.
And with the white-robed throng,
Upon Mount Sion be,
And joyful sing our Sabbath song
Through all eternity.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0390', 'verse', 1, 0, '[\"We love Thy Sabbath, Lord,\",\"And worship at Thy will;\",\"Oh may these hours sweet peace afford\",\"And deeper faith instill.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0390', 'verse', 2, 1, '[\"Thine angels sang for joy\",\"Creation\'s work to see;\",\"We too, this day, would raise our hearts\",\"In grateful praise to Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0390', 'verse', 3, 2, '[\"Praise for Thy wondrous love,\",\"That sealed this sacred day,\",\"A sign that all may understand\",\"We own Thy sovereign sway.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0390', 'verse', 4, 3, '[\"O great Creator King,\",\"Through Thy redeeming grace,\",\"Renew and sanctify our hearts\",\"That we may see Thy face.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0390', 'verse', 5, 4, '[\"And with the white-robed throng,\",\"Upon Mount Sion be,\",\"And joyful sing our Sabbath song\",\"Through all eternity.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0391', 391, 'Welcome, Welcome, Day of Rest', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Welcome, welcome, day of rest,
To the world in kindness given;
Welcome to this humble breast,
As the beaming light from heaven.
Day of calm and sweet repose,
Gently now thy moments run;
Balm to soothe our cares and woes,
Till our labor here is done.
Holy day that most we prize,
Day of solemn praise and prayer,
Day to make the simple wise,
O, how great thy blessings are!
Welcome, welcome, day of rest,
With thy influence all divine;
May thy hallowed hours be blessed
To this waiting heart of mine.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0391', 'verse', 1, 0, '[\"Welcome, welcome, day of rest,\",\"To the world in kindness given;\",\"Welcome to this humble breast,\",\"As the beaming light from heaven.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0391', 'verse', 2, 1, '[\"Day of calm and sweet repose,\",\"Gently now thy moments run;\",\"Balm to soothe our cares and woes,\",\"Till our labor here is done.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0391', 'verse', 3, 2, '[\"Holy day that most we prize,\",\"Day of solemn praise and prayer,\",\"Day to make the simple wise,\",\"O, how great thy blessings are!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0391', 'verse', 4, 3, '[\"Welcome, welcome, day of rest,\",\"With thy influence all divine;\",\"May thy hallowed hours be blessed\",\"To this waiting heart of mine.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0392', 392, 'Dear Lord We Come At Set of Sun', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Dear Lord, we come at set of sun,
And at Your feet we kneel
To worship You, Creator, King,
This day, Your sign and seal.
Our earthly tasks we lay aside,
According to Your Word,
To enter now Your holy rest,
The Sabbath of the Lord.
Sweet Sabbath rest, your sacred hours
Are as a golden chain
That reaches back to Eden\'s gate
And points us home again.
And when this earth shall be renewed,
And sin and death destroyed,
Shall all redeemed each Sabbath day
Still meet to praise their God.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0392', 'verse', 1, 0, '[\"Dear Lord, we come at set of sun,\",\"And at Your feet we kneel\",\"To worship You, Creator, King,\",\"This day, Your sign and seal.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0392', 'verse', 2, 1, '[\"Our earthly tasks we lay aside,\",\"According to Your Word,\",\"To enter now Your holy rest,\",\"The Sabbath of the Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0392', 'verse', 3, 2, '[\"Sweet Sabbath rest, your sacred hours\",\"Are as a golden chain\",\"That reaches back to Eden\'s gate\",\"And points us home again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0392', 'verse', 4, 3, '[\"And when this earth shall be renewed,\",\"And sin and death destroyed,\",\"Shall all redeemed each Sabbath day\",\"Still meet to praise their God.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0393', 393, 'Lord of the Sabbath', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lord of the Sabbath and its light,
I hail Thy hallowed day of rest;
It is my weary soul\'s delight,
The solace of my careworn breast,
The solace of my careworn breast.
O sacred day of peace and joy,
Thy hours are ever dear to me;
Ne\'er may a sinful thought destroy
The holy calm I find in thee,
The holy calm I find in thee.
How sweetly now they glide along!
How hallowed is the calm they yield!
Transporting is their rapturous song,
And heavenly visions seem revealed,
And heavenly visions seem revealed.
O Jesus, let me ever hail
Thy presence with the day of rest;
Then will Thy servant never fail
To deem Thy Sabbath doubly blest,
To deem Thy Sabbath doubly blest.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0393', 'verse', 1, 0, '[\"Lord of the Sabbath and its light,\",\"I hail Thy hallowed day of rest;\",\"It is my weary soul\'s delight,\",\"The solace of my careworn breast,\",\"The solace of my careworn breast.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0393', 'verse', 2, 1, '[\"O sacred day of peace and joy,\",\"Thy hours are ever dear to me;\",\"Ne\'er may a sinful thought destroy\",\"The holy calm I find in thee,\",\"The holy calm I find in thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0393', 'verse', 3, 2, '[\"How sweetly now they glide along!\",\"How hallowed is the calm they yield!\",\"Transporting is their rapturous song,\",\"And heavenly visions seem revealed,\",\"And heavenly visions seem revealed.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0393', 'verse', 4, 3, '[\"O Jesus, let me ever hail\",\"Thy presence with the day of rest;\",\"Then will Thy servant never fail\",\"To deem Thy Sabbath doubly blest,\",\"To deem Thy Sabbath doubly blest.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0394', 394, 'Far From All Care', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Far from all care we hail the Sabbath morning;
O\'er waving field and from the distant sea
Swell notes of praise in harmony resounding
As all creation turns her heart to Thee.
Though man alone, Lord, of Thy great creation
Fails now to laud Thee for Thy love and power,
Yet still a remnant love Thee and remember
Thy holy law and each sweet Sabbath hour.
Lord of the Sabbath, Savior and Creator,
Calm now the throbbings of each troubled breast.
Speak to our hearts the peace of Thy commandments,
Breathe on each soul fair Eden\'s hallowed rest.
Strong in Thy might and quiet in Thy meekness,
May we Thine image bear from day to day.
Then may we enter pearly gates eternal
And sing redemption\'s song each Sabbath day.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0394', 'verse', 1, 0, '[\"Far from all care we hail the Sabbath morning;\",\"O\'er waving field and from the distant sea\",\"Swell notes of praise in harmony resounding\",\"As all creation turns her heart to Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0394', 'verse', 2, 1, '[\"Though man alone, Lord, of Thy great creation\",\"Fails now to laud Thee for Thy love and power,\",\"Yet still a remnant love Thee and remember\",\"Thy holy law and each sweet Sabbath hour.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0394', 'verse', 3, 2, '[\"Lord of the Sabbath, Savior and Creator,\",\"Calm now the throbbings of each troubled breast.\",\"Speak to our hearts the peace of Thy commandments,\",\"Breathe on each soul fair Eden\'s hallowed rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0394', 'verse', 4, 3, '[\"Strong in Thy might and quiet in Thy meekness,\",\"May we Thine image bear from day to day.\",\"Then may we enter pearly gates eternal\",\"And sing redemption\'s song each Sabbath day.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0395', 395, 'As Birds Unto the Genial Homeland', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'As birds unto the genial homeland fly,
The winter\'s cold and low\'ring skies to flee,
So seeks my soul Thy gracious presence here
And finds, O God, its rest and peace in Thee.
Here at Thy shrine we leave all vexing care,
For get the disappointment, grief and tear,
And on the wings of hopeful song and prayer
We rise, and rising feel Thy Spirit here.
Bless all who spend this night in pain and woe,
The burdened heart, the fainting, and distressed,
Thy comfort send to darkened homes bereaved,
Thy saving help to those by want oppressed.
Come, Sabbath joy, each trusting heart now fill,
And blissful peace within our homes abide,
May thankful praise each grateful heart now thrill,
And to God\'s loving care their lives confide.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0395', 'verse', 1, 0, '[\"As birds unto the genial homeland fly,\",\"The winter\'s cold and low\'ring skies to flee,\",\"So seeks my soul Thy gracious presence here\",\"And finds, O God, its rest and peace in Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0395', 'verse', 2, 1, '[\"Here at Thy shrine we leave all vexing care,\",\"For get the disappointment, grief and tear,\",\"And on the wings of hopeful song and prayer\",\"We rise, and rising feel Thy Spirit here.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0395', 'verse', 3, 2, '[\"Bless all who spend this night in pain and woe,\",\"The burdened heart, the fainting, and distressed,\",\"Thy comfort send to darkened homes bereaved,\",\"Thy saving help to those by want oppressed.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0395', 'verse', 4, 3, '[\"Come, Sabbath joy, each trusting heart now fill,\",\"And blissful peace within our homes abide,\",\"May thankful praise each grateful heart now thrill,\",\"And to God\'s loving care their lives confide.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0396', 396, 'Lord God, Your Love Has Called Us Here', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lord God, Your love has called us here,
As we, by love, for love were made.
Your living likeness still we bear
Tho\' marred, dishonored, disobeyed.
We come, with all our heart and mind
Your call to hear, Your love to find.
We come with self-inflicted pains
Of broken trust and chosen wrong,
Half-free, half-bound by inner chains,
By social forces swept along,
By powers and systems close confined,
Yet seeking hope for humankind.
Lord God, in Christ You call our name,
And then receive us as Your own,
Not thro\' some merit, right, or claim,
But by Your gracious love alone.
We strain to glimpse Your mercy-seat,
And find You kneeling at our feet.
Then take the towel, and break the bread,
And humble us, and call us friends.
Suffer and serve till all are fed
And show how grandly love intends
To work till all creation sings,
To fill all worlds, to crown all things.
Lord God, in Christ You set us free
Your life to live, Your joy to share.
Give us Your Spirit\'s liberty
To turn from guilt and dull despair
And offer all that faith can do,
While love is making all things new.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0396', 'verse', 1, 0, '[\"Lord God, Your love has called us here,\",\"As we, by love, for love were made.\",\"Your living likeness still we bear\",\"Tho\' marred, dishonored, disobeyed.\",\"We come, with all our heart and mind\",\"Your call to hear, Your love to find.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0396', 'verse', 2, 1, '[\"We come with self-inflicted pains\",\"Of broken trust and chosen wrong,\",\"Half-free, half-bound by inner chains,\",\"By social forces swept along,\",\"By powers and systems close confined,\",\"Yet seeking hope for humankind.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0396', 'verse', 3, 2, '[\"Lord God, in Christ You call our name,\",\"And then receive us as Your own,\",\"Not thro\' some merit, right, or claim,\",\"But by Your gracious love alone.\",\"We strain to glimpse Your mercy-seat,\",\"And find You kneeling at our feet.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0396', 'verse', 4, 3, '[\"Then take the towel, and break the bread,\",\"And humble us, and call us friends.\",\"Suffer and serve till all are fed\",\"And show how grandly love intends\",\"To work till all creation sings,\",\"To fill all worlds, to crown all things.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0396', 'verse', 5, 4, '[\"Lord God, in Christ You set us free\",\"Your life to live, Your joy to share.\",\"Give us Your Spirit\'s liberty\",\"To turn from guilt and dull despair\",\"And offer all that faith can do,\",\"While love is making all things new.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0397', 397, 'An Upper Room', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'An upper room did our Lord prepare
For those loved until the end:
And His disciples still gather there,
To celebrate their risen Friend.
And after supper He washed their feet,
For service, too, is sacrament.
In Him our joy shall be made complete
Sent out to serve, as He was sent.
A lasting gift Jesus gave His own:
To share His bread, His loving cup.
Whatever burdens may bow us down,
He by His cross shall lift us up.
No end there is! we depart in peace.
He loves beyond our uttermost:
In every room in our Father\'s house,
He will be there, as Lord and host.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0397', 'verse', 1, 0, '[\"An upper room did our Lord prepare\",\"For those loved until the end:\",\"And His disciples still gather there,\",\"To celebrate their risen Friend.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0397', 'verse', 2, 1, '[\"And after supper He washed their feet,\",\"For service, too, is sacrament.\",\"In Him our joy shall be made complete\",\"Sent out to serve, as He was sent.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0397', 'verse', 3, 2, '[\"A lasting gift Jesus gave His own:\",\"To share His bread, His loving cup.\",\"Whatever burdens may bow us down,\",\"He by His cross shall lift us up.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0397', 'verse', 4, 3, '[\"No end there is! we depart in peace.\",\"He loves beyond our uttermost:\",\"In every room in our Father\'s house,\",\"He will be there, as Lord and host.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0398', 398, 'Bread of the World', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Bread of the world in mercy broken,
Wine of the soul in mercy shed,
By whom the words of life are spoken,
And in whose death our sins are dead;
Look on the heart by sorrow broken,
Look on the tears by sinners shed;
And be Thy feast to us the token
That by Thy grace our souls are fed.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0398', 'verse', 1, 0, '[\"Bread of the world in mercy broken,\",\"Wine of the soul in mercy shed,\",\"By whom the words of life are spoken,\",\"And in whose death our sins are dead;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0398', 'verse', 2, 1, '[\"Look on the heart by sorrow broken,\",\"Look on the tears by sinners shed;\",\"And be Thy feast to us the token\",\"That by Thy grace our souls are fed.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0399', 399, 'Beneath the Forms of Outward Rite', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Beneath the forms of outward rite
Thy supper, Lord, is spread
In every quiet upper room
Where fainting souls are fed.
The bread is always consecrate
Which men divide with men;
And every act of brotherhood
Repeats Thy feast again.
The blessed cup is only passed
True memory of Thee,
When life anew pours out its wine
With rich sufficiency.
O Master, through these symbols shared,
Thine own dear self impart,
That in our daily life may flame
The passion of Thy heart.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0399', 'verse', 1, 0, '[\"Beneath the forms of outward rite\",\"Thy supper, Lord, is spread\",\"In every quiet upper room\",\"Where fainting souls are fed.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0399', 'verse', 2, 1, '[\"The bread is always consecrate\",\"Which men divide with men;\",\"And every act of brotherhood\",\"Repeats Thy feast again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0399', 'verse', 3, 2, '[\"The blessed cup is only passed\",\"True memory of Thee,\",\"When life anew pours out its wine\",\"With rich sufficiency.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0399', 'verse', 4, 3, '[\"O Master, through these symbols shared,\",\"Thine own dear self impart,\",\"That in our daily life may flame\",\"The passion of Thy heart.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0400', 400, 'I Come With Joy', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I come with joy to meet my Lord,
Forgiven, loved and free,
In awe and wonder to recall
His life laid down for me,
His life laid down for me.
I come with Christians far and near
To find, as all are fed,
Our true community of love
In Christ\'s communion bread,
In Christ\'s communion bread.
As Christ breaks bread for us to share
Each proud division ends.
That love that made us makes us one,
And strangers now are friends,
And strangers now are friends.
And thus with joy we meet our Lord.
His presence always near,
Is in such friendship better known:
We see and praise Him here,
We see and praise Him here.
Together met, together bound,
We\'ll go our diff\'rent ways,
And as His people in the world,
We\'ll live and speak His praise,
We\'ll live and speak His praise.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0400', 'verse', 1, 0, '[\"I come with joy to meet my Lord,\",\"Forgiven, loved and free,\",\"In awe and wonder to recall\",\"His life laid down for me,\",\"His life laid down for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0400', 'verse', 2, 1, '[\"I come with Christians far and near\",\"To find, as all are fed,\",\"Our true community of love\",\"In Christ\'s communion bread,\",\"In Christ\'s communion bread.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0400', 'verse', 3, 2, '[\"As Christ breaks bread for us to share\",\"Each proud division ends.\",\"That love that made us makes us one,\",\"And strangers now are friends,\",\"And strangers now are friends.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0400', 'verse', 4, 3, '[\"And thus with joy we meet our Lord.\",\"His presence always near,\",\"Is in such friendship better known:\",\"We see and praise Him here,\",\"We see and praise Him here.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0400', 'verse', 5, 4, '[\"Together met, together bound,\",\"We\'ll go our diff\'rent ways,\",\"And as His people in the world,\",\"We\'ll live and speak His praise,\",\"We\'ll live and speak His praise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0401', 401, 'In Imitation, Lord of Thee', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'In imitation, Lord, of Thee,
This solemn service we repeat;
For Thine example, full of grace,
Has made this humble duty sweet.
Renew each sacred spark of love,
And vitalize the holy flame;
May union strong our hearts unite
While this we do in Jesus\' name.
Our great example Thou shalt be,
In washing Thy disciples feet;
And as we follow Thy command,
Make Thou our fellowship complete.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0401', 'verse', 1, 0, '[\"In imitation, Lord, of Thee,\",\"This solemn service we repeat;\",\"For Thine example, full of grace,\",\"Has made this humble duty sweet.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0401', 'verse', 2, 1, '[\"Renew each sacred spark of love,\",\"And vitalize the holy flame;\",\"May union strong our hearts unite\",\"While this we do in Jesus\' name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0401', 'verse', 3, 2, '[\"Our great example Thou shalt be,\",\"In washing Thy disciples feet;\",\"And as we follow Thy command,\",\"Make Thou our fellowship complete.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0402', 402, 'By Christ Redeemed', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'By Christ redeemed, in Christ restored,
We keep the memory adored,
And show the death of our dear Lord,
Until He come.
His broken body in our
stead Is here, in this memorial bread;
And so our feeble love is fed,
Until He come.
His fearful drops of agony,
His lifeblood shed for us we see;
The wine shall tell the mystery,
Until He come.
And thus that dark betrayal night,
With the last advent we unite-
The shame, the glory, by this rite,
Until He come.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0402', 'verse', 1, 0, '[\"By Christ redeemed, in Christ restored,\",\"We keep the memory adored,\",\"And show the death of our dear Lord,\",\"Until He come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0402', 'verse', 2, 1, '[\"His broken body in our\",\"stead Is here, in this memorial bread;\",\"And so our feeble love is fed,\",\"Until He come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0402', 'verse', 3, 2, '[\"His fearful drops of agony,\",\"His lifeblood shed for us we see;\",\"The wine shall tell the mystery,\",\"Until He come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0402', 'verse', 4, 3, '[\"And thus that dark betrayal night,\",\"With the last advent we unite-\",\"The shame, the glory, by this rite,\",\"Until He come.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0403', 403, 'Let Us Break Bread Together', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Let us break bread together on our knees;
Let us break bread together on our knees.
When I fall on my knees,
With my face to the rising sun,
O Lord, have mercy on me.
Let us drink wine together on our knees;
Let us drink wine together on our knees.
Let us praise God together on our knees;
Let us praise God together on our knees.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0403', 'verse', 1, 0, '[\"Let us break bread together on our knees;\",\"Let us break bread together on our knees.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0403', 'chorus', 0, 1, '[\"When I fall on my knees,\",\"With my face to the rising sun,\",\"O Lord, have mercy on me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0403', 'verse', 2, 2, '[\"Let us drink wine together on our knees;\",\"Let us drink wine together on our knees.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0403', 'verse', 3, 3, '[\"Let us praise God together on our knees;\",\"Let us praise God together on our knees.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0404', 404, 'Now Let Us From This Table Rise', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Now let us from this table rise
Renewed in body, mind, and soul;
With Christ we die and live again,
His selfless love has made us whole.
With minds alert, upheld by grace,
To spread the word in speech and deed,
We follow in the steps of Christ,
At one with all in hope and need.
To fill each human house with love,
It is the sacrament of care;
The work that Christ began to do
We humbly pledge ourselves to share.
Then grant us courage, Father God,
To choose again the pilgrim way
And help us to accept with joy
The challenge of tomorrow\'s day.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0404', 'verse', 1, 0, '[\"Now let us from this table rise\",\"Renewed in body, mind, and soul;\",\"With Christ we die and live again,\",\"His selfless love has made us whole.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0404', 'verse', 2, 1, '[\"With minds alert, upheld by grace,\",\"To spread the word in speech and deed,\",\"We follow in the steps of Christ,\",\"At one with all in hope and need.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0404', 'verse', 3, 2, '[\"To fill each human house with love,\",\"It is the sacrament of care;\",\"The work that Christ began to do\",\"We humbly pledge ourselves to share.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0404', 'verse', 4, 3, '[\"Then grant us courage, Father God,\",\"To choose again the pilgrim way\",\"And help us to accept with joy\",\"The challenge of tomorrow\'s day.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0405', 405, 'O God, Unseen, Yet Ever Near', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O God, unseen, yet ever near,
Reveal Thy presence now
While we in love that hath no fear,
Before Thy glory bow.
Here may Thy faithful people know
The blessings of Thy love,
The streams that thro\' the desert flow,
The manna from above.
We come, obedient to Thy Word
To feast on heav\'nly food,
Our meat, the body of our Lord,
Our drink, His precious blood.
Thus may we all Thy words obey,
For we, O God, are Thine,
And go rejoicing on our way,
Renewed by strength divine.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0405', 'verse', 1, 0, '[\"O God, unseen, yet ever near,\",\"Reveal Thy presence now\",\"While we in love that hath no fear,\",\"Before Thy glory bow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0405', 'verse', 2, 1, '[\"Here may Thy faithful people know\",\"The blessings of Thy love,\",\"The streams that thro\' the desert flow,\",\"The manna from above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0405', 'verse', 3, 2, '[\"We come, obedient to Thy Word\",\"To feast on heav\'nly food,\",\"Our meat, the body of our Lord,\",\"Our drink, His precious blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0405', 'verse', 4, 3, '[\"Thus may we all Thy words obey,\",\"For we, O God, are Thine,\",\"And go rejoicing on our way,\",\"Renewed by strength divine.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0406', 406, 'Love Consecrates the Humblest Act', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Love consecrates the humblest act
And haloes mercy\'s deeds;
It sheds a benediction sweet
And hallows human needs.
When in the shadow of the cross
Christ knelt and washed the feet
Of His disciples, He gave us
A sign of love complete.
Love serves and willing, stoops to serve;
What Christ in love so true
Has freely done for one and all,
Let us now gladly do!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0406', 'verse', 1, 0, '[\"Love consecrates the humblest act\",\"And haloes mercy\'s deeds;\",\"It sheds a benediction sweet\",\"And hallows human needs.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0406', 'verse', 2, 1, '[\"When in the shadow of the cross\",\"Christ knelt and washed the feet\",\"Of His disciples, He gave us\",\"A sign of love complete.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0406', 'verse', 3, 2, '[\"Love serves and willing, stoops to serve;\",\"What Christ in love so true\",\"Has freely done for one and all,\",\"Let us now gladly do!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0407', 407, 'Sent Forth By God\'s Blessing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Sent forth by God\'s blessing,
Our true faith confessing,
The people of God from His dwelling take leave.
The supper is ended.
Oh, now be extended
The fruits of this service in all who believe.
The seed of His teaching,
Receptive souls reaching,
Shall blossom in action for God and for all.
His grace did invite us,
His love shall unite us
To work for God\'s kingdom and answer His call.
With praise and thanksgiving
To God ever-living,
The tasks of our everyday life we will face.
Our faith ever sharing,
In love ever caring,
Embracing His children of each tribe and race.
With Your feast You feed us,
With Your light now lead us;
Unite us as one in this life that we share.
Then may all the living
With praise and thanksgiving
Give honor to Christ and His name that we bear.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0407', 'verse', 1, 0, '[\"Sent forth by God\'s blessing,\",\"Our true faith confessing,\",\"The people of God from His dwelling take leave.\",\"The supper is ended.\",\"Oh, now be extended\",\"The fruits of this service in all who believe.\",\"The seed of His teaching,\",\"Receptive souls reaching,\",\"Shall blossom in action for God and for all.\",\"His grace did invite us,\",\"His love shall unite us\",\"To work for God\'s kingdom and answer His call.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0407', 'verse', 2, 1, '[\"With praise and thanksgiving\",\"To God ever-living,\",\"The tasks of our everyday life we will face.\",\"Our faith ever sharing,\",\"In love ever caring,\",\"Embracing His children of each tribe and race.\",\"With Your feast You feed us,\",\"With Your light now lead us;\",\"Unite us as one in this life that we share.\",\"Then may all the living\",\"With praise and thanksgiving\",\"Give honor to Christ and His name that we bear.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0408', 408, 'Lord, Enthroned in Heavenly Splendor', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lord, enthroned in heav\'nly splendor,
First begotten from the dead,
You alone, our strong defender,
Lifting up Your people\'s head.
Alleluia,
Jesus, true and living Bread!
Tho\' the lowliest form now veil You
As of old in Bethlehem,
Here as there Your angels hail You
Branch and flow\'r of Jesse\'s stem.
Alleluia,
We in worship join with them.
Paschal Lamb, Your off\'ring finished
Once for all where You were slain,
In its fullness undiminished
Shall forever more remain.
Alleluia,
Cleansing souls from every stain.
Life-imparting heav\'nly manna,
Stricken rock with streaming side,
Heav\'n and earth with loud hosanna
Worship You the Lamb who died.
Alleluia,
Ris\'n, ascended, glorified!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0408', 'verse', 1, 0, '[\"Lord, enthroned in heav\'nly splendor,\",\"First begotten from the dead,\",\"You alone, our strong defender,\",\"Lifting up Your people\'s head.\",\"Alleluia,\",\"Jesus, true and living Bread!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0408', 'verse', 2, 1, '[\"Tho\' the lowliest form now veil You\",\"As of old in Bethlehem,\",\"Here as there Your angels hail You\",\"Branch and flow\'r of Jesse\'s stem.\",\"Alleluia,\",\"We in worship join with them.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0408', 'verse', 3, 2, '[\"Paschal Lamb, Your off\'ring finished\",\"Once for all where You were slain,\",\"In its fullness undiminished\",\"Shall forever more remain.\",\"Alleluia,\",\"Cleansing souls from every stain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0408', 'verse', 4, 3, '[\"Life-imparting heav\'nly manna,\",\"Stricken rock with streaming side,\",\"Heav\'n and earth with loud hosanna\",\"Worship You the Lamb who died.\",\"Alleluia,\",\"Ris\'n, ascended, glorified!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0409', 409, 'Jesus Invites His Saints', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Jesus invites His saints
To meet around His board,
And sup in memory of the death
And sufferings of their Lord.
We take the bread and wine
As emblems of Thy death;
Lord, raise our souls above the sign,
To feast on Thee by faith.
Faith eats the bread of life,
And drinks the living wine;
It looks beyond this scene of strife;
Unites us to the Vine.
Soon shall the night be gone,
Our Lord will come again;
The marriage supper of the Lamb
Will usher in His reign.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0409', 'verse', 1, 0, '[\"Jesus invites His saints\",\"To meet around His board,\",\"And sup in memory of the death\",\"And sufferings of their Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0409', 'verse', 2, 1, '[\"We take the bread and wine\",\"As emblems of Thy death;\",\"Lord, raise our souls above the sign,\",\"To feast on Thee by faith.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0409', 'verse', 3, 2, '[\"Faith eats the bread of life,\",\"And drinks the living wine;\",\"It looks beyond this scene of strife;\",\"Unites us to the Vine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0409', 'verse', 4, 3, '[\"Soon shall the night be gone,\",\"Our Lord will come again;\",\"The marriage supper of the Lamb\",\"Will usher in His reign.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0410', 410, 'Thy Broken Body Gracious Lord', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Thy broken body, gracious Lord,
Is shadowed by this broken bread;
The wine which in this cup is poured,
Points to the blood which Thou hast shed.
And while we meet together thus,
We show that we are one in Thee;
Thy precious blood was shed for us,
Thy death, O Lord, hast set us free!
We have one hope that Thou wilt come,
Thee in the air we wait to see;
When Thou wilt give Thy saints a home,
And we shall ever reign with Thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0410', 'verse', 1, 0, '[\"Thy broken body, gracious Lord,\",\"Is shadowed by this broken bread;\",\"The wine which in this cup is poured,\",\"Points to the blood which Thou hast shed.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0410', 'verse', 2, 1, '[\"And while we meet together thus,\",\"We show that we are one in Thee;\",\"Thy precious blood was shed for us,\",\"Thy death, O Lord, hast set us free!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0410', 'verse', 3, 2, '[\"We have one hope that Thou wilt come,\",\"Thee in the air we wait to see;\",\"When Thou wilt give Thy saints a home,\",\"And we shall ever reign with Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0411', 411, 'The Son of God Proclaim', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'The Son of God proclaim,
The Lord of time and space;
The God who bade the light break forth
Now shines in Jesus\' face.
Behold His outstretched hands,
Though all was in His power
He took the towel and basin then,
And serves us in this hour.
He, God\'s creative word,
The church\'s Lord and head,
Here bids us gather as His friends,
And share His wine and bread.
The Lord of life and death
With wondering praise we sing;
We break the bread at His command,
And name Him God and King.
We take this cup in hope:
For He, who gladly bore
The shameful cross, is ris\'n again,
And reigns forevermore.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0411', 'verse', 1, 0, '[\"The Son of God proclaim,\",\"The Lord of time and space;\",\"The God who bade the light break forth\",\"Now shines in Jesus\' face.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0411', 'verse', 2, 1, '[\"Behold His outstretched hands,\",\"Though all was in His power\",\"He took the towel and basin then,\",\"And serves us in this hour.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0411', 'verse', 3, 2, '[\"He, God\'s creative word,\",\"The church\'s Lord and head,\",\"Here bids us gather as His friends,\",\"And share His wine and bread.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0411', 'verse', 4, 3, '[\"The Lord of life and death\",\"With wondering praise we sing;\",\"We break the bread at His command,\",\"And name Him God and King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0411', 'verse', 5, 4, '[\"We take this cup in hope:\",\"For He, who gladly bore\",\"The shameful cross, is ris\'n again,\",\"And reigns forevermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0412', 412, 'Cover With His Life', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Look upon Jesus, sinless is He;
Father, impute His life unto me.
My life of scarlet, my sin and woe,
Cover with His life, whiter than snow.
Cover with His life, whiter than snow;
Fullness of His life then shall I know;
My life of scarlet, my sin and woe,
Cover with His life, whiter than snow.
Deep are the wounds transgression has made;
Red are the stains; my soul is afraid.
O to be covered, Jesus, with Thee,
Safe from the law that now judgeth me!
Longing the joy of pardon to know;
Jesus holds out a robe white as snow;
\"Lord, I accept it! leaving my own,
Gladly I wear Thy pure life alone.\"
Reconciled by His death for my sin,
Justified by His life pure and clean,
Sanctified by obeying His word,
Glorified when returneth my Lord.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0412', 'verse', 1, 0, '[\"Look upon Jesus, sinless is He;\",\"Father, impute His life unto me.\",\"My life of scarlet, my sin and woe,\",\"Cover with His life, whiter than snow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0412', 'chorus', 0, 1, '[\"Cover with His life, whiter than snow;\",\"Fullness of His life then shall I know;\",\"My life of scarlet, my sin and woe,\",\"Cover with His life, whiter than snow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0412', 'verse', 2, 2, '[\"Deep are the wounds transgression has made;\",\"Red are the stains; my soul is afraid.\",\"O to be covered, Jesus, with Thee,\",\"Safe from the law that now judgeth me!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0412', 'verse', 3, 3, '[\"Longing the joy of pardon to know;\",\"Jesus holds out a robe white as snow;\",\"\\\"Lord, I accept it! leaving my own,\",\"Gladly I wear Thy pure life alone.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0412', 'verse', 4, 4, '[\"Reconciled by His death for my sin,\",\"Justified by His life pure and clean,\",\"Sanctified by obeying His word,\",\"Glorified when returneth my Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0413', 413, 'God Has Spoken By His Prophets', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'God has spoken by His prophets,
Spoken His unchanging Word,
Each from age to age proclaiming
God, the one, the righteous Lord.
Mid the world\'s despair and turmoil,
One firm anchor holding fast;
God is King, His throne eternal,
God the first, and God the last.
God has spoken by Christ Jesus,
Christ, the everlasting Son,
Brightness of the Father\'s glory,
With the Father ever one;
Spoken by the Word incarnate,
God of God, ere time began,
Light of light, to earth descending,
Man, revealing God to man.
God yet speaks by His own Spirit
Speaking to the hearts of men,
In the age-long Word expounding
God\'s own message, now as then;
Through the rise and fall of nations
One sure faith yet standing fast,
God is King, His Word unchanging,
God the first, and God the last.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0413', 'verse', 1, 0, '[\"God has spoken by His prophets,\",\"Spoken His unchanging Word,\",\"Each from age to age proclaiming\",\"God, the one, the righteous Lord.\",\"Mid the world\'s despair and turmoil,\",\"One firm anchor holding fast;\",\"God is King, His throne eternal,\",\"God the first, and God the last.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0413', 'verse', 2, 1, '[\"God has spoken by Christ Jesus,\",\"Christ, the everlasting Son,\",\"Brightness of the Father\'s glory,\",\"With the Father ever one;\",\"Spoken by the Word incarnate,\",\"God of God, ere time began,\",\"Light of light, to earth descending,\",\"Man, revealing God to man.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0413', 'verse', 3, 2, '[\"God yet speaks by His own Spirit\",\"Speaking to the hearts of men,\",\"In the age-long Word expounding\",\"God\'s own message, now as then;\",\"Through the rise and fall of nations\",\"One sure faith yet standing fast,\",\"God is King, His Word unchanging,\",\"God the first, and God the last.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0414', 414, 'Fruitful Trees the Spirit\'s Sowing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Fruitful trees, the Spirit\'s sowing,
May we ripen and increase,
Fruit to life eternal growing,
Rich in love and joy and peace.
Laden branches freely bearing
Gifts the Giver loves to bless;
Here is fruit that grows by sharing,
Patience, kindness, gentleness.
Rooted deep in Christ, our Master,
Christ, our pattern and our goal,
Teach us, as the years fly faster,
Goodness, faith, and self control.
Fruitful trees, the Spirit\'s tending,
May we grow till harvests cease;
Till we taste, in life unending,
Heaven\'s love and joy and peace.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0414', 'verse', 1, 0, '[\"Fruitful trees, the Spirit\'s sowing,\",\"May we ripen and increase,\",\"Fruit to life eternal growing,\",\"Rich in love and joy and peace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0414', 'verse', 2, 1, '[\"Laden branches freely bearing\",\"Gifts the Giver loves to bless;\",\"Here is fruit that grows by sharing,\",\"Patience, kindness, gentleness.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0414', 'verse', 3, 2, '[\"Rooted deep in Christ, our Master,\",\"Christ, our pattern and our goal,\",\"Teach us, as the years fly faster,\",\"Goodness, faith, and self control.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0414', 'verse', 4, 3, '[\"Fruitful trees, the Spirit\'s tending,\",\"May we grow till harvests cease;\",\"Till we taste, in life unending,\",\"Heaven\'s love and joy and peace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0415', 415, 'Christ the Lord All Power Possessing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Christ, the Lord, all power possessing,
Parting, mounted heaven\'s height,
Gracious hands outstretched in blessing,
Clouds received Him from their sight.
Christ ascended, Christ ascended,
Christ ascended on the clouds.
Christ ascended on the clouds.
Daniel views earth\'s judgment hour,
Angels gathering open books.
God enthroned inflaming power
For His Son\'s arrival looks.
Christ approaches, Christ approaches,
Christ approaches on the clouds.
Christ approaches on the clouds.
Revelation\'s word fulfilling,
Trumpet, voices pierce the air.
Saint and sinner fainting, thrilling,
Every eye behold Him there.
Christ is coming, Christ is coming,
Christ is coming on the clouds.
Christ is coming on the clouds.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0415', 'verse', 1, 0, '[\"Christ, the Lord, all power possessing,\",\"Parting, mounted heaven\'s height,\",\"Gracious hands outstretched in blessing,\",\"Clouds received Him from their sight.\",\"Christ ascended, Christ ascended,\",\"Christ ascended on the clouds.\",\"Christ ascended on the clouds.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0415', 'verse', 2, 1, '[\"Daniel views earth\'s judgment hour,\",\"Angels gathering open books.\",\"God enthroned inflaming power\",\"For His Son\'s arrival looks.\",\"Christ approaches, Christ approaches,\",\"Christ approaches on the clouds.\",\"Christ approaches on the clouds.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0415', 'verse', 3, 2, '[\"Revelation\'s word fulfilling,\",\"Trumpet, voices pierce the air.\",\"Saint and sinner fainting, thrilling,\",\"Every eye behold Him there.\",\"Christ is coming, Christ is coming,\",\"Christ is coming on the clouds.\",\"Christ is coming on the clouds.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0416', 416, 'The Judgment Has Set', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'The judgment has set, the books have been opened;
How shall we stand in that great day
When every thought, and word, and action,
God, the righteous Judge, shall weigh?
How shall we stand in that great day?
How shall we stand in that great day?
Shall we be found before Him wanting?
Or with our sins all washed away?
The work is begun with those who are sleeping,
Soon will the living here be tried,
Out of the books of God\'s remembrance,
His decision to abide.
O, how shall we stand that moment of searching,
When all our sins those books reveal?
When from that court, each case decided,
Shall be granted no appeal?');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0416', 'verse', 1, 0, '[\"The judgment has set, the books have been opened;\",\"How shall we stand in that great day\",\"When every thought, and word, and action,\",\"God, the righteous Judge, shall weigh?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0416', 'chorus', 0, 1, '[\"How shall we stand in that great day?\",\"How shall we stand in that great day?\",\"Shall we be found before Him wanting?\",\"Or with our sins all washed away?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0416', 'verse', 2, 2, '[\"The work is begun with those who are sleeping,\",\"Soon will the living here be tried,\",\"Out of the books of God\'s remembrance,\",\"His decision to abide.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0416', 'verse', 3, 3, '[\"O, how shall we stand that moment of searching,\",\"When all our sins those books reveal?\",\"When from that court, each case decided,\",\"Shall be granted no appeal?\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0417', 417, 'O Solemn Thought', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O solemn thought and can it be
The hour of judgment now is come
Which soon must fix our destiny,
And seal the sinner\'s fearful doom?
Yes, it is so; the judgment hour
Is swiftly hastening to its close;
Then will the Judge, in mighty power,
Descend in vengeance on His foes.
He who came down to earth to die
An offering for the sins of men,
And then ascended upon on high,
And will e\'er long return again,
Is standing now before the ark,
And mercy seat and cherubim,
To plead His blood for saints, and make
The last remembrance of their sin.
The solemn moment is at hand
When we who have His name confessed,
Each in his lot must singly stand
And pass the final, searching test.
Jesus! we hope in Thee alone;
In mercy now upon us look,
Confess our names before the throne,
And blot our sins from out Thy book.
O blessed Savior! may we feel
The full importance of this hour.
Inspire our hearts with holy zeal,
And aid us by Thy Spirit\'s power,
That we may in Thy strength be strong,
And brave the conflict valiantly;
Then, on Mount Zion, join the song,
And swell the notes of victory.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0417', 'verse', 1, 0, '[\"O solemn thought and can it be\",\"The hour of judgment now is come\",\"Which soon must fix our destiny,\",\"And seal the sinner\'s fearful doom?\",\"Yes, it is so; the judgment hour\",\"Is swiftly hastening to its close;\",\"Then will the Judge, in mighty power,\",\"Descend in vengeance on His foes.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0417', 'verse', 2, 1, '[\"He who came down to earth to die\",\"An offering for the sins of men,\",\"And then ascended upon on high,\",\"And will e\'er long return again,\",\"Is standing now before the ark,\",\"And mercy seat and cherubim,\",\"To plead His blood for saints, and make\",\"The last remembrance of their sin.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0417', 'verse', 3, 2, '[\"The solemn moment is at hand\",\"When we who have His name confessed,\",\"Each in his lot must singly stand\",\"And pass the final, searching test.\",\"Jesus! we hope in Thee alone;\",\"In mercy now upon us look,\",\"Confess our names before the throne,\",\"And blot our sins from out Thy book.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0417', 'verse', 4, 3, '[\"O blessed Savior! may we feel\",\"The full importance of this hour.\",\"Inspire our hearts with holy zeal,\",\"And aid us by Thy Spirit\'s power,\",\"That we may in Thy strength be strong,\",\"And brave the conflict valiantly;\",\"Then, on Mount Zion, join the song,\",\"And swell the notes of victory.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0418', 418, 'Day of Judgment, Day of Wonders!', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Day of judgment, day of wonders!
Hark the trumpet\'s awful sound,
Louder than a thousand thunders,
Shakes the vast creation round!
How the summons,
How the summons
Will the sinner\'s heart confound!
See the Lord in glory nearing,
Clothed in majesty divine.
You who long for His appearing,
Then shall say, \'\'This God is mine!\"
Gracious Savior,
Gracious Savior,
Own me in that day as Thine.
At His call the dead awaken,
Rise to life from earth and sea!
All the powers of nature shaken
By His looks prepare to flee.
Careless sinner,
Careless sinner,
What will then become of thee?
But to those who have confessed
Loved and served the Lord below,
He will say, \"Come near, ye blessed,
See the kingdom I bestow;
You forever,
You forever
Shall My love and glory know?\"');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0418', 'verse', 1, 0, '[\"Day of judgment, day of wonders!\",\"Hark the trumpet\'s awful sound,\",\"Louder than a thousand thunders,\",\"Shakes the vast creation round!\",\"How the summons,\",\"How the summons\",\"Will the sinner\'s heart confound!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0418', 'verse', 2, 1, '[\"See the Lord in glory nearing,\",\"Clothed in majesty divine.\",\"You who long for His appearing,\",\"Then shall say, \'\'This God is mine!\\\"\",\"Gracious Savior,\",\"Gracious Savior,\",\"Own me in that day as Thine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0418', 'verse', 3, 2, '[\"At His call the dead awaken,\",\"Rise to life from earth and sea!\",\"All the powers of nature shaken\",\"By His looks prepare to flee.\",\"Careless sinner,\",\"Careless sinner,\",\"What will then become of thee?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0418', 'verse', 4, 3, '[\"But to those who have confessed\",\"Loved and served the Lord below,\",\"He will say, \\\"Come near, ye blessed,\",\"See the kingdom I bestow;\",\"You forever,\",\"You forever\",\"Shall My love and glory know?\\\"\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0419', 419, 'Soon Shall the Trump of God', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Soon shall the trump of God
Give out the welcome sound,
That shakes death\'s silent chamber walls,
And breaks the turf sealed ground.
You dwellers in the dust,
Awake, come forth, and sing;
Sharp has your frost of winter been,
But bright shall be your spring.
\'Twas sown in weakness here;
\'Twill then be raised in power;
That which was sown in earthly seed
Shall rise a heav\'nly flower.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0419', 'verse', 1, 0, '[\"Soon shall the trump of God\",\"Give out the welcome sound,\",\"That shakes death\'s silent chamber walls,\",\"And breaks the turf sealed ground.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0419', 'verse', 2, 1, '[\"You dwellers in the dust,\",\"Awake, come forth, and sing;\",\"Sharp has your frost of winter been,\",\"But bright shall be your spring.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0419', 'verse', 3, 2, '[\"\'Twas sown in weakness here;\",\"\'Twill then be raised in power;\",\"That which was sown in earthly seed\",\"Shall rise a heav\'nly flower.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0420', 420, 'Jerusalem My Happy Home', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Jerusalem, my happy home,
O how I long for thee!
When will my sorrows have an end,
The joys when shall I see?
The walls are all of precious stone,
Most glorious to behold;
Thy gates are richly set with pearl,
Thy streets are paved with gold.
Thy garden and thy pleasant walks
My study long have been;
Such dazzling views by human sight
Have never yet been seen.
Lord, help us by Thy mighty grace,
To keep in view the prize,
Till Thou dost come to take us home
To that blessed paradise.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0420', 'verse', 1, 0, '[\"Jerusalem, my happy home,\",\"O how I long for thee!\",\"When will my sorrows have an end,\",\"The joys when shall I see?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0420', 'verse', 2, 1, '[\"The walls are all of precious stone,\",\"Most glorious to behold;\",\"Thy gates are richly set with pearl,\",\"Thy streets are paved with gold.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0420', 'verse', 3, 2, '[\"Thy garden and thy pleasant walks\",\"My study long have been;\",\"Such dazzling views by human sight\",\"Have never yet been seen.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0420', 'verse', 4, 3, '[\"Lord, help us by Thy mighty grace,\",\"To keep in view the prize,\",\"Till Thou dost come to take us home\",\"To that blessed paradise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0421', 421, 'For All the Saints', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'For all the saints who from their labors rest,
Who Thee by faith before the world confessed,
Thy name, O Jesus, be forever blest:
Alleluia!
Alleluia!
Thou wast their Rock, their Fortress, and their Might,
Thou, Lord, their captain in the well-fought fight;
Thou, in the darkness drear, their one true light:
Alleluia!
Alleluia!
O may Thy soldiers, faithful, true, and bold,
Fight as the saints who nobly fought of old,
And win with them the victor\'s crown of gold:
Alleluia!
Alleluia!
And when the strife is fierce, the warfare long,
Steals on the ear the distant triumph song,
And hearts are brave again, and arms are strong.
Alleluia!
Alleluia!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0421', 'verse', 1, 0, '[\"For all the saints who from their labors rest,\",\"Who Thee by faith before the world confessed,\",\"Thy name, O Jesus, be forever blest:\",\"Alleluia!\",\"Alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0421', 'verse', 2, 1, '[\"Thou wast their Rock, their Fortress, and their Might,\",\"Thou, Lord, their captain in the well-fought fight;\",\"Thou, in the darkness drear, their one true light:\",\"Alleluia!\",\"Alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0421', 'verse', 3, 2, '[\"O may Thy soldiers, faithful, true, and bold,\",\"Fight as the saints who nobly fought of old,\",\"And win with them the victor\'s crown of gold:\",\"Alleluia!\",\"Alleluia!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0421', 'verse', 4, 3, '[\"And when the strife is fierce, the warfare long,\",\"Steals on the ear the distant triumph song,\",\"And hearts are brave again, and arms are strong.\",\"Alleluia!\",\"Alleluia!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0422', 422, 'Marching to Zion', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Come, we that love the Lord,
And let our joys be known;
Join in a song with sweet accord,
Join in a song with sweet accord,
And thus surround the throne,
And thus surround the throne.
We\'re marching to Zion,
Beautiful, Beautiful Zion;
We\'re marching upward to Zion,
The beautiful city of God.
Let those refuse to sing
Who never knew our God;
But children of the heavenly King,
But children of the heavenly King,
May speak their joys abroad,
May speak their joys abroad.
The hill of Zion yields
A thousand sacred sweets,
Before we reach the heavenly fields,
Before we reach the heavenly fields
Or walk the golden streets,
Or walk the golden streets.
Then let our songs abound,
And every tear be dry;
We\'re marching through Immanuel\'s ground,
We\'re marching through Immanuel\'s ground,
To fairer worlds on high,
To fairer worlds on high.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0422', 'verse', 1, 0, '[\"Come, we that love the Lord,\",\"And let our joys be known;\",\"Join in a song with sweet accord,\",\"Join in a song with sweet accord,\",\"And thus surround the throne,\",\"And thus surround the throne.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0422', 'chorus', 0, 1, '[\"We\'re marching to Zion,\",\"Beautiful, Beautiful Zion;\",\"We\'re marching upward to Zion,\",\"The beautiful city of God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0422', 'verse', 2, 2, '[\"Let those refuse to sing\",\"Who never knew our God;\",\"But children of the heavenly King,\",\"But children of the heavenly King,\",\"May speak their joys abroad,\",\"May speak their joys abroad.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0422', 'verse', 3, 3, '[\"The hill of Zion yields\",\"A thousand sacred sweets,\",\"Before we reach the heavenly fields,\",\"Before we reach the heavenly fields\",\"Or walk the golden streets,\",\"Or walk the golden streets.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0422', 'verse', 4, 4, '[\"Then let our songs abound,\",\"And every tear be dry;\",\"We\'re marching through Immanuel\'s ground,\",\"We\'re marching through Immanuel\'s ground,\",\"To fairer worlds on high,\",\"To fairer worlds on high.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0423', 423, 'Glorious Things of Thee Are Spoken', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Glorious things of thee are spoken,
Zion, city of our God;
He whose word cannot be broken
Formed thee for His own abode;
On the Rock of Ages founded,
What can shake thy sure repose?
With salvation\'s wall surrounded,
Thou mayst smile at all thy foes.
See the streams of living waters
Springing from eternal love,
Well supply thy sons and daughters,
And all fear and want remove;
Who can faint when such a river
Ever flows their thirst to assuage?
Grace, which, like the Lord, the Giver,
Never fails from age to age.
Round each habitation hovering,
See the cloud and fire appear
For a glory and a covering,
Showing that the Lord is near;
Blest inhabitants of Zion,
Washed in the Redeemer\'s blood;
Jesus, whom their souls rely on,
Makes them kings and priests to God.
Savior, if of Zion\'s city
I, through grace, a member am,
Let the world deride or pity,
I will glory in Thy name;
Fading is the worldling\'s pleasure,
All his boasted pomp and show;
Solid joys and lasting treasure
None but Zion\'s children know.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0423', 'verse', 1, 0, '[\"Glorious things of thee are spoken,\",\"Zion, city of our God;\",\"He whose word cannot be broken\",\"Formed thee for His own abode;\",\"On the Rock of Ages founded,\",\"What can shake thy sure repose?\",\"With salvation\'s wall surrounded,\",\"Thou mayst smile at all thy foes.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0423', 'verse', 2, 1, '[\"See the streams of living waters\",\"Springing from eternal love,\",\"Well supply thy sons and daughters,\",\"And all fear and want remove;\",\"Who can faint when such a river\",\"Ever flows their thirst to assuage?\",\"Grace, which, like the Lord, the Giver,\",\"Never fails from age to age.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0423', 'verse', 3, 2, '[\"Round each habitation hovering,\",\"See the cloud and fire appear\",\"For a glory and a covering,\",\"Showing that the Lord is near;\",\"Blest inhabitants of Zion,\",\"Washed in the Redeemer\'s blood;\",\"Jesus, whom their souls rely on,\",\"Makes them kings and priests to God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0423', 'verse', 4, 3, '[\"Savior, if of Zion\'s city\",\"I, through grace, a member am,\",\"Let the world deride or pity,\",\"I will glory in Thy name;\",\"Fading is the worldling\'s pleasure,\",\"All his boasted pomp and show;\",\"Solid joys and lasting treasure\",\"None but Zion\'s children know.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0424', 424, 'For Thee, O Dear, Dear Country', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'For thee, O dear, dear country,
Mine eyes their vigils keep;
For very love beholding
Thy holy name, they weep.
The mention of thy glory
Is unction to the breast,
And medicine in sickness,
And love, and life, and rest.
O one, O only mansion!
O Paradise of joy!
Where tears are ever banish\'d
And smiles have no alloy;
Thy loveliness oppresses
All human thought and heart,
And none, O Peace, O Sion,
Can sing thavas thou art.
With jasper glow thy bulwarks,
Thy streets with emeralds blaze;
The sardius and the topaz
Unite in thee their rays;
Thine ageless walls are bonded
With amethyst unpriced;
The saints shall build thy fabric,
And the cornerstone is Christ.
The cross is all thy splendor,
The Crucified thy praise;
His laud and benediction
Thy ransom\'d saints shall raise;
Upon the Rock of Ages
They build thy holy tower;
Thine is the victor\'s laurel,
And thine the golden dower.
O sweet and blessed country,
The home of God\'s elect!
O sweet and blessed country
That eager hearts expect!
Jesus, in mercy bring us
To that dear land of rest,
Who art, with God the Father,
And Spirit, ever blest.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0424', 'verse', 1, 0, '[\"For thee, O dear, dear country,\",\"Mine eyes their vigils keep;\",\"For very love beholding\",\"Thy holy name, they weep.\",\"The mention of thy glory\",\"Is unction to the breast,\",\"And medicine in sickness,\",\"And love, and life, and rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0424', 'verse', 2, 1, '[\"O one, O only mansion!\",\"O Paradise of joy!\",\"Where tears are ever banish\'d\",\"And smiles have no alloy;\",\"Thy loveliness oppresses\",\"All human thought and heart,\",\"And none, O Peace, O Sion,\",\"Can sing thavas thou art.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0424', 'verse', 3, 2, '[\"With jasper glow thy bulwarks,\",\"Thy streets with emeralds blaze;\",\"The sardius and the topaz\",\"Unite in thee their rays;\",\"Thine ageless walls are bonded\",\"With amethyst unpriced;\",\"The saints shall build thy fabric,\",\"And the cornerstone is Christ.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0424', 'verse', 4, 3, '[\"The cross is all thy splendor,\",\"The Crucified thy praise;\",\"His laud and benediction\",\"Thy ransom\'d saints shall raise;\",\"Upon the Rock of Ages\",\"They build thy holy tower;\",\"Thine is the victor\'s laurel,\",\"And thine the golden dower.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0424', 'verse', 5, 4, '[\"O sweet and blessed country,\",\"The home of God\'s elect!\",\"O sweet and blessed country\",\"That eager hearts expect!\",\"Jesus, in mercy bring us\",\"To that dear land of rest,\",\"Who art, with God the Father,\",\"And Spirit, ever blest.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0425', 425, 'Holy, Holy, Is What the Angels Sing', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'There is singing up in heaven such as we have never known,
Where the angels sing the praises of the Lamb upon the throne;
Their sweet harps are ever tuneful and their voices always clear,
O that we might be more like them while we serve the Master here!
Holy, holy, is what the angels sing,
And I expect to help them make the courts of heaven ring;
But when I sing redemption\'s story, they will fold their wings,
For angels never felt the joys that our salvation brings.
But I hear another anthem, blending voices clear and strong,
\"Unto Him who hath redeemed us and hath bought us,\" is the song;
We have come thro\' tribulations to this land so fair and bright,
In the fountain freely flowing He hath made our garments white.
Then the angels stand and listen, for they cannot join that song,
Like the sound of many waters, by that happy, bloodwashed throng;
For they sing about great trials, battles fought and vict\'ries won,
And they praise their great Redeemer, who hath said to them, \"Well done.\"
So, although I\'m not an angel, yet I know that over there
I will join a blessed chorus that the angels cannot share;
I will sing about my Savior, who upon dark Calvary
Freely pardoned my transgressions, died to set a sinner free.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0425', 'verse', 1, 0, '[\"There is singing up in heaven such as we have never known,\",\"Where the angels sing the praises of the Lamb upon the throne;\",\"Their sweet harps are ever tuneful and their voices always clear,\",\"O that we might be more like them while we serve the Master here!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0425', 'chorus', 0, 1, '[\"Holy, holy, is what the angels sing,\",\"And I expect to help them make the courts of heaven ring;\",\"But when I sing redemption\'s story, they will fold their wings,\",\"For angels never felt the joys that our salvation brings.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0425', 'verse', 2, 2, '[\"But I hear another anthem, blending voices clear and strong,\",\"\\\"Unto Him who hath redeemed us and hath bought us,\\\" is the song;\",\"We have come thro\' tribulations to this land so fair and bright,\",\"In the fountain freely flowing He hath made our garments white.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0425', 'verse', 3, 3, '[\"Then the angels stand and listen, for they cannot join that song,\",\"Like the sound of many waters, by that happy, bloodwashed throng;\",\"For they sing about great trials, battles fought and vict\'ries won,\",\"And they praise their great Redeemer, who hath said to them, \\\"Well done.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0425', 'verse', 4, 4, '[\"So, although I\'m not an angel, yet I know that over there\",\"I will join a blessed chorus that the angels cannot share;\",\"I will sing about my Savior, who upon dark Calvary\",\"Freely pardoned my transgressions, died to set a sinner free.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0426', 426, 'I Shall See the King', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I shall see the King
Where the angels sing,
I shall see the King some day,
In the better land,
On the golden strand
And with Him shall ever stay.
In His glory, I shall see the King,
And forever endless praises sing;
\'Twas on Calvary Jesus died for me;
I shall see the King some day.
In the land of song,
In the glory throng,
Where there never comes a night,
With my Lord once slain
I shall ever reign
In the glory land of light.
I shall see the King,
All my tributes bring,
And shall look upon His face;
Then my song shall be
How He ransomed me
And has kept me by His grace.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0426', 'verse', 1, 0, '[\"I shall see the King\",\"Where the angels sing,\",\"I shall see the King some day,\",\"In the better land,\",\"On the golden strand\",\"And with Him shall ever stay.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0426', 'chorus', 0, 1, '[\"In His glory, I shall see the King,\",\"And forever endless praises sing;\",\"\'Twas on Calvary Jesus died for me;\",\"I shall see the King some day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0426', 'verse', 2, 2, '[\"In the land of song,\",\"In the glory throng,\",\"Where there never comes a night,\",\"With my Lord once slain\",\"I shall ever reign\",\"In the glory land of light.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0426', 'verse', 3, 3, '[\"I shall see the King,\",\"All my tributes bring,\",\"And shall look upon His face;\",\"Then my song shall be\",\"How He ransomed me\",\"And has kept me by His grace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0427', 427, 'No Night There', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'In the land of fadeless day
Lies \"the city foursquare;\"
It shall never pass away,
And there is \"no night there?\"
God shall \"wipe away all tears;\"
There\'s no death, no pain, nor fears;
And they count not time by years,
For there is \"no night there.\"
All the gates of pearl are made,
In \"the city foursquare;\"
All the streets with gold are laid,
And there is \"no night there!\"
And the gates shall never close
To \"the city four square;\"
There life\'s crystal river flows,
And there is \"no night there!\"
There they need no sunshine bright,
In \"that city foursquare,\"
For the Lamb is all the light;
And there is \"no night there?\"');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0427', 'verse', 1, 0, '[\"In the land of fadeless day\",\"Lies \\\"the city foursquare;\\\"\",\"It shall never pass away,\",\"And there is \\\"no night there?\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0427', 'chorus', 0, 1, '[\"God shall \\\"wipe away all tears;\\\"\",\"There\'s no death, no pain, nor fears;\",\"And they count not time by years,\",\"For there is \\\"no night there.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0427', 'verse', 2, 2, '[\"All the gates of pearl are made,\",\"In \\\"the city foursquare;\\\"\",\"All the streets with gold are laid,\",\"And there is \\\"no night there!\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0427', 'verse', 3, 3, '[\"And the gates shall never close\",\"To \\\"the city four square;\\\"\",\"There life\'s crystal river flows,\",\"And there is \\\"no night there!\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0427', 'verse', 4, 4, '[\"There they need no sunshine bright,\",\"In \\\"that city foursquare,\\\"\",\"For the Lamb is all the light;\",\"And there is \\\"no night there?\\\"\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0428', 428, 'Sweet By and By', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'There\'s a land that is fairer than day,
And by faith we can see it afar;
For the Father waits over the way,
To prepare us a dwelling place there.
In the sweet by and by,
We shall meet on that beautiful shore;
In the sweet by and by,
We shall meet on that beautiful shore.
We shall sing on that beautiful shore
The melodious songs of the blest,
And our spirits shall sorrow no more,
Not a sigh for the blessing of rest.
To our bountiful Father above,
We will offer a tribute of praise,
For the glorious gift of His love,
And the blessings that hallow our days.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0428', 'verse', 1, 0, '[\"There\'s a land that is fairer than day,\",\"And by faith we can see it afar;\",\"For the Father waits over the way,\",\"To prepare us a dwelling place there.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0428', 'chorus', 0, 1, '[\"In the sweet by and by,\",\"We shall meet on that beautiful shore;\",\"In the sweet by and by,\",\"We shall meet on that beautiful shore.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0428', 'verse', 2, 2, '[\"We shall sing on that beautiful shore\",\"The melodious songs of the blest,\",\"And our spirits shall sorrow no more,\",\"Not a sigh for the blessing of rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0428', 'verse', 3, 3, '[\"To our bountiful Father above,\",\"We will offer a tribute of praise,\",\"For the glorious gift of His love,\",\"And the blessings that hallow our days.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0429', 429, 'Jerusalem the Golden', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Jerusalem the golden,
With milk and honey blest,
Beneath thy contemplation
Sink heart and voice oppressed.
I know not, O I know not
What holy joys are there;
What radiancy of glory,
What bliss beyond compare.
They stand, those halls of Zion,
All jubilant with song,
And bright with many an angel,
And all the martyr throng.
The Prince is ever in them,
The daylight is serene;
The pastures of the blessed
Are decked in glorious sheen.
There is the throne of David,
And there, from care released,
The shout of them that triumph,
The song of them that feast;
And they who, with their Leader,
Have conquered in the fight,
Forever and forever
Are clad in robes of white.
O sweet and blessed country,
The home of God\'s elect!
O sweet and blessed country,
That eager hearts expect!
Jesus, in mercy bring us
To that dear land of rest;
Who art, with God the Father,
And Spirit, ever blest.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0429', 'verse', 1, 0, '[\"Jerusalem the golden,\",\"With milk and honey blest,\",\"Beneath thy contemplation\",\"Sink heart and voice oppressed.\",\"I know not, O I know not\",\"What holy joys are there;\",\"What radiancy of glory,\",\"What bliss beyond compare.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0429', 'verse', 2, 1, '[\"They stand, those halls of Zion,\",\"All jubilant with song,\",\"And bright with many an angel,\",\"And all the martyr throng.\",\"The Prince is ever in them,\",\"The daylight is serene;\",\"The pastures of the blessed\",\"Are decked in glorious sheen.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0429', 'verse', 3, 2, '[\"There is the throne of David,\",\"And there, from care released,\",\"The shout of them that triumph,\",\"The song of them that feast;\",\"And they who, with their Leader,\",\"Have conquered in the fight,\",\"Forever and forever\",\"Are clad in robes of white.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0429', 'verse', 4, 3, '[\"O sweet and blessed country,\",\"The home of God\'s elect!\",\"O sweet and blessed country,\",\"That eager hearts expect!\",\"Jesus, in mercy bring us\",\"To that dear land of rest;\",\"Who art, with God the Father,\",\"And Spirit, ever blest.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0430', 430, 'Joy By and By', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O there\'ll be joy when the work is done,
Joy when the reapers gather home,
Bringing the sheaves at set of sun
To the New Jerusalem.
Joy, joy, there\'ll be joy by and by,
Joy, joy, where the joys never die;
Joy, joy; for the day draweth nigh
When the workers gather home.
Sweet are the songs that we hope to sing,
Grateful the thanks our hearts shall bring,
Praising forever Christ our King
In the New Jerusalem.
Pure are the joys that await us there,
Many the golden mansions fair;
Jesus Himself doth them prepare,
In the New Jerusalem.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0430', 'verse', 1, 0, '[\"O there\'ll be joy when the work is done,\",\"Joy when the reapers gather home,\",\"Bringing the sheaves at set of sun\",\"To the New Jerusalem.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0430', 'chorus', 0, 1, '[\"Joy, joy, there\'ll be joy by and by,\",\"Joy, joy, where the joys never die;\",\"Joy, joy; for the day draweth nigh\",\"When the workers gather home.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0430', 'verse', 2, 2, '[\"Sweet are the songs that we hope to sing,\",\"Grateful the thanks our hearts shall bring,\",\"Praising forever Christ our King\",\"In the New Jerusalem.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0430', 'verse', 3, 3, '[\"Pure are the joys that await us there,\",\"Many the golden mansions fair;\",\"Jesus Himself doth them prepare,\",\"In the New Jerusalem.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0431', 431, 'Over Yonder', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Come, let us sing of homeland,
Down by the crystal sea;
Wonderful land where Jesus
Buildeth a mansion for me.
Over yonder, down by the crystal sea,
Over yonder,
There\'s where I long to be,
No more sorrow, toil, grief, nor care,
In the homeland bright and fair,
Over, over there.
Water of life there floweth,
Fruit in abundant store;
Citizens of that country
Hunger and thirst nevermore.
Come go with me to homeland,
Jesus invites you there;
Help spread the invitation,
Tell it to men everywhere.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0431', 'verse', 1, 0, '[\"Come, let us sing of homeland,\",\"Down by the crystal sea;\",\"Wonderful land where Jesus\",\"Buildeth a mansion for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0431', 'chorus', 0, 1, '[\"Over yonder, down by the crystal sea,\",\"Over yonder,\",\"There\'s where I long to be,\",\"No more sorrow, toil, grief, nor care,\",\"In the homeland bright and fair,\",\"Over, over there.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0431', 'verse', 2, 2, '[\"Water of life there floweth,\",\"Fruit in abundant store;\",\"Citizens of that country\",\"Hunger and thirst nevermore.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0431', 'verse', 3, 3, '[\"Come go with me to homeland,\",\"Jesus invites you there;\",\"Help spread the invitation,\",\"Tell it to men everywhere.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0432', 432, 'Shall We Gather at the River', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Shall we gather at the river
Where bright angel feet have trod,
With its crystal tide forever
Flowing by the throne of God?
Yes, we\'ll gather at the river,
The beautiful, the beautiful river;
Gather with the saints at the river
That flows by the throne of God.
On the margin of the river,
Washing up its silver spray
We will walk and worship ever,
All the happy golden day.
Ere we reach the shining river,
Lay we every burden down;
Grace our spirits will deliver,
And provide a robe and crown.
Soon we\'ll reach the shining river,
Soon our pilgrimage will cease,
Soon our happy hearts will quiver
With the melody of peace.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0432', 'verse', 1, 0, '[\"Shall we gather at the river\",\"Where bright angel feet have trod,\",\"With its crystal tide forever\",\"Flowing by the throne of God?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0432', 'chorus', 0, 1, '[\"Yes, we\'ll gather at the river,\",\"The beautiful, the beautiful river;\",\"Gather with the saints at the river\",\"That flows by the throne of God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0432', 'verse', 2, 2, '[\"On the margin of the river,\",\"Washing up its silver spray\",\"We will walk and worship ever,\",\"All the happy golden day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0432', 'verse', 3, 3, '[\"Ere we reach the shining river,\",\"Lay we every burden down;\",\"Grace our spirits will deliver,\",\"And provide a robe and crown.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0432', 'verse', 4, 4, '[\"Soon we\'ll reach the shining river,\",\"Soon our pilgrimage will cease,\",\"Soon our happy hearts will quiver\",\"With the melody of peace.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0433', 433, 'Ten Thousand Times Ten Thousand', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Ten thousand times ten thousand,
In sparkling raiment bright,
The armies of the ransomed saints
Throng up the steeps of light.
\'Tis finished, all is finished,
Their fight with death and sin.
Fling open wide the golden gates,
And let the victors in.
What rush of hallelujahs
Fills all the earth and sky!
The ringing of a thousand harps
Proclaims the triumph high.
O day for which creation
And all its tribes were made!
O joy, for all its former woes
A thousand-fold repaid!
O then what raptured greetings
On Canaan\'s happy shore!
What knitting severed friendship where
Death partings are no more!
Then eyes with joy shall sparkle,
That brimmed with tears of late;
Orphans no longer fatherless,
Nor widows desolate.
Bring near Thy great salvation,
Thou Lamb for sinners slain,
Fill up the roll of Thine elect,
Then take Thy power and reign!
Appear, Desire of nations,
Thine exiles long for home;
Show in the heavens Thy promised sign;
Thou Prince and Savior, come!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0433', 'verse', 1, 0, '[\"Ten thousand times ten thousand,\",\"In sparkling raiment bright,\",\"The armies of the ransomed saints\",\"Throng up the steeps of light.\",\"\'Tis finished, all is finished,\",\"Their fight with death and sin.\",\"Fling open wide the golden gates,\",\"And let the victors in.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0433', 'verse', 2, 1, '[\"What rush of hallelujahs\",\"Fills all the earth and sky!\",\"The ringing of a thousand harps\",\"Proclaims the triumph high.\",\"O day for which creation\",\"And all its tribes were made!\",\"O joy, for all its former woes\",\"A thousand-fold repaid!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0433', 'verse', 3, 2, '[\"O then what raptured greetings\",\"On Canaan\'s happy shore!\",\"What knitting severed friendship where\",\"Death partings are no more!\",\"Then eyes with joy shall sparkle,\",\"That brimmed with tears of late;\",\"Orphans no longer fatherless,\",\"Nor widows desolate.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0433', 'verse', 4, 3, '[\"Bring near Thy great salvation,\",\"Thou Lamb for sinners slain,\",\"Fill up the roll of Thine elect,\",\"Then take Thy power and reign!\",\"Appear, Desire of nations,\",\"Thine exiles long for home;\",\"Show in the heavens Thy promised sign;\",\"Thou Prince and Savior, come!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0434', 434, 'We Speak of the Realms', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'We speak of the realms of the blest,
That country so bright and so fair,
And oft are its glories confessed;
But what must it be to be there!
We speak of its pathway of gold;
Its walls decked with jewels so rare,
Its wonders and pleasures untold;
But what must it be to be there!
We speak of its freedom from sin,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0434', 'verse', 1, 0, '[\"We speak of the realms of the blest,\",\"That country so bright and so fair,\",\"And oft are its glories confessed;\",\"But what must it be to be there!\",\"We speak of its pathway of gold;\",\"Its walls decked with jewels so rare,\",\"Its wonders and pleasures untold;\",\"But what must it be to be there!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0434', 'verse', 2, 1, '[\"We speak of its freedom from sin,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0435', 435, 'The Glory Song', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'When all my labors and trials are o\'er,
And I am safe on that beautiful shore,
Just to be near the dear Lord I adore,
Will through the ages be glory for me.
O that will be glory for me,
Glory for me, glory for me;
When by His grace I shall look on His face,
That will be glory, be glory for me.
When, by the gift of His infinite grace,
I am accorded in heaven a place,
Just to be there and to look on His face,
Will through the ages be glory for me.
Friends will be there I have loved long ago;
Joy like a river around me will flow,
Yet, just a smile from my Savior, I know,
Will through the ages be glory for me.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0435', 'verse', 1, 0, '[\"When all my labors and trials are o\'er,\",\"And I am safe on that beautiful shore,\",\"Just to be near the dear Lord I adore,\",\"Will through the ages be glory for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0435', 'chorus', 0, 1, '[\"O that will be glory for me,\",\"Glory for me, glory for me;\",\"When by His grace I shall look on His face,\",\"That will be glory, be glory for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0435', 'verse', 2, 2, '[\"When, by the gift of His infinite grace,\",\"I am accorded in heaven a place,\",\"Just to be there and to look on His face,\",\"Will through the ages be glory for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0435', 'verse', 3, 3, '[\"Friends will be there I have loved long ago;\",\"Joy like a river around me will flow,\",\"Yet, just a smile from my Savior, I know,\",\"Will through the ages be glory for me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0436', 436, 'The Homeland', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'The homeland! O the homeland!
The land of the freeborn!
There\'s no night in the homeland,
But aye the fadeless morn;
I\'m sighing for the homeland,
My heart is aching here;
There is no pain in the homeland
To which I\'m drawing near;
There is no pain in the homeland
To which I\'m drawing near.
My Lord is in the homeland,
With angels bright and fair;
There\'s no sin in the homeland,
And no temptation there;
The music of the homeland
Is ringing in my ears;
And when I think of the homeland
My eyes are filled with tears;
And when I think of the homeland
My eyes are filled with tears.
The dwellers in the homeland
Are beckoning me to come,
Where neither death nor sorrow
Invades their holy home;
O dear, dear native country!
O rest and peace above!
Christ bring us all to the homeland
Of Thy redeeming love;
Christ bring us all to the homeland
Of Thy redeeming love.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0436', 'verse', 1, 0, '[\"The homeland! O the homeland!\",\"The land of the freeborn!\",\"There\'s no night in the homeland,\",\"But aye the fadeless morn;\",\"I\'m sighing for the homeland,\",\"My heart is aching here;\",\"There is no pain in the homeland\",\"To which I\'m drawing near;\",\"There is no pain in the homeland\",\"To which I\'m drawing near.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0436', 'verse', 2, 1, '[\"My Lord is in the homeland,\",\"With angels bright and fair;\",\"There\'s no sin in the homeland,\",\"And no temptation there;\",\"The music of the homeland\",\"Is ringing in my ears;\",\"And when I think of the homeland\",\"My eyes are filled with tears;\",\"And when I think of the homeland\",\"My eyes are filled with tears.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0436', 'verse', 3, 2, '[\"The dwellers in the homeland\",\"Are beckoning me to come,\",\"Where neither death nor sorrow\",\"Invades their holy home;\",\"O dear, dear native country!\",\"O rest and peace above!\",\"Christ bring us all to the homeland\",\"Of Thy redeeming love;\",\"Christ bring us all to the homeland\",\"Of Thy redeeming love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0437', 437, 'I\'m Going Home', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'My heav\'nly home is bright and fair,
Nor pain nor death can enter there;
Its glitt\'ring tow\'rs the sun outshine,
That heav\'nly mansion shall be mine.
I\'m going home, I\'m going home,
I\'m going home to die no more;
To die no more; to die no more;
I\'m going home to die no more.
My Father\'s house is built on high,
Far, far above the starry sky;
When from this earthly prison free,
That heav\'nly mansion mine shall be.
Let others seek a home below,
Which flames devour or waves o\'erflow;
Be mine a happier lot to own
A heav\'nly mansion near the throne.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0437', 'verse', 1, 0, '[\"My heav\'nly home is bright and fair,\",\"Nor pain nor death can enter there;\",\"Its glitt\'ring tow\'rs the sun outshine,\",\"That heav\'nly mansion shall be mine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0437', 'chorus', 0, 1, '[\"I\'m going home, I\'m going home,\",\"I\'m going home to die no more;\",\"To die no more; to die no more;\",\"I\'m going home to die no more.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0437', 'verse', 2, 2, '[\"My Father\'s house is built on high,\",\"Far, far above the starry sky;\",\"When from this earthly prison free,\",\"That heav\'nly mansion mine shall be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0437', 'verse', 3, 3, '[\"Let others seek a home below,\",\"Which flames devour or waves o\'erflow;\",\"Be mine a happier lot to own\",\"A heav\'nly mansion near the throne.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0438', 438, 'You Will See Your Lord A-coming', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'You will see your Lord a-coming,
You will see your Lord a-coming,
You will see your Lord a-coming
In a few more days.
Hear the band of music,
Hear the band of music,
Hear the band of music which is sounding thro\' the air.
Gabriel sounds his mighty trumpet,
Gabriel sounds his mighty trumpet,
Gabriel sounds his mighty trumpet
In a few more days.
You will see the saints a-rising,
You will see the saints a-rising,
You will see the saints a-rising
In a few more days.
Angels bear them to the Savior,
Angels bear them to the Savior,
Angels bear them to the Savior
In a few more days.
Then we\'ll shout, our suff\'ring over,
Then we\'ll shout, our suff\'ring over,
Then we\'ll shout, our suff\'ring over
In a few more days.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0438', 'verse', 1, 0, '[\"You will see your Lord a-coming,\",\"You will see your Lord a-coming,\",\"You will see your Lord a-coming\",\"In a few more days.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0438', 'chorus', 0, 1, '[\"Hear the band of music,\",\"Hear the band of music,\",\"Hear the band of music which is sounding thro\' the air.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0438', 'verse', 2, 2, '[\"Gabriel sounds his mighty trumpet,\",\"Gabriel sounds his mighty trumpet,\",\"Gabriel sounds his mighty trumpet\",\"In a few more days.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0438', 'verse', 3, 3, '[\"You will see the saints a-rising,\",\"You will see the saints a-rising,\",\"You will see the saints a-rising\",\"In a few more days.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0438', 'verse', 4, 4, '[\"Angels bear them to the Savior,\",\"Angels bear them to the Savior,\",\"Angels bear them to the Savior\",\"In a few more days.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0438', 'verse', 5, 5, '[\"Then we\'ll shout, our suff\'ring over,\",\"Then we\'ll shout, our suff\'ring over,\",\"Then we\'ll shout, our suff\'ring over\",\"In a few more days.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0439', 439, 'How Far From Home?', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'How far from home? I asked, as on
I bent my steps; the watchman spake:
\"The long, dark night is almost gone,
The morning soon will break.
Then weep no more, but speed thy flight,
With Hope\'s bright star thy guiding ray,
Till thou shalt reach the realms of light,
In everlasting day.\"
I asked the warrior on the field;
This was his soul-inspiring song:
\"With courage, bold, the sword I\'ll wield,
The battle is not long.
Then weep no more, but well endure
The conflict, till thy work is done;
For this we know, the prize is sure,
When victory is won.\"
I asked again; earth, sea, and sun
Seemed, with one voice, to make reply:
\"Time\'s wasting sands are nearly run,
Eternity is nigh.
Then weep no more; with warning tones,
Portentous signs are thickening round,
The whole creation, waiting, groans,
To hear the trumpet sound.\"
Not far from home! O blessed thought!
The traveler\'s lonely heart to cheer;
Which oft a healing balm has brought,
And dried the mourner\'s tear.
Then weep no more, since we shall meet
Where weary footsteps never roam;
Our trials past, our joys complete,
Safe in our Father\'s home.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0439', 'verse', 1, 0, '[\"How far from home? I asked, as on\",\"I bent my steps; the watchman spake:\",\"\\\"The long, dark night is almost gone,\",\"The morning soon will break.\",\"Then weep no more, but speed thy flight,\",\"With Hope\'s bright star thy guiding ray,\",\"Till thou shalt reach the realms of light,\",\"In everlasting day.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0439', 'verse', 2, 1, '[\"I asked the warrior on the field;\",\"This was his soul-inspiring song:\",\"\\\"With courage, bold, the sword I\'ll wield,\",\"The battle is not long.\",\"Then weep no more, but well endure\",\"The conflict, till thy work is done;\",\"For this we know, the prize is sure,\",\"When victory is won.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0439', 'verse', 3, 2, '[\"I asked again; earth, sea, and sun\",\"Seemed, with one voice, to make reply:\",\"\\\"Time\'s wasting sands are nearly run,\",\"Eternity is nigh.\",\"Then weep no more; with warning tones,\",\"Portentous signs are thickening round,\",\"The whole creation, waiting, groans,\",\"To hear the trumpet sound.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0439', 'verse', 4, 3, '[\"Not far from home! O blessed thought!\",\"The traveler\'s lonely heart to cheer;\",\"Which oft a healing balm has brought,\",\"And dried the mourner\'s tear.\",\"Then weep no more, since we shall meet\",\"Where weary footsteps never roam;\",\"Our trials past, our joys complete,\",\"Safe in our Father\'s home.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0440', 440, 'How Cheering Is the Christian\'s Hope', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'How cheering is the Christian\'s hope,
While toiling here below!
It bouys us up while this passing through
This wilderness of woe,
It bouys us up while passing through
This wilderness of woe.
It points us to a land of rest
Where saints with Christ will reign;
Where we shall meet the loved of earth,
And never part again.
Fly, lingering moments, fly, O, fly,
Dear Savior, quickly come!
We long to see Thee as Thou art,
And reach that blissful home.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0440', 'verse', 1, 0, '[\"How cheering is the Christian\'s hope,\",\"While toiling here below!\",\"It bouys us up while this passing through\",\"This wilderness of woe,\",\"It bouys us up while passing through\",\"This wilderness of woe.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0440', 'verse', 2, 1, '[\"It points us to a land of rest\",\"Where saints with Christ will reign;\",\"Where we shall meet the loved of earth,\",\"And never part again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0440', 'verse', 3, 2, '[\"Fly, lingering moments, fly, O, fly,\",\"Dear Savior, quickly come!\",\"We long to see Thee as Thou art,\",\"And reach that blissful home.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0441', 441, 'I Saw One Weary', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I saw one weary, sad, and torn,
With eager steps press on the way,
Who long the hallowed cross had borne,
Still looking for the promised day;
While many a line of grief and care,
Upon his brow was furrowed there;
I asked what buoyed his spirits up,
\"O this!\" said he \"the blessed hope.\"
And one I saw, with sword and shield,
Who boldly braved the world\'s cold frown,
And fought, unyielding, on the field,
To win an everlasting crown.
Though worn with toil, oppressed by foes,
No murmur from his heart arose;
I asked what buoyed his spirits up,
\"O this!\" said he \"the blessed hope.\"
And there was one who left behind
The cherished friends of early years,
And honor, pleasure, wealth resigned,
To tread the path bedewed with tears.
Through trials deep and conflicts sore,
Yet still a smile of joy he wore;
I asked what buoyed his spirits up,
\"O this!\" said he \"the blessed hope.\"
While pilgrims here we journey on
In this dark vale of sin and gloom,
Through tribulation, hate, and scorn,
Or through the portals of the tomb,
Till our returning King shall come
To take His exile captives home,
O! what can buoy the spirits up?
\'Tis this alone the blessed hope.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0441', 'verse', 1, 0, '[\"I saw one weary, sad, and torn,\",\"With eager steps press on the way,\",\"Who long the hallowed cross had borne,\",\"Still looking for the promised day;\",\"While many a line of grief and care,\",\"Upon his brow was furrowed there;\",\"I asked what buoyed his spirits up,\",\"\\\"O this!\\\" said he \\\"the blessed hope.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0441', 'verse', 2, 1, '[\"And one I saw, with sword and shield,\",\"Who boldly braved the world\'s cold frown,\",\"And fought, unyielding, on the field,\",\"To win an everlasting crown.\",\"Though worn with toil, oppressed by foes,\",\"No murmur from his heart arose;\",\"I asked what buoyed his spirits up,\",\"\\\"O this!\\\" said he \\\"the blessed hope.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0441', 'verse', 3, 2, '[\"And there was one who left behind\",\"The cherished friends of early years,\",\"And honor, pleasure, wealth resigned,\",\"To tread the path bedewed with tears.\",\"Through trials deep and conflicts sore,\",\"Yet still a smile of joy he wore;\",\"I asked what buoyed his spirits up,\",\"\\\"O this!\\\" said he \\\"the blessed hope.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0441', 'verse', 4, 3, '[\"While pilgrims here we journey on\",\"In this dark vale of sin and gloom,\",\"Through tribulation, hate, and scorn,\",\"Or through the portals of the tomb,\",\"Till our returning King shall come\",\"To take His exile captives home,\",\"O! what can buoy the spirits up?\",\"\'Tis this alone the blessed hope.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0442', 442, 'How Sweet Are the Tidings', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'How sweet are the tidings that greet the pilgrim\'s ear,
As he wanders in exile from home!
Soon, soon will the Savior in glory appear,
And soon will the kingdom come.
He\'s coming, coming, coming soon I know,
Coming back to this earth again;
And the weary pilgrims will to glory go,
When the Savior comes to reign.
The mossy old graves where the pilgrims sleep
Shall be open as wide as before,
And the millions that sleep in the mighty deep
Shall live on this earth once more.
There we\'ll meet ne\'er to part in our happy Eden home,
Sweet songs of redemption we\'ll sing;');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0442', 'verse', 1, 0, '[\"How sweet are the tidings that greet the pilgrim\'s ear,\",\"As he wanders in exile from home!\",\"Soon, soon will the Savior in glory appear,\",\"And soon will the kingdom come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0442', 'chorus', 0, 1, '[\"He\'s coming, coming, coming soon I know,\",\"Coming back to this earth again;\",\"And the weary pilgrims will to glory go,\",\"When the Savior comes to reign.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0442', 'verse', 2, 2, '[\"The mossy old graves where the pilgrims sleep\",\"Shall be open as wide as before,\",\"And the millions that sleep in the mighty deep\",\"Shall live on this earth once more.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0442', 'verse', 3, 3, '[\"There we\'ll meet ne\'er to part in our happy Eden home,\",\"Sweet songs of redemption we\'ll sing;\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0443', 443, 'There\'ll Be No Sorrow There', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'There\'ll be no night in heaven,
In that blest world above;
No anxious toil, no weary hours;
For labor there is love.
There\'ll be no grief in heaven;
For life is one glad day,
And tears are those of former things
Which all have passed away.
There\'ll be no sin in heaven;
Behold that blessed throng,
All holy in their spotless robes,
All holy in their song.
There\'ll be no sorrow there,
There\'ll be no sorrow there;
In heaven above, where all is love,
There\'ll be no sorrow there.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0443', 'verse', 1, 0, '[\"There\'ll be no night in heaven,\",\"In that blest world above;\",\"No anxious toil, no weary hours;\",\"For labor there is love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0443', 'verse', 2, 1, '[\"There\'ll be no grief in heaven;\",\"For life is one glad day,\",\"And tears are those of former things\",\"Which all have passed away.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0443', 'verse', 3, 2, '[\"There\'ll be no sin in heaven;\",\"Behold that blessed throng,\",\"All holy in their spotless robes,\",\"All holy in their song.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0443', 'verse', 4, 3, '[\"There\'ll be no sorrow there,\",\"There\'ll be no sorrow there;\",\"In heaven above, where all is love,\",\"There\'ll be no sorrow there.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0444', 444, 'I\'m a Pilgrim', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I\'m a pilgrim, and I\'m a stranger;
I can tarry, I can tarry but a night;
Do not detain me, for I am going
To where the fountains are ever flowing.
I\'m a pilgrim, and I\'m a stranger;
I can tarry, I can tarry but a night.
There the glory is ever shining!
O, my longing heart, my longing heart is there;
Here in this country so dark and dreary,
I long have wandered forlorn and weary.
There\'s the city to which I journey;
My Redeemer, my Redeemer is its light!
There is no sorrow, nor any sighing,
Nor any tears there, or any dying.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0444', 'verse', 1, 0, '[\"I\'m a pilgrim, and I\'m a stranger;\",\"I can tarry, I can tarry but a night;\",\"Do not detain me, for I am going\",\"To where the fountains are ever flowing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0444', 'chorus', 0, 1, '[\"I\'m a pilgrim, and I\'m a stranger;\",\"I can tarry, I can tarry but a night.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0444', 'verse', 2, 2, '[\"There the glory is ever shining!\",\"O, my longing heart, my longing heart is there;\",\"Here in this country so dark and dreary,\",\"I long have wandered forlorn and weary.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0444', 'verse', 3, 3, '[\"There\'s the city to which I journey;\",\"My Redeemer, my Redeemer is its light!\",\"There is no sorrow, nor any sighing,\",\"Nor any tears there, or any dying.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0445', 445, 'I\'m But a Stranger Here', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I\'m but a stranger here,
Heaven is my home;
Earth is a desert drear,
Heaven is my home;
Danger and sorrow stand
Round me on every hand;
Heaven is my Fatherland,
Heaven is my home.
What though the tempest rage,
Heaven is my home;
Short is my pilgrimage,
Heaven is my home.
Time\'s cold and wintry blast
Soon will be over-past;
I shall reach home at last;
Heaven is my home.
There at my Savior\'s side,
Heaven is my home;
I shall be glorified,
Heaven is my home.
There\'ll be the good and blest,
Those I love most and best,
There, too, I soon shall rest;
Heaven is my home.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0445', 'verse', 1, 0, '[\"I\'m but a stranger here,\",\"Heaven is my home;\",\"Earth is a desert drear,\",\"Heaven is my home;\",\"Danger and sorrow stand\",\"Round me on every hand;\",\"Heaven is my Fatherland,\",\"Heaven is my home.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0445', 'verse', 2, 1, '[\"What though the tempest rage,\",\"Heaven is my home;\",\"Short is my pilgrimage,\",\"Heaven is my home.\",\"Time\'s cold and wintry blast\",\"Soon will be over-past;\",\"I shall reach home at last;\",\"Heaven is my home.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0445', 'verse', 3, 2, '[\"There at my Savior\'s side,\",\"Heaven is my home;\",\"I shall be glorified,\",\"Heaven is my home.\",\"There\'ll be the good and blest,\",\"Those I love most and best,\",\"There, too, I soon shall rest;\",\"Heaven is my home.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0446', 446, 'Lo, What a Glorious Sight Appears', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Lo, what a glorious sight appears
To our believing eyes!
The earth and seas are passed away,
And the old rolling skies.
And the old rolling skies,
And the old rolling skies;
The earth and seas are passed a way,
And the old rolling skies.
O that will be joyful, joyful, joyful!
O that will be joyful
When we meet to part no more!
When we meet to part no more on Canaan\'s happy shore;
Tis there we\'ll meet at Jesus\' feet,
When we meet to part no more!
Attending angels shout for joy
And the bright armies sing;
Mortals! behold the sacred seat
Of your descending King.
Of your descending King,
Of your descending King;
Mortals! behold the sacred seat
Of your descending King.
His own soft hand shall wipe the tears');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0446', 'verse', 1, 0, '[\"Lo, what a glorious sight appears\",\"To our believing eyes!\",\"The earth and seas are passed away,\",\"And the old rolling skies.\",\"And the old rolling skies,\",\"And the old rolling skies;\",\"The earth and seas are passed a way,\",\"And the old rolling skies.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0446', 'chorus', 0, 1, '[\"O that will be joyful, joyful, joyful!\",\"O that will be joyful\",\"When we meet to part no more!\",\"When we meet to part no more on Canaan\'s happy shore;\",\"Tis there we\'ll meet at Jesus\' feet,\",\"When we meet to part no more!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0446', 'verse', 2, 2, '[\"Attending angels shout for joy\",\"And the bright armies sing;\",\"Mortals! behold the sacred seat\",\"Of your descending King.\",\"Of your descending King,\",\"Of your descending King;\",\"Mortals! behold the sacred seat\",\"Of your descending King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0446', 'verse', 3, 3, '[\"His own soft hand shall wipe the tears\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0447', 447, 'Long Upon the Mountains', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Long upon the mountains weary,
Have the scattered flock been torn;
Dark the desert paths, and dreary;
Grievous trials have they borne.
Now the gathering call is sounding,
Solemn in its warning voice;
Union, faith, and love, abounding,
Bid the little flock rejoice.
Now the light of truth they\'re seeking,
In its onward track pursue;
All the ten commandments keeping,
They are holy, just, and true.
On the words of life they\'re feeding,
Precious to their taste so sweet;
All their Master\'s precepts heeding,
Bowing humbly at His feet.
In that light of light and beauty,
In that golden city fair,
Soon its pearly gates they\'ll enter,
And of all its glories share.
There, divine the soul\'s expansions;
Free from sin, and death, and pain;
Tears will never dim those mansions
Where the saints immortal reign.
Soon He comes! with clouds descending;
All His saints, entombed arise;
The redeemed, in anthems blending,
Shout their vict\'ry thro\' the skies.
O, we long for Thine appearing;
Come, O Savior, quickly come!
Blessed hope! our spirits cheering,
Take Thy ransomed children home.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0447', 'verse', 1, 0, '[\"Long upon the mountains weary,\",\"Have the scattered flock been torn;\",\"Dark the desert paths, and dreary;\",\"Grievous trials have they borne.\",\"Now the gathering call is sounding,\",\"Solemn in its warning voice;\",\"Union, faith, and love, abounding,\",\"Bid the little flock rejoice.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0447', 'verse', 2, 1, '[\"Now the light of truth they\'re seeking,\",\"In its onward track pursue;\",\"All the ten commandments keeping,\",\"They are holy, just, and true.\",\"On the words of life they\'re feeding,\",\"Precious to their taste so sweet;\",\"All their Master\'s precepts heeding,\",\"Bowing humbly at His feet.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0447', 'verse', 3, 2, '[\"In that light of light and beauty,\",\"In that golden city fair,\",\"Soon its pearly gates they\'ll enter,\",\"And of all its glories share.\",\"There, divine the soul\'s expansions;\",\"Free from sin, and death, and pain;\",\"Tears will never dim those mansions\",\"Where the saints immortal reign.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0447', 'verse', 4, 3, '[\"Soon He comes! with clouds descending;\",\"All His saints, entombed arise;\",\"The redeemed, in anthems blending,\",\"Shout their vict\'ry thro\' the skies.\",\"O, we long for Thine appearing;\",\"Come, O Savior, quickly come!\",\"Blessed hope! our spirits cheering,\",\"Take Thy ransomed children home.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0448', 448, 'O When Shall I See Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'O, when shall I see Jesus and reign with Him above,
And shall hear the trumpet sound in that morning?
And from the flowing fountain drink everlasting love,
And shall hear the trumpet sound in that morning.
O, shout, glory!
For I shall mount above the skies,
When I hear the trumpet sound in that morning.
Gird on the gospel armor of faith and hope and love,
And you\'ll hear the trumpet sound in that morning.
And when the combat\'s ended He\'ll carry you above,
And you\'ll hear the trumpet sound in that morning.
Our ears shall hear with transport the host of heaven sing,
And shall hear the trumpet sound in that morning.
Our tongues shall chant the glories of our immortal King.
And shall hear the trumpet sound in that morning,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0448', 'verse', 1, 0, '[\"O, when shall I see Jesus and reign with Him above,\",\"And shall hear the trumpet sound in that morning?\",\"And from the flowing fountain drink everlasting love,\",\"And shall hear the trumpet sound in that morning.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0448', 'chorus', 0, 1, '[\"O, shout, glory!\",\"For I shall mount above the skies,\",\"When I hear the trumpet sound in that morning.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0448', 'verse', 2, 2, '[\"Gird on the gospel armor of faith and hope and love,\",\"And you\'ll hear the trumpet sound in that morning.\",\"And when the combat\'s ended He\'ll carry you above,\",\"And you\'ll hear the trumpet sound in that morning.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0448', 'verse', 3, 3, '[\"Our ears shall hear with transport the host of heaven sing,\",\"And shall hear the trumpet sound in that morning.\",\"Our tongues shall chant the glories of our immortal King.\",\"And shall hear the trumpet sound in that morning,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0449', 449, 'Never Part Again', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'There is a land of pure delight,
Where bliss eternal reigns,
Infinite day excludes the night
And pleasures banish pain.
We\'re trav\'ling to Immanuel\'s land,
We soon shall hear the trumpet sound,
And soon we shall with Jesus reign,
And never, never part again.
What! Never part again?
No, never part again,
What! Never part again?
No, never part again,
And soon we shall with Jesus reign,
And never, never part again.
There everlasting spring abides,
And never with\'ring flowers,
And but a little space divides
This heav\'nly land from ours.
Could we but stand where Moses stood,
And view the landscape o\'er,
Not all this world\'s pretended good
Could ever charm us more.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0449', 'verse', 1, 0, '[\"There is a land of pure delight,\",\"Where bliss eternal reigns,\",\"Infinite day excludes the night\",\"And pleasures banish pain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0449', 'chorus', 0, 1, '[\"We\'re trav\'ling to Immanuel\'s land,\",\"We soon shall hear the trumpet sound,\",\"And soon we shall with Jesus reign,\",\"And never, never part again.\",\"What! Never part again?\",\"No, never part again,\",\"What! Never part again?\",\"No, never part again,\",\"And soon we shall with Jesus reign,\",\"And never, never part again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0449', 'verse', 2, 2, '[\"There everlasting spring abides,\",\"And never with\'ring flowers,\",\"And but a little space divides\",\"This heav\'nly land from ours.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0449', 'verse', 3, 3, '[\"Could we but stand where Moses stood,\",\"And view the landscape o\'er,\",\"Not all this world\'s pretended good\",\"Could ever charm us more.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0450', 450, 'Beautiful Zion', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Beautiful Zion, built above,
Beautiful city that I love,
Beautiful gates of pearly white,
Beautiful temple, God its light.
Beautiful trees forever there,
Beautiful fruit they always bear,
Beautiful rivers gliding by,
Beautiful fountains never dry.
Beautiful crowns on every brow,
Beautiful palms the conquerors show,
Beautiful robes the ransomed wear,
Beautiful all who enter there.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0450', 'verse', 1, 0, '[\"Beautiful Zion, built above,\",\"Beautiful city that I love,\",\"Beautiful gates of pearly white,\",\"Beautiful temple, God its light.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0450', 'verse', 2, 1, '[\"Beautiful trees forever there,\",\"Beautiful fruit they always bear,\",\"Beautiful rivers gliding by,\",\"Beautiful fountains never dry.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0450', 'verse', 3, 2, '[\"Beautiful crowns on every brow,\",\"Beautiful palms the conquerors show,\",\"Beautiful robes the ransomed wear,\",\"Beautiful all who enter there.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0451', 451, 'Together Let Us Sweetly Live', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Together let us sweetly live,
I am bound for the land of Canaan.
Together love to Jesus give;
I am bound for the land of Canaan.
O Canaan, bright Canaan,
I am bound for the land of Canaan.
O Canaan, it is my happy home,
I am bound for the land of Canaan.
Together let us watch and pray;
I am bound for the land of Canaan.
And wait redemption\'s joyous day;
I am bound for the land of Canaan.
Our songs of praise shall fill the skies;
I am bound for the land of Canaan.
While higher still our joys shall rise;
I am bound for the land of Canaan.
Then come with me, beloved friend;
I am bound for the land of Canaan.
The joys to come shall never end;
I am bound for the land of Canaan.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0451', 'verse', 1, 0, '[\"Together let us sweetly live,\",\"I am bound for the land of Canaan.\",\"Together love to Jesus give;\",\"I am bound for the land of Canaan.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0451', 'chorus', 0, 1, '[\"O Canaan, bright Canaan,\",\"I am bound for the land of Canaan.\",\"O Canaan, it is my happy home,\",\"I am bound for the land of Canaan.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0451', 'verse', 2, 2, '[\"Together let us watch and pray;\",\"I am bound for the land of Canaan.\",\"And wait redemption\'s joyous day;\",\"I am bound for the land of Canaan.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0451', 'verse', 3, 3, '[\"Our songs of praise shall fill the skies;\",\"I am bound for the land of Canaan.\",\"While higher still our joys shall rise;\",\"I am bound for the land of Canaan.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0451', 'verse', 4, 4, '[\"Then come with me, beloved friend;\",\"I am bound for the land of Canaan.\",\"The joys to come shall never end;\",\"I am bound for the land of Canaan.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0452', 452, 'What Heavenly Music', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'What heavenly music steals over the sea!
Entrancing the senses like sweet melody!
\'Tis the voice of the angels borne soft on the air;
For me they are singing; their welcome I hear.
On the banks of old Jordan, here gazing I stand,
And earnestly longing, I stretch forth my hand;
Send a convoy of angels, dear Jesus, I pray!
Let me join that sweet music; come, take me away.
Though dark are the waters and rough is the wave,
If Jesus permit, the wild surges I\'ll brave;
For that heavenly music hath ravished me so,
I must join in that chorus! I\'ll go! let me go!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0452', 'verse', 1, 0, '[\"What heavenly music steals over the sea!\",\"Entrancing the senses like sweet melody!\",\"\'Tis the voice of the angels borne soft on the air;\",\"For me they are singing; their welcome I hear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0452', 'verse', 2, 1, '[\"On the banks of old Jordan, here gazing I stand,\",\"And earnestly longing, I stretch forth my hand;\",\"Send a convoy of angels, dear Jesus, I pray!\",\"Let me join that sweet music; come, take me away.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0452', 'verse', 3, 2, '[\"Though dark are the waters and rough is the wave,\",\"If Jesus permit, the wild surges I\'ll brave;\",\"For that heavenly music hath ravished me so,\",\"I must join in that chorus! I\'ll go! let me go!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0453', 453, 'We Have Heard', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'We have heard from the bright, the holy, land;
We have heard, and our hearts are glad;
For we were a lonely pilgrim band,
And weary, and worn, and sad.
They tell us the saints have a dwelling there;
No longer are homeless ones;
And we know that the goodly land is fair,
Where life\'s pure river runs.
They say green fields are waving there,
That never a blight shall know;
And the deserts wild are blooming fair,
And the roses of Sharon grow.
There are lovely birds in the bowers green,
Their songs are blithe and sweet;
And their warblings, gushing ever new,
The angels\' harpings greet.
We have heard of the palms, the robes, the crowns,
And the silvery band in white;
Of the city fair, with pearly gates,
All radiant with light.
We have heard of the angels there, and saints,
With their harps of gold, how they sing;
Of the mount with the fruitful tree of life,
Of the leaves that healing bring.
The King of that country, He is fair,
He\'s the joy and light of the place;
In His beauty we shall behold Him there,
And bask in His smiling face.
We\'ll be there, we\'ll be there in a little while,
We\'ll join the pure and the blest;
We\'ll have the palm, the robe, the crown,
And forever be at rest.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0453', 'verse', 1, 0, '[\"We have heard from the bright, the holy, land;\",\"We have heard, and our hearts are glad;\",\"For we were a lonely pilgrim band,\",\"And weary, and worn, and sad.\",\"They tell us the saints have a dwelling there;\",\"No longer are homeless ones;\",\"And we know that the goodly land is fair,\",\"Where life\'s pure river runs.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0453', 'verse', 2, 1, '[\"They say green fields are waving there,\",\"That never a blight shall know;\",\"And the deserts wild are blooming fair,\",\"And the roses of Sharon grow.\",\"There are lovely birds in the bowers green,\",\"Their songs are blithe and sweet;\",\"And their warblings, gushing ever new,\",\"The angels\' harpings greet.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0453', 'verse', 3, 2, '[\"We have heard of the palms, the robes, the crowns,\",\"And the silvery band in white;\",\"Of the city fair, with pearly gates,\",\"All radiant with light.\",\"We have heard of the angels there, and saints,\",\"With their harps of gold, how they sing;\",\"Of the mount with the fruitful tree of life,\",\"Of the leaves that healing bring.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0453', 'verse', 4, 3, '[\"The King of that country, He is fair,\",\"He\'s the joy and light of the place;\",\"In His beauty we shall behold Him there,\",\"And bask in His smiling face.\",\"We\'ll be there, we\'ll be there in a little while,\",\"We\'ll join the pure and the blest;\",\"We\'ll have the palm, the robe, the crown,\",\"And forever be at rest.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0454', 454, 'Don\'t You See My Jesus Coming', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Don\'t you see my Jesus coming,
See Him come in yonder cloud?
With ten thousand angels round Him,
How they do my Jesus crowd!
I am bound for the kingdom,
Will you go to glory with me?
Hallelujah! O praise ye the Lord!
Don\'t you see the saints ascending,
Hear them shouting thro\' the air.
Jesus smiling, trumpets sounding,
Now His glory they shall share.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0454', 'verse', 1, 0, '[\"Don\'t you see my Jesus coming,\",\"See Him come in yonder cloud?\",\"With ten thousand angels round Him,\",\"How they do my Jesus crowd!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0454', 'chorus', 0, 1, '[\"I am bound for the kingdom,\",\"Will you go to glory with me?\",\"Hallelujah! O praise ye the Lord!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0454', 'verse', 2, 2, '[\"Don\'t you see the saints ascending,\",\"Hear them shouting thro\' the air.\",\"Jesus smiling, trumpets sounding,\",\"Now His glory they shall share.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0455', 455, 'Immortal Love, Forever Full', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Immortal Love, forever full,
Forever flowing free,
Forever shared, forever whole,
A never ebbing sea!
We may not climb the heavenly steeps
To bring the Lord Christ down;
In vain we search the lowest deeps,
For Him no depths can drown.
But warm, sweet, tender, even yet
A present help is He;
And faith has still its Olivet,
And love its Galilee.
The healing of His seamless dress
Is by our beds of pain;
We touch Him in life\'s throng and press,
And we are whole again.
Through Him the first fond prayers are said,
Our lips of childhood frame;
The last low whispers of our dead
Are burdened with His name.
O Lord and Master of us all:
What e\'er our name or sign,
We own Thy sway, we hear Thy call,
We test our lives by Thine!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0455', 'verse', 1, 0, '[\"Immortal Love, forever full,\",\"Forever flowing free,\",\"Forever shared, forever whole,\",\"A never ebbing sea!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0455', 'verse', 2, 1, '[\"We may not climb the heavenly steeps\",\"To bring the Lord Christ down;\",\"In vain we search the lowest deeps,\",\"For Him no depths can drown.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0455', 'verse', 3, 2, '[\"But warm, sweet, tender, even yet\",\"A present help is He;\",\"And faith has still its Olivet,\",\"And love its Galilee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0455', 'verse', 4, 3, '[\"The healing of His seamless dress\",\"Is by our beds of pain;\",\"We touch Him in life\'s throng and press,\",\"And we are whole again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0455', 'verse', 5, 4, '[\"Through Him the first fond prayers are said,\",\"Our lips of childhood frame;\",\"The last low whispers of our dead\",\"Are burdened with His name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0455', 'verse', 6, 5, '[\"O Lord and Master of us all:\",\"What e\'er our name or sign,\",\"We own Thy sway, we hear Thy call,\",\"We test our lives by Thine!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0456', 456, 'My Lord and I', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I have a Friend so precious,
So very dear to me,
He loves me with such tender love,
He loves so faithfully;
I could not live apart from Him,
I love to feel Him nigh,
And so we dwell together,
My Lord and I.
Sometimes I\'m faint and weary,
He knows that I am weak,
And as He bids me lean on Him,
His help I gladly seek;
He leads me in the paths of light,
Beneath a sunny sky,
And so we walk together,
My Lord and I.
I tell Him all my sorrows,
I tell Him all my joys,
I tell Him all that pleases me,
I tell Him what annoys;
He tells me what I ought to do,
He tells me how to try,
And so we talk together,
My Lord and I.
He knows that I am longing
Some weary soul to win,
And so He bids me go and speak
The loving word for Him;
He bids me tell His wondrous love,
And why He came to die,
And so we work together,
My Lord and I.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0456', 'verse', 1, 0, '[\"I have a Friend so precious,\",\"So very dear to me,\",\"He loves me with such tender love,\",\"He loves so faithfully;\",\"I could not live apart from Him,\",\"I love to feel Him nigh,\",\"And so we dwell together,\",\"My Lord and I.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0456', 'verse', 2, 1, '[\"Sometimes I\'m faint and weary,\",\"He knows that I am weak,\",\"And as He bids me lean on Him,\",\"His help I gladly seek;\",\"He leads me in the paths of light,\",\"Beneath a sunny sky,\",\"And so we walk together,\",\"My Lord and I.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0456', 'verse', 3, 2, '[\"I tell Him all my sorrows,\",\"I tell Him all my joys,\",\"I tell Him all that pleases me,\",\"I tell Him what annoys;\",\"He tells me what I ought to do,\",\"He tells me how to try,\",\"And so we talk together,\",\"My Lord and I.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0456', 'verse', 4, 3, '[\"He knows that I am longing\",\"Some weary soul to win,\",\"And so He bids me go and speak\",\"The loving word for Him;\",\"He bids me tell His wondrous love,\",\"And why He came to die,\",\"And so we work together,\",\"My Lord and I.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0457', 457, 'I Love to Tell the Story', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I love to tell the story
Of unseen things above,
Of Jesus and His glory,
Of Jesus and His love;
I love to tell the story,
Because I know \'tis true;
It satisfies my longing
As nothing else can do.
I love to tell the story;
\'Twill be my theme in glory
To tell the old, old story
Of Jesus and His love.
I love to tell the story;
More wonderful it seems
Than all the golden fancies
Of all our golden dreams;
I love to tell the story,
It did so much for me,
And that is just the reason
I tell it now to thee.
I love to tell the story;
\'Tis pleasant to repeat
What seems each time I tell it,
More wonderfully sweet;
I love to tell the story,
For some have never heard
The message of salvation');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0457', 'verse', 1, 0, '[\"I love to tell the story\",\"Of unseen things above,\",\"Of Jesus and His glory,\",\"Of Jesus and His love;\",\"I love to tell the story,\",\"Because I know \'tis true;\",\"It satisfies my longing\",\"As nothing else can do.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0457', 'chorus', 0, 1, '[\"I love to tell the story;\",\"\'Twill be my theme in glory\",\"To tell the old, old story\",\"Of Jesus and His love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0457', 'verse', 2, 2, '[\"I love to tell the story;\",\"More wonderful it seems\",\"Than all the golden fancies\",\"Of all our golden dreams;\",\"I love to tell the story,\",\"It did so much for me,\",\"And that is just the reason\",\"I tell it now to thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0457', 'verse', 3, 3, '[\"I love to tell the story;\",\"\'Tis pleasant to repeat\",\"What seems each time I tell it,\",\"More wonderfully sweet;\",\"I love to tell the story,\",\"For some have never heard\",\"The message of salvation\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0458', 458, 'More Love to Thee', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'More love to Thee, O Christ!
More love to Thee;
Hear Thou the prayer I make
On bended knee.
This is my earnest plea,
More love, O Christ, to Thee,
More love to Thee!
More love to Thee!
Once earthly joy I craved,
Sought peace and rest;
Now Thee alone I seek,
Give what is best.
This all my prayer shall be,
More love, O Christ, to Thee,
More love to Thee!
More love to Thee!
Let sorrow do its work,
Send grief or pain;
Sweet are Thy messengers,
Sweet their refrain,
When they can sing with me,
More love, O Christ, to Thee,
More love to Thee!
More love to Thee!
Then shall my latest breath
Whisper Thy praise;
This be the parting cry
My heart shall raise,
This still its prayer shall be:
More love, O Christ, to Thee,
More love to Thee!
More love to Thee!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0458', 'verse', 1, 0, '[\"More love to Thee, O Christ!\",\"More love to Thee;\",\"Hear Thou the prayer I make\",\"On bended knee.\",\"This is my earnest plea,\",\"More love, O Christ, to Thee,\",\"More love to Thee!\",\"More love to Thee!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0458', 'verse', 2, 1, '[\"Once earthly joy I craved,\",\"Sought peace and rest;\",\"Now Thee alone I seek,\",\"Give what is best.\",\"This all my prayer shall be,\",\"More love, O Christ, to Thee,\",\"More love to Thee!\",\"More love to Thee!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0458', 'verse', 3, 2, '[\"Let sorrow do its work,\",\"Send grief or pain;\",\"Sweet are Thy messengers,\",\"Sweet their refrain,\",\"When they can sing with me,\",\"More love, O Christ, to Thee,\",\"More love to Thee!\",\"More love to Thee!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0458', 'verse', 4, 3, '[\"Then shall my latest breath\",\"Whisper Thy praise;\",\"This be the parting cry\",\"My heart shall raise,\",\"This still its prayer shall be:\",\"More love, O Christ, to Thee,\",\"More love to Thee!\",\"More love to Thee!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0459', 459, 'As the Bridegroom to His Chosen', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'As the bridegroom to his chosen,
as the king to his realm,
As the keep unto the castle,
as the pilot to the helm,
So, Lord, art Thou to me.
As the fountain in the garden,
as the candle in the dark,
As the treasure in the coffer,
as the manna in the ark,
So, Lord, art Thou to me.
As the ruby in the setting,
as the honey in the comb,
As the light within the lantern,
as the father in the home,
So, Lord, art Thou to me.
As the sunshine in the heavens,
as the image in the glass,
As the fruits up in the fig tree,
as the dew upon the grass,
So, Lord, art Thou to me.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0459', 'verse', 1, 0, '[\"As the bridegroom to his chosen,\",\"as the king to his realm,\",\"As the keep unto the castle,\",\"as the pilot to the helm,\",\"So, Lord, art Thou to me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0459', 'verse', 2, 1, '[\"As the fountain in the garden,\",\"as the candle in the dark,\",\"As the treasure in the coffer,\",\"as the manna in the ark,\",\"So, Lord, art Thou to me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0459', 'verse', 3, 2, '[\"As the ruby in the setting,\",\"as the honey in the comb,\",\"As the light within the lantern,\",\"as the father in the home,\",\"So, Lord, art Thou to me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0459', 'verse', 4, 3, '[\"As the sunshine in the heavens,\",\"as the image in the glass,\",\"As the fruits up in the fig tree,\",\"as the dew upon the grass,\",\"So, Lord, art Thou to me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0460', 460, 'As Water to the Thirsty', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'As water to the thirsty,
As beauty to the eyes,
As strength that follows weakness,
As truth instead of lies;
As songtime and springtime and summertime to be,
So is my Lord, my living Lord,
So is my Lord to me.
Like calm in place of clamor
Like peace that follows pain,
Like meeting after parting,
Like sunshine after rain;
Like moonlight and starlight and sunlight on the sea,
So is my Lord, my living Lord,
So is my Lord to me.
As sleep that follows fever,
As gold instead of grey,
As freedom after bondage,
As sunrise to the day;
As home to the trav\'ler and all he longs to see,
So is my Lord, my Living Lord,
So is my Lord to me.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0460', 'verse', 1, 0, '[\"As water to the thirsty,\",\"As beauty to the eyes,\",\"As strength that follows weakness,\",\"As truth instead of lies;\",\"As songtime and springtime and summertime to be,\",\"So is my Lord, my living Lord,\",\"So is my Lord to me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0460', 'verse', 2, 1, '[\"Like calm in place of clamor\",\"Like peace that follows pain,\",\"Like meeting after parting,\",\"Like sunshine after rain;\",\"Like moonlight and starlight and sunlight on the sea,\",\"So is my Lord, my living Lord,\",\"So is my Lord to me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0460', 'verse', 3, 2, '[\"As sleep that follows fever,\",\"As gold instead of grey,\",\"As freedom after bondage,\",\"As sunrise to the day;\",\"As home to the trav\'ler and all he longs to see,\",\"So is my Lord, my Living Lord,\",\"So is my Lord to me.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0461', 461, 'Be Still My Soul', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Be still, my soul: the Lord is on thy side;
Bear patiently the cross of grief or pain;
Leave to thy God to order and provide;
In every change He faithful will remain.
Be still, my soul: thy best, thy heavenly friend
Through thorny ways leads to a joyful end.
Be still, my soul: thy God doth undertake
To guide the future as He has the past.
Thy hope, thy confidence let nothing shake;
All now mysterious shall be bright at last.
Be still, my soul: the waves and winds still know
His voice who ruled them while He dwelth below.
Be still, my soul: the hour is hastening on
When we shall be forever with the Lord,
When disappointment, grief, and fear are gone,
Sorrow forgot, love\'s purest joys restored.
Be still, my soul: when change and tears are past,
All safe and blessed we shall meet at last.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0461', 'verse', 1, 0, '[\"Be still, my soul: the Lord is on thy side;\",\"Bear patiently the cross of grief or pain;\",\"Leave to thy God to order and provide;\",\"In every change He faithful will remain.\",\"Be still, my soul: thy best, thy heavenly friend\",\"Through thorny ways leads to a joyful end.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0461', 'verse', 2, 1, '[\"Be still, my soul: thy God doth undertake\",\"To guide the future as He has the past.\",\"Thy hope, thy confidence let nothing shake;\",\"All now mysterious shall be bright at last.\",\"Be still, my soul: the waves and winds still know\",\"His voice who ruled them while He dwelth below.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0461', 'verse', 3, 2, '[\"Be still, my soul: the hour is hastening on\",\"When we shall be forever with the Lord,\",\"When disappointment, grief, and fear are gone,\",\"Sorrow forgot, love\'s purest joys restored.\",\"Be still, my soul: when change and tears are past,\",\"All safe and blessed we shall meet at last.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0462', 462, 'Blessed Assurance, Jesus Is Mine!', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Blessed assurance, Jesus is mine!
O, what a foretaste of glory divine!
Heir of salvation, purchase of God,
Born of His Spirit, washed in His blood.
This is my story, this is my song,
Praising my Savior all the day long;
This is my story, this is my song,
Praising my Savior all the day long.
Perfect submission, perfect delight,
Visions of rapture now burst on my sight.
Angels descending bring from above
Echoes of mercy, whispers of love.
Perfect submission, all is at rest,
I in my Savior am happy and blest,
Watching and waiting, looking above,
Filled with His goodness, lost in His love.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0462', 'verse', 1, 0, '[\"Blessed assurance, Jesus is mine!\",\"O, what a foretaste of glory divine!\",\"Heir of salvation, purchase of God,\",\"Born of His Spirit, washed in His blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0462', 'chorus', 0, 1, '[\"This is my story, this is my song,\",\"Praising my Savior all the day long;\",\"This is my story, this is my song,\",\"Praising my Savior all the day long.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0462', 'verse', 2, 2, '[\"Perfect submission, perfect delight,\",\"Visions of rapture now burst on my sight.\",\"Angels descending bring from above\",\"Echoes of mercy, whispers of love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0462', 'verse', 3, 3, '[\"Perfect submission, all is at rest,\",\"I in my Savior am happy and blest,\",\"Watching and waiting, looking above,\",\"Filled with His goodness, lost in His love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0463', 463, 'Peace, Perfect Peace', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Peace, perfect peace, in this dark world of sin?
The blood of Jesus whispers peace within.
Peace, perfect peace, by thronging duties pressed?
To do the will of Jesus: this is rest.
Peace, perfect peace, with loved ones far away?
In Jesus\' keeping we are safe, and they.
Peace, perfect peace, our future all unknown?
Jesus we know, and He is on the throne.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0463', 'verse', 1, 0, '[\"Peace, perfect peace, in this dark world of sin?\",\"The blood of Jesus whispers peace within.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0463', 'verse', 2, 1, '[\"Peace, perfect peace, by thronging duties pressed?\",\"To do the will of Jesus: this is rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0463', 'verse', 3, 2, '[\"Peace, perfect peace, with loved ones far away?\",\"In Jesus\' keeping we are safe, and they.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0463', 'verse', 4, 3, '[\"Peace, perfect peace, our future all unknown?\",\"Jesus we know, and He is on the throne.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0464', 464, 'When I Can Read My Title Clear', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'When I can read my title clear
To mansions in the skies
I\'ll bid farewell to every fear,
And wipe my weeping eyes;
And wipe my weeping eyes,
And wipe my weeping eyes,
I\'ll bid farewell to every fear,
And wipe my weeping eyes.
Should earth against my soul engage,
And fiery darts be hurled,
Then I can smile at Satan\'s rage,
And face a frowning world;
And face a frowning world,
And face a frowning world,
Then I can smile at Satan\'s rage,
And face a frowning world.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0464', 'verse', 1, 0, '[\"When I can read my title clear\",\"To mansions in the skies\",\"I\'ll bid farewell to every fear,\",\"And wipe my weeping eyes;\",\"And wipe my weeping eyes,\",\"And wipe my weeping eyes,\",\"I\'ll bid farewell to every fear,\",\"And wipe my weeping eyes.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0464', 'verse', 2, 1, '[\"Should earth against my soul engage,\",\"And fiery darts be hurled,\",\"Then I can smile at Satan\'s rage,\",\"And face a frowning world;\",\"And face a frowning world,\",\"And face a frowning world,\",\"Then I can smile at Satan\'s rage,\",\"And face a frowning world.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0465', 465, 'I Heard the Voice of Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I heard the voice of Jesus say,
\"Come unto Me and rest;
Lay down, thou weary one, lay down
Thy head upon My breast.\"
I came to Jesus as I was,
Weary and worn and sad;
I found in Him a resting place,
And He has made me glad.
I heard the voice of Jesus say,
\"Behold, I freely give
The living water; thirsty one,
Stoop down and drink and live.\"
I came to Jesus, and I drank
Of that life giving stream;
My thirst was quench\'d, my soul revived,
And now I live in Him.
I heard the voice of Jesus say,
\"I am this dark world\'s light;
Look unto Me, thy morn shall rise,
And all thy day be bright.\"
I looked to Jesus, and I found
In Him my star, my sun;
And in that light of life I\'ll walk,
Till trav\'ling days are done.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0465', 'verse', 1, 0, '[\"I heard the voice of Jesus say,\",\"\\\"Come unto Me and rest;\",\"Lay down, thou weary one, lay down\",\"Thy head upon My breast.\\\"\",\"I came to Jesus as I was,\",\"Weary and worn and sad;\",\"I found in Him a resting place,\",\"And He has made me glad.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0465', 'verse', 2, 1, '[\"I heard the voice of Jesus say,\",\"\\\"Behold, I freely give\",\"The living water; thirsty one,\",\"Stoop down and drink and live.\\\"\",\"I came to Jesus, and I drank\",\"Of that life giving stream;\",\"My thirst was quench\'d, my soul revived,\",\"And now I live in Him.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0465', 'verse', 3, 2, '[\"I heard the voice of Jesus say,\",\"\\\"I am this dark world\'s light;\",\"Look unto Me, thy morn shall rise,\",\"And all thy day be bright.\\\"\",\"I looked to Jesus, and I found\",\"In Him my star, my sun;\",\"And in that light of life I\'ll walk,\",\"Till trav\'ling days are done.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0466', 466, 'Wonderful Peace', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Far away in the depths of my spirit tonight,
Rolls a melody sweeter than psalm;
In celestial-like strains it unceasingly falls
O\'er my soul like an infinite calm.
Peace! peace! wonderful peace,
Coming down from the Father above;
Sweep over my spirit forever, I pray,
In fathomless billows of love.
What a treasure I have in this wonderful peace,
Buried deep in my innermost soul,
So secure that no power can mine it away,
While the years of eternity roll!
I believe when I rise to that city of peace,
Where the Author of peace I shall see,
That one strain of the song which the ransomed will sing,
In that heavenly kingdom will be;
Weary soul, without gladness or comfort or rest,
Passing down the rough pathway of time!
Make the Savior your friend ere the shadows grow dark;
O accept of this peace so sublime.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0466', 'verse', 1, 0, '[\"Far away in the depths of my spirit tonight,\",\"Rolls a melody sweeter than psalm;\",\"In celestial-like strains it unceasingly falls\",\"O\'er my soul like an infinite calm.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0466', 'chorus', 0, 1, '[\"Peace! peace! wonderful peace,\",\"Coming down from the Father above;\",\"Sweep over my spirit forever, I pray,\",\"In fathomless billows of love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0466', 'verse', 2, 2, '[\"What a treasure I have in this wonderful peace,\",\"Buried deep in my innermost soul,\",\"So secure that no power can mine it away,\",\"While the years of eternity roll!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0466', 'verse', 3, 3, '[\"I believe when I rise to that city of peace,\",\"Where the Author of peace I shall see,\",\"That one strain of the song which the ransomed will sing,\",\"In that heavenly kingdom will be;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0466', 'verse', 4, 4, '[\"Weary soul, without gladness or comfort or rest,\",\"Passing down the rough pathway of time!\",\"Make the Savior your friend ere the shadows grow dark;\",\"O accept of this peace so sublime.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0467', 467, 'Life Is Great! So Sing About It', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Life is great! So sing about it,
As we can and as we should-
Shop and buses, towns and people,
Village, farmland, field and wood,
Life is great and life is given;
Life is lovely, free and good.
Life is great!- what ever happens,
Snow or sunshine, joy or pain,
Hardship, grief or disillusion,
Suffering that I can\'t explain-
Life is great if someone loves me,
Holds my hand and calls my name.
Love is great!- the love of lovers,
Whispered words and longing eyes;
Love that gazes at the cradle
Where a child of loving lies;
Love that lasts when youth has faded,
Bends with age, but never dies.
Love is giving and receiving-
Boy and girl, or friend with friend;
Love is bearing and forgiving
All the hurts that hate can send;
Love\'s the greatest way of living,
Hoping, trusting to the end.
God is great! in Christ He loved us,
As we should, but never can-
Love that suffered, hoped and trusted
When disciples turned and ran,
Love that broke through death forever.
Praise that loving, living Man!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0467', 'verse', 1, 0, '[\"Life is great! So sing about it,\",\"As we can and as we should-\",\"Shop and buses, towns and people,\",\"Village, farmland, field and wood,\",\"Life is great and life is given;\",\"Life is lovely, free and good.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0467', 'verse', 2, 1, '[\"Life is great!- what ever happens,\",\"Snow or sunshine, joy or pain,\",\"Hardship, grief or disillusion,\",\"Suffering that I can\'t explain-\",\"Life is great if someone loves me,\",\"Holds my hand and calls my name.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0467', 'verse', 3, 2, '[\"Love is great!- the love of lovers,\",\"Whispered words and longing eyes;\",\"Love that gazes at the cradle\",\"Where a child of loving lies;\",\"Love that lasts when youth has faded,\",\"Bends with age, but never dies.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0467', 'verse', 4, 3, '[\"Love is giving and receiving-\",\"Boy and girl, or friend with friend;\",\"Love is bearing and forgiving\",\"All the hurts that hate can send;\",\"Love\'s the greatest way of living,\",\"Hoping, trusting to the end.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0467', 'verse', 5, 4, '[\"God is great! in Christ He loved us,\",\"As we should, but never can-\",\"Love that suffered, hoped and trusted\",\"When disciples turned and ran,\",\"Love that broke through death forever.\",\"Praise that loving, living Man!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0468', 468, 'A Child of the King', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'My Father is rich in houses and lands;
He holdeth the wealth of the world in His hands!
Of rubies and diamonds, of silver and gold,
His coffers are full; He has riches untold.
I\'m a child of the King, a child of the King!
With Jesus, my Savior, I\'m a child of the King!
My Father\'s own Son, the Savior of men,
Once wandered on earth as the poorest of them;
But now He is pleading for sinners on high,
And will give me a home when He comes by and by.
I once was an outcast, a stranger on earth,
A sinner by choice, and an alien by birth!
But I\'ve been adopted, my name\'s written down,
An heir to a mansion, a robe, and a crown.
A tent or a cottage, O why should I care?
They\'re building a palace for me over there!
Though exiled from home, yet still I may sing:
\"All glory to God, I\'m a child of the King.\"');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0468', 'verse', 1, 0, '[\"My Father is rich in houses and lands;\",\"He holdeth the wealth of the world in His hands!\",\"Of rubies and diamonds, of silver and gold,\",\"His coffers are full; He has riches untold.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0468', 'chorus', 0, 1, '[\"I\'m a child of the King, a child of the King!\",\"With Jesus, my Savior, I\'m a child of the King!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0468', 'verse', 2, 2, '[\"My Father\'s own Son, the Savior of men,\",\"Once wandered on earth as the poorest of them;\",\"But now He is pleading for sinners on high,\",\"And will give me a home when He comes by and by.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0468', 'verse', 3, 3, '[\"I once was an outcast, a stranger on earth,\",\"A sinner by choice, and an alien by birth!\",\"But I\'ve been adopted, my name\'s written down,\",\"An heir to a mansion, a robe, and a crown.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0468', 'verse', 4, 4, '[\"A tent or a cottage, O why should I care?\",\"They\'re building a palace for me over there!\",\"Though exiled from home, yet still I may sing:\",\"\\\"All glory to God, I\'m a child of the King.\\\"\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0469', 469, 'Leaning on the Everlasting Arms', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'What a fellowship, what a joy divine,
Leaning on the everlasting arms;
What a blessedness, what a peace is mine,
Leaning on the everlasting arms.
Leaning, leaning,
Safe and secure from all alarms;
Leaning, leaning,
Leaning on the everlasting arms.
O how sweet to walk in this pilgrim way,
Leaning on the everlasting arms;
O how bright the path grows from day to day,
Leaning on the everlasting arms.
What have I to dread, what have I to fear,
Leaning on the everlasting arms?
I have blessed peace with my Lord so near,
Leaning on the everlasting arms.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0469', 'verse', 1, 0, '[\"What a fellowship, what a joy divine,\",\"Leaning on the everlasting arms;\",\"What a blessedness, what a peace is mine,\",\"Leaning on the everlasting arms.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0469', 'chorus', 0, 1, '[\"Leaning, leaning,\",\"Safe and secure from all alarms;\",\"Leaning, leaning,\",\"Leaning on the everlasting arms.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0469', 'verse', 2, 2, '[\"O how sweet to walk in this pilgrim way,\",\"Leaning on the everlasting arms;\",\"O how bright the path grows from day to day,\",\"Leaning on the everlasting arms.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0469', 'verse', 3, 3, '[\"What have I to dread, what have I to fear,\",\"Leaning on the everlasting arms?\",\"I have blessed peace with my Lord so near,\",\"Leaning on the everlasting arms.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0470', 470, 'There\'s Sunshine in My Soul Today', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'There\'s sunshine in my soul today,
More glorious and bright,
Than glows in any earthly sky,
For Jesus is my light.
O there\'s sunshine, blessed sunshine,
When the peaceful, happy moments roll;
When Jesus shows His smiling face
There is sunshine in the soul.
There\'s music in my soul today,
A carol to my King,
And Jesus, listening, can hear
The songs I cannot sing.
There\'s springtime in my soul today,
For when the Lord is near,
The dove of peace sings in my heart,
The flowers of grace appear.
There\'s gladness in my soul today,
And hope, and praise, and love,
For blessings which He gives me now,
For joys \"laid up\" above.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0470', 'verse', 1, 0, '[\"There\'s sunshine in my soul today,\",\"More glorious and bright,\",\"Than glows in any earthly sky,\",\"For Jesus is my light.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0470', 'chorus', 0, 1, '[\"O there\'s sunshine, blessed sunshine,\",\"When the peaceful, happy moments roll;\",\"When Jesus shows His smiling face\",\"There is sunshine in the soul.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0470', 'verse', 2, 2, '[\"There\'s music in my soul today,\",\"A carol to my King,\",\"And Jesus, listening, can hear\",\"The songs I cannot sing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0470', 'verse', 3, 3, '[\"There\'s springtime in my soul today,\",\"For when the Lord is near,\",\"The dove of peace sings in my heart,\",\"The flowers of grace appear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0470', 'verse', 4, 4, '[\"There\'s gladness in my soul today,\",\"And hope, and praise, and love,\",\"For blessings which He gives me now,\",\"For joys \\\"laid up\\\" above.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0471', 471, 'Grant Us Your Peace', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Dona nobis pacem, pacem;
