INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0471', 'verse', 2, 1, '[\"Father grant us, grant us Your peace;\",\"Oh, loving Father, grant us Your peace.\",\"Grant us, grant us peace;\",\"Grant us, grant us, grant Your peace;\",\"Grant us, grant us peace;\",\"Loving Father, grant us Your peace.\"]');
