INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0472', 472, 'A Song of Heaven and Homeland', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Sometimes I hear strange music,
Like none e\'er heard before,
Come floating softly earthward
As thro\' heav\'n\'s open door:
It seems like angel voices,
In strains of joy and love,
That swell the mighty chorus
Around the throne above.
O sweet, celestial music,
Heard from a land afar;
The song of Heav\'n and Homeland,
Thro\' doors God leaves ajar!
Now soft, and low, and restful,
It floods my soul with peace,
As if God\'s benediction
Bade all earth\'s troubles cease.
Then grander than the voices,
Of wind, and wave, and sea;
It fills the dome of heaven
With glorious harmony.
This music haunts me ever,
Like something heard in dreams;
It seems to catch the cadence
Of heav\'nly winds and streams.
My heart is filled with rapture,
To think, some day to come,
I\'ll sing it with the angels;
The song of heav\'n and home.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0472', 'verse', 1, 0, '[\"Sometimes I hear strange music,\",\"Like none e\'er heard before,\",\"Come floating softly earthward\",\"As thro\' heav\'n\'s open door:\",\"It seems like angel voices,\",\"In strains of joy and love,\",\"That swell the mighty chorus\",\"Around the throne above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0472', 'chorus', 0, 1, '[\"O sweet, celestial music,\",\"Heard from a land afar;\",\"The song of Heav\'n and Homeland,\",\"Thro\' doors God leaves ajar!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0472', 'verse', 2, 2, '[\"Now soft, and low, and restful,\",\"It floods my soul with peace,\",\"As if God\'s benediction\",\"Bade all earth\'s troubles cease.\",\"Then grander than the voices,\",\"Of wind, and wave, and sea;\",\"It fills the dome of heaven\",\"With glorious harmony.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0472', 'verse', 3, 3, '[\"This music haunts me ever,\",\"Like something heard in dreams;\",\"It seems to catch the cadence\",\"Of heav\'nly winds and streams.\",\"My heart is filled with rapture,\",\"To think, some day to come,\",\"I\'ll sing it with the angels;\",\"The song of heav\'n and home.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0473', 473, 'Nearer My God, to Thee', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Nearer, my God, to Thee,
Nearer to Thee!
E\'en though it be a cross
That raiseth me!
Still all my song shall be,
Nearer, my God, to Thee,
Nearer, my God, to Thee,
Nearer to Thee.
Though like a wanderer,
Daylight all gone,
Darkness be over me,
My rest a stone;
Yet in my dreams I\'d be
Nearer, my God, to Thee,
Nearer, my God, to Thee,
Nearer to Thee.
There let the way appear,
Steps up to heaven;
All that Thou sendest me,
In mercy given;
Angels to beckon me
Nearer, my God, to Thee,
Nearer, my God, to Thee,
Nearer to Thee.
Then, with my waking thoughts
Bright with Thy praise,
Out of my stony griefs
Bethel I raise;
So by my woes to be
Nearer, my God, to Thee,
Nearer, my God, to Thee,
Nearer to Thee.
Or if, on joyful wing
Cleaving the sky,
Sun, moon, and stars forgot,
Upward I fly,
Still all my song shall be,
Nearer, my God, to Thee,
Nearer, my God, to Thee,
Nearer to Thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0473', 'verse', 1, 0, '[\"Nearer, my God, to Thee,\",\"Nearer to Thee!\",\"E\'en though it be a cross\",\"That raiseth me!\",\"Still all my song shall be,\",\"Nearer, my God, to Thee,\",\"Nearer, my God, to Thee,\",\"Nearer to Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0473', 'verse', 2, 1, '[\"Though like a wanderer,\",\"Daylight all gone,\",\"Darkness be over me,\",\"My rest a stone;\",\"Yet in my dreams I\'d be\",\"Nearer, my God, to Thee,\",\"Nearer, my God, to Thee,\",\"Nearer to Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0473', 'verse', 3, 2, '[\"There let the way appear,\",\"Steps up to heaven;\",\"All that Thou sendest me,\",\"In mercy given;\",\"Angels to beckon me\",\"Nearer, my God, to Thee,\",\"Nearer, my God, to Thee,\",\"Nearer to Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0473', 'verse', 4, 3, '[\"Then, with my waking thoughts\",\"Bright with Thy praise,\",\"Out of my stony griefs\",\"Bethel I raise;\",\"So by my woes to be\",\"Nearer, my God, to Thee,\",\"Nearer, my God, to Thee,\",\"Nearer to Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0473', 'verse', 5, 4, '[\"Or if, on joyful wing\",\"Cleaving the sky,\",\"Sun, moon, and stars forgot,\",\"Upward I fly,\",\"Still all my song shall be,\",\"Nearer, my God, to Thee,\",\"Nearer, my God, to Thee,\",\"Nearer to Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0474', 474, 'Take the Name of Jesus With You', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Take the name of Jesus with you,
Child of sorrow and of woe;
It will joy and comfort give you,
Take it, then, where\'er you go.
Precious name, O how sweet!
Hope of earth and joy of heaven;
Precious name, O how sweet!
Hope of earth and joy of heaven.
Take the name of Jesus ever,
As a shield from every snare;
If temptations round you gather,
Breathe that holy name in prayer.
O the precious name of Jesus!
How it thrills our souls with joy,
When His loving arms receive us,
And His songs our tongues employ.
At the name of Jesus bowing,
Falling prostrate at His feet,
King of kings in heaven we\'ll crown Him,
When our journey is complete.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0474', 'verse', 1, 0, '[\"Take the name of Jesus with you,\",\"Child of sorrow and of woe;\",\"It will joy and comfort give you,\",\"Take it, then, where\'er you go.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0474', 'chorus', 0, 1, '[\"Precious name, O how sweet!\",\"Hope of earth and joy of heaven;\",\"Precious name, O how sweet!\",\"Hope of earth and joy of heaven.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0474', 'verse', 2, 2, '[\"Take the name of Jesus ever,\",\"As a shield from every snare;\",\"If temptations round you gather,\",\"Breathe that holy name in prayer.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0474', 'verse', 3, 3, '[\"O the precious name of Jesus!\",\"How it thrills our souls with joy,\",\"When His loving arms receive us,\",\"And His songs our tongues employ.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0474', 'verse', 4, 4, '[\"At the name of Jesus bowing,\",\"Falling prostrate at His feet,\",\"King of kings in heaven we\'ll crown Him,\",\"When our journey is complete.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0475', 475, 'Balm in Gilead', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Sometimes I feel discouraged,
And think my work\'s in vain,
But then the Holy Spirit
Revives my soul again.
There is a balm in Gilead to make the wounded whole;
There is a balm in Gilead to heal the sinsick soul.
If you cannot preach like Peter,
If you cannot pray like Paul,
You can tell the love of Jesus,
And say He died for all.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0475', 'verse', 1, 0, '[\"Sometimes I feel discouraged,\",\"And think my work\'s in vain,\",\"But then the Holy Spirit\",\"Revives my soul again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0475', 'chorus', 0, 1, '[\"There is a balm in Gilead to make the wounded whole;\",\"There is a balm in Gilead to heal the sinsick soul.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0475', 'verse', 2, 2, '[\"If you cannot preach like Peter,\",\"If you cannot pray like Paul,\",\"You can tell the love of Jesus,\",\"And say He died for all.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0476', 476, 'Burdens Are Lifted At Calvary', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Days are filled with sorrow and care,
Hearts are lonely and drear;
Burdens are lifted at Calvary,
Jesus is very near.
Burdens are lifted at Calvary,
Calvary, Calvary;
Burdens are lifted at Calvary,
Jesus is very near.
Cast your care on Jesus today,
Leave your worry and fear;
Burdens are lifted at Calvary,
Jesus is very near.
Troubled soul, the Savior can see
Every heartache and tear;
Burdens are lifted at Calvary,
Jesus is very near.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0476', 'verse', 1, 0, '[\"Days are filled with sorrow and care,\",\"Hearts are lonely and drear;\",\"Burdens are lifted at Calvary,\",\"Jesus is very near.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0476', 'chorus', 0, 1, '[\"Burdens are lifted at Calvary,\",\"Calvary, Calvary;\",\"Burdens are lifted at Calvary,\",\"Jesus is very near.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0476', 'verse', 2, 2, '[\"Cast your care on Jesus today,\",\"Leave your worry and fear;\",\"Burdens are lifted at Calvary,\",\"Jesus is very near.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0476', 'verse', 3, 3, '[\"Troubled soul, the Savior can see\",\"Every heartache and tear;\",\"Burdens are lifted at Calvary,\",\"Jesus is very near.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0477', 477, 'Come, Ye Disconsolate', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Come, ye disconsolate, where\'er ye languish;
Come to the mercy seat, fervently kneel;
Here bring your wounded hearts, here tell your anguish;
Earth has no sorrow that heaven cannot heal.
Joy of the comfortless, light of the straying,
Hope of the penitent, fadeless and pure!
Here speaks the Comforter, tenderly saying,
\"Earth has no sorrow that heaven cannot cure.\"
Here see the Bread of Life; see waters flowing
Forth from the throne of God, pure from above;
Come to the feast of love; come, ever knowing
Earth has no sorrow but heaven can remove.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0477', 'verse', 1, 0, '[\"Come, ye disconsolate, where\'er ye languish;\",\"Come to the mercy seat, fervently kneel;\",\"Here bring your wounded hearts, here tell your anguish;\",\"Earth has no sorrow that heaven cannot heal.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0477', 'verse', 2, 1, '[\"Joy of the comfortless, light of the straying,\",\"Hope of the penitent, fadeless and pure!\",\"Here speaks the Comforter, tenderly saying,\",\"\\\"Earth has no sorrow that heaven cannot cure.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0477', 'verse', 3, 2, '[\"Here see the Bread of Life; see waters flowing\",\"Forth from the throne of God, pure from above;\",\"Come to the feast of love; come, ever knowing\",\"Earth has no sorrow but heaven can remove.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0478', 478, 'Sweet Hour of Prayer', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Sweet hour of prayer, sweet hour of prayer,
That calls me from a world of care,
And bids me, at my Father\'s throne,
Make all my wants and wishes known!
In seasons of distress and grief,
My soul has often found relief.
And oft escaped the tempters snare,
By thy return, sweet hour of prayer.
Sweet hour of prayer! sweet hour of prayer!
Thy wings shall my petition bear
To Him whose truth and faithfulness
Engage the waiting soul to bless.
And since He bids me seek His face,
Believe His word, and trust His grace,
I\'ll cast on Him my every care,
And wait for thee, sweet hour of prayer.
Sweet hour of prayer! sweet hour of prayer!
May I thy consolation share
Till from Mount Pisgah\'s lofty height
I view my home and take my flight.
In my immortal flesh I\'ll rise
To seize the everlasting prize.
And shout while passing through the air,
\"Farewell, farewell, sweet hour of prayer!\"');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0478', 'verse', 1, 0, '[\"Sweet hour of prayer, sweet hour of prayer,\",\"That calls me from a world of care,\",\"And bids me, at my Father\'s throne,\",\"Make all my wants and wishes known!\",\"In seasons of distress and grief,\",\"My soul has often found relief.\",\"And oft escaped the tempters snare,\",\"By thy return, sweet hour of prayer.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0478', 'verse', 2, 1, '[\"Sweet hour of prayer! sweet hour of prayer!\",\"Thy wings shall my petition bear\",\"To Him whose truth and faithfulness\",\"Engage the waiting soul to bless.\",\"And since He bids me seek His face,\",\"Believe His word, and trust His grace,\",\"I\'ll cast on Him my every care,\",\"And wait for thee, sweet hour of prayer.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0478', 'verse', 3, 2, '[\"Sweet hour of prayer! sweet hour of prayer!\",\"May I thy consolation share\",\"Till from Mount Pisgah\'s lofty height\",\"I view my home and take my flight.\",\"In my immortal flesh I\'ll rise\",\"To seize the everlasting prize.\",\"And shout while passing through the air,\",\"\\\"Farewell, farewell, sweet hour of prayer!\\\"\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0479', 479, 'Tread Softly', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Be silent, be silent,
A whisper is heard;
Be silent, and listen,
Oh, treasure each word.
Tread softly, tread softly,
The Master is here;
Tread softly, tread softly,
He bids us draw near.
Be silent, be silent,
For holy this place,
This altar that echoes
The message of grace.
Be silent, be silent,
Breathe humbly our prayer;
A foretaste of Eden
This moment we share.
Be silent, be silent,
His mercy record;
Be silent, be silent,
And wait on the Lord.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0479', 'verse', 1, 0, '[\"Be silent, be silent,\",\"A whisper is heard;\",\"Be silent, and listen,\",\"Oh, treasure each word.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0479', 'chorus', 0, 1, '[\"Tread softly, tread softly,\",\"The Master is here;\",\"Tread softly, tread softly,\",\"He bids us draw near.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0479', 'verse', 2, 2, '[\"Be silent, be silent,\",\"For holy this place,\",\"This altar that echoes\",\"The message of grace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0479', 'verse', 3, 3, '[\"Be silent, be silent,\",\"Breathe humbly our prayer;\",\"A foretaste of Eden\",\"This moment we share.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0479', 'verse', 4, 4, '[\"Be silent, be silent,\",\"His mercy record;\",\"Be silent, be silent,\",\"And wait on the Lord.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0480', 480, 'Dear Lord and Father', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Dear Lord and Father of mankind,
Forgive our foolish ways;
Reclothe us in our rightful mind,
In purer lives Thy service find,
In deeper reverence praise,
In deeper reverence, praise.
In simple trust like theirs who heard,
Beside the Syrian sea,
The gracious calling of the Lord,
Let us, like them, without a word,
Rise up and follow Thee,
Rise up and follow Thee.
O Sabbath rest by Galilee,
O calm of hills above,
Where Jesus knelt to share with Thee
The silence of eternity,
Interpreted by love,
Interpreted by love.
Drop Thy still dews of quietness,
Till all our strivings cease;
Take from our souls the strain and stress,
And let our ordered lives confess
The beauty of Thy peace,
The beauty of Thy peace.
Breathe thro\' the heats of our desire,
Thy coolness and Thy balm;
Let sense be dumb, let flesh retire;
Speak thro\' the earthquake, wind, and fire,
O still small voice of calm,
O still small voice of calm.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0480', 'verse', 1, 0, '[\"Dear Lord and Father of mankind,\",\"Forgive our foolish ways;\",\"Reclothe us in our rightful mind,\",\"In purer lives Thy service find,\",\"In deeper reverence praise,\",\"In deeper reverence, praise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0480', 'verse', 2, 1, '[\"In simple trust like theirs who heard,\",\"Beside the Syrian sea,\",\"The gracious calling of the Lord,\",\"Let us, like them, without a word,\",\"Rise up and follow Thee,\",\"Rise up and follow Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0480', 'verse', 3, 2, '[\"O Sabbath rest by Galilee,\",\"O calm of hills above,\",\"Where Jesus knelt to share with Thee\",\"The silence of eternity,\",\"Interpreted by love,\",\"Interpreted by love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0480', 'verse', 4, 3, '[\"Drop Thy still dews of quietness,\",\"Till all our strivings cease;\",\"Take from our souls the strain and stress,\",\"And let our ordered lives confess\",\"The beauty of Thy peace,\",\"The beauty of Thy peace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0480', 'verse', 5, 4, '[\"Breathe thro\' the heats of our desire,\",\"Thy coolness and Thy balm;\",\"Let sense be dumb, let flesh retire;\",\"Speak thro\' the earthquake, wind, and fire,\",\"O still small voice of calm,\",\"O still small voice of calm.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0481', 481, 'Dear Lord and Father', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Dear Lord and Father of mankind,
Forgive our feverish ways;
Reclothe us in our rightful mind
In purer lives Thy service find,
In deeper reverence praise.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0481', 'verse', 1, 0, '[\"Dear Lord and Father of mankind,\",\"Forgive our feverish ways;\",\"Reclothe us in our rightful mind\",\"In purer lives Thy service find,\",\"In deeper reverence praise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0482', 482, 'Father, Lead Me Day by Day', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Father, lead me day by day,
Ever in Thine own sweet way;
Teach me to be pure and true;
Show me what I ought to do.
When in danger, make me brave;
Make me know that Thou canst save;
Keep me safe by Thy dear side;
Let me in Thy love abide.
When I\'m tempted to do wrong,
Make me steadfast, wise, and strong;
And when all alone I stand,
Shield me with Thy mighty hand.
May I do the good I know,
Be Thy loving child below,
Then at last go home to Thee,
Evermore Thy child to be.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0482', 'verse', 1, 0, '[\"Father, lead me day by day,\",\"Ever in Thine own sweet way;\",\"Teach me to be pure and true;\",\"Show me what I ought to do.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0482', 'verse', 2, 1, '[\"When in danger, make me brave;\",\"Make me know that Thou canst save;\",\"Keep me safe by Thy dear side;\",\"Let me in Thy love abide.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0482', 'verse', 3, 2, '[\"When I\'m tempted to do wrong,\",\"Make me steadfast, wise, and strong;\",\"And when all alone I stand,\",\"Shield me with Thy mighty hand.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0482', 'verse', 4, 3, '[\"May I do the good I know,\",\"Be Thy loving child below,\",\"Then at last go home to Thee,\",\"Evermore Thy child to be.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0483', 483, 'I Need Thee Every Hour', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I need Thee every hour,
Most gracious Lord;
No tender voice like Thine
Can peace afford.
I need Thee, O I need Thee;
Every hour I need Thee!
O bless me now, my Savior;
I come to Thee.
I need Thee every hour,
Stay Thou near by;
Temptations lose their power
When Thou art nigh.
I need Thee every hour,
In joy or pain;
Come quickly, and abide,
Or life is vain.
I need Thee every hour,
Teach me Thy will,
And Thy rich promises
In me fulfill.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0483', 'verse', 1, 0, '[\"I need Thee every hour,\",\"Most gracious Lord;\",\"No tender voice like Thine\",\"Can peace afford.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0483', 'chorus', 0, 1, '[\"I need Thee, O I need Thee;\",\"Every hour I need Thee!\",\"O bless me now, my Savior;\",\"I come to Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0483', 'verse', 2, 2, '[\"I need Thee every hour,\",\"Stay Thou near by;\",\"Temptations lose their power\",\"When Thou art nigh.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0483', 'verse', 3, 3, '[\"I need Thee every hour,\",\"In joy or pain;\",\"Come quickly, and abide,\",\"Or life is vain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0483', 'verse', 4, 4, '[\"I need Thee every hour,\",\"Teach me Thy will,\",\"And Thy rich promises\",\"In me fulfill.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0484', 484, 'I Need Thee, Precious Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I need Thee, precious Jesus,
For I am very poor;
A stranger and a pilgrim,
I have no earthly store.
I need the love of Jesus
To cheer me on my way,
To guide my doubting footsteps,
To be my strength and stay.
I need the heart of Jesus
To feel each anxious care,
To tell my every trial,
And all my sorrows share.
I need the Holy Spirit
To teach me what I am,
To show me more of Jesus,
To point me to the Lamb.
I need Thee, precious Jesus,
I hope to see Thee soon,
Encircled with the rainbow,
And seated on Thy throne.
There, with Thy blood-bought children,
My joy shall ever be
To sing Thy ceaseless praises,
To gaze, my Lord, on Thee!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0484', 'verse', 1, 0, '[\"I need Thee, precious Jesus,\",\"For I am very poor;\",\"A stranger and a pilgrim,\",\"I have no earthly store.\",\"I need the love of Jesus\",\"To cheer me on my way,\",\"To guide my doubting footsteps,\",\"To be my strength and stay.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0484', 'verse', 2, 1, '[\"I need the heart of Jesus\",\"To feel each anxious care,\",\"To tell my every trial,\",\"And all my sorrows share.\",\"I need the Holy Spirit\",\"To teach me what I am,\",\"To show me more of Jesus,\",\"To point me to the Lamb.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0484', 'verse', 3, 2, '[\"I need Thee, precious Jesus,\",\"I hope to see Thee soon,\",\"Encircled with the rainbow,\",\"And seated on Thy throne.\",\"There, with Thy blood-bought children,\",\"My joy shall ever be\",\"To sing Thy ceaseless praises,\",\"To gaze, my Lord, on Thee!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0485', 485, 'I Must Tell Jesus', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I must tell Jesus all of my trials;
I cannot bear the burdens alone,
In my distress He kindly will help me,
He ever loves and cares for His own.
I must tell Jesus!
I must tell Jesus!
I cannot bear my burdens alone;
I must tell Jesus!
I must tell Jesus!
Jesus can help me, Jesus alone.
I must tell Jesus all of my troubles,
He is a kind, compassionate Friend;
If I but ask Him, He will deliver,
Makes of my troubles quickly an end.
O how the world to evil allures me!
O how my heart is tempted to sin!
I must tell Jesus, and He will help me
Over the world the vict\'ry to win.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0485', 'verse', 1, 0, '[\"I must tell Jesus all of my trials;\",\"I cannot bear the burdens alone,\",\"In my distress He kindly will help me,\",\"He ever loves and cares for His own.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0485', 'chorus', 0, 1, '[\"I must tell Jesus!\",\"I must tell Jesus!\",\"I cannot bear my burdens alone;\",\"I must tell Jesus!\",\"I must tell Jesus!\",\"Jesus can help me, Jesus alone.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0485', 'verse', 2, 2, '[\"I must tell Jesus all of my troubles,\",\"He is a kind, compassionate Friend;\",\"If I but ask Him, He will deliver,\",\"Makes of my troubles quickly an end.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0485', 'verse', 3, 3, '[\"O how the world to evil allures me!\",\"O how my heart is tempted to sin!\",\"I must tell Jesus, and He will help me\",\"Over the world the vict\'ry to win.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0486', 486, 'I Do Believe', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Father, I stretch my hands to Thee;
No other help I know;
If Thou withdraw Thyself from me,
Ah, whither shall I go?
On Thy dear Son I now believe,
O let me feel Thy power;
And all my varied wants relieve,
In this accepted hour.
Author of faith! to Thee I lift
My weary, longing eyes;
O let me now receive that gift;
My soul without it dies.
Surely Thou canst not let me die;
O speak, and I shall live;
And here I will unwearied lie,
Till Thou Thy Spirit give.
How would my fainting soul rejoice
Could I but see Thy face!
Now let me hear Thy quickening voice,
And taste Thy pardoning grace.
I do believe, I now believe
That Jesus died for me,
And that He shed His precious blood');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0486', 'verse', 1, 0, '[\"Father, I stretch my hands to Thee;\",\"No other help I know;\",\"If Thou withdraw Thyself from me,\",\"Ah, whither shall I go?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0486', 'verse', 2, 1, '[\"On Thy dear Son I now believe,\",\"O let me feel Thy power;\",\"And all my varied wants relieve,\",\"In this accepted hour.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0486', 'verse', 3, 2, '[\"Author of faith! to Thee I lift\",\"My weary, longing eyes;\",\"O let me now receive that gift;\",\"My soul without it dies.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0486', 'verse', 4, 3, '[\"Surely Thou canst not let me die;\",\"O speak, and I shall live;\",\"And here I will unwearied lie,\",\"Till Thou Thy Spirit give.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0486', 'verse', 5, 4, '[\"How would my fainting soul rejoice\",\"Could I but see Thy face!\",\"Now let me hear Thy quickening voice,\",\"And taste Thy pardoning grace.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0486', 'verse', 6, 5, '[\"I do believe, I now believe\",\"That Jesus died for me,\",\"And that He shed His precious blood\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0487', 487, 'In the Garden', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'I come to the garden alone,
While the dew is still on the roses;
And the voice I hear, falling on my ear,
The Son of God discloses.
And He walks with me, and He talks with me,
And He tells me I am His own;
And the joy we share as we tarry there,
None other has ever known.
He speaks, and the sound of His voice
Is so sweet the birds hush their singing,
And the melody that He gave to me
Within my heart is ringing.
I\'d stay in the garden with Him
Though the night around me be falling,
But He bids me go; through the voice of woe,
His voice to me is calling.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0487', 'verse', 1, 0, '[\"I come to the garden alone,\",\"While the dew is still on the roses;\",\"And the voice I hear, falling on my ear,\",\"The Son of God discloses.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0487', 'chorus', 0, 1, '[\"And He walks with me, and He talks with me,\",\"And He tells me I am His own;\",\"And the joy we share as we tarry there,\",\"None other has ever known.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0487', 'verse', 2, 2, '[\"He speaks, and the sound of His voice\",\"Is so sweet the birds hush their singing,\",\"And the melody that He gave to me\",\"Within my heart is ringing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0487', 'verse', 3, 3, '[\"I\'d stay in the garden with Him\",\"Though the night around me be falling,\",\"But He bids me go; through the voice of woe,\",\"His voice to me is calling.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0488', 488, 'At First I Prayed for Light', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'At first I prayed for light:
Could I but see the way,
How gladly, swiftly would I walk
To everlasting day!
And next I prayed for strength:
That I might tread the road
With firm, unfaltering feet, and win
The heaven\'s serene abode.
And then I asked for faith:
Could I but trust my God,
I\'d live infolded in His peace,
Though foes were all abroad.
But now I pray for love:
Deep love to God and man;
A living love that will not fail,
However dark His plan.
And light and strength and faith
Are opening everywhere!
God waited patiently until
I prayed the larger prayer.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0488', 'verse', 1, 0, '[\"At first I prayed for light:\",\"Could I but see the way,\",\"How gladly, swiftly would I walk\",\"To everlasting day!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0488', 'verse', 2, 1, '[\"And next I prayed for strength:\",\"That I might tread the road\",\"With firm, unfaltering feet, and win\",\"The heaven\'s serene abode.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0488', 'verse', 3, 2, '[\"And then I asked for faith:\",\"Could I but trust my God,\",\"I\'d live infolded in His peace,\",\"Though foes were all abroad.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0488', 'verse', 4, 3, '[\"But now I pray for love:\",\"Deep love to God and man;\",\"A living love that will not fail,\",\"However dark His plan.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0488', 'verse', 5, 4, '[\"And light and strength and faith\",\"Are opening everywhere!\",\"God waited patiently until\",\"I prayed the larger prayer.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('SDAH-0489', 489, 'Jesus, Lover of My Soul', 'SDAH', 'en', '', '', 0, 0, 0, 0, 0, 'Jesus, lover of my soul,
Let me to Thy bosom fly,
While the billows near me roll,
While the tempest still is high;
Hide me, O my Savior, hide!
Till the storm of life is past;
Safe into the haven guide,
O receive my soul at last!
Other refuge have I none,
Hangs my helpless soul on Thee;
Leave, O leave me not alone!
Still support and comfort me;
All my trust on Thee is stayed,
All my help from Thee I bring;
Cover my defenseless head
With the shadow of Thy wing.
Thou, O Christ, art all I want,
More than all in Thee I find;
Raise the fallen, cheer the faint,
Heal the sick, and lead the blind.
Just and holy is Thy name,
I am all unrighteousness;
Vile and full of sin I am,
Thou art full of truth and grace.
Plenteous grace with Thee is found;
Grace to pardon all my sin;
Let the healing streams abound,
Make and keep me pure within;
Thou of life the Fountain art,
Freely let me take of Thee;
Spring Thou up within my heart,
Rise to all eternity.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0489', 'verse', 1, 0, '[\"Jesus, lover of my soul,\",\"Let me to Thy bosom fly,\",\"While the billows near me roll,\",\"While the tempest still is high;\",\"Hide me, O my Savior, hide!\",\"Till the storm of life is past;\",\"Safe into the haven guide,\",\"O receive my soul at last!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0489', 'verse', 2, 1, '[\"Other refuge have I none,\",\"Hangs my helpless soul on Thee;\",\"Leave, O leave me not alone!\",\"Still support and comfort me;\",\"All my trust on Thee is stayed,\",\"All my help from Thee I bring;\",\"Cover my defenseless head\",\"With the shadow of Thy wing.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('SDAH-0489', 'verse', 3, 2, '[\"Thou, O Christ, art all I want,\",\"More than all in Thee I find;\",\"Raise the fallen, cheer the faint,\",\"Heal the sick, and lead the blind.\",\"Just and holy is Thy name,\",\"I am all unrighteousness;\",\"Vile and full of sin I am,\",\"Thou art full of truth and grace.\"]');
