INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0160', 'verse', 4, 3, '[\"Well, the delightful day will come,\",\"When my dear Lord will bring me home,\",\"And I shall see His face;\",\"Then with my Saviour, Brother, Friend,\",\"A blest eternity I’ll spend,\",\"Triumphant in His grace,\",\"Triumphant in His grace.\"]');
