INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0227', 227, 'Behold the Saviour at the Door', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Behold the Saviour at the door!
He gently knocks, has knocked before,
Has waited long, is waiting still;
You treat no other friend so ill.
He counsels thee to buy of him
Gold tried by fire, and raiment clean;
Anoint thine eyes, that thou mayest see,
And put away thy stains from thee.
O, hear the faithful Witness\' voice,
He offers now a final choice;
Thou art offensive, O lukewarm!
Therefore be zealous and reform.
His mission now is almost o\'er,
Before the throne He\'ll plead no more;
The filthy must his filth retain,
He that is holy, so remain.
His locks with dews of night are wet,
But at thy heart he lingereth yet.
O wake, and open wide the door;
Bid thy Beloved wait no more.
Yea, bring him in, a welcome guest;
So shalt thou in his presence rest,
And in communion sweet and free,
Shalt sup with him and he with thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0227', 'verse', 1, 0, '[\"Behold the Saviour at the door!\",\"He gently knocks, has knocked before,\",\"Has waited long, is waiting still;\",\"You treat no other friend so ill.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0227', 'verse', 2, 1, '[\"He counsels thee to buy of him\",\"Gold tried by fire, and raiment clean;\",\"Anoint thine eyes, that thou mayest see,\",\"And put away thy stains from thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0227', 'verse', 3, 2, '[\"O, hear the faithful Witness\' voice,\",\"He offers now a final choice;\",\"Thou art offensive, O lukewarm!\",\"Therefore be zealous and reform.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0227', 'verse', 4, 3, '[\"His mission now is almost o\'er,\",\"Before the throne He\'ll plead no more;\",\"The filthy must his filth retain,\",\"He that is holy, so remain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0227', 'verse', 5, 4, '[\"His locks with dews of night are wet,\",\"But at thy heart he lingereth yet.\",\"O wake, and open wide the door;\",\"Bid thy Beloved wait no more.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0227', 'verse', 6, 5, '[\"Yea, bring him in, a welcome guest;\",\"So shalt thou in his presence rest,\",\"And in communion sweet and free,\",\"Shalt sup with him and he with thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0228', 228, 'Almost Persuaded', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Almost persuaded now to believe;
Almost persuaded Christ to receive.
Seems now some soul to say,
“Go, Spirit, go thy way,
Some more convenient day
On thee I’ll call.”
Almost persuaded, come, come today;
Almost persuaded, turn not away.
Jesus invites you here,
Angels are lingering near,
Prayers rise from hearts so dear;
O wanderer, come!
Almost persuaded, harvest is past;
Almost persuaded, doom comes at last!
“Almost” cannot avail;
“Almost” is but to fail!
Sad, sad that bitter wail,
“Almost—but lost!”');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0228', 'verse', 1, 0, '[\"Almost persuaded now to believe;\",\"Almost persuaded Christ to receive.\",\"Seems now some soul to say,\",\"“Go, Spirit, go thy way,\",\"Some more convenient day\",\"On thee I’ll call.”\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0228', 'verse', 2, 1, '[\"Almost persuaded, come, come today;\",\"Almost persuaded, turn not away.\",\"Jesus invites you here,\",\"Angels are lingering near,\",\"Prayers rise from hearts so dear;\",\"O wanderer, come!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0228', 'verse', 3, 2, '[\"Almost persuaded, harvest is past;\",\"Almost persuaded, doom comes at last!\",\"“Almost” cannot avail;\",\"“Almost” is but to fail!\",\"Sad, sad that bitter wail,\",\"“Almost—but lost!”\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0229', 229, 'Lord, We Come With Hearts Aflame', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Lord, we come with hearts aflame,
Seeking service in thy name;
All our youth and strength are thine,
Given to help thy work divine;
All our love and faith we bring,
They are thine, O heavenly King.
Lord of hosts, we ask thine aid,
Keep us ever unafraid;
Hold us loyal, hold us true
To the task we have to do;
Lead us on to victory,
We shall triumph praising thee.
Lord of all, we take our stand,
Giving help at thy command;
Eager, joyful, blithe, and strong,
Thrilled with love and filled with song;
Lord, we come with hearts aflame,
Seeking service in thy name.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0229', 'verse', 1, 0, '[\"Lord, we come with hearts aflame,\",\"Seeking service in thy name;\",\"All our youth and strength are thine,\",\"Given to help thy work divine;\",\"All our love and faith we bring,\",\"They are thine, O heavenly King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0229', 'verse', 2, 1, '[\"Lord of hosts, we ask thine aid,\",\"Keep us ever unafraid;\",\"Hold us loyal, hold us true\",\"To the task we have to do;\",\"Lead us on to victory,\",\"We shall triumph praising thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0229', 'verse', 3, 2, '[\"Lord of all, we take our stand,\",\"Giving help at thy command;\",\"Eager, joyful, blithe, and strong,\",\"Thrilled with love and filled with song;\",\"Lord, we come with hearts aflame,\",\"Seeking service in thy name.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0230', 230, 'I Gave My Life for Thee', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'I gave my life for thee,
My precious blood I shed,
That thou might\'st ransom be,
And quickened from the dead;
I gave, I gave my life for thee,
What hast thou given for me?
I gave, I gave my life for thee,
What hast thou given for me?
My Fathers house of light,
My glory circled throne,
I left for earthly night,
For wanderings sad and lone;
I left, I left it all for thee,
Hast thou left aught for me?
I left, I left it all for thee,
Hast thou left aught for me?
I suffered much for thee,
More than thy tongue can tell,
Of bitterest agony,
To rescue thee from hell;
I\'ve borne, I\'ve borne it all for thee,
What hast thou borne for me?
I\'ve borne, I\'ve borne it all for thee,
What hast thou borne for me?');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0230', 'verse', 1, 0, '[\"I gave my life for thee,\",\"My precious blood I shed,\",\"That thou might\'st ransom be,\",\"And quickened from the dead;\",\"I gave, I gave my life for thee,\",\"What hast thou given for me?\",\"I gave, I gave my life for thee,\",\"What hast thou given for me?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0230', 'verse', 2, 1, '[\"My Fathers house of light,\",\"My glory circled throne,\",\"I left for earthly night,\",\"For wanderings sad and lone;\",\"I left, I left it all for thee,\",\"Hast thou left aught for me?\",\"I left, I left it all for thee,\",\"Hast thou left aught for me?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0230', 'verse', 3, 2, '[\"I suffered much for thee,\",\"More than thy tongue can tell,\",\"Of bitterest agony,\",\"To rescue thee from hell;\",\"I\'ve borne, I\'ve borne it all for thee,\",\"What hast thou borne for me?\",\"I\'ve borne, I\'ve borne it all for thee,\",\"What hast thou borne for me?\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0231', 231, 'O Jesus, Thou Art Standing', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'O Jesus, thou art standing,
Outside the fast-closed door,
In lowly patience waiting
To pass the threshold o\'er:
Shame on us, Christian brethren,
His Name and sign who bear,
O shame, thrice shame upon us,
To keep him standing there!
O Jesus, thou art knocking;
And lo, that hand is scarred,
And thorns thy brow encircle,
And tears thy face have marred.
O love that passeth knowledge,
So patiently to wait!
O sin that hath no equal,
So fast to bar the gate!
O Jesus, thou art pleading
In accents meek and low,
\"I died for you, my children,
And will you treat me so?\"
O Lord, with shame and sorrow
We open now the door;
Dear Saviour, enter, enter,
And leave us never more.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0231', 'verse', 1, 0, '[\"O Jesus, thou art standing,\",\"Outside the fast-closed door,\",\"In lowly patience waiting\",\"To pass the threshold o\'er:\",\"Shame on us, Christian brethren,\",\"His Name and sign who bear,\",\"O shame, thrice shame upon us,\",\"To keep him standing there!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0231', 'verse', 2, 1, '[\"O Jesus, thou art knocking;\",\"And lo, that hand is scarred,\",\"And thorns thy brow encircle,\",\"And tears thy face have marred.\",\"O love that passeth knowledge,\",\"So patiently to wait!\",\"O sin that hath no equal,\",\"So fast to bar the gate!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0231', 'verse', 3, 2, '[\"O Jesus, thou art pleading\",\"In accents meek and low,\",\"\\\"I died for you, my children,\",\"And will you treat me so?\\\"\",\"O Lord, with shame and sorrow\",\"We open now the door;\",\"Dear Saviour, enter, enter,\",\"And leave us never more.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0232', 232, 'Flee as a Bird', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Flee as a bird to your mountain,
Thou who art weary of sin;
Go to the clear flowing Fountain,
Where you may wash and be clean;
Fly, for th\'avenger is near thee,
Call, and the Saviour will hear thee,
He on his bosom will bear thee;
O thou who art weary of sin,
O thou who art weary of sin.
He will protect thee forever,
Wipe every falling tear;
He will forsake thee, oh, never,
Sheltered so tenderly there!
Haste, then, the daylight is flying,
Spend not the moments in sighing,
Cease from your sorrow and crying,
The Saviour will wipe every tear,
Yes, Jesus will wipe every tear.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0232', 'verse', 1, 0, '[\"Flee as a bird to your mountain,\",\"Thou who art weary of sin;\",\"Go to the clear flowing Fountain,\",\"Where you may wash and be clean;\",\"Fly, for th\'avenger is near thee,\",\"Call, and the Saviour will hear thee,\",\"He on his bosom will bear thee;\",\"O thou who art weary of sin,\",\"O thou who art weary of sin.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0232', 'verse', 2, 1, '[\"He will protect thee forever,\",\"Wipe every falling tear;\",\"He will forsake thee, oh, never,\",\"Sheltered so tenderly there!\",\"Haste, then, the daylight is flying,\",\"Spend not the moments in sighing,\",\"Cease from your sorrow and crying,\",\"The Saviour will wipe every tear,\",\"Yes, Jesus will wipe every tear.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0233', 233, 'Jesus, To Thee I Now Can Fly', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Jesus, to thee I now can fly,
On whom my help is laid;
Oppressed by sins, I lift my eye,
And see the shadows fade.
Believing on my Lord, I find
A sure and present aid;
On thee alone my constant mind
Be every moment stayed.
Whate\'er in me seems wise, or good,
Or strong, I here disclaim;
I wash my garments in the blood
Of the atoning Lamb.
Jesus, my Strength, my Life, my Rest,
On thee will I depend,
Till summoned to the marriage-feast,
When faith in sight shall end.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0233', 'verse', 1, 0, '[\"Jesus, to thee I now can fly,\",\"On whom my help is laid;\",\"Oppressed by sins, I lift my eye,\",\"And see the shadows fade.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0233', 'verse', 2, 1, '[\"Believing on my Lord, I find\",\"A sure and present aid;\",\"On thee alone my constant mind\",\"Be every moment stayed.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0233', 'verse', 3, 2, '[\"Whate\'er in me seems wise, or good,\",\"Or strong, I here disclaim;\",\"I wash my garments in the blood\",\"Of the atoning Lamb.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0233', 'verse', 4, 3, '[\"Jesus, my Strength, my Life, my Rest,\",\"On thee will I depend,\",\"Till summoned to the marriage-feast,\",\"When faith in sight shall end.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0234', 234, 'Depth of Mercy!', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Depth of mercy! — can there be
Mercy still reserved for me?
Can my God his wrath forbear?
Me, the chief of sinners, spare?
I have long withstood his grace,
Long provoked him to his face,
Would not hearken to his calls,
Grieved him by a thousand falls.
Now incline me to repent;
Let me now my sins lament;
Now my foul revolt deplore,
Weep, believe, and sin no more.
There for me the Saviour stands,
Shows his wounds and spreads his hands;
God is love! I know, I feel;
Jesus weeps, and loves me still.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0234', 'verse', 1, 0, '[\"Depth of mercy! — can there be\",\"Mercy still reserved for me?\",\"Can my God his wrath forbear?\",\"Me, the chief of sinners, spare?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0234', 'verse', 2, 1, '[\"I have long withstood his grace,\",\"Long provoked him to his face,\",\"Would not hearken to his calls,\",\"Grieved him by a thousand falls.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0234', 'verse', 3, 2, '[\"Now incline me to repent;\",\"Let me now my sins lament;\",\"Now my foul revolt deplore,\",\"Weep, believe, and sin no more.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0234', 'verse', 4, 3, '[\"There for me the Saviour stands,\",\"Shows his wounds and spreads his hands;\",\"God is love! I know, I feel;\",\"Jesus weeps, and loves me still.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0235', 235, 'We Stand In Deep Repentance', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'We stand in deep repentance,
Before thy throne of love;
O God of grace, forgive us,
The stain of guilt remove.
Behold us while with weeping
We lift our eyes to thee;
And, all our sins subduing,
Our Father, set us free!
O, shouldst thou from the fallen
Withhold thy grace to guide,
Forever we should wander,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0235', 'verse', 1, 0, '[\"We stand in deep repentance,\",\"Before thy throne of love;\",\"O God of grace, forgive us,\",\"The stain of guilt remove.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0235', 'verse', 2, 1, '[\"Behold us while with weeping\",\"We lift our eyes to thee;\",\"And, all our sins subduing,\",\"Our Father, set us free!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0235', 'verse', 3, 2, '[\"O, shouldst thou from the fallen\",\"Withhold thy grace to guide,\",\"Forever we should wander,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0236', 236, 'Lord! at Thy Feet', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Lord! at thy feet we humbly lie,
And knock at mercy\'s door;
With heavy heart and downcast eye
Thy favor we implore.
\'Tis mercy, we implore;
We would thy pity move;
Thy grace is an exhaustless store,
And thou thyself art love.
O, for thine own, for Jesus\' sake,
Our numerous sins forgive!
Thy grace our stony hearts can break;
Heal us, and bid us live.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0236', 'verse', 1, 0, '[\"Lord! at thy feet we humbly lie,\",\"And knock at mercy\'s door;\",\"With heavy heart and downcast eye\",\"Thy favor we implore.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0236', 'verse', 2, 1, '[\"\'Tis mercy, we implore;\",\"We would thy pity move;\",\"Thy grace is an exhaustless store,\",\"And thou thyself art love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0236', 'verse', 3, 2, '[\"O, for thine own, for Jesus\' sake,\",\"Our numerous sins forgive!\",\"Thy grace our stony hearts can break;\",\"Heal us, and bid us live.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0237', 237, 'Jesus, Full of All Compassion', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Jesus, full of all compassion,
Hear thy humble suppliant’s cry;
Let me know thy great salvation;
See, I languish, faint and die.
Guilty, but with heart relenting,
Overwhelmed with helpless grief,
Prostrate at Thy feet repining,
Send, O send me quick relief.
Whither should my soul be flying,
But to him who comfort gives?
Whither, from the dread of dying,
But to him who ever lives?
While I view thee, wounded, grieving,
Breathless, on the cursed tree,
Fain I’d feel my heart believing
Thou didst suffer thus for me.
With thy righteousness and Spirit,
I am more than angels blessed;
Heir with thee, all things inherit —
Peace, and joy, and endless rest.
Saved! the deed shall spread new glory
Through the shining realms above;
Angels sing the pleasing story,
All enraptured with thy love.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0237', 'verse', 1, 0, '[\"Jesus, full of all compassion,\",\"Hear thy humble suppliant’s cry;\",\"Let me know thy great salvation;\",\"See, I languish, faint and die.\",\"Guilty, but with heart relenting,\",\"Overwhelmed with helpless grief,\",\"Prostrate at Thy feet repining,\",\"Send, O send me quick relief.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0237', 'verse', 2, 1, '[\"Whither should my soul be flying,\",\"But to him who comfort gives?\",\"Whither, from the dread of dying,\",\"But to him who ever lives?\",\"While I view thee, wounded, grieving,\",\"Breathless, on the cursed tree,\",\"Fain I’d feel my heart believing\",\"Thou didst suffer thus for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0237', 'verse', 3, 2, '[\"With thy righteousness and Spirit,\",\"I am more than angels blessed;\",\"Heir with thee, all things inherit —\",\"Peace, and joy, and endless rest.\",\"Saved! the deed shall spread new glory\",\"Through the shining realms above;\",\"Angels sing the pleasing story,\",\"All enraptured with thy love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0238', 238, 'Chief of Sinners', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Chief of sinners though I be,
Jesus shed his blood for me;
Died that I might live on high,
Died that I might never die;
As the brance is to the vine,
I am his, and he is mine.
O the height of Jesus\' love!
Higher than the heaven above,
Deeper than the deepest sea,
Lasting as eternity;
Love that found me - wondrous thought!
Found me when I sought him not!
Chief of sinners though I be,
Christ is all in all to me;
All my wants to him are known,
All my sorrows are his own;
Safe with Him from earthly strife,
He sustains the hidden life.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0238', 'verse', 1, 0, '[\"Chief of sinners though I be,\",\"Jesus shed his blood for me;\",\"Died that I might live on high,\",\"Died that I might never die;\",\"As the brance is to the vine,\",\"I am his, and he is mine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0238', 'verse', 2, 1, '[\"O the height of Jesus\' love!\",\"Higher than the heaven above,\",\"Deeper than the deepest sea,\",\"Lasting as eternity;\",\"Love that found me - wondrous thought!\",\"Found me when I sought him not!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0238', 'verse', 3, 2, '[\"Chief of sinners though I be,\",\"Christ is all in all to me;\",\"All my wants to him are known,\",\"All my sorrows are his own;\",\"Safe with Him from earthly strife,\",\"He sustains the hidden life.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0239', 239, 'Low at Thy Pierced Feet', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Low at thy pierced feet,
Saviour of all,
Helpless and sorrowful
Prostrate I fall.
O cast me not away,
Forgive my sin this day,
Forgive my sin,
All, all my sin.
Sinful my life hath been,
Unclean, unclean;
All my iniquity
Thine eye hath seen;
Cleanse thou my soul today,
Wash all my sin away
In thine own blood,
In thine own blood.
By all thy grief and pain,
Forgive me now;
Before thy cross in shame
Lowly I bow.
Lord, let that blood of thine
Wash now this soul of mine;
Wash now this soul,
Wash now this soul.
Thou didst for me endure
Dread Calvary;
Sin\'s punishment and shame
All, all for me.
On thee my guilt was laid,
By thee my dept was paid,
To set me free,
To set me free.
Lord, I accept thee now,
Accept thou me;
I have delayed too long,
And grieved thee.
By all thy love to me,
I give myself to thee;
Make me thine own,
All, all thine own.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0239', 'verse', 1, 0, '[\"Low at thy pierced feet,\",\"Saviour of all,\",\"Helpless and sorrowful\",\"Prostrate I fall.\",\"O cast me not away,\",\"Forgive my sin this day,\",\"Forgive my sin,\",\"All, all my sin.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0239', 'verse', 2, 1, '[\"Sinful my life hath been,\",\"Unclean, unclean;\",\"All my iniquity\",\"Thine eye hath seen;\",\"Cleanse thou my soul today,\",\"Wash all my sin away\",\"In thine own blood,\",\"In thine own blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0239', 'verse', 3, 2, '[\"By all thy grief and pain,\",\"Forgive me now;\",\"Before thy cross in shame\",\"Lowly I bow.\",\"Lord, let that blood of thine\",\"Wash now this soul of mine;\",\"Wash now this soul,\",\"Wash now this soul.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0239', 'verse', 4, 3, '[\"Thou didst for me endure\",\"Dread Calvary;\",\"Sin\'s punishment and shame\",\"All, all for me.\",\"On thee my guilt was laid,\",\"By thee my dept was paid,\",\"To set me free,\",\"To set me free.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0239', 'verse', 5, 4, '[\"Lord, I accept thee now,\",\"Accept thou me;\",\"I have delayed too long,\",\"And grieved thee.\",\"By all thy love to me,\",\"I give myself to thee;\",\"Make me thine own,\",\"All, all thine own.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0240', 240, 'Show Pity, Lord', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Show pity, Lord; O Lord, forgive!
Let a repenting sinner live;
Are not thy mercies large and free?
May not the guilty trust in thee?
My crimes, though great, do not surpass
The power and glory of thy grace;
O, wash my soul from every sin,
And make my guilty conscience clean!
My lips with shame my sins confess,
Against thy law, against thy grace;
Lord, should thy judgment be severe,
I am condemned, but thou art clear.
Yet save a trembling sinner, Lord,
Whose hope, still hovering\'round thy Word,
Would light on some sweet promise there,
Some sure support against despair.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0240', 'verse', 1, 0, '[\"Show pity, Lord; O Lord, forgive!\",\"Let a repenting sinner live;\",\"Are not thy mercies large and free?\",\"May not the guilty trust in thee?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0240', 'verse', 2, 1, '[\"My crimes, though great, do not surpass\",\"The power and glory of thy grace;\",\"O, wash my soul from every sin,\",\"And make my guilty conscience clean!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0240', 'verse', 3, 2, '[\"My lips with shame my sins confess,\",\"Against thy law, against thy grace;\",\"Lord, should thy judgment be severe,\",\"I am condemned, but thou art clear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0240', 'verse', 4, 3, '[\"Yet save a trembling sinner, Lord,\",\"Whose hope, still hovering\'round thy Word,\",\"Would light on some sweet promise there,\",\"Some sure support against despair.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0241', 241, 'From Every Stormy Wind', 'CH', 'en', '', '', 0, 0, 0, 0, 0, '');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0242', 242, '\'Tis by the Faith of Joys', 'CH', 'en', '', '', 0, 0, 0, 0, 0, '’Tis by the faith of joys to come
We walk through deserts dark as night;
Till we arrive at Heaven our home,
Truth is our guide, and faith our light.
The want of sight she well supplies,
She makes the pearly gates appear;
Far into distant worlds she pries,
And brings eternal glories near.
Though lions roar, and tempests blow,
And rocks and dangers fill the way,
With joy we tread the desert through,
While faith inspires a heavenly ray.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0242', 'verse', 1, 0, '[\"’Tis by the faith of joys to come\",\"We walk through deserts dark as night;\",\"Till we arrive at Heaven our home,\",\"Truth is our guide, and faith our light.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0242', 'verse', 2, 1, '[\"The want of sight she well supplies,\",\"She makes the pearly gates appear;\",\"Far into distant worlds she pries,\",\"And brings eternal glories near.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0242', 'verse', 3, 2, '[\"Though lions roar, and tempests blow,\",\"And rocks and dangers fill the way,\",\"With joy we tread the desert through,\",\"While faith inspires a heavenly ray.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0243', 243, 'Come, O Thou Traveler', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Come, O thou Traveler unknown,
Whom still I hold but cannot see;
My company before is gone,
And I am left alone with thee;
With thee all night I mean to stay,
And wrestle till the break of day.
I need not tell thee who I am,
My sin and misery declare;
Thyself hast called me by my name,
Look on thy hands, and read it there;
But who, I ask thee, who art thou?
Tell me thy name, and tell me now.
In vain thou strugglest to get free;
I never will unloose my hold;
Art thou the Man that died for me?
The secret of thy love unfold;
Clinging, I will not let thee go,
Till I thy name, thy nature know.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0243', 'verse', 1, 0, '[\"Come, O thou Traveler unknown,\",\"Whom still I hold but cannot see;\",\"My company before is gone,\",\"And I am left alone with thee;\",\"With thee all night I mean to stay,\",\"And wrestle till the break of day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0243', 'verse', 2, 1, '[\"I need not tell thee who I am,\",\"My sin and misery declare;\",\"Thyself hast called me by my name,\",\"Look on thy hands, and read it there;\",\"But who, I ask thee, who art thou?\",\"Tell me thy name, and tell me now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0243', 'verse', 3, 2, '[\"In vain thou strugglest to get free;\",\"I never will unloose my hold;\",\"Art thou the Man that died for me?\",\"The secret of thy love unfold;\",\"Clinging, I will not let thee go,\",\"Till I thy name, thy nature know.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0244', 244, 'O Could Our Thoughts', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'O could our thoughts and wishes fly,
Above these gloomy shades,
To those bright worlds beyond the sky,
Where sorrow ne\'er invades!
There, joys unseen by mortal eyes,
Or reason\'s feeble ray,
In ever-blooming prospect rise,
Exposed to no decay.
Lord, send a beam of light divine,
To guide our upward aim;
With one reviving look of Thine,
Our languid hearts inflame.
O then, on faith\'s sublimest wing,
Our ardent souls shall rise
To those bright scenes where pleasures spring
Immortal in the skies.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0244', 'verse', 1, 0, '[\"O could our thoughts and wishes fly,\",\"Above these gloomy shades,\",\"To those bright worlds beyond the sky,\",\"Where sorrow ne\'er invades!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0244', 'verse', 2, 1, '[\"There, joys unseen by mortal eyes,\",\"Or reason\'s feeble ray,\",\"In ever-blooming prospect rise,\",\"Exposed to no decay.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0244', 'verse', 3, 2, '[\"Lord, send a beam of light divine,\",\"To guide our upward aim;\",\"With one reviving look of Thine,\",\"Our languid hearts inflame.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0244', 'verse', 4, 3, '[\"O then, on faith\'s sublimest wing,\",\"Our ardent souls shall rise\",\"To those bright scenes where pleasures spring\",\"Immortal in the skies.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0245', 245, 'O For a Faith', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'O for a faith that will not shrink,
Though pressed by many a foe;
That will not tremble on the brink of poverty,
Of poverty or woe;
Of poverty or woe;
That will not murmur or complain
Beneath the chastening rod,
But in the hour of grief or pain,
of grief or pain
Can lean upon its God;
Can lean upon its God.
A faith that shines more bright and clear
When tempests rage without;
That when in danger knows no fear,
knows of no fear,
In darkness feels no doubt;
In darkness feels no doubt.
That bears unmoved the world’s dread frown,
Nor heeds its scornful smile;
That sin’s wild ocean cannot drown,
no, cannot drown,
Nor its soft arts beguile;
Nor its soft arts beguile.
Lord, give me such a faith as this,
And then, whate’er may come
I’ll taste, e’en here the hallowed bliss,
the hallowed bliss
Of an eternal home;
Of an eternal home.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0245', 'verse', 1, 0, '[\"O for a faith that will not shrink,\",\"Though pressed by many a foe;\",\"That will not tremble on the brink of poverty,\",\"Of poverty or woe;\",\"Of poverty or woe;\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0245', 'verse', 2, 1, '[\"That will not murmur or complain\",\"Beneath the chastening rod,\",\"But in the hour of grief or pain,\",\"of grief or pain\",\"Can lean upon its God;\",\"Can lean upon its God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0245', 'verse', 3, 2, '[\"A faith that shines more bright and clear\",\"When tempests rage without;\",\"That when in danger knows no fear,\",\"knows of no fear,\",\"In darkness feels no doubt;\",\"In darkness feels no doubt.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0245', 'verse', 4, 3, '[\"That bears unmoved the world’s dread frown,\",\"Nor heeds its scornful smile;\",\"That sin’s wild ocean cannot drown,\",\"no, cannot drown,\",\"Nor its soft arts beguile;\",\"Nor its soft arts beguile.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0245', 'verse', 5, 4, '[\"Lord, give me such a faith as this,\",\"And then, whate’er may come\",\"I’ll taste, e’en here the hallowed bliss,\",\"the hallowed bliss\",\"Of an eternal home;\",\"Of an eternal home.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0246', 246, 'My Faith Looks Up to Thee', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'My faith looks up to thee,
Thou Lamb of Calvary,
Saviour divine;
Now hear me while I pray,
Take all my guilt away,
O let me from this day
Be wholly thine.
May thy rich grace impart
Strength to my fainting heart,
My zeal inspire;
As thou hast died for me,
O may my love to thee
Pure, warm, and changeless be,
A living fire!
While life\'s dark maze I tread,
And griefs around me spread,
Be thou my guide;
Bid darkness turn to day,
Wipe sorrow\'s tears away,
Nor let me ever stray');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0246', 'verse', 1, 0, '[\"My faith looks up to thee,\",\"Thou Lamb of Calvary,\",\"Saviour divine;\",\"Now hear me while I pray,\",\"Take all my guilt away,\",\"O let me from this day\",\"Be wholly thine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0246', 'verse', 2, 1, '[\"May thy rich grace impart\",\"Strength to my fainting heart,\",\"My zeal inspire;\",\"As thou hast died for me,\",\"O may my love to thee\",\"Pure, warm, and changeless be,\",\"A living fire!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0246', 'verse', 3, 2, '[\"While life\'s dark maze I tread,\",\"And griefs around me spread,\",\"Be thou my guide;\",\"Bid darkness turn to day,\",\"Wipe sorrow\'s tears away,\",\"Nor let me ever stray\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0247', 247, 'Toil On a Little Longer', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Toil on a little longer here,
For thy reward awaits above,
Nor droop in sadness or in fear
Beneath the rod that\'s sent in love;
The deeper wound our spirits feel,
The sweeter heaven\'s balm to heal.
Faith lifts the veil before our eyes,
And bids us view a happier clime,
Where verdant fields in beauty rise,
Beyond the withering blasts of time;
And brings the blissful moment near,
When we in glory shall appear.
What glory then shall fill the soul,
When parted friends again shall meet,
Beyond the reach of death\'s control,
And cast their crowns at Jesus\' feet;
His matchless love and grace adore,
And never taste of sorrow more.
Then let us hope; \'tis not in vain;
Though moistened by our grief the soil,
The harvest brings us joy for pain,
The rest repays the weary toil;
For they shall reap who sow in tears,
Rich gladness through eternal years.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0247', 'verse', 1, 0, '[\"Toil on a little longer here,\",\"For thy reward awaits above,\",\"Nor droop in sadness or in fear\",\"Beneath the rod that\'s sent in love;\",\"The deeper wound our spirits feel,\",\"The sweeter heaven\'s balm to heal.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0247', 'verse', 2, 1, '[\"Faith lifts the veil before our eyes,\",\"And bids us view a happier clime,\",\"Where verdant fields in beauty rise,\",\"Beyond the withering blasts of time;\",\"And brings the blissful moment near,\",\"When we in glory shall appear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0247', 'verse', 3, 2, '[\"What glory then shall fill the soul,\",\"When parted friends again shall meet,\",\"Beyond the reach of death\'s control,\",\"And cast their crowns at Jesus\' feet;\",\"His matchless love and grace adore,\",\"And never taste of sorrow more.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0247', 'verse', 4, 3, '[\"Then let us hope; \'tis not in vain;\",\"Though moistened by our grief the soil,\",\"The harvest brings us joy for pain,\",\"The rest repays the weary toil;\",\"For they shall reap who sow in tears,\",\"Rich gladness through eternal years.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0248', 248, '\'Tis My Happiness Below', 'CH', 'en', '', '', 0, 0, 0, 0, 0, '’Tis my happiness below
Not to live without the cross;
But the Saviour’s power to know,
Sanctifying every loss.
Trials must and will befall;
But with humble faith to see
Love inscribed upon them all —
This is happiness to me.
Did I meet no trials here,
No chastisement by the way,
Might I not with reason fear
I should prove a castaway?
Trials make the promise sweet;
Trials give new life to prayer;
Trials bring me to his feet,
Lay me low, and keep me there.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0248', 'verse', 1, 0, '[\"’Tis my happiness below\",\"Not to live without the cross;\",\"But the Saviour’s power to know,\",\"Sanctifying every loss.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0248', 'verse', 2, 1, '[\"Trials must and will befall;\",\"But with humble faith to see\",\"Love inscribed upon them all —\",\"This is happiness to me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0248', 'verse', 3, 2, '[\"Did I meet no trials here,\",\"No chastisement by the way,\",\"Might I not with reason fear\",\"I should prove a castaway?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0248', 'verse', 4, 3, '[\"Trials make the promise sweet;\",\"Trials give new life to prayer;\",\"Trials bring me to his feet,\",\"Lay me low, and keep me there.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0249', 249, 'If Through Unruffled Seas', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'If through unruffled seas
Calmly toward heaven we sail,
With grateful hearts, O God, to thee,
We\'ll own the favoring gale,
With grateful hearts, O God, to thee,
We\'ll own the favoring gale.
But should the surges rise,
And rest delay to come,
Blest be the sorrow, kind the storm,
Which drives us nearer home.
Blest be the sorrow, kind the storm,
Which drives us nearer home.
Soon shall our doubts and fears
All yield to thy control;
Thy tender mercies shall illume
The midnight of the soul,
Thy tender mercies shall illume
The midnight of the soul.
Teach us in every state,
To make thy will our own,
And when the joys of sense depart,
To live by faith alone,
And when the joys of sense depart,
To live by faith alone.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0249', 'verse', 1, 0, '[\"If through unruffled seas\",\"Calmly toward heaven we sail,\",\"With grateful hearts, O God, to thee,\",\"We\'ll own the favoring gale,\",\"With grateful hearts, O God, to thee,\",\"We\'ll own the favoring gale.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0249', 'verse', 2, 1, '[\"But should the surges rise,\",\"And rest delay to come,\",\"Blest be the sorrow, kind the storm,\",\"Which drives us nearer home.\",\"Blest be the sorrow, kind the storm,\",\"Which drives us nearer home.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0249', 'verse', 3, 2, '[\"Soon shall our doubts and fears\",\"All yield to thy control;\",\"Thy tender mercies shall illume\",\"The midnight of the soul,\",\"Thy tender mercies shall illume\",\"The midnight of the soul.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0249', 'verse', 4, 3, '[\"Teach us in every state,\",\"To make thy will our own,\",\"And when the joys of sense depart,\",\"To live by faith alone,\",\"And when the joys of sense depart,\",\"To live by faith alone.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0250', 250, 'When, My Saviour, Shall I Be', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'When, my Saviour, shall I be
Perfectly resigned to Thee?
Poor and vile in my own eyes,
Only in thy wisdom wise.
Only thee content to know,
Ignorant of all below;
Only guided by thy light,
Only mighty in thy might?
Fully in my life express
All the heights of holiness;
Sweetly let my spirit prove
All the depths of humble love.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0250', 'verse', 1, 0, '[\"When, my Saviour, shall I be\",\"Perfectly resigned to Thee?\",\"Poor and vile in my own eyes,\",\"Only in thy wisdom wise.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0250', 'verse', 2, 1, '[\"Only thee content to know,\",\"Ignorant of all below;\",\"Only guided by thy light,\",\"Only mighty in thy might?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0250', 'verse', 3, 2, '[\"Fully in my life express\",\"All the heights of holiness;\",\"Sweetly let my spirit prove\",\"All the depths of humble love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0251', 251, 'I Ask Not, Lord, for Less', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'I ask not, Lord, for less to bear
Here in the narrow way,
But that I may thy blessing share
In all I do or say,
In all I do or say.
Through whatsoe\'er my path shall lie,
With patience may I run;
With filial trust my heart reply,
\"Thy will, O God, be done.
Thy will, O God, be done.\"
With Thee to lead, I will not fear
In scenes with dangers rife,
While still thy cheering voice I hear,
\"I am the way, the life,
I am the way, the life\".
Thou art the refuge of my soul,
My hope when comforts flee,
My strength while life\'s rough billows roll,
My joy eternally,
My joy eternally.
Then help me to improve with care,
These precious moments given;
For they a faithful record bear,
Of good or ill, to heaven,
Of good or ill, to heaven.
And in Thine arms of love enfold
Me from the tempter\'s snare;
And in the book of life enrolled,
Be my name written there,
Be my name written there.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0251', 'verse', 1, 0, '[\"I ask not, Lord, for less to bear\",\"Here in the narrow way,\",\"But that I may thy blessing share\",\"In all I do or say,\",\"In all I do or say.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0251', 'verse', 2, 1, '[\"Through whatsoe\'er my path shall lie,\",\"With patience may I run;\",\"With filial trust my heart reply,\",\"\\\"Thy will, O God, be done.\",\"Thy will, O God, be done.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0251', 'verse', 3, 2, '[\"With Thee to lead, I will not fear\",\"In scenes with dangers rife,\",\"While still thy cheering voice I hear,\",\"\\\"I am the way, the life,\",\"I am the way, the life\\\".\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0251', 'verse', 4, 3, '[\"Thou art the refuge of my soul,\",\"My hope when comforts flee,\",\"My strength while life\'s rough billows roll,\",\"My joy eternally,\",\"My joy eternally.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0251', 'verse', 5, 4, '[\"Then help me to improve with care,\",\"These precious moments given;\",\"For they a faithful record bear,\",\"Of good or ill, to heaven,\",\"Of good or ill, to heaven.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0251', 'verse', 6, 5, '[\"And in Thine arms of love enfold\",\"Me from the tempter\'s snare;\",\"And in the book of life enrolled,\",\"Be my name written there,\",\"Be my name written there.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0252', 252, 'My Spirit on Thy Care', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'My spirit on thy care,
Blest Saviour, I recline;
Thou wilt not leave me to despair,
For Thou art love divine.
In thee I place my trust,
On thee I calmly rest;
I know thee good, I know thee just,
And count thy choice the best.
Whate\'er events betide,
Thy will they all perform;
Safe in Thy breast my head I hide,
Nor fear the coming storm.
Let good or ill befall,
It must be good for me,
Secure of having Thee in all,
Of having all in Thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0252', 'verse', 1, 0, '[\"My spirit on thy care,\",\"Blest Saviour, I recline;\",\"Thou wilt not leave me to despair,\",\"For Thou art love divine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0252', 'verse', 2, 1, '[\"In thee I place my trust,\",\"On thee I calmly rest;\",\"I know thee good, I know thee just,\",\"And count thy choice the best.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0252', 'verse', 3, 2, '[\"Whate\'er events betide,\",\"Thy will they all perform;\",\"Safe in Thy breast my head I hide,\",\"Nor fear the coming storm.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0252', 'verse', 4, 3, '[\"Let good or ill befall,\",\"It must be good for me,\",\"Secure of having Thee in all,\",\"Of having all in Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0253', 253, 'The Tempter to My Soul', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'The tempter to my soul hath said,
\"There is no help in God for thee;\"
Lord! lift thou up thy servant\'s head;
My glory, shield, and solace be.
Thus to the Lord I raised my cry;
He heard me from his holy hill;
At his command the waves rolled by;
He beckoned, and the winds were still.
I laid me down and slept, I woke —
Thou, Lord, my spirit didst sustain;
Bright, from the east, the morning broke;
Thy comforts rose on me again.
I will not fear, though armed throngs
Compass my steps in all their wrath;
Salvation to the Lord belongs;
His presence guards His people\'s path.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0253', 'verse', 1, 0, '[\"The tempter to my soul hath said,\",\"\\\"There is no help in God for thee;\\\"\",\"Lord! lift thou up thy servant\'s head;\",\"My glory, shield, and solace be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0253', 'verse', 2, 1, '[\"Thus to the Lord I raised my cry;\",\"He heard me from his holy hill;\",\"At his command the waves rolled by;\",\"He beckoned, and the winds were still.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0253', 'verse', 3, 2, '[\"I laid me down and slept, I woke —\",\"Thou, Lord, my spirit didst sustain;\",\"Bright, from the east, the morning broke;\",\"Thy comforts rose on me again.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0253', 'verse', 4, 3, '[\"I will not fear, though armed throngs\",\"Compass my steps in all their wrath;\",\"Salvation to the Lord belongs;\",\"His presence guards His people\'s path.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0254', 254, 'Sometimes a Light Surprises', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Sometimes a light surprises
The Christian while he sings;
It is the Lord, who rises
With healing in his wings;
When comforts are declining,
He grants the soul again
A season of clear shining,
To cheer it after rain.
In holy contemplation
We sweetly then pursue
The theme of God\'s salvation,
And find it ever new;
Set free from present sorrow,
We cheerfully can say,
Let the unknown tomorrow
Bring with it what it may.
Children of God lack nothing,
His promise bears them through;
Who gives the lilies clothing,
Will clothe his people too;
Beneath the spreading heavens
No creature but is fed,
And he who feeds the ravens
Will give his children bread.
Though vine nor fig tree neither
Their wonted fruit should bear,
Though all the fields should wither,
Nor flocks nor herds be there;
Yet God the same abiding,
His praise shall tune my voice,
For while in Him confiding,
I cannot but rejoice.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0254', 'verse', 1, 0, '[\"Sometimes a light surprises\",\"The Christian while he sings;\",\"It is the Lord, who rises\",\"With healing in his wings;\",\"When comforts are declining,\",\"He grants the soul again\",\"A season of clear shining,\",\"To cheer it after rain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0254', 'verse', 2, 1, '[\"In holy contemplation\",\"We sweetly then pursue\",\"The theme of God\'s salvation,\",\"And find it ever new;\",\"Set free from present sorrow,\",\"We cheerfully can say,\",\"Let the unknown tomorrow\",\"Bring with it what it may.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0254', 'verse', 3, 2, '[\"Children of God lack nothing,\",\"His promise bears them through;\",\"Who gives the lilies clothing,\",\"Will clothe his people too;\",\"Beneath the spreading heavens\",\"No creature but is fed,\",\"And he who feeds the ravens\",\"Will give his children bread.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0254', 'verse', 4, 3, '[\"Though vine nor fig tree neither\",\"Their wonted fruit should bear,\",\"Though all the fields should wither,\",\"Nor flocks nor herds be there;\",\"Yet God the same abiding,\",\"His praise shall tune my voice,\",\"For while in Him confiding,\",\"I cannot but rejoice.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0255', 255, 'How Firm a Foundation', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'How firm a foundation,
ye saints of the Lord,
Is laid for your faith
in his excellent word!
What more can he say
than to you he hath said,
Who unto the Saviour
for refuge have fled?
Who unto the Saviour
for refuge have fled?
Fear not, I am with thee;
O be not dismayed;
For I am thy God,
and will still give thee aid;
I\'ll strengthen thee, help thee,
and cause thee to stand,
Upheld by my righteous,
omnipotent hand,
Upheld by my righteous,
omnipotent hand.
When through deep waters
I call thee to go,
The rivers of sorrow
shall not overflow;
For I will be with thee,
thy troubles to bless,
And sanctify to thee
thy deepest distress,
And sanctify to thee
thy deepest distress.
When through fiery trials
thy pathways shall lie,
My grace, all-sufficient,
shall be thy supply;
The flame shall not hurt thee;
I only design
Thy dross to consume,
and thy gold to refine,
Thy dross to consume,
and thy gold to refine.
The soul that on Jesus
doth lean for respose,
I will not, I will not
depart to his foes;
That soul, though all hell
should endeavor to shake,
I\'ll never, no never,
no never forsake,
I\'ll never, no never,
no never forsake.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0255', 'verse', 1, 0, '[\"How firm a foundation,\",\"ye saints of the Lord,\",\"Is laid for your faith\",\"in his excellent word!\",\"What more can he say\",\"than to you he hath said,\",\"Who unto the Saviour\",\"for refuge have fled?\",\"Who unto the Saviour\",\"for refuge have fled?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0255', 'verse', 2, 1, '[\"Fear not, I am with thee;\",\"O be not dismayed;\",\"For I am thy God,\",\"and will still give thee aid;\",\"I\'ll strengthen thee, help thee,\",\"and cause thee to stand,\",\"Upheld by my righteous,\",\"omnipotent hand,\",\"Upheld by my righteous,\",\"omnipotent hand.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0255', 'verse', 3, 2, '[\"When through deep waters\",\"I call thee to go,\",\"The rivers of sorrow\",\"shall not overflow;\",\"For I will be with thee,\",\"thy troubles to bless,\",\"And sanctify to thee\",\"thy deepest distress,\",\"And sanctify to thee\",\"thy deepest distress.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0255', 'verse', 4, 3, '[\"When through fiery trials\",\"thy pathways shall lie,\",\"My grace, all-sufficient,\",\"shall be thy supply;\",\"The flame shall not hurt thee;\",\"I only design\",\"Thy dross to consume,\",\"and thy gold to refine,\",\"Thy dross to consume,\",\"and thy gold to refine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0255', 'verse', 5, 4, '[\"The soul that on Jesus\",\"doth lean for respose,\",\"I will not, I will not\",\"depart to his foes;\",\"That soul, though all hell\",\"should endeavor to shake,\",\"I\'ll never, no never,\",\"no never forsake,\",\"I\'ll never, no never,\",\"no never forsake.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0256', 256, 'I Am Trusting Thee', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'I am trusting thee, Lord Jesus,
Trusting only thee;
Trusting thee for full salvation,
Great and free.
I am trusting thee for pardon;
At thy feet I bow;
For thy grace and tender mercy,
Trusting now.
I am trusting thee to guide me;
Thou alone shalt lead;
Every day and hour supplying
All my need.
I am trusting thee, Lord Jesus;
Never let me fall;
I am trusting thee forever,
And for all.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0256', 'verse', 1, 0, '[\"I am trusting thee, Lord Jesus,\",\"Trusting only thee;\",\"Trusting thee for full salvation,\",\"Great and free.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0256', 'verse', 2, 1, '[\"I am trusting thee for pardon;\",\"At thy feet I bow;\",\"For thy grace and tender mercy,\",\"Trusting now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0256', 'verse', 3, 2, '[\"I am trusting thee to guide me;\",\"Thou alone shalt lead;\",\"Every day and hour supplying\",\"All my need.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0256', 'verse', 4, 3, '[\"I am trusting thee, Lord Jesus;\",\"Never let me fall;\",\"I am trusting thee forever,\",\"And for all.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0257', 257, 'Call Jehovah Thy Salvation', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Call Jehovah thy salvation,
Rest beneath th\' Almighty\'s shade;
In his secret habitation
Dwell, and never be dismayed.
Since, with pure and firm affection
Thou on God hast set thy love,
With the wings of his protection
He will shield thee from above.
Thou shalt call on him in trouble,
He will hearken, He will save;
For thy grief reward thee double,
Crown with life beyond the grave.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0257', 'verse', 1, 0, '[\"Call Jehovah thy salvation,\",\"Rest beneath th\' Almighty\'s shade;\",\"In his secret habitation\",\"Dwell, and never be dismayed.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0257', 'verse', 2, 1, '[\"Since, with pure and firm affection\",\"Thou on God hast set thy love,\",\"With the wings of his protection\",\"He will shield thee from above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0257', 'verse', 3, 2, '[\"Thou shalt call on him in trouble,\",\"He will hearken, He will save;\",\"For thy grief reward thee double,\",\"Crown with life beyond the grave.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0258', 258, 'I Need Thee Every Hour', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'I need thee every hour,
Most gracious Lord;
No tender voice like thine
Can peace afford.
I need thee,
O I need thee!
Every hour I need thee;
O bless me now, my Savior!
I come to thee.
I need thee every hour;
Stay thou nearby;
Temptations lose their power
When thou art nigh.
I need thee every hour,
In joy or pain;
Come quickly and abide,
Or life is vain.
I need thee every hour;
Teach me thy will;
And thy rich promises
In me fulfill.
I need thee every hour;
Most Holy One;
O make me thine indeed,
Thou blessed Son.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0258', 'verse', 1, 0, '[\"I need thee every hour,\",\"Most gracious Lord;\",\"No tender voice like thine\",\"Can peace afford.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0258', 'chorus', 0, 1, '[\"I need thee,\",\"O I need thee!\",\"Every hour I need thee;\",\"O bless me now, my Savior!\",\"I come to thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0258', 'verse', 2, 2, '[\"I need thee every hour;\",\"Stay thou nearby;\",\"Temptations lose their power\",\"When thou art nigh.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0258', 'verse', 3, 3, '[\"I need thee every hour,\",\"In joy or pain;\",\"Come quickly and abide,\",\"Or life is vain.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0258', 'verse', 4, 4, '[\"I need thee every hour;\",\"Teach me thy will;\",\"And thy rich promises\",\"In me fulfill.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0258', 'verse', 5, 5, '[\"I need thee every hour;\",\"Most Holy One;\",\"O make me thine indeed,\",\"Thou blessed Son.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0259', 259, 'All the Way', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'All the way my Savior leads me;
What have I to ask beside?
Can I doubt his tender mercy,
Who through life has been my guide?
Heavenly peace, divinest comfort,
Here by faith in him to dwell;
For I know whate\'er befall me,
Jesus doeth all things well;
For I know whate\'er befall me,
Jesus doeth all things well.
All the way my Savior leads me;
Cheers each winding path I tread;
Gives me grace for every trial,
Feeds me with the living bread;
Though my weary steps may falter,
And my soul athirst may be,
Gushing from the Rock before me,
Lo, a spring of joy I see;
Gushing from the Rock before me,
Lo, a spring of joy I see.
All the way my Savior leads me;
O the fullness of his love!
Perfect rest to me is promised
In my Father\'s house above;
When I wake to life immortal,
Wing my flight to realms of day,
This my song through endless ages,
Jesus led me all the way;
This my song through endless ages,
Jesus led me all the way.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0259', 'verse', 1, 0, '[\"All the way my Savior leads me;\",\"What have I to ask beside?\",\"Can I doubt his tender mercy,\",\"Who through life has been my guide?\",\"Heavenly peace, divinest comfort,\",\"Here by faith in him to dwell;\",\"For I know whate\'er befall me,\",\"Jesus doeth all things well;\",\"For I know whate\'er befall me,\",\"Jesus doeth all things well.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0259', 'verse', 2, 1, '[\"All the way my Savior leads me;\",\"Cheers each winding path I tread;\",\"Gives me grace for every trial,\",\"Feeds me with the living bread;\",\"Though my weary steps may falter,\",\"And my soul athirst may be,\",\"Gushing from the Rock before me,\",\"Lo, a spring of joy I see;\",\"Gushing from the Rock before me,\",\"Lo, a spring of joy I see.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0259', 'verse', 3, 2, '[\"All the way my Savior leads me;\",\"O the fullness of his love!\",\"Perfect rest to me is promised\",\"In my Father\'s house above;\",\"When I wake to life immortal,\",\"Wing my flight to realms of day,\",\"This my song through endless ages,\",\"Jesus led me all the way;\",\"This my song through endless ages,\",\"Jesus led me all the way.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0260', 260, 'The Lord\'s My Shepherd', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'The Lord’s my Shepherd, I’ll not want;
He makes me down to lie
In pastures green; He leadeth me
The quiet waters by,
The quiet waters by.
My soul He doth restore again;
And me to walk doth make
Within the paths of righteousness,
Even for his own name’s sake,
Even for his own name’s sake.
Yea, though I walk in death’s dark vale,
Yet will I fear none ill;
For thou art with me, and thy rod
And staff my comfort still,
And staff my comfort still.
My table thou hast furnished
In presence of my foes;
My head thou dost with oil anoint,
And my cup overflows,
And my cup overflows.
Goodness and mercy all my life
Shall surely follow me;
And in God’s house forevermore,
My dwelling place shall be,
My dwelling place shall be.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0260', 'verse', 1, 0, '[\"The Lord’s my Shepherd, I’ll not want;\",\"He makes me down to lie\",\"In pastures green; He leadeth me\",\"The quiet waters by,\",\"The quiet waters by.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0260', 'verse', 2, 1, '[\"My soul He doth restore again;\",\"And me to walk doth make\",\"Within the paths of righteousness,\",\"Even for his own name’s sake,\",\"Even for his own name’s sake.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0260', 'verse', 3, 2, '[\"Yea, though I walk in death’s dark vale,\",\"Yet will I fear none ill;\",\"For thou art with me, and thy rod\",\"And staff my comfort still,\",\"And staff my comfort still.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0260', 'verse', 4, 3, '[\"My table thou hast furnished\",\"In presence of my foes;\",\"My head thou dost with oil anoint,\",\"And my cup overflows,\",\"And my cup overflows.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0260', 'verse', 5, 4, '[\"Goodness and mercy all my life\",\"Shall surely follow me;\",\"And in God’s house forevermore,\",\"My dwelling place shall be,\",\"My dwelling place shall be.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0261', 261, 'A Mighty Fortress', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'A mighty fortress is our God,
A bulwark never failing;
Our helper he, amid the flood
Of mortal ills prevaling.
For still our ancient foe
Doth seek to work us woe;
His craft and power are great;
And armed with cruel hate,
On earth is not his equal.
Did we in our own strength confide,
Our striving would be losing,
Were not the right man on our side,
The man of God\'s own choosing.
Dost ask who that may be?
Christ Jesus, it is he;
Lord Sabbaoth, his name,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0261', 'verse', 1, 0, '[\"A mighty fortress is our God,\",\"A bulwark never failing;\",\"Our helper he, amid the flood\",\"Of mortal ills prevaling.\",\"For still our ancient foe\",\"Doth seek to work us woe;\",\"His craft and power are great;\",\"And armed with cruel hate,\",\"On earth is not his equal.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0261', 'verse', 2, 1, '[\"Did we in our own strength confide,\",\"Our striving would be losing,\",\"Were not the right man on our side,\",\"The man of God\'s own choosing.\",\"Dost ask who that may be?\",\"Christ Jesus, it is he;\",\"Lord Sabbaoth, his name,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0262', 262, 'Lord of Our Life', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Lord of our life, and God of our salvation,
Star of our night, and hope of every nation,
Hear and receive thy church’s supplication,
Lord God Almighty.
Lord, thou canst help when earthly armor faileth;
Lord, thou canst save when deadly sin assaileth;
Lord, o’er thy rock nor death nor hell prevaileth;
Grant us thy peace, Lord.
Peace in our hearts our evil thoughts assuaging;
Peace, in thy church, where brothers are engaging;
Peace, when the world its busy war is waging;
Send us, O Saviour.
Grant us thy help till foes are backward driven;
Grant them thy truth that they may be forgiven;
Grant peace on earth, and, after we have striven,
Peace in thy heaven.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0262', 'verse', 1, 0, '[\"Lord of our life, and God of our salvation,\",\"Star of our night, and hope of every nation,\",\"Hear and receive thy church’s supplication,\",\"Lord God Almighty.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0262', 'verse', 2, 1, '[\"Lord, thou canst help when earthly armor faileth;\",\"Lord, thou canst save when deadly sin assaileth;\",\"Lord, o’er thy rock nor death nor hell prevaileth;\",\"Grant us thy peace, Lord.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0262', 'verse', 3, 2, '[\"Peace in our hearts our evil thoughts assuaging;\",\"Peace, in thy church, where brothers are engaging;\",\"Peace, when the world its busy war is waging;\",\"Send us, O Saviour.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0262', 'verse', 4, 3, '[\"Grant us thy help till foes are backward driven;\",\"Grant them thy truth that they may be forgiven;\",\"Grant peace on earth, and, after we have striven,\",\"Peace in thy heaven.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0263', 263, 'Courage, Brother', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Courage brother! do not stumble,
Though thy path be dark as night;
There\'s a star to guide the humble;
Trust in God, and do the right.
Though the road be long and dreary,
And the end be out of sight,
Tread it bravely, strong or weary;
Trust in God, trust in God,
trust in God, and do the right.
Perish policy and cunning,
Perish all that fears the light,
Whether losing, whether winning,
Trust in God, and do the right.
Shun all forms of guilty passion,
Fiends can look like angels bright;
Heed no custom, school, nor fashion;
Trust in God, trust in God,
trust in God, and do the right.
Some will hate thee, some will love thee,
Some will flatter, some will slight;
Cease from man, and look above thee;
Trust in God, and do the right.
Simple rule and safest guiding,
Inward peace and shining light,
Star upon our path abiding;
Trust in God, trust in God,
trust in God, and do the right.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0263', 'verse', 1, 0, '[\"Courage brother! do not stumble,\",\"Though thy path be dark as night;\",\"There\'s a star to guide the humble;\",\"Trust in God, and do the right.\",\"Though the road be long and dreary,\",\"And the end be out of sight,\",\"Tread it bravely, strong or weary;\",\"Trust in God, trust in God,\",\"trust in God, and do the right.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0263', 'verse', 2, 1, '[\"Perish policy and cunning,\",\"Perish all that fears the light,\",\"Whether losing, whether winning,\",\"Trust in God, and do the right.\",\"Shun all forms of guilty passion,\",\"Fiends can look like angels bright;\",\"Heed no custom, school, nor fashion;\",\"Trust in God, trust in God,\",\"trust in God, and do the right.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0263', 'verse', 3, 2, '[\"Some will hate thee, some will love thee,\",\"Some will flatter, some will slight;\",\"Cease from man, and look above thee;\",\"Trust in God, and do the right.\",\"Simple rule and safest guiding,\",\"Inward peace and shining light,\",\"Star upon our path abiding;\",\"Trust in God, trust in God,\",\"trust in God, and do the right.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0264', 264, 'To Thee, O Dear Saviour', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'To thee, O dear, dear Saviour,
My spirit turns for rest;
My peace is in thy favor,
My pillow on thy breast;
Though all the world deceive me,
I know that I am thine,
And thou wilt never leave me,
O blessed Saviour mine.
In thee my trust abideth,
On thee my hope relies,
O thou whose love provideth
For all beneath the skies;
O thou whose mercy found me,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0264', 'verse', 1, 0, '[\"To thee, O dear, dear Saviour,\",\"My spirit turns for rest;\",\"My peace is in thy favor,\",\"My pillow on thy breast;\",\"Though all the world deceive me,\",\"I know that I am thine,\",\"And thou wilt never leave me,\",\"O blessed Saviour mine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0264', 'verse', 2, 1, '[\"In thee my trust abideth,\",\"On thee my hope relies,\",\"O thou whose love provideth\",\"For all beneath the skies;\",\"O thou whose mercy found me,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0265', 265, 'My Life Flows On', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'My life flows on in endless song;
Amid earth\'s lamentation,
I hear the sweet, though far-off hymn
That hails a new creation;
Through all the tumult and the strife
I hear the music ringing;
It finds an echo in my soul,
How can I keep from singing?
What though my joys and comforts die,
The Lord my Helper liveth!
What though the darkness gather round:
Songs in the night He giveth!
No storm can shake my inmost calm
While to that refuge clinging;
Since God is Lord of heaven and earth,
How can I keep from singing?
I lift mine eyes; the cloud grows thin;
I see the blue above it;
And day by day this pathway smooths
Since first I learned to love it.
The peace of God makes fresh my heart.
A fountain ever spinging;
All things are mine, since I am His
How can I keep from singing?');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0265', 'verse', 1, 0, '[\"My life flows on in endless song;\",\"Amid earth\'s lamentation,\",\"I hear the sweet, though far-off hymn\",\"That hails a new creation;\",\"Through all the tumult and the strife\",\"I hear the music ringing;\",\"It finds an echo in my soul,\",\"How can I keep from singing?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0265', 'verse', 2, 1, '[\"What though my joys and comforts die,\",\"The Lord my Helper liveth!\",\"What though the darkness gather round:\",\"Songs in the night He giveth!\",\"No storm can shake my inmost calm\",\"While to that refuge clinging;\",\"Since God is Lord of heaven and earth,\",\"How can I keep from singing?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0265', 'verse', 3, 2, '[\"I lift mine eyes; the cloud grows thin;\",\"I see the blue above it;\",\"And day by day this pathway smooths\",\"Since first I learned to love it.\",\"The peace of God makes fresh my heart.\",\"A fountain ever spinging;\",\"All things are mine, since I am His\",\"How can I keep from singing?\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0266', 266, 'I Will Follow Thee', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'I will follow thee, my Saviour,
Wheresoe\'er my lot may be.
Where thou goest I will follow;
Yes, my Lord, I\'ll follow thee.
I will follow thee, my Saviour,
Thou didst shed thy blood for me;
And though all men should forsake thee;
By thy grace I\'ll follow thee.
Though the road be rough and thorny,
Trackless as the foaming sea,
Thou hast trod this way before me,
And I\'ll gladly follow thee.
Though I meet with tribulations,
Sorely tempted though I be;
I remember thou wast tempted,
And rejoice to follow thee.
Though thou leadest me through affliction,
Poor, forsaken though I be;
Thou wast destitute, afflicted,
And I only follow thee.
Though to Jordan\'s rolling billows,
Cold and deep, thou leadest me,
Thou hast crossed the waves before me,
And I still will follow thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0266', 'verse', 1, 0, '[\"I will follow thee, my Saviour,\",\"Wheresoe\'er my lot may be.\",\"Where thou goest I will follow;\",\"Yes, my Lord, I\'ll follow thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0266', 'chorus', 0, 1, '[\"I will follow thee, my Saviour,\",\"Thou didst shed thy blood for me;\",\"And though all men should forsake thee;\",\"By thy grace I\'ll follow thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0266', 'verse', 2, 2, '[\"Though the road be rough and thorny,\",\"Trackless as the foaming sea,\",\"Thou hast trod this way before me,\",\"And I\'ll gladly follow thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0266', 'verse', 3, 3, '[\"Though I meet with tribulations,\",\"Sorely tempted though I be;\",\"I remember thou wast tempted,\",\"And rejoice to follow thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0266', 'verse', 4, 4, '[\"Though thou leadest me through affliction,\",\"Poor, forsaken though I be;\",\"Thou wast destitute, afflicted,\",\"And I only follow thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0266', 'verse', 5, 5, '[\"Though to Jordan\'s rolling billows,\",\"Cold and deep, thou leadest me,\",\"Thou hast crossed the waves before me,\",\"And I still will follow thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0267', 267, 'Jesus, I My Cross Have Taken', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Jesus, I my cross have taken,
All to leave and follow thee;
All things else I have forsaken;
Thou from hence my all shalt be.
Perish every fond ambition,
All I\'ve sought, or hoped, or known;
Yet how rich is my condition,
While I prove the Lord my own.
Let the world despise and leave me —
They have left my Saviour, too;
Human hearts and looks deceive me —
Thou art faithful, thou art true.
O, \'tis not in grief to harm me,
While thy love is felt to me;
O, \'twere not in joy to charm me,
If that love be hid from me.
Soul, then know thy full salvation;
Rise o\'er sin, and fear, and care;
Joy to find in every station
Something still to do or bear.
Think what Spirit dwells within thee;
Think what Father\'s smiles are thine;
Think that Jesus died to win thee;
Child of Heaven, canst thou repine?
Haste thee on from grace to glory,
Armed by faith and winged by prayer;
Heaven\'s eternal day\'s before thee;
God\'s own hand shall guide thee there.
Soon shall close the earthly mission,
Soon shall pass thy pilgrim days,
Hope shall change to glad fruition,
Faith to sight, and prayer to praise.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0267', 'verse', 1, 0, '[\"Jesus, I my cross have taken,\",\"All to leave and follow thee;\",\"All things else I have forsaken;\",\"Thou from hence my all shalt be.\",\"Perish every fond ambition,\",\"All I\'ve sought, or hoped, or known;\",\"Yet how rich is my condition,\",\"While I prove the Lord my own.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0267', 'verse', 2, 1, '[\"Let the world despise and leave me —\",\"They have left my Saviour, too;\",\"Human hearts and looks deceive me —\",\"Thou art faithful, thou art true.\",\"O, \'tis not in grief to harm me,\",\"While thy love is felt to me;\",\"O, \'twere not in joy to charm me,\",\"If that love be hid from me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0267', 'verse', 3, 2, '[\"Soul, then know thy full salvation;\",\"Rise o\'er sin, and fear, and care;\",\"Joy to find in every station\",\"Something still to do or bear.\",\"Think what Spirit dwells within thee;\",\"Think what Father\'s smiles are thine;\",\"Think that Jesus died to win thee;\",\"Child of Heaven, canst thou repine?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0267', 'verse', 4, 3, '[\"Haste thee on from grace to glory,\",\"Armed by faith and winged by prayer;\",\"Heaven\'s eternal day\'s before thee;\",\"God\'s own hand shall guide thee there.\",\"Soon shall close the earthly mission,\",\"Soon shall pass thy pilgrim days,\",\"Hope shall change to glad fruition,\",\"Faith to sight, and prayer to praise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0268', 268, 'Blessed Jesus, Meek and Lowly', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Blessed Jesus, meek and lowly,
With us here take thine abode;
We would fain like thee be holy,
Humbly walking with our God.
We would thy sweet Spirit cherish,
Welcome in our hearts thy stay;
Lest without thine aid we perish,
O, abide with us, we pray!
Guide us in the path to heaven,
Rugged though that path may be;
Let each bitter cup that\'s given,
Serve to draw us nearer thee.
In thy footsteps traced before us,
There we see earth\'s scorn and frown;
There is suffering ere the glory,
There\'s a cross before the crown.
In thy vineyard let us labor,
Of thy goodness let us tell;
All is ill without thy favor,
With thy presence all is well.
While the evening shadows gather,
Through this dreary night of tears,
Tarry with us, O our Saviour,
Till the morning light appears.
Then with thee may we forever
Reign with all the good and blest,
Where no sin from thee can sever,
Where the weary are at rest;
There to praise the matchless Giver,
There with angels to adore
Him who did through grace deliver
Us from death forevermore.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0268', 'verse', 1, 0, '[\"Blessed Jesus, meek and lowly,\",\"With us here take thine abode;\",\"We would fain like thee be holy,\",\"Humbly walking with our God.\",\"We would thy sweet Spirit cherish,\",\"Welcome in our hearts thy stay;\",\"Lest without thine aid we perish,\",\"O, abide with us, we pray!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0268', 'verse', 2, 1, '[\"Guide us in the path to heaven,\",\"Rugged though that path may be;\",\"Let each bitter cup that\'s given,\",\"Serve to draw us nearer thee.\",\"In thy footsteps traced before us,\",\"There we see earth\'s scorn and frown;\",\"There is suffering ere the glory,\",\"There\'s a cross before the crown.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0268', 'verse', 3, 2, '[\"In thy vineyard let us labor,\",\"Of thy goodness let us tell;\",\"All is ill without thy favor,\",\"With thy presence all is well.\",\"While the evening shadows gather,\",\"Through this dreary night of tears,\",\"Tarry with us, O our Saviour,\",\"Till the morning light appears.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0268', 'verse', 4, 3, '[\"Then with thee may we forever\",\"Reign with all the good and blest,\",\"Where no sin from thee can sever,\",\"Where the weary are at rest;\",\"There to praise the matchless Giver,\",\"There with angels to adore\",\"Him who did through grace deliver\",\"Us from death forevermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0269', 269, 'Take My Heart, O Father', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Take my heart, O Father, take it!
Make and keep it all thine own;
Let thy Spirit melt and break it,
This proud heart of sin and stone.
Father, make it pure and lowly,
Fond of peace and far from strife;
Turning from the paths unholy,
Of this vain and sinful life.
Ever let thy grace surround me,
Strengthen me with power divine;
By thy cords of love that bound me,
Make me to be wholly thine.
May the blood of Jesus heal me,
And my sins be all forgiven;
Holy Spirit, take and seal me,
Guide me in the path to heaven.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0269', 'verse', 1, 0, '[\"Take my heart, O Father, take it!\",\"Make and keep it all thine own;\",\"Let thy Spirit melt and break it,\",\"This proud heart of sin and stone.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0269', 'verse', 2, 1, '[\"Father, make it pure and lowly,\",\"Fond of peace and far from strife;\",\"Turning from the paths unholy,\",\"Of this vain and sinful life.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0269', 'verse', 3, 2, '[\"Ever let thy grace surround me,\",\"Strengthen me with power divine;\",\"By thy cords of love that bound me,\",\"Make me to be wholly thine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0269', 'verse', 4, 3, '[\"May the blood of Jesus heal me,\",\"And my sins be all forgiven;\",\"Holy Spirit, take and seal me,\",\"Guide me in the path to heaven.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0270', 270, 'Give Thy Youth to God', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Give thou thy youth to God,
With all its budding love;
Send up the opening heart to him,
Fix it on things above.
He seeks thy heart, my child;
He wants to make thee blest;
Thy soul with his own joy to fill,
To give thee peace and rest.
Take thou the side of God,
In all things great or small;
So shall he ever take thy side,
And bear thee safe through all.
Guide me in the path to heaven.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0270', 'verse', 1, 0, '[\"Give thou thy youth to God,\",\"With all its budding love;\",\"Send up the opening heart to him,\",\"Fix it on things above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0270', 'verse', 2, 1, '[\"He seeks thy heart, my child;\",\"He wants to make thee blest;\",\"Thy soul with his own joy to fill,\",\"To give thee peace and rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0270', 'verse', 3, 2, '[\"Take thou the side of God,\",\"In all things great or small;\",\"So shall he ever take thy side,\",\"And bear thee safe through all.\",\"Guide me in the path to heaven.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0271', 271, 'Not I, but Christ', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Not I, but Christ,
be honored, loved, exalted;
Not I, but Christ,
be seen, be known, be heard;
Not I, but Christ,
in every look and action,
Not I, but Christ,
in every thought and word.
Not I, but Christ,
to gently soothe in sorrow,
Not I, but Christ,
to wipe the falling tear;
Not I, but Christ,
to lift the weary burden,
Not I, but Christ,
to hush away all fear.
Christ, only Christ!
No idle words e\'er falling,
Christ, only Christ;
no needless bustling sound;
Christ, only Christ,
no self important bearing;
Christ, only Christ,
no trace of \"I\" be found.
Not I, but Christ,
my every need supplying,
Not I, but Christ,
my strength and health to be;
Christ, only Christ,
for body, soul, and spirit,
Christ, only Christ,
here and eternally.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0271', 'verse', 1, 0, '[\"Not I, but Christ,\",\"be honored, loved, exalted;\",\"Not I, but Christ,\",\"be seen, be known, be heard;\",\"Not I, but Christ,\",\"in every look and action,\",\"Not I, but Christ,\",\"in every thought and word.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0271', 'verse', 2, 1, '[\"Not I, but Christ,\",\"to gently soothe in sorrow,\",\"Not I, but Christ,\",\"to wipe the falling tear;\",\"Not I, but Christ,\",\"to lift the weary burden,\",\"Not I, but Christ,\",\"to hush away all fear.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0271', 'verse', 3, 2, '[\"Christ, only Christ!\",\"No idle words e\'er falling,\",\"Christ, only Christ;\",\"no needless bustling sound;\",\"Christ, only Christ,\",\"no self important bearing;\",\"Christ, only Christ,\",\"no trace of \\\"I\\\" be found.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0271', 'verse', 4, 3, '[\"Not I, but Christ,\",\"my every need supplying,\",\"Not I, but Christ,\",\"my strength and health to be;\",\"Christ, only Christ,\",\"for body, soul, and spirit,\",\"Christ, only Christ,\",\"here and eternally.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0272', 272, 'Have Thine Own Way', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Have thine own way, Lord!
Have thine own way!
Thou art the potter;
I am the clay.
Mold me and make me
After thy will,
While I am waiting,
Yielded and still.
Have thine own way,
Lord! Have thine own way!
Search me and try me,
Master today!
Whiter than snow,
Lord, Wash me just now,
As in thy presence
Humbly I bow.
Have thine own way, Lord!
Have thine own way!
Wounded and weary,
Help me I pray!
Power, all power —
Surely is thine!
Touch me and heal me,
Saviour divine!
Have thine own way, Lord!
Have thine own way!
Hold o\'er my being
Absolute sway!
Fill with thy Spirit
Till all shall see
Christ only, always,
Living in me!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0272', 'verse', 1, 0, '[\"Have thine own way, Lord!\",\"Have thine own way!\",\"Thou art the potter;\",\"I am the clay.\",\"Mold me and make me\",\"After thy will,\",\"While I am waiting,\",\"Yielded and still.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0272', 'verse', 2, 1, '[\"Have thine own way,\",\"Lord! Have thine own way!\",\"Search me and try me,\",\"Master today!\",\"Whiter than snow,\",\"Lord, Wash me just now,\",\"As in thy presence\",\"Humbly I bow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0272', 'verse', 3, 2, '[\"Have thine own way, Lord!\",\"Have thine own way!\",\"Wounded and weary,\",\"Help me I pray!\",\"Power, all power —\",\"Surely is thine!\",\"Touch me and heal me,\",\"Saviour divine!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0272', 'verse', 4, 3, '[\"Have thine own way, Lord!\",\"Have thine own way!\",\"Hold o\'er my being\",\"Absolute sway!\",\"Fill with thy Spirit\",\"Till all shall see\",\"Christ only, always,\",\"Living in me!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0273', 273, 'Take My Life and Let It Be', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Take my life, and let it be
Consecrated, Lord, to thee;
Take my hands, and let them move
At the impulse of thy love,
At the impulse of thy love.
Take my feet, and let them be
Swift and beautiful for thee.
Take my voice, and let me sing
Always, only, for my King,
Always, only, for my King.
Take my lips, and let them be
Filled with messages from thee.
Take my silver and my gold,
Not a mite would I withhold,
Not a mite would I withhold.
Take my will, and make it thine;
It shall be no longer mine;
Take my heart, it is thine own,
It shall be thy royal throne,
It shall be thy royal throne.
Take my love; my Lord, I pour
At thy feet its treasure store;
Take myself, and I will be,
Ever, only, all for thee,
Ever, only, all for thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0273', 'verse', 1, 0, '[\"Take my life, and let it be\",\"Consecrated, Lord, to thee;\",\"Take my hands, and let them move\",\"At the impulse of thy love,\",\"At the impulse of thy love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0273', 'verse', 2, 1, '[\"Take my feet, and let them be\",\"Swift and beautiful for thee.\",\"Take my voice, and let me sing\",\"Always, only, for my King,\",\"Always, only, for my King.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0273', 'verse', 3, 2, '[\"Take my lips, and let them be\",\"Filled with messages from thee.\",\"Take my silver and my gold,\",\"Not a mite would I withhold,\",\"Not a mite would I withhold.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0273', 'verse', 4, 3, '[\"Take my will, and make it thine;\",\"It shall be no longer mine;\",\"Take my heart, it is thine own,\",\"It shall be thy royal throne,\",\"It shall be thy royal throne.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0273', 'verse', 5, 4, '[\"Take my love; my Lord, I pour\",\"At thy feet its treasure store;\",\"Take myself, and I will be,\",\"Ever, only, all for thee,\",\"Ever, only, all for thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0274', 274, 'Must Jesus Bear the Cross Alone?', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Must Jesus bear the cross alone,
And all the world go free?
No, there\'s a cross for everyone,
And there\'s a cross for me.
The consecrated cross I\'ll bear,
Till he shall set me free;
And then go home my crown to wear,
For there\'s a crown for me.
Upon the crystal pavement, down
At Jesus\' pierced feet,
With joy I\'ll cast my golden crown,
And His dear name repeat.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0274', 'verse', 1, 0, '[\"Must Jesus bear the cross alone,\",\"And all the world go free?\",\"No, there\'s a cross for everyone,\",\"And there\'s a cross for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0274', 'verse', 2, 1, '[\"The consecrated cross I\'ll bear,\",\"Till he shall set me free;\",\"And then go home my crown to wear,\",\"For there\'s a crown for me.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0274', 'verse', 3, 2, '[\"Upon the crystal pavement, down\",\"At Jesus\' pierced feet,\",\"With joy I\'ll cast my golden crown,\",\"And His dear name repeat.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0275', 275, 'Deeper Yet', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'In the blood from the cross
I have been washed from sin;
But to be free from dross,
Still I would enter in.
Deeper yet, deeper yet,
Into the crimson flood;
Deeper yet, deeper yet,
Under the precious blood.
Day by day, hour by hour,
Blessings are sent to me;
But for more of his power,
Ever my prayer shall be.
Near to Christ I would live,
Following him each day;
What I ask he will give;
So then with faith I pray.
Now I have peace, sweet peace,
While in this world of sin;
But to pray I’ll not cease
Till I am pure within.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0275', 'verse', 1, 0, '[\"In the blood from the cross\",\"I have been washed from sin;\",\"But to be free from dross,\",\"Still I would enter in.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0275', 'chorus', 0, 1, '[\"Deeper yet, deeper yet,\",\"Into the crimson flood;\",\"Deeper yet, deeper yet,\",\"Under the precious blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0275', 'verse', 2, 2, '[\"Day by day, hour by hour,\",\"Blessings are sent to me;\",\"But for more of his power,\",\"Ever my prayer shall be.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0275', 'verse', 3, 3, '[\"Near to Christ I would live,\",\"Following him each day;\",\"What I ask he will give;\",\"So then with faith I pray.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0275', 'verse', 4, 4, '[\"Now I have peace, sweet peace,\",\"While in this world of sin;\",\"But to pray I’ll not cease\",\"Till I am pure within.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0276', 276, 'My Jesus, I Love Thee', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'My Jesus, I love thee, I know thou art mine;
For thee all the follies of sin I resign;
My gracious Redeemer, my Saviour art thou;
If ever I loved thee, my Jesus, \'tis now.
I love thee because thou hast first loved me,
And purchased my pardon on Calvary\'s tree;
I love thee for wearing the thorns on thy brow;
If ever I loved thee, my Jesus, \'tis now.
I\'ll love thee in life, I will love thee in death,
And praise thee as long as thou lendest me breath;
And say when the death dew lies cold on my brow,
If ever I loved thee, my Jesus, \'tis now.
In mansions of glory and endless delight,
I\'ll ever adore thee in heaven so bright;
I\'ll sing with the glittering crown on my brow;
If ever I loved thee, my Jesus, \'tis now.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0276', 'verse', 1, 0, '[\"My Jesus, I love thee, I know thou art mine;\",\"For thee all the follies of sin I resign;\",\"My gracious Redeemer, my Saviour art thou;\",\"If ever I loved thee, my Jesus, \'tis now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0276', 'verse', 2, 1, '[\"I love thee because thou hast first loved me,\",\"And purchased my pardon on Calvary\'s tree;\",\"I love thee for wearing the thorns on thy brow;\",\"If ever I loved thee, my Jesus, \'tis now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0276', 'verse', 3, 2, '[\"I\'ll love thee in life, I will love thee in death,\",\"And praise thee as long as thou lendest me breath;\",\"And say when the death dew lies cold on my brow,\",\"If ever I loved thee, my Jesus, \'tis now.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0276', 'verse', 4, 3, '[\"In mansions of glory and endless delight,\",\"I\'ll ever adore thee in heaven so bright;\",\"I\'ll sing with the glittering crown on my brow;\",\"If ever I loved thee, my Jesus, \'tis now.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0277', 277, 'Fade, Fade Each Earthly Joy', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Fade, fade each earthly joy, Jesus is mine!
Break every tender tie, Jesus is mine!
Dark is the wilderness,
Earth has no resting place,
Jesus alone can bless, Jesus is mine!
Tempt not my soul away, Jesus is mine!
Here would I ever stay, Jesus is mine!
Perishing things of clay,
Born but for one brief day,
Pass from my heart away, Jesus is mine!
Farewell, ye dreams of night, Jesus is mine!
Lost in this dawning light, Jesus is mine!
All that my soul has tried,
Left but a dismal void,
Jesus has satisfied, Jesus is mine!
Farewell, mortality, Jesus is mine!
Welcome eternity, Jesus is mine!
Welcome, O loved and blest,
Welcome, sweet scenes of rest,
Welsome my Saviour\'s breast, Jesus is mine!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0277', 'verse', 1, 0, '[\"Fade, fade each earthly joy, Jesus is mine!\",\"Break every tender tie, Jesus is mine!\",\"Dark is the wilderness,\",\"Earth has no resting place,\",\"Jesus alone can bless, Jesus is mine!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0277', 'verse', 2, 1, '[\"Tempt not my soul away, Jesus is mine!\",\"Here would I ever stay, Jesus is mine!\",\"Perishing things of clay,\",\"Born but for one brief day,\",\"Pass from my heart away, Jesus is mine!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0277', 'verse', 3, 2, '[\"Farewell, ye dreams of night, Jesus is mine!\",\"Lost in this dawning light, Jesus is mine!\",\"All that my soul has tried,\",\"Left but a dismal void,\",\"Jesus has satisfied, Jesus is mine!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0277', 'verse', 4, 3, '[\"Farewell, mortality, Jesus is mine!\",\"Welcome eternity, Jesus is mine!\",\"Welcome, O loved and blest,\",\"Welcome, sweet scenes of rest,\",\"Welsome my Saviour\'s breast, Jesus is mine!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0278', 278, 'I Lay My Sins on Jesus', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'I lay my sins on Jesus,
The spotless Lamb of God;
He bears them all, and frees us');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0278', 'verse', 1, 0, '[\"I lay my sins on Jesus,\",\"The spotless Lamb of God;\",\"He bears them all, and frees us\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0279', 279, 'Live Out Thy Life Within Me', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Live out Thy life within me,
O Jesus, King of kings!
Be Thou Thyself the answer
To all my questionings;
Live out Thy life within me,
In all things have Thy way!
I, the transparent medium
Thy glory to display.
The temple has been yielded,
And purified of sin;
Let Thy Shekinah glory
Now shine forth from within,
And all the earth keep silence,
The body henceforth be
Thy silent, gentle servant,
Moved only as by Thee.
Its members every moment
Held subject to Thy call,
Ready to have Thee use them,
Or not be used at all;
Held without restless longing,
Or strain, or stress, or fret
Or chafings at Thy dealings,
Or thoughts of vain regret.
But restful, calm, and pliant,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0279', 'verse', 1, 0, '[\"Live out Thy life within me,\",\"O Jesus, King of kings!\",\"Be Thou Thyself the answer\",\"To all my questionings;\",\"Live out Thy life within me,\",\"In all things have Thy way!\",\"I, the transparent medium\",\"Thy glory to display.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0279', 'verse', 2, 1, '[\"The temple has been yielded,\",\"And purified of sin;\",\"Let Thy Shekinah glory\",\"Now shine forth from within,\",\"And all the earth keep silence,\",\"The body henceforth be\",\"Thy silent, gentle servant,\",\"Moved only as by Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0279', 'verse', 3, 2, '[\"Its members every moment\",\"Held subject to Thy call,\",\"Ready to have Thee use them,\",\"Or not be used at all;\",\"Held without restless longing,\",\"Or strain, or stress, or fret\",\"Or chafings at Thy dealings,\",\"Or thoughts of vain regret.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0279', 'verse', 4, 3, '[\"But restful, calm, and pliant,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0280', 280, 'Beneath the Cross of Jesus', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Beneath the cross of Jesus
I fain would take my stand,
The shadow of a mighty rock
Wthin a weary land;
A home within the wilderness,
A rest upon the way,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0280', 'verse', 1, 0, '[\"Beneath the cross of Jesus\",\"I fain would take my stand,\",\"The shadow of a mighty rock\",\"Wthin a weary land;\",\"A home within the wilderness,\",\"A rest upon the way,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0281', 281, 'There Lives a Voice Within Me', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'There lives a voice within me,
Guest angel of my heart,
Whose whisperings strive to win me
To act a noble part.
Up evermore it springeth
Like some sweet melody,
And evermore it singeth
This song of songs to me:
This world is full of beauty
That points the soul above,
And if we did our duty,
It might be full of love.
The leaf tongues of the forest,
The flower lips of the sod,
The birds that hymn their raptures
Up to the throne of God;
The summer wind that bringeth
Joy over land and sea,
Have each a voice that singeth
This song of songs to me:
O voice of God most tender,
O voice of God divine,
Still be my heart\'s defender
Till every thought is Thine;
My soul in gladness bringeth
Its songs of praise to Thee,
While all around me singeth
This song of songs to me:');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0281', 'verse', 1, 0, '[\"There lives a voice within me,\",\"Guest angel of my heart,\",\"Whose whisperings strive to win me\",\"To act a noble part.\",\"Up evermore it springeth\",\"Like some sweet melody,\",\"And evermore it singeth\",\"This song of songs to me:\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0281', 'chorus', 0, 1, '[\"This world is full of beauty\",\"That points the soul above,\",\"And if we did our duty,\",\"It might be full of love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0281', 'verse', 2, 2, '[\"The leaf tongues of the forest,\",\"The flower lips of the sod,\",\"The birds that hymn their raptures\",\"Up to the throne of God;\",\"The summer wind that bringeth\",\"Joy over land and sea,\",\"Have each a voice that singeth\",\"This song of songs to me:\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0281', 'verse', 3, 3, '[\"O voice of God most tender,\",\"O voice of God divine,\",\"Still be my heart\'s defender\",\"Till every thought is Thine;\",\"My soul in gladness bringeth\",\"Its songs of praise to Thee,\",\"While all around me singeth\",\"This song of songs to me:\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0282', 282, 'Thine Forever', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Thine forever! God of love,
Hear us from Thy throne above;
Thine forever may we be,
Here and in eternity.
Thine forever! Lord of life,
Shield us through our earthly strife;
Thou the life, the truth, the way,
Guide us to the realms of day.
Thine forever! Oh how blest
They who find in Thee their rest!
Saviour, Guardian, heavenly Friend,
O defend us to the end.
Thine forever! Saviour, keep
These Thy frail and trembling sheep;
Safe alone beneath Thy care,
Let us all Thy goodness share.
Thine forever! Thou our Guide,
All our wants by Thee supplied,
All our sins by Thee forgiven,
Lead us, Lord, from earth to heaven.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0282', 'verse', 1, 0, '[\"Thine forever! God of love,\",\"Hear us from Thy throne above;\",\"Thine forever may we be,\",\"Here and in eternity.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0282', 'verse', 2, 1, '[\"Thine forever! Lord of life,\",\"Shield us through our earthly strife;\",\"Thou the life, the truth, the way,\",\"Guide us to the realms of day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0282', 'verse', 3, 2, '[\"Thine forever! Oh how blest\",\"They who find in Thee their rest!\",\"Saviour, Guardian, heavenly Friend,\",\"O defend us to the end.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0282', 'verse', 4, 3, '[\"Thine forever! Saviour, keep\",\"These Thy frail and trembling sheep;\",\"Safe alone beneath Thy care,\",\"Let us all Thy goodness share.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0282', 'verse', 5, 4, '[\"Thine forever! Thou our Guide,\",\"All our wants by Thee supplied,\",\"All our sins by Thee forgiven,\",\"Lead us, Lord, from earth to heaven.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0283', 283, 'Saviour! Thy Dying Love', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Saviour! Thy dying love
Thou gavest me,
Nor should I aught withhold,
Dear Lord, from Thee;
In love my soul would bow,
My heart fulfill its vow,
Some offering bring Thee now,
Something for Thee.
At the blest mercy seat,
Pleading for me,
My feeble faith looks up,
Jesus, to Thee;
Help me the cross to bear,
Thy wondrous love declare,
Some song to raise, or prayer,
Something for Thee.
Give me a faithful heart,
Likeness to Thee,
That each departing day
Henceforth may see
Some work of love begun,
Some deed of kindness done,
Some wanderer sought and won,
Something for Thee.
All that I am and have,
Thy gifts so free,
In joy, in grief, through life,
Dear Lord, for Thee!
And when Thy face I see,
My ransomed soul shall be.
Through all eternity
Something for Thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0283', 'verse', 1, 0, '[\"Saviour! Thy dying love\",\"Thou gavest me,\",\"Nor should I aught withhold,\",\"Dear Lord, from Thee;\",\"In love my soul would bow,\",\"My heart fulfill its vow,\",\"Some offering bring Thee now,\",\"Something for Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0283', 'verse', 2, 1, '[\"At the blest mercy seat,\",\"Pleading for me,\",\"My feeble faith looks up,\",\"Jesus, to Thee;\",\"Help me the cross to bear,\",\"Thy wondrous love declare,\",\"Some song to raise, or prayer,\",\"Something for Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0283', 'verse', 3, 2, '[\"Give me a faithful heart,\",\"Likeness to Thee,\",\"That each departing day\",\"Henceforth may see\",\"Some work of love begun,\",\"Some deed of kindness done,\",\"Some wanderer sought and won,\",\"Something for Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0283', 'verse', 4, 3, '[\"All that I am and have,\",\"Thy gifts so free,\",\"In joy, in grief, through life,\",\"Dear Lord, for Thee!\",\"And when Thy face I see,\",\"My ransomed soul shall be.\",\"Through all eternity\",\"Something for Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0284', 284, 'Make Me a Captive, Lord', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Make me a captive, Lord,
And then I shall be free;
Force me to render up my sword,
And I shall conqueror be.
I sink in life’s alarms
When by myself I stand;
Imprison me within Thine arms,
And strong shall be my hand.
My heart is weak and poor
Till it a master find;
It has no spring of action sure —
It varies with the wind.
It cannot freely move
Till Thou hast wrought its chain;
Enslave it with Thy matchless love,
And deathless it shall reign.
My will is not my own
Till Thou hast made it Thine;
If it would reach a monarch’s throne
It must its crown resign;
It only stands unbent,
Amid the clashing strife,
When on Thy bosom it has leant
And found in Thee its life.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0284', 'verse', 1, 0, '[\"Make me a captive, Lord,\",\"And then I shall be free;\",\"Force me to render up my sword,\",\"And I shall conqueror be.\",\"I sink in life’s alarms\",\"When by myself I stand;\",\"Imprison me within Thine arms,\",\"And strong shall be my hand.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0284', 'verse', 2, 1, '[\"My heart is weak and poor\",\"Till it a master find;\",\"It has no spring of action sure —\",\"It varies with the wind.\",\"It cannot freely move\",\"Till Thou hast wrought its chain;\",\"Enslave it with Thy matchless love,\",\"And deathless it shall reign.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0284', 'verse', 3, 2, '[\"My will is not my own\",\"Till Thou hast made it Thine;\",\"If it would reach a monarch’s throne\",\"It must its crown resign;\",\"It only stands unbent,\",\"Amid the clashing strife,\",\"When on Thy bosom it has leant\",\"And found in Thee its life.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0285', 285, 'I Give My Heart to Thee', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'I give my heart to Thee,
O Jesus most desired;
And heart for heart the gift shall be,
For Thou my soul hast fired.
Thou hearts alone wouldst move,
Thou only hearts dost love;
I would love Thee as Thou lovest me,
O Jesus most desired.
What offering can I make,
Dear Lord, to love like Thine —
That Thou, the Word, didst stoop to take
A human form like mine?
Thy heart is opened wide,
Its offered love most free,
That heart to heart I may abide,
And hide myself in Thee.
Ah, how Thy love doth burn,
Till I that love return!
I would love Thee as Thou lovest me,
O Jesus most desired.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0285', 'verse', 1, 0, '[\"I give my heart to Thee,\",\"O Jesus most desired;\",\"And heart for heart the gift shall be,\",\"For Thou my soul hast fired.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0285', 'verse', 2, 1, '[\"Thou hearts alone wouldst move,\",\"Thou only hearts dost love;\",\"I would love Thee as Thou lovest me,\",\"O Jesus most desired.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0285', 'verse', 3, 2, '[\"What offering can I make,\",\"Dear Lord, to love like Thine —\",\"That Thou, the Word, didst stoop to take\",\"A human form like mine?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0285', 'verse', 4, 3, '[\"Thy heart is opened wide,\",\"Its offered love most free,\",\"That heart to heart I may abide,\",\"And hide myself in Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0285', 'verse', 5, 4, '[\"Ah, how Thy love doth burn,\",\"Till I that love return!\",\"I would love Thee as Thou lovest me,\",\"O Jesus most desired.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0286', 286, 'I Come to Thee, O Father', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'I come to Thee, O Father,
Confessing all my sin;
I come and claim Thy promise;
Come in, dear Lord, come in.
Drive out my sinful nature,
Implant Thine own, I pray;
And wash and cleanse and save me
Each moment, hour and day.
O send Thy Holy Spirit
To guide me, I implore;
For Jesus\' sake, O make me
Thy child forevermore.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0286', 'verse', 1, 0, '[\"I come to Thee, O Father,\",\"Confessing all my sin;\",\"I come and claim Thy promise;\",\"Come in, dear Lord, come in.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0286', 'verse', 2, 1, '[\"Drive out my sinful nature,\",\"Implant Thine own, I pray;\",\"And wash and cleanse and save me\",\"Each moment, hour and day.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0286', 'verse', 3, 2, '[\"O send Thy Holy Spirit\",\"To guide me, I implore;\",\"For Jesus\' sake, O make me\",\"Thy child forevermore.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0287', 287, 'Saviour Blessed Saviour', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Saviour, blessed Saviour,
Listen whilst we sing,
Hearts and voices raising
Praises to our King.
All we have we offer;
All we hope to be,
Body, soul, and spirit,
All we yield to Thee.
Nearer, ever nearer,
Christ, we draw to Thee,
Deep in adoration
Bending low the knee.
Thou for our redemption
Camest on earth to die;
Thou, that we might follow,
Hast gone up on high.
Great, and ever greater,
Are Thy mercies here,
True and ever lasting
Are the glories there,
Where no pain, or sorrow,
Toil, or care is known,
Where the angel legions
Circle round Thy throne.
Clearer still and clearer
Dawns the light from heaven,
In our sadness bringing
News of sin forgiven;
Life has lost its shadows,
Pure the light within;
Thou hast shed Thy radiance
On a world of sin.
Onward, ever onward,
Journeying o\'er the road
Worn by saints before us
Journeying on to God;
Leaving all behind us,
May we hasten on,
Backward never looking
Till the prize is won.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0287', 'verse', 1, 0, '[\"Saviour, blessed Saviour,\",\"Listen whilst we sing,\",\"Hearts and voices raising\",\"Praises to our King.\",\"All we have we offer;\",\"All we hope to be,\",\"Body, soul, and spirit,\",\"All we yield to Thee.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0287', 'verse', 2, 1, '[\"Nearer, ever nearer,\",\"Christ, we draw to Thee,\",\"Deep in adoration\",\"Bending low the knee.\",\"Thou for our redemption\",\"Camest on earth to die;\",\"Thou, that we might follow,\",\"Hast gone up on high.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0287', 'verse', 3, 2, '[\"Great, and ever greater,\",\"Are Thy mercies here,\",\"True and ever lasting\",\"Are the glories there,\",\"Where no pain, or sorrow,\",\"Toil, or care is known,\",\"Where the angel legions\",\"Circle round Thy throne.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0287', 'verse', 4, 3, '[\"Clearer still and clearer\",\"Dawns the light from heaven,\",\"In our sadness bringing\",\"News of sin forgiven;\",\"Life has lost its shadows,\",\"Pure the light within;\",\"Thou hast shed Thy radiance\",\"On a world of sin.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0287', 'verse', 5, 4, '[\"Onward, ever onward,\",\"Journeying o\'er the road\",\"Worn by saints before us\",\"Journeying on to God;\",\"Leaving all behind us,\",\"May we hasten on,\",\"Backward never looking\",\"Till the prize is won.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0288', 288, 'O Jesus, I Have Promised', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'O Jesus, I have promised
To serve thee to the end;
Be Thou forever near me,
My Master and my friend.
I shall not fear the battle
If Thou art by my side,
Nor wander from the pathway
If Thou wilt be my guide.
O let me feel Thee near me;
The world is ever near!
I see the sights that dazzle,
The tempting sounds I hear;
My foes are ever near me,
Around me and within;
But Jesus, draw Thou nearer,
And shield my soul from sin.
O Jesus, Thou hast promised
To all who follow Thee
That where thou art in glory
There shall Thy servant be;
And Jesus, I have promised
To serve Thee to the end;
O give me grace to follow
My Master and my Friend.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0288', 'verse', 1, 0, '[\"O Jesus, I have promised\",\"To serve thee to the end;\",\"Be Thou forever near me,\",\"My Master and my friend.\",\"I shall not fear the battle\",\"If Thou art by my side,\",\"Nor wander from the pathway\",\"If Thou wilt be my guide.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0288', 'verse', 2, 1, '[\"O let me feel Thee near me;\",\"The world is ever near!\",\"I see the sights that dazzle,\",\"The tempting sounds I hear;\",\"My foes are ever near me,\",\"Around me and within;\",\"But Jesus, draw Thou nearer,\",\"And shield my soul from sin.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0288', 'verse', 3, 2, '[\"O Jesus, Thou hast promised\",\"To all who follow Thee\",\"That where thou art in glory\",\"There shall Thy servant be;\",\"And Jesus, I have promised\",\"To serve Thee to the end;\",\"O give me grace to follow\",\"My Master and my Friend.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0289', 289, 'Weary of Earth', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Weary of earth and laden with my sin,
I look to heaven and long to enter in;
But there no evil thing may find a home,
And yet I hear a voice that bids me, \"Come.\"
The while I fain would tread the heavenly way,
Evil is ever with me day by day;
Yet on mine ears the gracious tidings fall,
\"Repent, return; thou shalt be loosed from all.\"
Cease, restless will! Thy lonely strife resign!
I know too well how little strength is mine;
Grant me, dear Lord, Thy saving love to see;
I strive no more; I give myself to Thee.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0289', 'verse', 1, 0, '[\"Weary of earth and laden with my sin,\",\"I look to heaven and long to enter in;\",\"But there no evil thing may find a home,\",\"And yet I hear a voice that bids me, \\\"Come.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0289', 'verse', 2, 1, '[\"The while I fain would tread the heavenly way,\",\"Evil is ever with me day by day;\",\"Yet on mine ears the gracious tidings fall,\",\"\\\"Repent, return; thou shalt be loosed from all.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0289', 'verse', 3, 2, '[\"Cease, restless will! Thy lonely strife resign!\",\"I know too well how little strength is mine;\",\"Grant me, dear Lord, Thy saving love to see;\",\"I strive no more; I give myself to Thee.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0290', 290, 'O Lamb of God! Still Keep Me', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'O Lamb of God! still keep me
Near to Thy wounded side;
\'Tis only there in safely
And peace I can abide!
What foes and snares surround me,
What doubts and fears within!
The grace that sought and found me,
Alone can keep me clean.
\'Tis only in Thee hiding
I know my life secure —
Only in Thee abiding,
The conflict can endure.
Thine arm the victory gaineth
O\'er every hateful foe;
Thy love my heart sustaineth
In all its care and woe.
Soon shall my eyes behold Thee,
With rapture, face to face;
One half hath not been told me
Of all Thy power and grace.
Thy beauty, Lord, and glory,
The wonders of Thy love,
Shall be the endless story
Of all the saints above.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0290', 'verse', 1, 0, '[\"O Lamb of God! still keep me\",\"Near to Thy wounded side;\",\"\'Tis only there in safely\",\"And peace I can abide!\",\"What foes and snares surround me,\",\"What doubts and fears within!\",\"The grace that sought and found me,\",\"Alone can keep me clean.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0290', 'verse', 2, 1, '[\"\'Tis only in Thee hiding\",\"I know my life secure —\",\"Only in Thee abiding,\",\"The conflict can endure.\",\"Thine arm the victory gaineth\",\"O\'er every hateful foe;\",\"Thy love my heart sustaineth\",\"In all its care and woe.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0290', 'verse', 3, 2, '[\"Soon shall my eyes behold Thee,\",\"With rapture, face to face;\",\"One half hath not been told me\",\"Of all Thy power and grace.\",\"Thy beauty, Lord, and glory,\",\"The wonders of Thy love,\",\"Shall be the endless story\",\"Of all the saints above.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0291', 291, 'Come, Thou Fount of Every Blessing', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Come, Thou Fount of every blessing,
Tune my heart to sing Thy grace;
Streams of mercy, never ceasing,
Call for songs of loudest praise.
Teach me ever to adore Thee,
May I still Thy goodness prove,
While the hope of endless glory
Fills my heart with joy and love.
Here I raise mine Ebenezer,
Hither by thy help I\'ve come,
And I hope by Thy good pleasure,
Safely to arrive at home.
Jesus sought me when a stranger,
Wandering from the fold of God;
He to rescue me from danger
Interposed His precious blood.
O, to grace how great a debtor
Daily I\'m constrained to be!
Let Thy goodness, like a fetter,
Bind me closer still to Thee.
Prone to wander, Lord, I feel it,
Prone to leave the God I love;
Here\'s my heart — O, take and seal it;
Seal it for Thy courts above.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0291', 'verse', 1, 0, '[\"Come, Thou Fount of every blessing,\",\"Tune my heart to sing Thy grace;\",\"Streams of mercy, never ceasing,\",\"Call for songs of loudest praise.\",\"Teach me ever to adore Thee,\",\"May I still Thy goodness prove,\",\"While the hope of endless glory\",\"Fills my heart with joy and love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0291', 'verse', 2, 1, '[\"Here I raise mine Ebenezer,\",\"Hither by thy help I\'ve come,\",\"And I hope by Thy good pleasure,\",\"Safely to arrive at home.\",\"Jesus sought me when a stranger,\",\"Wandering from the fold of God;\",\"He to rescue me from danger\",\"Interposed His precious blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0291', 'verse', 3, 2, '[\"O, to grace how great a debtor\",\"Daily I\'m constrained to be!\",\"Let Thy goodness, like a fetter,\",\"Bind me closer still to Thee.\",\"Prone to wander, Lord, I feel it,\",\"Prone to leave the God I love;\",\"Here\'s my heart — O, take and seal it;\",\"Seal it for Thy courts above.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0292', 292, 'O How Happy Are They', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'O how happy are they
Who their Saviour obey,
And have laid up their treasure above!
Tongue can never express
The sweet comfort and peace
Of a soul in its earliest love.
That sweet comfort is mine,
Since the favor divine
I received through the blood of the Lamb;
Since my heart first believed.
What a joy I\'ve received,
What a heaven in Jesus\' dear name!
\'Tis a heaven below
My Redeemer to know;
And the angels can do nothing more
Than to fall at His feet,
And the story repeat,
And the Lover of sinners adore.
Jesus all the day long
Is my joy and my song;
O that all to this refuge might fly!
He hath loved me, indeed,
He did suffer and bleed,
To redeem such a rebel as I.
On the wings of His love,
I am carried above
All my sin, and temptation, and pain;
O, that all would believe,
And by sin never grieve,
And thus cause Him to suffer again.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0292', 'verse', 1, 0, '[\"O how happy are they\",\"Who their Saviour obey,\",\"And have laid up their treasure above!\",\"Tongue can never express\",\"The sweet comfort and peace\",\"Of a soul in its earliest love.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0292', 'verse', 2, 1, '[\"That sweet comfort is mine,\",\"Since the favor divine\",\"I received through the blood of the Lamb;\",\"Since my heart first believed.\",\"What a joy I\'ve received,\",\"What a heaven in Jesus\' dear name!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0292', 'verse', 3, 2, '[\"\'Tis a heaven below\",\"My Redeemer to know;\",\"And the angels can do nothing more\",\"Than to fall at His feet,\",\"And the story repeat,\",\"And the Lover of sinners adore.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0292', 'verse', 4, 3, '[\"Jesus all the day long\",\"Is my joy and my song;\",\"O that all to this refuge might fly!\",\"He hath loved me, indeed,\",\"He did suffer and bleed,\",\"To redeem such a rebel as I.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0292', 'verse', 5, 4, '[\"On the wings of His love,\",\"I am carried above\",\"All my sin, and temptation, and pain;\",\"O, that all would believe,\",\"And by sin never grieve,\",\"And thus cause Him to suffer again.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0293', 293, 'Awake! Jerusalem, Awake!', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Awake! Jerusalem, awake!
No longer in thy sins lie down;
The garment of salvation take,
Thy beauty and thy strength put on.
Shake off the dust that blinds thy sight,
And hides the promise from thine eyes:
Arise, and struggle into light;
The great Deliverer calls, Arise!
Shake off the bands of sad despair;
Zion, assert thy liberty;
Look up, thy broken heart prepare,
And God shall set the captive free.
Vessels of mercy, sons of grace,
Be purged from every sinful slain;
Be like your Lord, His word embrace,
Nor bear His hallowed name in vain.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0293', 'verse', 1, 0, '[\"Awake! Jerusalem, awake!\",\"No longer in thy sins lie down;\",\"The garment of salvation take,\",\"Thy beauty and thy strength put on.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0293', 'verse', 2, 1, '[\"Shake off the dust that blinds thy sight,\",\"And hides the promise from thine eyes:\",\"Arise, and struggle into light;\",\"The great Deliverer calls, Arise!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0293', 'verse', 3, 2, '[\"Shake off the bands of sad despair;\",\"Zion, assert thy liberty;\",\"Look up, thy broken heart prepare,\",\"And God shall set the captive free.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0293', 'verse', 4, 3, '[\"Vessels of mercy, sons of grace,\",\"Be purged from every sinful slain;\",\"Be like your Lord, His word embrace,\",\"Nor bear His hallowed name in vain.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0294', 294, 'Lift Up Your Heads', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Lift up your heads, ye mighty gates!
Behold the King of glory waits;
The King of kings is drawing near,
The Saviour of the world is here.
The Lord is just, a helper tried;
Mercy is ever at His side;
His kingly crowns is holiness,
His scepter, pity in distress.
O blest the land, the city blest,
Where Christ the Ruler is confessed!
O happy hearts and happy homes
To whom this King in triumph comes!
Fling wide the portals of your heart;
Make it a temple, set apart');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0294', 'verse', 1, 0, '[\"Lift up your heads, ye mighty gates!\",\"Behold the King of glory waits;\",\"The King of kings is drawing near,\",\"The Saviour of the world is here.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0294', 'verse', 2, 1, '[\"The Lord is just, a helper tried;\",\"Mercy is ever at His side;\",\"His kingly crowns is holiness,\",\"His scepter, pity in distress.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0294', 'verse', 3, 2, '[\"O blest the land, the city blest,\",\"Where Christ the Ruler is confessed!\",\"O happy hearts and happy homes\",\"To whom this King in triumph comes!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0294', 'verse', 4, 3, '[\"Fling wide the portals of your heart;\",\"Make it a temple, set apart\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0295', 295, 'Amazing Grace', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Amazing grace! How sweet the sound
That saved a wretch like me!
I once was lost, but now am found;
Was blind, but now I see.
\'Twas grace that taught my heart to fear,
And grace my fears relieved;
How precious did that grace appear
The hour I first believed!
Through many dangers, toils, and snares,
I have already come;
\'Tis grace hath brought me safe thus far,
And grace will lead me home.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0295', 'verse', 1, 0, '[\"Amazing grace! How sweet the sound\",\"That saved a wretch like me!\",\"I once was lost, but now am found;\",\"Was blind, but now I see.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0295', 'verse', 2, 1, '[\"\'Twas grace that taught my heart to fear,\",\"And grace my fears relieved;\",\"How precious did that grace appear\",\"The hour I first believed!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0295', 'verse', 3, 2, '[\"Through many dangers, toils, and snares,\",\"I have already come;\",\"\'Tis grace hath brought me safe thus far,\",\"And grace will lead me home.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0296', 296, 'We Sing the Praise', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'We sing the praise of Him who died,
Of Him who died upon the cross;
The sinner\'s hope let men deride;
For this we count the world but loss.
Inscribed upon the cross we see
In shining letters, \"God is love;\"
He bears our sins upon the tree:
He brings us mercy from above.
The cross — it takes our guilt away;
It holds the fainting spirit up;
It cheers with hope the gloomy day,
And sweetens every bitter cup.
It makes the coward spirit brave,
And nerves the feeble arm for fight;
It takes the terror from the grabe,
And gilds the bed of death with light.
The balm of life, the cure of woe,
The measure and the pledge of love,
The sinner\'s refuge here below,
The angels\' theme in heaven above.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0296', 'verse', 1, 0, '[\"We sing the praise of Him who died,\",\"Of Him who died upon the cross;\",\"The sinner\'s hope let men deride;\",\"For this we count the world but loss.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0296', 'verse', 2, 1, '[\"Inscribed upon the cross we see\",\"In shining letters, \\\"God is love;\\\"\",\"He bears our sins upon the tree:\",\"He brings us mercy from above.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0296', 'verse', 3, 2, '[\"The cross — it takes our guilt away;\",\"It holds the fainting spirit up;\",\"It cheers with hope the gloomy day,\",\"And sweetens every bitter cup.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0296', 'verse', 4, 3, '[\"It makes the coward spirit brave,\",\"And nerves the feeble arm for fight;\",\"It takes the terror from the grabe,\",\"And gilds the bed of death with light.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0296', 'verse', 5, 4, '[\"The balm of life, the cure of woe,\",\"The measure and the pledge of love,\",\"The sinner\'s refuge here below,\",\"The angels\' theme in heaven above.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0297', 297, 'Let Heaven Highest Praises Bring', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Let heaven highest praises bring,
And earth her songs of gladness sing,
To magnify our Saviour, King,
Who bought us by His precious blood.
May all the suffering Thou hast borne,
The bleeding side, the cruel thorn,
Our hearts to Thee in sorrow turn,
And lead us safely home to God.
By scourgings, spittings, stripes, and scars,
Jesus, the Maker of the stars,
The gates of heaven for us unbars,
And bids us freely enter in.
Fill us, O Saviour, with Thy love,
Grant us eternal joys above,
Oh, faithful to Thy promise prove,
And cleanse us from our every sin.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0297', 'verse', 1, 0, '[\"Let heaven highest praises bring,\",\"And earth her songs of gladness sing,\",\"To magnify our Saviour, King,\",\"Who bought us by His precious blood.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0297', 'verse', 2, 1, '[\"May all the suffering Thou hast borne,\",\"The bleeding side, the cruel thorn,\",\"Our hearts to Thee in sorrow turn,\",\"And lead us safely home to God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0297', 'verse', 3, 2, '[\"By scourgings, spittings, stripes, and scars,\",\"Jesus, the Maker of the stars,\",\"The gates of heaven for us unbars,\",\"And bids us freely enter in.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0297', 'verse', 4, 3, '[\"Fill us, O Saviour, with Thy love,\",\"Grant us eternal joys above,\",\"Oh, faithful to Thy promise prove,\",\"And cleanse us from our every sin.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0298', 298, 'Hark, My Soul! It Is the Lord', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Hark, my soul! it is the Lord;
\'Tis thy Saviour, hear His word;
Jesus speaks, and speaks to thee,
\"Say, poor sinner, lovest thou Me?\"
\"Mine is an unchanging love,
Higher than the heights above;
Deeper than the depths beneath,
Free and faithful, strong as death.\"
\"Thou shalt see My glory soon,
When the work of grace is done;
Partner of My throne shalt be!
Say, poor sinner, lovest thou Me?\"
Lord, it is my chief complaint
That my love is weak and faint;
Yet I love Thee and adore;
O for grace to love more!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0298', 'verse', 1, 0, '[\"Hark, my soul! it is the Lord;\",\"\'Tis thy Saviour, hear His word;\",\"Jesus speaks, and speaks to thee,\",\"\\\"Say, poor sinner, lovest thou Me?\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0298', 'verse', 2, 1, '[\"\\\"Mine is an unchanging love,\",\"Higher than the heights above;\",\"Deeper than the depths beneath,\",\"Free and faithful, strong as death.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0298', 'verse', 3, 2, '[\"\\\"Thou shalt see My glory soon,\",\"When the work of grace is done;\",\"Partner of My throne shalt be!\",\"Say, poor sinner, lovest thou Me?\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0298', 'verse', 4, 3, '[\"Lord, it is my chief complaint\",\"That my love is weak and faint;\",\"Yet I love Thee and adore;\",\"O for grace to love more!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0299', 299, 'There Is a Land Of Pure Delight', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'There is a land of pure delight,
Where saints immortal reign,
Infinite day excludes the night,
And pleasures banish pain.
There everlasting spring abides,
And never withering flowers,
And but a little space divides
This heav’nly land from ours.
O could we make our doubts remove,
Those gloomy thoughts that rise,
And see the Canaan that we love,
With unbeclouded eyes;
Could we but climb where Moses stood,
And view the landscape o’er,
Not all this world\'s pretended good
Could ever charm us more.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0299', 'verse', 1, 0, '[\"There is a land of pure delight,\",\"Where saints immortal reign,\",\"Infinite day excludes the night,\",\"And pleasures banish pain.\",\"There everlasting spring abides,\",\"And never withering flowers,\",\"And but a little space divides\",\"This heav’nly land from ours.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0299', 'verse', 2, 1, '[\"O could we make our doubts remove,\",\"Those gloomy thoughts that rise,\",\"And see the Canaan that we love,\",\"With unbeclouded eyes;\",\"Could we but climb where Moses stood,\",\"And view the landscape o’er,\",\"Not all this world\'s pretended good\",\"Could ever charm us more.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0300', 300, 'Jerusalem the Golden', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Jerusalem the golden,
With milk and honey blest,
Beneath thy contemplation
Sink heart and voice oppressed.
I know not, O I know not
What holy joys are there;
What radiancy of glory,
What bliss beyond compare.
They stand, those hall of Zion,
All jubilant with song,
And bright with many an angel,
And all the martyr throng.
The Prince is ever in them,
The daylight is serene;
The pastures of the blessed
Are deck in glorious sheen.
There is the throne of David,
And there, from care released,
The song of them that triumph,
The shout of them that feast;
And they who, with their Leader,
Have conquered in the fight,
Forever and forever
Are clad in robes of white.
O sweet and blessed country,
The home of God\'s elect!
O sweet and blessed country,
That eager hearts expect!
Jesus, in mercy bring us
To  that dear land of rest;
Who art, with God the Father,
And Spirit, ever blest.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0300', 'verse', 1, 0, '[\"Jerusalem the golden,\",\"With milk and honey blest,\",\"Beneath thy contemplation\",\"Sink heart and voice oppressed.\",\"I know not, O I know not\",\"What holy joys are there;\",\"What radiancy of glory,\",\"What bliss beyond compare.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0300', 'verse', 2, 1, '[\"They stand, those hall of Zion,\",\"All jubilant with song,\",\"And bright with many an angel,\",\"And all the martyr throng.\",\"The Prince is ever in them,\",\"The daylight is serene;\",\"The pastures of the blessed\",\"Are deck in glorious sheen.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0300', 'verse', 3, 2, '[\"There is the throne of David,\",\"And there, from care released,\",\"The song of them that triumph,\",\"The shout of them that feast;\",\"And they who, with their Leader,\",\"Have conquered in the fight,\",\"Forever and forever\",\"Are clad in robes of white.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0300', 'verse', 4, 3, '[\"O sweet and blessed country,\",\"The home of God\'s elect!\",\"O sweet and blessed country,\",\"That eager hearts expect!\",\"Jesus, in mercy bring us\",\"To  that dear land of rest;\",\"Who art, with God the Father,\",\"And Spirit, ever blest.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0301', 301, 'There Is a Happy Land', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'There is a happy land,
Far, far away,
Where saints in glory stand,
Bright, bright as day.
O! how they sweetly sing,
\"Worthy is our Saviour King;\"
Loud let His praises ring,
Praise, praise for aye.
Come to that happy land
Come, come away;
Why will ye doubting stand?
Why still delay?
O! we shall happy be,');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0301', 'verse', 1, 0, '[\"There is a happy land,\",\"Far, far away,\",\"Where saints in glory stand,\",\"Bright, bright as day.\",\"O! how they sweetly sing,\",\"\\\"Worthy is our Saviour King;\\\"\",\"Loud let His praises ring,\",\"Praise, praise for aye.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0301', 'verse', 2, 1, '[\"Come to that happy land\",\"Come, come away;\",\"Why will ye doubting stand?\",\"Why still delay?\",\"O! we shall happy be,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0302', 302, 'Hail to the Brightness', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Hail to the brightness of Zion\'s glad morning!
Joy to the lands that in darkness have lain!
Hushed be the accents of sorrow and mourning;
Zion, in triumph, begins her mild reign.
Lo, in the desert rich flowers are springing;
Streams ever copious are gliding along;
Loud, from the mountaintops echoes are ringing;
Wastes rise in verdure, and mingle in song.
See, the dead risen from land and from ocean;
Praise to Jehovah, ascending on high;
Fallen the engines of war and commotion,
Shouts of salvation are rending the sky.
Reign, reign for aye.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0302', 'verse', 1, 0, '[\"Hail to the brightness of Zion\'s glad morning!\",\"Joy to the lands that in darkness have lain!\",\"Hushed be the accents of sorrow and mourning;\",\"Zion, in triumph, begins her mild reign.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0302', 'verse', 2, 1, '[\"Lo, in the desert rich flowers are springing;\",\"Streams ever copious are gliding along;\",\"Loud, from the mountaintops echoes are ringing;\",\"Wastes rise in verdure, and mingle in song.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0302', 'verse', 3, 2, '[\"See, the dead risen from land and from ocean;\",\"Praise to Jehovah, ascending on high;\",\"Fallen the engines of war and commotion,\",\"Shouts of salvation are rending the sky.\",\"Reign, reign for aye.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0303', 303, 'Daughter of Zion', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Daughter of Zion, awake from thy sadness;
Awake, for thy foes shall oppress thee no more,
Bright, o\'er thy hills, dawns the daystar of gladness,
Arise for the night of thy sorrow is o\'er.
Daughter of Zion, awake from thy sadness;
Awake, for thy foes shall oppress thee no more.
Strong were thy foes; but the arm that subdued them,
And scattered their legions, was mightier far;
They fled like the chaff from the scourge that pursued them;
In vain were their steeds and their chariots of war.
Strong were thy foes; but the arm that subdued them,
And scattered their legions, was mightier far.
Daughter of Zion, the power that hath saved thee,
Extolled with the harp and the timbrel shall be.
Shout; for the foe is destroyed that enslaved thee,
The oppressor is vanquished, and Zion is free
Daughter of Zion, the power that hath saved thee,
Extolled with the harp and the timbrel shall be.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0303', 'verse', 1, 0, '[\"Daughter of Zion, awake from thy sadness;\",\"Awake, for thy foes shall oppress thee no more,\",\"Bright, o\'er thy hills, dawns the daystar of gladness,\",\"Arise for the night of thy sorrow is o\'er.\",\"Daughter of Zion, awake from thy sadness;\",\"Awake, for thy foes shall oppress thee no more.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0303', 'verse', 2, 1, '[\"Strong were thy foes; but the arm that subdued them,\",\"And scattered their legions, was mightier far;\",\"They fled like the chaff from the scourge that pursued them;\",\"In vain were their steeds and their chariots of war.\",\"Strong were thy foes; but the arm that subdued them,\",\"And scattered their legions, was mightier far.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0303', 'verse', 3, 2, '[\"Daughter of Zion, the power that hath saved thee,\",\"Extolled with the harp and the timbrel shall be.\",\"Shout; for the foe is destroyed that enslaved thee,\",\"The oppressor is vanquished, and Zion is free\",\"Daughter of Zion, the power that hath saved thee,\",\"Extolled with the harp and the timbrel shall be.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0304', 304, 'Glorious Things of Thee Are Spoken', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Glorious things of thee are spoken,
Zion, city of our God;
He whose word cannot be broken
Formed thee for His own abode;
On the Rock of Ages founded,
What can shake thy sure repose?
With salvation\'s wall surrounded,
Thou mayest smile at all thy foes.
See the streams of living waters
Springing from eternal love,
Well supply thy sons and daughters,
And all fear and want remove;
Who can faint when such a river
Ever flows their thirst to assuage?
Grace, which, like the Lord, the Giver,
Never fails from age to age.
Round each habitation hovering,
See the cloud and fire appear
For a glory and a covering,
Showing that the Lord is near;
Blest inhabitants of Zion,
Washed in the Redeemer\'s blood;
Jesus, whom their souls rely on,
Makes them kings and priests to God.
Savior, if of Zion\'s city
I, through grace, a member am,
Let the world deride or pity,
I will glory in Thy name;
Fading is the worldling\'s pleasure,
All his boasted pomp and show;
Solid joys and lasting treasure
None but Zion\'s children know.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0304', 'verse', 1, 0, '[\"Glorious things of thee are spoken,\",\"Zion, city of our God;\",\"He whose word cannot be broken\",\"Formed thee for His own abode;\",\"On the Rock of Ages founded,\",\"What can shake thy sure repose?\",\"With salvation\'s wall surrounded,\",\"Thou mayest smile at all thy foes.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0304', 'verse', 2, 1, '[\"See the streams of living waters\",\"Springing from eternal love,\",\"Well supply thy sons and daughters,\",\"And all fear and want remove;\",\"Who can faint when such a river\",\"Ever flows their thirst to assuage?\",\"Grace, which, like the Lord, the Giver,\",\"Never fails from age to age.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0304', 'verse', 3, 2, '[\"Round each habitation hovering,\",\"See the cloud and fire appear\",\"For a glory and a covering,\",\"Showing that the Lord is near;\",\"Blest inhabitants of Zion,\",\"Washed in the Redeemer\'s blood;\",\"Jesus, whom their souls rely on,\",\"Makes them kings and priests to God.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0304', 'verse', 4, 3, '[\"Savior, if of Zion\'s city\",\"I, through grace, a member am,\",\"Let the world deride or pity,\",\"I will glory in Thy name;\",\"Fading is the worldling\'s pleasure,\",\"All his boasted pomp and show;\",\"Solid joys and lasting treasure\",\"None but Zion\'s children know.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0305', 305, 'We Have Heard', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'We have heard from the bright, the holy, land;
We have heard, and our hearts are glad;
For we were a lonely pilgrim band,
And weary, and worn, and sad.
They tell us the saints have a dwelling there —
No longer are homeless ones;
And we know that the goodly land is fair,
Where life\'s pure river runs.
They say green fields are waving there,
That never a blight shall know;
And the deserts wild are blooming fair,
And the roses of Sharon grow.
There are lovely birds in the bowers green,
Their songs are blithe and sweet;
And their warblings, gushing ever new,
The angels\' harpings greet.
We have heard of the palms, the robes, the crowns,
And the silvery band in white;
Of the city fair, with pearly gates,
All radiant with light.
We have heard of the angels there, and saints,
With their harps of gold, how they sing;
Of the mount with the fruitful tree of life,
Of the leaves that healing bring.
The King of that country, He is fair,
He\'s the joy and light of the place;
In His beauty we shall behold Him there,
And bask in His smiling face,
We\'ll be there, we\'ll be there in a little while,
We\'ll join the pure and the blest;
We\'ll have the palm, the robe, the crown,
And forever be at rest.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0305', 'verse', 1, 0, '[\"We have heard from the bright, the holy, land;\",\"We have heard, and our hearts are glad;\",\"For we were a lonely pilgrim band,\",\"And weary, and worn, and sad.\",\"They tell us the saints have a dwelling there —\",\"No longer are homeless ones;\",\"And we know that the goodly land is fair,\",\"Where life\'s pure river runs.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0305', 'verse', 2, 1, '[\"They say green fields are waving there,\",\"That never a blight shall know;\",\"And the deserts wild are blooming fair,\",\"And the roses of Sharon grow.\",\"There are lovely birds in the bowers green,\",\"Their songs are blithe and sweet;\",\"And their warblings, gushing ever new,\",\"The angels\' harpings greet.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0305', 'verse', 3, 2, '[\"We have heard of the palms, the robes, the crowns,\",\"And the silvery band in white;\",\"Of the city fair, with pearly gates,\",\"All radiant with light.\",\"We have heard of the angels there, and saints,\",\"With their harps of gold, how they sing;\",\"Of the mount with the fruitful tree of life,\",\"Of the leaves that healing bring.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0305', 'verse', 4, 3, '[\"The King of that country, He is fair,\",\"He\'s the joy and light of the place;\",\"In His beauty we shall behold Him there,\",\"And bask in His smiling face,\",\"We\'ll be there, we\'ll be there in a little while,\",\"We\'ll join the pure and the blest;\",\"We\'ll have the palm, the robe, the crown,\",\"And forever be at rest.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0306', 306, 'Ten Thousand Times Ten Thousand', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Ten thousand times ten thousand,
In sparkling raiment bright,
The armies of the ransomed saints
Throng up the steeps of light.
\'Tis finished, all is finished,
Their fight with death and sin.
Fling open wide the golden gates,
And let the victors in.
What rush of hallelujahs
Fills all the earth and sky!
The ringing of a thousand harps
Proclaims the triumph high.
O day for which creation
And all its tribes were made!
O joy, for all its former woes
A thousandfold repaid!
O then what raptured greetings
On Canaan\'s happy shore!
What knitting severed friendship where
Death partings are no more!
Then eyes with joy shall sparkle,
That brimmed with tears of late;
Orphans no longer fatherless,
Nor widows desolate.
Bring near Thy great salvation,
Thou Lamb for sinners slain,
Fill up the roll of Thine elect,
Then take Thy power and reign!
Appear, Desire of nations,
Thine exiles long for home;
Show in the heavens Thy promised sign;
Thou Prince and Savior come!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0306', 'verse', 1, 0, '[\"Ten thousand times ten thousand,\",\"In sparkling raiment bright,\",\"The armies of the ransomed saints\",\"Throng up the steeps of light.\",\"\'Tis finished, all is finished,\",\"Their fight with death and sin.\",\"Fling open wide the golden gates,\",\"And let the victors in.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0306', 'verse', 2, 1, '[\"What rush of hallelujahs\",\"Fills all the earth and sky!\",\"The ringing of a thousand harps\",\"Proclaims the triumph high.\",\"O day for which creation\",\"And all its tribes were made!\",\"O joy, for all its former woes\",\"A thousandfold repaid!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0306', 'verse', 3, 2, '[\"O then what raptured greetings\",\"On Canaan\'s happy shore!\",\"What knitting severed friendship where\",\"Death partings are no more!\",\"Then eyes with joy shall sparkle,\",\"That brimmed with tears of late;\",\"Orphans no longer fatherless,\",\"Nor widows desolate.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0306', 'verse', 4, 3, '[\"Bring near Thy great salvation,\",\"Thou Lamb for sinners slain,\",\"Fill up the roll of Thine elect,\",\"Then take Thy power and reign!\",\"Appear, Desire of nations,\",\"Thine exiles long for home;\",\"Show in the heavens Thy promised sign;\",\"Thou Prince and Savior come!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0307', 307, 'The Time Is Near', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'The time is near when Zion\'s sons,
With rapturous joy shall sing the song
Foretold by seers — anointed ones:
We have a city great and strong,
We have a city great and strong.
Open, ye gates! The glorious King
Approaches with a holy throng;
Open, ye gates! Saints, angels, sing
On golden harps the victor\'s song!
On golden harps the victor\'s song!
O righteous nation! enter in,
That kept the law of truth below,
Enter the place, all free from sin,
Where life\'s pure waters gently flow.
Where life\'s pure waters gently flow.
Within these walls shall they remain,
Who trusted, mighty Lord! in Thee.
Death, their last enemy, is slain;
They have a right to life\'s fair tree.
They have a right to life\'s fair tree.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0307', 'verse', 1, 0, '[\"The time is near when Zion\'s sons,\",\"With rapturous joy shall sing the song\",\"Foretold by seers — anointed ones:\",\"We have a city great and strong,\",\"We have a city great and strong.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0307', 'verse', 2, 1, '[\"Open, ye gates! The glorious King\",\"Approaches with a holy throng;\",\"Open, ye gates! Saints, angels, sing\",\"On golden harps the victor\'s song!\",\"On golden harps the victor\'s song!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0307', 'verse', 3, 2, '[\"O righteous nation! enter in,\",\"That kept the law of truth below,\",\"Enter the place, all free from sin,\",\"Where life\'s pure waters gently flow.\",\"Where life\'s pure waters gently flow.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0307', 'verse', 4, 3, '[\"Within these walls shall they remain,\",\"Who trusted, mighty Lord! in Thee.\",\"Death, their last enemy, is slain;\",\"They have a right to life\'s fair tree.\",\"They have a right to life\'s fair tree.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0308', 308, 'We’ve No Abiding City Here', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'We\'ve no abiding city here;
Sad truth, were this to be our home;
But let this thought our spirits cheer,
We seek a city yet to come,
We seek a city yet to come.
We\'ve no abiding city here,
We seek a city out of sight;
Zion its name — the Lord is there —
It shines with everlasting light,
It shines with everlasting light.
O sweet abode of peace and love,
Where pilgrims, freed from toil, are blest!
Had I the pinions of a dove,
I\'d fly to thee, and be at rest,
I\'d fly to thee, and be at rest.
But hush, my soul! nor dare repine;
The time my God appoints is best;
While here, to do His will be mine,
And His to fix my time of rest,
And His to fix my time of rest.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0308', 'verse', 1, 0, '[\"We\'ve no abiding city here;\",\"Sad truth, were this to be our home;\",\"But let this thought our spirits cheer,\",\"We seek a city yet to come,\",\"We seek a city yet to come.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0308', 'verse', 2, 1, '[\"We\'ve no abiding city here,\",\"We seek a city out of sight;\",\"Zion its name — the Lord is there —\",\"It shines with everlasting light,\",\"It shines with everlasting light.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0308', 'verse', 3, 2, '[\"O sweet abode of peace and love,\",\"Where pilgrims, freed from toil, are blest!\",\"Had I the pinions of a dove,\",\"I\'d fly to thee, and be at rest,\",\"I\'d fly to thee, and be at rest.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0308', 'verse', 4, 3, '[\"But hush, my soul! nor dare repine;\",\"The time my God appoints is best;\",\"While here, to do His will be mine,\",\"And His to fix my time of rest,\",\"And His to fix my time of rest.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0309', 309, 'Jerusalem, My Happy Home', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Jerusalem, my happy home,
O how I long for thee!
When will my sorrows have an end?
Thy joys when shall I see?
Thy walls are all of precious stone,
Most glorious to behold;
Thy gates are richly set with pearl,
Thy streets are paved with gold.
Thy garden and thy pleasant walks
My study long have been;
Such dazzling views by human sight
Have never yet been seen.
Lord, help us by Thy mighty grace,
To keep in view the prize
Till Thou dost come to take us home
To that blessed paradise.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0309', 'verse', 1, 0, '[\"Jerusalem, my happy home,\",\"O how I long for thee!\",\"When will my sorrows have an end?\",\"Thy joys when shall I see?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0309', 'verse', 2, 1, '[\"Thy walls are all of precious stone,\",\"Most glorious to behold;\",\"Thy gates are richly set with pearl,\",\"Thy streets are paved with gold.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0309', 'verse', 3, 2, '[\"Thy garden and thy pleasant walks\",\"My study long have been;\",\"Such dazzling views by human sight\",\"Have never yet been seen.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0309', 'verse', 4, 3, '[\"Lord, help us by Thy mighty grace,\",\"To keep in view the prize\",\"Till Thou dost come to take us home\",\"To that blessed paradise.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0310', 310, 'O Happy Day! That Fixed My Choice', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'O happy day! that fixed my choice
On Thee, my Saviour and my God;
Well may this glowing heart rejoice,
And tell its raptures all abroad.
Happy day, happy day,
When Jesus washed my sins away!
He taught me how to watch and pray,
And live rejoicing every day;
Happy day, happy day,
When Jesus washed my sins away!
\'Tis done, the great transaction\'s done;
I am my Lord\'s, and He is mine;
He drew me and I followed on,
Charmed to confess the voice divine.
Now rest, my long-divided heart,
Fixed on this blissful center, rest;
Nor ever from thy Lord depart,
With Him of every good possessed.
High Heaven, that heard the solemn vow,
That vow renewed shall daily hear,
Till in time\'s latest hour I bow,
And bless at last a bond so dear.
And when the bright celestial train.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0310', 'verse', 1, 0, '[\"O happy day! that fixed my choice\",\"On Thee, my Saviour and my God;\",\"Well may this glowing heart rejoice,\",\"And tell its raptures all abroad.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0310', 'chorus', 0, 1, '[\"Happy day, happy day,\",\"When Jesus washed my sins away!\",\"He taught me how to watch and pray,\",\"And live rejoicing every day;\",\"Happy day, happy day,\",\"When Jesus washed my sins away!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0310', 'verse', 2, 2, '[\"\'Tis done, the great transaction\'s done;\",\"I am my Lord\'s, and He is mine;\",\"He drew me and I followed on,\",\"Charmed to confess the voice divine.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0310', 'verse', 3, 3, '[\"Now rest, my long-divided heart,\",\"Fixed on this blissful center, rest;\",\"Nor ever from thy Lord depart,\",\"With Him of every good possessed.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0310', 'verse', 4, 4, '[\"High Heaven, that heard the solemn vow,\",\"That vow renewed shall daily hear,\",\"Till in time\'s latest hour I bow,\",\"And bless at last a bond so dear.\"]');
