INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0369', 'verse', 5, 4, '[\"O, that each in the day of His coming may say,\",\"\\\"I have fought my way through;\",\"I have finished the work Thou didst give me to do.\",\"I have finished the work Thou didst give me to do.\\\"\"]');
