INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0370', 'verse', 1, 0, '[\"Day is done, gone the sun,\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0371', 371, 'I Saw One Weary', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'I saw one weary, sad, and torn,
With eager steps press on the way,
Who long the hallowed cross had born,
Still looking for the promised day;
While many a line of grief and care,
Upon his brow was furrowed there;
I asked what buoyed his spirits up,
\"O this\" said he - \"the blessed hope.\"
And one I saw, with sword and shield,
Who boldly braved the world\'s cold frown,
And fought, unyielding, on the field,
To win an everlasting crown.
Though worn with toil, oppressed by foes,
No murmur from his heart arose;
I asked what buoyed his spirits up,
\"O this!\" said he - \"the blessed hope.\"
And there was  one who left behind
The cherished friends of early years,
And honor, pleasure, wealth resigned,
To tread the path bedewed with tears.
Through trials deep and conflict sore,
Yet still a smile of joy he wore;
I asked what buoyed his spirits up,
\"O this!\" said he - \"the blessed hope.\"
While pilgrims here we journey on
In this dark vale of sin and gloom,
Through tribulation, hate, and scorn,
Or through the portals of the tomb,
Till our returning King shall come
To tkae His exile captives home,
O! what can bouy the spirits up?
\'Tis this alone - the blessed hope.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0371', 'verse', 1, 0, '[\"I saw one weary, sad, and torn,\",\"With eager steps press on the way,\",\"Who long the hallowed cross had born,\",\"Still looking for the promised day;\",\"While many a line of grief and care,\",\"Upon his brow was furrowed there;\",\"I asked what buoyed his spirits up,\",\"\\\"O this\\\" said he - \\\"the blessed hope.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0371', 'verse', 2, 1, '[\"And one I saw, with sword and shield,\",\"Who boldly braved the world\'s cold frown,\",\"And fought, unyielding, on the field,\",\"To win an everlasting crown.\",\"Though worn with toil, oppressed by foes,\",\"No murmur from his heart arose;\",\"I asked what buoyed his spirits up,\",\"\\\"O this!\\\" said he - \\\"the blessed hope.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0371', 'verse', 3, 2, '[\"And there was  one who left behind\",\"The cherished friends of early years,\",\"And honor, pleasure, wealth resigned,\",\"To tread the path bedewed with tears.\",\"Through trials deep and conflict sore,\",\"Yet still a smile of joy he wore;\",\"I asked what buoyed his spirits up,\",\"\\\"O this!\\\" said he - \\\"the blessed hope.\\\"\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0371', 'verse', 4, 3, '[\"While pilgrims here we journey on\",\"In this dark vale of sin and gloom,\",\"Through tribulation, hate, and scorn,\",\"Or through the portals of the tomb,\",\"Till our returning King shall come\",\"To tkae His exile captives home,\",\"O! what can bouy the spirits up?\",\"\'Tis this alone - the blessed hope.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0372', 372, 'A Few More Years Shall Roll', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'A few more years shall roll,
A few more seasons come,
And we shall meet the loved who now
Are sleeping in the tomb.
Then, O my Lord, prepare
My soul for that great day;
O, wash me in Thy precious blood,
And take my sins away!
A few more storms shall beat
On this wild, rocky shore,
And we shall be where tempests cease,
And surges swell no more.
Then, O my Lord, prepare
My soul for that calm day;
O, wash me in Thy precious blood,
And take my sins away!
A few more struggles here,
A few more partings sore,
A few more toils, a few more tears,
And we shall weep no more.
Then, O my Lord, prepare
My soul for that blest day;
O, wash me in Thy precious blood,
And take my sins away!
\'Tis but a little while,
And He shall come again,
Who died that we might live, who lives
That we may with Him reign.
Then, O my Lord, prepare
My soul for that glad day;
O, wash me in Thy precious blood,
And take my sins away!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0372', 'verse', 1, 0, '[\"A few more years shall roll,\",\"A few more seasons come,\",\"And we shall meet the loved who now\",\"Are sleeping in the tomb.\",\"Then, O my Lord, prepare\",\"My soul for that great day;\",\"O, wash me in Thy precious blood,\",\"And take my sins away!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0372', 'verse', 2, 1, '[\"A few more storms shall beat\",\"On this wild, rocky shore,\",\"And we shall be where tempests cease,\",\"And surges swell no more.\",\"Then, O my Lord, prepare\",\"My soul for that calm day;\",\"O, wash me in Thy precious blood,\",\"And take my sins away!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0372', 'verse', 3, 2, '[\"A few more struggles here,\",\"A few more partings sore,\",\"A few more toils, a few more tears,\",\"And we shall weep no more.\",\"Then, O my Lord, prepare\",\"My soul for that blest day;\",\"O, wash me in Thy precious blood,\",\"And take my sins away!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0372', 'verse', 4, 3, '[\"\'Tis but a little while,\",\"And He shall come again,\",\"Who died that we might live, who lives\",\"That we may with Him reign.\",\"Then, O my Lord, prepare\",\"My soul for that glad day;\",\"O, wash me in Thy precious blood,\",\"And take my sins away!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0373', 373, 'Pilgrims, on! the Day Is Dawning', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Pilgrims, on! the day is dawning;
Strike your tents, and homeward haste;
Sleep not while the blush or morning
Calls ou on the desert waste.
Though the way be dark and dreary,
Life\'s sharp anguish must be borne;
Courage, then, ye faint and weary,
Linger not to weep and mourn.
Pilgrims, on! the storm is beating,
Beating wildly on your way;
Tarry not, the time is fleeting;
Shall the storm your foot-steps stay?
Hasten on, through joy and sorrow,
Or whatever may betide,
Wait not for the calm tomorow,
Faithful at your work abide.
Pilgrims, on! what though in dangers,
Life\'s eventful course pursue;
Labor on, ye friendless strangers,
Grace will guide you safely through.
What if trials must befall you!
What if fierce temptations rise!
Shall earth\'s bitter strife appall you
While contending for the prize?
Pilgrims, on! there\'s rest in heaven,
Rest from every anxious care,
Rest in Jesus\' smiles, forgiven,
Peaceful and eternal there.
O, \'twere sweet to toil in sadness,
O, \'twere well the cross to bear,
If, at last in joy or gladness,
We may rest forever there!');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0373', 'verse', 1, 0, '[\"Pilgrims, on! the day is dawning;\",\"Strike your tents, and homeward haste;\",\"Sleep not while the blush or morning\",\"Calls ou on the desert waste.\",\"Though the way be dark and dreary,\",\"Life\'s sharp anguish must be borne;\",\"Courage, then, ye faint and weary,\",\"Linger not to weep and mourn.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0373', 'verse', 2, 1, '[\"Pilgrims, on! the storm is beating,\",\"Beating wildly on your way;\",\"Tarry not, the time is fleeting;\",\"Shall the storm your foot-steps stay?\",\"Hasten on, through joy and sorrow,\",\"Or whatever may betide,\",\"Wait not for the calm tomorow,\",\"Faithful at your work abide.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0373', 'verse', 3, 2, '[\"Pilgrims, on! what though in dangers,\",\"Life\'s eventful course pursue;\",\"Labor on, ye friendless strangers,\",\"Grace will guide you safely through.\",\"What if trials must befall you!\",\"What if fierce temptations rise!\",\"Shall earth\'s bitter strife appall you\",\"While contending for the prize?\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0373', 'verse', 4, 3, '[\"Pilgrims, on! there\'s rest in heaven,\",\"Rest from every anxious care,\",\"Rest in Jesus\' smiles, forgiven,\",\"Peaceful and eternal there.\",\"O, \'twere sweet to toil in sadness,\",\"O, \'twere well the cross to bear,\",\"If, at last in joy or gladness,\",\"We may rest forever there!\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0374', 374, 'There Is a Road', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'There is a road, though narrow and obscure,
Which we must traverse till earth\'s days be past,
Which though unheeded by the passing throng,
Leads us to our eternal home at last.
Here trod the faithful when the work began;
Some still are with us, but, alas, not all;
Many have laid their heavy burdens down
And will rejoin us when the Lord shall call.
And there is One who, though to eye unseen,
Journeys besideus wheresoe\'er we go;
Guards all our footsteps with the tenderest care,
And sorrows with us in our earthly woe.
Almost the city towers we can discern
And hear the music from those courts above.
Jesus is waiting with the table spread;
O what a welcome in those arms of love.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0374', 'verse', 1, 0, '[\"There is a road, though narrow and obscure,\",\"Which we must traverse till earth\'s days be past,\",\"Which though unheeded by the passing throng,\",\"Leads us to our eternal home at last.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0374', 'verse', 2, 1, '[\"Here trod the faithful when the work began;\",\"Some still are with us, but, alas, not all;\",\"Many have laid their heavy burdens down\",\"And will rejoin us when the Lord shall call.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0374', 'verse', 3, 2, '[\"And there is One who, though to eye unseen,\",\"Journeys besideus wheresoe\'er we go;\",\"Guards all our footsteps with the tenderest care,\",\"And sorrows with us in our earthly woe.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0374', 'verse', 4, 3, '[\"Almost the city towers we can discern\",\"And hear the music from those courts above.\",\"Jesus is waiting with the table spread;\",\"O what a welcome in those arms of love.\"]');
INSERT INTO tblSongs (SongId, Number, Title, SongbookAbbr, Language, Copyright, Ccli, Verified, LyricsPublicDomain, MusicPublicDomain, HasAudio, HasSheetMusic, LyricsText) VALUES ('CH-0375', 375, 'Hark! Hark, My Soul!', 'CH', 'en', '', '', 0, 0, 0, 0, 0, 'Hark! hark, my soul! angelic songs are swelling
O\'er earth\'s green fields and ocean\'s wave-beat shore;
How sweet the truth those blessed strains are telling
Of that new life when sin shall be no more!
Angels of Jesus, angels of light,
Singing to welcome the pilgrims of the night.
Onward we go, for still we hear them singing,
\"Come, weary souls, for Jesus bids you come;\"
And through the dark, its echoes sweetly ringing,
The music of the gospel leads us home.
Far, fur away, like bells at evening pealing,
The voice of Jesus sounds o\'er land and sea;
And laden souls, by thousands meekly stealing,
Kind Shepherd, turn their weary steps to Thee.
Angels, sing on, your faithful watches keeping;
Sing us sweet fragment of the songs above,
Till morning\'s joy shall end the night of weeping,
And life\'s long shadows break in cloudless love.');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0375', 'verse', 1, 0, '[\"Hark! hark, my soul! angelic songs are swelling\",\"O\'er earth\'s green fields and ocean\'s wave-beat shore;\",\"How sweet the truth those blessed strains are telling\",\"Of that new life when sin shall be no more!\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0375', 'chorus', 0, 1, '[\"Angels of Jesus, angels of light,\",\"Singing to welcome the pilgrims of the night.\"]');
INSERT INTO tblSongComponents (SongId, Type, Number, SortOrder, LinesJson) VALUES ('CH-0375', 'verse', 2, 2, '[\"Onward we go, for still we hear them singing,\",\"\\\"Come, weary souls, for Jesus bids you come;\\\"\",\"And through the dark, its echoes sweetly ringing,\",\"The music of the gospel leads us home.\"]');
